-- ----------------------------
-- View structure for V_CUARTO_REP_RESERVA_CERT_CA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_CUARTO_REP_RESERVA_CERT_CA]') AND type IN ('V'))
	DROP VIEW [dbo].[V_CUARTO_REP_RESERVA_CERT_CA]
GO

CREATE VIEW [dbo].[V_CUARTO_REP_RESERVA_CERT_CA] AS SELECT 
A1.ANO_EJE,
A1.SEC_EJEC,
X1.NRO_CERTIFICA,
C1.FUENTE_FINANC,
D1.SEC_FUNC,
D1.CLASIFICADOR,
SUM(
CASE
WHEN B1.SEC_OPERA = 1 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 2 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 3 THEN (-1)* COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 4 THEN (-1)* COALESCE(D1.VALOR_SOLES,0)
END
) TOTAL_CA
FROM 
SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1, SIG_CERTIFICACION_OPERACION B1,
SIG_CERTIFICACION_OPER_FUENTE C1, SIG_CERTIFICACION_PPTO D1
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
A1.ANO_EJE = B1.ANO_EJE AND A1.SEC_EJEC = B1.SEC_EJEC AND
A1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND A1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.ANO_EJE = B1.ANO_EJE AND C1.SEC_EJEC = B1.SEC_EJEC AND
C1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = B1.SECUENCIA_OPERA AND
C1.ANO_EJE = D1.ANO_EJE AND C1.SEC_EJEC = D1.SEC_EJEC AND
C1.NRO_CERTIFICA = D1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = D1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = D1.SECUENCIA_OPERA AND C1.SECUENCIA_DET = D1.SECUENCIA_DET AND
A1.SEC_FASE = 2 
GROUP BY 
A1.ANO_EJE,A1.SEC_EJEC,X1.NRO_CERTIFICA,C1.FUENTE_FINANC,D1.SEC_FUNC,D1.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_CUARTO_REP_RESERVA_VW_CERT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_CUARTO_REP_RESERVA_VW_CERT]') AND type IN ('V'))
	DROP VIEW [dbo].[V_CUARTO_REP_RESERVA_VW_CERT]
GO

CREATE VIEW [dbo].[V_CUARTO_REP_RESERVA_VW_CERT] AS SELECT 
A1.ANO_EJE,
A1.SEC_EJEC,
X1.NRO_CERTIFICA,
X1.COD_CERTIFICA,
C1.FUENTE_FINANC,
D1.SEC_FUNC,
D1.CLASIFICADOR,
SUM(
CASE
WHEN B1.SEC_OPERA = 1 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 2 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 3 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 4 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
END
) TOTAL_CP
FROM 
SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1, SIG_CERTIFICACION_OPERACION B1,
SIG_CERTIFICACION_OPER_FUENTE C1, SIG_CERTIFICACION_PPTO D1
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
 
A1.ANO_EJE = B1.ANO_EJE AND A1.SEC_EJEC = B1.SEC_EJEC AND
A1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND A1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
 
C1.ANO_EJE = B1.ANO_EJE AND C1.SEC_EJEC = B1.SEC_EJEC AND
C1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = B1.SECUENCIA_OPERA AND
 
C1.ANO_EJE = D1.ANO_EJE AND C1.SEC_EJEC = D1.SEC_EJEC AND
C1.NRO_CERTIFICA = D1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = D1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = D1.SECUENCIA_OPERA AND C1.SECUENCIA_DET = D1.SECUENCIA_DET AND
A1.SEC_FASE = 1 
GROUP BY A1.ANO_EJE,A1.SEC_EJEC,X1.NRO_CERTIFICA,X1.COD_CERTIFICA,C1.FUENTE_FINANC,D1.SEC_FUNC,D1.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_CUARTO_REPORTE_RESERVA_CA_CM
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_CUARTO_REPORTE_RESERVA_CA_CM]') AND type IN ('V'))
	DROP VIEW [dbo].[V_CUARTO_REPORTE_RESERVA_CA_CM]
GO

CREATE VIEW [dbo].[V_CUARTO_REPORTE_RESERVA_CA_CM] AS SELECT 
D.ANO_EJE,
D.SEC_EJEC,
X1.NRO_CERTIFICA,
F.FUENTE_FINANC,
F.SEC_FUNC,
F.CLASIFICADOR,
SUM(COALESCE(F.VALOR_SOLES, 0))  TOTAL_CM
FROM SIG_CERTIFICACION_FASE A1, SIG_ORDEN_ADQUISICION D,
SIG_ORDEN_SECUENCIA E, SIG_ORDEN_PRESUPUESTO F, SIG_CERTIFICACION X1
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND
A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
D.ANO_EJE = E.ANO_EJE AND
D.SEC_EJEC = E.SEC_EJEC AND
D.TIPO_PPTO = E.TIPO_PPTO AND
D.TIPO_BIEN = E.TIPO_BIEN AND
D.NRO_ORDEN = E.NRO_ORDEN AND
F.ANO_EJE = E.ANO_EJE AND
F.SEC_EJEC = E.SEC_EJEC AND
F.TIPO_PPTO = E.TIPO_PPTO AND
F.TIPO_BIEN = E.TIPO_BIEN AND
F.NRO_ORDEN = E.NRO_ORDEN AND
F.SEC_ORDEN = E.SEC_ORDEN AND
A1.ANO_EJE = D.ANO_EJE AND A1.SEC_EJEC = D.SEC_EJEC AND
A1.NRO_CERTIFICA = D.NRO_CERTIFICA AND
A1.SEC_FASE = 2 AND 
(
(
(CASE 
WHEN COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) > 0 AND COALESCE(A1.NRO_ORDEN,0) =0
THEN A1.NRO_CONTRATO
WHEN COALESCE(A1.NRO_CONSOLID,0) = 0  AND COALESCE(A1.NRO_CONTRATO,0) > 0 AND COALESCE(A1.NRO_ORDEN,0) =0
THEN A1.NRO_CONTRATO
END)= D.SEC_CONTRATO AND COALESCE(A1.NRO_ORDEN,0) =0 ) OR
(
(CASE 
WHEN COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='B'
THEN A1.NRO_ORDEN
WHEN COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='S'
THEN A1.NRO_ORDEN
WHEN COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='V'
THEN A1.NRO_ORDEN
END) = COALESCE(D.NRO_ORDEN, 0) AND COALESCE(A1.NRO_ORDEN,0) > 0  AND A1.TIPO_BIEN = D.TIPO_BIEN AND D.TIPO_PPTO = 1  )
)
GROUP BY D.ANO_EJE,D.SEC_EJEC,X1.NRO_CERTIFICA,F.FUENTE_FINANC,F.SEC_FUNC,F.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_CUARTO_REPORTE_RESERVA_VW_CA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_CUARTO_REPORTE_RESERVA_VW_CA]') AND type IN ('V'))
