CASE
WHEN B1.SEC_OPERA = 1 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 2 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 3 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 4 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
END
) TOTAL_CA
FROM 
SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1, SIG_CERTIFICACION_OPERACION B1,
SIG_CERTIFICACION_OPER_FUENTE C1, SIG_CERTIFICACION_PPTO D1
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
A1.ANO_EJE = B1.ANO_EJE AND A1.SEC_EJEC = B1.SEC_EJEC AND
A1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND A1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.ANO_EJE = B1.ANO_EJE AND C1.SEC_EJEC = B1.SEC_EJEC AND
C1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = B1.SECUENCIA_OPERA AND
C1.ANO_EJE = D1.ANO_EJE AND C1.SEC_EJEC = D1.SEC_EJEC AND
C1.NRO_CERTIFICA = D1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = D1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = D1.SECUENCIA_OPERA AND C1.SECUENCIA_DET = D1.SECUENCIA_DET AND
A1.SEC_FASE = 2 
GROUP BY A1.ANO_EJE,A1.SEC_EJEC,X1.NRO_CERTIFICA,X1.COD_CERTIFICA,C1.FUENTE_FINANC,D1.SEC_FUNC,D1.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_DESTINOS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_DESTINOS]') AND type IN ('V'))
	DROP VIEW [dbo].[V_DESTINOS]
GO

CREATE VIEW [dbo].[V_DESTINOS] AS SELECT SIG_PROY_DESTINO.SEC_DESTINO codigo,   
	' ' ce_pais,   
	' ' ce_ciudad,   
	SIG_PROY_DESTINO.TIPO_VIAJE,   
	SIG_PROY_DESTINO.L_PAIS cp_pais,   
	SIG_PROY_DESTINO.L_DEPARTAMENTO cp_departamento,
	SIG_PROY_DESTINO.L_PROVINCIA cp_provincia,
	SIG_PROY_DESTINO.L_DISTRITO cp_distrito,   
	' ' ne_pais,   
	' ' ne_ciudad,    
	A.NOMBRE  np_departamento,
	B.NOMBRE  np_provincia,
	UBIGEO.NOMBRE np_distrito
FROM SIG_PROY_DESTINO,   
	UBIGEO, 
	UBIGEO A,
	UBIGEO B  
WHERE  UBIGEO.PAIS         = SIG_PROY_DESTINO.L_PAIS
	AND UBIGEO.DEPARTAMENTO = SIG_PROY_DESTINO.L_DEPARTAMENTO
	AND UBIGEO.PROVINCIA    = SIG_PROY_DESTINO.L_PROVINCIA
	AND UBIGEO.DISTRITO     = SIG_PROY_DESTINO.L_DISTRITO
	AND A.PAIS              = SIG_PROY_DESTINO.L_PAIS
	AND A.DEPARTAMENTO = SIG_PROY_DESTINO.L_DEPARTAMENTO
	AND A.PROVINCIA    = '00'
	AND A.DISTRITO     = '00'
	AND B.PAIS         = SIG_PROY_DESTINO.L_PAIS
	AND B.DEPARTAMENTO = SIG_PROY_DESTINO.L_DEPARTAMENTO
	AND B.PROVINCIA    = SIG_PROY_DESTINO.L_PROVINCIA
	AND B.DISTRITO     = '00'
	AND (SIG_PROY_DESTINO.ESTADO = 'A'
	AND SIG_PROY_DESTINO.TIPO_VIAJE = 'P')

UNION

SELECT SIG_PROY_DESTINO.SEC_DESTINO codigo,   
	SIG_PROY_DESTINO.E_PAIS ce_pais,   
	SIG_PROY_DESTINO.E_CIUDAD ce_ciudad,   
	SIG_PROY_DESTINO.TIPO_VIAJE,   
	' ' cp_pais,   
	' ' cp_departamento,
	' ' cp_provincia,
	' ' cp_distrito,    
	A.NOMBRE ne_pais,   
	SIG_PROY_CIUDAD.NOMBRE ne_ciudad ,
	' ' np_departamento,
	' ' np_provincia,
	' ' np_distrito
FROM SIG_PROY_DESTINO,   
	SIG_PROY_CIUDAD A,
	SIG_PROY_CIUDAD
WHERE A.PAIS = SIG_PROY_DESTINO.E_PAIS
	AND A.CIUDAD = '0000'
	AND SIG_PROY_CIUDAD.PAIS = SIG_PROY_DESTINO.E_PAIS
	AND SIG_PROY_CIUDAD.CIUDAD = SIG_PROY_DESTINO.E_CIUDAD
	AND ( SIG_PROY_DESTINO.ESTADO = 'A'
	AND SIG_PROY_DESTINO.TIPO_VIAJE = 'E')
GO


