CREATE VIEW [dbo].[v_metas_x_centro_int] AS SELECT ano_eje,
       sec_ejec,
       secuencia,
       centro_costo ,
       origen,
       fuente_financ ,
       tipo_recurso,
       porc_gfijos ,
       porc_techo,
       cuser_id ,
       fecha_reg,
       flag_bloqueo_ppr ,
