-- ----------------------------
-- View structure for V_PRIMER_REPORTE_VW_CABECERA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PRIMER_REPORTE_VW_CABECERA]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PRIMER_REPORTE_VW_CABECERA]
GO

CREATE VIEW [dbo].[V_PRIMER_REPORTE_VW_CABECERA] AS SELECT  
M.ANO_EJE, M.SEC_EJEC,M.FUENTE_FINANC, M.COD_NIVEL1, M.COD_NIVEL2, M.CLASIFICADOR ,  
SUM(COALESCE(M.TOTAL,0)) - SUM(COALESCE(R.TOTAL,0)) TOTAL ,
SUM(COALESCE(M.TOTAL,0)) TOTAL_CP ,
SUM(COALESCE(R.TOTAL,0)) TOTAL_CA
FROM  SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1,
V_PRIMER_REPORTE_VW_DETA_DOCM M LEFT OUTER JOIN V_PRIMER_REPORTE_VW_DETA_DOCW R ON
R.ANO_EJE = M.ANO_EJE AND  
R.SEC_EJEC = M.SEC_EJEC AND 
R.NRO_CERTIFICA = M.NRO_CERTIFICA AND 
R.NRO_CONSOLID = M.NRO_CONSOLID AND
R.FUENTE_FINANC = M.FUENTE_FINANC AND 
R.COD_NIVEL1 = M.COD_NIVEL1 AND 
R.COD_NIVEL2 = M.COD_NIVEL2 AND
R.SEC_FUNC = M.SEC_FUNC AND 
R.CLASIFICADOR = M.CLASIFICADOR 

WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
 
M.ANO_EJE = X1.ANO_EJE AND 
M.SEC_EJEC = X1.SEC_EJEC AND 
M.NRO_CERTIFICA = X1.NRO_CERTIFICA AND 

A1.SEC_FASE = 1 AND  
A1.NRO_CONSOLID >0 

GROUP BY  
M.ANO_EJE, M.SEC_EJEC,M.FUENTE_FINANC, M.COD_NIVEL1, M.COD_NIVEL2, M.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_PRIMER_REPORTE_VW_DETA_DOC
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PRIMER_REPORTE_VW_DETA_DOC]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PRIMER_REPORTE_VW_DETA_DOC]
GO

CREATE VIEW [dbo].[V_PRIMER_REPORTE_VW_DETA_DOC] AS SELECT  
M.ANO_EJE, M.SEC_EJEC,A1.NRO_CONSOLID, X1.NRO_CERTIFICA, X1.COD_CERTIFICA, X1.NRO_CERTIFICA_SIAF, 
M.FUENTE_FINANC, M.COD_NIVEL1, M.COD_NIVEL2, M.CLASIFICADOR ,  
SUM(COALESCE(M.TOTAL,0)) - SUM(COALESCE(R.TOTAL,0)) TOTAL ,
SUM(COALESCE(M.TOTAL,0)) TOTAL_CP ,
SUM(COALESCE(R.TOTAL,0)) TOTAL_CA
FROM  
SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1,
V_PRIMER_REPORTE_VW_DETA_DOCM M LEFT JOIN V_PRIMER_REPORTE_VW_DETA_DOCW R ON
R.ANO_EJE = M.ANO_EJE AND  
R.SEC_EJEC = M.SEC_EJEC AND 
R.NRO_CERTIFICA = M.NRO_CERTIFICA AND 
R.NRO_CONSOLID = M.NRO_CONSOLID AND 
R.FUENTE_FINANC = M.FUENTE_FINANC AND 
R.COD_NIVEL1 = M.COD_NIVEL1 AND 
R.COD_NIVEL2 = M.COD_NIVEL2 AND
R.SEC_FUNC = M.SEC_FUNC AND
R.CLASIFICADOR = M.CLASIFICADOR
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
 
M.ANO_EJE = X1.ANO_EJE AND M.SEC_EJEC = X1.SEC_EJEC AND 
M.NRO_CERTIFICA = X1.NRO_CERTIFICA AND 

A1.SEC_FASE = 1 

GROUP BY  
M.ANO_EJE, M.SEC_EJEC,A1.NRO_CONSOLID, X1.NRO_CERTIFICA, X1.COD_CERTIFICA, X1.NRO_CERTIFICA_SIAF, 
M.FUENTE_FINANC, M.COD_NIVEL1, M.COD_NIVEL2, M.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_PRIMER_REPORTE_VW_DETA_DOCM
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PRIMER_REPORTE_VW_DETA_DOCM]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PRIMER_REPORTE_VW_DETA_DOCM]
GO

CREATE VIEW [dbo].[V_PRIMER_REPORTE_VW_DETA_DOCM] AS SELECT  
X1.ANO_EJE, X1.SEC_EJEC,X1.NRO_CERTIFICA, A1.NRO_CONSOLID,
C1.FUENTE_FINANC, R.COD_NIVEL1, R.COD_NIVEL2, D1.SEC_FUNC, D1.CLASIFICADOR ,  
SUM( 
CASE WHEN B1.SEC_OPERA = 1 THEN COALESCE(D1.VALOR_SOLES,0) 
WHEN B1.SEC_OPERA = 2 THEN COALESCE(D1.VALOR_SOLES,0) 
WHEN B1.SEC_OPERA = 3 THEN (-1) * COALESCE(D1.VALOR_SOLES,0) 
WHEN B1.SEC_OPERA = 4 THEN (-1) * COALESCE(D1.VALOR_SOLES,0) 
END) TOTAL 
FROM  SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1, 
SIG_CERTIFICACION_OPERACION B1, SIG_CERTIFICACION_OPER_FUENTE C1, 
SIG_CERTIFICACION_PPTO D1, SIG_CLASIFICADOR_GASTO R
WHERE  
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND 
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND 

A1.ANO_EJE = B1.ANO_EJE AND A1.SEC_EJEC = B1.SEC_EJEC AND 
A1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND A1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND 

C1.ANO_EJE = B1.ANO_EJE AND C1.SEC_EJEC = B1.SEC_EJEC AND C1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND 
C1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND C1.SECUENCIA_OPERA = B1.SECUENCIA_OPERA AND 

C1.ANO_EJE = D1.ANO_EJE AND C1.SEC_EJEC = D1.SEC_EJEC AND 
C1.NRO_CERTIFICA = D1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = D1.SECUENCIA_FASE AND 
C1.SECUENCIA_OPERA = D1.SECUENCIA_OPERA AND C1.SECUENCIA_DET = D1.SECUENCIA_DET AND 

R.ANO_EJE = D1.ANO_EJE AND  
R.CLASIFICADOR = D1.CLASIFICADOR AND 

A1.SEC_FASE = 1 AND COALESCE(A1.NRO_CONTRATO, 0) = 0
GROUP BY  
X1.ANO_EJE, X1.SEC_EJEC,X1.NRO_CERTIFICA, A1.NRO_CONSOLID,
C1.FUENTE_FINANC, R.COD_NIVEL1, R.COD_NIVEL2, D1.SEC_FUNC, D1.CLASIFICADOR
GO


