IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PRIMER_REPORTE_VW_DETA_DOCW]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PRIMER_REPORTE_VW_DETA_DOCW]
