GO

CREATE VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_CONT] AS SELECT D.ANO_CONTRATO, 
D.ANO_EJE,D.SEC_EJEC,D.NRO_CERTIFICA, A1.NRO_CONTRATO, R.FUENTE_FINANC, 
F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR, COUNT(*) CUENTA, SUM(COALESCE(R.VALOR_SOLES,0)) TOTAL
FROM SIG_CERTIFICACION_FASE A1, SIG_ORDEN_ADQUISICION D, SIG_ORDEN_SECUENCIA S, 
SIG_ORDEN_PRESUPUESTO R, SIG_CLASIFICADOR_GASTO F
WHERE 
A1.ANO_EJE = D.ANO_EJE AND A1.SEC_EJEC = D.SEC_EJEC AND
A1.NRO_CERTIFICA = D.NRO_CERTIFICA AND
A1.SEC_FASE = 2 AND 
(
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) > 0 AND COALESCE(A1.NRO_ORDEN,0) =0) OR
(COALESCE(A1.NRO_CONSOLID,0) = 0  AND COALESCE(A1.NRO_CONTRATO,0) > 0 AND COALESCE(A1.NRO_ORDEN,0) =0)
) AND
(COALESCE(A1.NRO_CONTRATO,0) = COALESCE(D.SEC_CONTRATO,0) AND COALESCE(A1.NRO_ORDEN,0) =0 ) AND
D.ANO_EJE = S.ANO_EJE AND
D.SEC_EJEC = S.SEC_EJEC AND
D.TIPO_PPTO = S.TIPO_PPTO AND
D.TIPO_BIEN = S.TIPO_BIEN AND
D.NRO_ORDEN = S.NRO_ORDEN AND
R.ANO_EJE = S.ANO_EJE AND
R.SEC_EJEC = S.SEC_EJEC AND
R.TIPO_PPTO = S.TIPO_PPTO AND
R.TIPO_BIEN = S.TIPO_BIEN AND
R.NRO_ORDEN = S.NRO_ORDEN AND
R.SEC_ORDEN = S.SEC_ORDEN AND
F.ANO_EJE = R.ANO_EJE AND
F.CLASIFICADOR = R.CLASIFICADOR
GROUP BY D.ANO_CONTRATO, 
D.ANO_EJE,D.SEC_EJEC,D.NRO_CERTIFICA, A1.NRO_CONTRATO, R.FUENTE_FINANC, F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_SEGUNDO_REPORTE_VW_DETA_DOCU
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_SEGUNDO_REPORTE_VW_DETA_DOCU]') AND type IN ('V'))
	DROP VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_DOCU]
GO

CREATE VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_DOCU] AS SELECT A.ANO_EJE XANO_EJE,
A.SEC_EJEC XSEC_EJEC,A.FUENTE_FINANC XFUENTE_FINANC,  
A.COD_NIVEL1 XCOD_NIVEL1, A.COD_NIVEL2 XCOD_NIVEL2,
A.CLASIFICADOR XCLASIFICADOR,SUM(A.TOTAL) XTOTAL
FROM
(
SELECT D.ANO_EJE,D.SEC_EJEC,D.FUENTE_FINANC, 
D.COD_NIVEL1, D.COD_NIVEL2,D.CLASIFICADOR, (coalesce(SUM(D.TOTAL),0) - coalesce(SUM(B.TOTAL),0)) TOTAL
FROM V_SEGUNDO_REPORTE_VW_DETA_ORDX D LEFT OUTER JOIN V_SEGUNDO_REPORTE_VW_DETA_ORDT B ON
B.ANO_EJE = D.ANO_EJE AND
B.SEC_EJEC = D.SEC_EJEC AND
B.FUENTE_FINANC = D.FUENTE_FINANC AND
B.COD_NIVEL1 = D.COD_NIVEL1 AND
B.COD_NIVEL2 = D.COD_NIVEL2 AND
B.CLASIFICADOR = D.CLASIFICADOR
GROUP BY 
D.ANO_EJE,D.SEC_EJEC,D.FUENTE_FINANC, 
D.COD_NIVEL1,D.COD_NIVEL2,D.CLASIFICADOR
HAVING coalesce(SUM(D.TOTAL),0) - coalesce(SUM(B.TOTAL),0) <> 0

UNION

SELECT V.ANO_EJE_DOC ANO_EJE, V.SEC_EJEC,V.FUENTE_FINANC,  
V.COD_NIVEL1, V.COD_NIVEL2,V.CLASIFICADOR,coalesce(SUM(V.TOTAL),0) - coalesce(SUM(W.TOTAL),0) TOTAL
FROM  V_SEGUNDO_REP_VW_DETA_CONTX V LEFT OUTER JOIN V_SEGUNDO_REP_VW_DETA_CONTT W ON
V.ANO_EJE_DOC = W.ANO_CONTRATO AND 
V.SEC_EJEC = W.SEC_EJEC AND
V.NRO_CERTIFICA = W.NRO_CERTIFICA AND
V.NRO_CONTRATO = W.NRO_CONTRATO AND
V.FUENTE_FINANC = W.FUENTE_FINANC AND
V.COD_NIVEL1 = W.COD_NIVEL1 AND
V.COD_NIVEL2 = W.COD_NIVEL2 AND
V.CLASIFICADOR  = W.CLASIFICADOR
GROUP BY
V.ANO_EJE_DOC , V.SEC_EJEC,V.FUENTE_FINANC,V.COD_NIVEL1, V.COD_NIVEL2,V.CLASIFICADOR
HAVING coalesce(SUM(V.TOTAL),0) - coalesce(SUM(W.TOTAL),0) <> 0
) A
GROUP BY
A.ANO_EJE,A.SEC_EJEC,A.FUENTE_FINANC,A.COD_NIVEL1 , A.COD_NIVEL2,A.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_SEGUNDO_REPORTE_VW_DETA_ORD
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORD]') AND type IN ('V'))
	DROP VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORD]
GO

CREATE VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORD] AS SELECT D.ANO_EJE,D.SEC_EJEC,D.NRO_CERTIFICA,A1.TIPO_BIEN,D.TIPO_PPTO,
A1.NRO_ORDEN, R.FUENTE_FINANC, F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR,
COUNT(*) CUENTA, SUM(COALESCE(R.VALOR_SOLES,0)) TOTAL
FROM SIG_CERTIFICACION_FASE A1, SIG_ORDEN_ADQUISICION D, SIG_ORDEN_SECUENCIA S, 
SIG_ORDEN_PRESUPUESTO R,SIG_CLASIFICADOR_GASTO F
WHERE 
A1.ANO_EJE = D.ANO_EJE AND A1.SEC_EJEC = D.SEC_EJEC AND
A1.NRO_CERTIFICA = D.NRO_CERTIFICA AND 
A1.SEC_FASE = 2 AND 
A1.TIPO_BIEN = D.TIPO_BIEN AND D.TIPO_PPTO = 1 AND
(
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='B') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='S') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='V')
) AND
(COALESCE(A1.NRO_ORDEN,0) = COALESCE(D.NRO_ORDEN,0) AND COALESCE(A1.NRO_ORDEN,0) > 0 ) AND
D.ANO_EJE = S.ANO_EJE AND
D.SEC_EJEC = S.SEC_EJEC AND
D.TIPO_PPTO = S.TIPO_PPTO AND
D.TIPO_BIEN = S.TIPO_BIEN AND
D.NRO_ORDEN = S.NRO_ORDEN AND
R.ANO_EJE = S.ANO_EJE AND
R.SEC_EJEC = S.SEC_EJEC AND
R.TIPO_PPTO = S.TIPO_PPTO AND
R.TIPO_BIEN = S.TIPO_BIEN AND
R.NRO_ORDEN = S.NRO_ORDEN AND
R.SEC_ORDEN = S.SEC_ORDEN AND
F.ANO_EJE = R.ANO_EJE AND
F.CLASIFICADOR = R.CLASIFICADOR
GROUP BY 
D.ANO_EJE,D.SEC_EJEC,D.NRO_CERTIFICA,A1.TIPO_BIEN,D.TIPO_PPTO,A1.NRO_ORDEN, R.FUENTE_FINANC,F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_SEGUNDO_REPORTE_VW_DETA_ORDT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDT]') AND type IN ('V'))
	DROP VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDT]
GO

CREATE VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDT] AS SELECT D.ANO_EJE,D.SEC_EJEC,R.FUENTE_FINANC, 
F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR,SUM(COALESCE(R.VALOR_SOLES,0)) TOTAL
FROM SIG_CERTIFICACION_FASE A1, SIG_ORDEN_ADQUISICION D, SIG_ORDEN_SECUENCIA S, SIG_ORDEN_PRESUPUESTO R,
SIG_CLASIFICADOR_GASTO F
WHERE 
A1.ANO_EJE = D.ANO_EJE AND A1.SEC_EJEC = D.SEC_EJEC AND
A1.NRO_CERTIFICA = D.NRO_CERTIFICA AND 
A1.SEC_FASE = 2 AND 
A1.TIPO_BIEN = D.TIPO_BIEN AND D.TIPO_PPTO = 1 AND
(
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='B') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='S') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='V')
) AND
(COALESCE(A1.NRO_ORDEN,0) = COALESCE(D.NRO_ORDEN,0) AND COALESCE(A1.NRO_ORDEN,0) > 0 ) AND
D.ANO_EJE = S.ANO_EJE AND
D.SEC_EJEC = S.SEC_EJEC AND
D.TIPO_PPTO = S.TIPO_PPTO AND
D.TIPO_BIEN = S.TIPO_BIEN AND
D.NRO_ORDEN = S.NRO_ORDEN AND
R.ANO_EJE = S.ANO_EJE AND
R.SEC_EJEC = S.SEC_EJEC AND
R.TIPO_PPTO = S.TIPO_PPTO AND
R.TIPO_BIEN = S.TIPO_BIEN AND
R.NRO_ORDEN = S.NRO_ORDEN AND
R.SEC_ORDEN = S.SEC_ORDEN AND
F.ANO_EJE = R.ANO_EJE AND
F.CLASIFICADOR = R.CLASIFICADOR
GROUP BY D.ANO_EJE,D.SEC_EJEC,R.FUENTE_FINANC,F.COD_NIVEL1, F.COD_NIVEL2,R.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_SEGUNDO_REPORTE_VW_DETA_ORDX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDX]') AND type IN ('V'))
	DROP VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDX]
GO

CREATE VIEW [dbo].[V_SEGUNDO_REPORTE_VW_DETA_ORDX] AS SELECT 
A1.ANO_EJE,
A1.SEC_EJEC,
C1.FUENTE_FINANC,
SCG.COD_NIVEL1,
SCG.COD_NIVEL2,
D1.CLASIFICADOR,
COUNT(*) CUENTA,
SUM(
CASE
WHEN B1.SEC_OPERA = 1 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 2 THEN COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 3 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
WHEN B1.SEC_OPERA = 4 THEN (-1)*COALESCE(D1.VALOR_SOLES,0)
END) TOTAL
FROM 
SIG_CERTIFICACION X1, SIG_CERTIFICACION_FASE A1, SIG_CERTIFICACION_OPERACION B1,
SIG_CERTIFICACION_OPER_FUENTE C1, SIG_CERTIFICACION_PPTO D1, SIG_CLASIFICADOR_GASTO SCG
WHERE 
A1.ANO_EJE = X1.ANO_EJE AND A1.SEC_EJEC = X1.SEC_EJEC AND
A1.NRO_CERTIFICA = X1.NRO_CERTIFICA AND
 
A1.ANO_EJE = B1.ANO_EJE AND A1.SEC_EJEC = B1.SEC_EJEC AND
A1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND A1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
 
C1.ANO_EJE = B1.ANO_EJE AND C1.SEC_EJEC = B1.SEC_EJEC AND
C1.NRO_CERTIFICA = B1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = B1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = B1.SECUENCIA_OPERA AND
 
C1.ANO_EJE = D1.ANO_EJE AND C1.SEC_EJEC = D1.SEC_EJEC AND
C1.NRO_CERTIFICA = D1.NRO_CERTIFICA AND C1.SECUENCIA_FASE = D1.SECUENCIA_FASE AND
C1.SECUENCIA_OPERA = D1.SECUENCIA_OPERA AND C1.SECUENCIA_DET = D1.SECUENCIA_DET AND

SCG.ANO_EJE = D1.ANO_EJE AND
SCG.CLASIFICADOR = D1.CLASIFICADOR AND

A1.SEC_FASE = 2 AND 

(
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='B') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='S') OR
(COALESCE(A1.NRO_CONSOLID,0) > 0  AND COALESCE(A1.NRO_CONTRATO,0) = 0 AND COALESCE(A1.NRO_ORDEN,0) >0 and A1.TIPO_BIEN='V')
)
GROUP BY 
A1.ANO_EJE,A1.SEC_EJEC,C1.FUENTE_FINANC,SCG.COD_NIVEL1,SCG.COD_NIVEL2,D1.CLASIFICADOR
GO


-- ----------------------------
-- View structure for V_TERCER_REPORTE_VW
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_TERCER_REPORTE_VW]') AND type IN ('V'))
	DROP VIEW [dbo].[V_TERCER_REPORTE_VW]
GO

CREATE VIEW [dbo].[V_TERCER_REPORTE_VW] AS SELECT X.ANO_EJE, X.SEC_EJEC, 
X.FUENTE_FINANC, Y.FUENTE_FINANC_AGREGADA,
Z.CLASIFICADOR, SUM(X.PPTO_MODIF) VALOR_PIM, 
SUM(X.PPTO_PIA) -SUM(X.PPTO_CONTAB) VALOR_PIA
FROM SIG_TECHO_PRESUPUESTO X, FUENTE_FINANC Y, SIG_CLASIFICADOR_GASTO Z
WHERE
X.ANO_EJE =Y.ANO_EJE AND
X.FUENTE_FINANC = Y.FUENTE_FINANC AND
X.ANO_EJE = Z.ANO_EJE AND
X.CLASIFICADOR = Z.CLASIFICADOR AND
X.FLAG_META_APROB = '1' AND
X.INDICADOR = '4'
GROUP BY X.ANO_EJE, X.SEC_EJEC, 
X.FUENTE_FINANC, Y.FUENTE_FINANC_AGREGADA,
Z.CLASIFICADOR
GO


-- ----------------------------
-- View structure for VCATALOGOORIGINAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VCATALOGOORIGINAL]') AND type IN ('V'))
	DROP VIEW [dbo].[VCATALOGOORIGINAL]
GO

CREATE VIEW [dbo].[VCATALOGOORIGINAL] AS SELECT c.TIPO_BIEN+   
         c.GRUPO_BIEN+  
         c.CLASE_BIEN+  
         c.FAMILIA_BIEN+  
         c.ITEM_BIEN AS CODIGO_BIEN   ,
         u.nombre,
         c.NOMBRE_ITEM,
	 c.unidad_adquis	
       /*  CATALOGO_BIEN_SERV_ORIGINAL.ESTADO  ,
	 CATALOGO_BIEN_SERV_ORIGINAL.TIPO_BIEN,
         CATALOGO_BIEN_SERV_ORIGINAL.GRUPO_BIEN,
         CATALOGO_BIEN_SERV_ORIGINAL.CLASE_BIEN,  
         CATALOGO_BIEN_SERV_ORIGINAL.FAMILIA_BIEN,
         CATALOGO_BIEN_SERV_ORIGINAL.ITEM_BIEN*/
    FROM CATALOGO_BIEN_SERV_ORIGINAL c,
	 unidad_medida u
   WHERE c.ESTADO = 'A' and
	 c.unidad_adquis = u.unidad_medida
GO


-- ----------------------------
-- View structure for VCatalogoXClasificador
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VCatalogoXClasificador]') AND type IN ('V'))
	DROP VIEW [dbo].[VCatalogoXClasificador]
GO

CREATE VIEW [dbo].[VCatalogoXClasificador] AS SELECT DISTINCT CATALOGO_BIEN_SERV_ORIGINAL.TIPO_BIEN,   
         CATALOGO_BIEN_SERV_ORIGINAL.GRUPO_BIEN,   
         CATALOGO_BIEN_SERV_ORIGINAL.CLASE_BIEN,   
         CATALOGO_BIEN_SERV_ORIGINAL.FAMILIA_BIEN,   
         CATALOGO_BIEN_SERV_ORIGINAL.ITEM_BIEN,   
         CATALOGO_BIEN_SERV_ORIGINAL.NOMBRE_ITEM,   
         CATALOGO_BIEN_SERV_ORIGINAL.FLAG_ACTIVO,   
         CATALOGO_BIEN_SERV_ORIGINAL.UNIDAD_MEDIDA,   
         unidad_medida.NOMBRE,   
         CATALOGO_BIEN_SERV_ORIGINAL.FECHA_ALTA,   
         SIG_FAMILIA_CLASIFICADOR.TIPO_USO,   
         SIG_FAMILIA_CLASIFICADOR.CLASIFICADOR  
    FROM CATALOGO_BIEN_SERV_ORIGINAL,   
         unidad_medida,   
         SIG_FAMILIA_CLASIFICADOR  
   WHERE ( CATALOGO_BIEN_SERV_ORIGINAL.UNIDAD_MEDIDA = unidad_medida.UNIDAD_MEDIDA ) and  
         ( CATALOGO_BIEN_SERV_ORIGINAL.TIPO_BIEN = SIG_FAMILIA_CLASIFICADOR.TIPO_BIEN ) and  
		 ( SIG_FAMILIA_CLASIFICADOR.ano_eje = 2012 ) and	
         ( SIG_FAMILIA_CLASIFICADOR.GRUPO_BIEN = CATALOGO_BIEN_SERV_ORIGINAL.GRUPO_BIEN ) and  
         ( CATALOGO_BIEN_SERV_ORIGINAL.CLASE_BIEN = SIG_FAMILIA_CLASIFICADOR.CLASE_BIEN ) and  
         ( SIG_FAMILIA_CLASIFICADOR.FAMILIA_BIEN = CATALOGO_BIEN_SERV_ORIGINAL.FAMILIA_BIEN ) and  
         ( ( SIG_FAMILIA_CLASIFICADOR.TIPO_ACT_PROY = '1' ) AND  
         ( SIG_FAMILIA_CLASIFICADOR.ESTADO = 'A' )   
         )
GO


-- ----------------------------
-- View structure for VCLASIFICADORFAMILIA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VCLASIFICADORFAMILIA]') AND type IN ('V'))
	DROP VIEW [dbo].[VCLASIFICADORFAMILIA]
GO

CREATE VIEW [dbo].[VCLASIFICADORFAMILIA] AS select 	t1.codigo,
	t1.nombre_fam,
	t1.clasificador,
	( select nombre_clasif from SIG_CLASIFICADOR_GASTO g
	  where t1.clasificador = g.clasificador and g.ano_eje= 2009
	) as des_clasificador
	from
	(
	  SELECT FAMILIA_BIEN_SERV.TIPO_BIEN+  
	         FAMILIA_BIEN_SERV.GRUPO_BIEN+   
	         FAMILIA_BIEN_SERV.CLASE_BIEN+   
	         FAMILIA_BIEN_SERV.FAMILIA_BIEN as codigo,
		 FAMILIA_BIEN_SERV.nombre_fam as nombre_fam,
	         SIG_FAMILIA_CLASIFICADOR.CLASIFICADOR 
	    FROM FAMILIA_BIEN_SERV,   
		 SIG_FAMILIA_CLASIFICADOR  
	   WHERE ( FAMILIA_BIEN_SERV.TIPO_BIEN = SIG_FAMILIA_CLASIFICADOR.TIPO_BIEN ) and  
	         ( SIG_FAMILIA_CLASIFICADOR.GRUPO_BIEN = FAMILIA_BIEN_SERV.GRUPO_BIEN ) and  
	         ( FAMILIA_BIEN_SERV.CLASE_BIEN = SIG_FAMILIA_CLASIFICADOR.CLASE_BIEN ) and  
	         ( SIG_FAMILIA_CLASIFICADOR.FAMILIA_BIEN = FAMILIA_BIEN_SERV.FAMILIA_BIEN ) and  
	         ( SIG_FAMILIA_CLASIFICADOR.TIPO_ACT_PROY = '1' ) and  
	         ( SIG_FAMILIA_CLASIFICADOR.TIPO_USO = 'C' ) and  
		 ( SIG_FAMILIA_CLASIFICADOR.ano_eje= 2009 ) and
	         ( FAMILIA_BIEN_SERV.ESTADO = 'A' ) AND  
	         ( SIG_FAMILIA_CLASIFICADOR.ESTADO = 'A' )
		
	) T1
WHERE CODIGO in
(
	select tp.codigo
	from
	(
		select 	t1.codigo,
			count( t1.clasificador) as cantidad
			from
			(
			  SELECT FAMILIA_BIEN_SERV.TIPO_BIEN+  
			         FAMILIA_BIEN_SERV.GRUPO_BIEN+   
			         FAMILIA_BIEN_SERV.CLASE_BIEN+   
			         FAMILIA_BIEN_SERV.FAMILIA_BIEN as codigo,
				 FAMILIA_BIEN_SERV.nombre_fam as nombre_fam,
			         SIG_FAMILIA_CLASIFICADOR.CLASIFICADOR 
			    FROM FAMILIA_BIEN_SERV,   
				 SIG_FAMILIA_CLASIFICADOR  
		   WHERE ( FAMILIA_BIEN_SERV.TIPO_BIEN = SIG_FAMILIA_CLASIFICADOR.TIPO_BIEN ) and  
		         ( SIG_FAMILIA_CLASIFICADOR.GRUPO_BIEN = FAMILIA_BIEN_SERV.GRUPO_BIEN ) and  
		         ( FAMILIA_BIEN_SERV.CLASE_BIEN = SIG_FAMILIA_CLASIFICADOR.CLASE_BIEN ) and  
		         ( SIG_FAMILIA_CLASIFICADOR.FAMILIA_BIEN = FAMILIA_BIEN_SERV.FAMILIA_BIEN ) and  
		         ( SIG_FAMILIA_CLASIFICADOR.TIPO_ACT_PROY = '1' ) and  
		         ( SIG_FAMILIA_CLASIFICADOR.TIPO_USO = 'C' ) and  
			 ( SIG_FAMILIA_CLASIFICADOR.ano_eje= 2009 ) and
		         ( FAMILIA_BIEN_SERV.ESTADO = 'A' ) AND  
		         ( SIG_FAMILIA_CLASIFICADOR.ESTADO = 'A' )				
			) T1
		
		group by 
			t1.codigo
		having count( t1.clasificador) =1
	)tp
)
group by 
	t1.codigo,
	t1.nombre_fam,
	t1.clasificador
GO


-- ----------------------------
-- View structure for VProcesaCargaKit
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VProcesaCargaKit]') AND type IN ('V'))
	DROP VIEW [dbo].[VProcesaCargaKit]
GO

CREATE VIEW [dbo].[VProcesaCargaKit] AS SELECT 
		ssf.ano_eje, 					kit.sec_kit,	  				kit.sub_finalidad,    			ssf.id_sub_finalidad,		kit.tipo_bien,				kit.item_bien,  		
		kit.grupo_bien,     			kit.clase_bien,      			kit.familia_bien ,    			kit.item,  					 	kit.estado, 				kit.clasificador,  	kit.tipo_costo_di,
		kit.tipo_costo_fv,				kit.tipo_costo_dik, 			kit.agrupa_item,    			kit.um_uso,        			 	kit.cantidad_vez,  			kit.nro_veces,          
	   	(CASE WHEN ((kit.cantidad_caso IS NULL) OR (kit.cantidad_caso =0)) THEN 1 ELSE kit.cantidad_caso END)  cantidad_caso,
		(CASE WHEN ((kit.factor_convers IS NULL) OR (kit.factor_convers =0)) THEN 1 ELSE kit.factor_convers END)  factor_convers,
		coalesce(kit.porcent_uso,1) 	porcent_uso,  				   	coalesce(kit.factor_merma,0) factor_merma, 
		kit.tipo_calculo, 				kit.categ_i_1,      			kit.flag_i_1,       	
		kit.categ_i_2,      			kit.flag_i_2,        			kit.categ_i_3,        			kit.flag_i_3,       			kit.categ_i_4,        		kit.flag_i_4,        	kit.categ_ii_1,      	
		kit.flag_ii_1,       			kit.categ_ii_2 ,     			kit.flag_ii_2 ,       			kit.categ_iii_1,         		kit.flag_iii_1,      		kit.categ_iii_2,     	kit.flag_iii_2,      
		kit.categ_eess_movil, 			kit.flag_eess_movil,  			kit.categ_disa,       			kit.flag_disa,      	   		kit.categ_red,        		kit.flag_red,        	kit.categ_mred,     	
		kit.flag_mred ,      			kit.categ_minsa,     			kit.flag_minsa ,      			kit.categ_14,         		 	kit.flag_14,          		kit.categ_15,         kit.flag_15,         	
		kit.categ_16 ,       			kit.flag_16 ,        		   	kit.categ_99 ,       			kit.flag_99 ,  					kit.especificacion,   		kit.prog_rector,     			kit.compl_sustit,    		kit.version , 		cO.flag_activo activo, 		
		ssf.componente ,				ssf.ACT_PROY ,					ssf.FINALIDAD, 					kit.nivel ,      				ssf.PROGRAMA_INSTITUCIONAL Programa , 				kit.F_GENERACION                  ,
    COALESCE(kit.S_CRITICO, 'N') AS S_CRITICO, kit.S_TIPO ,kit.S_FINANCIA ,kit.S_CLASIFICA 
		FROM tmp_carga_kit kit,	
	CATALOGO_BIEN_SERV_ORIGINAL co,
	SIG_SUB_FINALIDAD ssf with (index(IND_sub_finalidad01))
	 WHERE 
	 kit.nivel='I' AND
	 CO.TIPO_BIEN=KIT.tipo_bien AND
	 CO.GRUPO_BIEN= KIT.grupo_bien AND
	 CO.CLASE_BIEN= KIT.clase_bien AND
	 CO.FAMILIA_BIEN =KIT.FAMILIA_BIEN AND
	 CO.ITEM_BIEN = KIT.item AND
	 co. estado ='A' AND
		ssf.sub_finalidad= kit.sub_finalidad AND
	 ssf.estado='A' AND
	 ssf.ano_eje= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND
	 EXISTS ( SELECT * FROM SIG_FAMILIA_CLASIFICADOR sfc with (index(IND_FAM_CLAS_04))
	 	WHERE kit.tipo_bien= sfc.TIPO_BIEN AND
	 kit.grupo_bien= sfc.GRUPO_BIEN AND
	 kit.clase_bien = sfc.CLASE_BIEN AND
	 kit.familia_bien= sfc.FAMILIA_BIEN AND
	 kit.clasificador= sfc.CLASIFICADOR  AND
	 sfc.ESTADO='A' AND
	 sfc.ANO_EJE=  ssf.ano_eje AND
	 sfc.TIPO_ACT_PROY='1' AND
	 sfc.TIPO_USO='C' )
UNION ALL	  
	SELECT 
		ssf.ano_eje, 					kit.sec_kit,	  				kit.sub_finalidad,    			ssf.id_sub_finalidad,		kit.tipo_bien,				kit.item_bien,  	   
		kit.grupo_bien,     			kit.clase_bien,      			kit.familia_bien ,    			kit.item,  					 	kit.estado, 				kit.clasificador,  	kit.tipo_costo_di,
		kit.tipo_costo_fv,				kit.tipo_costo_dik, 			kit.agrupa_item,    			kit.um_uso,        			 	kit.cantidad_vez,  			kit.nro_veces,          
		(CASE WHEN ((kit.cantidad_caso IS NULL) OR (kit.cantidad_caso =0)) THEN 1 ELSE kit.cantidad_caso END)  cantidad_caso,
		(CASE WHEN ((kit.factor_convers IS NULL) OR (kit.factor_convers =0)) THEN 1 ELSE kit.factor_convers END)  factor_convers,
		coalesce(kit.porcent_uso,1) 	porcent_uso,  				   	coalesce(kit.factor_merma,0) factor_merma, 
		kit.tipo_calculo, 				kit.categ_i_1,      			kit.flag_i_1,       	
		kit.categ_i_2,      			kit.flag_i_2,        			kit.categ_i_3,        			kit.flag_i_3,       			kit.categ_i_4,        		kit.flag_i_4,        	kit.categ_ii_1,      	
		kit.flag_ii_1,   		   		kit.categ_ii_2 ,     			kit.flag_ii_2 ,       			kit.categ_iii_1,         		kit.flag_iii_1,      	   	kit.categ_iii_2,     	kit.flag_iii_2,      
		kit.categ_eess_movil, 			kit.flag_eess_movil,  			kit.categ_disa,       			kit.flag_disa,      	   		kit.categ_red,        		kit.flag_red,        	kit.categ_mred,     	
		kit.flag_mred ,      			kit.categ_minsa,     			kit.flag_minsa ,      			kit.categ_14,         		 	kit.flag_14,          		kit.categ_15,        	 kit.flag_15,         	
		kit.categ_16 ,       			kit.flag_16 ,        		    kit.categ_99 ,       			kit.flag_99 ,  
		kit.especificacion,   			kit.prog_rector,     			kit.compl_sustit,    		kit.version , 		   NULL activo, 		
		ssf.componente ,				ssf.ACT_PROY ,					ssf.FINALIDAD, 					kit.nivel ,      				ssf.PROGRAMA_INSTITUCIONAL Programa , 				kit.F_GENERACION               ,
    COALESCE(kit.S_CRITICO, 'N') AS S_CRITICO, kit.S_TIPO ,kit.S_FINANCIA ,kit.S_CLASIFICA 
    FROM tmp_carga_kit kit,	
     	SIG_SUB_FINALIDAD ssf with (index(IND_sub_finalidad01))
	 WHERE 
	 ssf.ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND
	 kit.nivel='F' and
	  ssf.sub_finalidad= kit.sub_finalidad AND
	 ssf.estado='A'  AND
	 EXISTS ( SELECT 1 
					FROM	familia_bien_serv FBS 
					WHERE 	FBS.TIPO_BIEN+FBS.grupo_bien+FBS.clase_bien+FBS.familia_bien=KIT.tipo_bien+KIT.GRUPO_BIEN+KIT.clase_bien+KIT.FAMILIA_BIEN AND
					FBS.ESTADO			='A' )   AND
	 EXISTS ( SELECT 1 
					 FROM SIG_FAMILIA_CLASIFICADOR sfc with (index(IND_FAM_CLAS_04))
					 	WHERE kit.tipo_bien= sfc.TIPO_BIEN AND
					 kit.grupo_bien= sfc.GRUPO_BIEN AND
					 kit.clase_bien = sfc.CLASE_BIEN AND
					 kit.familia_bien= sfc.FAMILIA_BIEN AND
					 kit.clasificador= sfc.CLASIFICADOR  AND
					 sfc.ESTADO='A' AND
					 sfc.ANO_EJE=  ssf.ano_eje AND
					 sfc.TIPO_ACT_PROY='1' AND
					 sfc.TIPO_USO='C' )
GO


-- ----------------------------
-- View structure for VW_CLASIFICADORES_DE_GASTO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VW_CLASIFICADORES_DE_GASTO]') AND type IN ('V'))
	DROP VIEW [dbo].[VW_CLASIFICADORES_DE_GASTO]
GO

CREATE VIEW [dbo].[VW_CLASIFICADORES_DE_GASTO] AS SELECT  DISTINCT
SUBSTRING(CLASIFICADOR,1,1) C_TIPO_TRANSACCION, 
(SELECT NOMBRE_CLASIF FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE = 2011 AND CLASIFICADOR = SUBSTRING(CLA.CLASIFICADOR,1,1) + '.0. 0  0. 0  0') 
D_TIPO_TRANSACCION,
SUBSTRING(CLASIFICADOR,3,1) C_GENERICA, 
(SELECT SUBSTRING(CLASIFICADOR,3,1) + ' '+ NOMBRE_CLASIF FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE = 2011 AND CLASIFICADOR = SUBSTRING(CLA.CLASIFICADOR,1,3) + '. 0  0. 0  0') 
D_GENERICA,
REPLACE(SUBSTRING(CLASIFICADOR,3,4), ' ','') C_SUB_GENERICA_1, 
(SELECT REPLACE(SUBSTRING(CLASIFICADOR,3,4), ' ','') + ' ' + NOMBRE_CLASIF FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE = 2011 AND CLASIFICADOR = SUBSTRING(CLA.CLASIFICADOR,1,6) + '  0. 0  0') 
D_SUB_GENERICA_1,
REPLACE(SUBSTRING(CLASIFICADOR,3,7), ' ','') C_SUB_GENERICA_2, 
(SELECT REPLACE(SUBSTRING(CLASIFICADOR,3,7), ' ','') + ' ' + NOMBRE_CLASIF FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE = 2011 AND CLASIFICADOR = SUBSTRING(CLA.CLASIFICADOR,1,9) + '. 0  0') 
D_SUB_GENERICA_2,
REPLACE(SUBSTRING(CLASIFICADOR,3,10), ' ','') C_ESPECIFICA, 
(SELECT REPLACE(SUBSTRING(CLASIFICADOR,3,10), ' ','') + ' ' + NOMBRE_CLASIF FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE = 2011 AND CLASIFICADOR = SUBSTRING(CLA.CLASIFICADOR,1,12) + '  0') 
D_ESPECIFICA,
REPLACE(SUBSTRING(CLASIFICADOR,3,13), ' ','') C_ESPECIFICA_1, 
REPLACE(SUBSTRING(CLASIFICADOR,3,13), ' ','') + ' ' +NOMBRE_CLASIF D_ESPECIFICA_1
FROM SIG_CLASIFICADOR_GASTO CLA
WHERE ANO_EJE >= 2009
GO


-- ----------------------------
-- View structure for vw_config_prog
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_config_prog]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_config_prog]
GO

CREATE VIEW [dbo].[vw_config_prog] AS SELECT 	 FIN.ano_eje,
		 FIN.sec_ejec,
		 FIN.nro_fase,
		 FIN.sec_func,
		CSD.SEC_ESTABLEC,
		 FIN.SUB_FINALIDAD,
		 FIN.ID_SUB_FINALIDAD
   FROM  sig_ppr_metfis_x_subfin FIN 
    JOIN SIG_PPR_META_PROPUESTA MP ON  (MP.ANO_EJE = FIN.ANO_EJE	AND		MP.SEC_EJEC      = FIN.SEC_EJEC AND
											       MP.NRO_FASE      = FIN.NRO_FASE AND      MP.SEC_FUNC_PROP = FIN.SEC_FUNC AND
											       MP.FLAG_ESTRATEGIA = 'S') 
    JOIN SIG_PPR_SEDE CSD 			ON		(MP.ANO_EJE      = CSD.ANO_EJE  and	   MP.SEC_EJEC     = CSD.SEC_EJEC and
											       CSD.sec_establec = fin.sec_establec) 
    JOIN sig_metas_prop_x_centro mxc ON	(mxc.ano_eje       = csd.ano_eje and	 mxc.sec_ejec      = csd.sec_ejec and
														 MXC.CENTRO_COSTO IS NOT NULL 	AND	MXC.SECUENCIA IS NOT NULL		AND
													   mxc.sec_func_prop = MP.SEC_FUNC_PROP )
    JOIN sig_centro_costo  scc ON			( SCC.ANO_EJE      = mxc.ANO_EJE  and	  SCC.SEC_EJEC     = mxc.SEC_EJEC and
												   scc.centro_costo = mxc.centro_costo and	   scc.pliego       = CSD.pliego and
												   scc.sede         = CSD.sede  and		   scc.estado       = 'A')
    JOIN SIG_SEDES DSD ON						( DSD.SEDE   = CSD.SEDE and			DSD.PLIEGO = CSD.PLIEGO ) ,
         sig_ppr_establecimiento eess,
         sig_centro_costo_tarea CCT,   
         SIG_TAREA_ESTRATEGICO MXT 
   WHERE  eess.ano_eje      = CSD.ANO_EJE      AND
         eess.sec_ejec     = CSD.SEC_EJEC     AND
         eess.cod_establec = CSD.cod_establec AND
         CCT.sec_ejec      = MXT.SEC_EJEC and  
         CCT.ano_eje       = MXT.ANO_EJE and  
         CCT.centro_costo  = scc.centro_costo AND  
         CCT.tipo_tarea    = MXT.TIPO_TAREA and  
         CCT.nivel_tarea   = MXT.NIVEL_TAREA and  
         CCT.codigo_tarea  = MXT.TAREA_GENERAL and  
         CCT.ano_eje       = SCC.ANO_EJE AND  
         CCT.sec_ejec      = SCC.SEC_EJEC AND  
         MXT.subfinalidad = FIN.SUB_FINALIDAD AND
         MXT.id_sub_finalidad=FIN.ID_SUB_FINALIDAD		
union
SELECT 	FIN.ano_eje,
		 FIN.sec_ejec,
		 FIN.nro_fase,
		 FIN.sec_func,
		CSD.SEC_ESTABLEC,
		 FIN.SUB_FINALIDAD,
		 FIN.ID_SUB_FINALIDAD
   FROM  sig_ppr_metfis_x_subfin FIN 
    JOIN SIG_PPR_META_PROPUESTA MP ON  (MP.ANO_EJE       = FIN.ANO_EJE	AND		MP.SEC_EJEC      = FIN.SEC_EJEC AND
											       MP.NRO_FASE      = FIN.NRO_FASE AND      MP.SEC_FUNC_PROP = FIN.SEC_FUNC AND
											       MP.FLAG_ESTRATEGIA = 'S') 
    JOIN SIG_PPR_SEDE CSD 			ON		(MP.ANO_EJE      = CSD.ANO_EJE  and	   MP.SEC_EJEC     = CSD.SEC_EJEC and
											       CSD.sec_establec = fin.sec_establec) 
    JOIN sig_metas_x_centro mxc ON	(mxc.ano_eje       = csd.ano_eje and	 mxc.sec_ejec      = csd.sec_ejec and
														 MXC.CENTRO_COSTO IS NOT NULL 	AND	MXC.SECUENCIA	IS NOT NULL	AND
													    mxc.sec_func = MP.SEC_FUNC)

    JOIN sig_centro_costo  scc ON		( SCC.ANO_EJE      = mxc.ANO_EJE  and		   SCC.SEC_EJEC     = mxc.SEC_EJEC and
													   scc.centro_costo = mxc.centro_costo and   scc.pliego       = CSD.pliego and
													   scc.sede         = CSD.sede  and		   scc.estado       = 'A')
    JOIN SIG_SEDES DSD ON					( DSD.SEDE   = CSD.SEDE and		   DSD.PLIEGO = CSD.PLIEGO ) ,
         sig_ppr_establecimiento eess,
         sig_centro_costo_tarea CCT,   
         SIG_TAREA_ESTRATEGICO MXT 
   WHERE 
         eess.ano_eje      = CSD.ANO_EJE      AND
         eess.sec_ejec     = CSD.SEC_EJEC     AND
         eess.cod_establec = CSD.cod_establec AND
         CCT.sec_ejec      = MXT.SEC_EJEC and  
         CCT.ano_eje       = MXT.ANO_EJE and  
         CCT.centro_costo  = scc.centro_costo AND  
         CCT.tipo_tarea    = MXT.TIPO_TAREA and  
         CCT.nivel_tarea   = MXT.NIVEL_TAREA and  
         CCT.codigo_tarea  = MXT.TAREA_GENERAL and  
         CCT.ano_eje       = SCC.ANO_EJE AND  
         CCT.sec_ejec      = SCC.SEC_EJEC AND  
         MXT.subfinalidad = FIN.SUB_FINALIDAD AND
         MXT.id_sub_finalidad=FIN.ID_SUB_FINALIDAD
GO


-- ----------------------------
-- View structure for vw_cruza_metas_fisicas
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_cruza_metas_fisicas]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_cruza_metas_fisicas]
GO

CREATE VIEW [dbo].[vw_cruza_metas_fisicas] AS SELECT DISTINCT a.sec_ejec, 
a.sec_establec,
c.sector_ambito,
a.sub_finalidad,
a.id_sub_finalidad,
cantidad mf_2012, 0 mf_2013, 0 mf_2014
FROM sig_ppr_metfis_x_subfin a,
sig_ppr_sede b,
SIG_PPR_ESTABLECIMIENTO c
WHERE b.ANO_EJE		= c.ANO_EJE
AND b.SEC_EJEC 		= c.SEC_EJEC
AND b.SEC_ESTABLEC  = a.sec_establec
AND c.ANO_EJE 		= a.ANO_EJE
AND c.SEC_EJEC 		= a.SEC_EJEC
AND c.COD_ESTABLEC  = b.COD_ESTABLEC
AND a.ano_eje 		= 2012
AND a.nro_fase		= 1
AND a.sub_finalidad in (select DISTINCT(sub_finalidad) from sig_sub_finalidad
                      where ano_eje = 2014 and sub_finalidad = a.sub_finalidad  
                      AND estado='A')
AND a.sec_establec  in (select DISTINCT(sec_establec) from sig_ppr_sede
                      where ano_eje = 2014 and sec_establec = a.sec_establec)
UNION
select distinct a.sec_ejec, 
a.sec_establec,
c.sector_ambito,
a.sub_finalidad,
a.ID_SUB_FINALIDAD,
0 mf_2012, a.cantidad mf_2013, 0 mf_2014
from sig_ppr_metfis_x_subfin a,
sig_ppr_sede b,
SIG_PPR_ESTABLECIMIENTO c
where b.ANO_EJE		= c.ANO_EJE
AND b.SEC_EJEC 		= c.SEC_EJEC
AND b.SEC_ESTABLEC  = a.sec_establec
AND c.ANO_EJE 		= a.ANO_EJE
AND c.SEC_EJEC 		= a.SEC_EJEC
AND c.COD_ESTABLEC  = b.COD_ESTABLEC
and a.ano_eje 		= 2013
and a.nro_fase		= 1
and a.sub_finalidad in (SELECT DISTINCT( sub_finalidad) from sig_sub_finalidad
                      where ano_eje = 2014 and sub_finalidad = a.sub_finalidad and estado='A' )
and a.sec_establec  in (select DISTINCT(sec_establec) from sig_ppr_sede
                      where ano_eje = 2014 and sec_establec = a.sec_establec)
UNION
select distinct a.sec_ejec, 
a.sec_establec,
c.sector_ambito,
a.sub_finalidad,
a.id_sub_finalidad,
0 mf_2012, 0 mf_2013, cantidad mf_2014
from sig_ppr_metfis_x_subfin a,
sig_ppr_sede b,
SIG_PPR_ESTABLECIMIENTO c
where b.ANO_EJE		= c.ANO_EJE
AND b.SEC_EJEC 		= c.SEC_EJEC
AND b.SEC_ESTABLEC  = a.sec_establec
AND c.ANO_EJE 		= a.ANO_EJE
AND c.SEC_EJEC 		= a.SEC_EJEC
AND c.COD_ESTABLEC  = b.COD_ESTABLEC
and a.ano_eje 		= 2014
and a.nro_fase		= 1
and a.sub_finalidad in (select DISTINCT(sub_finalidad) from sig_sub_finalidad
                      where ano_eje = 2014 and sub_finalidad = a.sub_finalidad and estado='A' AND
                      id_sub_finalidad=a.id_sub_finalidad)
and a.sec_establec  in (select DISTINCT(sec_establec) from sig_ppr_sede
                      where ano_eje = 2014 and sec_establec = a.sec_establec)
GO


-- ----------------------------
-- View structure for VW_EJECUTORAS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VW_EJECUTORAS]') AND type IN ('V'))
	DROP VIEW [dbo].[VW_EJECUTORAS]
GO

CREATE VIEW [dbo].[VW_EJECUTORAS] AS SELECT EJE.SEC_EJEC,
		EJE.SECTOR + ' ' + EJE.PLIEGO + ' ' + EJE.EJECUTORA + ' ' + EJE.NOMBRE D_EJECUTORA,
		EJE.EJECUTORA C_EJECUTORA,
		EJE.PLIEGO C_PLIEGO,
		EJE.PLIEGO + ' ' + PLI.NOMBRE D_PLIEGO,
		EJE.SECTOR C_SECTOR,
		EJE.SECTOR + ' ' + SEC.NOMBRE D_SECTOR
   FROM EJECUTORA EJE
   JOIN PLIEGO PLI
   ON ( EJE.PLIEGO = PLI.PLIEGO
   AND  EJE.SECTOR = PLI.SECTOR)
   JOIN SECTOR SEC
   ON ( EJE.SECTOR = SEC.SECTOR)
   WHERE EJE.ESTADO = 'A'
AND EJE.NOMBRE NOT LIKE '%MUNICIPAL%'
AND EJE.NOMBRE NOT LIKE '%MUN.%'
AND EJE.NOMBRE NOT LIKE '%MUNIC.%'
AND EJE.NOMBRE NOT LIKE '%MUNICIP.%'
GO


