CREATE VIEW [dbo].[VW_KIT_CATEGORIA] AS SELECT SEC_KIT,		1 CATEGORIA,		FLAG_I_1 FLAG , ID_SUB_FINALIDAD
  FROM VProcesaCargaKit 
 WHERE ANO_EJE = (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO') AND 
 	   CATEG_I_1=1 AND 
 	   estado ='A' AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		2 CATEGORIA, 		FLAG_I_2 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
 WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
 	   CATEG_I_2=1 AND 
 	   estado ='A' AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		3 CATEGORIA, 		FLAG_I_3 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
  		CATEG_I_3=1 AND 
  		estado ='A' AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		4 CATEGORIA,		FLAG_I_4 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
  		CATEG_I_4=1 AND 
  		estado ='A' AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		5 CATEGORIA,		FLAG_II_1 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND
  		CATEG_II_1=1 AND 
  		estado ='A' AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		6 CATEGORIA,		FLAG_II_2 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
  		CATEG_II_2=1 AND 
  		estado ='A'  AND
 	   TIPO_CALCULO IS NOT NULL
UNION ALL
SELECT SEC_KIT,		7 CATEGORIA,		FLAG_III_1 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')   AND 
  		CATEG_III_1=1 		AND 
  		estado ='A'			AND
 	   TIPO_CALCULO 		IS NOT NULL
UNION ALL
SELECT SEC_KIT,		8 CATEGORIA,		FLAG_III_2 FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
  		CATEG_III_2=1 AND 
  		estado ='A'AND
 	   TIPO_CALCULO 		IS NOT NULL
UNION ALL
SELECT SEC_KIT,		9 CATEGORIA,		FLAG_EESS_MOVIL FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO') AND 
  		CATEG_EESS_MOVIL=1 AND 
  		estado ='A'AND
 	   TIPO_CALCULO 		IS NOT NULL
UNION ALL
SELECT SEC_KIT,		10 CATEGORIA,		FLAG_DISA FLAG, ID_SUB_FINALIDAD
  FROM VProcesaCargaKit  
  WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
  		CATEG_DISA=1 AND 
  		estado  ='A'AND
 	   TIPO_CALCULO 		IS NOT NULL
UNION ALL
SELECT SEC_KIT,		11 CATEGORIA,		FLAG_RED FLAG, ID_SUB_FINALIDAD
FROM VProcesaCargaKit  
WHERE ANO_EJE= (SELECT max(sig_parametro_ejecutora.valor)
   								FROM sig_parametro_ejecutora  with (index(ind_sig_parametro_ejec_01))
   								WHERE cod_maestro = 'PROG_CN_ANO')  AND 
