-- ----------------------------
-- View structure for VW_KIT_EST_CATEGORIA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VW_KIT_EST_CATEGORIA]') AND type IN ('V'))
	DROP VIEW [dbo].[VW_KIT_EST_CATEGORIA]
GO

CREATE VIEW [dbo].[VW_KIT_EST_CATEGORIA] AS SELECT VKCAT.SEC_KIT,SEDE.SEC_ESTABLEC ,SEDE.SEC_EJEC, SEDE.ANO_EJE
FROM VW_KIT_CATEGORIA VKCAT,
SIG_PPR_SEDE SEDE,
SIG_PPR_ESTABLECIMIENTO ESTA
WHERE 
SEDE.ANO_EJE = ESTA.ANO_EJE AND
SEDE.SEC_EJEC = ESTA.SEC_EJEC AND
SEDE.COD_ESTABLEC= ESTA.COD_ESTABLEC AND
VKCAT.CATEGORIA= ESTA.CATEGORIA
GO


