-- ----------------------------
-- View structure for vw_meta_fisica_tri_anual
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_meta_fisica_tri_anual]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_meta_fisica_tri_anual]
GO

CREATE VIEW [dbo].[vw_meta_fisica_tri_anual] AS select distinct sec_ejec, sec_establec, sub_finalidad, cantidad mf_2010, 0 mf_2011, 0 mf_2012
from sig_ppr_metfis_x_subfin
where ano_eje = 2010 and nro_fase = 1
and sub_finalidad in (select sub_finalidad from sig_sub_finalidad
where ano_eje = 2012 and sub_finalidad = sig_ppr_metfis_x_subfin.sub_finalidad and ESTADO = 'A')
and sec_establec in (select sec_establec from sig_ppr_sede
where ano_eje = 2012 and sec_establec = sig_ppr_metfis_x_subfin.sec_establec)
union
select distinct sec_ejec, sec_establec, sub_finalidad, 0 mf_2010, cantidad mf_2011, 0 mf_2012
from sig_ppr_metfis_x_subfin
where ano_eje = 2011 and nro_fase = 1
and sub_finalidad in (select sub_finalidad from sig_sub_finalidad
where ano_eje = 2012 and sub_finalidad = sig_ppr_metfis_x_subfin.sub_finalidad and ESTADO = 'A')
and sec_establec in (select sec_establec from sig_ppr_sede
where ano_eje = 2012 and sec_establec = sig_ppr_metfis_x_subfin.sec_establec)
union
select distinct sec_ejec, sec_establec, sub_finalidad, 0 mf_2010, 0 mf_2011, cantidad mf_2012
from sig_ppr_metfis_x_subfin
where ano_eje = 2012 and nro_fase =1
and sub_finalidad in (select sub_finalidad from sig_sub_finalidad
where ano_eje = 2012 and sub_finalidad = sig_ppr_metfis_x_subfin.sub_finalidad  and ESTADO = 'A')
and sec_establec in (select sec_establec from sig_ppr_sede
where ano_eje = 2012 and sec_establec = sig_ppr_metfis_x_subfin.sec_establec)
GO


-- ----------------------------
-- View structure for vw_meta_fisica_tri_anual_expo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_meta_fisica_tri_anual_expo]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_meta_fisica_tri_anual_expo]
GO

CREATE VIEW [dbo].[vw_meta_fisica_tri_anual_expo] AS select  sec_ejec,PP,FINALIDAD,sub_finalidad,cod_renaes,categoria,mf_2010,mf_2011,mf_2012
from vw_meta_fisica_tri_anual_tabla
where mf_2010 > 0 or mf_2011 > 0 or mf_2012 > 0
GO


-- ----------------------------
-- View structure for vw_meta_fisica_tri_anual_tabla
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_meta_fisica_tri_anual_tabla]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_meta_fisica_tri_anual_tabla]
GO

CREATE VIEW [dbo].[vw_meta_fisica_tri_anual_tabla] AS select vw.sec_ejec,
(select cod_ogei from sig_ppr_establecimiento ee join sig_ppr_sede cd on (ee.ano_eje = cd.ano_eje and ee.sec_ejec = cd.sec_ejec and ee.cod_establec = cd.cod_establec) where cd.ano_eje = 2012 and cd.sec_ejec = vw.sec_ejec and cd.sec_establec = vw.sec_establec) cod_renaes,
(select CATEGORIA from sig_ppr_establecimiento ee join sig_ppr_sede cd on (ee.ano_eje = cd.ano_eje and ee.sec_ejec = cd.sec_ejec and ee.cod_establec = cd.cod_establec) where cd.ano_eje = 2012 and cd.sec_ejec = vw.sec_ejec and cd.sec_establec = vw.sec_establec) categoria,
 sf.PROGRAMA_INSTITUCIONAL PP,
 sf.FINALIDAD ,
vw.sub_finalidad,
sum(mf_2010) mf_2010,
sum(mf_2011) mf_2011,
sum(mf_2012) mf_2012
from vw_meta_fisica_tri_anual vw
join sig_sub_finalidad sf on (vw.SUB_FINALIDAD = sf.SUB_FINALIDAD and sf.ANO_EJE = 2012 and sf.ESTADO = 'A') 
group by vw.SEC_EJEC,
sf.PROGRAMA_INSTITUCIONAL,
sf.FINALIDAD ,
vw.sub_finalidad,
VW.SEC_ESTABLEC
GO


