CREATE VIEW [dbo].[VW_MVTO_COMPONENTE] AS SELECT MVC.SECUENCIA_MVTO,
	   MVC.SEC_EJEC,
	   MVC.SEDE,
	   MVC.NMB_SEDE,
	   MVC.SECUENCIA,
	   MVC.NMB_INMUEBLE,
	   MVC.SEC_UNIDAD_ACTIVO,
	   MVC.NMB_UACTIVO,
	   MVC.SEC_COMPONENTE,
	   MVC.NMB_COMPONENTE,
	   MVC.ANIO_CONTABLE,
	   (REPLICATE('0', (2 - LEN(MVC.MES_CONTABLE))) + CONVERT(VARCHAR,MVC.MES_CONTABLE)) AS MES_CONTABLE,
	   MVC.DETALLE_MOVIMTO,
	   MVC.DOC_SUSTENTO,
	   MVC.FEC_SUSTENTO,
	   MVC.VALOR_INICIAL AS VALOR_INICIAL_TEMP,
	   MVC.VALOR_AUMENTO,
	   CASE WHEN MVC.TIPO_MOVIMTO = 3 OR MVC.TIPO_MOVIMTO = 4
				 THEN (MVC.VALOR_INICIAL + COALESCE((SELECT SUM(COALESCE(VALOR_AUMENTO, 0) - COALESCE(VALOR_DISMINUCION, 0))
													   FROM dbo.VW_MVTO_COMPONENTE_TEMP MVCM
													  WHERE MVCM.SECUENCIA_MVTO    < MVC.SECUENCIA_MVTO
														AND MVCM.SECUENCIA         = MVC.SECUENCIA
														AND MVCM.SEC_UNIDAD_ACTIVO = MVC.SEC_UNIDAD_ACTIVO
														AND MVCM.SEC_COMPONENTE    = MVC.SEC_COMPONENTE), 0))
			ELSE MVC.VALOR_DISMINUCION
	   END AS VALOR_DISMINUCION,
	   MVC.PLIEGO
  FROM dbo.VW_MVTO_COMPONENTE_TEMP MVC
GO


-- ----------------------------
-- View structure for VW_MVTO_COMPONENTE_TEMP
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VW_MVTO_COMPONENTE_TEMP]') AND type IN ('V'))
	DROP VIEW [dbo].[VW_MVTO_COMPONENTE_TEMP]
GO

CREATE VIEW [dbo].[VW_MVTO_COMPONENTE_TEMP] AS SELECT
(ROW_NUMBER() OVER (PARTITION BY SECUENCIA, SEC_UNIDAD_ACTIVO, SEC_COMPONENTE
       ORDER BY SECUENCIA, SEC_UNIDAD_ACTIVO, SEC_COMPONENTE, ANIO_CONTABLE, MES_CONTABLE, FEC_SUSTENTO, DETALLE_MOVIMTO)) SECUENCIA_MVTO
,T_CONTABLE.*
FROM (
/*INICIO: MVTO REGISTRO INICIAL Y ALTA PARA EDIFICACIONES Y TERRENOS*/
SELECT
    INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,YEAR(CO.FECHA_ALTA) ANIO_CONTABLE
	,MONTH(CO.FECHA_ALTA) MES_CONTABLE
	,1 AS TIPO_MOVIMTO
	,CASE INM.TIPO_MOVIMTO
		WHEN 'A' THEN 'Registro Inicial'
		WHEN 'I' THEN 'Alta'
	END AS DETALLE_MOVIMTO
	,' ' AS DOC_SUSTENTO
	,NULL AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,0 AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO <> 'E'
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO <> 'E'
/*FIN: MVTO REGISTRO INICIAL Y ALTA PARA EDIFICACIONES Y TERRENOS*/

UNION
/*INICIO: MVTO AJUSTE POSTERIOR (AUMENTO Y DISMINUCIÓN) PARA EDIFICACIONES y TERRENOS*/
(
SELECT
     INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,ME.ANO_EJE AS ANIO_CONTABLE
	,ME.MES_MEJORA AS MES_CONTABLE
	,2 AS TIPO_MOVIMTO
	,AP.DESCRIPCION as DETALLE_MOVIMTO 
	,DME.DOCUMENTO_REFER AS DOC_SUSTENTO
	,DME.FECHA_REFER AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,CASE DME.TIPO_AJUSTE_DETALLE 
	 	WHEN '1' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '3' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '4' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '5' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '6' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	ELSE 0 END AS VALOR_AUMENTO
	,CASE DME.TIPO_AJUSTE_DETALLE 
	 	WHEN '2' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '7' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	WHEN '8' THEN COALESCE(DME.VALOR_MEJORA, 0) 
	 	ELSE 0 END AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO <> 'E'
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO <> 'E'
	INNER JOIN SIG_MEJORAS ME
	ON ME.SEC_EJEC = CO.SEC_EJEC
	AND ME.SECUENCIA = CO.SECUENCIA
	AND ME.SEC_UNIDAD_ACTIVO = CO.SEC_UNIDAD_ACTIVO
	AND ME.SEC_COMPONENTE = CO.SEC_COMPONENTE
	INNER JOIN SIG_DETALLE_MEJORAS DME 
	ON DME.SEC_EJEC = ME.SEC_EJEC
	AND DME.ANO_EJE = ME.ANO_EJE
	AND DME.SECUENCIA = ME.SECUENCIA
	AND DME.NRO_MEJORA = ME.NRO_MEJORA
	LEFT JOIN SIG_AJUSTE_POSTERIOR AP
	ON AP.VALOR_AJUSTE = DME.TIPO_AJUSTE_DETALLE 
	AND AP.NOMBRE_AJUSTE = 'SUB_TIPO_AJUSTE' 
WHERE
	ME.TIPO_PATRIMONIO = '2'

)
/*FIN: MVTO AJUSTE POSTERIOR (AUMENTO Y DISMINUCIÓN) PARA EDIFICACIONES Y TERRENOS*/

UNION
/*INICIO: MVTO DEVOLUCIÓN PARA EDIFICACIONES*/
SELECT
     INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,UA.ANO_BAJA AS ANIO_CONTABLE
	,UA.MES_BAJA AS MES_CONTABLE
	,3 AS TIPO_MOVIMTO
	,'Devuelto' AS DETALLE_MOVIMTO
	,UA.NRO_RESOLUCION_BAJA AS DOC_SUSTENTO
	,UA.FECHA_RESOLUCION_BAJA AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,0 AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO = 'D'
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO = 'D'
	AND NOT EXISTS(
	SELECT 1 FROM SIG_INM_UNIDAD_ACTIVO_BAJA UAB 
	WHERE UAB.SEC_EJEC = UA.SEC_EJEC 
	AND UAB.SECUENCIA = UA.SECUENCIA 
	AND UAB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	)
/*FIN: MVTO DEVOLUCIÓN PARA EDIFICACIONES*/

UNION
/*INICIO: MVTO DEVOLUCIÓN PARA TERRENOS*/
SELECT
     INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,UA.ANO_BAJA AS ANIO_CONTABLE
	,UA.MES_BAJA AS MES_CONTABLE
	,4 AS TIPO_MOVIMTO
	,'Devuelto' AS DETALLE_MOVIMTO
	,UA.NRO_RESOLUCION_BAJA AS DOC_SUSTENTO
	,UA.FECHA_RESOLUCION_BAJA AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,COALESCE(UAB.VALOR_COSTO, 0) + COALESCE(UAB.VALOR_AJUSTE_REV, 0)  AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO = 'D'
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO = 'D'
	INNER JOIN SIG_INM_UNIDAD_ACTIVO_BAJA UAB 
	ON UAB.SEC_EJEC = UA.SEC_EJEC 
	AND UAB.SECUENCIA = UA.SECUENCIA 
	AND UAB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	
/*FIN: MVTO DEVOLUCIÓN PARA TERRENOS*/

UNION
/*INICIO: MVTO BAJA PARA EDIFICACIONES (B:BAJA)*/
SELECT
     INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,UA.ANO_BAJA AS ANIO_CONTABLE
	,UA.MES_BAJA AS MES_CONTABLE
	,3 AS TIPO_MOVIMTO
	,'Baja' AS DETALLE_MOVIMTO
	,UA.NRO_RESOLUCION_BAJA AS DOC_SUSTENTO
	,UA.FECHA_RESOLUCION_BAJA AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,0 AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO = 'B'
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO = 'B'
	AND NOT EXISTS(
	SELECT 1 FROM SIG_INM_UNIDAD_ACTIVO_BAJA UAB 
	WHERE UAB.SEC_EJEC = UA.SEC_EJEC 
	AND UAB.SECUENCIA = UA.SECUENCIA 
	AND UAB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	)
/*FIN: MVTO BAJA PARA EDIFICACIONES*/
UNION
/*INICIO: MVTO BAJA PARA TERRENOS (B:TOTAL)*/
SELECT
    INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,UAB.ANO_BAJA AS ANIO_CONTABLE
	,UAB.MES_BAJA AS MES_CONTABLE	
	,5 AS TIPO_MOVIMTO
	,'Baja - total' AS DETALLE_MOVIMTO
	,UAB.NRO_RESOLUCION_BAJA AS DOC_SUSTENTO
	,UAB.FECHA_RESOLUCION_BAJA AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,COALESCE(UAB.VALOR_COSTO, 0) + COALESCE(UAB.VALOR_AJUSTE_REV, 0)  AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO IN('B', 'P')
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO IN('B', 'P')
	INNER JOIN SIG_INM_UNIDAD_ACTIVO_BAJA UAB 
	ON UAB.SEC_EJEC = UA.SEC_EJEC 
	AND UAB.SECUENCIA = UA.SECUENCIA 
	AND UAB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
WHERE
	INM.RP_AREA_TERRENO = (
	SELECT TOP 1 AREA_BAJA FROM SIG_INM_UNIDAD_ACTIVO_BAJA UABB
	WHERE 
	UABB.SEC_EJEC = UA.SEC_EJEC 
	AND UABB.SECUENCIA = UA.SECUENCIA 
	AND UABB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	)
	AND (
	SELECT COUNT(1) FROM SIG_INM_UNIDAD_ACTIVO_BAJA UABB
	WHERE 
	UABB.SEC_EJEC = UA.SEC_EJEC 
	AND UABB.SECUENCIA = UA.SECUENCIA 
	AND UABB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	) = 1
/*FIN: MVTO BAJA PARA TERRENOS (B:TOTAL)*/

UNION
/*INICIO: MVTO BAJA PARA TERRENOS (P:PARCIAL)*/
SELECT
     INM.SEC_EJEC
	,INM.SEDE
	,SE.NOMBRE_SEDE AS NMB_SEDE
	,INM.SECUENCIA
	,INM.NOMBRE_INMUEBLE AS NMB_INMUEBLE
	,UA.SEC_UNIDAD_ACTIVO
	,UA.DESCRIPCION AS NMB_UACTIVO
	,CO.SEC_COMPONENTE
	,CO.DENOMINACION AS NMB_COMPONENTE
	,UAB.ANO_BAJA AS ANIO_CONTABLE
	,UAB.MES_BAJA AS MES_CONTABLE	
	,6 AS TIPO_MOVIMTO
	,'Baja - Parcial' AS DETALLE_MOVIMTO
	,UAB.NRO_RESOLUCION_BAJA AS DOC_SUSTENTO
	,UAB.FECHA_RESOLUCION_BAJA AS FEC_SUSTENTO
	,COALESCE(CO.VALOR_INICIAL_REV_COSTO, 0) + COALESCE(CO.VALOR_INICIAL_REV_AJUSTE, 0) - COALESCE(CO.VALOR_DETERIORO, 0) AS VALOR_INICIAL
	,0 AS VALOR_AUMENTO
	,COALESCE(UAB.VALOR_COSTO, 0) + COALESCE(UAB.VALOR_AJUSTE_REV, 0)  AS VALOR_DISMINUCION
	,SE.PLIEGO
FROM
	SIG_SEDES SE
	INNER JOIN SIG_PATRIMONIO_INM INM
	ON SE.SEDE = INM.SEDE
	INNER JOIN SIG_INM_UNIDAD_ACTIVO UA 
	ON UA.SEC_EJEC = INM.SEC_EJEC
	AND UA.SECUENCIA = INM.SECUENCIA
	AND UA.ESTADO IN('B', 'P')
	INNER JOIN SIG_INM_COMPONENTE CO
	ON CO.SEC_EJEC = UA.SEC_EJEC
	AND CO.SECUENCIA = UA.SECUENCIA
	AND CO.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	AND CO.ESTADO IN('B', 'P')
	INNER JOIN SIG_INM_UNIDAD_ACTIVO_BAJA UAB 
	ON UAB.SEC_EJEC = UA.SEC_EJEC 
	AND UAB.SECUENCIA = UA.SECUENCIA 
	AND UAB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
WHERE
	INM.RP_AREA_TERRENO > (
	SELECT MAX(AREA_BAJA) FROM SIG_INM_UNIDAD_ACTIVO_BAJA UABB
	WHERE 
	UABB.SEC_EJEC = UA.SEC_EJEC 
	AND UABB.SECUENCIA = UA.SECUENCIA 
	AND UABB.SEC_UNIDAD_ACTIVO = UA.SEC_UNIDAD_ACTIVO
	)
	
/*FIN: MVTO BAJA PARA TERRENOS (P:PARCIAL)*/

) AS T_CONTABLE
GO


-- ----------------------------
-- View structure for vw_paso_1
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_paso_1]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_paso_1]
GO

CREATE VIEW [dbo].[vw_paso_1] AS select sub_finalidad, sec_kit from kit where not exists
(select 1 from catalogo_bien_serv_original cat
where kit.tipo_bien = cat.tipo_bien 
and kit.grupo_bien = cat.grupo_bien
and kit.clase_bien  = cat.clase_bien
and kit.familia_bien = cat.familia_bien
and kit.item  = cat.item_bien)
GO


-- ----------------------------
-- View structure for vw_paso_2
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_paso_2]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_paso_2]
GO

CREATE VIEW [dbo].[vw_paso_2] AS select sub_finalidad, sec_kit from kit 
where estado <> 'I' and exists
(select 1 from catalogo_bien_serv_original cat
where kit.tipo_bien = cat.tipo_bien 
and kit.grupo_bien = cat.grupo_bien
and kit.clase_bien  = cat.clase_bien
and kit.familia_bien = cat.familia_bien
and kit.item  = cat.item_bien
and cat.estado = 'I')
GO


