	DROP VIEW [dbo].[vw_paso_3]
GO

CREATE VIEW [dbo].[vw_paso_3] AS select sub_finalidad, sec_kit from kit 
where estado <> 'I' and not exists
(select 1 from sig_clasificador_gasto cat
where cat.ano_eje = 2011
and kit.clasificador  = cat.clasificador)
