CREATE VIEW [dbo].[vw_paso_4] AS select sub_finalidad, sec_kit from kit 
where estado <> 'I' and not exists
(select 1 from sig_familia_clasificador cat
where cat.ano_eje = 2011
and kit.clasificador  = cat.clasificador
and kit.TIPO_BIEN = cat.TIPO_BIEN
and kit.GRUPO_BIEN = cat.GRUPO_BIEN
and kit.CLASE_BIEN = cat.CLASE_BIEN
and kit.FAMILIA_BIEN = cat.FAMILIA_BIEN)
GO


-- ----------------------------
-- View structure for vw_paso_5
