IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_GETOBJWITHPROP_U]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_GETOBJWITHPROP_U]
GO

CREATE PROCEDURE [dbo].[DT_GETOBJWITHPROP_U]
	@property varchar(30),
	@uvalue nvarchar(255)
as
	set nocount on

	if (@property is null) or (@property = '')
	begin
		raiserror('Must specify a property name.',-1,-1)
		return (1)
	end

	if (@uvalue is null)
		select objectid id from dbo.dtproperties
			where property=@property

	else
		select objectid id from dbo.dtproperties
			where property=@property and uvalue=@uvalue
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_CLASIFICADOR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_CLASIFICADOR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_CLASIFICADOR]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_CLASIFICADOR]  
    @P_ANO_EJE   NUMERIC(4,0),
    @P_SEC_EJEC  VARCHAR(10)
AS
BEGIN  
	TRUNCATE TABLE TA_CLASIFICADOR
			INSERT INTO TA_CLASIFICADOR (ANO_EJE, CLASIFICADOR, NOMBRE_CLADIF)
  			SELECT DISTINCT  SI_PROGRAMACION_DETA_TRX.ANO_EJE,   
				              SI_PROGRAMACION_DETA_TRX.CLASIFICADOR, ''	
				              FROM SI_PROGRAMACION_DETA_TRX, SI_PROGRAMACION_TRX
				              WHERE	SI_PROGRAMACION_DETA_TRX.ANO_EJE = @P_ANO_EJE AND  
						SI_PROGRAMACION_DETA_TRX.SEC_EJEC = SI_PROGRAMACION_TRX.SEC_EJEC AND  
						SI_PROGRAMACION_DETA_TRX.ID_SI_PROGRAMACION = SI_PROGRAMACION_TRX.ID_SI_PROGRAMACION 

					UPDATE TA_EJECUTORA SET D_SECTOR = (SELECT SECTOR.nombre from SECTOR
							WHERE TA_EJECUTORA.C_sector = SECTOR.sector)
					UPDATE PLIEGO set nombre = REPLACE(nombre , 'GOBIERNO REGIONAL', 'G.R.') 
		   					WHERE nombre LIKE '%GOBIERNO REGIONAL%'
					UPDATE TA_EJECUTORA SET D_PLIEGO = (SELECT PLIEGO.nombre from PLIEGO
							WHERE TA_EJECUTORA.C_sector = PLIEGO.sector 
							AND   TA_EJECUTORA.C_pliego = PLIEGO.pliego)
					UPDATE TA_CLASIFICADOR
						   SET NOMBRE_CLADIF = (select NOMBRE_CLASIF  
						   from SIG_CLASIFICADOR_GASTO  
						   where SIG_CLASIFICADOR_GASTO.ANO_EJE = ta_clasificador.ANO_EJE 
						   and SIG_CLASIFICADOR_GASTO.CLASIFICADOR = ta_clasificador.CLASIFICADOR 
						   and SIG_CLASIFICADOR_GASTO.ANO_EJE = @P_ANO_EJE)
END
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_CN_FASE_22
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_CN_FASE_22]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_CN_FASE_22]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_CN_FASE_22]    
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)    
AS    
    
BEGIN    
 DECLARE @lI_FASE_CUADRO NUMERIC(1,0)    
 DECLARE @ls_clasificador VARCHAR(20)    
 DECLARE @ls_flag_presup VARCHAR(1)    
 DECLARE @ls_centro_costo_presup VARCHAR(15)    
 DECLARE @ls_centro_costo_cambio VARCHAR(15)    
 DECLARE @ls_centro_costo VARCHAR(15)    
 DECLARE @ls_centro_padre VARCHAR(15)    
 DECLARE @ls_origen VARCHAR(1)    
 DECLARE @ls_codi_fuen VARCHAR(2)    
 DECLARE @ls_codi_fuen_impto VARCHAR(2)    
 DECLARE @ls_clas_gast VARCHAR(20)    
 DECLARE @ld_Secu_func NUMERIC(4,0)    
 DECLARE @li_contador NUMERIC(10,0)    
 DECLARE @ld_valor_imp_progra NUMERIC(14,2)    
 DECLARE @li_secuencia NUMERIC(10,0)    
 DECLARE @ld_valor_progra NUMERIC(14,2)    
 DECLARE @ld_valor_aprob NUMERIC(14,2)    
 DECLARE @ld_mnto_impto NUMERIC(14,2)    
 DECLARE @ld_monto_progra NUMERIC(14,2)    
 DECLARE @ld_mnto_total NUMERIC(14,2)    
 DECLARE @ld_mnto_apro NUMERIC(14,2)    
 DECLARE @ld_mnto_asig NUMERIC(14,2)    
 DECLARE @ld_mnto_modif NUMERIC(14,2)    
 DECLARE @ls_categ_gasto VARCHAR(1)    
 DECLARE @ls_grupo_gasto VARCHAR(1)    
 DECLARE @ls_grupo VARCHAR(2)    
 DECLARE @ls_grupo1 VARCHAR(2)    
 DECLARE @ls_flag_gen_esp VARCHAR(1)    
 DECLARE @ld_valor_imp_asignado NUMERIC(14,2)    
 DECLARE @ld_valor_asignado NUMERIC(14,2)    
 DECLARE @ld_monto_asignado NUMERIC(14,2)    
 DECLARE @ld_monto_aprob NUMERIC(14,2)    
 DECLARE @ld_valor_imp_aprob NUMERIC(14,2)    
 declare @ld_min_correl numeric(8,0)    
 DECLARE @ls_flag_techo varchar(1)    
    
SELECT @ls_flag_gen_esp = valor    
  FROM sig_parametro_ejecutora_anio    
 WHERE ano_eje  = @PN_ANIO and    
       sec_ejec = @PN_EJEC and    
       cod_maestro = 'FLAG_TECHO_NIVEL'    
    
SELECT @ls_flag_techo = valor     
FROM sig_parametro_ejecutora_anio    
WHERE ano_eje  = @PN_ANIO and          
sec_ejec = @PN_EJEC and    
cod_maestro = 'FLAG_RESP_TECHO'    
    
SELECT @li_secuencia = IsNull(MAX(secuencia), 0)    
FROM sig_techo_presupuesto    
WHERE ano_eje  = @PN_ANIO and    
      sec_ejec = @PN_EJEC    
    
SET NOCOUNT ON    
    
  
IF @ls_flag_gen_esp <> '0'   
BEGIN    
     INSERT INTO tmp_techo_fase_7    
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,    
                  sec_func_prop, centro_costo_presup, clasificador)    
          SELECT DISTINCT    
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,    
                 b.sec_func_prop, b.centro_costo_presup, b.clasificador    
            FROM sig_techo_presupuesto b    
           WHERE b.ano_eje     = @PN_ANIO and    
                 b.sec_ejec    = @PN_EJEC and    
                 b.fase_cuadro = @PN_FASE and    
                 b.indicador   = '0'      and    
                 b.flag_meta_aprob = '0'  and    
                 not exists (SELECT '1'    
                               FROM sig_techo_presupuesto c    
                              WHERE c.ano_eje     = b.ano_eje  and    
                                    c.sec_ejec    = b.sec_ejec and    
                                    c.fase_cuadro = @PN_FASE   and    
                                    c.origen      = b.origen   and    
                                    c.fuente_financ = b.fuente_financ and    
                                    c.categ_gasto   = b.categ_gasto   and    
                                    c.grupo_gasto   = b.grupo_gasto   and    
                                    c.sec_func_prop = b.sec_func_prop and    
                                    c.centro_costo_presup = b.centro_costo_presup and    
                                    c.clasificador    = b.clasificador and    
                                    c.indicador       = '5' and    
                                    c.flag_meta_aprob = '0')    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
    END    
         
  
     SELECT @li_secuencia = IsNull(MAX(secuencia), 0)    
       FROM sig_techo_presupuesto    
      WHERE ano_eje  = @PN_ANIO and    
            sec_ejec = @PN_EJEC    
         
  
     INSERT INTO sig_techo_presupuesto    
                 (ano_eje    , sec_ejec    , origen      , fuente_financ, secuencia    ,    
                  categ_gasto, grupo_gasto , clasificador,    
                  sec_func   , centro_costo, ppto_progra , ppto_aprob   , ppto_asignado,    
                  ppto_modif , mnto_progra , mnto_asig   , mnto_aprob   , mnto_modif   ,    
                  indicador  , paac_inicial, paac_modif  , porc_techo   , porc_asig    ,    
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)    
          SELECT @PN_ANIO, @PN_EJEC, origen , fuente_financ, (@li_secuencia + secuencia),    
                 categ_gasto, grupo_gasto, clasificador, NULL, NULL,    
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '5', 0, 0, 0,    
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE    
            FROM tmp_techo_fase_7    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
     END    
         
  
     UPDATE sig_techo_presupuesto    
        SET mnto_asig = (SELECT SUM(A.mnto_asig)    
                           FROM sig_techo_presupuesto A    
                          WHERE A.ano_eje     = @PN_ANIO and    
                                A.sec_ejec    = @PN_EJEC and    
                                A.fase_cuadro = @PN_FASE and    
                                A.origen      = sig_techo_presupuesto.origen and    
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and    
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and    
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and    
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and    
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and    
                                A.clasificador  =  sig_techo_presupuesto.clasificador and    
                                A.indicador       = '0' and    
                                A.flag_meta_aprob = '0')    
      WHERE ano_eje     = @PN_ANIO and    
            sec_ejec    = @PN_EJEC and    
            fase_cuadro = @PN_FASE and    
            indicador   = '5'      and    
            flag_meta_aprob = '0'    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
     END    
         
  
     INSERT INTO tmp_techo_fase_8    
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,    
                  sec_func_prop, centro_costo_presup)    
          SELECT DISTINCT    
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,    
                 b.sec_func_prop, b.centro_costo_presup    
            FROM sig_techo_presupuesto b    
           WHERE b.ano_eje     = @PN_ANIO and    
                 b.sec_ejec    = @PN_EJEC and    
                 b.fase_cuadro = @PN_FASE and    
                 b.indicador   = '0'      and    
                 b.flag_meta_aprob = '0'  and    
                 not exists (SELECT '1'    
                               FROM sig_techo_presupuesto c    
                              WHERE c.ano_eje     = b.ano_eje  and    
                                    c.sec_ejec    = b.sec_ejec and    
                                    c.fase_cuadro = @PN_FASE   and    
                                    c.origen      = b.origen   and    
                                    c.fuente_financ = b.fuente_financ and    
                                    c.categ_gasto   = b.categ_gasto   and    
                                    c.grupo_gasto   = b.grupo_gasto   and    
c.sec_func_prop = b.sec_func_prop and    
                                    c.centro_costo_presup = b.centro_costo_presup and    
                                    c.indicador       = '4' and    
                                    c.flag_meta_aprob = '0')    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
     END    
         
     SELECT @li_secuencia = max(secuencia)     
       FROM sig_techo_presupuesto     
      WHERE ano_eje  = @PN_ANIO and    
            sec_ejec = @PN_EJEC    
         
     INSERT INTO sig_techo_presupuesto    
                 (ano_eje      , sec_ejec       , origen      , fuente_financ, secuencia    ,    
                  categ_gasto  , grupo_gasto    , clasificador,    
                  sec_func     , centro_costo   , ppto_progra , ppto_aprob   , ppto_asignado,    
                  ppto_modif   , mnto_progra    , mnto_asig   , mnto_aprob   , mnto_modif   ,    
                  indicador    , paac_inicial   , paac_modif  , porc_techo   , porc_asig    ,    
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)    
          SELECT @PN_ANIO, @PN_EJEC, origen, fuente_financ, (@li_secuencia + secuencia),    
                 categ_gasto, grupo_gasto, NULL, NULL, NULL,    
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '4', 0, 0, 0,    
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE    
            FROM tmp_techo_fase_8    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
     END    
         
     UPDATE sig_techo_presupuesto    
        SET mnto_asig = (SELECT SUM(A.mnto_asig)    
                           FROM sig_techo_PRESUPUESTO A    
                          WHERE A.ano_eje     = @PN_ANIO and    
                                A.sec_ejec    = @PN_EJEC and    
                                A.fase_cuadro = @PN_FASE and    
                                A.origen      = sig_techo_presupuesto.origen and    
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and    
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and    
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and    
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and    
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and    
                                A.indicador       = '0' and    
                                A.flag_meta_aprob = '0')    
      WHERE ano_eje     = @PN_ANIO and    
            sec_ejec    = @PN_EJEC and    
            fase_cuadro = @PN_FASE and    
            indicador   = '4'      and    
            flag_meta_aprob = '0'    
         
     IF @@ERROR <> 0    
     BEGIN    
    return -1    
     END    
END    
    
TRUNCATE TABLE dbo.tmp_techo_cn_fase     
TRUNCATE TABLE dbo.tmp_propuesta_fase     
TRUNCATE TABLE dbo.tmp_techo_fase_2     
TRUNCATE TABLE dbo.tmp_techo_fase_3    
TRUNCATE TABLE dbo.tmp_techo_fase_4    
TRUNCATE TABLE dbo.tmp_techo_fase_5    
TRUNCATE TABLE dbo.tmp_techo_fase_6    
TRUNCATE TABLE dbo.tmp_techo_fase_7    
TRUNCATE TABLE dbo.tmp_techo_fase_8    
    
RETURN 1    
END;--/
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_SEDE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_SEDE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_SEDE]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_SEDE]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJEC   	    	VARCHAR(10),
    @fecha_carga_inicio     	VARCHAR(10),
    @fecha_carga_fin        	VARCHAR(10),
    @usuario_n              	VARCHAR(50),
    @O_ERR_NUM   	    	NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG   	    	VARCHAR(255) OUTPUT   
AS
DECLARE @LC_SEDE 		 NUMERIC(5)
DECLARE @LC_ID_SI_SEDE 		 NUMERIC(5)
DECLARE @Lc_PLIEGO            	 VARCHAR(3)	
DECLARE @Lc_SECTOR            	 VARCHAR(2)
DECLARE @Lc_NOMBRE_SEDE       	 VARCHAR(50)
DECLARE @fecha_carga_inicio_1  	 DATETIME
DECLARE @fecha_carga_fin_1     	 DATETIME

BEGIN  
	DELETE FROM SI_SEDE
	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101) 
                SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

	SELECT @LC_ID_SI_SEDE = MAX(ID_SI_SEDE) FROM SI_SEDE 
	IF @LC_ID_SI_SEDE IS NULL 
		SET @LC_ID_SI_SEDE = 0	

        DECLARE C_1 CURSOR FOR 
		SELECT SEDE, PLIEGO, SECTOR, NOMBRE_SEDE FROM SIG_SEDES

	  	OPEN C_1
		FETCH NEXT FROM C_1 
		INTO  @LC_SEDE, @LC_PLIEGO, @LC_SECTOR, @LC_NOMBRE_SEDE

		WHILE @@FETCH_STATUS = 0
		BEGIN
	        	SET @LC_ID_SI_SEDE  = @LC_ID_SI_SEDE + 1
		        INSERT INTO SI_SEDE (ANO_EJE, SEC_EJEC, SEDE, PLIEGO, SECTOR, ID_SI_SEDE, NOMBRE_SEDE, 
					    FECHA_CARGA_INICIO, FECHA_CARGA_FIN,
					    FECHA_ENVIO, USUARIO_ENVIO)
		        VALUES (@P_ANO_EJE, @P_SEC_EJEC, @LC_SEDE, @LC_PLIEGO, @LC_SECTOR, @LC_ID_SI_SEDE, @LC_NOMBRE_sEDE, 
			      	@fecha_carga_inicio_1, @fecha_carga_fin_1,  
		      		convert(varchar(10),getdate(),112), @usuario_n)

	        FETCH NEXT FROM C_1
        	INTO @LC_SEDE, @LC_PLIEGO, @LC_SECTOR, @LC_NOMBRE_sEDE
		END
        CLOSE C_1
        DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_TECHOC_FASE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_TECHOC_FASE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_TECHOC_FASE]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_TECHOC_FASE]
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)
AS

BEGIN
	DECLARE @lI_FASE_CUADRO NUMERIC(1,0)
	DECLARE @ls_clasificador VARCHAR(20)
	DECLARE @ls_flag_presup VARCHAR(1)
	DECLARE @ls_centro_costo_presup VARCHAR(15)
	DECLARE @ls_centro_costo_cambio VARCHAR(15)
	DECLARE @ls_centro_costo VARCHAR(15)
	DECLARE @ls_centro_padre VARCHAR(15)
	DECLARE @ls_origen VARCHAR(1)
	DECLARE @ls_codi_fuen VARCHAR(2)
	DECLARE @ls_codi_fuen_impto VARCHAR(2)
	DECLARE @ls_clas_gast VARCHAR(20)
	DECLARE @ls_funcion VARCHAR(2)
	DECLARE @ls_programa VARCHAR(3)
	DECLARE @ld_Secu_func NUMERIC(4,0)
	DECLARE @li_contador NUMERIC(10,0)
	DECLARE @ld_valor_imp_progra NUMERIC(14,2)
	DECLARE @li_secuencia NUMERIC(10,0)
	DECLARE @ld_valor_progra NUMERIC(14,2)
	DECLARE @ld_valor_aprob NUMERIC(14,2)
	DECLARE @ld_mnto_impto NUMERIC(14,2)
	DECLARE @ld_monto_progra NUMERIC(14,2)
	DECLARE @ld_mnto_total NUMERIC(14,2)
	DECLARE @ld_mnto_apro NUMERIC(14,2)
	DECLARE @ld_mnto_asig NUMERIC(14,2)
	DECLARE @ld_mnto_modif NUMERIC(14,2)
	DECLARE @ls_categ_gasto VARCHAR(1)
	DECLARE @ls_grupo_gasto VARCHAR(1)
	DECLARE @ls_grupo VARCHAR(2)
	DECLARE @ls_grupo1 VARCHAR(2)
	DECLARE @ls_flag_gen_esp VARCHAR(1)
	DECLARE @ld_valor_imp_asignado NUMERIC(14,2)
	DECLARE @ld_valor_asignado NUMERIC(14,2)
	DECLARE @ld_monto_asignado NUMERIC(14,2)
	DECLARE @ld_monto_aprob NUMERIC(14,2)
	DECLARE @ld_valor_imp_aprob NUMERIC(14,2)
	declare @ld_min_correl numeric(8,0)

SELECT @li_contador = COUNT(*)
FROM  SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND 
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

IF ( @li_contador IS NULL) OR ( @li_contador <= 0)
 --GOTO ERROR
   return -1

--MENOS PARA EL TECHO APROBADO
SELECT @ls_flag_gen_esp = VALOR
FROM  SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND 
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

SELECT @li_secuencia = MAX( secuencia ) 
  FROM sig_techo_presupuesto 
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC


if @li_secuencia  IS NULL 
  SELECT @li_secuencia = 0

SET NOCOUNT ON

--BEGIN --TRAN

IF @PN_FASE = 1
--FASE 1 REQUERIDO
 update sig_techo_presupuesto 
 set    mnto_progra  =0
 WHERE ANO_EJE = @PN_ANIO AND
        SEC_EJEC = @PN_EJEC AND
        flag_meta_aprob = '0' AND
	FASE_CUADRO = 1

IF @PN_FASE = 2 
--FASE 2 PROGRAMACION
 update sig_techo_presupuesto 
 set    mnto_asig  =0 
 WHERE  ANO_EJE = @PN_ANIO AND
	SEC_EJEC = @PN_EJEC AND
	flag_meta_aprob = '0' AND
	FASE_CUADRO = 2


IF @PN_FASE = 3
--FASE 3 APROBACION
 update sig_techo_presupuesto
 set    mnto_aprob  =0 
 WHERE ANO_EJE = @PN_ANIO AND
       SEC_EJEC = @PN_EJEC AND
       flag_meta_aprob = '1'


IF @@ERROR <> 0
-- GOTO ERROR
return -1

--------------------------------------------
-- ACTUALIZACION DE FASE REQUERIDO Y 
-- PROGRAMADO
--------------------------------------------
IF @PN_FASE = 1 OR @PN_FASE = 2 
BEGIN

 -- FASE 1
	 IF @PN_FASE = 1 
		UPDATE SIG_TECHO_PRESUPUESTO
		set    mnto_progra  =0 					 
		WHERE  ano_eje  	  =@PN_ANIO and
		       sec_ejec 	  =@PN_EJEC and
		       FASE_CUADRO       = 1  AND
		EXISTS( SELECT '1' 
			  FROM SIG_CUADRO_NECESIDAD A
			 WHERE A.ano_eje    = SIG_TECHO_PRESUPUESTO.ANO_EJE and
			       A.sec_ejec   = SIG_TECHO_PRESUPUESTO.SEC_EJEC and
			       A.FASE_CUADRO= 1  AND
			       A.origen     = SIG_TECHO_PRESUPUESTO.ORIGEN and
			      (A.FUENTE_FINANC= SIG_TECHO_PRESUPUESTO.fuente_financ or
			       A.fuente_impto=SIG_TECHO_PRESUPUESTO.fuente_financ) and
			      A.clasificador =SIG_TECHO_PRESUPUESTO.CLASIFICADOR and
			      A.sec_func_prop =SIG_TECHO_PRESUPUESTO.SEC_FUNC_PROP and
			      A.centro_costo = SIG_TECHO_PRESUPUESTO.CENTRO_COSTO and
			      SIG_TECHO_PRESUPUESTO.indicador = '0' and
			      SIG_TECHO_PRESUPUESTO.flag_meta_aprob = '0')  
	 IF @PN_FASE = 2 
	 BEGIN
		UPDATE SIG_TECHO_PRESUPUESTO
		set    mnto_asig  =0 					 
		WHERE ano_eje  	  =@PN_ANIO and
		      sec_ejec 	  =@PN_EJEC and
		      FASE_CUADRO       = 2  AND
		EXISTS( SELECT '1' 
			  FROM SIG_CUADRO_NECESIDAD A
			 WHERE A.ano_eje    = SIG_TECHO_PRESUPUESTO.ANO_EJE and
			       A.sec_ejec   = SIG_TECHO_PRESUPUESTO.SEC_EJEC and
			       A.FASE_CUADRO= 1  AND
			       A.origen     = SIG_TECHO_PRESUPUESTO.ORIGEN and
			      (A.FUENTE_FINANC= SIG_TECHO_PRESUPUESTO.fuente_financ or
			       A.FUENTE_FINANC=SIG_TECHO_PRESUPUESTO.fuente_financ) and
			      A.clasificador =SIG_TECHO_PRESUPUESTO.CLASIFICADOR and
			      A.sec_func_prop =SIG_TECHO_PRESUPUESTO.SEC_FUNC_PROP and
			      A.centro_costo = SIG_TECHO_PRESUPUESTO.CENTRO_COSTO and
			      SIG_TECHO_PRESUPUESTO.indicador = '0' and
			      SIG_TECHO_PRESUPUESTO.flag_meta_aprob = '0')

	 END

	IF @@ERROR <> 0
	 --return GOTO ERROR
	   return -1


	INSERT INTO tmp_propuesta_fase
	( centro_costo,ORIGEN,fuente_impto,CLASIFICADOR,sec_func_prop,FUNCION,PROGRAMA,FASE_CUADRO)
	SELECT  DISTINCT
		c.centro_costo,
		c.origen,
		c.fuente_impto,
		c.clasificador,
		c.sec_func_prop,
		m.funcion,
		m.programa,
		@PN_FASE
	FROM  sig_cuadro_necesidad c, sig_meta_propuesta m
	WHERE	( c.ano_eje   = m.ano_eje    and
		  c.sec_ejec  = m.sec_ejec   and
		  c.ano_eje      = @PN_ANIO  and
		  c.sec_ejec     = @PN_EJEC )and
		  c.fase_cuadro  = @PN_FASE and
          c.fase_cuadro  = m.fase_cuadro and
		  c.sec_func_prop  = m.sec_func_prop and
		  c.tipo_impuesto <> '0'

	IF @@ERROR <> 0
	 --return GOTO ERROR
	BEGIN
 	   return -1
	END

IF @PN_FASE = 1 
BEGIN
	insert INTO tmp_techo_cn_fase  
	( 	ano_eje     , sec_ejec      , origen         , fuente_financ,
		categ_gasto   , grupo_gasto    , clasificador, 
		funcion      , programa      , sec_func       , centro_costo, 
		ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
		mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
		indicador	 , paac_inicial  , paac_modif     , porc_techo ,
		porc_asig    , sec_func_prop , flag_meta_aprob, FASE_CUADRO
	)
	SELECT 
	@PN_ANIO ,@PN_EJEC,c.origen,c.fuente_impto,
	( SELECT COD_NIVEL1
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),
	( SELECT COD_NIVEL2
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),c.clasificador,
	  c.funcion,c.programa,c.sec_func_prop,c.centro_costo,
	  0	 , 0		  , 0	 , 0      ,
	( SELECT  SUM( cn.valor_imp_progra )
	    FROM  sig_cuadro_necesidad cn
	   WHERE cn.ano_eje      = @PN_ANIO and
		 cn.sec_ejec     = @PN_EJEC	and
		 cn.centro_costo = c.centro_costo and
		 cn.fase_cuadro  = @PN_FASE and
		 cn.origen       = c.origen and
		 cn.fuente_impto = c.fuente_impto and
		 cn.categ_gasto  in (  SELECT COD_NIVEL1 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.clasificador = c.clasificador and
		 cn.sec_func_prop =c.sec_func_prop and
		 cn.tipo_impuesto <>'0'			
	),
	0, 0, 0 ,
	'0' , 0  , 0  , 0    ,
	0   , c.sec_func_prop , '0', @PN_FASE
FROM tmp_propuesta_fase c
WHERE not  exists  (
		SELECT '1'
		FROM sig_techo_presupuesto
		WHERE 
		ano_eje       = @PN_ANIO and
		sec_ejec      = @PN_EJEC	and
		origen        = c.origen  and
		fuente_financ = c.fuente_impto  and
		categ_gasto   in(  SELECT COD_NIVEL1
				   FROM SIG_CLASIFICADOR_GASTO
				  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador )and
		grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador)  and
		clasificador  = c.clasificador  and
		funcion       = c.funcion and
		programa      = c.programa and
		sec_func_prop = c.sec_func_prop and
		centro_costo  = c.centro_costo and
		indicador     = '0' and
		flag_meta_aprob = '0' AND FASE_CUADRO = 1
		)
	IF @@ERROR <> 0
	BEGIN
	    return -1
	END

END

IF @PN_FASE = 2
BEGIN
	insert INTO tmp_techo_cn_fase  
	( 	ano_eje     , sec_ejec      , origen         , fuente_financ,
		categ_gasto   , grupo_gasto    , clasificador, 
		funcion      , programa      , sec_func       , centro_costo, 
		ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
		mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
	
		indicador	 , paac_inicial  , paac_modif     , porc_techo ,
		porc_asig    , sec_func_prop , flag_meta_aprob, FASE_CUADRO
	)
	SELECT 
	@PN_ANIO ,@PN_EJEC,c.origen,c.fuente_impto,
	( SELECT COD_NIVEL1
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),
	( SELECT COD_NIVEL2
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),c.clasificador,
	  c.funcion,c.programa,c.sec_func_prop,c.centro_costo,
	  0	 , 0		  , 0	 , 0      ,
		0,
	( SELECT  SUM( cn.valor_imp_asignado )
	    FROM  sig_cuadro_necesidad cn
	   WHERE cn.ano_eje      = @PN_ANIO and
		 cn.sec_ejec     = @PN_EJEC	and
		 cn.centro_costo = c.centro_costo and
		 cn.fase_cuadro  = @PN_FASE and
		 cn.origen       = c.origen and
		 cn.fuente_impto = c.fuente_impto and
		 cn.categ_gasto  in (  SELECT COD_NIVEL1 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador ) and
		 cn.clasificador = c.clasificador and
		 cn.sec_func_prop =c.sec_func_prop and
		 cn.tipo_impuesto <>'0'			
	), 0, 0 ,
	'0' , 0  , 0  , 0    ,
	0   , c.sec_func_prop , '0', @PN_FASE
FROM tmp_propuesta_fase c
WHERE not  exists  (
		SELECT '1'
		FROM sig_techo_presupuesto
		WHERE 
		ano_eje       = @PN_ANIO and
		sec_ejec      = @PN_EJEC	and
		origen        = c.origen  and
		fuente_financ = c.fuente_impto  and
		categ_gasto   in(  SELECT COD_NIVEL1
				   FROM SIG_CLASIFICADOR_GASTO
				  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador )and
		grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador)  and
		clasificador  = c.clasificador  and
		funcion       = c.funcion and
		programa      = c.programa and
		sec_func_prop = c.sec_func_prop and
		centro_costo  = c.centro_costo and
		indicador     = '0' and
		flag_meta_aprob = '0' AND FASE_CUADRO = 2
		)

	IF @@ERROR <> 0
	BEGIN
	    return -1
	END

END


		insert INTO sig_techo_presupuesto
		(ano_eje     , sec_ejec      , origen         , fuente_financ,
		secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
		funcion      , programa      , sec_func       , centro_costo, 
		ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
		mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
		indicador	 , paac_inicial  , paac_modif     , porc_techo ,
		porc_asig    , sec_func_prop , flag_meta_aprob, FASE_CUADRO)
		SELECT 
			ano_eje     , sec_ejec      , origen         , fuente_financ,
			@li_secuencia + secuencia1    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , null       , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     , porc_techo ,
			porc_asig    , sec_func_prop , flag_meta_aprob, FASE_CUADRO
		FROM tmp_techo_cn_fase
	


SELECT @li_secuencia = max(secuencia) 
  FROM sig_techo_presupuesto 
 WHERE ano_eje= @PN_ANIO and
       sec_ejec = @PN_EJEC

	insert INTO tmp_propuesta_fase 
	( centro_costo,ORIGEN,fuente_financ,CLASIFICADOR,sec_func_prop,FUNCION,PROGRAMA, FASE_CUADRO)
	SELECT  DISTINCT
		c.centro_costo,
		c.origen,
		c.fuente_financ,
		c.clasificador,
		c.sec_func_prop,
		m.funcion,
		m.programa,
		@PN_FASE
	FROM  sig_cuadro_necesidad c, sig_meta_propuesta m
	WHERE	c.ano_eje   = m.ano_eje and
		c.sec_ejec  = m.sec_ejec and
		c.sec_func_prop  = m.sec_func_prop and
		c.ano_eje      = @PN_ANIO  and
		c.sec_ejec     = @PN_EJEC and
		c.fase_cuadro  = @PN_FASE and
        c.fase_cuadro  = m.fase_cuadro and
		c.tipo_impuesto <>'0'

	IF @@ERROR <> 0
	BEGIN

	return -1
	END



IF @PN_FASE = 1
BEGIN
	insert INTO tmp_techo_cn_fase  
	( 	ano_eje     , sec_ejec      , origen         , FUENTE_FINANC,
		categ_gasto   , grupo_gasto    , clasificador, 
		funcion      , programa      , sec_func       , centro_costo, 
		ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
		mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
	
		indicador	 , paac_inicial  , paac_modif     , porc_techo ,
		porc_asig    , sec_func_prop , flag_meta_aprob, FASE_CUADRO
	)
	SELECT 	@PN_ANIO ,@PN_EJEC,c.origen,c.fuente_impto,
	( SELECT COD_NIVEL1
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),
	( SELECT COD_NIVEL2
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),c.clasificador,
	  c.funcion,c.programa,c.sec_func_prop,c.centro_costo,
	  0	 , 0		  , 0	 , 0      ,
	( SELECT  SUM( cn.valor_imp_progra )
	    FROM  sig_cuadro_necesidad cn
	   WHERE cn.ano_eje      = @PN_ANIO and
		 cn.sec_ejec     = @PN_EJEC	and
		 cn.centro_costo = c.centro_costo and
		 cn.fase_cuadro  = @PN_FASE and
		 cn.origen       = c.origen and
		 cn.fuente_financ = c.fuente_financ and
		 cn.categ_gasto  in (  SELECT COD_NIVEL1 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.clasificador = c.clasificador and
		 cn.sec_func_prop =c.sec_func_prop and
		 cn.tipo_impuesto <>'0'			
	),
	0, 0, 0 ,
	'0' , 0  , 0  , 0    ,
	0   , c.sec_func_prop , '0', 1
	FROM tmp_propuesta_fase c
	WHERE not  exists  (
				SELECT '1'
				FROM sig_techo_presupuesto
				WHERE 
				ano_eje       = @PN_ANIO and
				sec_ejec      = @PN_EJEC	and
				origen        = c.origen  and
				fuente_financ = c.fuente_financ  and
				categ_gasto   in(  SELECT COD_NIVEL1
						   FROM SIG_CLASIFICADOR_GASTO
						  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador )and
				grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
						      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador)  and
				clasificador  = c.clasificador  and
				funcion       = c.funcion and
				programa      = c.programa and
				sec_func_prop = c.sec_func_prop and
				centro_costo  = c.centro_costo and
				indicador     = '0' and
				flag_meta_aprob = '0' AND
				FASE_CUADRO = 1
			)

	IF @@ERROR <> 0
	BEGIN
	return -1
	END



END

IF @PN_FASE = 2
BEGIN
	insert INTO tmp_techo_cn_fase  
	( 	ano_eje     , sec_ejec      , origen         , FUENTE_FINANC,
