	)
	SELECT 	@PN_ANIO ,@PN_EJEC,c.origen,c.fuente_impto,
	( SELECT COD_NIVEL1
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),
	( SELECT COD_NIVEL2
	   FROM SIG_CLASIFICADOR_GASTO
	  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador ),c.clasificador,
	  c.funcion,c.programa,c.sec_func_prop,c.centro_costo,
	  0	 , 0		  , 0	 , 0      ,
	0,
	( SELECT  SUM( cn.valor_imp_asignado )
	    FROM  sig_cuadro_necesidad cn
	   WHERE cn.ano_eje      = @PN_ANIO and
		 cn.sec_ejec     = @PN_EJEC	and
		 cn.centro_costo = c.centro_costo and
		 cn.fase_cuadro  = @PN_FASE and
		 cn.origen       = c.origen and
		 cn.fuente_financ = c.fuente_financ and
		 cn.categ_gasto  in (  SELECT COD_NIVEL1 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador) and
		 cn.grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
				      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador ) and
		 cn.clasificador = c.clasificador and
		 cn.sec_func_prop =c.sec_func_prop and
		 cn.tipo_impuesto <>'0'			
	), 0, 0 ,
	'0' , 0  , 0  , 0    ,
	0   , c.sec_func_prop , '0',2
	FROM tmp_propuesta_fase c
	WHERE not  exists  (
				SELECT '1'
				FROM sig_techo_presupuesto
				WHERE 
				ano_eje       = @PN_ANIO and
				sec_ejec      = @PN_EJEC	and
				origen        = c.origen  and
				fuente_financ = c.fuente_financ  and
				categ_gasto   in(  SELECT COD_NIVEL1
						   FROM SIG_CLASIFICADOR_GASTO
						  WHERE ANO_EJE = @PN_ANIO AND CLASIFICADOR = c.clasificador )and
				grupo_gasto  in ( SELECT COD_NIVEL2 FROM SIG_CLASIFICADOR_GASTO 
						      WHERE ANO_EJE = @PN_ANIO aND CLASIFICADOR = c.clasificador)  and
				clasificador  = c.clasificador  and
				funcion       = c.funcion and
				programa      = c.programa and
				sec_func_prop = c.sec_func_prop and
				centro_costo  = c.centro_costo and
				indicador     = '0' and
				flag_meta_aprob = '0' AND
				FASE_CUADRO = 2
			)

	IF @@ERROR <> 0
	BEGIN
	return -1
	END



END


		insert INTO sig_techo_presupuesto
		(ano_eje     , sec_ejec      , origen         , fuente_financ,
		secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
		funcion      , programa      , sec_func       , centro_costo, 
		ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
		mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
		indicador	 , paac_inicial  , paac_modif     , porc_techo ,
		porc_asig    , sec_func_prop , flag_meta_aprob, fase_cuadro)
		SELECT 
			ano_eje     , sec_ejec      , origen         , fuente_financ,
			@li_secuencia + secuencia1    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , null       , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     , porc_techo ,
			porc_asig    , sec_func_prop , flag_meta_aprob, fase_cuadro
		FROM tmp_techo_cn_fase


	IF @@ERROR <> 0
	 --GOTO ERROR
	return -1

	 IF @PN_FASE = 1 
	 BEGIN
		      update sig_techo_presupuesto 
			set mnto_progra =(
				SELECT  sum(c.monto_progra)
				FROM  sig_cuadro_necesidad c
				WHERE 	c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.fase_cuadro    = @PN_FASE and 
					c.centro_costo   = sig_techo_presupuesto.centro_costo and
					c.origen =sig_techo_presupuesto.origen and
					c.fuente_financ=sig_techo_presupuesto.fuente_financ and
					c.clasificador=sig_techo_presupuesto.clasificador and
					c.sec_func_prop=sig_techo_presupuesto.sec_func_prop 
					 )
			WHERE 	ano_eje  = @PN_ANIO and
				sec_ejec = @PN_EJEC and
				FASE_CUADRO = 1 AND
				exists (
					SELECT '1' FROM sig_cuadro_necesidad c
					WHERE
						c.ano_eje        = @PN_ANIO and
						c.sec_ejec       = @PN_EJEC and
						c.origen = sig_techo_presupuesto.origen and
						c.fuente_financ =  sig_techo_presupuesto.fuente_financ and
						c.clasificador  = sig_techo_presupuesto.clasificador  and
						c.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
						c.centro_costo  = sig_techo_presupuesto.centro_costo and
						sig_techo_presupuesto.indicador = '0' and
						sig_techo_presupuesto.flag_meta_aprob = '0'
					)and
				indicador = '0' and flag_meta_aprob = '0'
				
	 END
	 IF @PN_FASE = 2 
	 BEGIN
		      update sig_techo_presupuesto 
			set mnto_asig =(
				SELECT  sum(c.monto_asignado)
				FROM  sig_cuadro_necesidad c
				WHERE 	c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.fase_cuadro    = @PN_FASE and 
					c.centro_costo   = sig_techo_presupuesto.centro_costo and
					c.origen =sig_techo_presupuesto.origen and
					c.fuente_financ=sig_techo_presupuesto.fuente_financ and
					c.clasificador=sig_techo_presupuesto.clasificador and
					c.sec_func_prop=sig_techo_presupuesto.sec_func_prop 
					 )
			WHERE 	ano_eje  = @PN_ANIO and
				sec_ejec = @PN_EJEC and
				FASE_CUADRO = 2 AND
				exists (
					SELECT '1' FROM sig_cuadro_necesidad c
					WHERE
						c.ano_eje        = @PN_ANIO and
						c.sec_ejec       = @PN_EJEC and
						c.origen = sig_techo_presupuesto.origen and
						c.fuente_financ =  sig_techo_presupuesto.fuente_financ and
						c.clasificador  = sig_techo_presupuesto.clasificador  and
						c.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
						c.centro_costo  = sig_techo_presupuesto.centro_costo and
						sig_techo_presupuesto.indicador = '0' and
						sig_techo_presupuesto.flag_meta_aprob = '0'
					)and
				indicador = '0' and flag_meta_aprob = '0'
	 END

	IF @@ERROR <> 0
	 --GOTO ERROR
	return -1

	 IF @PN_FASE = 1 
	 BEGIN
			update sig_techo_presupuesto 
			set mnto_progra = mnto_progra + (
				SELECT  sum(c.valor_imp_progra)
				FROM  sig_cuadro_necesidad c
				WHERE 	c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.fase_cuadro    = @PN_FASE and 
					c.centro_costo   = sig_techo_presupuesto.centro_costo and
					c.origen =sig_techo_presupuesto.origen and
					c.fuente_impto=sig_techo_presupuesto.fuente_financ and
					c.clasificador=sig_techo_presupuesto.clasificador and
					c.sec_func_prop=sig_techo_presupuesto.sec_func_prop 

			)
		WHERE 	ano_eje  = @PN_ANIO and
			sec_ejec = @PN_EJEC and
			FASE_CUADRO = 1 AND
			exists (
				SELECT '1' FROM sig_cuadro_necesidad c
				WHERE
					c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.origen = sig_techo_presupuesto.origen and
					c.fuente_impto =  sig_techo_presupuesto.fuente_financ and
					c.clasificador  = sig_techo_presupuesto.clasificador  and
					c.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
					c.centro_costo  = sig_techo_presupuesto.centro_costo and
					sig_techo_presupuesto.indicador = '0' and
					sig_techo_presupuesto.flag_meta_aprob = '0'
				)and indicador = '0' and flag_meta_aprob = '0'
	 END
	 IF @PN_FASE = 2 
	 BEGIN
			update sig_techo_presupuesto 
			set mnto_asig = mnto_asig + (
				SELECT  sum(c.valor_imp_asignado)
				FROM  sig_cuadro_necesidad c
				WHERE 	c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.fase_cuadro    = @PN_FASE and 
					c.centro_costo   = sig_techo_presupuesto.centro_costo and
					c.origen =sig_techo_presupuesto.origen and
					c.fuente_impto=sig_techo_presupuesto.fuente_financ and
					c.clasificador=sig_techo_presupuesto.clasificador and
					c.sec_func_prop=sig_techo_presupuesto.sec_func_prop 

			)
		WHERE 	ano_eje  = @PN_ANIO and
			sec_ejec = @PN_EJEC and
			FASE_CUADRO = 2 AND
			exists (
				SELECT '1' FROM sig_cuadro_necesidad c
				WHERE
					c.ano_eje        = @PN_ANIO and
					c.sec_ejec       = @PN_EJEC and
					c.origen = sig_techo_presupuesto.origen and
					c.fuente_impto =  sig_techo_presupuesto.fuente_financ and
					c.clasificador  = sig_techo_presupuesto.clasificador  and
					c.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
					c.centro_costo  = sig_techo_presupuesto.centro_costo and
					sig_techo_presupuesto.indicador = '0' and
					sig_techo_presupuesto.flag_meta_aprob = '0'
				)and indicador = '0' and flag_meta_aprob = '0'

	 END
	IF @@ERROR <> 0
	 --GOTO ERROR
	return -1

END
ELSE
BEGIN
	DELETE FROM TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_CN_TECHO_APROB_UPD
	( centro_costo,	origen,	fuente_financ,fuente_impto,clasificador,sec_func)
	SELECT DISTINCT m.centro_costo, m.origen, m.fuente_financ , m.fuente_impto, m.clasificador, m.sec_func
	FROM sig_cuadro_necesidad m
	WHERE m.ano_eje	= @PN_ANIO    and
	m.sec_ejec	= @PN_EJEC and 
	m.fase_cuadro    = @PN_FASE and
	(m.fuente_financ is not  null) and
	(m.clasificador is not null) and
	(m.sec_func is not null)
	
	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	update sig_techo_presupuesto
	set    mnto_aprob  =0 					 
	WHERE  
	ano_eje   = @PN_ANIO and
	sec_ejec  = @PN_EJEC and
	indicador = '0' and
	flag_meta_aprob = '1' AND
	EXISTS( SELECT '1' FROM TMP_SIG_CN_TECHO_APROB_UPD A
	WHERE
	sig_techo_presupuesto.origen   	  = A.ORIGEN and
	(sig_techo_presupuesto.fuente_financ = A.FUENTE_FINANC or
	sig_techo_presupuesto.fuente_financ = A.FUENTE_IMPTO) and
	sig_techo_presupuesto.clasificador = A.CLASIFICADOR and
	sig_techo_presupuesto.sec_func     = A.SEC_FUNC and
	sig_techo_presupuesto.centro_costo = A.CENTRO_COSTO)

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	delete from TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_CN_TECHO_APROBADO
	(secuencia, centro_costo, origen, fuente_financ, 
	categ_gasto, 
	grupo_gasto,
	clasificador,sec_func,
	valor_cn)
	SELECT  0, c.centro_costo, c.origen, c.fuente_impto, 
	C.CATEG_GASTO, C.GRUPO_GASTO,
	c.clasificador, c.sec_func, sum(ISNULL(C.valor_imp_aprob, 0.00))
	FROM  sig_cuadro_necesidad c, meta m
	WHERE  c.ano_eje   = m.ano_eje and
	c.sec_ejec  = m.sec_ejec and
	c.sec_func  = m.sec_func and
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <>'0' and
	(c.fuente_impto is not null) and
	(c.clasificador is not null) and
	(c.sec_func is not null)
	GROUP BY
	c.centro_costo, c.origen, c.fuente_impto, 
	C.CATEG_GASTO, C.GRUPO_GASTO,
	c.clasificador, c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	UPDATE TMP_SIG_CN_TECHO_APROBADO
	SET FUNCION = (SELECT FUNCION FROM META 
	WHERE ano_eje= @PN_ANIO and 
	sec_ejec = @PN_EJEC AND 
	SEC_FUNC = TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC),
	PROGRAMA = (SELECT PROGRAMA FROM META 
	WHERE ano_eje= @PN_ANIO and 
	sec_ejec = @PN_EJEC AND 
	SEC_FUNC = TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC)

	IF @@ERROR <> 0
	BEGIN
		return -1
	END


	SELECT @ld_min_correl = MIN(CORRELATIVO) FROM TMP_SIG_CN_TECHO_APROBADO

	UPDATE TMP_SIG_CN_TECHO_APROBADO
	SET secuencia = correlativo - @ld_min_correl + 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @li_secuencia = MAX( secuencia ) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	if @li_secuencia  IS NULL 
	begin
	  SELECT @li_secuencia = 0
	end 

	insert INTO sig_techo_presupuesto  
	(ano_eje     , sec_ejec      ,  origen        ,fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
	funcion      , programa      ,	sec_func     , centro_costo, 
	ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
	mnto_progra  ,mnto_asig		  , mnto_aprob		 , mnto_modif,
	indicador	 , paac_inicial  , paac_modif     ,porc_techo ,
	porc_asig, flag_meta_aprob)
	select 
	@PN_ANIO    , @PN_EJEC  , m.origen     , m.fuente_financ,
	m.secuencia + @li_secuencia, m.categ_gasto, m.grupo_gasto, m.clasificador, 
	m.funcion  , m.programa   , m.sec_func   ,m.centro_costo,
	0 ,0  , 0 ,0 ,
	0  , 0	,m.valor_cn , 0,
	'0' , 0	  , 0   ,0  ,
	0, '1'
	from TMP_SIG_CN_TECHO_APROBADO m
	where
	(SELECT count(*) 
	FROM sig_techo_presupuesto
	WHERE 
	ano_eje  = @PN_ANIO and
	sec_ejec = @PN_EJEC	and
	origen = m.origen and
	fuente_financ = m.fuente_financ and
	categ_gasto = m.categ_gasto and
	grupo_gasto = m.grupo_gasto and
	clasificador = m.clasificador and
	funcion     = m.funcion and
	programa= m.programa  and
	sec_func = m.sec_func and
	centro_costo= m.centro_costo and
	indicador     = '0' and
	flag_meta_aprob = '1') = 0

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	delete from TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_CN_TECHO_APROBADO
	(secuencia, centro_costo, origen, fuente_financ, 
	categ_gasto, 
	grupo_gasto,
	clasificador,sec_func,
	valor_cn)
	SELECT  0, c.centro_costo, c.origen, c.fuente_financ, 
	C.CATEG_GASTO,C.GRUPO_GASTO,
	c.clasificador, c.sec_func,SUM(ISNULL(C.monto_aprob, 0.00))
  	FROM  sig_cuadro_necesidad c, meta m
 	WHERE  
	c.ano_eje   = m.ano_eje and
	c.sec_ejec  = m.sec_ejec and
	c.sec_func  = m.sec_func and
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.fase_cuadro  = @PN_FASE and
	(c.fuente_financ is not null) and
	(c.clasificador is not null) and
	(c.sec_func is not null)		
	GROUP BY
	c.centro_costo, c.origen, c.fuente_financ, 
	C.CATEG_GASTO,C.GRUPO_GASTO,
	c.clasificador, c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	UPDATE TMP_SIG_CN_TECHO_APROBADO
	SET FUNCION = (SELECT FUNCION FROM META 
	WHERE ano_eje= @PN_ANIO and 
	sec_ejec = @PN_EJEC AND 
	SEC_FUNC = TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC),
	PROGRAMA = (SELECT PROGRAMA FROM META 
	WHERE ano_eje= @PN_ANIO and 
	sec_ejec = @PN_EJEC AND 
	SEC_FUNC = TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC)

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @ld_min_correl = MIN(CORRELATIVO) FROM TMP_SIG_CN_TECHO_APROBADO

	UPDATE TMP_SIG_CN_TECHO_APROBADO
	SET secuencia = correlativo - @ld_min_correl + 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @li_secuencia = MAX( secuencia ) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	if @li_secuencia  IS NULL 
	begin
	  SELECT @li_secuencia = 0
	end 

	insert INTO sig_techo_presupuesto  
	(ano_eje     , sec_ejec      ,  origen        ,fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
	funcion      , programa      ,	sec_func     , centro_costo, 
	ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
	mnto_progra  ,mnto_asig		  , mnto_aprob		 , mnto_modif,
	indicador	 , paac_inicial  , paac_modif     ,porc_techo ,
	porc_asig, flag_meta_aprob)
	select 
	@PN_ANIO    , @PN_EJEC  , m.origen     , m.fuente_financ,
	m.secuencia + @li_secuencia, m.categ_gasto, m.grupo_gasto, m.clasificador, 
	m.funcion  , m.programa   , m.sec_func   ,m.centro_costo,
	0 ,0  , 0 ,0 ,
	0  , 0	,m.valor_cn , 0,
	'0' , 0	  , 0   ,0  ,
	0, '1'
	from TMP_SIG_CN_TECHO_APROBADO m
	where
	(SELECT count(*) 
	FROM sig_techo_presupuesto
	WHERE 
	ano_eje  = @PN_ANIO and
	sec_ejec = @PN_EJEC	and
	origen = m.origen and
	fuente_financ = m.fuente_financ and
	categ_gasto = m.categ_gasto and
	grupo_gasto = m.grupo_gasto and
	clasificador = m.clasificador and
	funcion     = m.funcion and
	programa= m.programa  and
	sec_func = m.sec_func and
	centro_costo= m.centro_costo and
	indicador     = '0' and
	flag_meta_aprob = '1') = 0

	IF @@ERROR <> 0
	BEGIN
		return -1
	END


	delete from TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	DELETE FROM TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_CN_TECHO_APROB_UPD
	(centro_costo,origen,fuente_financ,fuente_impto,clasificador,sec_func,valor_cn1,valor_cn2)
	SELECT  c.centro_costo, c.origen, c.fuente_financ, '00', c.clasificador, c.sec_func, sum(c.valor_imp_aprob), sum(c.monto_aprob)
  	FROM  sig_cuadro_necesidad c
 	WHERE 
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.fase_cuadro  = @PN_FASE and
	(c.fuente_financ is not null ) and
	(c.clasificador is not null) and
	(c.sec_func is not null)
	group by c.centro_costo, c.origen, c.fuente_financ, c.clasificador, c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END



	update sig_techo_presupuesto
	set mnto_aprob = (SELECT SUM(ISNULL(M.VALOR_CN2,0.00)) 
			FROM TMP_SIG_CN_TECHO_APROB_UPD M
			WHERE
			M.origen   	 = sig_techo_presupuesto.ORIGEN AND
			M.fuente_financ= sig_techo_presupuesto.FUENTE_FINANC AND
			M.clasificador = sig_techo_presupuesto.CLASIFICADOR AND
			M.sec_func  = sig_techo_presupuesto.SEC_FUNC AND
			M.centro_costo = sig_techo_presupuesto.CENTRO_COSTO)
	WHERE 
	ano_eje  	 = @PN_ANIO and
	sec_ejec 	 =@PN_EJEC and
	indicador = '0' and
	flag_meta_aprob = '1' AND 
	EXISTS (SELECT '1'
	FROM TMP_SIG_CN_TECHO_APROB_UPD M
	WHERE
	M.origen   	 = sig_techo_presupuesto.ORIGEN AND
	M.fuente_financ= sig_techo_presupuesto.FUENTE_FINANC AND
	M.clasificador = sig_techo_presupuesto.CLASIFICADOR AND
	M.sec_func  = sig_techo_presupuesto.SEC_FUNC AND
	M.centro_costo = sig_techo_presupuesto.CENTRO_COSTO)

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	DELETE FROM TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_CN_TECHO_APROB_UPD
	(centro_costo,origen,fuente_financ,fuente_impto,clasificador,sec_func,valor_cn1,valor_cn2)
	SELECT  c.centro_costo, c.origen, '00',c.fuente_impto, c.clasificador, c.sec_func, sum(c.valor_imp_aprob), sum(c.monto_aprob)
  	FROM  sig_cuadro_necesidad c
 	WHERE 
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <>'0' and
	( c.fuente_impto is not null) and
	( c.clasificador is not null ) and
	( c.sec_func is not null )
	group by c.centro_costo, c.origen, c.fuente_impto, c.clasificador, c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	update sig_techo_presupuesto
	set mnto_aprob = ISNULL(mnto_aprob, 0.00) + (SELECT SUM(ISNULL(M.VALOR_CN1,0.00)) 
			FROM TMP_SIG_CN_TECHO_APROB_UPD M
			WHERE
			M.origen   	 = sig_techo_presupuesto.ORIGEN AND
			M.fuente_impto   = sig_techo_presupuesto.FUENTE_FINANC AND
			M.clasificador   = sig_techo_presupuesto.CLASIFICADOR AND
			M.sec_func       = sig_techo_presupuesto.SEC_FUNC AND
			M.centro_costo   = sig_techo_presupuesto.CENTRO_COSTO)
	WHERE 
	ano_eje  	 =@PN_ANIO and
	sec_ejec 	 =@PN_EJEC and
	indicador = '0' and
	flag_meta_aprob = '1' AND
	EXISTS(SELECT '1'
	FROM TMP_SIG_CN_TECHO_APROB_UPD M
	WHERE
	M.origen   	 = sig_techo_presupuesto.ORIGEN AND
	M.fuente_impto   = sig_techo_presupuesto.FUENTE_FINANC AND
	M.clasificador   = sig_techo_presupuesto.CLASIFICADOR AND
	M.sec_func       = sig_techo_presupuesto.SEC_FUNC AND
	M.centro_costo   = sig_techo_presupuesto.CENTRO_COSTO)

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	DELETE FROM TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

END

declare c_0b cursor for
select distinct centro_costo
from sig_techo_presupuesto
where 
ano_eje  	 = @PN_ANIO and
sec_ejec 	 = @PN_EJEC and
indicador     = '0' and
(centro_costo_presup is null or centro_costo_presup = '')

open c_0b
fetch c_0b into @ls_centro_costo

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @ls_centro_costo_cambio = @ls_centro_costo

	SELECT @ls_flag_presup = 'N'

	WHILE @ls_flag_presup = 'N'
	BEGIN
		select @ls_centro_padre = CENTRO_PADRE,
		@ls_flag_presup = FLAG_PRESUPUESTO
		from SIG_CENTRO_COSTO
		where 
		ano_eje = @PN_ANIO and
		sec_ejec = @PN_EJEC and
		centro_costo = @ls_centro_costo_cambio

		if (@ls_flag_presup IS NULL) or (@ls_flag_presup = '')
		BEGIN
			SELECT @Ls_flag_presup = 'N'
		END
		
		IF upper(@ls_flag_presup) <> 'S' 
		BEGIN
			IF  (@ls_centro_padre IS NULL) or (@ls_centro_padre = '') 
			BEGIN
				SELECT @Ls_flag_presup = 'S'
				SELECT @ls_centro_costo_presup = ''
			END			   	
			ELSE
			BEGIN
				SELECT @ls_centro_costo_cambio = @ls_centro_padre
				SELECT @Ls_flag_presup = 'N'
			END
		END
		ELSE
		BEGIN
			SELECT @Ls_flag_presup = 'S'
			SELECT @ls_centro_costo_presup = @ls_centro_costo_cambio
		END
	END

	update  sig_techo_presupuesto
	set centro_costo_presup = @ls_centro_costo_presup
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	centro_costo = @ls_centro_costo and 
	indicador = '0' and
	(centro_costo_presup is null or centro_costo_presup = '')

	IF @@ERROR <> 0
	BEGIN
		CLOSE c_0b
		DEALLOCATE c_0b
		--GOTO ERROR
		return -1
	END
		
	fetch c_0b into @ls_centro_costo
END
CLOSE c_0b
DEALLOCATE c_0b


IF @PN_FASE = 1 OR @PN_FASE = 2 
BEGIN

SELECT @li_secuencia = max(secuencia) 
  FROM sig_techo_presupuesto 
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

IF @PN_FASE = 1
BEGIN
insert into tmp_techo_fase_2
( origen ,fuente_financ , mnto_progra , FASE_CUADRO)
	SELECT DISTINCT b.origen, b.fuente_financ,
	(
		SELECT  sum(mnto_progra) 
		FROM sig_techo_presupuesto  a
		WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND
		       a.origen   = b.origen and a.fuente_financ = b.fuente_financ and
		       a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1
	) as total, 1
	FROM sig_techo_presupuesto b
	WHERE 	b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND
		b.indicador     = '0' and b.flag_meta_aprob = '0' and
		B.FASE_CUADRO = 1 AND
		not exists ( select '1'
		  	      FROM sig_techo_presupuesto c
			     WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND
				   c.origen    = b.origen and c.fuente_financ = b.fuente_financ and
				   c.FASE_CUADRO = 1 AND
				   c.indicador     ='1' and c.flag_meta_aprob = '0')


			insert INTO sig_techo_presupuesto  
		      ( ano_eje     , sec_ejec      , origen         , fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , sec_func       , centro_costo, 
			ppto_progra  , ppto_aprob  , ppto_asignado ,	ppto_modif,
			mnto_progra  , mnto_asig  , mnto_aprob	    , mnto_modif,
			indicador   , paac_inicial  , paac_modif     , porc_techo , 
			porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,
			FASE_CUADRO )
		  select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,
			( @li_secuencia + secuencia ) , NULL, NULL , NULL,
 			NULL ,NULL , NULL , NULL,
			0 , 0 , 0 , 0 ,
			mnto_progra,0, 0, 0 ,
			'1' ,0, 0 , 0 ,
			0 , NULL , '0' , NULL, 1
			from tmp_techo_fase_2

END

IF @PN_FASE = 2 
BEGIN

insert into tmp_techo_fase_2
( origen ,fuente_financ , mnto_progra , FASE_CUADRO)
	SELECT DISTINCT b.origen, b.fuente_financ,
	(
		SELECT  sum(mnto_ASIG) 
		FROM sig_techo_presupuesto  a
		WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND
		       a.origen   = b.origen and a.fuente_financ = b.fuente_financ and
		       a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 2
	) as total, 2
	FROM sig_techo_presupuesto b
	WHERE 	b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND
		b.indicador     = '0' and b.flag_meta_aprob = '0' and
		B.FASE_CUADRO = 2 AND
		not exists ( select '1'
		  	      FROM sig_techo_presupuesto c
			     WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND
				   c.origen    = b.origen and c.fuente_financ = b.fuente_financ and
				   c.FASE_CUADRO = 2 AND
				   c.indicador     ='1' and c.flag_meta_aprob = '0')


			insert INTO sig_techo_presupuesto  
		      ( ano_eje     , sec_ejec      , origen         , fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , sec_func       , centro_costo, 
			ppto_progra  , ppto_aprob  , ppto_asignado ,	ppto_modif,
			mnto_progra  , mnto_asig  , mnto_aprob	    , mnto_modif,
			indicador   , paac_inicial  , paac_modif     , porc_techo , 
			porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,
			FASE_CUADRO )
		  select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,
			( @li_secuencia + secuencia ) , NULL, NULL , NULL,
 			NULL ,NULL , NULL , NULL,
			0 , 0 , 0 , 0 ,
			mnto_progra,0, 0, 0 ,
			'1' ,0, 0 , 0 ,
			0 , NULL , '0' , NULL, 2
			from tmp_techo_fase_2

END

SELECT @li_secuencia = max(secuencia) 
  FROM sig_techo_presupuesto 
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	declare c_2b cursor for
	select origen, fuente_financ, sum(mnto_progra)
	from sig_techo_presupuesto
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     = '0' and
	flag_meta_aprob = '0' AND
	FASE_CUADRO = 1 
	group by origen, fuente_financ
	open c_2b
	fetch c_2b into @ls_origen, @ls_codi_fuen, @ld_valor_progra
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@ld_valor_progra IS NULL ) 
		BEGIN
			SELECT @ld_valor_progra = 0.00
		END

		IF @PN_FASE = 1
		BEGIN
			update sig_techo_presupuesto
			set mnto_progra = @ld_valor_progra
			where 
			ano_eje = @PN_ANIO and
			sec_ejec = @PN_EJEC AND
			origen    = @ls_origen and 
			fuente_financ = @ls_codi_fuen and
			indicador     ='1' and
			flag_meta_aprob = '0' AND
			FASE_CUADRO = 1
		END 

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_2b
			DEALLOCATE c_2b
			--GOTO ERROR
			return -1
		END
	
		fetch c_2b into @ls_origen, @ls_codi_fuen, @ld_valor_progra
	END
	CLOSE c_2b
	DEALLOCATE c_2b

	declare c_2b00 cursor for
	select origen, fuente_financ, SUM(mnto_asig)
	from sig_techo_presupuesto
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     = '0' and
	flag_meta_aprob = '0' AND
	FASE_CUADRO = 2 
	group by origen, fuente_financ
	open c_2b00
	fetch c_2b00 into @ls_origen, @ls_codi_fuen, @ld_valor_asignado
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@ld_valor_asignado IS NULL ) 
		BEGIN
			SELECT @ld_valor_asignado = 0.00
		END

		IF @PN_FASE = 2
		BEGIN
			update sig_techo_presupuesto
			set mnto_asig = @ld_valor_asignado
			where 
			ano_eje = @PN_ANIO and
			sec_ejec = @PN_EJEC AND
			origen    = @ls_origen and 
			fuente_financ = @ls_codi_fuen and
			indicador     ='1' and
			flag_meta_aprob = '0' AND
			FASE_CUADRO = 2
		END

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_2b00
			DEALLOCATE c_2b00
			--GOTO ERROR
			return -1
		END
	
		fetch c_2b00 into @ls_origen, @ls_codi_fuen, @ld_valor_asignado
	END
	CLOSE c_2b00
	DEALLOCATE c_2b00
	
	declare c_3b cursor for
	select distinct FASE_CUADRO, origen, fuente_financ, categ_gasto, grupo_gasto
	from sig_techo_presupuesto
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     = '0' and
	flag_meta_aprob = '0'
	open c_3b
	fetch c_3b into @lI_FASE_CUADRO, @ls_origen, @ls_codi_fuen, @ls_categ_gasto, @ls_grupo_gasto
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @lI_FASE_CUADRO = 1 
		BEGIN
			select @li_contador  = count(*) 
			from sig_techo_presupuesto
			where 
			ano_eje = @PN_ANIO and
			sec_ejec = @PN_EJEC AND
			origen    = @ls_origen and 
			fuente_financ = @ls_codi_fuen and
			categ_gasto   = @ls_categ_gasto and 
			grupo_gasto   = @ls_grupo_gasto and 
			indicador     ='2' and
			flag_meta_aprob = '0' AND
			FASE_CUADRO = 1
	
			if (@li_contador=0) or (@li_contador IS NULL)
			BEGIN
				SELECT @li_contador=0
			END
		
			IF @li_contador = 0 
			BEGIN
				select @ld_valor_progra = sum(mnto_progra)
				from sig_techo_presupuesto
				where 
				ano_eje = @PN_ANIO and
				sec_ejec = @PN_EJEC AND
				origen    = @ls_origen and 
				fuente_financ = @ls_codi_fuen and
				categ_gasto   = @ls_categ_gasto and 
				grupo_gasto   = @ls_grupo_gasto and 
				indicador     ='0' and
				flag_meta_aprob = '0'AND
				FASE_CUADRO = 1
			
				if (@ld_valor_progra IS NULL) 
				BEGIN
					SELECT @ld_valor_progra= 0.00
				END

				SELECT @li_secuencia = @li_secuencia +1			

				insert into sig_techo_presupuesto  
				(ano_eje     , sec_ejec      , origen         , fuente_financ,
				secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
				funcion      , programa      , sec_func       , centro_costo, 
				ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
				mnto_progra  , mnto_asig	  , mnto_aprob	    , mnto_modif,
				indicador	 , paac_inicial  , paac_modif     , porc_techo , 
				porc_asig    , sec_func_prop , flag_meta_aprob, centro_costo_presup,
				FASE_CUADRO)
				values 
				(@PN_ANIO     , @PN_EJEC    , @ls_origen      , @ls_codi_fuen,
				@li_secuencia, @ls_categ_gasto , @ls_grupo_gasto , NULL, 
				NULL  , NULL    , NULL        , NULL,
				0 , 0   , 0 , 0  ,
				@ld_valor_progra,0 , 0 , 0 ,
				'2' , 0 , 0  , 0  ,
				0  , NULL , '0', NULL ,1)

				IF @@ERROR <> 0
				BEGIN
					CLOSE c_3b
					DEALLOCATE c_3b
					--GOTO ERROR
					return -1
				END
			END
		END


		IF @lI_FASE_CUADRO = 2
		BEGIN
			select @li_contador  = count(*) 
			from sig_techo_presupuesto
			where 
			ano_eje = @PN_ANIO and
			sec_ejec = @PN_EJEC AND
			origen    = @ls_origen and 
			fuente_financ = @ls_codi_fuen and
			categ_gasto   = @ls_categ_gasto and 
			grupo_gasto   = @ls_grupo_gasto and 
			indicador     ='2' and
			flag_meta_aprob = '0' AND
			FASE_CUADRO = 2
	
			if (@li_contador=0) or (@li_contador IS NULL)
			BEGIN
				SELECT @li_contador=0
			END
		
			IF @li_contador = 0 
			BEGIN
				select @ld_valor_asignado = sum(mnto_asig) 
