ELSE
BEGIN
	--FASE 3 APROBACION
	--nivel de fuente de financiamiento insert
	delete from TMP_SIG_TECHO_APROB_UPD_01

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO TMP_SIG_TECHO_APROB_UPD_01
	(secuencia, origen, fuente_financ, valor_techo)
	select 0, a.origen, a.fuente_financ, sum(a.mnto_aprob) 
	from sig_techo_presupuesto a
	where 
	a.ano_eje = @PN_ANIO and
	a.sec_ejec = @PN_EJEC AND
	a.indicador     = '0' and
	a.flag_meta_aprob = '1' and
	a.funcion is not null and
	a.programa is not null and
	(select count(*) from sig_techo_presupuesto b
	where 
	b.ano_eje = @PN_ANIO and
	b.sec_ejec = @PN_EJEC AND
	b.origen    = a.origen and 
	b.fuente_financ = a.fuente_financ and
	b.indicador     = '1' and
	b.flag_meta_aprob = '1') = 0
	group by a.origen, a.fuente_financ


	IF @@ERROR <> 0
	BEGIN
		return -1
	END
	
	SELECT @ld_min_correl = 0
	SELECT @ld_min_correl = MIN(CORRELATIVO) FROM TMP_SIG_TECHO_APROB_UPD_01

	UPDATE TMP_SIG_TECHO_APROB_UPD_01
	SET secuencia = correlativo - @ld_min_correl + 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @li_secuencia = MAX( secuencia ) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	if @li_secuencia  IS NULL 
	begin
	  SELECT @li_secuencia = 0
	end 

	insert INTO sig_techo_presupuesto  
	(ano_eje     , sec_ejec      ,  origen        ,fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
	funcion      , programa      ,	sec_func     , centro_costo, 
	ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
	mnto_progra  ,mnto_asig		  , mnto_aprob		 , mnto_modif,
	indicador	 , paac_inicial  , paac_modif     ,porc_techo ,
	porc_asig, sec_func_prop, flag_meta_aprob)
	select 
	@PN_ANIO    , @PN_EJEC  , m.origen     , m.fuente_financ,
	m.secuencia + @li_secuencia, null, null, null, 
	null  , null   , null   ,null,
	0 ,0  , 0 ,0 ,
	0  , 0	,m.valor_techo , 0,
	'1' , 0	  , 0   ,0  ,
	0, null, '1'
	from TMP_SIG_TECHO_APROB_UPD_01 m

	IF @@ERROR <> 0
