TRUNCATE TABLE dbo.TMP_SIG_TECHO_APROB_UPD_02
TRUNCATE TABLE dbo.TMP_SIG_TECHO_APROB_UPD_03
TRUNCATE TABLE dbo.TMP_SIG_TECHO_APROB_UPD_04
TRUNCATE TABLE dbo.TMP_SIG_TECHO_APROB_UPD_05
