-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_CONTRATO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_CONTRATO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_CONTRATO]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_CONTRATO]
    @P_ANO_EJE                  NUMERIC(4,0),
    @P_SEC_EJC         		VARCHAR(10),
    @fecha_carga_inicio         VARCHAR(10),
    @fecha_carga_fin            VARCHAR(10),
    @P_USUARIO       		VARCHAR(30),
    @O_ERR_NUM     		NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG     		VARCHAR(255) OUTPUT    
AS
/******************************************************************************/
/*Descripci?n  : Inserta              */
/*               en tablas finales SI_CONTRATOS, SI_CONTRATOS_DETA            */
/*Input        : Todos los IN                                                 */
/*Output       : Todos los OUT                                                */
/*Creaci?n     : 11/06/2009 - Hugo Pilco S. (En base a la version            */
/*               para Oracle, desarrollado por Nery Arroyo)                   */
/******************************************************************************/
DECLARE @LC_TIPO_BIEN               VARCHAR(1)
DECLARE @LC_NRO_CONTRATO      VARCHAR(50)
DECLARE @LC_PROVEEDOR_NRO_RUC       VARCHAR(11)       
DECLARE @LC_D_PROVEEDOR      VARCHAR(100)
DECLARE @LC_ESPEC_TECNICAS      VARCHAR(350)   
DECLARE @LC_FECHA_INICIAL      DATETIME  
DECLARE @LC_FECHA_FINAL      DATETIME  
DECLARE @LC_FECHA       DATETIME        
DECLARE @LC_MONEDA_PAGO      VARCHAR(10)
DECLARE @LC_NRO_DOCUMENTO           VARCHAR(15)
DECLARE @LN_ID_SI_CONTRATO      NUMERIC(10,0)
DECLARE @LN_ID_SI_CONTRATO_DETA     NUMERIC(10,0)
DECLARE @LC_ANO_PROCESO      NUMERIC(4,0)   
DECLARE @LC_MES_PROCESO        VARCHAR(2)     
DECLARE @LC_ESTADO                  VARCHAR(20)
DECLARE @LC_NRO_ORDEN       NUMERIC(7,0)     
DECLARE @LC_TIPO              VARCHAR(1)
DECLARE @LC_EJECUTADO       NUMERIC(16,2)
DECLARE @LC_IMPORTE       NUMERIC(16,2) 
DECLARE @_CANTIDAD        NUMERIC(16,2)  
DECLARE @LC_FECHA_ORDEN      DATETIME
DECLARE @fecha_carga_inicio_1         DATETIME
DECLARE @fecha_carga_fin_1            DATETIME  
DECLARE @fecha_carga_inicio_2         VARCHAR(10)
DECLARE @fecha_carga_fin_2            VARCHAR(10)  
BEGIN  
     DELETE FROM DBO.SI_CONTRATO_DETA 
     DELETE FROM DBO.SI_CONTRATO 

     SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
     SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
     SET @fecha_carga_inicio_2 = Convert(VARCHAR, @fecha_carga_inicio_1, 112)
     SET @fecha_carga_fin_2    = Convert(VARCHAR, @fecha_carga_fin_1, 112)
          
     SELECT @LN_ID_SI_CONTRATO = MAX(ID_SI_CONTRATO)
     FROM SI_CONTRATO
     WHERE ANO_EJE  = @P_ANO_EJE 
       AND SEC_EJEC = @P_SEC_EJC

     IF @LN_ID_SI_CONTRATO IS NULL
           SET @LN_ID_SI_CONTRATO = 0
 
  DECLARE C_1 CURSOR FOR 
  SELECT DISTINCT(NRO_CONTRATO) AS NRO_CONTRATO, TIPO_BIEN, NOMBRE_PROV,
  NRO_RUC, FECHA, ESPEC_TECNICAS, FECHA_INICIAL, FECHA_FINAL,
  MONEDA_PAGO,  NRO_DOCUMENTO
  FROM(
  SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,  
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
            SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Pendiente' as estado,   
           0 as nro_orden,   
           '1' as tipo,   
           0 as ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
          FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
           (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
           ( sig_contrato_item_mensual.flag_proceso = 'N' ) ) AND  
 	   ( CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
  	     CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2)

    GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
            SIG_CONTRATOS.TIPO_BIEN,
            SIG_CONTRATISTAS.NOMBRE_PROV,   
            SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
            SIG_CONTRATOS.FECHA_INICIAL,   
            SIG_CONTRATOS.FECHA_FINAL,   
            SIG_CONTRATOS.MONEDA_PAGO,         
            SIG_CONTRATOS.NRO_DOCUMENTO,         
            SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
            SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
    SELECT SIG_CONTRATOS.NRO_CONTRATO, 
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Cuadro' as estado,   
           0 as nro_orden,   
           '2' as tipo,   
           0 as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM  SIG_CONTRATOS,   
           SIG_CONTRATO_ITEM_MENSUAL,   
           SIG_CUADRO_ADQUISICION,   
          SIG_CONTRATISTAS  
       WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
            ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
            ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
            ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
            ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
            ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
            ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
            ( sig_contratos.ano_eje = sig_cuadro_adquisicion.ano_contrato ) AND  
            ( sig_cuadro_adquisicion.estado = '1' ) AND  
            ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
            (sig_contrato_item_mensual.ano_proceso > 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) ) AND  
(CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
 CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2 )   
 
    GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
             SIG_CONTRATOS.TIPO_BIEN,
             SIG_CONTRATISTAS.NOMBRE_PROV,   
             SIG_CONTRATISTAS.NRO_RUC,   
             SIG_CONTRATOS.FECHA,   
             SIG_CONTRATOS.ESPEC_TECNICAS,   
             SIG_CONTRATOS.FECHA_INICIAL,   
             SIG_CONTRATOS.FECHA_FINAL,   
             SIG_CONTRATOS.MONEDA_PAGO,         
             SIG_CONTRATOS.NRO_DOCUMENTO,         
             SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
             SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
  SELECT  SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN,   
          SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
       SIG_CONTRATOS.FECHA_INICIAL,   
    SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           sig_contratos.tipo_bien as estado,   
           sig_orden_adquisicion.nro_orden as nro_orden,   
           '3' as tipo,   
           sig_orden_adquisicion.total_fact_moneda as  ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda)  as importe,   
           sig_orden_adquisicion.fecha_orden as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CUADRO_ADQUISICION,   
                SIG_ORDEN_ADQUISICION,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.ANO_EJE = SIG_ORDEN_ADQUISICION.ANO_CUADRO ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_EJEC = SIG_ORDEN_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CUADRO_ADQUISICION.TIPO_BIEN = SIG_ORDEN_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_CUADRO = SIG_ORDEN_ADQUISICION.SEC_CUADRO ) and  
           ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
          ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
           ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
           ( sig_cuadro_adquisicion.estado = '2' ) AND  
           ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
           (sig_contrato_item_mensual.ano_proceso > 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) ) AND
 
 ( CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2)
 
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN, 
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,  
           SIG_CONTRATOS.NRO_DOCUMENTO,                
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           SIG_ORDEN_ADQUISICION.NRO_ORDEN,   
           SIG_ORDEN_ADQUISICION.FECHA_ORDEN,   
           SIG_ORDEN_ADQUISICION.TOTAL_FACT_MONEDA
  UNION   
  SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
          SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Externo' as estado,   
            0 as nro_orden,   
           '4' as tipo,   
           sum ( sig_contrato_item_mensual.valor_moneda) as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATISTAS.PROVEEDOR = SIG_CONTRATOS.PROVEEDOR ) and  
          ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
          ( sig_contrato_item_mensual.flag_proceso = 'S' ) AND  
          ( sig_contrato_item_mensual.sec_cuadro is null ) )  AND
 
 ( CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2) 
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
    )AS TABLE1
 
  		
    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,    @LC_D_PROVEEDOR, 
  	 @LC_PROVEEDOR_NRO_RUC, @LC_FECHA,        @LC_ESPEC_TECNICAS, 
  	 @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  @LC_MONEDA_PAGO, 
  	 @LC_NRO_DOCUMENTO
 
    WHILE @@FETCH_STATUS = 0
    BEGIN
    SET @LN_ID_SI_CONTRATO = @LN_ID_SI_CONTRATO + 1

    INSERT INTO SI_CONTRATO
    (ANO_EJE,             SEC_EJEC,           ID_SI_CONTRATO, 
     NRO_CONTRATO,        TIPO_BIEN,          FECHA_CONTRATO, 
     CONCEPTO_CONTRATO,   PROVEEDOR_NRO_RUC,  D_PROVEEDOR, 
     FECHA_INICIO,   	  FECHA_FIN,          MONEDA_PAGO, 
     FECHA_CARGA_INICIO,  NRO_DOCUMENTO,      FECHA_CARGA_FIN, 
     FECHA_ENVIO,         USUARIO_ENVIO)        
  VALUES 
    (@P_ANO_EJE,            @P_SEC_EJC,              @LN_ID_SI_CONTRATO,
     @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,           @LC_FECHA, 
     @LC_ESPEC_TECNICAS,    @LC_PROVEEDOR_NRO_RUC,   @LC_D_PROVEEDOR, 
     @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,         @LC_MONEDA_PAGO, 
     @fecha_carga_inicio_1, @LC_NRO_DOCUMENTO,       @fecha_carga_fin_1, 
     CONVERT(varchar, getdate(), 101),               @P_USUARIO) 
  

  DECLARE C_2 CURSOR FOR
  SELECT NRO_CONTRATO, TIPO_BIEN, NOMBRE_PROV,
         NRO_RUC, FECHA, ESPEC_TECNICAS, FECHA_INICIAL,
         FECHA_FINAL, MONEDA_PAGO, NRO_DOCUMENTO, 
         ANO_PROCESO, MES_PROCESO, estado, nro_orden,
         tipo, ejecutado, importe, fecha_orden 
         FROM (
          
   SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,  
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
            SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
          SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Pendiente' as estado,   
           0 as nro_orden,   
           '1' as tipo,   
           0 as ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
          FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
           (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
 
           ( sig_contrato_item_mensual.flag_proceso = 'N' ) )  AND

 ( CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2) 
 
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
            SIG_CONTRATOS.TIPO_BIEN,
            SIG_CONTRATISTAS.NOMBRE_PROV,   
            SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
            SIG_CONTRATOS.FECHA_INICIAL,   
            SIG_CONTRATOS.FECHA_FINAL,   
            SIG_CONTRATOS.MONEDA_PAGO,         
            SIG_CONTRATOS.NRO_DOCUMENTO,         
            SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
            SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
    SELECT SIG_CONTRATOS.NRO_CONTRATO, 
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Cuadro' as estado,   
           0 as nro_orden,   
           '2' as tipo,   
           0 as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM  SIG_CONTRATOS,   
           SIG_CONTRATO_ITEM_MENSUAL,   
           SIG_CUADRO_ADQUISICION,   
          SIG_CONTRATISTAS  
       WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
            ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
            ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
            ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
            ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
            ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
            ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
            ( sig_contratos.ano_eje = sig_cuadro_adquisicion.ano_contrato ) AND  
 
            ( sig_cuadro_adquisicion.estado = '1' ) AND  
            ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
            (sig_contrato_item_mensual.ano_proceso > 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) ) AND  
 
 ( CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2)
   
    GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
            SIG_CONTRATOS.TIPO_BIEN,
                   SIG_CONTRATISTAS.NOMBRE_PROV,   
            SIG_CONTRATISTAS.NRO_RUC,   
            SIG_CONTRATOS.FECHA,   
            SIG_CONTRATOS.ESPEC_TECNICAS,   
            SIG_CONTRATOS.FECHA_INICIAL,   
             SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
     SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
  SELECT  SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN,   
          SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           sig_contratos.tipo_bien as estado,   
           sig_orden_adquisicion.nro_orden as nro_orden,   
           '3' as tipo,   
           sig_orden_adquisicion.total_fact_moneda as  ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda)  as importe,   
           sig_orden_adquisicion.fecha_orden as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CUADRO_ADQUISICION,   
                SIG_ORDEN_ADQUISICION,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.ANO_EJE = SIG_ORDEN_ADQUISICION.ANO_CUADRO ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_EJEC = SIG_ORDEN_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CUADRO_ADQUISICION.TIPO_BIEN = SIG_ORDEN_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_CUADRO = SIG_ORDEN_ADQUISICION.SEC_CUADRO ) and  
           ( SIG_CONTRATOS.PROVEEDOR = SIG_CONTRATISTAS.PROVEEDOR ) and  
          ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
           ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
 
           ( sig_cuadro_adquisicion.estado = '2' ) AND  
           ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
           (sig_contrato_item_mensual.ano_proceso > 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) )   
   AND   

  (CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2)
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN, 
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,  
           SIG_CONTRATOS.NRO_DOCUMENTO,                
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           SIG_ORDEN_ADQUISICION.NRO_ORDEN,   
           SIG_ORDEN_ADQUISICION.FECHA_ORDEN,   
           SIG_ORDEN_ADQUISICION.TOTAL_FACT_MONEDA
  UNION   
  SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
          SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
      SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Externo' as estado,   
            0 as nro_orden,   
           '4' as tipo,   
           sum ( sig_contrato_item_mensual.valor_moneda) as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CONTRATISTAS  
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATISTAS.PROVEEDOR = SIG_CONTRATOS.PROVEEDOR ) and  
          ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
          
          ( sig_contrato_item_mensual.flag_proceso = 'S' ) AND  
          ( sig_contrato_item_mensual.sec_cuadro is null ) )   
 
   AND   
  (CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) >= @fecha_carga_inicio_2 AND
   CONVERT(VARCHAR, SIG_CONTRATOS.FECHA, 112) <= @fecha_carga_fin_2)
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATISTAS.NOMBRE_PROV,   
           SIG_CONTRATISTAS.NRO_RUC,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  )AS TABLA1 WHERE NRO_CONTRATO = @LC_NRO_CONTRATO
 
  OPEN C_2
         FETCH NEXT FROM C_2 
         INTO @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,    @LC_D_PROVEEDOR, 
            @LC_PROVEEDOR_NRO_RUC, @LC_FECHA,        @LC_ESPEC_TECNICAS, 
            @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  @LC_MONEDA_PAGO, 
            @LC_NRO_DOCUMENTO,     @LC_ANO_PROCESO,  @LC_MES_PROCESO,
            @LC_ESTADO,      @LC_NRO_ORDEN,    @LC_TIPO, 
       @LC_EJECUTADO,     @LC_IMPORTE,      @LC_FECHA_ORDEN  
 
         WHILE @@FETCH_STATUS = 0
         BEGIN         
 
  SELECT @LN_ID_SI_CONTRATO_DETA = MAX(ID_SI_CONTRATO_DETA)
         FROM SI_CONTRATO_DETA
              WHERE ANO_EJE= @P_ANO_EJE 
                AND SEC_EJEC = @P_SEC_EJC
                AND ID_SI_CONTRATO = @LN_ID_SI_CONTRATO
 
  IF @LC_ESTADO = 'B'      
   SET @LC_ESTADO = 'O/C'
 
  IF @LC_ESTADO = 'S'      
   SET @LC_ESTADO = 'O/S'
 
         IF @LN_ID_SI_CONTRATO_DETA IS NULL
                 SET @LN_ID_SI_CONTRATO_DETA = 0
 
                SET @LN_ID_SI_CONTRATO_DETA = @LN_ID_SI_CONTRATO_DETA + 1


     	INSERT INTO SI_CONTRATO_DETA
                    (ANO_EJE,        SEC_EJEC,    ID_SI_CONTRATO,  
         ID_SI_CONTRATO_DETA,  ANO_PROCESO,        MES_PROCESO,          
         ESTADO,        NRO_ORDEN,    TIPO,          
         MONTO_EJECUTADO,      MONTO_IMPORTE,      FECHA_ORDEN, 
           FECHA_CARGA_INICIO,   FECHA_CARGA_FIN,    FECHA_ENVIO,     
           USUARIO_ENVIO)
           VALUES
             (@P_ANO_EJE,            @P_SEC_EJC,         @LN_ID_SI_CONTRATO,  
           @LN_ID_SI_CONTRATO_DETA,  @LC_ANO_PROCESO,    @LC_MES_PROCESO,      
           @LC_ESTADO,               @LC_NRO_ORDEN,      @LC_TIPO,
     @LC_EJECUTADO,            @LC_IMPORTE,        @LC_FECHA_ORDEN,
           @fecha_carga_inicio_1,    @fecha_carga_fin_1,   
   CONVERT(varchar, getdate(), 112),    @P_USUARIO)
 
         FETCH NEXT FROM C_2 
         INTO @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,    @LC_D_PROVEEDOR, 
            @LC_PROVEEDOR_NRO_RUC, @LC_FECHA,        @LC_ESPEC_TECNICAS, 
            @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  @LC_MONEDA_PAGO, 
            @LC_NRO_DOCUMENTO,     @LC_ANO_PROCESO,  @LC_MES_PROCESO,
            @LC_ESTADO,      @LC_NRO_ORDEN,    @LC_TIPO, 
       @LC_EJECUTADO,     @LC_IMPORTE,      @LC_FECHA_ORDEN  
         END
         CLOSE C_2
         DEALLOCATE C_2
    FETCH NEXT FROM C_1
         INTO @LC_NRO_CONTRATO,   @LC_TIPO_BIEN,    @LC_D_PROVEEDOR, 
       	      @LC_PROVEEDOR_NRO_RUC,    @LC_FECHA,        @LC_ESPEC_TECNICAS, 
       	      @LC_FECHA_INICIAL,  @LC_FECHA_FINAL,  @LC_MONEDA_PAGO, 
       	      @LC_NRO_DOCUMENTO
    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_ACTUALIZA_IDSUBFINALIDAD
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_ACTUALIZA_IDSUBFINALIDAD]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_ACTUALIZA_IDSUBFINALIDAD]
GO

CREATE PROCEDURE [dbo].[SP_ACTUALIZA_IDSUBFINALIDAD](
@P_ANO_EJE_OR   	    	NUMERIC(4,0),
@P_ANO_EJE_dest  	    	NUMERIC(4,0)
)
AS
declare @ls_subfinalidad varchar(7),
	@ls_programa_institucional varchar(6),
	@ll_id_subfin Numeric(10,0),
	@ll_id_subfin_OLD Numeric(10,0),
	@ls_componente varchar(10),
	@ll_cont int ,
	@ll_fila int

BEGIN 
	INSERT INTO SIG_SUB_FINALIDAD (
	ANO_EJE,SUB_FINALIDAD,NOMBRE,FINALIDAD,
	UNIDAD_MEDIDA,CADENA_FUNCIONAL,PROGRAMA_INSTITUCIONAL,ESTADO,ID_SUB_FINALIDAD, COMPONENTE ,ACT_PROY, TIPO_ESTRATEGIA )
	SELECT @P_ANO_EJE_dest as ano_dest,SUB_FINALIDAD,NOMBRE,FINALIDAD,
	       UNIDAD_MEDIDA,CADENA_FUNCIONAL,PROGRAMA_INSTITUCIONAL,ESTADO,ID_SUB_FINALIDAD, COMPONENTE,ACT_PROY, TIPO_ESTRATEGIA
	  FROM SIG_SUB_FINALIDAD  F
	 WHERE ANO_EJE = @P_ANO_EJE_OR  AND 
	       NOT EXISTS (SELECT ANO_EJE FROM SIG_SUB_FINALIDAD  E
				WHERE E.ANO_EJE           = @P_ANO_EJE_dest       AND
				E.SUB_FINALIDAD           = F.SUB_FINALIDAD  AND
				E.PROGRAMA_INSTITUCIONAL  = F.PROGRAMA_INSTITUCIONAL)


	SELECT @ll_fila = @@rowcount
	IF  (	@ll_fila )>0
	BEGIN

		SELECT @ll_id_subfin = COALESCE ( MAX(IsNull(id_sub_finalidad,0)) +1 , 1 )
		 FROM SIG_SUB_FINALIDAD
	
		SELECT ID_SUB_FINALIDAD 
		  INTO #t1
	          FROM SIG_SUB_FINALIDAD
		 WHERE ANO_EJE =@P_ANO_EJE_dest

		DECLARE C_SUBFIN CURSOR FOR
		select ID_SUB_FINALIDAD from #t1
	   	OPEN C_SUBFIN
		FETCH NEXT FROM C_SUBFIN INTO @ll_id_subfin_OLD
		WHILE @@FETCH_STATUS = 0
		BEGIN		
		
			UPDATE SIG_SUB_FINALIDAD WITH (UPDLOCK)
			   SET ID_SUB_FINALIDAD= @ll_id_subfin
			 WHERE ano_eje = @P_ANO_EJE_dest and
			       ID_SUB_FINALIDAD =@ll_id_subfin_OLD
	
			SET @ll_id_subfin = @ll_id_subfin + 1	

		FETCH NEXT FROM C_SUBFIN INTO @ll_id_subfin_OLD
		End

		CLOSE C_SUBFIN
		DEALLOCATE C_SUBFIN

		drop table #t1

	END

END;
GO


-- ----------------------------
-- procedure structure for DT_ISUNDERSOURCECONTROL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_ISUNDERSOURCECONTROL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_ISUNDERSOURCECONTROL]
GO

CREATE PROCEDURE [dbo].[DT_ISUNDERSOURCECONTROL]
    @vchLoginName varchar(255) = '',
    @vchPassword  varchar(255) = '',
    @iWhoToo      int = 0 /* 0 => Just check project; 1 => get list of objs */

as

	set nocount on

	declare @iReturn int
	declare @iObjectId int
	select @iObjectId = 0

	declare @VSSGUID varchar(100)
	select @VSSGUID = 'SQLVersionControl.VCS_SQL'

	declare @iReturnValue int
	select @iReturnValue = 0

	declare @iStreamObjectId int
	select @iStreamObjectId   = 0

	declare @vchTempText varchar(255)

    declare @iPropertyObjectId int
    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    declare @vchProjectName   varchar(255)
    declare @vchSourceSafeINI varchar(255)
    declare @vchServerName    varchar(255)
    declare @vchDatabaseName  varchar(255)
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSProject',       @vchProjectName   OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSourceSafeINI', @vchSourceSafeINI OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLServer',     @vchServerName    OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLDatabase',   @vchDatabaseName  OUT

    if (@vchProjectName = '')	set @vchProjectName		= null
    if (@vchSourceSafeINI = '') set @vchSourceSafeINI	= null
    if (@vchServerName = '')	set @vchServerName		= null
    if (@vchDatabaseName = '')	set @vchDatabaseName	= null
    
    if (@vchProjectName is null) or (@vchSourceSafeINI is null) or (@vchServerName is null) or (@vchDatabaseName is null)
    begin
        RAISERROR('Not Under Source Control',16,-1)
        return
    end

    if @iWhoToo = 1
    begin

        /* Get List of Procs in the project */
        exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT
        if @iReturn <> 0 GOTO E_OAError

        exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
												'GetListOfObjects',
												NULL,
												@vchProjectName,
												@vchSourceSafeINI,
												@vchServerName,
												@vchDatabaseName,
												@vchLoginName,
												@vchPassword

        if @iReturn <> 0 GOTO E_OAError

        exec @iReturn = master.dbo.sp_OAGetProperty @iObjectId, 'GetStreamObject', @iStreamObjectId OUT

        if @iReturn <> 0 GOTO E_OAError

        create table #ObjectList (id int identity, vchObjectlist varchar(255))

        select @vchTempText = 'STUB'
        while @vchTempText is not null
        begin
            exec @iReturn = master.dbo.sp_OAMethod @iStreamObjectId, 'GetStream', @iReturnValue OUT, @vchTempText OUT
            if @iReturn <> 0 GOTO E_OAError
            
            if (@vchTempText = '') set @vchTempText = null
            if (@vchTempText is not null) insert into #ObjectList (vchObjectlist ) select @vchTempText
        end

        select vchObjectlist from #ObjectList order by id
    end

CleanUp:
    return

E_OAError:
    exec dbo.dt_displayoaerror @iObjectId, @iReturn
    goto CleanUp
GO


-- ----------------------------
-- procedure structure for SP_PPR_PROCESAR_TECHOC_FASE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PPR_PROCESAR_TECHOC_FASE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PPR_PROCESAR_TECHOC_FASE]
GO

CREATE PROCEDURE [dbo].[SP_PPR_PROCESAR_TECHOC_FASE]
( @PN_ANIO NUMERIC, 
  @PN_EJEC NUMERIC,
  @PN_FASE NUMERIC
)
AS
BEGIN
        DECLARE @lI_FASE_CUADRO NUMERIC(1,0)
        DECLARE @ls_clasificador VARCHAR(20)
        DECLARE @ls_flag_presup VARCHAR(1)
        DECLARE @ls_centro_costo_presup VARCHAR(15)
        DECLARE @ls_centro_costo VARCHAR(15)
        DECLARE @ls_centro_padre VARCHAR(15)
        DECLARE @ls_origen VARCHAR(1)
        DECLARE @ls_codi_fuen VARCHAR(2)
        DECLARE @ls_codi_fuen_impto VARCHAR(2)
        DECLARE @ls_clas_gast VARCHAR(20)
        DECLARE @ls_funcion VARCHAR(2)
        DECLARE @ls_programa VARCHAR(3)
        DECLARE @ld_Secu_func NUMERIC(4,0)
        DECLARE @li_contador NUMERIC(10,0)
        DECLARE @ld_valor_imp_progra NUMERIC(14,2)
        DECLARE @li_secuencia NUMERIC(10,0)
        DECLARE @ld_valor_progra NUMERIC(14,2)
        DECLARE @ld_valor_aprob NUMERIC(14,2)
        DECLARE @ld_mnto_impto NUMERIC(14,2)
        DECLARE @ld_monto_progra NUMERIC(14,2)
        DECLARE @ld_mnto_total NUMERIC(14,2)
        DECLARE @ld_mnto_apro NUMERIC(14,2)
        DECLARE @ld_mnto_asig NUMERIC(14,2)
        DECLARE @ld_mnto_modif NUMERIC(14,2)
        DECLARE @ls_categ_gasto VARCHAR(1)
        DECLARE @ls_grupo_gasto VARCHAR(1)
        DECLARE @ls_grupo VARCHAR(2)
        DECLARE @ls_grupo1 VARCHAR(2)
        DECLARE @Ls_flag_gen_esp VARCHAR(1)
        DECLARE @ld_valor_imp_asignado NUMERIC(14,2)
        DECLARE @ld_valor_asignado NUMERIC(14,2)
        DECLARE @ld_monto_asignado NUMERIC(14,2)
        DECLARE @ld_monto_aprob NUMERIC(14,2)
        DECLARE @ld_valor_imp_aprob NUMERIC(14,2)

IF @PN_FASE <> 3
   return -1

SELECT @li_contador = COUNT(*)
FROM SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND COD_MAESTRO = 'FLAG_TECHO_NIVEL'

IF ( @li_contador IS NULL) OR ( @li_contador <= 0)
   return -1

SELECT @ls_flag_gen_esp = VALOR
  FROM SIG_PARAMETRO_EJECUTORA_ANIO
 WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND COD_MAESTRO = 'FLAG_TECHO_NIVEL'

SELECT @li_secuencia = MAX( secuencia ) 
  FROM sig_ppr_techo_presupuesto 
 WHERE ano_eje = @PN_ANIO and sec_ejec = @PN_EJEC

if @li_secuencia  IS NULL 
  SELECT @li_secuencia = 0

SET NOCOUNT ON

IF @PN_FASE = 3
 update sig_ppr_techo_presupuesto
 set mnto_aprob = 0 
 WHERE ANO_EJE = @PN_ANIO AND
       SEC_EJEC = @PN_EJEC AND
       flag_meta_aprob = '1'

IF @@ERROR <> 0
   return -1

IF @PN_FASE = 3 
--------------------------------------------
-- ACTUALIZACION DE FASE APROBADO
--------------------------------------------
BEGIN
        DECLARE c_c01A SCROLL Cursor For
        SELECT DISTINCT m.centro_costo, m.origen, m.fuente_financ, m.fuente_impto, m.clasificador, m.sec_func
        FROM sig_ppr_cuadro_necesidad m
        WHERE m.ano_eje = @PN_ANIO and
              m.sec_ejec = @PN_EJEC and 
              m.fase_cuadro = @PN_FASE and
              m.fuente_financ is not null and
              m.clasificador is not null and
              m.sec_func is not null
        OPEN c_c01A
