        OPEN c_040A
        FETCH c_040A INTO @ls_centro_costo, @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
                
        WHILE @@FETCH_STATUS = 0
        BEGIN
                SELECT @ls_categ_gasto = COD_NIVEL1,
