                FROM SIG_CLASIFICADOR_GASTO
                WHERE
                ANO_EJE = @PN_ANIO AND
                CLASIFICADOR = @ls_clas_gast
        
                SELECT @li_contador = count(*) 
                FROM sig_ppr_techo_presupuesto
                WHERE 
                ano_eje = @PN_ANIO and
                sec_ejec = @PN_EJEC and
                origen = @ls_origen and
                fuente_financ = @ls_codi_fuen and
