                END

                FETCH c_050A    INTO @ls_centro_costo, @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob
        END
        CLOSE c_050A
        DEALLOCATE c_050A

        --cursor con contrapartida o con impuesto
        DECLARE c_05A SCROLL cursor for 
        SELECT  c.centro_costo, c.origen, c.fuente_impto, c.clasificador, c.sec_func, sum(c.valor_imp_aprob), sum(c.monto_aprob)
        FROM  sig_ppr_cuadro_necesidad c
        WHERE 
        c.ano_eje = @PN_ANIO and
        c.sec_ejec = @PN_EJEC and
        c.fase_cuadro = @PN_FASE and
        c.tipo_impuesto <>'0' and
        ( c.fuente_impto is not null) and
        ( c.clasificador is not null ) and
        ( c.sec_func is not null )
        group by c.centro_costo, c.origen, c.fuente_impto, c.clasificador, c.sec_func
        OPEN c_05A

        FETCH c_05A     INTO @ls_centro_costo, @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob

        WHILE @@FETCH_STATUS = 0
        BEGIN
                if (@ld_valor_imp_aprob IS NULL) 
                BEGIN
                        SELECT @Ld_valor_imp_aprob = 0.00
                END 
                if (@ld_monto_aprob IS NULL) 
                BEGIN
                        SELECT @ld_monto_aprob = 0.00
                END
        
                update sig_ppr_techo_presupuesto 
                set mnto_aprob = mnto_aprob + @ld_valor_imp_aprob 
                WHERE 
                ano_eje = @PN_ANIO and
                sec_ejec = @PN_EJEC and
                origen = @ls_origen and
                fuente_financ = @ls_codi_fuen and
                clasificador = @ls_clas_gast and
