                centro_costo = @ls_centro_costo and
                indicador = '0' and
                flag_meta_aprob = '1'

                IF @@ERROR <> 0
                BEGIN
                        CLOSE c_05A
                        DEALLOCATE c_05A
                        return -1
                END
                                        
                FETCH c_05A     INTO @ls_centro_costo, @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob

        END
        CLOSE c_05A
        DEALLOCATE c_05A

        --SUBIR A TODOS LOS NIVELES
END

declare c_0b cursor for
select distinct centro_costo
from sig_ppr_techo_presupuesto
where 
ano_eje = @PN_ANIO and
sec_ejec = @PN_EJEC and
indicador = '0'

open c_0b
fetch c_0b into @ls_centro_costo

WHILE @@FETCH_STATUS = 0
BEGIN
        SELECT @ls_flag_presup = 'N'
        WHILE @ls_flag_presup = 'N'
        BEGIN
                select @ls_centro_padre = CENTRO_PADRE,
                @ls_flag_presup = FLAG_PRESUPUESTO
                from SIG_CENTRO_COSTO
                where 
                ano_eje = @PN_ANIO and
                sec_ejec = @PN_EJEC and
                centro_costo = @ls_centro_costo

                if (@ls_flag_presup IS NULL)
                BEGIN
                        SELECT @Ls_flag_presup = 'N'
                END
                
                IF @ls_flag_presup <> 'S' 
                BEGIN
                        IF  (@ls_centro_padre IS NULL) or (@ls_centro_padre = '') 
                        BEGIN
                                SELECT @Ls_flag_presup = 'S'
                                SELECT @ls_centro_costo_presup = ''
                        END                             
                        ELSE
                        BEGIN
                                SELECT @ls_centro_costo = @ls_centro_padre
                                SELECT @Ls_flag_presup = 'N'
                        END
                END
                ELSE
                BEGIN
                        SELECT @Ls_flag_presup = 'S'
                        SELECT @ls_centro_costo_presup = @ls_centro_costo
                END
        END

        update  sig_ppr_techo_presupuesto
        set centro_costo_presup = @ls_centro_costo_presup
        where 
        ano_eje = @PN_ANIO and
        sec_ejec = @PN_EJEC AND
        centro_costo = @ls_centro_costo and 
        indicador = '0' and
        (centro_costo_presup IS NULL )

        IF @@ERROR <> 0
        BEGIN
                CLOSE c_0b
                DEALLOCATE c_0b
                return -1
        END
                
        fetch c_0b into @ls_centro_costo
END
