CREATE PROCEDURE [dbo].[USP_CNDETALLEUPDATE] (
/*
CREATED BY : CHRISTIAN ROSALES
DATE : 20060623
*/
		@sec_ejec numeric(6,0),
		@centro_costo varchar(15),
		@cuser_id varchar(8),
		@fuente_financ varchar(2),
		@tipo_tarea char(1),
		@nivel_tarea char(1),
		@codigo_tarea numeric(10,0),
		@secuencia numeric(5,0),
		@tipo_bien char(1),
		@clasificador varchar(6),
		@precio_unit numeric(16,6),
		@cant_01 numeric(14,2),
		@cant_02 numeric(14,2),
		@cant_03 numeric(14,2),
		@cant_04 numeric(14,2),
		@cant_05 numeric(14,2),
		@cant_06 numeric(14,2),
		@cant_07 numeric(14,2),
		@cant_08 numeric(14,2),
		@cant_09 numeric(14,2),
		@cant_10 numeric(14,2),
		@cant_11 numeric(14,2),
		@cant_12 numeric(14,2),
		@tipo_impto char(1),
		@tasa_impto numeric(14,2),
		@fte_impto varchar(2),
		@item_sec  numeric(6,0),
		@meta numeric(5,0),
		@respuesta varchar(50) OUTPUT
)
AS
--Variable para conocer Estado de Control de Techo
DECLARE @flag_techo_cn char(1)
DECLARE @SECUENCIA2 numeric(10,0)
-- El Año, lo voy a obtener desde la Tabla SIG_PARAMETRO_EJECUTORA
DECLARE @ano_eje numeric(4,0)
-- La Fase y el Estado lo voy obtendre desde la Tabla SIG_CUADRO_X_CENTRO
DECLARE @fase_cuadro numeric(1,0)
DECLARE @estado char(1)
-- campo GASTO, VALOR_IMPTO ...
DECLARE @categ_gasto varchar(1)
DECLARE @grupo_gasto varchar(1)
DECLARE @valor_impto numeric(14,2)
DECLARE @cant_total numeric(14,2)
DECLARE @mnto_01 numeric(14,2)
DECLARE @mnto_02 numeric(14,2)
DECLARE @mnto_03 numeric(14,2)
DECLARE @mnto_04 numeric(14,2)
DECLARE @mnto_05 numeric(14,2)
DECLARE @mnto_06 numeric(14,2)
DECLARE @mnto_07 numeric(14,2)
DECLARE @mnto_08 numeric(14,2)
DECLARE @mnto_09 numeric(14,2)
DECLARE @mnto_10 numeric(14,2)
DECLARE @mnto_11 numeric(14,2)
DECLARE @mnto_12 numeric(14,2)
DECLARE @mnto_total numeric(14,2)
DECLARE @mnto_controltecho numeric(14,2)
DECLARE @resultado varchar(50)
DECLARE @lTotalTP numeric(5,0)
DECLARE @funcion varchar(2)
DECLARE @programa varchar(3)
DECLARE @mnto_progra numeric(14,2)
DECLARE @mnto_asig numeric(14,2)
DECLARE @mnto_aprob numeric(14,2)
DECLARE @mnto_modif numeric(14,2)
DECLARE @mnto_anterior numeric(14,2)
DECLARE @ppto_controltecho numeric(14,2)

if @fte_impto = '' set @fte_impto = null
SET @respuesta = ''
-- Obtención del Año del CN
SELECT @ano_eje = VALOR FROM SIG_PARAMETRO_EJECUTORA 
WHERE COD_MAESTRO = 'PROG_CN_ANO'

-- Obtener el Estado del Control de Techo
SELECT @flag_techo_cn = VALOR FROM SIG_PARAMETRO_EJECUTORA 
WHERE COD_MAESTRO = 'FLAG_TECHO_CN'

-- Obtención del estado y Fase del CN
SELECT @estado = ESTADO FROM SIG_CUADRO_X_CENTRO
WHERE ANO_EJE = @ano_eje AND SEC_EJEC = @sec_ejec
AND CENTRO_COSTO = @centro_costo
IF @estado= '0' SET @fase_cuadro=1
IF @estado= '1' OR @estado= '2' OR @estado= '3'  SET @fase_cuadro=2 
IF @estado= '4' OR @estado= '5' OR @estado= '6'  SET @fase_cuadro=3 
IF @estado = 2 
begin
set @estado = 0
set @fase_cuadro = 1
end

SET @categ_gasto = SUBSTRING(@clasificador,1,2)
SET @grupo_gasto = SUBSTRING(@clasificador,2,3)

SET @cant_total = @cant_01 + @cant_02 + @cant_03 + @cant_04 + @cant_05 + @cant_06 + @cant_07 + @cant_08 + @cant_09 + @cant_10 + @cant_11 + @cant_12 

IF @tipo_bien = 'B'
BEGIN
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit
		SET @mnto_02 = @cant_02 * @precio_unit
		SET @mnto_03 = @cant_03 * @precio_unit
		SET @mnto_04 = @cant_04 * @precio_unit
		SET @mnto_05 = @cant_05 * @precio_unit
		SET @mnto_06 = @cant_06 * @precio_unit
		SET @mnto_07 = @cant_07 * @precio_unit
		SET @mnto_08 = @cant_08 * @precio_unit
		SET @mnto_09 = @cant_09 * @precio_unit
		SET @mnto_10 = @cant_10 * @precio_unit
		SET @mnto_11 = @cant_11 * @precio_unit
		SET @mnto_12 = @cant_12 * @precio_unit
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_02 = @cant_02 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_03 = @cant_03 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_04 = @cant_04 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_05 = @cant_05 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_06 = @cant_06 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_07 = @cant_07 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_08 = @cant_08 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_09 = @cant_09 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_10 = @cant_10 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_11 = @cant_11 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_12 = @cant_12 * @precio_unit * 100 / (100 + @tasa_impto)
	END
END
ELSE
BEGIN
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 
		SET @mnto_02 = @cant_02 
		SET @mnto_03 = @cant_03 
		SET @mnto_04 = @cant_04 
		SET @mnto_05 = @cant_05 
		SET @mnto_06 = @cant_06 
		SET @mnto_07 = @cant_07 
		SET @mnto_08 = @cant_08 
		SET @mnto_09 = @cant_09 
		SET @mnto_10 = @cant_10 
		SET @mnto_11 = @cant_11 
		SET @mnto_12 = @cant_12 
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * (100 - @tasa_impto) / 100
		SET @mnto_02 = @cant_02 * (100 - @tasa_impto) / 100
		SET @mnto_03 = @cant_03 * (100 - @tasa_impto) / 100
		SET @mnto_04 = @cant_04 * (100 - @tasa_impto) / 100
		SET @mnto_05 = @cant_05 * (100 - @tasa_impto) / 100
		SET @mnto_06 = @cant_06 * (100 - @tasa_impto) / 100
		SET @mnto_07 = @cant_07 * (100 - @tasa_impto) / 100
		SET @mnto_08 = @cant_08 * (100 - @tasa_impto) / 100
		SET @mnto_09 = @cant_09 * (100 - @tasa_impto) / 100
		SET @mnto_10 = @cant_10 * (100 - @tasa_impto) / 100
		SET @mnto_11 = @cant_11 * (100 - @tasa_impto) / 100
		SET @mnto_12 = @cant_12 * (100 - @tasa_impto) / 100
	END

END 

SET @mnto_total = @mnto_01 + @mnto_02 + @mnto_03 + @mnto_04 + @mnto_05 + @mnto_06 + @mnto_07 + @mnto_08 + @mnto_09 + @mnto_10 + @mnto_11 + @mnto_12
IF @tipo_impto <> '0'
	IF @tipo_bien = 'B'
		SET @valor_impto = (@cant_total * @precio_unit) - @mnto_total 
	ELSE
		SET @valor_impto = @cant_total  - @mnto_total 
ELSE
	SET @valor_impto = 0


SELECT 
	@mnto_anterior = mnto_total
FROM SIG_DETALLE_CUADRO_ANUAL
WHERE 
	ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND centro_costo = @centro_costo
	AND tipo_tarea = @tipo_tarea AND nivel_tarea = @nivel_tarea AND codigo_tarea = @codigo_tarea
	AND secuencia = @secuencia AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
	AND clasificador = @clasificador AND fase_cuadro = @fase_cuadro AND item_sec = @item_sec

BEGIN TRAN
PRINT '@flag_techo_cn'
PRINT @flag_techo_cn
IF @flag_techo_cn = 0
BEGIN
	PRINT 'INGRESO DETALLE CUADRO ANUAL'
	UPDATE SIG_DETALLE_CUADRO_ANUAL 
	SET
	cant_01=@cant_01 ,  cant_02 =@cant_02 ,  cant_03 =@cant_03, 
	cant_04 =@cant_04 ,  cant_05 =@cant_05 ,  cant_06 =@cant_06, 
	cant_07 =@cant_07 ,  cant_08 =@cant_08 ,  cant_09 =@cant_09, 
	cant_10 =@cant_10 ,  cant_11 =@cant_11 ,  cant_12 =@cant_12, 
	cant_total =@cant_total, 
	mnto_01 =@mnto_01 ,  mnto_02 =@mnto_02 ,  mnto_03 =@mnto_03, 
	mnto_04 =@mnto_04 ,  mnto_05 =@mnto_05 ,  mnto_06 =@mnto_06, 
	
	mnto_07 =@mnto_07 ,  mnto_08 =@mnto_08 ,  mnto_09 =@mnto_09, 
	mnto_10  =@mnto_10 ,  mnto_11 =@mnto_11 ,  mnto_12 =@mnto_12, 
	mnto_total =@mnto_total , valor_impto = @valor_impto
	WHERE 
	sec_ejec = @sec_ejec AND centro_costo = @centro_costo AND ano_eje = @ano_eje
	AND tipo_tarea = @tipo_tarea AND nivel_tarea = @nivel_tarea AND codigo_tarea = @codigo_tarea
	AND secuencia = @secuencia AND fase_cuadro = @fase_cuadro AND item_sec = @item_sec

	SELECT @lTotalTP = COUNT(*) FROM SIG_TECHO_PRESUPUESTAL
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND centro_costo = @centro_costo AND origen = 1 
	AND fuente_financ = @fuente_financ AND clasificador = @clasificador AND sec_func = @meta 
	AND INDICADOR = '5'

	IF @lTotalTP = 0
	BEGIN
		SELECT @SECUENCIA2 = MAX(SECUENCIA) FROM SIG_TECHO_PRESUPUESTAL

		if @mnto_total  is null set @mnto_total  = 0
		if @mnto_asig  is null set @mnto_asig  = 0
		if @mnto_aprob  is null set @mnto_aprob  = 0
		if @mnto_modif  is null set @mnto_modif  = 0
		INSERT INTO SIG_TECHO_PRESUPUESTAL (
		ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto, clasificador, 
		funcion, programa, sec_func, centro_costo, porc_techo, 
		ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
		mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, paac_inicial, paac_modif, porc_asig
		) VALUES (
		@ano_eje, @sec_ejec, 1, @fuente_financ, @SECUENCIA2, @categ_gasto, @grupo_gasto, @clasificador, 
		@funcion, @programa, @meta, @centro_costo, 0, 
		0, 0, 0, 0, 
		@mnto_total, @mnto_asig, @mnto_aprob, @mnto_modif, 5, 0, 0, 0
		)	
	END
	ELSE
		BEGIN

		SELECT @mnto_total = SUM(mnto_total)  
		FROM SIG_DETALLE_CUADRO_ANUAL A INNER JOIN SIG_CUADRO_ANUAL B
		ON A.ANO_EJE = B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC 
		AND A.CENTRO_COSTO = B.CENTRO_COSTO AND A.TIPO_TAREA = B.TIPO_TAREA 
		AND A.NIVEL_TAREA = B.NIVEL_TAREA AND A.CODIGO_TAREA = B.CODIGO_TAREA
		AND A. SECUENCIA = B.SECUENCIA
		WHERE 
		A.ano_eje = @ano_eje AND A.sec_ejec = @sec_ejec AND B.origen=1 
		AND B.fuente_financ = @fuente_financ AND A.categ_gasto = @categ_gasto 
		AND A.grupo_gasto = @grupo_gasto
		AND A.clasificador = @clasificador AND B.sec_func = @meta 
		AND A.centro_costo = @centro_costo AND A.FASE_CUADRO = @fase_cuadro

		if @mnto_total  is null set @mnto_total  = 0
		IF @fase_cuadro = 1
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_progra = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 2
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_asig = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 3
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_aprob = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5



/*
		IF @fase_cuadro = 1
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_progra = mnto_progra + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 2
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_asig = mnto_asig + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 3
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_aprob = mnto_aprob + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
*/
		END
	IF @@ERROR <> 0
	   GOTO ERROR
	
END
ELSE
BEGIN 
SELECT @ppto_controltecho = CASE @fase_cuadro
	WHEN '1' THEN PPTO_PROGRA
	WHEN '2' THEN PPTO_ASIGNADO
	WHEN '3' THEN PPTO_APROB
	END, 
	@mnto_controltecho = CASE @fase_cuadro
	WHEN '1' THEN MNTO_PROGRA
	WHEN '2' THEN MNTO_ASIG
	WHEN '3' THEN MNTO_APROB
	END
FROM SIG_TECHO_PRESUPUESTAL 
WHERE ANO_EJE = @ano_eje AND SEC_EJEC = @sec_ejec
AND CENTRO_COSTO = @centro_costo AND FUENTE_FINANC = @fuente_financ
AND ORIGEN = 1 AND CATEG_GASTO = @categ_gasto
AND GRUPO_GASTO = @grupo_gasto AND CLASIFICADOR = @clasificador
AND INDICADOR = '5' AND sec_func = @meta

PRINT 'CON CONTROL DE TECHO'
PRINT @ppto_controltecho
PRINT @mnto_controltecho
PRINT @mnto_total
IF @ppto_controltecho >= @mnto_controltecho + @mnto_total - @mnto_anterior
	UPDATE SIG_DETALLE_CUADRO_ANUAL 
	SET
	cant_01=@cant_01 ,  cant_02 =@cant_02 ,  cant_03 =@cant_03, 
	cant_04 =@cant_04 ,  cant_05 =@cant_05 ,  cant_06 =@cant_06, 
	cant_07 =@cant_07 ,  cant_08 =@cant_08 ,  cant_09 =@cant_09, 
	cant_10 =@cant_10 ,  cant_11 =@cant_11 ,  cant_12 =@cant_12, 
	cant_total =@cant_total, 
	mnto_01 =@mnto_01 ,  mnto_02 =@mnto_02 ,  mnto_03 =@mnto_03, 
	mnto_04 =@mnto_01 ,  mnto_05 =@mnto_05 ,  mnto_06 =@mnto_06, 
	
	mnto_07 =@mnto_07 ,  mnto_08 =@mnto_08 ,  mnto_09 =@mnto_09, 
	mnto_10  =@mnto_10 ,  mnto_11 =@mnto_11 ,  mnto_12 =@mnto_12, 
	mnto_total =@mnto_total , valor_impto = @valor_impto, cuser_id = @cuser_id
	WHERE 
	sec_ejec = @sec_ejec AND centro_costo = @centro_costo AND ano_eje = @ano_eje
	AND tipo_tarea = @tipo_tarea AND nivel_tarea = @nivel_tarea AND codigo_tarea = @codigo_tarea
	AND secuencia = @secuencia AND fase_cuadro = @fase_cuadro AND item_sec = @item_sec

	IF @lTotalTP = 0
	BEGIN

		if @mnto_total  is null set @mnto_total  = 0
		if @mnto_asig  is null set @mnto_asig  = 0
		if @mnto_aprob  is null set @mnto_aprob  = 0
		if @mnto_modif  is null set @mnto_modif  = 0

		SELECT @SECUENCIA2 = MAX(SECUENCIA) FROM SIG_TECHO_PRESUPUESTAL
		INSERT INTO SIG_TECHO_PRESUPUESTAL (
		ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto, clasificador, 
		funcion, programa, sec_func, centro_costo, porc_techo, 
		ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
		mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, paac_inicial, paac_modif, porc_asig
		) VALUES (
		@ano_eje, @sec_ejec, 1, @fuente_financ, @SECUENCIA2, @categ_gasto, @grupo_gasto, @clasificador, 
		@funcion, @programa, @meta, @centro_costo, 0, 
		0, 0, 0, 0, 
		@mnto_total, @mnto_asig, @mnto_aprob, @mnto_modif, 5, 0, 0, 0
		)	
	END
	ELSE
		BEGIN

		SELECT @mnto_total = SUM(mnto_total)  
		FROM SIG_DETALLE_CUADRO_ANUAL A INNER JOIN SIG_CUADRO_ANUAL B
		ON A.ANO_EJE = B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC 
		AND A.CENTRO_COSTO = B.CENTRO_COSTO AND A.TIPO_TAREA = B.TIPO_TAREA 
		AND A.NIVEL_TAREA = B.NIVEL_TAREA AND A.CODIGO_TAREA = B.CODIGO_TAREA
		AND A. SECUENCIA = B.SECUENCIA
		WHERE 
		A.ano_eje = @ano_eje AND A.sec_ejec = @sec_ejec AND B.origen=1 
		AND B.fuente_financ = @fuente_financ AND A.categ_gasto = @categ_gasto 
		AND A.grupo_gasto = @grupo_gasto
		AND A.clasificador = @clasificador AND B.sec_func = @meta 
		AND A.centro_costo = @centro_costo AND A.FASE_CUADRO = @fase_cuadro

		if @mnto_total  is null set @mnto_total  = 0
		IF @fase_cuadro = 1
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_progra = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 2
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_asig = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 3
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_aprob = @mnto_total 
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5


/*
		IF @fase_cuadro = 1
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_progra = mnto_progra + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 2
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_asig = mnto_asig + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
		IF @fase_cuadro = 3
			UPDATE SIG_TECHO_PRESUPUESTAL
				SET mnto_aprob = mnto_aprob + @mnto_total - @mnto_anterior
			WHERE 
			ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND origen=1 AND fuente_financ = @fuente_financ
			AND categ_gasto = @categ_gasto AND grupo_gasto = @grupo_gasto
			AND clasificador = @clasificador AND sec_func = @meta AND centro_costo = @centro_costo
			AND indicador = 5
*/

		END
	
	IF @@ERROR <> 0
	   GOTO ERROR

ELSE 
	SET @resultado = 'SOBRE PASA EL TECHO'
END
PRINT @resultado
SET @respuesta = @resultado

COMMIT TRAN
RETURN 0

ERROR:
   ROLLBACK TRAN
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_PRECIOS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_PRECIOS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_PRECIOS]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_PRECIOS]
AS
BEGIN  
insert into TA_PRECIOS
		(ANO_ORDEN,			UE_SEC_EJEC,	                UE_NOMBRE,			TIPO_BIEN,
		ITEM_CATALOGO,		                D_ITEM_CATALOGO,              CANTIDAD_ITEM_BS,	                PRECIO_UNITARIO,
		PRECIO_TOTAL,		                ESPECIFICACIONES,                NRO_ORDEN,			FECHA_ORDEN,
		CONCEPTO_ORDEN,		RUC_PROVEEDOR,		D_PROVEEDOR,		                CLASIFICADOR,
		FUENTE_FINANCIAMIENTO)

SELECT DISTINCT 
             O.ano_eje AS ANO_ORDEN, 
             O.sec_ejec AS UE_SEC_EJEC, 
             '' AS UE_NOMBRE, 
             O.tipo_bien, 
             OD.item_catalogo, 
             OD.d_item_catalogo, 
             OD.cantidad_item_bs, 
            CASE WHEN OD.CANTIDAD_ITEM_BS > 0 
            THEN CASE WHEN abs(OD.PRECIO_UNITARIO - OD.PRECIO_TOTAL / OD.CANTIDAD_ITEM_BS) < 1 
                      THEN OD.PRECIO_UNITARIO 
                      ELSE CASE WHEN abs(OD.PRECIO_UNITARIO - (OD.PRECIO_TOTAL / OD.CANTIDAD_ITEM_BS) * 10) < 1 
                                THEN OD.PRECIO_UNITARIO / 10 
                                ELSE OD.PRECIO_UNITARIO 
                           END 
                 END 
            ELSE OD.PRECIO_UNITARIO 
       END AS PRECIO_UNITARIO, 
       OD.precio_total, 
       OD.especificaciones_item_bs AS ESPECIFICACIONES, 
       O.nro_orden, 
       O.fecha_orden, 
       O.concepto_orden, 
       O.proveedor_nro_ruc AS RUC_PROVEEDOR, 
       O.d_proveedor, 
       OD.clasificador, 
       OD.fuente_financiamiento
		FROM   dbo.si_orden_trx O INNER 
		JOIN   dbo.si_orden_deta_trx OD ON 
				O.ano_eje = OD.ano_eje AND 
				O.sec_ejec = OD.sec_ejec AND 
				O.id_si_orden = OD.id_si_orden 
        
         UPDATE TA_PRECIOS SET UE_NOMBRE = (select nombre from EJECUTORA where sec_ejec = TA_PRECIOS.UE_SEC_EJEC)
END
GO


-- ----------------------------
-- procedure structure for SP_PRG_GENERA_TABLA_FINAL_2
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PRG_GENERA_TABLA_FINAL_2]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PRG_GENERA_TABLA_FINAL_2]
GO

CREATE PROCEDURE [dbo].[SP_PRG_GENERA_TABLA_FINAL_2]
    @ano_eje  			numeric(4,0), 
    @sec_ejec 			numeric(5,0), 
    @nro_fase 			numeric(1,0),
    @fecha_carga_inicio 	varchar(10),
    @fecha_carga_fin  		varchar(10),
    @usuario_n          	varchar(30)
AS
   DECLARE @fecha_carga_inicio_1         DATETIME
   DECLARE @fecha_carga_fin_1            DATETIME  
BEGIN
    declare @tipo_plant 	  numeric(1,0)
    declare @max_sec    	  numeric(10,0)
    declare @estrategia_nacional  varchar(4)
    declare @funcion       	  varchar(2)
    declare @programa      	  varchar(3)
    declare @sub_programa  	  varchar(4)
    declare @act_proy      	  varchar(7)
    declare @componente    	  varchar(7)
    declare @finalidad     	  varchar(5)
    declare @sec_func      	  numeric(5,0)
    declare @tipo_bien     	  varchar(1)
    declare @grupo_bien    varchar(2)
    declare @clase_bien    varchar(2)
    declare @familia_bien  varchar(4)
    declare @item_bien     varchar(4)
    declare @unidad_medida numeric(5,0)
    declare @precio_unit   numeric(16,6)
    declare @origen        varchar(1)
    declare @fuente_financ varchar(2)
    declare @clasificador  varchar(20)
    declare @cantidad      numeric(10,0)
    declare @monto         numeric(12,2)    
    declare @d_item_bien   varchar(100)
    declare @d_uni_medida  varchar(100)
    set @tipo_plant = 1

    TRUNCATE TABLE SI_PRG_META_EJECUTORA

    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
    
    DECLARE cursor_metas CURSOR FOR 

	       SELECT ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, SUB_PROGRAMA, 
               ACT_PROY, COMPONENTE, FINALIDAD, SEC_FUNC
	       FROM META 
               WHERE SEC_EJEC = @sec_ejec
               and ANO_EJE = @ano_eje
               and FLAG_ESTRATEGIA = 'S'
               and @nro_fase = 3
               UNION
               SELECT ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, SUB_PROGRAMA, 
               ACT_PROY, COMPONENTE, FINALIDAD, SEC_FUNC_PROP
               FROM SIG_META_PROPUESTA  
	       WHERE SEC_EJEC = @sec_ejec
               and ANO_EJE = @ano_eje
               and FLAG_ESTRATEGIA = 'S'
               and @nro_fase < 3
    
    OPEN cursor_metas
    FETCH NEXT FROM cursor_metas 
    INTO @estrategia_nacional, 		@funcion, 
	 @programa,   @sub_programa, 	@act_proy, 
	 @componente, @finalidad, 	@sec_func
    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE cursor_items CURSOR FOR 
            SELECT det.TIPO_BIEN     ,
                   det.GRUPO_BIEN    ,
                   det.CLASE_BIEN    ,
                   det.FAMILIA_BIEN  ,
                   det.ITEM_BIEN     ,
                   det.PRECIO_UNIT   ,
                   det.UNIDAD_MEDIDA ,
                   uni.nombre        ,
                   cab.clasificador  ,
                   cab.ORIGEN        ,
                   cab.FUENTE_FINANC ,
                   sum(det.CANT_TOTAL) as cantidad,
                   sum(det.MNTO_TOTAL) as monto
             FROM SIG_CUADRO_NECESIDAD cab,   
                  SIG_CUADRO_NECESIDAD_DET det,
                  UNIDAD_MEDIDA uni
            WHERE det.ANO_EJE       = cab.ANO_EJE
              and det.SEC_EJEC      = cab.SEC_EJEC
              and det.CENTRO_COSTO  = cab.CENTRO_COSTO
              and det.SECUENCIA     = cab.SECUENCIA
              and det.FASE_CUADRO   = cab.FASE_CUADRO
              and det.UNIDAD_MEDIDA = uni.UNIDAD_MEDIDA 
              and cab.ANO_EJE       = @ano_eje
              and cab.SEC_EJEC      = @sec_ejec
              and cab.FASE_CUADRO   = @nro_fase
              and cab.SEC_FUNC_PROP = @sec_func
              and @nro_fase          < 3
         GROUP BY det.TIPO_BIEN     ,
                  det.GRUPO_BIEN    ,
                  det.CLASE_BIEN    ,
                  det.FAMILIA_BIEN  ,
                  det.ITEM_BIEN     ,
                  det.PRECIO_UNIT   ,
                  det.UNIDAD_MEDIDA ,
                  uni.nombre        ,
                  cab.clasificador  ,
                  cab.ORIGEN        ,
                  cab.FUENTE_FINANC 
        union
            SELECT det.TIPO_BIEN     ,
                   det.GRUPO_BIEN    ,
                   det.CLASE_BIEN    ,
                   det.FAMILIA_BIEN  ,
                   det.ITEM_BIEN     ,
                   det.PRECIO_UNIT   ,
                   det.UNIDAD_MEDIDA ,
                   uni.nombre        ,
                   cab.clasificador  ,
                   cab.ORIGEN        ,
                   cab.FUENTE_FINANC ,
                   sum(det.CANT_TOTAL) as cantidad,
                   sum(det.MNTO_TOTAL) as monto
             FROM SIG_CUADRO_NECESIDAD cab,   
                  SIG_CUADRO_NECESIDAD_DET det,
                  UNIDAD_MEDIDA uni
            WHERE det.ANO_EJE       = cab.ANO_EJE
              and det.SEC_EJEC      = cab.SEC_EJEC
              and det.CENTRO_COSTO  = cab.CENTRO_COSTO
              and det.SECUENCIA     = cab.SECUENCIA
              and det.FASE_CUADRO   = cab.FASE_CUADRO
              and det.UNIDAD_MEDIDA = uni.UNIDAD_MEDIDA 
              and cab.ANO_EJE       = @ano_eje
              and cab.SEC_EJEC      = @sec_ejec
              and cab.FASE_CUADRO   = @nro_fase
              and cab.SEC_FUNC      = @sec_func
              and @nro_fase         = 3
         GROUP BY det.TIPO_BIEN     ,
                  det.GRUPO_BIEN    ,
                  det.CLASE_BIEN    ,
                  det.FAMILIA_BIEN  ,
                  det.ITEM_BIEN     ,
                  det.PRECIO_UNIT   ,
                  det.UNIDAD_MEDIDA ,
                  uni.nombre        ,
                  cab.clasificador  ,
                  cab.ORIGEN        ,
                  cab.FUENTE_FINANC 
    
        OPEN cursor_items
    
        FETCH NEXT FROM cursor_items
        INTO @tipo_bien, 	@grupo_bien, 	@clase_bien, 
	     @familia_bien, 	@item_bien, 	@precio_unit, 
	     @unidad_medida, 	@d_uni_medida,  @clasificador, 
	     @origen, 		@fuente_financ, @cantidad, 
	     @monto
    
        WHILE @@FETCH_STATUS = 0
        BEGIN
    
            Select @d_item_bien = NOMBRE_ITEM
            FROM CATALOGO_BIEN_SERV_ORIGINAL
            where TIPO_BIEN    = @tipo_bien
              and GRUPO_BIEN   = @grupo_bien
              and CLASE_BIEN   = @clase_bien
              and FAMILIA_BIEN = @familia_bien
              and ITEM_BIEN    = @item_bien

            Select @max_sec = max(SECUENCIA)
            from SI_PRG_META_EJECUTORA
            where ANO_EJE  = @ano_eje
              and SEC_EJEC = @sec_ejec
              and SEC_FUNC = @sec_func
              and NRO_FASE = @nro_fase
              and TIPO_PLANTILLA = 1

            if @max_sec Is Null SET @max_sec = 0            
            SET @max_sec = @max_sec + 1

            INSERT INTO SI_PRG_META_EJECUTORA
            (ANO_EJE, TIPO_PLANTILLA, NRO_FASE, 
	     SEC_FUNC, SEC_EJEC, SECUENCIA,
             TIPO_BIEN, GRUPO_BIEN, CLASE_BIEN, 
	     FAMILIA_BIEN, ITEM_BIEN, D_ITEM_BIEN,
             ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, 
	     SUB_PROGRAMA, ACT_PROY, COMPONENTE, 
	     FINALIDAD, PRECIO_REF, UNIDAD_MEDIDA, 
	     D_UNIDAD_MEDIDA, CANT_COMPRA, PREC_COMPRA, 
	     CLASIFICADOR, FUENTE_FINANC, ORIGEN_FUENTE, 
	     PROGRAMA_INSTITUCIONAL, FECHA_CARGA_INICIO, 
	     FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
            values
            (@ano_eje, @tipo_plant, @nro_fase, 
	     @sec_func, @sec_ejec, @max_sec, 
             @tipo_bien, @grupo_bien, @clase_bien, 
	     @familia_bien, @item_bien, @d_item_bien,
             @estrategia_nacional, @funcion, @programa, 
	     @sub_programa, @act_proy, @componente, @finalidad,
             @precio_unit, @unidad_medida, @d_uni_medida, 
	     @cantidad, @monto, @clasificador, @fuente_financ, 
	     @origen, @estrategia_nacional, @fecha_carga_inicio_1, 
	     @fecha_carga_fin_1, getdate(), @usuario_n)
	     
	     FETCH NEXT FROM cursor_items
             INTO @tipo_bien, 	  @grupo_bien,     @clase_bien, 
		  @familia_bien,  @item_bien,      @precio_unit, 
		  @unidad_medida, @d_uni_medida,   @clasificador, 
		  @origen, 	  @fuente_financ,  @cantidad, @monto
        END        
        CLOSE cursor_items
        DEALLOCATE cursor_items

        FETCH NEXT FROM cursor_metas 
        INTO @estrategia_nacional, 	@funcion, 	@programa, 
	     @sub_programa, 		@act_proy, 	@componente, 
	     @finalidad, 		@sec_func
    END   
    CLOSE cursor_metas
    DEALLOCATE cursor_metas
end
GO


-- ----------------------------
-- function structure for SF_FASE_ACTIVA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_FASE_ACTIVA]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_FASE_ACTIVA]
GO

CREATE FUNCTION [dbo].[SF_FASE_ACTIVA] 
(@vgi_ano_cn  decimal(6,0),
 @vgi_sec_eje decimal(6,0)
)
returns integer
AS
begin
	DECLARE  @li_fase_cuadro INTEGER
	DECLARE  @ll_estado_cn_1 INTEGER
	DECLARE  @ai_ano_eje INTEGER

	SET @li_fase_cuadro = 0

	select @ll_estado_cn_1 = count(*)
	from sig_cuadro_x_centro
	where ANO_EJE  = @vgi_ano_cn
	  and SEC_EJEC = @vgi_sec_eje
	  and estado   = '0'

	if @ll_estado_cn_1 is null 
		SET @ll_estado_cn_1 = 0

	if @ll_estado_cn_1 > 0 
		SET @li_fase_cuadro = 1

	select @ll_estado_cn_1 = count(*) 
	from sig_cuadro_x_centro
	where ANO_EJE  = @vgi_ano_cn 
	  and SEC_EJEC = @vgi_sec_eje
	  and estado = '7'

	if @ll_estado_cn_1 is null
		set @ll_estado_cn_1 = 0

	if @ll_estado_cn_1 > 0 
		set @li_fase_cuadro = 1

	if	@li_fase_cuadro = 0 
	begin
		select @ll_estado_cn_1 = count(*) 
		from sig_cuadro_x_centro
		where ANO_EJE  = @vgi_ano_cn 
		  and SEC_EJEC = @vgi_sec_eje
		  and estado = '1'
		
		if @ll_estado_cn_1 is null
			set @ll_estado_cn_1 = 0
		
		if @ll_estado_cn_1 > 0 
			set @li_fase_cuadro = 2
		
		select @ll_estado_cn_1 = count(*)
		from sig_cuadro_x_centro
		where ANO_EJE  = @vgi_ano_cn 
		  and SEC_EJEC = @vgi_sec_eje 
		  and estado = '3'
		
		if @ll_estado_cn_1 is null
			set @ll_estado_cn_1 = 0
		
		if @ll_estado_cn_1 > 0 
			set @li_fase_cuadro = 2
	end

	if	@li_fase_cuadro = 0 
	begin
		select @ll_estado_cn_1 = count(*) 
		from sig_cuadro_x_centro
		where ANO_EJE  = @vgi_ano_cn 
		  and SEC_EJEC = @vgi_sec_eje 
		  and estado = '4'

		if @ll_estado_cn_1 is null
			set @ll_estado_cn_1 = 0
		
		if @ll_estado_cn_1 > 0 
			set @li_fase_cuadro = 3
		
		select @ll_estado_cn_1 = count(*)
		from sig_cuadro_x_centro
		where ANO_EJE  = @vgi_ano_cn 
		  and SEC_EJEC = @vgi_sec_eje
		  and estado in ('5','6')

		if @ll_estado_cn_1 is null 
			set @ll_estado_cn_1 = 0
		
		if @ll_estado_cn_1 > 0 
			set @li_fase_cuadro = 3
	end

	Return @li_fase_cuadro
end
GO


-- ----------------------------
-- procedure structure for SP_CARGA_PAAC_MENSUAL_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_PAAC_MENSUAL_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_PAAC_MENSUAL_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_PAAC_MENSUAL_TRX]
   ( @P_ANO_EJE            NUMERIC(4,0),
     @P_SEC_EJEC           NUMERIC(6,0),
     @O_ERR_NUM        NUMERIC(6,0)   OUTPUT,
     @O_ERR_MSG         VARCHAR(255) OUTPUT )
AS   
DECLARE @LS_TIPO_CONSOLID    VARCHAR(1)
DECLARE @LN_NRO_CONSOLID     NUMERIC(5,0)
DECLARE @LN_TIPO_GENERACION VARCHAR(1)
DECLARE @LN_MES_INICIAL      NUMERIC(2,0)
DECLARE @LN_MES_FINAL        NUMERIC(2,0)
DECLARE @LN_MES_PROPUESTO    NUMERIC(2,0)
DECLARE @LS_TIPO_PROCESO    VARCHAR(2)
DECLARE @LS_OBJETO          VARCHAR(2)
DECLARE @LS_TIPO_CIIU       VARCHAR(1)
DECLARE @LS_GRUPO_CIIU      VARCHAR(2)
DECLARE @LS_CATEGORIA_CIIU  VARCHAR(3)
DECLARE @LS_PAIS            VARCHAR(4)
DECLARE @LS_DEPARTAMENTO    VARCHAR(2)
DECLARE @LS_PROVINCIA       VARCHAR(2)
DECLARE @LS_DISTRITO        VARCHAR(2)
DECLARE @LN_VALOR_MONEDA     NUMERIC(16,2)
DECLARE @LN_VALOR_PLAN        NUMERIC(16,2)
DECLARE @LS_ORGANO_CONVOCACION VARCHAR(60)
DECLARE @LS_TIPO_BIEN          VARCHAR(1)
DECLARE @LS_GRUPO_BIEN        VARCHAR(2)
DECLARE @LS_CLASE_BIEN         VARCHAR(2)
DECLARE @LS_FAMILIA_BIEN       VARCHAR(4)
DECLARE @LS_ITEM_BIEN         VARCHAR(4)
DECLARE @LN_UNIDAD_MEDIDA     NUMERIC(3,0)
DECLARE @LN_CANTIDAD          NUMERIC(20,6) 
DECLARE @LN_PRECIO_UNIT       NUMERIC(16,6)   
DECLARE @LS_FUENTE_FINANC    VARCHAR(2)      
DECLARE @LS_FTE_FTO_IMPTO     VARCHAR(2)
DECLARE @LS_CLASIFICADOR      VARCHAR (20)
DECLARE @LS_TIPO_IMPTO         VARCHAR (1)
DECLARE @LS_MONEDA            VARCHAR (6)
DECLARE @LN_TIPO_CAMBIO       NUMERIC (10,6)
DECLARE @LN_SECUENCIA          NUMERIC (10,0)
DECLARE @LS_SECTOR             VARCHAR(2)
DECLARE @LS_PLIEGO             VARCHAR(3)        
DECLARE @LS_CATEGORIA      VARCHAR(3)
DECLARE @LS_GRUPO          VARCHAR(3)
DECLARE @LS_MODALIDAD      VARCHAR(5)
DECLARE @LS_ELEMENTO_GASTO VARCHAR(5)
DECLARE @LL_INICIO INTEGER
DECLARE @LL_LONG   INTEGER     
DECLARE @CATEG_GASTO2		 VARCHAR(3)
DECLARE @MODALIDAD_GASTO2    VARCHAR(5)      
  
BEGIN
    DELETE FROM dbo.SGE_PAAC_MENSUAL_TRX

    SELECT @LN_SECUENCIA = MAX(secuencia)
           FROM SGE_PAAC_MENSUAL_TRX
     WHERE ANO_EJE  = @P_ANO_EJE  AND
           SEC_EJEC = @P_SEC_EJEC 

	IF @LN_SECUENCIA IS NULL   
		SET @LN_SECUENCIA = 0   
		
    DECLARE C1 CURSOR  FOR
      
            SELECT 
                A.TIPO_CONSOLID,
                A.NRO_CONSOLID,
                A.TIPO_GENERACION,
                A.MES_INICIAL,
                A.MES_FINAL,
                A.MES_PROPUESTO,
                A.TIPO_PROCESO,
                A.OBJETO,
                A.TIPO_CIIU,
                A.GRUPO_CIIU,
                A.CATEGORIA_CIIU,
                A.PAIS,
                A.DEPARTAMENTO,
                A.PROVINCIA,
                A.DISTRITO,
                C.VALOR_MONEDA,
                C.VALOR_MONEDA VALOR_PLAN,
                A.ORGANO_CONVOCACION,
                C.TIPO_BIEN,
                C.GRUPO_BIEN,
                C.CLASE_BIEN,
                C.FAMILIA_BIEN,
                C.ITEM_BIEN,
                C.UNIDAD_MEDIDA,
                C.CANTIDAD,
                C.PRECIO_UNIT,
                (    SELECT MAX(SIG_PAAC_METAS.FUENTE_FINANC)
                    FROM SIG_PAAC_METAS
                    WHERE SIG_PAAC_METAS.ANO_EJE            = C.ANO_EJE
                        AND SIG_PAAC_METAS.sec_ejec            = C.SEC_EJEC
                        AND SIG_PAAC_METAS.TIPO_CONSOLID    = C.TIPO_CONSOLID
                        AND SIG_PAAC_METAS.NRO_CONSOLID        = C.NRO_CONSOLID
                        AND SIG_PAAC_METAS.TIPO_GENERACION    = C.TIPO_GENERACION
                        AND SIG_PAAC_METAS.TIPO_BIEN        = C.TIPO_BIEN
                        AND SIG_PAAC_METAS.SEC_CONSOLID        = C.SEC_CONSOLID
                        AND SIG_PAAC_METAS.SEC_RESUMEN        = C.SEC_RESUMEN
                ) FUENTE_FINANC,
                NULL FTE_FTO_IMPTO,
                (    SELECT MAX(SIG_PAAC_METAS.CLASIFICADOR)
                    FROM SIG_PAAC_METAS
                    WHERE SIG_PAAC_METAS.ANO_EJE            = C.ANO_EJE
                        AND SIG_PAAC_METAS.sec_ejec            = C.SEC_EJEC
                        AND SIG_PAAC_METAS.TIPO_CONSOLID    = C.TIPO_CONSOLID
                        AND SIG_PAAC_METAS.NRO_CONSOLID        = C.NRO_CONSOLID
                        AND SIG_PAAC_METAS.TIPO_GENERACION    = C.TIPO_GENERACION
                        AND SIG_PAAC_METAS.TIPO_BIEN        = C.TIPO_BIEN
                        AND SIG_PAAC_METAS.SEC_CONSOLID        = C.SEC_CONSOLID
                        AND SIG_PAAC_METAS.SEC_RESUMEN        = C.SEC_RESUMEN
                ) CLASIFICADOR,
                '0' TIPO_IMPTO,
                C.MONEDA,
                C.TIPO_CAMBIO,
                D.sector,
                D.pliego,
                NULL CATEG_GASTO2,
                NULL MODALIDAD_GASTO2
            FROM SIG_PAAC_CONSOLIDADO A
            JOIN SIG_PAAC_SECUENCIA B
                ON  B.ANO_EJE            = A.ANO_EJE
                AND B.SEC_EJEC            = A.SEC_EJEC
                AND B.TIPO_CONSOLID        = A.TIPO_CONSOLID
                AND B.NRO_CONSOLID        = A.NRO_CONSOLID
                AND B.TIPO_GENERACION    = A.TIPO_GENERACION
                AND B.TIPO_BIEN            = A.TIPO_BIEN
            JOIN SIG_PAAC_ITEM C
                ON  C.ANO_EJE            = B.ANO_EJE
                AND C.SEC_EJEC            = B.SEC_EJEC
                AND C.TIPO_CONSOLID        = B.TIPO_CONSOLID
                AND C.NRO_CONSOLID        = B.NRO_CONSOLID
                AND C.TIPO_GENERACION    = B.TIPO_GENERACION
                AND C.TIPO_BIEN            = B.TIPO_BIEN
                AND C.SEC_CONSOLID        = B.SEC_CONSOLID
            JOIN SIG_EJECUTORA D
                ON  D.sec_ejec = A.SEC_EJEC
                AND D.estado='A'
            WHERE
                A.ANO_EJE  = @P_ANO_EJE AND
                A.SEC_EJEC = @P_SEC_EJEC 
                              
			OPEN C1
				
	  FETCH NEXT FROM C1
	  INTO
          	@LS_TIPO_CONSOLID,	@LN_NRO_CONSOLID ,	@LN_TIPO_GENERACION  ,	@LN_MES_INICIAL,	@LN_MES_FINAL,		@LN_MES_PROPUESTO ,
     		@LS_TIPO_PROCESO ,	@LS_OBJETO,		    @LS_TIPO_CIIU        ,  @LS_GRUPO_CIIU,     @LS_CATEGORIA_CIIU,	@LS_PAIS             ,
      		@LS_DEPARTAMENTO  , @LS_PROVINCIA     , @LS_DISTRITO         ,  @LN_VALOR_MONEDA  , @LN_VALOR_PLAN  ,	@LS_ORGANO_CONVOCACION ,
      		@LS_TIPO_BIEN    ,  @LS_GRUPO_BIEN   ,  @LS_CLASE_BIEN      ,   @LS_FAMILIA_BIEN   ,@LS_ITEM_BIEN,		@LN_UNIDAD_MEDIDA,
      		@LN_CANTIDAD ,      @LN_PRECIO_UNIT ,   @LS_FUENTE_FINANC    ,  @LS_FTE_FTO_IMPTO , @LS_CLASIFICADOR ,  @LS_TIPO_IMPTO      ,
      		@LS_MONEDA, 	    @LN_TIPO_CAMBIO,    @LS_SECTOR    ,			@LS_PLIEGO ,		@CATEG_GASTO2 ,		@MODALIDAD_GASTO2
     
      WHILE @@FETCH_STATUS = 0
        BEGIN
	  
	    SET  @LL_INICIO = 0    
            SET  @LL_LONG = 0 
            SET @LN_SECUENCIA = @LN_SECUENCIA + 1       
            
            SET @LS_CATEGORIA =  SUBSTRING(@LS_CLASIFICADOR, 1  , (CHARINDEX('.',@LS_CLASIFICADOR ,  1) -1))
       
	        SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 
		    SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1)) - (CHARINDEX('.' ,@LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 )  
		    SET @LS_GRUPO  = SUBSTRING( @LS_CLASIFICADOR, @LL_INICIO, @LL_LONG)
		   
		    SET @LL_INICIO = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1
		    SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) - (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) )   + 1)
		    SET @LS_MODALIDAD = SUBSTRING( @LS_CLASIFICADOR,@LL_INICIO, @LL_LONG )
	
		    SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) +1
		    SET @LL_LONG   = LEN(@LS_CLASIFICADOR) -  CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1)  ) 
		    SET @LS_ELEMENTO_GASTO = SUBSTRING(@LS_CLASIFICADOR, @LL_INICIO, @LL_LONG )  
	    
        
            INSERT INTO SGE_PAAC_MENSUAL_TRX
            ( ANO_EJE,               SEC_EJEC,       TIPO_CONSOLID,      NRO_CONSOLID,      TIPO_GENERACION,
              SECUENCIA,             MES_INICIAL,    MES_FINAL,          MES_PROPUESTO,     TIPO_PROCESO,
              OBJETO,                TIPO_CIIU,      GRUPO_CIIU,         CATEGORIA_CIIU,    PAIS,
              DEPARTAMENTO,          PROVINCIA,      DISTRITO,           VALOR_MONEDA,      VALOR_PLAN,
              ORGANO_CONVOCACION,    TIPO_BIEN,      GRUPO_BIEN,         CLASE_BIEN,        FAMILIA_BIEN,
              ITEM_BIEN,             UNIDAD_MEDIDA,  CANTIDAD,           PRECIO_UNIT,       FUENTE_FINANC,
              FTE_FTO_IMPTO,         CLASIFICADOR,   GRUPO_GASTO,        CATEG_GASTO,       ELEMENTO_GASTO,
              MODALIDAD_GASTO,       TIPO_IMPTO,     MONEDA,             TIPO_CAMBIO,       SECTOR,
              PLIEGO,                CATEG_GASTO2,   MODALIDAD_GASTO2    )
            VALUES
            ( @P_ANO_EJE,             @P_SEC_EJEC,              @LS_TIPO_CONSOLID ,    @LN_NRO_CONSOLID   ,     @LN_TIPO_GENERACION  ,
              @LN_SECUENCIA,          @LN_MES_INICIAL ,        @LN_MES_FINAL     ,    @LN_MES_PROPUESTO  ,     @LS_TIPO_PROCESO    ,
              @LS_OBJETO      ,       @LS_TIPO_CIIU   ,         @LS_GRUPO_CIIU    ,    @LS_CATEGORIA_CIIU ,     @LS_PAIS   ,            
              @LS_DEPARTAMENTO   ,    @LS_PROVINCIA   ,         @LS_DISTRITO      ,    @LN_VALOR_MONEDA   ,     @LN_VALOR_PLAN ,    
              @LS_ORGANO_CONVOCACION, @LS_TIPO_BIEN   ,         @LS_GRUPO_BIEN    ,    @LS_CLASE_BIEN     ,     @LS_FAMILIA_BIEN  ,
              @LS_ITEM_BIEN         , @LN_UNIDAD_MEDIDA,         @LN_CANTIDAD      ,   @LN_PRECIO_UNIT    ,     @LS_FUENTE_FINANC ,  
              @LS_FTE_FTO_IMPTO,      @LS_CLASIFICADOR ,        @LS_CATEGORIA     ,    @LS_GRUPO          ,     @LS_MODALIDAD,
              @LS_ELEMENTO_GASTO,     @LS_TIPO_IMPTO   ,        @LS_MONEDA        ,    @LN_TIPO_CAMBIO    ,     @LS_SECTOR  ,
              @LS_PLIEGO  ,           NULL ,                   NULL )
              
           FETCH NEXT FROM C1
	  INTO
          	@LS_TIPO_CONSOLID,	@LN_NRO_CONSOLID ,	@LN_TIPO_GENERACION  ,	@LN_MES_INICIAL,	@LN_MES_FINAL,		@LN_MES_PROPUESTO ,
     		@LS_TIPO_PROCESO ,	@LS_OBJETO,		    @LS_TIPO_CIIU        ,  @LS_GRUPO_CIIU,     @LS_CATEGORIA_CIIU,	@LS_PAIS             ,
      		@LS_DEPARTAMENTO  , @LS_PROVINCIA     , @LS_DISTRITO         ,  @LN_VALOR_MONEDA  , @LN_VALOR_PLAN  ,	@LS_ORGANO_CONVOCACION ,
      		@LS_TIPO_BIEN    ,  @LS_GRUPO_BIEN   ,  @LS_CLASE_BIEN      ,   @LS_FAMILIA_BIEN   ,@LS_ITEM_BIEN,		@LN_UNIDAD_MEDIDA,
      		@LN_CANTIDAD ,      @LN_PRECIO_UNIT ,   @LS_FUENTE_FINANC    ,  @LS_FTE_FTO_IMPTO , @LS_CLASIFICADOR ,  @LS_TIPO_IMPTO      ,
      		@LS_MONEDA, 	    @LN_TIPO_CAMBIO,    @LS_SECTOR    ,			@LS_PLIEGO ,		@CATEG_GASTO2 ,		@MODALIDAD_GASTO2
          
       
    END 
    CLOSE C1
    DEALLOCATE C1   
   
    BEGIN
        UPDATE SGE_PAAC_MENSUAL_TRX
           SET SGE_PAAC_MENSUAL_TRX.SECTOR = (SELECT B.SECTOR FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_PAAC_MENSUAL_TRX.SEC_EJEC),
               SGE_PAAC_MENSUAL_TRX.PLIEGO = (SELECT B.PLIEGO FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_PAAC_MENSUAL_TRX.SEC_EJEC)
         WHERE 
              SGE_PAAC_MENSUAL_TRX.ANO_EJE  = @P_ANO_EJE AND
              SGE_PAAC_MENSUAL_TRX.SEC_EJEC = @P_SEC_EJEC

        IF @@ERROR <> 0
       			 BEGIN
		 		SET @O_ERR_MSG='Ocurrió error en la actualización de SGE_PAAC_MENSUAL_TRX'
				 return -1
	  		END  
           END            
    END
GO


