	@PN_ANIO NUMERIC,  
	@PN_EJECUTORA NUMERIC,  
	@PN_NRO_PAO NUMERIC,  
	@ps_tipo_generacion varchar(1), @PS_TIPO varCHAR(1),  
	@PS_MES_INI INT, @PS_MES_FIN INT, @ps_especif varchar(100),  
	@ps_opcion_pao varchar(1), @ps_tipo_compra varchar(1), @ps_modal_compra varchar(2),  
	@PS_USUARIO VARCHAR(30)  
)  
   
AS  
   
	DECLARE @ls_moneda varchar(5), @ls_pais varchar(4), @ls_depa varchar(2), @ls_prov varchar(2),  
       @ls_dist varchar(2), @ls_estado varchar(1), @ld_tipo_Camb numeric(2),   
       @ldt_fecha_Cons datetime, @ls_equipo varchar(20), @li_secu_cons varchar(2), @ls_tipo_cons char(1),  
       @li_unidad_med_cons int, @ls_tipo_organismo varchar(2) ,
       @li_cont NUMERIC(2) 
      
------ Valores iniciales ------------  
	set nocount on  
	  
	select @ls_moneda      = 'S/.'  
	select @ls_estado      = '0'  
	select @ld_tipo_Camb   =  1   
	select @ls_tipo_cons   = '1'   
	select @li_secu_cons   = '01'  
	select @ldt_fecha_Cons = GETDATE()  
	SELECT @ls_equipo      = ''  
	select @ls_tipo_organismo  = '01'  
	select @li_unidad_med_cons = case when @PS_TIPO = 'B' then 112 else 113 end  
	   
