	      		   where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND centro_costo = D.CENTRO_COSTO  )   AND
	  
	         EXISTS(SELECT '1' FROM tmp_parametros_pao  
	               	 where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO AND  
	                     C.TIPO_USO = TIPO_USO AND  
	                     C.TIPO_TAREA = TIPO_TAREA AND  
	                     C.NIVEL_TAREA = NIVEL_TAREA AND  
	                     C.CODIGO_TAREA = CODIGO_TAREA AND
						 TIPO_USO = C.TIPO_USO ) AND 
	       				( (D.FASE_CUADRO =  3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012) ) and	       
	         (  
		      EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
		      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
			  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
						ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
			  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
						ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
		       ) AND	       
	           
		       ( D.ano_eje    = C.ano_eje ) and  
		       ( D.sec_ejec     = C.sec_ejec ) and  
		       ( D.centro_costo = C.centro_costo ) and  
		       ( D.FASE_CUADRO   = C.FASE_CUADRO ) and   
		       ( D.secuencia    = C.secuencia ) and  
				/*
		       ( D.mnto_total   > 0 ) AND
			   */
			   (COALESCE(D.MNTO_TOTAL, 0) + COALESCE(D.MNTO_TOTAL_ANNO_01, 0) + COALESCE(D.MNTO_TOTAL_ANNO_02, 0) + COALESCE(D.MNTO_TOTAL_ANNO_03, 0)) > 0 and
		       ( D.estado_item_kit = 'A' ) and
		    EXISTS(SELECT '1' FROM TMP_PARAMETROS_PAO AA  
				    WHERE   
				    AA.CODIGO = 1 AND   
				    AA.NRO_PAO = @PN_NRO_PAO AND  
				    AA.CENTRO_COSTO = D.CENTRO_COSTO AND   
				    AA.SECUENCIA_CN = D.SECUENCIA AND  
				    AA.ITEM_SEC_CN = D.ITEM_SEC AND  
				    ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN = AA.ITEM ) )  	  
		GROUP BY C.sec_func ,  
		         C.origen ,  
		         C.fuente_financ ,  
		      	 C.clasificador ,  
		         C.tipo_impuesto ,  
		         C.tasa_impto ,  
		         case when C.fuente_impto is null or RTRIM(LTRIM(C.fuente_impto)) = '' then null else  C.fuente_impto end,  
		         sec_resumen1     
  
	DECLARE @SEC_RESUMEN numeric(5, 0), @SEC_META1 numeric(5, 0), @NUM INT, @SEC_RESUMEN_ANT numeric(5, 0)  
	DECLARE CUR_META CURSOR FOR  
	SELECT SEC_RESUMEN, SEC_META1 FROM #TMP_SIG_PAAC_METAS WHERE SEC_RESUMEN IN (SELECT SEC_RESUMEN FROM #TMP_SIG_PAAC_METAS GROUP BY SEC_RESUMEN HAVING COUNT(*) > 1) ORDER BY SEC_RESUMEN  
	   
	OPEN CUR_META  
	FETCH CUR_META INTO @SEC_RESUMEN, @SEC_META1  
	WHILE @@FETCH_STATUS = 0  
	BEGIN  
	   SELECT @NUM = 1  
	   SELECT @SEC_RESUMEN_ANT = @SEC_RESUMEN  
	   WHILE @@FETCH_STATUS = 0 AND @SEC_RESUMEN_ANT = @SEC_RESUMEN  
	   BEGIN  
	      UPDATE #TMP_SIG_PAAC_METAS SET SEC_META = @NUM WHERE SEC_META1 = @SEC_META1  
	      SELECT @NUM = @NUM + 1  
	      FETCH CUR_META INTO @SEC_RESUMEN, @SEC_META1  
	   END  
	END  
	CLOSE CUR_META  
	DEALLOCATE CUR_META  
	   
	UPDATE #TMP_SIG_PAAC_METAS SET SEC_META = 1 WHERE SEC_META IS NULL  
	   
	---- Centro Costo  
	   
	INSERT INTO #TMP_SIG_PAAC_CENTRO_COSTO  
	 (		ANO_EJE,  		SEC_EJEC, 		 TIPO_CONSOLID,  NRO_CONSOLID,   TIPO_GENERACION,TIPO_BIEN, SEC_CONSOLID,  
	  		SEC_RESUMEN, 	SEC_META,  		 TIPO_TAREA,     CODIGO_TAREA, 	 MES_01,  		 MES_02,   
	     	MES_03,   		MES_04,    		 MES_05,    	 MES_06,   		 MES_07,  		 MES_08,
	  		MES_09,   		MES_10,    	     MES_11,    	 MES_12,   		 CANTIDAD, 		 CANTIDAD_ANNO_01,   
	  		CANTIDAD_ANNO_02,CANTIDAD_ANNO_03, VALOR,  		 VALOR_ANNO_01,  VALOR_ANNO_02,  VALOR_ANNO_03,     
	  		TIPO_IMPTO,  	TASA_IMPTO,   	 FTE_FTO_IMPTO,  VALOR_IMPTO, 	 VALOR_MONEDA,	 VALOR_IMPTO_MONEDA, 
	  		CENTRO_COSTO,   FECHA_REG,		 CUSER_ID,		 NIVEL_TAREA,    TIPO_USO, MAYOR,SUB_CTA_DET, 
	 		MES_01_ANNO_01, MES_02_ANNO_01,  MES_03_ANNO_01, MES_04_ANNO_01, MES_05_ANNO_01, MES_06_ANNO_01,   
	 	    MES_07_ANNO_01, MES_08_ANNO_01,  MES_09_ANNO_01, MES_10_ANNO_01 ,MES_11_ANNO_01, MES_12_ANNO_01,     
	 	    MES_01_ANNO_02, MES_02_ANNO_02 , MES_03_ANNO_02, MES_04_ANNO_02, MES_05_ANNO_02, MES_06_ANNO_02,   
	   	    MES_07_ANNO_02, MES_08_ANNO_02 , MES_09_ANNO_02, MES_10_ANNO_02, MES_11_ANNO_02, MES_12_ANNO_02,    
	 	    MES_01_ANNO_03, MES_02_ANNO_03 , MES_03_ANNO_03, MES_04_ANNO_03, MES_05_ANNO_03, MES_06_ANNO_03,  
	   	    MES_07_ANNO_03, MES_08_ANNO_03 , MES_09_ANNO_03, MES_10_ANNO_03, MES_11_ANNO_03, MES_12_ANNO_03)

	SELECT @PN_ANIO, 
		   @PN_EJECUTORA, 
		   '1', 
		   @PN_NRO_PAO, 
		   @ps_tipo_generacion, 
		   @PS_TIPO, 
		   '1',   
	       I.sec_resumen1, 
	       m.sec_meta, 
	       C.TIPO_TAREA,     
	       C.CODIGO_TAREA,           
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.CANT_01 else 0 END) else 0 end as cant_01,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.CANT_02 else 0 END) else 0 end as cant_02,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.CANT_03 else 0 END) else 0 end as cant_03,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.CANT_04 else 0 END) else 0 end as cant_04,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.CANT_05 else 0 END) else 0 end as cant_05,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.CANT_06 else 0 END) else 0 end as cant_06,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.CANT_07 else 0 END) else 0 end as cant_07,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.CANT_08 else 0 END) else 0 end as cant_08,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.CANT_09 else 0 END) else 0 end as cant_09,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.CANT_10 else 0 END) else 0 end as cant_10,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.CANT_11 else 0 END) else 0 end as cant_11,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.CANT_12 else 0 END) else 0 end as cant_12,
	       
	       sum(case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.CANT_01 ELSE 0 end) else 0 end +    
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.CANT_02 else 0 END) else 0 end +    
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN THEN (CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.CANT_03 else 0 END) else 0 end +    
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.CANT_04 else 0 END) else 0 end +    
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.CANT_05 else 0 END) else 0 end +    
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.CANT_06 else 0 END) else 0 end +    
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.CANT_07 else 0 END) else 0 end +    
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.CANT_08 else 0 END) else 0 end +    
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.CANT_09 else 0 END) else 0 end +    
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.CANT_10 else 0 END) else 0 end +    
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.CANT_11 else 0 END) else 0 end +    
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.CANT_12 else 0 END) else 0 end) - sum(D.STOCK_ASIG) CANTIDAD, 
		   SUM(m.CANTIDAD_ANNO_01) CANTIDAD_ANNO_01,    
		   SUM(m.CANTIDAD_ANNO_02) CANTIDAD_ANNO_02,    
	       SUM(m.CANTIDAD_ANNO_03) CANTIDAD_ANNO_03, 
	           
	       SUM(CASE when 1 = @PS_MES_INI and 12 = @PS_MES_FIN THEN (
	        	CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.mnto_01 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.mnto_02 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.mnto_03 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.mnto_04 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.mnto_05 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.mnto_06 ELSE 0 END +      
	      		CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.mnto_07 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.mnto_08 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.mnto_09 ELSE 0 END +
	   			CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.mnto_10 ELSE 0 END +
	      		CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.mnto_11 ELSE 0 END +
	      	    CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.mnto_12 ELSE 0 END  + D.valor_impto )  
	       else (  
	       case when C.tipo_IMPUESTO = '0' then (   
		       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.mnto_01 ELSE 0 END) else 0 end +  
		       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.mnto_02 ELSE 0 END) else 0 end +  
		       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.mnto_03 ELSE 0 END) else 0 end +  
		       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.mnto_04 ELSE 0 END) else 0 end +  
		       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.mnto_05 ELSE 0 END) else 0 end +  
		       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.mnto_06 ELSE 0 END) else 0 end +  
		       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.mnto_07 ELSE 0 END) else 0 end +  
		       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.mnto_08 ELSE 0 END) else 0 end +  
		       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.mnto_09 ELSE 0 END) else 0 end +  
		       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.mnto_10 ELSE 0 END) else 0 end +  
		       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.mnto_11 ELSE 0 END) else 0 end +  
		       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.mnto_12 ELSE 0 END) else 0 end)              
		   when C.tipo_IMPUESTO = '1' then (  
		       (case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.mnto_01 ELSE 0 END) else 0 end +  
		       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.mnto_02 ELSE 0 END) else 0 end +  
		       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.mnto_03 ELSE 0 END) else 0 end +  
		       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.mnto_04 ELSE 0 END) else 0 end +  
		       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.mnto_05 ELSE 0 END) else 0 end +  
		       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.mnto_06 ELSE 0 END) else 0 end +  
		       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.mnto_07 ELSE 0 END) else 0 end +  
		       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.mnto_08 ELSE 0 END) else 0 end +  
		       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.mnto_09 ELSE 0 END) else 0 end +  
		       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.mnto_10 ELSE 0 END) else 0 end +  
		       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.mnto_11 ELSE 0 END) else 0 end +  
		       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.mnto_12 ELSE 0 END) else 0 end)* (0.01 * C.tasa_impto + 1) )  
		    when C.tipo_IMPUESTO = '2' then (  
		       (case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.mnto_01 ELSE 0 END) else 0 end +  
		       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.mnto_02 ELSE 0 END) else 0 end +  
		       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.mnto_03 ELSE 0 END) else 0 end +  
		       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.mnto_04 ELSE 0 END) else 0 end +  
		       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.mnto_05 ELSE 0 END) else 0 end +  
		       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.mnto_06 ELSE 0 END) else 0 end +  
		       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.mnto_07 ELSE 0 END) else 0 end +  
		       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.mnto_08 ELSE 0 END) else 0 end +  
		       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.mnto_09 ELSE 0 END) else 0 end +  
		       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.mnto_10 ELSE 0 END) else 0 end +  
		       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.mnto_11 ELSE 0 END) else 0 end +  
		       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.mnto_12 ELSE 0 END) else 0 end)* (100/(100 - C.tasa_impto) ) )  
		       else 0 end ) end ) - sum (D.VALOR_STOCK) VALOR,  
	       
	       SUM(m.VALOR_ANNO_01) VALOR_ANNO_01,   
		   SUM(m.VALOR_ANNO_02) VALOR_ANNO_02,  
		   SUM(m.VALOR_ANNO_03) VALOR_ANNO_03, 
	       C.TIPO_IMPUESTO,     
	       C.TASA_IMPTO,     
	       case when C.fuente_impto is null or RTRIM(LTRIM(C.fuente_impto)) = '' then null else  C.fuente_impto end  as fte_impto,	       
	               
	       NULL, 
	       NULL, 
	       NULL,
	       
	       D.CENTRO_COSTO,     
