	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_01 = '1' THEN D.CANT_01_ANNO_01 else 0 END) else 0 END as cant_01_anno_01,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO_01 = '1' THEN D.CANT_02_ANNO_01 else 0 END) else 0 end as cant_02_anno_01,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO_01 = '1' THEN D.CANT_03_ANNO_01 else 0 END) else 0 end as cant_03_anno_01,       
