	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO_02 = '1' THEN D.CANT_04_ANNO_02 else 0 END) else 0 end as cant_04_anno_02,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO_02 = '1' THEN D.CANT_05_ANNO_02 else 0 END) else 0 end as cant_05_anno_02,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO_02 = '1' THEN D.CANT_06_ANNO_02 else 0 END) else 0 end as cant_06_anno_02,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO_02 = '1' THEN D.CANT_07_ANNO_02 else 0 END) else 0 end as cant_07_anno_02,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_02 = '1' THEN D.CANT_08_ANNO_02 else 0 END) else 0 end as cant_08_anno_02,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO_02 = '1' THEN D.CANT_09_ANNO_02 else 0 END) else 0 end as cant_09_anno_02,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_02 = '1' THEN D.CANT_10_ANNO_02 else 0 END) else 0 end as cant_10_anno_02,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_02 = '1' THEN D.CANT_11_ANNO_02 else 0 END) else 0 end as cant_11_anno_02,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_02 = '1' THEN D.CANT_12_ANNO_02 else 0 END) else 0 end as cant_12_anno_02,   
	       
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_03 = '1' THEN D.CANT_01_ANNO_03 else 0 END) else 0 END as cant_01_anno_03,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO_03 = '1' THEN D.CANT_02_ANNO_03 else 0 END) else 0 end as cant_02_anno_03,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO_03 = '1' THEN D.CANT_03_ANNO_03 else 0 END) else 0 end as cant_03_anno_03,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO_03 = '1' THEN D.CANT_04_ANNO_03 else 0 END) else 0 end as cant_04_anno_03,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO_03 = '1' THEN D.CANT_05_ANNO_03 else 0 END) else 0 end as cant_05_anno_03,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO_03 = '1' THEN D.CANT_06_ANNO_03 else 0 END) else 0 end as cant_06_anno_03,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO_03 = '1' THEN D.CANT_07_ANNO_03 else 0 END) else 0 end as cant_07_anno_03,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_03 = '1' THEN D.CANT_08_ANNO_03 else 0 END) else 0 end as cant_08_anno_03,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO_03 = '1' THEN D.CANT_09_ANNO_03 else 0 END) else 0 end as cant_09_anno_03,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_03 = '1' THEN D.CANT_10_ANNO_03 else 0 END) else 0 end as cant_10_anno_03,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_03 = '1' THEN D.CANT_11_ANNO_03 else 0 END) else 0 end as cant_11_anno_03,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_03 = '1' THEN D.CANT_12_ANNO_03 else 0 END) else 0 end as cant_12_anno_03      
	             
	  FROM SIG_CUADRO_necesidad C,     
	       SIG_CUADRO_necesidad_det D,     
	       #TMP_SIG_PAAC_ITEM i,  
	       #TMP_SIG_PAAC_METAS m  
	 WHERE I.ANO_EJE=D.ANO_EJE AND I.SEC_EJEC=D.SEC_EJEC AND i.item_bien = d.item_bien and i.grupo_bien = d.grupo_bien and i.clase_bien = d.clase_bien and i.familia_bien = d.familia_bien and i.item_bien = d.item_bien and  
	       I.NRO_CONSOLID = @PN_NRO_PAO and   
	       I.SEC_RESUMEN1 = M.SEC_RESUMEN AND M.SEC_FUNC = C.SEC_FUNC AND M.FUENTE_FINANC = C.FUENTE_FINANC AND M.CLASIFICADOR = C.CLASIFICADOR AND  
	       ( D.ANO_EJE = C.ANO_EJE ) and    
	       ( D.SEC_EJEC = C.SEC_EJEC ) and    
	       ( D.CENTRO_COSTO = C.CENTRO_COSTO ) and    
	       ( D.fase_cuadro = C.fase_cuadro) and    
	       ( D.SECUENCIA = C.SECUENCIA ) and    
	       (  C.ANO_EJE = @PN_ANIO ) AND    
	       ( C.SEC_EJEC = @PN_EJECUTORA ) AND    
	       ( D.TIPO_BIEN = @PS_TIPO ) AND    
	       ( D.ESTADO = '5' ) AND    
	       
	       EXISTS(select FUENTE from tmp_parametros_pao 
	      		  where CODIGO = 3 and NRO_PAO = @PN_NRO_PAO AND Fuente = C.FUENTE_FINANC) AND
	     
	       EXISTS (select CLASIFICADOR from tmp_parametros_pao 
	      		  where CODIGO = 2 and NRO_PAO = @PN_NRO_PAO AND CLASIFICADOR = C.CLASIFICADOR) AND 
	     
	       EXISTS (select SEC_FUNC from tmp_parametros_pao 
	        	   where CODIGO = 4 and NRO_PAO = @PN_NRO_PAO AND SEC_FUNC = C.SEC_FUNC) AND
	
	       EXISTS(select CENTRO_COSTO from tmp_parametros_pao 
	      		  where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND centro_costo = D.CENTRO_COSTO  )   AND
	
	       EXISTS( SELECT '1' FROM tmp_parametros_pao  
	                where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO AND  
	                      C.TIPO_USO = TIPO_USO AND  
	                      C.TIPO_TAREA = TIPO_TAREA AND  
	                      C.NIVEL_TAREA = NIVEL_TAREA AND  
	                      C.CODIGO_TAREA = CODIGO_TAREA AND
						  TIPO_USO = C.TIPO_USO ) AND
	      ( (D.FASE_CUADRO =  3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012) ) AND    
	       (  
	      EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
	      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
		  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
					ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
		  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
					ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
	       ) AND     
	      
	      ( D.MNTO_TOTAL > 0 )    AND
	      ( D.estado_item_kit = 'A' ) and
	    EXISTS(SELECT '1' FROM TMP_PARAMETROS_PAO AA  
			    WHERE   
			    AA.CODIGO = 1 AND   
			    AA.NRO_PAO = @PN_NRO_PAO AND  
			    AA.CENTRO_COSTO = D.CENTRO_COSTO AND   
			    AA.SECUENCIA_CN = D.SECUENCIA AND  
			    AA.ITEM_SEC_CN = D.ITEM_SEC AND  
			    ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN = AA.ITEM ) )  
	  
	GROUP BY D.CENTRO_COSTO,     
	         C.TIPO_TAREA,     
	         C.CODIGO_TAREA,     
	         C.TIPO_IMPuesTO,     
	         C.TASA_IMPTO,     
	         case when C.fuente_impto is null or RTRIM(LTRIM(C.fuente_impto)) = '' then null else  C.fuente_impto end,  
	         C.NIVEL_TAREA,  
	         I.SEC_RESUMEN1, M.SEC_META,  
	  		 C.TIPO_USO, C.MAYOR, C.SUB_CTA_DET  
  
	DECLARE @SEC_META numeric(5, 0), @SEC_CTRO_COSTO1 numeric(5, 0), @SEC_META_ANT VARCHAR(100)  
	DECLARE CUR_CC CURSOR FOR  
		SELECT T.SEC_RESUMEN, T.SEC_META, T.SEC_CTRO_COSTO1   
		FROM #TMP_SIG_PAAC_CENTRO_COSTO T, (SELECT SEC_RESUMEN, SEC_META FROM #TMP_SIG_PAAC_CENTRO_COSTO GROUP BY SEC_RESUMEN, SEC_META HAVING COUNT(*) > 1) A  
		WHERE T.SEC_RESUMEN = A.SEC_RESUMEN AND T.SEC_META = A.SEC_META  
		ORDER BY T.SEC_RESUMEN, T.SEC_META 
	   
	OPEN CUR_CC  
	FETCH CUR_CC INTO @SEC_RESUMEN, @SEC_META, @SEC_CTRO_COSTO1  
	WHILE @@FETCH_STATUS = 0  
	BEGIN  
	   SELECT @NUM = 1  
	   SELECT @SEC_META_ANT = LTRIM(STR(@SEC_RESUMEN)) + LTRIM(STR(@SEC_META))  
	   WHILE @@FETCH_STATUS = 0 AND @SEC_META_ANT = LTRIM(STR(@SEC_RESUMEN)) + LTRIM(STR(@SEC_META))  
	   BEGIN  
	      UPDATE #TMP_SIG_PAAC_CENTRO_COSTO SET SEC_CTRO_COSTO = @NUM WHERE SEC_RESUMEN = @SEC_RESUMEN AND SEC_META = @SEC_META AND SEC_CTRO_COSTO1 = @SEC_CTRO_COSTO1  
	      SELECT @NUM = @NUM + 1  
	      FETCH CUR_CC INTO @SEC_RESUMEN, @SEC_META, @SEC_CTRO_COSTO1  
	   END  
	END  
	CLOSE CUR_CC  
	DEALLOCATE CUR_CC  
   
	UPDATE #TMP_SIG_PAAC_CENTRO_COSTO SET SEC_CTRO_COSTO = 1 WHERE SEC_CTRO_COSTO IS NULL  
	  
	--Determina Ubigeo de UE  
	SELECT @ls_pais = coalesce(pais,''),  
	       @ls_depa = coalesce(departamento,''),  
	     @ls_prov = coalesce(provincia,''),  
	       @ls_dist = coalesce(distrito,'')  
	  FROM Ejecutora  
	 WHERE sec_ejec = @PN_EJECUTORA  
	  
	If (@ls_pais = '') or (@ls_depa = '') or (@ls_prov = '') or (@ls_dist = '')  
	Begin  
	     select @ls_pais = '4028'  
	     select @ls_depa = '15'  
	     select @ls_prov = '01'  
	     select @ls_dist = '01'  
	End  
	  
	----- Inserta tablas fisicas  
	BEGIN TRAN  
	   
		-- Inserta Cabecera PAAC   
		INSERT INTO sig_paac_consolidado  
		(ANO_EJE,      SEC_EJEC,    TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, ESTADO,  
		 MES_INICIAL,    MES_FINAL,     FECHA_CONS,    TIPO_BIEN,    MONEDA,          TIPO_CAMBIO,  
		 FECHA_TCAMBIO,  TIPO_COMPRA,  MODAL_COMPRA,  PAIS,        DEPARTAMENTO,    PROVINCIA,  
		 DISTRITO,  EQUIPO_REG, CUSER_ID,      ESPEC_TECNICAS,  UNIDAD_MEDIDA, TIPO_ORGANISMO ) VALUES  
		(@PN_ANIO, @PN_EJECUTORA, @ls_tipo_cons, @PN_NRO_PAO, @ps_tipo_generacion, @ls_estado,   
		 RIGHT('00' + LTRIM(STR(@PS_MES_INI)),2), RIGHT('00' + LTRIM(STR(@PS_MES_FIN)),2), @ldt_fecha_Cons, @ps_tipo, @ls_moneda, @ld_tipo_Camb,  
		 @ldt_fecha_Cons, @Ps_TIPO_COMPRA, @PS_MODAL_COMPRA, @ls_pais, @ls_depa, @ls_prov,  
		 @ls_dist, @ls_equipo, @PS_USUARIO, @Ps_especif, @li_unidad_med_cons, @ls_tipo_organismo)  
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
	   
	   	SET @li_cont = 0
      	WHILE (@li_cont < 4 )   -- RF09 - 200200  - Secuencia para Años consecutivos al año de programación 
      	BEGIN  
	   
			insert into sig_paac_secuencia  
			(ANO_EJE,  		SEC_EJEC, 	 TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,  
			 SEC_CONSOLID,  ANO_PROCESO, MES_INICIAL, 	MES_FINAL,    FECHA_REG,       CUSER_ID,   
			 ESPECIF_TECNICA )  
			values  
			(@PN_ANIO, 		@PN_EJECUTORA, @ls_tipo_cons, @PN_NRO_PAO, @ps_tipo_generacion, @ps_tipo,  
			 @li_secu_cons, (@PN_ANIO + @li_cont), RIGHT('00' + LTRIM(STR(@PS_MES_INI)),2), RIGHT('00' + LTRIM(STR(@PS_MES_FIN)),2), @ldt_fecha_Cons, @PS_USUARIO, 
			 @Ps_especif )  
			  
			IF @@ERROR <> 0  
			   GOTO ERROR  
			   
			-- Inserta Items   
			INSERT INTO SIG_PAAC_ITEM  
			  (ANO_EJE,   	SEC_EJEC,  		TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,  
			   SEC_CONSOLID,GRUPO_BIEN,     CLASE_BIEN,    FAMILIA_BIEN, ITEM_BIEN,  
			   MES_01,   	MES_02, 		MES_03,        MES_04,       MES_05,       MES_06,  
			   MES_07,  	MES_08,         MES_09,        MES_10,       MES_11,       MES_12,  
			   CANTIDAD,    UNIDAD_MEDIDA,  FECHA_PRECIO,  MONEDA,       TIPO_CAMBIO,  PRECIO_UNIT,  
			   VALOR,  		PRECIO_MONEDA,  VALOR_MONEDA,  CANTIDAD_USO, UNIDAD_USO,   PRECIO_USO, 
			   FACTOR_UNIDAD,PRESENTACION,  FECHA_REG, 	   CUSER_ID, 	 EQUIPO_REG,   SEC_RESUMEN   )  
			SELECT 
			   ANO_EJE,   	   SEC_EJEC,  TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,    
			   @li_secu_cons,  GRUPO_BIEN,    CLASE_BIEN,   FAMILIA_BIEN,    ITEM_BIEN,  
			   CASE @li_secu_cons WHEN 1 THEN MES_01   
			   		 			  WHEN 2 THEN MES_01_ANNO_01
				    			  WHEN 3 THEN MES_01_ANNO_02 
				    			  WHEN 4 THEN MES_01_ANNO_03 ELSE 0 END AS MES_01,
 			   CASE @li_secu_cons WHEN 1 THEN MES_02   
			   		 			  WHEN 2 THEN MES_02_ANNO_01
				    			  WHEN 3 THEN MES_02_ANNO_02 
				    			  WHEN 4 THEN MES_02_ANNO_03 ELSE 0 END AS MES_02,	
   			   CASE @li_secu_cons WHEN 1 THEN MES_03   
			   		 			  WHEN 2 THEN MES_03_ANNO_01
				    			  WHEN 3 THEN MES_03_ANNO_02 
				    			  WHEN 4 THEN MES_03_ANNO_03 ELSE 0 END AS MES_03,
 			   CASE @li_secu_cons WHEN 1 THEN MES_04   
			   		 			  WHEN 2 THEN MES_04_ANNO_01
				    			  WHEN 3 THEN MES_04_ANNO_02 
				    			  WHEN 4 THEN MES_04_ANNO_03 ELSE 0 END AS MES_04,	
			   CASE @li_secu_cons WHEN 1 THEN MES_05   
			   		 			  WHEN 2 THEN MES_05_ANNO_01
				    			  WHEN 3 THEN MES_05_ANNO_02 
				    			  WHEN 4 THEN MES_05_ANNO_03 ELSE 0 END AS MES_05,
 			   CASE @li_secu_cons WHEN 1 THEN MES_06   
			   		 			  WHEN 2 THEN MES_06_ANNO_01
				    			  WHEN 3 THEN MES_06_ANNO_02 
				    			  WHEN 4 THEN MES_06_ANNO_03 ELSE 0 END AS MES_06,	
   			   CASE @li_secu_cons WHEN 1 THEN MES_07  
			   		 			  WHEN 2 THEN MES_07_ANNO_01
				    			  WHEN 3 THEN MES_07_ANNO_02 
				    			  WHEN 4 THEN MES_07_ANNO_03 ELSE 0 END AS MES_07,
 			   CASE @li_secu_cons WHEN 1 THEN MES_08   
			   		 			  WHEN 2 THEN MES_08_ANNO_01
				    			  WHEN 3 THEN MES_08_ANNO_02 
				    			  WHEN 4 THEN MES_08_ANNO_03 ELSE 0 END AS MES_08,	    			  
			   CASE @li_secu_cons WHEN 1 THEN MES_09   
			   		 			  WHEN 2 THEN MES_09_ANNO_01
				    			  WHEN 3 THEN MES_09_ANNO_02 
				    			  WHEN 4 THEN MES_09_ANNO_03 ELSE 0 END AS MES_09,
 			   CASE @li_secu_cons WHEN 1 THEN MES_10   
			   		 			  WHEN 2 THEN MES_10_ANNO_01
				    			  WHEN 3 THEN MES_10_ANNO_02 
				    			  WHEN 4 THEN MES_10_ANNO_03 ELSE 0 END AS MES_10,	
   			   CASE @li_secu_cons WHEN 1 THEN MES_11  
			   		 			  WHEN 2 THEN MES_11_ANNO_01
				    			  WHEN 3 THEN MES_11_ANNO_02 
				    			  WHEN 4 THEN MES_11_ANNO_03 ELSE 0 END AS MES_11,
 			   CASE @li_secu_cons WHEN 1 THEN MES_12   
			   		 			  WHEN 2 THEN MES_12_ANNO_01
				    			  WHEN 3 THEN MES_12_ANNO_02 
				    			  WHEN 4 THEN MES_12_ANNO_03 ELSE 0 END AS MES_12,
			   CASE @li_secu_cons WHEN 1 THEN CANTIDAD   
			   		 			  WHEN 2 THEN CANTIDAD_ANNO_01
				    			  WHEN 3 THEN CANTIDAD_ANNO_02 
				    			  WHEN 4 THEN CANTIDAD_ANNO_03 ELSE 0 END AS CANTIDAD, 	 
			   UNIDAD_MEDIDA, FECHA_PRECIO, MONEDA,       TIPO_CAMBIO,    PRECIO_UNIT,  
			   CASE @li_secu_cons WHEN 1 THEN VALOR   
			   		 			  WHEN 2 THEN VALOR_ANNO_01
				    			  WHEN 3 THEN VALOR_ANNO_02 
				    			  WHEN 4 THEN VALOR_ANNO_03 ELSE 0 END AS VALOR,  
			   PRECIO_MONEDA, VALOR_MONEDA, CANTIDAD_USO, UNIDAD_USO, 	PRECIO_USO,     
			   FACTOR_UNIDAD, PRESENTACION, FECHA_REG, 	  CUSER_ID, 	EQUIPO_REG, 	SEC_RESUMEN1    
			FROM #TMP_SIG_PAAC_ITEM  
			   
			IF @@ERROR <> 0  
			   GOTO ERROR  
			   
			-- Inserta Metas   
			INSERT INTO SIG_PAAC_METAS  
			 (ANO_EJE, 		SEC_EJEC, 	 TIPO_CONSOLID,  NRO_CONSOLID,  TIPO_GENERACION, TIPO_BIEN,  
			  SEC_CONSOLID, SEC_RESUMEN, SEC_FUNC,  	 ORIGEN,    	FUENTE_FINANC,   TIPO_RECURSO,  
			  CLASIFICADOR, MES_01,  	 MES_02,   		 MES_03,    	MES_04,   		 MES_05,  
			  MES_06,   	MES_07,  	 MES_08,   		 MES_09,    	MES_10,   		 MES_11,  
			  MES_12,   	CANTIDAD, 	 VALOR,   		 TIPO_IMPTO,    FTE_FTO_IMPTO,   TASA_IMPTO,  
			  VALOR_IMPTO,  VALOR_MONEDA,VALOR_IMPTO_MONEDA,FECHA_REG,  CUSER_ID, 		 EQUIPO_REG, SEC_META )  
		    SELECT ANO_EJE,  	   SEC_EJEC,    TIPO_CONSOLID,  NRO_CONSOLID,  TIPO_GENERACION, TIPO_BIEN,    
			 	   @li_secu_cons,  SEC_RESUMEN, SEC_FUNC,  		ORIGEN,    		FUENTE_FINANC,  TIPO_RECURSO,    
			  	   CLASIFICADOR, 
			  	   CASE @li_secu_cons WHEN 1 THEN MES_01   
				   		 			  WHEN 2 THEN MES_01_ANNO_01
					    			  WHEN 3 THEN MES_01_ANNO_02 
					    			  WHEN 4 THEN MES_01_ANNO_03 ELSE 0 END AS MES_01,
 			   	   CASE @li_secu_cons WHEN 1 THEN MES_02   
				   		 			  WHEN 2 THEN MES_02_ANNO_01
					    			  WHEN 3 THEN MES_02_ANNO_02 
					    			  WHEN 4 THEN MES_02_ANNO_03 ELSE 0 END AS MES_02,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_03   
				   		 			  WHEN 2 THEN MES_03_ANNO_01
					    			  WHEN 3 THEN MES_03_ANNO_02 
					    			  WHEN 4 THEN MES_03_ANNO_03 ELSE 0 END AS MES_03,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_04   
				   		 			  WHEN 2 THEN MES_04_ANNO_01
					    			  WHEN 3 THEN MES_04_ANNO_02 
					    			  WHEN 4 THEN MES_04_ANNO_03 ELSE 0 END AS MES_04,	
				   CASE @li_secu_cons WHEN 1 THEN MES_05   
				   		 			  WHEN 2 THEN MES_05_ANNO_01
					    			  WHEN 3 THEN MES_05_ANNO_02 
					    			  WHEN 4 THEN MES_05_ANNO_03 ELSE 0 END AS MES_05,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_06   
				   		 			  WHEN 2 THEN MES_06_ANNO_01
					    			  WHEN 3 THEN MES_06_ANNO_02 
					    			  WHEN 4 THEN MES_06_ANNO_03 ELSE 0 END AS MES_06,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_07  
				   		 			  WHEN 2 THEN MES_07_ANNO_01
					    			  WHEN 3 THEN MES_07_ANNO_02 
					    			  WHEN 4 THEN MES_07_ANNO_03 ELSE 0 END AS MES_07,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_08   
				   		 			  WHEN 2 THEN MES_08_ANNO_01
					    			  WHEN 3 THEN MES_08_ANNO_02 
					    			  WHEN 4 THEN MES_08_ANNO_03 ELSE 0 END AS MES_08,	    			  
				   CASE @li_secu_cons WHEN 1 THEN MES_09   
				   		 			  WHEN 2 THEN MES_09_ANNO_01
					    			  WHEN 3 THEN MES_09_ANNO_02 
					    			  WHEN 4 THEN MES_09_ANNO_03 ELSE 0 END AS MES_09,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_10   
				   		 			  WHEN 2 THEN MES_10_ANNO_01
					    			  WHEN 3 THEN MES_10_ANNO_02 
					    			  WHEN 4 THEN MES_10_ANNO_03 ELSE 0 END AS MES_10,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_11  
				   		 			  WHEN 2 THEN MES_11_ANNO_01
					    			  WHEN 3 THEN MES_11_ANNO_02 
					    			  WHEN 4 THEN MES_11_ANNO_03 ELSE 0 END AS MES_11,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_12   
				   		 			  WHEN 2 THEN MES_12_ANNO_01
					    			  WHEN 3 THEN MES_12_ANNO_02 
					    			  WHEN 4 THEN MES_12_ANNO_03 ELSE 0 END AS MES_12,
 				   CASE @li_secu_cons WHEN 1 THEN CANTIDAD   
				   		 			  WHEN 2 THEN CANTIDAD_ANNO_01
					    			  WHEN 3 THEN CANTIDAD_ANNO_02 
					    			  WHEN 4 THEN CANTIDAD_ANNO_03 ELSE 0 END AS CANTIDAD, 	 					    			  
			  	   CASE @li_secu_cons WHEN 1 THEN VALOR   
				   		 			  WHEN 2 THEN VALOR_ANNO_01
					    			  WHEN 3 THEN VALOR_ANNO_02 
					    			  WHEN 4 THEN VALOR_ANNO_03 ELSE 0 END AS VALOR, 
			  	   TIPO_IMPTO, FTE_FTO_IMPTO,  TASA_IMPTO,  VALOR_IMPTO,  
			   	   VALOR_MONEDA, VALOR_IMPTO_MONEDA,FECHA_REG,  CUSER_ID,  	EQUIPO_REG,  SEC_META  
			FROM #TMP_SIG_PAAC_METAS  
			   
			IF @@ERROR <> 0  
			   GOTO ERROR  
			   
			-- Inserta Centro Costo   
			INSERT INTO SIG_PAAC_CENTRO_COSTO  
			 (ANO_EJE,  	SEC_EJEC, 	 TIPO_CONSOLID, NRO_CONSOLID, 	TIPO_GENERACION, TIPO_BIEN,  
			  SEC_CONSOLID, SEC_RESUMEN, SEC_META,  	SEC_CTRO_COSTO, TIPO_TAREA,   	 CODIGO_TAREA, 
			  MES_01,  	  	MES_02,  	 MES_03,   		MES_04,    		MES_05,    		 MES_06,   
			  MES_07,		MES_08,  	 MES_09,   		MES_10,    		MES_11,    		 MES_12,   
			  CANTIDAD,     VALOR,  	 TIPO_IMPTO,  	TASA_IMPTO,   	FTE_FTO_IMPTO,   VALOR_IMPTO, 
			  VALOR_MONEDA, VALOR_IMPTO_MONEDA,CENTRO_COSTO,FECHA_REG,  CUSER_ID,   	 NIVEL_TAREA,  
			  TIPO_USO, 	MAYOR, 		 SUB_CTA_DET)  
			SELECT ANO_EJE,  SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,    
			       @li_secu_cons, SEC_RESUMEN, SEC_META, SEC_CTRO_COSTO, TIPO_TAREA, CODIGO_TAREA,   
			       CASE @li_secu_cons WHEN 1 THEN MES_01   
				   		 			  WHEN 2 THEN MES_01_ANNO_01
					    			  WHEN 3 THEN MES_01_ANNO_02 
					    			  WHEN 4 THEN MES_01_ANNO_03 ELSE 0 END AS MES_01,
 			   	   CASE @li_secu_cons WHEN 1 THEN MES_02   
				   		 			  WHEN 2 THEN MES_02_ANNO_01
					    			  WHEN 3 THEN MES_02_ANNO_02 
					    			  WHEN 4 THEN MES_02_ANNO_03 ELSE 0 END AS MES_02,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_03   
				   		 			  WHEN 2 THEN MES_03_ANNO_01
					    			  WHEN 3 THEN MES_03_ANNO_02 
					    			  WHEN 4 THEN MES_03_ANNO_03 ELSE 0 END AS MES_03,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_04   
				   		 			  WHEN 2 THEN MES_04_ANNO_01
					    			  WHEN 3 THEN MES_04_ANNO_02 
					    			  WHEN 4 THEN MES_04_ANNO_03 ELSE 0 END AS MES_04,	
				   CASE @li_secu_cons WHEN 1 THEN MES_05   
				   		 			  WHEN 2 THEN MES_05_ANNO_01
					    			  WHEN 3 THEN MES_05_ANNO_02 
					    			  WHEN 4 THEN MES_05_ANNO_03 ELSE 0 END AS MES_05,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_06   
				   		 			  WHEN 2 THEN MES_06_ANNO_01
					    			  WHEN 3 THEN MES_06_ANNO_02 
					    			  WHEN 4 THEN MES_06_ANNO_03 ELSE 0 END AS MES_06,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_07  
				   		 			  WHEN 2 THEN MES_07_ANNO_01
					    			  WHEN 3 THEN MES_07_ANNO_02 
					    			  WHEN 4 THEN MES_07_ANNO_03 ELSE 0 END AS MES_07,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_08   
				   		 			  WHEN 2 THEN MES_08_ANNO_01
					    			  WHEN 3 THEN MES_08_ANNO_02 
					    			  WHEN 4 THEN MES_08_ANNO_03 ELSE 0 END AS MES_08,	    			  
				   CASE @li_secu_cons WHEN 1 THEN MES_09   
				   		 			  WHEN 2 THEN MES_09_ANNO_01
					    			  WHEN 3 THEN MES_09_ANNO_02 
					    			  WHEN 4 THEN MES_09_ANNO_03 ELSE 0 END AS MES_09,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_10   
				   		 			  WHEN 2 THEN MES_10_ANNO_01
					    			  WHEN 3 THEN MES_10_ANNO_02 
					    			  WHEN 4 THEN MES_10_ANNO_03 ELSE 0 END AS MES_10,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_11  
				   		 			  WHEN 2 THEN MES_11_ANNO_01
					    			  WHEN 3 THEN MES_11_ANNO_02 
					    			  WHEN 4 THEN MES_11_ANNO_03 ELSE 0 END AS MES_11,
	 			   CASE @li_secu_cons WHEN 1 THEN MES_12   
				   		 			  WHEN 2 THEN MES_12_ANNO_01
					    			  WHEN 3 THEN MES_12_ANNO_02 
					    			  WHEN 4 THEN MES_12_ANNO_03 ELSE 0 END AS MES_12, 
 				   CASE @li_secu_cons WHEN 1 THEN CANTIDAD   
				   		 			  WHEN 2 THEN CANTIDAD_ANNO_01
					    			  WHEN 3 THEN CANTIDAD_ANNO_02 
					    			  WHEN 4 THEN CANTIDAD_ANNO_03 ELSE 0 END AS CANTIDAD, 	
 				   CASE @li_secu_cons WHEN 1 THEN VALOR   
				   		 			  WHEN 2 THEN VALOR_ANNO_01
					    			  WHEN 3 THEN VALOR_ANNO_02 
					    			  WHEN 4 THEN VALOR_ANNO_03 ELSE 0 END AS VALOR, 					    			  					    			  			     
			      TIPO_IMPTO, 	TASA_IMPTO, FTE_FTO_IMPTO, 	VALOR_IMPTO, VALOR_MONEDA, VALOR_IMPTO_MONEDA, 
			      CENTRO_COSTO, FECHA_REG,  CUSER_ID,   	NIVEL_TAREA,    
			 	  TIPO_USO, 	MAYOR, 	    SUB_CTA_DET   
			 FROM #TMP_SIG_PAAC_CENTRO_COSTO  
			   
			IF @@ERROR <> 0  
			   GOTO ERROR  
   
   			SET @li_secu_cons = @li_secu_cons + 1
	     	SET @li_cont = @li_cont + 1   
		      
     	END 
   
		DELETE SIG_PAAC_CENTRO_COSTO   
		WHERE   
		ANO_EJE = @PN_ANIO AND  
		SEC_EJEC = @PN_EJECUTORA AND  
		TIPO_CONSOLID = '1' AND  
		NRO_CONSOLID = @PN_NRO_PAO AND   
		TIPO_GENERACION = @ps_tipo_generacion AND  
		CANTIDAD = 0  
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
		   
		DELETE SIG_PAAC_METAS   
		WHERE   
		ANO_EJE = @PN_ANIO AND  
		SEC_EJEC = @PN_EJECUTORA AND  
		TIPO_CONSOLID = '1' AND  
		NRO_CONSOLID = @PN_NRO_PAO AND  
		TIPO_GENERACION = @ps_tipo_generacion AND  
		CANTIDAD = 0  
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
		   
		DELETE SIG_PAAC_ITEM   
		WHERE   
		ANO_EJE = @PN_ANIO AND  
		SEC_EJEC = @PN_EJECUTORA AND  
		TIPO_CONSOLID = '1' AND  
		NRO_CONSOLID = @PN_NRO_PAO AND  
		TIPO_GENERACION = @ps_tipo_generacion AND  
		CANTIDAD = 0  
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
   
         DELETE SIG_PAAC_SECUENCIA
		 WHERE ANO_EJE 			= @PN_ANIO AND 
			   SEC_EJEC 		= @PN_EJECUTORA AND 
			   TIPO_CONSOLID 	= '1' AND 
			   NRO_CONSOLID  	= @PN_NRO_PAO AND 
			   TIPO_GENERACION 	= @ps_tipo_generacion AND 	
			   TIPO_BIEN 		= @PS_TIPO AND 		
			   NOT EXISTS ( SELECT 1   FROM SIG_PAAC_ITEM I
				             WHERE I.ano_eje          = SIG_PAAC_SECUENCIA.ANO_EJE AND
				                   I.sec_ejec         = SIG_PAAC_SECUENCIA.SEC_EJEC AND
				                   I.tipo_consolid    = SIG_PAAC_SECUENCIA.TIPO_CONSOLID AND
				                   I.nro_consolid     = SIG_PAAC_SECUENCIA.NRO_CONSOLID AND
				                   I.TIPO_GENERACION  = SIG_PAAC_SECUENCIA.TIPO_GENERACION AND
				                   I.TIPO_BIEN        = SIG_PAAC_SECUENCIA.TIPO_BIEN AND 
				                   I.SEC_CONSOLID 	  =  SIG_PAAC_SECUENCIA.SEC_CONSOLID  )
							
		IF @@ERROR <> 0    
		   GOTO ERROR  	    
		    
			UPDATE  SIG_PAAC_ITEM
			SET         SIG_PAAC_ITEM.PRECIO_UNIT = D.PRECIO_UNIT , SIG_PAAC_ITEM.PRECIO_MONEDA = D.PRECIO_UNIT
			FROM 
			SIG_PAAC_METAS,
			SIG_PAAC_ITEM I,
			SIG_CUADRO_NECESIDAD,
			SIG_CUADRO_NECESIDAD_DET D,
			SIG_PAAC_CENTRO_COSTO
			WHERE   
			SIG_PAAC_CENTRO_COSTO.SEC_EJEC           = SIG_PAAC_METAS.SEC_EJEC           
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = SIG_PAAC_METAS.ANO_EJE  
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = SIG_PAAC_METAS.TIPO_CONSOLID      
			AND     SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID       = SIG_PAAC_METAS.NRO_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION    = SIG_PAAC_METAS.TIPO_GENERACION    
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_BIEN          = SIG_PAAC_METAS.TIPO_BIEN          
			AND     SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID       = SIG_PAAC_METAS.SEC_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN        = SIG_PAAC_METAS.SEC_RESUMEN        
			AND     SIG_PAAC_CENTRO_COSTO.SEC_META           = SIG_PAAC_METAS.SEC_META           
			AND     SIG_PAAC_CENTRO_COSTO.SEC_EJEC           = I.SEC_EJEC           
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = I.ANO_EJE  
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = I.TIPO_CONSOLID      
			AND     SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID       = I.NRO_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION    = I.TIPO_GENERACION    
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_BIEN          = I.TIPO_BIEN          
			AND     SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID       = I.SEC_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN        = I.SEC_RESUMEN    
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = 1
			AND     SIG_CUADRO_NECESIDAD.SEC_EJEC      = SIG_PAAC_CENTRO_COSTO.SEC_EJEC           
			AND     SIG_CUADRO_NECESIDAD.ANO_EJE       = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND     SIG_CUADRO_NECESIDAD.CENTRO_COSTO  = SIG_PAAC_CENTRO_COSTO.CENTRO_COSTO  
			
			AND     SIG_CUADRO_NECESIDAD.FASE_CUADRO   = 5
			AND     SIG_CUADRO_NECESIDAD.SEC_FUNC      = SIG_PAAC_METAS.SEC_FUNC
			AND     SIG_CUADRO_NECESIDAD.CLASIFICADOR  = SIG_PAAC_METAS.CLASIFICADOR
			AND     SIG_CUADRO_NECESIDAD.ORIGEN        = SIG_PAAC_METAS.ORIGEN
			AND     SIG_CUADRO_NECESIDAD.FUENTE_FINANC = SIG_PAAC_METAS.FUENTE_FINANC
			
			AND     SIG_CUADRO_NECESIDAD.NIVEL_TAREA   = SIG_PAAC_CENTRO_COSTO.NIVEL_TAREA	
			AND     SIG_CUADRO_NECESIDAD.CODIGO_TAREA  = SIG_PAAC_CENTRO_COSTO.CODIGO_TAREA
			
			AND     SIG_CUADRO_NECESIDAD.SEC_EJEC      = D.SEC_EJEC      
			AND     SIG_CUADRO_NECESIDAD.ANO_EJE       = D.ANO_EJE       
			AND     SIG_CUADRO_NECESIDAD.CENTRO_COSTO  = D.CENTRO_COSTO  
			AND     SIG_CUADRO_NECESIDAD.SECUENCIA     = D.SECUENCIA    
			AND     SIG_CUADRO_NECESIDAD.FASE_CUADRO   = D.FASE_CUADRO
			AND     I.TIPO_BIEN    = D.TIPO_BIEN
			AND     I.GRUPO_BIEN   = D.GRUPO_BIEN
			AND     I.CLASE_BIEN   = D.CLASE_BIEN
			AND     I.FAMILIA_BIEN = D.FAMILIA_BIEN
			AND     I.ITEM_BIEN	= D.ITEM_BIEN
			
			AND     I.ANO_EJE = @PN_ANIO     
			AND     I.SEC_EJEC = @PN_EJECUTORA     
			AND     I.TIPO_CONSOLID = '1'     
			AND     I.NRO_CONSOLID = @PN_NRO_PAO   
			AND     I.TIPO_GENERACION = @ps_tipo_generacion
	
			IF @@ERROR <> 0    
				GOTO ERROR  

		------------- Actualiza montos faltantes -----------------------  
		UPDATE SIG_PAAC_ITEM   
		SET   
			PRECIO_UNIT = VALOR / CANTIDAD,   
			PRECIO_MONEDA = VALOR / CANTIDAD,   
			VALOR_MONEDA = VALOR,   
			PRECIO_USO = VALOR / CANTIDAD  
		WHERE 
			ANO_EJE = @PN_ANIO AND  
			SEC_EJEC = @PN_EJECUTORA AND  
			TIPO_CONSOLID = '1' AND  
			NRO_CONSOLID = @PN_NRO_PAO AND  
			TIPO_GENERACION = @ps_tipo_generacion
		 	and cantidad > 0  
		  
--UPDATE SIG_PAAC_ITEM SET VALOR_MONEDA = VALOR,  
--precio_unit = (SELECT MIN(A.PRECIO_UNIT) FROM SIG_CUADRO_NECESIDAD_DET A, #TMP_SIG_PAAC_ITEM B  
--WHERE A.FASE_CUADRO = 3 AND A.ANO_EJE =B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC AND  
