--A.ITEM_BIEN = B.ITEM_BIEN AND  
--SIG_PAAC_ITEM.ANO_EJE =B.ANO_EJE AND SIG_PAAC_ITEM.SEC_EJEC = B.SEC_EJEC AND  
--SIG_PAAC_ITEM.TIPO_BIEN = B.TIPO_BIEN AND SIG_PAAC_ITEM.GRUPO_BIEN = B.GRUPO_BIEN AND   
--SIG_PAAC_ITEM.CLASE_BIEN = B.CLASE_BIEN AND SIG_PAAC_ITEM.FAMILIA_BIEN = B.FAMILIA_BIEN AND  
--SIG_PAAC_ITEM.ITEM_BIEN = B.ITEM_BIEN),  
--PRECIO_MONEDA = (SELECT MIN(A.PRECIO_UNIT) FROM SIG_CUADRO_NECESIDAD_DET A, #TMP_SIG_PAAC_ITEM B  
--WHERE A.FASE_CUADRO = 3 AND A.ANO_EJE =B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC AND  
--A.TIPO_BIEN = B.TIPO_BIEN AND A.GRUPO_BIEN = B.GRUPO_BIEN AND   
--A.CLASE_BIEN = B.CLASE_BIEN AND A.FAMILIA_BIEN = B.FAMILIA_BIEN AND  
--A.ITEM_BIEN = B.ITEM_BIEN AND  
--SIG_PAAC_ITEM.ANO_EJE =B.ANO_EJE AND SIG_PAAC_ITEM.SEC_EJEC = B.SEC_EJEC AND  
--SIG_PAAC_ITEM.TIPO_BIEN = B.TIPO_BIEN AND SIG_PAAC_ITEM.GRUPO_BIEN = B.GRUPO_BIEN AND   
