--SIG_PAAC_ITEM.ITEM_BIEN = B.ITEM_BIEN),  
--PRECIO_USO = (SELECT MIN(A.PRECIO_UNIT) FROM SIG_CUADRO_NECESIDAD_DET A, #TMP_SIG_PAAC_ITEM B  
--WHERE A.FASE_CUADRO = 3 AND A.ANO_EJE =B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC AND  
--A.TIPO_BIEN = B.TIPO_BIEN AND A.GRUPO_BIEN = B.GRUPO_BIEN AND   
--A.CLASE_BIEN = B.CLASE_BIEN AND A.FAMILIA_BIEN = B.FAMILIA_BIEN AND  
--A.ITEM_BIEN = B.ITEM_BIEN AND  
--SIG_PAAC_ITEM.ANO_EJE =B.ANO_EJE AND SIG_PAAC_ITEM.SEC_EJEC = B.SEC_EJEC AND  
--SIG_PAAC_ITEM.TIPO_BIEN = B.TIPO_BIEN AND SIG_PAAC_ITEM.GRUPO_BIEN = B.GRUPO_BIEN AND   
--SIG_PAAC_ITEM.CLASE_BIEN = B.CLASE_BIEN AND SIG_PAAC_ITEM.FAMILIA_BIEN = B.FAMILIA_BIEN AND  
--SIG_PAAC_ITEM.ITEM_BIEN = B.ITEM_BIEN)  
--WHERE   
--NRO_CONSOLID = @PN_NRO_PAO AND   
--cantidad > 0   
   
		IF @@ERROR <> 0  
		   GOTO ERROR  
  
		UPDATE SIG_PAAC_METAS   
		SET   
		VALOR = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,  
		VALOR_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,  
		VALOR_IMPTO = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END,  
		VALOR_IMPTO_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END  
		WHERE ANO_EJE = @PN_ANIO AND  
			  SEC_EJEC = @PN_EJECUTORA AND  
			  TIPO_CONSOLID = '1' AND  
			  NRO_CONSOLID = @PN_NRO_PAO AND  
			  TIPO_GENERACION = @ps_tipo_generacion
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
   
		UPDATE SIG_PAAC_CENTRO_COSTO   
		SET   
		VALOR = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,  
		VALOR_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,  
		VALOR_IMPTO = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END,  
		VALOR_IMPTO_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END  
		WHERE ANO_EJE = @PN_ANIO AND  
			  SEC_EJEC = @PN_EJECUTORA AND  
			  TIPO_CONSOLID = '1' AND  
			  NRO_CONSOLID = @PN_NRO_PAO AND  
			  TIPO_GENERACION = @ps_tipo_generacion
   
		IF @@ERROR <> 0  
		   GOTO ERROR  
		  
		----- Actualizar cantidades almacen  
		UPDATE SIG_PAAC_ITEM SET   
