		       MES_07 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_07 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06)) ELSE MES_07 END,  
		       MES_08 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_08 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07)) ELSE MES_08 END,  
		       MES_10 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_10 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09)) ELSE MES_10 END,  
		       MES_09 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_09 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08)) ELSE MES_09 END,  
		       MES_11 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_11 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10)) ELSE MES_11 END,  
		       MES_12 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_12 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11)) ELSE MES_12 END  
		WHERE (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > CANTIDAD  AND
		ANO_EJE = @PN_ANIO AND  
		SEC_EJEC = @PN_EJECUTORA AND  
		TIPO_CONSOLID = '1' AND  
		NRO_CONSOLID = @PN_NRO_PAO AND  
		TIPO_GENERACION = @ps_tipo_generacion
		   
		IF @@ERROR <> 0  
		   GOTO ERROR  
   
------ Proceso seleccion --------------------  
        /* MPC - Issue 384 - Ampliación a 5 caracteres */
		DECLARE @pn_monto_total_item numeric(16,2), @ls_proc_selec VARCHAR(2), @ls_nume_plan VARCHAR(5)  
		DECLARE @pn_monto_total_item_val numeric(16,2)    
		   
		SELECT @pn_monto_total_item = SUM(coalesce(VALOR,0))
		from sig_paac_item  
		where ano_eje  = @PN_ANIO  and  
		   sec_ejec = @PN_EJECUTORA  and  
		   tipo_consolid = @ls_tipo_cons  and  
		   nro_consolid  = @PN_NRO_PAO  and  
		   TIPO_GENERACION = @ps_tipo_generacion and  
		   TIPO_BIEN   = @PS_TIPO  		   
		   
		/*IF ( @pn_monto_total_item is null Or @pn_monto_total_item = 0 ) */
		IF ( @pn_monto_total_item = 0 )
		BEGIN
			set @pn_monto_total_item_val = 0.01
		END
		
		IF ( @pn_monto_total_item > 0 )
		BEGIN
			set @pn_monto_total_item_val = @pn_monto_total_item
		END		   
		   
		SELECT @ls_proc_selec = CODIGO  
		FROM SIG_TOPES_PROCESOS   
		WHERE ANO_EJE   = @PN_ANIO  AND    
		 TIPO_ORGANISMO = @ls_tipo_organismo AND  
		      TIPO_BIEN = @PS_TIPO AND  
		      FLAG  = '1' AND  
		      CODIGO NOT IN ('33') AND
			  @pn_monto_total_item_val BETWEEN MONTO_MINIMO AND MONTO_MAXIMO
		      /*@pn_monto_total_item BETWEEN MONTO_MINIMO AND MONTO_MAXIMO*/
			  		   
		/*IF @pn_monto_total_item > 0 AND @ls_proc_selec <> '14'*/ -- Diferencia a menor cuantia (Antes 05)  
		IF @pn_monto_total_item_val > 0 AND @ls_proc_selec <> '14'
		BEGIN
		     /*
		    select @ls_nume_plan = max(nro_paac)  
		      from sig_paac_consolidado  
		    where ano_eje  = @PN_ANIO  and  
		                  sec_ejec = @PN_EJECUTORA and  
		                  tipo_consolid = @ls_tipo_cons and  
		                  TIPO_GENERACION = @ps_tipo_generacion AND  
		                  flag_paac = '1'  
            */
            
            SELECT @ls_nume_plan = MAX(CAST(nro_paac AS INT))
              FROM SIG_PAAC_CONSOLIDADO
            WHERE ANO_EJE                      = @PN_ANIO
                 AND SEC_EJEC                      = @PN_EJECUTORA
                 AND TIPO_CONSOLID       = @ls_tipo_cons
                 AND TIPO_GENERACION = @ps_tipo_generacion
                 AND flag_paac                     = '1'
                 AND coalesce(NRO_PAAC,' ') <>  ' '
		   
		   IF @ls_nume_plan is NULL
		      /* select @ls_nume_plan = '00001 */  
		      select @ls_nume_plan = '0001'  
		   ELSE
		      /* select @ls_nume_plan = right('0000' + ltrim(str(convert(int, @ls_nume_plan) + 1)),4) */
		      select @ls_nume_plan = right('00000' + ltrim(str(convert(int, @ls_nume_plan) + 1)),5)
		      
		   UPDATE SIG_PAAC_CONSOLIDADO  
		   SET VALOR_PLAN   = @pn_monto_total_item,  
		       VALOR_MONEDA = @pn_monto_total_item,  
		       TIPO_PROCESO = @ls_proc_selec,   
		       FLAG_PAAC = '1',    NRO_PAAC = @ls_nume_plan ,  
		       UNIDAD_MEDIDA = 112, CONVOCACION_PROCESO = '0', PRECEDENTE = '0'  
		   WHERE ano_eje  = @PN_ANIO  and  
		    sec_ejec = @PN_EJECUTORA  and  
		    tipo_consolid = @ls_tipo_cons  and  
		    nro_consolid  = @PN_NRO_PAO and  
		    TIPO_GENERACION = @ps_tipo_generacion  
		   
		    IF @@ERROR <> 0  
		       GOTO ERROR  
		   
		END  
		/*IF @pn_monto_total_item > 0 AND @ls_proc_selec = '14'*/
		IF @pn_monto_total_item_val > 0 AND @ls_proc_selec = '14'
		BEGIN
		   UPDATE SIG_PAAC_CONSOLIDADO  
		   SET VALOR_PLAN   = @pn_monto_total_item,  
		       VALOR_MONEDA = @pn_monto_total_item,  
		       TIPO_PROCESO = @ls_proc_selec,  
		       FLAG_PAAC = '0' ,  UNIDAD_MEDIDA = 112, CONVOCACION_PROCESO = '0', PRECEDENTE = '0'  
		   WHERE ano_eje  = @PN_ANIO and  
		         sec_ejec = @PN_EJECUTORA and  
		         tipo_consolid = @ls_tipo_cons  and  
		         nro_consolid  = @PN_NRO_PAO and  
		         TIPO_GENERACION = @ps_tipo_generacion  
		   
		   IF @@ERROR <> 0  
		   GOTO ERROR
		 END
		 
		If @PS_MODAL_COMPRA = 'MP'  
		BEGIN
		   set @ls_proc_selec = '26' 
		   UPDATE SIG_PAAC_CONSOLIDADO    
		   SET 
		       TIPO_PROCESO = @ls_proc_selec   
		   WHERE ano_eje  		= @PN_ANIO and    
		         sec_ejec 		= @PN_EJECUTORA and    
		         tipo_consolid 	= @ls_tipo_cons  and    
		         nro_consolid  	= @PN_NRO_PAO and    
		         TIPO_GENERACION = @ps_tipo_generacion    
		     
		   IF @@ERROR <> 0    
		   GOTO ERROR
		END
   
		--IF @PS_MES_INI = 1 and @PS_MES_FIN = 12   
		--BEGIN  
		-- ========================================  
		-- Actualiza Items existentes en el PAO  
		-- ========================================  
		update sig_cuadro_necesidaD_det  
		   set sig_cuadro_necesidad_det.estado = 6  
		 FROM SIG_CUADRO_necesidad C,     
		      SIG_CUADRO_necesidad_Det D ,  
		      CATALOGO_BIEN_SERV S  
		WHERE ( D.ANO_EJE   = @PN_ANIO  AND    
		      D.SEC_EJEC    = @PN_EJECUTORA  AND
		      ((D.FASE_CUADRO =  3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012)) and
		      D.TIPO_BIEN  = @PS_TIPO  AND    
		      
		      EXISTS(select CENTRO_COSTO from tmp_parametros_pao 
		      		  where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND centro_costo = D.CENTRO_COSTO  )   AND
		  
		      EXISTS (SELECT '1' FROM tmp_parametros_pao  
					   where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO AND  
					                     C.TIPO_USO = TIPO_USO AND  
					                     C.TIPO_TAREA = TIPO_TAREA AND  
					                     C.NIVEL_TAREA = NIVEL_TAREA AND  
					                     C.CODIGO_TAREA = CODIGO_TAREA AND
										 TIPO_USO = C.TIPO_USO) AND  		       
		      (  
		      EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
		      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
			  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
						ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
			  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
						ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
		       ) AND 		    
		        
		       EXISTS(select FUENTE from tmp_parametros_pao 
		      		  where CODIGO = 3 and NRO_PAO = @PN_NRO_PAO AND Fuente = C.FUENTE_FINANC) AND
		      
		      EXISTS (select CLASIFICADOR from tmp_parametros_pao 
		      		  where CODIGO = 2 and NRO_PAO = @PN_NRO_PAO AND CLASIFICADOR = C.CLASIFICADOR) AND 
		      
		      EXISTS (select SEC_FUNC from tmp_parametros_pao 
		     		 where CODIGO = 4 and NRO_PAO = @PN_NRO_PAO AND SEC_FUNC = C.SEC_FUNC) AND
		   
		      /*D.CANT_TOTAL > 0   AND*/
			  (COALESCE(D.CANT_TOTAL, 0) + COALESCE(D.CANT_TOTAL_ANNO_01, 0) + COALESCE(D.CANT_TOTAL_ANNO_02, 0) + COALESCE(D.CANT_TOTAL_ANNO_03, 0)) > 0 and
		      ( ( @ps_modal_compra = 'SI' AND S.FLAG_SUBASTA_INVERSA = '1' ) OR  
		        ( @ps_modal_compra = 'CP' AND S.BOLSA_PRODUCTO = '1' ) OR  
		        ( @ps_modal_compra = 'MP' AND S.FLAG_MARCO_PRECIO = 'S') OR  
		        ( @ps_modal_compra NOT IN ('SI','CP','MP') AND (S.FLAG_SUBASTA_INVERSA <> '1' or S.FLAG_SUBASTA_INVERSA is null ) AND (S.BOLSA_PRODUCTO <> '1' or  S.BOLSA_PRODUCTO is null ) AND (S.FLAG_MARCO_PRECIO <> 'S' or S.FLAG_MARCO_PRECIO is null) ) ) ) AND   
		      ( D.ANO_EJE  = C.ANO_EJE  and    
		        D.SEC_EJEC = C.SEC_EJEC  and    
		        D.CENTRO_COSTO  = C.CENTRO_COSTO  and    
		        D.fase_cuadro   = C.fase_cuadro  and    
		        D.SECUENCIA     = C.SECUENCIA  AND  
		        D.SEC_EJEC 	= S.SEC_EJEC AND  
		        D.TIPO_BIEN = S.TIPO_BIEN AND  
		        D.GRUPO_BIEN = S.GRUPO_BIEN AND  
		        D.CLASE_BIEN = S.CLASE_BIEN AND  
		        D.FAMILIA_BIEN = S.FAMILIA_BIEN AND  
		        D.ITEM_BIEN = S.ITEM_BIEN) AND  
		    EXISTS(SELECT '1' FROM TMP_PARAMETROS_PAO AA  
				    WHERE   
				    AA.CODIGO = 1 AND   
				    AA.NRO_PAO = @PN_NRO_PAO AND  
				    AA.CENTRO_COSTO = D.CENTRO_COSTO AND   
				    AA.SECUENCIA_CN = D.SECUENCIA AND  
				    AA.ITEM_SEC_CN = D.ITEM_SEC AND  
				    ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN = AA.ITEM ) )  
		--END  
   
		IF @@ERROR <> 0  
		     GOTO ERROR  
		  
		DELETE tmp_parametros_pao WHERE NRO_PAO = @PN_NRO_PAO  
		   
		IF @@ERROR <> 0  
		     GOTO ERROR  
   
	COMMIT TRAN  
	set nocount off  
	RETURN 0  
	   
	ERROR:  
	   ROLLBACK TRAN  
	   set nocount off  
	   RETURN 1
GO


-- ----------------------------
-- function structure for SF_FECHA_FIN_HABIL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_FECHA_FIN_HABIL]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_FECHA_FIN_HABIL]
GO

CREATE FUNCTION [dbo].[SF_FECHA_FIN_HABIL]
(
@ad_fecha_inicio_dt    DATETIME,
@al_dias_dif           INTEGER
)
RETURNS DATETIME
AS
BEGIN

DECLARE @ll_dias_sem     INTEGER
DECLARE @ll_item         INTEGER
DECLARE @ll_busqueda     INTEGER
DECLARE @ll_cont         INTEGER
DECLARE @ll_cont1        INTEGER
DECLARE @ld_fecha_ref    DATE
DECLARE @ld_fecha_fin_ref DATE
DECLARE @ad_fecha_inicio  DATE

--Inicializando Variables
SET @ll_cont     = 0
SET @ll_cont1    = 0
SET @ad_fecha_inicio = CONVERT(DATE,@ad_fecha_inicio_dt)

BEGIN
	 
	SET @ll_item     = 1
	WHILE @ll_cont1 <> @al_dias_dif 
	BEGIN
	    SET @ld_fecha_ref   = DATEADD(DAY, @ll_item, @ad_fecha_inicio)
	    SET @ll_dias_sem    = DATEPART(WEEKDAY, @ld_fecha_ref)
	 
	    SET @ll_busqueda = 0
	    IF ((@ll_dias_sem = 6) OR (@ll_dias_sem = 7))
	        SET @ll_busqueda = 1
	    ELSE
	        SELECT  @ll_busqueda    = COUNT(1)
	        FROM    FERIADO
	        WHERE   FECHA   = @ld_fecha_ref
	 
	    IF @ll_busqueda > 0
	        SET @ll_cont    = @ll_cont + 1
        ELSE
            SET @ll_cont1   = @ll_cont1 + 1
	 
	    SET @ll_item    = @ll_item + 1
	        
	END
	 
	--Cálculo Real de la fecha Transcurrida
	SET @ld_fecha_fin_ref   = DATEADD(DAY, (@al_dias_dif + @ll_cont), @ad_fecha_inicio_dt)

END
 
--Retorna Fecha Final Habil
RETURN  @ld_fecha_fin_ref
 
END
GO


-- ----------------------------
-- procedure structure for SP_SYS_ALLSPACE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SYS_ALLSPACE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SYS_ALLSPACE]
GO

CREATE PROCEDURE [dbo].[SP_SYS_ALLSPACE]
-- IMPORTANT! usage info. should be updated before running me.
-- Empty tables are ommitted from the results. 
as

declare @objname varchar(150)        -- The object we want size on.
declare @id    int             -- The object id of @objname.
declare @type    smallint        -- The object type.
declare    @pages    int             -- Working variable for size calc.
declare @dbname varchar(30)
declare @dbsize dec(15,0)

declare @trows dec(15,0)
declare @tall dec(15,0)
declare @tdata dec(15,0)
declare @tidx dec(15,0)
declare @tuu dec(15,0)

declare @srows dec(15,0)
declare @sall dec(15,0)
declare @sdata dec(15,0)
declare @sidx dec(15,0)
declare @suu dec(15,0)

declare @irows dec(15,0)
declare @iall dec(15,0)
declare @idata dec(15,0)
declare @iidx dec(15,0)
declare @iuu dec(15,0)
declare @iname varchar(20)

declare @msg varchar(80)

declare AllTables insensitive cursor
for
select name from sysobjects order by name

open AllTables

/*
** We need to create a temp table to do the calculation.
** reserved: sum(reserved) where indid in (0, 1, 255)
** data: sum(dpages) where indid < 2 + sum(used) where indid = 255 (text)
** indexp: sum(used) where indid in (0, 1, 255) - data
** unused: sum(reserved) - sum(used) where indid in (0, 1, 255)
*/
create table #spt_space
(
    name         varchar(150),
    rows        int null,
    reserved    dec(15) null,
    data        dec(15) null,
    indexp        dec(15) null,
    unused        dec(15) null
)
set nocount on
select getdate()

fetch next from AllTables into @objname

/*
** Insert the row for the table
*/

insert into #spt_space (name,rows,reserved,data,indexp,unused)
        values ('zzUser Table Totals',0,0,0,0,0)
insert into #spt_space (name,rows,reserved,data,indexp,unused)
        values ('zzSystem Table Totals',0,0,0,0,0)

while @@fetch_status = 0
begin

    /*
    ** Find the object.
    */
    select @id = null
    select @id = id, @type = sysstat & 0xf
        from sysobjects
        where id = object_id(@objname)

    /*
    ** See if it's a space object.
    ** types are:
    **    1 - system table
    **    2 - view
    **    3 - user table
    **    4 - sproc
    **    6 - default
    **    7 - rule
    **    8 - trigger
    **    9 - primary key
    **    10 - check constraint
    **    11 - foreign key
    **    12 - replication filter stored proc
    */

    if @type in (1,3)
    begin
        /*
        ** Insert the row for the table
        */
        insert into #spt_space (name)
            values (@objname)
        /*
        ** Now calculate the summary data.
        ** reserved: sum(reserved) where indid in (0, 1, 255)
        */
        /* insert into #spt_space (reserved) */
        select @iall = sum(reserved)
            from sysindexes
            where indid in (0, 1, 255)
                and id = @id
        update #spt_space 
            set reserved = @iall
            where name = @objname
        /* Update Totals */
        if @type = 3 
            update #spt_space
                set reserved = reserved + @iall
                where name = 'zzUser Table Totals'
        else
            update #spt_space
                set reserved = reserved + @iall
                where name = 'zzSystem Table Totals'

        /*
        ** data: sum(dpages) where indid < 2
        **    + sum(used) where indid = 255 (text)
        */
        select @pages = sum(dpages)
            from sysindexes
            where indid < 2 and id = @id

        select @pages = @pages + isnull(sum(used), 0)
            from sysindexes
            where indid = 255 and id = @id
        update #spt_space
            set data = @pages
            where name = @objname
        /* Update Totals */
        if @type = 3 
            update #spt_space
                set data = data + @pages
                where name = 'zzUser Table Totals'
        else
            update #spt_space
                set data = data + @pages
                where name = 'zzSystem Table Totals'
    
    
        /* index: sum(used) where indid in (0, 1, 255) - data */
        select @iidx = sum(used) 
            from sysindexes
            where indid in (0, 1, 255) and id = @id        
        update #spt_space
            set indexp = @iidx - data
            where name = @objname
        /* Update Totals */
        if @type = 3 
            update #spt_space
                set indexp = indexp + (@iidx - data)
                where name = 'zzUser Table Totals'
        else
            update #spt_space
                set indexp = indexp + (@iidx - data)
                where name = 'zzSystem Table Totals'
    

        /* unused: sum(reserved) - sum(used) where indid in (0, 1, 255) */
        update #spt_space
            set unused = reserved - @iidx
            where name = @objname
        /* Update Totals */
        if @type = 3 
            update #spt_space
                set unused = unused + (reserved - @iidx)
                where name = 'zzUser Table Totals'
        else
            update #spt_space
                set unused = unused + (reserved    - @iidx)
                where name = 'zzSystem Table Totals'

        select @irows = i.rows
            from sysindexes i
            where i.indid < 2 and i.id = @id
        update #spt_space
            set rows = @irows
            where name = @objname
        /* Update totals */
        if @type = 3 
            update #spt_space
                set rows = rows + @irows
                where name = 'zzUser Table Totals'
        else
            update #spt_space
                set rows = rows + @irows
                where name = 'zzSystem Table Totals'    
    end
    fetch next from AllTables into @objname
end
/* end while loop here and print out totals */
select 'Table' = substring(#spt_space.name, 1,120 ),
    'Rows' = str(rows,12),
    'Reserved KB' = (str(reserved * d.low / 1024.,15)),
    'Data Space KB' = (str(data * d.low / 1024.,15)),
    'Index Space KB' = (str(indexp * d.low / 1024.,15)),
    'Unused Space KB' = (str(unused * d.low / 1024.,15))
from #spt_space, master.dbo.spt_values d
    where (d.number = 1 and d.type = 'E')
        -- and rows 0 -- do not show empty tables
order by #spt_space.name

close AllTables
deallocate AllTables

return (0)
GO


