-- ----------------------------
-- procedure structure for ELIMINAR_CONSTRAINT_CATALOGO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ELIMINAR_CONSTRAINT_CATALOGO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[ELIMINAR_CONSTRAINT_CATALOGO]
GO

CREATE PROCEDURE [dbo].[ELIMINAR_CONSTRAINT_CATALOGO]
AS

DECLARE @NOMBRE_FOREINGKEY VARCHAR(200)
DECLARE @NOMBRE_TABLE1 VARCHAR(200)
DECLARE @NOMBRE_TABLE2 VARCHAR(200)
DECLARE @ID_FOREINGKEY VARCHAR(200)
DECLARE @CADENASQL NVARCHAR(100)

DECLARE CUR_TABLAS_CAMPOS_CATALOGO CURSOR FOR
SELECT NOMBRE_CLAVE_FORANEA.NAME, NOMBRE_CLAVE_FORANEA.ID, TABLA_F.NAME, TABLA_R.NAME 
FROM SYSFOREIGNKEYS CLAVES_FORANEAS 
INNER JOIN SYSCOLUMNS COLUMNA_F
ON CLAVES_FORANEAS.FKEYID = COLUMNA_F.ID
AND CLAVES_FORANEAS.FKEY = COLUMNA_F.COLID 
INNER JOIN SYSCOLUMNS COLUMNA_R
ON CLAVES_FORANEAS.RKEYID = COLUMNA_R.ID
AND CLAVES_FORANEAS.RKEY = COLUMNA_R.COLID 
INNER JOIN SYSOBJECTS TABLA_F
ON  TABLA_F.ID = COLUMNA_F.ID 
INNER JOIN SYSOBJECTS TABLA_R
ON  TABLA_R.ID = COLUMNA_R.ID 
INNER JOIN SYSOBJECTS NOMBRE_CLAVE_FORANEA
ON CLAVES_FORANEAS.CONSTID = NOMBRE_CLAVE_FORANEA.ID
WHERE ((COLUMNA_R.NAME = 'ITEM_BIEN' AND TABLA_R.NAME <> 'CATALOGO_BIEN_SERV')
OR (TABLA_F.NAME <> 'CATALOGO_BIEN_SERV' AND COLUMNA_F.NAME = 'ITEM_BIEN'))
AND 
(COLUMNA_F.ID NOT IN (
	SELECT COLUMNAS_AD.ID
	FROM SYSCOLUMNS COLUMNAS_AD INNER JOIN SYSFOREIGNKEYS FORANEA_AD
	ON FORANEA_AD.FKEYID = COLUMNAS_AD.ID
	AND FORANEA_AD.FKEY = COLUMNAS_AD.COLID 
	WHERE COLUMNAS_AD.NAME = 'SEC_EJEC'
	AND COLUMNAS_AD.ID = CLAVES_FORANEAS.FKEYID 
	AND FORANEA_AD.CONSTID = CLAVES_FORANEAS.CONSTID
	)
)
AND 
(COLUMNA_R.ID NOT IN (
	SELECT COLUMNAS_AD.ID
	FROM SYSCOLUMNS COLUMNAS_AD INNER JOIN SYSFOREIGNKEYS FORANEA_AD
	ON FORANEA_AD.RKEYID = COLUMNAS_AD.ID
	AND FORANEA_AD.RKEY = COLUMNAS_AD.COLID 
	WHERE COLUMNAS_AD.NAME = 'SEC_EJEC'
	AND COLUMNAS_AD.ID = CLAVES_FORANEAS.RKEYID 
	AND FORANEA_AD.CONSTID = CLAVES_FORANEAS.CONSTID
	)
)

OPEN CUR_TABLAS_CAMPOS_CATALOGO
FETCH CUR_TABLAS_CAMPOS_CATALOGO INTO @NOMBRE_FOREINGKEY, @ID_FOREINGKEY, @NOMBRE_TABLE1, @NOMBRE_TABLE2

WHILE @@FETCH_STATUS = 0
BEGIN
	SET @CADENASQL = 'ALTER TABLE ' + @NOMBRE_TABLE1 + ' DROP CONSTRAINT ' + @NOMBRE_FOREINGKEY
	EXEC SP_EXECUTESQL  @CADENASQL

	FETCH NEXT FROM CUR_TABLAS_CAMPOS_CATALOGO INTO @NOMBRE_FOREINGKEY, @ID_FOREINGKEY, @NOMBRE_TABLE1, @NOMBRE_TABLE2
END
CLOSE CUR_TABLAS_CAMPOS_CATALOGO
DEALLOCATE CUR_TABLAS_CAMPOS_CATALOGO;
--/
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_PROGRAMACION_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_PROGRAMACION_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_PROGRAMACION_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_PROGRAMACION_TRX]
   (@P_ANO_EJE          NUMERIC(4,0),
    @P_SEC_EJEC         NUMERIC(6,0),
    @fecha_carga_inicio VARCHAR(10),
    @fecha_carga_fin    VARCHAR(10),
    @usuario_n          VARCHAR(10),
    @n_fase             NUMERIC(6,0),
    @O_ERR_NUM       	NUMERIC(6,0) OUTPUT ,
    @O_ERR_MSG       	VARCHAR(255) OUTPUT) 
AS
 DECLARE 
   	@ln_estrategia   	VARCHAR (4) 	,
  	@ln_fUNCION 		VARCHAR (2) 	,
   	@ln_PROGRAMA 		VARCHAR (3) 	,
   	@ln_SUB_PROGRAMA	VARCHAR (4) 	,
   	@ln_ACT_PROY		VARCHAR (7) 	,
   	@ln_COMPONENTE 		VARCHAR (7) 	,
   	@ln_meta			VARCHAR (5) 	,
   	@ln_d_meta			VARCHAR (200) 	,
   	@ln_UNIDAD_MEDIDA	VARCHAR (3) 	,
   	@ln_d_unidad_medida	VARCHAR (100) 	,
   	@ln_SEC_FUNC_prop 	NUMERIC (4) 	,
   	@ln_FINALIDAD		VARCHAR (10) 	,
   	@ln_d_finalidad		VARCHAR(250) ,
   	@ln_SUB_FINALIDAD  	VARCHAR (7)    	,
   	@ln_d_subfinalidad 	VARCHAR (200) 	,
   	@ln_SEDE  			NUMERIC (3) 	,
   	@ln_NOMBRE_SEDE 	VARCHAR (50) 	,
   	@ln_COD_ESTABLEC  	NUMERIC (6) 	,
   	@ln_DESC_ESTABLEC 	VARCHAR (200) 	,
   	@ln_CATEGORIA 		NUMERIC (2) 	,
   	@ln_D_CATEGORIA 	VARCHAR (50) 	,
   	@ln_NOMBRE_CORTO 	VARCHAR (20) 	,
   	@ln_MONTO_TOTAL  	NUMERIC (19,2)	,
   	@ln_CANTIDAD 		NUMERIC (20,3) 	,
    @ln_date_fecha_ini 	DATETIME,
    @LN_ID_SI_PROGRAMACION NUMERIC (6),
    @ln_date_fecha_fin 	DATETIME
   BEGIN 

    DELETE FROM SI_PROGRAMACION_ID_KIT_TRX
    DELETE FROM SI_PROGRAMACION_DETA_TRX
    DELETE FROM SI_PROGRAMACION_TRX
    
    SET @ln_date_fecha_ini= convert (datetime,@fecha_carga_inicio,111 )
     SET @ln_date_fecha_fin= convert (datetime,@fecha_carga_fin,111 )

DECLARE C_1 CURSOR FOR    
  
     SELECT MPF.PROGRAMA_INSTITUCIONAL as estrategia_nacional ,MPF.FUNCION , MPF.PROGRAMA , MPF.SUB_PROGRAMA ,
          MPF.ACT_PROY ,  MPF.COMPONENTE ,  MPF.SEC_FUNC_PROP as meta, mpf.nombre as d_meta,     mpf.UNIDAD_MEDIDA ,    u.nombre as d_unidad_medida,
            MPF.SEC_FUNC_prop ,MPF.FINALIDAD, FINA.NOMBRE as d_finalidad,METXSUF.SUB_FINALIDAD , SUBFINA.NOMBRE as d_subfinalidad , 
            CSD.SEDE ,      DSD.NOMBRE_SEDE , CSD.COD_ESTABLEC ,  EESS.DESC_ESTABLEC,            EESS.CATEGORIA ,   CAT.NOMBRE AS D_CATEGORIA ,
            CAT.NOMBRE_CORTO, sum(DET.MNTO_TOTAL) AS MONTO_TOTAL, METXSUF.CANTIDAD    
    
       FROM SIG_META_PROPUESTA MPF 
	     JOIN sig_ppr_metfis_x_subfin METXSUF ON
	        (METXSUF.ANO_EJE       = MPF.ANO_EJE 
	     AND METXSUF.SEC_EJEC      = MPF.SEC_EJEC 
	     AND METXSUF.NRO_FASE      = @n_fase
	     AND METXSUF.SEC_FUNC      = MPF.SEC_FUNC_PROP )
	     JOIN SIG_SUB_FINALIDAD SUBFINA ON
	        (SUBFINA.ANO_EJE                = MPF.ANO_EJE
	     AND SUBFINA.SUB_FINALIDAD          = METXSUF.SUB_FINALIDAD
	     AND SUBFINA.PROGRAMA_INSTITUCIONAL = MPF.PROGRAMA_INSTITUCIONAL) 
	     JOIN SIG_PPR_SEDE CSD ON 
	        (MPF.ANO_EJE      = CSD.ANO_EJE 
	     AND MPF.SEC_EJEC     = CSD.SEC_EJEC 
	     AND CSD.SEC_ESTABLEC = METXSUF.SEC_ESTABLEC ) 
	     JOIN SIG_SEDES DSD ON 
	        (DSD.SEDE   = CSD.SEDE 
	     AND DSD.PLIEGO = CSD.PLIEGO ) 
	     JOIN SIG_PPR_ESTABLECIMIENTO EESS ON
	        (EESS.ANO_EJE      = CSD.ANO_EJE
	     AND EESS.SEC_EJEC     = CSD.SEC_EJEC
	     AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC) 
	     JOIN FINALIDAD_fase FINA ON
	      ( fina.FASE_CUADRO = METXSUF.NRO_FASE and FINA.FINALIDAD   = MPF.FINALIDAD  AND FINA.ANO_EJE = MPF.ANO_EJE )
         	    JOIN SIG_CENTRO_COSTO CC ON
	        (CC.ANO_EJE  = CSD.ANO_EJE
	     AND CC.SEC_EJEC = CSD.SEC_EJEC
	     AND CC.SEDE     = CSD.SEDE
	     AND CC.PLIEGO   = CSD.PLIEGO) LEFT OUTER
	    JOIN SIG_CUADRO_NECESIDAD CAB ON
	        (MPF.ANO_EJE           = CAB.ANO_EJE
	     AND MPF.SEC_EJEC          = CAB.SEC_EJEC
	     AND MPF.SEC_FUNC_PROP     = CAB.SEC_FUNC_PROP 
	     AND METXSUF.SUB_FINALIDAD = CAB.SUB_FINALIDAD 
	     AND METXSUF.SEC_ESTABLEC  = CAB.SEC_ESTABLEC
	     AND CC.CENTRO_COSTO = CAB.CENTRO_COSTO) LEFT OUTER
	    JOIN SIG_CUADRO_NECESIDAD_DET DET ON 
	        (DET.ANO_EJE      = CAB.ANO_EJE
	     AND DET.SEC_EJEC     = CAB.SEC_EJEC
	     AND DET.CENTRO_COSTO = CAB.CENTRO_COSTO
	     AND DET.SECUENCIA    = CAB.SECUENCIA
	     AND DET.FASE_CUADRO  = CAB.FASE_CUADRO
	     AND DET.ESTADO_ITEM_KIT = 'A' ) LEFT OUTER
	    JOIN CATALOGO_BIEN_SERV CBS ON
	        (CBS.SEC_EJEC     = MPF.SEC_EJEC 
	     AND CBS.TIPO_BIEN    = DET.TIPO_BIEN
	     AND CBS.GRUPO_BIEN   = DET.GRUPO_BIEN
	     AND CBS.CLASE_BIEN   = DET.CLASE_BIEN
	     AND CBS.FAMILIA_BIEN = DET.FAMILIA_BIEN
	     AND CBS.ITEM_BIEN    = DET.ITEM_BIEN)
	 	     LEFT JOIN UNIDAD_MEDIDA U ON
	     ( mpf.UNIDAD_MEDIDA = U.UNIDAD_MEDIDA )
	     LEFT JOIN SIG_PPR_CATEGORIA CAT ON 
	     (METXSUF.ANO_EJE = cat.ano_eje
	     and EESS.CATEGORIA = cat.CATEGORIA) 
	      AND @n_fase <  5
	   WHERE MPF.ANO_EJE = @P_ANO_EJE
	      AND MPF.SEC_EJEC= @P_SEC_EJEC
	      AND MPF.FLAG_ESTRATEGIA = 'S' 
 	      GROUP BY MPF.PROGRAMA_INSTITUCIONAL ,MPF.FUNCION , MPF.PROGRAMA , MPF.SUB_PROGRAMA ,
            MPF.ACT_PROY ,  MPF.COMPONENTE ,  MPF.SEC_FUNC_PROP , mpf.nombre ,     mpf.UNIDAD_MEDIDA ,    u.nombre ,
            MPF.SEC_FUNC_prop ,MPF.FINALIDAD, FINA.NOMBRE ,METXSUF.SUB_FINALIDAD , SUBFINA.NOMBRE  , 
            CSD.SEDE ,      DSD.NOMBRE_SEDE , CSD.COD_ESTABLEC ,  EESS.DESC_ESTABLEC,            EESS.CATEGORIA ,   CAT.NOMBRE  ,
            CAT.NOMBRE_CORTO,  METXSUF.CANTIDAD  
            HAVING sum(DET.MNTO_TOTAL) >0
	UNION 
         SELECT MPF.PROGRAMA_INSTITUCIONAL as estrategia_nacional ,MPF.FUNCION , MPF.PROGRAMA , MPF.SUB_PROGRAMA ,
          MPF.ACT_PROY ,  MPF.COMPONENTE ,  MPF.SEC_FUNC as meta, mpf.nombre as d_meta,     mpf.UNIDAD_MEDIDA ,    u.nombre as d_unidad_medida,
            MPF.SEC_FUNC ,MPF.FINALIDAD, FINA.NOMBRE as d_finalidad,METXSUF.SUB_FINALIDAD , SUBFINA.NOMBRE as d_subfinalidad , 
            CSD.SEDE ,      DSD.NOMBRE_SEDE , CSD.COD_ESTABLEC ,  EESS.DESC_ESTABLEC,            EESS.CATEGORIA ,   CAT.NOMBRE AS D_CATEGORIA ,
            CAT.NOMBRE_CORTO, sum(DET.MNTO_TOTAL) AS MONTO_TOTAL, METXSUF.CANTIDAD    
      FROM META MPF 
	     JOIN sig_ppr_metfis_x_subfin METXSUF ON
	        (METXSUF.ANO_EJE       = MPF.ANO_EJE 
	     AND METXSUF.SEC_EJEC      = MPF.SEC_EJEC 
	     AND METXSUF.NRO_FASE      = @n_fase
	     AND METXSUF.SEC_FUNC      = MPF.SEC_FUNC )
	     JOIN SIG_SUB_FINALIDAD SUBFINA ON
	        (SUBFINA.ANO_EJE                = MPF.ANO_EJE
	     AND SUBFINA.SUB_FINALIDAD          = METXSUF.SUB_FINALIDAD
	     AND SUBFINA.PROGRAMA_INSTITUCIONAL = MPF.PROGRAMA_INSTITUCIONAL) 
	     JOIN SIG_PPR_SEDE CSD ON 
	        (MPF.ANO_EJE      = CSD.ANO_EJE 
	     AND MPF.SEC_EJEC     = CSD.SEC_EJEC 
	     AND CSD.SEC_ESTABLEC = METXSUF.SEC_ESTABLEC ) 
	     JOIN SIG_SEDES DSD ON 
	        (DSD.SEDE   = CSD.SEDE 
	     AND DSD.PLIEGO = CSD.PLIEGO ) 
	     JOIN SIG_PPR_ESTABLECIMIENTO EESS ON
	        (EESS.ANO_EJE      = CSD.ANO_EJE
	     AND EESS.SEC_EJEC     = CSD.SEC_EJEC
	     AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC) 
	     JOIN FINALIDAD FINA ON
	      (  FINA.FINALIDAD   = MPF.FINALIDAD  AND FINA.ANO_EJE = MPF.ANO_EJE  AND FINA.estado='A')
         	    JOIN SIG_CENTRO_COSTO CC ON
	        (CC.ANO_EJE  = CSD.ANO_EJE
	     AND CC.SEC_EJEC = CSD.SEC_EJEC
	     AND CC.SEDE     = CSD.SEDE
	     AND CC.PLIEGO   = CSD.PLIEGO) LEFT OUTER
	    JOIN SIG_CUADRO_NECESIDAD CAB ON
	        (MPF.ANO_EJE           = CAB.ANO_EJE
	     AND MPF.SEC_EJEC          = CAB.SEC_EJEC
	     AND MPF.SEC_FUNC     = CAB.SEC_FUNC 
	     AND METXSUF.SUB_FINALIDAD = CAB.SUB_FINALIDAD 
	     AND METXSUF.SEC_ESTABLEC  = CAB.SEC_ESTABLEC
	     AND CC.CENTRO_COSTO = CAB.CENTRO_COSTO) LEFT OUTER
	    JOIN SIG_CUADRO_NECESIDAD_DET DET ON 
	        (DET.ANO_EJE      = CAB.ANO_EJE
	     AND DET.SEC_EJEC     = CAB.SEC_EJEC
	     AND DET.CENTRO_COSTO = CAB.CENTRO_COSTO
	     AND DET.SECUENCIA    = CAB.SECUENCIA
	     AND DET.FASE_CUADRO  = CAB.FASE_CUADRO
	     AND DET.ESTADO_ITEM_KIT = 'A' ) LEFT OUTER
	    JOIN CATALOGO_BIEN_SERV CBS ON
	        (CBS.SEC_EJEC     = MPF.SEC_EJEC 
	     AND CBS.TIPO_BIEN    = DET.TIPO_BIEN
	     AND CBS.GRUPO_BIEN   = DET.GRUPO_BIEN
	     AND CBS.CLASE_BIEN   = DET.CLASE_BIEN
	     AND CBS.FAMILIA_BIEN = DET.FAMILIA_BIEN
	     AND CBS.ITEM_BIEN    = DET.ITEM_BIEN)
	 	     LEFT JOIN UNIDAD_MEDIDA U ON
	     ( mpf.UNIDAD_MEDIDA = U.UNIDAD_MEDIDA )
	     LEFT JOIN SIG_PPR_CATEGORIA CAT ON 
	     (METXSUF.ANO_EJE = cat.ano_eje
	     and EESS.CATEGORIA = cat.CATEGORIA) 
	       AND @n_fase =5
	   WHERE MPF.ANO_EJE = @P_ANO_EJE
	      AND MPF.SEC_EJEC= @P_SEC_EJEC
	      AND MPF.FLAG_ESTRATEGIA = 'S' 
 	      GROUP BY MPF.PROGRAMA_INSTITUCIONAL ,MPF.FUNCION , MPF.PROGRAMA , MPF.SUB_PROGRAMA ,
            MPF.ACT_PROY ,  MPF.COMPONENTE ,  MPF.SEC_FUNC, mpf.nombre ,     mpf.UNIDAD_MEDIDA ,    u.nombre ,
            MPF.SEC_FUNC ,MPF.FINALIDAD, FINA.NOMBRE ,METXSUF.SUB_FINALIDAD , SUBFINA.NOMBRE  , 
            CSD.SEDE ,      DSD.NOMBRE_SEDE , CSD.COD_ESTABLEC ,  EESS.DESC_ESTABLEC,            EESS.CATEGORIA ,   CAT.NOMBRE  ,
            CAT.NOMBRE_CORTO,  METXSUF.CANTIDAD  
            HAVING sum(DET.MNTO_TOTAL) >0
  
         OPEN C_1 
        FETCH NEXT FROM C_1 INTO 	@ln_estrategia,	@ln_fUNCION ,		@ln_PROGRAMA,		@ln_SUB_PROGRAMA, 	@ln_ACT_PROY,  	@ln_COMPONENTE ,	@ln_meta,
   									@ln_d_meta,		@ln_UNIDAD_MEDIDA,	@ln_d_unidad_medida,@ln_SEC_FUNC_prop , @ln_FINALIDAD,	@ln_d_finalidad,   	@ln_SUB_FINALIDAD,
								   	@ln_d_subfinalidad,@ln_SEDE,		@ln_NOMBRE_SEDE,	@ln_COD_ESTABLEC,	@ln_DESC_ESTABLEC,@ln_CATEGORIA,   	@ln_D_CATEGORIA,
								   	@ln_NOMBRE_CORTO,@ln_MONTO_TOTAL,  	@ln_CANTIDAD  
        WHILE @@FETCH_STATUS = 0
	   	BEGIN        
             
        INSERT INTO SI_PROGRAMACION_TRX
        ( ANO_EJE,      	SEC_EJEC,				NRO_FASE,		ESTRATEGIA_NACIONAL,	FUNCION,				PROGRAMA,		 		SUB_PROGRAMA,
          ACT_PROY,     	COMPONENTE,         	META,          	D_META, 				UNIDAD_MEDIDA_META, 	D_UNIDAD_MEDIDA_META,  	SEC_FUNC, 		 	FINALIDAD,
          D_FINALIDAD,  	SUB_FINALIDAD,    		D_SUB_FINALIDAD,SEDE,        			D_SEDE,            		COD_ESTABLEC,  	        D_COD_ESTABLEC,		COD_CATEGORIA,  
          D_COD_CATEGORIA,	D_CORTO_COD_CATEGORIA,	MONTO,          CANTIDAD,     			FECHA_CARGA_INICIO,   	FECHA_CARGA_FIN,       	FECHA_ENVIO,   		USUARIO_ENVIO  )
       VALUES(
          @P_ANO_EJE,	 	@P_SEC_EJEC, 			@n_fase,	   	@ln_estrategia,		  	@ln_fUNCION,			@ln_PROGRAMA,		   	@ln_SUB_PROGRAMA,
 		  @ln_ACT_PROY,	   	@ln_COMPONENTE,		   	@ln_meta,   	@ln_d_meta,			   	@ln_UNIDAD_MEDIDA,   	@ln_d_unidad_medida,   	@ln_SEC_FUNC_prop ,	@ln_FINALIDAD,
		  @ln_d_finalidad,	@ln_SUB_FINALIDAD,   	@ln_d_subfinalidad,@ln_SEDE,			@ln_NOMBRE_SEDE,	   	@ln_COD_ESTABLEC,   	@ln_DESC_ESTABLEC, 	@ln_CATEGORIA,
   		  @ln_D_CATEGORIA,	@ln_NOMBRE_CORTO,	  	@ln_MONTO_TOTAL,@ln_CANTIDAD,			@ln_date_fecha_ini,   	@ln_date_fecha_fin ,    Getdate() , 		@usuario_n)
        
  	
    FETCH NEXT FROM C_1 INTO 	@ln_estrategia,	@ln_fUNCION ,		@ln_PROGRAMA,		@ln_SUB_PROGRAMA, 	@ln_ACT_PROY,  	@ln_COMPONENTE ,	@ln_meta,
   									@ln_d_meta,		@ln_UNIDAD_MEDIDA,	@ln_d_unidad_medida,@ln_SEC_FUNC_prop , @ln_FINALIDAD,	@ln_d_finalidad,   	@ln_SUB_FINALIDAD,
								   	@ln_d_subfinalidad,@ln_SEDE,		@ln_NOMBRE_SEDE,	@ln_COD_ESTABLEC,	@ln_DESC_ESTABLEC,@ln_CATEGORIA,   	@ln_D_CATEGORIA,
								   	@ln_NOMBRE_CORTO,@ln_MONTO_TOTAL,  	@ln_CANTIDAD   
	     END
         CLOSE C_1
         DEALLOCATE C_1
         
 
        DECLARE C_2 CURSOR FOR 
        SELECT DISTINCT meta, ID_SI_PROGRAMACION FROM SI_PROGRAMACION_TRX
        
        OPEN C_2 
        FETCH NEXT FROM C_2 INTO @ln_meta , @LN_ID_SI_PROGRAMACION
        
        WHILE @@FETCH_STATUS = 0
	   	BEGIN  		       
                 SELECT   
               		IDENTITY(INT, 1, 1) AS ID_SI_PROGRAMACION_DETA, CAB.CENTRO_COSTO ,  	CCN.NOMBRE_DEPEND  , 
               		DET.TIPO_BIEN , CAT.CODIGO_ITEM, CAT.NOMBRE_ITEM  ,   CAT.UNIDAD_MEDIDA ,      UNI.NOMBRE  ,	 	DET.PRECIO_UNIT   , 
               		DET.CANT_TOTAL, DET.MNTO_TOTAL , CAB.CLASIFICADOR ,   CAB.ORIGEN        ,       CAB.FUENTE_FINANC,    DET.SECUENCIA     , 	  
               		DET.ITEM_SEC   	 
               	 INTO #tmp_programcion_deta_trx	                                  
		         FROM   SIG_CUADRO_NECESIDAD       CAB,   
		                SIG_CUADRO_NECESIDAD_DET   DET,   
		                CATALOGO_BIEN_SERV         CAT,
		                UNIDAD_MEDIDA              UNI,
		                SIG_CENTRO_COSTO           CCN                                         
		     	WHERE     DET.ANO_EJE       = CAB.ANO_EJE
		              AND DET.SEC_EJEC      = CAB.SEC_EJEC
		              AND DET.CENTRO_COSTO  = CAB.CENTRO_COSTO
		              AND DET.SECUENCIA     = CAB.SECUENCIA
		              AND DET.FASE_CUADRO   = CAB.FASE_CUADRO 
		              AND ( (CAB.SEC_FUNC_PROP = @ln_meta AND @n_fase<5 ) 
		              OR (CAB.SEC_FUNC = @ln_meta AND @n_fase = 5 ))		              
		              AND UNI.UNIDAD_MEDIDA = DET.UNIDAD_MEDIDA 
		              AND CCN.ANO_EJE       = CAB.ANO_EJE 
		              AND CCN.SEC_EJEC      = CAB.SEC_EJEC 
		              AND CCN.CENTRO_COSTO  = CAB.CENTRO_COSTO 
		              AND CCN.ESTADO        = 'A' 
		              AND DET.SEC_EJEC      = CAT.SEC_EJEC
		              AND DET.TIPO_BIEN     = CAT.TIPO_BIEN
		              AND DET.GRUPO_BIEN    = CAT.GRUPO_BIEN
		              AND DET.CLASE_BIEN    = CAT.CLASE_BIEN
		              AND DET.FAMILIA_BIEN  = CAT.FAMILIA_BIEN
		              AND DET.ITEM_BIEN     = CAT.ITEM_BIEN
		              AND CAB.ANO_EJE       = @P_ANO_EJE
		              AND CAB.SEC_EJEC      = @P_SEC_EJEC
		              AND CAB.FASE_CUADRO   = @n_fase
		              AND DET.ESTADO_ITEM_KIT = 'A'
		              
		      
		           
                                                 
                INSERT INTO SI_PROGRAMACION_DETA_TRX (
                    ANO_EJE,     	SEC_EJEC,       ID_SI_PROGRAMACION,   ID_SI_PROGRAMACION_DETA,     CENTRO_COSTO,            D_CENTRO_COSTO, 
                    TIPO_BIEN,   	ITEM_CATALOGO,  D_ITEM_CATALOGO,      UNIDAD_MEDIDA_ITEM_BS,       D_UNIDAD_MEDIDA_ITEM_BS, PRECIO_REF, 
                    CANT_COMPRA, 	PREC_COMPRA,    CLASIFICADOR,         ORIGEN_FUENTE,               FUENTE_FINANC,           FECHA_CARGA_INICIO, 
                    FECHA_CARGA_FIN,FECHA_ENVIO, 	USUARIO_ENVIO,   	  SECUENCIA, 				   ITEM_SEC )                
               SELECT   
               		@P_ANO_EJE,		@P_SEC_EJEC, 	@LN_ID_SI_PROGRAMACION, ID_SI_PROGRAMACION_DETA,    CENTRO_COSTO ,  	NOMBRE_DEPEND  , 
               		TIPO_BIEN , CODIGO_ITEM, NOMBRE_ITEM  ,   UNIDAD_MEDIDA ,          NOMBRE  ,	 	PRECIO_UNIT   , 
               		CANT_TOTAL, MNTO_TOTAL , CLASIFICADOR ,   ORIGEN        ,          FUENTE_FINANC, 	@ln_date_fecha_ini, 
               		@ln_date_fecha_fin,Getdate(),  	 @usuario_n, 		  SECUENCIA     , 	  	   ITEM_SEC   		                                  
		         FROM   #tmp_programcion_deta_trx	
                            
             
                INSERT INTO SI_PROGRAMACION_ID_KIT_TRX
                 (   ANO_EJE,           SEC_EJEC,               ID_SI_PROGRAMACION,    ID_SI_PROGRAMACION_DETA,    ID_ITEM_ID,     
                     ITEM_SEC,          ID_KIT,                 TIPO_CALCULO,          CANTIDAD_UNITARIA,          CANT_TOTAL,            
                     FECHA_CARGA_INICIO,FECHA_CARGA_FIN,        FECHA_ENVIO,           USUARIO_ENVIO  )
                SELECT @P_ANO_EJE         ,@P_SEC_EJEC         , @LN_ID_SI_PROGRAMACION, tmp.ID_SI_PROGRAMACION_DETA , c.ITEM_ID    ,
                       tmp.ITEM_SEC       ,c.ID_KIT            , c.TIPO_CALCULO        , c.CANTIDAD_UNITARIA         , c.CANT_TOTAL ,
                       @ln_date_fecha_ini,@ln_date_fecha_fin    , GETDATE()             , @USUARIO_N
   FROM SIG_CUA_NEC_DET_ID c , #tmp_programcion_deta_trx tmp
                 WHERE c.ANO_EJE      = @P_ANO_EJE 
                   AND c.SEC_EJEC     = @P_SEC_EJEC  
                   AND c.CENTRO_COSTO = tmp.CENTRO_COSTO --@LS_CENTRO_COSTO
                   AND c.SECUENCIA    = tmp.secuencia -- @LN_SECUENCIA 
                   AND c.FASE_CUADRO  = @N_FASE
                   AND c.ITEM_SEC     = tmp.item_sec --@LN_ITEM_SEC
                   AND c.ESTADO       = 'A' 

		 	DROP TABLE #tmp_programcion_deta_trx	
			
         FETCH NEXT FROM C_2 INTO @ln_meta , @LN_ID_SI_PROGRAMACION    
	     END
         CLOSE C_2
         DEALLOCATE C_2
   -- DROP TABLE #tmp_programacion_trx  

END
GO


-- ----------------------------
-- procedure structure for SP_SIG_PROC_CONT_INM
-- ----------------------------
/* procedure [SP_SIG_PROC_CONT_INM] is encrypted */

-- ----------------------------
-- procedure structure for sp_upgraddiagrams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_upgraddiagrams]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[sp_upgraddiagrams]
GO

CREATE PROCEDURE [dbo].[sp_upgraddiagrams]
	AS
	BEGIN
		IF OBJECT_ID(N'dbo.sysdiagrams') IS NOT NULL
			return 0;
	
		CREATE TABLE dbo.sysdiagrams
		(
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
	
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
			(
				principal_id,
				name
			)
		);


		/* Add this if we need to have some form of extended properties for diagrams */
		/*
		IF OBJECT_ID(N'dbo.sysdiagram_properties') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
			(
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
			)
		END
		*/

		IF OBJECT_ID(N'dbo.dtproperties') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
			(
				[name],
				[principal_id],
				[version],
				[definition]
			)
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N'dbo'),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = 'DtgSchemaGUID' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = 'DtgSchemaDATA' and dgdef.[objectid] = dgnm.[objectid]
				
			where dgnm.[property] = 'DtgSchemaNAME' and dggd.[uvalue] like N'_EA3E6268-D998-11CE-9454-00AA00A3F36E_' 
			return 2;
		end
		return 1;
	END
GO


-- ----------------------------
-- procedure structure for SP_INT_TAREA_ESTRATEGICA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_INT_TAREA_ESTRATEGICA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_INT_TAREA_ESTRATEGICA]
GO

CREATE PROCEDURE [dbo].[SP_INT_TAREA_ESTRATEGICA]
(@an_ano_eje numeric(4), @an_sec_eje numeric(6), @retorno NUMERIC(2) OUT)

AS
DECLARE @ls_fase             varchar(1),
        @ls_control          varchar(1),
        @ls_tarea_nivel      varchar(1),
        @ls_tarea_tipo       varchar(1),
        @ls_tarea_grupo      varchar(2),
        @ls_meta_nmb         varchar(150),
        @ls_act_proy         varchar(7),
        @ls_finalidad        varchar(5),
        @ls_finalidad_tipo   varchar(1),
        @ls_finalidad_nmb    varchar(250),
        @ls_subfinalidad     varchar(7),
        @ls_subfinalidad_nmb varchar(200),
        @ls_pi               varchar(6),
        @ld_tarea_gnral      numeric(4),
        @ll_cuenta           numeric(5),
        @ldt_fecha_actual    datetime

--Inicializando Variables
set @ls_tarea_nivel   = 'E'
set @ldt_fecha_actual = GETDATE()

--Recuperando Valor del campo [FLAG_SUBFASE_INT]
EXECUTE sp_int_parametro_ejecutora_anio @an_ano_eje, @an_sec_eje, 'FLAG_SUBFASE_INT', @ls_fase
If @ls_fase = 'x'
   select @ls_fase = '0'

--Recuperando Valor del campo [FLAG_CONTROL_INT]
EXECUTE sp_int_parametro_ejecutora_anio @an_ano_eje, @an_sec_eje, 'FLAG_CONTROL_INT', @ls_control
If @ls_control = 'x'
   select @ls_control = '0'

--Se inicializa la meta estrategica sino esta en movimiento
DELETE FROM sig_tarea_estrategico
 WHERE ano_eje  = @an_ano_eje and
       sec_ejec = @an_sec_eje and
       not exists (SELECT CCT.ano_eje
                     FROM sig_centro_costo_tarea CCT
                    WHERE CCT.ano_eje      = @an_ano_eje    and
                          CCT.sec_ejec     = @an_sec_eje    and
                          CCT.tipo_tarea   = tipo_tarea     and
                          CCT.nivel_tarea  = nivel_tarea    and
                          CCT.codigo_tarea = tarea_general) and
       not exists (SELECT EN.ano_eje
                     FROM estrategia_nacional EN                                left join estrategia_nacional_ejec ENE
                          on EN.ano_eje             = ENE.ano_eje     and EN.fase_cuadro  = ENE.fase_cuadro  and
                             EN.estrategia_nacional = ENE.estrategia_nacional   left join sig_estrategia_parametro EP
                          on EN.ano_eje             = EP.ano_eje      and EN.fase_cuadro  = EP.fase_cuadro   and
                             EN.estrategia_nacional = EP.programa_institucional left join sig_meta_propuesta_fase  MPF
                          on EN.fase_cuadro         = MPF.fase_cuadro and EN.funcion      = MPF.funcion      and
                             EN.programa            = MPF.programa    and EN.sub_programa = MPF.sub_programa and
                             EN.act_proy            = MPF.act_proy    and EN.componente   = MPF.componente   and
                             EN.finalidad           = MPF.finalidad
                    WHERE ENE.ano_eje  = @an_ano_eje and
                          ENE.sec_ejec = @an_sec_eje and
                          ENE.estado   = 'A'         and
                          EN.estado    = 'A'         and
                          EP.estado    = 'A'         and
                          MPF.finalidad              = sig_tarea_estrategico.finalidad  and
                          MPF.programa_institucional = sig_tarea_estrategico.programa_institucional) and
       not exists (SELECT MP.ano_eje
                     FROM sig_meta_propuesta MP
                    WHERE MP.ano_eje   = @an_ano_eje and
                          MP.sec_ejec  = @an_sec_eje and
                          MP.finalidad = finalidad   and
                          MP.programa_institucional = programa_institucional) and
       not exists (SELECT M.ano_eje
                     FROM meta M
                    WHERE M.ano_eje   = @an_ano_eje and
                          M.sec_ejec  = @an_sec_eje and
                          M.finalidad = finalidad   and
                          M.programa_institucional = programa_institucional)

If @@ERROR < 0
   Return -55

--Se inicializa Tareas
DELETE FROM sig_tarea
 WHERE ano_eje     = @an_ano_eje     and
       sec_ejec    = @an_sec_eje     and
       nivel_tarea = @ls_tarea_nivel and
       not exists (SELECT TE.ano_eje
                     FROM sig_tarea_estrategico TE
                    WHERE TE.ano_eje       = @an_ano_eje and
                          TE.sec_ejec      = @an_sec_eje and
                          TE.tipo_tarea    = tipo_tarea  and
                          TE.nivel_tarea   = nivel_tarea and
                          TE.tarea_general = tarea_general)

If @@ERROR < 0
   Return -56

--Se genera las tareas por cada meta estrategica
--Obs: Solo procesa las metas que no tienen tarea
DECLARE c_estrategia CURSOR FOR
SELECT DISTINCT
       MPF.act_proy,
       MPF.finalidad,
       SF.sub_finalidad, '1',
       SF.nombre,
       MPF.programa_institucional,
       F.nombre
  FROM sig_meta_propuesta_fase MPF                                 left join finalidad F
       on MPF.ano_eje = F.ano_eje  and MPF.finalidad = F.finalidad left join sig_sub_finalidad SF
       on MPF.ano_eje = SF.ano_eje and MPF.finalidad = SF.finalidad
 WHERE MPF.ano_eje  = @an_ano_eje and
       MPF.sec_ejec = @an_sec_eje and
       (MPF.fase_cuadro = @ls_fase and @ls_control = '0')     and
       MPF.flag_estrategia        = 'S'                       and
       MPF.programa_institucional = SF.programa_institucional and
       not exists (SELECT ano_eje
                     FROM sig_tarea_estrategico
                    WHERE ano_eje      = @an_ano_eje   and
                          sec_ejec     = @an_sec_eje   and
                          finalidad    = MPF.finalidad and
                          programa_institucional = MPF.programa_institucional and
                          subfinalidad = SF.sub_finalidad)
ORDER BY 2,3,6

--
OPEN c_estrategia
FETCH NEXT FROM c_estrategia
INTO @ls_act_proy, @ls_finalidad, @ls_subfinalidad, @ls_finalidad_tipo, @ls_subfinalidad_nmb, @ls_pi, @ls_finalidad_nmb

WHILE @@FETCH_STATUS = 0
BEGIN
     If (@ls_finalidad_tipo = '0')
        set @ls_subfinalidad = null
     
     --Grupo de Tarea Actividad
     set @ls_tarea_grupo = '02'
     set @ls_tarea_tipo  = '1'
     set @ls_tarea_nivel = 'E'
     set @ld_tarea_gnral = null
     
     --Grupo de Tarea Proyecto
     If (substring(@ls_act_proy,1,1) = '2')
        BEGIN
             set @ls_tarea_grupo = '03'
             set @ls_tarea_tipo  = '2'
        END
     
     SELECT @ll_cuenta = count(*)
       FROM sig_tarea
      WHERE ano_eje     = @an_ano_eje     and
            sec_ejec    = @an_sec_eje     and
            tipo_tarea  = @ls_tarea_tipo  and
            nivel_tarea = @ls_tarea_nivel and
            exists (SELECT ano_eje
                      FROM sig_tarea_estrategico TE
                     WHERE TE.ano_eje       = @an_ano_eje     and
                           TE.sec_ejec      = @an_sec_eje     and
                           TE.tipo_tarea    = tipo_tarea      and
                           TE.nivel_tarea   = nivel_tarea     and
                           TE.tarea_general = tarea_general   and
                           TE.finalidad     = @ls_finalidad   and
                           TE.programa_institucional = @ls_pi and
                           TE.subfinalidad  = @ls_subfinalidad)
     
     If (@ll_cuenta > 0)
        set @ll_cuenta = @ll_cuenta
     Else
        BEGIN
             SELECT @ld_tarea_gnral = coalesce(max(tarea_general),0)+1
               FROM sig_tarea
              WHERE ano_eje     = @an_ano_eje and
                    sec_ejec    = @an_sec_eje and
                    nivel_tarea = @ls_tarea_nivel
             
             set @ls_meta_nmb = substring(@ls_pi+'-'+@ls_subfinalidad+'-'+@ls_subfinalidad_nmb, 1, 150)
             
             INSERT INTO sig_tarea
                         (ano_eje, sec_ejec, tipo_tarea, nivel_tarea, tarea_general, nombre,
                          grupo_tarea, estado, fecha_reg, cuser_id, tipo_ppto, tipo_uso, sec_ejec2,
                          orden_tarea, tipo_tarea_pad, nivel_tarea_pad, tarea_general_pad, tipo_meta)
                  VALUES (@an_ano_eje, @an_sec_eje, @ls_tarea_tipo, @ls_tarea_nivel, @ld_tarea_gnral,
                          @ls_meta_nmb, @ls_tarea_grupo, 'A', @ldt_fecha_actual, 'ADMIN', 1, 'X',
                          null, null , null, null, null, 'E')
             
             If @@ERROR < 0
                BEGIN
                     close c_estrategia
                     DEALLOCATE c_estrategia
                     Return -57
                END
             
             INSERT INTO sig_tarea_estrategico
                         (ano_eje, sec_ejec, tipo_tarea, nivel_tarea, tarea_general,
                          finalidad, programa_institucional, subfinalidad)
                  SELECT DISTINCT
                         @an_ano_eje, @an_sec_eje, @ls_tarea_tipo, @ls_tarea_nivel,
                         @ld_tarea_gnral, @ls_finalidad, @ls_pi, @ls_subfinalidad
                    FROM sig_ejecutora
                   WHERE not exists (SELECT ano_eje
                                       FROM sig_tarea_estrategico
                                      WHERE ano_eje       = @an_ano_eje     and
                                            sec_ejec      = @an_sec_eje     and
                                            tipo_tarea    = @ls_tarea_tipo  and
                                            nivel_tarea   = @ls_tarea_nivel and
                                            tarea_general = @ld_tarea_gnral and
                                            finalidad     = @ls_finalidad   and
                                            programa_institucional = @ls_pi and
                                            subfinalidad  = @ls_subfinalidad)
             
             If @@ERROR < 0
                BEGIN
                     close c_estrategia
                     DEALLOCATE c_estrategia
                     Return -58
                END
        END
        
     FETCH NEXT FROM c_estrategia
     INTO @ls_act_proy, @ls_finalidad, @ls_subfinalidad, @ls_finalidad_tipo, @ls_subfinalidad_nmb, @ls_pi, @ls_finalidad_nmb
END
CLOSE c_estrategia
DEALLOCATE c_estrategia

UPDATE sig_meta_propuesta_fase
   SET flag_estrategia = 'N',
       tipo_estrategia = null,
       tipo_tarea      = null,
       nivel_tarea     = null,
       tarea_general   = null,
       programa_institucional = '0000'
 WHERE ano_eje  = @an_ano_eje and
       sec_ejec = @an_sec_eje and
       (fase_cuadro = @ls_fase and @ls_control = '0') and
       programa_institucional IS NULL

If @@ERROR < 0
   BEGIN
        Return -59
   END

Return 1
GO


-- ----------------------------
-- procedure structure for DT_SETPROPERTYBYID
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_SETPROPERTYBYID]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_SETPROPERTYBYID]
GO

CREATE PROCEDURE [dbo].[DT_SETPROPERTYBYID]
	@id int,
	@property varchar(64),
	@value varchar(255),
	@lvalue image
as
	set nocount on
	declare @uvalue nvarchar(255) 
	set @uvalue = convert(nvarchar(255), @value) 
	if exists (select * from dbo.dtproperties 
			where objectid=@id and property=@property)
	begin
		--
		-- bump the version count for this row as we update it
		--
		update dbo.dtproperties set value=@value, uvalue=@uvalue, lvalue=@lvalue, version=version+1
			where objectid=@id and property=@property
	end
	else
	begin
		--
		-- version count is auto-set to 0 on initial insert
		--
		insert dbo.dtproperties (property, objectid, value, uvalue, lvalue)
			values (@property, @id, @value, @uvalue, @lvalue)
	end
GO


