-- ----------------------------
-- procedure structure for SP_VALIDA_RESPONSABLE_ASIG
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_VALIDA_RESPONSABLE_ASIG]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_VALIDA_RESPONSABLE_ASIG]
GO

CREATE PROCEDURE [dbo].[SP_VALIDA_RESPONSABLE_ASIG] 
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC)
AS
BEGIN

DECLARE @PCENTROCOSTO VARCHAR(15)
DECLARE @ls_centro_padre VARCHAR(10), @ls_flag_presup VARCHAR(10)
DECLARE @nombre_depend VARCHAR(250)
DECLARE @PRETURN NUMERIC

declare cur01 cursor for
SELECT distinct SIG_CENTRO_COSTO.centro_costo
FROM SIG_CENTRO_COSTO, SIG_SEDES, SIG_PERSONAL  
WHERE 
( SIG_CENTRO_COSTO.EMPLEADO = SIG_PERSONAL.EMPLEADO ) and  
( SIG_CENTRO_COSTO.SEC_EJEC = SIG_PERSONAL.SEC_EJEC ) and  
( SIG_SEDES.SEDE = SIG_CENTRO_COSTO.SEDE ) and  
( SIG_CENTRO_COSTO.PLIEGO = SIG_SEDES.PLIEGO ) and  
sig_centro_costo.centro_costo not in 
							( select distinct sig_centro_costo_a.centro_costo  
							from sig_centro_costo sig_centro_costo_a,   
							sig_centro_costo sig_centro_costo_b  
							where
							sig_centro_costo_a.ano_eje = sig_centro_costo_b.ano_eje  and  
							sig_centro_costo_a.sec_ejec = sig_centro_costo_b.sec_ejec  and  
							sig_centro_costo_a.centro_costo = sig_centro_costo_b.centro_padre and  
							sig_centro_costo_a.ano_eje  = @PN_ANIO and  
							sig_centro_costo_a.sec_ejec = @PN_EJEC) and  	
							sig_centro_costo.tipo_depend = '1'  and
							( sig_centro_costo.sec_ejec = @PN_EJEC ) AND  
							( sig_centro_costo.estado like 'A') AND  
							( sig_centro_costo.ano_eje = @PN_ANIO);


open cur01
fetch cur01 into @PCENTROCOSTO


WHILE @@FETCH_STATUS = 0
BEGIN

	SELECT @ls_centro_padre  = ISNULL(CENTRO_PADRE,''),
		   @ls_flag_presup 	 = ISNULL(FLAG_PRESUPUESTO,'N')
	from SIG_CENTRO_COSTO
	where 
	ano_eje 		= @PN_ANIO and
	sec_ejec 		= @PN_EJEC and
	centro_costo 	= @PCENTROCOSTO
		
	--PRINT @ls_flag_presup+'-'+@ls_centro_padre+'-'+@ls_centro_padre 	
	if @ls_flag_presup = 'S'
		BEGIN		
		   IF @ls_centro_padre = '' 
		   		BEGIN
		   			SELECT -1
				   	CLOSE cur01
					DEALLOCATE cur01				   	
				  	RETURN 
			   	END
		   	  
			ELSE
				BEGIN									
					SELECT @ls_centro_padre  = ISNULL(CENTRO_PADRE,'')						   
					from SIG_CENTRO_COSTO
					where 
					ano_eje 		= @PN_ANIO and
					sec_ejec 		= @PN_EJEC and
					centro_costo 	= @ls_centro_padre
				END 

		END

	ELSE
		BEGIN
			SELECT @ls_centro_padre = ISNULL(@PCENTROCOSTO,'')
		END
		
	
	--SELECT @ls_centro_padre = '' 
	IF @ls_centro_padre = '' 
		BEGIN
			SELECT @nombre_depend = ISNULL(nombre_depend,'')
			FROM sig_centro_costo
			WHERE ano_eje 	 = @PN_ANIO AND  
				sec_ejec  	 = @PN_EJEC AND  
				centro_costo = @PCENTROCOSTO
			
			--SELECT @nombre_depend=''
			if @nombre_depend=''
				BEGIN
					SELECT -1
					CLOSE cur01
					DEALLOCATE cur01					
					RETURN 
				END									   									   		
		END
		  	
	  
FETCH cur01 INTO  @PCENTROCOSTO
END
CLOSE cur01
DEALLOCATE cur01

SELECT @PRETURN = 1

SELECT  @PRETURN 

RETURN 
END;--/
GO


-- ----------------------------
-- procedure structure for SP_SIG_ITEM_EXCLUSIVO_SINCRO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_ITEM_EXCLUSIVO_SINCRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_ITEM_EXCLUSIVO_SINCRO]
GO

CREATE PROCEDURE [dbo].[SP_SIG_ITEM_EXCLUSIVO_SINCRO]
AS
BEGIN
	DECLARE
	@ll_ejec_sec NUMERIC(10),
	@ls_sector   VARCHAR(4)

	DECLARE lcur_ejecutora CURSOR
	FOR
	SELECT sec_ejec,
	 	   sector
	  FROM sig_ejecutora
	 WHERE estado = 'A'
	
	OPEN lcur_ejecutora
	
    WHILE 1    = 1
    BEGIN
        FETCH NEXT
         FROM lcur_ejecutora
         INTO @ll_ejec_sec,
              @ls_sector
        
        IF @@FETCH_STATUS <> 0
        BEGIN
            BREAK
        END
        
        DELETE FROM tmp_item_exclusivo
            
        /* inserta los items a los que SI tiene acceso y a los que NO tiene acceso */
        INSERT INTO tmp_item_exclusivo
                    (
					 l_ejec_sec,
					 s_acceso,
					 s_accion,
					 tipo_bien,
					 grupo_bien,
					 clase_bien,
					 familia_bien,
					 item_bien
					)
		SELECT @ll_ejec_sec,
			   'S' AS s_acceso,
			   'B' AS s_accion,
			   catalogo_bien_serv_original.tipo_bien,
			   catalogo_bien_serv_original.grupo_bien,
			   catalogo_bien_serv_original.clase_bien,
			   catalogo_bien_serv_original.familia_bien,
			   catalogo_bien_serv_original.item_bien
		  FROM catalogo_bien_serv_original
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien  = catalogo_bien_serv_original.tipo_bien
                AND sig_catalogo_sector.grupo_bien = catalogo_bien_serv_original.grupo_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 1
           AND (
                (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                 OR
                (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2' )
               )
            
        UNION
        
        SELECT @ll_ejec_sec                            ,
               'S' as s_acceso                         ,
               'B' as s_accion                         ,
               catalogo_bien_serv_original.tipo_bien   ,
               catalogo_bien_serv_original.grupo_bien  ,
               catalogo_bien_serv_original.clase_bien  ,
               catalogo_bien_serv_original.familia_bien,
               catalogo_bien_serv_original.item_bien
          FROM catalogo_bien_serv_original
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien  = catalogo_bien_serv_original.tipo_bien
                AND sig_catalogo_sector.grupo_bien = catalogo_bien_serv_original.grupo_bien
                AND sig_catalogo_sector.clase_bien = catalogo_bien_serv_original.clase_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 2
           AND (
                (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                 OR
                (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2' )
               )
        
        UNION
        
        SELECT @ll_ejec_sec                            ,
               'S' as s_acceso                         ,
               'B' as s_accion                         ,
               catalogo_bien_serv_original.tipo_bien   ,
               catalogo_bien_serv_original.grupo_bien  ,
               catalogo_bien_serv_original.clase_bien  ,
               catalogo_bien_serv_original.familia_bien,
               catalogo_bien_serv_original.item_bien
          FROM catalogo_bien_serv_original
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien    = catalogo_bien_serv_original.tipo_bien
                AND sig_catalogo_sector.grupo_bien   = catalogo_bien_serv_original.grupo_bien
                AND sig_catalogo_sector.clase_bien   = catalogo_bien_serv_original.clase_bien
                AND sig_catalogo_sector.familia_bien = catalogo_bien_serv_original.familia_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 3
           AND (
                (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec and sig_catalogo_sector.flag_entidad = '1')
                 OR
                (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector and sig_catalogo_sector.flag_entidad = '2' )
               )
        
        UNION
        
        SELECT @ll_ejec_sec                            ,
               'S' as s_acceso                         ,
               'B' as s_accion                         ,
               catalogo_bien_serv_original.tipo_bien   ,
               catalogo_bien_serv_original.grupo_bien  ,
               catalogo_bien_serv_original.clase_bien  ,
               catalogo_bien_serv_original.familia_bien,
               catalogo_bien_serv_original.item_bien
          FROM catalogo_bien_serv_original
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien    = catalogo_bien_serv_original.tipo_bien
                AND sig_catalogo_sector.grupo_bien   = catalogo_bien_serv_original.grupo_bien
                AND sig_catalogo_sector.clase_bien   = catalogo_bien_serv_original.clase_bien
                AND sig_catalogo_sector.familia_bien = catalogo_bien_serv_original.familia_bien
                AND sig_catalogo_sector.item_bien    = catalogo_bien_serv_original.item_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 4
           and (
                (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                 OR
                (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2')
               )
        
        UNION
        
        SELECT @ll_ejec_sec                            ,
               'N' as s_acceso                         ,
               'B' as s_accion                         ,
               catalogo_bien_serv_original.tipo_bien   ,
               catalogo_bien_serv_original.grupo_bien  ,
               catalogo_bien_serv_original.clase_bien  ,
               catalogo_bien_serv_original.familia_bien,
               catalogo_bien_serv_original.item_bien
          FROM catalogo_bien_serv_original
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien  = catalogo_bien_serv_original.tipo_bien
