         WHERE sig_catalogo_sector.nivel_catalogo = 1
           AND NOT (
                    (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec and sig_catalogo_sector.flag_entidad = '1')
                     OR
                    (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector and sig_catalogo_sector.flag_entidad = '2')
                   )
         
        UNION
        
        SELECT @ll_ejec_sec                            ,
               'N' as s_acceso                         ,
