         WHERE sig_catalogo_sector.nivel_catalogo = 4
           AND NOT (
                    (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                     OR
