               'N' as s_acceso                ,
               'B' as s_accion                ,
               catalogo_bien_serv.tipo_bien   ,
               catalogo_bien_serv.grupo_bien  ,
               catalogo_bien_serv.clase_bien  ,
               catalogo_bien_serv.familia_bien,
               catalogo_bien_serv.item_bien
          FROM catalogo_bien_serv
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien  = catalogo_bien_serv.tipo_bien
                AND sig_catalogo_sector.grupo_bien = catalogo_bien_serv.grupo_bien
                AND sig_catalogo_sector.clase_bien = catalogo_bien_serv.clase_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 2
           AND NOT (
                    (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                     OR
                    (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2')
                   )
         
        UNION
        
        SELECT @ll_ejec_sec                   ,
               'N' as s_acceso                ,
               'B' as s_accion                ,
               catalogo_bien_serv.tipo_bien   ,
               catalogo_bien_serv.grupo_bien  ,
               catalogo_bien_serv.clase_bien  ,
               catalogo_bien_serv.familia_bien,
               catalogo_bien_serv.item_bien
          FROM catalogo_bien_serv
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien    = catalogo_bien_serv.tipo_bien
                AND sig_catalogo_sector.grupo_bien   = catalogo_bien_serv.grupo_bien
                AND sig_catalogo_sector.clase_bien   = catalogo_bien_serv.clase_bien
                AND sig_catalogo_sector.familia_bien = catalogo_bien_serv.familia_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 3
           AND NOT (
                    (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                     OR
                    (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2')
                   )
        
        UNION
        
        SELECT @ll_ejec_sec                   ,
               'N' as s_acceso                ,
               'B' as s_accion                ,
               catalogo_bien_serv.tipo_bien   ,
               catalogo_bien_serv.grupo_bien  ,
               catalogo_bien_serv.clase_bien  ,
               catalogo_bien_serv.familia_bien,
               catalogo_bien_serv.item_bien
          FROM catalogo_bien_serv
               JOIN sig_catalogo_sector
                 ON sig_catalogo_sector.tipo_bien    = catalogo_bien_serv.tipo_bien
                AND sig_catalogo_sector.grupo_bien   = catalogo_bien_serv.grupo_bien
                AND sig_catalogo_sector.clase_bien   = catalogo_bien_serv.clase_bien
                AND sig_catalogo_sector.familia_bien = catalogo_bien_serv.familia_bien
                AND sig_catalogo_sector.item_bien    = catalogo_bien_serv.item_bien
         WHERE sig_catalogo_sector.nivel_catalogo = 4
           AND NOT (
                    (coalesce(sig_catalogo_sector.sec_ejec, 0) = @ll_ejec_sec AND sig_catalogo_sector.flag_entidad = '1')
                     OR
                    (coalesce(sig_catalogo_sector.sector, '*') = @ls_sector AND sig_catalogo_sector.flag_entidad = '2')
                   )
         
        /* elimina los registros "duplicados" de los items a los que SI tiene acceso */
        DELETE FROM tmp_item_exclusivo
         WHERE s_acceso ='N'
           AND EXISTS (SELECT 1
	                     FROM tmp_item_exclusivo tab_item_permitido
	                    WHERE tab_item_permitido.l_ejec_sec   = tmp_item_exclusivo.l_ejec_sec
	                      AND tab_item_permitido.tipo_bien    = tmp_item_exclusivo.tipo_bien
	                      AND tab_item_permitido.grupo_bien   = tmp_item_exclusivo.grupo_bien
	                      AND tab_item_permitido.clase_bien   = tmp_item_exclusivo.clase_bien
	                      AND tab_item_permitido.familia_bien = tmp_item_exclusivo.familia_bien
	                      AND tab_item_permitido.item_bien    = tmp_item_exclusivo.item_bien
	                      AND tab_item_permitido.s_acceso     = 'S')
        
        /* elimina los items a los que SI tiene acceso */
        DELETE FROM tmp_item_exclusivo
         WHERE s_acceso ='S'
        
        /* marca si tiene o no dependencias, a razon de eso se elimina o desactiva */
        EXEC dbo.SP_SIG_ITEM_EXCLUSIVO_DEPEND @ll_ejec_sec
        
        /* elimina items prohibidos a los que no se tiene acceso */
        DELETE FROM dbo.catalogo_bien_serv_original
         WHERE EXISTS (SELECT 1
	                     FROM tmp_item_exclusivo
	                    WHERE tmp_item_exclusivo.tipo_bien    = catalogo_bien_serv_original.tipo_bien
	                      AND tmp_item_exclusivo.grupo_bien   = catalogo_bien_serv_original.grupo_bien
	                      AND tmp_item_exclusivo.clase_bien   = catalogo_bien_serv_original.clase_bien
	                      AND tmp_item_exclusivo.familia_bien = catalogo_bien_serv_original.familia_bien
	                      AND tmp_item_exclusivo.item_bien    = catalogo_bien_serv_original.item_bien
	                      AND tmp_item_exclusivo.s_accion     = 'B')
        
        /* desactiva items prohibidos a los que no se tiene acceso pero han sido utilizados */
        UPDATE dbo.catalogo_bien_serv_original
           SET estado = 'I'
         WHERE EXISTS (SELECT 1
	                     FROM tmp_item_exclusivo
	                    WHERE tmp_item_exclusivo.tipo_bien    = catalogo_bien_serv_original.tipo_bien
	                      AND tmp_item_exclusivo.grupo_bien   = catalogo_bien_serv_original.grupo_bien
	                      AND tmp_item_exclusivo.clase_bien   = catalogo_bien_serv_original.clase_bien
	                      AND tmp_item_exclusivo.familia_bien = catalogo_bien_serv_original.familia_bien
	                      AND tmp_item_exclusivo.item_bien    = catalogo_bien_serv_original.item_bien
	                      AND tmp_item_exclusivo.s_accion     = 'A')
        
        /* elimina items prohibidos a los que no se tiene acceso */
        DELETE FROM dbo.catalogo_bien_serv
         WHERE EXISTS (SELECT 1
	                     FROM tmp_item_exclusivo
	                    WHERE tmp_item_exclusivo.l_ejec_sec   = catalogo_bien_serv.sec_ejec
	                      AND tmp_item_exclusivo.tipo_bien    = catalogo_bien_serv.tipo_bien
	                      AND tmp_item_exclusivo.grupo_bien   = catalogo_bien_serv.grupo_bien
	                      AND tmp_item_exclusivo.clase_bien   = catalogo_bien_serv.clase_bien
	                      AND tmp_item_exclusivo.familia_bien = catalogo_bien_serv.familia_bien
	                      AND tmp_item_exclusivo.item_bien    = catalogo_bien_serv.item_bien
	                      AND tmp_item_exclusivo.s_accion     = 'B')
        
        /* desactiva items prohibidos a los que no se tiene acceso pero han sido utilizados */
        UPDATE dbo.catalogo_bien_serv
           SET estado = 'I'
         WHERE EXISTS (SELECT 1
	                     FROM tmp_item_exclusivo
	                    WHERE tmp_item_exclusivo.l_ejec_sec   = catalogo_bien_serv.sec_ejec
	                      AND tmp_item_exclusivo.tipo_bien    = catalogo_bien_serv.tipo_bien
	                      AND tmp_item_exclusivo.grupo_bien   = catalogo_bien_serv.grupo_bien
	                      AND tmp_item_exclusivo.clase_bien   = catalogo_bien_serv.clase_bien
	                      AND tmp_item_exclusivo.familia_bien = catalogo_bien_serv.familia_bien
	                      AND tmp_item_exclusivo.item_bien    = catalogo_bien_serv.item_bien
	                      AND tmp_item_exclusivo.s_accion     = 'A') 
	
	END
	
	CLOSE lcur_ejecutora
	
	DEALLOCATE lcur_ejecutora
END
GO


-- ----------------------------
-- procedure structure for DT_WHOCHECKEDOUT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_WHOCHECKEDOUT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_WHOCHECKEDOUT]
GO

CREATE PROCEDURE [dbo].[DT_WHOCHECKEDOUT]
        @chObjectType  char(4),
        @vchObjectName varchar(255),
        @vchLoginName  varchar(255),
        @vchPassword   varchar(255)

as

set nocount on

declare @iReturn int
declare @iObjectId int
select @iObjectId =0

declare @VSSGUID varchar(100)
select @VSSGUID = 'SQLVersionControl.VCS_SQL'

    declare @iPropertyObjectId int

    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    declare @vchProjectName   varchar(255)
    declare @vchSourceSafeINI varchar(255)
    declare @vchServerName    varchar(255)
    declare @vchDatabaseName  varchar(255)
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSProject',       @vchProjectName   OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSourceSafeINI', @vchSourceSafeINI OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLServer',     @vchServerName    OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLDatabase',   @vchDatabaseName  OUT

    if @chObjectType = 'PROC'
    begin
        exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT

        if @iReturn <> 0 GOTO E_OAError

        declare @vchReturnValue varchar(255)
        select @vchReturnValue = ''

        exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
												'WhoCheckedOut',
												@vchReturnValue OUT,
												@sProjectName = @vchProjectName,
												@sSourceSafeINI = @vchSourceSafeINI,
												@sObjectName = @vchObjectName,
												@sServerName = @vchServerName,
												@sDatabaseName = @vchDatabaseName,
												@sLoginName = @vchLoginName,
												@sPassword = @vchPassword

        if @iReturn <> 0 GOTO E_OAError

        select @vchReturnValue

    end

CleanUp:
    return

E_OAError:
    exec dbo.dt_displayoaerror @iObjectId, @iReturn
    GOTO CleanUp
GO


