-- ----------------------------
-- procedure structure for SP_SI_ACTUALIZA_KIT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_ACTUALIZA_KIT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_ACTUALIZA_KIT]
GO

CREATE PROCEDURE [dbo].[SP_SI_ACTUALIZA_KIT] @P_ANO_CN numeric(4, 0), @P_SEC_EJEC numeric(6, 0), @P_FASE_CUADRO numeric(1, 0), @AS_AMBITO VARCHAR(5)
AS
BEGIN
DECLARE @ll_fase NUMERIC(10)
DECLARE @ls_fase VARCHAR(1)
DECLARE @ls_fase_estado VARCHAR(1)

/* INICIO ACTUALIZA EL KIT BASE */
	UPDATE  SI_PPR_KIT_ITEMS 
	    SET TIPO_COSTO_DI			=PK.TIPO_COSTO_DI  		,	TIPO_COSTO_FV		  	  =PK.TIPO_COSTO_FV		,
			TIPO_BIEN				=PK.TIPO_BIEN	   		,	ITEM_BIEN  		   	  	  =PK.ITEM_BIEN  		,
			CLASIFICADOR        	=PK.CLASIFICADOR       	,	AGRUPA_ITEM     	 	  =PK.AGRUPA_ITEM     	        ,
			CANTIDAD_VEZ            =PK.CANTIDAD_VEZ    	,	NRO_VECES                 =PK.NRO_VECES                 ,
			CANTIDAD_CASO           =PK.CANTIDAD_CASO      	,	PORCENT_USO               =PK.PORCENT_USO               ,
			FACTOR_CONVERS          =PK.FACTOR_CONVERS     	,	FACTOR_MERMA              =PK.FACTOR_MERMA              ,
			TIPO_CALCULO            =PK.TIPO_CALCULO       	,	CATEG_I_1                 =PK.CATEG_I_1                 ,
			CATEG_I_2               =PK.CATEG_I_2          	,	CATEG_I_3                 =PK.CATEG_I_3                 ,
			CATEG_I_4               =PK.CATEG_I_4          	,	CATEG_II_1                =PK.CATEG_II_1                ,
			CATEG_II_2              =PK.CATEG_II_2         	,	CATEG_III_1               =PK.CATEG_III_1               ,
			CATEG_III_2             =PK.CATEG_III_2        	,	CATEG_EESS_MOVIL          =PK.CATEG_EESS_MOVIL          ,
			CATEG_DISA              =PK.CATEG_DISA         	,	CATEG_RED                 =PK.CATEG_RED                 ,
			CATEG_MRED              =PK.CATEG_MRED         	,	CATEG_MINSA               =PK.CATEG_MINSA               ,
			CATEG_14                =PK.CATEG_14           	,	CATEG_15                  =PK.CATEG_15                  ,
			CATEG_16                =PK.CATEG_16           	,   CATEG_99                  =PK.CATEG_99              	,
			FLAG_I_1                =PK.FLAG_I_1            ,
			FLAG_I_2                =PK.FLAG_I_2           	,	FLAG_I_3                  =PK.FLAG_I_3                  ,
			FLAG_I_4                =PK.FLAG_I_4           	,	FLAG_II_1                 =PK.FLAG_II_1                 ,
			FLAG_II_2               =PK.FLAG_II_2          	,	FLAG_III_1                =PK.FLAG_III_1                ,
			FLAG_III_2              =PK.FLAG_III_2         	,	FLAG_EESS_MOVIL           =PK.FLAG_EESS_MOVIL           ,
			FLAG_DISA               =PK.FLAG_DISA          	,	FLAG_RED                  =PK.FLAG_RED                  ,
			FLAG_MRED               =PK.FLAG_MRED          	,	FLAG_MINSA                =PK.FLAG_MINSA                ,
			FLAG_14 	        	=PK.FLAG_14 	    	,	FLAG_15	                  =PK.FLAG_15	                ,  
			FLAG_16                 =PK.FLAG_16             ,	FLAG_99                   =PK.FLAG_99         	       ,
			ESPECIFICACION          =PK.ESPECIFICACION      ,
			ACTIVO_FIJO             =PK.ACTIVO        		,	GRUPO_BIEN                =PK.GRUPO_BIEN         	,
			CLASE_BIEN              =PK.CLASE_BIEN          ,   
			FAMILIA_BIEN            =PK.FAMILIA_BIEN       	,	ITEM                      =PK.ITEM                      ,
			ESTADO                  =PK.ESTADO             	,	FECHA_MOD                 =GETDATE()              ,         
			TIPO_COSTO_DIK          =PK.TIPO_COSTO_DIK    	,	UM_USO                    =PK.UM_USO                    ,
			prog_rector             =PK.prog_rector        	,	compl_sustit              =PK.compl_sustit              ,
			ACT_PROY                =PK.ACT_PROY           	,	COMPONENTE                =PK.COMPONENTE                , 
			FINALIDAD               =PK.FINALIDAD          	,	PROGRAMA_INSTITUCIONAL    =PK.PROGRAMA    ,
			NIVEL		   			=PK.NIVEL				,   F_GENERACION			  =PK.F_GENERACION, 
			S_CRITICO 				= PK.S_CRITICO			, 	S_TIPO 						= PK.S_TIPO 				, 
			S_FINANCIA  			= PK.S_FINANCIA 		,S_CLASIFICA = PK.S_CLASIFICA
			
		FROM VProcesaCargaKit PK         
  	WHERE   SI_PPR_KIT_ITEMS.ANO_EJE					=PK.ANO_EJE				  	AND
 			/* SI_PPR_KIT_ITEMS.sub_finalidad 		   		=PK.sub_finalidad			AND */
		   	SI_PPR_KIT_ITEMS.sec_kit       	 			=PK.sec_kit 			   	/*AND
		   	SI_PPR_KIT_ITEMS.id_sub_finalidad			=PK.id_sub_finalidad	  */
/* FIN ACTUALIZA EL KIT BASE */


/* INICIO INSERTA EN EL KIT BASE */
	  
	 INSERT INTO dbo.SI_PPR_KIT_ITEMS
	  (	ANO_EJE,		SUB_FINALIDAD,		ID_SUB_FINALIDAD,	SEC_KIT,   		TIPO_COSTO_DI, 	TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,
		CLASIFICADOR,	AGRUPA_ITEM,		CANTIDAD_VEZ,		NRO_VECES, 		CANTIDAD_CASO, 	PORCENT_USO,		FACTOR_CONVERS,	FACTOR_MERMA,
		TIPO_CALCULO,	CATEG_I_1,			CATEG_I_2,			CATEG_I_3, 		CATEG_I_4,		CATEG_II_1,			CATEG_II_2,		CATEG_III_1,
		CATEG_III_2,	CATEG_EESS_MOVIL,	CATEG_DISA,			CATEG_RED,		CATEG_MRED,		CATEG_MINSA,		CATEG_14,		CATEG_15,
		CATEG_16,	    CATEG_99,			ESPECIFICACION,		ACTIVO_FIJO, 	GRUPO_BIEN,		CLASE_BIEN,		FAMILIA_BIEN,		ITEM,  			ESTADO,	
		TIPO_COSTO_DIK,	UM_USO,				prog_rector,		compl_sustit,	ACT_PROY,		COMPONENTE,			FINALIDAD,		PROGRAMA_INSTITUCIONAL,
		FLAG_I_1, 		FLAG_I_2     	,	FLAG_I_3 ,			FLAG_I_4,		FLAG_II_1,		FLAG_II_2 ,			FLAG_III_1 ,	FLAG_III_2      	,  
		FLAG_EESS_MOVIL,FLAG_DISA  ,		FLAG_RED ,			FLAG_MRED   ,	FLAG_MINSA,		FLAG_14  ,			FLAG_15,  		FLAG_16,
		FLAG_99,		NIVEL,				FECHA_MOD,    		F_GENERACION, 	S_CRITICO  ,	S_TIPO,			S_FINANCIA ,		S_CLASIFICA)
	  SELECT 
		ANO_EJE,		SUB_FINALIDAD,		ID_SUB_FINALIDAD,	SEC_KIT,		TIPO_COSTO_DI, 	TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,
		CLASIFICADOR,	AGRUPA_ITEM,		CANTIDAD_VEZ,		NRO_VECES,		CANTIDAD_CASO,	PORCENT_USO,		FACTOR_CONVERS,	FACTOR_MERMA,
		TIPO_CALCULO,	CATEG_I_1,			CATEG_I_2,			CATEG_I_3,		CATEG_I_4,		CATEG_II_1,			CATEG_II_2,		CATEG_III_1,
		CATEG_III_2,	CATEG_EESS_MOVIL,	CATEG_DISA,			CATEG_RED,		CATEG_MRED,		CATEG_MINSA,		CATEG_14,		CATEG_15,
		CATEG_16,		CATEG_99,			ESPECIFICACION,		ACTIVO, 	   		GRUPO_BIEN,		CLASE_BIEN,		FAMILIA_BIEN,		ITEM,  			ESTADO,	
		TIPO_COSTO_DIK,	UM_USO,				prog_rector,		compl_sustit,	ACT_PROY,		COMPONENTE,			FINALIDAD,		PROGRAMA,
		FLAG_I_1, 		FLAG_I_2     	,	FLAG_I_3 ,			FLAG_I_4,		FLAG_II_1,		FLAG_II_2 ,			FLAG_III_1 ,	FLAG_III_2      	,  
		FLAG_EESS_MOVIL,FLAG_DISA  ,		FLAG_RED ,			FLAG_MRED   ,	FLAG_MINSA,		FLAG_14  ,			FLAG_15,  		FLAG_16,
		FLAG_99,		NIVEL,				GETDATE(),    		F_GENERACION, 		S_CRITICO,  	S_TIPO,			S_FINANCIA,			S_CLASIFICA
	FROM 	VProcesaCargaKit PK
	WHERE 	
			NOT EXISTS (SELECT 1
						  FROM SI_PPR_KIT_ITEMS kit
						 WHERE  KIT.ANO_EJE = PK.ANO_EJE AND
						 		KIT.SEC_KIT = PK.SEC_KIT /*AND
						 		KIT.SUB_FINALIDAD= PK.SUB_FINALIDAD AND
						 		KIT.ID_SUB_FINALIDAD= PK.ID_SUB_FINALIDAD*/ )

/*
FIN  INSERTA EN EL KIT BASE 
INICIO 	INSERTA EN EL KIT X CATEGORIA SI NO EXISTE PARA REGISTRO PARA DICHA CATEGORIA
*/

 	 INSERT INTO SIG_PPR_KIT_ITEMS
				(ANO_EJE,			SEC_EJEC,			   	ID_SUB_FINALIDAD,	CATEGORIA,			SEC_KIT,
				 SECTOR_AMBITO,		FLAG_SUGERIDO,			ESTADO,				FECHA_MOD,			FLAG_RETIRAR  )
	   	 SELECT @P_ANO_CN, 			@P_SEC_EJEC,			ID_SUB_FINALIDAD, 	CATEGORIA,			SEC_KIT,
	   	   		@AS_AMBITO,			FLAG,					'A',				GETDATE(), 			'0'
	   	 FROM VW_KIT_CATEGORIA VKC
		 WHERE 
		 	  NOT EXISTS (SELECT 1 
		  					FROM SIG_PPR_KIT_ITEMS KIT
	 			 			WHERE KIT.ANO_EJE= @P_ANO_CN AND
	 			 				  KIT.SEC_EJEC= @P_SEC_EJEC	AND
	 			 				  KIT.CATEGORIA= VKC.CATEGORIA AND
	 			 				  KIT.SEC_KIT = VKC.SEC_KIT AND
	 			 				  KIT.SECTOR_AMBITO=@AS_AMBITO)
	 			 				  
	 UPDATE SIG_PPR_KIT_ITEMS
	   SET SIG_PPR_KIT_ITEMS.ESTADO = KIT.ESTADO
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS.SEC_EJEC		= @p_Sec_Ejec 						AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS.ID_SUB_FINALIDAD  AND
            KIT.NIVEL= 'I'
	       
/* INICIO 	ACTUALIZA LA CANTIDAD DE AQUELLOS QUE SE ENCUENTRA EN LOS ESTABLECIMIENTOS */
	BEGIN

	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD= (1 + FACTOR_MERMA) * ((CANTIDAD_CASO * PORCENT_USO / 100) / FACTOR_CONVERS)
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD AND
	       KIT.TIPO_CALCULO   	 				= 4			      					AND 
	       KIT.TIPO_BIEN 	   					= 'B'								AND
	       KIT.ESTADO		  					= 'A'								
	       
	
   	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD								= 0
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD		AND
	       (FACTOR_CONVERS = 0  OR  TIPO_CALCULO  <>4)			 			AND 
	       KIT.ESTADO		  					= 'A'	
	
	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD								= 0
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD		AND
	       SIG_PPR_KIT_ITEMS_EST.CANTIDAD		  IS NULL							AND
	       KIT.ESTADO		  					= 'A'	
	       
	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET ESTADO=KIT.ESTADO
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD              AND
           KIT.NIVEL= 'I'
	       
	  update SIG_CUA_NEC_DET_ID
			set estado = 'I'
			where ano_eje = @p_Ano_CN
			  and fase_cuadro = @P_FASE_CUADRO
			  AND sec_ejec= @P_sec_ejec
			  and id_kit in (SELECT KIT.SEC_KIT FROM
			  				SI_PPR_KIT_ITEMS KIT
			  				WHERE KIT.ANO_EJE = @p_Ano_CN AND
			  					  KIT.ESTADO = 'I' AND
			  					  KIT.GRUPO_BIEN= SIG_CUA_NEC_DET_ID.grupo_bien AND
			  					  KIT.CLASE_BIEN= SIG_CUA_NEC_DET_ID.clase_bien AND
			  					  kit.FAMILIA_BIEN= SIG_CUA_NEC_DET_ID.familia_bien AND
			  					  kit.ITEM= SIG_CUA_NEC_DET_ID.item_bien  AND
			  					  KIT.NIVEL= 'I') 
	
   	
	
			update sig_cuadro_necesidad_det
					  set estado_item_kit = 'I',
							mnto_01= 0,				mnto_02= 0,			mnto_03= 0,				mnto_04= 0,
							mnto_05= 0,				mnto_06= 0,			mnto_07= 0,				mnto_08= 0,
							mnto_09= 0,				mnto_10= 0,			mnto_11= 0,				mnto_12= 0,
							mnto_total= 0,			valor_impto= 0,
							CANT_01 = 0, 			CANT_02 = 0, 		CANT_03 = 0, 			CANT_04 = 0, 
							CANT_05 = 0, 			CANT_06 = 0, 		CANT_07 = 0, 			CANT_08 = 0, 
							CANT_09 = 0, 			CANT_10 = 0, 		CANT_11 = 0, 			CANT_12 = 0, 
							CANT_TOTAL = 0
					where exists (select 1 from SIG_CUA_NEC_DET_ID cn_idx
									  where cn_idx.ANO_EJE = sig_cuadro_necesidad_det.ANO_EJE
										 and cn_idx.SEC_EJEC = sig_cuadro_necesidad_det.SEC_EJEC
										 and cn_idx.CENTRO_COSTO = sig_cuadro_necesidad_det.CENTRO_COSTO
										 and cn_idx.SECUENCIA = sig_cuadro_necesidad_det.SECUENCIA
										 and cn_idx.FASE_CUADRO = sig_cuadro_necesidad_det.FASE_CUADRO
										 and cn_idx.ITEM_SEC = sig_cuadro_necesidad_det.ITEM_SEC
										 and cn_idx.estado = 'I'
										                                         )
              and not exists (select 1 from SIG_CUA_NEC_DET_ID cn_idy
									  where cn_idy.ANO_EJE = sig_cuadro_necesidad_det.ANO_EJE
										 and cn_idy.SEC_EJEC = sig_cuadro_necesidad_det.SEC_EJEC
										 and cn_idy.CENTRO_COSTO = sig_cuadro_necesidad_det.CENTRO_COSTO
										 and cn_idy.SECUENCIA = sig_cuadro_necesidad_det.SECUENCIA
										 and cn_idy.FASE_CUADRO = sig_cuadro_necesidad_det.FASE_CUADRO
										 and cn_idy.ITEM_SEC = sig_cuadro_necesidad_det.ITEM_SEC
										 and cn_idy.estado = 'A'
																			     )
					and ano_eje 	=@p_Ano_CN
					and fase_cuadro = @P_FASE_CUADRO   
				  AND sec_ejec= @P_sec_ejec
    END
  /* FIN 	ACTUALIZA LA CANTIDAD DE AQUELLOS QUE SE ENCUENTRA EN LOS ESTABLECIMIENTOS	 */
	 			 				  
/*
***********************************************************************	
INICIO DEL PROCESO DE ACTUALIZACION DEL CATALOGO
************************************************************************	
*/
/* Inserte en el catálogo institucional */
INSERT INTO CATALOGO_BIEN_SERV ( 
		 SEC_EJEC,							TIPO_BIEN,							GRUPO_BIEN,							CLASE_BIEN,						FAMILIA_BIEN,		
		 ITEM_BIEN,							NOMBRE_ITEM,						FLAG_ACTIVO,						TIPO_ACTIVO,					UNIDAD_ADQUIS,
		 FACTOR_UNIDAD,					UNIDAD_MEDIDA,						PRESENTACION,						COND_ALMAC,						MARCA_REF,
		 PRECIO_REF,						FECHA_REF,							PRECIO_COMPRA,						FECHA_COMPRA,					ITEM_CRITICO,
		 FLAG_ITEM,							PRECIO_DOLAR,						STOCK_MINIMO,						STOCK_MAXIMO,					ESTADO,
		 FECHA_ALTA,						FECHA_ACT,							BOLSA_PRODUCTO,					CUSER_ID,						PAIS,
		 FLAG_VISUALIZA,					ENVIADO,								FLAG_UNIDADES,						TIPO_MARCA,						FLAG_SUBASTA_INVERSA,
		 FLAG_MARCO_PRECIO,				FLAG_ESTADO,						GRUPO_BIEN_PADRE,					CLASE_BIEN_PADRE,				FAMILIA_BIEN_PADRE,
		 ITEM_BIEN_PADRE,					CODIGO_ONU,							CODIGO_ITEM,						ESTADO_MEF )
SELECT DISTINCT 
        @P_SEC_EJEC,					CAT_MEF.TIPO_BIEN,        		CAT_MEF.GRUPO_BIEN,           CAT_MEF.CLASE_BIEN,        CAT_MEF.FAMILIA_BIEN,
		 CAT_MEF.ITEM_BIEN,				CAT_MEF.NOMBRE_ITEM,   			CAT_MEF.FLAG_ACTIVO,   			CAT_MEF.TIPO_ACTIVO,       CAT_MEF.UNIDAD_ADQUIS,
		 CAT_MEF.FACTOR_UNIDAD,    	CAT_MEF.UNIDAD_MEDIDA,			CAT_MEF.PRESENTACION,		  	CAT_MEF.COND_ALMAC, 			CAT_MEF.MARCA_REF,
		 CAT_MEF.PRECIO_REF,  			CAT_MEF.FECHA_REF,        		CAT_MEF.PRECIO_COMPRA,			CAT_MEF.FECHA_COMPRA,  		CAT_MEF.ITEM_CRITICO,
		 CAT_MEF.FLAG_ITEM,           CAT_MEF.PRECIO_DOLAR,    		CAT_MEF.STOCK_MINIMO,    		CAT_MEF.STOCK_MAXIMO,      CAT_MEF.ESTADO,
		 CAT_MEF.FECHA_ALTA,        	CAT_MEF.FECHA_ACT,            CAT_MEF.BOLSA_PRODUCTO, 		CAT_MEF.CUSER_ID,          CAT_MEF.PAIS,
	     CAT_MEF.FLAG_VISUALIZA,		CAT_MEF.ENVIADO,            	CAT_MEF.FLAG_UNIDADES,        CAT_MEF.TIPO_MARCA,        CAT_MEF.FLAG_SUBASTA_INVERSA, 
         CAT_MEF.FLAG_MARCO_PRECIO,	CAT_MEF.FLAG_ESTADO,  	      CAT_MEF.GRUPO_BIEN_PADRE,    	CAT_MEF.CLASE_BIEN_PADRE,	CAT_MEF.FAMILIA_BIEN_PADRE, 
         CAT_MEF.ITEM_BIEN_PADRE,		CAT_MEF.CODIGO_ONU,        	KIT.ITEM_BIEN,            		'A'
    FROM SI_PPR_KIT_ITEMS KIT,
	     CATALOGO_BIEN_SERV_ORIGINAL CAT_MEF with (index(PK_CATALOGO_BIEN_SERV_ORIGINAL))
WHERE    CAT_MEF.TIPO_BIEN     = KIT.TIPO_BIEN        AND 
         CAT_MEF.GRUPO_BIEN    = KIT.GRUPO_BIEN       AND
         CAT_MEF.CLASE_BIEN    = KIT.CLASE_BIEN       AND        
         CAT_MEF.FAMILIA_BIEN  = KIT.FAMILIA_BIEN     AND
         CAT_MEF.ITEM_BIEN     = KIT.ITEM			 	AND 		
         KIT.NIVEL             = 'I' 					AND
         KIT.ESTADO			   = 'A'    				AND
         KIT.ANO_EJE		   =  @P_ANO_CN				AND
           NOT EXISTS(SELECT 1 
	 				  FROM CATALOGO_BIEN_SERV CAT_INS   
	               WHERE CAT_INS.SEC_EJEC = @P_SEC_EJEC	          AND
	               		 CAT_INS.TIPO_BIEN 	= CAT_MEF.TIPO_BIEN       AND
                         CAT_INS.GRUPO_BIEN   = CAT_MEF.GRUPO_BIEN    AND
                         CAT_INS.CLASE_BIEN   = CAT_MEF.CLASE_BIEN    AND
                   CAT_INS.FAMILIA_BIEN = CAT_MEF.FAMILIA_BIEN  AND
                         CAT_INS.ITEM_BIEN    = CAT_MEF.ITEM_BIEN)

/* Activa el catalogo_precio */
	UPDATE SIG_CATALOGO_BIEN_SERV_PRECIO 
		SET INDICADOR= 1
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_CATALOGO_BIEN_SERV_PRECIO.ANO_EJE   =@P_ANO_CN          AND 
			 SIG_CATALOGO_BIEN_SERV_PRECIO.SEC_EJEC  =@P_SEC_EJEC AND
			 KIT.ANO_EJE      = SIG_CATALOGO_BIEN_SERV_PRECIO.ANO_EJE       AND
			 KIT.TIPO_BIEN    = SIG_CATALOGO_BIEN_SERV_PRECIO.TIPO_BIEN     AND
			 KIT.GRUPO_BIEN   = SIG_CATALOGO_BIEN_SERV_PRECIO.GRUPO_BIEN    AND
			 KIT.CLASE_BIEN   = SIG_CATALOGO_BIEN_SERV_PRECIO.CLASE_BIEN    AND
			 KIT.FAMILIA_BIEN = SIG_CATALOGO_BIEN_SERV_PRECIO.FAMILIA_BIEN  AND
			 KIT.ITEM         = SIG_CATALOGO_BIEN_SERV_PRECIO.ITEM_BIEN  	AND
			 KIT.NIVEL		  = 'I'											AND
			 KIT.ESTADO		  = 'A' 


/* Actualiza catálogo insitucional */

UPDATE CATALOGO_BIEN_SERV
   SET ESTADO= 'A'
 WHERE SEC_EJEC = @P_SEC_EJEC  AND
       ESTADO   = 'I'            AND
       EXISTS (SELECT 1 
                 FROM SI_PPR_KIT_ITEMS A
                 JOIN CATALOGO_BIEN_SERV_ORIGINAL C with (index(PK_CATALOGO_BIEN_SERV_ORIGINAL)) ON (                                           
                      C.TIPO_BIEN    = A.TIPO_BIEN     AND
                      C.GRUPO_BIEN   = A.GRUPO_BIEN    AND
                      C.CLASE_BIEN   = A.CLASE_BIEN    AND
                      C.FAMILIA_BIEN = A.FAMILIA_BIEN  AND
                      C.ITEM_BIEN    = A.ITEM		   AND
                      A.NIVEL		 = 'I')
                WHERE A.ANO_EJE      = @P_ANO_CN                    AND  
                      A.TIPO_BIEN    = C.TIPO_BIEN                     AND
                      A.GRUPO_BIEN   = CATALOGO_BIEN_SERV.GRUPO_BIEN   AND
                      A.CLASE_BIEN   = CATALOGO_BIEN_SERV.CLASE_BIEN   AND
                      A.FAMILIA_BIEN = CATALOGO_BIEN_SERV.FAMILIA_BIEN AND
                      A.ITEM         = CATALOGO_BIEN_SERV.ITEM_BIEN)
                      

/* Inserto en el catálogo precio */
INSERT INTO SIG_CATALOGO_BIEN_SERV_PRECIO (
		 ANO_EJE,						SEC_EJEC,					TIPO_BIEN,				GRUPO_BIEN, 
		 CLASE_BIEN,					FAMILIA_BIEN,				ITEM_BIEN,				PRECIO_REF, 
		 UNIDAD_MEDIDA,			   		ESTADO,						INDICADOR,				FECHA_REG,
		 CUSER_ID,						EQUIPO_REG)
SELECT DISTINCT 
		 @P_ANO_CN, 					@P_SEC_EJEC  ,				A.TIPO_BIEN,			A.GRUPO_BIEN, 
		 A.CLASE_BIEN,	 				A.FAMILIA_BIEN,		   		A.ITEM_BIEN,			coalesce( A.PRECIO_REF, 0,A.PRECIO_REF ) PRECIO_REF  , 
		 A.UNIDAD_MEDIDA,				A.ESTADO,					'1' INDICADOR,						getdate() FECHA_REG,
		 'SIGA' CUSER_ID,				'SIGA' EQUIPO_REG
  FROM CATALOGO_BIEN_SERV A  WITH(INDEX=IND_CATALOGO_03),
	   SI_PPR_KIT_ITEMS C WITH(INDEX=IND_SI_PPR_KIT_ITEMS_05)
WHERE 	  a.SEC_EJEC	 = @P_SEC_EJEC and  
		  C.ANO_EJE		 = @P_ANO_CN AND 
		  A.ESTADO	 	 = 'A'  AND
		  C.TIPO_BIEN 	 = 'B'  AND 
		  C.TIPO_BIEN    = A.TIPO_BIEN     AND
		  C.GRUPO_BIEN   = A.GRUPO_BIEN    AND
		  C.CLASE_BIEN   = A.CLASE_BIEN    AND
		  C.FAMILIA_BIEN = A.FAMILIA_BIEN  AND
          C.ITEM	     = A.ITEM_BIEN     AND 
          C.NIVEL		 ='I'			   AND
		  C.ESTADO 		 = 'A' AND
		 NOT EXISTS (SELECT 1
					 FROM SIG_CATALOGO_BIEN_SERV_PRECIO B WITH( INDEX=IND_CUADRO_NECS_01)
					WHERE   B.ANO_EJE 	= @P_ANO_CN	 	AND 
							B.SEC_EJEC	= A.SEC_EJEC	AND 
							c.TIPO_BIEN  = B.TIPO_BIEN 		AND 
							c.GRUPO_BIEN= B.GRUPO_BIEN 	AND 
							c.CLASE_BIEN = B.CLASE_BIEN 	AND 
							c.FAMILIA_BIEN = B.FAMILIA_BIEN 	AND 
							c.ITEM    = B.ITEM_BIEN )	
							

INSERT INTO SIG_CATALOGO_UNIDAD_EJECUTORA (
       SEC_EJEC,						TIPO_BIEN,					GRUPO_BIEN,                   CLASE_BIEN,   
       FAMILIA_BIEN,    	    	ITEM_BIEN,              UNIDAD_MEDIDA,                ESTADO )  
SELECT DISTINCT 
       EJE.SEC_EJEC,					CAT_UND.TIPO_BIEN,      CAT_UND.GRUPO_BIEN,           CAT_UND.CLASE_BIEN, 
       CAT_UND.FAMILIA_BIEN,     CAT_UND.ITEM_BIEN,      CAT_UND.UNIDAD_MEDIDA,        CAT_UND.ESTADO  
  FROM CATALOGO_BIEN_SERV CAT_INS 
  JOIN SIG_CATALOGO_BIEN_SERV_UNIDAD CAT_UND ON (
       CAT_INS.TIPO_BIEN    = CAT_UND.TIPO_BIEN    AND       CAT_INS.GRUPO_BIEN   = CAT_UND.GRUPO_BIEN   AND
       CAT_INS.CLASE_BIEN   = CAT_UND.CLASE_BIEN   AND       CAT_INS.FAMILIA_BIEN = CAT_UND.FAMILIA_BIEN AND
       CAT_INS.ITEM_BIEN    = CAT_UND.ITEM_BIEN)    
  JOIN SIG_EJECUTORA EJE ON (
       CAT_INS.SEC_EJEC  = EJE.SEC_EJEC)
 WHERE CAT_INS.SEC_EJEC = @P_SEC_EJEC AND
       EJE.ESTADO = 'A' AND
       NOT EXISTS (SELECT 1
                     FROM SIG_CATALOGO_UNIDAD_EJECUTORA U
                    WHERE U.SEC_EJEC = EJE.SEC_EJEC AND
                          U.TIPO_BIEN = CAT_UND.TIPO_BIEN AND
                          U.GRUPO_BIEN = CAT_UND.GRUPO_BIEN AND
                          U.CLASE_BIEN = CAT_UND.CLASE_BIEN AND
                          U.FAMILIA_BIEN = CAT_UND.FAMILIA_BIEN AND
                          U.ITEM_BIEN = CAT_UND.ITEM_BIEN AND
                          U.UNIDAD_MEDIDA = CAT_UND.UNIDAD_MEDIDA)



INSERT INTO SIG_FAMILIA_CLAS_EJECUTORA (
		 ANO_EJE,					SEC_EJEC,					FAMILIA_CLASIFICADOR,					TIPO_BIEN,
		 GRUPO_BIEN,				CLASE_BIEN,   				FAMILIA_BIEN,							TIPO_USO,
		 TIPO_ACT_PROY,				CLASIFICADOR, 				ESTADO,   								FECHA_ING,
		 USUARIO_ING,				FECHA_MOD,					USUARIO_MOD)
SELECT DISTINCT 
       FAM.ANO_EJE,     	  @P_SEC_EJEC, 			FAM.FAMILIA_CLASIFICADOR,        FAM.TIPO_BIEN,
       FAM.GRUPO_BIEN,     	FAM.CLASE_BIEN,         FAM.FAMILIA_BIEN,                FAM.TIPO_USO,
       FAM.TIPO_ACT_PROY,		FAM.CLASIFICADOR,       FAM.ESTADO,                      FAM.FECHA_ING,
       FAM.USUARIO_ING,    	FAM.FECHA_MOD,          FAM.USUARIO_MOD
  FROM SI_PPR_KIT_ITEMS KIT  ,
	   SIG_FAMILIA_CLASIFICADOR FAM with (index(PK_SIG_FAMILIA_CLASIFICADOR))
where (	   
	   FAM.TIPO_BIEN    = KIT.TIPO_BIEN         AND  
	   FAM.GRUPO_BIEN   = KIT.GRUPO_BIEN  AND
       FAM.CLASE_BIEN   = KIT.CLASE_BIEN        AND       
       FAM.FAMILIA_BIEN = KIT.FAMILIA_BIEN       AND
       FAM.ANO_EJE      = KIT.ANO_EJE) and
	   KIT.ANO_EJE      = @P_ANO_CN   AND
	   NOT EXISTS (SELECT 1
                    FROM SIG_FAMILIA_CLAS_EJECUTORA  with (index(PK_SIG_FAMILIA_CLAS_EJECUTORA))
                   WHERE ANO_EJE  = @P_ANO_CN    AND
                         SIG_FAMILIA_CLAS_EJECUTORA.SEC_EJEC =@P_SEC_EJEC  AND
                         FAMILIA_CLASIFICADOR = FAM.FAMILIA_CLASIFICADOR)
                                
                                
UPDATE SIG_FAMILIA_CLAS_EJECUTORA
   SET ESTADO= 'A'
 WHERE ANO_EJE  = @P_ANO_CN   AND 
 		 SEC_EJEC = @P_SEC_EJEC AND 
		 ESTADO   = 'I'            AND
		 EXISTS (SELECT 1 
                 FROM SI_PPR_KIT_ITEMS KIT
                 JOIN SIG_FAMILIA_CLASIFICADOR FAM with (index(PK_SIG_FAMILIA_CLASIFICADOR)) ON (
                      FAM.TIPO_BIEN    = KIT.TIPO_BIEN        AND FAM.GRUPO_BIEN   = KIT.GRUPO_BIEN     AND
                      FAM.CLASE_BIEN   = KIT.CLASE_BIEN       AND FAM.FAMILIA_BIEN = KIT.FAMILIA_BIEN   AND
                      FAM.ANO_EJE      = KIT.ANO_EJE          AND FAM.CLASIFICADOR = KIT.CLASIFICADOR	AND
                      KIT.NIVEL		   = 'I' 				  AND KIT.ESTADO	   = 'A')
                 WHERE 	KIT.ANO_EJE		= @P_ANO_CN 		  AND
               		    KIT.ANO_EJE              = SIG_FAMILIA_CLAS_EJECUTORA.ANO_EJE  AND
                        FAM.FAMILIA_CLASIFICADOR = SIG_FAMILIA_CLAS_EJECUTORA.FAMILIA_CLASIFICADOR) 	 			 				  


SET @ls_fase           = dbo.SF_CN_FASE_ESTADO(@P_SEC_EJEC, @P_ANO_CN, 1)
SET @ls_fase_estado = dbo.SF_CN_FASE_ESTADO(@P_SEC_EJEC, @P_ANO_CN, 2)
SET @ll_fase           = CAST(@ls_fase AS INT) 

IF (@ll_fase = 1 OR @ll_fase = 2) AND @ls_fase_estado = 'A' AND @P_ANO_CN >= 2023
BEGIN
            UPDATE	SIG_CUADRO_NECESIDAD_DET
            SET		
                STOCK	=	
                    COALESCE((
                        SELECT	SUM(COALESCE(SIG_CUA_NEC_DET_ID.STOCK, 0))
                        FROM		SIG_CUA_NEC_DET_ID
                        WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                        AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                        AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                        AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                        AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                        AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                        AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                        ), 0) ,
        
                CANT_01 = 
                COALESCE((
                                            SELECT	SUM(COALESCE(SIG_CUA_NEC_DET_ID.CANT_TOTAL, 0))
                                            FROM		SIG_CUA_NEC_DET_ID
                                            WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                                            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                                            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                                            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                                            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                                            AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                                            AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                                            ), 0)  ,
        
                CANT_TOTAL = 
                COALESCE((
                                            SELECT	SUM(COALESCE(SIG_CUA_NEC_DET_ID.CANT_TOTAL, 0))
                                            FROM		SIG_CUA_NEC_DET_ID
                                            WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                                            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                                            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                                            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                                            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                                            AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                                            AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                                            ), 0)  ,
                                            
                MNTO_01 = 
                    PRECIO_UNIT * COALESCE((
                                            SELECT	SUM(COALESCE(SIG_CUA_NEC_DET_ID.CANT_TOTAL, 0))
                                            FROM		SIG_CUA_NEC_DET_ID
                                            WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                                            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                                            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                                            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                                            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                                            AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                                            AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                                            ), 0)  ,
        
                MNTO_TOTAL = 
                    PRECIO_UNIT * COALESCE((
                                            SELECT	SUM(COALESCE(SIG_CUA_NEC_DET_ID.CANT_TOTAL, 0))
                                            FROM		SIG_CUA_NEC_DET_ID
                                            WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                                            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                                            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                                            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                                            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                                            AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                                            AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                                            ), 0)  ,
        
                ID_KIT = 
                COALESCE((
                                            SELECT	MAX(COALESCE(SIG_CUA_NEC_DET_ID.ID_KIT, 0))
                                            FROM		SIG_CUA_NEC_DET_ID
                                            WHERE		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                                            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                                            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                                            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                                            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                                            AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                                            AND		SIG_CUA_NEC_DET_ID.ESTADO = 'A'
                                            ), 0)
        
        WHERE EXISTS 
                (
                SELECT 1
                FROM		SIG_CUA_NEC_DET_ID
               WHERE	SIG_CUA_NEC_DET_ID.SEC_EJEC		=   @P_SEC_EJEC
               AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= @P_ANO_CN
                AND		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                AND		SIG_CUA_NEC_DET_ID.ITEM_SEC		= SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= @ll_fase
                AND		SIG_CUA_NEC_DET_ID.TIPO_CALCULO = 4
                ) 

    IF @ls_fase = '1'
    BEGIN
        UPDATE	SIG_CUADRO_NECESIDAD
        SET		
            TOTAL_PROGRA	=	
                COALESCE((
                    SELECT	SUM(SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL)
                    FROM		SIG_CUADRO_NECESIDAD_DET
                    WHERE		SIG_CUADRO_NECESIDAD_DET.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
                    AND		SIG_CUADRO_NECESIDAD_DET.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
                    AND		SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
                    AND		SIG_CUADRO_NECESIDAD_DET.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
                    AND		SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
                    ), 0)   ,
    
            MONTO_PROGRA	=	
                COALESCE((
                    SELECT	SUM(SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL)
                    FROM		SIG_CUADRO_NECESIDAD_DET
                    WHERE		SIG_CUADRO_NECESIDAD_DET.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
                    AND		SIG_CUADRO_NECESIDAD_DET.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
                    AND		SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
                    AND		SIG_CUADRO_NECESIDAD_DET.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
                    AND		SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
                    ), 0) 
    WHERE EXISTS 
            (
            SELECT 1
            FROM		SIG_CUA_NEC_DET_ID
            
            WHERE	SIG_CUA_NEC_DET_ID.SEC_EJEC		=   @P_SEC_EJEC
            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= @P_ANO_CN
            AND		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= @ll_fase
            AND		SIG_CUA_NEC_DET_ID.TIPO_CALCULO = 4
            ) 
    END

    IF @ls_fase = '2'
    BEGIN
        UPDATE	SIG_CUADRO_NECESIDAD
        SET		
            TOTAL_ASIGNADO	=	
                COALESCE((
                    SELECT	SUM(SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL)
                    FROM		SIG_CUADRO_NECESIDAD_DET
                    WHERE		SIG_CUADRO_NECESIDAD_DET.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
                    AND		SIG_CUADRO_NECESIDAD_DET.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
                    AND		SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
                    AND		SIG_CUADRO_NECESIDAD_DET.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
                    AND		SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
                    ), 0)   ,
    
            MONTO_ASIGNADO	=	
                COALESCE((
                    SELECT	SUM(SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL)
                    FROM		SIG_CUADRO_NECESIDAD_DET
                    WHERE		SIG_CUADRO_NECESIDAD_DET.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
                    AND		SIG_CUADRO_NECESIDAD_DET.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
                    AND		SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
                    AND		SIG_CUADRO_NECESIDAD_DET.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
                    AND		SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
                    ), 0) 
    WHERE EXISTS 
            (
            SELECT 1
            FROM		SIG_CUA_NEC_DET_ID
            
            WHERE	SIG_CUA_NEC_DET_ID.SEC_EJEC		=   @P_SEC_EJEC
            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= @P_ANO_CN
            AND		SIG_CUA_NEC_DET_ID.SEC_EJEC		= SIG_CUADRO_NECESIDAD.SEC_EJEC
            AND		SIG_CUA_NEC_DET_ID.ANO_EJE			= SIG_CUADRO_NECESIDAD.ANO_EJE
            AND		SIG_CUA_NEC_DET_ID.CENTRO_COSTO	= SIG_CUADRO_NECESIDAD.CENTRO_COSTO
            AND		SIG_CUA_NEC_DET_ID.SECUENCIA		= SIG_CUADRO_NECESIDAD.SECUENCIA
            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= SIG_CUADRO_NECESIDAD.FASE_CUADRO
            AND		SIG_CUA_NEC_DET_ID.FASE_CUADRO	= @ll_fase
            AND		SIG_CUA_NEC_DET_ID.TIPO_CALCULO = 4
            ) 
    END
END        


END
GO


-- ----------------------------
-- procedure structure for DT_ADDUSEROBJECT_VCS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_ADDUSEROBJECT_VCS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_ADDUSEROBJECT_VCS]
GO

CREATE PROCEDURE [dbo].[DT_ADDUSEROBJECT_VCS]
    @vchProperty varchar(64)

as

set nocount on

declare @iReturn int
    /*
    ** Create the user object if it does not exist already
    */
    begin transaction
        select @iReturn = objectid from dbo.dtproperties where property = @vchProperty
        if @iReturn IS NULL
        begin
            insert dbo.dtproperties (property) VALUES (@vchProperty)
            update dbo.dtproperties set objectid=@@identity
                    where id=@@identity and property=@vchProperty
            select @iReturn = @@identity
        end
    commit
    return @iReturn
GO


