-- ----------------------------
-- procedure structure for SP_PPR_CUA_NEC_DET_CALC_MONT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PPR_CUA_NEC_DET_CALC_MONT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PPR_CUA_NEC_DET_CALC_MONT]
GO

CREATE PROCEDURE [dbo].[SP_PPR_CUA_NEC_DET_CALC_MONT]
(
@adc_cant_01        NUMERIC(20, 4),
@adc_cant_02        NUMERIC(20, 4),
@adc_cant_03        NUMERIC(20, 4),
@adc_cant_04        NUMERIC(20, 4),
@adc_cant_05        NUMERIC(20, 4),
@adc_cant_06        NUMERIC(20, 4),
@adc_cant_07        NUMERIC(20, 4),
@adc_cant_08        NUMERIC(20, 4),
@adc_cant_09        NUMERIC(20, 4),
@adc_cant_10        NUMERIC(20, 4),
@adc_cant_11        NUMERIC(20, 4),
@adc_cant_12        NUMERIC(20, 4),
@adc_precio_unit    NUMERIC(20, 6),
@as_impu_tipo       VARCHAR(1),
@adc_impu_tasa      NUMERIC(20, 4),
------------------------------------------
@adc_mont_01        NUMERIC(20, 4)  OUTPUT,
@adc_mont_02        NUMERIC(20, 4)  OUTPUT,
@adc_mont_03        NUMERIC(20, 4)  OUTPUT,
@adc_mont_04        NUMERIC(20, 4)  OUTPUT,
@adc_mont_05        NUMERIC(20, 4)  OUTPUT,
@adc_mont_06        NUMERIC(20, 4)  OUTPUT,
@adc_mont_07        NUMERIC(20, 4)  OUTPUT,
@adc_mont_08        NUMERIC(20, 4)  OUTPUT,
@adc_mont_09        NUMERIC(20, 4)  OUTPUT,
@adc_mont_10        NUMERIC(20, 4)  OUTPUT,
@adc_mont_11        NUMERIC(20, 4)  OUTPUT,
@adc_mont_12        NUMERIC(20, 4)  OUTPUT,
@adc_montos_redo    NUMERIC(20, 4)  OUTPUT,
@adc_impu_redo      NUMERIC(20, 4)  OUTPUT
)
------------------------------------------
AS
------------------------------------------------------------------------------------
--Autor : Felix Castillo
--Objeto: Calcula los montos en el proceso de simulacion del cuadro de necesidades desde el ppr
------------------------------------------------------------------------------------
BEGIN
DECLARE @ldc_mont_01        NUMERIC(20, 4) 
DECLARE @ldc_mont_02        NUMERIC(20, 4) 
DECLARE @ldc_mont_03        NUMERIC(20, 4) 
DECLARE @ldc_mont_04        NUMERIC(20, 4) 
DECLARE @ldc_mont_05        NUMERIC(20, 4) 
DECLARE @ldc_mont_06        NUMERIC(20, 4) 
DECLARE @ldc_mont_07        NUMERIC(20, 4) 
DECLARE @ldc_mont_08        NUMERIC(20, 4) 
DECLARE @ldc_mont_09        NUMERIC(20, 4) 
DECLARE @ldc_mont_10        NUMERIC(20, 4) 
DECLARE @ldc_mont_11        NUMERIC(20, 4) 
DECLARE @ldc_mont_12        NUMERIC(20, 4) 
DECLARE @ldc_cant_total     NUMERIC(20, 4) 
DECLARE @ldc_monto_redo     NUMERIC(20, 4) 
DECLARE @ldc_impu_redo      NUMERIC(20, 4) 
DECLARE @ldc_montos_redo    NUMERIC(20, 4) 
DECLARE @ldc_diferencia     NUMERIC(20, 4) 

--calculo segun tipo de impuesto
IF  @as_impu_tipo = '1'
BEGIN
    SELECT  @ldc_mont_01    =   ROUND(
                                @adc_cant_01 * @adc_precio_unit
                                -
                                ((@adc_cant_01 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_02    =   ROUND(
                                @adc_cant_02 * @adc_precio_unit
                                -
                                ((@adc_cant_02 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_03    =   ROUND(
                                @adc_cant_03 * @adc_precio_unit
                                -
                                ((@adc_cant_03 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_04    =   ROUND(
                                @adc_cant_04 * @adc_precio_unit
                                -
                                ((@adc_cant_04 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_05    =   ROUND(
                                @adc_cant_05 * @adc_precio_unit
                                -
                                ((@adc_cant_05 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_06    =   ROUND(@adc_cant_06 * @adc_precio_unit
                                -
                                ((@adc_cant_06 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_07    =   ROUND(@adc_cant_07 * @adc_precio_unit
                                -
                                ((@adc_cant_07 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_08    =   ROUND(@adc_cant_08 * @adc_precio_unit
                                -
                                ((@adc_cant_08 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_09    =   ROUND(@adc_cant_09 * @adc_precio_unit
                                -
                                ((@adc_cant_09 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_10    =   ROUND(@adc_cant_10 * @adc_precio_unit
                                -
                                ((@adc_cant_10 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_11    =   ROUND(@adc_cant_11 * @adc_precio_unit
                                -
                                ((@adc_cant_11 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
    SELECT  @ldc_mont_12    =   ROUND(@adc_cant_12 * @adc_precio_unit
                                -
                                ((@adc_cant_12 * @adc_precio_unit * @adc_impu_tasa) / (@adc_impu_tasa + 100))
                                , 2) 
END
ELSE    IF  @as_impu_tipo = '0'
BEGIN
    SELECT  @ldc_mont_01    =   ROUND((@adc_cant_01 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_02    =   ROUND((@adc_cant_02 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_03    =   ROUND((@adc_cant_03 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_04    =   ROUND((@adc_cant_04 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_05    =   ROUND((@adc_cant_05 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_06    =   ROUND((@adc_cant_06 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_07    =   ROUND((@adc_cant_07 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_08    =   ROUND((@adc_cant_08 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_09    =   ROUND((@adc_cant_09 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_10    =   ROUND((@adc_cant_10 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_11    =   ROUND((@adc_cant_11 * @adc_precio_unit), 2) 
    SELECT  @ldc_mont_12    =   ROUND((@adc_cant_12 * @adc_precio_unit), 2) 
END
ELSE
BEGIN
    SELECT  @ldc_mont_01    =   ROUND(@adc_cant_01 * @adc_precio_unit -
                                ((@adc_cant_01 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_02    =   ROUND(@adc_cant_02 * @adc_precio_unit -
                                ((@adc_cant_02 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_03    =   ROUND(@adc_cant_03 * @adc_precio_unit -
                                ((@adc_cant_03 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_04    =   ROUND(@adc_cant_04 * @adc_precio_unit -
                                ((@adc_cant_04 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_05    =   ROUND(@adc_cant_05 * @adc_precio_unit -
                                ((@adc_cant_05 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_06    =   ROUND(@adc_cant_06 * @adc_precio_unit -
                                ((@adc_cant_06 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_07    =   ROUND(@adc_cant_07 * @adc_precio_unit -
                                ((@adc_cant_07 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_08    =   ROUND(@adc_cant_08 * @adc_precio_unit -
                                ((@adc_cant_08 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_09    =   ROUND(@adc_cant_09 * @adc_precio_unit -
                                ((@adc_cant_09 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_10    =   ROUND(@adc_cant_10 * @adc_precio_unit -
                                ((@adc_cant_10 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_11    =   ROUND(@adc_cant_11 * @adc_precio_unit -
                                ((@adc_cant_11 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
    SELECT  @ldc_mont_12    =   ROUND(@adc_cant_12 * @adc_precio_unit -
                                ((@adc_cant_12 * @adc_precio_unit * @adc_impu_tasa) / 100), 2) 
END 

SELECT  @ldc_cant_total = @adc_cant_01 + @adc_cant_02 + @adc_cant_03 + @adc_cant_04 + @adc_cant_05 + @adc_cant_06 +
                          @adc_cant_07 + @adc_cant_08 + @adc_cant_09 + @adc_cant_10 + @adc_cant_11 + @adc_cant_12 

--monto totales para el redondeo
IF  @as_impu_tipo = '1'
BEGIN
    SELECT  @ldc_impu_redo  =   ROUND((ROUND(@ldc_cant_total * @adc_precio_unit,2) * @adc_impu_tasa) / (@adc_impu_tasa + 100), 2) 
END
ELSE    IF  @as_impu_tipo = '0'
BEGIN
    SELECT  @ldc_impu_redo  =   0 
END
ELSE
BEGIN
    SELECT  @ldc_impu_redo  =   ROUND((ROUND(@ldc_cant_total * @adc_precio_unit, 2)* @adc_impu_tasa) / 100, 2) 
END 

SELECT  @ldc_monto_redo     =   ROUND(@ldc_cant_total * @adc_precio_unit, 2) - @ldc_impu_redo 
SELECT  @ldc_montos_redo    =   @ldc_mont_01 + @ldc_mont_02 + @ldc_mont_03 + @ldc_mont_04 + @ldc_mont_05 + @ldc_mont_06 +
							    @ldc_mont_07 + @ldc_mont_08 + @ldc_mont_09 + @ldc_mont_10 + @ldc_mont_11 + @ldc_mont_12 
SELECT  @ldc_diferencia     =   ROUND(@ldc_monto_redo - @ldc_montos_redo, 2) 

------------------------------------------
--ajustando los montos por cada mes
------------------------------------------

--ajuste para el mes 01
IF  @ldc_mont_01 > 0
BEGIN
    IF  @ldc_diferencia > 0
    BEGIN
        SELECT  @ldc_mont_01 = @ldc_mont_01 + 0.01 
    END
    ELSE    IF  @ldc_diferencia < 0
    BEGIN
        IF  @ldc_mont_02 > 0 or @ldc_mont_03 > 0 or @ldc_mont_04 > 0 or @ldc_mont_05 > 0 or
            @ldc_mont_06 > 0 or @ldc_mont_07 > 0 or @ldc_mont_08 > 0 or @ldc_mont_09 > 0 or
            @ldc_mont_10 > 0 or @ldc_mont_11 > 0 or @ldc_mont_12 > 0
        BEGIN

            SELECT  @ldc_mont_01    = @ldc_mont_01 - 0.01 
        END
        ELSE
        BEGIN
            SELECT  @ldc_mont_01    = @ldc_mont_01 + @ldc_diferencia 
        END
    END
    SELECT  @ldc_montos_redo    =   @ldc_mont_01 + @ldc_mont_02 + @ldc_mont_03 + @ldc_mont_04 +
                                    @ldc_mont_05 + @ldc_mont_06 + @ldc_mont_07 + @ldc_mont_08 +
                                    @ldc_mont_09 + @ldc_mont_10 + @ldc_mont_11 + @ldc_mont_12 
    SELECT  @ldc_diferencia     =   ROUND(@ldc_monto_redo - @ldc_montos_redo, 2) 
END 

--ajuste para el mes 02
IF  @ldc_mont_02 > 0
BEGIN
    IF  @ldc_diferencia > 0
    BEGIN
