-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_ALMACEN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_ALMACEN]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_ALMACEN]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_ALMACEN]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJEC   	    	VARCHAR(10),
    @fecha_carga_inicio     	VARCHAR(10),
    @fecha_carga_fin        	VARCHAR(10),
    @usuario_n              	VARCHAR(50)
AS
	DECLARE @fecha_carga_inicio_1     DATETIME  
	DECLARE @fecha_carga_fin_1        DATETIME  

BEGIN  
	TRUNCATE TABLE SI_ALMACEN
    	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    	SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

		 INSERT INTO SI_ALMACEN(
				ANO_EJE, SEC_EJEC, ALMACEN, SEC_ALMACEN, PLIEGO, 
				SEDE, NOMBRE_ALM, DIRECCION, TELEFONOS, 
				PAIS, DEPARTAMENTO, PROVINCIA, DISTRITO, 
				ANO_PROCESO, MES_PROCESO,
				FLAG_SISMED, FLAG_DONACION, 
				FECHA_CARGA_INICIO, FECHA_CARGA_FIN, 
				FECHA_ENVIO, USUARIO_ENVIO
				)
				SELECT @P_ANO_EJE, @P_SEC_EJEC, ALMACEN, SEC_ALMACEN, PLIEGO,
				SEDE, NOMBRE_ALM, DIRECCION, TELEFONOS, PAIS, 
				DEPARTAMENTO, PROVINCIA, DISTRITO, 
				ANO_PROCESO, MES_PROCESO,
				FLAG_SISMED, FLAG_DONACION,
				@fecha_carga_inicio_1, @fecha_carga_fin_1, 
				convert(varchar(10),getdate(),112), @usuario_n
				FROM SIG_ALMACEN
				WHERE SEC_EJEC = @P_SEC_EJEC 
				AND ESTADO = 'A'
END
GO


-- ----------------------------
-- function structure for SF_SIG_DIA_MES
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_SIG_DIA_MES]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_SIG_DIA_MES]
GO

CREATE FUNCTION [dbo].[SF_SIG_DIA_MES] (
									@PN_MES    		NUMERIC,
									@PN_ANIO		NUMERIC
									)
RETURNS INTEGER
AS
BEGIN

  DECLARE @Numdias NUMERIC(2)
  DECLARE  @ldc_ind_febrero NUMERIC(8,2)
  DECLARE @ldc_ind_febrero2 NUMERIC(8,2)
  DECLARE @ls_anio_bisiesto VARCHAR(1)


	IF @PN_MES IN (1, 3, 5, 7, 8, 10, 12)  
	BEGIN
		SET @Numdias = 31
	END 
	ELSE IF  @PN_MES IN (4, 6, 9, 11)  
	BEGIN
		SET @Numdias = 30
	END
	ELSE IF @PN_MES = 2  
	BEGIN
		--Inicio verifico si se trata de año bisiesto
		SELECT @ldc_ind_febrero = @PN_ANIO%100
		
		SET @ldc_ind_febrero2 = @PN_ANIO%4
		   
		IF @ldc_ind_febrero = 0 
		BEGIN
			SET @ls_anio_bisiesto ='N'
		END
		ELSE IF @ldc_ind_febrero2 = 0 
		BEGIN
		 	SET @ls_anio_bisiesto ='S'
		END
		ELSE
		BEGIN
			SET @ls_anio_bisiesto ='N'
		END 

		IF @ls_anio_bisiesto = 'S' 
		BEGIN
		   SET	@Numdias = 29
		END
	ELSE
	BEGIN
	   SET	@Numdias = 28
	END       		 
	--Fin verifico si se trata de año bisiesto
	
	END 

    RETURN @Numdias
END
GO


-- ----------------------------
-- procedure structure for SP_SIG_ITEM_EXCLUSIVO_DEPEND
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_ITEM_EXCLUSIVO_DEPEND]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_ITEM_EXCLUSIVO_DEPEND]
GO

CREATE PROCEDURE [dbo].[SP_SIG_ITEM_EXCLUSIVO_DEPEND]
    (@al_ejec_sec NUMERIC(10))
AS
BEGIN
	DECLARE
	@ls_tipo_bien    VARCHAR(1),
	@ls_grupo_bien   VARCHAR(2),
	@ls_clase_bien   VARCHAR(2),
	@ls_familia_bien VARCHAR(4),
	@ls_item_bien    VARCHAR(4)

	DECLARE lcur_item_prohibido CURSOR
	FOR
        SELECT tipo_bien   ,
               grupo_bien  ,
               clase_bien  ,
               familia_bien,
               item_bien
          FROM tmp_item_exclusivo
        
        OPEN lcur_item_prohibido
        
        WHILE 1 = 1
        BEGIN
            FETCH NEXT
             FROM lcur_item_prohibido
             INTO @ls_tipo_bien   ,
                  @ls_grupo_bien  ,
                  @ls_clase_bien  ,
                  @ls_familia_bien,
                  @ls_item_bien
            
            IF @@FETCH_STATUS <> 0
            BEGIN
                BREAK
            END
            
            IF EXISTS
               (
                SELECT 1
                  FROM dbo.sig_contrato_item tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
                
                UNION ALL
                
                SELECT 1
                  FROM dbo.sig_orden_item tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
                
                UNION ALL
                
                SELECT 1
                  FROM dbo.sig_detalle_movim_almacen tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
                
                UNION ALL
                
                SELECT 1
                  FROM dbo.sig_detalle_pedidos tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
                
                UNION ALL
                
                SELECT 1
                  FROM dbo.sig_cuadro_modificado_det tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
                
                UNION ALL
                
                SELECT 1
                  FROM dbo.sig_cuadro_necesidad_det tab_valida
                 WHERE tab_valida.sec_ejec = @al_ejec_sec
                   AND EXISTS (SELECT 1
		                         FROM tmp_item_exclusivo
		                        WHERE tmp_item_exclusivo.tipo_bien    = @ls_tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = @ls_grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = @ls_clase_bien
		                          AND tmp_item_exclusivo.familia_bien = @ls_familia_bien
		                          AND tmp_item_exclusivo.item_bien    = @ls_item_bien
		                          AND tmp_item_exclusivo.l_ejec_sec   = tab_valida.sec_ejec
		                          AND tmp_item_exclusivo.tipo_bien    = tab_valida.tipo_bien
		                          AND tmp_item_exclusivo.grupo_bien   = tab_valida.grupo_bien
		                          AND tmp_item_exclusivo.clase_bien   = tab_valida.clase_bien
		                          AND tmp_item_exclusivo.familia_bien = tab_valida.familia_bien
		                          AND tmp_item_exclusivo.item_bien    = tab_valida.item_bien)
		       )

            BEGIN
                /* existe al menos una dependencia */
                UPDATE tmp_item_exclusivo
                   SET s_accion = 'A'
                 WHERE l_ejec_sec   = @al_ejec_sec
                   AND tipo_bien    = @ls_tipo_bien
                   AND grupo_bien   = @ls_grupo_bien
                   AND clase_bien   = @ls_clase_bien
                   AND familia_bien = @ls_familia_bien
                   AND item_bien    = @ls_item_bien
            END 
	END

	CLOSE lcur_item_prohibido

	DEALLOCATE lcur_item_prohibido
END
GO


