CREATE PROCEDURE [dbo].[SP_CARGA_KIT](
	@pn_Ano_Eje		NUMERIC(4,0),
	@pn_Sec_Eje		NUMERIC(4,0)
)
AS
BEGIN 
DECLARE @li_Cont					NUMERIC(5,0)
DECLARE @ls_Id_Sub_Finalidad	NUMERIC(10,0)
