DECLARE @ln_Sec_Kit				NUMERIC(10,0)
DECLARE @ln_Categoria			NUMERIC(3,0)
DECLARE @ls_Tipo_Costo_DI		CHAR(1)
DECLARE @ls_Tipo_Costo_FV		CHAR(1)
DECLARE @ls_Tipo_Bien			VARCHAR(1)
DECLARE @ls_Item_Bien			VARCHAR(4)
DECLARE @ls_Clasificador		VARCHAR(20)
DECLARE @ln_Agrupa_Item			NUMERIC(3,0)
DECLARE @ln_Cantidad_Vez		NUMERIC(12,6)
DECLARE @ln_Nro_Veces			NUMERIC(12,6)
DECLARE @ln_Cantidad_Caso		NUMERIC(12,6)
DECLARE @ln_Porcent_Uso			NUMERIC(5,2)
DECLARE @ln_Factor_Convers		NUMERIC(12,6)
DECLARE @ln_Factor_Merma		NUMERIC(12,6)
DECLARE @ln_Tipo_Calculo		NUMERIC(3,0)
DECLARE @ls_Especificacion		VARCHAR(200)
DECLARE @ls_Flag_Activo			CHAR(1)
DECLARE @ls_Cadena_Funcional	VARCHAR(50)
DECLARE @ls_Grupo_Bien			VARCHAR(2)
DECLARE @ls_Clase_Bien			VARCHAR(2)
DECLARE @ls_Familia_Bien		VARCHAR(4)
DECLARE @ls_Item				VARCHAR(4)
DECLARE @ls_Flag_Uso			CHAR(1)
DECLARE @ls_Estado				VARCHAR(1)
DECLARE @ls_Error				VARCHAR(255)
DECLARE @ln_Ins					NUMERIC(5,0)
DECLARE @ls_Tipo_Costo_DIK		CHAR(1)
DECLARE @ls_UM_Uso				VARCHAR(50)
declare @lid_sub_fin numeric ( 18, 0 )
declare @ls_sub_fin varchar ( 10 )
declare @lfinalidad varchar ( 10 )
declare @lpe varchar ( 10 )
declare @lcomponente varchar ( 10 )
declare @lactproy varchar ( 10 )
-- elimina Servicios Generales
DELETE FROM SI_PPR_KIT_ITEMS
 WHERE ANO_EJE    = @pn_Ano_Eje AND
       GRUPO_BIEN = 87          AND 
       ESTADO     = 'N'
-- actualiza el Flag Activo
UPDATE SI_PPR_KIT_ITEMS 
   SET FLAG_ACTIVO = (SELECT CAT.FLAG_ACTIVO
	                    FROM CATALOGO_BIEN_SERV CAT
					   WHERE CAT.TIPO_BIEN    = SI_PPR_KIT_ITEMS.TIPO_BIEN		AND
							 CAT.GRUPO_BIEN   = SI_PPR_KIT_ITEMS.GRUPO_BIEN		AND
							 CAT.CLASE_BIEN   = SI_PPR_KIT_ITEMS.CLASE_BIEN		AND
							 CAT.FAMILIA_BIEN = SI_PPR_KIT_ITEMS.FAMILIA_BIEN	AND
							 CAT.ITEM_BIEN    = SI_PPR_KIT_ITEMS.ITEM			AND
							 CAT.SEC_EJEC     = @pn_Sec_Eje)
 WHERE EXISTS (SELECT TOP 1 1
				 FROM CATALOGO_BIEN_SERV CAT
				WHERE CAT.TIPO_BIEN    = SI_PPR_KIT_ITEMS.TIPO_BIEN		AND
					  CAT.GRUPO_BIEN   = SI_PPR_KIT_ITEMS.GRUPO_BIEN		AND
					  CAT.CLASE_BIEN   = SI_PPR_KIT_ITEMS.CLASE_BIEN		AND
					  CAT.FAMILIA_BIEN = SI_PPR_KIT_ITEMS.FAMILIA_BIEN	AND
					  CAT.ITEM_BIEN    = SI_PPR_KIT_ITEMS.ITEM			AND
					  CAT.SEC_EJEC     = @pn_Sec_Eje)
-- las columnas por categoría de un registro en SI pasan a ser filas en SIG
-- Cursor de "reordenamiento" por categorías (uso predefinido)
DECLARE C_1 CURSOR FOR
SELECT SUB_FINALIDAD,		SEC_KIT,		1,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_I_1,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS WHERE ANO_EJE = @pn_Ano_Eje AND CATEG_I_1=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		2,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_I_2,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_I_2=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		3,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_I_3,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_I_3=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		4,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_I_4,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_I_4=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		5,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_II_1,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_II_1=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		6,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_II_2,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_II_2=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		7,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_III_1,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_III_1=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		8,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_III_2,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_III_2=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		9,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_EESS_MOVIL,	ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_EESS_MOVIL=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		10,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_DISA,		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_DISA=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		11,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_RED,	ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_RED=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		12,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				FLAG_MRED,	ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_MRED=1 AND estado in ('N' , 'M')
UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		13,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				'0',		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_MINSA=1 AND estado in ('N' , 'M')
  UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		14,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				'0',		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_14=1 AND estado in ('N' , 'M')
  UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		15,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				'0',		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_15=1 AND estado in ('N' , 'M')
  UNION ALL
SELECT SUB_FINALIDAD,		SEC_KIT,		16,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,		ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,	NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,	FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,	CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,	ITEM,				'0',		ESTADO,
       TIPO_COSTO_DIK,      UM_USO,			ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS  WHERE ANO_EJE=@pn_Ano_Eje AND CATEG_16=1 AND estado in ('N' , 'M')
  
 --FALTAN LAS CATEGORIAS POR DEFINIR CATEG_17 Y CATEG_18
  
SELECT @ln_Ins= 0
-- recorre C_1
OPEN C_1

FETCH NEXT FROM C_1
 INTO @ls_Sub_Finalidad,	@ln_Sec_Kit,		@ln_Categoria,			@ls_Tipo_Costo_DI,
	  @ls_Tipo_Costo_FV,	@ls_Tipo_Bien,		@ls_Item_Bien,			@ls_Clasificador,
	  @ln_Agrupa_Item,		@ln_Cantidad_Vez,	@ln_Nro_Veces,			@ln_Cantidad_Caso,
	  @ln_Porcent_Uso,		@ln_Factor_Convers,	@ln_Factor_Merma,		@ln_Tipo_Calculo,
	  @ls_Especificacion,	@ls_Flag_Activo,	@ls_Cadena_Funcional,	@ls_Grupo_Bien,
	  @ls_Clase_Bien,		@ls_Familia_Bien,	@ls_Item,				@ls_Flag_Uso,
      @ls_Estado,			@ls_Tipo_Costo_DIK,	@ls_UM_Uso,				@ls_Id_Sub_Finalidad
-- recorre filas SI
WHILE @@FETCH_STATUS = 0 BEGIN
	  SELECT @li_Cont= COUNT(*)
		FROM SIG_PPR_KIT_ITEMS
		WHERE ANO_EJE       = @pn_Ano_Eje
		  AND SUB_FINALIDAD = @ls_Sub_Finalidad
		  AND SEC_EJEC      = @pn_Sec_Eje
		  AND CATEGORIA     = @ln_Categoria
		  AND SEC_KIT       = @ln_Sec_Kit
		  AND ID_SUB_FINALIDAD=@ls_Id_Sub_Finalidad

	  IF @li_Cont IS NULL
		 SELECT @li_Cont = 0

	  IF @li_Cont = 0 BEGIN
		 INSERT INTO SIG_PPR_KIT_ITEMS
				(ANO_EJE,			SUB_FINALIDAD,			SEC_KIT,			SEC_EJEC,
				 CATEGORIA,			TIPO_COSTO_DI,			TIPO_COSTO_FV,		TIPO_BIEN,
				 GRUPO_BIEN,		CLASE_BIEN,				FAMILIA_BIEN,		ITEM_BIEN,
				 CLASIFICADOR,		AGRUPA_ITEM,			CANTIDAD_VEZ,		NRO_VECES,
				 CANTIDAD_CASO,		PORCENT_USO,			FACTOR_CONVERS,		FACTOR_MERMA,
				 TIPO_CALCULO,		CANTIDAD,				FLAG_USO,			ESPECIFICACION,
				 FLAG_ACTIVO,		CADENA_FUNCIONAL,		PROGRAMA_INSTITUCIONAL,	FUNCION,
				 PROGRAMA,			SUB_PROGRAMA,			ACT_PROY,			COMPONENTE,
				 FINALIDAD,			ESTADO,					TIPO_COSTO_DIK,		UM_USO,
				 ID_SUB_FINALIDAD)
		 VALUES
				(@pn_Ano_Eje,		@ls_Sub_Finalidad,		@ln_Sec_Kit,		@pn_Sec_Eje,
				 @ln_Categoria,		@ls_Tipo_Costo_DI,		@ls_Tipo_Costo_FV,	@ls_Tipo_Bien,
				 @ls_Grupo_Bien,	@ls_Clase_Bien,			@ls_Familia_Bien,	@ls_Item,
				 @ls_Clasificador,	@ln_Agrupa_Item,		@ln_Cantidad_Vez,	@ln_Nro_Veces,
				 @ln_Cantidad_Caso,	@ln_Porcent_Uso,		@ln_Factor_Convers,	@ln_Factor_Merma,
				 @ln_Tipo_Calculo,	0,						@ls_Flag_Uso,		@ls_Especificacion,
				 @ls_Flag_Activo,	@ls_Cadena_Funcional,	NULL,				NULL,
				 NULL,				NULL,					NULL,				NULL,
				 NULL,				'N',					@ls_Tipo_Costo_DIK,	@ls_UM_Uso,
				 @ls_Id_Sub_Finalidad)
				 
	   select @lfinalidad=finalidad,@lpe=PROGRAMA_INSTITUCIONAL,@lcomponente= componente,@lactproy=ACT_PROY
	      from SIG_SUB_FINALIDAD
	   where ANO_EJE= 2013 and SUB_FINALIDAD= @ls_Sub_Finalidad  AND ID_SUB_FINALIDAD= @ls_Id_Sub_Finalidad

		update SIG_PPR_KIT_ITEMS 
		   set FINALIDAD=@lfinalidad,
		       PROGRAMA_INSTITUCIONAL=@lpe,
		       componente=@lcomponente,
		       ACT_PROY=@lactproy
		where  ANO_EJE= 2012 and SUB_FINALIDAD = @ls_Sub_Finalidad AND id_sub_finalidad= @ls_Id_Sub_Finalidad 
                     

		 IF @@ERROR <> 0 BEGIN		    
			CLOSE C_1
			DEALLOCATE C_1
			
		 END
      END

	  FETCH NEXT FROM C_1
	   INTO @ls_Sub_Finalidad,	@ln_Sec_Kit,		@ln_Categoria,		@ls_Tipo_Costo_DI,
			@ls_Tipo_Costo_FV,	@ls_Tipo_Bien,		@ls_Item_Bien,		@ls_Clasificador,
			@ln_Agrupa_Item,	@ln_Cantidad_Vez,	@ln_Nro_Veces,		@ln_Cantidad_Caso,
			@ln_Porcent_Uso,	@ln_Factor_Convers,	@ln_Factor_Merma,	@ln_Tipo_Calculo,
			@ls_Especificacion, @ls_Flag_Activo,	@ls_Cadena_Funcional, @ls_Grupo_Bien,
			@ls_Clase_Bien,		@ls_Familia_Bien,	@ls_Item,			@ls_Flag_Uso,
			@ls_Estado,			@ls_Tipo_Costo_DIK,	@ls_UM_Uso,			@ls_Id_Sub_Finalidad
END

CLOSE C_1
DEALLOCATE C_1
-- cursor para CATEGORÍA 99
DECLARE C_99 CURSOR FOR 
SELECT SUB_FINALIDAD,		SEC_KIT,			99,					TIPO_COSTO_DI,
	   TIPO_COSTO_FV,		TIPO_BIEN,			ITEM_BIEN,			CLASIFICADOR,
	   AGRUPA_ITEM,			CANTIDAD_VEZ,		NRO_VECES,			CANTIDAD_CASO,
	   PORCENT_USO,			FACTOR_CONVERS,		FACTOR_MERMA,		TIPO_CALCULO,
	   ESPECIFICACION,		FLAG_ACTIVO,		CADENA_FUNCIONAL,	GRUPO_BIEN,
	   CLASE_BIEN,			FAMILIA_BIEN,		ITEM,				'A',
	   ESTADO,				TIPO_COSTO_DIK,		UM_USO,				ID_SUB_FINALIDAD
  FROM SI_PPR_KIT_ITEMS 
 WHERE ANO_EJE	=   @pn_Ano_Eje AND 	   ESTADO	IN ('N' , 'M')
OPEN C_99
FETCH NEXT FROM C_99
 INTO @ls_Sub_Finalidad,	@ln_Sec_Kit,		@ln_Categoria,			@ls_Tipo_Costo_DI,
	  @ls_Tipo_Costo_FV,	@ls_Tipo_Bien,		@ls_Item_Bien,			@ls_Clasificador,
	  @ln_Agrupa_Item,		@ln_Cantidad_Vez,	@ln_Nro_Veces,			@ln_Cantidad_Caso,
	  @ln_Porcent_Uso,		@ln_Factor_Convers,	@ln_Factor_Merma,	    @ln_Tipo_Calculo,
	  @ls_Especificacion,	@ls_Flag_Activo,	@ls_Cadena_Funcional,	@ls_Grupo_Bien,
	  @ls_Clase_Bien,		@ls_Familia_Bien,	@ls_Item,				@ls_Flag_Uso,
	  @ls_Estado,			@ls_Tipo_Costo_DIK,	@ls_UM_Uso,				@ls_Id_Sub_Finalidad
-- recorre filas SI
WHILE @@FETCH_STATUS = 0 BEGIN
	  SELECT @li_Cont= COUNT(*)
		FROM SIG_PPR_KIT_ITEMS
		WHERE ANO_EJE       = @pn_Ano_Eje
		  AND SUB_FINALIDAD = @ls_Sub_Finalidad
		  AND ID_SUB_FINALIDAD=@ls_Id_Sub_Finalidad
		  AND SEC_EJEC      = @pn_Sec_Eje
		  AND CATEGORIA     = @ln_Categoria
		  AND SEC_KIT       = @ln_Sec_Kit
	  IF @li_Cont IS NULL
		 SELECT @li_Cont = 0
	  IF @li_Cont = 0 BEGIN
		 INSERT INTO SIG_PPR_KIT_ITEMS
				(ANO_EJE,			SUB_FINALIDAD,			SEC_KIT,			SEC_EJEC,
				 CATEGORIA,			TIPO_COSTO_DI,			TIPO_COSTO_FV,		TIPO_BIEN,
				 GRUPO_BIEN,		CLASE_BIEN,				FAMILIA_BIEN,		ITEM_BIEN,
				 CLASIFICADOR,		AGRUPA_ITEM,			CANTIDAD_VEZ,		NRO_VECES,
				 CANTIDAD_CASO,		PORCENT_USO,			FACTOR_CONVERS,		FACTOR_MERMA,
				 TIPO_CALCULO,		CANTIDAD,				FLAG_USO,			ESPECIFICACION,
				 FLAG_ACTIVO,		CADENA_FUNCIONAL,		PROGRAMA_INSTITUCIONAL,	FUNCION,
				 PROGRAMA,			SUB_PROGRAMA,			ACT_PROY,			COMPONENTE,
				 FINALIDAD,			ESTADO,					TIPO_COSTO_DIK,		UM_USO,
				 ID_SUB_FINALIDAD)
		 VALUES
				(@pn_Ano_Eje,		@ls_Sub_Finalidad,		@ln_Sec_Kit,		@pn_Sec_Eje,
				 @ln_Categoria,		@ls_Tipo_Costo_DI,		@ls_Tipo_Costo_FV,	@ls_Tipo_Bien,
				 @ls_Grupo_Bien,	@ls_Clase_Bien,			@ls_Familia_Bien,	@ls_Item,
				 @ls_Clasificador,	@ln_Agrupa_Item,		@ln_Cantidad_Vez,	@ln_Nro_Veces,
				 @ln_Cantidad_Caso,	@ln_Porcent_Uso,		@ln_Factor_Convers,	@ln_Factor_Merma,
				 @ln_Tipo_Calculo,	0,						@ls_Flag_Uso,		@ls_Especificacion,
				 @ls_Flag_Activo,	@ls_Cadena_Funcional,	NULL,				NULL,
				 NULL,				NULL,					NULL,				NULL,
				 NULL,				'N',					@ls_Tipo_Costo_DIK,	@ls_UM_Uso,
				 @ls_Id_Sub_Finalidad)
				 
				 
		 select @lfinalidad=finalidad,@lpe=PROGRAMA_INSTITUCIONAL,@lcomponente= componente,@lactproy=ACT_PROY
	      from SIG_SUB_FINALIDAD
	   where ANO_EJE= 2013 and SUB_FINALIDAD= @ls_Sub_Finalidad  AND ID_SUB_FINALIDAD= @ls_Id_Sub_Finalidad

		update SIG_PPR_KIT_ITEMS 
		   set FINALIDAD=@lfinalidad,
		       PROGRAMA_INSTITUCIONAL=@lpe,
		       componente=@lcomponente,
		       ACT_PROY=@lactproy
		where  ANO_EJE= 2012 and SUB_FINALIDAD = @ls_Sub_Finalidad AND id_sub_finalidad= @ls_Id_Sub_Finalidad 
		
		 IF @@ERROR <> 0 BEGIN		    
			CLOSE C_99
			DEALLOCATE C_99			
		 END

		 SELECT @ln_Ins= @ln_Ins + 1
	  END

	  FETCH NEXT FROM C_99
	   INTO @ls_Sub_Finalidad,	@ln_Sec_Kit,		@ln_Categoria,			@ls_Tipo_Costo_DI,
			@ls_Tipo_Costo_FV,	@ls_Tipo_Bien,		@ls_Item_Bien,			@ls_Clasificador,
			@ln_Agrupa_Item,	@ln_Cantidad_Vez,	@ln_Nro_Veces,			@ln_Cantidad_Caso,
			@ln_Porcent_Uso,	@ln_Factor_Convers,	@ln_Factor_Merma,		@ln_Tipo_Calculo,
			@ls_Especificacion, @ls_Flag_Activo,	@ls_Cadena_Funcional,	@ls_Grupo_Bien,
			@ls_Clase_Bien,		@ls_Familia_Bien,	@ls_Item,				@ls_Flag_Uso,
			@ls_Estado,			@ls_Tipo_Costo_DIK,	@ls_UM_Uso,				@ls_Id_Sub_Finalidad
END
CLOSE C_99
DEALLOCATE C_99

-- datos por fase 1 Req.
UPDATE SIG_PPR_KIT_ITEMS 
   SET FUNCION=					M.FUNCION,
	   PROGRAMA=				M.PROGRAMA,
	   SUB_PROGRAMA=			M.SUB_PROGRAMA,
	   ACT_PROY=				M.ACT_PROY,
	   COMPONENTE=				M.COMPONENTE,
	   FINALIDAD=				M.FINALIDAD,	
	   PROGRAMA_INSTITUCIONAL=	M.PROGRAMA_INSTITUCIONAL
  FROM SIG_META_PROPUESTA M
 WHERE SIG_PPR_KIT_ITEMS.ANO_EJE  = M.ANO_EJE   AND
	   SIG_PPR_KIT_ITEMS.SEC_EJEC = M.SEC_EJEC  AND
	   SUBSTRING(SIG_PPR_KIT_ITEMS.SUB_FINALIDAD, 1, 5) = M.FINALIDAD AND
       SIG_PPR_KIT_ITEMS.ANO_EJE  = @pn_Ano_Eje AND 
       SIG_PPR_KIT_ITEMS.SEC_EJEC = @pn_Sec_Eje
       
 
-- flag de uso por categoría
UPDATE SIG_PPR_KIT_ITEMS
   SET FLAG_USO= CASE FLAG_USO WHEN  '0' THEN 'I'
                     WHEN '1' THEN 'A'
                     ELSE ISNULL(FLAG_USO, 'I') END 
 WHERE ANO_EJE  = @pn_Ano_Eje AND
       SEC_EJEC = @pn_Sec_Eje
       
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_PATRIMONIO_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_PATRIMONIO_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_PATRIMONIO_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_PATRIMONIO_TRX]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJC   	    	VARCHAR(10),
    @fecha_carga_inicio     VARCHAR(10),
    @fecha_carga_fin        VARCHAR(10),
    @usuario_n              VARCHAR(30),
    @O_ERR_NUM   	    	NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG   	    	VARCHAR(255) OUTPUT   
AS 
DECLARE @LD_FECHA_INI			DATETIME
DECLARE @LD_FECHA_FIN			DATETIME
DECLARE @LN_ID_SI_PEDIDO		NUMERIC(10,0)
DECLARE @LN_ID_SI_PEDIDO_DETA   NUMERIC(10,0)
DECLARE @LC_TIPO_BIEN			VARCHAR(1)
DECLARE @LC_TIPO_PEDIDO			VARCHAR(1)
DECLARE @LC_GRUPO_BIEN			VARCHAR(3)
DECLARE @LC_CLASE_BIEN			VARCHAR(3)
DECLARE @LC_FAMILIA_BIEN		VARCHAR(4)
DECLARE @LC_ITEM_BIEN			VARCHAR(20)
DECLARE @LC_TIPO_DOCUMENTO		VARCHAR(3) 
DECLARE @LC_FECHA_INICIAL   	DATETIME
DECLARE @LC_FECHA_FINAL     	DATETIME
DECLARE @LC_MONEDA_PAGO     	VARCHAR(3)
DECLARE @LC_NRO_DOCUMENTO   	VARCHAR(11) 	
DECLARE @LC_VALOR_NEA 			NUMERIC(16,6)
DECLARE @LC_FECHA_NEA       	DATETIME
DECLARE @LC_MEDIDAS 	    	VARCHAR(30) 		
DECLARE @LC_ESTADO_ACTUAL   	VARCHAR(1) 	
DECLARE @LC_ESTADO_CONSERV  	VARCHAR(1)
DECLARE @LC_FECHA_COMPRA    	DATETIME 	
DECLARE @LC_VALOR_COMPRA   	    NUMERIC(16,6) 	
DECLARE @LC_NRO_ORDEN       	NUMERIC(7)
DECLARE @LC_FEC_FIN_VIDA    	DATETIME
DECLARE @LC_VIDA_UTIL 	    	NUMERIC(8,6)
DECLARE @LC_TIPO_MODALIDAD      NUMERIC(1)
DECLARE @LC_CENTRO_COSTO    	VARCHAR(150)
DECLARE @LC_NOMBRE_DEPEND   	VARCHAR(150) 	
DECLARE @LC_CODIGO_ACTIVO   	VARCHAR(12)
DECLARE @LC_DESCRIPCION     	VARCHAR(200)
DECLARE @LC_MODELO 	    	    VARCHAR(40)	
DECLARE @LC_NRO_SERIE 	    	VARCHAR(20)
DECLARE @LC_NOMBRE 	    	    VARCHAR(10) 
DECLARE @LC_ESTADO	    	    VARCHAR(2)	
DECLARE @LC_D_ITEM_CATALOGO  	VARCHAR(150)
DECLARE @LN_ID_SI_PATRIMONIO 	    NUMERIC(10,0)
DECLARE @fecha_carga_inicio_1  	    DATETIME
DECLARE @fecha_carga_fin_1     	    DATETIME
DECLARE @LC_MARCA            	    VARCHAR(10)
DECLARE @LC_ANO_PROCESO             NUMERIC(4,0)
DECLARE @LC_MES_PROCESO             VARCHAR(2)
--inicio omrv 27.01.10
DECLARE @SEDE						numeric(3,0)
DECLARE @D_SEDE						varchar(50)
DECLARE @COD_ESTABLEC				numeric(6,0)
DECLARE @COD_ESTABLEC_SIS			varchar(20)
DECLARE @D_COD_ESTABLEC				varchar(200)
DECLARE @COD_CATEGORIA				numeric(2,0)
DECLARE @D_CORTO_COD_CATEGORIA		varchar(20)
DECLARE @PLIEGO						varchar(30),
--fin omrv 27.01.10
-- inicio omrv 22.07.10
@V_ANO_PATRIMONIO		NUMERIC(4,0),
@V_MES_PATRIMONIO		VARCHAR(2),
@V_DES_MES_PATRIMONIO	VARCHAR(150),
@V_FECHA_MOVIMTO_PATRI	DATETIME,
@V_VALOR_NETO			NUMERIC(16,2),
@V_DEPREC_ACUMALDA		NUMERIC(16,2),
@V_SUB_CTA				VARCHAR(15),
@V_NOM_SUB_CTA			VARCHAR(150),
@V_COD_OGEI				VARCHAR(20),
@V_SECTOR_AMBITO		VARCHAR(2),
@V_SECUENCIA_PATRI		NUMERIC(8,0),
@V_SUB_CTA_PATRI		varchar(8),
@V_MAYOR_PATRI			varchar(4),
-- fin omrv 22.07.10
@LC_ESTADO_ASIG         varchar(20)

BEGIN  
	TRUNCATE TABLE SI_PATRIMONIO_TRX
	
		SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio,101) 
		SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
	
		IF @LN_ID_SI_PATRIMONIO IS NULL
				SET @LN_ID_SI_PATRIMONIO = 0	

        DECLARE C_1 CURSOR FOR	
		
			SELECT DISTINCT   
			sig_patrimonio.tipo_bien,
			sig_patrimonio.grupo_bien,
			sig_patrimonio.clase_bien,
			sig_patrimonio.familia_bien,
			sig_patrimonio.item_bien,
			sig_patrimonio.tipo_documento,
			sig_patrimonio.valor_nea,
			sig_patrimonio.fecha_nea,
			sig_patrimonio.medidas,
			sig_patrimonio.estado_actual,
			sig_patrimonio.estado_conserv,
			sig_patrimonio.fecha_compra,
			sig_patrimonio.valor_compra,
			sig_patrimonio.nro_orden,
			sig_patrimonio.fec_fin_vida,
			sig_patrimonio.vida_util,
			sig_patrimonio.tipo_modalidad,
			sig_patrimonio.centro_costo,
		    sig_patrimonio.codigo_activo ,
			sig_patrimonio.descripcion ,
			sig_patrimonio.modelo ,
			sig_patrimonio.nro_serie ,
			sig_patrimonio.marca,
			sig_patrimonio.tipo_marca,
			sig_patrimonio.estado, 
			sig_patrimonio.ano_proceso, 
		    sig_patrimonio.mes_proceso,
			sig_patrimonio.secuencia,
			sig_patrimonio.mayor,
			sig_patrimonio.SUB_CTA,
			'NO ASIGNADO'
			FROM sig_patrimonio 
			WHERE (sig_patrimonio.sec_ejec = @P_SEC_EJC) and          
		           (not exists (Select p.secuencia from sig_patrimonio p 
				    where  p.sec_ejec=sig_patrimonio.sec_ejec 
				    and   p.tipo_modalidad=sig_patrimonio.tipo_modalidad 
					and   p.secuencia=sig_patrimonio.secuencia 
					and  (p.mayor is null or p.mayor = '')) ) 
					and  (not exists ( Select a.secuencia 
					from sig_asignaciones a 
			   		where a.ano_eje = @P_ANO_EJE 
					and   a.sec_ejec = sig_patrimonio.sec_ejec 
					and   a.tipo_modalidad = sig_patrimonio.tipo_modalidad 
					and   a.secuencia = sig_patrimonio.secuencia)) 
				   --	and   (sig_patrimonio.estado = 1 ) 
					--AND sig_patrimonio.codigo_activo = '536446650064'
			UNION    
		SELECT  sig_patrimonio.tipo_bien,
				sig_patrimonio.grupo_bien,
				sig_patrimonio.clase_bien,
				sig_patrimonio.familia_bien,
				sig_patrimonio.item_bien,
				sig_patrimonio.tipo_documento,
				sig_patrimonio.valor_nea,
				sig_patrimonio.fecha_nea,
				sig_patrimonio.medidas,
				sig_patrimonio.estado_actual,
				sig_patrimonio.estado_conserv,
				sig_patrimonio.fecha_compra,
				sig_patrimonio.valor_compra,
				sig_patrimonio.nro_orden,
				sig_patrimonio.fec_fin_vida,
				sig_patrimonio.vida_util,
				sig_patrimonio.tipo_modalidad,
				sig_asignaciones.centro_entrega, 
				sig_patrimonio.codigo_activo ,
				sig_patrimonio.descripcion ,
				sig_patrimonio.modelo ,
				sig_patrimonio.nro_serie,
				sig_patrimonio.marca,
				sig_patrimonio.tipo_marca,
				sig_patrimonio.estado, 
				sig_patrimonio.ano_proceso, 
		        sig_patrimonio.mes_proceso,
				sig_patrimonio.secuencia,
				sig_patrimonio.mayor,
				sig_patrimonio.SUB_CTA,
			    'ASIGNADO'
				FROM sig_asignaciones,
    				 sig_patrimonio 
		WHERE ( sig_patrimonio.sec_ejec = sig_asignaciones.sec_ejec ) and          
		      ( sig_patrimonio.tipo_modalidad = sig_asignaciones.tipo_modalidad ) and          
		      ( sig_patrimonio.secuencia = sig_asignaciones.secuencia ) and          
		      ( sig_asignaciones.ano_eje = @P_ANO_EJE ) and          
		      ( sig_asignaciones.sec_ejec = @P_SEC_EJC ) and          
		      ( sig_asignaciones.nro_asignac = 
		      ( Select max(nro_asignac) from sig_asignaciones a 
					where a.ano_eje=sig_asignaciones.ano_eje 
					and a.sec_ejec=sig_asignaciones.sec_ejec 
					and a.tipo_modalidad=sig_asignaciones.tipo_modalidad 
					and a.secuencia=sig_asignaciones.secuencia )) 
					and (not exists 
						(Select p.secuencia from sig_patrimonio p 
							where p.sec_ejec=sig_patrimonio.sec_ejec 
							and p.tipo_modalidad=sig_patrimonio.tipo_modalidad 
							and p.secuencia=sig_patrimonio.secuencia 
							and ( p.mayor is null or p.mayor='')))
						   --	and ( sig_patrimonio.estado=1) 
			--AND sig_patrimonio.codigo_activo = '536446650064'
    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_TIPO_BIEN,  		@LC_GRUPO_BIEN,   		@LC_CLASE_BIEN, 
		 @LC_FAMILIA_BIEN, 		@LC_ITEM_BIEN, 	     	@LC_TIPO_DOCUMENTO, 
		 @LC_VALOR_NEA,         @LC_FECHA_NEA,          @LC_MEDIDAS,
		 @LC_ESTADO_ACTUAL, 	@LC_ESTADO_CONSERV,     @LC_FECHA_COMPRA,
		 @LC_VALOR_COMPRA, 		@LC_NRO_ORDEN,			@LC_FEC_FIN_VIDA,
		 @LC_VIDA_UTIL,         @LC_TIPO_MODALIDAD,     @LC_CENTRO_COSTO,
		 @LC_CODIGO_ACTIVO, 	@LC_DESCRIPCION,
		 @LC_MODELO,			@LC_NRO_SERIE,			@LC_NOMBRE,
		 @LC_MARCA,   			@LC_ESTADO, 			@LC_ANO_PROCESO,
		 @LC_MES_PROCESO,		@V_SECUENCIA_PATRI,		@V_MAYOR_PATRI,
		 @V_SUB_CTA_PATRI,		@LC_ESTADO_ASIG

    WHILE @@FETCH_STATUS = 0
	BEGIN
					SET @LN_ID_SI_PATRIMONIO = @LN_ID_SI_PATRIMONIO + 1
					-- inicio omrv 27.01.10
					SELECT  @SEDE					= SCC.SEDE,
							@PLIEGO					= SCC.PLIEGO,
							@COD_ESTABLEC			= CSD.COD_ESTABLEC,
							@COD_ESTABLEC_SIS		= EESS.COD_INTERNO,
							@COD_CATEGORIA			= EESS.CATEGORIA
							FROM  SIG_PPR_SEDE CSD JOIN SIG_CENTRO_COSTO SCC ON
								  ( SCC.ANO_EJE      = CSD.ANO_EJE      AND
									SCC.SEC_EJEC     = CSD.SEC_EJEC     AND
									SCC.PLIEGO       = CSD.PLIEGO       AND
									SCC.SEDE         = CSD.SEDE         AND
									SCC.ESTADO       = 'A')
									JOIN SIG_SEDES DSD ON
									(   DSD.SEDE   = CSD.SEDE AND
										  DSD.PLIEGO = CSD.PLIEGO ),
									SIG_PPR_ESTABLECIMIENTO EESS
									    WHERE EESS.ANO_EJE      = CSD.ANO_EJE
											AND EESS.SEC_EJEC     = CSD.SEC_EJEC
												AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
													AND CSD.ANO_EJE       = @P_ANO_EJE
														AND CSD.SEC_EJEC      = @P_SEC_EJC
															AND SCC.CENTRO_COSTO  = @LC_CENTRO_COSTO
									-- inicio fin 27.01.10
 

-- inicio omrv 27.01.10
-- SELECT COD_OGEI FROM SIG_PPR_ESTABLECIMIENTO
SELECT @SEDE					= SCC.SEDE,
       @D_SEDE					= DSD.NOMBRE_SEDE,
       @COD_ESTABLEC			= CSD.COD_ESTABLEC,
       @COD_ESTABLEC_SIS		= EESS.COD_INTERNO,
       @D_COD_ESTABLEC			= EESS.DESC_ESTABLEC,
       @COD_CATEGORIA			= EESS.CATEGORIA,
       @D_CORTO_COD_CATEGORIA	= (SELECT CA.NOMBRE_CORTO FROM 
			SIG_PPR_CATEGORIA CA 
		WHERE CA.ANO_EJE = CSD.ANO_EJE AND 
				CA.CATEGORIA = EESS.CATEGORIA AND 
                                                                CA.SECTOR_AMBITO=DSD.sector_ambito)  ,
	   @V_COD_OGEI				= COD_OGEI,
	   @V_SECTOR_AMBITO			= DSD.SECTOR_AMBITO

FROM  SIG_PPR_SEDE CSD JOIN SIG_CENTRO_COSTO  SCC ON
     ( SCC.ANO_EJE      = CSD.ANO_EJE      AND
       SCC.SEC_EJEC     = CSD.SEC_EJEC     AND
       SCC.PLIEGO       = CSD.PLIEGO       AND
       SCC.SEDE         = CSD.SEDE         AND
       SCC.ESTADO       = 'A')
JOIN SIG_SEDES DSD ON
     ( DSD.SEDE   = CSD.SEDE AND
       DSD.PLIEGO = CSD.PLIEGO ) ,
     SIG_PPR_ESTABLECIMIENTO EESS
WHERE EESS.ANO_EJE      = CSD.ANO_EJE
  AND EESS.SEC_EJEC     = CSD.SEC_EJEC
  AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
  AND CSD.ANO_EJE       = @P_ANO_EJE
  AND CSD.SEC_EJEC      = @P_SEC_EJC
  AND SCC.CENTRO_COSTO  = @LC_CENTRO_COSTO

-- fin 27.01.10
 
-- INICIO  22.07.10
----//////////////////////////////////////////////////////
select	@V_ANO_PATRIMONIO		=	ano_eje			,
		@V_MES_PATRIMONIO		=	nmes_proc_amc	,
		@V_DES_MES_PATRIMONIO	=(select nombre 
									from sig_maestro_det_cadena 
									where cod_maestro = 'MES_PROC_CTBLE' and
										  cod_detalle = sig_movimiento_contable.nmes_proc_amc) ,
		@V_FECHA_MOVIMTO_PATRI	=	fecha_movimto ,
		@V_VALOR_NETO			=	hvalor_inicial - (hdepr_inicial+hdepr_ejercicio+hdepr_ajustada), 
		@V_DEPREC_ACUMALDA		=	(hdepr_inicial+hdepr_ejercicio+hdepr_ajustada)
from sig_movimiento_contable
WHERE	ANO_EJE	= (select max(ANO_EJE)
							from sig_movimiento_contable
							WHERE
									SEC_EJEC = @P_SEC_EJC AND
									TIPO_MODALIDAD = @LC_TIPO_MODALIDAD AND
									SECUENCIA = @V_SECUENCIA_PATRI) AND
		SEC_EJEC = @P_SEC_EJC AND
		TIPO_MODALIDAD = @LC_TIPO_MODALIDAD AND
		SECUENCIA = @V_SECUENCIA_PATRI and
		nmes_proc_amc = (select max(nmes_proc_amc)
							from sig_movimiento_contable
							WHERE ANO_EJE	= (select max(ANO_EJE)
												from sig_movimiento_contable
												WHERE SEC_EJEC = @P_SEC_EJC AND
												TIPO_MODALIDAD = @LC_TIPO_MODALIDAD AND
												SECUENCIA = @V_SECUENCIA_PATRI) AND
									SEC_EJEC = @P_SEC_EJC AND
									TIPO_MODALIDAD = @LC_TIPO_MODALIDAD AND
									SECUENCIA = @V_SECUENCIA_PATRI AND
									NMES_PROC_AMC<'13')

----//////////////////////////////////////////////////////
select	@V_SUB_CTA		=	MAYOR + sub_cta	,
		@V_NOM_SUB_CTA	=	nombre  
from PLAN_CTB_SUB_CTA 
where ano_eje = (select max(ANO_EJE)
							from sig_movimiento_contable
							WHERE
									SEC_EJEC		= @P_SEC_EJC AND
									TIPO_MODALIDAD	= @LC_TIPO_MODALIDAD AND
									SECUENCIA		= @V_SECUENCIA_PATRI) and
		mayor	=	@V_MAYOR_PATRI	and
		sub_cta	=	@V_SUB_CTA_PATRI
----//////////////////////////////////////////////////////

-- FIN 22.07.10



			INSERT INTO SI_PATRIMONIO_TRX
		    ( ANO_EJE, 			SEC_EJEC, 			ID_SI_PATRIMONIO, 
			  TIPO_BIEN, 	    ITEM_CATALOGO,  	D_ITEM_CATALOGO,
			  TIPO_DOCUMENTO, VALOR_NEA,   		FECHA_NEA,
			  MEDIDAS,			ESTADO_ACTUAL,      ESTADO_CONSERVACION,
			  FECHA_COMPRA,     VALOR_COMPRA,       NRO_ORDEN,
			  FECHA_FIN_VIDA,   VIDA_UTIL,          TIPO_MODALIDAD,
  			  CENTRO_COSTO,     D_CENTRO_COSTO,     CODIGO_ACTIVO,
			  MODELO,           NRO_SERIE,			DESCRIPCION_ACTIVO, 
	  		  CODIGO_MARCA,	    NOMBRE_MARCA,       ESTADO_ACTIVO,
  			  FECHA_CARGA_FIN,  FECHA_ENVIO,        FECHA_CARGA_INICIO, 
  			  USUARIO_ENVIO,    ANO_PROCESO,        MES_PROCESO,
			  SEDE,				D_SEDE,				COD_ESTABLEC,
			  COD_ESTABLEC_SIS, D_COD_ESTABLEC,		COD_CATEGORIA,
			  D_CORTO_COD_CATEGORIA,ANO_PATRIMONIO			,MES_PATRIMONIO			,
			DES_MES_PATRIMONIO		,FECHA_MOVIMTO_PATRI	,VALOR_NETO				,
			SUB_CTA					,NOM_SUB_CTA			,SECTOR_AMBITO			,
			COD_OGEI				,DEPREC_ACUMULADA		,ASIGNACION)
			VALUES 
        	( @P_ANO_EJE, 	         @P_SEC_EJC, 	     @LN_ID_SI_PATRIMONIO,
			  @LC_TIPO_BIEN, 		 @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN,      
			  '',					 @LC_TIPO_DOCUMENTO, @LC_VALOR_NEA,      
			  @LC_FECHA_NEA,		 @LC_MEDIDAS, 	     @LC_ESTADO_ACTUAL,		@LC_ESTADO_CONSERV,
			  @LC_FECHA_COMPRA,      @LC_VALOR_COMPRA,   @LC_NRO_ORDEN,
			  @LC_FEC_FIN_VIDA,      @LC_VIDA_UTIL,      @LC_TIPO_MODALIDAD,
        	  @LC_CENTRO_COSTO,      '',				 @LC_CODIGO_ACTIVO,
              @LC_MODELO,            @LC_NRO_SERIE,      @LC_DESCRIPCION, 
			  @LC_MARCA,			 @LC_NOMBRE,	     @LC_ESTADO,
			  @fecha_carga_fin_1,    convert(varchar(10),getdate(),112),          
			  @fecha_carga_inicio_1, @usuario_n,         @LC_ANO_PROCESO,
			  @LC_MES_PROCESO,		 @SEDE,			'',  @COD_ESTABLEC,
			  @COD_ESTABLEC_SIS		,'', @COD_CATEGORIA, '',@V_ANO_PATRIMONIO			,@V_MES_PATRIMONIO		,
			@V_DES_MES_PATRIMONIO	,@V_FECHA_MOVIMTO_PATRI		,@V_VALOR_NETO			,
			@V_SUB_CTA				,@V_NOM_SUB_CTA				,@V_SECTOR_AMBITO		,
			@V_COD_OGEI				,@V_DEPREC_ACUMALDA, @LC_ESTADO_ASIG)


--**********
select 	@V_ANO_PATRIMONIO		=null
select 	@V_MES_PATRIMONIO		=null
select 	@V_DES_MES_PATRIMONIO	=null
select	@V_FECHA_MOVIMTO_PATRI	=null
select	@V_VALOR_NETO			=null
select	@V_DEPREC_ACUMALDA		=null
select	@V_SUB_CTA				=null
select	@V_NOM_SUB_CTA			=null

--**********

FETCH NEXT FROM C_1
    INTO @LC_TIPO_BIEN,  	@LC_GRUPO_BIEN,   		@LC_CLASE_BIEN, 
	 @LC_FAMILIA_BIEN, 		@LC_ITEM_BIEN, 	     	@LC_TIPO_DOCUMENTO, 
	 @LC_VALOR_NEA,         @LC_FECHA_NEA,          @LC_MEDIDAS,
	 @LC_ESTADO_ACTUAL, 	@LC_ESTADO_CONSERV,     @LC_FECHA_COMPRA,
	 @LC_VALOR_COMPRA, 		@LC_NRO_ORDEN,			@LC_FEC_FIN_VIDA,
	 @LC_VIDA_UTIL,         @LC_TIPO_MODALIDAD,     @LC_CENTRO_COSTO,
	 @LC_CODIGO_ACTIVO, 	@LC_DESCRIPCION,
	 @LC_MODELO,			@LC_NRO_SERIE,			@LC_NOMBRE,
	 @LC_MARCA,   			@LC_ESTADO, 			@LC_ANO_PROCESO,
	 @LC_MES_PROCESO,		@V_SECUENCIA_PATRI,		@V_MAYOR_PATRI,
	 @V_SUB_CTA_PATRI, @LC_ESTADO_ASIG		
    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


