				--SELECT @NUM = @NUM + 1
				SELECT @SADJUDICADO = 'N'

				INSERT INTO TMP_SEGUIMIENTO_PAAC_MODIF
				(
				CREPORTE,CANO_EJE,CSEC_EJEC,CTIPO_CONSOLID,CNRO_CONSOLID,
				CTIPO_GENERACION,CFLAG_PAAC,CNRO_PAAC,CITEM_UNICO,CTIPO_PROCESO,
