				ERUC_EJEC,CINSTRUMENTO,CVALOR_MONEDA,CFUENTE,
				INRO_ITEM,ITIPO_BIEN,IGRUPO_BIEN,ICLASE_BIEN,IFAMILIA_BIEN,
				IITEM_BIEN,INOMBRE_ITEM,IUNIDAD_MEDIDA,INOMBRE_UNIDAD,
				ICANTIDAD,IVALOR_MONEDA,
				SSEC_ITEM, SVALOR_REF, SESTADO, SNRO_PROCESO_SEL, SNRO_CONVOCATORIA,
				SPROVEEDOR, SNOM_PROVEEDOR, SNRO_RUC, SVALOR_UNIT, SVALOR_TOTAL,
				SCANTIDAD_ADJUDICADA, SNRO_PROV, SADJUDICADO, CNOM_TIPO_PROCESO_ABREV
				)
				VALUES
				(		
				@PN_REPORTE,@CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
				@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC, @CITEM_UNICO, @CTIPO_PROCESO,
				@CNOM_TIPO_PROCESO, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
				@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
				@ERUC_EJEC,@CINSTRUMENTO,@CVALOR_MONEDA,@CFUENTE,
				@NUM,@ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,@IFAMILIA_BIEN,
				@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,@INOMBRE_UNIDAD,
				@ICANTIDAD,@IVALOR_MONEDA ,
				0, 0.00,'', '', NULL,
				NULL, '', '', 0.00,0.00,
				0, 0, @SADJUDICADO, @CNOM_TIPO_PROCESO_ABREV
				)

				IF @@ERROR <> 0
				BEGIN
					CLOSE CUR_PAAC_ITEM
					DEALLOCATE CUR_PAAC_ITEM
					CLOSE CUR_PAAC
					DEALLOCATE CUR_PAAC
					GOTO ERROR
				END
			END

			FETCH CUR_PAAC_ITEM INTO @ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,
			@IFAMILIA_BIEN,@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,
			@INOMBRE_UNIDAD,@ICANTIDAD,@IVALOR_MONEDA 
		END
		CLOSE CUR_PAAC_ITEM
		DEALLOCATE CUR_PAAC_ITEM
	END

	--ASIGNAR DESCRIPCION DE ESTADO EN CABECERA
	--

	SELECT @CTITULO = ' '

	SELECT @WCUENTA_TOTAL_ITEM = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION
	
	IF @WCUENTA_TOTAL_ITEM IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_DESIERTO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'DESIERTO'

	IF @WCUENTA_TOTAL_ITEM_DESIERTO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_DESIERTO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_CANCELADO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'CANCELADO'

	IF @WCUENTA_TOTAL_ITEM_CANCELADO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_CANCELADO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_CONCLUIDO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'CONCLUIDO'

	IF @WCUENTA_TOTAL_ITEM_CONCLUIDO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_CONCLUIDO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_PROCESO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'PROCESO'

	IF @WCUENTA_TOTAL_ITEM_PROCESO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_PROCESO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_PENDIENTE = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'PENDIENTE'

	IF @WCUENTA_TOTAL_ITEM_PENDIENTE IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_PENDIENTE = 0 
	END



	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_DESIERTO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'DESIERTO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_CANCELADO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'CANCELADO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_CONCLUIDO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'ADJUDICACION TOTAL'
	END


	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_PROCESO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_PENDIENTE AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'PENDIENTE'
	END


	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_CONCLUIDO AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_CONCLUIDO > 0
	BEGIN
		SELECT @CTITULO = 'ADJUDICACION PARCIAL'
	END

	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_PROCESO AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_PROCESO > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_PENDIENTE AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_PENDIENTE > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_S = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO'AND
	SADJUDICADO = 'S'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_S IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_S = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_S > 0
	BEGIN
		SELECT @CTITULO = 'CONCLUIDO'
	END


	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_N = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO'AND
	SADJUDICADO = 'N'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_N IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_N = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_N > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END


	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO CONSENTIDA'AND
	SADJUDICADO = 'S'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S > 0
	BEGIN
		SELECT @CTITULO = 'CONCLUIDO'
	END


	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO CONSENTIDA'AND
	SADJUDICADO = 'N'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	UPDATE TMP_SEGUIMIENTO_PAAC_MODIF
	SET CTITULO = @CTITULO
	WHERE
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION 

	--
	--ASIGNAR DESCRIPCION DE ESTADO EN CABECERA

	FETCH CUR_PAAC INTO @CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
	@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC,@CITEM_UNICO ,@CTIPO_PROCESO,
	@CNOM_TIPO_PROCESO,@CNOM_TIPO_PROCESO_ABREV, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
	@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
	@ERUC_EJEC,@CINSTRUMENTO, @CVALOR_MONEDA

END

CLOSE CUR_PAAC
DEALLOCATE CUR_PAAC

RETURN 0
 
ERROR:
   RETURN 1;

-- /
GO


-- ----------------------------
-- procedure structure for DT_DROPPROPERTIESBYID
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_DROPPROPERTIESBYID]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_DROPPROPERTIESBYID]
GO

CREATE PROCEDURE [dbo].[DT_DROPPROPERTIESBYID]
	@id int,
	@property varchar(64)
as
	set nocount on

	if (@property is null) or (@property = '')
		delete from dbo.dtproperties where objectid=@id
	else
		delete from dbo.dtproperties 
			where objectid=@id and property=@property
GO


-- ----------------------------
-- procedure structure for SP_PPR_PROCESAR_TECHOC_FASE_3
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PPR_PROCESAR_TECHOC_FASE_3]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PPR_PROCESAR_TECHOC_FASE_3]
GO

CREATE PROCEDURE [dbo].[SP_PPR_PROCESAR_TECHOC_FASE_3]
(
@al_anio    NUMERIC,
@al_ejec    NUMERIC,
@al_fase    NUMERIC
)
AS
BEGIN
DECLARE @ls_flag_presup         VARCHAR(1) 
DECLARE @ls_centro_costo_presup VARCHAR(15) 
DECLARE @ls_centro_costo_cambio VARCHAR(15) 
DECLARE @ls_centro_costo        VARCHAR(15) 
DECLARE @ls_centro_padre        VARCHAR(15) 
DECLARE @ls_origen              VARCHAR(1) 
DECLARE @ls_codi_fuen           VARCHAR(2) 
DECLARE @ls_codi_fuen_impto     VARCHAR(2) 
DECLARE @ls_clas_gast           VARCHAR(20) 
DECLARE @ls_funcion             VARCHAR(2) 
DECLARE @ls_programa            VARCHAR(3) 
DECLARE @ld_secu_func           NUMERIC(4, 0) 
DECLARE @li_contador            NUMERIC(10, 0) 
DECLARE @ld_valor_imp_progra    NUMERIC(14, 2) 
DECLARE @li_secuencia           NUMERIC(10, 0) 
DECLARE @ld_valor_progra        NUMERIC(14, 2) 
DECLARE @ld_valor_aprob         NUMERIC(14, 2) 
DECLARE @ld_mnto_impto          NUMERIC(14, 2) 
DECLARE @ld_monto_progra        NUMERIC(14, 2) 
DECLARE @ld_mnto_total          NUMERIC(14, 2) 
DECLARE @ld_mnto_apro           NUMERIC(14, 2) 
DECLARE @ld_mnto_asig           NUMERIC(14, 2) 
DECLARE @ld_mnto_modif          NUMERIC(14, 2) 
DECLARE @ls_categ_gasto         VARCHAR(1) 
DECLARE @ls_flag_gen_esp        VARCHAR(1) 
DECLARE @ld_valor_imp_asignado  NUMERIC(14, 2) 
DECLARE @ld_valor_asignado      NUMERIC(14, 2) 
DECLARE @ld_monto_asignado      NUMERIC(14, 2) 
DECLARE @ld_monto_aprob         NUMERIC(14, 2) 
DECLARE @ld_valor_imp_aprob     NUMERIC(14, 2) 
DECLARE @ld_min_correl          NUMERIC(8, 0) 

SELECT
@li_contador    = COUNT(1)
FROM    SIG_PARAMETRO_EJECUTORA_ANIO
WHERE   SEC_EJEC        = @al_ejec
AND     ANO_EJE         = @al_anio
AND     COD_MAESTRO     = 'FLAG_TECHO_NIVEL' 
IF  (@li_contador   IS  NULL)   OR  (@li_contador   <=  0)
BEGIN
    RETURN 
END 

SELECT
@ls_flag_gen_esp    = VALOR
FROM    SIG_PARAMETRO_EJECUTORA_ANIO
WHERE   SEC_EJEC    = @al_ejec
AND     ANO_EJE     = @al_anio
AND     COD_MAESTRO = 'FLAG_TECHO_NIVEL' 

SELECT
@li_secuencia   = COALESCE(MAX(SECUENCIA), 0)
FROM    SIG_PPR_TECHO_PRESUPUESTO
WHERE   SEC_EJEC    = @al_ejec
AND     ANO_EJE     = @al_anio 

SET NOCOUNT ON 

CREATE  TABLE   #TMP_SIG_CN_TECHO_APROB_UPD
(
CORRELATIVO     NUMERIC(8, 0)   IDENTITY    NOT NULL,
CENTRO_COSTO    VARCHAR(15)     NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
FUENTE_IMPTO    VARCHAR(2)      NULL,
CLASIFICADOR    VARCHAR(20)     NULL,
SEC_FUNC        NUMERIC(4, 0)   NULL,
VALOR_CN1       NUMERIC(15, 2)  NULL,
VALOR_CN2       NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_CN_TECHO_APROBADO
(
CORRELATIVO     NUMERIC(8, 0)   IDENTITY    NOT NULL,
SECUENCIA       NUMERIC(8, 0)   NULL,
CENTRO_COSTO    VARCHAR(15)     NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
CATEG_GASTO     VARCHAR(1)      NULL,
GRUPO_GASTO     VARCHAR(1)      NULL,
CLASIFICADOR    VARCHAR(20)     NULL,
SEC_FUNC        NUMERIC(4, 0)   NULL,
FUNCION         VARCHAR(2)      NULL,
PROGRAMA        VARCHAR(3)      NULL,
VALOR_CN        NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_TECHO_APROB_UPD_01
(
CORRELATIVO     NUMERIC(20, 0)  IDENTITY    NOT NULL,
SECUENCIA       NUMERIC(8,0)    NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
VALOR_TECHO     NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_TECHO_APROB_UPD_02
(
CORRELATIVO     NUMERIC(20, 0)  IDENTITY    NOT NULL,
SECUENCIA       NUMERIC(8, 0)   NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
CATEG_GASTO     VARCHAR(1)      NULL,
GRUPO_GASTO     VARCHAR(1)      NULL,
VALOR_TECHO     NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_TECHO_APROB_UPD_03
(
CORRELATIVO     NUMERIC(20, 0)  IDENTITY    NOT NULL,
SECUENCIA       NUMERIC(8, 0)   NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
CATEG_GASTO     VARCHAR(1)      NULL,
GRUPO_GASTO     VARCHAR(1)      NULL,
CLASIFICADOR    VARCHAR(20)     NULL,
VALOR_TECHO     NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_TECHO_APROB_UPD_04
(
CORRELATIVO     NUMERIC(20, 0)  IDENTITY    NOT NULL,
SECUENCIA       NUMERIC(8, 0)   NULL,
ORIGEN          VARCHAR(1)      NULL,
FUENTE_FINANC   VARCHAR(2)      NULL,
CATEG_GASTO     VARCHAR(1)      NULL,
GRUPO_GASTO     VARCHAR(1)      NULL,
CLASIFICADOR    VARCHAR(20)     NULL,
SEC_FUNC        NUMERIC(4, 0)   NULL,
FUNCION         VARCHAR(2)      NULL,
PROGRAMA        VARCHAR(3)      NULL,
VALOR_TECHO     NUMERIC(15, 2)  NULL
) 

CREATE  TABLE   #TMP_SIG_TECHO_APROB_UPD_05
(
CORRELATIVO         NUMERIC(20, 0)  IDENTITY    NOT NULL,
SECUENCIA           NUMERIC(8, 0)   NULL,
ORIGEN              VARCHAR(1)      NULL,
FUENTE_FINANC       VARCHAR(2)      NULL,
CATEG_GASTO         VARCHAR(1)      NULL,
GRUPO_GASTO         VARCHAR(1)      NULL,
CLASIFICADOR        VARCHAR(20)     NULL,
SEC_FUNC            NUMERIC(4,0)    NULL,
FUNCION             VARCHAR(2)      NULL,
PROGRAMA            VARCHAR(3)      NULL,
CENTRO_COSTO_PRESUP VARCHAR(15)     NULL,
VALOR_TECHO         NUMERIC(15, 2)  NULL
) 

IF  @al_fase    = 3
    UPDATE  SIG_PPR_TECHO_PRESUPUESTO
    SET     MNTO_APROB      = 0
    WHERE   SEC_EJEC        = @al_ejec
    AND     ANO_EJE         = @al_anio
    AND     FLAG_META_APROB = '1' 

    DELETE
    FROM    #TMP_SIG_CN_TECHO_APROB_UPD 

    INSERT  INTO    #TMP_SIG_CN_TECHO_APROB_UPD(
                    CENTRO_COSTO, ORIGEN, FUENTE_FINANC, FUENTE_IMPTO,
                    CLASIFICADOR,SEC_FUNC
                    )
    SELECT  DISTINCT
    CENTRO_COSTO, ORIGEN, FUENTE_FINANC, FUENTE_IMPTO,
    CLASIFICADOR, SEC_FUNC
    FROM    SIG_PPR_CUADRO_NECESIDAD
    WHERE   ANO_EJE         = @al_anio
    AND     SEC_EJEC        = @al_ejec
    AND     FASE_CUADRO     = @al_fase
    AND     FUENTE_FINANC   IS  NOT NULL
    AND     CLASIFICADOR    IS  NOT NULL
    AND     SEC_FUNC        IS  NOT NULL 

    DELETE
    FROM    #TMP_SIG_CN_TECHO_APROBADO 

    INSERT  INTO    #TMP_SIG_CN_TECHO_APROBADO(
                    SECUENCIA, CENTRO_COSTO, ORIGEN, FUENTE_FINANC,
                    CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR, SEC_FUNC,
                    VALOR_CN
                    )
    SELECT
    0, C.CENTRO_COSTO, C.ORIGEN, C.FUENTE_IMPTO,
    C.CATEG_GASTO, C.GRUPO_GASTO, C.CLASIFICADOR, C.SEC_FUNC,
    SUM(COALESCE(C.VALOR_IMP_APROB, 0.00))
    FROM  SIG_PPR_CUADRO_NECESIDAD C JOIN META M
    ON C.ANO_EJE= M.ANO_EJE AND C.SEC_EJEC  = M.SEC_EJEC AND C.SEC_FUNC  = M.SEC_FUNC
    WHERE
    C.ANO_EJE      = @al_anio AND
    C.SEC_EJEC     = @al_ejec AND
    C.FASE_CUADRO  = @al_fase AND
    C.TIPO_IMPUESTO <>'0' 	  AND
    C.FUENTE_IMPTO IS NOT NULL AND
    C.CLASIFICADOR IS NOT NULL AND
    C.SEC_FUNC     IS NOT NULL
    GROUP BY
    C.CENTRO_COSTO, 	C.ORIGEN, 			C.FUENTE_IMPTO, 		C.CATEG_GASTO,
    C.GRUPO_GASTO,		C.CLASIFICADOR, 	C.SEC_FUNC 

    UPDATE #TMP_SIG_CN_TECHO_APROBADO
         SET FUNCION = (
                        SELECT META.FUNCION FROM META
                        WHERE META.ANO_EJE = @al_anio
                        AND META.SEC_EJEC  = @al_ejec
                        AND META.SEC_FUNC  = #TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC
                       ),
            PROGRAMA=   (
                        SELECT META.PROGRAMA FROM META
                        WHERE META.ANO_EJE = @al_anio
                        AND META.SEC_EJEC  = @al_ejec
                        AND META.SEC_FUNC  = #TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC
                        ) 

	SELECT
    @ld_min_correl = MIN(CORRELATIVO)
    FROM #TMP_SIG_CN_TECHO_APROBADO 

	UPDATE #TMP_SIG_CN_TECHO_APROBADO
	SET SECUENCIA = CORRELATIVO - @ld_min_correl + 1 

	SELECT
    @li_secuencia = COALESCE(MAX(SECUENCIA), 0)
	FROM SIG_PPR_TECHO_PRESUPUESTO
	WHERE ANO_EJE= @al_anio
    AND SEC_EJEC = @al_ejec 

	INSERT INTO SIG_PPR_TECHO_PRESUPUESTO
	(ANO_EJE     , SEC_EJEC      	, ORIGEN        	,FUENTE_FINANC,
	SECUENCIA    , CATEG_GASTO   	, GRUPO_GASTO    	,CLASIFICADOR,
	FUNCION      , PROGRAMA      	, SEC_FUNC     		,CENTRO_COSTO,
	PPTO_PROGRA  , PPTO_APROB	  	, PPTO_ASIGNADO	 	,PPTO_MODIF,
	MNTO_PROGRA  , MNTO_ASIG		, MNTO_APROB		,MNTO_MODIF,
	INDICADOR	 , PAAC_INICIAL  	, PAAC_MODIF     	,PORC_TECHO ,
	PORC_ASIG	 , FLAG_META_APROB)
	SELECT
	@al_anio    , @al_ejec  		, M.ORIGEN     		, M.FUENTE_FINANC,
	M.SECUENCIA + @li_secuencia, M.CATEG_GASTO, M.GRUPO_GASTO, M.CLASIFICADOR,
	M.FUNCION  	 , M.PROGRAMA   	, M.SEC_FUNC   		,M.CENTRO_COSTO,
	0 			 ,0  				, 0 				,0 ,
	0  			 ,0					, M.VALOR_CN 		,0 ,
	'0' 		 ,0	  				, 0   				,0 ,
	0			 ,'1'
	FROM #TMP_SIG_CN_TECHO_APROBADO M
	WHERE
	NOT EXISTS
	(SELECT 1
	FROM SIG_PPR_TECHO_PRESUPUESTO
	WHERE
	ANO_EJE  		= @al_anio AND
	SEC_EJEC 		= @al_ejec	AND
	ORIGEN 	 		= M.ORIGEN AND
	FUENTE_FINANC 	= M.FUENTE_FINANC AND
	CATEG_GASTO 	= M.CATEG_GASTO AND
	GRUPO_GASTO 	= M.GRUPO_GASTO AND
	CLASIFICADOR 	= M.CLASIFICADOR AND
	FUNCION     	= M.FUNCION AND
	PROGRAMA		= M.PROGRAMA  AND
	SEC_FUNC 		= M.SEC_FUNC AND
	CENTRO_COSTO	= M.CENTRO_COSTO AND
	INDICADOR     	= '0' AND
	FLAG_META_APROB = '1') 

	DELETE
    FROM #TMP_SIG_CN_TECHO_APROBADO 

	INSERT INTO #TMP_SIG_CN_TECHO_APROBADO
	(SECUENCIA, 		CENTRO_COSTO, 		ORIGEN, 		FUENTE_FINANC,
	CATEG_GASTO,  		GRUPO_GASTO,		CLASIFICADOR,	SEC_FUNC,
	VALOR_CN)
	SELECT
	0, 					C.CENTRO_COSTO, 	C.ORIGEN, 		C.FUENTE_FINANC,
	C.CATEG_GASTO,		C.GRUPO_GASTO,		C.CLASIFICADOR, C.SEC_FUNC,
	SUM(COALESCE(C.MONTO_APROB, 0.00))
  	FROM  SIG_PPR_CUADRO_NECESIDAD C, META M
 	WHERE
	C.ANO_EJE   	= M.ANO_EJE AND
	C.SEC_EJEC  	= M.SEC_EJEC AND
	C.SEC_FUNC  	= M.SEC_FUNC AND
	C.ANO_EJE       = @al_anio AND
	C.SEC_EJEC      = @al_ejec AND
	C.FASE_CUADRO   = @al_fase AND
	C.FUENTE_FINANC IS NOT NULL AND
	C.CLASIFICADOR  IS NOT NULL AND
	C.SEC_FUNC      IS NOT NULL
	GROUP BY
	C.CENTRO_COSTO, 	C.ORIGEN, 			C.FUENTE_FINANC,C.CATEG_GASTO,
	C.GRUPO_GASTO,		C.CLASIFICADOR, 	C.SEC_FUNC 

     UPDATE #TMP_SIG_CN_TECHO_APROBADO
     SET FUNCION = (
                    SELECT META.FUNCION FROM META
                    WHERE META.ANO_EJE = @al_anio
                    AND META.SEC_EJEC  = @al_ejec
                    AND META.SEC_FUNC  = #TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC
                   ),
        PROGRAMA=   (
                    SELECT META.PROGRAMA FROM META
                    WHERE META.ANO_EJE = @al_anio
                    AND META.SEC_EJEC  = @al_ejec
                    AND META.SEC_FUNC  = #TMP_SIG_CN_TECHO_APROBADO.SEC_FUNC
                    ) 

	SELECT
    @ld_min_correl = MIN(CORRELATIVO)
    FROM #TMP_SIG_CN_TECHO_APROBADO 

	UPDATE #TMP_SIG_CN_TECHO_APROBADO
	SET SECUENCIA = CORRELATIVO - @ld_min_correl + 1 

	SELECT
    @li_secuencia = MAX(SECUENCIA)
	FROM SIG_PPR_TECHO_PRESUPUESTO
	WHERE ANO_EJE= @al_anio
    AND SEC_EJEC = @al_ejec 

	IF @li_secuencia  IS NULL
	BEGIN
	  SELECT @li_secuencia = 0 
	END 

	INSERT INTO SIG_PPR_TECHO_PRESUPUESTO
	(ANO_EJE     	, SEC_EJEC      	, ORIGEN        	, FUENTE_FINANC,
	SECUENCIA    	, CATEG_GASTO   	, GRUPO_GASTO    	, CLASIFICADOR,
	FUNCION      	, PROGRAMA      	, SEC_FUNC     		, CENTRO_COSTO,
	PPTO_PROGRA  	, PPTO_APROB	  	, PPTO_ASIGNADO	 	, PPTO_MODIF,
	MNTO_PROGRA  	, MNTO_ASIG		  	, MNTO_APROB		, MNTO_MODIF,
	INDICADOR	 	, PAAC_INICIAL  	, PAAC_MODIF     	,PORC_TECHO ,
	PORC_ASIG		, FLAG_META_APROB)
	SELECT
	@al_anio    	, @al_ejec  		, M.ORIGEN     		, M.FUENTE_FINANC,
	M.SECUENCIA + @li_secuencia, M.CATEG_GASTO, M.GRUPO_GASTO, M.CLASIFICADOR,
	M.FUNCION  		, M.PROGRAMA   		, M.SEC_FUNC   		,M.CENTRO_COSTO,
	0 				, 0  				, 0 				,0 ,
	0  				, 0					, M.VALOR_CN 		, 0,
	'0' 			, 0	  				, 0   				,0  ,
	0				, '1'
	FROM #TMP_SIG_CN_TECHO_APROBADO M
	WHERE
    NOT EXISTS (SELECT 1
		FROM SIG_PPR_TECHO_PRESUPUESTO
		WHERE
		ANO_EJE  		= @al_anio AND
		SEC_EJEC 		= @al_ejec	AND
		ORIGEN 			= M.ORIGEN AND
		FUENTE_FINANC 	= M.FUENTE_FINANC AND
		CATEG_GASTO 	= M.CATEG_GASTO AND
		GRUPO_GASTO 	= M.GRUPO_GASTO AND
		CLASIFICADOR 	= M.CLASIFICADOR AND
		FUNCION     	= M.FUNCION AND
		PROGRAMA		= M.PROGRAMA  AND
		SEC_FUNC 		= M.SEC_FUNC AND
		CENTRO_COSTO	= M.CENTRO_COSTO AND
		INDICADOR     	= '0' AND
		FLAG_META_APROB = '1') 

	DELETE
    FROM #TMP_SIG_CN_TECHO_APROBADO 

	DELETE
    FROM #TMP_SIG_CN_TECHO_APROB_UPD 

	INSERT INTO #TMP_SIG_CN_TECHO_APROB_UPD
	(CENTRO_COSTO,		ORIGEN,			FUENTE_FINANC,		FUENTE_IMPTO,
	CLASIFICADOR,		SEC_FUNC,		VALOR_CN1,			VALOR_CN2)
	SELECT
	C.CENTRO_COSTO, 	C.ORIGEN, 		C.FUENTE_FINANC, 	'00',
	C.CLASIFICADOR, 	C.SEC_FUNC, 	SUM(C.VALOR_IMP_APROB), SUM(C.MONTO_APROB)
  	FROM  SIG_PPR_CUADRO_NECESIDAD C
 	WHERE
	C.ANO_EJE      = @al_anio AND
	C.SEC_EJEC     = @al_ejec AND
	C.FASE_CUADRO  = @al_fase AND
	C.FUENTE_FINANC IS NOT NULL  AND
	C.CLASIFICADOR 	IS NOT NULL AND
	C.SEC_FUNC 		IS NOT NULL
	GROUP BY C.CENTRO_COSTO, C.ORIGEN, C.FUENTE_FINANC, C.CLASIFICADOR, C.SEC_FUNC 

	UPDATE SIG_PPR_TECHO_PRESUPUESTO
	SET MNTO_APROB = (SELECT SUM(COALESCE(M.VALOR_CN2,0.00))
					FROM #TMP_SIG_CN_TECHO_APROB_UPD M
					WHERE
					M.ORIGEN   	 	= SIG_PPR_TECHO_PRESUPUESTO.ORIGEN AND
					M.FUENTE_FINANC	= SIG_PPR_TECHO_PRESUPUESTO.FUENTE_FINANC AND
					M.CLASIFICADOR 	= SIG_PPR_TECHO_PRESUPUESTO.CLASIFICADOR AND
					M.SEC_FUNC  	= SIG_PPR_TECHO_PRESUPUESTO.SEC_FUNC AND
					M.CENTRO_COSTO 	= SIG_PPR_TECHO_PRESUPUESTO.CENTRO_COSTO)
	WHERE
	ANO_EJE  	 	= @al_anio AND
	SEC_EJEC 	 	= @al_ejec AND
	INDICADOR 	 	= '0' AND
	FLAG_META_APROB = '1' AND
	EXISTS (SELECT '1'
			FROM #TMP_SIG_CN_TECHO_APROB_UPD M
			WHERE
			M.ORIGEN   	 	= SIG_PPR_TECHO_PRESUPUESTO.ORIGEN AND
			M.FUENTE_FINANC	= SIG_PPR_TECHO_PRESUPUESTO.FUENTE_FINANC AND
			M.CLASIFICADOR 	= SIG_PPR_TECHO_PRESUPUESTO.CLASIFICADOR AND
			M.SEC_FUNC  	= SIG_PPR_TECHO_PRESUPUESTO.SEC_FUNC AND
			M.CENTRO_COSTO 	= SIG_PPR_TECHO_PRESUPUESTO.CENTRO_COSTO) 

	DELETE
    FROM #TMP_SIG_CN_TECHO_APROB_UPD 

	INSERT INTO #TMP_SIG_CN_TECHO_APROB_UPD
	(CENTRO_COSTO,			ORIGEN,			FUENTE_FINANC,			FUENTE_IMPTO,
	CLASIFICADOR,			SEC_FUNC,		VALOR_CN1,				VALOR_CN2)
	SELECT
	C.CENTRO_COSTO, 		C.ORIGEN, 		'00',					C.FUENTE_IMPTO,
	C.CLASIFICADOR, 		C.SEC_FUNC, 	SUM(C.VALOR_IMP_APROB), SUM(C.MONTO_APROB)
  	FROM  SIG_PPR_CUADRO_NECESIDAD C
 	WHERE
	C.ANO_EJE      = @al_anio AND
	C.SEC_EJEC     = @al_ejec AND
	C.FASE_CUADRO  = @al_fase AND
	C.TIPO_IMPUESTO <>'0' AND
	C.FUENTE_IMPTO IS NOT NULL AND
	C.CLASIFICADOR IS NOT NULL AND
	C.SEC_FUNC 	   IS NOT NULL
	GROUP BY C.CENTRO_COSTO, C.ORIGEN, C.FUENTE_IMPTO, C.CLASIFICADOR, C.SEC_FUNC 

	UPDATE SIG_PPR_TECHO_PRESUPUESTO
	SET MNTO_APROB = COALESCE(MNTO_APROB, 0.00) + (SELECT SUM(COALESCE(M.VALOR_CN1,0.00))
			FROM #TMP_SIG_CN_TECHO_APROB_UPD M
			WHERE
			M.ORIGEN   	 = SIG_PPR_TECHO_PRESUPUESTO.ORIGEN AND
			M.FUENTE_IMPTO   = SIG_PPR_TECHO_PRESUPUESTO.FUENTE_FINANC AND
			M.CLASIFICADOR   = SIG_PPR_TECHO_PRESUPUESTO.CLASIFICADOR AND
			M.SEC_FUNC       = SIG_PPR_TECHO_PRESUPUESTO.SEC_FUNC AND
			M.CENTRO_COSTO   = SIG_PPR_TECHO_PRESUPUESTO.CENTRO_COSTO)
	WHERE
	ANO_EJE  	 	= @al_anio AND
	SEC_EJEC 	 	= @al_ejec AND
	INDICADOR 		= '0' AND
	FLAG_META_APROB = '1' AND
	EXISTS(SELECT '1'
		   FROM #TMP_SIG_CN_TECHO_APROB_UPD M
		   WHERE
		   M.ORIGEN   	 	= SIG_PPR_TECHO_PRESUPUESTO.ORIGEN AND
		   M.FUENTE_IMPTO   = SIG_PPR_TECHO_PRESUPUESTO.FUENTE_FINANC AND
		   M.CLASIFICADOR   = SIG_PPR_TECHO_PRESUPUESTO.CLASIFICADOR AND
		   M.SEC_FUNC       = SIG_PPR_TECHO_PRESUPUESTO.SEC_FUNC AND
		   M.CENTRO_COSTO   = SIG_PPR_TECHO_PRESUPUESTO.CENTRO_COSTO) 

	DELETE
    FROM #TMP_SIG_CN_TECHO_APROB_UPD 
END 

DECLARE C_0B CURSOR FOR
SELECT
DISTINCT CENTRO_COSTO
FROM SIG_PPR_TECHO_PRESUPUESTO
WHERE   ANO_EJE  	 = @al_anio 
AND     SEC_EJEC 	 = @al_ejec 
AND     INDICADOR     = '0' 
AND     (CENTRO_COSTO_PRESUP IS NULL OR CENTRO_COSTO_PRESUP = '') 

OPEN    C_0B 
WHILE   1 = 1
BEGIN
    FETCH   C_0B
    INTO    @ls_centro_costo 
    IF  @@FETCH_STATUS <> 0
    BEGIN
        BREAK 
    END 

	SELECT  @ls_centro_costo_cambio = @ls_centro_costo 
	SELECT  @ls_flag_presup         = 'N' 

	WHILE @ls_flag_presup = 'N'
	BEGIN
		SELECT
        @ls_centro_padre = CENTRO_PADRE,
		@ls_flag_presup = FLAG_PRESUPUESTO
		FROM SIG_CENTRO_COSTO
		WHERE   ANO_EJE = @al_anio 
        AND     SEC_EJEC = @al_ejec 
        AND		CENTRO_COSTO = @ls_centro_costo_cambio 

		IF (@ls_flag_presup IS NULL) OR (@ls_flag_presup = '')
		BEGIN
			SELECT @ls_flag_presup = 'N' 
		END 

		IF UPPER(@ls_flag_presup) <> 'S'
		BEGIN
			IF  (@ls_centro_padre IS NULL) OR (@ls_centro_padre = '')
			BEGIN
				SELECT @ls_flag_presup = 'S' 
				SELECT @ls_centro_costo_presup = '' 
			END
			ELSE
			BEGIN
				SELECT @ls_centro_costo_cambio = @ls_centro_padre 
				SELECT @ls_flag_presup = 'N' 
			END 
		END
		ELSE
		BEGIN
			SELECT @ls_flag_presup = 'S' 
			SELECT @ls_centro_costo_presup = @ls_centro_costo_cambio 
		END 
	END 

	UPDATE  SIG_PPR_TECHO_PRESUPUESTO
	SET CENTRO_COSTO_PRESUP = @ls_centro_costo_presup
	WHERE   ANO_EJE 	 = @al_anio 
    AND     SEC_EJEC 	 = @al_ejec 
    AND     CENTRO_COSTO = @ls_centro_costo 
    AND     INDICADOR 	 = '0'
    AND     CENTRO_COSTO_PRESUP IS NULL OR CENTRO_COSTO_PRESUP = '' 
END 

CLOSE       C_0B 
DEALLOCATE  C_0B 

IF @al_fase = 1 OR @al_fase = 2
BEGIN
    RETURN 
END
ELSE
BEGIN
	DELETE
    FROM #TMP_SIG_TECHO_APROB_UPD_01 

	INSERT INTO #TMP_SIG_TECHO_APROB_UPD_01
	(SECUENCIA, 		ORIGEN, 		FUENTE_FINANC, 			VALOR_TECHO)
	SELECT 0, 			A.ORIGEN, 		A.FUENTE_FINANC, 		SUM(A.MNTO_APROB)
	FROM SIG_PPR_TECHO_PRESUPUESTO A
	WHERE
	A.ANO_EJE 		= @al_anio AND
	A.SEC_EJEC 		= @al_ejec AND
	A.INDICADOR     = '0' AND
	A.FLAG_META_APROB = '1' AND
	A.FUNCION 		IS NOT NULL AND
	A.PROGRAMA 		IS NOT NULL AND
	NOT EXISTS (SELECT 1
		FROM SIG_PPR_TECHO_PRESUPUESTO B
		WHERE
		B.ANO_EJE 		= @al_anio AND
		B.SEC_EJEC 		= @al_ejec AND
		B.ORIGEN    	= A.ORIGEN AND
		B.FUENTE_FINANC = A.FUENTE_FINANC AND
		B.INDICADOR     = '1' AND
		B.FLAG_META_APROB = '1')
	GROUP BY A.ORIGEN, A.FUENTE_FINANC 

	SELECT @ld_min_correl = 0 

	SELECT
    @ld_min_correl = MIN(CORRELATIVO)
    FROM #TMP_SIG_TECHO_APROB_UPD_01 

	UPDATE #TMP_SIG_TECHO_APROB_UPD_01
	SET SECUENCIA = CORRELATIVO - @ld_min_correl + 1 

