	EXISTS			(   SELECT '1' FROM SIG_PPR_TECHO_PRESUPUESTO B
						WHERE
						B.ANO_EJE 		  = @al_anio AND
						B.SEC_EJEC 		  = @al_ejec AND
						B.INDICADOR       = '0' AND
