						B.PROGRAMA IS NOT NULL AND
						B.ORIGEN = SIG_PPR_TECHO_PRESUPUESTO.ORIGEN AND
						B.FUENTE_FINANC = SIG_PPR_TECHO_PRESUPUESTO.FUENTE_FINANC) 

	DELETE
    FROM #TMP_SIG_TECHO_APROB_UPD_02 

	INSERT INTO #TMP_SIG_TECHO_APROB_UPD_02
	(SECUENCIA, 		ORIGEN, 		FUENTE_FINANC, 		CATEG_GASTO,
	GRUPO_GASTO, 		VALOR_TECHO)
	SELECT
	0, 					A.ORIGEN, 		A.FUENTE_FINANC, 	A.CATEG_GASTO,
	A.GRUPO_GASTO, 		SUM(A.MNTO_APROB)
	FROM SIG_PPR_TECHO_PRESUPUESTO A
	WHERE
	A.ANO_EJE 		  = @al_anio AND
	A.SEC_EJEC 		  = @al_ejec AND
	A.INDICADOR       = '0' AND
	A.FLAG_META_APROB = '1' AND
	A.FUNCION  IS NOT NULL AND
	A.PROGRAMA IS NOT NULL AND
	NOT EXISTS (SELECT 1
		FROM SIG_PPR_TECHO_PRESUPUESTO B
		WHERE
		B.ANO_EJE 		= @al_anio AND
		B.SEC_EJEC 		= @al_ejec AND
		B.ORIGEN    	= A.ORIGEN AND
		B.FUENTE_FINANC = A.FUENTE_FINANC AND
		B.CATEG_GASTO 	= A.CATEG_GASTO AND
		B.GRUPO_GASTO 	= A.GRUPO_GASTO AND
		B.INDICADOR     = '2' AND
		B.FLAG_META_APROB = '1')
	GROUP BY A.ORIGEN, A.FUENTE_FINANC, A.CATEG_GASTO, A.GRUPO_GASTO 

	SELECT @ld_min_correl = 0 

	SELECT
    @ld_min_correl = MIN(CORRELATIVO)
    FROM #TMP_SIG_TECHO_APROB_UPD_02 

	UPDATE #TMP_SIG_TECHO_APROB_UPD_02
	SET SECUENCIA = CORRELATIVO - @ld_min_correl + 1 

	SELECT
    @li_secuencia = MAX(SECUENCIA)
	FROM SIG_PPR_TECHO_PRESUPUESTO
	WHERE ANO_EJE= @al_anio
    AND SEC_EJEC = @al_ejec 

	IF @li_secuencia  IS NULL
	BEGIN
	  SELECT @li_secuencia = 0 
	END 

	INSERT INTO SIG_PPR_TECHO_PRESUPUESTO
	(ANO_EJE     	, SEC_EJEC      	, ORIGEN        	, FUENTE_FINANC,
	SECUENCIA    	, CATEG_GASTO   	, GRUPO_GASTO    	, CLASIFICADOR,
	FUNCION      	, PROGRAMA      	, SEC_FUNC     		, CENTRO_COSTO,
	PPTO_PROGRA  	, PPTO_APROB	  	, PPTO_ASIGNADO	 	, PPTO_MODIF,
	MNTO_PROGRA  	, MNTO_ASIG		  	, MNTO_APROB		, MNTO_MODIF,
	INDICADOR	 	, PAAC_INICIAL  	, PAAC_MODIF     	, PORC_TECHO ,
	PORC_ASIG		, SEC_FUNC_PROP		, FLAG_META_APROB)
	SELECT
	@al_anio    	, @al_ejec  		, M.ORIGEN     		, M.FUENTE_FINANC,
	M.SECUENCIA + @li_secuencia, M.CATEG_GASTO, M.GRUPO_GASTO, NULL,
	NULL  			, NULL   	, NULL   		, NULL,
	0 			, 0  		, 0 			, 0 ,
	0  			, 0		, M.VALOR_TECHO 	, 0,
	'2' 			, 0	  	, 0   			,0  ,
	0			, NULL		, '1'
	FROM #TMP_SIG_TECHO_APROB_UPD_02 M 

	UPDATE SIG_PPR_TECHO_PRESUPUESTO
	SET MNTO_APROB =  ( SELECT SUM(A.MNTO_APROB)
						FROM SIG_PPR_TECHO_PRESUPUESTO A
						WHERE
						A.ANO_EJE 		  = @al_anio AND
						A.SEC_EJEC 		  = @al_ejec AND
						A.INDICADOR       = '0' AND
						A.FLAG_META_APROB = '1' AND
