	programa VARCHAR(3) COLLATE Modern_Spanish_CI_AS NULL,
	valor_techo NUMERIC(15,2) NULL
	)

CREATE TABLE #TMP_SIG_TECHO_APROB_UPD_05
	(
	correlativo NUMERIC(20,0) IDENTITY NOT NULL,
	secuencia NUMERIC(8,0) NULL,
	origen VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_financ VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	categ_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	grupo_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	clasIFicador VARCHAR(20) COLLATE Modern_Spanish_CI_AS NULL,
	sec_func NUMERIC(4,0) NULL,
	funcion VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	programa VARCHAR(3) COLLATE Modern_Spanish_CI_AS NULL,
	centro_costo_presup VARCHAR(15) COLLATE Modern_Spanish_CI_AS NULL,
	valor_techo NUMERIC(15,2) NULL
	)

IF @PN_FASE = 3
 UPDATE sig_techo_presupuesto
 SET    mnto_aprob  =0 
 WHERE ANO_EJE = @PN_ANIO AND
       SEC_EJEC = @PN_EJEC AND
       flag_meta_aprob = '1'

IF @@ERROR <> 0
return -1


	DELETE FROM #TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO #TMP_SIG_CN_TECHO_APROB_UPD
	( centro_costo,	origen,	fuente_financ,fuente_impto,clasIFicador,sec_func)
	SELECT DISTINCT m.centro_costo, m.origen, m.fuente_financ , m.fuente_impto, m.clasIFicador, m.sec_func
