DECLARE c_0b CURSOR for
SELECT distinct centro_costo
FROM sig_techo_presupuesto
WHERE 
ano_eje  	 = @PN_ANIO AND
sec_ejec 	 = @PN_EJEC AND
indicador     = '0' AND
(centro_costo_presup is null or centro_costo_presup = '')

open c_0b
fetch c_0b into @ls_centro_costo

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @ls_centro_costo_cambio = @ls_centro_costo

	SELECT @ls_flag_presup = 'N'

	WHILE @ls_flag_presup = 'N'
	BEGIN
		SELECT @ls_centro_padre = CENTRO_PADRE,
		@ls_flag_presup = FLAG_PRESUPUESTO
		FROM SIG_CENTRO_COSTO
		WHERE 
		ano_eje = @PN_ANIO AND
		sec_ejec = @PN_EJEC AND
		centro_costo = @ls_centro_costo_cambio

		IF (@ls_flag_presup IS NULL) or (@ls_flag_presup = '')
		BEGIN
			SELECT @Ls_flag_presup = 'N'
		END
		
		IF upper(@ls_flag_presup) <> 'S' 
		BEGIN
			IF  (@ls_centro_padre IS NULL) or (@ls_centro_padre = '') 
			BEGIN
				SELECT @Ls_flag_presup = 'S'
				SELECT @ls_centro_costo_presup = ''
			END			   	
			ELSE
			BEGIN
				SELECT @ls_centro_costo_cambio = @ls_centro_padre
				SELECT @Ls_flag_presup = 'N'
			END
		END
		ELSE
		BEGIN
			SELECT @Ls_flag_presup = 'S'
			SELECT @ls_centro_costo_presup = @ls_centro_costo_cambio
		END
	END

	UPDATE  sig_techo_presupuesto
	SET centro_costo_presup = @ls_centro_costo_presup
	WHERE 
	ano_eje 	 = @PN_ANIO AND
	sec_ejec 	 = @PN_EJEC AND
	centro_costo = @ls_centro_costo AND 
	indicador 	 = '0' AND
	centro_costo_presup is null or centro_costo_presup = ''

	IF @@ERROR <> 0
	BEGIN
		CLOSE c_0b
		DEALLOCATE c_0b		
		return -1
	END
		
	fetch c_0b into @ls_centro_costo
END

CLOSE c_0b
DEALLOCATE c_0b


