-- ----------------------------
-- procedure structure for SP_INT_CARGA_MAESTROS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_INT_CARGA_MAESTROS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_INT_CARGA_MAESTROS]
GO

CREATE PROCEDURE [dbo].[SP_INT_CARGA_MAESTROS]
(@ano_eje numeric(4), @sec_ejec numeric(6), @sec_aud numeric(10), @retorno numeric(2) OUT)
AS
DECLARE @total_reg numeric(5)

--Verificando Meta
SELECT @total_reg = count(*)
  FROM sig_int_tmp_meta
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg <= 0
   return -30

--Verificando Función
SELECT @total_reg = count(*)
  FROM sig_int_funcion_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Función
        INSERT INTO Funcion
                    (ano_eje, funcion, nombre, estado)
             SELECT DISTINCT
                    ano_eje, funcion, nombre, estado
               FROM sig_int_funcion_nombre
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT F.ano_eje
                                  FROM Funcion F
                                 WHERE F.ano_eje = ano_eje and
                                       F.funcion = funcion)
        
        If @@ERROR < 0
           Return -31
   End

--Verificando Programa
SELECT @total_reg = count(*)
  FROM sig_int_programa_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Programa Nombre
        INSERT INTO Programa_Nombre
                    (ano_eje, programa, nombre, estado)
             SELECT DISTINCT
                    ano_eje, programa, nombre, estado
               FROM sig_int_programa_nombre
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT P.ano_eje
                                  FROM Programa_Nombre P
                                 WHERE P.ano_eje  = ano_eje and
                                       P.programa = programa)
        
        If @@ERROR < 0
           Return -32
        
        --Actualizando Programa Nombre
        UPDATE Programa_Nombre
           SET nombre = (SELECT DISTINCT P.nombre
                           FROM sig_int_programa_nombre P
                          WHERE P.ano_eje_mov  = @ano_eje  and
                                P.sec_ejec_mov = @sec_ejec and
                                P.sec_aud_mov  = @sec_aud  and
                                P.ano_eje      = ano_eje   and
                                P.Programa     = programa ),
               estado = (SELECT DISTINCT P.estado
                           FROM sig_int_programa_nombre P
                          WHERE P.ano_eje_mov  = @ano_eje  and
                                P.sec_ejec_mov = @sec_ejec and
                                P.sec_aud_mov  = @sec_aud  and
                                P.ano_eje      = ano_eje   and
                                P.programa     = programa)
         WHERE EXISTS (SELECT P.ano_eje FROM sig_int_programa_nombre P
                        WHERE P.ano_eje_mov  = @ano_eje  and
                              P.sec_ejec_mov = @sec_ejec and
                              P.sec_aud_mov  = @sec_aud  and
                              P.ano_eje      = ano_eje   and
                              P.programa     = programa)
        
        If @@ERROR < 0
           Return -33
        
        --Agregando Programa
        INSERT INTO Programa
                    (ano_eje, funcion, programa)
             SELECT DISTINCT
                    ano_eje, funcion, programa
               FROM sig_int_tmp_meta
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT P.ano_eje
                                  FROM Programa P
                                 WHERE P.ano_eje  = ano_eje and
                                       P.funcion  = funcion and
                                       P.programa = programa)
        
        If @@ERROR < 0
           Return -34
   END

--Verificando Sub Programa
SELECT @total_reg = count(*)
  FROM sig_int_sub_programa_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Sub Programa Nombre
        INSERT INTO sub_programa_nombre
                    (ano_eje,  sub_programa, nombre, estado)
             SELECT DISTINCT
                    ano_eje, sub_programa, nombre, estado
               FROM sig_int_sub_programa_nombre
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT P.ano_eje
                                  FROM sub_programa_nombre P
                                 WHERE P.ano_eje      = ano_eje and
                                       P.sub_programa = sub_programa)
        
        If @@ERROR < 0
           Return -35
        
        --Actualizando Sub Programa Nombre
        UPDATE sub_programa_nombre
           SET nombre = (SELECT DISTINCT SP.nombre
                           FROM sig_int_sub_programa_nombre SP
                          WHERE SP.ano_eje_mov  = @ano_eje  and
                                SP.sec_ejec_mov = @sec_ejec and
                                SP.sec_aud_mov  = @sec_aud  and
                                SP.ano_eje      = ano_eje   and
                                SP.sub_programa = sub_programa),
               estado = (SELECT DISTINCT SP.estado
                           FROM sig_int_sub_programa_nombre SP
                          WHERE SP.ano_eje_mov  = @ano_eje  and
                                SP.sec_ejec_mov = @sec_ejec and
                                SP.sec_aud_mov  = @sec_aud  and
                                SP.ano_eje      = ano_eje   and
                                SP.sub_programa = sub_programa)
         WHERE EXISTS (SELECT SP.ano_eje FROM sig_int_sub_programa_nombre SP
                        WHERE SP.ano_eje_mov  = @ano_eje  and
                              SP.sec_ejec_mov = @sec_ejec and
                              SP.sec_aud_mov  = @sec_aud  and
                              SP.ano_eje      = ano_eje   and
                              SP.sub_programa = sub_programa)
        
        If @@ERROR < 0
           Return -36
        
        --Agregando Sub Programa
        INSERT INTO Sub_Programa
                    (ano_eje, funcion, programa, sub_programa)
             SELECT DISTINCT
                    ano_eje, funcion, programa, sub_programa
               FROM sig_int_tmp_meta
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT SP.ano_eje
                                  FROM Sub_Programa SP
                                 WHERE SP.ano_eje      = ano_eje  and
                                       SP.funcion      = funcion  and
                                       SP.programa     = programa and
                                       SP.sub_programa = sub_programa)
        
        If @@ERROR < 0
           Return -37
   End
   
--Verificando Act. Proy.
SELECT @total_reg = count(*)
  FROM sig_int_act_proy_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Act Proy Nombre
        INSERT INTO act_proy_nombre
                    (ano_eje, act_proy, tipo_act_proy, nombre, estado)
             SELECT DISTINCT
                    ano_eje, act_proy, tipo_act_proy, nombre, estado
               FROM sig_int_act_proy_nombre
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT A.ano_eje
                                  FROM Act_proy_nombre A
                                 WHERE A.ano_eje  = ano_eje  and
                                       A.act_proy = act_proy and
                                       A.tipo_act_proy = tipo_act_proy)
        
        If @@ERROR < 0
           Return -38
        
        --Agregando Act Proy
        INSERT INTO act_proy
                    (ano_eje, funcion, programa, sub_programa, act_proy, estado)
             SELECT DISTINCT
                    ano_eje, funcion, programa, sub_programa, act_proy, 'A'
               FROM sig_int_tmp_meta
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT A.ano_eje
                                  FROM act_proy A
                                 WHERE A.ano_eje      = ano_eje  and
                                       A.funcion      = funcion  and
                                       A.programa     = programa and
                                       A.sub_programa = sub_programa and
                                       A.act_proy     = act_proy)
        
        If @@ERROR < 0
           Return -39
   END
   
--Verificando Componente
SELECT @total_reg = count(*)
  FROM sig_int_componente_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Componente Nombre
        SELECT @total_reg = count(*)
          FROM sig_int_componente_nombre
         WHERE ano_eje_mov  = @ano_eje  and    
               sec_ejec_mov = @sec_ejec and    
               sec_aud_mov  = @sec_aud  and    
               NOT EXISTS (SELECT C.ano_eje    
                             FROM componente_nombre C
                            WHERE C.ano_eje    = ano_eje and
                                  C.componente = componente)
        
        If @total_reg > 0
           BEGIN
                INSERT INTO componente_nombre
                            (ano_eje, componente, tipo_componente, nombre, estado, estado_envio)
                     SELECT DISTINCT
                            ano_eje, componente, tipo_componente, nombre, estado, '1'
                       FROM sig_int_componente_nombre
                      WHERE ano_eje_mov  = @ano_eje  and
                            sec_ejec_mov = @sec_ejec and
                            sec_aud_mov  = @sec_aud  and
                            NOT EXISTS (SELECT C.ano_eje
                                          FROM componente_nombre C
                                         WHERE C.ano_eje    = ano_eje and
                                               C.componente = componente)
                
                If @@ERROR < 0
                   Return -40
           END
           
        --Agregando Componente     
        SELECT @total_reg = count(*)
          FROM sig_int_tmp_meta M , componente_nombre CN
         WHERE M.ano_eje_mov  = @ano_eje  and
               M.sec_ejec_mov = @sec_ejec and
               M.sec_aud_mov  = @sec_aud  and
               M.ano_eje = CN.ano_eje     and
               M.componente = CN.componente  and
               NOT EXISTS (SELECT C.ANO_EJE
                             FROM Componente C
                            WHERE C.ano_eje      = M.ano_eje  and
                                  C.funcion      = M.funcion  and
                                  C.programa     = M.programa and
                                  C.sub_programa = M.sub_programa and
                                  C.act_proy     = M.act_proy and
                                  C.componente   = M.componente) and
               EXISTS (SELECT A.ano_eje
                         FROM act_proy A
                        WHERE A.ano_eje      = M.ano_eje  and
                              A.funcion      = M.funcion  and
                              A.programa     = M.programa and
                              A.sub_programa = M.sub_programa and
                              A.act_proy     = M.act_proy)
        
        If @total_reg > 0
           BEGIN
                INSERT INTO componente
                            (ano_eje, funcion, programa, sub_programa, act_proy, componente, estado, estado_envio)
                     SELECT DISTINCT
                            M.ano_eje, M.funcion, M.programa, m.sub_programa, M.act_proy, M.componente, CN.estado, '1'
                       FROM sig_int_tmp_meta M,componente_nombre CN
                      WHERE M.ano_eje_mov  = @ano_eje  and
                            M.sec_ejec_mov = @sec_ejec and
                            M.sec_aud_mov  = @sec_aud  and
                            M.ano_eje = CN.ano_eje and M.componente = CN.componente  and
                            NOT EXISTS (SELECT C.ano_eje
                                          FROM Componente C
                                         WHERE C.ano_eje      = M.ano_eje  and
                                               C.funcion      = M.funcion  and
                                               C.programa     = M.programa and
                                               C.sub_programa = M.sub_programa and
                                               C.act_proy     = M.act_proy and
                                               C.componente   = M.componente) and
                            EXISTS (SELECT A.ano_eje
                                      FROM act_proy A
                                     WHERE A.ano_eje      = M.ano_eje  and
                                           A.funcion      = M.funcion  and
                                           A.programa     = M.programa and
                                           A.sub_programa = M.sub_programa and
                                           A.act_proy     = M.act_proy)
                
                If @@ERROR < 0
                   Return -41
           END
        
        --Agregando Componente Ejec
        SELECT @total_reg = count(*)
          FROM sig_int_tmp_meta M ,componente_nombre CN
         WHERE M.ano_eje_mov  = @ano_eje  and
               M.sec_ejec_mov = @sec_ejec and
               M.sec_aud_mov  = @sec_aud  and
               M.ano_eje = CN.ano_eje and M.componente = CN.componente and
               NOT EXISTS (SELECT C.ano_eje
                             FROM componente_ejec C
                            WHERE C.ano_eje      = M.ano_eje  and
                                  C.sec_ejec     = @sec_ejec  and
                                  C.funcion      = M.funcion  and
                                  C.programa     = M.programa and
                                  C.sub_programa = M.sub_programa and
                                  C.act_proy     = M.act_proy and
                                  C.componente   = M.componente) and
               EXISTS (SELECT C.ano_eje
                         FROM componente C
                        WHERE C.ano_eje      = M.ano_eje  and
                              C.funcion      = M.funcion  and
                              C.programa     = M.programa and
                              C.sub_programa = M.sub_programa and
                              C.act_proy     = M.act_proy and
                              C.componente   = M.componente)
        
        If @total_reg > 0
           BEGIN
                INSERT INTO componente_ejec
                            (ano_eje, sec_ejec, funcion, programa, sub_programa, act_proy, componente, estado, estado_envio)
                     SELECT DISTINCT
                            M.ano_eje, M.sec_ejec, M.funcion, M.programa, M.sub_programa, M.act_proy, M.componente, CN.estado, '1'
                       FROM sig_int_tmp_meta M ,componente_nombre CN
                      WHERE M.ano_eje_mov  = @ano_eje  and
                            M.sec_ejec_mov = @sec_ejec and
                            M.sec_aud_mov  = @sec_aud  and
                            M.ano_eje = CN.ano_eje and M.componente = CN.componente and
                            NOT EXISTS (SELECT C.ano_eje
                                          FROM componente_ejec C
                                         WHERE C.ano_eje      = M.ano_eje  and
                                               C.sec_ejec     = @sec_ejec  and
                                               C.funcion      = M.funcion  and
                                               C.programa     = M.programa and
                                               C.sub_programa = M.sub_programa and
                                               C.act_proy     = M.act_proy and
                                               C.componente   = M.componente) and
                            EXISTS (SELECT C.ano_eje
                                      FROM componente C
                                     WHERE C.ano_eje      = M.ano_eje  and
                                           C.funcion      = M.funcion  and
                                           C.programa     = M.programa and
                                           C.sub_programa = M.sub_programa and
                                           C.act_proy     = M.act_proy and
                                           C.componente   = M.componente)
                
                If @@ERROR < 0
                   Return -42
           END
           
        --Actualizando Componente Ejec
        UPDATE componente_ejec
           SET estado = (SELECT DISTINCT CN.estado
                           FROM sig_int_tmp_meta M ,componente_nombre CN
                          WHERE M.ano_eje_mov  = @ano_eje  and
                                M.sec_ejec_mov = @sec_ejec and
                                M.sec_aud_mov  = @sec_aud  and
                                M.ano_eje = CN.ano_eje and M.componente = CN.componente and
                                M.ano_eje      = componente_ejec.ano_eje  and
                                M.funcion      = componente_ejec.funcion  and
                                M.programa     = componente_ejec.programa and
                                M.sub_programa = componente_ejec.sub_programa and
                                M.act_proy     = componente_ejec.act_proy and
                                M.componente   = componente_ejec.componente)
         WHERE EXISTS (SELECT M.ano_eje FROM sig_int_tmp_meta M
                        WHERE M.ano_eje_mov  = @ano_eje  and
                              M.sec_ejec_mov = @sec_ejec and
                              M.sec_aud_mov  = @sec_aud  and
                              M.ano_eje      = ano_eje   and
                              M.funcion      = funcion   and
                              M.programa     = programa  and
                              M.sub_programa = sub_programa and
                              M.act_proy     = act_proy  and
                              M.componente   = componente)
        
        If @@ERROR < 0
           Return -43
   END
   
--Verificando Finalidad
SELECT @total_reg = count(*)
  FROM sig_int_finalidad_nombre
 WHERE ano_eje_mov = @ano_eje and sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud

If @total_reg > 0
   BEGIN
        --Agregando Finalidad
        INSERT INTO Finalidad
                    (ano_eje, finalidad, nombre, estado, estado_envio)
             SELECT DISTINCT
                    ano_eje, finalidad, nombre, estado, estado_envio
               FROM sig_int_finalidad_nombre
              WHERE ano_eje_mov  = @ano_eje  and
                    sec_ejec_mov = @sec_ejec and
                    sec_aud_mov  = @sec_aud  and
                    NOT EXISTS (SELECT F.ano_eje
                                  FROM Finalidad F
                                 WHERE F.ano_eje   = ano_eje and
                                       F.finalidad = finalidad)
        
        If @@ERROR < 0
           Return -44
        
   END
--
Return 1
GO


-- ----------------------------
-- procedure structure for SPU_LIMPIACADENACATALOGO
-- ----------------------------
/* procedure [SPU_LIMPIACADENACATALOGO] is encrypted */

-- ----------------------------
-- procedure structure for USP_TPPROCESO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[USP_TPPROCESO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[USP_TPPROCESO]
GO

CREATE PROCEDURE [dbo].[USP_TPPROCESO]
/*
CREATED BY : CHRISTIAN ROSALES
DATE : 20060627
*/
		@sec_ejec numeric(6,0),
		@centro_costo varchar(15)
AS
-- La insercion del Año, lo voy a obtener desde la Tabla SIG_PARAMETRO_EJECUTORA
DECLARE @ano_eje numeric(4,0)
DECLARE @fase_cuadro numeric(1,0)
DECLARE @flag_techo_cn char(1)
DECLARE @estado char(1)
DECLARE @FUENTE_FINANCTP char(2)
DECLARE @GASTOTP char(2)
DECLARE @CLASIFICADORTP varchar(6)
DECLARE @SEC_FUNCTP  numeric(5,0)
DECLARE @TOTALTP  numeric(5,0)
DECLARE @mnto_progTP numeric(14,2)
DECLARE @mnto_asigTP numeric(14,2)
DECLARE @mnto_aprobTP numeric(14,2)
DECLARE @secuencia numeric(5,0)
DECLARE @categ_gasto varchar(1)
DECLARE @grupo_gasto varchar(1)
DECLARE @funcion varchar(2)
DECLARE @programa varchar(3)

-- Obtención del Año del CN
SELECT @ano_eje = VALOR FROM SIG_PARAMETRO_EJECUTORA 
WHERE COD_MAESTRO = 'PROG_CN_ANO'

-- Obtención de la Fase para el Centro de Costo 
-- Obtención del estado y Fase del CN
SELECT @estado = ESTADO FROM SIG_CUADRO_X_CENTRO
WHERE ANO_EJE = @ano_eje AND SEC_EJEC = @sec_ejec
AND CENTRO_COSTO = @centro_costo
IF @estado= '0' SET @fase_cuadro=1
IF @estado= '1' OR @estado= '2' OR @estado= '3'  SET @fase_cuadro=2 
IF @estado= '4' OR @estado= '5' OR @estado= '6'  SET @fase_cuadro=3

-- Obtener el Estado del Control de Techo
SELECT @flag_techo_cn = VALOR FROM SIG_PARAMETRO_EJECUTORA 
WHERE COD_MAESTRO = 'FLAG_TECHO_CN'

-- PARA EL INDICADOR 0
DECLARE CUR_TP0 CURSOR FOR
SELECT DISTINCT FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO, CLASIFICADOR, SEC_FUNC
FROM SIG_TECHO_PRESUPUESTAL
WHERE INDICADOR = 5
GROUP BY FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO, CLASIFICADOR, SEC_FUNC

BEGIN TRAN

OPEN CUR_TP0
FETCH CUR_TP0 INTO @FUENTE_FINANCTP, @GASTOTP, @CLASIFICADORTP, @SEC_FUNCTP
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @mnto_progTP = SUM(ISNULL(MNTO_PROGRA,0)),
	@mnto_asigTP = SUM(ISNULL(MNTO_ASIG,0)), @mnto_aprobTP = SUM(ISNULL(MNTO_APROB,0)) 
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP AND CLASIFICADOR = @CLASIFICADORTP
	AND SEC_FUNC = @SEC_FUNCTP AND INDICADOR = 5

	SELECT @TOTALTP = COUNT(*)
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP AND CLASIFICADOR = @CLASIFICADORTP
	AND SEC_FUNC = @SEC_FUNCTP AND INDICADOR = 0

	SET @categ_gasto = SUBSTRING(@CLASIFICADORTP,1,2)
	SET @grupo_gasto = SUBSTRING(@CLASIFICADORTP,2,3)

	IF @mnto_progTP < 0 SET @mnto_progTP = 0
	IF @mnto_asigTP < 0 SET @mnto_asigTP = 0
	IF @mnto_aprobTP < 0 SET @mnto_aprobTP = 0

	if @mnto_progTP is null set @mnto_progTP = 0
	if @mnto_asigTP is null set @mnto_asigTP = 0
	if @mnto_aprobTP is null set @mnto_aprobTP = 0
	IF @TOTALTP>0
	BEGIN
		PRINT 'INGRESO UPDATE'
		UPDATE SIG_TECHO_PRESUPUESTAL SET
		MNTO_PROGRA = @mnto_progTP,
		MNTO_ASIG = @mnto_asigTP ,
		MNTO_APROB = @mnto_aprobTP
		WHERE INDICADOR = 0 AND FUENTE_FINANC = @FUENTE_FINANCTP 
		AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP 
		AND CLASIFICADOR = @CLASIFICADORTP AND SEC_FUNC = @SEC_FUNCTP
		AND CENTRO_COSTO IS NULL
	END
	ELSE
	BEGIN
		PRINT 'INGRESO INSERT'
		IF @flag_techo_cn = 0
		BEGIN
			PRINT 'FLAG DE TECHO 0'
			SELECT @secuencia = MAX(SECUENCIA)
			FROM 	SIG_TECHO_PRESUPUESTAL
			WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec
			GROUP BY ano_eje, sec_ejec

			IF @secuencia IS NULL SET @secuencia = 0
			SET @secuencia = @secuencia + 1

			SELECT @funcion = FUNCION, @programa = PROGRAMA 
			FROM SIG_META_PROP 
			WHERE SEC_FUNC = @SEC_FUNCTP AND SEC_EJEC = @sec_ejec 

			INSERT INTO SIG_TECHO_PRESUPUESTAL
			(
			ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto, clasificador, 
			funcion, programa, sec_func, porc_techo, 
			ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
			mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, 
			paac_inicial, paac_modif, porc_asig
			)
			VALUES
			(
			@ano_eje, @sec_ejec, '1', @FUENTE_FINANCTP, @secuencia, @categ_gasto, @grupo_gasto, @clasificadorTP, 

			@funcion, @programa, @sec_funcTP, 0, 
			0, 0, 0, 0, 
			@mnto_progTP, @mnto_asigTP, @mnto_aprobTP, 0, 0, 
			0, 0, 0 
			)
		END
		ELSE
		BEGIN
	   		GOTO ERROR
		END
	END
	FETCH CUR_TP0 INTO @FUENTE_FINANCTP, @GASTOTP, @CLASIFICADORTP, @SEC_FUNCTP
END
CLOSE CUR_TP0
DEALLOCATE CUR_TP0

-- PARA EL INDICADOR 3
DECLARE CUR_TP3 CURSOR FOR
SELECT DISTINCT FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO, CLASIFICADOR
FROM SIG_TECHO_PRESUPUESTAL
WHERE INDICADOR = 5
GROUP BY FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO, CLASIFICADOR

OPEN CUR_TP3
FETCH CUR_TP3 INTO @FUENTE_FINANCTP, @GASTOTP, @CLASIFICADORTP
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @mnto_progTP = SUM(ISNULL(MNTO_PROGRA,0)),
	@mnto_asigTP = SUM(ISNULL(MNTO_ASIG,0)), @mnto_aprobTP = SUM(ISNULL(MNTO_APROB,0)) 
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP AND CLASIFICADOR = @CLASIFICADORTP
	 AND INDICADOR = 5

	if @mnto_progTP is null set @mnto_progTP = 0
	if @mnto_asigTP is null set @mnto_asigTP = 0
	if @mnto_aprobTP is null set @mnto_aprobTP = 0
	SELECT @TOTALTP = COUNT(*)
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP AND CLASIFICADOR = @CLASIFICADORTP
	 AND INDICADOR = 3

	SET @categ_gasto = SUBSTRING(@CLASIFICADORTP,1,2)
	SET @grupo_gasto = SUBSTRING(@CLASIFICADORTP,2,3)

	if @mnto_progTP is null set @mnto_progTP = 0
	if @mnto_asigTP is null set @mnto_asigTP = 0
	if @mnto_aprobTP is null set @mnto_aprobTP = 0
	IF @mnto_progTP < 0 SET @mnto_progTP = 0
	IF @mnto_asigTP < 0 SET @mnto_asigTP = 0
	IF @mnto_aprobTP < 0 SET @mnto_aprobTP = 0

	IF @TOTALTP>0
	BEGIN
		UPDATE SIG_TECHO_PRESUPUESTAL SET
		MNTO_PROGRA = @mnto_progTP,
		MNTO_ASIG = @mnto_asigTP ,
		MNTO_APROB = @mnto_aprobTP
		WHERE INDICADOR = 3 AND FUENTE_FINANC = @FUENTE_FINANCTP 
		AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP 
		AND CLASIFICADOR = @CLASIFICADORTP 
		AND CENTRO_COSTO IS NULL AND SEC_FUNC IS NULL
	END
	ELSE
	BEGIN
		IF @flag_techo_cn = 0
		BEGIN
			SELECT @secuencia = MAX(SECUENCIA)
			FROM 	SIG_TECHO_PRESUPUESTAL
			WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec
			GROUP BY ano_eje, sec_ejec

			IF @secuencia IS NULL SET @secuencia = 0
			SET @secuencia = @secuencia + 1

			INSERT INTO SIG_TECHO_PRESUPUESTAL
			(
			ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto, clasificador, 
			porc_techo, 
			ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
			mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, 
			paac_inicial, paac_modif, porc_asig
			)
			VALUES
			(
			@ano_eje, @sec_ejec, '1', @FUENTE_FINANCTP, @secuencia, @categ_gasto, @grupo_gasto, @clasificadorTP, 
			0, 
			0, 0, 0, 0, 
			@mnto_progTP, @mnto_asigTP, @mnto_aprobTP, 0, 3, 
			0, 0, 0 
			)
		END
		ELSE
		BEGIN
	   		GOTO ERROR
		END
	END
	FETCH CUR_TP3 INTO @FUENTE_FINANCTP, @GASTOTP, @CLASIFICADORTP
END
CLOSE CUR_TP3
DEALLOCATE CUR_TP3

-- PARA EL INDICADOR 2
DECLARE CUR_TP2 CURSOR FOR
SELECT DISTINCT FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO
FROM SIG_TECHO_PRESUPUESTAL
WHERE INDICADOR = 5
GROUP BY FUENTE_FINANC, CATEG_GASTO + GRUPO_GASTO

OPEN CUR_TP2
FETCH CUR_TP2 INTO @FUENTE_FINANCTP, @GASTOTP
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @mnto_progTP = SUM(ISNULL(MNTO_PROGRA,0)),
	@mnto_asigTP = SUM(ISNULL(MNTO_ASIG,0)), @mnto_aprobTP = SUM(ISNULL(MNTO_APROB,0)) 
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP
	 AND INDICADOR = 5

	if @mnto_progTP is null set @mnto_progTP = 0
	if @mnto_asigTP is null set @mnto_asigTP = 0
	if @mnto_aprobTP is null set @mnto_aprobTP = 0
	SELECT @TOTALTP = COUNT(*)
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP
--	 AND CLASIFICADOR IS NULL
--	AND SEC_FUNC IS NULL AND CENTRO_COSTO IS NULL
	 AND INDICADOR = 2

	SET @categ_gasto = SUBSTRING(@CLASIFICADORTP,1,2)
	SET @grupo_gasto = SUBSTRING(@CLASIFICADORTP,2,3)

	IF @mnto_progTP < 0 SET @mnto_progTP = 0
	IF @mnto_asigTP < 0 SET @mnto_asigTP = 0
	IF @mnto_aprobTP < 0 SET @mnto_aprobTP = 0

	IF @TOTALTP>0
	BEGIN
		UPDATE SIG_TECHO_PRESUPUESTAL SET
		MNTO_PROGRA = @mnto_progTP,
		MNTO_ASIG = @mnto_asigTP ,
		MNTO_APROB = @mnto_aprobTP
		WHERE INDICADOR = 2 AND FUENTE_FINANC = @FUENTE_FINANCTP 
		AND CATEG_GASTO + GRUPO_GASTO = @GASTOTP 
		AND CENTRO_COSTO IS NULL AND SEC_FUNC IS NULL
		AND CLASIFICADOR IS NULL 
	END
	ELSE
	BEGIN
		IF @flag_techo_cn = 0
		BEGIN
			SELECT @secuencia = MAX(SECUENCIA)
			FROM 	SIG_TECHO_PRESUPUESTAL
			WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec
			GROUP BY ano_eje, sec_ejec

			IF @secuencia IS NULL SET @secuencia = 0
			SET @secuencia = @secuencia + 1

			INSERT INTO SIG_TECHO_PRESUPUESTAL
			(
			ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto,
			porc_techo, 
			ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
			mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, 
			paac_inicial, paac_modif, porc_asig
			)
			VALUES
			(
			@ano_eje, @sec_ejec, '1', @FUENTE_FINANCTP, @secuencia, @categ_gasto, @grupo_gasto, 
			0, 
			0, 0, 0, 0, 
			@mnto_progTP, @mnto_asigTP, @mnto_aprobTP, 0, 2, 
			0, 0, 0 
			)
		END
		ELSE
		BEGIN
	   		GOTO ERROR
		END
	END
	FETCH CUR_TP2 INTO @FUENTE_FINANCTP, @GASTOTP
END
CLOSE CUR_TP2
DEALLOCATE CUR_TP2


-- PARA EL INDICADOR 1
DECLARE CUR_TP1 CURSOR FOR
SELECT DISTINCT FUENTE_FINANC
FROM SIG_TECHO_PRESUPUESTAL
WHERE INDICADOR = 5
GROUP BY FUENTE_FINANC

OPEN CUR_TP1
FETCH CUR_TP1 INTO @FUENTE_FINANCTP
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @mnto_progTP = SUM(ISNULL(MNTO_PROGRA,0)),
	@mnto_asigTP = SUM(ISNULL(MNTO_ASIG,0)), @mnto_aprobTP = SUM(ISNULL(MNTO_APROB,0)) 
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
	 AND INDICADOR = 5

	SELECT @TOTALTP = COUNT(*)
	 FROM SIG_TECHO_PRESUPUESTAL
	WHERE FUENTE_FINANC = @FUENTE_FINANCTP 
--	AND CATEG_GASTO IS NULL AND GRUPO_GASTO IS NULL
--	 AND CLASIFICADOR IS NULL
--	AND SEC_FUNC IS NULL AND CENTRO_COSTO IS NULL
	 AND INDICADOR = 1

	if @mnto_progTP is null set @mnto_progTP = 0
	if @mnto_asigTP is null set @mnto_asigTP = 0
	if @mnto_aprobTP is null set @mnto_aprobTP = 0
	IF @mnto_progTP < 0 SET @mnto_progTP = 0
	IF @mnto_asigTP < 0 SET @mnto_asigTP = 0
	IF @mnto_aprobTP < 0 SET @mnto_aprobTP = 0

	IF @TOTALTP>0
	BEGIN
		UPDATE SIG_TECHO_PRESUPUESTAL SET
		MNTO_PROGRA = @mnto_progTP,
		MNTO_ASIG = @mnto_asigTP ,
		MNTO_APROB = @mnto_aprobTP
		WHERE INDICADOR = 1 AND FUENTE_FINANC = @FUENTE_FINANCTP 
--		AND CATEG_GASTO IS NULL AND GRUPO_GASTO IS NULL
--		AND CENTRO_COSTO IS NULL AND SEC_FUNC IS NULL
--		AND CLASIFICADOR IS NULL 
	END
	ELSE
	BEGIN
		IF @flag_techo_cn = 0
		BEGIN
			SELECT @secuencia = MAX(SECUENCIA)
			FROM 	SIG_TECHO_PRESUPUESTAL
			WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec
			GROUP BY ano_eje, sec_ejec

			IF @secuencia IS NULL SET @secuencia = 0
			SET @secuencia = @secuencia + 1

			INSERT INTO SIG_TECHO_PRESUPUESTAL
			(
			ano_eje, sec_ejec, origen, fuente_financ, secuencia, --categ_gasto, grupo_gasto,
			porc_techo, 
			ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, 
			mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, 
			paac_inicial, paac_modif, porc_asig
			)
			VALUES
			(
			@ano_eje, @sec_ejec, '1', @FUENTE_FINANCTP, @secuencia, --@categ_gasto, @grupo_gasto, 
			0, 
			0, 0, 0, 0, 
			@mnto_progTP, @mnto_asigTP, @mnto_aprobTP, 0, 1, 
			0, 0, 0 
			)
		END
		ELSE
		BEGIN
	   		GOTO ERROR
		END
	END
	FETCH CUR_TP1 INTO @FUENTE_FINANCTP
END
CLOSE CUR_TP1
DEALLOCATE CUR_TP1


COMMIT TRAN
set nocount off
RETURN 0

ERROR:
   ROLLBACK TRAN
   set nocount off
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_SIG_KARDEX_PEPS_SALDO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_KARDEX_PEPS_SALDO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_KARDEX_PEPS_SALDO]
GO

CREATE PROCEDURE [dbo].[SP_SIG_KARDEX_PEPS_SALDO]
@an_ano_eje numeric(4), @an_sec_ejec numeric(6), @as_almacen varchar(3), @as_sec_alma varchar(3),
@as_mes varchar(2), @as_tipo_uso varchar(1), @an_tipo_ppto numeric(2), @an_encargo numeric(6),
@as_tipo_bien varchar(1), @as_grup_bien varchar(2), @as_clas_bien varchar(2), @as_fami_bien varchar(4),
@as_item_bien varchar(4), @as_clas_gast varchar(20), @as_plan_mayo varchar(4), @as_plan_scta varchar(8),
@as_origen varchar(1)

------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

AS
DECLARE
@ls_tipo_bien varchar(1),
@ls_grup_bien varchar(2),
@ls_clas_bien varchar(2),
@ls_fami_bien varchar(4),
@ls_item_bien varchar(4),
@ls_clas_gast varchar(20),
@ls_plan_mayo varchar(4),
@ls_plan_scta varchar(8),
@ls_tipo_movi varchar(1),
@ls_tipo_uso  varchar(1),

@ld_codi_marc numeric(5),
@ld_tipo_tran numeric(2),
--@ld_nume_movi numeric(5),
@ld_nume_movi numeric(6),
@ld_secuencia numeric(2),
@ld_secu_deta numeric(5),
@ld_cant_arti numeric(18,4),
@ld_valo_tota numeric(14,2),
@ld_cant_actu numeric(18,4),
@ld_valo_actu numeric(14,2),

@ld_unid_medi numeric(3),
@ld_item_bien_det numeric(5),

@ls_kardex_clasif varchar(1),
@ld_kardex_verifi  numeric(1)

set @ld_cant_arti = 0
set @ld_valo_tota = 0
set @ld_cant_actu = 0
set @ld_valo_actu = 0

-- Si parametro existe y esta activo se trabaja sin clasificador en kardex
set @ls_kardex_clasif = 'S'

SELECT @ld_kardex_verifi = count(*)
  FROM sig_maestro_det_numerico 
 WHERE cod_maestro = 'PARAMETRO' AND
       cod_detalle = 1 AND
       @an_ano_eje >= valor_numerico AND
       estado = 'A'

set @ld_kardex_verifi = isnull(@ld_kardex_verifi, 0)

If (@ld_kardex_verifi > 0)
Begin
	set @as_clas_gast = '%'
	set @ls_kardex_clasif = 'N'
End

--
DECLARE citem CURSOR FOR
SELECT DISTINCT d.tipo_bien,    d.grupo_bien, d.clase_bien,
		d.familia_bien, d.item_bien,  d.marca,
		case @ls_kardex_clasif when 'N' then '0' else d.clasificador end as clasificador, d.mayor, d.sub_cta,
		d.tipo_uso, d.unidad_medida,  d.item_bien_det
   FROM sig_detalle_movim_almacen d,
	sig_movim_almacen m
  WHERE d.ano_eje      = m.ano_eje  and
 	d.sec_ejec     = m.sec_ejec and
	d.almacen      = m.almacen  and
	d.sec_almacen  = m.sec_almacen  and
	d.tipo_movimto = m.tipo_movimto and
	d.tipo_transac = m.tipo_transac and
	d.tipo_ppto    = m.tipo_ppto    and
	d.nro_movimto  = m.nro_movimto  and
    m.estado_kardex= 'S' and
 	d.ano_eje      = @an_ano_eje     and
	d.sec_ejec     = @an_sec_ejec    and
    d.almacen      = @as_almacen     and
	d.sec_almacen  = @as_sec_alma    and
	d.tipo_movimto in ('A','I','S') and
	d.mes_proceso  >= @as_mes        and
	m.tipo_ppto    = @an_tipo_ppto   and
	((@an_tipo_ppto = 1) or
	 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	((@as_tipo_uso =  '2' and d.tipo_uso = @as_tipo_uso) or
	 (@as_tipo_uso <> '2' and m.tipo_uso = @as_tipo_uso)) and
	d.tipo_bien    like @as_tipo_bien  and
	d.grupo_bien   like @as_grup_bien and
	d.clase_bien   like @as_clas_bien and
	d.familia_bien like @as_fami_bien  and
	d.item_bien    like @as_item_bien  and
	d.clasificador like @as_clas_gast  and
	d.mayor        like @as_plan_mayo and
	d.sub_cta      like @as_plan_scta 

OPEN citem
FETCH NEXT FROM citem INTO @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien, 
		        @ls_item_bien, @ld_codi_marc, @ls_clas_gast, @ls_plan_mayo,
			@ls_plan_scta, @ls_tipo_uso, @ld_unid_medi, @ld_item_bien_det
WHILE @@FETCH_STATUS = 0
BEGIN

	set @ld_cant_actu = 0
	set @ld_valo_actu = 0

	DECLARE cdetalle CURSOR FOR
	 SELECT d.tipo_movimto, d.tipo_transac, d.nro_movimto,
		d.secuencia,    d.sec_detalle,  d.cant_articulo,
		d.valor_total
	   FROM sig_detalle_movim_almacen d,
		sig_movim_almacen m
	  WHERE d.ano_eje      = m.ano_eje  and
	 	d.sec_ejec     = m.sec_ejec and
		d.almacen      = m.almacen  and
		d.sec_almacen  = m.sec_almacen  and
		d.tipo_movimto = m.tipo_movimto and
		d.tipo_transac = m.tipo_transac and
		d.tipo_ppto    = m.tipo_ppto    and
		d.nro_movimto  = m.nro_movimto  and
		m.estado_kardex= 'S' and
		d.ano_eje      = @an_ano_eje  and
		d.sec_ejec     = @an_sec_ejec and
--		d.mes_proceso  >= @as_mes     and
		d.almacen      = @as_almacen  and
		d.sec_almacen  = @as_sec_alma and
		d.tipo_movimto in ('A','I','S') and
		d.tipo_bien    = @ls_tipo_bien   and
		d.grupo_bien   = @ls_grup_bien   and
		d.clase_bien   = @ls_clas_bien   and
		d.familia_bien = @ls_fami_bien   and
		d.item_bien    = @ls_item_bien   and
		d.marca        = @ld_codi_marc   and
		d.tipo_uso     = @ls_tipo_uso    and
		m.tipo_ppto    = @an_tipo_ppto   and
		((@an_tipo_ppto = 1) or
		 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
		((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
		 (@ls_kardex_clasif = 'N')) and
		d.mayor        = @ls_plan_mayo and
		d.sub_cta      = @ls_plan_scta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
	order by d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
		 d.secuencia, d.sec_detalle

	OPEN cdetalle
	FETCH NEXT FROM cdetalle INTO @ls_tipo_movi, @ld_tipo_tran, @ld_nume_movi, @ld_secuencia, 
			        @ld_secu_deta, @ld_cant_arti, @ld_valo_tota
	WHILE @@FETCH_STATUS = 0
	BEGIN

		If (@ls_tipo_movi = 'A' or @ls_tipo_movi = 'I')
		begin
			set @ld_cant_actu = @ld_cant_actu + @ld_cant_arti
			set @ld_valo_actu = @ld_valo_actu + @ld_valo_tota
		end
		Else
		begin
			If (@ls_tipo_movi = 'S')
			begin
				set @ld_cant_actu = @ld_cant_actu - @ld_cant_arti
				set @ld_valo_actu = @ld_valo_actu - @ld_valo_tota
			End
		end

		 UPDATE sig_detalle_movim_almacen  
		    SET stock_actual = @ld_cant_actu,
			valor_actual = @ld_valo_actu
		  WHERE ano_eje  = @an_ano_eje  AND  
			sec_ejec = @an_sec_ejec AND  
			almacen  = @as_almacen  AND  
			sec_almacen  = @as_sec_alma  AND  
			tipo_movimto = @ls_tipo_movi AND  
			tipo_transac = @ld_tipo_tran AND  
			tipo_ppto    = @an_tipo_ppto AND  
			nro_movimto  = @ld_nume_movi AND  
			secuencia    = @ld_secuencia AND  
			sec_detalle  = @ld_secu_deta 

		FETCH NEXT FROM cdetalle INTO @ls_tipo_movi, @ld_tipo_tran, @ld_nume_movi, @ld_secuencia, 
				        @ld_secu_deta, @ld_cant_arti, @ld_valo_tota
	END
	CLOSE cdetalle
	DEALLOCATE cdetalle

	FETCH NEXT FROM citem INTO @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien, 
			        @ls_item_bien, @ld_codi_marc, @ls_clas_gast, @ls_plan_mayo,
				@ls_plan_scta, @ls_tipo_uso, @ld_unid_medi, @ld_item_bien_det

END
CLOSE citem
DEALLOCATE citem
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_PPR_SEDE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_PPR_SEDE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_PPR_SEDE]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_PPR_SEDE]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJEC   	    	VARCHAR(10),
    @fecha_carga_inicio     	VARCHAR(10),
    @fecha_carga_fin        	VARCHAR(10),
    @usuario_n              	VARCHAR(50),
    @O_ERR_NUM   	    	NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG   	    	VARCHAR(255) OUTPUT   
AS
	DECLARE @LC_ANO_EJE		  NUMERIC(5)
	DECLARE @LC_SEC_EJEC              NUMERIC(5)	
	DECLARE @LC_SEC_ESTABLEC          NUMERIC(5)
	DECLARE @LC_COD_ESTABLEC          NUMERIC(5)
	DECLARE @LC_ID_SI_PPR_SEDE        NUMERIC(5)
	DECLARE @LC_SEDE  	    	  NUMERIC(5)
	DECLARE @LC_PLIEGO    	    	  VARCHAR(3)
 	DECLARE @fecha_carga_inicio_1     DATETIME
    	DECLARE @fecha_carga_fin_1        DATETIME

BEGIN  
	DELETE FROM SI_PPR_SEDE

	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101) 
        SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

	SELECT @LC_ID_SI_PPR_SEDE = MAX(ID_SI_PPR_SEDE) 
	FROM SI_PPR_SEDE WHERE ANO_EJE = @P_ANO_EJE 
	AND SEC_EJEC = @P_SEC_EJEC

	IF @LC_ID_SI_PPR_SEDE IS NULL 
		SET @LC_ID_SI_PPR_SEDE = 0	

        DECLARE C_1 CURSOR FOR 
		SELECT ANO_EJE, SEC_EJEC, SEC_ESTABLEC, 
		COD_ESTABLEC, SEDE, PLIEGO FROM SIG_PPR_SEDE
		WHERE ANO_EJE = @P_ANO_EJE 
		AND SEC_EJEC = @P_SEC_EJEC
		
  	OPEN C_1
		FETCH NEXT FROM C_1 
		INTO @LC_ANO_EJE, @LC_SEC_EJEC, @LC_SEC_ESTABLEC, 
		     @LC_COD_ESTABLEC, @LC_SEDE, @LC_PLIEGO

		WHILE @@FETCH_STATUS = 0
		BEGIN
	        	SET @LC_ID_SI_PPR_SEDE = @LC_ID_SI_PPR_SEDE  + 1

		        INSERT INTO SI_PPR_SEDE (ANO_EJE, SEC_EJEC, SEC_ESTABLEC, 
						 COD_ESTABLEC, ID_SI_PPR_SEDE, 
						 SEDE, PLIEGO, FECHA_CARGA_INICIO, 
						 FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
		        VALUES (@LC_ANO_EJE, @LC_SEC_EJEC, @LC_SEC_ESTABLEC, 
				@LC_COD_ESTABLEC, @LC_ID_SI_PPR_SEDE, 
				@LC_SEDE, @LC_PLIEGO, @fecha_carga_inicio_1, 
				@fecha_carga_fin_1,
				convert(varchar(10),getdate(),112), @usuario_n)

        	 FETCH NEXT FROM C_1
        	 INTO 	@LC_ANO_EJE, @LC_SEC_EJEC, @LC_SEC_ESTABLEC, 
			@LC_COD_ESTABLEC, @LC_SEDE, @LC_PLIEGO
		END
        CLOSE C_1
        DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_ORDEN_EJECUCION_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_ORDEN_EJECUCION_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_ORDEN_EJECUCION_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_ORDEN_EJECUCION_TRX]
     @P_ANO_EJE			  NUMERIC(4,0),
     @P_SEC_EJEC		  NUMERIC(6,0),
     @fecha_carga_inicio  VARCHAR(10), 
     @fecha_carga_fin     VARCHAR(10),
     @usuario_n           varchar(30),
     @O_ERR_NUM			  NUMERIC(6,0) OUTPUT,
     @O_ERR_MSG			  VARCHAR(255) OUTPUT 
 AS        
 DECLARE @fecha_carga_inicio_1         DATETIME
 DECLARE @fecha_carga_fin_1            DATETIME
 
 DECLARE @LN_ID_SI_ORDEN            NUMERIC(10,0)
 DECLARE @LN_ID_SI_ORDEN_DETA       NUMERIC(10,0)
 DECLARE @LS_NOM_PROVEEDOR         VARCHAR(100)
 DECLARE @LS_PROVEEDOR_GIRO        VARCHAR(250)
 DECLARE @LN_NRO_ORDEN              NUMERIC(7,0)
 DECLARE @LC_TIPO_BIEN              CHAR(1)
 DECLARE @LC_NOMBRE_ITEM            VARCHAR(100)
 DECLARE @LC_NOMBRE_UM              VARCHAR(100)
 DECLARE @LC_ITEM_CATALOGO          VARCHAR(20)
 DECLARE @LC_FUNCION                CHAR(2)
 DECLARE @LC_PROGRAMA               CHAR(3)
 DECLARE @LC_SUB_PROGRAMA           CHAR(4)
 DECLARE @LC_ACT_PROY               CHAR(7)
 DECLARE @LC_COMPONENTE				CHAR(7)
 DECLARE @LC_META                   VARCHAR(5)
 DECLARE @LN_MONTO_META             NUMERIC(19,2)
 DECLARE @LN_CANTIDAD_META			NUMERIC(20,3)
 DECLARE @LC_UNIDAD_MEDIDA_META     NUMERIC(3,0)
 DECLARE @LC_D_UNIDAD_MEDIDA_META   VARCHAR(100)
 DECLARE @LC_DEPARTAMENTO           CHAR(2)
 DECLARE @LC_PROVINCIA              CHAR(2)
 DECLARE @LC_DISTRITO               CHAR(2)
 DECLARE @LC_FINALIDAD              CHAR(5)
 DECLARE @LC_D_FINALIDAD            VARCHAR(250)
 DECLARE @LC_PROGRAMA_INSTITUCIONAL VARCHAR(6)
 DECLARE @LN_CANT_ITEM              NUMERIC(16,6)
 DECLARE @LN_PRECIO_TOTAL           NUMERIC(16,2)
 DECLARE @LD_FECHA_INI              DATETIME
 DECLARE @LD_FECHA_FIN              DATETIME
 DECLARE @LD_FECHA_ORDEN            DATETIME
 DECLARE @LS_CONCEPTO               VARCHAR(350)
 DECLARE @LN_MNTO_SUBTOTAL          NUMERIC(16,2)
 DECLARE @LN_MNTO_DESCUENTO         NUMERIC(16,2)
 DECLARE @LN_MNTO_TOTAL             NUMERIC(16,2)
 DECLARE @LS_NRO_CONTRATO           VARCHAR(50)
 DECLARE @LD_FECHA_CONTRATO         DATETIME
 DECLARE @LS_DOCUM_REFERENCIA       VARCHAR(100)
 DECLARE @LN_EXP_SIAF               NUMERIC(10,0)
 DECLARE @LS_NRO_PROC_SEL           VARCHAR(50)
 DECLARE @LS_GLOSA                  varchar(3000)
 DECLARE @LC_ESTADO                 CHAR(1)
 DECLARE @LC_ESTADO_SIAF            CHAR(1)
 DECLARE @LN_SEC_FUNC               NUMERIC(4,0)
 DECLARE @LS_CLASIFICADOR           VARCHAR(20)
 DECLARE @LS_FUENTE_FINANC          VARCHAR(2)
 DECLARE @LC_GRUPO_BIEN             CHAR(2)
 DECLARE @LC_CLASE_BIEN             CHAR(2)
 DECLARE @LC_FAMILIA_BIEN           CHAR(4)
 DECLARE @LC_ITEM_BIEN              CHAR(4)
 DECLARE @LN_PREC_UNIT_MONEDA       NUMERIC(16,6)
 DECLARE @LN_PREC_TOT_SOLES         NUMERIC(16,2)
 DECLARE @LN_UNIDAD_MEDIDA          NUMERIC(3,0)
 DECLARE @LN_MARCA                  NUMERIC(5,0)
 DECLARE @LC_TIPO_MARCA             CHAR(1)
 DECLARE @LS_ESPECIFICACIONES       varchar(3000)
 DECLARE @LN_CANT_ARTICULO          NUMERIC(16,6)
 DECLARE @LN_MNTO_SOLES             NUMERIC(16,2)
 DECLARE @LN_TIPO_PPTO		    NUMERIC(2,0)
 DECLARE @LS_RUC_PROVEEDOR  	VARCHAR(11)

 
 BEGIN
     SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
     SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)                                                             
     
     DELETE FROM SI_ORDEN_DETA_TRX
     DELETE FROM SI_ORDEN_TRX
 
     SELECT @LN_ID_SI_ORDEN = MAX(ID_SI_ORDEN) 
       FROM SI_ORDEN_TRX
      WHERE ANO_EJE  = @P_ANO_EJE AND SEC_EJEC = @P_SEC_EJEC
	 
     IF @LN_ID_SI_ORDEN IS NULL
	 SET @LN_ID_SI_ORDEN = 0
 
     --Cursor de órdenes.  ESTADO=1: Orden Comprometida, ESTADO_SIAF=2: Orden Aprobada por SIAF
     DECLARE C_1 CURSOR FOR
        SELECT 		    
		    A.NRO_ORDEN,
		    A.TIPO_BIEN,
		    A.TIPO_PPTO,
		    A.FECHA_ORDEN,
		    A.CONCEPTO CONCEPTO_ORDEN,
		    B.NRO_RUC PROVEEDOR_NRO_RUC,
		    dbo.f_elimina_tabs(B.NOMBRE_PROV) D_PROVEEDOR,
		    B.GIRO_GENERAL PROVEEDOR_GIRO,
		    A.SUBTOTAL_MONEDA MONTO_SUBTOTAL,
		    A.TOTAL_IGV_MONEDA MONTO_DESCUENTO,
		    A.TOTAL_FACT_MONEDA MONTO_TOTAL,
		    A.NRO_CONTRATO,
		    NULL FECHA_CONTRATO,
		    A.DOCUM_REFERENCIA DOCUMENTO_REFERENCIA,
		    A.EXP_SIAF EXPEDIENTE_SIAF,
		    A.NRO_PROC_SEL NRO_PROCESO_SELECCION,
		    dbo.f_elimina_tabs(A.GLOSA) GLOSA_ORDEN,
		    A.ESTADO ESTADO_ORDEN,
		    A.ESTADO_SIAF		    
		FROM SIG_ORDEN_ADQUISICION A
		JOIN SIG_CONTRATISTAS B
		    ON B.PROVEEDOR = A.PROVEEDOR
		WHERE A.ANO_EJE  = @P_ANO_EJE AND
		      A.SEC_EJEC = @P_SEC_EJEC       
        
     OPEN C_1
     FETCH NEXT FROM C_1
     INTO @LN_NRO_ORDEN,	     @LC_TIPO_BIEN,		     @LN_TIPO_PPTO,		@LD_FECHA_ORDEN,	
     	  @LS_CONCEPTO,          @LS_RUC_PROVEEDOR,	     @LS_NOM_PROVEEDOR,	@LS_PROVEEDOR_GIRO, 
     	  @LN_MNTO_SUBTOTAL,  	 @LN_MNTO_DESCUENTO, 	 @LN_MNTO_TOTAL,	@LS_NRO_CONTRATO,   
     	  @LD_FECHA_CONTRATO,    @LS_DOCUM_REFERENCIA,   @LN_EXP_SIAF,		@LS_NRO_PROC_SEL, 
    	  @LS_GLOSA, @LC_ESTADO, @LC_ESTADO_SIAF
 
     WHILE @@FETCH_STATUS = 0
     BEGIN
		SET @LN_ID_SI_ORDEN = @LN_ID_SI_ORDEN + 1
		INSERT INTO SI_ORDEN_TRX
			(ANO_EJE, SEC_EJEC, ID_SI_ORDEN, NRO_ORDEN, TIPO_BIEN, FECHA_ORDEN, CONCEPTO_ORDEN,                      
			PROVEEDOR_NRO_RUC, D_PROVEEDOR, PROVEEDOR_GIRO,                                                        
			MONTO_SUBTOTAL, MONTO_DESCUENTO, MONTO_TOTAL,                                                           
			NRO_CONTRATO, FECHA_CONTRATO, DOCUMENTO_REFERENCIA, EXPEDIENTE_SIAF,                                    
			NRO_PROCESO_SELECCION, GLOSA_ORDEN, ESTADO_ORDEN, ESTADO_SIAF,                                          
			FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)                                               
		VALUES      
			(@P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_ORDEN, @LN_NRO_ORDEN, @LC_TIPO_BIEN, @LD_FECHA_ORDEN, @LS_CONCEPTO,        
			@LS_RUC_PROVEEDOR, @LS_NOM_PROVEEDOR,  @LS_PROVEEDOR_GIRO, 
			@LN_MNTO_SUBTOTAL, @LN_MNTO_DESCUENTO, @LN_MNTO_TOTAL,  
			@LS_NRO_CONTRATO,  @LD_FECHA_CONTRATO, @LS_DOCUM_REFERENCIA, @LN_EXP_SIAF,                               
			@LS_NRO_PROC_SEL,  @LS_GLOSA, @LC_ESTADO, @LC_ESTADO_SIAF,                                               
			@fecha_carga_inicio_1, @fecha_carga_fin_1, Getdate(), @usuario_n)                                  
                                                                                                                  
	--CURSOR DE DETALLE_ORDEN                                                                            
		DECLARE C_2 CURSOR FOR                                                                                   
		 SELECT OIP.SEC_FUNC,                                                                                 
	                OIP.CLASIFICADOR,                                                                             
	                OIP.FUENTE_FINANC,                                                                            
	                OI.GRUPO_BIEN,                                                                                
	                OI.CLASE_BIEN,                                                                                
	                OI.FAMILIA_BIEN,                                                                              
	                OI.ITEM_BIEN,                                                                                 
	                OI.CANT_ITEM,                                                                                 
	                OI.PREC_UNIT_MONEDA,                                                                          
	                OI.PREC_TOT_SOLES,                                                                            
	                OI.UNIDAD_MEDIDA,                                                                             
	                OI.MARCA,                                                                                     
	                OI.TIPO_MARCA,                                                                                
	                dbo.f_elimina_tabs(OI.ESPECIFICACIONES) ESPECIFICACIONES,                                                                          
	                OIP.CANT_ARTICULO,                                                                            
	                OIP.MNTO_SOLES,
	                OIP.TIPO_PPTO                                                                                
		 FROM SIG_ORDEN_ITEM_PPTO OIP,                                                                        
		      SIG_ORDEN_ITEM OI                                                                               
		WHERE OIP.ANO_EJE   = OI.ANO_EJE      
		  AND OIP.SEC_EJEC  = OI.SEC_EJEC                                                                    
		  AND OIP.NRO_ORDEN = OI.NRO_ORDEN                                                                   
		  AND OIP.TIPO_BIEN = OI.TIPO_BIEN                                                                   
	 	  AND OIP.SEC_ITEM  = OI.SEC_ITEM                                                                    
		  AND OI.ANO_EJE    = @P_ANO_EJE                                                                     
		  AND OI.SEC_EJEC   = @P_SEC_EJEC                                                                    
		  AND OI.NRO_ORDEN  = @LN_NRO_ORDEN                                                                  
		  AND OI.TIPO_BIEN  = @LC_TIPO_BIEN                                             
		ORDER BY OIP.SEC_ITEM     		             
                                                                                                                  
        OPEN C_2                                                                                                 
        FETCH NEXT FROM C_2 INTO 
		@LN_SEC_FUNC,     @LS_CLASIFICADOR, 	@LS_FUENTE_FINANC, 	@LC_GRUPO_BIEN, 		@LC_CLASE_BIEN, 	
		@LC_FAMILIA_BIEN, @LC_ITEM_BIEN,  		@LN_CANT_ITEM,  	@LN_PREC_UNIT_MONEDA, 	@LN_PREC_TOT_SOLES,
		@LN_UNIDAD_MEDIDA,@LN_MARCA, 			@LC_TIPO_MARCA, 	@LS_ESPECIFICACIONES, 	@LN_CANT_ARTICULO, 
		@LN_MNTO_SOLES,   @LN_TIPO_PPTO                                                  
                                                                                                                  
        WHILE @@FETCH_STATUS = 0                    
        BEGIN                                                                                                    
		SET @LC_ITEM_CATALOGO = @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN           
		set @LC_NOMBRE_ITEM = ''
		set @LC_NOMBRE_UM   = ''

              --CAMPOS DE META SEGUN AÑO, EJECUTORA Y SEC_FUNC                                                 
              SELECT @LC_FUNCION                = ME.FUNCION,                                                     
                     @LC_PROGRAMA               = ME.PROGRAMA,                         
                     @LC_SUB_PROGRAMA           = ME.SUB_PROGRAMA,                                                
                     @LC_ACT_PROY               = ME.ACT_PROY,                                                    
                     @LC_COMPONENTE             = ME.COMPONENTE,                                             
                     @LC_META                   = ME.META,                                                        
                     @LN_MONTO_META             = ME.MONTO,                                                       
                     @LN_CANTIDAD_META          = ME.CANTIDAD,                                                    
                     @LC_UNIDAD_MEDIDA_META     = ME.UNIDAD_MEDIDA,                                               
                     @LC_DEPARTAMENTO           = ME.DEPARTAMENTO,                                                
                     @LC_PROVINCIA              = ME.PROVINCIA,                                                   
                     @LC_DISTRITO               = ME.DISTRITO,                                                    
                     @LC_PROGRAMA_INSTITUCIONAL = ME.PROGRAMA_INSTITUCIONAL,                                      
                     @LC_FINALIDAD              = ME.FINALIDAD                                                    
                FROM META ME                                                                                      
               WHERE ME.ANO_EJE  = @P_ANO_EJE                                              
                 AND ME.SEC_EJEC = @P_SEC_EJEC   
                 AND ME.SEC_FUNC = @LN_SEC_FUNC                                                                  
			
					
                SELECT @LC_D_UNIDAD_MEDIDA_META = M.NOMBRE 
                  FROM UNIDAD_MEDIDA M
                 WHERE M.UNIDAD_MEDIDA = @LN_UNIDAD_MEDIDA


               SELECT @LC_D_FINALIDAD= F.NOMBRE 
                 FROM FINALIDAD F
                WHERE F.ANO_EJE = @P_ANO_EJE 
                  AND F.FINALIDAD=( SELECT FINALIDAD
                                      FROM META
                                     WHERE ANO_EJE  = @P_ANO_EJE 
                                       AND SEC_EJEC = @P_SEC_EJEC
                                       AND SEC_FUNC = @LN_SEC_FUNC )
                		
		
		
			 
		        SET @LN_CANT_ITEM  = @LN_CANT_ARTICULO                                                            
				SET @LN_PRECIO_TOTAL = @LN_MNTO_SOLES                                                            
		                                                               
		                                                                                                                  
		        --MAXIMO SECUENCIAL EN SI_ORDEN_DETA                                                             
		        SELECT @LN_ID_SI_ORDEN_DETA = MAX(SIOD.ID_SI_ORDEN_DETA)                                            
				  FROM SI_ORDEN_DETA_TRX SIOD                                                                             
			     WHERE SIOD.ANO_EJE= @P_ANO_EJE  AND SIOD.SEC_EJEC = @P_SEC_EJEC                                                                   
				   AND SIOD.ID_SI_ORDEN = @LN_ID_SI_ORDEN                                                            
		                                                                                                                  
		        IF @LN_ID_SI_ORDEN_DETA IS NULL  SET @LN_ID_SI_ORDEN_DETA = 0                                                                       
		                                                                                    
				SET @LN_ID_SI_ORDEN_DETA = @LN_ID_SI_ORDEN_DETA + 1 

	                                                               
                                                                                                                  
              INSERT INTO SI_ORDEN_DETA_TRX
              (ANO_EJE,		   SEC_EJEC,	   ID_SI_ORDEN,			 ID_SI_ORDEN_DETA,		  NRO_ORDEN,				TIPO_BIEN,                                 
               ITEM_CATALOGO,  D_ITEM_CATALOGO,GRUPO_BS,			 CLASE_BS,FAMILIA_BS,	  ITEM_BS,					CANTIDAD_ITEM_BS,
               PRECIO_UNITARIO,PRECIO_TOTAL,   UNIDAD_MEDIDA_ITEM_BS,D_UNIDAD_MEDIDA_ITEM_BS, ESPECIFICACIONES_ITEM_BS, SEC_FUNC,                          
               CLASIFICADOR,   FUENTE_FINANCIAMIENTO,FUNCION,		 PROGRAMA,				  SUB_PROGRAMA,				ACT_PROY,
               COMPONENTE,     META,		   UNIDAD_MEDIDA_META,	 D_UNIDAD_MEDIDA_META,    DEPARTAMENTO_META,		PROVINCIA_META,
               DISTRITO_META,  FINALIDAD,	   D_FINALIDAD,			 PROGRAMA_INSTITUCIONAL,  FECHA_CARGA_INICIO, 		FECHA_CARGA_FIN, 
               FECHA_ENVIO,    USUARIO_ENVIO)
              VALUES                                                                                              
              (@P_ANO_EJE, 	    @P_SEC_EJEC,     @LN_ID_SI_ORDEN, 	 @LN_ID_SI_ORDEN_DETA,    @LN_NRO_ORDEN,		     @LC_TIPO_BIEN,        
               @LC_ITEM_CATALOGO,@LC_NOMBRE_ITEM, @LC_GRUPO_BIEN, 	 @LC_CLASE_BIEN, 		  @LC_FAMILIA_BIEN, 		 @LC_ITEM_BIEN, 
               @LN_CANT_ITEM,    @LN_PREC_UNIT_MONEDA,@LN_PRECIO_TOTAL,@LN_UNIDAD_MEDIDA, 	  @LC_D_UNIDAD_MEDIDA_META,  @LS_ESPECIFICACIONES,                                            
               @LN_SEC_FUNC, 	 @LS_CLASIFICADOR,@LS_FUENTE_FINANC, @LC_FUNCION, 			  @LC_PROGRAMA, 			 @LC_SUB_PROGRAMA, 
               @LC_ACT_PROY,	 @LC_COMPONENTE,  @LC_META,  		 @LC_UNIDAD_MEDIDA_META,  @LC_D_UNIDAD_MEDIDA_META,  @LC_DEPARTAMENTO, 
               @LC_PROVINCIA, 	 @LC_DISTRITO,    @LC_FINALIDAD, 	 @LC_D_FINALIDAD,  		  @LC_PROGRAMA_INSTITUCIONAL,@fecha_carga_inicio_1, 
               @fecha_carga_fin_1,Getdate(), 	  @usuario_n )             
                            
	     -- SELECT @LS_SUBFIN=''     
                                                                                            
               FETCH NEXT FROM C_2                                                                                
               INTO 	@LN_SEC_FUNC,     @LS_CLASIFICADOR, 	@LS_FUENTE_FINANC, 	@LC_GRUPO_BIEN, 		@LC_CLASE_BIEN, 	
						@LC_FAMILIA_BIEN, @LC_ITEM_BIEN,  		@LN_CANT_ITEM,  	@LN_PREC_UNIT_MONEDA, 	@LN_PREC_TOT_SOLES,
						@LN_UNIDAD_MEDIDA,@LN_MARCA, 			@LC_TIPO_MARCA, 	@LS_ESPECIFICACIONES, 	@LN_CANT_ARTICULO, 
						@LN_MNTO_SOLES,   @LN_TIPO_PPTO                                     
	           END                                                                                                    
	           CLOSE C_2                                                                                              
	           DEALLOCATE C_2                                                                                         
	                                                                                                                  
	   FETCH NEXT FROM C_1                                                                                    
	    INTO  @LN_NRO_ORDEN,	     @LC_TIPO_BIEN,		     @LN_TIPO_PPTO,		@LD_FECHA_ORDEN,	
	     	  @LS_CONCEPTO,          @LS_RUC_PROVEEDOR,	     @LS_NOM_PROVEEDOR,	@LS_PROVEEDOR_GIRO, 
	     	  @LN_MNTO_SUBTOTAL,  	 @LN_MNTO_DESCUENTO, 	 @LN_MNTO_TOTAL,	@LS_NRO_CONTRATO,   
	     	  @LD_FECHA_CONTRATO,    @LS_DOCUM_REFERENCIA,   @LN_EXP_SIAF,		@LS_NRO_PROC_SEL, 
	    	  @LS_GLOSA, @LC_ESTADO, @LC_ESTADO_SIAF                      
       END                                                                                                        
       CLOSE C_1                                                                                                  
       DEALLOCATE C_1                                                                                             
END
GO


-- ----------------------------
-- procedure structure for SP_CARGA_ORDEN_X_CC
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_ORDEN_X_CC]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_ORDEN_X_CC]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_ORDEN_X_CC]
(@pn_ano numeric, @pn_sec_ejec numeric, @pn_tipo_ppto numeric,
 @ps_mes varchar(2), @ls_tipo_proceso varchar(2),  @ln_identificador numeric)   
  
AS  

DECLARE @ls_tipo_bien VARCHAR(1)
DECLARE @ln_nro_orden NUMERIC

DECLARE @ls_centro_costo VARCHAR(800)
DECLARE @ls_cc_cadena    VARCHAR(800)
DECLARE @ls_cc_cadena_x  VARCHAR(800)
DECLARE @ls_separador    CHAR(1)
DECLARE @ln_cantidad     NUMERIC
DECLARE @lb_Exit         bit


IF @ls_tipo_proceso = '1'
BEGIN
DECLARE cc_orden CURSOR FOR 
SELECT  
a.tipo_bien,
a.nro_orden
FROM sig_orden_adquisicion a
WHERE 
( a.sec_ejec   = @pn_sec_ejec ) and         
( a.ano_eje    = @pn_ano )      and 
( a.tipo_bien  in ('B','S'))     and        
( a.tipo_ppto  = @pn_tipo_ppto ) and         
( a.mes_calend = @ps_mes ) 
ORDER BY 1,2

 OPEN cc_orden  
 FETCH cc_orden INTO @ls_tipo_bien,@ln_nro_orden
 
 WHILE @@FETCH_STATUS = 0  
 BEGIN  
         SELECT @lb_Exit = 0
         
 		 DECLARE  ccn_item CURSOR FOR  
		  SELECT DISTINCT 
		         coalesce(SIG_CENTRO_COSTO.ABREVIADO_DEPEND,'.')   
 		    FROM SIG_ORDEN_ADQUISICION,   
		         SIG_DETALLE_BSERV_CUADRO,   
		         SIG_DETALLE_METAS_CUADRO,   
		         SIG_DEPEN_META_CUADRO,   
		         SIG_CENTRO_COSTO   
		   WHERE ( SIG_ORDEN_ADQUISICION.ANO_CUADRO = SIG_DETALLE_BSERV_CUADRO.ANO_EJE ) and  
		         ( SIG_ORDEN_ADQUISICION.SEC_EJEC = SIG_DETALLE_BSERV_CUADRO.SEC_EJEC ) and  
		         ( SIG_ORDEN_ADQUISICION.TIPO_BIEN = SIG_DETALLE_BSERV_CUADRO.TIPO_BIEN ) and  
		         ( SIG_ORDEN_ADQUISICION.SEC_CUADRO = SIG_DETALLE_BSERV_CUADRO.SEC_CUADRO ) and  
		         ( SIG_DETALLE_BSERV_CUADRO.ANO_EJE = SIG_DETALLE_METAS_CUADRO.ANO_EJE ) and  
		         ( SIG_DETALLE_BSERV_CUADRO.SEC_EJEC = SIG_DETALLE_METAS_CUADRO.SEC_EJEC ) and  
		         ( SIG_DETALLE_BSERV_CUADRO.TIPO_BIEN = SIG_DETALLE_METAS_CUADRO.TIPO_BIEN ) and  
		         ( SIG_DETALLE_BSERV_CUADRO.SEC_CUADRO = SIG_DETALLE_METAS_CUADRO.SEC_CUADRO ) and  
		         ( SIG_DETALLE_BSERV_CUADRO.SECUENCIA = SIG_DETALLE_METAS_CUADRO.SECUENCIA ) and 
		         ( SIG_DEPEN_META_CUADRO.ANO_EJE = SIG_DETALLE_METAS_CUADRO.ANO_EJE ) and  
		         ( SIG_DEPEN_META_CUADRO.SEC_EJEC = SIG_DETALLE_METAS_CUADRO.SEC_EJEC ) and  
		         ( SIG_DEPEN_META_CUADRO.TIPO_BIEN = SIG_DETALLE_METAS_CUADRO.TIPO_BIEN ) and  
		         ( SIG_DEPEN_META_CUADRO.SEC_CUADRO = SIG_DETALLE_METAS_CUADRO.SEC_CUADRO ) and  
		         ( SIG_DEPEN_META_CUADRO.SECUENCIA = SIG_DETALLE_METAS_CUADRO.SECUENCIA ) and  
		         ( SIG_DEPEN_META_CUADRO.SEC_META = SIG_DETALLE_METAS_CUADRO.SEC_META ) and  
		         ( SIG_DEPEN_META_CUADRO.ANO_EJE = SIG_CENTRO_COSTO.ANO_EJE ) and  
		         ( SIG_DEPEN_META_CUADRO.SEC_EJEC = SIG_CENTRO_COSTO.SEC_EJEC ) and  
		         ( SIG_DEPEN_META_CUADRO.CENTRO_COSTO = SIG_CENTRO_COSTO.CENTRO_COSTO ) and 
		         ( ( SIG_ORDEN_ADQUISICION.SEC_EJEC = @pn_sec_ejec ) AND  
		         ( SIG_ORDEN_ADQUISICION.ANO_EJE    = @pn_ano ) AND  
		         ( SIG_ORDEN_ADQUISICION.TIPO_BIEN  = @ls_tipo_bien ) AND  
		         ( SIG_ORDEN_ADQUISICION.NRO_ORDEN  = @ln_nro_orden ) AND  
		         ( SIG_ORDEN_ADQUISICION.TIPO_PPTO  = @pn_tipo_ppto ) )  

         OPEN ccn_item  
	     FETCH ccn_item INTO @ls_centro_costo    
	     
	     SELECT @ls_cc_cadena = ' '
	     SELECT @ls_cc_cadena_x = ''
	     
 
		 WHILE @@FETCH_STATUS = 0 AND @lb_Exit = 0
		 BEGIN  
   	       SELECT @ls_cc_cadena = @ls_cc_cadena + @ls_centro_costo + ' , '
		   FETCH ccn_item INTO @ls_centro_costo   
		   
		   SELECT @ln_cantidad = LEN(@ls_cc_cadena) + LEN(@ls_centro_costo) 
   	       IF @ln_cantidad > 256 
   	          BEGIN
   	            SELECT @lb_Exit = 1
   	          END
		   
		   IF @@ERROR <> 0  
		      BEGIN  
				  CLOSE ccn_item  
				  DEALLOCATE ccn_item  
				  GOTO ERROR  
			  END   
		 END 
	 
         IF len(@ls_cc_cadena) > 2  
	      BEGIN
            SELECT @ls_cc_cadena_x = substring(@ls_cc_cadena,1,len(@ls_cc_cadena) - 2)    
          END 
        
		 INSERT INTO TMP_ORDEN_X_CC  
		        (ano_eje,sec_ejec,TIPO_BIEN,TIPO_PPTO,NRO_ORDEN,NOMBRE_CC_ORD,NRO_MES,IDENTIFICADOR ) 
		 VALUES (@pn_ano,@pn_sec_ejec,@ls_tipo_bien,@pn_tipo_ppto,@ln_nro_orden,@ls_cc_cadena_x,@ps_mes,@Ln_identificador)       
		
			IF @@ERROR <> 0  
			     BEGIN  
				  CLOSE ccn_item  
				  DEALLOCATE ccn_item  
				  GOTO ERROR  
			     END            
	 
		 CLOSE ccn_item  
		 DEALLOCATE ccn_item  
		 
  FETCH cc_orden INTO @ls_tipo_bien,@ln_nro_orden
  
 END  
 
 CLOSE cc_orden 
 DEALLOCATE cc_orden

END

IF @ls_tipo_proceso = '2' 
BEGIN
 DELETE FROM TMP_ORDEN_X_CC 
  WHERE ANO_EJE  = @pn_ano AND 
        SEC_EJEC  = @pn_sec_ejec AND 
        TIPO_PPTO = @pn_tipo_ppto AND
        NRO_MES  = @ps_mes AND 
        IDENTIFICADOR = @ln_identificador
	IF @@ERROR <> 0  
			     BEGIN  
				  CLOSE ccn_item  
				  DEALLOCATE ccn_item  
				  GOTO ERROR  
			     END           
END


RETURN 0  
   
ERROR:  
   RETURN 1
GO


-- ----------------------------
-- procedure structure for spu_registra_kit_log
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[spu_registra_kit_log]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[spu_registra_kit_log]
GO

CREATE PROCEDURE [dbo].[spu_registra_kit_log]
( @ls_grupo_bien varchar(2),@ls_clase_bien varchar(2),@ls_familia_bien varchar(4),@ls_item varchar(4),@ls_msje varchar(255),@ls_tipo_bien varchar(1),
  @ll_version numeric(18,0),@ll_sec_kit numeric(18,0)
 )
 as
 begin
 INSERT INTO SIG_PPR_LOG_CARGA_KIT
		(TIPO_BIEN,		GRUPO_BIEN,			CLASE_BIEN,		FAMILIA_BIEN,
		 ITEM_BIEN,		FECHA_CARGA,		OBSERVACION	, version, SEC_KIT)
	VALUES(
		 @ls_tipo_bien ,@ls_grupo_bien,@ls_clase_bien ,	@ls_familia_bien,
		 @ls_item ,	    getdate(),	@ls_msje ,@ll_version	, @ll_sec_kit)	
end
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_PROGRAMACION
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_PROGRAMACION]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_PROGRAMACION]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_PROGRAMACION]
     @P_ANO_EJE             NUMERIC(4,0),
     @P_SEC_EJEC            NUMERIC(6,0),
     @FECHA_CARGA_INICIO    VARCHAR(10), 
     @FECHA_CARGA_FIN       VARCHAR(10),
     @USUARIO_N             VARCHAR(30),
     @O_ERR_NUM             NUMERIC(6,0) OUTPUT,
     @O_ERR_MSG             VARCHAR(255) OUTPUT 
 AS
    DECLARE @FECHA_CARGA_INICIO_1       DATETIME
    DECLARE @FECHA_CARGA_FIN_1          DATETIME
    DECLARE @LN_ID_SI_PROGRAMACION      NUMERIC(10,0)
    DECLARE @LN_ID_SI_PROGRAMACION_DETA NUMERIC(10,0)
    DECLARE @LC_ESTRATEGIA_NACIONAL     VARCHAR(4)
    DECLARE @LC_FUNCION                 VARCHAR(2)
    DECLARE @LC_PROGRAMA                VARCHAR(3)
    DECLARE @LC_SUB_PROGRAMA            VARCHAR(4)
    DECLARE @LC_ACT_PROY                VARCHAR(7)
    DECLARE @LC_COMPONENTE              VARCHAR(7)
    DECLARE @LC_FINALIDAD               VARCHAR(5)
    DECLARE @LC_D_FINALIDAD             VARCHAR(250)
    DECLARE @LN_SEC_FUNC                NUMERIC(4,0)
    DECLARE @LC_META                    VARCHAR(5)
    DECLARE @LC_D_META                  VARCHAR(150)
    DECLARE @LC_UNIDAD_MEDIDA_META      NUMERIC(3,0)
    DECLARE @LC_D_UNIDAD_MEDIDA_META    VARCHAR(100)
    DECLARE @LC_SUB_FINALIDAD           VARCHAR(7)
    DECLARE @LC_D_SUB_FINALIDAD         VARCHAR(200)
    DECLARE @LN_SEDE                    NUMERIC(3,0)
    DECLARE @LC_PLIEGO                  VARCHAR(3)
    DECLARE @LC_D_SEDE                  VARCHAR(50)
    DECLARE @LN_SEC_ESTABLEC            NUMERIC(6,0)
    DECLARE @LN_COD_ESTABLEC            NUMERIC(6,0)
    DECLARE @LC_D_COD_ESTABLEC          VARCHAR(200)
    DECLARE @LN_COD_CATEGORIA           NUMERIC(3,0)
    DECLARE @LC_D_COD_CATEGORIA         VARCHAR(50)
    DECLARE @LC_D_CORTO_COD_CATEGORIA   VARCHAR(20)
    DECLARE @LN_NRO_FASE                NUMERIC(1,0)
    DECLARE @LC_ITEM_CATALOGO           VARCHAR(20)
    DECLARE @LC_D_ITEM_CATALOGO         VARCHAR(100)
    DECLARE @LC_D_CENTRO_COSTO          VARCHAR(100)
    DECLARE @LN_COUNT_CC                NUMERIC(1,0)
    DECLARE @LN_MONTO                   NUMERIC(19,2)
    DECLARE @LN_CANTIDAD                NUMERIC(20,3)
    DECLARE @LC_TIPO_BIEN               VARCHAR(1)
    DECLARE @LC_GRUPO_BIEN              VARCHAR(2)
    DECLARE @LC_CLASE_BIEN              VARCHAR(2)
    DECLARE @LC_FAMILIA_BIEN            VARCHAR(4)
    DECLARE @LC_ITEM_BIEN               VARCHAR(4)
    DECLARE @LC_CENTRO_COSTO            VARCHAR(15)
    DECLARE @LN_PRECIO_UNIT             NUMERIC(19,2)
    DECLARE @LC_UNIDAD_MEDIDA_ITEM_BS   NUMERIC(3,0)
    DECLARE @LC_D_UNIDAD_MEDIDA_ITEM_BS VARCHAR(100)
    DECLARE @LC_CLASIFICADOR            VARCHAR(100)
    DECLARE @LN_ORIGEN                  NUMERIC(1,0)
    DECLARE @LC_FUENTE_FINANC           VARCHAR(2)
    DECLARE @LN_MONTO_C2                NUMERIC(19,2)
    DECLARE @LN_CANTIDAD_C2             NUMERIC(20,3)
    DECLARE @LN_SECUENCIA               NUMERIC(10,0)
    DECLARE @LN_ITEM_SEC                NUMERIC(6,0)

-- INICIO OMRV 27.01.10
    DECLARE @COD_ESTABLEC_SIS    VARCHAR (20)
    DECLARE @UBIGEO                VARCHAR (20)
-- FIN OMRV 27.01.10
BEGIN
    DELETE FROM SI_PROGRAMACION_ID_KIT
    DELETE FROM SI_PROGRAMACION_DETA
    DELETE FROM SI_PROGRAMACION

    SET @FECHA_CARGA_INICIO_1 = CONVERT(DATETIME, @FECHA_CARGA_INICIO, 101)
    SET @FECHA_CARGA_FIN_1    = CONVERT(DATETIME, @FECHA_CARGA_FIN, 101)

    SET @LN_ID_SI_PROGRAMACION = 0

    DECLARE C_1 CURSOR FOR
        SELECT FIN.NRO_FASE, MP.PROGRAMA_INSTITUCIONAL, MP.FUNCION, 
               MP.PROGRAMA, MP.SUB_PROGRAMA, MP.ACT_PROY, MP.COMPONENTE, MP.META, MP.NOMBRE, MP.UNIDAD_MEDIDA,
               (SELECT UM.NOMBRE FROM UNIDAD_MEDIDA UM WHERE UM.UNIDAD_MEDIDA = MP.UNIDAD_MEDIDA) D_UM_META,
               FIN.SEC_FUNC, MP.FINALIDAD, 
               (SELECT FI.nombre from FINALIDAD FI WHERE FI.ANO_EJE = MP.ANO_EJE AND FI.FINALIDAD = MP.FINALIDAD AND FI.ESTADO = 'A') D_FINALIDAD,
               FIN.SUB_FINALIDAD,
               (SELECT SU.NOMBRE FROM SIG_SUB_FINALIDAD SU WHERE SU.SUB_FINALIDAD = FIN.SUB_FINALIDAD AND SU.ANO_EJE = FIN.ANO_EJE) D_SUB_FIN,
       SCC.SEDE,
               SCC.PLIEGO,
               DSD.NOMBRE_SEDE,
               CSD.COD_ESTABLEC,
               EESS.DESC_ESTABLEC,
               EESS.CATEGORIA,
               (SELECT CA.NOMBRE FROM SIG_PPR_CATEGORIA CA WHERE CA.ANO_EJE = FIN.ANO_EJE AND CA.CATEGORIA = EESS.CATEGORIA) D_CATEG,
               (SELECT CA_.NOMBRE_CORTO FROM SIG_PPR_CATEGORIA CA_ WHERE CA_.ANO_EJE = FIN.ANO_EJE AND CA_.CATEGORIA = EESS.CATEGORIA) D_CATEG_,
               FIN.MONTO,
               FIN.CANTIDAD,
               EESS.COD_INTERNO,
               EESS.UBIGEO
           FROM  SIG_PPR_METFIS_X_SUBFIN FIN 
            JOIN SIG_PPR_META_PROPUESTA MP ON
                  ( MP.ANO_EJE        = FIN.ANO_EJE AND
                    MP.SEC_EJEC      = FIN.SEC_EJEC AND
                    MP.SEC_FUNC_PROP = FIN.SEC_FUNC AND
                    MP.NRO_FASE      = FIN.NRO_FASE AND
                    MP.FLAG_ESTRATEGIA = 'S') 
            JOIN SIG_PPR_SEDE CSD ON
                 ( MP.ANO_EJE      = CSD.ANO_EJE  AND
                   MP.SEC_EJEC     = CSD.SEC_EJEC AND
                   CSD.SEC_ESTABLEC = FIN.SEC_ESTABLEC) 
            JOIN SIG_METAS_PROP_X_CENTRO MXC ON
                 ( MXC.ANO_EJE       = CSD.ANO_EJE  AND
                   MXC.SEC_EJEC      = CSD.SEC_EJEC AND
                   MXC.SEC_FUNC_PROP = MP.SEC_FUNC_PROP )
            JOIN SIG_CENTRO_COSTO  SCC ON
                 ( SCC.ANO_EJE      = MXC.ANO_EJE      AND
                   SCC.SEC_EJEC     = MXC.SEC_EJEC     AND
                   SCC.CENTRO_COSTO = MXC.CENTRO_COSTO AND
                   SCC.PLIEGO       = CSD.PLIEGO       AND
                   SCC.SEDE         = CSD.SEDE         AND
                   SCC.ESTADO       = 'A')
            JOIN SIG_SEDES DSD ON
                 ( DSD.SEDE   = CSD.SEDE AND
                   DSD.PLIEGO = CSD.PLIEGO ) ,
                 SIG_PPR_ESTABLECIMIENTO EESS,
                 SIG_CENTRO_COSTO_TAREA CCT,   
                 SIG_META_X_TAREA       MXT 
           WHERE FIN.SEC_EJEC      = @P_SEC_EJEC
             AND FIN.ANO_EJE       = @P_ANO_EJE
             AND FIN.NRO_FASE      < 3
             AND EESS.ANO_EJE      = CSD.ANO_EJE
             AND EESS.SEC_EJEC     = CSD.SEC_EJEC
             AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
             AND CCT.SEC_EJEC      = MXT.SEC_EJEC  
             AND CCT.ANO_EJE       = MXT.ANO_EJE  
             AND CCT.TIPO_TAREA    = MXT.TIPO_TAREA  
             AND CCT.NIVEL_TAREA   = MXT.NIVEL_TAREA  
             AND CCT.CODIGO_TAREA  = MXT.CODIGO_TAREA  
             AND CCT.ANO_EJE       = SCC.ANO_EJE  
             AND CCT.SEC_EJEC      = SCC.SEC_EJEC  
             AND CCT.CENTRO_COSTO  = SCC.CENTRO_COSTO  
             AND MXT.SEC_FUNC      = MP.SEC_FUNC_PROP  
             AND MXT.NRO_FASE      = MP.NRO_FASE
             AND MXT.SUB_FINALIDAD = FIN.SUB_FINALIDAD
             AND FIN.CANTIDAD      > 0 
            
        UNION
        SELECT FIN.NRO_FASE, MP.PROGRAMA_INSTITUCIONAL, MP.FUNCION, 
               MP.PROGRAMA, MP.SUB_PROGRAMA, MP.ACT_PROY, MP.COMPONENTE, MP.META, MP.NOMBRE, MP.UNIDAD_MEDIDA,
               (SELECT UM.NOMBRE FROM UNIDAD_MEDIDA UM WHERE UM.UNIDAD_MEDIDA = MP.UNIDAD_MEDIDA) D_UM_META,
               FIN.SEC_FUNC, MP.FINALIDAD, 
               (SELECT FI.nombre from FINALIDAD FI WHERE FI.ANO_EJE = MP.ANO_EJE AND FI.FINALIDAD = MP.FINALIDAD AND FI.ESTADO = 'A') D_FINALIDAD,
               FIN.SUB_FINALIDAD,
               (SELECT SU.NOMBRE FROM SIG_SUB_FINALIDAD SU WHERE SU.SUB_FINALIDAD = FIN.SUB_FINALIDAD AND SU.ANO_EJE = FIN.ANO_EJE) D_SUB_FIN,
               SCC.SEDE,
               SCC.PLIEGO,
               DSD.NOMBRE_SEDE,
               CSD.COD_ESTABLEC,
               EESS.DESC_ESTABLEC,
               EESS.CATEGORIA,
               (SELECT CA.NOMBRE FROM SIG_PPR_CATEGORIA CA WHERE CA.ANO_EJE = FIN.ANO_EJE AND CA.CATEGORIA = EESS.CATEGORIA) D_CATEG,
               (SELECT CA_.NOMBRE_CORTO FROM SIG_PPR_CATEGORIA CA_ WHERE CA_.ANO_EJE = FIN.ANO_EJE AND CA_.CATEGORIA = EESS.CATEGORIA) D_CATEG_,
               FIN.MONTO,
               FIN.CANTIDAD,
               EESS.COD_INTERNO,
               EESS.UBIGEO
           FROM  SIG_PPR_METFIS_X_SUBFIN FIN 
            JOIN SIG_PPR_META_PROPUESTA MP ON
                  ( MP.ANO_EJE       = FIN.ANO_EJE  AND
                    MP.SEC_EJEC      = FIN.SEC_EJEC AND
                    MP.SEC_FUNC_PROP = FIN.SEC_FUNC AND
                    MP.NRO_FASE      = FIN.NRO_FASE AND
                    MP.FLAG_ESTRATEGIA = 'S') 
            JOIN SIG_PPR_SEDE CSD ON
                 ( MP.ANO_EJE      = CSD.ANO_EJE  AND
                   MP.SEC_EJEC     = CSD.SEC_EJEC AND
                 CSD.SEC_ESTABLEC = FIN.SEC_ESTABLEC) 
            JOIN SIG_METAS_X_CENTRO MXC ON
                 ( MXC.ANO_EJE  = CSD.ANO_EJE AND
                 MXC.SEC_EJEC = CSD.SEC_EJEC AND
                   MXC.SEC_FUNC = MP.SEC_FUNC )
            JOIN SIG_CENTRO_COSTO  SCC ON
                 ( SCC.ANO_EJE      = MXC.ANO_EJE      AND
                   SCC.SEC_EJEC     = MXC.SEC_EJEC     AND
                   SCC.CENTRO_COSTO = MXC.CENTRO_COSTO AND
                   SCC.PLIEGO       = CSD.PLIEGO       AND
                   SCC.SEDE         = CSD.SEDE         AND
                   SCC.ESTADO       = 'A')
            JOIN SIG_SEDES DSD ON
                 ( DSD.SEDE   = CSD.SEDE AND
                   DSD.PLIEGO = CSD.PLIEGO ) ,
                 SIG_PPR_ESTABLECIMIENTO EESS,
                 SIG_CENTRO_COSTO_TAREA CCT,   
                 SIG_META_X_TAREA       MXT 
           WHERE FIN.SEC_EJEC      = @P_SEC_EJEC
             AND FIN.ANO_EJE       = @P_ANO_EJE
             AND FIN.NRO_FASE      = 3
             AND EESS.ANO_EJE      = CSD.ANO_EJE
             AND EESS.SEC_EJEC     = CSD.SEC_EJEC
             AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
             AND CCT.SEC_EJEC      = MXT.SEC_EJEC
             AND CCT.ANO_EJE       = MXT.ANO_EJE
             AND CCT.TIPO_TAREA    = MXT.TIPO_TAREA
             AND CCT.NIVEL_TAREA   = MXT.NIVEL_TAREA
             AND CCT.CODIGO_TAREA  = MXT.CODIGO_TAREA
             AND CCT.ANO_EJE       = SCC.ANO_EJE
             AND CCT.SEC_EJEC      = SCC.SEC_EJEC
             AND CCT.CENTRO_COSTO  = SCC.CENTRO_COSTO
             AND MXT.SEC_FUNC      = MP.SEC_FUNC
             AND MXT.NRO_FASE      = MP.NRO_FASE
             AND MXT.SUB_FINALIDAD = FIN.SUB_FINALIDAD
             AND FIN.CANTIDAD      > 0
             
    OPEN C_1
    FETCH NEXT FROM C_1
    INTO  @LN_NRO_FASE             , @LC_ESTRATEGIA_NACIONAL , @LC_FUNCION         , @LC_PROGRAMA              , @LC_SUB_PROGRAMA       , 
          @LC_ACT_PROY             , @LC_COMPONENTE          , @LC_META            , @LC_D_META                , @LC_UNIDAD_MEDIDA_META , 
          @LC_D_UNIDAD_MEDIDA_META , @LN_SEC_FUNC            , @LC_FINALIDAD       , @LC_D_FINALIDAD           , @LC_SUB_FINALIDAD      , 
          @LC_D_SUB_FINALIDAD      , @LN_SEDE                , @LC_PLIEGO          , @LC_D_SEDE                , @LN_COD_ESTABLEC       , 
          @LC_D_COD_ESTABLEC       , @LN_COD_CATEGORIA       , @LC_D_COD_CATEGORIA , @LC_D_CORTO_COD_CATEGORIA , @LN_MONTO              , 
          @LN_CANTIDAD               , @COD_ESTABLEC_SIS         , @UBIGEO    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF @LC_D_SEDE IS NULL SET @LC_D_SEDE = 'SIN SEDE'
        IF @LC_D_COD_ESTABLEC IS NULL SET @LC_D_COD_ESTABLEC = 'SIN ESTABLECIMIENTO'
        IF @LN_COD_CATEGORIA IS NULL SET @LN_COD_CATEGORIA = 99
        IF @LC_D_COD_CATEGORIA IS NULL SET @LC_D_COD_CATEGORIA = 'SIN CATEGORIA'
        IF @LC_D_CORTO_COD_CATEGORIA IS NULL SET @LC_D_CORTO_COD_CATEGORIA = 'SIN CATEG'

        SET @LN_ID_SI_PROGRAMACION = @LN_ID_SI_PROGRAMACION + 1

        INSERT INTO SI_PROGRAMACION
        ( ANO_EJE               , SEC_EJEC       , ID_SI_PROGRAMACION , NRO_FASE             , ESTRATEGIA_NACIONAL ,
          FUNCION               , PROGRAMA       , SUB_PROGRAMA       , ACT_PROY             , COMPONENTE          ,
          META                  , D_META         , UNIDAD_MEDIDA_META , D_UNIDAD_MEDIDA_META , SEC_FUNC            ,
          FINALIDAD             , D_FINALIDAD    , SUB_FINALIDAD      , D_SUB_FINALIDAD      , SEDE                ,
          D_SEDE                , COD_ESTABLEC   , D_COD_ESTABLEC     , COD_CATEGORIA        , D_COD_CATEGORIA     ,
          D_CORTO_COD_CATEGORIA , MONTO          , CANTIDAD           , FECHA_CARGA_INICIO   , FECHA_CARGA_FIN     , 
          FECHA_ENVIO           , USUARIO_ENVIO  , COD_ESTABLEC_SIS      , UBIGEO    )
        VALUES
        ( @P_ANO_EJE                , @P_SEC_EJEC      , @LN_ID_SI_PROGRAMACION , @LN_NRO_FASE             , @LC_ESTRATEGIA_NACIONAL ,
          @LC_FUNCION               , @LC_PROGRAMA     , @LC_SUB_PROGRAMA       , @LC_ACT_PROY             , @LC_COMPONENTE          ,
          @LC_META                  , @LC_D_META       , @LC_UNIDAD_MEDIDA_META , @LC_D_UNIDAD_MEDIDA_META , @LN_SEC_FUNC            ,
          @LC_FINALIDAD             , @LC_D_FINALIDAD  , @LC_SUB_FINALIDAD      , @LC_D_SUB_FINALIDAD      , @LN_SEDE                , 
          @LC_D_SEDE                , @LN_COD_ESTABLEC , @LC_D_COD_ESTABLEC     , @LN_COD_CATEGORIA        , @LC_D_COD_CATEGORIA     ,
          @LC_D_CORTO_COD_CATEGORIA , @LN_MONTO        , @LN_CANTIDAD           , @FECHA_CARGA_INICIO_1    , @FECHA_CARGA_FIN_1      , 
          GETDATE()                 , @USUARIO_N       , @COD_ESTABLEC_SIS         , @UBIGEO    )

        DECLARE C_2 CURSOR FOR
            SELECT   CAB.CENTRO_COSTO , CCN.NOMBRE_DEPEND , DET.TIPO_BIEN     , CAT.CODIGO_ITEM,
                     CAT.NOMBRE_ITEM  , DET.PRECIO_UNIT   , CAT.UNIDAD_MEDIDA , UNI.NOMBRE     ,
                     CAB.CLASIFICADOR , CAB.ORIGEN        , CAB.FUENTE_FINANC , DET.CANT_TOTAL ,   
                     DET.MNTO_TOTAL   , DET.SECUENCIA     , DET.ITEM_SEC
                FROM SIG_CUADRO_NECESIDAD       CAB,   
                     SIG_CUADRO_NECESIDAD_DET   DET,   
                     SIG_META_PROPUESTA         MPF,
                     CATALOGO_BIEN_SERV         CAT,
                     UNIDAD_MEDIDA              UNI,
                     SIG_CENTRO_COSTO           CCN,
                     SIG_META_X_TAREA           MXT,
                     SIG_CENTRO_COSTO_TAREA     CCT
            WHERE DET.ANO_EJE        = CAB.ANO_EJE
              AND DET.SEC_EJEC       = CAB.SEC_EJEC
              AND DET.CENTRO_COSTO   = CAB.CENTRO_COSTO
              AND DET.SECUENCIA      = CAB.SECUENCIA
              AND DET.FASE_CUADRO    = CAB.FASE_CUADRO
              AND CCT.ANO_EJE        = CAB.ANO_EJE
              AND CCT.SEC_EJEC       = CAB.SEC_EJEC
              AND CCT.CENTRO_COSTO   = CAB.CENTRO_COSTO
              AND CCT.ANO_EJE        = CCN.ANO_EJE
              AND CCT.SEC_EJEC       = CCN.SEC_EJEC
              AND CCT.CENTRO_COSTO   = CCN.CENTRO_COSTO
              AND CCT.ANO_EJE        = MXT.ANO_EJE
              AND CCT.SEC_EJEC       = MXT.SEC_EJEC
              AND CCT.TIPO_TAREA     = MXT.TIPO_TAREA
              AND CCT.NIVEL_TAREA    = MXT.NIVEL_TAREA
              AND CCT.CODIGO_TAREA   = MXT.CODIGO_TAREA
              AND CAB.ANO_EJE        = MXT.ANO_EJE
              AND CAB.SEC_EJEC       = MXT.SEC_EJEC
              AND CAB.SEC_FUNC_PROP  = MXT.SEC_FUNC
              AND CAB.CODIGO_TAREA   = MXT.CODIGO_TAREA
              AND CAB.TIPO_TAREA     = MXT.TIPO_TAREA
              AND CAB.NIVEL_TAREA    = MXT.NIVEL_TAREA
              AND MXT.NRO_FASE      = CAB.FASE_CUADRO
              AND MXT.SUB_FINALIDAD = @LC_SUB_FINALIDAD
              AND CAB.SEC_FUNC_PROP = @LN_SEC_FUNC
              AND CCN.SEDE          = @LN_SEDE 
              AND CCN.PLIEGO        = @LC_PLIEGO
              AND UNI.UNIDAD_MEDIDA = DET.UNIDAD_MEDIDA 
              AND CCN.ANO_EJE       = CAB.ANO_EJE 
              AND CCN.SEC_EJEC      = CAB.SEC_EJEC 
              AND CCN.CENTRO_COSTO  = CAB.CENTRO_COSTO 
              AND CCN.ESTADO        = 'A' 
              AND MPF.ANO_EJE       = CAB.ANO_EJE
              AND MPF.SEC_EJEC      = CAB.SEC_EJEC
              AND MPF.SEC_FUNC_PROP = CAB.SEC_FUNC_PROP
              AND DET.SEC_EJEC      = CAT.SEC_EJEC
              AND DET.TIPO_BIEN     = CAT.TIPO_BIEN
              AND DET.GRUPO_BIEN    = CAT.GRUPO_BIEN
              AND DET.CLASE_BIEN    = CAT.CLASE_BIEN
              AND DET.FAMILIA_BIEN  = CAT.FAMILIA_BIEN
              AND DET.ITEM_BIEN     = CAT.ITEM_BIEN
              AND CAB.ANO_EJE       = @P_ANO_EJE
              AND CAB.SEC_EJEC      = @P_SEC_EJEC
              AND CAB.FASE_CUADRO   = @LN_NRO_FASE
              AND @LN_NRO_FASE      < 3
              AND DET.ESTADO_ITEM_KIT = 'A'
            UNION
              SELECT CAB.CENTRO_COSTO , CCN.NOMBRE_DEPEND , DET.TIPO_BIEN     , CAT.CODIGO_ITEM,
                     CAT.NOMBRE_ITEM  , DET.PRECIO_UNIT   , CAT.UNIDAD_MEDIDA , UNI.NOMBRE     ,
                     CAB.CLASIFICADOR , CAB.ORIGEN        , CAB.FUENTE_FINANC , DET.CANT_TOTAL ,   
                     DET.MNTO_TOTAL   , DET.SECUENCIA     , DET.ITEM_SEC
                FROM SIG_CUADRO_NECESIDAD       CAB,   
                     SIG_CUADRO_NECESIDAD_DET   DET,   
                     META                       MPF,
                     CATALOGO_BIEN_SERV         CAT,
                     UNIDAD_MEDIDA              UNI,
                     SIG_CENTRO_COSTO           CCN,
                     SIG_META_X_TAREA           MXT,
                     SIG_CENTRO_COSTO_TAREA     CCT
               WHERE DET.ANO_EJE        = CAB.ANO_EJE  
                 AND DET.SEC_EJEC       = CAB.SEC_EJEC  
                 AND DET.CENTRO_COSTO   = CAB.CENTRO_COSTO  
                 AND DET.SECUENCIA      = CAB.SECUENCIA  
                 AND DET.FASE_CUADRO    = CAB.FASE_CUADRO
                 AND CCT.ANO_EJE        = CAB.ANO_EJE
                 AND CCT.SEC_EJEC       = CAB.SEC_EJEC
                 AND CCT.CENTRO_COSTO   = CAB.CENTRO_COSTO
                 AND CCT.ANO_EJE        = CCN.ANO_EJE
                 AND CCT.SEC_EJEC       = CCN.SEC_EJEC
                 AND CCT.CENTRO_COSTO   = CCN.CENTRO_COSTO
                 AND CCT.ANO_EJE        = MXT.ANO_EJE
                 AND CCT.SEC_EJEC       = MXT.SEC_EJEC
                 AND CCT.TIPO_TAREA     = MXT.TIPO_TAREA
                 AND CCT.NIVEL_TAREA    = MXT.NIVEL_TAREA
                 AND CCT.CODIGO_TAREA   = MXT.CODIGO_TAREA
                 AND CAB.ANO_EJE        = MXT.ANO_EJE
                 AND CAB.SEC_EJEC       = MXT.SEC_EJEC
                 AND CAB.SEC_FUNC       = MXT.SEC_FUNC
                 AND CAB.CODIGO_TAREA   = MXT.CODIGO_TAREA
                 AND CAB.TIPO_TAREA     = MXT.TIPO_TAREA
                 AND CAB.NIVEL_TAREA    = MXT.NIVEL_TAREA
                 AND MXT.NRO_FASE       = CAB.FASE_CUADRO
                 AND MXT.SUB_FINALIDAD  = @LC_SUB_FINALIDAD
                 AND CAB.SEC_FUNC       = @LN_SEC_FUNC
                 AND CCN.SEDE           = @LN_SEDE 
                 AND CCN.PLIEGO         = @LC_PLIEGO
                 AND UNI.UNIDAD_MEDIDA = DET.UNIDAD_MEDIDA
                 AND CCN.ANO_EJE       = CAB.ANO_EJE 
                 AND CCN.SEC_EJEC      = CAB.SEC_EJEC 
                 AND CCN.CENTRO_COSTO  = CAB.CENTRO_COSTO
                 AND CCN.ESTADO        = 'A'
                 AND MPF.ANO_EJE       = CAB.ANO_EJE   
                 AND MPF.SEC_EJEC      = CAB.SEC_EJEC   
                 AND MPF.SEC_FUNC      = CAB.SEC_FUNC
                 AND DET.SEC_EJEC      = CAT.SEC_EJEC   
                 AND DET.TIPO_BIEN     = CAT.TIPO_BIEN   
                 AND DET.GRUPO_BIEN    = CAT.GRUPO_BIEN   
                 AND DET.CLASE_BIEN    = CAT.CLASE_BIEN   
                 AND DET.FAMILIA_BIEN  = CAT.FAMILIA_BIEN  
                 AND DET.ITEM_BIEN     = CAT.ITEM_BIEN
                 AND CAB.ANO_EJE       = @P_ANO_EJE
                 AND CAB.SEC_EJEC      = @P_SEC_EJEC
                 AND CAB.FASE_CUADRO   = @LN_NRO_FASE
                 AND @LN_NRO_FASE      = 3 
                 AND DET.ESTADO_ITEM_KIT = 'A'
        OPEN C_2 FETCH NEXT FROM C_2 
        INTO @LC_CENTRO_COSTO  , @LC_D_CENTRO_COSTO        , @LC_TIPO_BIEN               , @LC_ITEM_CATALOGO , @LC_D_ITEM_CATALOGO ,
             @LN_PRECIO_UNIT   , @LC_UNIDAD_MEDIDA_ITEM_BS , @LC_D_UNIDAD_MEDIDA_ITEM_BS , @LC_CLASIFICADOR  , @LN_ORIGEN          ,
             @LC_FUENTE_FINANC , @LN_CANTIDAD_C2           , @LN_MONTO_C2                , @LN_SECUENCIA     , @LN_ITEM_SEC
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @LN_ID_SI_PROGRAMACION_DETA = MAX(PD.ID_SI_PROGRAMACION_DETA)
            FROM SI_PROGRAMACION_DETA PD
            WHERE PD.ANO_EJE  = @P_ANO_EJE
              AND PD.SEC_EJEC = @P_SEC_EJEC
              AND PD.ID_SI_PROGRAMACION = @LN_ID_SI_PROGRAMACION

            IF @LN_ID_SI_PROGRAMACION_DETA IS NULL SET @LN_ID_SI_PROGRAMACION_DETA = 0
            IF @LC_D_CENTRO_COSTO IS NULL SET @LC_D_CENTRO_COSTO = 'SIN DESCRIPCION'
            IF @LC_D_ITEM_CATALOGO IS NULL SET @LC_D_ITEM_CATALOGO = 'SIN DESCRI ITEM'

            SET @LN_ID_SI_PROGRAMACION_DETA = @LN_ID_SI_PROGRAMACION_DETA + 1

            INSERT INTO SI_PROGRAMACION_DETA
            ( ANO_EJE                , SEC_EJEC                , ID_SI_PROGRAMACION      , ID_SI_PROGRAMACION_DETA , CENTRO_COSTO    , 
              D_CENTRO_COSTO         , TIPO_BIEN               , ITEM_CATALOGO           , D_ITEM_CATALOGO         , PRECIO_REF      , 
              UNIDAD_MEDIDA_ITEM_BS  , D_UNIDAD_MEDIDA_ITEM_BS , CANT_COMPRA             , PREC_COMPRA             , CLASIFICADOR    , 
              ORIGEN_FUENTE          , FUENTE_FINANC           , FECHA_CARGA_INICIO      , FECHA_CARGA_FIN         , FECHA_ENVIO     , 
              USUARIO_ENVIO          , SECUENCIA               , ITEM_SEC)
            VALUES(
              @P_ANO_EJE                , @P_SEC_EJEC                 , @LN_ID_SI_PROGRAMACION      , @LN_ID_SI_PROGRAMACION_DETA , @LC_CENTRO_COSTO , 
              @LC_D_CENTRO_COSTO        , @LC_TIPO_BIEN               , @LC_ITEM_CATALOGO           , @LC_D_ITEM_CATALOGO         , @LN_PRECIO_UNIT  , 
              @LC_UNIDAD_MEDIDA_ITEM_BS , @LC_D_UNIDAD_MEDIDA_ITEM_BS , @LN_CANTIDAD_C2             , @LN_MONTO_C2                , @LC_CLASIFICADOR , 
              @LN_ORIGEN                , @LC_FUENTE_FINANC           , @FECHA_CARGA_INICIO_1       , @FECHA_CARGA_FIN_1          , GETDATE()        , 
              @USUARIO_N                , @LN_SECUENCIA               , @LN_ITEM_SEC)

            INSERT INTO SI_PROGRAMACION_ID_KIT
                 ( ANO_EJE               , SEC_EJEC           , ID_SI_PROGRAMACION     , ID_SI_PROGRAMACION_DETA     , ID_ITEM_ID ,        
                   ITEM_SEC              , ID_KIT             , TIPO_CALCULO           , CANTIDAD_UNITARIA           , CANT_TOTAL ,
                   FECHA_CARGA_INICIO    , FECHA_CARGA_FIN    , FECHA_ENVIO            , USUARIO_ENVIO)
               SELECT @P_ANO_EJE            , @P_SEC_EJEC        , @LN_ID_SI_PROGRAMACION , @LN_ID_SI_PROGRAMACION_DETA , ITEM_ID    ,
                   @LN_ITEM_SEC          , ID_KIT             , TIPO_CALCULO           , CANTIDAD_UNITARIA           , CANT_TOTAL ,
                   @FECHA_CARGA_INICIO_1 , @FECHA_CARGA_FIN_1 , GETDATE()              , @USUARIO_N
            FROM SIG_CUA_NEC_DET_ID
            WHERE ANO_EJE      = @P_ANO_EJE 
              AND SEC_EJEC     = @P_SEC_EJEC  
              AND CENTRO_COSTO = @LC_CENTRO_COSTO
              AND SECUENCIA    = @LN_SECUENCIA 
              AND FASE_CUADRO  = @LN_NRO_FASE
              AND ITEM_SEC     = @LN_ITEM_SEC
              AND ESTADO       = 'A' 

            FETCH NEXT FROM C_2 
            INTO @LC_CENTRO_COSTO  , @LC_D_CENTRO_COSTO        , @LC_TIPO_BIEN               , @LC_ITEM_CATALOGO , @LC_D_ITEM_CATALOGO ,
                 @LN_PRECIO_UNIT   , @LC_UNIDAD_MEDIDA_ITEM_BS , @LC_D_UNIDAD_MEDIDA_ITEM_BS , @LC_CLASIFICADOR  , @LN_ORIGEN          ,
                 @LC_FUENTE_FINANC , @LN_CANTIDAD_C2           , @LN_MONTO_C2                , @LN_SECUENCIA     , @LN_ITEM_SEC
       END 
       CLOSE C_2
       DEALLOCATE C_2

       FETCH NEXT FROM C_1
       INTO  @LN_NRO_FASE             , @LC_ESTRATEGIA_NACIONAL , @LC_FUNCION         , @LC_PROGRAMA              , @LC_SUB_PROGRAMA       , 
             @LC_ACT_PROY             , @LC_COMPONENTE          , @LC_META            , @LC_D_META                , @LC_UNIDAD_MEDIDA_META , 
             @LC_D_UNIDAD_MEDIDA_META , @LN_SEC_FUNC            , @LC_FINALIDAD       , @LC_D_FINALIDAD           , @LC_SUB_FINALIDAD      , 
             @LC_D_SUB_FINALIDAD      , @LN_SEDE                , @LC_PLIEGO          , @LC_D_SEDE                , @LN_COD_ESTABLEC       , 
             @LC_D_COD_ESTABLEC       , @LN_COD_CATEGORIA       , @LC_D_COD_CATEGORIA , @LC_D_CORTO_COD_CATEGORIA , @LN_MONTO              , 
             @LN_CANTIDAD              , @COD_ESTABLEC_SIS         , @UBIGEO    
    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


-- ----------------------------
-- function structure for SF_CN_FASE_ESTADO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_CN_FASE_ESTADO]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_CN_FASE_ESTADO]
GO

CREATE FUNCTION [dbo].[SF_CN_FASE_ESTADO]
(
 @vgi_sec_eje NUMERIC(10), 
 @vgi_ano_cn  NUMERIC(10),
 @tipo NUMERIC(10)
)
returns VARCHAR
AS
begin

DECLARE  @li_Fase_Cuadro INTEGER
DECLARE  @li_Estado_CN_1 INTEGER
DECLARE  @ls_estado VARCHAR

SET @li_Fase_Cuadro = 0 
SET @ls_estado = '*'

/* estado '0' requerido de centro de costo, corresponde fase 1*/
select @li_Estado_CN_1 = count(*) 
  from sig_cuadro_x_centro
 where ANO_EJE  = @vgi_ano_cn and
 		 SEC_EJEC = @vgi_sec_eje and
		 estado   = '0' and	
       exists (select 1 from sig_centro_costo a
				    where ANO_EJE  = @vgi_ano_cn and 
							 SEC_EJEC = @vgi_sec_eje and
							 a.centro_costo = sig_cuadro_x_centro.centro_costo and 
							 a.estado = 'A')

if @li_Estado_CN_1 > 0
BEGIN
	SET @li_Fase_Cuadro = 1
	SET @ls_estado = 'A'
end

/* estado '7' cierre de requerido de centro de costo, fase 1*/
select @li_Estado_CN_1 = count(*) 
  from sig_cuadro_x_centro
 where ANO_EJE  = @vgi_ano_cn and
 	 	 SEC_EJEC = @vgi_sec_eje and
		 estado = '7' and 
		 exists (select 1 from sig_centro_costo a
					 where ANO_EJE  = @vgi_ano_cn and 
					 		 SEC_EJEC = @vgi_sec_eje and  
							 a.centro_costo = sig_cuadro_x_centro.centro_costo and 
							 a.estado = 'A')

if @li_Estado_CN_1 > 0
BEGIN
	SET @li_Fase_Cuadro = 1
	SET @ls_estado = 'C'
end


if	@li_Fase_Cuadro = 0
BEGIN
	/* estado '1' programado anteproyecto de centro de costo, fase 2*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
			 SEC_EJEC = @vgi_sec_eje and
		  	 estado = '1' and 
				exists (select 1 
							 from sig_centro_costo a
			   			where ANO_EJE  = @vgi_ano_cn and 
									SEC_EJEC = @vgi_sec_eje and 
									a.centro_costo = sig_cuadro_x_centro.centro_costo and 
									a.estado = 'A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 2
		SET @ls_estado = 'A'
	end
		
	/* estado '2' cierre de programado anteproyecto de centro de costo, fase 2*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
			 SEC_EJEC = @vgi_sec_eje and
			 estado = '2' and 
			 exists (select 1 from sig_centro_costo a
			 			 where ANO_EJE  = @vgi_ano_cn	and 
						  		 SEC_EJEC = @vgi_sec_eje and 
								 a.centro_costo = sig_cuadro_x_centro.centro_costo and 
								 a.estado = 'A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 2
		SET @ls_estado = 'C'
	end
end



if	@li_Fase_Cuadro = 0
BEGIN
	/* estado '3' programado proyecto de centro de costo, fase 3*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
	 		 SEC_EJEC = @vgi_sec_eje and
			 estado = '3' and 
			 exists (select 1 
			 			  from sig_centro_costo a
			   		 where ANO_EJE  = @vgi_ano_cn	and 
						 		 SEC_EJEC = @vgi_sec_eje and 
								 a.centro_costo = sig_cuadro_x_centro.centro_costo and 
								 a.estado = 'A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 3
		SET @ls_estado = 'A'
	end
	
	
	/* estado '8' cierre de programado proyecto de centro de costo, fase 3*/
	select @li_Estado_CN_1 = count(*) 
	from sig_cuadro_x_centro
	where 
	ANO_EJE  = @vgi_ano_cn and
	SEC_EJEC = @vgi_sec_eje and
	estado = '8' and 
	exists (select 1 
			    from sig_centro_costo a
			   where ANO_EJE  = @vgi_ano_cn and 
				 		SEC_EJEC = @vgi_sec_eje and 
						a.centro_costo = sig_cuadro_x_centro.centro_costo and 
						a.estado = 'A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 3
		SET @ls_estado = 'C'
	end
end



if	@li_Fase_Cuadro = 0
BEGIN
	/* estado '9' programado mensualizado de centro de costo, fase 4*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
	 		 SEC_EJEC = @vgi_sec_eje and
			 estado = '9' and 
			 exists (select 1 
			 			  from sig_centro_costo a
			   		 where ANO_EJE  = @vgi_ano_cn and 
						 		 SEC_EJEC = @vgi_sec_eje and 
								 a.centro_costo = sig_cuadro_x_centro.centro_costo and
								 a.estado = 'A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 4
		SET @ls_estado = 'A'
	end
	
	
	/* estado 'A' cierre de programado mensualizado de centro de costo, fase 4*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
	 		 SEC_EJEC = @vgi_sec_eje and
			 estado = 'A' and 
			 exists (select 1 
			 			  from sig_centro_costo a
			   		 where ANO_EJE  = @vgi_ano_cn	and 
						 		 SEC_EJEC = @vgi_sec_eje and 
								  a.centro_costo = sig_cuadro_x_centro.centro_costo and 
								  a.estado='A')
	
	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 4
		SET @ls_estado = 'C'
	end
end



if	@li_Fase_Cuadro = 0 
BEGIN
	/* estado '4' aprobado de centro de costo, fase 3*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
			 SEC_EJEC = @vgi_sec_eje and
			 estado = '4' and 
			 exists (select 1 
			 			  from sig_centro_costo a
			   		 where ANO_EJE  = @vgi_ano_cn and 
						 		 SEC_EJEC = @vgi_sec_eje and
								  a.centro_costo = sig_cuadro_x_centro.centro_costo and 
								  a.estado = 'A')

	if @li_Estado_CN_1 > 0
    BEGIN
		SET @li_Fase_Cuadro = 5
		SET @ls_estado = 'A'
	end

	/* estado '5', '6' de cierre de aprobado y pao respectivamente, fase 3*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
	 where ANO_EJE  = @vgi_ano_cn and
			 SEC_EJEC = @vgi_sec_eje and
			 estado in ('5','6') and 
			 exists (select 1 
			 			  from sig_centro_costo a
			   		 where ANO_EJE  = @vgi_ano_cn	and 
						 		 SEC_EJEC = @vgi_sec_eje and 
								  a.centro_costo = sig_cuadro_x_centro.centro_costo and 
								  a.estado = 'A')
	
	if @li_Estado_CN_1 > 0 
    BEGIN
		SET @li_Fase_Cuadro = 5
		SET @ls_estado = 'C'
	end
	
	/* Obs. 203 PpR	 Fecha 25052010    Resp. JCMA*/
	select @li_Estado_CN_1 = count(*) 
	  from sig_cuadro_x_centro
 	 where ANO_EJE  = @vgi_ano_cn and
			 SEC_EJEC = @vgi_sec_eje and 
			 exists (select 1 
			 			 from sig_centro_costo a
			   		where ANO_EJE  = @vgi_ano_cn and 
								SEC_EJEC = @vgi_sec_eje and 
								a.centro_costo = sig_cuadro_x_centro.centro_costo and
								a.estado = 'A')
end

IF @TIPO = 1
BEGIN
    return CAST(@li_Fase_Cuadro AS varchar)
END

IF @TIPO = 2
BEGIN
    return @ls_estado
END

RETURN '*'
   
end
GO


-- ----------------------------
-- procedure structure for SP_ACTUALIZA_TECHO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_ACTUALIZA_TECHO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_ACTUALIZA_TECHO]
GO

CREATE PROCEDURE [dbo].[SP_ACTUALIZA_TECHO]
(@ps_anio numeric(5,0), @pn_ejecutora numeric(5,0), @ps_estado char(1), @ps_extorno char(1))
as

--------------------------------------------
/*
declare @ps_anio numeric(5,0), @pn_ejecutora numeric(5,0), @ps_estado char(1)

select @ps_anio = 2005, @pn_ejecutora = 151, @ps_estado = '2'
*/
-------------------------------

declare @li_fase_cuadro_ins numeric(5,0), @li_fase_cuadro_ins_new numeric(5,0), @ls_estado char(1)
declare @ls_equipo_reg varchar(20), @ls_cuser_id varchar(8), @ldt_fecha_reg datetime

select @ls_equipo_reg = '', 
       @ls_cuser_id = 'siga', 
       @ldt_fecha_reg = getdate()


select @li_fase_cuadro_ins = case @ps_estado when '3' then 2 when '6' then 3 when '7' then 3 end
select @li_fase_cuadro_ins_new  = @li_fase_cuadro_ins + 1
select @ls_estado = case @ps_estado when '3' then '4' when '6' then '7' end

IF @ps_extorno = 'N'
BEGIN
   delete SIG_DETALLE_CUADRO_ANUAL  
   WHERE ano_eje  = @ps_anio and 
         sec_ejec = @pn_ejecutora and
         fase_cuadro = @li_fase_cuadro_ins_new

   INSERT INTO SIG_DETALLE_CUADRO_ANUAL 
   (ano_eje, sec_ejec, centro_costo, tipo_tarea, nivel_tarea, codigo_tarea, secuencia, fase_cuadro, item_sec,
    tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, clasificador, unidad_medida, precio_unit,
    cant_01, cant_02, cant_03, cant_04, cant_05, cant_06, cant_07, cant_08, cant_09, cant_10, cant_11, cant_12, cant_total, 
    mnto_01, mnto_02, mnto_03, mnto_04, mnto_05, mnto_06, mnto_07, mnto_08, mnto_09, mnto_10, mnto_11, mnto_12, mnto_total, 
    tipo_impto, tasa_impto, fte_impto, valor_impto, estado, cant_hist, mnto_hist, equipo_reg, cuser_id, fecha_reg, 
    categ_gasto, grupo_gasto, porc_gasto, flag_gasto, flag_modif)
   select @ps_anio, @pn_ejecutora, centro_costo, tipo_tarea, nivel_tarea, codigo_tarea, secuencia, @li_fase_cuadro_ins_new, item_sec,
    tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, clasificador, unidad_medida, precio_unit,
    cant_01, cant_02, cant_03, cant_04, cant_05, cant_06, cant_07, cant_08, cant_09, cant_10, cant_11, cant_12, cant_total, 
    mnto_01, mnto_02, mnto_03, mnto_04, mnto_05, mnto_06, mnto_07, mnto_08, mnto_09, mnto_10, mnto_11, mnto_12, mnto_total, 
    tipo_impto, tasa_impto, fte_impto, valor_impto, @ps_estado, cant_hist, mnto_hist, @ls_equipo_reg, @ls_cuser_id, @ldt_fecha_reg, 
    categ_gasto, grupo_gasto, porc_gasto, flag_gasto, '0' 
   from SIG_DETALLE_CUADRO_ANUAL  
   WHERE ano_eje  = @ps_anio and 
         sec_ejec = @pn_ejecutora and
         fase_cuadro = @li_fase_cuadro_ins
END

------ Actualiza cabecera cuadro necesidades ----------------

update sig_cuadro_anual set monto_asignado=0 , valor_imp_asignado=0, 
                            monto_aprob=0, valor_imp_aprob=0, monto_modif=0 , valor_imp_modif=0   
where ano_eje = @ps_anio and
      sec_ejec= @pn_ejecutora


SELECT a.tipo_tarea, a.nivel_tarea, a.codigo_tarea, a.secuencia , a.fase_cuadro,
      sum(a.mnto_total) mnto_total, sum(a.valor_impto) valor_impto, a.centro_costo
into #consolidado
FROM  sig_detalle_cuadro_anual a 
WHERE a.ano_eje = @ps_anio and a.sec_ejec = @pn_ejecutora
GROUP BY a.tipo_tarea, a.nivel_tarea, a.codigo_tarea, a.secuencia, a.fase_cuadro,
         a.centro_costo;

SELECT sum(b.mnto_total) mnto_total, sum(b.valor_impto) valor_impto
INTO #consolidado1
FROM sig_detalle_cuadro_anual a,   
     sig_detalle_cuadro_anual b,
     #consolidado t
WHERE a.ano_eje   = @ps_anio and  
      a.sec_ejec   = @pn_ejecutora and  
      a.fase_cuadro  = 2 and  
      b.fase_cuadro  = 1 and  
      a.centro_costo = t.centro_costo and  
      a.tipo_tarea   = t.tipo_tarea and  
      a.nivel_tarea  = t.nivel_tarea and
      a.codigo_tarea = t.codigo_tarea and  
      a.secuencia    = t.secuencia and
      b.ano_eje    = a.ano_eje and  
      b.sec_ejec   = a.sec_ejec and  
      b.centro_costo = a.centro_costo and  
      b.tipo_tarea   = a.tipo_tarea and  
      b.nivel_tarea  = a.nivel_tarea and
      b.codigo_tarea = a.codigo_tarea and  
      b.secuencia  = a.secuencia and  
      b.item_sec   = a.item_sec 


update sig_cuadro_anual 
set monto_progra = case a.fase_cuadro when 1 then a.mnto_total when 2 then t.mnto_total else monto_progra end, 
    valor_imp_progra = case a.fase_cuadro when 1 then a.valor_impto else valor_imp_progra end,
    monto_asignado = case a.fase_cuadro when 2 then a.mnto_total else monto_asignado end, 
    valor_imp_asignado = case a.fase_cuadro when 2 then a.valor_impto else valor_imp_asignado end,
    monto_aprob = case a.fase_cuadro when 3 then a.mnto_total else monto_aprob end, 
    valor_imp_aprob = case a.fase_cuadro when 3 then a.valor_impto else valor_imp_aprob end,
    monto_modif = case a.fase_cuadro when 4 then a.mnto_total else monto_modif end, 
    valor_imp_modif = case a.fase_cuadro when 4 then a.valor_impto else valor_imp_modif end
from sig_cuadro_anual c, #consolidado a, #consolidado1 t
where c.ano_eje   = @ps_anio  and  
      c.sec_ejec     = @pn_ejecutora and
      c.centro_costo  = a.centro_costo and 
      c.tipo_tarea    = a.tipo_tarea and
      c.nivel_tarea   = a.nivel_tarea and
      c.codigo_tarea  = a.codigo_tarea and
      c.secuencia     = a.secuencia


--- Actualiza techo presupuestal ------------------

SELECT a.fase_cuadro, a.centro_costo, b.sec_func, b.origen, b.fuente_financ, a.clasificador,
       sum(a.mnto_total) mnto_total, sum(a.valor_impto) valor_impto
into #tmp_techo
FROM  sig_detalle_cuadro_anual a , sig_cuadro_anual b  
WHERE ( a.ano_eje = @ps_anio and a.sec_ejec = @pn_ejecutora) and
        a.ano_eje  = b.ano_eje and 
        a.sec_ejec  = b.sec_ejec and
        a.centro_costo= b.centro_costo and
        a.tipo_tarea  = b.tipo_tarea and
        a.nivel_tarea = b.nivel_tarea and
        a.codigo_tarea= b.codigo_tarea and
        a.secuencia   = b.secuencia and
        a.tipo_impto = '0'
GROUP BY a.fase_cuadro,a.centro_costo, b.sec_func, b.origen, b.fuente_financ,a.clasificador
union all
SELECT a.fase_cuadro, a.centro_costo, b.sec_func, b.origen, a.fte_impto, a.clasificador,
       sum(a.mnto_total) mnto_total, sum(a.valor_impto) valor_impto
FROM  sig_detalle_cuadro_anual a , sig_cuadro_anual b  
WHERE ( a.ano_eje = @ps_anio and a.sec_ejec = @pn_ejecutora) and
        a.ano_eje  = b.ano_eje and 
        a.sec_ejec  = b.sec_ejec and
        a.centro_costo= b.centro_costo and
        a.tipo_tarea  = b.tipo_tarea and
        a.nivel_tarea = b.nivel_tarea and
        a.codigo_tarea= b.codigo_tarea and
        a.secuencia   = b.secuencia and
        a.tipo_impto <> '0'
GROUP BY a.fase_cuadro,a.centro_costo, b.sec_func, b.origen, a.fte_impto, a.clasificador

select fase_cuadro, centro_costo, sec_func, origen, fuente_financ, clasificador, 
       sum(mnto_total) mnto_total, sum(valor_impto) valor_impto
into #tmp_techo_t
from #tmp_techo
group  by fase_cuadro, centro_costo, sec_func, origen, fuente_financ, clasificador

update sig_techo_presupuestal
set  mnto_progra=0,  mnto_asig =0, mnto_aprob=0 , mnto_modif=0
from  sig_techo_presupuestal t, #tmp_techo_t a 
where ano_eje     = @ps_anio and
      t.sec_ejec    = @pn_ejecutora and
      t.centro_costo = a.centro_costo and
      t.sec_func = a.sec_func and
      t.origen = a.origen and
      t.fuente_financ = a.fuente_financ and
      t.clasificador = a.clasificador and
      t.indicador='5'

update sig_techo_presupuestal
   set mnto_progra = case a.fase_cuadro when 1 then mnto_total + valor_impto else mnto_progra end,
       mnto_asig = case a.fase_cuadro when 2 then mnto_total + valor_impto else mnto_asig end,
       mnto_aprob = case a.fase_cuadro when 3 then mnto_total + valor_impto else mnto_aprob end,
       mnto_modif = case a.fase_cuadro when 4 then mnto_total + valor_impto else mnto_modif end
from sig_techo_presupuestal t, #tmp_techo_t a
where t.ano_eje     = @ps_anio and
      t.sec_ejec    = @pn_ejecutora and
      t.centro_costo = a.centro_costo and 
      t.sec_func     = a.sec_func and
      t.origen      = a.origen and
      t.fuente_financ = a.fuente_financ and
      t.clasificador = a.clasificador and
      t.indicador='5'
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_TECHOC_FASE_3
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_TECHOC_FASE_3]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_TECHOC_FASE_3]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_TECHOC_FASE_3]
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)
AS

BEGIN
	DECLARE @lI_FASE_CUADRO NUMERIC(1,0)
	DECLARE @ls_clasificador VARCHAR(20)
	DECLARE @ls_flag_presup VARCHAR(1)
	DECLARE @ls_centro_costo_presup VARCHAR(15)
	DECLARE @ls_centro_costo_cambio VARCHAR(15)
	DECLARE @ls_centro_costo VARCHAR(15)
	DECLARE @ls_centro_padre VARCHAR(15)
	DECLARE @ls_origen VARCHAR(1)
	DECLARE @ls_codi_fuen VARCHAR(2)
	DECLARE @ls_codi_fuen_impto VARCHAR(2)
	DECLARE @ls_clas_gast VARCHAR(20)
	DECLARE @ls_funcion VARCHAR(2)
	DECLARE @ls_programa VARCHAR(3)
	DECLARE @ld_Secu_func NUMERIC(4,0)
	DECLARE @li_contador NUMERIC(10,0)
	DECLARE @ld_valor_imp_progra NUMERIC(14,2)
	DECLARE @li_secuencia NUMERIC(10,0)
	DECLARE @ld_valor_progra NUMERIC(14,2)
	DECLARE @ld_valor_aprob NUMERIC(14,2)
	DECLARE @ld_mnto_impto NUMERIC(14,2)
	DECLARE @ld_monto_progra NUMERIC(14,2)
	DECLARE @ld_mnto_total NUMERIC(14,2)
	DECLARE @ld_mnto_apro NUMERIC(14,2)
	DECLARE @ld_mnto_asig NUMERIC(14,2)
	DECLARE @ld_mnto_modif NUMERIC(14,2)
	DECLARE @ls_categ_gasto VARCHAR(1)
	DECLARE @ls_grupo_gasto VARCHAR(1)
	DECLARE @ls_grupo VARCHAR(2)
	DECLARE @ls_grupo1 VARCHAR(2)
	DECLARE @ls_flag_gen_esp VARCHAR(1)
	DECLARE @ld_valor_imp_asignado NUMERIC(14,2)
	DECLARE @ld_valor_asignado NUMERIC(14,2)
	DECLARE @ld_monto_asignado NUMERIC(14,2)
	DECLARE @ld_monto_aprob NUMERIC(14,2)
	DECLARE @ld_valor_imp_aprob NUMERIC(14,2)
	declare @ld_min_correl numeric(8,0)

SELECT @li_contador = COUNT(1)
FROM  SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND 
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

IF ( @li_contador IS NULL) OR ( @li_contador <= 0)
   return -1

SELECT @ls_flag_gen_esp = VALOR
FROM  SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND 
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

SELECT @li_secuencia = MAX( secuencia ) 
  FROM sig_techo_presupuesto 
 WHERE ano_eje= @PN_ANIO AND sec_ejec = @PN_EJEC


if @li_secuencia  IS NULL 
  SELECT @li_secuencia = 0

SET NOCOUNT ON


CREATE TABLE #TMP_SIG_CN_TECHO_APROB_UPD
	(
	correlativo NUMERIC(8,0) IDENTITY NOT NULL,
	centro_costo VARCHAR(15) COLLATE Modern_Spanish_CI_AS NULL,
	origen VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_financ VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_impto VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	clasificador VARCHAR(20) COLLATE Modern_Spanish_CI_AS NULL,
	sec_func NUMERIC(4,0) NULL,
	valor_cn1 NUMERIC(15,2) NULL,
	valor_cn2 NUMERIC(15,2) NULL,
    MNTO_OPAGO NUMERIC(15,2) NULL,
    MNTO_PREVISION NUMERIC(15,2) NULL,
    MNTO_OPAGO2 NUMERIC(15,2) NULL,
    MNTO_PREVISION2 NUMERIC(15,2) NULL,
    MNTO_OPAGO3 NUMERIC(15,2) NULL,
    MNTO_PREVISION3 NUMERIC(15,2) NULL,
    MNTO_OPAGO4 NUMERIC(15,2) NULL,
    MNTO_PREVISION4 NUMERIC(15,2) NULL,
	MNTO_ANNO_01 NUMERIC(15,2) NULL,
	MNTO_ANNO_02 NUMERIC(15,2) NULL,
	MNTO_ANNO_03 NUMERIC(15,2) NULL
	)

