	(
	correlativo NUMERIC(20,0) IDENTITY NOT NULL,
	secuencia NUMERIC(8,0) NULL,
	origen VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_financ VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	categ_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	grupo_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	clasIFicador VARCHAR(20) COLLATE Modern_Spanish_CI_AS NULL,
	valor_techo NUMERIC(15,2) NULL
	)

CREATE TABLE #TMP_SIG_TECHO_APROB_UPD_04
	(
	correlativo NUMERIC(20,0) IDENTITY NOT NULL,
	secuencia NUMERIC(8,0) NULL,
	origen VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_financ VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	categ_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	grupo_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	clasIFicador VARCHAR(20) COLLATE Modern_Spanish_CI_AS NULL,
	sec_func NUMERIC(4,0) NULL,
	funcion VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	programa VARCHAR(3) COLLATE Modern_Spanish_CI_AS NULL,
	valor_techo NUMERIC(15,2) NULL
	)

CREATE TABLE #TMP_SIG_TECHO_APROB_UPD_05
	(
	correlativo NUMERIC(20,0) IDENTITY NOT NULL,
	secuencia NUMERIC(8,0) NULL,
	origen VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	fuente_financ VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	categ_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	grupo_gasto VARCHAR(1) COLLATE Modern_Spanish_CI_AS NULL,
	clasIFicador VARCHAR(20) COLLATE Modern_Spanish_CI_AS NULL,
	sec_func NUMERIC(4,0) NULL,
	funcion VARCHAR(2) COLLATE Modern_Spanish_CI_AS NULL,
	programa VARCHAR(3) COLLATE Modern_Spanish_CI_AS NULL,
	centro_costo_presup VARCHAR(15) COLLATE Modern_Spanish_CI_AS NULL,
	valor_techo NUMERIC(15,2) NULL
	)

IF @PN_FASE = 5
 UPDATE sig_techo_presupuesto
 SET    mnto_aprob  =0 ,
        MNTO_OPAGO  = 0,
        MNTO_PREVISION  = 0,
		MNTO_OPAGO2  = 0,
        MNTO_PREVISION2  = 0,
		MNTO_OPAGO3  = 0,
        MNTO_PREVISION3  = 0,
		MNTO_OPAGO4  = 0,
        MNTO_PREVISION4  = 0,
		MNTO_ANNO_01 = 0,
		MNTO_ANNO_02 = 0,
		MNTO_ANNO_03 = 0
 WHERE ANO_EJE = @PN_ANIO AND
       SEC_EJEC = @PN_EJEC AND
       flag_meta_aprob = '1'

IF @@ERROR <> 0
return -1


	DELETE FROM #TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END
	INSERT INTO #TMP_SIG_CN_TECHO_APROB_UPD
	( centro_costo,	origen,	fuente_financ,fuente_impto,clasIFicador,sec_func)
	SELECT DISTINCT m.centro_costo, m.origen, m.fuente_financ , m.fuente_impto, m.clasIFicador, m.sec_func
	FROM sig_cuadro_necesidad m
	WHERE m.ano_eje	= @PN_ANIO    AND
	m.sec_ejec	= @PN_EJEC AND 
	m.fase_cuadro    = @PN_FASE AND
	(m.fuente_financ is not  null) AND
	(m.clasIFicador  is not null) AND
	(m.sec_func      is not null)
	
	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	delete from #TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO #TMP_SIG_CN_TECHO_APROBADO
	(secuencia, 		centro_costo, 		origen, 		fuente_financ, 
	categ_gasto, 		grupo_gasto,		clasIFicador,sec_func,
	valor_cn)
	SELECT  
	0, 					c.centro_costo, 	c.origen, 		c.fuente_impto, 
	C.CATEG_GASTO, 		C.GRUPO_GASTO,		c.clasIFicador, c.sec_func, 
	sum(ISNULL(C.valor_imp_aprob, 0.00))
	FROM  sig_cuadro_necesidad c JOIN meta m 
	ON c.ANO_EJE= m.ano_eje AND c.sec_ejec  = m.sec_ejec AND c.sec_func  = m.sec_func	
	WHERE  	
	c.ano_eje      = @PN_ANIO AND
	c.sec_ejec     = @PN_EJEC AND
	c.fase_cuadro  = @PN_FASE AND
	c.tipo_impuesto <>'0' 	  AND
	c.fuente_impto is not NULL AND
	c.clasIFicador is not null AND
	c.sec_func     is not null
	GROUP BY
	c.centro_costo, 	c.origen, 			c.fuente_impto, 		C.CATEG_GASTO, 	
	C.GRUPO_GASTO,		c.clasIFicador, 	c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	UPDATE #TMP_SIG_CN_TECHO_APROBADO  
	SET Funcion = b.funcion, Programa =  b.programa
	FROM meta b
	WHERE ano_eje = b.ano_eje
	AND sec_ejec  = b.sec_ejec
	AND #TMP_SIG_CN_TECHO_APROBADO.sec_func  = b.sec_func	
	AND ano_eje   = @PN_ANIO
	AND sec_ejec  = @PN_EJEC

	IF @@ERROR <> 0
	BEGIN
		return -1
	END


	SELECT @ld_min_correl = MIN(CORRELATIVO) FROM #TMP_SIG_CN_TECHO_APROBADO

	UPDATE #TMP_SIG_CN_TECHO_APROBADO
	SET secuencia = correlativo - @ld_min_correl + 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @li_secuencia = MAX( secuencia ) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO AND sec_ejec = @PN_EJEC

	IF @li_secuencia  IS NULL 
	begin
	  SELECT @li_secuencia = 0
	end 

	INSERT INTO sig_techo_presupuesto  
	(ano_eje     , sec_ejec      	, origen        	,fuente_financ,
	secuencia    , categ_gasto   	, grupo_gasto    	,clasIFicador, 
	funcion      , programa      	, sec_func     		,centro_costo, 
	ppto_progra  , ppto_aprob	  	, ppto_asignado	 	,ppto_modIF,
	mnto_progra  , mnto_asig		, mnto_aprob		,mnto_modIF,
	indicador	 , paac_inicial  	, paac_modIF     	,porc_techo ,
	porc_asig	 , flag_meta_aprob)
	select 
	@PN_ANIO    , @PN_EJEC  		, m.origen     		, m.fuente_financ,
	m.secuencia + @li_secuencia, m.categ_gasto, m.grupo_gasto, m.clasIFicador, 
	NULL  	 , NULL  	, m.sec_func   		,m.centro_costo,
	0 			 ,0  				, 0 				,0 ,
	0  			 ,0					, m.valor_cn 		,0 ,
	'0' 		 ,0	  				, 0   				,0 ,
	0			 ,'1'
	from #TMP_SIG_CN_TECHO_APROBADO m
	WHERE
	not exists
	(SELECT 1 
	FROM sig_techo_presupuesto
	WHERE 
	ano_eje  		= @PN_ANIO AND
	sec_ejec 		= @PN_EJEC	AND
	origen 	 		= m.origen AND
	fuente_financ 	= m.fuente_financ AND
	categ_gasto 	= m.categ_gasto AND
	grupo_gasto 	= m.grupo_gasto AND
	clasIFicador 	= m.clasIFicador AND
	sec_func 		= m.sec_func AND
	centro_costo	= m.centro_costo AND
	indicador     	= '0' AND
	flag_meta_aprob = '1') 

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	delete from #TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO #TMP_SIG_CN_TECHO_APROBADO
	(secuencia, 		centro_costo, 		origen, 		fuente_financ, 
	categ_gasto,  		grupo_gasto,		clasIFicador,	sec_func,
	valor_cn)
	SELECT  
	0, 					c.centro_costo, 	c.origen, 		c.fuente_financ, 
	C.CATEG_GASTO,		C.GRUPO_GASTO,		c.clasIFicador, c.sec_func,			
	SUM(ISNULL(C.monto_aprob, 0.00))
  	FROM  sig_cuadro_necesidad c, meta m
 	WHERE  
	c.ano_eje   	= m.ano_eje AND
	c.sec_ejec  	= m.sec_ejec AND
	c.sec_func  	= m.sec_func AND
	c.ano_eje       = @PN_ANIO AND
	c.sec_ejec      = @PN_EJEC AND
	c.fase_cuadro   = @PN_FASE AND
	c.fuente_financ is not null AND
	c.clasIFicador  is not null AND
	c.sec_func      is not null
	GROUP BY
	c.centro_costo, 	c.origen, 			c.fuente_financ,C.CATEG_GASTO,
	C.GRUPO_GASTO,		c.clasIFicador, 	c.sec_func

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	UPDATE #TMP_SIG_CN_TECHO_APROBADO  
	SET Funcion = b.funcion, Programa =  b.programa
	FROM meta b
	WHERE ano_eje = b.ano_eje
	AND sec_ejec  = b.sec_ejec
	AND #TMP_SIG_CN_TECHO_APROBADO.sec_func  = b.sec_func	
	AND ano_eje   = @PN_ANIO
	AND sec_ejec  = @PN_EJEC


	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @ld_min_correl = MIN(CORRELATIVO) FROM #TMP_SIG_CN_TECHO_APROBADO

	UPDATE #TMP_SIG_CN_TECHO_APROBADO
	SET secuencia = correlativo - @ld_min_correl + 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	SELECT @li_secuencia = MAX( secuencia ) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO AND sec_ejec = @PN_EJEC

	IF @li_secuencia  IS NULL 
	begin
	  SELECT @li_secuencia = 0
	end 

	INSERT INTO sig_techo_presupuesto  
	(ano_eje     	, sec_ejec      	, origen        	, fuente_financ,
	secuencia    	, categ_gasto   	, grupo_gasto    	, clasIFicador, 
	funcion      	, programa      	, sec_func     		, centro_costo, 
	ppto_progra  	, ppto_aprob	  	, ppto_asignado	 	, ppto_modIF,
	mnto_progra  	, mnto_asig		  	, mnto_aprob		, mnto_modIF,
	indicador	 	, paac_inicial  	, paac_modIF     	,porc_techo ,
	porc_asig		, flag_meta_aprob)
	select 
	@PN_ANIO    	, @PN_EJEC  		, m.origen     		, m.fuente_financ,
	m.secuencia + @li_secuencia, m.categ_gasto, m.grupo_gasto, m.clasIFicador, 
	NULL  		, NULL  		, m.sec_func   		,m.centro_costo,
	0 				, 0  				, 0 				,0 ,
	0  				, 0					, m.valor_cn 		, 0,
	'0' 			, 0	  				, 0   				,0  ,
	0				, '1'
	from #TMP_SIG_CN_TECHO_APROBADO m
	WHERE
	not exists (SELECT 1 
		FROM sig_techo_presupuesto
		WHERE 
		ano_eje  		= @PN_ANIO AND
		sec_ejec 		= @PN_EJEC	AND
		origen 			= m.origen AND
		fuente_financ 	= m.fuente_financ AND
		categ_gasto 	= m.categ_gasto AND
		grupo_gasto 	= m.grupo_gasto AND
		clasIFicador 	= m.clasIFicador AND
		sec_func 		= m.sec_func AND
		centro_costo	= m.centro_costo AND
		indicador     	= '0' AND
		flag_meta_aprob = '1') 

	IF @@ERROR <> 0
	BEGIN
		return -1
	END


	delete FROM #TMP_SIG_CN_TECHO_APROBADO

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	DELETE FROM #TMP_SIG_CN_TECHO_APROB_UPD

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	INSERT INTO #TMP_SIG_CN_TECHO_APROB_UPD
	(centro_costo,		origen,			fuente_financ,		fuente_impto,
	clasIFicador,		sec_func,		valor_cn1,			valor_cn2,
    MNTO_OPAGO, MNTO_PREVISION,
	MNTO_OPAGO2, MNTO_PREVISION2,
	MNTO_OPAGO3, MNTO_PREVISION3,
	MNTO_OPAGO4, MNTO_PREVISION4,
	MNTO_ANNO_01,
	MNTO_ANNO_02,
	MNTO_ANNO_03
    )
	SELECT  
	c.centro_costo, 	c.origen, 		c.fuente_financ, 	'00', 
	c.clasIFicador, 	c.sec_func, 	sum(c.valor_imp_aprob), sum(c.monto_aprob),
    SUM(COALESCE(d.MNTO_OPAGO1, 0)), SUM(COALESCE(d.MNTO_PREVISION1, 0)),
	SUM(COALESCE(d.MNTO_OPAGO2, 0)), SUM(COALESCE(d.MNTO_PREVISION2, 0)),
	SUM(COALESCE(d.MNTO_OPAGO3, 0)), SUM(COALESCE(d.MNTO_PREVISION3, 0)),
	SUM(COALESCE(d.MNTO_OPAGO4, 0)), SUM(COALESCE(d.MNTO_PREVISION4, 0)),
	SUM(COALESCE(d.MNTO_TOTAL_ANNO_01, 0)), SUM(COALESCE(d.MNTO_TOTAL_ANNO_02, 0)),
	SUM(COALESCE(d.MNTO_TOTAL_ANNO_03, 0))
  	FROM  sig_cuadro_necesidad c
		LEFT JOIN
               (SELECT  ano_eje, sec_ejec, fase_cuadro, centro_costo, secuencia,
			SUM(COALESCE(MNTO_OPAGO1, 0)) AS mnto_opago1, SUM(COALESCE(MNTO_PREVISION1, 0)) AS mnto_prevision1,
			SUM(COALESCE(MNTO_OPAGO2, 0)) AS mnto_opago2, SUM(COALESCE(MNTO_PREVISION2, 0)) AS mnto_prevision2,
			SUM(COALESCE(MNTO_OPAGO3, 0)) AS mnto_opago3, SUM(COALESCE(MNTO_PREVISION3, 0)) AS mnto_prevision3,
			SUM(COALESCE(MNTO_OPAGO4, 0)) AS mnto_opago4, SUM(COALESCE(MNTO_PREVISION4, 0)) AS mnto_prevision4,
			SUM(COALESCE(MNTO_TOTAL_ANNO_01, 0)) AS MNTO_TOTAL_ANNO_01,
			SUM(COALESCE(MNTO_TOTAL_ANNO_02, 0)) AS MNTO_TOTAL_ANNO_02,
			SUM(COALESCE(MNTO_TOTAL_ANNO_03, 0)) AS MNTO_TOTAL_ANNO_03
	  	FROM  sig_cuadro_necesidad_det
	 	WHERE ano_eje      = @PN_ANIO AND
		      sec_ejec     = @PN_EJEC AND
		      fase_cuadro  = @PN_FASE 
		 group by ano_eje, sec_ejec, fase_cuadro, centro_costo, secuencia) d
	ON
		c.ano_eje      = d.ano_eje and
		c.sec_ejec     = d.sec_ejec and
		c.fase_cuadro  = d.FASE_CUADRO and
		c.CENTRO_COSTO = d.CENTRO_COSTO and
		c.SECUENCIA    = d.SECUENCIA 
	WHERE 
		c.ano_eje      = @PN_ANIO AND
		c.sec_ejec     = @PN_EJEC AND
		c.fase_cuadro  = @PN_FASE AND
		c.fuente_financ is not null  AND
		c.clasIFicador 	is not null AND
		c.sec_func 		is not null
		group by c.centro_costo, c.origen, c.fuente_financ, c.clasIFicador, c.sec_func
	IF @@ERROR <> 0
	BEGIN
		return -1
	END


