DECLARE c_0b CURSOR for
SELECT distinct centro_costo
FROM sig_techo_presupuesto
WHERE 
ano_eje  	 = @PN_ANIO AND
sec_ejec 	 = @PN_EJEC AND
indicador     = '0' AND
COALESCE(centro_costo_presup,'') = '' --(centro_costo_presup is null or centro_costo_presup = '') 

open c_0b
fetch c_0b into @ls_centro_costo

WHILE @@FETCH_STATUS = 0
BEGIN

		UPDATE  sig_techo_presupuesto
		SET centro_costo_presup = @ls_centro_costo
		WHERE 
		ano_eje 	 = @PN_ANIO AND
		sec_ejec 	 = @PN_EJEC AND
		centro_costo = @ls_centro_costo AND 
		indicador 	 = '0' AND
		centro_costo_presup is null or centro_costo_presup = ''

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_0b
			DEALLOCATE c_0b		
			return -1
		END
		fetch c_0b into @ls_centro_costo
		
	
END

CLOSE c_0b
DEALLOCATE c_0b


IF @PN_FASE = 1 OR @PN_FASE = 2 
BEGIN
	RETURN -1
END
ELSE
