		return -1
	END

	INSERT INTO #TMP_SIG_TECHO_APROB_UPD_01
	(secuencia, 		origen, 		fuente_financ, 			valor_techo)
	SELECT 0, 			a.origen, 		a.fuente_financ, 		sum(a.mnto_aprob) 
	FROM sig_techo_presupuesto a
	WHERE 
	a.ano_eje 		= @PN_ANIO AND
	a.sec_ejec 		= @PN_EJEC AND
	a.indicador     = '0' AND
	a.flag_meta_aprob = '1' AND
