	 MNTO_PREVISION3 =(SELECT sum(a.MNTO_PREVISION3) 
					FROM sig_techo_presupuesto a
					WHERE 
					a.ano_eje 		= @PN_ANIO AND
					a.sec_ejec 		= @PN_EJEC AND
					a.indicador     = '0' AND
					a.flag_meta_aprob = '1' AND
					a.origen    	= sig_techo_presupuesto.origen AND 
					a.fuente_financ = sig_techo_presupuesto.fuente_financ AND
				  	a.categ_gasto   = sig_techo_presupuesto.categ_gasto AND 
					a.grupo_gasto   = sig_techo_presupuesto.grupo_gasto AND 
					a.sec_func 	    = sig_techo_presupuesto.sec_func AND 
					a.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup AND
					a.clasIFicador = sig_techo_presupuesto.clasIFicador),
	 MNTO_PREVISION4 =(SELECT sum(a.MNTO_PREVISION4) 
					FROM sig_techo_presupuesto a
					WHERE 
					a.ano_eje 		= @PN_ANIO AND
					a.sec_ejec 		= @PN_EJEC AND
					a.indicador     = '0' AND
					a.flag_meta_aprob = '1' AND
					a.origen    	= sig_techo_presupuesto.origen AND 
					a.fuente_financ = sig_techo_presupuesto.fuente_financ AND
				  	a.categ_gasto   = sig_techo_presupuesto.categ_gasto AND 
					a.grupo_gasto   = sig_techo_presupuesto.grupo_gasto AND 
					a.sec_func 	    = sig_techo_presupuesto.sec_func AND 
					a.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup AND
					a.clasIFicador = sig_techo_presupuesto.clasIFicador)
	WHERE 
	ano_eje 		= @PN_ANIO AND
	sec_ejec 		= @PN_EJEC AND
	indicador     	= '5' AND
	flag_meta_aprob = '1' AND
	exists(SELECT '1' FROM sig_techo_presupuesto b
	WHERE 
	b.ano_eje 			= @PN_ANIO AND
	b.sec_ejec 			= @PN_EJEC AND
	b.indicador     	= '0' AND
	b.flag_meta_aprob 	= '1' AND
	b.origen    	= sig_techo_presupuesto.origen AND 
