-- ----------------------------
-- function structure for SF_INM_TASA_MEJORA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_INM_TASA_MEJORA]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_INM_TASA_MEJORA]
GO

CREATE FUNCTION [dbo].[SF_INM_TASA_MEJORA](
	@an_sec_ejec NUMERIC,
	@al_anno NUMERIC,
	@as_mes VARCHAR(2),
	@al_secuencia NUMERIC,
	@al_sec_unidad_activo NUMERIC,
	@al_sec_componente NUMERIC
)
RETURNS NUMERIC
AS
BEGIN

	DECLARE @TASA_DEPREC NUMERIC(10,2)
	DECLARE @ANO_EJE NUMERIC
	DECLARE @MES_MEJORA VARCHAR(2)
	DECLARE @LDC_RETORNO NUMERIC(10,2) = -1

	SELECT	TOP 1
			@TASA_DEPREC = COALESCE(tasa_deprec, 0), 
			@ANO_EJE = YEAR(SIG_MEJORAS.FECHA_MEJORA), 
			@MES_MEJORA = MES_MEJORA
	FROM	SIG_MEJORAS
	WHERE	SEC_EJEC				= @an_sec_ejec
	AND		(
				(YEAR(FECHA_MEJORA)	= @al_anno AND MES_MEJORA <= @as_mes)
				OR
				(YEAR(FECHA_MEJORA)	< @al_anno)
			)
	AND		SECUENCIA			= @al_secuencia
	AND		SEC_UNIDAD_ACTIVO	= @al_sec_unidad_activo
	AND		SEC_COMPONENTE		= @al_sec_componente
	AND		EXISTS	(
						SELECT	1
						FROM
							SIG_MOVIM_CONTABLE_INM_COMP
						WHERE
							SIG_MOVIM_CONTABLE_INM_COMP.SEC_EJEC		= SIG_MEJORAS.SEC_EJEC
							AND	SIG_MOVIM_CONTABLE_INM_COMP.ANO_EJE				= YEAR(SIG_MEJORAS.FECHA_MEJORA)
							AND	SIG_MOVIM_CONTABLE_INM_COMP.NMES_PROC_AMC		= SIG_MEJORAS.MES_MEJORA
							AND	SIG_MOVIM_CONTABLE_INM_COMP.SECUENCIA			= SIG_MEJORAS.SECUENCIA
							AND	SIG_MOVIM_CONTABLE_INM_COMP.SEC_UNIDAD_ACTIVO	= SIG_MEJORAS.SEC_UNIDAD_ACTIVO
							AND	SIG_MOVIM_CONTABLE_INM_COMP.SEC_COMPONENTE		= SIG_MEJORAS.SEC_COMPONENTE
					)
	ORDER	BY YEAR(SIG_MEJORAS.FECHA_MEJORA) DESC, MES_MEJORA DESC

	IF (CAST(@ANO_EJE AS VARCHAR) + @MES_MEJORA >= CAST(@al_anno AS VARCHAR) + @as_mes)
		SET @LDC_RETORNO = @TASA_DEPREC * 100

	--PRINT @LDC_RETORNO
	RETURN	@LDC_RETORNO

END
GO


