-- ----------------------------
-- procedure structure for SP_SI_TRANSMISION_PROGRAMACION
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_TRANSMISION_PROGRAMACION]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_TRANSMISION_PROGRAMACION]
GO

CREATE PROCEDURE [dbo].[SP_SI_TRANSMISION_PROGRAMACION] 
@P_ANO_EJE numeric(4, 0),  @P_SEC_EJEC numeric(6, 0), @P_FASE_CUADRO numeric(1, 0), @O_ERR_NUM numeric(6, 0) OUTPUT, @O_ERR_MSG varchar(255) OUTPUT
AS
BEGIN


IF OBJECT_ID ('SIG_TRANS_PROGRAMACION_TMP') IS NOT NULL
	DROP TABLE SIG_TRANS_PROGRAMACION_TMP 

truncate TABLE  SIG_TRANS_PROGRAMACION_UE 

SELECT cab.ano_eje, cab.fase_cuadro fase_cuadro,
	CASE cab.fase_cuadro
	     WHEN 1 THEN 'REQUERIDO'
	     WHEN 2 THEN 'PROGRAMADO/ANTEPROYECTO'
	     WHEN 5 THEN 'APROBADO'
	END FASE,
	CAB.SEC_EJEC,	
	STR.SECTOR SECTOR,
	STR.SECTOR  +' - '+ RTRIM(STR.NOMBRE) NOM_SECTOR,
	PG.pliego PLIEGO,
	RTRIM( PG.pliego+' - '+PG.nombre) NOM_PLIEGO, 
	 EJC.sec_ejec EJECUTORA,
	CONVERT (VARCHAR, EJC.sec_ejec)+' - '+  EJC.nombre NOM_EJECUTORA,
	SCC.CENTRO_COSTO CENTRO_COSTO,
	SCC.CENTRO_COSTO+' - '+SCC.ABREVIADO_DEPEND NOM_CENTRO_COSTO,
	COALESCE(SPS.COD_ESTABLEC ,'00000') PTO_ATEN,
   	SPE.DESC_ESTABLEC DESC_ESTABLEC,
	CTG.CATEGORIA PTO_ATEN_CATEGORIA,
               LTRIM(RTRIM(CTG.NOMBRE_CORTO)) nom_categoria,
	CASE LEN (COALESCE( SPE.COD_OGEI,'00000')) 
	     WHEN 4 THEN '0'+ SPE.COD_OGEI 
	     ELSE      COALESCE( SPE.COD_OGEI,'00000')
	END PTO_ATEN_COD_RENAES,
	CASE  SPE.CATEGORIA
	     WHEN 9 THEN 'M'
	     WHEN 99 THEN 'N'
	      ELSE 'F'
	END TIPO_PTO_ATEN,
	
	SPE.UBIGEO ,
	COALESCE( SPD.DESC_DISA,'NO TIENE') PTO_ATEN_DISA,
	COALESCE( SPR.DESC_RED,'NO TIENE') PTO_ATEN_RED,
	COALESCE( SPM.DESC_MICRORED,'NO TIENE') PTO_ATEN_MICRORED,
	COALESCE(STI.INST_DESCRI,'NO TIENE') PTO_ATEN_INSTITUCION,
    SPE.ESTADO estado_pto,
	CASE  SPE.ESTADO
	     WHEN 'A' THEN 'Activo'
	     WHEN 'I' THEN 'Activo'
	     ELSE 	'NO TIENE'
	END NOM_PTO_ATEN_ESTADO,
	cab.sec_func_prop sec_func1,
	cab.sec_func sec_func2,
	CASE  CAB.fase_cuadro
	     WHEN 5 THEN cab.sec_func
	     ELSE      cab.sec_func_prop
	END sec_func,
	COALESCE(CAB.sub_finalidad ,0000000) SUB_PRODUCTO,
	CASE  CAB.sub_finalidad
	     WHEN '' THEN '0000000 - SIN SUB_PRODUCTO'
	     ELSE      CAB.sub_finalidad +' - '+ SSF.NOMBRE
	END NOM_SUB_PRODUCTO,
	CASE  SSF.TRAZADOR
	     WHEN 1 THEN 'S'
	     ELSE 'N'
	END TRAZADOR,
	COALESCE(MXS.CANT_01,0)+COALESCE(MXS.CANT_02,0)+COALESCE(MXS.CANT_03,0)+COALESCE(MXS.CANT_04,0)+COALESCE(MXS.CANT_05,0)+COALESCE(MXS.CANT_06,0)+COALESCE(MXS.CANT_07,0)+COALESCE(MXS.CANT_08,0)+COALESCE(MXS.CANT_09,0)+COALESCE(MXS.CANT_10,0)+COALESCE(MXS.CANT_11,0)+COALESCE(MXS.CANT_12,0) META_FISICA,
    CAB.CLASIFICADOR clasificador,
   	SUBSTRING (CAB.CLASIFICADOR,1,3) GENERICA,
	SUBSTRING (CAB.CLASIFICADOR,1,6) SUB_GENERICA1,
	SUBSTRING (CAB.CLASIFICADOR,1,9) SUB_GENERICA2,
	SUBSTRING (CAB.CLASIFICADOR,1,12) ESPECIFICA1,
	CAB.CLASIFICADOR ESPECIFICA2,
	CAB.FUENTE_FINANC Fuente_Financ ,
	CASE  CAB.FUENTE_FINANC
	     WHEN '00' THEN '00 - RECURSOS ORDINARIOS'
	     WHEN '09' THEN '09 - RECURSOS DIRECTAMENTE RECAUDADOS'
   	END NOM_Fuente_Financ,
	DET.TIPO_BIEN, 
	DET.GRUPO_BIEN, 
	DET.CLASE_BIEN,
	DET.FAMILIA_BIEN,
	DET.ITEM_BIEN,
	DET.TIPO_BIEN+DET.GRUPO_BIEN+ DET.CLASE_BIEN+	DET.FAMILIA_BIEN+DET.ITEM_BIEN ITEM_CATALOGO,
  	cab.tipo_uso,
	CASE  cab.tipo_uso
	     WHEN 'C' THEN 'CONSUMO'
	     WHEN 'V' THEN 'VENTA'
   	     WHEN 'H' THEN 'HUMANO'
   	     WHEN 'P' THEN 'PRODUCCION'
  	     WHEN 'D' THEN 'DISTRIBUCION GRATUITA'	    
	END TIPO_USO_DES,
                CONVERT(VARCHAR(20), UM.UNIDAD_MEDIDA) + UM.NOMBRE NOM_unidad_medida,
	UM.UNIDAD_MEDIDA unidad_medida,
	DET.PRECIO_UNIT PRECIO_UNIT,
	DET.CANT_TOTAL CANTIDAD,
	DET.MNTO_TOTAL MONTO,
	CID.id_kit,
	CAB.ID_SUB_FINALIDAD,
	SSF.UNIDAD_MEDIDA AS SUB_PRODUCTO_UM,
	spe.SECTOR_AMBITO
  INTO SIG_TRANS_PROGRAMACION_TMP
FROM SIG_CUADRO_NECESIDAD CAB LEFT
	OUTER JOIN  SIG_SUB_FINALIDAD SSF ON
	(CAB.ANO_EJE= SSF.ANO_EJE  AND
	 CAB.SUB_FINALIDAD = SSF.SUB_FINALIDAD AND
	 CAB.ID_SUB_FINALIDAD = SSF.ID_SUB_FINALIDAD  AND
	SSF.ESTADO='A') LEFT 
	OUTER JOIN SIG_PPR_METFIS_X_SUBFIN MXS ON
	(CAB.ANO_EJE=MXS.ANO_EJE AND
	CAB.SEC_EJEC= MXS.SEC_EJEC AND
	CAB.FASE_CUADRO = MXS.NRO_FASE AND 
	(CAB.SEC_FUNC_PROP = MXS.SEC_FUNC OR 
	CAB.sec_func= MXS.SEC_FUNC) AND
	CAB.SEC_ESTABLEC= MXS.SEC_ESTABLEC AND
	CAB.sub_finalidad= MXS.SUB_FINALIDAD AND
	CAB.ID_SUB_FINALIDAD= MXS.ID_SUB_FINALIDAD),
	SIG_CUADRO_NECESIDAD_DET DET LEFT
	 OUTER JOIN sig_cua_nec_det_id CID ON
	 ( DET.ANO_EJE= CID.ano_eje AND
	 DET.sec_ejec = CID.sec_ejec AND
	 DET.CENTRO_COSTO = CID.centro_costo AND
	 DET.SECUENCIA = CID.secuencia AND
	DET.FASE_CUADRO  = CID.fase_cuadro AND
	DET.ITEM_SEC = CID.item_sec ) ,
	unidad_medida UM ,
	ejecutora EJC,
	SIG_CENTRO_COSTO SCC,
	PLIEGO PG,
	SIG_PPR_SEDE SPS,
	SIG_PPR_ESTABLECIMIENTO SPE LEFT
	OUTER JOIN  SIG_PPR_DISA SPD ON
	( SUBSTRING(SPE.CAD_OPERATIVA,1,2) = SPD.COD_DISA  AND
	SPD.ESTADO='A') LEFT
	OUTER JOIN SIG_PPR_RED SPR ON
	(SUBSTRING(SPE.CAD_OPERATIVA,1,4) = SPR.COD_DISA + SPR.COD_RED  AND 
	SPR.ESTADO='A') LEFT
	OUTER JOIN SIG_PPR_MICRORED SPM ON 
	(SUBSTRING(SPE.CAD_OPERATIVA,1,6) = SPM.COD_DISA + SPM.COD_RED + SPM.COD_MICRORED AND
	SPM.ESTADO='A') LEFT
	 OUTER JOIN 	SIG_PPR_TIPO_INSTITUCION STI ON 
	 (STI.INST_TIPO= SPE.INST_TIPO  ),
	SIG_PPR_CATEGORIA CTG ,
	sector STR 

	WHERE
	CAB.ANO_EJE=@P_ANO_EJE AND
	CAB.SEC_EJEC=@P_SEC_EJEC AND
	DET.ANO_EJE= CAB.ANO_EJE AND
	DET.SEC_EJEC= CAB.SEC_EJEC AND
	DET.CENTRO_COSTO= CAB.CENTRO_COSTO AND
	DET.SECUENCIA = CAB.SECUENCIA AND
	DET.FASE_CUADRO = CAB.FASE_CUADRO  AND
	det.ESTADO_ITEM_KIT= 'A' AND
	det.FASE_CUADRO= @P_FASE_CUADRO  AND
	DET.UNIDAD_MEDIDA = UM.UNIDAD_MEDIDA AND
	scc.ANO_EJE= DET.ANO_EJE AND
	SCC.SEC_EJEC= DET.SEC_EJEC AND
	SCC.CENTRO_COSTO= DET.CENTRO_COSTO AND
	SCC.ESTADO= 'A' AND
	EJC.sec_ejec= CAB.SEC_EJEC AND
	EJC.estado= 'A'  AND
	PG.PLIEGO= EJC.pliego AND
	PG.sector= EJC.sector AND
	PG.estado= 'A' AND
	SPS.ANO_EJE= SCC.ANO_EJE AND
	SPS.SEC_EJEC= SCC.SEC_EJEC AND
	SPS.SEDE= SCC.SEDE AND
	SPE.ANO_EJE= SPS.ANO_EJE AND
	SPE.SEC_EJEC= SPS.SEC_EJEC AND
	SPE.COD_ESTABLEC= SPS.COD_ESTABLEC AND 
	((SPE.ESTADO= 'A' AND SPE.ANO_EJE > 2013) OR (SPE.ANO_EJE <= 2013 )) AND
	CTG.ANO_EJE= SPE.ANO_EJE AND
	CTG.CATEGORIA= SPE.CATEGORIA AND
	CTG.ESTADO= 'A' AND CTG.SECTOR_AMBITO='01' AND
		STR.SECTOR= EJC.SECTOR	

INSERT INTO SIG_TRANS_PROGRAMACION_UE  (			ano_eje,   				fase_cuadro,			FASE,  					SEC_EJEC,				NOM_SECTOR,
	SECTOR,				PLIEGO,						NOM_PLIEGO,				 EJECUTORA,				NOM_EJECUTORA,			CENTRO_COSTO         ,	NOM_CENTRO_COSTO,		
	PTO_ATEN_CATEGORIA,			nom_categoria,			PTO_ATEN_COD_RENAES  , 	TIPO_PTO_ATEN        ,	UBIGEO             ,	PTO_ATEN_DISA        , 
	PTO_ATEN_RED      ,	PTO_ATEN_MICRORED, 	 		PTO_ATEN_INSTITUCION ,	estado_pto     ,    	NOM_PTO_ATEN_ESTADO,	sec_func,				SUB_PRODUCTO	,	   
	NOM_SUB_PRODUCTO  ,	TRAZADOR        ,			META_FISICA          , 	CLASIFICADOR         ,	tipo_uso,				tipo_uso_DES,			GENERICA             , 
	SUB_GENERICA1     ,	SUB_GENERICA2   ,			ESPECIFICA1        ,	ESPECIFICA2        ,	Fuente_Financ      ,	NOM_Fuente_Financ,		TIPO_BIEN          ,	
	GRUPO_BIEN       ,	CLASE_BIEN      ,			FAMILIA_BIEN       ,	ITEM_BIEN 			,	NOM_unidad_medida,		unidad_medida      ,	PRECIO_UNIT        ,   
	CANTIDAD         , 	MONTO          	,  			id_kit	  		,		ID_SUB_FINALIDAD,		ITEM_CATALOGO,			PTO_ATEN ,				DESC_ESTABLEC, 
	SUB_PRODUCTO_UM , SECTOR_AMBITO)

SELECT   											ano_eje,	 			fase_cuadro,			FASE,  					SEC_EJEC,				NOM_SECTOR,
	SECTOR,				PLIEGO,						NOM_PLIEGO,				EJECUTORA,				NOM_EJECUTORA,			CENTRO_COSTO         ,	NOM_CENTRO_COSTO,		
	PTO_ATEN_CATEGORIA,			nom_categoria,			PTO_ATEN_COD_RENAES  ,	TIPO_PTO_ATEN        ,	UBIGEO             ,	PTO_ATEN_DISA        ,	
	PTO_ATEN_RED    ,	PTO_ATEN_MICRORED,			PTO_ATEN_INSTITUCION , 	estado_pto     ,    	NOM_PTO_ATEN_ESTADO,	sec_func,				SUB_PRODUCTO	,	 
	NOM_SUB_PRODUCTO ,	TRAZADOR        ,			META_FISICA          ,	CLASIFICADOR         ,	tipo_uso,				tipo_uso_DES,			GENERICA             ,  
	SUB_GENERICA1    ,	SUB_GENERICA2   ,  			ESPECIFICA1        ,  	ESPECIFICA2        ,	Fuente_Financ      ,	NOM_Fuente_Financ,		TIPO_BIEN          ,	
	GRUPO_BIEN       , 	CLASE_BIEN      ,			FAMILIA_BIEN       ,	ITEM_BIEN 			,  	NOM_unidad_medida,		unidad_medida      ,  	PRECIO_UNIT        ,   
	CANTIDAD         ,  MONTO      		, 		 	id_kit				,	ID_SUB_FINALIDAD,		ITEM_CATALOGO ,			PTO_ATEN,				DESC_ESTABLEC, 
	SUB_PRODUCTO_UM, SECTOR_AMBITO
FROM SIG_TRANS_PROGRAMACION_TMP 

  	IF (@@error <> 0)
		begin
			set @O_ERR_MSG = 'No existen datos para los filtros seleccionados.Verificar'
			RETURN
		End

UPDATE SIG_TRANS_PROGRAMACION_UE
SET nombre_DPTO_PTO ='NO TIENE',
	NOMBRE_PROV_PTO= 'NO TIENE',
	NOMBRE_DIST_PTO ='NO TIENE'
	WHERE ano_eje= @P_ANO_EJE  AND
	SEC_EJEC= @P_SEC_EJEC AND
	UBIGEO='000000'  AND
	fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE  
SET nombre_DPTO_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,1,2) AND UBG.provincia='00' AND
						UBG.distrito='00' AND UBG.estado='A' )
WHERE  nombre_DPTO_PTO IS NULL AND 
	ano_eje= @P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC  AND
	fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE  
SET nombre_PROV_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,1,2) AND 
							  UBG.provincia= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,3,2) AND
							 UBG.distrito='00' AND UBG.estado='A' )
WHERE  nombre_PROV_PTO IS NULL AND 
		ano_eje=@P_ANO_EJE AND
		SEC_EJEC=@P_SEC_EJEC AND
		fase_cuadro= @P_FASE_CUADRO 



UPDATE SIG_TRANS_PROGRAMACION_UE  
SET nombre_DIST_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,1,2) AND 
						      UBG.provincia= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,3,2) AND
						      UBG.distrito= SUBSTRING(SIG_TRANS_PROGRAMACION_UE.UBIGEO,5,2)  AND 
						      UBG.estado='A' )
WHERE  nombre_DIST_PTO IS NULL AND 
		ano_eje=@P_ANO_EJE AND
		SEC_EJEC=@P_SEC_EJEC AND
		fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE
	SET CATEG_PPTAL = 'ACCIONES (SIN PROGRAMA)'
  WHERE  
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC  AND
	ESTRATEGIA_NACIONAL= '9001'  AND
	fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET CATEG_PPTAL = 'ASIGNACIONES (SIN PROGRAMA)'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC  AND
ESTRATEGIA_NACIONAL= '9002' and
fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET CATEG_PPTAL = 'CON PROGRAMA',
    META_PROG_PPTO = ESTRATEGIA_NACIONAL+' - '+(SELECT enn.NOMBRE
			FROM 
			ESTRATEGIA_NACIONAL_NOMBRE enn
			WHERE enn.ANO_EJE= SIG_TRANS_PROGRAMACION_UE.ano_eje AND
			enn.ESTRATEGIA_NACIONAL= SIG_TRANS_PROGRAMACION_UE.ESTRATEGIA_NACIONAL AND
			enn.ESTADO='A') 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ESTRATEGIA_NACIONAL NOT IN ('9001','9002') 


UPDATE SIG_TRANS_PROGRAMACION_UE
SET META_PROG_PPTO = '0000 - SIN PROGRAMA PRESUPUESTAL'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ESTRATEGIA_NACIONAL  IN ('9001','9002') 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET ACT_PROY = (SELECT smp.ACT_PROY
						FROM SIG_META_PROPUESTA smp 
						WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE.ano_eje AND 
						smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE.SEC_EJEC AND
						smp.SEC_FUNC_PROP= SIG_TRANS_PROGRAMACION_UE.sec_func ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO AND @P_FASE_CUADRO <5 
	
UPDATE SIG_TRANS_PROGRAMACION_UE
SET ACT_PROY = (SELECT smp.ACT_PROY
						FROM meta smp 
						WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE.ano_eje AND 
						smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE.SEC_EJEC AND
						smp.SEC_FUNC= SIG_TRANS_PROGRAMACION_UE.sec_func)
WHERE
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC AND
	fase_cuadro= 5 
    AND @P_FASE_CUADRO= 5 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET META_PRODUCTO = ACT_PROY+' - '+(  		   
		SELECT LTRIM(RTRIM(NOMBRE))
			FROM Act_Proy_Nombre_FASE  
			WHERE ANO_EJE=  SIG_TRANS_PROGRAMACION_UE.ano_eje AND 
					act_proy= SIG_TRANS_PROGRAMACION_UE.ACT_PROY    AND 
					estado= 'A' 
					AND @P_FASE_CUADRO IN (1, 2)
		UNION
		 
		SELECT NOMBRE 
			FROM Act_Proy_Nombre  
			WHERE ANO_EJE= SIG_TRANS_PROGRAMACION_UE.ano_eje AND 
					act_proy= SIG_TRANS_PROGRAMACION_UE.ACT_PROY   AND 
					estado= 'A'	
					AND @P_FASE_CUADRO = 5 
			) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ACT_PROY NOT IN ('3999999') 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET META_PRODUCTO = '000000 - SIN PRODUCTO'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ACT_PROY  IN ('3999999') 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET TIPO_CALCULO = 0,
	TIPO_COSTO_DI ='N',
	TIPO_COSTO_FV = 'N',
	ES_ESTRATEGICO='N',
	NIVEL='SIN KIT'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
id_kit IS null 

UPDATE SIG_TRANS_PROGRAMACION_UE
SET TIPO_CALCULO = (SELECT TIPO_CALCULO
						FROM SI_PPR_KIT_ITEMS KIT
						WHERE 	kit.ano_eje = SIG_TRANS_PROGRAMACION_UE.ano_eje AND
						       	KIT.SEC_KIT= SIG_TRANS_PROGRAMACION_UE.id_kit AND
								KIT.id_sub_finalidad =SIG_TRANS_PROGRAMACION_UE.ID_SUB_FINALIDAD 
							    ),
	TIPO_COSTO_DI = (SELECT TIPO_COSTO_DI
						FROM SI_PPR_KIT_ITEMS KIT
						WHERE 	kit.ano_eje = SIG_TRANS_PROGRAMACION_UE.ano_eje AND
						       	KIT.SEC_KIT= SIG_TRANS_PROGRAMACION_UE.id_kit AND
								KIT.id_sub_finalidad =SIG_TRANS_PROGRAMACION_UE.ID_SUB_FINALIDAD 
							    ),
	TIPO_COSTO_FV = (SELECT TIPO_COSTO_FV
						FROM SI_PPR_KIT_ITEMS KIT
						WHERE 	kit.ano_eje = SIG_TRANS_PROGRAMACION_UE.ano_eje AND
						       	KIT.SEC_KIT= SIG_TRANS_PROGRAMACION_UE.id_kit AND
								KIT.id_sub_finalidad =SIG_TRANS_PROGRAMACION_UE.ID_SUB_FINALIDAD 
							    ),
	PROG_RECTOR = (SELECT PROG_RECTOR
						FROM SI_PPR_KIT_ITEMS KIT
						WHERE 	kit.ano_eje = SIG_TRANS_PROGRAMACION_UE.ano_eje AND
						       	KIT.SEC_KIT= SIG_TRANS_PROGRAMACION_UE.id_kit AND
								KIT.id_sub_finalidad =SIG_TRANS_PROGRAMACION_UE.ID_SUB_FINALIDAD
							    )
WHERE
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
id_kit IS NOT null 


UPDATE 	SIG_TRANS_PROGRAMACION_UE
SET PTO_ATEN_NOMBRE = 	PTO_ATEN_COD_RENAES+' - '+LTRIM(RTRIM(DESC_ESTABLEC )),

NOM_GENERICA= GENERICA  +' - '+ (
	SELECT nombre_clasif FROM SIG_CLASIFICADOR_GASTO 
	WHERE ANO_EJE= @P_ANO_EJE 
	AND CLASIFICADOR =GENERICA+'. 0  0. 0  0' AND
	estado='A'),

NOM_SUB_GENERICA1= SUB_GENERICA1 +' - '+ (
	SELECT nombre_clasif FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE= @P_ANO_EJE 
	AND CLASIFICADOR =SUB_GENERICA1+'  0. 0  0' AND
	estado='A'),
    
NOM_SUB_GENERICA2= SUB_GENERICA2 +' - '+ (
	SELECT nombre_clasif FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE= @P_ANO_EJE 
	AND CLASIFICADOR =SUB_GENERICA2+'. 0  0' AND
	estado='A'),
    
FAMILIA_BIEN_C=TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+' - '+(	SELECT nombre_fam 
					FROM familia_bien_serv
					WHERE tipo_bien= SIG_TRANS_PROGRAMACION_UE.TIPO_BIEN AND 
					grupo_bien=SIG_TRANS_PROGRAMACION_UE.grupo_bien 
					AND clase_bien= SIG_TRANS_PROGRAMACION_UE.CLASE_BIEN AND 
					familia_bien=SIG_TRANS_PROGRAMACION_UE.FAMILIA_BIEN AND
					ESTADO ='A'),
                    
ITEM_BIEN_C= TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+ITEM_BIEN+' - '+NOM_ITEM_BIEN,

CLASE_BIEN_C=TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+' - '+(	SELECT nombre_clase 
					FROM clase_bien_serv
					WHERE tipo_bien= SIG_TRANS_PROGRAMACION_UE.TIPO_BIEN AND 
					grupo_bien=SIG_TRANS_PROGRAMACION_UE.grupo_bien 
					AND clase_bien= SIG_TRANS_PROGRAMACION_UE.CLASE_BIEN and
					ESTADO ='A'),

NOM_ESPECIFICA1= ESPECIFICA1 +' - '+ (
	SELECT nombre_clasif FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE= @P_ANO_EJE 
	AND CLASIFICADOR =ESPECIFICA1+'  0' AND
	estado='A'),



NOM_ESPECIFICA2= ESPECIFICA2 +' - '+ (
	SELECT nombre_clasif FROM SIG_CLASIFICADOR_GASTO WHERE ANO_EJE= @P_ANO_EJE 
	AND CLASIFICADOR =ESPECIFICA2 AND
	estado='A'),

GRUPO_BIEN_C= TIPO_BIEN+GRUPO_BIEN+' - '+(	SELECT nombre_grupo 
					FROM grupo_bien_serv
					WHERE tipo_bien= SIG_TRANS_PROGRAMACION_UE.TIPO_BIEN AND grupo_bien=SIG_TRANS_PROGRAMACION_UE.GRUPO_BIEN AND
					ESTADO ='A')

WHERE
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO 

END
GO


-- ----------------------------
-- procedure structure for SP_CARGA_PATRIMONIO_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_PATRIMONIO_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_PATRIMONIO_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_PATRIMONIO_TRX]
   ( @P_ANO_EJE       NUMERIC(4,0),
     @P_SEC_EJEC      NUMERIC(6,0),
     @O_ERR_NUM       NUMERIC(6,0)   OUTPUT,
     @O_ERR_MSG       VARCHAR(255) OUTPUT )
AS
DECLARE  
  @LS_TIPO_MOVIMTO   VARCHAR(1),
  @LS_TIPO_BIEN      VARCHAR(1),
  @LS_ESTADO_BIEN    VARCHAR(1),
  @LN_VALOR_INICIAL  NUMERIC(16,2),
  @LS_CLASIFICADOR   VARCHAR(20),
  @LS_MAYOR          VARCHAR(4),
  @LS_SUB_CTA        VARCHAR(8),
  @LN_VIDA_UTIL      NUMERIC(4,2) ,
  @LN_MES_PROCESO    NUMERIC(2,0) ,
  @LN_DEPRECIACION   NUMERIC(16,2),
  @LN_TIPO_ENTIDAD   NUMERIC(2,0) ,
  @LL_SECUENCIA      NUMERIC(8,0) ,
  @LS_GRUPO_BIEN     VARCHAR(2),
  @LS_CLASE_BIEN     VARCHAR(2),
  @LS_FAMILIA_BIEN   VARCHAR(4),
  @LS_ITEM_BIEN      VARCHAR(4),
  @LS_DEPARTAMENTO   VARCHAR(2),
  @LS_PROVINCIA      VARCHAR(2),
  @LS_SECTOR         VARCHAR(2),
  @LS_PLIEGO         VARCHAR(3),
  @LS_CATEGORIA      VARCHAR(3),
  @LS_GRUPO          VARCHAR(3),
  @LS_MODALIDAD      VARCHAR(5),
  @LS_ELEMENTO_GASTO VARCHAR(5),  
  @LN_SECUENCIA      NUMERIC (10,0),
  @LL_INICIO INTEGER,
  @LL_LONG   INTEGER 
  
BEGIN
	DELETE FROM SGE_PATRIMONIO_TRX

   
    SELECT @LN_SECUENCIA = MAX(secuencia)
           FROM SGE_PATRIMONIO_TRX
     WHERE ANO_EJE  = @P_ANO_EJE  AND
           SEC_EJEC = @P_SEC_EJEC    
           
	IF @LN_SECUENCIA IS NULL   
		SET @LN_SECUENCIA = 0     


    DECLARE C_1 CURSOR FOR
	 	SELECT            
            A.TIPO_MOV_INGR,     
            A.TIPO_BIEN,   
            A.GRUPO_BIEN,   
            A.CLASE_BIEN,   
            A.FAMILIA_BIEN,   
            A.ITEM_BIEN,   
            A.ESTADO,   
            A.VALOR_INICIAL,   
            A.CLASIFICADOR,   
            A.MAYOR,   
            A.SUB_CTA,   
            A.VIDA_UTIL,   
            A.MES_PROCESO,
            A.VALOR_DEPREC,
            C.TIPO_ENTIDAD,
            C.departamento,
            C.provincia, 
            B.sector,
            B.pliego
        FROM SIG_PATRIMONIO A
        JOIN SIG_EJECUTORA B
            ON  B.sec_ejec = A.SEC_EJEC
            AND B.estado   = 'A'
        JOIN EJECUTORA C
            ON  C.sec_ejec = B.SEC_EJEC
        WHERE
            A.ANO_EJE  =  @P_ANO_EJE AND
            A.SEC_EJEC =  @P_SEC_EJEC AND
            A.CLASIFICADOR IS NOT NULL AND
            A.MES_PROCESO IS NOT NULL    
     
    OPEN C_1
    FETCH NEXT FROM C_1 INTO
    @LS_TIPO_MOVIMTO  ,  @LS_TIPO_BIEN  ,  @LS_GRUPO_BIEN  ,  @LS_CLASE_BIEN ,  @LS_FAMILIA_BIEN  ,  @LS_ITEM_BIEN,    @LS_ESTADO_BIEN ,  @LN_VALOR_INICIAL  ,  @LS_CLASIFICADOR ,  
    @LS_MAYOR ,  		 @LS_SUB_CTA    ,  @LN_VIDA_UTIL   ,  @LN_MES_PROCESO,  @LN_DEPRECIACION  ,  @LN_TIPO_ENTIDAD, @LS_DEPARTAMENTO , @LS_PROVINCIA      ,  @LS_SECTOR       ,
    @LS_PLIEGO 
 
    
    WHILE @@FETCH_STATUS = 0         
    BEGIN
	SET  @LL_INICIO = 0    
	SET  @LL_LONG = 0 
       SET @LN_SECUENCIA = @LN_SECUENCIA +1 
                
       SET @LS_CATEGORIA =  SUBSTRING(@LS_CLASIFICADOR, 1  , (CHARINDEX('.',@LS_CLASIFICADOR ,  1) -1))
       
       SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 
	   SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1)) - (CHARINDEX('.' ,@LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 )  
	   SET @LS_GRUPO  = SUBSTRING( @LS_CLASIFICADOR, @LL_INICIO, @LL_LONG)
	   
	   SET @LL_INICIO = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1
	   SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) - (CHARINDEX('.' ,@LS_CLASIFICADOR, (charindex('.',@LS_CLASIFICADOR) + 1) )   + 1)
	   SET @LS_MODALIDAD = SUBSTRING( @LS_CLASIFICADOR,@LL_INICIO, @LL_LONG )

	   SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) +1
	   SET @LL_LONG = LEN(@LS_CLASIFICADOR) -  charindex('.' ,@LS_CLASIFICADOR, (charindex('.' ,@LS_CLASIFICADOR, (charindex('.',@LS_CLASIFICADOR) + 1) ) + 1)  ) 
	   SET @LS_ELEMENTO_GASTO =	 SUBSTRING(@LS_CLASIFICADOR, @LL_INICIO, @LL_LONG )  
	   
 	                             
    
       INSERT INTO SGE_PATRIMONIO_TRX 
        (   ANO_EJE,              SEC_EJEC,        TIPO_MOVIMTO,        SECUENCIA,
            TIPO_BIEN,            GRUPO_BIEN,      CLASE_BIEN,          FAMILIA_BIEN,
            ITEM_BIEN,            ESTADO_BIEN,     VALOR_INICIAL,       CLASIFICADOR,
            MAYOR,                SUB_CTA,         VIDA_UTIL,           MES_PROCESO,
            TIPO_ENTIDAD,    	  DEPARTAMENTO,    PROVINCIA,           CATEGORIA_GASTO,
            GRUPO,           	  MODALIDAD,       ELEMENTO_GASTO,  	DEPRECIACION,
            SECTOR,               PLIEGO         )
       VALUES
       (    @P_ANO_EJE,           @P_SEC_EJEC,        @LS_TIPO_MOVIMTO,   @LN_SECUENCIA,
            @LS_TIPO_BIEN,        @LS_GRUPO_BIEN,     @LS_CLASE_BIEN,     @LS_FAMILIA_BIEN,
            @LS_ITEM_BIEN,        @LS_ESTADO_BIEN,    @LN_VALOR_INICIAL,  @LS_CLASIFICADOR,
            @LS_MAYOR,            @LS_SUB_CTA,        @LN_VIDA_UTIL,      @LN_MES_PROCESO, 
            @LN_TIPO_ENTIDAD,     @LS_DEPARTAMENTO,   @LS_PROVINCIA,      @LS_CATEGORIA,        
            @LS_GRUPO,            @LS_MODALIDAD,      @LS_ELEMENTO_GASTO, @LN_DEPRECIACION,
            @LS_SECTOR,           @LS_PLIEGO )
            
	 FETCH NEXT FROM C_1 INTO
    	@LS_TIPO_MOVIMTO  ,  @LS_TIPO_BIEN  ,  @LS_GRUPO_BIEN  ,  @LS_CLASE_BIEN ,  @LS_FAMILIA_BIEN  ,  @LS_ITEM_BIEN,    @LS_ESTADO_BIEN ,  @LN_VALOR_INICIAL  ,  @LS_CLASIFICADOR ,  
    	@LS_MAYOR ,  		 @LS_SUB_CTA    ,  @LN_VIDA_UTIL   ,  @LN_MES_PROCESO,  @LN_DEPRECIACION  ,  @LN_TIPO_ENTIDAD, @LS_DEPARTAMENTO , @LS_PROVINCIA      ,  @LS_SECTOR       ,
    	@LS_PLIEGO 
	  
  	END 
  	CLOSE C_1
  	DEALLOCATE C_1         
      
    BEGIN 
	  UPDATE SGE_PATRIMONIO_TRX
	        SET SGE_PATRIMONIO_TRX.SECTOR  = (SELECT B.SECTOR FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_PATRIMONIO_TRX.SEC_EJEC),
	             SGE_PATRIMONIO_TRX.PLIEGO = (SELECT B.PLIEGO FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_PATRIMONIO_TRX.SEC_EJEC)
	        WHERE 
	            SGE_PATRIMONIO_TRX.ANO_EJE  = @P_ANO_EJE AND
	            SGE_PATRIMONIO_TRX.SEC_EJEC = @P_SEC_EJEC
	        
	    IF @@ERROR <>0  
	        SET @O_ERR_MSG ='Ocurrió error en la actualización de SGE_PATRIMONIO_TRX'
			RETURN - 1
	    END  
   
  	END
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_TECHO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_TECHO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_TECHO]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_TECHO]
(@PN_ANIO NUMERIC,@PN_EJEC NUMERIC, @PN_FASE NUMERIC, @PS_CENTRO VARCHAR(15) )
AS
--SP_HELP SIG_CUAdro_necesidad
--SP_HELP SIG_TECHO_PRESUPUESTO
DECLARE @ls_clasificador VARCHAR(20)
DECLARE @ls_flag_presup VARCHAR(1)
DECLARE @ls_centro_costo_presup VARCHAR(15)
DECLARE @ls_centro_costo VARCHAR(15)
DECLARE @ls_centro_padre VARCHAR(15)
DECLARE @ls_origen VARCHAR(1)
DECLARE @ls_codi_fuen VARCHAR(2)
DECLARE @ls_codi_fuen_impto VARCHAR(2)
DECLARE @ls_clas_gast VARCHAR(20)
DECLARE @ls_funcion VARCHAR(2)
DECLARE @ls_programa VARCHAR(3)
DECLARE @ld_Secu_func NUMERIC(4,0)
DECLARE @li_contador NUMERIC(10,0)
DECLARE @ld_valor_imp_progra NUMERIC(14,2)
DECLARE @li_secuencia NUMERIC(10,0)
DECLARE @ld_valor_progra NUMERIC(14,2)
DECLARE @ld_valor_aprob NUMERIC(14,2)
DECLARE @ld_mnto_impto NUMERIC(14,2)
DECLARE @ld_monto_progra NUMERIC(14,2)
DECLARE @ld_mnto_total NUMERIC(14,2)
DECLARE @ld_mnto_apro NUMERIC(14,2)
DECLARE @ld_mnto_asig NUMERIC(14,2)
DECLARE @ld_mnto_modif NUMERIC(14,2)
DECLARE @ls_categ_gasto VARCHAR(1)
DECLARE @ls_grupo_gasto VARCHAR(1)
DECLARE @ls_grupo VARCHAR(2)
DECLARE @ls_grupo1 VARCHAR(2)
DECLARE @Ls_flag_gen_esp VARCHAR(1)
DECLARE @ld_valor_imp_asignado NUMERIC(14,2)
DECLARE @ld_valor_asignado NUMERIC(14,2)
DECLARE @ld_monto_asignado NUMERIC(14,2)
DECLARE @ld_monto_aprob NUMERIC(14,2)
DECLARE @ld_valor_imp_aprob NUMERIC(14,2)

set nocount on

SELECT @li_contador = COUNT(*)
FROM SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND
SEC_EJEC = @PN_EJEC AND
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

IF ( @li_contador IS NULL) OR ( @li_contador <= 0) 
BEGIN
	GOTO ERROR
END 

SELECT @ls_flag_gen_esp = VALOR
FROM SIG_PARAMETRO_EJECUTORA_ANIO
WHERE ANO_EJE = @PN_ANIO AND
SEC_EJEC = @PN_EJEC AND
COD_MAESTRO = 'FLAG_TECHO_NIVEL'

BEGIN TRAN

select @li_secuencia = max(secuencia) 
from sig_techo_presupuesto 
where 
ano_eje= @PN_ANIO and
sec_ejec = @PN_EJEC;
	
if @li_secuencia  IS NULL 
BEGIN
	SELECT @li_secuencia = 0
END 

IF @PN_FASE = 1 OR @PN_FASE = 2 
--FASE 1 REQUERIDO, FASE 2 PROGRAMACION
BEGIN
	DECLARE c_c01 CURSOR FOR
	Select DISTINCT m.origen, m.fuente_financ, m.fuente_impto, m.clasificador, m.sec_func_prop
	From sig_cuadro_necesidad m
	Where
	m.ano_eje	= @PN_ANIO     and
	m.sec_ejec	= @PN_EJEC and 
	m.centro_costo  = @PS_CENTRO and
	m.fase_cuadro   = @PN_FASE
	 
	OPEN c_c01
	FETCH c_c01 INTO @ls_origen, @ls_codi_fuen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--REQUERIDO
		IF @PN_FASE = 1 
		BEGIN
			update sig_techo_presupuesto
			set    mnto_progra  =0 					 
			where  
			ano_eje  	  =@PN_ANIO and
			sec_ejec 	  =@PN_EJEC and
			origen   	  =@ls_origen and
			(fuente_financ=@ls_codi_fuen or
			 fuente_financ=@ls_codi_fuen_impto) and
			clasificador =@ls_clas_gast and
			sec_func_prop =@ld_secu_func and
			centro_costo = @PS_CENTRO and
			indicador = '0' and
			flag_meta_aprob = '0'
	
		END 
	
		--PROGRAMACION
		IF @PN_FASE = 2
		BEGIN
			update sig_techo_presupuesto
			set    mnto_asig  =0 					 
			where
			ano_eje  	  =@PN_ANIO and
			sec_ejec 	  =@PN_EJEC and
			origen   	   = @ls_origen and
			(fuente_financ = @ls_codi_fuen or
			fuente_financ  = @ls_codi_fuen_impto) and
			clasificador   = @ls_clas_gast and
			sec_func_prop  = @ld_secu_func and
			centro_costo   = @PS_CENTRO and
			indicador      = '0' and
			flag_meta_aprob = '0'
		END
	
		IF @@ERROR <> 0
		BEGIN
			CLOSE c_c01
			DEALLOCATE c_c01
			GOTO ERROR
		END
	
		FETCH c_c01 INTO @ls_origen, @ls_codi_fuen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func
	END
	CLOSE c_c01
	DEALLOCATE c_c01
	
	
	declare c_04 cursor for 
	select  distinct c.origen, c.fuente_impto, c.clasificador, c.sec_func_prop, m.funcion , m.programa
	from  sig_cuadro_necesidad c, sig_meta_propuesta m
	where
	c.ano_eje   = m.ano_eje and
	c.sec_ejec  = m.sec_ejec and
	c.sec_func_prop  = m.sec_func_prop and
	c.ano_eje      = @PN_ANIO  and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <>'0'		
	
	open c_04
	Fetch c_04 Into @ls_origen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--SELECT @ls_categ_gasto = SUBSTRING(@ls_clas_gast,1,1)
		--SELECT @ls_grupo_gasto = SUBSTRING(@ls_clas_gast,2,1)
		select @ls_categ_gasto = COD_NIVEL1,
		@ls_grupo_gasto = COD_NIVEL2
		FROM SIG_CLASIFICADOR_GASTO
		WHERE
		ANO_EJE = @PN_ANIO AND
		CLASIFICADOR = @ls_clas_gast
	
		select @li_contador  = count(*) 
		from sig_techo_presupuesto
		where 
		ano_eje       = @PN_ANIO and
		sec_ejec      = @PN_EJEC	and
		origen        = @ls_origen and
		fuente_financ = @ls_codi_fuen_impto and
		categ_gasto   = @ls_categ_gasto and
		grupo_gasto   = @ls_grupo_gasto and
		clasificador  = @ls_clas_gast and
		funcion       = @ls_funcion and
		programa      = @ls_programa and
		sec_func_prop = @ld_secu_func and
		centro_costo  = @PS_CENTRO and
		indicador     = '0' and
		flag_meta_aprob = '0'
	
		IF (@li_contador=0)  or (@li_contador IS NULL)
		BEGIN
			SELECT @li_contador=0
		END
	
		IF @PN_FASE = 1 
		--FASE 1 REQUERIDO
		BEGIN
			select @ld_valor_imp_progra = sum(c.valor_imp_progra)
			from  sig_cuadro_necesidad c
			where
			c.ano_eje      = @PN_ANIO and
			c.sec_ejec     = @PN_EJEC	and
			c.centro_costo = @PS_CENTRO and
			c.fase_cuadro  = @PN_FASE and
			c.origen       = @ls_origen and
			c.fuente_impto = @ls_codi_fuen_impto and
			c.categ_gasto  = @ls_categ_gasto and
			c.grupo_gasto  = @ls_grupo_gasto and
			c.clasificador = @ls_clas_gast and
			c.sec_func_prop = @ld_secu_func and
			c.tipo_impuesto <>'0'
			
			if (@ld_valor_imp_progra IS NULL) 
			BEGIN
				SELECT @ld_valor_imp_progra= 0.00
			END
			SELECT @ld_valor_imp_asignado= 0.00
		END 
	
		IF @PN_FASE = 2
		--FASE 2 PROGRAMADO
		BEGIN
			select @ld_valor_imp_asignado = sum(c.valor_imp_asignado)
			from  sig_cuadro_necesidad c
		   	where
			c.ano_eje      = @PN_ANIO and
			c.sec_ejec     = @PN_EJEC	 and
			c.centro_costo = @PS_CENTRO  and
			c.fase_cuadro  = @PN_FASE and
			c.origen = @ls_origen and
			c.fuente_impto = @ls_codi_fuen_impto and
			c.categ_gasto = @ls_categ_gasto and
			c.grupo_gasto = @ls_grupo_gasto and
			c.clasificador = @ls_clas_gast and
			c.sec_func_prop = @ld_secu_func and
			c.tipo_impuesto <>'0'		
		
			if (@ld_valor_imp_asignado IS NULL) 
			BEGIN
				SELECT @ld_valor_imp_asignado= 0.00
			END
			SELECT @ld_valor_imp_progra= 0.00
		END 
	
		IF @li_contador = 0 
		BEGIN
		  	SELECT @li_secuencia = @li_secuencia +1			
			  
			insert into sig_techo_presupuesto  
			(ano_eje     , sec_ejec      , origen         , fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , sec_func       , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  , mnto_asig	  , mnto_aprob		 , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     , porc_techo ,
			porc_asig    , sec_func_prop , flag_meta_aprob)
			values 
			(@PN_ANIO     , @PN_EJEC  , @ls_origen     , @ls_codi_fuen_impto,
			@li_secuencia,@ls_categ_gasto, @ls_grupo_gasto, @ls_clas_gast, 
			@ls_funcion  ,@ls_programa   , NULL       , @PS_CENTRO,
			0	 , 0		  , 0	 , 0      ,
			@ld_valor_imp_progra, @ld_valor_imp_asignado, 0	, 0 ,
			'0' , 0  , 0  , 0    ,
			0   , @ld_secu_func , '0')
		
			IF @@ERROR <> 0
			BEGIN
				CLOSE c_c01
				DEALLOCATE c_c01
				GOTO ERROR
			END
		end
		
		Fetch c_04 Into @ls_origen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
	
	END
	CLOSE c_04
	DEALLOCATE c_04
	
	
	declare c_040 cursor for 
	select  distinct c.origen, c.fuente_financ, c.clasificador, c.sec_func_prop, m.funcion , m.programa
	from  sig_cuadro_necesidad c, sig_meta_propuesta m
	where
	c.ano_eje   	  = m.ano_eje and
	c.sec_ejec       = m.sec_ejec and
	c.sec_func_prop  = m.sec_func_prop and
	c.ano_eje        = @PN_ANIO and
	c.sec_ejec       = @PN_EJEC and
	c.centro_costo   = @PS_CENTRO  and
	c.fase_cuadro    = @PN_FASE		

	open c_040
	Fetch c_040 Into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--SELECT @ls_categ_gasto = SUBSTRING(@ls_clas_gast,1,1)
		--SELECT @ls_grupo_gasto = SUBSTRING(@ls_clas_gast,2,1)
		select @ls_categ_gasto = COD_NIVEL1,
		@ls_grupo_gasto = COD_NIVEL2
		FROM SIG_CLASIFICADOR_GASTO
		WHERE
		ANO_EJE = @PN_ANIO AND
		CLASIFICADOR = @ls_clas_gast

		select @li_contador  = count(*) 
		from sig_techo_presupuesto
		where 
		ano_eje	  = @PN_ANIO and
		sec_ejec  = @PN_EJEC	and 
		origen    = @ls_origen and 
		fuente_financ = @ls_codi_fuen and
		categ_gasto   = @ls_categ_gasto and 
		grupo_gasto   = @ls_grupo_gasto and 
		clasificador  = @ls_clas_gast and
		funcion       = @ls_funcion and 
		programa      = @ls_programa and 
		sec_func_prop = @ld_secu_func and 
		centro_costo  = @PS_CENTRO and
		indicador     ='0' and
		flag_meta_aprob = '0'
	
		if (@li_contador=0) or (@li_contador is null) 
		begin
			SELECT @li_contador=0
		END

		IF @PN_FASE = 1 
		--FASE 1 REQUERIDO
		BEGIN		
			select @ld_valor_progra = sum(c.monto_progra) 
		   	from  sig_cuadro_necesidad c
			where  
			C.ano_eje	= @PN_ANIO and
			C.sec_ejec      = @PN_EJEC and 
			C.centro_costo  = @PS_CENTRO and
			c.fase_cuadro  = @PN_FASE and
			c.origen       = @ls_origen and
			c.categ_gasto  = @ls_categ_gasto and
			c.grupo_gasto  = @ls_grupo_gasto and
			c.fuente_financ = @ls_codi_fuen and
			c.clasificador  = @ls_clas_gast and
			c.sec_func_prop = @ld_secu_func
	
			if (@ld_valor_progra IS NULL) 
			BEGIN
				SELECT @ld_valor_progra= 0.00
			END
			SELECT @ld_valor_asignado= 0.00

		END 
		ELSE
		--FASE 2 PROGRAMADO
		BEGIN		
			select @ld_valor_asignado = sum(c.monto_asignado) 
		   	from  sig_cuadro_necesidad c
	   		where  
			C.ano_eje	= @PN_ANIO and
			C.sec_ejec      = @PN_EJEC and 
			C.centro_costo  = @PS_CENTRO and
			c.fase_cuadro  = @PN_FASE and
			c.origen        = @ls_origen and
			c.categ_gasto = @ls_categ_gasto and
			c.grupo_gasto = @ls_grupo_gasto and
			c.fuente_financ = @ls_codi_fuen and
			c.clasificador = @ls_clas_gast and
			c.sec_func_prop = @ld_secu_func

	
			if (@ld_valor_asignado IS NULL) 
			BEGIN
				SELECT @ld_valor_asignado= 0.00
			END
			SELECT @ld_valor_progra= 0.00

		END

		
		IF @li_contador = 0 
		BEGIN
			SELECT @li_secuencia=@li_secuencia +1			
			
			insert into sig_techo_presupuesto  
			(ano_eje     , sec_ejec      , origen         , fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , sec_func       , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  , mnto_asig	  , mnto_aprob	    , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     , porc_techo , 
			porc_asig    , sec_func_prop , flag_meta_aprob)
			values 
			(@PN_ANIO     , @PN_EJEC    , @ls_origen      , @ls_codi_fuen,
			@li_secuencia, @ls_categ_gasto , @ls_grupo_gasto , @ls_clas_gast, 
			@ls_funcion  , @ls_programa    , NULL        , @PS_CENTRO,
			0 , 0	, 0	, 0 ,
			@ld_valor_progra, @ld_valor_asignado, 0	 , 0 ,
			'0' , 0 , 0 , 0   ,
			0 , @ld_secu_func , '0')

			IF @@ERROR <> 0
			BEGIN
				CLOSE c_040
				DEALLOCATE c_040
				GOTO ERROR
			END
		END

		Fetch c_040 Into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa	

	END
	CLOSE c_040
	DEALLOCATE c_040

	--sin contrapartida - actualiza techo presupuestal
	declare c_050 cursor for 
	select  c.origen, c.fuente_financ, c.clasificador, c.sec_func_prop, sum(c.valor_imp_progra), sum(c.monto_progra), sum(c.valor_imp_asignado), sum(c.monto_asignado)
	from  sig_cuadro_necesidad c
	where 
	c.ano_eje        = @PN_ANIO and
	c.sec_ejec       = @PN_EJEC and
	c.centro_costo   = @PS_CENTRO  and
	c.fase_cuadro    = @PN_FASE		
	group by c.origen, c.fuente_financ, c.clasificador, c.sec_func_prop
	open c_050
	fetch c_050 into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_progra, @ld_monto_progra, @ld_valor_imp_asignado, @ld_monto_asignado

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@ld_monto_progra IS NULL) 
		BEGIN
			SELECT @ld_monto_progra = 0.00
		END
		IF (@ld_valor_imp_progra IS NULL) 
		BEGIN		
			SELECT @ld_valor_imp_progra = 0.00	
		END
		IF (@ld_valor_imp_asignado IS NULL) 
		BEGIN		
			SELECT @ld_valor_imp_asignado = 0.00	
		END
		IF (@ld_monto_asignado IS NULL) 
		BEGIN		
			SELECT @ld_monto_asignado = 0.00	
		END

		IF @PN_FASE = 1
		--FSE 1 REQUERIDO
		BEGIN	
			update sig_techo_presupuesto 
			set mnto_progra = @ld_monto_progra 
			where 
			ano_eje  	 = @PN_ANIO and
			sec_ejec 	 = @PN_EJEC and
			origen   	 = @ls_origen and
			fuente_financ = @ls_codi_fuen and
			clasificador  = @ls_clas_gast and
			sec_func_prop = @ld_secu_func and
			centro_costo  = @PS_CENTRO and
			indicador = '0' and
			flag_meta_aprob = '0'
		END
		ELSE
		--FASE 2 PROGRAMADO
		BEGIN	
			update sig_techo_presupuesto 
			set mnto_asig =@ld_monto_asignado
			where 
			ano_eje  	 = @PN_ANIO and
			sec_ejec 	 = @PN_EJEC and
			origen   	 = @ls_origen and
			fuente_financ = @ls_codi_fuen and
			clasificador = @ls_clas_gast and
			sec_func_prop  = @ld_secu_func and
			centro_costo = @PS_CENTRO and
			indicador      = '0' and
			flag_meta_aprob = '0'

		END

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_050
			DEALLOCATE c_050
			GOTO ERROR
		END

			
		fetch c_050 into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_progra, @ld_monto_progra, @ld_valor_imp_asignado, @ld_monto_asignado

	END
	CLOSE c_050
	DEALLOCATE c_050

	--cursor con contrapartida o con impuesto
	declare c_05 cursor for 
	select  c.origen, c.fuente_impto, c.clasificador, c.sec_func_prop, sum(c.valor_imp_progra), sum(c.monto_progra), sum(c.valor_imp_asignado), sum(c.monto_asignado)
  	from  sig_cuadro_necesidad c
 	where 
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <> '0'
	group by c.origen, c.fuente_impto, c.clasificador, c.sec_func_prop
	open c_05
	fetch c_05 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_progra, @ld_monto_progra, @ld_valor_imp_asignado, @ld_monto_asignado

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@ld_valor_imp_progra IS NULL) 
		BEGIN
			SELECT  @ld_valor_imp_progra = 0.00
		END
		IF (@ld_monto_progra IS NULL)
		BEGIN
			SELECT @ld_monto_progra = 0.00
		END
		IF (@ld_valor_imp_asignado IS NULL) 
		BEGIN
			SELECT  @ld_valor_imp_asignado = 0.00
		END
		IF (@ld_monto_asignado IS NULL) 
		BEGIN
			SELECT  @ld_monto_asignado = 0.00
		END

		IF @PN_FASE = 1
		--FSE 1 REQUERIDO
		BEGIN	
			update sig_techo_presupuesto 
			set mnto_progra = mnto_progra + @ld_valor_imp_progra 
			where 
			ano_eje  	 = @PN_ANIO and
			sec_ejec 	 = @PN_EJEC and
			origen   	 = @ls_origen and
			fuente_financ= @ls_codi_fuen and
			clasificador = @ls_clas_gast and
			sec_func_prop = @ld_secu_func and
			centro_costo  = @PS_CENTRO and 
			indicador     = '0' and
			flag_meta_aprob = '0'
		END 
		IF @PN_FASE = 2
		--FSE 2 PROGRAMADO
		BEGIN	
			update sig_techo_presupuesto set
			mnto_asig = mnto_asig + @ld_valor_imp_asignado
			where 
			ano_eje  	 = @PN_ANIO and
			sec_ejec 	 = @PN_EJEC and
			origen   	 = @ls_origen and
			fuente_financ= @ls_codi_fuen and
			clasificador = @ls_clas_gast and
			sec_func_prop    = @ld_secu_func and
			centro_costo = @PS_CENTRO and
			indicador      = '0' and
			flag_meta_aprob = '0'
		END 

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_05
			DEALLOCATE c_05
			GOTO ERROR
		END
		fetch c_05 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_progra, @ld_monto_progra, @ld_valor_imp_asignado, @ld_monto_asignado
	END
	CLOSE c_05
	DEALLOCATE c_05

	---SUBIR A OTROS NIVELES
END
ELSE
--FASE APROBADO
BEGIN
	Declare c_c01A Cursor For
	Select DISTINCT m.origen, m.fuente_financ , m.fuente_impto, m.clasificador, m.sec_func
	From sig_cuadro_necesidad m
	Where m.ano_eje	= @PN_ANIO    and
	m.sec_ejec	= @PN_EJEC and 
 	m.centro_costo   = @PS_CENTRO  and
	m.fase_cuadro    = @PN_FASE and
	(m.fuente_financ is not  null) and
	(m.clasificador is not null) and
	(m.sec_func is not null)
	
	Open c_c01A
	Fetch c_c01A Into @ls_origen, @ls_codi_fuen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func
	WHILE @@FETCH_STATUS = 0
	BEGIN
		update sig_techo_presupuesto
		set    mnto_aprob  =0 					 
		where  ano_eje   = @PN_ANIO and
			sec_ejec 	  = @PN_EJEC and
			origen   	  = @ls_origen and
			(fuente_financ = @ls_codi_fuen or
			fuente_financ = @ls_codi_fuen_impto) and
			clasificador = @ls_clas_gast and
			sec_func     = @ld_secu_func and
			centro_costo = @PS_CENTRO and
			indicador = '0' and
			flag_meta_aprob = '1'
	
		IF @@ERROR <> 0
		BEGIN
			CLOSE c_c01A
			DEALLOCATE c_c01A
			GOTO ERROR
		END
	

		Fetch c_c01A Into @ls_origen, @ls_codi_fuen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func
	END
	CLOSE c_c01A
	DEALLOCATE c_c01A


	declare c_04A cursor for 
	select  distinct c.origen, c.fuente_impto, c.clasificador, c.sec_func, m.funcion , m.programa
	from  sig_cuadro_necesidad c, meta m
	where  c.ano_eje   = m.ano_eje and
	c.sec_ejec  = m.sec_ejec and
	c.sec_func  = m.sec_func and
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <>'0' and
	(c.fuente_impto is not null) and
	(c.clasificador is not null) and
	(c.sec_func is not null)
	
	open c_04A

	Fetch c_04A Into @ls_origen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--SELECT @ls_categ_gasto = SUBSTRING(@ls_clas_gast,1,1)
		--SELECT @ls_grupo_gasto = SUBSTRING(@ls_clas_gast,2,1)
		select @ls_categ_gasto = COD_NIVEL1,
		@ls_grupo_gasto = COD_NIVEL2
		FROM SIG_CLASIFICADOR_GASTO
		WHERE
		ANO_EJE = @PN_ANIO AND
		CLASIFICADOR = @ls_clas_gast
	
		select @li_contador  = count(*) 
		from sig_techo_presupuesto
		where 
		ano_eje  = @PN_ANIO and
		sec_ejec = @PN_EJEC	and
		origen = @ls_origen and
		fuente_financ = @ls_codi_fuen_impto and
		categ_gasto = @ls_categ_gasto and
		grupo_gasto = @ls_grupo_gasto and
		clasificador = @ls_clas_gast and
		funcion     = @ls_funcion and
		programa= @ls_programa and
		sec_func = @ld_secu_func and
		centro_costo= @PS_CENTRO and
		indicador     = '0' and
		flag_meta_aprob = '1'

		if (@li_contador=0) or (@li_contador IS NULL)
		BEGIN
			SELECT @li_contador=0 
		END

		select @ld_valor_imp_aprob = sum(c.valor_imp_aprob) 
		from  sig_cuadro_necesidad c
		where  
		c.ano_eje      = @PN_ANIO and
		c.sec_ejec     = @PN_EJEC and
		c.centro_costo = @PS_CENTRO  and
		c.fase_cuadro  = @PN_FASE and
		c.origen = @ls_origen and
		c.fuente_impto = @ls_codi_fuen_impto and
		c.categ_gasto = @ls_categ_gasto and
		c.grupo_gasto = @ls_grupo_gasto and
		c.clasificador = @ls_clas_gast and
		c.sec_func = @ld_secu_func and
		c.tipo_impuesto <>'0'		
		
		if (@ld_valor_imp_aprob IS NULL) 
		BEGIN
			SELECT @ld_valor_imp_aprob= 0.00
		END 
	
		if @li_contador=0  
		BEGIN
		  	SELECT @li_secuencia = @li_secuencia +1
			
			insert into sig_techo_presupuesto  
			(ano_eje     , sec_ejec      ,  origen        ,fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      ,	sec_func     , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  ,mnto_asig		  , mnto_aprob		 , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     ,porc_techo ,
			porc_asig, flag_meta_aprob)
			values 
			(@PN_ANIO    , @PN_EJEC  , @ls_origen     , @ls_codi_fuen_impto,
			@li_secuencia, @ls_categ_gasto, @ls_grupo_gasto, @ls_clas_gast, 
			@ls_funcion  , @ls_programa   , @ld_secu_func   ,@PS_CENTRO,
			0 ,0  , 0 ,0 ,
			0  , 0	,@ld_valor_imp_aprob , 0,
			'0' , 0	  , 0   ,0  ,
			0, '1')

			IF @@ERROR <> 0
			BEGIN
				CLOSE c_04A
				DEALLOCATE c_04A
				GOTO ERROR
			END
		END

		Fetch c_04A Into @ls_origen, @ls_codi_fuen_impto, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
	END
	CLOSE c_04A
	DEALLOCATE c_04A

	--cursor para sin contrapartida
	declare c_040A cursor for 
	select  distinct c.origen, c.fuente_financ, c.clasificador, c.sec_func, m.funcion , m.programa
  	from  sig_cuadro_necesidad c, meta m
 	where  
	c.ano_eje   = m.ano_eje and
	c.sec_ejec  = m.sec_ejec and
	c.sec_func  = m.sec_func and
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	(c.fuente_financ is not null) and
	(c.clasificador is not null) and
	(c.sec_func is not null)		

	open c_040A
	Fetch c_040A Into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--SELECT @ls_categ_gasto = SUBSTRING(@ls_clas_gast,1,1)
		--SELECT @ls_grupo_gasto = SUBSTRING(@ls_clas_gast,2,1)
		select @ls_categ_gasto = COD_NIVEL1,
		@ls_grupo_gasto = COD_NIVEL2
		FROM SIG_CLASIFICADOR_GASTO
		WHERE
		ANO_EJE = @PN_ANIO AND
		CLASIFICADOR = @ls_clas_gast
	
		select @li_contador  = count(*) 
		from sig_techo_presupuesto
		where 
		ano_eje  = @PN_ANIO and
		sec_ejec = @PN_EJEC	and
		origen = @ls_origen and
		fuente_financ = @ls_codi_fuen and
	   	categ_gasto = @ls_categ_gasto and 
		grupo_gasto = @ls_grupo_gasto and 
		clasificador = @ls_clas_gast and
		funcion     = @ls_funcion and
		programa= @ls_programa and 
		sec_func = @ld_secu_func and 
		centro_costo= @PS_CENTRO and
		indicador     = '0' and
		flag_meta_aprob = '1'
			 
		if (@li_contador=0) or (@li_contador IS NULL)
		BEGIN
			SELECT @li_contador=0
		END

		select @ld_valor_aprob = sum(c.monto_aprob) 
	   	from  sig_cuadro_necesidad c
	   	where  
		c.ano_eje      = @PN_ANIO and
		c.sec_ejec     = @PN_EJEC and
		c.centro_costo = @PS_CENTRO  and
		c.fase_cuadro  = @PN_FASE and
		c.origen        = @ls_origen and
		c.categ_gasto = @ls_categ_gasto and
		c.grupo_gasto = @ls_grupo_gasto and
		c.fuente_financ = @ls_codi_fuen and
		c.clasificador = @ls_clas_gast and
		c.sec_func = @ld_secu_func

		IF @Li_contador = 0 
		BEGIN
			SELECT @li_secuencia = @li_secuencia +1			
			  
			insert into sig_techo_presupuesto  
			(ano_eje     , sec_ejec      ,  origen        ,fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      ,	sec_func     , centro_costo, 
			ppto_progra  , ppto_aprob	  , ppto_asignado	 ,	ppto_modif,
			mnto_progra  ,mnto_asig		  , mnto_aprob		 , mnto_modif,
			indicador	 , paac_inicial  , paac_modif     ,porc_techo ,
			porc_asig, flag_meta_aprob)
			values 
			(@PN_ANIO    , @PN_EJEC  , @ls_origen     , @ls_codi_fuen,
			@li_secuencia,@ls_categ_gasto, @ls_grupo_gasto,@ls_clas_gast, 
			@ls_funcion  ,@ls_programa   , @ld_secu_func   , @PS_CENTRO,
			0 ,0	, 0 ,0   ,
			0, 0  , @ld_valor_aprob	 ,0   ,
			'0' , 0  , 0 ,0  ,
			0, '1')

			IF @@ERROR <> 0
			BEGIN
				CLOSE c_040A
				DEALLOCATE c_040A
				GOTO ERROR
			END
		END
		
		Fetch c_040A Into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ls_funcion, @ls_programa
		
	END
	CLOSE c_040A
	DEALLOCATE c_040A

	--sin contrapartida
	declare c_050A cursor for 
	select  c.origen, c.fuente_financ, c.clasificador, c.sec_func, sum(c.valor_imp_aprob), sum(c.monto_aprob)
  	from  sig_cuadro_necesidad c
 	where 
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	(c.fuente_financ is not null ) and
	(c.clasificador is not null) and
	(c.sec_func is not null)
	group by c.origen, c.fuente_financ, c.clasificador, c.sec_func
	open c_050A
	fetch c_050A 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob

	WHILE @@FETCH_STATUS = 0
	BEGIN
		if (@ld_monto_aprob IS NULL) 
		BEGIN
			SELECT @ld_monto_aprob = 0.00
		END 
		if (@ld_valor_imp_aprob IS NULL) 
		BEGIN
			SELECT @ld_valor_imp_aprob = 0.00	
		END 

		update sig_techo_presupuesto
		set mnto_aprob = @ld_monto_aprob 
		where 
		ano_eje  	 =@PN_ANIO and
		sec_ejec 	 =@PN_EJEC and
		origen   	 = @ls_origen and
		fuente_financ= @ls_codi_fuen and
		clasificador = @ls_clas_gast and
		sec_func  = @ld_secu_func and
		centro_costo = @PS_CENTRO and
		indicador = '0' and
		flag_meta_aprob = '1'

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_050A
			DEALLOCATE c_050A
			GOTO ERROR
		END

		fetch c_050A 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob
	END
	CLOSE c_050A
	DEALLOCATE c_050A

	--cursor con contrapartida o con impuesto
	declare c_05A cursor for 
	select  c.origen, c.fuente_impto, c.clasificador, c.sec_func, sum(c.valor_imp_aprob), sum(c.monto_aprob)
  	from  sig_cuadro_necesidad c
 	where 
	c.ano_eje      = @PN_ANIO and
	c.sec_ejec     = @PN_EJEC and
	c.centro_costo = @PS_CENTRO  and
	c.fase_cuadro  = @PN_FASE and
	c.tipo_impuesto <>'0' and
	( c.fuente_impto is not null) and
	( c.clasificador is not null ) and
	( c.sec_func is not null )
	group by c.origen, c.fuente_impto, c.clasificador, c.sec_func
	open c_05A

	fetch c_05A 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob

	WHILE @@FETCH_STATUS = 0
	BEGIN
		if (@ld_valor_imp_aprob IS NULL) 
		BEGIN
			SELECT @Ld_valor_imp_aprob = 0.00
		END 
		if (@ld_monto_aprob IS NULL) 
		BEGIN
			SELECT @ld_monto_aprob = 0.00
		END
	
		update sig_techo_presupuesto 
		set mnto_aprob = mnto_aprob + @ld_valor_imp_aprob 
		where 
		ano_eje  	 = @PN_ANIO and
		sec_ejec 	 = @PN_EJEC and
		origen   	 = @ls_origen and
		fuente_financ = @ls_codi_fuen and
		clasificador = @ls_clas_gast and
		sec_func    = @ld_secu_func and
		centro_costo = @PS_CENTRO and
		indicador     = '0' and
		flag_meta_aprob = '1'

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_05A
			DEALLOCATE c_05A
			GOTO ERROR
		END
					
		fetch c_05A 	into @ls_origen, @ls_codi_fuen, @ls_clas_gast, @ld_secu_func, @ld_valor_imp_aprob, @ld_monto_aprob

	END
	CLOSE c_05A
	DEALLOCATE c_05A

	--SUBIR A TODOS LOS NIVELES
END

--//actualiza centro de costo de presupuesto
declare c_0b cursor for
select distinct centro_costo
from sig_techo_presupuesto
where 
ano_eje  	 = @PN_ANIO and
sec_ejec 	 = @PN_EJEC and
indicador     = '0'

open c_0b
fetch c_0b into @ls_centro_costo

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @ls_flag_presup = 'N'
	WHILE @ls_flag_presup = 'N'
	BEGIN
		select @ls_centro_padre = CENTRO_PADRE,
		@ls_flag_presup = FLAG_PRESUPUESTO
		from SIG_CENTRO_COSTO
		where 
		ano_eje = @PN_ANIO and
		sec_ejec = @PN_EJEC and
		centro_costo = @ls_centro_costo

		if (@ls_flag_presup IS NULL)
		BEGIN
			SELECT @Ls_flag_presup = 'N'
		END
		
		IF @ls_flag_presup <> 'S' 
		BEGIN
			IF  (@ls_centro_padre IS NULL) or (@ls_centro_padre = '') 
			BEGIN
				SELECT @Ls_flag_presup = 'S'
				SELECT @ls_centro_costo_presup = ''
			END			   	
			ELSE
			BEGIN
				SELECT @ls_centro_costo = @ls_centro_padre
				SELECT @Ls_flag_presup = 'N'
			END
		END
		ELSE
		BEGIN
			SELECT @Ls_flag_presup = 'S'
			SELECT @ls_centro_costo_presup = @ls_centro_costo
		END
	END

	update  sig_techo_presupuesto
	set centro_costo_presup = @ls_centro_costo_presup
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	centro_costo = @ls_centro_costo and 
	indicador = '0' and
	(centro_costo_presup IS NULL )

	IF @@ERROR <> 0
	BEGIN
		CLOSE c_0b
		DEALLOCATE c_0b
		GOTO ERROR
	END
		
	fetch c_0b into @ls_centro_costo
END
CLOSE c_0b
DEALLOCATE c_0b


IF @PN_FASE = 1 OR @PN_FASE = 2 
BEGIN
	--//actualiza primer nivel : fuente financ
	declare c_1b cursor for
	select distinct origen, fuente_financ
	from sig_techo_presupuesto
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     = '0' and
	flag_meta_aprob = '0'
	open c_1b
	fetch c_1b into @ls_origen, @ls_codi_fuen
	WHILE @@FETCH_STATUS = 0
	BEGIN
		select @li_contador  = count(*) 
		from sig_techo_presupuesto
		where 
		ano_eje = @PN_ANIO and
		sec_ejec = @PN_EJEC AND
		origen    = @ls_origen and 
		fuente_financ = @ls_codi_fuen and
		indicador     ='1' and
		flag_meta_aprob = '0'
		
		IF (@li_contador=0) or (@li_contador IS NULL)
		BEGIN
			SELECT @li_contador=0
		END
			
		IF @li_contador = 0 
		BEGIN
			select @ld_valor_progra = sum(mnto_progra) 
			from sig_techo_presupuesto
			where 
			ano_eje = @PN_ANIO and
			sec_ejec = @PN_EJEC AND
			origen    = @ls_origen and 
			fuente_financ = @ls_codi_fuen and
			indicador     ='0' and
			flag_meta_aprob = '0'
	
			IF (@ld_valor_progra IS NULL) 
			BEGIN
				SELECT @ld_valor_progra= 0.00
			END
		
			SELECT @li_secuencia = @li_secuencia +1			
	
			insert into sig_techo_presupuesto  
			(ano_eje     , sec_ejec      , origen         , fuente_financ,
			secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
			funcion      , programa      , sec_func       , centro_costo, 
			ppto_progra  , ppto_aprob  , ppto_asignado ,	ppto_modif,
			mnto_progra  , mnto_asig  , mnto_aprob	    , mnto_modif,
			indicador   , paac_inicial  , paac_modif     , porc_techo , 
			porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup)
			values 
			(@PN_ANIO     , @PN_EJEC , @ls_origen , @ls_codi_fuen,
			@li_secuencia, NULL, NULL , NULL,
 			NULL ,NULL , NULL , NULL,
			0 , 0 , 0 , 0 ,
			@ld_valor_progra,0, 0, 0 ,
			'1' ,0, 0 , 0 ,
			0 , NULL , '0' , NULL)

			IF @@ERROR <> 0
			BEGIN
				CLOSE c_1b
				DEALLOCATE c_1b
				GOTO ERROR
			END
		END
		fetch c_1b into @ls_origen, @ls_codi_fuen		
	
	END
	CLOSE c_1b
	DEALLOCATE c_1b

	declare c_2b cursor for
	select origen, fuente_financ, sum(mnto_progra), SUM(mnto_asig)
	from sig_techo_presupuesto
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     = '0' and
	flag_meta_aprob = '0'
	group by origen, fuente_financ
	open c_2b
	fetch c_2b into @ls_origen, @ls_codi_fuen, @ld_valor_progra, @ld_valor_asignado
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@ld_valor_progra IS NULL ) 
		BEGIN
			SELECT @ld_valor_progra = 0.00
		END
		IF (@ld_valor_asignado IS NULL ) 
		BEGIN
			SELECT @ld_valor_asignado = 0.00
		END

		IF @PN_FASE = 1
