	funcion is not null and
	programa is not null
	group by origen, fuente_financ, categ_gasto, grupo_gasto, funcion, programa, sec_func, centro_costo_presup, clasificador
	open c_8bA
	fetch c_8bA into @ls_origen, @ls_codi_fuen, @ls_categ_gasto, @ls_grupo_gasto, @ls_funcion,@ls_programa, @ld_secu_func, @ls_centro_costo_presup, @ls_clasificador, @ld_valor_progra
	WHILE @@FETCH_STATUS = 0
	BEGIN
		update sig_techo_presupuesto
		set mnto_aprob = @ld_valor_progra
		where 
		ano_eje = @PN_ANIO and
		sec_ejec = @PN_EJEC AND
		origen    = @ls_origen and 
		fuente_financ = @ls_codi_fuen and
	  	categ_gasto   = @ls_categ_gasto and 
		grupo_gasto   = @ls_grupo_gasto and 
		funcion       = @ls_funcion and 
		programa      = @ls_programa and 
		sec_func 	  = @ld_secu_func and 
		centro_costo_presup = @ls_centro_costo_presup and
		clasificador = @ls_clasificador and
		indicador     ='5' and
		flag_meta_aprob = '1'

		IF @@ERROR <> 0
		BEGIN
			CLOSE c_8bA
			DEALLOCATE c_8bA
			GOTO ERROR
		END

		fetch c_8bA into @ls_origen, @ls_codi_fuen, @ls_categ_gasto, @ls_grupo_gasto, @ls_funcion,@ls_programa, @ld_secu_func, @ls_centro_costo_presup, @ls_clasificador, @ld_valor_progra
	END
	CLOSE c_8bA
	DEALLOCATE c_8bA

END


COMMIT TRAN
set nocount off
RETURN 1

ERROR:
   ROLLBACK TRAN
   set nocount off
   RETURN -1;

-- /
GO


