-- ----------------------------
-- procedure structure for SP_PROCESO_VALOR_REFERENCIAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESO_VALOR_REFERENCIAL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESO_VALOR_REFERENCIAL]
GO

CREATE PROCEDURE [dbo].[SP_PROCESO_VALOR_REFERENCIAL](
 @vi_anio numeric(4),	
 @vi_ejecutora numeric(6),	
 @vs_tipo_con varchar(2), 
 @vi_nro_con numeric(5),
 @vs_tip_gen varchar(2),
 @vi_nro_estudio numeric(6)			
 )
as

begin

  declare @vi_valor_min   numeric(16,6)
  declare @vi_precio_min  numeric(16,6)
  declare @vi_valor_tot   numeric(16,6)
  declare @vs_codigo	  varchar(12)
  declare @vs_moneda	  varchar(6)
  declare @vs_nom_item	  varchar(150)
  declare @vi_cantidad    numeric(20,6)
  declare @vs_nom_prov	  varchar(100)
  declare @vi_valor_prov  numeric(16,2)
  declare @vi_prec_unit   numeric(16,6)
  declare @vs_tipo_bien   char(1)
  declare @vs_abreviatura varchar(100)
  declare @vd_fec_max     datetime
  declare @vi_precio_his  numeric(16,6)
  declare @vi_valor_his   numeric(16,6)
  declare @ls_tipo_bien   char(1)
  declare @li_sec_con     numeric(2)
  declare @li_sec_res     numeric(5)
  declare @vs_objeto      char(2)
  DECLARE @vs_criterio  varchar(20)


  create table #VALOR_REF( ANO_EJE         numeric(4)    null,
			   SEC_EJEC        numeric(6)    null,
			   TIPO_CONSOLID   varchar(1)    null, 
			   NRO_CONSOLID    numeric(5)    null, 	
			   TIPO_GENERACION varchar(1)    null, 
			   TIPO_BIEN       varchar(1)    null,
			   SEC_CONSOLID    numeric(2)    null, 					 	
			   SEC_RESUMEN     numeric(5)    null, 					 	
		  	   CODIGO_ITEM     varchar(12)   null, 
			   NOMBRE_ITEM     varchar(150)  null, 
			   CANTIDAD        numeric(20,6) null,
			   NOMBRE_PROV     varchar(100)  null, 		
			   VALOR_PROV      numeric(16,6) null,
			   SECUENCIA       int identity,
			   PRECIO_UNIT     numeric(16,6) null,
			   FLAG_DATA	   numeric(2)    null,
			   ABREVIATURA     varchar(15)   NULL,
			   TIPO_CRITERIO   VARCHAR(20) NULL,
			    )

 insert #VALOR_REF
             (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
              SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
              VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, TIPO_CRITERIO)
  select C.ANO_EJE, C.SEC_EJEC, C.TIPO_CONSOLID, C.NRO_CONSOLID, C.TIPO_GENERACION, C.TIPO_BIEN,
             1 as SEC_CONSOLID, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM, sum(C.CANTIDAD) as cantidad,
             CASE B.ESTADO WHEN 'T' THEN  '- COMPRAS EXT. - '+B.NOMBRE_PROV WHEN 'P' THEN B.NOMBRE_PROV END, 
             CASE C.TIPO_BIEN WHEN 'B' THEN ROUND(D.PRECIO_PROV,6) WHEN 'S' THEN D.VALOR_PROV END , 
             C.PRECIO_UNIT, 
             CASE B.ESTADO WHEN 'T' THEN 2 WHEN 'P' THEN 3 END ,
             F.ABREVIATURA  ,
             (case C.SECUENCIA WHEN 1 THEN 'Menor Valor' WHEN 2 THEN 'Promedio' WHEN 4 THEN 'F. CVR' WHEN 3 THEN 'Otro' WHEN 5 THEN 'Mixto' ELSE '' END) TIPO_CRITERIO             
        from CATALOGO_BIEN_SERV A,   
	     SIG_CONTRATISTAS B,   
	     SIG_PAAC_ITEM C,   
	     SIG_SOLICITUD_COTIZACION_ITEM D,   
	     SIG_SOLICITUD_COTIZACION E,
	     UNIDAD_MEDIDA F	
       where ( C.SEC_EJEC        = A.SEC_EJEC        ) and  
	     ( C.TIPO_BIEN       = A.TIPO_BIEN       ) and  
	     ( C.GRUPO_BIEN      = A.GRUPO_BIEN      ) and  
	     ( C.CLASE_BIEN      = A.CLASE_BIEN      ) and  
	     ( C.FAMILIA_BIEN    = A.FAMILIA_BIEN    ) and  
	     ( C.ITEM_BIEN       = A.ITEM_BIEN       ) and  
	     ( D.ANO_EJE         = C.ANO_EJE         ) and  
	     ( D.SEC_EJEC        = C.SEC_EJEC        ) and  
	     ( D.TIPO_CONSOLID   = C.TIPO_CONSOLID   ) and  
	     ( D.NRO_CONSOLID    = C.NRO_CONSOLID    ) and  
	     ( D.TIPO_GENERACION = C.TIPO_GENERACION ) and  
	     ( D.TIPO_BIEN       = C.TIPO_BIEN       ) and  
	     ( D.SEC_RESUMEN     = C.SEC_RESUMEN     ) and  
	     ( D.ANO_EJE         = E.ANO_EJE         ) and  
	     ( D.SEC_EJEC        = E.SEC_EJEC        ) and  
	     ( D.TIPO_CONSOLID   = E.TIPO_CONSOLID   ) and  
	     ( D.NRO_CONSOLID    = E.NRO_CONSOLID    ) and  
	     ( D.TIPO_GENERACION = E.TIPO_GENERACION ) and  
	     ( D.NRO_SOLICITUD   = E.NRO_SOLICITUD   ) and  
	     ( C.UNIDAD_MEDIDA   = F.UNIDAD_MEDIDA   ) and	
	     ( E.PROVEEDOR 	 = B.PROVEEDOR       ) and  
	     ( D.ANO_EJE 	 = @vi_anio         ) and  
	     ( D.SEC_EJEC 	 = @vi_ejecutora     ) and
	     ( D.TIPO_CONSOLID   = @vs_tipo_con      ) and 
	     ( D.NRO_CONSOLID    = @vi_nro_con        ) and 
	     ( D.TIPO_GENERACION = @vs_tip_gen       ) and
	     ( B.ESTADO 	 in ('T','X','P')               ) and
	     ( D.FLAG_PARTICIPA  = '1'               ) and
	     ( D.VALOR_PROV <> 0.00 )
       GROUP BY C.ANO_EJE, C.SEC_EJEC, C.TIPO_CONSOLID, C.NRO_CONSOLID, C.TIPO_GENERACION,
                C.TIPO_BIEN, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM, B.NOMBRE_PROV  ,
                ROUND(D.PRECIO_PROV,6),D.VALOR_PROV, C.PRECIO_UNIT, F.ABREVIATURA, B.ESTADO, C.SECUENCIA

UNION
  select C.ANO_EJE, C.SEC_EJEC, C.TIPO_CONSOLID, C.NRO_CONSOLID, C.TIPO_GENERACION, C.TIPO_BIEN,
             1 as SEC_CONSOLID, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM, sum(C.CANTIDAD) as cantidad,
             G.nombre, 
             CASE C.TIPO_BIEN WHEN 'B' THEN ROUND(D.PRECIO_PROV,6) WHEN 'S' THEN D.VALOR_PROV END , 
             C.PRECIO_UNIT, 
             (convert(int, g.cod_detalle) + 3) ,
             F.ABREVIATURA , 
             (case C.SECUENCIA WHEN 1 THEN 'Menor Valor' WHEN 2 THEN 'Promedio' WHEN 4 THEN 'F. CVR' WHEN 3 THEN 'Otro' WHEN 5 THEN 'Mixto' ELSE '' END) TIPO_CRITERIO                    
        from CATALOGO_BIEN_SERV A,
	     SIG_PAAC_ITEM C,   
	     SIG_SOLICITUD_COTIZACION_ITEM D,   
	     SIG_SOLICITUD_COTIZACION E,
	     UNIDAD_MEDIDA F	,
	     sig_maestro_det_cadena G 
       where ( C.SEC_EJEC        = A.SEC_EJEC        ) and  
	     ( C.TIPO_BIEN       = A.TIPO_BIEN       ) and  
	     ( C.GRUPO_BIEN      = A.GRUPO_BIEN      ) and  
	     ( C.CLASE_BIEN      = A.CLASE_BIEN      ) and  
	     ( C.FAMILIA_BIEN    = A.FAMILIA_BIEN    ) and  
	     ( C.ITEM_BIEN       = A.ITEM_BIEN       ) and  
	     ( D.ANO_EJE         = C.ANO_EJE         ) and  
	     ( D.SEC_EJEC        = C.SEC_EJEC        ) and  
	     ( D.TIPO_CONSOLID   = C.TIPO_CONSOLID   ) and  
	     ( D.NRO_CONSOLID    = C.NRO_CONSOLID    ) and  
	     ( D.TIPO_GENERACION = C.TIPO_GENERACION ) and  
	     ( D.TIPO_BIEN       = C.TIPO_BIEN       ) and  
	     ( D.SEC_RESUMEN     = C.SEC_RESUMEN     ) and  
	     ( D.ANO_EJE         = E.ANO_EJE         ) and  
	     ( D.SEC_EJEC        = E.SEC_EJEC        ) and  
	     ( D.TIPO_CONSOLID   = E.TIPO_CONSOLID   ) and  
	     ( D.NRO_CONSOLID    = E.NRO_CONSOLID    ) and  
	     ( D.TIPO_GENERACION = E.TIPO_GENERACION ) and  
	     ( D.NRO_SOLICITUD   = E.NRO_SOLICITUD   ) and  
	     ( C.UNIDAD_MEDIDA   = F.UNIDAD_MEDIDA   ) and	
	      e.COD_FUENTE = g.cod_detalle AND
	      g.cod_maestro = 'TIPO_FUENTE' AND
	      G.estado = 'A' AND
	     ( D.ANO_EJE 	 = @vi_anio           ) and  
	     ( D.SEC_EJEC 	 = @vi_ejecutora     ) and
	     ( D.TIPO_CONSOLID   = @vs_tipo_con      ) and 
	     ( D.NRO_CONSOLID    = @vi_nro_con        ) and 
	     ( D.TIPO_GENERACION = @vs_tip_gen       ) and
	     ( D.FLAG_PARTICIPA  = '1'               ) AND
	     ( D.VALOR_PROV <> 0.00 )
       GROUP BY C.ANO_EJE, C.SEC_EJEC, C.TIPO_CONSOLID, C.NRO_CONSOLID, C.TIPO_GENERACION,
                C.TIPO_BIEN, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM, g.NOMBRE  ,
                ROUND(D.PRECIO_PROV,6),D.VALOR_PROV, C.PRECIO_UNIT, F.ABREVIATURA, g.cod_detalle, C.SECUENCIA
                
declare lista_item cursor for
 select C.TIPO_BIEN, 1 as SEC_CONSOLID, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM,
        sum(C.CANTIDAD) as CANTIDAD, C.PRECIO_UNIT, C.TIPO_BIEN, D.ABREVIATURA, C.MONEDA	, 
       (case C.SECUENCIA WHEN 1 THEN 'Menor Valor' WHEN 2 THEN 'Promedio' WHEN 4 THEN 'F. CVR' WHEN 3 THEN 'Otro' WHEN 5 THEN 'Mixto' ELSE '' END) 		
  from CATALOGO_BIEN_SERV A,
       SIG_PAAC_ITEM C,
       UNIDAD_MEDIDA D
 where ( C.SEC_EJEC 	   = A.SEC_EJEC     ) and
       ( C.TIPO_BIEN 	   = A.TIPO_BIEN    ) and
       ( C.GRUPO_BIEN      = A.GRUPO_BIEN   ) and
       ( C.CLASE_BIEN      = A.CLASE_BIEN   ) and
       ( C.FAMILIA_BIEN    = A.FAMILIA_BIEN ) and
       ( C.ITEM_BIEN 	   = A.ITEM_BIEN    ) and
       ( C.UNIDAD_MEDIDA   = D.UNIDAD_MEDIDA) and
       ( C.ANO_EJE 	   = @vi_anio       ) and
       ( C.SEC_EJEC 	   = @vi_ejecutora  ) and
       ( C.TIPO_CONSOLID   = @vs_tipo_con   ) and
       ( C.NRO_CONSOLID    = @vi_nro_con    ) and
       ( C.TIPO_GENERACION = @vs_tip_gen    )
 GROUP BY C.TIPO_BIEN, C.SEC_RESUMEN, A.CODIGO_ITEM, A.NOMBRE_ITEM, C.PRECIO_UNIT,	
	  C.TIPO_BIEN, D.ABREVIATURA, C.MONEDA,  C.SECUENCIA			

 open lista_item

 fetch next from lista_item
  into @ls_tipo_bien, @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, @vi_prec_unit, @vs_tipo_bien, @vs_abreviatura, @vs_moneda, @vs_criterio
 while @@fetch_status = 0 
    begin

      --Fecha 	
      select top 1 @vd_fec_max = sig_orden_adquisicion.fecha_orden
        from sig_orden_adquisicion, 
	     sig_orden_item
       where ( sig_orden_adquisicion.ano_eje   = sig_orden_item.ano_eje   ) and
	     ( sig_orden_adquisicion.sec_ejec  = sig_orden_item.sec_ejec  ) and
  	     ( sig_orden_adquisicion.nro_orden = sig_orden_item.nro_orden ) and
	     ( sig_orden_adquisicion.tipo_bien = sig_orden_item.tipo_bien ) and
	     ( sig_orden_adquisicion.tipo_ppto = sig_orden_item.tipo_ppto ) and
	     ( sig_orden_item.tipo_bien    = @vs_tipo_bien) and
	     ( sig_orden_item.grupo_bien   = substring(@vs_codigo,1,2)) and
	     ( sig_orden_item.clase_bien   = substring(@vs_codigo,3,2)) and
	     ( sig_orden_item.familia_bien = substring(@vs_codigo,5,4)) and
	     ( sig_orden_item.item_bien    = substring(@vs_codigo,9,4))
       order by sig_orden_adquisicion.fecha_orden desc
      
      select @vi_precio_his = sig_orden_item.prec_unit_moneda,
	     @vi_valor_his = sig_orden_item.prec_tot_moneda
	from sig_orden_adquisicion, 
	     sig_orden_item
       where ( sig_orden_adquisicion.ano_eje   = sig_orden_item.ano_eje   ) and
	     ( sig_orden_adquisicion.sec_ejec  = sig_orden_item.sec_ejec  ) and
	     ( sig_orden_adquisicion.nro_orden = sig_orden_item.nro_orden ) and
	     ( sig_orden_adquisicion.tipo_bien = sig_orden_item.tipo_bien ) and
	     ( sig_orden_adquisicion.tipo_ppto = sig_orden_item.tipo_ppto ) and
	     ( sig_orden_item.tipo_bien    = @vs_tipo_bien ) and
	     ( sig_orden_item.grupo_bien   = substring(@vs_codigo,1,2)) and
	     ( sig_orden_item.clase_bien   = substring(@vs_codigo,3,2)) and
	     ( sig_orden_item.familia_bien = substring(@vs_codigo,5,4)) and
	     ( sig_orden_item.item_bien    = substring(@vs_codigo,9,4)) and
	     ( sig_orden_adquisicion.fecha_orden = @vd_fec_max) 
       
      select @vi_valor_min = isnull(A.MONTO_CRITERIO,0.00)
	from SIG_PAAC_ITEM A,
	     CATALOGO_BIEN_SERV B   
       where ( A.SEC_EJEC        = B.SEC_EJEC     ) and
	     ( A.TIPO_BIEN       = B.TIPO_BIEN    ) and
         ( A.GRUPO_BIEN      = B.GRUPO_BIEN   ) and
	     ( A.CLASE_BIEN      = B.CLASE_BIEN   ) and
         ( A.FAMILIA_BIEN    = B.FAMILIA_BIEN ) and
	     ( A.ITEM_BIEN 	 = B.ITEM_BIEN    ) and
    	 ( A.ANO_EJE 	 = @vi_anio       ) and
         ( A.SEC_EJEC 	 = @vi_ejecutora  ) and
  	     ( A.TIPO_CONSOLID   = @vs_tipo_con   ) and
         ( A.NRO_CONSOLID    = @vi_nro_con    ) and
	     ( A.TIPO_GENERACION = @vs_tip_gen    ) and
	     ( A.TIPO_BIEN       = @ls_tipo_bien  ) and
	     ( A.SEC_CONSOLID    = @li_sec_con    ) and
	     ( A.SEC_RESUMEN     = @li_sec_res    )
--	     ( B.CODIGO_ITEM     = @vs_codigo )	
	
	/*
     if @vi_valor_min = 0.00 
	begin
	  select @vi_valor_min =  min(D.VALOR_PROV),
		 @vi_precio_min = min(D.PRECIO_PROV)
	    from CATALOGO_BIEN_SERV A,	         
	         SIG_PAAC_ITEM C,   
	         SIG_SOLICITUD_COTIZACION_ITEM D,   
        	 SIG_SOLICITUD_COTIZACION E  
	   where ( C.SEC_EJEC	     = A.SEC_EJEC        ) AND
			 ( C.TIPO_BIEN       = A.TIPO_BIEN       ) AND
        	 ( C.GRUPO_BIEN      = A.GRUPO_BIEN      ) AND
	         ( C.CLASE_BIEN      = A.CLASE_BIEN      ) AND
        	 ( C.FAMILIA_BIEN    = A.FAMILIA_BIEN    ) AND
			 ( C.ITEM_BIEN       = A.ITEM_BIEN       ) AND
	         ( D.ANO_EJE         = C.ANO_EJE         ) AND
        	 ( D.SEC_EJEC 	     = C.SEC_EJEC        ) AND
	         ( D.TIPO_CONSOLID   = C.TIPO_CONSOLID   ) AND
        	 ( D.NRO_CONSOLID    = C.NRO_CONSOLID    ) AND
	         ( D.TIPO_GENERACION = C.TIPO_GENERACION ) AND
        	 ( D.TIPO_BIEN       = C.TIPO_BIEN       ) AND
	         ( D.SEC_CONSOLID    = C.SEC_CONSOLID    ) AND
        	 ( D.SEC_RESUMEN     = C.SEC_RESUMEN     ) AND
	         ( D.ANO_EJE 	     = E.ANO_EJE         ) AND
        	 ( D.SEC_EJEC	     = E.SEC_EJEC        ) AND
	 	     ( D.TIPO_CONSOLID   = E.TIPO_CONSOLID   ) AND
        	 ( D.NRO_CONSOLID    = E.NRO_CONSOLID    ) AND
		     ( D.TIPO_GENERACION = E.TIPO_GENERACION ) AND
        	 ( D.NRO_SOLICITUD   = E.NRO_SOLICITUD   ) AND 
    	     ( D.ANO_EJE 	     = @vi_anio          ) AND
        	 ( D.SEC_EJEC 	     = @vi_ejecutora     ) AND
  	         ( D.TIPO_CONSOLID   = @vs_tipo_con      ) AND
        	 ( D.NRO_CONSOLID    = @vi_nro_con       ) AND
	         ( D.TIPO_GENERACION = @vs_tip_gen       ) AND
			 ( D.TIPO_BIEN       = @ls_tipo_bien     ) AND
			 ( D.SEC_CONSOLID    = @li_sec_con       ) AND
			 ( D.SEC_RESUMEN     = @li_sec_res       ) AND
			 ( D.FLAG_PARTICIPA  = '1'               )
		--
	  if @vs_tipo_bien ='B'
	     begin
		select @vi_valor_min = round(@vi_precio_min,6)    
	     end	
	end */
	
	if @vs_tipo_bien ='B'
	   begin	
                          			
	     insert into #VALOR_REF
                         (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                          SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                          VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, TIPO_CRITERIO)
		   values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                          @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, '-PRECIO HISTORICO-',
                          round(@vi_precio_his,6), @vi_precio_his, 1, @vs_abreviatura, @vs_criterio)
		
	     insert into #VALOR_REF
                         (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                          SEC_CONSOLID, SEC_RESUMEN, codigo_item, nombre_item, cantidad, nombre_prov,
                          valor_prov, precio_unit, flag_data, abreviatura, TIPO_CRITERIO)
		   values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                          @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Precio Ref.   Unit. ' + @vs_moneda,
                          round(@vi_valor_min,6), @vi_prec_unit, 11, @vs_abreviatura, @vs_criterio)
	     
	     select @vi_valor_tot = round(@vi_cantidad*@vi_valor_min,2)	
		  
	     insert into #VALOR_REF
                         (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                          SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                          VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, TIPO_CRITERIO)
		   values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                          @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref.   Total ' + @vs_moneda,
                          @vi_valor_tot, @vi_prec_unit, 12, @vs_abreviatura, @vs_criterio)
	
	     If (@vi_anio < 2009)
		Begin
		  insert into #VALOR_REF
                              (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                               SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                               VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA)
		        values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                               @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref.    70% ' + @vs_moneda,
                               round(@vi_valor_tot*0.7,2), @vi_prec_unit, 6, @vs_abreviatura)
		
		  insert into #VALOR_REF
                              (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                               SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                               VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA)
		        values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                               @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref. 110% ' + @vs_moneda,
                               round(@vi_valor_tot*1.1,2), @vi_prec_unit, 7, @vs_abreviatura)
		end
	    end
	else
	    begin
	      insert into #VALOR_REF
                          (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                           SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                           VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, tipo_criterio)
	           values (@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                           @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, '-VALOR HISTORICO-',
                           @vi_valor_his, round(@vi_precio_his,6), 1, @vs_abreviatura, @vs_criterio)

	      insert into #VALOR_REF
                          (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                           SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                           VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, TIPO_CRITERIO)
	            values(@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                           @li_sec_con , @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Referencial '+ @vs_moneda,
                           round(@vi_valor_min,6), @vi_prec_unit, 12, @vs_abreviatura, @vs_criterio)

	      If (@vi_anio < 2009)
	  	 Begin
		   insert into #VALOR_REF
                               (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                                SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                                VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA)
		        values (@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                                @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref.  70% '+ @vs_moneda,
                                round(@vi_valor_min*0.7,2), @vi_prec_unit, 5, @vs_abreviatura)
	            
		   insert into #VALOR_REF
                               (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                                SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                                VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA)			
		        values (@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                                @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref. 110% ' + @vs_moneda,
                                round(@vi_valor_min*1.1,2), @vi_prec_unit, 6, @vs_abreviatura)
		 end
	      Else
		 Begin
		   If (@vs_objeto = '04')
		      Begin
			If (@vi_valor_min*0.9 <> round(@vi_valor_min*0.9,2,1))
			   set @vi_valor_min = round(@vi_valor_min*0.9,2,1) + 0.01
			Else
			   set @vi_valor_min = round(@vi_valor_min*0.9,2,1)
                           
			   insert into #VALOR_REF
                                       (ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,
                                        SEC_CONSOLID, SEC_RESUMEN, CODIGO_ITEM, NOMBRE_ITEM, CANTIDAD, NOMBRE_PROV,
                                        VALOR_PROV, PRECIO_UNIT, FLAG_DATA, ABREVIATURA, TIPO_CRITERIO)
			        values (@vi_anio, @vi_ejecutora, @vs_tipo_con, @vi_nro_con, @vs_tip_gen, @ls_tipo_bien,
                                        @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, 'Valor Ref.  90% '+ @vs_moneda,
                                        @vi_valor_min, @vi_prec_unit, 12, @vs_abreviatura, @vs_criterio)
		      End
		End
	  end 		
 	  
          fetch next from lista_item
	  into @ls_tipo_bien, @li_sec_con, @li_sec_res, @vs_codigo, @vs_nom_item, @vi_cantidad, @vi_prec_unit, @vs_tipo_bien, @vs_abreviatura, @vs_moneda, @vs_criterio

	end 

 close lista_item
 deallocate lista_item

select 	*
from #VALOR_REF
order by FLAG_DATA, SECUENCIA asc

end
GO


-- ----------------------------
-- procedure structure for DT_CHECKOUTOBJECT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_CHECKOUTOBJECT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_CHECKOUTOBJECT]
GO

CREATE PROCEDURE [dbo].[DT_CHECKOUTOBJECT]
    @chObjectType  char(4),
    @vchObjectName varchar(255),
    @vchComment    varchar(255),
    @vchLoginName  varchar(255),
    @vchPassword   varchar(255),
    @iVCSFlags     int = 0,
    @iActionFlag   int = 0/* 0 => Checkout, 1 => GetLatest, 2 => UndoCheckOut */

as

	set nocount on

	declare @iReturn int
	declare @iObjectId int
	select @iObjectId =0

	declare @VSSGUID varchar(100)
	select @VSSGUID = 'SQLVersionControl.VCS_SQL'

	declare @iReturnValue int
	select @iReturnValue = 0

	declare @vchTempText varchar(255)

	/* this is for our strings */
	declare @iStreamObjectId int
	select @iStreamObjectId = 0

    declare @iPropertyObjectId int
    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    declare @vchProjectName   varchar(255)
    declare @vchSourceSafeINI varchar(255)
    declare @vchServerName    varchar(255)
    declare @vchDatabaseName  varchar(255)
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSProject',       @vchProjectName   OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSourceSafeINI', @vchSourceSafeINI OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLServer',     @vchServerName    OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLDatabase',   @vchDatabaseName  OUT

    if @chObjectType = 'PROC'
    begin
        /* Procedure Can have up to three streams
           Drop Stream, Create Stream, GRANT stream */

        exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT

        if @iReturn <> 0 GOTO E_OAError

        exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
												'CheckOut_StoredProcedure',
												NULL,
												@sProjectName = @vchProjectName,
												@sSourceSafeINI = @vchSourceSafeINI,
												@sObjectName = @vchObjectName,
												@sServerName = @vchServerName,
												@sDatabaseName = @vchDatabaseName,
												@sComment = @vchComment,
												@sLoginName = @vchLoginName,
												@sPassword = @vchPassword,
												@iVCSFlags = @iVCSFlags,
												@iActionFlag = @iActionFlag

        if @iReturn <> 0 GOTO E_OAError


        exec @iReturn = master.dbo.sp_OAGetProperty @iObjectId, 'GetStreamObject', @iStreamObjectId OUT

        if @iReturn <> 0 GOTO E_OAError

        create table #commenttext (id int identity, sourcecode varchar(255))


        select @vchTempText = 'STUB'
        while @vchTempText is not null
        begin
            exec @iReturn = master.dbo.sp_OAMethod @iStreamObjectId, 'GetStream', @iReturnValue OUT, @vchTempText OUT
            if @iReturn <> 0 GOTO E_OAError
            
            if (@vchTempText = '') set @vchTempText = null
            if (@vchTempText is not null) insert into #commenttext (sourcecode) select @vchTempText
        end

        select 'VCS'=sourcecode from #commenttext order by id
        select 'SQL'=text from syscomments where id = object_id(@vchObjectName) order by colid

    end

CleanUp:
    return

E_OAError:
    exec dbo.dt_displayoaerror @iObjectId, @iReturn
    GOTO CleanUp
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_CN_FASE_11
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_CN_FASE_11]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_CN_FASE_11]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_CN_FASE_11]  
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)    
AS    
    
BEGIN    
 DECLARE @lI_FASE_CUADRO NUMERIC(1,0)    
 DECLARE @ls_clasificador VARCHAR(20)    
 DECLARE @ls_flag_presup VARCHAR(1)    
 DECLARE @ls_centro_costo_presup VARCHAR(15)    
 DECLARE @ls_centro_costo_cambio VARCHAR(15)    
 DECLARE @ls_centro_costo VARCHAR(15)    
 DECLARE @ls_centro_padre VARCHAR(15)    
 DECLARE @ls_origen VARCHAR(1)    
 DECLARE @ls_codi_fuen VARCHAR(2)    
 DECLARE @ls_codi_fuen_impto VARCHAR(2)    
 DECLARE @ls_clas_gast VARCHAR(20)
 DECLARE @ld_Secu_func NUMERIC(4,0)    
 DECLARE @li_contador NUMERIC(10,0)    
 DECLARE @ld_valor_imp_progra NUMERIC(14,2)    
 DECLARE @li_secuencia NUMERIC(10,0)    
 DECLARE @ld_valor_progra NUMERIC(14,2)    
 DECLARE @ld_valor_aprob NUMERIC(14,2)    
 DECLARE @ld_mnto_impto NUMERIC(14,2)    
 DECLARE @ld_monto_progra NUMERIC(14,2)    
 DECLARE @ld_mnto_total NUMERIC(14,2)    
 DECLARE @ld_mnto_apro NUMERIC(14,2)    
 DECLARE @ld_mnto_asig NUMERIC(14,2)    
 DECLARE @ld_mnto_modif NUMERIC(14,2)    
 DECLARE @ls_categ_gasto VARCHAR(1)    
 DECLARE @ls_grupo_gasto VARCHAR(1)    
 DECLARE @ls_grupo VARCHAR(2)    
 DECLARE @ls_grupo1 VARCHAR(2)    
 DECLARE @ls_flag_gen_esp VARCHAR(1)    
 DECLARE @ld_valor_imp_asignado NUMERIC(14,2)    
 DECLARE @ld_valor_asignado NUMERIC(14,2)    
 DECLARE @ld_monto_asignado NUMERIC(14,2)    
 DECLARE @ld_monto_aprob NUMERIC(14,2)    
 DECLARE @ld_valor_imp_aprob NUMERIC(14,2)    
 declare @ld_min_correl numeric(8,0)    
 declare @li_CUENTA numeric(10,0)     
     
    
 SELECT @ls_flag_gen_esp = VALOR    
 FROM  SIG_PARAMETRO_EJECUTORA_ANIO    
 WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND     
 COD_MAESTRO = 'FLAG_TECHO_NIVEL'    
    
 SELECT @li_secuencia = ISNULL(MAX(secuencia),0)     
 FROM sig_techo_presupuesto     
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC    
    
 SET NOCOUNT ON    
    
 update  sig_techo_presupuesto    
 set centro_costo_presup = CENTRO_COSTO    
 where     
 ano_eje = @PN_ANIO and    
 sec_ejec = @PN_EJEC AND    
 FASE_CUADRO = 1 AND    
 FLAG_META_APROB = '0' AND    
 indicador = '0' and    
 centro_costo_presup is null    
     
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
      
SELECT @li_secuencia = ISNULL(MAX(secuencia),0)     
FROM sig_techo_presupuesto     
WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC    
    
IF @ls_flag_gen_esp = '0'    
BEGIN    
 insert into tmp_techo_fase_5    
 ( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, SEC_FUNC_PROP, CENTRO_COSTO, CENTRO_COSTO_PRESUP)    
 SELECT DISTINCT b.origen, b.fuente_financ,    
 (    
  SELECT  sum(mnto_progra)     
  FROM sig_techo_presupuesto  a    
  WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND    
         a.origen   = b.origen and a.fuente_financ = b.fuente_financ and    
         A.CATEG_GASTO = B.CATEG_GASTO AND A.GRUPO_GASTO =B.GRUPO_GASTO AND    
         A.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND    
         A.CENTRO_COSTO = B.CENTRO_COSTO AND    
         A.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND    
         a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1    
 ) as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.SEC_FUNC_PROP,    
 B.CENTRO_COSTO, B.CENTRO_COSTO_PRESUP    
 FROM sig_techo_presupuesto b    
 WHERE  b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND    
  b.indicador     = '0' and b.flag_meta_aprob = '0' and    
  B.FASE_CUADRO = 1 AND    
  not exists ( select '1'    
           FROM sig_techo_presupuesto c    
        WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND    
       c.origen    = b.origen and c.fuente_financ = b.fuente_financ and    
       C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND 
       C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND    
       C.CENTRO_COSTO = B.CENTRO_COSTO AND    
       C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND    
       c.FASE_CUADRO = 1 AND    
       c.indicador     ='6' and c.flag_meta_aprob = '0')    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
 insert INTO sig_techo_presupuesto      
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,    
 secuencia    , categ_gasto   , grupo_gasto    , clasificador,     
 sec_func       , centro_costo,     
 ppto_progra  , ppto_aprob  , ppto_asignado , ppto_modif,    
 mnto_progra  , mnto_asig  , mnto_aprob     , mnto_modif,    
 indicador   , paac_inicial  , paac_modif     , porc_techo ,     
 porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,    
 FASE_CUADRO )    
   select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,    
 ( @li_secuencia + secuencia ) , CATEG_GASTO, GRUPO_GASTO , NULL,    
   NULL , CENTRO_COSTO,    
 0 , 0 , 0 , 0 ,    
 mnto_progra,0, 0, 0 ,    
 '6' ,0, 0 , 0 ,    
 0 , SEC_FUNC_PROP , '0' , CENTRO_COSTO_PRESUP, 1    
 from tmp_techo_fase_5    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
 update sig_techo_presupuesto    
 set mnto_progra = ( SELECT SUM(A.MNTO_PROGRA) FROM SIG_TECHO_PRESUPUESTO A    
 where     
 A.ano_eje = @PN_ANIO and    
 A.sec_ejec = @PN_EJEC AND    
 A.origen    = sig_techo_presupuesto.ORIGEN AND    
 A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND    
 A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND    
 A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND   
 A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND    
 A.CENTRO_COSTO =  sig_techo_presupuesto.CENTRO_COSTO AND    
 A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND    
 A.indicador     ='0' and    
 A.flag_meta_aprob = '0' AND    
 A.FASE_CUADRO = 1)    
 where     
 ano_eje = @PN_ANIO and    
 sec_ejec = @PN_EJEC AND    
 indicador     ='6' and    
 flag_meta_aprob = '0' AND    
 FASE_CUADRO = 1    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
    
 SELECT @li_secuencia = max(ISNULL(secuencia,0))     
 FROM sig_techo_presupuesto     
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC    
    
 insert into tmp_techo_fase_6    
 ( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, SEC_FUNC_PROP, CENTRO_COSTO_PRESUP)    
 SELECT DISTINCT b.origen, b.fuente_financ,    
 (    
  SELECT  sum(mnto_progra)     
  FROM sig_techo_presupuesto  a    
  WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND    
         a.origen   = b.origen and a.fuente_financ = b.fuente_financ and    
         A.CATEG_GASTO = B.CATEG_GASTO AND A.GRUPO_GASTO =B.GRUPO_GASTO AND       
         A.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND    
         A.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND    
         a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1    
 ) as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.SEC_FUNC_PROP,    
 B.CENTRO_COSTO_PRESUP    
 FROM sig_techo_presupuesto b    
 WHERE  b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND    
  b.indicador     = '0' and b.flag_meta_aprob = '0' and    
  B.FASE_CUADRO = 1 AND    
  not exists ( select '1'    
           FROM sig_techo_presupuesto c    
        WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND    
       c.origen    = b.origen and c.fuente_financ = b.fuente_financ and    
       C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND    
       C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND    
       C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND    
       c.FASE_CUADRO = 1 AND    
       c.indicador     ='4' and c.flag_meta_aprob = '0')    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
    
 insert INTO sig_techo_presupuesto      
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,    
 secuencia    , categ_gasto   , grupo_gasto    , clasificador,     
 sec_func       , centro_costo,     
 ppto_progra  , ppto_aprob  , ppto_asignado , ppto_modif,    
 mnto_progra  , mnto_asig  , mnto_aprob     , mnto_modif,    
 indicador   , paac_inicial  , paac_modif     , porc_techo ,     
 porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,    
 FASE_CUADRO )    
   select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,    
 ( @li_secuencia + secuencia ) , CATEG_GASTO, GRUPO_GASTO , NULL,    
   NULL , NULL,    
 0 , 0 , 0 , 0 ,    
 mnto_progra,0, 0, 0 ,    
 '4' ,0, 0 , 0 ,    
 0 , SEC_FUNC_PROP , '0' , CENTRO_COSTO_PRESUP, 1    
 from tmp_techo_fase_6    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
    
 update sig_techo_presupuesto    
 set mnto_progra = ( SELECT SUM(A.MNTO_PROGRA) FROM SIG_TECHO_PRESUPUESTO A    
 where     
 A.ano_eje = @PN_ANIO and    
 A.sec_ejec = @PN_EJEC AND    
 A.origen    = sig_techo_presupuesto.ORIGEN AND    
 A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND    
 A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND    
 A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND      
 A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND    
 A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND    
 A.indicador     ='0' and    
 A.flag_meta_aprob = '0' AND    
 A.FASE_CUADRO = 1)    
 where     
 ano_eje = @PN_ANIO and    
 sec_ejec = @PN_EJEC AND    
 indicador     ='4' and    
 flag_meta_aprob = '0' AND    
 FASE_CUADRO = 1    
    
 IF @@ERROR <> 0    
 BEGIN    
  return -1    
 END    
    
END    
    
    
    
