-- ----------------------------
-- procedure structure for DT_SETPROPERTYBYID_U
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_SETPROPERTYBYID_U]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_SETPROPERTYBYID_U]
GO

CREATE PROCEDURE [dbo].[DT_SETPROPERTYBYID_U]
	@id int,
	@property varchar(64),
	@uvalue nvarchar(255),
	@lvalue image
as
	set nocount on
	-- 
	-- If we are writing the name property, find the ansi equivalent. 
	-- If there is no lossless translation, generate an ansi name. 
	-- 
	declare @avalue varchar(255) 
	set @avalue = null 
	if (@uvalue is not null) 
	begin 
		if (convert(nvarchar(255), convert(varchar(255), @uvalue)) = @uvalue) 
		begin 
			set @avalue = convert(varchar(255), @uvalue) 
		end 
		else 
		begin 
			if 'DtgSchemaNAME' = @property 
			begin 
				exec dbo.dt_generateansiname @avalue output 
			end 
		end 
	end 
	if exists (select * from dbo.dtproperties 
			where objectid=@id and property=@property)
	begin
		--
		-- bump the version count for this row as we update it
		--
		update dbo.dtproperties set value=@avalue, uvalue=@uvalue, lvalue=@lvalue, version=version+1
			where objectid=@id and property=@property
	end
	else
	begin
		--
		-- version count is auto-set to 0 on initial insert
		--
		insert dbo.dtproperties (property, objectid, value, uvalue, lvalue)
			values (@property, @id, @avalue, @uvalue, @lvalue)
	end
GO


-- ----------------------------
-- procedure structure for SP_INT_PARAMETRO_EJECUTORA_ANIO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_INT_PARAMETRO_EJECUTORA_ANIO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_INT_PARAMETRO_EJECUTORA_ANIO]
GO

CREATE PROCEDURE [dbo].[SP_INT_PARAMETRO_EJECUTORA_ANIO]
(@ano_eje NUMERIC(4), @sec_ejec NUMERIC(6),@cod_maestro VARCHAR(50), @ls_valor VARCHAR(1) OUT)
AS

BEGIN
     SELECT @ls_valor = COALESCE(rtrim(ltrim(valor)),'x')
       FROM sig_parametro_ejecutora_anio
      WHERE ano_eje     = @ano_eje  and
            sec_ejec    = @sec_ejec and
            cod_maestro = @cod_maestro
     
     select @ls_valor
END
GO


