-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[USP_PRDETALLEUPDATE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[USP_PRDETALLEUPDATE]
GO

CREATE PROCEDURE [dbo].[USP_PRDETALLEUPDATE] (
	@ano_eje numeric(4,0),
	@sec_ejec numeric(6,0),	
	@centro_costo varchar(15),
	@cuser_id varchar(8),
	@fuente_financ varchar(2),
	@sec_func numeric(5,0),
	@tipo_tarea char(1),
	@nivel_tarea char(1),
	@codigo_tarea numeric(10,0),
	@tipo_bien char(1), 
	@grupo_bien char(2),
	@clase_bien char(2),
	@familia_bien char(4),
	@item_bien char(4),
	@clasificador varchar(6),
	@cant_01 numeric(14,2),
	@cant_02 numeric(14,2),
	@cant_03 numeric(14,2),
	@cant_04 numeric(14,2),
	@cant_05 numeric(14,2),
	@cant_06 numeric(14,2),
	@cant_07 numeric(14,2),
	@cant_08 numeric(14,2),
	@cant_09 numeric(14,2),
	@cant_10 numeric(14,2),
	@cant_11 numeric(14,2),
	@cant_12 numeric(14,2),
	@tipo_impto char(1),
	@fte_impto varchar(2),
	@tasa_impto numeric(14,2),
	@nro_consolid numeric(5,0),
	@nro_pedido char(5),
	@sec_consolid numeric(5,0),
	@sec_resumen numeric(5,0),
	@sec_meta numeric(5,0),
	@sec_ctro_costo numeric(5,0),
	@respuesta varchar(50) OUTPUT )
AS
DECLARE @moneda varchar(6)
DECLARE @total_paac_item numeric(10,0)
DECLARE @total_paac_meta numeric(10,0)
DECLARE @total_paac_centro_costo numeric(10,0)
DECLARE @ano_proceso numeric(10,0)
DECLARE @valor_impto numeric(14,2)
DECLARE @cant_total numeric(14,2)
DECLARE @valor_total numeric(14,2)
DECLARE @mnto_01 numeric(14,2)
DECLARE @mnto_02 numeric(14,2)
DECLARE @mnto_03 numeric(14,2)
DECLARE @mnto_04 numeric(14,2)
DECLARE @mnto_05 numeric(14,2)
DECLARE @mnto_06 numeric(14,2)
DECLARE @mnto_07 numeric(14,2)
DECLARE @mnto_08 numeric(14,2)
DECLARE @mnto_09 numeric(14,2)
DECLARE @mnto_10 numeric(14,2)
DECLARE @mnto_11 numeric(14,2)
DECLARE @mnto_12 numeric(14,2)
DECLARE @mnto_total numeric(14,2)
DECLARE @mnto_controltecho numeric(14,2)
DECLARE @DIFERENCIA numeric(14,2)
DECLARE @resultado varchar(50)
DECLARE @precio_unit numeric(14,2)
DECLARE @precio_moneda numeric(14,2)
DECLARE @factor_unidad numeric(5,0)
DECLARE @lTotalTP NUMERIC(5,0)
DECLARE @presentacion varchar(40)

DECLARE @tot_01 numeric(14,2)
DECLARE @tot_02 numeric(14,2)
DECLARE @tot_03 numeric(14,2)
DECLARE @tot_04 numeric(14,2)
DECLARE @tot_05 numeric(14,2)
DECLARE @tot_06 numeric(14,2)
DECLARE @tot_07 numeric(14,2)
DECLARE @tot_08 numeric(14,2)
DECLARE @tot_09 numeric(14,2)
DECLARE @tot_10 numeric(14,2)
DECLARE @tot_11 numeric(14,2)
DECLARE @tot_12 numeric(14,2)
DECLARE @cantidad_tot numeric(14,2)
DECLARE @valor_tot numeric(14,2)
DECLARE @valor_moneda  numeric(14,2)
DECLARE @valor_impto_moneda  numeric(14,2)

	DECLARE @validar BIT
	DECLARE @fuente_financ_result VARCHAR(2)
	DECLARE @sec_func_result NUMERIC(5,0)
	DECLARE @clasificador_result VARCHAR(6)


SET @resultado = ''
SET @cant_total = @cant_01 + @cant_02 + @cant_03 + @cant_04 + @cant_05 + @cant_06 + @cant_07 + @cant_08 + @cant_09 + @cant_10 + @cant_11 + @cant_12 
SELECT @ano_proceso = CAST(valor AS INTEGER) FROM SIG_PARAMETRO_EJECUTORA WHERE COD_MAESTRO = 'PROC_SIS_ANO'

SELECT @factor_unidad=factor_unidad , @precio_unit=precio_ref
FROM catalogo_bien_serv 
WHERE tipo_bien =@tipo_bien  AND grupo_bien =@grupo_bien 
AND clase_bien =@clase_bien AND familia_bien =@familia_bien 
AND item_bien =@item_bien

SELECT @precio_moneda = @precio_unit 


IF @tipo_bien = 'B'
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit
		SET @mnto_02 = @cant_02 * @precio_unit
		SET @mnto_03 = @cant_03 * @precio_unit
		SET @mnto_04 = @cant_04 * @precio_unit
		SET @mnto_05 = @cant_05 * @precio_unit
		SET @mnto_06 = @cant_06 * @precio_unit
		SET @mnto_07 = @cant_07 * @precio_unit
		SET @mnto_08 = @cant_08 * @precio_unit
		SET @mnto_09 = @cant_09 * @precio_unit
		SET @mnto_10 = @cant_10 * @precio_unit
		SET @mnto_11 = @cant_11 * @precio_unit
		SET @mnto_12 = @cant_12 * @precio_unit
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_02 = @cant_02 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_03 = @cant_03 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_04 = @cant_04 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_05 = @cant_05 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_06 = @cant_06 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_07 = @cant_07 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_08 = @cant_08 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_09 = @cant_09 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_10 = @cant_10 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_11 = @cant_11 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_12 = @cant_12 * @precio_unit * 100 / (100 + @tasa_impto)
	END
ELSE
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 
		SET @mnto_02 = @cant_02 
		SET @mnto_03 = @cant_03 
		SET @mnto_04 = @cant_04 
		SET @mnto_05 = @cant_05 
		SET @mnto_06 = @cant_06 
		SET @mnto_07 = @cant_07 
		SET @mnto_08 = @cant_08 
		SET @mnto_09 = @cant_09 
		SET @mnto_10 = @cant_10 
		SET @mnto_11 = @cant_11 
		SET @mnto_12 = @cant_12 
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * (100 - @tasa_impto) / 100
		SET @mnto_02 = @cant_02 * (100 - @tasa_impto) / 100
		SET @mnto_03 = @cant_03 * (100 - @tasa_impto) / 100
		SET @mnto_04 = @cant_04 * (100 - @tasa_impto) / 100
		SET @mnto_05 = @cant_05 * (100 - @tasa_impto) / 100
		SET @mnto_06 = @cant_06 * (100 - @tasa_impto) / 100
		SET @mnto_07 = @cant_07 * (100 - @tasa_impto) / 100
		SET @mnto_08 = @cant_08 * (100 - @tasa_impto) / 100
		SET @mnto_09 = @cant_09 * (100 - @tasa_impto) / 100
		SET @mnto_10 = @cant_10 * (100 - @tasa_impto) / 100
		SET @mnto_11 = @cant_11 * (100 - @tasa_impto) / 100
		SET @mnto_12 = @cant_12 * (100 - @tasa_impto) / 100
	END

SET @mnto_total = @mnto_01 + @mnto_02 + @mnto_03 + @mnto_04 + @mnto_05 + @mnto_06 + @mnto_07 + @mnto_08 + @mnto_09 + @mnto_10 + @mnto_11 + @mnto_12
IF @tipo_impto <> '0'
	IF @tipo_bien = 'B'
		SET @valor_impto = (@cant_total * @precio_unit) - @mnto_total 
	ELSE
		SET @valor_impto = @cant_total  - @mnto_total 
ELSE
	SET @valor_impto = 0

BEGIN TRAN

	if @presentacion is null
		SELECT @factor_unidad = FACTOR 
		FROM SIG_CATALOGO_PRESENTACION WHERE codigo is null
	else
		SELECT @factor_unidad = FACTOR 
		FROM SIG_CATALOGO_PRESENTACION WHERE codigo = @factor_unidad

	UPDATE sig_paac_centro_costo
	SET 
	mes_01=@cant_01, mes_02=@cant_02, mes_03=@cant_03, mes_04=@cant_04, 
	mes_05=@cant_05, mes_06=@cant_06, mes_07=@cant_07, mes_08=@cant_08, 
	mes_09=@cant_09, mes_10=@cant_10, mes_11=@cant_11, mes_12=@cant_12, 
	cantidad=@cant_total, valor=@mnto_total, valor_impto = @valor_impto,
	valor_moneda=@mnto_total, valor_impto_moneda = @valor_impto
	WHERE 
	ano_eje=@ano_eje AND sec_ejec=@sec_ejec AND  tipo_consolid=2 AND  
	nro_consolid=@nro_consolid AND tipo_generacion=0 AND sec_consolid=@sec_consolid 
	AND  sec_resumen=@sec_resumen AND  sec_ctro_costo=@sec_ctro_costo AND sec_meta = @sec_meta

	SELECT @tot_01 = SUM(isnull(mes_01,0)), @tot_02 = SUM(isnull(mes_02,0)), @tot_03 = SUM(isnull(mes_03,0)), 
	@tot_04 = SUM(isnull(mes_04,0)), @tot_05 = SUM(isnull(mes_05,0)), @tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)), 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)), 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta AND @sec_ctro_costo = @sec_ctro_costo

	UPDATE sig_paac_metas 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @mnto_total, 
	valor_impto  = @valor_impto, valor_moneda = @mnto_total, valor_impto_moneda = @valor_impto,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta

	SELECT @tot_01 = SUM(isnull(mes_01,0)), @tot_02 = SUM(isnull(mes_02,0)), @tot_03 = SUM(isnull(mes_03,0)), 
	@tot_04 = SUM(isnull(mes_04,0)), @tot_05 = SUM(isnull(mes_05,0)), @tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)) , 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)) , 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta AND sec_ctro_costo = @sec_ctro_costo

	UPDATE sig_paac_item 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @valor_tot, valor_moneda  = @valor_tot,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND grupo_bien = @grupo_bien AND clase_bien = @clase_bien 
	AND familia_bien = @familia_bien AND item_bien = @item_bien 
	AND sec_consolid = @sec_consolid 
   set @respuesta = 1
   print 'casi OK'

	EXEC USP_PRTPProceso @ano_eje,  @sec_ejec, @centro_costo,  @tipo_bien, @nro_pedido, '3', @validar OUTPUT, @fuente_financ_result OUTPUT, @sec_func_result OUTPUT, @clasificador_result OUTPUT

COMMIT TRAN
   print 'OK'
RETURN 0

ERROR:
   print 'no OK'
   ROLLBACK TRAN
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_CREA_KIT_X_EESS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CREA_KIT_X_EESS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CREA_KIT_X_EESS]
GO

CREATE PROCEDURE [dbo].[SP_CREA_KIT_X_EESS] (
	@p_Ano_CN	NUMERIC(4,0),
	@p_Sec_Ejec	NUMERIC(4,0)
)
AS

/***************************************************************************************************************************
REALIZA LA GENERACION DE KITS POR ESTABLECIMIENTOS, AQUELLOS MARCADOS EN LA PERSONALIZACIÓN DE INSUMOS (1 X ESTABLECIMIENTO)
****************************************************************************************************************************/

BEGIN 

  INSERT INTO SIG_PPR_KIT_ITEMS_EST (
	     ANO_EJE       , SEC_EJEC     , 	ID_SUB_FINALIDAD,		COD_ESTABLEC   , 	SEC_KIT ,
	     TIPO_ORIGEN    , ESTADO		  ,	FECHA_MOD)  		
 SELECT @p_Ano_CN, 		@p_Sec_Ejec,		ITEM.ID_SUB_FINALIDAD,	SEDE.SEC_ESTABLEC,	ITEM.SEC_KIT,
   		'0'            ,  'A'     , 		GETDATE()
	FROM SIG_PPR_KIT_ITEMS ITEM,
   		SIG_PPR_SEDE  SEDE, 
       SIG_PPR_ESTABLECIMIENTO   EESS
 WHERE   SEDE.COD_ESTABLEC = EESS.COD_ESTABLEC AND
	   SEDE.ANO_EJE      = EESS.ANO_EJE      AND
	   SEDE.SEC_EJEC     = EESS.SEC_EJEC	AND
 		ITEM.ANO_EJE   = @p_Ano_CN   AND
	     ITEM.SEC_EJEC  = @p_Sec_Ejec  AND
	     EESS.ANO_EJE	 = ITEM.ANO_EJE AND
	     EESS.SEC_EJEC	 = ITEM.SEC_EJEC AND
	     ITEM.CATEGORIA =   EESS.CATEGORIA	 AND
	     ITEM.FLAG_RETIRAR = '0' AND
        ISNULL(ITEM.FLAG_SUGERIDO, '0') = '1' and 
	      	      NOT EXISTS (SELECT 1 FROM SIG_PPR_KIT_ITEMS_EST DEST
			  WHERE DEST.ANO_EJE =ITEM.ANO_EJE      AND
			  		DEST.SEC_EJEC      = ITEM.SEC_EJEC       AND
					DEST.COD_ESTABLEC  = SEDE.SEC_ESTABLEC    AND
					DEST.SEC_KIT       = ITEM.SEC_KIT	      AND
					dest.ID_SUB_FINALIDAD= ITEM.ID_sub_finalidad
                    )  


END
/***************************************************************************************************************************
REALIZA LA GENERACION DE KITS POR ESTABLECIMIENTOS, AQUELLOS MARCADOS EN LA PERSONALIZACIÓN DE INSUMOS (1 X ESTABLECIMIENTO)
****************************************************************************************************************************/
	BEGIN

	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD= (1 + FACTOR_MERMA) * ((CANTIDAD_CASO * PORCENT_USO / 100) / FACTOR_CONVERS)
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD AND
	       KIT.TIPO_CALCULO   	 				= 4			      					AND 
	       KIT.TIPO_BIEN 	   					= 'B'								AND
	       KIT.ESTADO		  					= 'A'								
	       
	
   	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD								= 0
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD		AND
	       (FACTOR_CONVERS = 0  OR  TIPO_CALCULO  <>4)			 			AND 
	       KIT.ESTADO		  					= 'A'	
	
	UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD								= 0
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @p_Ano_CN  						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @p_Sec_Ejec 						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD		AND
	       SIG_PPR_KIT_ITEMS_EST.CANTIDAD		  IS NULL							AND
	       KIT.ESTADO		  					= 'A'	
    END
GO


-- ----------------------------
-- procedure structure for SP_GENERA_CUADRO_OT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERA_CUADRO_OT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_GENERA_CUADRO_OT]
GO

CREATE PROCEDURE [dbo].[SP_GENERA_CUADRO_OT]  
(@pn_ano NUMERIC, @pn_sec_ejec NUMERIC, @ps_tipo_contrato varchar(1),  
 @pn_nro_contrato NUMERIC,@ps_mes_periodo varchar(2),@pn_tipo_cambio NUMERIC,  
 @pd_fecha_pago DATE, @ps_flag_clcc varchar(1), @pn_nro_proceso numeric)  
  
AS  
DECLARE @ls_parametro VARCHAR(1)
DECLARE @ln_anio numeric(9,0)  
DECLARE @ln_cuenta NUMERIC(10,0)	
DECLARE @ln_ejecutora numeric(9,0)  
  
DECLARE @ln_sec_periodo  numeric(3,0)  
DECLARE @ln_sec_ppto     numeric(3,0)  	
DECLARE @ln_sec_depend   numeric(3,0)  
  
DECLARE @ls_centro_costo VARCHAR(15)  
DECLARE @ls_nivel_tarea  VARCHAR(1)  
DECLARE @ln_sec_cc       numeric(9,0)  
DECLARE @ls_clas_gast_param varchar(20)  
  
DECLARE @LN_ANO_EJE_I NUMERIC  
DECLARE @LN_SEC_EJEC_I NUMERIC  
DECLARE @LS_TIPO_CONTRATO_I VARCHAR(1)  
DECLARE @LN_NRO_CONTRATO_I NUMERIC  
DECLARE @LN_NRO_ITEM_I NUMERIC  
DECLARE @LS_TIPO_BIEN_I VARCHAR(1)  
DECLARE @LS_GRUPO_BIEN_I VARCHAR(2)  
DECLARE @LS_CLASE_BIEN_I VARCHAR(2)  
DECLARE @LS_FAMILIA_BIEN_I VARCHAR(4)  
DECLARE @LS_ITEM_BIEN_I VARCHAR(4)  
  
DECLARE @LN_ANO_EJE_C NUMERIC  
DECLARE @LN_SEC_EJEC_C NUMERIC  
DECLARE @LS_TIPO_CONTRATO_C VARCHAR(1)  
DECLARE @LN_NRO_CONTRATO_C NUMERIC  
DECLARE @LN_NRO_ITEM_C NUMERIC  
DECLARE @LN_SEC_PERIODO_C NUMERIC  
DECLARE @LS_TIPO_BIEN_C VARCHAR(1)  
DECLARE @LS_GRUPO_BIEN_C VARCHAR(2)  
DECLARE @LS_CLASE_BIEN_C VARCHAR(2)  
DECLARE @LS_FAMILIA_BIEN_C VARCHAR(4)  
DECLARE @LS_ITEM_BIEN_C VARCHAR(4)  
  
DECLARE @LN_ANO_EJE_S NUMERIC  
DECLARE @LN_SEC_EJEC_S NUMERIC  
DECLARE @LS_TIPO_CONTRATO_S VARCHAR(1)  
DECLARE @LN_NRO_CONTRATO_S NUMERIC  
DECLARE @LN_NRO_ITEM_S NUMERIC  
DECLARE @LN_SEC_PERIODO_S NUMERIC  
DECLARE @LN_SEC_PPTO_S NUMERIC  
DECLARE @LS_TIPO_BIEN_S VARCHAR(1)  
DECLARE @LS_GRUPO_BIEN_S VARCHAR(2)  
DECLARE @LS_CLASE_BIEN_S VARCHAR(2)  
DECLARE @LS_FAMILIA_BIEN_S VARCHAR(4)  
DECLARE @LS_ITEM_BIEN_S VARCHAR(4)  


DECLARE @LN_ANO_EJE_S_1 NUMERIC  
DECLARE @LN_SEC_EJEC_S_1 NUMERIC  
DECLARE @LS_TIPO_CONTRATO_S_1 VARCHAR(1)  
DECLARE @LN_NRO_CONTRATO_S_1 NUMERIC  
DECLARE @LN_NRO_ITEM_S_1 NUMERIC  
DECLARE @LN_SEC_PERIODO_S_1 NUMERIC  
DECLARE @LN_SEC_PPTO_S_1 NUMERIC  


DECLARE  ccn_item CURSOR FOR  
SELECT distinct CTI.ANO_EJE,  
       CTI.SEC_EJEC,  
       CTI.TIPO_CONTRATO,  
       CTI.NRO_CONTRATO,  
       CTI.NRO_ITEM,  
       CTI.TIPO_BIEN,  
       CTI.GRUPO_BIEN,  
       CTI.CLASE_BIEN,  
       CTI.FAMILIA_BIEN,  
       CTI.ITEM_BIEN  
 FROM  SIG_CONTRATO_ITEM CTI,  
       SIG_CONTRATOS CTR  
WHERE  CTI.ano_eje  = @pn_ano AND  
       CTI.SEC_EJEC = @PN_SEC_EJEC AND  
       CTI.TIPO_CONTRATO = @PS_TIPO_CONTRATO AND  
       CTI.NRO_CONTRATO  = @PN_NRO_CONTRATO AND  
       CTI.ano_eje  >= 2013 AND  
       CTI.TIPO_BIEN  = 'S' AND  
       CTR.ANO_EJE      = CTI.ANO_EJE AND  
       CTR.SEC_EJEC     = CTI.SEC_EJEC AND  
       CTR.TIPO_CONTRATO= CTI.TIPO_CONTRATO AND  
       CTR.NRO_CONTRATO = CTI.NRO_CONTRATO AND  
       CTR.TIPO_BIEN  = 'S' AND  
       COALESCE(CTR.FLAG_CONTR_OT,'0') = '1' AND  
         
   EXISTS( 
   SELECT PED.ANO_EJE  
   FROM SIG_PEDIDOS PED,  
         SIG_DETALLE_PEDIDOS DET  
   WHERE DET.ANO_EJE = PED.ANO_EJE AND  
         DET.SEC_EJEC = PED.SEC_EJEC AND  
         DET.TIPO_BIEN = PED.TIPO_BIEN AND  
         DET.NRO_PEDIDO = PED.NRO_PEDIDO AND  
         DET.ANO_EJE  = @pn_ano AND  
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND   
         COALESCE(DET.FLAG_PEDIDO_OT,'0') = '1' AND  
         COALESCE(DET.FLAG_PROC_OT, '0') = '0' AND  
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') <> 'XX' AND
    DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN = CTI.GRUPO_BIEN  +  CTI.CLASE_BIEN  +  CTI.FAMILIA_BIEN  +  CTI.ITEM_BIEN AND  
      
         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  PED.FUENTE_FTO  +  PED.NRO_PEDIDO IN (   
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO    
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S')
 
   UNION
 
   SELECT PED.ANO_EJE  
   FROM SIG_PEDIDOS PED,  
        SIG_DETALLE_PEDIDOS DET  ,
        SIG_METAS_X_CENTRO SMC
   WHERE DET.ANO_EJE = PED.ANO_EJE AND  
         DET.SEC_EJEC = PED.SEC_EJEC AND  
         DET.TIPO_BIEN = PED.TIPO_BIEN AND  
         DET.NRO_PEDIDO = PED.NRO_PEDIDO AND  
         PED.ANO_EJE = SMC.ANO_EJE AND
         PED.SEC_EJEC = SMC.SEC_EJEC AND
         PED.CENTRO_COSTO = SMC.CENTRO_COSTO AND
         PED.SEC_FUNC = SMC.SEC_FUNC AND
         DET.ANO_EJE  = @pn_ano AND  
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND   
         COALESCE(DET.FLAG_PEDIDO_OT,'0') = '1' AND  
	 COALESCE(DET.FLAG_PROC_OT,'0') = '0' AND
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') = 'XX' AND
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN = CTI.GRUPO_BIEN  +  CTI.CLASE_BIEN  +  CTI.FAMILIA_BIEN  +  CTI.ITEM_BIEN AND  
      
         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  

         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  SMC.FUENTE_FINANC  +  PED.NRO_PEDIDO IN (   
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO    
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
   X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S')

         )   
       
DECLARE ccn_item_mensual CURSOR FOR  
SELECT DISTINCT CTM.ANO_EJE,  
       CTM.SEC_EJEC,  
       CTM.TIPO_CONTRATO,  
       CTM.NRO_CONTRATO,  
       CTM.NRO_ITEM,  
       CTM.SEC_PERIODO,  
       CTI.GRUPO_BIEN,  
       CTI.CLASE_BIEN,  
       CTI.FAMILIA_BIEN,  
       CTI.ITEM_BIEN  
FROM   SIG_CONTRATO_ITEM_MENSUAL CTM,   
       SIG_CONTRATO_ITEM CTI,  
       SIG_CONTRATOS CTR  
WHERE  CTM.ano_eje  = @pn_ano AND  
       CTM.SEC_EJEC = @PN_SEC_EJEC AND  
       CTM.TIPO_CONTRATO = @PS_TIPO_CONTRATO AND  
       CTM.NRO_CONTRATO  = @PN_NRO_CONTRATO AND  
       CTM.ANO_EJE       = CTI.ANO_EJE  AND        
       CTM.SEC_EJEC      = CTI.SEC_EJEC AND        
       CTM.TIPO_CONTRATO = CTI.TIPO_CONTRATO AND    
       CTM.NRO_CONTRATO  = CTI.NRO_CONTRATO AND    
       CTM.NRO_ITEM      = CTI.NRO_ITEM AND        
       CTM.ano_eje  >= 2013 AND  
       CTI.ANO_EJE       = CTR.ANO_EJE AND         
       CTI.SEC_EJEC      = CTR.SEC_EJEC AND        
       CTI.TIPO_CONTRATO = CTR.TIPO_CONTRATO AND    
       CTI.NRO_CONTRATO  = CTR.NRO_CONTRATO AND    
       CTR.TIPO_BIEN  = 'S' AND  
       CTR.FLAG_CONTR_OT = '1' AND   
       CTM.FECHA_PAGO = @pd_fecha_pago AND
         
   EXISTS( 
   SELECT PED.ANO_EJE  
   FROM SIG_PEDIDOS PED,  
         SIG_DETALLE_PEDIDOS DET  
   WHERE DET.ANO_EJE = PED.ANO_EJE AND  
         DET.SEC_EJEC = PED.SEC_EJEC AND  
         DET.TIPO_BIEN = PED.TIPO_BIEN AND  
         DET.NRO_PEDIDO = PED.NRO_PEDIDO AND  
         DET.ANO_EJE =  @pn_ano AND  
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND   
         COALESCE(DET.FLAG_PEDIDO_OT,'0') = '1' AND  
	 COALESCE(DET.FLAG_PROC_OT,'0') = '0' AND
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') <> 'XX' AND           
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN = CTI.GRUPO_BIEN  +  CTI.CLASE_BIEN  +  CTI.FAMILIA_BIEN  +  CTI.ITEM_BIEN AND      

         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  

         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  PED.FUENTE_FTO  +  PED.NRO_PEDIDO IN (  
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S')
 
   UNION
 
   SELECT PED.ANO_EJE  
   FROM   SIG_PEDIDOS PED,  
          SIG_DETALLE_PEDIDOS DET ,
          SIG_METAS_X_CENTRO SMC 
   WHERE DET.ANO_EJE = PED.ANO_EJE AND  
         DET.SEC_EJEC = PED.SEC_EJEC AND  
         DET.TIPO_BIEN = PED.TIPO_BIEN AND  
         DET.NRO_PEDIDO = PED.NRO_PEDIDO AND  
         PED.ANO_EJE = SMC.ANO_EJE AND     
         PED.SEC_EJEC = SMC.SEC_EJEC AND
         PED.CENTRO_COSTO = SMC.CENTRO_COSTO AND
         PED.SEC_FUNC = SMC.SEC_FUNC AND
         DET.ANO_EJE =  @pn_ano AND  
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND   
         COALESCE(DET.FLAG_PEDIDO_OT,'0') = '1' AND  
	 COALESCE(DET.FLAG_PROC_OT,'0') = '0' AND
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') = 'XX' AND           
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN = CTI.GRUPO_BIEN  +  CTI.CLASE_BIEN  +  CTI.FAMILIA_BIEN  +  CTI.ITEM_BIEN AND      

         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  

         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  SMC.FUENTE_FINANC  +  PED.NRO_PEDIDO IN (  
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S')

	 )   
  
DECLARE @ls_parametro_fuente VARCHAR(1)  
DECLARE @ls_flag_procedencia VARCHAR(1)

SELECT @ls_parametro_fuente = sig_parametro_ejecutora.valor  
  FROM sig_parametro_ejecutora  
 WHERE sec_ejec    =  @pn_sec_ejec AND  
       cod_maestro = 'FLAG_FUENTE'
       
IF @ls_parametro_fuente IS NULL   
   BEGIN   
    SELECT @ls_parametro_fuente= '0'  
   END   

SELECT @ls_flag_procedencia = SIG_CONTRATOS.flag_procedencia
   FROM SIG_CONTRATOS
  WHERE ANO_EJE =  @pn_ano AND
        sec_ejec = @pn_sec_ejec AND
        tipo_contrato = @ps_tipo_contrato  AND
        NRO_CONTRATO = @pn_nro_contrato


 OPEN ccn_item  
 FETCH ccn_item INTO   
     @LN_ANO_EJE_I,@LN_SEC_EJEC_I,@LS_TIPO_CONTRATO_I,@LN_NRO_CONTRATO_I,   
        @LN_NRO_ITEM_I,@LS_TIPO_BIEN_I,@LS_GRUPO_BIEN_I,@LS_CLASE_BIEN_I,  
        @LS_FAMILIA_BIEN_I,@LS_ITEM_BIEN_I      
  
 WHILE @@FETCH_STATUS = 0  
 BEGIN  
           
   SELECT @ln_sec_periodo = MAX(SIG_CONTRATO_ITEM_MENSUAL.sec_periodo)  
   FROM SIG_CONTRATO_ITEM_MENSUAL  
   WHERE ANO_EJE = @LN_ANO_EJE_I  AND SEC_EJEC = @LN_SEC_EJEC_I AND   
         TIPO_CONTRATO = @LS_TIPO_CONTRATO_I AND NRO_CONTRATO = @LN_NRO_CONTRATO_I AND   
         NRO_ITEM = @LN_NRO_ITEM_I  
     
   IF @ln_sec_periodo IS NULL   
   BEGIN   
      SELECT @ln_sec_periodo= 0  
   END   
     
  
    IF @ls_parametro_fuente = '1'
    BEGIN
    
    SELECT @ln_sec_periodo = @ln_sec_periodo + 1  
                 
   INSERT INTO sig_contrato_item_mensual  
            ( ano_eje    , sec_ejec   , tipo_contrato, nro_contrato  , nro_item,  
              sec_periodo, ano_proceso, mes_proceso  , cantidad      , valor_moneda, 
              valor_soles, fecha_reg  , cuser_id     , flag_proceso  , sec_movimiento, 
              fecha_pago,  flag_origen, tipo_cambio  , precio_moneda )  
   SELECT @LN_ANO_EJE_I         , @LN_SEC_EJEC_I, @LS_TIPO_CONTRATO_I, @LN_NRO_CONTRATO_I    , @LN_NRO_ITEM_I,            
          @ln_sec_periodo       , @pn_ano   , @ps_mes_periodo    , coalesce(sum(DET.cant_aprobada),0), coalesce(sum(DET.cant_aprobada),0),  
          coalesce(sum(DET.cant_aprobada),0), GETDATE()     , '1'                , 'N'                   , NULL,      
          @pd_fecha_pago        , '0'           , @pn_tipo_cambio    , 1 
    FROM SIG_PEDIDOS PED,  
         SIG_DETALLE_PEDIDOS DET  
   WHERE PED.ANO_EJE = DET.ANO_EJE AND  
         PED.SEC_EJEC = DET.SEC_EJEC AND  
         PED.TIPO_BIEN   = DET.TIPO_BIEN AND  
         PED.NRO_PEDIDO = DET.NRO_PEDIDO AND  
         DET.ANO_EJE =  @pn_ano AND    
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND  
         COALESCE(DET.FLAG_PEDIDO_OT, '0') = '1' AND  
         COALESCE(DET.FLAG_PROC_OT, '0') = '0' AND
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') <> 'XX' AND    
       
         DET.TIPO_BIEN  = @LS_TIPO_BIEN_I AND  
         DET.GRUPO_BIEN = @LS_GRUPO_BIEN_I AND  
         DET.CLASE_BIEN = @LS_CLASE_BIEN_I AND  
         DET.FAMILIA_BIEN = @LS_FAMILIA_BIEN_I AND  
         DET.ITEM_BIEN    = @LS_ITEM_BIEN_I AND   
           
         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec  AND  
         X.PERIODO  = @ps_mes_periodo  AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  
           
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  PED.FUENTE_FTO  +  PED.NRO_PEDIDO IN (  
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S') AND
	NOT EXISTS(SELECT X.ANO_EJE 
	FROM sig_contrato_item_mensual X
	WHERE
        X.ANO_EJE =  @pn_ano AND    
        X.SEC_EJEC = @pn_sec_ejec AND  
	X.TIPO_CONTRATO = @LS_TIPO_CONTRATO_I AND 
	X.NRO_CONTRATO = @LN_NRO_CONTRATO_I AND   
        X.NRO_ITEM = @LN_NRO_ITEM_I AND
	X.SEC_PERIODO = @ln_sec_periodo)

 
        IF @@ERROR <> 0  
       	BEGIN  
	  CLOSE ccn_item  
	  DEALLOCATE ccn_item  
	  GOTO ERROR  
	END   
	
   END	

  IF @ls_parametro_fuente = '0'
    BEGIN

   SELECT @ln_sec_periodo = @ln_sec_periodo + 1  

   INSERT INTO sig_contrato_item_mensual  
            ( ano_eje, sec_ejec, tipo_contrato, nro_contrato, nro_item,  
           sec_periodo, ano_proceso, mes_proceso, cantidad, valor_moneda, valor_soles, 
           fecha_reg, cuser_id, flag_proceso, sec_movimiento, fecha_pago,  
           flag_origen, tipo_cambio, precio_moneda )  
   SELECT @LN_ANO_EJE_I, @LN_SEC_EJEC_I, @LS_TIPO_CONTRATO_I, @LN_NRO_CONTRATO_I, @LN_NRO_ITEM_I,            
         @ln_sec_periodo,                 @pn_ano,              @ps_mes_periodo,
         coalesce(sum(DET.cant_aprobada),0),coalesce(sum(DET.cant_aprobada),0), coalesce(sum(DET.cant_aprobada),0),  
         GETDATE(),      '1',             'N',       NULL,  @pd_fecha_pago,   
         '0',            @pn_tipo_cambio, 1 
   FROM SIG_PEDIDOS PED,  
         SIG_DETALLE_PEDIDOS DET ,
         SIG_METAS_X_CENTRO SMC 
   WHERE PED.ANO_EJE = DET.ANO_EJE AND  
         PED.SEC_EJEC = DET.SEC_EJEC AND  
         PED.TIPO_BIEN = DET.TIPO_BIEN AND  
         PED.NRO_PEDIDO = DET.NRO_PEDIDO AND  
         PED.ANO_EJE = SMC.ANO_EJE AND     
         PED.SEC_EJEC = SMC.SEC_EJEC AND
         PED.CENTRO_COSTO = SMC.CENTRO_COSTO AND
         PED.SEC_FUNC = SMC.SEC_FUNC AND
         DET.ANO_EJE =  @pn_ano AND    
         DET.SEC_EJEC = @pn_sec_ejec AND  
         DET.TIPO_BIEN = 'S'   AND  
         DET.TIPO_PEDIDO = '2' AND  
         COALESCE(DET.FLAG_PEDIDO_OT, '0') = '1' AND  
         COALESCE(DET.FLAG_PROC_OT, '0') = '0' AND
         PED.ESTADO =  '2' AND  
         PED.ANO_EJE >= 2013  AND  
         COALESCE(PED.FUENTE_FTO, 'XX') = 'XX' AND           
         DET.TIPO_BIEN  = @LS_TIPO_BIEN_I AND  
         DET.GRUPO_BIEN = @LS_GRUPO_BIEN_I AND  
         DET.CLASE_BIEN = @LS_CLASE_BIEN_I AND  
         DET.FAMILIA_BIEN = @LS_FAMILIA_BIEN_I AND  
         DET.ITEM_BIEN    = @LS_ITEM_BIEN_I AND   
           
         PED.SEC_FUNC IN (   
         SELECT X.SEC_FUNC   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec  AND  
         X.PERIODO  = @ps_mes_periodo  AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'M'  
         ) AND  
           
         DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
         SELECT X.CODIGO_ITEM  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE   
         X.ANO_EJE = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO = 'I') AND  
           
         DET.CLASIFICADOR IN (  
         SELECT X.CLASIFICADOR  
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'C') AND  
           
         PED.CENTRO_COSTO  +  SMC.FUENTE_FINANC  +  PED.NRO_PEDIDO IN (  
         SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO   
         FROM TMP_PARAMETROS_CRON_OT X  
         WHERE  
         X.ANO_EJE  = @pn_ano AND  
         X.SEC_EJEC = @pn_sec_ejec AND  
         X.PERIODO  = @ps_mes_periodo AND  
	 X.PROCESO  = @pn_nro_proceso AND
         X.TIPO     = 'S') AND
	NOT EXISTS(SELECT X.ANO_EJE 
	FROM sig_contrato_item_mensual X
	WHERE
        X.ANO_EJE =  @pn_ano AND    
        X.SEC_EJEC = @pn_sec_ejec AND  
	X.TIPO_CONTRATO = @LS_TIPO_CONTRATO_I AND 
	X.NRO_CONTRATO = @LN_NRO_CONTRATO_I AND   
        X.NRO_ITEM = @LN_NRO_ITEM_I AND
	X.SEC_PERIODO = @ln_sec_periodo)


        IF @@ERROR <> 0  
       	BEGIN  
	  CLOSE ccn_item  
	  DEALLOCATE ccn_item  
	  GOTO ERROR  
	END   
           
  END

     INSERT INTO SIG_CONTRATO_ITEM_MENS_PED        
