PED.SEC_EJEC = DET.SEC_EJEC AND  
PED.TIPO_BIEN = DET.TIPO_BIEN AND  
PED.NRO_PEDIDO = DET.NRO_PEDIDO AND  
PED.ANO_EJE = SMC.ANO_EJE AND     
PED.SEC_EJEC = SMC.SEC_EJEC AND
PED.CENTRO_COSTO = SMC.CENTRO_COSTO AND
PED.SEC_FUNC = SMC.SEC_FUNC AND
 
SIG_DETALLE_PEDIDOS.ANO_EJE = DET.ANO_EJE AND  
SIG_DETALLE_PEDIDOS.SEC_EJEC = DET.SEC_EJEC AND  
SIG_DETALLE_PEDIDOS.TIPO_BIEN = DET.TIPO_BIEN AND  
SIG_DETALLE_PEDIDOS.TIPO_PEDIDO = DET.TIPO_PEDIDO AND  
SIG_DETALLE_PEDIDOS.SECUENCIA = DET.SECUENCIA AND
SIG_DETALLE_PEDIDOS.NRO_PEDIDO = DET.NRO_PEDIDO AND
 
DET.ANO_EJE =  @pn_ano AND  
DET.SEC_EJEC = @pn_sec_ejec AND  
DET.TIPO_BIEN = 'S'   AND  
DET.TIPO_PEDIDO = '2' AND  
COALESCE(DET.FLAG_PEDIDO_OT, '0') = '1' AND  
COALESCE(DET.FLAG_PROC_OT, '0') = '0' AND  
PED.ESTADO =  '2' AND  
PED.ANO_EJE >= 2013 AND  
COALESCE(PED.FUENTE_FTO, 'XX') = 'XX' AND           
 
PED.SEC_FUNC IN (   
SELECT X.SEC_FUNC   
FROM TMP_PARAMETROS_CRON_OT X  
WHERE   
X.ANO_EJE  = @pn_ano AND  
X.SEC_EJEC = @pn_sec_ejec AND  
X.PERIODO  = @ps_mes_periodo AND 
X.PROCESO  = @pn_nro_proceso AND 
X.TIPO = 'M'  
) AND  
 
DET.GRUPO_BIEN  +  DET.CLASE_BIEN  +  DET.FAMILIA_BIEN  +  DET.ITEM_BIEN IN (   
SELECT X.CODIGO_ITEM  
FROM TMP_PARAMETROS_CRON_OT X  
WHERE   
X.ANO_EJE = @pn_ano AND  
X.SEC_EJEC = @pn_sec_ejec AND  
X.PERIODO = @ps_mes_periodo AND  
X.PROCESO  = @pn_nro_proceso AND
X.TIPO = 'I') AND  
 
DET.CLASIFICADOR IN (  
SELECT X.CLASIFICADOR  
FROM TMP_PARAMETROS_CRON_OT X  
WHERE  
X.ANO_EJE  = @pn_ano AND  
X.SEC_EJEC = @pn_sec_ejec AND  
X.PERIODO  = @ps_mes_periodo AND  
X.PROCESO  = @pn_nro_proceso AND
X.TIPO     = 'C') AND  
 
PED.CENTRO_COSTO  +  SMC.FUENTE_FINANC  +  PED.NRO_PEDIDO  IN (  
SELECT X.CENTRO_COSTO  +  X.FUENTE_FINANC  +  X.NRO_PEDIDO   
FROM TMP_PARAMETROS_CRON_OT X  
WHERE  
X.ANO_EJE  = @pn_ano AND  
X.SEC_EJEC = @pn_sec_ejec AND  
X.PERIODO  = @ps_mes_periodo AND  
X.PROCESO  = @pn_nro_proceso AND
X.TIPO     = 'S')  

)
 
IF @@ERROR <> 0  
BEGIN  
    GOTO ERROR  
END   


RETURN 0  
   
ERROR:  
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_GENERA_SGE_PAAC_MENSUAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERA_SGE_PAAC_MENSUAL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_GENERA_SGE_PAAC_MENSUAL]
GO

CREATE PROCEDURE [dbo].[SP_GENERA_SGE_PAAC_MENSUAL] (
	   @vAnio INT,
	   @vEjecutora INT,
	   @vMesIni  VARCHAR(2),
	   @vMesFin  VARCHAR(2))
AS

--------------------------------------------------------
DECLARE @PMESINI INT
DECLARE @PMESFIN INT
DECLARE @WANO_EJE numeric(4, 0)
DECLARE	@WSEC_EJEC numeric(6, 0)
DECLARE	@WTIPO_CONSOLID char(1)
DECLARE @WNRO_CONSOLID numeric(5, 0)
DECLARE	@WTIPO_GENERACION char(1)
DECLARE	@WMES_INICIAL varchar(2)
DECLARE	@WMES_FINAL varchar(2)
DECLARE	@WMES_PROPUESTO varchar(2)
DECLARE	@WTIPO_PROCESO varchar(2)
DECLARE	@WOBJETO varchar(2)
DECLARE	@WTIPO_CIIU varchar(1)
DECLARE	@WGRUPO_CIIU varchar(2)
DECLARE	@WCATEGORIA_CIIU varchar(2)
DECLARE	@WPAIS varchar(4)
DECLARE	@WDEPARTAMENTO varchar(2)
DECLARE	@WPROVINCIA varchar(2)
DECLARE	@WDISTRITO varchar(2)
DECLARE	@WVALOR_MONEDA numeric(16, 2)
DECLARE	@WVALOR_PLAN numeric(16, 2)
DECLARE	@WORGANO_CONVOCACION varchar(60)
DECLARE	@WNRO_PAAC varchar(4)
DECLARE	@WFLAG_PAAC varchar(1)
DECLARE	@WTIPO_BIEN varchar(1)
DECLARE @WGRUPO_BIEN varchar(2)
DECLARE	@WCLASE_BIEN varchar(2)
DECLARE	@WFAMILIA_BIEN varchar(4)
DECLARE	@WITEM_BIEN varchar(4)
DECLARE @WUNIDAD_MEDIDA numeric(3, 0)
DECLARE	@WPRECIO_UNIT numeric(16, 6)
DECLARE	@WMONEDA varchar(6)
DECLARE	@WTIPO_CAMBIO numeric(10, 6)
DECLARE	@WCANTIDAD numeric(20, 6)
DECLARE	@WFUENTE_FINANC varchar(2)
DECLARE	@WFTE_FTO_IMPTO varchar(2)
DECLARE	@WCLASIFICADOR varchar(20)
DECLARE	@WTIPO_IMPTO varchar(1)
DECLARE @WTEXTO_PROCESO VARCHAR(250)
DECLARE @WTEXTO_TIPO VARCHAR(250)
DECLARE @WCADENA_PROCESO VARCHAR(250)
DECLARE @WTEXTO_FLAG_PSA VARCHAR(5)
DECLARE @WTEXTO_WNRO_PROCESO VARCHAR(250)
DECLARE @WFLAG_PSA VARCHAR(1)
DECLARE @WANO_PROCESO NUMERIC(4,0)
DECLARE @WNRO_PROCESO NUMERIC(5,0)
DECLARE @WSIGLAS VARCHAR(40)
DECLARE @WPROCESO NUMERIC(5,0)
--------------------------------------------------------

SELECT @PMESINI = CAST( @vMesIni AS INT )
SELECT @PMESFIN = CAST( @vMesFin AS INT )

DELETE FROM SGE_PAAC_MENSUAL_EXP
   WHERE ANO_EJE= @vAnio
     AND SEC_EJEC= @vEjecutora
	AND @PMESINI <= MES_INICIAL AND mes_final <= @PMESFIN


--RECUPERAR CONSOLIDADOS QUE TENGAN NRO REFERENCIA
--RECUPERAR CONSOLIDADOS QUE SEAN DEL PAO INCIAL
DECLARE CUR_PAAC CURSOR FOR
SELECT A.ANO_EJE, A.SEC_EJEC, A.TIPO_CONSOLID, A.NRO_CONSOLID, A.TIPO_GENERACION,
cast(A.MES_INICIAL AS INT) mes_inicial, cast(A.MES_FINAL AS INT) mes_final,
CAST(A.MES_PROPUESTO AS INT) MES_PROPUESTO, A.TIPO_PROCESO, A.OBJETO, A.TIPO_CIIU,
A.GRUPO_CIIU, A.CATEGORIA_CIIU, A.PAIS, A.DEPARTAMENTO,  A.PROVINCIA,  A.DISTRITO,
( D.CANTIDAD * C.PRECIO_MONEDA ) VALOR_MONEDA, 
( CASE C.TIPO_CAMBIO WHEN NULL THEN 1 WHEN 0 THEN 1 ELSE C.TIPO_CAMBIO END )*( D.CANTIDAD * C.PRECIO_MONEDA ) VALOR_PLAN, 
A.ORGANO_CONVOCACION, B.TIPO_BIEN, C.GRUPO_BIEN,
C.CLASE_BIEN, C.FAMILIA_BIEN, C.ITEM_BIEN,  C.UNIDAD_MEDIDA, D.CANTIDAD , C.PRECIO_UNIT,
D.FUENTE_FINANC, D.FTE_FTO_IMPTO, D.CLASIFICADOR, D.TIPO_IMPTO, C.MONEDA, C.TIPO_CAMBIO,
A.NRO_PAAC, A.FLAG_PAAC
FROM SIG_PAAC_CONSOLIDADO A, SIG_PAAC_SECUENCIA B,
SIG_PAAC_ITEM C, SIG_PAAC_METAS D
WHERE 
A.ANO_EJE = B.ANO_EJE AND
A.SEC_EJEC = B.SEC_EJEC  AND
A.TIPO_CONSOLID = B.TIPO_CONSOLID AND
A.NRO_CONSOLID  = B.NRO_CONSOLID AND
A.TIPO_GENERACION = B.TIPO_GENERACION AND
B.ANO_EJE = C.ANO_EJE AND
B.SEC_EJEC = C.SEC_EJEC  AND
B.TIPO_CONSOLID = C.TIPO_CONSOLID AND
B.NRO_CONSOLID  = C.NRO_CONSOLID AND
B.TIPO_GENERACION = C.TIPO_GENERACION AND             	
B.TIPO_BIEN   = C.TIPO_BIEN AND
B.SEC_CONSOLID  = C.SEC_CONSOLID AND
C.ANO_EJE = D.ANO_EJE AND
C.SEC_EJEC = D.SEC_EJEC  AND
C.TIPO_CONSOLID = D.TIPO_CONSOLID AND
C.NRO_CONSOLID  = D.NRO_CONSOLID AND
C.TIPO_GENERACION = D.TIPO_GENERACION AND             	
C.TIPO_BIEN   = D.TIPO_BIEN AND
C.SEC_CONSOLID  = D.SEC_CONSOLID AND
C.SEC_RESUMEN  = D.SEC_RESUMEN	AND
A.ANO_EJE= @vAnio AND
A.SEC_EJEC= @vEjecutora AND
A.TIPO_CONSOLID = '1' AND
A.FLAG_PAAC NOT IN ('0','3','5') AND
( @PMESINI <= cast(A.MES_INICIAL AS INT) AND cast(A.MES_FINAL AS INT) <= @PMESFIN ) 
ORDER BY
A.ANO_EJE, A.SEC_EJEC, A.TIPO_CONSOLID, 
A.NRO_CONSOLID, A.TIPO_GENERACION,A.NRO_PAAC

OPEN CUR_PAAC
FETCH CUR_PAAC INTO 
@WANO_EJE, @WSEC_EJEC, @WTIPO_CONSOLID, @WNRO_CONSOLID,@WTIPO_GENERACION,
@WMES_INICIAL , @WMES_FINAL,
@WMES_PROPUESTO, @WTIPO_PROCESO, @WOBJETO, @WTIPO_CIIU ,
@WGRUPO_CIIU, @WCATEGORIA_CIIU ,@WPAIS, @WDEPARTAMENTO, @WPROVINCIA , @WDISTRITO,
@WVALOR_MONEDA ,
@WVALOR_PLAN,
@WORGANO_CONVOCACION, @WTIPO_BIEN, @WGRUPO_BIEN,
@WCLASE_BIEN, @WFAMILIA_BIEN, @WITEM_BIEN, @WUNIDAD_MEDIDA,@WCANTIDAD,@WPRECIO_UNIT,
@WFUENTE_FINANC, @WFTE_FTO_IMPTO, @WCLASIFICADOR,@WTIPO_IMPTO, @WMONEDA,@WTIPO_CAMBIO,
@WNRO_PAAC, @WFLAG_PAAC

WHILE @@FETCH_STATUS = 0
BEGIN
	--RECUPERAR LA DESCRIPCION DEL TIPO DE PROCESO
	SELECT @WTEXTO_TIPO = sig_maestro_proceso.descripcion 
	FROM sig_maestro_proceso
	WHERE 
	sig_maestro_proceso.ano_eje = @WANO_EJE AND  
	sig_maestro_proceso.tipo_organismo = '01'  AND  
	sig_maestro_proceso.codigo = 'TIPO_PROCESO' AND
	sig_maestro_proceso.codigo_det = @WTIPO_PROCESO	
	--RECUPERAR LA DESCRIPCION DEL TIPO DE PROCESO

	--RECUPERAR DESCRIPCION DE PROCESO DE SELECCION
	--SELECT @WTEXTO_PROCESO =
	SELECT @WCADENA_PROCESO = ''
	SELECT  @WTEXTO_FLAG_PSA = ''
	SELECT  @WTEXTO_WNRO_PROCESO = ''

	IF @WTIPO_CONSOLID = 1 
	BEGIN
		--RECUPERAR DE LLAVE DE PAAC MODIFICADO
		DECLARE CUR_PAAC_PROCESO CURSOR FOR
		SELECT DISTINCT A.PROCESO
		FROM SIG_PROCESO_DE_SELECCION A
		WHERE A.ANO_EJE = @WANO_EJE AND
		A.SEC_EJEC = @WSEC_EJEC AND
		A.TIPO_GENERACION = @WTIPO_GENERACION AND
		A.TIPO_CONSOLID =  '2' AND
		A.NRO_CONSOLID = @WNRO_CONSOLID

		OPEN CUR_PAAC_PROCESO
		FETCH CUR_PAAC_PROCESO INTO @WPROCESO
		WHILE @@FETCH_STATUS = 0
		BEGIN
			--RECUPERAR DATOS DE PROCESO
			DECLARE CUR_PAAC_PROCESO_SEC CURSOR FOR
			SELECT DISTINCT A.ANO_PROCESO, A.NRO_PROCESO, A.SIGLAS, A.FLAG_PSA
			FROM SIG_PROCESO_SECUENCIA A
			WHERE A.ANO_EJE = @WANO_EJE AND
			A.SEC_EJEC = @WSEC_EJEC AND
			A.TIPO_GENERACION = @WTIPO_GENERACION AND
			A.PROCESO =  @WPROCESO 

			OPEN CUR_PAAC_PROCESO_SEC
			FETCH CUR_PAAC_PROCESO_SEC INTO 
			@WANO_PROCESO, @WNRO_PROCESO, @WSIGLAS, @WFLAG_PSA
			WHILE @@FETCH_STATUS = 0
			BEGIN
				IF  @WFLAG_PSA = 'S'
				BEGIN
					SELECT  @WTEXTO_FLAG_PSA = 'PSA'
				END
				ELSE
				BEGIN
					SELECT  @WTEXTO_FLAG_PSA = ''
				END
			
				IF @WNRO_PROCESO IS NULL
				BEGIN
					SELECT  @WTEXTO_WNRO_PROCESO = ''
				END
				ELSE
				BEGIN
					SELECT  @WTEXTO_WNRO_PROCESO = RIGHT('00000' + RTRIM(LTRIM(CAST(@WNRO_PROCESO AS VARCHAR(5) ))), 5) + '-' + CAST(@WANO_PROCESO AS VARCHAR(4) ) + '-'

					IF @WSIGLAS IS NULL
					BEGIN
						SELECT  @WTEXTO_WNRO_PROCESO = RTRIM(LTRIM(@WTEXTO_FLAG_PSA)) + ' ' + RTRIM(LTRIM(@WTEXTO_WNRO_PROCESO))
					END
					ELSE
					BEGIN
						SELECT  @WTEXTO_WNRO_PROCESO = RTRIM(LTRIM(@WTEXTO_FLAG_PSA)) + ' ' + RTRIM(LTRIM(@WTEXTO_WNRO_PROCESO)) + RTRIM(LTRIM(@WSIGLAS))
					END
				END

				IF @WCADENA_PROCESO = ''
				BEGIN
					SELECT @WCADENA_PROCESO =  RTRIM(LTRIM(@WTEXTO_WNRO_PROCESO))
				END
				ELSE
				BEGIN
					IF LEN(RTRIM(LTRIM(@WCADENA_PROCESO))) + LEN(RTRIM(LTRIM(@WTEXTO_WNRO_PROCESO))) <= 250
					BEGIN
						SELECT @WCADENA_PROCESO = RTRIM(LTRIM(@WCADENA_PROCESO)) + ', ' + RTRIM(LTRIM(@WTEXTO_WNRO_PROCESO))
					END
				END	

				FETCH CUR_PAAC_PROCESO_SEC INTO 
				@WANO_PROCESO, @WNRO_PROCESO, @WSIGLAS, @WFLAG_PSA
			END
			CLOSE CUR_PAAC_PROCESO_SEC
			DEALLOCATE CUR_PAAC_PROCESO_SEC

			FETCH CUR_PAAC_PROCESO INTO @WPROCESO
		END	
		CLOSE CUR_PAAC_PROCESO
		DEALLOCATE CUR_PAAC_PROCESO

		--RECUPERAR DESCRIPCION DE PROCESO DE SELECCION
	END

	SELECT @WTEXTO_PROCESO = RTRIM(LTRIM(@WCADENA_PROCESO))

	INSERT INTO SGE_PAAC_MENSUAL_EXP
	(ANO_EJE, SEC_EJEC, TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION,
	MES_INICIAL, MES_FINAL, MES_PROPUESTO, TIPO_PROCESO, OBJETO, TIPO_CIIU,
	GRUPO_CIIU, CATEGORIA_CIIU, PAIS, DEPARTAMENTO,  PROVINCIA,  DISTRITO,
	VALOR_MONEDA, VALOR_PLAN, ORGANO_CONVOCACION, TIPO_BIEN, GRUPO_BIEN,
	CLASE_BIEN, FAMILIA_BIEN, ITEM_BIEN,  UNIDAD_MEDIDA, CANTIDAD , PRECIO_UNIT,
	FUENTE_FINANC, FTE_FTO_IMPTO, CLASIFICADOR, TIPO_IMPTO, MONEDA, TIPO_CAMBIO,
	NRO_PAAC, FLAG_PAAC, TEXTO_PROCESO, TEXTO_TIPO)
	VALUES
	(@WANO_EJE, @WSEC_EJEC, @WTIPO_CONSOLID, @WNRO_CONSOLID,@WTIPO_GENERACION,
	@WMES_INICIAL , @WMES_FINAL, @WMES_PROPUESTO, @WTIPO_PROCESO, @WOBJETO, @WTIPO_CIIU ,
	@WGRUPO_CIIU, @WCATEGORIA_CIIU ,@WPAIS, @WDEPARTAMENTO, @WPROVINCIA , @WDISTRITO,
	@WVALOR_MONEDA ,@WVALOR_PLAN,@WORGANO_CONVOCACION, @WTIPO_BIEN, @WGRUPO_BIEN,
	@WCLASE_BIEN, @WFAMILIA_BIEN, @WITEM_BIEN, @WUNIDAD_MEDIDA,@WCANTIDAD,@WPRECIO_UNIT,
	@WFUENTE_FINANC, @WFTE_FTO_IMPTO, @WCLASIFICADOR,@WTIPO_IMPTO, @WMONEDA,@WTIPO_CAMBIO,
	@WNRO_PAAC, @WFLAG_PAAC, @WTEXTO_PROCESO, @WTEXTO_TIPO )

	FETCH CUR_PAAC INTO 
	@WANO_EJE, @WSEC_EJEC, @WTIPO_CONSOLID, @WNRO_CONSOLID,@WTIPO_GENERACION,
	@WMES_INICIAL , @WMES_FINAL,
	@WMES_PROPUESTO, @WTIPO_PROCESO, @WOBJETO, @WTIPO_CIIU ,
	@WGRUPO_CIIU, @WCATEGORIA_CIIU ,@WPAIS, @WDEPARTAMENTO, @WPROVINCIA , @WDISTRITO,
	@WVALOR_MONEDA ,
	@WVALOR_PLAN,
	@WORGANO_CONVOCACION, @WTIPO_BIEN, @WGRUPO_BIEN,
	@WCLASE_BIEN, @WFAMILIA_BIEN, @WITEM_BIEN, @WUNIDAD_MEDIDA,@WCANTIDAD,@WPRECIO_UNIT,
	@WFUENTE_FINANC, @WFTE_FTO_IMPTO, @WCLASIFICADOR,@WTIPO_IMPTO, @WMONEDA,@WTIPO_CAMBIO,
	@WNRO_PAAC, @WFLAG_PAAC

END

CLOSE CUR_PAAC
DEALLOCATE CUR_PAAC
--/
GO


-- ----------------------------
-- procedure structure for DT_DISPLAYOAERROR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_DISPLAYOAERROR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_DISPLAYOAERROR]
GO

CREATE PROCEDURE [dbo].[DT_DISPLAYOAERROR]
    @iObject int,
    @iresult int
as

set nocount on

declare @vchOutput      varchar(255)
declare @hr             int
declare @vchSource      varchar(255)
declare @vchDescription varchar(255)

    exec @hr = master.dbo.sp_OAGetErrorInfo @iObject, @vchSource OUT, @vchDescription OUT

    select @vchOutput = @vchSource + ': ' + @vchDescription
    raiserror (@vchOutput,16,-1)

    return
GO


-- ----------------------------
-- procedure structure for SP_SIG_PROC_CONT_HT_MUEBLES
-- ----------------------------
/* procedure [SP_SIG_PROC_CONT_HT_MUEBLES] is encrypted */

-- ----------------------------
-- procedure structure for SP_SIG_ACTUALIZA_KARDEX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_ACTUALIZA_KARDEX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_ACTUALIZA_KARDEX]
GO

CREATE PROCEDURE [dbo].[SP_SIG_ACTUALIZA_KARDEX]
@an_ano_eje numeric(4), @an_sec_ejec numeric(6), @as_almacen varchar(3), @as_sec_alma varchar(3),
@as_tipo_movi varchar(1), @ai_tipo_tran numeric(2), @an_nro_movi numeric(6), @as_mes varchar(2),
@as_tipo_uso varchar(1), @ai_tipo_ppto numeric(2), @an_encargo numeric(6), @ad_fech_movi datetime,
@as_tipo_bien varchar(1), @as_grupo_bien varchar(2), @as_clase_bien varchar(2), @as_fami_bien varchar(4),
@as_item_bien varchar(4), @as_clas_gast varchar(20), @as_plan_mayor varchar(4), @as_plan_subcta varchar(8), 
@as_usuing varchar(30), @adt_fecha_actual datetime, @as_equipo varchar(20),
@as_message varchar(100) output

------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

AS
BEGIN
DECLARE
@ls_msg varchar(1000),
@ls_correlativo varchar(4),
@li_count numeric(8),
@ld_err	 numeric(8),
@li_code  numeric(8),

--variables para calcular los valores del reg actual
@ldec_pu numeric(16,6),
@ldec_sa numeric(18,4),
@ldec_pp numeric(16,6),
@ldec_vt numeric(14,2),
@ldec_va numeric(14,2),

--variables que mantienen los valores del reg anterior
@ldt_fech_movi2 datetime,
@ls_tipo_movi2 varchar(1),
@li_tipo_tran2 numeric(2),
--@li_nro_movi2 numeric(5),
@li_nro_movi2 numeric(6),
@li_secuencia2 numeric(2),
@li_sec_deta2 numeric(5),
@ldec_c2 numeric(18,4),
@ldec_pu2 numeric(16,6),
@ldec_sa2 numeric(18,4),
@ldec_pp2 numeric(16,6),
@ldec_pp3 numeric(16,6),
@ldec_vt2 numeric(14,2),
@ldec_va2 numeric(14,2),
@ldec_va3 numeric(14,2),
@ldec_sa3 numeric (18,4),
@ldec_tsai numeric(14,2),
@ldec_tsti numeric (18,4),

--variables para los valores totales de sig_detalle_movim_almacen por bien
@ldec_ncant numeric(18,4),
@ldec_nprecunit numeric(16,6),
@ldec_icant numeric(18,4),
@ldec_scant numeric(18,4),
@ldec_nvalo numeric(14,2),
@ldec_ivalo numeric(14,2),
@ldec_svalo numeric(14,2),
@ldec_nprecinve numeric(16,6),

--cbucle_generico
@ls_tipo_bien varchar(1),
@ls_grupo_bien varchar(2),
@ls_clase_bien varchar(2),
@ls_fami_bien varchar(4),
@ls_item_bien varchar(4),
@ls_clas_gast varchar(20),
@ls_plan_mayor varchar(4),
@ls_plan_subcta varchar(8),
@ls_codi_bien varchar(12),
@ls_tipo_marc varchar(1),
@ld_marca numeric(5),
@ld_encargo numeric(6),
@ld_sec_ejec2 numeric(6),

--cdetmov_intervalo_in_out
@ld_fech_movi datetime,
@ls_tipo_movi varchar(1),
@li_tipo_tran numeric(2),
--@li_nro_movi numeric(5),
@li_nro_movi numeric(6),
@li_secuencia numeric(2),
@li_sec_detalle numeric(5),
@ldec_tc numeric(18,4),
@ldec_tpu numeric(16,6),
@ldec_tsa numeric(18,4),
@ldec_tpp numeric(16,6),
@ldec_tvt numeric(14,2),
@ldec_tva numeric(14,2),
@ld_temp numeric(6),
@ld_unid_medi numeric(3),
@ld_item_bien_det numeric(5),
@ls_kardex_clasif varchar(1),
@ld_kardex_verifi  numeric(1)

-- Si parametro existe y esta activo se trabaja sin clasificador en kardex
set @ls_kardex_clasif = 'S'

SELECT @ld_kardex_verifi = count(*)
  FROM sig_maestro_det_numerico 
 WHERE cod_maestro = 'PARAMETRO' AND
       cod_detalle = 1 AND
       @an_ano_eje >= valor_numerico AND
       estado = 'A'

set @ld_kardex_verifi = isnull(@ld_kardex_verifi, 0)

If (@ld_kardex_verifi > 0)
Begin
	set @as_clas_gast = '%'
	set @ls_kardex_clasif = 'N'
END

IF (@ai_tipo_ppto = 2) 
Begin
   IF (@an_ano_eje >= 2014) 
	   SET @ls_kardex_clasif = 'S'
   
END 

--
set @ls_correlativo = '0001'

-- cursor para proceso en batch o en linea (1 bien)
DECLARE cbucle_generico CURSOR FOR
SELECT DISTINCT d.tipo_bien,    d.grupo_bien, d.clase_bien,
		 d.familia_bien, d.item_bien,  d.marca,
		 m.nro_encargo,  m.sec_ejec2,  case @ls_kardex_clasif when 'N' then '0' else d.clasificador end,
		 d.mayor,	 d.sub_cta, d.tipo_marca,
		 d.unidad_medida, d.item_bien_det
  FROM sig_detalle_movim_almacen d,
  	sig_movim_almacen m
 WHERE d.ano_eje      = m.ano_eje  and
       d.sec_ejec     = m.sec_ejec and
       d.almacen      = m.almacen  and
       d.sec_almacen  = m.sec_almacen  and
       d.tipo_movimto = m.tipo_movimto and
       d.tipo_transac = m.tipo_transac and
       d.tipo_ppto    = m.tipo_ppto    and
       d.nro_movimto  = m.nro_movimto  and
       m.estado_kardex= 'S' and
       d.ano_eje      = @an_ano_eje    and
       d.sec_ejec     = @an_sec_ejec   and
       d.almacen      = @as_almacen    and
       d.sec_almacen  = @as_sec_alma   and
       d.tipo_movimto in ('A','I','S') and
       d.mes_proceso  = @as_mes        and
       m.tipo_ppto    = @ai_tipo_ppto  and
       ((@ai_tipo_ppto = 1) or
	(@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
       m.tipo_uso     = @as_tipo_uso   and
       d.cant_articulo >= 0            and
       d.fecha_movimto >= @ad_fech_movi   and
       d.tipo_bien    like @as_tipo_bien  and
       d.grupo_bien   like @as_grupo_bien and
       d.clase_bien   like @as_clase_bien and
       d.familia_bien like @as_fami_bien  and
       d.item_bien    like @as_item_bien  and
       d.clasificador like @as_clas_gast  and
       d.mayor        like @as_plan_mayor and
       d.sub_cta      like @as_plan_subcta 

-- para todos los bienes upd sig_detalle_movim_almacen y sig_kardex_por_almacen
OPEN cbucle_generico
FETCH NEXT FROM cbucle_generico INTO @ls_tipo_bien, @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien,
					@ls_item_bien, @ld_marca, @ld_encargo, @ld_sec_ejec2,
					@ls_clas_gast, @ls_plan_mayor, @ls_plan_subcta, @ls_tipo_marc,
					@ld_unid_medi, @ld_item_bien_det
WHILE @@FETCH_STATUS = 0
BEGIN
	set @ls_codi_bien = @ls_grupo_bien + @ls_clase_bien + @ls_fami_bien + @ls_item_bien
	set @ldec_tsti= 0
	set @ldec_tsai= 0
	set @ldec_pu2 = 0
	set @ldec_vt2 = 0
	set @ldec_sa2 = 0
	set @ldec_va2 = 0
	set @ldec_pp2 = 0

	-- captura datos del kardex y calcular el precio promedio inicial
	 SELECT @ldec_tsti = stock_inicial, @ldec_tsai = saldo_inicial
	   FROM sig_kardex_por_almacen
	  WHERE ano_eje      = @an_ano_eje    and
	 	sec_ejec     = @an_sec_ejec   and
	 	mes_proceso  = @as_mes        and
	 	almacen      = @as_almacen    and
	 	sec_almacen  = @as_sec_alma   and
	 	tipo_bien    = @ls_tipo_bien  and
	 	codigo_bien  = @ls_codi_bien  and
	 	marca        = @ld_marca      and
	 	clasificador = @ls_clas_gast  and
	 	mayor        = @ls_plan_mayor and
	 	sub_cta      = @ls_plan_subcta and
	 	tipo_uso     = @as_tipo_uso   and
	 	tipo_ppto    = @ai_tipo_ppto  and
	 	secuencia    = @an_encargo    and
		unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and item_bien_det is null) or
		 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

	set @ld_temp = @@rowcount
	If (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al capturar los datos del kardex :'
		return -1
	end

	IF (@ld_temp = 0)
	begin
		set @ldec_pp2= 0
		set @ldec_sa = 0
		set @ldec_sa2= 0
		set @ldec_va = 0
		set @ldec_va2= 0
		set @ldec_pu = 0
		set @ldec_vt = 0
		set @ldec_pp = 0
	end

	If (@ldec_tsti = 0)
		set @ldec_pp2 = 0
	Else
		set @ldec_pp2 = round(@ldec_tsai / @ldec_tsti,6)
		
	set @li_count= 0
	set @ldec_tc = 0
	set @ldec_tpu= 0
	set @ldec_tvt= 0
	set @ldec_tsa= 0
	set @ldec_tva= 0
	set @ldec_tpp= 0

	-- upd sig_detalle_movim_almacen ********************************
	-- get inout for item_bien since ad_fech_movi
	DECLARE cdetmov_intervalo_in_out CURSOR FOR
	SELECT d.fecha_movimto, d.tipo_movimto,
	       d.tipo_transac,  d.nro_movimto,   d.secuencia,
	       d.sec_detalle,   d.cant_articulo, d.precio_unit,
	       d.valor_total,   d.stock_actual,  d.valor_actual,
	       d.precio_promed
	  FROM sig_detalle_movim_almacen d,
	       sig_movim_almacen m
	 WHERE d.ano_eje      = m.ano_eje  and
	       d.sec_ejec     = m.sec_ejec and
	       d.almacen      = m.almacen  and
	       d.sec_almacen  = m.sec_almacen  and
	       d.tipo_movimto = m.tipo_movimto and
	       d.tipo_transac = m.tipo_transac and
	       d.tipo_ppto    = m.tipo_ppto    and
	       d.nro_movimto  = m.nro_movimto  and
	       m.estado_kardex= 'S' and
	       d.ano_eje      = @an_ano_eje  and
	       d.sec_ejec     = @an_sec_ejec and
	       d.mes_proceso  = @as_mes      and
	       d.almacen      = @as_almacen  and
	       d.sec_almacen  = @as_sec_alma and
	       d.tipo_movimto in ('A','I','S')  and
	       d.tipo_bien    = @ls_tipo_bien   and
	       d.grupo_bien   = @ls_grupo_bien  and
	       d.clase_bien   = @ls_clase_bien  and
	       d.familia_bien = @ls_fami_bien   and
	       d.item_bien    = @ls_item_bien   and
	       d.marca        = @ld_marca       and
	       m.tipo_uso     = @as_tipo_uso    and
	       m.tipo_ppto    = @ai_tipo_ppto   and	
	       ((@ai_tipo_ppto = 1) or
	        (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	       d.fecha_movimto >= @ad_fech_movi  and
	       d.cant_articulo >= 0 and
	       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
	        (@ls_kardex_clasif = 'N')) and
	       d.mayor          = @ls_plan_mayor and
	       d.sub_cta        = @ls_plan_subcta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
	       order by d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
	                d.secuencia, d.sec_detalle

	OPEN cdetmov_intervalo_in_out
	FETCH NEXT FROM cdetmov_intervalo_in_out INTO @ld_fech_movi, @ls_tipo_movi, @li_tipo_tran, @li_nro_movi,
							@li_secuencia, @li_sec_detalle, @ldec_tc, @ldec_tpu,
							@ldec_tvt, @ldec_tsa, @ldec_tva, @ldec_tpp
	WHILE @@FETCH_STATUS = 0
	BEGIN
		set @li_count = @li_count + 1

		--for other case get values of preview detmov record
		DECLARE cpreview CURSOR FOR
		SELECT d.fecha_movimto, d.tipo_movimto,
		       d.tipo_transac,  d.nro_movimto,   d.secuencia,
		       d.sec_detalle,   d.cant_articulo, d.precio_unit,
		       d.valor_total,   d.stock_actual,  d.valor_actual,
		       d.precio_promed
		  FROM sig_detalle_movim_almacen d,
		       sig_movim_almacen m
		 WHERE d.ano_eje      = m.ano_eje  and
		       d.sec_ejec     = m.sec_ejec and
		       d.almacen      = m.almacen  and
		       d.sec_almacen  = m.sec_almacen  and
		       d.tipo_movimto = m.tipo_movimto and
		       d.tipo_transac = m.tipo_transac and
		       d.tipo_ppto    = m.tipo_ppto    and
		       d.nro_movimto  = m.nro_movimto  and
		       m.estado_kardex= 'S' and
		       d.ano_eje      = @an_ano_eje  and
		       d.sec_ejec     = @an_sec_ejec and
		       d.mes_proceso  = @as_mes      and
		       d.almacen      = @as_almacen  and
		       d.sec_almacen  = @as_sec_alma and
		       d.tipo_movimto in ('A','I','S')  and
		       d.tipo_bien    = @ls_tipo_bien   and
		       d.grupo_bien   = @ls_grupo_bien  and
		       d.clase_bien   = @ls_clase_bien  and
		       d.familia_bien = @ls_fami_bien   and
		       d.item_bien    = @ls_item_bien   and
		       d.marca        = @ld_marca       and
		       m.tipo_uso     = @as_tipo_uso    and
		       m.tipo_ppto    = @ai_tipo_ppto   and
		       ((@ai_tipo_ppto = 1) or
		        (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
		       d.fecha_movimto <= @ld_fech_movi  and
		       d.cant_articulo >= 0 and
		       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
		        (@ls_kardex_clasif = 'N')) and
		       d.mayor          = @ls_plan_mayor and
		       d.sub_cta        = @ls_plan_subcta and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		       order by d.fecha_movimto desc, d.fecha_reg desc, d.tipo_movimto, d.tipo_transac,
		                d.nro_movimto, d.secuencia, d.sec_detalle
		--		 d.fecha_movimto < ld_fech_movi  and


		OPEN cpreview
		FETCH NEXT FROM cpreview INTO @ldt_fech_movi2, @ls_tipo_movi2, 
					  @li_tipo_tran2, @li_nro_movi2, @li_secuencia2, @li_sec_deta2, 
					  @ldec_c2, @ldec_pu2, @ldec_vt2, @ldec_sa3, @ldec_va3, @ldec_pp3
		set @li_code = @@rowcount
		CLOSE cpreview
		DEALLOCATE cpreview

		If (@li_code > 0)
		begin
			IF (@ls_tipo_movi = 'A')
			begin
				set @ldec_pu = @ldec_tpu
				set @ldec_vt = @ldec_tvt
				set @ldec_sa = @ldec_tc + @ldec_sa2
				set @ldec_va = @ldec_vt + @ldec_va2
				set @ldec_pp = @ldec_pu
			END
			IF (@ls_tipo_movi = 'I')
			begin
				set @ldec_pu = @ldec_tpu
				set @ldec_vt = round(@ldec_tc * @ldec_pu,2)
				set @ldec_sa = @ldec_tc + @ldec_sa2
				set @ldec_va = @ldec_vt + @ldec_va2
				set @ldec_pp = round(@ldec_va / @ldec_sa,6)
			END
			IF (@ls_tipo_movi = 'S')
			begin
				set @ldec_pu = @ldec_pp2
				set @ldec_vt = round(@ldec_tc * @ldec_pp2,2)
				set @ldec_sa = @ldec_sa2 - @ldec_tc
				set @ldec_va = @ldec_va2 - @ldec_vt
				set @ldec_pp = @ldec_pp2
			END

			set @ldec_pp2 = @ldec_pp

		end
		Else
		begin
			-- if not exist a older record than this one then init values with the same
			if ((@ls_tipo_movi = 'A' and @li_tipo_tran = 1) or @li_count = 1) 
			Begin
				set @ldec_pu = @ldec_tpu
				set @ldec_vt = @ldec_tvt
				set @ldec_sa = @ldec_tsa
				set @ldec_va = @ldec_tvt
				set @ldec_pp = @ldec_tpu
			End
		end
		--init values for next record
		set @ldec_pu2 = @ldec_pu
		set @ldec_vt2 = @ldec_vt
		set @ldec_sa2 = @ldec_sa
		set @ldec_va2 = @ldec_va
		set @ldec_pp2 = @ldec_pp

		update sig_detalle_movim_almacen
		   set precio_unit  = @ldec_pu, valor_total  = @ldec_vt, stock_actual = @ldec_sa,
		       valor_actual = @ldec_va, precio_promed= @ldec_pp
		 where ano_eje      = @an_ano_eje   and
		       sec_ejec     = @an_sec_ejec  and
		       almacen      = @as_almacen   and
		       sec_almacen  = @as_sec_alma  and
		       tipo_movimto = @ls_tipo_movi and
		       tipo_transac = @li_tipo_tran and
		       tipo_ppto    = @ai_tipo_ppto and
		       nro_movimto  = @li_nro_movi  and
		       secuencia    = @li_secuencia and
		       sec_detalle  = @li_sec_detalle 

		IF (@@error <> 0)
		begin
			close cdetmov_intervalo_in_out
			close cbucle_generico
			DEALLOCATE cdetmov_intervalo_in_out
			DEALLOCATE cbucle_generico
			set @as_message = 'Error al actualizar detalle de almacén :'
			return -1
		End

		FETCH NEXT FROM cdetmov_intervalo_in_out INTO @ld_fech_movi, @ls_tipo_movi, @li_tipo_tran, @li_nro_movi,
								@li_secuencia, @li_sec_detalle, @ldec_tc, @ldec_tpu,
								@ldec_tvt, @ldec_tsa, @ldec_tva, @ldec_tpp
	END
	CLOSE cdetmov_intervalo_in_out
	DEALLOCATE cdetmov_intervalo_in_out

	-- upd sig_kardex_por_almacen 
	-- get final values from sig_detalle_movim_almacen
	set @ldec_ncant = 0
	set @ldec_nprecunit = 0
	set @ldec_nvalo = 0
	set @ldec_icant = 0
	set @ldec_ivalo = 0
	set @ldec_scant = 0
	set @ldec_svalo = 0

	SELECT @ldec_ncant = d.cant_articulo, @ldec_nprecunit = d.precio_unit, @ldec_nvalo = d.valor_total
	  FROM sig_detalle_movim_almacen d,
	       sig_movim_almacen m
	 WHERE d.ano_eje      = m.ano_eje  and
	       d.sec_ejec     = m.sec_ejec and
	       d.almacen      = m.almacen  and
	       d.sec_almacen  = m.sec_almacen  and
	       d.tipo_movimto = m.tipo_movimto and
	       d.tipo_transac = m.tipo_transac and
	       d.tipo_ppto    = m.tipo_ppto    and
	       d.nro_movimto  = m.nro_movimto  and
	       d.ano_eje      = @an_ano_eje   and
	       d.sec_ejec     = @an_sec_ejec  and
	       d.almacen      = @as_almacen   and
	       d.sec_almacen  = @as_sec_alma  and
	       d.tipo_movimto = 'A'           and
	       d.tipo_transac = 1             and
	       d.tipo_bien    = @ls_tipo_bien and
	       d.grupo_bien   = @ls_grupo_bien and
	       d.clase_bien   = @ls_clase_bien and
	       d.familia_bien = @ls_fami_bien and
	       d.item_bien    = @ls_item_bien and
	       d.marca        = @ld_marca     and
	       d.mes_proceso  = @as_mes       and
	       m.tipo_ppto    = @ai_tipo_ppto and
	       ((@ai_tipo_ppto = 1) or
	        (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	       m.tipo_uso     = @as_tipo_uso  and
	       d.cant_articulo >= 0 and
	       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
	        (@ls_kardex_clasif = 'N')) and
	       d.mayor          = @ls_plan_mayor  and
	       d.sub_cta        = @ls_plan_subcta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al leer los valores Iniciales : '
		return -1
	End

	SELECT @ldec_icant = sum(d.cant_articulo), @ldec_ivalo = sum(d.valor_total)
	  FROM sig_detalle_movim_almacen d,
	       sig_movim_almacen m
	 WHERE d.ano_eje      = m.ano_eje  and
	       d.sec_ejec     = m.sec_ejec and
	       d.almacen      = m.almacen  and
	       d.sec_almacen  = m.sec_almacen  and
	       d.tipo_movimto = m.tipo_movimto and
	       d.tipo_transac = m.tipo_transac and
	       d.tipo_ppto    = m.tipo_ppto    and
	       d.nro_movimto  = m.nro_movimto  and
	       m.estado_kardex= 'S' and
	       d.ano_eje      = @an_ano_eje   and
	       d.sec_ejec     = @an_sec_ejec  and
	       d.almacen      = @as_almacen   and
	       d.sec_almacen  = @as_sec_alma  and
	       d.tipo_movimto = 'I'           and
	       d.tipo_bien    = @ls_tipo_bien and
	       d.grupo_bien   = @ls_grupo_bien and
	       d.clase_bien   = @ls_clase_bien and
	       d.familia_bien = @ls_fami_bien and
	       d.item_bien    = @ls_item_bien and
	       d.marca        = @ld_marca     and
	       d.mes_proceso  = @as_mes       and
	       m.tipo_ppto    = @ai_tipo_ppto and
	       ((@ai_tipo_ppto = 1) or
	        (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	       m.tipo_uso     = @as_tipo_uso  and
	       d.cant_articulo >= 0 and
	       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
	        (@ls_kardex_clasif = 'N')) and
	       d.mayor          = @ls_plan_mayor  and
	       d.sub_cta        = @ls_plan_subcta and
		   d.unidad_medida = @ld_unid_medi and
		   ((@ld_item_bien_det is null and d.item_bien_det is null) or
		    (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al leer los valores de Ingreso : '
		return -1
	End

	SELECT @ldec_scant = sum(d.cant_articulo), @ldec_svalo = sum(d.valor_total)
	  FROM sig_detalle_movim_almacen d,
	       sig_movim_almacen m
	 WHERE d.ano_eje      = m.ano_eje  and
	       d.sec_ejec     = m.sec_ejec and
	       d.almacen      = m.almacen  and
	       d.sec_almacen  = m.sec_almacen  and
	       d.tipo_movimto = m.tipo_movimto and
	       d.tipo_transac = m.tipo_transac and
	       d.tipo_ppto    = m.tipo_ppto    and
	       d.nro_movimto  = m.nro_movimto  and
	       m.estado_kardex= 'S' and
	       d.ano_eje      = @an_ano_eje   and
	       d.sec_ejec     = @an_sec_ejec  and
	       d.almacen      = @as_almacen   and
	       d.sec_almacen  = @as_sec_alma  and
	       d.tipo_movimto = 'S'           and
	       d.tipo_bien    = @ls_tipo_bien and
	       d.grupo_bien   = @ls_grupo_bien and
	       d.clase_bien   = @ls_clase_bien and
	       d.familia_bien = @ls_fami_bien and
	       d.item_bien    = @ls_item_bien and
	       d.marca        = @ld_marca     and
	       d.mes_proceso  = @as_mes       and
	       m.tipo_ppto    = @ai_tipo_ppto and
	       ((@ai_tipo_ppto = 1) or
	        (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	       m.tipo_uso     = @as_tipo_uso  and
	       d.cant_articulo >= 0 and
	       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
	        (@ls_kardex_clasif = 'N')) and
	       d.mayor          = @ls_plan_mayor  and
	       d.sub_cta        = @ls_plan_subcta and
		   d.unidad_medida = @ld_unid_medi and
		   ((@ld_item_bien_det is null and d.item_bien_det is null) or
		    (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al leer los valores de Salida : '
		return -1
	End

	set @ldec_ncant = isnull(@ldec_ncant, 0)
	set @ldec_nprecunit = isnull(@ldec_nprecunit, 0)
	set @ldec_nvalo = isnull(@ldec_nvalo, 0)
	set @ldec_icant = isnull(@ldec_icant, 0)
	set @ldec_scant = isnull(@ldec_scant, 0)
	set @ldec_ivalo = isnull(@ldec_ivalo, 0)
	set @ldec_svalo = isnull(@ldec_svalo, 0)

	If (@ldec_ncant = 0)
		set @ldec_nprecinve = 0
	Else
		set @ldec_nprecinve = @ldec_nprecunit

	UPDATE sig_kardex_por_almacen
	   SET stock_inicial = @ldec_ncant,
	       cant_ingreso  = @ldec_icant,
	       cant_egreso   = @ldec_scant,
	       stock_actual  = @ldec_ncant + @ldec_icant - @ldec_scant,
	       precio_invent = @ldec_nprecinve,
	       precio_promed = @ldec_pp,
	       saldo_inicial = @ldec_nvalo,
	       valor_ingreso = @ldec_ivalo,
	       valor_egreso  = @ldec_svalo,
	       saldo_valor   = @ldec_nvalo + @ldec_ivalo - @ldec_svalo
	 WHERE ano_eje     = @an_ano_eje    and
	       sec_ejec    = @an_sec_ejec   and
	       mes_proceso = @as_mes        and
	       almacen     = @as_almacen    and
	       sec_almacen = @as_sec_alma   and
	       tipo_bien   = @ls_tipo_bien  and
	       codigo_bien = @ls_codi_bien  and
	       marca       = @ld_marca      and
	       clasificador= @ls_clas_gast  and
	       mayor       = @ls_plan_mayor and
	       sub_cta     = @ls_plan_subcta and
	       tipo_ppto   = @ai_tipo_ppto  and
	       tipo_uso    = @as_tipo_uso   and
	       secuencia   = @an_encargo    and
		unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and item_bien_det is null) or
		 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

	set @ld_temp = @@rowcount

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al actualizar el Kardex : '
		return -1
	End

	IF (@ld_temp = 0)
	begin
		set @ls_correlativo = ''
		SELECT @ls_correlativo = max(correlativo)
		  FROM sig_kardex_por_almacen
		 WHERE ano_eje       = @an_ano_eje    and
			sec_ejec      = @an_sec_ejec   and
			mes_proceso   = @as_mes        and
			almacen       = @as_almacen    and
			sec_almacen   = @as_sec_alma   and
			tipo_bien     = @ls_tipo_bien  and
			codigo_bien   = @ls_codi_bien  and
			marca         = @ld_marca      and
			clasificador  = @ls_clas_gast  and
			mayor         = @ls_plan_mayor and
			sub_cta       = @ls_plan_subcta and
			tipo_uso      = @as_tipo_uso   and
			tipo_ppto     = @ai_tipo_ppto  and
			secuencia     = @an_encargo

		set @ls_correlativo = isnull(@ls_correlativo, '0')
		If (@ls_correlativo = '')
		   set @ls_correlativo = '0'
				 
		set @ls_correlativo = right('0000'+convert(varchar(4), @ls_correlativo*1 + 1),4)

		  INSERT INTO sig_kardex_por_almacen  
			( ano_eje,       sec_ejec,      mes_proceso,   
			  almacen,       sec_almacen,   tipo_bien,  codigo_bien, 
			  grupo_bien,    clase_bien,    familia_bien,   
			  item_bien,     tipo_marca,    marca,
			  clasificador,  mayor,         sub_cta,
			  tipo_uso,      tipo_ppto,     secuencia,
			  correlativo,   nro_encargo,
			  sec_ejec2,	  cant_invent,   cant_bueno,   
			  stock_inicial, cant_ingreso,  cant_egreso,   
			  stock_actual,  precio_promed, saldo_valor,   
			  valor_ingreso, valor_egreso,  saldo_inicial,   
			  stock_enero,   cons_enero,    precio_invent,
			  cuser_id,      fecha_reg,     equipo_reg,
			  unidad_medida, item_bien_det )  
		  VALUES (@an_ano_eje,    @an_sec_ejec,   @as_mes,   
			  @as_almacen,    @as_sec_alma,   @ls_tipo_bien, @ls_codi_bien,  
			  @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien,   
			  @ls_item_bien,  @ls_tipo_marc,  @ld_marca,
			  @ls_clas_gast,  @ls_plan_mayor, @ls_plan_subcta,
			  @as_tipo_uso,   @ai_tipo_ppto,  @an_encargo,
			  @ls_correlativo, @ld_encargo,
			  @ld_sec_ejec2,	0,              0,   
			  @ldec_ncant,    @ldec_icant,    @ldec_scant,   
			  @ldec_ncant + @ldec_icant - @ldec_scant, @ldec_pp, @ldec_nvalo + @ldec_ivalo - @ldec_svalo,   
			  @ldec_ivalo,    @ldec_svalo,    @ldec_nvalo,   
			  0,              0,              @ldec_nprecinve,
			  @as_usuing,     @adt_fecha_actual, @as_equipo,
			  @ld_unid_medi,  @ld_item_bien_det )  

		IF (@@error <> 0)
		begin
			close cbucle_generico
			DEALLOCATE cbucle_generico
			set @as_message = 'Error al insertar en el Kardex : '
			return -1
		End
	End
	FETCH NEXT FROM cbucle_generico INTO @ls_tipo_bien, @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien,
						@ls_item_bien, @ld_marca, @ld_encargo, @ld_sec_ejec2,
						@ls_clas_gast, @ls_plan_mayor, @ls_plan_subcta, @ls_tipo_marc,
						@ld_unid_medi, @ld_item_bien_det
END
CLOSE cbucle_generico
DEALLOCATE cbucle_generico

-- actualizar flag de ingreso de kardex  en movim de almacen
 UPDATE sig_movim_almacen
    SET estado_kardex = 'S'
  WHERE ano_eje  = @an_ano_eje  and
	sec_ejec = @an_sec_ejec and
	almacen  = @as_almacen  and
	sec_almacen  = @as_sec_alma  and
	tipo_movimto = @as_tipo_movi and
	tipo_transac = @ai_tipo_tran and
	tipo_ppto    = @ai_tipo_ppto and
	nro_movimto  = @an_nro_movi 

IF (@@error <> 0)
begin
	set @as_message = 'Error al actualizar el estado Kardex: '
	return -1
End

set @as_message = 'Concluyó conforme : '

Return 1
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CALCULO_FORMULA_MULTI
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CALCULO_FORMULA_MULTI]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CALCULO_FORMULA_MULTI]
GO

CREATE PROCEDURE [dbo].[SP_SI_CALCULO_FORMULA_MULTI]
	@Ano_eje    			NUMERIC(4,0),
    @SubFin   				VARCHAR(7),
    @IdSubFin				NUMERIC(10,0)
  
AS

BEGIN 
	update sig_ppr_kit_items_EST
	set cantidad = (1 + FACTOR_MERMA) * ((CANTIDAD_CASO * PORCENT_USO / 100) / FACTOR_CONVERS )
	where FACTOR_CONVERS > 0
     and  TIPO_CALCULO   in (4,8)            
	  and TIPO_BIEN = 'B'
	  and ano_eje = @Ano_eje
	  and sub_finalidad = @SubFin
                  AND ID_SUB_FINALIDAD = @IdSubFin 

update sig_ppr_kit_items_EST
   set cantidad = 0
 where (FACTOR_CONVERS IS NULL 
    OR  FACTOR_CONVERS = 0
    OR  TIPO_CALCULO  not in (4,8))			
   and ano_eje = @Ano_eje
   and sub_finalidad = @SubFin
AND ID_SUB_FINALIDAD = @IdSubFin 

 update sig_ppr_kit_items_EST
 set cantidad = 0
 where cantidad IS NULL
and ano_eje = @Ano_eje
 and sub_finalidad = @SubFin
    AND ID_SUB_FINALIDAD = @IdSubFin 

END
GO


-- ----------------------------
-- procedure structure for SP_GENERACION_PAO_NE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERACION_PAO_NE]') AND type IN ('P', 'PC', 'RF', 'X'))
