	INSERT #TMP_SIG_PAAC_ITEM    
	  (ANO_EJE,   SEC_EJEC,  TIPO_CONSOLID, NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,    
	   SEC_CONSOLID, GRUPO_BIEN,    CLASE_BIEN,   FAMILIA_BIEN,    ITEM_BIEN,    
	   MES_01,   	MES_02, 		MES_03,        MES_04,      MES_05,       MES_06,    
	   MES_07,  	MES_08,         MES_09,        MES_10,      MES_11,       MES_12,    
	   CANTIDAD, 	CANTIDAD_ANNO_01, CANTIDAD_ANNO_02, CANTIDAD_ANNO_03, UNIDAD_MEDIDA, FECHA_PRECIO, 
	   MONEDA,      TIPO_CAMBIO,      PRECIO_UNIT,  	VALOR, 			  VALOR_ANNO_01, VALOR_ANNO_02, 
	   VALOR_ANNO_03,PRECIO_MONEDA,   VALOR_MONEDA, 	FECHA_REG,   	  CUSER_ID,      CANTIDAD_USO,    
	   UNIDAD_USO,   PRECIO_USO, 	  FACTOR_UNIDAD, 	MES_01_ANNO_01,   MES_02_ANNO_01,MES_03_ANNO_01 ,    
 	   MES_04_ANNO_01, MES_05_ANNO_01,	MES_06_ANNO_01, MES_07_ANNO_01, MES_08_ANNO_01 , MES_09_ANNO_01,    
 	   MES_10_ANNO_01 ,MES_11_ANNO_01,  MES_12_ANNO_01, MES_01_ANNO_02, MES_02_ANNO_02 , MES_03_ANNO_02,  
   	   MES_04_ANNO_02, MES_05_ANNO_02,	MES_06_ANNO_02, MES_07_ANNO_02, MES_08_ANNO_02 , MES_09_ANNO_02,    
 	   MES_10_ANNO_02, MES_11_ANNO_02,  MES_12_ANNO_02, MES_01_ANNO_03, MES_02_ANNO_03 , MES_03_ANNO_03,  
   	   MES_04_ANNO_03, MES_05_ANNO_03,	MES_06_ANNO_03, MES_07_ANNO_03, MES_08_ANNO_03 , MES_09_ANNO_03,    
 	   MES_10_ANNO_03, MES_11_ANNO_03,  MES_12_ANNO_03 ) 
	SELECT @PN_ANIO, @PN_EJECUTORA, '1' TIPO_CONSOLID, @PN_NRO_PAO, @ps_tipo_generacion,     
	       D.TIPO_BIEN, 1 as SEC_CONSOLID,     
	       D.GRUPO_BIEN,       
	       D.CLASE_BIEN,       
	       D.FAMILIA_BIEN,       
	       D.ITEM_BIEN,                    
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.CANT_01 else 0 END) else 0 end as cant_01,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.CANT_02 else 0 END) else 0 end as cant_02,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.CANT_03 else 0 END) else 0 end as cant_03,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.CANT_04 else 0 END) else 0 end as cant_04,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.CANT_05 else 0 END) else 0 end as cant_05,       
