	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO_01 = '1' THEN D.CANT_05_ANNO_01 else 0 END) else 0 end as cant_05_anno_01,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO_01 = '1' THEN D.CANT_06_ANNO_01 else 0 END) else 0 end as cant_06_anno_01,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO_01 = '1' THEN D.CANT_07_ANNO_01 else 0 END) else 0 end as cant_07_anno_01,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_01 = '1' THEN D.CANT_08_ANNO_01 else 0 END) else 0 end as cant_08_anno_01,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO_01 = '1' THEN D.CANT_09_ANNO_01 else 0 END) else 0 end as cant_09_anno_01,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_01 = '1' THEN D.CANT_10_ANNO_01 else 0 END) else 0 end as cant_10_anno_01,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_01 = '1' THEN D.CANT_11_ANNO_01 else 0 END) else 0 end as cant_11_anno_01,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_01 = '1' THEN D.CANT_12_ANNO_01 else 0 END) else 0 end as cant_12_anno_01,   
	       
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_02 = '1' THEN D.CANT_01_ANNO_02 else 0 END) else 0 END as cant_01_anno_02,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO_02 = '1' THEN D.CANT_02_ANNO_02 else 0 END) else 0 end as cant_02_anno_02,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO_02 = '1' THEN D.CANT_03_ANNO_02 else 0 END) else 0 end as cant_03_anno_02,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO_02 = '1' THEN D.CANT_04_ANNO_02 else 0 END) else 0 end as cant_04_anno_02,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO_02 = '1' THEN D.CANT_05_ANNO_02 else 0 END) else 0 end as cant_05_anno_02,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO_02 = '1' THEN D.CANT_06_ANNO_02 else 0 END) else 0 end as cant_06_anno_02,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO_02 = '1' THEN D.CANT_07_ANNO_02 else 0 END) else 0 end as cant_07_anno_02,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_02 = '1' THEN D.CANT_08_ANNO_02 else 0 END) else 0 end as cant_08_anno_02,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO_02 = '1' THEN D.CANT_09_ANNO_02 else 0 END) else 0 end as cant_09_anno_02,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_02 = '1' THEN D.CANT_10_ANNO_02 else 0 END) else 0 end as cant_10_anno_02,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_02 = '1' THEN D.CANT_11_ANNO_02 else 0 END) else 0 end as cant_11_anno_02,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_02 = '1' THEN D.CANT_12_ANNO_02 else 0 END) else 0 end as cant_12_anno_02,   
	       
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_03 = '1' THEN D.CANT_01_ANNO_03 else 0 END) else 0 END as cant_01_anno_03,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO_03 = '1' THEN D.CANT_02_ANNO_03 else 0 END) else 0 end as cant_02_anno_03,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO_03 = '1' THEN D.CANT_03_ANNO_03 else 0 END) else 0 end as cant_03_anno_03,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO_03 = '1' THEN D.CANT_04_ANNO_03 else 0 END) else 0 end as cant_04_anno_03,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO_03 = '1' THEN D.CANT_05_ANNO_03 else 0 END) else 0 end as cant_05_anno_03,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO_03 = '1' THEN D.CANT_06_ANNO_03 else 0 END) else 0 end as cant_06_anno_03,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO_03 = '1' THEN D.CANT_07_ANNO_03 else 0 END) else 0 end as cant_07_anno_03,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_03 = '1' THEN D.CANT_08_ANNO_03 else 0 END) else 0 end as cant_08_anno_03,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO_03 = '1' THEN D.CANT_09_ANNO_03 else 0 END) else 0 end as cant_09_anno_03,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_03 = '1' THEN D.CANT_10_ANNO_03 else 0 END) else 0 end as cant_10_anno_03,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_03 = '1' THEN D.CANT_11_ANNO_03 else 0 END) else 0 end as cant_11_anno_03,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_03 = '1' THEN D.CANT_12_ANNO_03 else 0 END) else 0 end as cant_12_anno_03      
	      
	FROM SIG_CUADRO_NECESIDAD C,       
	     SIG_CUADRO_NECESIDAD_DET D ,    
	     CATALOGO_BIEN_SERV S    
	WHERE D.ANO_EJE   	= @PN_ANIO  AND      
	      D.SEC_EJEC    = @PN_EJECUTORA  AND   
	      EXISTS(select CENTRO_COSTO from tmp_parametros_pao 
	      		  where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND centro_costo = D.CENTRO_COSTO  )   AND
	        
	      EXISTS(select TIPO_TAREA from tmp_parametros_pao 
	      		  where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO AND
	      		        TIPO_TAREA = C.TIPO_TAREA AND
	      		 		CODIGO_TAREA = C.CODIGO_TAREA and
						tipo_uso = C.tipo_uso) AND
	      ((D.FASE_CUADRO =  3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012)) AND    
	      D.TIPO_BIEN  = @PS_TIPO  AND   
	      
	      (  
	      EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
	      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
		  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
					ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
		  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
					ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
	       ) AND    
	      
	      D.ESTADO   = '5' AND      
	      
	      EXISTS(select FUENTE from tmp_parametros_pao 
	      		  where CODIGO = 3 and NRO_PAO = @PN_NRO_PAO AND Fuente = C.FUENTE_FINANC) AND
	       
	      EXISTS (select CLASIFICADOR from tmp_parametros_pao 
	      		  where CODIGO = 2 and NRO_PAO = @PN_NRO_PAO AND CLASIFICADOR = C.CLASIFICADOR) AND 
	       
	     EXISTS (select SEC_FUNC from tmp_parametros_pao 
	     		 where CODIGO = 4 and NRO_PAO = @PN_NRO_PAO AND SEC_FUNC = C.SEC_FUNC) AND
	
	      ( ( @ps_modal_compra = 'SI' AND S.FLAG_SUBASTA_INVERSA = '1' ) OR    
	        ( @ps_modal_compra = 'CP' AND S.BOLSA_PRODUCTO = '1' ) OR    
	        ( @ps_modal_compra = 'MP' AND S.FLAG_MARCO_PRECIO = 'S') OR    
	        ( @ps_modal_compra NOT IN ('SI','CP','MP') AND (S.FLAG_SUBASTA_INVERSA <> '1' or S.FLAG_SUBASTA_INVERSA is null ) AND (S.BOLSA_PRODUCTO <> '1' or S.BOLSA_PRODUCTO is  null ) AND (S.FLAG_MARCO_PRECIO <> 'S' or S.FLAG_MARCO_PRECIO is null) ) ) AND     
	        D.ANO_EJE  = C.ANO_EJE  and      
	        D.SEC_EJEC = C.SEC_EJEC  and      
	        D.CENTRO_COSTO = C.CENTRO_COSTO  and      
	        D.FASE_CUADRO  = C.FASE_CUADRO  and      
	        D.SECUENCIA    = C.SECUENCIA and 
	        D.estado_item_kit = 'A' and
	        S.SEC_EJEC = D.SEC_EJEC AND    
	        S.TIPO_BIEN = D.TIPO_BIEN AND    
	        S.GRUPO_BIEN = D.GRUPO_BIEN AND    
	        S.CLASE_BIEN = D.CLASE_BIEN AND    
	        S.FAMILIA_BIEN = D.FAMILIA_BIEN AND    
	        S.ITEM_BIEN = D.ITEM_BIEN    
	GROUP BY D.TIPO_BIEN,       
	         D.GRUPO_BIEN,       
	         D.CLASE_BIEN,       
	         D.FAMILIA_BIEN,       
	         D.ITEM_BIEN,    
	         D.UNIDAD_MEDIDA   
	      
	IF @@ROWCOUNT = 0    
	   RETURN

	INSERT #TMP_SIG_PAAC_METAS    
	 ( ANO_EJE, SEC_EJEC, TIPO_CONSOLID,  NRO_CONSOLID, TIPO_GENERACION, TIPO_BIEN,    
	   SEC_CONSOLID, SEC_RESUMEN, SEC_FUNC,  ORIGEN,    FUENTE_FINANC, TIPO_RECURSO,  
	   CLASIFICADOR, MES_01,  	MES_02,   MES_03,    MES_04,   MES_05,    
	   MES_06,   	 MES_07,  	MES_08,   MES_09,    MES_10,   MES_11,    
	   MES_12,   	 CANTIDAD, 	CANTIDAD_ANNO_01, CANTIDAD_ANNO_02, CANTIDAD_ANNO_03, 
	   VALOR,    	 VALOR_ANNO_01, VALOR_ANNO_02, VALOR_ANNO_03, 	TIPO_IMPTO,   FTE_FTO_IMPTO, 
	   TASA_IMPTO,VALOR_IMPTO, VALOR_MONEDA, VALOR_IMPTO_MONEDA, FECHA_REG,  CUSER_ID ,
	   MES_01_ANNO_01, MES_02_ANNO_01,  MES_03_ANNO_01, MES_04_ANNO_01, MES_05_ANNO_01, MES_06_ANNO_01,   
 	   MES_07_ANNO_01, MES_08_ANNO_01,  MES_09_ANNO_01, MES_10_ANNO_01 ,MES_11_ANNO_01, MES_12_ANNO_01,     
 	   MES_01_ANNO_02, MES_02_ANNO_02 , MES_03_ANNO_02, MES_04_ANNO_02, MES_05_ANNO_02,	MES_06_ANNO_02,   
   	   MES_07_ANNO_02, MES_08_ANNO_02 , MES_09_ANNO_02, MES_10_ANNO_02, MES_11_ANNO_02, MES_12_ANNO_02,    
 	   MES_01_ANNO_03, MES_02_ANNO_03 , MES_03_ANNO_03, MES_04_ANNO_03, MES_05_ANNO_03,	MES_06_ANNO_03,  
   	   MES_07_ANNO_03, MES_08_ANNO_03 , MES_09_ANNO_03, MES_10_ANNO_03, MES_11_ANNO_03, MES_12_ANNO_03 )   
 	       
	SELECT @PN_ANIO, @PN_EJECUTORA, '1', @PN_NRO_PAO, @ps_tipo_generacion, @PS_TIPO,     
	       '1', sec_resumen1, C.sec_func AS sec_func,    
	       C.origen  as origen,    
	       C.fuente_financ as fuente_financ,    
	       '1'  as tipo_recurso,    
	       C.clasificador  as clasificador,    	       
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.CANT_01 else 0 END) else 0 end as cant_01,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.CANT_02 else 0 END) else 0 end as cant_02,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.CANT_03 else 0 END) else 0 end as cant_03,       
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.CANT_04 else 0 END) else 0 end as cant_04,       
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.CANT_05 else 0 END) else 0 end as cant_05,       
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.CANT_06 else 0 END) else 0 end as cant_06,       
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.CANT_07 else 0 END) else 0 end as cant_07,       
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.CANT_08 else 0 END) else 0 end as cant_08,       
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.CANT_09 else 0 END) else 0 end as cant_09,       
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.CANT_10 else 0 END) else 0 end as cant_10,       
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.CANT_11 else 0 END) else 0 end as cant_11,       
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.CANT_12 else 0 END) else 0 end as cant_12,	       	      	            
	       sum(case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO = '1' THEN D.CANT_01 ELSE 0 end) else 0 end +    
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO = '1' THEN D.CANT_02 else 0 END) else 0 end +    
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN THEN (CASE WHEN D.FLG_MNTO_03_ANNO = '1' THEN D.CANT_03 else 0 END) else 0 end +    
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO = '1' THEN D.CANT_04 else 0 END) else 0 end +    
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO = '1' THEN D.CANT_05 else 0 END) else 0 end +    
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO = '1' THEN D.CANT_06 else 0 END) else 0 end +    
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO = '1' THEN D.CANT_07 else 0 END) else 0 end +    
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO = '1' THEN D.CANT_08 else 0 END) else 0 end +    
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO = '1' THEN D.CANT_09 else 0 END) else 0 end +    
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO = '1' THEN D.CANT_10 else 0 END) else 0 end +    
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO = '1' THEN D.CANT_11 else 0 END) else 0 end +    
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO = '1' THEN D.CANT_12 else 0 END) else 0 end) - sum(D.STOCK_ASIG) CANTIDAD,   
	    
	       sum(case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO_01 = '1' THEN D.CANT_01_ANNO_01 ELSE 0 end) else 0 end +    
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO_01 = '1' THEN D.CANT_02_ANNO_01 else 0 END) else 0 end +    
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN THEN (CASE WHEN D.FLG_MNTO_03_ANNO_01 = '1' THEN D.CANT_03_ANNO_01 else 0 END) else 0 end +    
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO_01 = '1' THEN D.CANT_04_ANNO_01 else 0 END) else 0 end +    
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO_01 = '1' THEN D.CANT_05_ANNO_01 else 0 END) else 0 end +    
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO_01 = '1' THEN D.CANT_06_ANNO_01 else 0 END) else 0 end +    
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO_01 = '1' THEN D.CANT_07_ANNO_01 else 0 END) else 0 end +    
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO_01 = '1' THEN D.CANT_08_ANNO_01 else 0 END) else 0 end +    
	       case when 9 >= @PS_MES_INI and 9 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_09_ANNO_01 = '1' THEN D.CANT_09_ANNO_01 else 0 END) else 0 end +    
	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_10_ANNO_01 = '1' THEN D.CANT_10_ANNO_01 else 0 END) else 0 end +    
	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_11_ANNO_01 = '1' THEN D.CANT_11_ANNO_01 else 0 END) else 0 end +    
	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_12_ANNO_01 = '1' THEN D.CANT_12_ANNO_01 else 0 END) else 0 end) - sum(D.STOCK_ASIG) CANTIDAD_ANNO_01,   
	     
	       sum(case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_01_ANNO_02 = '1' THEN D.CANT_01_ANNO_02 ELSE 0 end) else 0 end +    
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_02_ANNO_02 = '1' THEN D.CANT_02_ANNO_02 else 0 END) else 0 end +    
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN THEN (CASE WHEN D.FLG_MNTO_03_ANNO_02 = '1' THEN D.CANT_03_ANNO_02 else 0 END) else 0 end +    
	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_04_ANNO_02 = '1' THEN D.CANT_04_ANNO_02 else 0 END) else 0 end +    
	       case when 5 >= @PS_MES_INI and 5 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_05_ANNO_02 = '1' THEN D.CANT_05_ANNO_02 else 0 END) else 0 end +    
	       case when 6 >= @PS_MES_INI and 6 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_06_ANNO_02 = '1' THEN D.CANT_06_ANNO_02 else 0 END) else 0 end +    
	       case when 7 >= @PS_MES_INI and 7 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_07_ANNO_02 = '1' THEN D.CANT_07_ANNO_02 else 0 END) else 0 end +    
	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then (CASE WHEN D.FLG_MNTO_08_ANNO_02 = '1' THEN D.CANT_08_ANNO_02 else 0 END) else 0 end +    
