	       case when 11 >= @PS_MES_INI and 11 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_11_ANNO_01 = '1' THEN COALESCE(D.CANT_11_ANNO_01,0) else 0 END) else 0 end as cant_11_anno_01,       
