	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_02 = '1' THEN COALESCE(D.CANT_01_ANNO_02,0) else 0 END) else 0 END as cant_01_anno_02,       
	       case when 2 >= @PS_MES_INI and 2 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_02_ANNO_02 = '1' THEN COALESCE(D.CANT_02_ANNO_02,0) else 0 END) else 0 end as cant_02_anno_02,       
	       case when 3 >= @PS_MES_INI and 3 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_03_ANNO_02 = '1' THEN COALESCE(D.CANT_03_ANNO_02,0) else 0 END) else 0 end as cant_03_anno_02,       
