	       case when 8 >= @PS_MES_INI and 8 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_08_ANNO_02 = '1' THEN COALESCE(D.CANT_08_ANNO_02,0) else 0 END) else 0 end as cant_08_anno_02,       
