	       case when 10 >= @PS_MES_INI and 10 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_10_ANNO_02 = '1' THEN COALESCE(D.CANT_10_ANNO_02,0) else 0 END) else 0 end as cant_10_anno_02,       
