	       case when 12 >= @PS_MES_INI and 12 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_12_ANNO_02 = '1' THEN COALESCE(D.CANT_12_ANNO_02,0) else 0 END) else 0 end as cant_12_anno_02,   
	       
	       case when 1 >= @PS_MES_INI and 1 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_01_ANNO_03 = '1' THEN COALESCE(D.CANT_01_ANNO_03,0) else 0 END) else 0 END as cant_01_anno_03,       
