	       case when 4 >= @PS_MES_INI and 4 <= @PS_MES_FIN then sum(CASE WHEN D.FLG_MNTO_04_ANNO_03 = '1' THEN COALESCE(D.CANT_04_ANNO_03,0) else 0 END) else 0 end as cant_04_anno_03,       
