				TIPO_CONSOLID = '1' AND    
				NRO_CONSOLID = @PN_NRO_PAO AND    
				TIPO_GENERACION = @ps_tipo_generacion and cantidad > 0
		     
			IF @@ERROR <> 0    
			   GOTO ERROR    
		    
		UPDATE SIG_PAAC_METAS SET VALOR = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,    
		                          VALOR_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN VALOR WHEN tipo_impto = 1 then VALOR / ((tasa_impto / 100) + 1) WHEN tipo_impto > 1 THEN VALOR - (VALOR * (tasa_impto / 100)) END,    
		                          VALOR_IMPTO = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END,    
		                          VALOR_IMPTO_MONEDA = CASE WHEN TIPO_IMPTO = 0 THEN 0 WHEN TIPO_IMPTO = 1 THEN VALOR - (VALOR / ((tasa_impto / 100) + 1)) WHEN TIPO_IMPTO > 1 THEN (VALOR * (tasa_impto / 100)) END    
		WHERE 
