		       MES_08 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_08 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07)) ELSE MES_08 END,    
		       MES_10 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_10 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09)) ELSE MES_10 END,    
		       MES_09 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_09 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08)) ELSE MES_09 END,    
		       MES_11 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_11 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10)) ELSE MES_11 END,    
		       MES_12 = CASE WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN 0 WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) THEN MES_12 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11)) ELSE MES_12 END    
		WHERE (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > CANTIDAD    AND
			   ANO_EJE 			= @PN_ANIO AND    
