			   TIPO_CONSOLID 	= '1' AND    
			   NRO_CONSOLID 	= @PN_NRO_PAO AND    
			   TIPO_GENERACION 	= @ps_tipo_generacion 

		IF @@ERROR <> 0    
		   GOTO ERROR    
           
            UPDATE SIG_PAAC_CENTRO_COSTO
            SET 
            FLAG_MES_01 =
                        (
                        CASE COALESCE(MES_01, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_02 =
                        (
                        CASE COALESCE(MES_02, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_03 =
                        (
                        CASE COALESCE(MES_03, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_04 =
                        (
                        CASE COALESCE(MES_04, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_05 =
                        (
                        CASE COALESCE(MES_05, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
           END
                        ),
            FLAG_MES_06 =
                        (
                        CASE COALESCE(MES_06, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_07 =
                        (
                        CASE COALESCE(MES_07, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_08 =
                        (
                        CASE COALESCE(MES_08, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_09 =
                        (
                        CASE COALESCE(MES_09, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_10 =
                        (
                        CASE COALESCE(MES_10, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_11 =
                        (
                        CASE COALESCE(MES_11, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        ),
            FLAG_MES_12 =
                        (
                        CASE COALESCE(MES_12, 0)
                        WHEN 0 THEN '0' 
                        ELSE '1' 
                        END
                        )
		WHERE  ANO_EJE 			= @PN_ANIO AND    
			   SEC_EJEC 		= @PN_EJECUTORA AND    
			   TIPO_CONSOLID 	= '1' AND    
			   NRO_CONSOLID 	= @PN_NRO_PAO AND    
			   TIPO_GENERACION 	= @ps_tipo_generacion 

		IF @@ERROR <> 0    
		   GOTO ERROR

        /* MPC - Issue 384 - Ampliación a 5 caracteres */
		DECLARE @pn_monto_total_item numeric(16,2), @ls_proc_selec VARCHAR(2), @ls_nume_plan VARCHAR(5)    
		DECLARE @pn_monto_total_item_val numeric(16,2)    
		     
		SELECT @pn_monto_total_item = SUM(coalesce(VALOR,0))     
		  from sig_paac_item    
		 where ano_eje  = @PN_ANIO  and    
			   sec_ejec = @PN_EJECUTORA  and    
			   tipo_consolid = @ls_tipo_cons  and    
			   nro_consolid  = @PN_NRO_PAO  and    
			   TIPO_GENERACION = @ps_tipo_generacion and    
			   TIPO_BIEN   = @PS_TIPO  
			   
		/*IF ( @pn_monto_total_item is null Or @pn_monto_total_item = 0 ) */
		IF ( @pn_monto_total_item = 0 )
		BEGIN
			set @pn_monto_total_item_val = 0.01
		END
		
		IF ( @pn_monto_total_item > 0 )
		BEGIN
			set @pn_monto_total_item_val = @pn_monto_total_item
		END
		
		SELECT @ls_proc_selec = CODIGO    
		  FROM SIG_TOPES_PROCESOS     
		 WHERE ANO_EJE   		= @PN_ANIO  AND      
		 	   TIPO_ORGANISMO 	= @ls_tipo_organismo AND    
		       TIPO_BIEN 		= @PS_TIPO AND    
		       FLAG  			= '1' AND    
		       CODIGO NOT IN ('33') AND
		       @pn_monto_total_item_val BETWEEN MONTO_MINIMO AND MONTO_MAXIMO   

	   		     
		IF @pn_monto_total_item_val > 0 AND @ls_proc_selec <> '14' -- Diferencia a menor cuantia (Antes 05)    
		BEGIN    
		     /*
		    select @ls_nume_plan = max(nro_paac)    
		      from sig_paac_consolidado    
		   where ano_eje  		 = @PN_ANIO  and    
			              sec_ejec 		 = @PN_EJECUTORA and    
			              tipo_consolid 	 = @ls_tipo_cons and    
			              TIPO_GENERACION = @ps_tipo_generacion AND    
			              flag_paac 		 = '1'    		     
            */

            SELECT @ls_nume_plan = MAX(CAST(nro_paac AS INT))
              FROM SIG_PAAC_CONSOLIDADO
            WHERE ANO_EJE                      = @PN_ANIO
                 AND SEC_EJEC                      = @PN_EJECUTORA
                 AND TIPO_CONSOLID       = @ls_tipo_cons
                 AND TIPO_GENERACION = @ps_tipo_generacion
                 AND flag_paac                     = '1'
                 AND coalesce(NRO_PAAC,' ') <>  ' '
		   
		   IF @ls_nume_plan is NULL
		      /* select @ls_nume_plan = '00001 */
		      select @ls_nume_plan = '00001'
		   ELSE
		      /* select @ls_nume_plan = right('0000' + ltrim(str(convert(int, @ls_nume_plan) + 1)),4) */    
		      select @ls_nume_plan = right('00000' + ltrim(str(convert(int, @ls_nume_plan) + 1)),5)
		           
		   UPDATE SIG_PAAC_CONSOLIDADO    
		   SET VALOR_PLAN   = @pn_monto_total_item,    
		       VALOR_MONEDA = @pn_monto_total_item,    
		       TIPO_PROCESO = @ls_proc_selec,     
		       FLAG_PAAC = '1',    NRO_PAAC = @ls_nume_plan ,    
		       UNIDAD_MEDIDA = 112, CONVOCACION_PROCESO = '0', PRECEDENTE = '0'    
		   WHERE ano_eje  		= @PN_ANIO  and    
		    	sec_ejec 		= @PN_EJECUTORA  and    
			    tipo_consolid 	= @ls_tipo_cons  and    
			    nro_consolid  	= @PN_NRO_PAO and    
			    TIPO_GENERACION = @ps_tipo_generacion    
		     
		    IF @@ERROR <> 0    
		       GOTO ERROR  
		END		
		
		IF @pn_monto_total_item_val > 0 AND @ls_proc_selec = '14'    
		   UPDATE SIG_PAAC_CONSOLIDADO    
		   SET VALOR_PLAN   = @pn_monto_total_item,    
		       VALOR_MONEDA = @pn_monto_total_item,    
		       TIPO_PROCESO = @ls_proc_selec,    
		       FLAG_PAAC = '0' ,  UNIDAD_MEDIDA = 112, CONVOCACION_PROCESO = '0', PRECEDENTE = '0'    
		   WHERE ano_eje  		= @PN_ANIO and    
		         sec_ejec 		= @PN_EJECUTORA and    
		         tipo_consolid 	= @ls_tipo_cons  and    
		         nro_consolid  	= @PN_NRO_PAO and    
		         TIPO_GENERACION = @ps_tipo_generacion    
		     
		   IF @@ERROR <> 0    
		   GOTO ERROR 

		If @PS_MODAL_COMPRA = 'MP'  
		BEGIN
		   set @ls_proc_selec = '26' 
		   UPDATE SIG_PAAC_CONSOLIDADO    
		   SET 
		       TIPO_PROCESO = @ls_proc_selec   
		   WHERE ano_eje  		= @PN_ANIO and    
		         sec_ejec 		= @PN_EJECUTORA and    
		         tipo_consolid 	= @ls_tipo_cons  and    
		         nro_consolid  	= @PN_NRO_PAO and    
		         TIPO_GENERACION = @ps_tipo_generacion    
		     
		   IF @@ERROR <> 0    
		   GOTO ERROR
		END
		     
		IF @PS_MES_INI = 1 and @PS_MES_FIN = 12     
		BEGIN    
		 
			update sig_cuadro_necesidaD_det    
			   set sig_cuadro_necesidad_det.estado = 6    
			  FROM SIG_CUADRO_necesidad C,       
			       SIG_CUADRO_necesidad_Det D ,    
			       CATALOGO_BIEN_SERV S    
			WHERE (D.ANO_EJE       = @PN_ANIO  AND      
			       D.SEC_EJEC      = @PN_EJECUTORA  AND      
			       ((D.FASE_CUADRO = 3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012))  AND    
			       D.TIPO_BIEN     = @PS_TIPO  AND      
			           
			       EXISTS(select CENTRO_COSTO from tmp_parametros_pao 
				   		  where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND  centro_costo = D.CENTRO_COSTO  )   AND
			       
			       EXISTS(select TIPO_TAREA from tmp_parametros_pao 
			       		   where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO AND
			      		    	     TIPO_TAREA = C.TIPO_TAREA AND CODIGO_TAREA = C.CODIGO_TAREA and
									 tipo_uso = C.tipo_uso) AND		                
	              (  
			       EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
			      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
				   EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
							ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
				   EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
							ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
				   ) AND			          
			                           
		            EXISTS(select FUENTE from tmp_parametros_pao 
		      	   	   	    where CODIGO = 3 and NRO_PAO = @PN_NRO_PAO AND Fuente = C.FUENTE_FINANC) AND  
				      
		      		EXISTS (select CLASIFICADOR from tmp_parametros_pao 
		      		  		where CODIGO = 2 and NRO_PAO = @PN_NRO_PAO AND CLASIFICADOR = C.CLASIFICADOR) AND 
				 
					EXISTS (select SEC_FUNC from tmp_parametros_pao 
				     		 where CODIGO = 4 and NRO_PAO = @PN_NRO_PAO AND SEC_FUNC = C.SEC_FUNC) AND				
					/*(D.CANT_TOTAL) > 0   AND*/
					(COALESCE(D.CANT_TOTAL, 0) + COALESCE(D.CANT_TOTAL_ANNO_01, 0) + COALESCE(D.CANT_TOTAL_ANNO_02, 0) + COALESCE(D.CANT_TOTAL_ANNO_03, 0)) > 0 and					
					 ( ( @ps_modal_compra = 'SI' AND S.FLAG_SUBASTA_INVERSA = '1' ) OR    
					 ( @ps_modal_compra = 'CP' AND S.BOLSA_PRODUCTO = '1' ) OR    
					 ( @ps_modal_compra = 'MP' AND S.FLAG_MARCO_PRECIO = 'S') OR    
					 ( @ps_modal_compra NOT IN ('SI','CP','MP') AND (S.FLAG_SUBASTA_INVERSA <> '1' or S.FLAG_SUBASTA_INVERSA is null ) AND (S.BOLSA_PRODUCTO <> '1' or  S.BOLSA_PRODUCTO is null ) AND (S.FLAG_MARCO_PRECIO <> 'S' or S.FLAG_MARCO_PRECIO is null) ) ) ) AND     
			      (  D.ANO_EJE  	= C.ANO_EJE  and      
			         D.SEC_EJEC 	= C.SEC_EJEC  and      
			         D.CENTRO_COSTO = C.CENTRO_COSTO  and      
			         D.fase_cuadro  = C.fase_cuadro  and      
			         D.SECUENCIA    = C.SECUENCIA  AND    
					 D.SEC_EJEC 	= S.SEC_EJEC AND    
					 D.TIPO_BIEN 	= S.TIPO_BIEN AND    
					 D.GRUPO_BIEN 	= S.GRUPO_BIEN AND    
					 D.CLASE_BIEN 	= S.CLASE_BIEN AND    
					 D.FAMILIA_BIEN = S.FAMILIA_BIEN AND    
					 D.ITEM_BIEN 	= S.ITEM_BIEN )     		     
		END    
     
		IF @@ERROR <> 0    
		     GOTO ERROR    
		     		    
	  	DELETE tmp_parametros_pao WHERE NRO_PAO = @PN_NRO_PAO    
		     
		IF @@ERROR <> 0    
		     GOTO ERROR    
		     
	COMMIT TRAN    
	set nocount off     
	RETURN 0    
	     
	ERROR:    
	   ROLLBACK TRAN    
	   set nocount off    
	   RETURN 1
GO


