-- ----------------------------
-- procedure structure for SP_CARGA_CONTRATISTAS_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_CONTRATISTAS_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_CONTRATISTAS_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_CONTRATISTAS_TRX]
 @O_ERR_NUM         NUMERIC(6,0) OUTPUT,
  @O_ERR_MSG        VARCHAR(255) OUTPUT

AS
BEGIN
     
    DELETE FROM dbo.SGE_CONTRATISTAS_TRX
     
    INSERT INTO SGE_CONTRATISTAS_TRX (RUC_PROV , NOMBRE_PROV)
   	SELECT  LTRIM(Rtrim(NRO_RUC)) ,
        	SUBSTRING(NOMBRE_PROV, 1,100) as NOMBRE_PROV    
     FROM SIG_CONTRATISTAS   
     WHERE NRO_RUC NOT IN (SELECT nro_ruc FROM SIG_CONTRATISTAS      						
     					   GROUP BY NRO_RUC HAVING count(nro_ruc) >1	)
       AND (NRO_RUC IS NOT NULL  and NRO_RUC <>'')	
      
    
 IF @@ERROR <> 0
       	 BEGIN
       			 SET @O_ERR_MSG='Ocurrió error en la actualización de SGE_PATRIMONIO_TRX'
		 return -1
	  	END  

END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_PPR_ESTABLECIMIENTO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_PPR_ESTABLECIMIENTO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_PPR_ESTABLECIMIENTO]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_PPR_ESTABLECIMIENTO]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJEC			NUMERIC(5),	
    @fecha_carga_inicio     	VARCHAR(10),
    @fecha_carga_fin        	VARCHAR(10),
    @usuario_n              	VARCHAR(50),
    @O_ERR_NUM   	    	NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG   	    	VARCHAR(255) OUTPUT   
AS
	DECLARE @LC_ANO_EJE		    	NUMERIC(5)
	DECLARE @Lc_SEC_EJEC                	NUMERIC(5)	
	DECLARE @Lc_COD_ESTABLEC            	NUMERIC(5)
	DECLARE @Lc_ID_SI_PPR_ESTABLECIMIENTO   NUMERIC(5)
	DECLARE @Lc_DESC_ESTABLEC           	VARCHAR(200)
	DECLARE @LC_TIPO_ESTABLEC  	    	VARCHAR(2)
	DECLARE @LC_SECTOR_AMBITO     	    	VARCHAR(2)
	DECLARE @LC_COD_INTERNO		    	VARCHAR(20)		
	DECLARE @LC_UBIGEO		    	VARCHAR(6)	
	DECLARE @LC_CATEGORIA		    	NUMERIC(5)
	DECLARE @LC_COD_OGEI		    	VARCHAR(20)
	DECLARE @fecha_carga_inicio_1     	DATETIME  
	DECLARE @fecha_carga_fin_1        	DATETIME  

BEGIN  
	DELETE FROM SI_PPR_ESTABLECIMIENTO

	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio,101) 
        SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

	SELECT @Lc_ID_SI_PPR_ESTABLECIMIENTO  = MAX(ID_SI_PPR_ESTABLECIMIENTO) 
	FROM SI_PPR_ESTABLECIMIENTO 
	WHERE ANO_EJE = @P_ANO_EJE  AND SEC_EJEC =  @P_SEC_EJEC

	IF @Lc_ID_SI_PPR_ESTABLECIMIENTO IS NULL 
		SET @Lc_ID_SI_PPR_ESTABLECIMIENTO = 0	

        DECLARE C_1 CURSOR FOR 
		SELECT ANO_EJE, SEC_EJEC, COD_ESTABLEC,
		DESC_ESTABLEC, TIPO_ESTABLEC, SECTOR_AMBITO,
		COD_INTERNO, UBIGEO, CATEGORIA, COD_OGEI 
		FROM SIG_PPR_ESTABLECIMIENTO 
		WHERE ANO_EJE = @P_ANO_EJE AND SEC_EJEC = @P_SEC_EJEC
		
  	OPEN C_1
		FETCH NEXT FROM C_1 
		INTO  	@LC_ANO_EJE, @LC_SEC_EJEC, @LC_COD_ESTABLEC,
		      	@LC_DESC_ESTABLEC, @LC_TIPO_ESTABLEC, @LC_SECTOR_AMBITO,
		        @LC_COD_INTERNO, @LC_UBIGEO, @LC_CATEGORIA, @LC_COD_OGEI

		WHILE @@FETCH_STATUS = 0
		BEGIN
	        	SET @Lc_ID_SI_PPR_ESTABLECIMIENTO = @Lc_ID_SI_PPR_ESTABLECIMIENTO + 1
		        INSERT INTO SI_PPR_ESTABLECIMIENTO (ANO_EJE, SEC_EJEC, COD_ESTABLEC,
					      ID_SI_PPR_ESTABLECIMIENTO, DESC_ESTABLEC, TIPO_ESTABLEC, 
					      SECTOR_AMBITO, COD_INTERNO, UBIGEO, CATEGORIA, 
					      COD_OGEI, FECHA_CARGA_INICIO, FECHA_CARGA_FIN, 
					      FECHA_ENVIO, USUARIO_ENVIO)
		        VALUES (@LC_ANO_EJE, @LC_SEC_EJEC, @LC_COD_ESTABLEC, @Lc_ID_SI_PPR_ESTABLECIMIENTO, 
				@LC_DESC_ESTABLEC, @LC_TIPO_ESTABLEC, @LC_SECTOR_AMBITO,
				@LC_COD_INTERNO, @LC_UBIGEO, @LC_CATEGORIA, @LC_COD_OGEI,
				@fecha_carga_inicio_1, @fecha_carga_fin_1,
				convert(varchar(10),getdate(),112), @usuario_n)

        	 FETCH NEXT FROM C_1
        	 INTO 	@LC_ANO_EJE, @LC_SEC_EJEC, @LC_COD_ESTABLEC,
		      	@LC_DESC_ESTABLEC, @LC_TIPO_ESTABLEC, @LC_SECTOR_AMBITO,
		      	@LC_COD_INTERNO, @LC_UBIGEO, @LC_CATEGORIA, @LC_COD_OGEI
		END
        CLOSE C_1
        DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_NIVELA_MONTO_RESERVA_PEDIDO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_NIVELA_MONTO_RESERVA_PEDIDO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_NIVELA_MONTO_RESERVA_PEDIDO]
GO

CREATE PROCEDURE [dbo].[SP_NIVELA_MONTO_RESERVA_PEDIDO]
@P_ANO_EJE  NUMERIC(4,0),
@P_SEC_EJEC NUMERIC(6,0),    
@O_ERR_NUM  NUMERIC(6,0) OUTPUT,
@O_ERR_MSG  VARCHAR(255) OUTPUT
AS
BEGIN 

DECLARE @ll_SEC_FUNC        NUMERIC(4)  
DECLARE @LS_FUENTE_FTO      VARCHAR(2)
DECLARE @LS_CLASIFICADOR    VARCHAR(20) 
DECLARE @ld_monto_item      NUMERIC(15,2)
DECLARE @ls_uso_fuente      VARCHAR(1)
DECLARE @ls_flag_pnp        VARCHAR(1)

BEGIN

  SELECT @ls_uso_fuente = ltrim(rtrim(valor))  
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec = @P_SEC_EJEC AND  
         cod_maestro = 'FLAG_FUENTE'

  IF @ls_uso_fuente IS NULL   
     SET @ls_uso_fuente = '0'

  SELECT @ls_flag_pnp = ltrim(rtrim(valor))
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec = @P_SEC_EJEC AND  
         cod_maestro = 'FLAG_PED_NP'

  IF @ls_flag_pnp IS NULL   
     SET @ls_flag_pnp = '0'
		
  IF @ls_uso_fuente = '1' and @ls_flag_pnp = '1' AND @P_ANO_EJE > 2012 
  BEGIN


	UPDATE sig_techo_presupuesto
	SET MNTO_RESERVA_PEDIDO = 0
	WHERE sec_ejec  = @P_SEC_EJEC and
			ano_eje   = @P_ANO_EJE   and
			indicador = '4'           and
			flag_meta_aprob = '1'     and
			( '0' = '0')
        
     IF @@ERROR <> 0         
	 BEGIN
		 SET @O_ERR_MSG='Error actualizando tabla SIG_TECHO_PRESUPUESTO.'
		return -1
	 END    
	 
	UPDATE sig_techo_presupuesto
	SET MNTO_RESERVA_PEDIDO = 0
	WHERE sec_ejec  = @P_SEC_EJEC and
			ano_eje   = @P_ANO_EJE   and
			indicador = '0'           and
			flag_meta_aprob = '1'     and
			( '0' = '1')
        
     IF @@ERROR <> 0         
	 BEGIN
		 SET @O_ERR_MSG='Error actualizando tabla SIG_TECHO_PRESUPUESTO.'
		return -1
	 END    	 
		
  DECLARE C1 CURSOR FOR
		select D.SEC_FUNC,D.FUENTE_FTO,D.CLASIFICADOR,D.monto_item
		from (SELECT A.SEC_FUNC,
			A.FUENTE_FTO,
			B.CLASIFICADOR,
			SUM(coalesce(
			case 
				when A.tipo_bien= 'B' then (case 
					when (B.estado_ped= '1' or A.estado='1') then B.cant_solicitada
					when B.estado_ped= '4' then B.cant_aprobada
				end * B.PRECIO_UNIT)
				when A.tipo_bien= 'S' then (case 
					when (B.estado_ped= '1' or A.estado='1') then B.cant_solicitada
					else B.cant_aprobada
				end )
				end ,0)) monto_item
			 FROM SIG_PEDIDOS A,
			      SIG_DETALLE_PEDIDOS B
			WHERE
				A.ANO_EJE = B.ANO_EJE AND
				A.SEC_EJEC = B.SEC_EJEC AND
				A.TIPO_BIEN = B.TIPO_BIEN AND
				A.TIPO_PEDIDO = B.TIPO_PEDIDO AND
				A.NRO_PEDIDO = B.NRO_PEDIDO AND
				A.estado<> '0' and A.estado<> '3' and 
				( (B.TIPO_ORDEN = 'C' and B.TIPO_BIEN ='B') or (B.TIPO_BIEN ='S') ) and 
				not exists (select T.nro_consolid
						from sig_paac_consolidado T, sig_paac_metas M
						where T.ano_eje        = A.ANO_EJE 	 and
							T.sec_ejec       = A.SEC_EJEC  and
							T.tipo_bien      = A.tipo_bien and
							T.tipo_consolid  = '2' and
							T.tipo_generacion= '0' and
							T.sec_cuadro_ini = B.nro_cuadro and
							T.ano_eje      	= M.ano_eje 		and
							T.sec_ejec       	= M.sec_ejec  		and
							T.tipo_bien  		= M.tipo_bien 	 and 
							T.tipo_consolid  	= M.tipo_consolid	and
							T.nro_consolid   	= M.nro_consolid 	and
							T.tipo_generacion	= M.tipo_generacion and
							M.sec_func        = A.SEC_FUNC  	   and
							M.fuente_financ   = A.FUENTE_FTO  	and
							M.CLASIFICADOR    = B.CLASIFICADOR ) and
				A.ano_eje = @P_ANO_EJE and
				A.sec_ejec = @P_SEC_EJEC	
			group by A.SEC_FUNC, A.FUENTE_FTO, B.CLASIFICADOR

			union

			  select M.sec_func,
				M.fuente_financ,
				M.CLASIFICADOR,
				sum(case when O.monto > 0 then (case when I.tipo_bien = 'B' then I.cantidad * I.precio_moneda 
								     when I.tipo_bien = 'S' then I.cantidad end ) 
					 else 0 end ) AS monto_item 
				 from sig_paac_item I
						left join (select count(a.ano_eje) as monto, a.ano_eje,a.sec_ejec,a.nro_cons_paac,a.tipo_bien,a.grupo_bien,a.clase_bien,a.familia_bien,a.item_bien
									  from sig_detalle_bserv_cuadro  a, sig_detalle_metas_cuadro  b,
											 sig_depen_meta_cuadro     c,	sig_detalle_pedido_cuadro d
									 where a.ano_eje    = b.ano_eje   and a.sec_ejec   = b.sec_ejec   and
											 a.tipo_bien  = b.tipo_bien and a.sec_cuadro = b.sec_cuadro and
											 a.secuencia  = b.secuencia and 
											 c.ano_eje    = b.ano_eje   and c.sec_ejec   = b.sec_ejec   and
											 c.tipo_bien  = b.tipo_bien and c.sec_cuadro = b.sec_cuadro and
											 c.secuencia  = b.secuencia and c.sec_meta   = d.sec_meta   and
											 c.ano_eje    = d.ano_eje   and c.sec_ejec   = d.sec_ejec   and
											 c.tipo_bien  = d.tipo_bien and c.sec_cuadro = d.sec_cuadro and
											 c.secuencia  = d.secuencia and c.sec_meta   = d.sec_meta   and
											 c.sec_depend = d.sec_depend 
									group by a.ano_eje,a.sec_ejec,a.nro_cons_paac,a.tipo_bien,a.grupo_bien,a.clase_bien,a.familia_bien,a.item_bien) O
						on O.ano_eje    = I.ano_eje and 
							O.sec_ejec   = I.sec_ejec and 
							O.nro_cons_paac = I.nro_consolid and 
							O.tipo_bien   = I.tipo_bien and
							O.grupo_bien  = I.grupo_bien and
							O.clase_bien  = I.clase_bien and
							O.familia_bien= I.familia_bien and
							O.item_bien   = I.item_bien,
						sig_paac_metas M
						left join SIG_PAAC_CENTRO_COSTO S
						on ( S.ANO_EJE      = M.ANO_EJE ) AND  
							( S.SEC_EJEC     = M.SEC_EJEC ) AND  
							( S.TIPO_CONSOLID= M.TIPO_CONSOLID ) AND  
							( S.NRO_CONSOLID = M.NRO_CONSOLID ) AND  
							( S.TIPO_GENERACION = M.TIPO_GENERACION ) AND  
							( S.TIPO_BIEN    = M.TIPO_BIEN ) AND  
							( S.SEC_CONSOLID = M.SEC_CONSOLID ) AND  
							( S.SEC_RESUMEN  = M.SEC_RESUMEN ) AND  
							( S.SEC_META     = M.SEC_META ),
						sig_paac_consolidado T,
						(select distinct A.NRO_PEDIDO,B.ANO_EJE,B.SEC_EJEC,B.tipo_bien,
								B.nro_cuadro,A.SEC_FUNC,A.FUENTE_FTO,B.CLASIFICADOR
						from  SIG_PEDIDOS A, SIG_DETALLE_PEDIDOS B
						where A.ANO_EJE     = B.ANO_EJE AND
								A.SEC_EJEC    = B.SEC_EJEC AND
								A.TIPO_BIEN   = B.TIPO_BIEN AND
								A.TIPO_PEDIDO = B.TIPO_PEDIDO AND
								A.NRO_PEDIDO  = B.NRO_PEDIDO) P
				where M.ano_eje  		= I.ano_eje 		 and
						M.sec_ejec 		= I.sec_ejec 	 and
						M.tipo_consolid 	= I.tipo_consolid and
						M.nro_consolid  	= I.nro_consolid  and
						M.tipo_generacion = I.tipo_generacion and
						M.tipo_bien  		= I.tipo_bien 	 and 
						M.sec_consolid  	= I.sec_consolid and 
						M.sec_resumen  	= I.sec_resumen and	
						T.ano_eje      	= I.ano_eje 		and
						T.sec_ejec        = I.sec_ejec  and
						T.tipo_bien  		= I.tipo_bien 	 and 
						T.tipo_consolid  = I.tipo_consolid and
						T.nro_consolid   = I.nro_consolid and
						T.tipo_generacion= I.tipo_generacion and
	
						T.ano_eje        = P.ANO_EJE 	 and
						T.sec_ejec       = P.SEC_EJEC  and
						T.tipo_bien      = P.tipo_bien and
						T.tipo_consolid  = '2' and
						T.tipo_generacion= '0' and
						coalesce(T.verifica_ppto,'N')  = 'N' and
						T.sec_cuadro_ini = P.nro_cuadro  and
						M.sec_func       = P.SEC_FUNC  	and
						M.fuente_financ  = P.FUENTE_FTO  and
						M.CLASIFICADOR   = P.CLASIFICADOR and
						I.ano_eje = @P_ANO_EJE and
						I.sec_ejec = @P_SEC_EJEC						
				group by M.sec_func,M.fuente_financ,M.CLASIFICADOR) D  
                  
                  
	OPEN C1     
	 FETCH NEXT FROM C1
	  INTO  
	  @ll_SEC_FUNC, @LS_FUENTE_FTO, @LS_CLASIFICADOR, @ld_monto_item
	               
        WHILE @@FETCH_STATUS = 0
        BEGIN     

			UPDATE sig_techo_presupuesto
			SET MNTO_RESERVA_PEDIDO = @ld_monto_item
			WHERE sec_ejec  = @P_SEC_EJEC and
					ano_eje   = @P_ANO_EJE   and
					indicador = '4'           and
					flag_meta_aprob = '1'     and			
					sec_func = @ll_SEC_FUNC AND
					fuente_financ = @LS_FUENTE_FTO AND
					clasificador = @LS_CLASIFICADOR and 	
					( '0' = '0')
	            
	         IF @@ERROR <> 0         
			 BEGIN
				 SET @O_ERR_MSG='Error actualizando tabla SIG_TECHO_PRESUPUESTO.'
				return -1
			 END   

			UPDATE sig_techo_presupuesto
			SET MNTO_RESERVA_PEDIDO = @ld_monto_item
			WHERE sec_ejec  = @P_SEC_EJEC and
					ano_eje   = @P_ANO_EJE   and
					indicador = '0'           and
					flag_meta_aprob = '1'     and			
					sec_func = @ll_SEC_FUNC AND
					fuente_financ = @LS_FUENTE_FTO AND
					clasificador = @LS_CLASIFICADOR and 
					( '0' = '1')
	            
	         IF @@ERROR <> 0         
			 BEGIN
				 SET @O_ERR_MSG='Error actualizando tabla SIG_TECHO_PRESUPUESTO.'
				return -1
			 END   
          
	   FETCH NEXT FROM C1
           INTO  
           @ll_SEC_FUNC, @LS_FUENTE_FTO, @LS_CLASIFICADOR, @ld_monto_item
                          
      END          
      CLOSE C1
      DEALLOCATE C1            
              
   END
   END 
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_RESUMEN_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_RESUMEN_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_RESUMEN_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_RESUMEN_TRX]
    @P_ANO_EJE          NUMERIC(4,0),
    @P_SEC_EJEC         NUMERIC(6,0),
    @fecha_carga_inicio VARCHAR(10),
    @fecha_carga_fin    VARCHAR(10),    
    @usuario_n          VARCHAR(10),
    @O_ERR_NUM          NUMERIC(6,0) OUTPUT,
    @O_ERR_MSG          VARCHAR(255) OUTPUT 
AS
 DECLARE  
    @LD_MONTO_PM      NUMERIC(18,2),
    @LL_ID_SI_RESUMEN NUMERIC(18,0),
    @LS_FINALIDAD     VARCHAR(5),
    @LS_D_SEC_EJEC    VARCHAR(150),
    @LS_D_FINALIDAD   VARCHAR(250)  

BEGIN
	SET @LL_ID_SI_RESUMEN = 0
     
     DECLARE C_1 CURSOR FOR
	  SELECT DISTINCT
	        A.FINALIDAD,
	        C.NOMBRE D_SEC_EJEC,      
	        B.NOMBRE D_FINALIDAD       
	    FROM META A
	    JOIN FINALIDAD B
	        ON  B.ANO_EJE = A.ANO_EJE
	        AND B.finalidad = A.finalidad
	    JOIN EJECUTORA C
	        ON  C.SEC_EJEC = A.SEC_EJEC
	    WHERE 
	        A.ANO_EJE  = @P_ANO_EJE AND
	        A.SEC_EJEC = @P_SEC_EJEC AND
	        A.FINALIDAD <>'00000'
	    ORDER BY A.FINALIDAD

  	 OPEN C_1
     FETCH NEXT FROM C_1
     INTO @LS_FINALIDAD, @LS_D_SEC_EJEC, @LS_D_FINALIDAD  

     WHILE @@FETCH_STATUS = 0
     BEGIN  	     
    
        SELECT @LL_ID_SI_RESUMEN = MAX(ID_SI_RESUMEN) 
        FROM SI_RESUMEN_TRX
        WHERE ANO_EJE = @P_ANO_EJE AND SEC_EJEC = @P_SEC_EJEC
        
        IF @LL_ID_SI_RESUMEN IS NULL  SET @LL_ID_SI_RESUMEN = 0
        
        SET @LL_ID_SI_RESUMEN = @LL_ID_SI_RESUMEN + 1 

	   

        INSERT INTO SI_RESUMEN_TRX(
        ANO_EJE,            ID_SI_RESUMEN,        FINALIDAD,    
        SEC_EJEC,           D_SEC_EJEC,           D_FINALIDAD
        )
        VALUES( 
        @P_ANO_EJE,         @LL_ID_SI_RESUMEN,    @LS_FINALIDAD,    
        @P_SEC_EJEC,        @LS_D_SEC_EJEC,       @LS_D_FINALIDAD
        )
   
--PASO2:    
    --ACTUALIZAR POR CADA FINALIDAD
        UPDATE SI_RESUMEN_TRX
           SET MONTO_PIM = ( SELECT SUM(A.PPTO_MODIF)                           
                               FROM SIG_TECHO_PRESUPUESTO A
                               JOIN META B
                                 ON  B.ano_eje = A.ANO_EJE
                                AND B.sec_ejec = A.SEC_EJEC
                                AND B.sec_func = A.sec_func
                              WHERE 
                                A.ANO_EJE            = @P_ANO_EJE     AND
                                A.sec_ejec           = @P_SEC_EJEC    AND
                                A.FLAG_META_APROB    = 1                 AND
                                A.INDICADOR          = 4    AND
                                B.FINALIDAD          = @LS_FINALIDAD)
        WHERE
            SI_RESUMEN_TRX.ANO_EJE    = @P_ANO_EJE    AND
            SI_RESUMEN_TRX.sec_ejec   = @P_SEC_EJEC   AND
            SI_RESUMEN_TRX.FINALIDAD  = @LS_FINALIDAD 


    FETCH NEXT FROM C_1
    INTO @LS_FINALIDAD, @LS_D_SEC_EJEC, @LS_D_FINALIDAD  
         
    END 
    
    CLOSE C_1
    DEALLOCATE C_1
    
--PASO3:
    UPDATE SI_RESUMEN_TRX
    SET MONTO_ORDEN =  (SELECT SUM(PRECIO_TOTAL) FROM SI_ORDEN_TRX  A
                            JOIN SI_ORDEN_DETA_TRX  B ON
                                A.ANO_EJE  = B.ANO_EJE AND
                                A.SEC_EJEC = B.SEC_EJEC AND
                                A.ID_SI_ORDEN = B.ID_SI_ORDEN
                            WHERE
                                A.ANO_EJE   = SI_RESUMEN_TRX.ANO_EJE AND
                                A.SEC_EJEC  = SI_RESUMEN_TRX.SEC_EJEC AND
                                B.FINALIDAD = SI_RESUMEN_TRX.FINALIDAD
                        )
    WHERE
        SI_RESUMEN_TRX.ANO_EJE  = @P_ANO_EJE AND
        SI_RESUMEN_TRX.SEC_EJEC = @P_SEC_EJEC
        
--PASO4:
    UPDATE SI_RESUMEN_TRX
    SET MONTO_PEDIDO =    (    SELECT SUM(Y.VALOR_TOTAL) FROM SI_PEDIDO_TRX  X
                                    JOIN SI_PEDIDO_DETA_TRX  Y
                                        ON  Y.ANO_EJE = X.ANO_EJE
                                        AND Y.SEC_EJEC = X.SEC_EJEC
                                        AND Y.ID_SI_PEDIDO = X.ID_SI_PEDIDO
                                    WHERE
                                        X.ANO_EJE  =  SI_RESUMEN_TRX.ANO_EJE AND
                                        X.SEC_EJEC  = SI_RESUMEN_TRX.SEC_EJEC AND
                                        X.FINALIDAD = SI_RESUMEN_TRX.FINALIDAD
                                ),
        CANT_PEDIDO =     (    SELECT COUNT(W.SEC_EJEC) FROM SI_PEDIDO_TRX  W
                                    WHERE W.ano_eje   = SI_RESUMEN_TRX.ANO_EJE
                                      AND W.sec_ejec  = SI_RESUMEN_TRX.SEC_EJEC
                                      AND W.FINALIDAD = SI_RESUMEN_TRX.FINALIDAD
                                      AND W.ESTADO<>'0'
                                )
    WHERE
        SI_RESUMEN_TRX.ANO_EJE    = @P_ANO_EJE AND
        SI_RESUMEN_TRX.SEC_EJEC   = @P_SEC_EJEC

    
--PASO5:
    UPDATE SI_RESUMEN_TRX
     SET MONTO_PECOSA =  (    SELECT SUM(VALOR_TOTAL)
                                FROM SI_PEDIDO_TRX  P
                                JOIN SI_PEDIDO_DETA_TRX PD
                                    ON  P.ANO_EJE            = PD.ANO_EJE 
                                    AND P.SEC_EJEC           = PD.SEC_EJEC 
                                    AND P.ID_SI_PEDIDO       = PD.ID_SI_PEDIDO
                                WHERE   P.ANO_EJE            = SI_RESUMEN_TRX.ANO_EJE
                                    AND P.SEC_EJEC           = SI_RESUMEN_TRX.SEC_EJEC
                                    --AND P.FLAG_ESTADO        = 1 
                                    --AND PD.FLAG_ESTADO       = 1 
                                    AND P.FINALIDAD=SI_RESUMEN_TRX.FINALIDAD
                                    AND P.TIPO_PEDIDO = 1 
                        )
     WHERE 
        SI_RESUMEN_TRX.ANO_EJE    = @P_ANO_EJE AND
        SI_RESUMEN_TRX.SEC_EJEC   = @P_SEC_EJEC        
        
--PASO6:
    UPDATE SI_RESUMEN_TRX 
    SET MONTO_ENTRADA_ALMACEN = (    SELECT SUM(X.PRECIO_TOTAL)
                                            FROM SI_MOVIMIENTO_ALMACEN_DETA_TRX  X
                                            WHERE  X.ANO_EJE     = SI_RESUMEN_TRX.ANO_EJE
                                              AND X.SEC_EJEC     = SI_RESUMEN_TRX.SEC_EJEC
                                              AND X.FINALIDAD    = SI_RESUMEN_TRX.FINALIDAD
                                 )
    WHERE 
        SI_RESUMEN_TRX.ANO_EJE    = @P_ANO_EJE AND
        SI_RESUMEN_TRX.SEC_EJEC   = @P_SEC_EJEC           

END
GO


-- ----------------------------
-- procedure structure for SP_SIG_TRANS_PATRIMONIO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_TRANS_PATRIMONIO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_TRANS_PATRIMONIO]
GO

CREATE PROCEDURE [dbo].[SP_SIG_TRANS_PATRIMONIO]
(
@al_ejec_sec    NUMERIC(10),
@al_ejec_anno   NUMERIC(4, 0),
@as_ambito_cod  VARCHAR(10)
)
AS
BEGIN
DECLARE @LN_ANO_MOV_CONT NUMERIC(6,0) 
DECLARE @LC_TIPO_BIEN VARCHAR(1)
DECLARE @LC_TIPO_PEDIDO VARCHAR(1)
DECLARE @LC_GRUPO_BIEN VARCHAR(3)
DECLARE @LC_CLASE_BIEN VARCHAR(3)
DECLARE @LC_FAMILIA_BIEN VARCHAR(4)
DECLARE @LC_ITEM_BIEN VARCHAR(20)
DECLARE @LC_TIPO_DOCUMENTO VARCHAR(3) 
DECLARE @LC_NRO_DOCUMENTO VARCHAR(11)  
DECLARE @LC_VALOR_NEA VARCHAR(50)
DECLARE @LC_FECHA_NEA VARCHAR(30)
DECLARE @LC_MEDIDAS VARCHAR(30)   
DECLARE @LC_ESTADO_ACTUAL VARCHAR(1)  
DECLARE @LC_ESTADO_CONSERV VARCHAR(1)
DECLARE @LC_FECHA_COMPRA VARCHAR(30)  
DECLARE @LC_VALOR_COMPRA VARCHAR(50)
DECLARE @LC_NRO_ORDEN VARCHAR(50)
DECLARE @LC_FEC_FIN_VIDA VARCHAR(30)
DECLARE @LC_VIDA_UTIL VARCHAR(50)
DECLARE @LC_TIPO_MODALIDAD VARCHAR(50)
DECLARE @LC_CENTRO_COSTO VARCHAR(150)
DECLARE @LC_NOMBRE_DEPEND VARCHAR(150)  
DECLARE @LC_CODIGO_ACTIVO VARCHAR(12)
DECLARE @LC_DESCRIPCION VARCHAR(200)
DECLARE @LC_MODELO VARCHAR(40) 
DECLARE @LC_NRO_SERIE VARCHAR(50)
DECLARE @LC_NOMBRE VARCHAR(10) 
DECLARE @LC_ESTADO VARCHAR(2) 
DECLARE @LN_ID_SI_PATRIMONIO VARCHAR(50)
DECLARE @LC_MARCA VARCHAR(10)
DECLARE @LC_ANO_PROCESO VARCHAR(50)
DECLARE @LC_MES_PROCESO VARCHAR(2)
DECLARE @SEDE VARCHAR(50)
DECLARE @D_SEDE varchar(50)
DECLARE @COD_ESTABLEC VARCHAR(50)
DECLARE @D_COD_ESTABLEC varchar(200)
DECLARE @COD_CATEGORIA VARCHAR(50)
DECLARE @D_CORTO_COD_CATEGORIA varchar(20)
DECLARE
	@V_ANO_PATRIMONIO VARCHAR(50),
	@V_MES_PATRIMONIO VARCHAR(2),
	@V_DES_MES_PATRIMONIO VARCHAR(150),
	@V_FECHA_MOVIMTO_PATRI VARCHAR(30),
	@V_VALOR_NETO VARCHAR(50),
	@V_DEPREC_ACUMALDA VARCHAR(50),
	@V_SUB_CTA VARCHAR(15),
	@V_NOM_SUB_CTA VARCHAR(150),
	@V_COD_OGEI VARCHAR(20),
	@V_SECTOR_AMBITO VARCHAR(2),
	@V_SECUENCIA_PATRI VARCHAR(50),
	@V_SUB_CTA_PATRI varchar(8),
	@V_MAYOR_PATRI varchar(4),
	@LC_ESTADO_ASIG varchar(20),
	@LC_SECTOR			VARCHAR(2), 
	@LC_NOM_SECTOR		VARCHAR(155),
	@LC_PLIEGO			VARCHAR(3),  
	@LC_NOM_PLIEGO		VARCHAR(156),
	@LC_nombre_dpto_pto VARCHAR(150),
	@LC_nombre_PROV_PTO VARCHAR(150),
	@LC_nombre_DIST_PTO VARCHAR(150),
	@LC_PTO_ATEN_DISA	VARCHAR(200),
	@LC_PTO_ATEN_RED	VARCHAR(200),
	@LC_PTO_ATEN_MICRORED VARCHAR(200)

	SELECT @al_ejec_sec = MAX(SEC_EJEC) FROM SIG_EJECUTORA

	DELETE FROM dbo.tmp_ppr_PATRIMONIO

  IF @LN_ID_SI_PATRIMONIO IS NULL
    SET @LN_ID_SI_PATRIMONIO = 0 

        DECLARE C_1 CURSOR FOR 
  
 
 SELECT DISTINCT   
		sig_patrimonio.tipo_bien,
		sig_patrimonio.grupo_bien,
		sig_patrimonio.clase_bien,
		sig_patrimonio.familia_bien,
		sig_patrimonio.item_bien,
		case sig_patrimonio.tipo_doc_refer when '031' then 'O/C' when '045' then 'NEA' else 'NNN' end tipo_documento,
		COALESCE(CAST(sig_patrimonio.valor_nea AS varchar(50)),''),
		COALESCE(convert(varchar(10),sig_patrimonio.fecha_nea,111),'') fecha_nea,
		COALESCE(sig_patrimonio.medidas,''),
		sig_patrimonio.estado_actual,
		sig_patrimonio.estado_conserv,
		COALESCE(convert(varchar(10),sig_patrimonio.fecha_compra,111),'') fecha_compra,
		COALESCE(CAST(sig_patrimonio.valor_compra AS varchar(50)),''),
		case sig_patrimonio.tipo_doc_refer when '031' then COALESCE(CAST(sig_patrimonio.nro_orden AS varchar(50)),'') when '045' then COALESCE(sig_patrimonio.nro_documento,'') else 'NR' end,
		COALESCE(convert(varchar(10),sig_patrimonio.fec_fin_vida,111),'') fec_fin_vida,
		COALESCE(CAST(sig_patrimonio.vida_util AS varchar(50)),''),
		sig_patrimonio.tipo_modalidad,
		sig_patrimonio.centro_costo,
		COALESCE(CAST(sig_patrimonio.codigo_activo AS varchar(50)),'') codigo_activo,
		sig_patrimonio.descripcion ,
		COALESCE(CAST(sig_patrimonio.modelo AS varchar(50)),''),
		COALESCE(CAST(sig_patrimonio.nro_serie AS varchar(50)),''),
        marca.nombre,
        marca.marca,
		sig_patrimonio.estado, 
		COALESCE(CAST(sig_patrimonio.ano_proceso AS varchar(50)),''),
		COALESCE(sig_patrimonio.mes_proceso,''),
		COALESCE(CAST(sig_patrimonio.secuencia AS varchar(50)),''),
		sig_patrimonio.mayor,
		sig_patrimonio.SUB_CTA,
		'NO ASIGNADO',
		COALESCE(SCC.SEDE,0),
		COALESCE(DSD.NOMBRE_SEDE,'NO TIENE SEDE'),
		COALESCE(CSD.COD_ESTABLEC,0),
		left(COALESCE(COD_OGEI,'NO TIENE COD RENAES') + ' - ' + COALESCE(EESS.DESC_ESTABLEC,'NO SE REGISTRO EL DATO') + ' - ' + COALESCE(CA.NOMBRE_CORTO,'NO TIENE CATEGORIA'),250),
		COALESCE(EESS.CATEGORIA,0),
		COALESCE(CA.NOMBRE_CORTO,'NO TIENE CATEGORIA'),
		COALESCE(COD_OGEI,'NO TIENE COD RENAES'),
		COALESCE(CA.SECTOR_AMBITO,''),
		COALESCE(SCC.NOMBRE_DEPEND,'NO TIENE CENTRO DE COSTO'),
		dsd.sector ,
		dsd.SECTOR  +' - '+ RTRIM(S.NOMBRE) NOM_SECTOR,
		dsd.pliego PLIEGO,
		RTRIM( DSD.pliego+' - '+P.nombre) NOM_PLIEGO,
		COALESCE((SELECT UBG.nombre FROM ubigeo UBG
			WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND UBG.provincia='00' AND
						UBG.distrito='00' AND UBG.estado='A' ),'NO TIENE') nombre_dpto_pto,
		COALESCE(( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND 
							  UBG.provincia= SUBSTRING(EESS.UBIGEO,3,2) AND
							 UBG.distrito='00' AND UBG.estado='A' )	,'NO TIENE')nombre_PROV_PTO	,			
		COALESCE(( SELECT UBG.nombre  FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND 
						      UBG.provincia= SUBSTRING(EESS.UBIGEO,3,2) AND
						      UBG.distrito= SUBSTRING(EESS.UBIGEO,5,2)  AND 
						      UBG.estado='A' ),'NO TIENE') nombre_DIST_PTO ,
dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 1) AS PTO_ATEN_DISA,
dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 2) AS PTO_ATEN_RED,
dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 3) AS PTO_ATEN_MICRORED 
FROM sig_patrimonio 
  JOIN sig_detalle_activos sdt
    ON (sdt.ano_eje = @al_ejec_anno
  and sdt.sec_ejec =  sig_patrimonio.sec_ejec
  and sdt.secuencia = sig_patrimonio.secuencia
  and sdt.tipo_movimto <> 'S') left outer
  join SIG_CENTRO_COSTO SCC ON
	   ( SCC.ANO_EJE = @al_ejec_anno   AND 
	     SCC.SEC_EJEC = sig_patrimonio.sec_ejec  AND 
	     SCC.CENTRO_COSTO = sig_patrimonio.centro_costo)
  	 JOIN SIG_SEDES DSD ON
	   ( DSD.SEDE  = SCC.SEDE AND
		 DSD.PLIEGO = SCC.PLIEGO ) left outer
	 JOIN SIG_PPR_SEDE CSD ON
	   ( SCC.ANO_EJE = CSD.ANO_EJE AND
		 SCC.SEC_EJEC = CSD.SEC_EJEC AND
		 SCC.PLIEGO = CSD.PLIEGO AND
		 SCC.SEDE = CSD.SEDE AND
		 SCC.ESTADO = 'A') left outer
	 JOIN SIG_PPR_ESTABLECIMIENTO EESS ON
	   ( EESS.ANO_EJE = CSD.ANO_EJE AND
	     EESS.SEC_EJEC = CSD.SEC_EJEC AND
	     EESS.COD_ESTABLEC = CSD.COD_ESTABLEC) left outer
	 JOIN SIG_PPR_CATEGORIA CA ON
	   ( CA.ANO_EJE = CSD.ANO_EJE AND 
	     CA.SECTOR_AMBITO = @as_ambito_cod and
	     CA.CATEGORIA = EESS.CATEGORIA) LEFT OUTER 
	JOIN marca 
		ON (sig_patrimonio.marca = marca.marca 
		AND sig_patrimonio.tipo_marca = marca.tipo_marca)
    JOIN sector s ON
		( S.SECTOR = DSD.sector )
    JOIN pliego p ON 
		( P.PLIEGO = DSD.pliego  AND 
		 P.sector =  DSD.sector) 
WHERE sig_patrimonio.sec_ejec = @al_ejec_sec
  and not exists (Select p.secuencia from sig_patrimonio p 
			       where p.sec_ejec=sig_patrimonio.sec_ejec 
					 and p.tipo_modalidad=sig_patrimonio.tipo_modalidad 
					 and p.secuencia=sig_patrimonio.secuencia 
					 and (p.mayor is null or p.mayor = ''))
   and not exists ( Select a.secuencia from sig_asignaciones a 
					 where a.ano_eje = @al_ejec_anno
                       and a.sec_ejec = sig_patrimonio.sec_ejec 
                       and a.tipo_modalidad = sig_patrimonio.tipo_modalidad 
                       and a.secuencia = sig_patrimonio.secuencia)
 UNION    
SELECT  
		sig_patrimonio.tipo_bien,
		sig_patrimonio.grupo_bien,
		sig_patrimonio.clase_bien,
		sig_patrimonio.familia_bien,
		sig_patrimonio.item_bien,
		case sig_patrimonio.tipo_doc_refer when '031' then 'O/C' when '045' then 'NEA' else 'NNN' end tipo_documento,
		COALESCE(CAST(sig_patrimonio.valor_nea AS varchar(50)),''),
		COALESCE(convert(varchar(10),sig_patrimonio.fecha_nea,111),'') fecha_nea,
		COALESCE(sig_patrimonio.medidas,''),
		sig_patrimonio.estado_actual,
		sig_asignaciones.ESTADO_ACTIVO as estado_conserv,
		COALESCE(convert(varchar(10),sig_patrimonio.fecha_compra,111),'') fecha_compra,
		COALESCE(CAST(sig_patrimonio.valor_compra AS varchar(50)),''),
		case sig_patrimonio.tipo_doc_refer when '031' then COALESCE(CAST(sig_patrimonio.nro_orden AS varchar(50)),'') when '045' then COALESCE(sig_patrimonio.nro_documento,'') else 'NR' end,
		COALESCE(convert(varchar(10),sig_patrimonio.fec_fin_vida,111),'') fec_fin_vida,
		COALESCE(CAST(sig_patrimonio.vida_util AS varchar(50)),''),
		sig_patrimonio.tipo_modalidad,
		SIG_ASIGNACIONES.CENTRO_ENTREGA as centro_costo,
		COALESCE(CAST(sig_patrimonio.codigo_activo AS varchar(50)),'') codigo_activo,
		sig_patrimonio.descripcion ,
		COALESCE(CAST(sig_patrimonio.modelo AS varchar(50)),''),
		COALESCE(CAST(sig_patrimonio.nro_serie AS varchar(50)),''),
        marca.nombre,
        marca.marca,
		sig_patrimonio.estado, 
		COALESCE(CAST(sig_patrimonio.ano_proceso AS varchar(50)),''),
		COALESCE(sig_patrimonio.mes_proceso,''),
		COALESCE(CAST(sig_patrimonio.secuencia AS varchar(50)),''),
		sig_patrimonio.mayor,
		sig_patrimonio.SUB_CTA,
		'ASIGNADO',
		COALESCE(SCC.SEDE,0),
		COALESCE(DSD.NOMBRE_SEDE,'NO TIENE SEDE'),
		COALESCE(CSD.COD_ESTABLEC,0),
		left(COALESCE(COD_OGEI,'NO TIENE COD RENAES') + ' - ' + COALESCE(EESS.DESC_ESTABLEC,'NO SE REGISTRO EL DATO') + ' - ' + COALESCE(CA.NOMBRE_CORTO,'NO TIENE CATEGORIA'),250),
		COALESCE(EESS.CATEGORIA,0),
		COALESCE(CA.NOMBRE_CORTO,'NO TIENE CATEGORIA'),
		COALESCE(COD_OGEI,'NO TIENE COD RENAES'),
		COALESCE(CA.SECTOR_AMBITO,''),
		COALESCE(SCC.NOMBRE_DEPEND,'NO TIENE CENTRO DE COSTO'),
		dsd.sector ,
		dsd.SECTOR  +' - '+ RTRIM(S.NOMBRE) NOM_SECTOR,
		dsd.pliego PLIEGO,
		RTRIM( DSD.pliego+' - '+P.nombre) NOM_PLIEGO,
		COALESCE((SELECT UBG.nombre FROM ubigeo UBG
			WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND UBG.provincia='00' AND
						UBG.distrito='00' AND UBG.estado='A' ),'NO TIENE') nombre_dpto_pto,
		COALESCE(( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND 
							  UBG.provincia= SUBSTRING(EESS.UBIGEO,3,2) AND
							 UBG.distrito='00' AND UBG.estado='A' )	,'NO TIENE')	nombre_PROV_PTO	,			
		COALESCE(( SELECT UBG.nombre FROM ubigeo UBG
						WHERE UBG.departamento= SUBSTRING(EESS.UBIGEO,1,2) AND 
						      UBG.provincia= SUBSTRING(EESS.UBIGEO,3,2) AND
						      UBG.distrito= SUBSTRING(EESS.UBIGEO,5,2)  AND 
						      UBG.estado='A' ) ,'NO TIENE') nombre_DIST_PTO ,
        dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 1) AS PTO_ATEN_DISA,
        dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 2) AS PTO_ATEN_RED,
        dbo.SF_NIVEL_DESC(CA.SECTOR_AMBITO, EESS.CAD_OPERATIVA, 3) AS PTO_ATEN_MICRORED 
  FROM sig_asignaciones 
  join SIG_CENTRO_COSTO SCC ON
	   ( SCC.ANO_EJE = SIG_ASIGNACIONES.ANO_EJE AND 
	     SCC.SEC_EJEC = SIG_ASIGNACIONES.sec_ejec  AND 
	     SCC.CENTRO_COSTO = SIG_ASIGNACIONES.CENTRO_ENTREGA)
  	 JOIN SIG_SEDES DSD ON
	   ( DSD.SEDE  = SCC.SEDE AND
		 DSD.PLIEGO = SCC.PLIEGO ) left outer
	 JOIN SIG_PPR_SEDE CSD ON
	   ( SCC.ANO_EJE = CSD.ANO_EJE AND
		 SCC.SEC_EJEC = CSD.SEC_EJEC AND
		 SCC.PLIEGO = CSD.PLIEGO AND
		 SCC.SEDE = CSD.SEDE AND
		 SCC.ESTADO = 'A') left outer
	 JOIN SIG_PPR_ESTABLECIMIENTO EESS ON
	   ( EESS.ANO_EJE = CSD.ANO_EJE AND
	     EESS.SEC_EJEC = CSD.SEC_EJEC AND
	     EESS.COD_ESTABLEC = CSD.COD_ESTABLEC) left outer
	 JOIN SIG_PPR_CATEGORIA CA ON
	   ( CA.ANO_EJE = CSD.ANO_EJE AND 
	     CA.SECTOR_AMBITO = @as_ambito_cod and
	     CA.CATEGORIA = EESS.CATEGORIA)
	 JOIN SECTOR S ON
		( S.SECTOR = DSD.sector)
     JOIN PLIEGO P ON 
		( P.PLIEGO = DSD.pliego  AND 
		  P.sector =  DSD.sector),
       sig_patrimonio 
  JOIN sig_detalle_activos sdt
    ON (sdt.ano_eje = @al_ejec_anno
  and sdt.sec_ejec =  sig_patrimonio.sec_ejec
  and sdt.secuencia = sig_patrimonio.secuencia
  and sdt.tipo_movimto <> 'S') LEFT OUTER 
  JOIN marca 
    ON (sig_patrimonio.marca = marca.marca 
    AND sig_patrimonio.tipo_marca = marca.tipo_marca) 
WHERE sig_patrimonio.sec_ejec = sig_asignaciones.sec_ejec
  and sig_patrimonio.tipo_modalidad = sig_asignaciones.tipo_modalidad
  and sig_patrimonio.secuencia = sig_asignaciones.secuencia
  and sig_asignaciones.ano_eje = @al_ejec_anno
  and sig_asignaciones.sec_ejec = @al_ejec_sec
  and sig_asignaciones.nro_asignac = ( Select max(nro_asignac) from sig_asignaciones a 
                                        where a.ano_eje = sig_asignaciones.ano_eje 
                                          and a.sec_ejec = sig_asignaciones.sec_ejec 
                                          and a.tipo_modalidad = sig_asignaciones.tipo_modalidad 
                                          and a.secuencia  =sig_asignaciones.secuencia )
  and not exists ( Select p.secuencia from sig_patrimonio p 
                    where p.sec_ejec = sig_patrimonio.sec_ejec 
                      and p.tipo_modalidad = sig_patrimonio.tipo_modalidad 
                      and p.secuencia=sig_patrimonio.secuencia 
                      and ( p.mayor is null or p.mayor=''))
 
    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_TIPO_BIEN,      @LC_GRUPO_BIEN,     @LC_CLASE_BIEN, 
	     @LC_FAMILIA_BIEN,   @LC_ITEM_BIEN,      @LC_TIPO_DOCUMENTO, 
	     @LC_VALOR_NEA,      @LC_FECHA_NEA,      @LC_MEDIDAS,
	     @LC_ESTADO_ACTUAL,  @LC_ESTADO_CONSERV, @LC_FECHA_COMPRA,
	     @LC_VALOR_COMPRA,   @LC_NRO_ORDEN,      @LC_FEC_FIN_VIDA,
	     @LC_VIDA_UTIL,      @LC_TIPO_MODALIDAD, @LC_CENTRO_COSTO,
	     @LC_CODIGO_ACTIVO,  @LC_DESCRIPCION,    @LC_MODELO,
	     @LC_NRO_SERIE,      @LC_NOMBRE,         @LC_MARCA,
	     @LC_ESTADO,         @LC_ANO_PROCESO,    @LC_MES_PROCESO,
	     @V_SECUENCIA_PATRI, @V_MAYOR_PATRI,     @V_SUB_CTA_PATRI,  
	     @LC_ESTADO_ASIG,    @SEDE,				 @D_SEDE, 
	     @COD_ESTABLEC,      @D_COD_ESTABLEC,    @COD_CATEGORIA,
         @D_CORTO_COD_CATEGORIA, @V_COD_OGEI,    @V_SECTOR_AMBITO,
         @LC_NOMBRE_DEPEND  ,@LC_SECTOR,		 @LC_NOM_SECTOR ,
		 @LC_PLIEGO ,		 @LC_NOM_PLIEGO ,     @LC_nombre_dpto_pto,
		 @LC_nombre_PROV_PTO,@LC_nombre_DIST_PTO ,@LC_PTO_ATEN_DISA,	
		 @LC_PTO_ATEN_RED ,	 @LC_PTO_ATEN_MICRORED	     
	     
    WHILE @@FETCH_STATUS = 0
 BEGIN
	SET @LN_ID_SI_PATRIMONIO = @LN_ID_SI_PATRIMONIO + 1

	select 
		  @V_ANO_PATRIMONIO  = COALESCE(CAST(mc.ano_eje AS VARCHAR(50)), '') , 
		   @V_MES_PATRIMONIO  = COALESCE(mc.nmes_proc_amc,'') ,
		   @V_DES_MES_PATRIMONIO =(select nombre from sig_maestro_det_cadena 
							 where cod_maestro = 'MES_PROC_CTBLE' 
							   and cod_detalle = mc.nmes_proc_amc) ,
		   @V_FECHA_MOVIMTO_PATRI = COALESCE(convert(varchar(10),mc.fecha_movimto,111),'')  ,
		   @V_VALOR_NETO = COALESCE(CAST(mc.hvalor_inicial - (mc.hdepr_inicial + mc.hdepr_ejercicio + mc.hdepr_ajustada)  AS VARCHAR(50)), '') , 
		   @V_DEPREC_ACUMALDA = COALESCE(CAST((mc.hdepr_inicial + mc.hdepr_ejercicio + mc.hdepr_ajustada)  AS VARCHAR(50)), '') ,

		   @V_SUB_CTA = mc.MAYOR + mc.sub_cta,
		   @V_NOM_SUB_CTA = pc.nombre

	from sig_movimiento_contable mc,
	     plan_ctb_sub_cta pc

	WHERE 
	    mc.ano_eje = pc.ano_eje
	AND mc.mayor = pc.mayor
	AND mc.sub_Cta = pc.sub_cta
      AND  mc.ano_eje = @al_ejec_anno 
      AND mc.SEC_EJEC = @al_ejec_sec
      AND mc.TIPO_MODALIDAD = @LC_TIPO_MODALIDAD 
      AND mc.SECUENCIA = @V_SECUENCIA_PATRI 
      AND mc.nmes_proc_amc = (select max(nmes_proc_amc) from sig_movimiento_contable
                            WHERE ANO_EJE = mc.ano_eje 
                              AND SEC_EJEC = mc.sec_ejec
                              AND TIPO_MODALIDAD = mc.tipo_modalidad
                              AND SECUENCIA = mc.secuencia
                              AND NMES_PROC_AMC < '13')

	SET @V_SUB_CTA = COALESCE(@V_SUB_CTA,'')
	SET @V_NOM_SUB_CTA = COALESCE(@V_NOM_SUB_CTA,'')
	SET @V_DES_MES_PATRIMONIO = COALESCE(@V_DES_MES_PATRIMONIO,'')
	SET @V_ANO_PATRIMONIO = COALESCE(@V_ANO_PATRIMONIO,'')
	SET @V_MES_PATRIMONIO = COALESCE(@V_MES_PATRIMONIO,'')
	SET @V_FECHA_MOVIMTO_PATRI = COALESCE(@V_FECHA_MOVIMTO_PATRI,'')
	SET @V_VALOR_NETO  = COALESCE(@V_VALOR_NETO,'')
	SET @V_DEPREC_ACUMALDA  = COALESCE(@V_DEPREC_ACUMALDA,'')
	
    insert into dbo.tmp_ppr_PATRIMONIO
	 (  ANO_EJE,        SEC_EJEC,        ID_SI_PATRIMONIO, 
		TIPO_BIEN,      GRUPO_BIEN,      CLASE_BIEN,     
		FAMILIA_BIEN,   ITEM_BIEN,		 ITEM_CATALOGO,   
		TIPO_DOCUMENTO, VALOR_NEA,       FECHA_NEA,
		MEDIDAS,        ESTADO_ACTUAL,   ESTADO_CONSERVACION,
		FECHA_COMPRA,   VALOR_COMPRA,    NRO_ORDEN,
		FECHA_FIN_VIDA, VIDA_UTIL,       TIPO_MODALIDAD,
		CENTRO_COSTO,   D_CENTRO_COSTO,  CODIGO_ACTIVO,
		MODELO,         NRO_SERIE,       DESCRIPCION_ACTIVO, 
		CODIGO_MARCA,   NOMBRE_MARCA,    ESTADO_ACTIVO,
		ANO_PROCESO,    MES_PROCESO,	 SEDE,    
		D_SEDE,         COD_ESTABLEC,     
		D_COD_ESTABLEC, COD_CATEGORIA,	 D_CORTO_COD_CATEGORIA,
		ANO_PATRIMONIO, MES_PATRIMONIO,  DES_MES_PATRIMONIO,
		FECHA_MOVIMTO_PATRI, VALOR_NETO, SUB_CTA,
		NOM_SUB_CTA,    SECTOR_AMBITO,	 COD_RENAES,
		DEPREC_ACUMULADA, ASIGNACION,	SECTOR,
		NOM_SECTOR ,	PLIEGO ,		NOM_PLIEGO ,
		nombre_dpto_pto,nombre_PROV_PTO,nombre_DIST_PTO ,
		PTO_ATEN_DISA,	PTO_ATEN_RED ,	PTO_ATEN_MICRORED)
	 VALUES 
	 (  @al_ejec_anno,              @al_ejec_sec,         @LN_ID_SI_PATRIMONIO,
		@LC_TIPO_BIEN,      @LC_GRUPO_BIEN,     @LC_CLASE_BIEN,     
		@LC_FAMILIA_BIEN,   @LC_ITEM_BIEN,		@LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN,		
		@LC_TIPO_DOCUMENTO, @LC_VALOR_NEA,      @LC_FECHA_NEA,   
		@LC_MEDIDAS,        @LC_ESTADO_ACTUAL,  @LC_ESTADO_CONSERV,
		@LC_FECHA_COMPRA,   @LC_VALOR_COMPRA,   @LC_NRO_ORDEN,
		@LC_FEC_FIN_VIDA,   @LC_VIDA_UTIL,      @LC_TIPO_MODALIDAD,
		@LC_CENTRO_COSTO,   @LC_NOMBRE_DEPEND,  @LC_CODIGO_ACTIVO,
		@LC_MODELO,         @LC_NRO_SERIE,      @LC_DESCRIPCION, 
		@LC_MARCA,          @LC_NOMBRE,         @LC_ESTADO,
		@LC_ANO_PROCESO,	@LC_MES_PROCESO,    @SEDE,   
		@D_SEDE,            @COD_ESTABLEC,		
		@D_COD_ESTABLEC,    @COD_CATEGORIA,     @D_CORTO_COD_CATEGORIA,
		@V_ANO_PATRIMONIO,  @V_MES_PATRIMONIO,  @V_DES_MES_PATRIMONIO,
		@V_FECHA_MOVIMTO_PATRI, @V_VALOR_NETO,	@V_SUB_CTA,
		@V_NOM_SUB_CTA,     @V_SECTOR_AMBITO,	@V_COD_OGEI,
		@V_DEPREC_ACUMALDA, @LC_ESTADO_ASIG,	@LC_SECTOR,		 
		@LC_NOM_SECTOR ,	@LC_PLIEGO ,		@LC_NOM_PLIEGO ,
		@LC_nombre_dpto_pto,@LC_nombre_PROV_PTO,@LC_nombre_DIST_PTO ,
		@LC_PTO_ATEN_DISA,	@LC_PTO_ATEN_RED ,	@LC_PTO_ATEN_MICRORED  )
		

	set @V_ANO_PATRIMONIO = null
	set @V_MES_PATRIMONIO = null
	set @V_DES_MES_PATRIMONIO = null
	set @V_FECHA_MOVIMTO_PATRI = null
	set @V_VALOR_NETO = null
	set @V_DEPREC_ACUMALDA  = null
	set @V_SUB_CTA = null
	set @V_NOM_SUB_CTA = null

	FETCH NEXT FROM C_1
    INTO @LC_TIPO_BIEN,      @LC_GRUPO_BIEN,     @LC_CLASE_BIEN, 
	     @LC_FAMILIA_BIEN,   @LC_ITEM_BIEN,      @LC_TIPO_DOCUMENTO, 
	     @LC_VALOR_NEA,      @LC_FECHA_NEA,      @LC_MEDIDAS,
	     @LC_ESTADO_ACTUAL,  @LC_ESTADO_CONSERV, @LC_FECHA_COMPRA,
	     @LC_VALOR_COMPRA,   @LC_NRO_ORDEN,      @LC_FEC_FIN_VIDA,
	     @LC_VIDA_UTIL,      @LC_TIPO_MODALIDAD, @LC_CENTRO_COSTO,
	     @LC_CODIGO_ACTIVO,  @LC_DESCRIPCION,    @LC_MODELO,
	     @LC_NRO_SERIE,      @LC_NOMBRE,         @LC_MARCA,
	     @LC_ESTADO,         @LC_ANO_PROCESO,    @LC_MES_PROCESO,
	     @V_SECUENCIA_PATRI, @V_MAYOR_PATRI,     @V_SUB_CTA_PATRI,  
	     @LC_ESTADO_ASIG,    @SEDE,				 @D_SEDE, 
	     @COD_ESTABLEC,      @D_COD_ESTABLEC,    @COD_CATEGORIA,
         @D_CORTO_COD_CATEGORIA, @V_COD_OGEI,    @V_SECTOR_AMBITO,
         @LC_NOMBRE_DEPEND , @LC_SECTOR,		 @LC_NOM_SECTOR ,
		 @LC_PLIEGO ,		 @LC_NOM_PLIEGO   ,	  @LC_nombre_dpto_pto,
		 @LC_nombre_PROV_PTO,@LC_nombre_DIST_PTO ,@LC_PTO_ATEN_DISA,	
		 @LC_PTO_ATEN_RED ,	@LC_PTO_ATEN_MICRORED
    END
    CLOSE C_1
    DEALLOCATE C_1   
 

	--17.GRUPO	
	UPDATE 	tmp_ppr_PATRIMONIO
	SET GRUPO_BIEN_C= TIPO_BIEN+GRUPO_BIEN+' - '+(	SELECT nombre_grupo 
					FROM grupo_bien_serv
					WHERE tipo_bien= tmp_ppr_PATRIMONIO.TIPO_BIEN AND grupo_bien=tmp_ppr_PATRIMONIO.GRUPO_BIEN AND
					ESTADO ='A') 	
   
	WHERE
	ano_eje=@al_ejec_anno AND
	SEC_EJEC=@al_ejec_sec 


	--17.CLASE	
	UPDATE 	tmp_ppr_PATRIMONIO
	SET CLASE_BIEN_C=TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+' - '+(	SELECT nombre_clase 
						FROM clase_bien_serv
						WHERE tipo_bien= tmp_ppr_PATRIMONIO.TIPO_BIEN AND 
						grupo_bien=tmp_ppr_PATRIMONIO.grupo_bien 
						AND clase_bien= tmp_ppr_PATRIMONIO.CLASE_BIEN and
						ESTADO ='A') 	
	   
	WHERE
	ano_eje=@al_ejec_anno AND
	SEC_EJEC=@al_ejec_sec 


	--18. FAMILIA	
	UPDATE 	tmp_ppr_PATRIMONIO
	SET FAMILIA_BIEN_C=TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+' - '+(	SELECT nombre_fam 
						FROM familia_bien_serv
						WHERE tipo_bien= tmp_ppr_PATRIMONIO.TIPO_BIEN AND 
						grupo_bien=tmp_ppr_PATRIMONIO.grupo_bien 
						AND clase_bien= tmp_ppr_PATRIMONIO.CLASE_BIEN AND 
						familia_bien=tmp_ppr_PATRIMONIO.FAMILIA_BIEN AND
						ESTADO ='A') 	
	   
	WHERE	ano_eje=@al_ejec_anno AND
	SEC_EJEC=@al_ejec_sec 


	--20. ITEM
    UPDATE 	tmp_ppr_PATRIMONIO
    SET ITEM_BIEN_C= TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+ITEM_BIEN+' - '+
    (	SELECT NOMBRE_ITEM COLLATE Modern_Spanish_CI_AS 
    FROM CATALOGO_BIEN_SERV
    WHERE 
    SEC_EJEC= tmp_ppr_PATRIMONIO.SEC_EJEC AND
    tipo_bien= tmp_ppr_PATRIMONIO.TIPO_BIEN AND 
    grupo_bien=tmp_ppr_PATRIMONIO.grupo_bien 
    AND clase_bien= tmp_ppr_PATRIMONIO.CLASE_BIEN AND 
    familia_bien=tmp_ppr_PATRIMONIO.FAMILIA_BIEN 
    AND ITEM_BIEN= tmp_ppr_PATRIMONIO.ITEM_BIEN AND					
    ESTADO ='A')
    WHERE
    ano_eje=@al_ejec_anno AND
    SEC_EJEC=@al_ejec_sec

END
GO


-- ----------------------------
-- procedure structure for SP_SI_TRANSMISION_PROGRAMACION_PPR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_TRANSMISION_PROGRAMACION_PPR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_TRANSMISION_PROGRAMACION_PPR]
GO

CREATE PROCEDURE [dbo].[SP_SI_TRANSMISION_PROGRAMACION_PPR] 
@P_ANO_EJE numeric(4, 0),  @P_SEC_EJEC numeric(6, 0), @P_FASE_CUADRO numeric(1, 0), @O_ERR_NUM numeric(6, 0) OUTPUT, @O_ERR_MSG varchar(255) OUTPUT
WITH EXEC AS CALLER
AS
BEGIN

IF OBJECT_ID ('dbo.SIG_TRANS_PROGRAMACION_TMP2') IS NOT NULL
      DROP TABLE dbo.SIG_TRANS_PROGRAMACION_TMP2

truncate    TABLE  dbo.SIG_TRANS_PROGRAMACION_UE2

SELECT
SIG_PPR_METFIS_X_SUBFIN.ANO_EJE,
SIG_PPR_METFIS_X_SUBFIN.NRO_FASE FASE_CUADRO,
CASE SIG_PPR_METFIS_X_SUBFIN.NRO_FASE
	  WHEN 1 THEN 'REQUERIDO'
	  WHEN 2 THEN 'PROGRAMADO/ANTEPROYECTO'
	  WHEN 5 THEN 'APROBADO'
END FASE,
SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC,     
SECTOR.SECTOR SECTOR,
SECTOR.SECTOR  +' - '+ RTRIM(SECTOR.NOMBRE) NOM_SECTOR,
PLIEGO.pliego PLIEGO,
RTRIM( PLIEGO.pliego+' - '+PLIEGO.nombre) NOM_PLIEGO, 
 EJECUTORA.sec_ejec EJECUTORA,
CONVERT (VARCHAR, EJECUTORA.sec_ejec)+' - '+  EJECUTORA.nombre NOM_EJECUTORA,
COALESCE(SIG_PPR_SEDE.COD_ESTABLEC ,'00000') PTO_ATEN,
SIG_PPR_ESTABLECIMIENTO.DESC_ESTABLEC DESC_ESTABLEC,
SIG_PPR_CATEGORIA.CATEGORIA PTO_ATEN_CATEGORIA,
			LTRIM(RTRIM(SIG_PPR_CATEGORIA.NOMBRE_CORTO)) nom_categoria,
CASE LEN (COALESCE( SIG_PPR_ESTABLECIMIENTO.COD_OGEI,'00000')) 
	  WHEN 4 THEN '0'+ SIG_PPR_ESTABLECIMIENTO.COD_OGEI 
	  ELSE      COALESCE( SIG_PPR_ESTABLECIMIENTO.COD_OGEI,'00000')
END PTO_ATEN_COD_RENAES,
CASE  SIG_PPR_ESTABLECIMIENTO.CATEGORIA
	  WHEN 9 THEN 'M'
	  WHEN 99 THEN 'N'
		ELSE 'F'
END TIPO_PTO_ATEN,
SIG_PPR_ESTABLECIMIENTO.UBIGEO ,
COALESCE( SIG_PPR_DISA.DESC_DISA,'NO TIENE') PTO_ATEN_DISA,
COALESCE( SIG_PPR_RED.DESC_RED,'NO TIENE') PTO_ATEN_RED,
COALESCE( SIG_PPR_MICRORED.DESC_MICRORED,'NO TIENE') PTO_ATEN_MICRORED,
COALESCE(SIG_PPR_TIPO_INSTITUCION.INST_DESCRI,'NO TIENE') PTO_ATEN_INSTITUCION,
SIG_PPR_ESTABLECIMIENTO.ESTADO estado_pto,
CASE  SIG_PPR_ESTABLECIMIENTO.ESTADO
	  WHEN 'A' THEN 'Activo'
	  WHEN 'I' THEN 'Activo'
	  ELSE   'NO TIENE'
END NOM_PTO_ATEN_ESTADO,
SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC SEC_FUNC1,
SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC SEC_FUNC2,
SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC,
COALESCE(SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD,0000000) SUB_PRODUCTO,
CASE  SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD
	  WHEN '' THEN '0000000 - SIN SUB_PRODUCTO'
	  ELSE      SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD +' - '+ SIG_SUB_FINALIDAD.NOMBRE
END NOM_SUB_PRODUCTO,
CASE  SIG_SUB_FINALIDAD.TRAZADOR
	  WHEN 1 THEN 'S'
	  ELSE 'N'
END TRAZADOR,
COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_01,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_02,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_03,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_04,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_05,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_06,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_07,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_08,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_09,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_10,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_11,0)+COALESCE(SIG_PPR_METFIS_X_SUBFIN.CANT_12,0) META_FISICA,


'.' AS CLASIFICADOR,
'.' AS GENERICA,
'.' AS SUB_GENERICA1,
'.' AS SUB_GENERICA2,
'.' AS ESPECIFICA1,
'.' AS ESPECIFICA2,
'.' AS TIPO_BIEN, 
'.' AS GRUPO_BIEN, 
'.' AS CLASE_BIEN,
'.' AS FAMILIA_BIEN,
'.' AS ITEM_BIEN,
'.' AS ITEM_CATALOGO,
CONVERT(VARCHAR(20), UNIDAD_MEDIDA.UNIDAD_MEDIDA) + UNIDAD_MEDIDA.NOMBRE NOM_unidad_medida,
UNIDAD_MEDIDA.UNIDAD_MEDIDA AS UNIDAD_MEDIDA,

0 AS PRECIO_UNIT,
0 AS CANTIDAD,
0 AS MONTO,
SIG_PPR_METFIS_X_SUBFIN.ID_SUB_FINALIDAD,
SIG_PPR_METFIS_X_SUBFIN.UNIDAD_MEDIDA AS SUB_PRODUCTO_UM,
SIG_PPR_ESTABLECIMIENTO.SECTOR_AMBITO
into SIG_TRANS_PROGRAMACION_TMP2
FROM
SIG_PPR_ESTABLECIMIENTO LEFT
OUTER JOIN  SIG_PPR_DISA  ON
( SUBSTRING(SIG_PPR_ESTABLECIMIENTO.CAD_OPERATIVA,1,2) = SIG_PPR_DISA.COD_DISA  AND
SIG_PPR_DISA.ESTADO='A') LEFT
OUTER JOIN SIG_PPR_RED ON
(SUBSTRING(SIG_PPR_ESTABLECIMIENTO.CAD_OPERATIVA,1,4) = SIG_PPR_RED.COD_DISA + SIG_PPR_RED.COD_RED  AND 
SIG_PPR_RED.ESTADO='A') LEFT
OUTER JOIN SIG_PPR_MICRORED ON 
(SUBSTRING(SIG_PPR_ESTABLECIMIENTO.CAD_OPERATIVA,1,6) = SIG_PPR_MICRORED.COD_DISA + SIG_PPR_MICRORED.COD_RED + SIG_PPR_MICRORED.COD_MICRORED AND
SIG_PPR_MICRORED.ESTADO='A') LEFT
OUTER JOIN       SIG_PPR_TIPO_INSTITUCION ON 
(SIG_PPR_TIPO_INSTITUCION.INST_TIPO= SIG_PPR_ESTABLECIMIENTO.INST_TIPO  ),
SIG_PPR_METFIS_X_SUBFIN,
SIG_PPR_CATEGORIA,
SECTOR,
UNIDAD_MEDIDA,
EJECUTORA,
PLIEGO,
SIG_PPR_SEDE,
SIG_PPR_META_PROPUESTA,
SIG_SUB_FINALIDAD
WHERE		SIG_PPR_METFIS_X_SUBFIN.ANO_EJE				= @P_ANO_EJE
AND		SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC				= @P_SEC_EJEC
AND		SIG_PPR_METFIS_X_SUBFIN.NRO_FASE				= @P_FASE_CUADRO
AND		SIG_PPR_METFIS_X_SUBFIN.UNIDAD_MEDIDA		= UNIDAD_MEDIDA.UNIDAD_MEDIDA
AND		SIG_PPR_METFIS_X_SUBFIN.ANO_EJE				= SIG_PPR_SEDE.ANO_EJE
AND		SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC				= SIG_PPR_SEDE.SEC_EJEC
AND		SIG_PPR_METFIS_X_SUBFIN.SEC_ESTABLEC		= SIG_PPR_SEDE.SEC_ESTABLEC
AND		SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC				= EJECUTORA.SEC_EJEC
AND		'A'													= EJECUTORA.ESTADO
AND		PLIEGO.SECTOR										= EJECUTORA.SECTOR
AND		PLIEGO.PLIEGO										= EJECUTORA.PLIEGO
AND		PLIEGO.ESTADO										= 'A'
AND		SECTOR.SECTOR										= EJECUTORA.SECTOR
AND		SIG_PPR_ESTABLECIMIENTO.ANO_EJE				= SIG_PPR_SEDE.ANO_EJE
AND		SIG_PPR_ESTABLECIMIENTO.SEC_EJEC				= SIG_PPR_SEDE.SEC_EJEC
AND		SIG_PPR_ESTABLECIMIENTO.COD_ESTABLEC		= SIG_PPR_SEDE.COD_ESTABLEC
AND		SIG_PPR_ESTABLECIMIENTO.ANO_EJE				= SIG_PPR_CATEGORIA.ANO_EJE
AND		SIG_PPR_ESTABLECIMIENTO.CATEGORIA			= SIG_PPR_CATEGORIA.CATEGORIA
AND		'01'													= SIG_PPR_CATEGORIA.SECTOR_AMBITO
AND		'A'													= SIG_PPR_CATEGORIA.ESTADO
AND SIG_SUB_FINALIDAD.ANO_EJE				 	    = SIG_PPR_METFIS_X_SUBFIN.ANO_EJE
AND SIG_SUB_FINALIDAD.SUB_FINALIDAD  			= SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD
AND SIG_SUB_FINALIDAD.ID_SUB_FINALIDAD  	= SIG_PPR_METFIS_X_SUBFIN.ID_SUB_FINALIDAD
AND SIG_SUB_FINALIDAD.PROGRAMA_INSTITUCIONAL = SIG_PPR_META_PROPUESTA.ESTRATEGIA_NACIONAL
AND SIG_SUB_FINALIDAD.componente            = SIG_PPR_META_PROPUESTA.componente
AND SIG_PPR_META_PROPUESTA.FLAG_ESTRATEGIA = 'S'
AND SIG_PPR_META_PROPUESTA.ANO_EJE        = SIG_PPR_METFIS_X_SUBFIN.ANO_EJE
AND SIG_PPR_META_PROPUESTA.SEC_EJEC      = SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC
AND SIG_PPR_META_PROPUESTA.NRO_FASE      = SIG_PPR_METFIS_X_SUBFIN.NRO_FASE
AND SIG_PPR_META_PROPUESTA.SEC_FUNC_PROP = SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC







INSERT INTO SIG_TRANS_PROGRAMACION_UE2  (             ano_eje,                      fase_cuadro,                 FASE,                              SEC_EJEC,                     NOM_SECTOR,
      SECTOR,                      PLIEGO,                                  NOM_PLIEGO,                   EJECUTORA,                  NOM_EJECUTORA,               
      PTO_ATEN_CATEGORIA,   nom_categoria,               PTO_ATEN_COD_RENAES  ,       TIPO_PTO_ATEN        ,  UBIGEO             ,    PTO_ATEN_DISA        , 
      PTO_ATEN_RED      ,     PTO_ATEN_MICRORED,                  PTO_ATEN_INSTITUCION ,      estado_pto     ,        NOM_PTO_ATEN_ESTADO,    sec_func,                     SUB_PRODUCTO      ,        
      NOM_SUB_PRODUCTO  ,     TRAZADOR        ,            META_FISICA          ,       CLASIFICADOR         ,                   GENERICA             , 
      SUB_GENERICA1     ,     SUB_GENERICA2   ,            ESPECIFICA1        ,    ESPECIFICA2        ,                TIPO_BIEN          ,    
      GRUPO_BIEN       ,      CLASE_BIEN      ,            FAMILIA_BIEN       ,    ITEM_BIEN                   ,     NOM_unidad_medida,           unidad_medida      ,    PRECIO_UNIT        ,   
      CANTIDAD         ,      MONTO             ,                             ID_SUB_FINALIDAD,       ITEM_CATALOGO,               PTO_ATEN ,                    DESC_ESTABLEC, 
      SUB_PRODUCTO_UM , SECTOR_AMBITO)

SELECT                                                                 ano_eje,                     fase_cuadro,                 FASE,                              SEC_EJEC,                     NOM_SECTOR,
      SECTOR,                      PLIEGO,                                  NOM_PLIEGO,                   EJECUTORA,                   NOM_EJECUTORA,              
      PTO_ATEN_CATEGORIA,                nom_categoria,               PTO_ATEN_COD_RENAES  ,      TIPO_PTO_ATEN        ,  UBIGEO             ,    PTO_ATEN_DISA        ,  
      PTO_ATEN_RED    , PTO_ATEN_MICRORED,                 PTO_ATEN_INSTITUCION , estado_pto     ,    NOM_PTO_ATEN_ESTADO,    sec_func,                    SUB_PRODUCTO      ,     
      NOM_SUB_PRODUCTO ,      TRAZADOR        ,            META_FISICA          ,      CLASIFICADOR         ,                   GENERICA             ,  
      SUB_GENERICA1    ,      SUB_GENERICA2   ,                  ESPECIFICA1        ,        ESPECIFICA2        ,               TIPO_BIEN          ,     
      GRUPO_BIEN       ,      CLASE_BIEN      ,            FAMILIA_BIEN       ,    ITEM_BIEN                   ,     NOM_unidad_medida,           unidad_medida      ,    PRECIO_UNIT        ,   
      CANTIDAD         ,  MONTO                ,                      ID_SUB_FINALIDAD,       ITEM_CATALOGO ,              PTO_ATEN,                     DESC_ESTABLEC, 
      SUB_PRODUCTO_UM, SECTOR_AMBITO

FROM SIG_TRANS_PROGRAMACION_TMP2

      IF (@@error <> 0)
            begin
                  set @O_ERR_MSG = 'No existen datos para los filtros seleccionados.Verificar'
                  RETURN
            End


UPDATE SIG_TRANS_PROGRAMACION_UE2
SET nombre_DPTO_PTO ='NO TIENE',
      NOMBRE_PROV_PTO= 'NO TIENE',
      NOMBRE_DIST_PTO ='NO TIENE'
      WHERE ano_eje= @P_ANO_EJE  AND
      SEC_EJEC= @P_SEC_EJEC AND
      UBIGEO='000000'  AND
      fase_cuadro= @P_FASE_CUADRO

UPDATE SIG_TRANS_PROGRAMACION_UE2  
SET nombre_DPTO_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
                                   WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,1,2) AND UBG.provincia='00' AND
                                   UBG.distrito='00' AND UBG.estado='A' )
WHERE  nombre_DPTO_PTO IS NULL AND 
      ano_eje= @P_ANO_EJE AND
      SEC_EJEC=@P_SEC_EJEC  AND
      fase_cuadro= @P_FASE_CUADRO        

UPDATE SIG_TRANS_PROGRAMACION_UE2  
SET nombre_PROV_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
                                   WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,1,2) AND 
                                           UBG.provincia= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,3,2) AND
                                         UBG.distrito='00' AND UBG.estado='A' )
WHERE  nombre_PROV_PTO IS NULL AND 
            ano_eje=@P_ANO_EJE AND
            SEC_EJEC=@P_SEC_EJEC AND
            fase_cuadro= @P_FASE_CUADRO



UPDATE SIG_TRANS_PROGRAMACION_UE2  
SET nombre_DIST_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
                                   WHERE UBG.departamento= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,1,2) AND 
                                         UBG.provincia= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,3,2) AND
                                         UBG.distrito= SUBSTRING(SIG_TRANS_PROGRAMACION_UE2.UBIGEO,5,2)  AND 
                                         UBG.estado='A' )
WHERE  nombre_DIST_PTO IS NULL AND 
            ano_eje=@P_ANO_EJE AND
            SEC_EJEC=@P_SEC_EJEC AND
            fase_cuadro= @P_FASE_CUADRO


UPDATE SIG_TRANS_PROGRAMACION_UE2
SET ESTRATEGIA_NACIONAL = (SELECT smp.ESTRATEGIA_NACIONAL
                                   FROM SIG_META_PROPUESTA smp 
                                   WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                                   smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE2.SEC_EJEC AND
                                   smp.SEC_FUNC_PROP= SIG_TRANS_PROGRAMACION_UE2.sec_func ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC AND
fase_cuadro= @P_FASE_CUADRO AND @P_FASE_CUADRO< 5
      
UPDATE SIG_TRANS_PROGRAMACION_UE2
SET ESTRATEGIA_NACIONAL = (SELECT smp.ESTRATEGIA_NACIONAL
                                   FROM META smp 
                                   WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                                   smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE2.SEC_EJEC AND
                                   smp.SEC_FUNC= SIG_TRANS_PROGRAMACION_UE2.sec_func ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC AND
fase_cuadro= @P_FASE_CUADRO AND @P_FASE_CUADRO = 5


UPDATE SIG_TRANS_PROGRAMACION_UE2
      SET CATEG_PPTAL = 'ACCIONES (SIN PROGRAMA)'
  WHERE  
      ano_eje=@P_ANO_EJE AND
      SEC_EJEC=@P_SEC_EJEC  AND
      ESTRATEGIA_NACIONAL= '9001'  AND
      fase_cuadro= @P_FASE_CUADRO
      
UPDATE SIG_TRANS_PROGRAMACION_UE2
SET CATEG_PPTAL = 'ASIGNACIONES (SIN PROGRAMA)'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC  AND
ESTRATEGIA_NACIONAL= '9002' and
fase_cuadro= @P_FASE_CUADRO 

UPDATE SIG_TRANS_PROGRAMACION_UE2
SET CATEG_PPTAL = 'CON PROGRAMA'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC  AND
ESTRATEGIA_NACIONAL NOT IN ('9001','9002') and
fase_cuadro= @P_FASE_CUADRO 


UPDATE SIG_TRANS_PROGRAMACION_UE2
SET META_PROG_PPTO = ESTRATEGIA_NACIONAL+' - '+(SELECT enn.NOMBRE
                  FROM 
                  ESTRATEGIA_NACIONAL_NOMBRE enn
                  WHERE enn.ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND
                  enn.ESTRATEGIA_NACIONAL= SIG_TRANS_PROGRAMACION_UE2.ESTRATEGIA_NACIONAL AND
                  enn.ESTADO='A') 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ESTRATEGIA_NACIONAL NOT IN ('9001','9002')


UPDATE SIG_TRANS_PROGRAMACION_UE2
SET META_PROG_PPTO = '0000 - SIN PROGRAMA PRESUPUESTAL'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ESTRATEGIA_NACIONAL  IN ('9001','9002')

UPDATE SIG_TRANS_PROGRAMACION_UE2
SET ACT_PROY = (SELECT smp.ACT_PROY
                                   FROM SIG_META_PROPUESTA smp 
                                   WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                                   smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE2.SEC_EJEC AND
                                   smp.SEC_FUNC_PROP= SIG_TRANS_PROGRAMACION_UE2.sec_func ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO AND @P_FASE_CUADRO <5
      

UPDATE SIG_TRANS_PROGRAMACION_UE2
SET ACT_PROY = (SELECT smp.ACT_PROY
                                   FROM meta smp 
                                   WHERE smp.ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                                   smp.SEC_EJEC= SIG_TRANS_PROGRAMACION_UE2.SEC_EJEC AND
                                   smp.SEC_FUNC= SIG_TRANS_PROGRAMACION_UE2.sec_func ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC AND
      fase_cuadro= 5 AND @P_FASE_CUADRO= 5
      
UPDATE SIG_TRANS_PROGRAMACION_UE2
SET META_PRODUCTO = ACT_PROY+' - '+(              
            SELECT LTRIM(RTRIM(NOMBRE))
                  FROM Act_Proy_Nombre_FASE  
                  WHERE ANO_EJE=  SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                             act_proy= SIG_TRANS_PROGRAMACION_UE2.ACT_PROY    AND 
                             estado= 'A' 
                             AND @P_FASE_CUADRO IN (1, 2)
            UNION
            
            SELECT NOMBRE 
                  FROM Act_Proy_Nombre  
                  WHERE ANO_EJE= SIG_TRANS_PROGRAMACION_UE2.ano_eje AND 
                             act_proy= SIG_TRANS_PROGRAMACION_UE2.ACT_PROY   AND 
                             estado= 'A'  
                             AND @P_FASE_CUADRO = 5
                  
                  ) 
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ACT_PROY NOT IN ('3999999')

UPDATE SIG_TRANS_PROGRAMACION_UE2
SET META_PRODUCTO = '000000 - SIN PRODUCTO'
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO  AND 
ACT_PROY  IN ('3999999')

UPDATE SIG_TRANS_PROGRAMACION_UE2
SET PTO_ATEN_NOMBRE =   PTO_ATEN_COD_RENAES+' - '+LTRIM(RTRIM(DESC_ESTABLEC ))
WHERE  
ano_eje=@P_ANO_EJE AND
SEC_EJEC=@P_SEC_EJEC and
fase_cuadro= @P_FASE_CUADRO 


END
GO


-- ----------------------------
-- procedure structure for SP_SIG_TECHO_MARCAS_DESCUADRE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_TECHO_MARCAS_DESCUADRE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_TECHO_MARCAS_DESCUADRE]
GO

CREATE PROCEDURE [dbo].[SP_SIG_TECHO_MARCAS_DESCUADRE]
@ai_ano_eje numeric(4), @an_sec_ejec numeric(6), @as_flag_fase_presup char(01)
 

AS
DECLARE
@ls_msg varchar(1000),
@ls_correlativo varchar(4),
@li_code numeric(8),
@li_count numeric(8),
--variables para calcular los valores del reg actual
@ls_origen varchar(1),
@ls_fuente_financ varchar(2),
@ls_categ_gasto   varchar(2),
@ls_grupo_gasto   varchar(2),
@ls_clasificador  varchar(14),
@ld_sec_func        numeric(4),
@ld_sum_ppto_progra numeric(15,2),
@ld_sum_ppto_asigna numeric(15,2), 
@ld_sum_ppto_aprob numeric(15,2),
@ld_ppto_req_meta   numeric(15,2),
@ld_ppto_req_clasificador   numeric(15,2),
@ld_ppto_req_clasificador_1 numeric(15,2),
@ld_ppto_req_categ_grupo    numeric(15,2),
@ld_ppto_req_categ_grupo_1  numeric(15,2),
@ld_ppto_req_fuente         numeric(15,2),
@ld_ppto_req_fuente_1       numeric(15,2),
@ld_ppto_asig_meta           numeric(15,2),
@ld_ppto_asig_clasificador   numeric(15,2),
@ld_ppto_asig_clasificador_1 numeric(15,2),
@ld_ppto_asig_categ_grupo    numeric(15,2),
@ld_ppto_asig_categ_grupo_1  numeric(15,2),
@ld_ppto_asig_fuente         numeric(15,2),
@ld_ppto_asig_fuente_1       numeric(15,2),
@ld_ppto_aprob_meta           numeric(15,2),
@ld_ppto_aprob_clasificador   numeric(15,2),
@ld_ppto_aprob_clasificador_1 numeric(15,2),
@ld_ppto_aprob_categ_grupo    numeric(15,2),
@ld_ppto_aprob_categ_grupo_1  numeric(15,2),
@ld_ppto_aprob_fuente         numeric(15,2),
@ld_ppto_aprob_fuente_1       numeric(15,2),
 
@as_message         varchar(30)
 

-- cursor para proceso en batch o en linea (1 bien)
DECLARE cbucle_techo_presupuestal CURSOR FOR
SELECT DISTINCT origen, fuente_financ, categ_gasto, grupo_gasto, clasificador, sec_func, sum(ppto_progra), sum(ppto_asignado), sum(ppto_aprob)
FROM sig_techo_presupuestal 
WHERE ano_eje  = @ai_ano_eje  
and   sec_ejec = @an_sec_ejec
and   indicador = '5'
group by origen, fuente_financ, categ_gasto, grupo_gasto, clasificador, sec_func
 
OPEN cbucle_techo_presupuestal
FETCH NEXT FROM cbucle_techo_presupuestal INTO @ls_origen, @ls_fuente_financ, @ls_categ_gasto, @ls_grupo_gasto, 
                   @ls_clasificador, @ld_sec_func, @ld_sum_ppto_progra, @ld_sum_ppto_asigna, @ld_sum_ppto_aprob
WHILE @@FETCH_STATUS = 0
BEGIN
-- se procesa los campos asociados a la fase del techo asignado
IF @as_flag_fase_presup = '1'
Begin 
 select @ld_ppto_req_meta = ppto_progra
 from sig_techo_presupuestal
 where ano_eje = @ai_ano_eje
 and sec_ejec  = @an_sec_ejec
 and origen    = @ls_origen
 and fuente_financ = @ls_fuente_financ 
 and categ_gasto   = @ls_categ_gasto
 and grupo_gasto   = @ls_grupo_gasto
 and clasificador  = @ls_clasificador
 and sec_func      = @ld_sec_func
 and indicador = '0';
 IF round(@ld_sum_ppto_progra,2) < round(@ld_ppto_req_meta,2) 
        Begin
  update sig_techo_presupuestal
  set cuadre_ppto_progra = '1'
  where ano_eje = @ai_ano_eje
  and sec_ejec = @an_sec_ejec
  and origen = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and clasificador  = @ls_clasificador
  and sec_func      = @ld_sec_func
  and indicador = '0';
  IF (@@error <> 0)
  begin
   close cbucle_techo_presupuestal
   DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 1'
   return -1
  End
  update sig_techo_presupuestal
  set cuadre_ppto_progra = '1'
  where ano_eje = @ai_ano_eje
  and sec_ejec = @an_sec_ejec
  and origen = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and clasificador  = @ls_clasificador
  and indicador = '3';
  IF (@@error <> 0)
  begin
   close cbucle_techo_presupuestal
   DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 2'
   return -1
  End
  update sig_techo_presupuestal
  set cuadre_ppto_progra = '1'
  where ano_eje = @ai_ano_eje
  and sec_ejec = @an_sec_ejec
  and origen = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and indicador = '2';
  IF (@@error <> 0)
  begin
   close cbucle_techo_presupuestal
   DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 3'
   return -1
  End
  update sig_techo_presupuestal
  set cuadre_ppto_progra = '1'
  where ano_eje = @ai_ano_eje
  and sec_ejec = @an_sec_ejec
  and origen = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and indicador = '1';
  IF (@@error <> 0)
  begin
   close cbucle_techo_presupuestal
   DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 4'
   return -1
  End
 end
 else
 IF round(@ld_sum_ppto_progra,2) = round(@ld_ppto_req_meta,2) 
 Begin
  update sig_techo_presupuestal
  set cuadre_ppto_progra = '0'
  where ano_eje = @ai_ano_eje
  and sec_ejec = @an_sec_ejec
  and origen = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and clasificador  = @ls_clasificador
  and sec_func      = @ld_sec_func
  and indicador = '0';
  IF (@@error <> 0)
  begin
   close cbucle_techo_presupuestal
   DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 1'
   return -1
  End
  select @ld_ppto_req_clasificador  = sum(ppto_progra) 
  from sig_techo_presupuestal
  where ano_eje = @ai_ano_eje
  and sec_ejec  = @an_sec_ejec
  and origen    = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and clasificador  = @ls_clasificador
  and indicador = '5';
 
  select @ld_ppto_req_clasificador_1 = ppto_progra 
  from sig_techo_presupuestal
  where ano_eje = @ai_ano_eje
  and sec_ejec  = @an_sec_ejec
  and origen    = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and clasificador  = @ls_clasificador
  and indicador = '3';
      
  if round(@ld_ppto_req_clasificador,2) = round(@ld_ppto_req_clasificador_1,2) 
  Begin
   update sig_techo_presupuestal
   set cuadre_ppto_progra = '0'
   where ano_eje = @ai_ano_eje
   and sec_ejec = @an_sec_ejec
   and origen = @ls_origen
   and fuente_financ = @ls_fuente_financ 
   and categ_gasto   = @ls_categ_gasto
   and grupo_gasto   = @ls_grupo_gasto
   and clasificador  = @ls_clasificador
   and indicador = '3';
   IF (@@error <> 0)
   begin
    close cbucle_techo_presupuestal
    DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 2'
    return -1
   End
  end 
  select @ld_ppto_req_categ_grupo  = sum(ppto_progra) 
  from sig_techo_presupuestal
  where ano_eje = @ai_ano_eje
  and sec_ejec  = @an_sec_ejec
  and origen    = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and indicador = '5';
 
  select @ld_ppto_req_categ_grupo_1 = ppto_progra 
  from sig_techo_presupuestal
  where ano_eje = @ai_ano_eje
  and sec_ejec  = @an_sec_ejec
  and origen    = @ls_origen
  and fuente_financ = @ls_fuente_financ 
  and categ_gasto   = @ls_categ_gasto
  and grupo_gasto   = @ls_grupo_gasto
  and indicador = '2';
      
  if round(@ld_ppto_req_categ_grupo,2) = round(@ld_ppto_req_categ_grupo_1,2) 
  Begin
   update sig_techo_presupuestal
   set cuadre_ppto_progra = '0'
   where ano_eje = @ai_ano_eje
   and sec_ejec = @an_sec_ejec
   and origen = @ls_origen
   and fuente_financ = @ls_fuente_financ 
   and categ_gasto   = @ls_categ_gasto
   and grupo_gasto   = @ls_grupo_gasto
   and indicador = '2';
   IF (@@error <> 0)
   begin
    close cbucle_techo_presupuestal
    DEALLOCATE cbucle_techo_presupuestal
   set @as_message = 'Error al actualizar el flag de descuadre de ppto programado 3'
    return -1
   End
  end 
  select @ld_ppto_req_fuente  = sum(ppto_progra) 
  from sig_techo_presupuestal
