-- ----------------------------
-- procedure structure for SP_GENERA_SGE_PATRIMONIO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERA_SGE_PATRIMONIO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_GENERA_SGE_PATRIMONIO]
GO

CREATE PROCEDURE [dbo].[SP_GENERA_SGE_PATRIMONIO] (@Anio int,@Ejecutora int,@MesIni  varchar(2),@MesFin  varchar(2))
AS

DELETE FROM SGE_PATRIMONIO_EXP
      WHERE ANO_EJE=@Anio
	AND SEC_EJEC=@Ejecutora
        AND MES_PROCESO BETWEEN ABS(@MesIni) AND ABS(@MesFin)

INSERT INTO SGE_PATRIMONIO_EXP
	    (ANO_EJE,SEC_EJEC,MES_PROCESO,TIPO_MOVIMTO,TIPO_BIEN,GRUPO_BIEN,CLASE_BIEN,FAMILIA_BIEN,
	    ITEM_BIEN,ESTADO_BIEN,VALOR_INICIAL,CLASIFICADOR,MAYOR,SUB_CTA,VIDA_UTIL,
	    TIPO_ENTIDAD,DEPARTAMENTO,PROVINCIA,CATEGORIA_GASTO,GRUPO,MODALIDAD,ELEMENTO_GASTO,
	    DEPRECIACION, SECTOR,PLIEGO)
     SELECT PA.ANO_EJE,PA.SEC_EJEC,DA.MES_PROCESO, MA.TIPO_MOVIMTO,PA.TIPO_BIEN,PA.GRUPO_BIEN,PA.CLASE_BIEN,
	    PA.FAMILIA_BIEN,PA.ITEM_BIEN,ESTADO_CONSERV ESTADO_BIEN,SUM(PA.VALOR_INICIAL) VALOR_INICIAL,
	    PA.CLASIFICADOR,PA.MAYOR,PA.SUB_CTA,PA.VIDA_UTIL,
	    E.TIPO_ENTIDAD,E.DEPARTAMENTO,E.PROVINCIA,SUBSTRING(PA.CLASIFICADOR,1,1) CATEGORIA_GASTO,
	    SUBSTRING(PA.CLASIFICADOR,2,1) GRUPO,SUBSTRING(PA.CLASIFICADOR,3,2) MODALIDAD,
	    SUBSTRING(PA.CLASIFICADOR,5,2) ELEMENTO_GASTO,PA.VALOR_DEPREC DEPRECIACION, E.SECTOR,E.PLIEGO
       FROM SIG_PATRIMONIO PA, SIG_MOVIMIENTO_ACTIVO MA, SIG_DETALLE_ACTIVOS DA,EJECUTORA E
      WHERE DA.ANO_EJE=MA.ANO_EJE
	    AND DA.SEC_EJEC=MA.SEC_EJEC
	    AND DA.MES_PROCESO=MA.MES_PROCESO
	    AND DA.TIPO_MOVIMTO=MA.TIPO_MOVIMTO
	    AND DA.NRO_MOVIMTO=MA.NRO_MOVIMTO
	    AND DA.ANO_EJE=PA.ANO_EJE
	    AND DA.SEC_EJEC=PA.SEC_EJEC
	    AND DA.SECUENCIA=PA.SECUENCIA
	    AND DA.TIPO_MODALIDAD=PA.TIPO_MODALIDAD
	    AND DA.SEC_EJEC=E.SEC_EJEC
	    AND DA.ANO_EJE=@Anio
	    AND DA.SEC_EJEC=@Ejecutora
	    AND DA.MES_PROCESO BETWEEN @MesIni AND @MesFin
   GROUP BY PA.ANO_EJE,PA.SEC_EJEC,DA.MES_PROCESO,MA.TIPO_MOVIMTO,PA.TIPO_BIEN,PA.GRUPO_BIEN,PA.CLASE_BIEN,
	    PA.FAMILIA_BIEN,PA.ITEM_BIEN,ESTADO_CONSERV,PA.CLASIFICADOR,PA.MAYOR,PA.SUB_CTA,PA.VIDA_UTIL,
	    E.TIPO_ENTIDAD,E.DEPARTAMENTO,E.PROVINCIA,PA.VALOR_DEPREC,E.SECTOR,E.PLIEGO;
--/
GO


