IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_CHECKINOBJECT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_CHECKINOBJECT]
GO

CREATE PROCEDURE [dbo].[DT_CHECKINOBJECT]
    @chObjectType  char(4),
    @vchObjectName varchar(255),
    @vchComment    varchar(255)='',
    @vchLoginName  varchar(255),
    @vchPassword   varchar(255)='',
    @iVCSFlags     int = 0,
    @iActionFlag   int = 0,   /* 0 => AddFile, 1 => CheckIn */
    @txStream1     Text = '', /* drop stream   */ /* There is a bug that if items are NULL they do not pass to OLE servers */
    @txStream2     Text = '', /* create stream */
    @txStream3     Text = ''  /* grant stream  */


as

	set nocount on

	declare @iReturn int
	declare @iObjectId int
	select @iObjectId = 0
	declare @iStreamObjectId int

	declare @VSSGUID varchar(100)
	select @VSSGUID = 'SQLVersionControl.VCS_SQL'

	declare @iPropertyObjectId int
	select @iPropertyObjectId  = 0

    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    declare @vchProjectName   varchar(255)
    declare @vchSourceSafeINI varchar(255)
    declare @vchServerName    varchar(255)
    declare @vchDatabaseName  varchar(255)
    declare @iReturnValue	  int
    declare @pos			  int
    declare @vchProcLinePiece varchar(255)

    
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSProject',       @vchProjectName   OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSourceSafeINI', @vchSourceSafeINI OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLServer',     @vchServerName    OUT
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSQLDatabase',   @vchDatabaseName  OUT

    if @chObjectType = 'PROC'
    begin
        if @iActionFlag = 1
        begin
            /* Procedure Can have up to three streams
            Drop Stream, Create Stream, GRANT stream */

            begin tran compile_all

            /* try to compile the streams */
            exec (@txStream1)
            if @@error <> 0 GOTO E_Compile_Fail

            exec (@txStream2)
            if @@error <> 0 GOTO E_Compile_Fail

            exec (@txStream3)
            if @@error <> 0 GOTO E_Compile_Fail
        end

        exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT
        if @iReturn <> 0 GOTO E_OAError

        exec @iReturn = master.dbo.sp_OAGetProperty @iObjectId, 'GetStreamObject', @iStreamObjectId OUT
        if @iReturn <> 0 GOTO E_OAError
        
        if @iActionFlag = 1
        begin
            
            declare @iStreamLength int
			
			select @pos=1
			select @iStreamLength = datalength(@txStream2)
			
			if @iStreamLength > 0
			begin
			
				while @pos < @iStreamLength
				begin
						
					select @vchProcLinePiece = substring(@txStream2, @pos, 255)
					
					exec @iReturn = master.dbo.sp_OAMethod @iStreamObjectId, 'AddStream', @iReturnValue OUT, @vchProcLinePiece
            		if @iReturn <> 0 GOTO E_OAError
            		
					select @pos = @pos + 255
					
				end
            
				exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
														'CheckIn_StoredProcedure',
														NULL,
														@sProjectName = @vchProjectName,
														@sSourceSafeINI = @vchSourceSafeINI,
														@sServerName = @vchServerName,
														@sDatabaseName = @vchDatabaseName,
														@sObjectName = @vchObjectName,
														@sComment = @vchComment,
														@sLoginName = @vchLoginName,
														@sPassword = @vchPassword,
														@iVCSFlags = @iVCSFlags,
														@iActionFlag = @iActionFlag,
														@sStream = ''
                                        
			end
        end
        else
        begin
        
            select colid, text into #ProcLines
            from syscomments
            where id = object_id(@vchObjectName)
            order by colid

            declare @iCurProcLine int
            declare @iProcLines int
            select @iCurProcLine = 1
            select @iProcLines = (select count(*) from #ProcLines)
            while @iCurProcLine <= @iProcLines
            begin
                select @pos = 1
                declare @iCurLineSize int
                select @iCurLineSize = len((select text from #ProcLines where colid = @iCurProcLine))
                while @pos <= @iCurLineSize
                begin                
                    select @vchProcLinePiece = convert(varchar(255),
                        substring((select text from #ProcLines where colid = @iCurProcLine),
                                  @pos, 255 ))
                    exec @iReturn = master.dbo.sp_OAMethod @iStreamObjectId, 'AddStream', @iReturnValue OUT, @vchProcLinePiece
                    if @iReturn <> 0 GOTO E_OAError
                    select @pos = @pos + 255                  
                end
                select @iCurProcLine = @iCurProcLine + 1
            end
            drop table #ProcLines

            exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
													'CheckIn_StoredProcedure',
													NULL,
													@sProjectName = @vchProjectName,
													@sSourceSafeINI = @vchSourceSafeINI,
													@sServerName = @vchServerName,
													@sDatabaseName = @vchDatabaseName,
													@sObjectName = @vchObjectName,
													@sComment = @vchComment,
													@sLoginName = @vchLoginName,
													@sPassword = @vchPassword,
													@iVCSFlags = @iVCSFlags,
													@iActionFlag = @iActionFlag,
													@sStream = ''
        end

        if @iReturn <> 0 GOTO E_OAError

        if @iActionFlag = 1
        begin
            commit tran compile_all
            if @@error <> 0 GOTO E_Compile_Fail
        end

    end

CleanUp:
	return

E_Compile_Fail:
	declare @lerror int
	select @lerror = @@error
	rollback tran compile_all
	RAISERROR (@lerror,16,-1)
	goto CleanUp

E_OAError:
	if @iActionFlag = 1 rollback tran compile_all
	exec dbo.dt_displayoaerror @iObjectId, @iReturn
	goto CleanUp
GO


-- ----------------------------
-- procedure structure for SP_PS_GRABA_PROPUESTAS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PS_GRABA_PROPUESTAS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PS_GRABA_PROPUESTAS]
GO

CREATE PROCEDURE [dbo].[SP_PS_GRABA_PROPUESTAS]
  (
  @pn_Ano_Eje NUMERIC,             @pn_Sec_Ejec NUMERIC,                @pn_Proceso NUMERIC,
  @pn_Sec_Pos NUMERIC,             @pv_Tipo_Generacion VARCHAR,         @pn_Convocatoria NUMERIC,
  @pn_Sec_Convocatoria NUMERIC,    @pv_User VARCHAR,                    @pv_Equipo  VARCHAR,
  @pn_PS_Importa NUMERIC
  )
AS


BEGIN

-- propuestas de proveedor
INSERT INTO SIG_PROPUESTA_PROVEEDOR (
       ANO_EJE,                             SEC_EJEC,                            TIPO_GENERACION,
       PROCESO,                             SEC_PROCESO,                         CONVOCATORIA,
       PROVEEDOR,                           FECHA,                               PROMPYME,
       SOBRE_NRO1,                          SOBRE_NRO2,
       NRO_COTIZACION,                      FECHA_COTIZACION,                    ESTADO,
       ESTADO_ENVIO,                        ORDEN,                               FECHA_REG,
       CUSER_ID,                            EQUIPO_REG,                          LOCALIDAD,
       FLAG_RNP,                            FLAG_DISCAPACIDAD,
       ESTADO_REQUISITO)
SELECT DISTINCT
       SIG_PROPUESTA_ARCHIVO.ANO_EJE,       SIG_PROPUESTA_ARCHIVO.SEC_EJEC,      @pv_Tipo_Generacion,
       @pn_Proceso,                         @pn_Sec_Pos,                         @pn_Convocatoria,
       SIG_CONTRATISTAS.PROVEEDOR,          GETDATE(),                             'N', 
       NULL,                                NULL,
       NULL,                                NULL,                                'S',
       NULL,                                NULL,                                GETDATE(),
       @pv_User,                             @pv_Equipo,                           'N',
       SIG_CONTRATISTAS.FLAG_RNP,           SIG_CONTRATISTAS.FLAG_DISCAPACIDAD, 
       CASE WHEN (SELECT COUNT(*) FROM SIG_CONVOCATORIA_REQUISITOS
                   WHERE SIG_CONVOCATORIA_REQUISITOS.ANO_EJE         = SIG_PROPUESTA_ARCHIVO.ANO_EJE  AND
                         SIG_CONVOCATORIA_REQUISITOS.SEC_EJEC        = SIG_PROPUESTA_ARCHIVO.SEC_EJEC AND
                         SIG_CONVOCATORIA_REQUISITOS.TIPO_GENERACION = @pv_Tipo_Generacion             AND
                         SIG_CONVOCATORIA_REQUISITOS.PROCESO         = @pn_Proceso                     AND
                         SIG_CONVOCATORIA_REQUISITOS.SEC_PROCESO     = SIG_PROPUESTA_ARCHIVO.SEC_POS  AND
                         SIG_CONVOCATORIA_REQUISITOS.CONVOCATORIA    = @pn_Convocatoria) > 0 THEN 'S' ELSE 'N' END
  FROM SIG_PROPUESTA_ARCHIVO
  JOIN SIG_CONTRATISTAS ON
       SIG_CONTRATISTAS.NRO_RUC = SIG_PROPUESTA_ARCHIVO.NRO_RUC
 WHERE SIG_PROPUESTA_ARCHIVO.ANO_EJE  = @pn_Ano_Eje  AND
       SIG_PROPUESTA_ARCHIVO.SEC_EJEC = @pn_Sec_Ejec AND
       SIG_PROPUESTA_ARCHIVO.SEC_POS  = @pn_PS_Importa



INSERT INTO SIG_PROPUESTA_REQUISITOS (
       ANO_EJE,                            SEC_EJEC,                                TIPO_GENERACION,
       PROCESO,                            SEC_PROCESO,                             CONVOCATORIA,
       PROVEEDOR,                          SEC_FACTOR,                              ESTADO,
       FECHA,                              FECHA_REG,                               CUSER_ID,
       EQUIPO_REG)
SELECT SIG_PROPUESTA_PROVEEDOR.ANO_EJE,    SIG_PROPUESTA_PROVEEDOR.SEC_EJEC,        SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION,
       SIG_PROPUESTA_PROVEEDOR.PROCESO,    SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO,     @pn_Convocatoria,
       SIG_PROPUESTA_PROVEEDOR.PROVEEDOR,  SIG_CONVOCATORIA_REQUISITOS.SEC_FACTOR,  'N',
       GETDATE(),                            GETDATE(),                                 @pv_User,
       @pv_Equipo
  FROM SIG_PROPUESTA_PROVEEDOR
  JOIN SIG_CONVOCATORIA_REQUISITOS ON
       SIG_CONVOCATORIA_REQUISITOS.ANO_EJE         = SIG_PROPUESTA_PROVEEDOR.ANO_EJE         AND
       SIG_CONVOCATORIA_REQUISITOS.SEC_EJEC        = SIG_PROPUESTA_PROVEEDOR.SEC_EJEC        AND
       SIG_CONVOCATORIA_REQUISITOS.TIPO_GENERACION = SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION AND
       SIG_CONVOCATORIA_REQUISITOS.PROCESO         = SIG_PROPUESTA_PROVEEDOR.PROCESO         AND
       SIG_CONVOCATORIA_REQUISITOS.SEC_PROCESO     = SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO     AND
       SIG_CONVOCATORIA_REQUISITOS.CONVOCATORIA    = SIG_PROPUESTA_PROVEEDOR.CONVOCATORIA
 WHERE SIG_PROPUESTA_PROVEEDOR.ANO_EJE         = @pn_Ano_Eje  AND
       SIG_PROPUESTA_PROVEEDOR.SEC_EJEC        = @pn_Sec_Ejec AND
       SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION = @pn_Proceso  AND
       SIG_PROPUESTA_PROVEEDOR.PROCESO         = @pn_Proceso  AND
       SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO     = @pn_Sec_Pos  AND
       SIG_PROPUESTA_PROVEEDOR.CONVOCATORIA    = @pn_Convocatoria



INSERT INTO SIG_PROPUESTA_LOTE (
       ANO_EJE,                            SEC_EJEC,                                TIPO_GENERACION,
       PROCESO,                            SEC_PROCESO,                             CONVOCATORIA,
       PROVEEDOR,                          NRO_LOTE,                                SEC_CONVOCATORIA,
       NRO_PROPUESTA,                      PUNTAJE_FINAL,                           ESTADO_FINAL,
       FECHA_FINAL,                        ORDEN_MERITO,                            BONIFICACION,
       PUNTAJE_TECNICO,                    ESTADO_TECNICO,                          FECHA_TECNICO,
       PUNTAJE_ECONOMICO,                  ESTADO_ECONOMICO,                        FECHA_ECONOMICO,
       OFERTA_ECONOMICA,                   PRODUCTO_NACIONAL,                       FECHA_REG,
       CUSER_ID,                           ADJUDICADO,                              TIPO_ADJUDICACION,
       FECHA_ADJUDICACION,                 REQUISITO,                               FLAG_PROCESO,
       EQUIPO_REG)
SELECT DISTINCT
       SIG_PROPUESTA_PROVEEDOR.ANO_EJE,    SIG_PROPUESTA_PROVEEDOR.SEC_EJEC,        SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION,
       SIG_PROPUESTA_PROVEEDOR.PROCESO,    SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO,     @pn_Convocatoria,
       SIG_PROPUESTA_PROVEEDOR.PROVEEDOR,  SIG_CONVOCATORIA_LOTE.NRO_LOTE,          @pn_Sec_Convocatoria,
       1,                                  0,                                       '0',
       NULL,                               0,                                       0,
       0,                                  '0',                                     NULL,
       0,                                  '0',                                     NULL,
       0,                                  'N',                                     GETDATE(),
       @pv_User,                            'N',                                     NULL,
       NULL,                               'N',                                     'N',
       @pv_Equipo
  FROM SIG_PROPUESTA_PROVEEDOR
  JOIN SIG_CONVOCATORIA_LOTE ON
       SIG_CONVOCATORIA_LOTE.ANO_EJE         = SIG_PROPUESTA_PROVEEDOR.ANO_EJE         AND
       SIG_CONVOCATORIA_LOTE.SEC_EJEC        = SIG_PROPUESTA_PROVEEDOR.SEC_EJEC        AND
       SIG_CONVOCATORIA_LOTE.TIPO_GENERACION = SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION AND
       SIG_CONVOCATORIA_LOTE.PROCESO         = SIG_PROPUESTA_PROVEEDOR.PROCESO         AND
       SIG_CONVOCATORIA_LOTE.SEC_PROCESO     = SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO     AND
       SIG_CONVOCATORIA_LOTE.CONVOCATORIA    = SIG_PROPUESTA_PROVEEDOR.CONVOCATORIA
  JOIN (
        SELECT DISTINCT
               SIG_PROPUESTA_ARCHIVO.ANO_EJE,       SIG_PROPUESTA_ARCHIVO.SEC_EJEC,      @pv_Tipo_Generacion AS TIPO_GENERACION,
               @pn_Proceso AS PROCESO,              @pn_Sec_Pos AS SEC_PROCESO,          @pn_Convocatoria AS CONVOCATORIA,
               SIG_CONTRATISTAS.PROVEEDOR,          SIG_PROPUESTA_ARCHIVO.NRO_LOTE
          FROM SIG_PROPUESTA_ARCHIVO
          JOIN SIG_CONTRATISTAS ON
               SIG_CONTRATISTAS.NRO_RUC = SIG_PROPUESTA_ARCHIVO.NRO_RUC
         WHERE SIG_PROPUESTA_ARCHIVO.ANO_EJE  = @pn_Ano_Eje  AND
               SIG_PROPUESTA_ARCHIVO.SEC_EJEC = @pn_Sec_Ejec AND
               SIG_PROPUESTA_ARCHIVO.SEC_POS  = @pn_PS_Importa)  	T ON
        T.ANO_EJE         = SIG_CONVOCATORIA_LOTE.ANO_EJE         AND
        T.SEC_EJEC        = SIG_CONVOCATORIA_LOTE.SEC_EJEC        AND
        T.TIPO_GENERACION = SIG_CONVOCATORIA_LOTE.TIPO_GENERACION AND
        T.PROCESO         = SIG_CONVOCATORIA_LOTE.PROCESO         AND
        T.SEC_PROCESO     = SIG_CONVOCATORIA_LOTE.SEC_PROCESO     AND
        T.CONVOCATORIA    = SIG_CONVOCATORIA_LOTE.CONVOCATORIA    AND
        T.PROVEEDOR       = SIG_PROPUESTA_PROVEEDOR.PROVEEDOR     AND
        T.NRO_LOTE        = SIG_CONVOCATORIA_LOTE.NRO_LOTE
  WHERE SIG_PROPUESTA_PROVEEDOR.ANO_EJE        = @pn_Ano_Eje         AND
       SIG_PROPUESTA_PROVEEDOR.SEC_EJEC        = @pn_Sec_Ejec        AND
       SIG_PROPUESTA_PROVEEDOR.TIPO_GENERACION = @pv_Tipo_Generacion AND
       SIG_PROPUESTA_PROVEEDOR.PROCESO         = @pn_Proceso         AND
       SIG_PROPUESTA_PROVEEDOR.SEC_PROCESO     = @pn_Sec_Pos         AND
       SIG_CONVOCATORIA_LOTE.CONVOCATORIA      = @pn_Convocatoria


INSERT INTO SIG_PROPUESTA_ITEM (
       ANO_EJE,                             SEC_EJEC,                           TIPO_GENERACION,
       PROCESO,                             SEC_PROCESO,                        CONVOCATORIA,
       SEC_CONVOCATORIA,                    NRO_LOTE,                           PROVEEDOR,
       NRO_PROPUESTA,                       NRO_ITEM,                           SEC_LOTE,
       CANTIDAD,                            PRECIO_MONEDA,                      VALOR_MONEDA,
       VALOR_SOLES,                         ESPEC_TECNICAS,                     PRODUCTO_NACIONAL,
       TIPO_BIEN,                           GRUPO_BIEN,                         CLASE_BIEN,
       FAMILIA_BIEN,                        ITEM_BIEN,                          CANTIDAD_ADJUDICA,
       UNIDAD_MEDIDA,                       FECHA_REG,                          CUSER_ID,
       EQUIPO_REG,                          ESTADO,                             PRESENTACION,
       TIPO_MARCA,                          MARCA,                              ITEM_PROCESO)
SELECT DISTINCT 
       SIG_PROPUESTA_LOTE.ANO_EJE,          SIG_PROPUESTA_LOTE.SEC_EJEC,        SIG_PROPUESTA_LOTE.TIPO_GENERACION,
       SIG_PROPUESTA_LOTE.PROCESO,          SIG_PROPUESTA_LOTE.SEC_PROCESO,     SIG_PROPUESTA_LOTE.CONVOCATORIA,
       SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA, SIG_PROPUESTA_LOTE.NRO_LOTE,        SIG_PROPUESTA_LOTE.PROVEEDOR,
       SIG_PROPUESTA_LOTE.NRO_PROPUESTA,    SIG_CONVOCATORIA_ITEM.NRO_ITEM,     SIG_CONVOCATORIA_ITEM.SEC_LOTE,
       T.VALOR_SOLES,     		    1,                                  T.VALOR_SOLES,
       T.VALOR_SOLES,                       NULL,                               'N',
       SIG_CONVOCATORIA_ITEM.TIPO_BIEN,     SIG_CONVOCATORIA_ITEM.GRUPO_BIEN,   SIG_CONVOCATORIA_ITEM.CLASE_BIEN,
       SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN,  SIG_CONVOCATORIA_ITEM.ITEM_BIEN,    T.VALOR_SOLES,
       SIG_CONVOCATORIA_ITEM.UNIDAD_MEDIDA, GETDATE(),                            @pv_User,
       @pv_Equipo,                           '0',                                SIG_CONVOCATORIA_ITEM.PRESENTACION,
       '1',                                 328,
       RIGHT( '0000' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.ANO_EJE), 4) + SIG_PROPUESTA_LOTE.TIPO_GENERACION + RIGHT( '00000' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.PROCESO), 5) +
	   RIGHT( '0000' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.SEC_PROCESO), 4) + RIGHT( '00' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.CONVOCATORIA), 2) +
	   RIGHT( '00' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA), 2) + RIGHT( '0000' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.NRO_LOTE), 4) +
	   RIGHT( '00000' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.PROVEEDOR), 4) + RIGHT( '0' + CONVERT( VARCHAR, SIG_PROPUESTA_LOTE.NRO_PROPUESTA), 1) +
	   RIGHT( '0000' + CONVERT( VARCHAR, SIG_CONVOCATORIA_ITEM.NRO_ITEM), 4) 
  FROM SIG_PROPUESTA_LOTE
  JOIN SIG_CONVOCATORIA_ITEM ON
       SIG_CONVOCATORIA_ITEM.ANO_EJE         = SIG_PROPUESTA_LOTE.ANO_EJE         AND
       SIG_CONVOCATORIA_ITEM.SEC_EJEC        = SIG_PROPUESTA_LOTE.SEC_EJEC        AND
       SIG_CONVOCATORIA_ITEM.TIPO_GENERACION = SIG_PROPUESTA_LOTE.TIPO_GENERACION AND
       SIG_CONVOCATORIA_ITEM.PROCESO         = SIG_PROPUESTA_LOTE.PROCESO         AND
       SIG_CONVOCATORIA_ITEM.SEC_PROCESO     = SIG_PROPUESTA_LOTE.SEC_PROCESO     AND
       SIG_CONVOCATORIA_ITEM.CONVOCATORIA    = SIG_PROPUESTA_LOTE.CONVOCATORIA    AND 
       SIG_CONVOCATORIA_ITEM.NRO_LOTE        = SIG_PROPUESTA_LOTE.NRO_LOTE 
  JOIN (
        SELECT DISTINCT
               SIG_PROPUESTA_ARCHIVO.ANO_EJE,       SIG_PROPUESTA_ARCHIVO.SEC_EJEC,       @pv_Tipo_Generacion AS TIPO_GENERACION,
               @pn_Proceso AS PROCESO,              @pn_Sec_Pos AS SEC_PROCESO,           @pn_Convocatoria AS CONVOCATORIA,
               SIG_CONTRATISTAS.PROVEEDOR,          SIG_PROPUESTA_ARCHIVO.NRO_LOTE,
               SIG_PROPUESTA_ARCHIVO.VALOR_SOLES
          FROM SIG_PROPUESTA_ARCHIVO
          JOIN SIG_CONTRATISTAS ON
               SIG_CONTRATISTAS.NRO_RUC = SIG_PROPUESTA_ARCHIVO.NRO_RUC
         WHERE SIG_PROPUESTA_ARCHIVO.ANO_EJE  = @pn_Ano_Eje  AND
               SIG_PROPUESTA_ARCHIVO.SEC_EJEC = @pn_Sec_Ejec AND
               SIG_PROPUESTA_ARCHIVO.SEC_POS  = @pn_PS_Importa)   T ON
       T.ANO_EJE         = SIG_PROPUESTA_LOTE.ANO_EJE         AND
       T.SEC_EJEC        = SIG_PROPUESTA_LOTE.SEC_EJEC        AND
       T.TIPO_GENERACION = SIG_PROPUESTA_LOTE.TIPO_GENERACION AND
       T.PROCESO         = SIG_PROPUESTA_LOTE.PROCESO         AND
       T.SEC_PROCESO     = SIG_PROPUESTA_LOTE.SEC_PROCESO     AND
       T.CONVOCATORIA    = SIG_PROPUESTA_LOTE.CONVOCATORIA    AND
       T.PROVEEDOR       = SIG_PROPUESTA_LOTE.PROVEEDOR       AND
       T.NRO_LOTE        = SIG_PROPUESTA_LOTE.NRO_LOTE       
 WHERE SIG_PROPUESTA_LOTE.ANO_EJE          = @pn_Ano_Eje           AND
       SIG_PROPUESTA_LOTE.SEC_EJEC         = @pn_Sec_Ejec          AND
       SIG_PROPUESTA_LOTE.TIPO_GENERACION  = @pv_Tipo_Generacion   AND
       SIG_PROPUESTA_LOTE.PROCESO          = @pn_Proceso           AND
       SIG_PROPUESTA_LOTE.SEC_PROCESO      = @pn_Sec_Pos           AND
       SIG_PROPUESTA_LOTE.CONVOCATORIA     = @pn_Convocatoria      AND
       SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA = @pn_Sec_Convocatoria  AND
	   NOT EXISTS ( SELECT *
					  FROM SIG_PROPUESTA_ITEM PI 
					 WHERE PI.ANO_EJE          = SIG_PROPUESTA_LOTE.ANO_EJE          AND  
						   PI.SEC_EJEC         = SIG_PROPUESTA_LOTE.SEC_EJEC         AND  
				 		   PI.TIPO_GENERACION  = SIG_PROPUESTA_LOTE.TIPO_GENERACION  AND  
						   PI.PROCESO          = SIG_PROPUESTA_LOTE.PROCESO          AND  
						   PI.SEC_PROCESO      = SIG_PROPUESTA_LOTE.SEC_PROCESO      AND  
						   PI.CONVOCATORIA     = SIG_PROPUESTA_LOTE.CONVOCATORIA     AND  
						   PI.SEC_CONVOCATORIA = SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA AND  
						   PI.NRO_LOTE         = SIG_PROPUESTA_LOTE.NRO_LOTE         AND  
						   PI.PROVEEDOR        = SIG_PROPUESTA_LOTE.PROVEEDOR        AND  
						   PI.NRO_PROPUESTA    = SIG_PROPUESTA_LOTE.NRO_PROPUESTA    AND  
						   PI.NRO_ITEM         = SIG_CONVOCATORIA_ITEM.NRO_ITEM ) 


INSERT INTO SIG_PROPUESTA_LOTE_FACTOR (
       ANO_EJE,                            SEC_EJEC,                                TIPO_GENERACION,
       PROCESO,                            SEC_PROCESO,                             CONVOCATORIA,
       PROVEEDOR,                          NRO_LOTE,                                SEC_CONVOCATORIA,
       NRO_PROPUESTA,                      SEC_PROP_FACTOR,                         TIPO_BIEN,
       TIPO_FACTOR,                        SEC_FACTOR,                              NIVEL_01,
       NIVEL_02,                           NIVEL_03,                                NIVEL_04,
       CALIFICACION,                       PUNTAJE,                                 ESTADO,
       TIPO_EVALUACION,                    NOMBRE_FACTOR,                           UNIDAD_MEDIDA,
       FECHA_REG,                          CUSER_ID,                                SEC_FACTOR_PADRE,
       EQUIPO_REG )
SELECT DISTINCT
       SIG_PROPUESTA_ITEM.ANO_EJE,         SIG_PROPUESTA_ITEM.SEC_EJEC,             SIG_PROPUESTA_ITEM.TIPO_GENERACION,
       SIG_PROPUESTA_ITEM.PROCESO,         SIG_PROPUESTA_ITEM.SEC_PROCESO,          SIG_PROPUESTA_ITEM.CONVOCATORIA,
       SIG_PROPUESTA_ITEM.PROVEEDOR,       SIG_PROPUESTA_ITEM.NRO_LOTE,             SIG_PROPUESTA_ITEM.SEC_CONVOCATORIA,
       SIG_PROPUESTA_ITEM.NRO_PROPUESTA,   SIG_CONVOCATORIA_LOTE_FACTOR.SEC_LOTE_FACTOR,   SIG_CONVOCATORIA_LOTE_FACTOR.TIPO_BIEN,
       SIG_CONVOCATORIA_LOTE_FACTOR.TIPO_FACTOR,  SIG_CONVOCATORIA_LOTE_FACTOR.SEC_FACTOR, SIG_CONVOCATORIA_LOTE_FACTOR.NIVEL_01,
       SIG_CONVOCATORIA_LOTE_FACTOR.NIVEL_02,     SIG_CONVOCATORIA_LOTE_FACTOR.NIVEL_03,   SIG_CONVOCATORIA_LOTE_FACTOR.NIVEL_04,
       0,                                  0,                                       '0',
       SIG_CONVOCATORIA_LOTE_FACTOR.TIPO_EVALUACION, SIG_CONVOCATORIA_LOTE_FACTOR.NOMBRE_FACTOR, SIG_CONVOCATORIA_LOTE_FACTOR.UNIDAD_MEDIDA, --NOMBRE Y UM?
       GETDATE(),                            @pv_User,                                 SIG_CONVOCATORIA_LOTE_FACTOR.SEC_FACTOR_PADRE,
       @pv_Equipo
  FROM SIG_PROPUESTA_ITEM
  JOIN SIG_CONVOCATORIA_LOTE_FACTOR ON
       SIG_CONVOCATORIA_LOTE_FACTOR.ANO_EJE         = SIG_PROPUESTA_ITEM.ANO_EJE         AND
       SIG_CONVOCATORIA_LOTE_FACTOR.SEC_EJEC        = SIG_PROPUESTA_ITEM.SEC_EJEC        AND
       SIG_CONVOCATORIA_LOTE_FACTOR.TIPO_GENERACION = SIG_PROPUESTA_ITEM.TIPO_GENERACION AND
       SIG_CONVOCATORIA_LOTE_FACTOR.PROCESO         = SIG_PROPUESTA_ITEM.PROCESO         AND
       SIG_CONVOCATORIA_LOTE_FACTOR.SEC_PROCESO     = SIG_PROPUESTA_ITEM.SEC_PROCESO     AND
       SIG_CONVOCATORIA_LOTE_FACTOR.CONVOCATORIA    = SIG_PROPUESTA_ITEM.CONVOCATORIA    AND
       SIG_CONVOCATORIA_LOTE_FACTOR.NRO_LOTE        = SIG_PROPUESTA_ITEM.NRO_LOTE        AND
       SIG_CONVOCATORIA_LOTE_FACTOR.TIPO_BIEN       = SIG_PROPUESTA_ITEM.TIPO_BIEN 
 WHERE SIG_PROPUESTA_ITEM.ANO_EJE          = @pn_Ano_Eje         AND
       SIG_PROPUESTA_ITEM.SEC_EJEC         = @pn_Sec_Ejec        AND
       SIG_PROPUESTA_ITEM.TIPO_GENERACION  = @pv_Tipo_Generacion AND
       SIG_PROPUESTA_ITEM.PROCESO          = @pn_Proceso         AND
       SIG_PROPUESTA_ITEM.SEC_PROCESO      = @pn_Sec_Pos         AND
       SIG_PROPUESTA_ITEM.CONVOCATORIA     = @pn_Convocatoria    AND
       SIG_PROPUESTA_ITEM.SEC_CONVOCATORIA = @pn_Sec_Convocatoria
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_UNIDAD_MEDIDA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_UNIDAD_MEDIDA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_UNIDAD_MEDIDA]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_UNIDAD_MEDIDA]
AS
BEGIN  
	TRUNCATE TABLE TA_UNIDAD_MEDIDA
	INSERT INTO TA_UNIDAD_MEDIDA ( UNIDAD_MEDIDA, NOMBRE)
	SELECT DISTINCT UME.UNIDAD_MEDIDA, UME.NOMBRE  
		FROM SI_PROGRAMACION_DETA_TRX DET,
		UNIDAD_MEDIDA UME
		WHERE DET.UNIDAD_MEDIDA_ITEM_BS = UME.UNIDAD_MEDIDA
	UNION
	SELECT DISTINCT UME.UNIDAD_MEDIDA, UME.NOMBRE  
		FROM SI_PROGRAMACION_TRX CAB,   
		UNIDAD_MEDIDA  UME
		WHERE CAB.UNIDAD_MEDIDA_META = UME.UNIDAD_MEDIDA
END
GO


