-- procedure structure for usp_GenCopiaCN2013
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GenCopiaCN2013]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GenCopiaCN2013]
GO

CREATE PROCEDURE [dbo].[usp_GenCopiaCN2013]
@anio int,
@secejec int
as
begin
--@anio 2013

-- CUADRO DE NECESIDADES
-- CABECERA

INSERT INTO SIG_CUADRO_NECESIDAD
(ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA, FASE_CUADRO, TIPO_TAREA, NIVEL_TAREA, CODIGO_TAREA, sec_func_prop, sec_func, ORIGEN, FUENTE_FINANC, 
		CONCEPTO_GASTO, CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR, TIPO_RECURSO, TOTAL_ASIGNADO, TOTAL_PROGRA, TOTAL_APROB,TOTAL_MODIF, MONTO_ASIGNADO, 
		MONTO_PROGRA, MONTO_APROB, MONTO_MODIF, VALOR_IMP_ASIGNADO, VALOR_IMP_PROGRA, VALOR_IMP_APROB, VALOR_IMP_MODIF,TIPO_IMPUESTO, FUENTE_IMPTO, 
		TASA_IMPTO, FLAG_GASTO, TIPO_PPTO, TIPO_USO, EQUIPO_REG, FECHA_REG, CUSER_ID, tipo_operacion, operacion, mayor,sub_cta, sub_cta_det, NRO_PLANTILLA, 
		tipo_bien, TIPO_ORIGEN_EXTERNO, ID_CLASIFICADOR, sec_establec, sub_finalidad, flag_origen_cab,   ID_SUB_FINALIDAD)

select  DISTINCT tmc.ANO_EJE, tmc.SEC_EJEC, tmc.CENTRO_COSTO, tmc.SECUENCIA,tmc.FASE_CUADRO, tmc.TIPO_TAREA, tmc.NIVEL_TAREA, 
		tmc.CODIGO_TAREA, tmc.sec_func_prop, tmc.sec_func, tmc.ORIGEN, tmc.FUENTE_FINANC, 
		CONCEPTO_GASTO, CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR, TIPO_RECURSO, TOTAL_ASIGNADO, TOTAL_PROGRA, TOTAL_APROB,TOTAL_MODIF, MONTO_ASIGNADO, 
		MONTO_PROGRA, MONTO_APROB, MONTO_MODIF, VALOR_IMP_ASIGNADO, VALOR_IMP_PROGRA, VALOR_IMP_APROB, VALOR_IMP_MODIF,TIPO_IMPUESTO, FUENTE_IMPTO, 
		TASA_IMPTO, FLAG_GASTO, TIPO_PPTO, TIPO_USO, EQUIPO_REG, FECHA_REG, CUSER_ID, tipo_operacion, operacion, mayor,sub_cta, sub_cta_det, NRO_PLANTILLA, 
		tipo_bien, TIPO_ORIGEN_EXTERNO, ID_CLASIFICADOR, sec_establec, sub_finalidad, flag_origen_cab,   ID_SUB_FINALIDAD
from tmp_cab tmc,
SIG_META_PROPUESTA smp
WHERE tmc.ANO_EJE=smp.ANO_EJE AND
tmc.SEC_EJEC= smp.SEC_EJEC AND 
tmc.SEC_FUNC_PROP= smp.SEC_FUNC_PROP


-- DETALLE 01

						INSERT INTO SIG_CUADRO_NECESIDAD_DET
							   (ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA, FASE_CUADRO, ITEM_SEC, TIPO_BIEN, GRUPO_BIEN, CLASE_BIEN, FAMILIA_BIEN,
								ITEM_BIEN, DESCRIP_SERVICIO, UNIDAD_MEDIDA, PRECIO_UNIT, CANT_01, CANT_02, CANT_03, CANT_04, CANT_05, CANT_06,
								CANT_07, CANT_08, CANT_09, CANT_10, CANT_11, CANT_12, CANT_TOTAL, MNTO_01, MNTO_02, MNTO_03, MNTO_04, MNTO_05,
								MNTO_06, MNTO_07, MNTO_08, MNTO_09, MNTO_10, MNTO_11, MNTO_12, MNTO_TOTAL, STOCK_ASIG, VALOR_STOCK, TIPO_IMPTO,
								TASA_IMPTO, FTE_IMPTO, VALOR_IMPTO, ESTADO, CANT_HIST, MNTO_HIST, NRO_CONSOLID, ESTADO_PAAC, NRO_PEDIDO, PORC_GASTO,
								FLAG_GASTO, FLAG_MODIF, EQUIPO_REG, CUSER_ID, FECHA_REG, flag_migra, tipo_origen_externo_det, cantidad_unitaria,
								porcentaje, ID_KIT, tipo_calculo, flag_origen_det, ESTADO_ITEM_KIT,  STOCK)
						 SELECT DISTINCT ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA, FASE_CUADRO, ITEM_SEC, TIPO_BIEN, GRUPO_BIEN, CLASE_BIEN, FAMILIA_BIEN,
								ITEM_BIEN, DESCRIP_SERVICIO, UNIDAD_MEDIDA, PRECIO_UNIT, CANT_01, CANT_02, CANT_03, CANT_04, CANT_05, CANT_06,
								CANT_07, CANT_08, CANT_09, CANT_10, CANT_11, CANT_12, CANT_TOTAL, MNTO_01, MNTO_02, MNTO_03, MNTO_04, MNTO_05,
								MNTO_06, MNTO_07, MNTO_08, MNTO_09, MNTO_10, MNTO_11, MNTO_12, MNTO_TOTAL, STOCK_ASIG, VALOR_STOCK, TIPO_IMPTO,
								TASA_IMPTO, FTE_IMPTO, VALOR_IMPTO, ESTADO, CANT_HIST, MNTO_HIST, NRO_CONSOLID, ESTADO_PAAC, NRO_PEDIDO, PORC_GASTO,
								FLAG_GASTO, FLAG_MODIF, EQUIPO_REG, CUSER_ID, FECHA_REG, flag_migra, tipo_origen_externo_det, cantidad_unitaria,
								porcentaje, ID_KIT, tipo_calculo, flag_origen_det, ESTADO_ITEM_KIT,  STOCK
						  FROM  tmp_det
--detalle02
					     INSERT INTO SIG_CUA_NEC_DET_ID
						(ano_eje,sec_ejec,centro_costo,secuencia,fase_cuadro,item_id,item_sec,id_kit,tipo_calculo,
						cantidad_unitaria,tipo_bien,grupo_bien, clase_bien, familia_bien, item_bien, cant_total, ESTADO, 
						  STOCK)
						
						 SELECT DISTINCT 2013, i.sec_ejec, i.centro_costo, i.secuencia, i.fase_cuadro, i.item_id, i.item_sec, i.id_kit, i.tipo_calculo,
											i.cantidad_unitaria, i.tipo_bien, i.grupo_bien, i.clase_bien, i.familia_bien, i.item_bien, i.cant_total, i.ESTADO,
											  i.STOCK
						  FROM SIG_CUADRO_NECESIDAD C,
							   SIG_CUA_NEC_DET_ID i,
							   CATALOGO_BIEN_SERV cbs,
							   SI_PPR_KIT_ITEMS   spk
						 where( c.ANO_EJE  = 2013 and C.EQUIPO_REG='MIGRA013' )and
							  (	i.ANO_EJE  = 2012 and
						        C.SEC_EJEC = i.SEC_EJEC  AND
						        C.CENTRO_COSTO = i.CENTRO_COSTO AND
						        C.SECUENCIA    = i.SECUENCIA AND
						        C.FASE_CUADRO  = i.FASE_CUADRO )and
							  ( cbs.TIPO_BIEN =i.TIPO_BIEN  and
							    cbs.GRUPO_BIEN=i.GRUPO_BIEN and  
							    cbs.CLASE_BIEN=i.CLASE_BIEN and
							    cbs.FAMILIA_BIEN=i.FAMILIA_BIEN and
							    cbs.ITEM_BIEN=i.ITEM_BIEN and
							    cbs.ESTADO='A' ) and
							    ( cbs.CODIGO_ITEM=spk.ITEM_BIEN and spk.TIPO_CALCULO IN (4,5,6,8) and spk.ANO_EJE= 2012 ) 
end
GO


-- ----------------------------
-- function structure for SF_NIVEL_DESC
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_NIVEL_DESC]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_NIVEL_DESC]
GO

CREATE FUNCTION [dbo].[SF_NIVEL_DESC]
(
@as_nivel_funcion   VARCHAR(10),
@as_cad_operativa   VARCHAR(10),
@al_nivel           INTEGER
)
RETURNS VARCHAR(200)
AS
BEGIN

DECLARE @ls_cadena      VARCHAR(200) 
DECLARE @ls_nivel_desc  VARCHAR(100) 

BEGIN

SELECT  @ls_nivel_desc  = DESC_NIVEL 
FROM    SIG_PPR_NIVEL_DESC
WHERE   FUNCION = @as_nivel_funcion
AND     NIVEL   = @al_nivel 

SELECT  @ls_cadena  = 'Sin ' ++ @ls_nivel_desc 

IF @al_nivel = 1
BEGIN
    SELECT  @ls_cadena  = DESC_NIVEL
    FROM    SIG_PPR_NIVEL
    WHERE   FUNCION     = @as_nivel_funcion
    AND     NIVEL       = @al_nivel
    AND     JERARQUIA   = SUBSTRING(@as_cad_operativa, 1, 2) 
END
IF @al_nivel = 2
BEGIN
    SELECT  @ls_cadena  = DESC_NIVEL
    FROM    SIG_PPR_NIVEL
    WHERE   FUNCION     = @as_nivel_funcion
    AND     NIVEL       = @al_nivel
    AND     JERARQUIA   = SUBSTRING(@as_cad_operativa, 1, 4) 
END
IF @al_nivel = 3
BEGIN
    SELECT  @ls_cadena  = DESC_NIVEL
    FROM    SIG_PPR_NIVEL
    WHERE   FUNCION     = @as_nivel_funcion
    AND     NIVEL       = @al_nivel
    AND     JERARQUIA   = SUBSTRING(@as_cad_operativa, 1, 6) 
END

END

RETURN  @ls_cadena 

END
GO


