CREATE PROCEDURE [dbo].[USP_PRDETALLEINSERT] (
	@ano_eje numeric(4,0),
	@sec_ejec numeric(6,0),	
	@centro_costo varchar(15),
	@cuser_id varchar(8),
	@fuente_financ varchar(2),
	@sec_func numeric(5,0),
	@tipo_tarea char(1),
	@nivel_tarea char(1),
	@codigo_tarea numeric(10,0),
	@tipo_bien char(1),
	@grupo_bien char(2),
	@clase_bien char(2),
	@familia_bien char(4),
	@item_bien char(4),
	@clasificador varchar(6),
	@cant_01 numeric(14,2),
	@cant_02 numeric(14,2),
	@cant_03 numeric(14,2),
	@cant_04 numeric(14,2),
	@cant_05 numeric(14,2),
	@cant_06 numeric(14,2),
	@cant_07 numeric(14,2),
	@cant_08 numeric(14,2),
	@cant_09 numeric(14,2),
	@cant_10 numeric(14,2),
	@cant_11 numeric(14,2),
	@cant_12 numeric(14,2),
	@tipo_impto char(1),
	@fte_impto varchar(2),
	@tasa_impto numeric(14,2),
	@nro_consolid numeric(5,0),
	@nro_pedido char(5),
	@respuesta varchar(50) OUTPUT )
AS
DECLARE @sec_consolid numeric(5,0)
DECLARE @sec_resumen numeric(5,0)
DECLARE @sec_meta numeric(5,0)
DECLARE @sec_ctro_costo numeric(5,0)
DECLARE @moneda varchar(6)
DECLARE @tipo_cambio  numeric(10,4)
DECLARE @unidad_adquis numeric(5,0)
DECLARE @unidad_medida numeric(5,0) 
DECLARE @factor_unidad numeric(5,0)
DECLARE @precio_unit numeric(16,6)
DECLARE @total_paac_item numeric(10,0)
DECLARE @total_paac_meta numeric(10,0)
DECLARE @total_paac_centro_costo numeric(10,0)
DECLARE @ano_proceso numeric(10,0)
DECLARE @valor_impto numeric(14,2)
DECLARE @cant_total numeric(14,2)
DECLARE @valor_total numeric(14,2)
DECLARE @mnto_01 numeric(14,2)
DECLARE @mnto_02 numeric(14,2)
DECLARE @mnto_03 numeric(14,2)
DECLARE @mnto_04 numeric(14,2)
DECLARE @mnto_05 numeric(14,2)
DECLARE @mnto_06 numeric(14,2)
DECLARE @mnto_07 numeric(14,2)
DECLARE @mnto_08 numeric(14,2)
DECLARE @mnto_09 numeric(14,2)
DECLARE @mnto_10 numeric(14,2)
DECLARE @mnto_11 numeric(14,2)
DECLARE @mnto_12 numeric(14,2)
DECLARE @mnto_total numeric(14,2)
DECLARE @mnto_controltecho numeric(14,2)
DECLARE @DIFERENCIA numeric(14,2)
DECLARE @resultado varchar(50)
DECLARE @precio_moneda numeric(14,2)
DECLARE @lTotalTP NUMERIC(5,0)
DECLARE @presentacion varchar(40)

DECLARE @tot_01 numeric(14,2)
DECLARE @tot_02 numeric(14,2)
DECLARE @tot_03 numeric(14,2)
DECLARE @tot_04 numeric(14,2)
DECLARE @tot_05 numeric(14,2)
DECLARE @tot_06 numeric(14,2)
DECLARE @tot_07 numeric(14,2)
DECLARE @tot_08 numeric(14,2)
DECLARE @tot_09 numeric(14,2)
DECLARE @tot_10 numeric(14,2)
DECLARE @tot_11 numeric(14,2)
DECLARE @tot_12 numeric(14,2)
DECLARE @cantidad_tot numeric(14,2)
DECLARE @valor_tot numeric(14,2)
DECLARE @valor_moneda  numeric(14,2)
DECLARE @valor_impto_moneda  numeric(14,2)

	DECLARE @validar BIT
	DECLARE @fuente_financ_result VARCHAR(2)
	DECLARE @sec_func_result NUMERIC(5,0)
	DECLARE @clasificador_result VARCHAR(6)

SET @resultado = ''
SET @cant_total = @cant_01 + @cant_02 + @cant_03 + @cant_04 + @cant_05 + @cant_06 + @cant_07 + @cant_08 + @cant_09 + @cant_10 + @cant_11 + @cant_12 
SELECT @ano_proceso = CAST(valor AS INTEGER) FROM SIG_PARAMETRO_EJECUTORA WHERE COD_MAESTRO = 'PROC_SIS_ANO'

	SELECT @moneda = moneda , @tipo_cambio = tipo_cambio 
	FROM sig_paac_consolidado 
	WHERE ano_eje =@ano_eje AND sec_ejec = @sec_ejec AND tipo_consolid ='2' 
	AND nro_consolid = @nro_consolid AND tipo_generacion ='0' 

	SELECT @unidad_adquis=unidad_adquis , @unidad_medida=unidad_medida , 
	@factor_unidad=factor_unidad , @precio_unit=precio_ref, 
	@presentacion = presentacion 
	FROM catalogo_bien_serv 
	WHERE tipo_bien =@tipo_bien  AND grupo_bien =@grupo_bien 
	AND clase_bien =@clase_bien AND familia_bien =@familia_bien 
	AND item_bien =@item_bien



IF @tipo_bien = 'B'
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit
		SET @mnto_02 = @cant_02 * @precio_unit
		SET @mnto_03 = @cant_03 * @precio_unit
		SET @mnto_04 = @cant_04 * @precio_unit
		SET @mnto_05 = @cant_05 * @precio_unit
		SET @mnto_06 = @cant_06 * @precio_unit
		SET @mnto_07 = @cant_07 * @precio_unit
		SET @mnto_08 = @cant_08 * @precio_unit
		SET @mnto_09 = @cant_09 * @precio_unit
		SET @mnto_10 = @cant_10 * @precio_unit
		SET @mnto_11 = @cant_11 * @precio_unit
		SET @mnto_12 = @cant_12 * @precio_unit
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_02 = @cant_02 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_03 = @cant_03 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_04 = @cant_04 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_05 = @cant_05 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_06 = @cant_06 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_07 = @cant_07 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_08 = @cant_08 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_09 = @cant_09 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_10 = @cant_10 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_11 = @cant_11 * @precio_unit * 100 / (100 + @tasa_impto)
		SET @mnto_12 = @cant_12 * @precio_unit * 100 / (100 + @tasa_impto)
	END
ELSE
	IF @tipo_impto = 0
	BEGIN
		SET @mnto_01 = @cant_01 
		SET @mnto_02 = @cant_02 
		SET @mnto_03 = @cant_03 
		SET @mnto_04 = @cant_04 
		SET @mnto_05 = @cant_05 
		SET @mnto_06 = @cant_06 
		SET @mnto_07 = @cant_07 
		SET @mnto_08 = @cant_08 
		SET @mnto_09 = @cant_09 
		SET @mnto_10 = @cant_10 
		SET @mnto_11 = @cant_11 
		SET @mnto_12 = @cant_12 
	END
	ELSE
	BEGIN
		SET @mnto_01 = @cant_01 * (100 - @tasa_impto) / 100
		SET @mnto_02 = @cant_02 * (100 - @tasa_impto) / 100
		SET @mnto_03 = @cant_03 * (100 - @tasa_impto) / 100
		SET @mnto_04 = @cant_04 * (100 - @tasa_impto) / 100
		SET @mnto_05 = @cant_05 * (100 - @tasa_impto) / 100
		SET @mnto_06 = @cant_06 * (100 - @tasa_impto) / 100
		SET @mnto_07 = @cant_07 * (100 - @tasa_impto) / 100
		SET @mnto_08 = @cant_08 * (100 - @tasa_impto) / 100
		SET @mnto_09 = @cant_09 * (100 - @tasa_impto) / 100
		SET @mnto_10 = @cant_10 * (100 - @tasa_impto) / 100
		SET @mnto_11 = @cant_11 * (100 - @tasa_impto) / 100
		SET @mnto_12 = @cant_12 * (100 - @tasa_impto) / 100
	END

SET @mnto_total = @mnto_01 + @mnto_02 + @mnto_03 + @mnto_04 + @mnto_05 + @mnto_06 + @mnto_07 + @mnto_08 + @mnto_09 + @mnto_10 + @mnto_11 + @mnto_12
IF @tipo_impto <> '0'
	IF @tipo_bien = 'B'
		SET @valor_impto = (@cant_total * @precio_unit) - @mnto_total 
	ELSE
		SET @valor_impto = @cant_total  - @mnto_total 
ELSE
	SET @valor_impto = 0

BEGIN TRAN

	SELECT  @sec_consolid = sec_consolid FROM sig_paac_secuencia 
	WHERE ano_eje = @ano_eje AND sec_ejec =@sec_ejec 
	AND tipo_consolid ='2' AND nro_consolid =@nro_consolid 
	AND tipo_generacion ='0' AND ano_proceso=@ano_proceso

	--SELECT @precio_moneda = round((@precio_unit / @tipo_cambio) *  @factor_unidad,6)
	SELECT @precio_moneda = @precio_unit 

	if @presentacion is null
		SELECT @factor_unidad = FACTOR 
		FROM SIG_CATALOGO_PRESENTACION WHERE codigo is null
	else
		SELECT @factor_unidad = FACTOR 
		FROM SIG_CATALOGO_PRESENTACION WHERE codigo = @factor_unidad

	SELECT @total_paac_item = COUNT(*) , @sec_resumen = MIN(sec_resumen) 
	FROM sig_paac_item
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND tipo_consolid = 2 
	AND nro_consolid = @nro_consolid AND tipo_generacion = 0 
	AND tipo_bien = @tipo_bien AND grupo_bien = @grupo_bien 
	AND clase_bien = @clase_bien AND familia_bien = @familia_bien 
	AND item_bien = @item_bien AND sec_consolid = @sec_consolid 

	PRINT 'antes total'
	PRINT @total_paac_item
	PRINT @sec_consolid
	PRINT @sec_resumen
	PRINT 'despues totall'

	IF @total_paac_item <= 0
	BEGIN
		SELECT @sec_resumen = MAX(sec_resumen) + 1
		FROM sig_paac_item
		WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec AND tipo_consolid = 2 
		AND nro_consolid = @nro_consolid AND tipo_generacion = 0 
		AND sec_consolid = @sec_consolid 

		PRINT 'antes consolidados 1 y 2'
		PRINT @sec_consolid
		PRINT @sec_resumen
		PRINT 'despues consolidados 1 y 2'

		INSERT INTO sig_paac_item (
		ano_eje, sec_ejec, tipo_consolid, nro_consolid, 
		tipo_generacion, sec_consolid, sec_resumen,
		tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, 
		mes_01, mes_02, mes_03, mes_04, mes_05, mes_06, mes_07, 
		mes_08, mes_09, mes_10, mes_11, mes_12, cantidad, 
		unidad_medida, moneda, tipo_cambio, 
		precio_unit, valor, precio_moneda , valor_moneda, 
		fecha_reg, cuser_id, 
		cantidad_uso, unidad_uso, precio_uso, factor_unidad, presentacion 
		) VALUES (
		@ano_eje, @sec_ejec, 2, @nro_consolid, 
		0, @sec_consolid, @sec_resumen,
		@tipo_bien, @grupo_bien, @clase_bien, @familia_bien, @item_bien, 
		@cant_01, @cant_02, @cant_03, @cant_04, @cant_05, @cant_06, 
		@cant_07, @cant_08, @cant_09, @cant_10, @cant_11, @cant_12, @cant_total, 
		@unidad_medida, @moneda, @tipo_cambio, 
		@precio_unit, @mnto_total, @precio_moneda, @mnto_total, 
		getdate(), @cuser_id, 
		0, @unidad_medida, @precio_unit, @factor_unidad, @presentacion 
		)
	END

	SELECT @total_paac_meta = COUNT(*) , @sec_meta = MIN(sec_meta)
	FROM sig_paac_metas
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND @sec_resumen = sec_resumen

	print 'Antes total meta'
	print @total_paac_meta
	print @sec_meta
	print 'Despues total meta'

	IF @total_paac_meta <= 0
	BEGIN
		SELECT @sec_meta = isnull(MAX(sec_meta),0) + 1 
		FROM sig_paac_metas 
		WHERE ano_eje =@ano_eje AND sec_ejec =@sec_ejec 
		AND tipo_consolid =2 AND nro_consolid =@nro_consolid 
		AND tipo_generacion ='0' AND tipo_bien =@tipo_bien  
		AND sec_consolid =@sec_consolid AND sec_resumen =@sec_resumen

		print 'Antes total meta2'
		print @sec_meta
		print 'Despues total meta2'

		INSERT INTO sig_paac_metas (
		ano_eje, sec_ejec, tipo_consolid, nro_consolid, 
		tipo_generacion, tipo_bien, sec_consolid, sec_resumen, sec_meta, 
		sec_func, origen, fuente_financ , clasificador , 
		mes_01 , mes_02 , mes_03 , mes_04 , mes_05 , mes_06 , 
		mes_07 , mes_08 , mes_09 , mes_10 , mes_11 , mes_12 , cantidad , 
		valor , tipo_impto , fte_fto_impto , tasa_impto , valor_impto , 
		valor_moneda , valor_impto_moneda , fecha_reg , cuser_id 
		) VALUES (
		@ano_eje, @sec_ejec, 2, @nro_consolid, 
		0, @tipo_bien, @sec_consolid, @sec_resumen, @sec_meta, 
		@sec_func, 1, @fuente_financ, @clasificador , 
		@cant_01, @cant_02, @cant_03, @cant_04, @cant_05, @cant_06, 
		@cant_07, @cant_08, @cant_09, @cant_10, @cant_11, @cant_12, @cant_total, 
		@valor_total, @tipo_impto , @fte_impto , @tasa_impto , @valor_impto , 
		@valor_total , @valor_impto , GETDATE() , @cuser_id 
		)
	END

	print 'ACTUALIZAR VALORES'

	SELECT @total_paac_centro_costo = COUNT(*) , @sec_ctro_costo = MIN(sec_ctro_costo)
	FROM sig_paac_centro_costo
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND @sec_resumen = sec_resumen
	AND @sec_meta = sec_meta 

	print @sec_ctro_costo
	
	IF @total_paac_centro_costo <= 0
	BEGIN
		SELECT @sec_ctro_costo = isnull(MAX(sec_ctro_costo),0) + 1
		FROM sig_paac_centro_costo
		WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
		AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
		AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
		AND sec_consolid = @sec_consolid AND @sec_resumen = sec_resumen
		AND @sec_meta = sec_meta 

		print 'antes de actualizar cc'
		print @sec_ctro_costo
		print 'luegos de actualizar cc'

		INSERT INTO sig_paac_centro_costo ( 
		ano_eje , sec_ejec , tipo_consolid , nro_consolid , tipo_generacion , tipo_bien , 
		sec_consolid , sec_resumen , sec_meta , sec_ctro_costo , tipo_tarea , codigo_tarea , 
		mes_01 , mes_02 , mes_03 , mes_04 , mes_05 , mes_06 , 
		mes_07 , mes_08 , mes_09 , mes_10 , mes_11 , mes_12 , cantidad , 
		valor, tipo_impto, tasa_impto, fte_fto_impto, valor_impto, valor_moneda, valor_impto_moneda, 
		centro_costo , fecha_reg , cuser_id , nivel_tarea, nro_pedido , tipo_pedido 
		) VALUES ( 
		@ano_eje, @sec_ejec, 2, @nro_consolid, 0, @tipo_bien, @sec_consolid, 
		@sec_resumen, @sec_meta, @sec_ctro_costo, @tipo_tarea, @codigo_tarea, 
		@cant_01, @cant_02, @cant_03, @cant_04, @cant_05, @cant_06, 
		@cant_07, @cant_08, @cant_09, @cant_10, @cant_11, @cant_12, @cant_total, 
		@valor_total, @tipo_impto, @tasa_impto, @fte_impto, @valor_impto, @valor_total, @valor_impto, 
		@centro_costo , GETDATE() , @cuser_id, @nivel_tarea, @nro_pedido , 3 
		)
	END
	ELSE
		GOTO ERROR

	print 'suma1'

	SELECT @tot_01 = SUM(isnull(mes_01,0)), @tot_02 = SUM(isnull(mes_02,0)), @tot_03 = SUM(isnull(mes_03,0)), 
	@tot_04 = SUM(isnull(mes_04,0)), @tot_05 = SUM(isnull(mes_05,0)), @tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)), 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)), 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta AND @sec_ctro_costo = @sec_ctro_costo

	print 'actualizacion'

	UPDATE sig_paac_metas 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @valor_tot, 
	valor_impto  = @valor_impto, valor_moneda = @valor_moneda, valor_impto_moneda = @valor_impto_moneda,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta AND sec_func = @sec_func 
	AND fuente_financ = @fuente_financ and clasificador = @clasificador 
	AND tipo_impto  = @tipo_impto 
	AND ( @tipo_impto = 0 or ( tipo_impto = @tipo_impto AND fte_fto_impto  = @fte_impto 
	AND tasa_impto = @tasa_impto ))

	print 'suma2'

			       
	SELECT @tot_01 = SUM(isnull(mes_01,0)), 
		@tot_02 = SUM(isnull(mes_02,0)), 
		@tot_03 = SUM(isnull(mes_03,0)), 

		@tot_04 = SUM(isnull(mes_04,0)), 

		@tot_05 = SUM(isnull(mes_05,0)), 


		@tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)) , 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)) , 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND sec_meta = @sec_meta AND @sec_ctro_costo = @sec_ctro_costo

	print 'actualizacion2'

	UPDATE sig_paac_item 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @valor_tot, valor_moneda  = @valor_tot,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @sec_consolid AND sec_resumen = @sec_resumen
	AND grupo_bien = @grupo_bien AND clase_bien = @clase_bien 
	AND familia_bien = @familia_bien AND item_bien = @item_bien 
	AND sec_consolid = @sec_consolid 
   set @respuesta = 1
   print 'casi OK'

	EXEC USP_PRTPProceso @ano_eje,  @sec_ejec, @centro_costo,  @tipo_bien, @nro_pedido, '3', @validar OUTPUT, @fuente_financ_result OUTPUT, @sec_func_result OUTPUT, @clasificador_result OUTPUT

COMMIT TRAN
   print 'OK'
RETURN 0

ERROR:
   print 'no OK'
   ROLLBACK TRAN
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_EA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_EA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_EA]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_EA]
    @P_ANO_EJE   	   NUMERIC(4,0),
    @P_SEC_EJEC  	   NUMERIC(6,0),
    @fecha_carga_inicio    VARCHAR(10),
    @fecha_carga_fin        VARCHAR(10),	
    @usuario_n	   VARCHAR(30),
    @O_ERR_NUM   	   NUMERIC(6,0) OUTPUT,
    @O_ERR_MSG   	   VARCHAR(255) OUTPUT
AS
DECLARE @fecha_carga_inicio_1         DATETIME
DECLARE @fecha_carga_fin_1            DATETIME      
DECLARE @LD_FECHA_MOVIMIENTO          DATETIME
DECLARE @LC_NRO_GUIA_NEA              VARCHAR(10)
DECLARE @LC_NRO_FACTURA               VARCHAR(15)
DECLARE @LC_EMPLEADO                  VARCHAR(15)
DECLARE @LC_OBSERVACION               VARCHAR(100)
DECLARE @LC_CLASIFICADOR              VARCHAR(20)
DECLARE @LC_GRUPO_BIEN                CHAR(2)
DECLARE @LC_CLASE_BIEN                CHAR(2)
DECLARE @LC_FAMILIA_BIEN              CHAR(4)
DECLARE @LC_ITEM_BIEN                 CHAR(4)
DECLARE @LN_ID_SI_MOV_ALM             NUMERIC(10,0)
DECLARE @LN_ID_SI_MOV_ALM_DETA        NUMERIC(10,0)
DECLARE @LN_SEC_FUNC                  NUMERIC(4,0)
DECLARE @LC_FINALIDAD                 CHAR(5)
DECLARE @LC_D_FINALIDAD               VARCHAR(250)
DECLARE @LC_META                      VARCHAR(5)
DECLARE @LC_UNIDAD_MEDIDA_META        NUMERIC(3,0)
DECLARE @LC_D_UNIDAD_MEDIDA_META      VARCHAR(100)
DECLARE @LC_ITEM_CATALOGO             VARCHAR(20)
DECLARE @LC_NOMBRE_ITEM               VARCHAR(100)
DECLARE @LC_D_UNIDAD_MEDIDA_ITEM_BS   VARCHAR(100)
DECLARE @LC_D_ALMACEN                 VARCHAR(40)
DECLARE @LC_D_EMPLEADO                VARCHAR(150)
DECLARE @LC_NOMBRE_MOVIMIENTO         VARCHAR(50)
DECLARE @LC_NRO_RUC                   VARCHAR(20)
DECLARE @LC_NOMBRE_PROV               VARCHAR(100)
DECLARE @LN_ALMACEN                   VARCHAR(3)
DECLARE @LN_SEC_ALMACEN               VARCHAR(3)
DECLARE @LC_TIPO_MOVIMIENTO           CHAR(1)
DECLARE @LC_TIPO_USO                  CHAR(1)
DECLARE @LN_TIPO_TRANSAC            NUMERIC(5,0)
DECLARE @LN_PROVEEDOR               NUMERIC(5,0)
DECLARE @LN_NRO_ORDEN               NUMERIC(5,0)
DECLARE @LN_TIPO_PPTO               NUMERIC(5,0)
DECLARE @LN_NRO_MOVIMTO             NUMERIC(5,0)
DECLARE @LC_D_MARCA                 VARCHAR(100)
DECLARE @LN_CANTIDAD_ITEM_BS        NUMERIC(13,6)
DECLARE @LN_PRECIO_TOTAL            NUMERIC(20,2)
DECLARE @LN_PRECIO_UNITARIO         NUMERIC(20,2)
DECLARE @LN_UNIDAD_MEDIDA           NUMERIC(3,0)
DECLARE @LN_MARCA                   NUMERIC(5,0)

BEGIN  
    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)    

    DELETE FROM SI_MOVIMIENTO_ALMACEN_DETA
    DELETE FROM SI_MOVIMIENTO_ALMACEN
      
    SELECT @LN_ID_SI_MOV_ALM = MAX(SA.ID_SI_MOV_ALM)
    FROM SI_MOVIMIENTO_ALMACEN SA WHERE SA.ANO_EJE  = @P_ANO_EJE 
    AND SA.SEC_EJEC = @P_SEC_EJEC

    IF @LN_ID_SI_MOV_ALM IS NULL
      	SET @LN_ID_SI_MOV_ALM = 0

    DECLARE C_1 CURSOR FOR
      SELECT NRO_MOVIMTO,
             FECHA_MOVIMTO,
             NRO_GUIA,
             PROVEEDOR,
             NRO_ORDEN,
             NRO_FACTURA,
             TIPO_MOVIMTO,
             TIPO_TRANSAC,
             RESPONSABLE,
             TIPO_USO,
             OBSERVACION,
             ALMACEN,
             SEC_ALMACEN,
             TIPO_PPTO
        FROM SIG_MOVIM_ALMACEN
       WHERE ANO_EJE         =  @P_ANO_EJE 
         AND SEC_EJEC        =  @P_SEC_EJEC
         AND (FECHA_MOVIMTO  >= @fecha_carga_inicio_1 
         AND  FECHA_MOVIMTO  <= @fecha_carga_fin_1)
         AND TIPO_MOVIMTO    =  'I' 
         AND TIPO_TRANSAC    =  1
       ORDER BY NRO_MOVIMTO

    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA, 
	 @LN_PROVEEDOR, @LN_NRO_ORDEN, @LC_NRO_FACTURA, @LC_TIPO_MOVIMIENTO, 
	 @LN_TIPO_TRANSAC, @LC_EMPLEADO, @LC_TIPO_USO, @LC_OBSERVACION, 
	 @LN_ALMACEN, @LN_SEC_ALMACEN, @LN_TIPO_PPTO

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SELECT @LC_D_EMPLEADO = LTRIM(RTRIM(COALESCE(APELLIDO_PATERNO,''))) + ' ' + LTRIM(RTRIM(COALESCE(APELLIDO_MATERNO,''))) + ' ' + LTRIM(RTRIM(COALESCE(NOMBRES,''))) 
        FROM SIG_PERSONAL
        WHERE SEC_EJEC = @P_SEC_EJEC
          AND EMPLEADO = @LC_EMPLEADO
        
        IF @LC_D_EMPLEADO IS NULL OR LTRIM(RTRIM(@LC_D_EMPLEADO)) = ''
            SET @LC_D_EMPLEADO = 'SIN DESCRIPCION'

        SELECT @LC_NRO_RUC = NRO_RUC,
               @LC_NOMBRE_PROV = NOMBRE_PROV
        FROM SIG_CONTRATISTAS
        WHERE PROVEEDOR = @LN_PROVEEDOR

        SELECT @LC_NOMBRE_MOVIMIENTO = NOMBRE_MOVIMTO
        FROM SIG_TIPO_MOVIMIENTO 
        WHERE TIPO_MOVIMTO = @LC_TIPO_MOVIMIENTO
          AND TIPO_TRANSAC = @LN_TIPO_TRANSAC

        SELECT @LC_D_ALMACEN = ALM.NOMBRE_ALM
        FROM SIG_ALMACEN ALM 
        WHERE ALM.SEC_EJEC    = @P_SEC_EJEC 
          AND ALM.ALMACEN     = @LN_ALMACEN
          AND ALM.SEC_ALMACEN = @LN_SEC_ALMACEN

        SET @LN_ID_SI_MOV_ALM = @LN_ID_SI_MOV_ALM + 1

        INSERT INTO SI_MOVIMIENTO_ALMACEN(
        ANO_EJE,SEC_EJEC,ID_SI_MOV_ALM,NRO_MOVIMIENTO,FECHA_MOVIMIENTO,NRO_GUIA_NEA,
        PROVEEDOR_NRO_RUC,D_PROVEEDOR,NRO_ORDEN,NRO_FACTURA,
        TIPO_MOVIMIENTO,TIPO_TRANSACCION,NOMBRE_MOVIMIENTO,EMPLEADO,D_EMPLEADO,
        TIPO_USO,OBSERVACION,ALMACEN,SEC_ALMACEN,D_ALMACEN,TIPO_PRESUPUESTO, 
	FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
        VALUES(
        @P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_MOV_ALM, @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA, 
        @LC_NRO_RUC, @LC_NOMBRE_PROV, @LN_NRO_ORDEN, @LC_NRO_FACTURA, 
        @LC_TIPO_MOVIMIENTO, @LN_TIPO_TRANSAC, @LC_NOMBRE_MOVIMIENTO, @LC_EMPLEADO, @LC_D_EMPLEADO, 
        @LC_TIPO_USO, @LC_OBSERVACION, @LN_ALMACEN, @LN_SEC_ALMACEN, @LC_D_ALMACEN, @LN_TIPO_PPTO, 
	@fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(), @usuario_n)

        DECLARE C_2 CURSOR FOR
             SELECT B.GRUPO_BIEN, 
                    B.CLASE_BIEN, 
                    B.FAMILIA_BIEN, 
                    B.ITEM_BIEN,
                    C.CANT_ARTICULO,
                    B.PRECIO_UNIT,
                    (coalesce(C.CANT_ARTICULO,0) * coalesce(B.PRECIO_UNIT,0)),
                    B.UNIDAD_MEDIDA, 
                    B.MARCA, 
                    B.TIPO_USO, 
                    C.CLASIFICADOR, 
                    C.SEC_FUNC
             FROM SIG_DETALLE_MOVIM_ALMACEN B, 
                  SIG_DETALLE_MOVIM_PPTO C
             WHERE B.ANO_EJE      = C.ANO_EJE 
               AND B.SEC_EJEC     = C.SEC_EJEC 
               AND B.ALMACEN      = C.ALMACEN
               AND B.SEC_ALMACEN  = C.SEC_ALMACEN 
               AND B.TIPO_MOVIMTO = C.TIPO_MOVIMTO 
               AND B.TIPO_TRANSAC = C.TIPO_TRANSAC
               AND B.TIPO_PPTO    = C.TIPO_PPTO 
               AND B.NRO_MOVIMTO  = C.NRO_MOVIMTO 
               AND B.SECUENCIA    = C.SECUENCIA
               AND B.SEC_DETALLE  = C.SEC_DETALLE
               AND B.ANO_EJE      = @P_ANO_EJE 
               AND B.SEC_EJEC     = @P_SEC_EJEC
               AND B.ALMACEN      = @LN_ALMACEN 
               AND B.SEC_ALMACEN  = @LN_SEC_ALMACEN 
               AND B.TIPO_MOVIMTO = @LC_TIPO_MOVIMIENTO 
               AND B.TIPO_TRANSAC = @LN_TIPO_TRANSAC 
               AND B.TIPO_PPTO    = @LN_TIPO_PPTO 
               AND B.NRO_MOVIMTO  = @LN_NRO_MOVIMTO
          ORDER BY B.NRO_MOVIMTO

        OPEN C_2
        FETCH NEXT FROM C_2 
        INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, 
	     @LC_ITEM_BIEN, @LN_CANTIDAD_ITEM_BS,
             @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL, 
	     @LN_UNIDAD_MEDIDA, @LN_MARCA, @LC_TIPO_USO, 
	     @LC_CLASIFICADOR, @LN_SEC_FUNC

        WHILE @@FETCH_STATUS = 0
        BEGIN

            SET @LC_ITEM_CATALOGO = @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN

            SELECT @LC_NOMBRE_ITEM = CAT.NOMBRE_ITEM
            FROM CATALOGO_BIEN_SERV_ORIGINAL CAT
            WHERE CAT.TIPO_BIEN    = 'B'
              AND CAT.GRUPO_BIEN   = @LC_GRUPO_BIEN
              AND CAT.CLASE_BIEN   = @LC_CLASE_BIEN
              AND CAT.FAMILIA_BIEN = @LC_FAMILIA_BIEN
              AND CAT.ITEM_BIEN    = @LC_ITEM_BIEN 

            SELECT @LC_D_UNIDAD_MEDIDA_ITEM_BS = M.NOMBRE
            FROM UNIDAD_MEDIDA M
            WHERE M.UNIDAD_MEDIDA = @LN_UNIDAD_MEDIDA

            SELECT @LC_META = META, 
                   @LC_UNIDAD_MEDIDA_META = UNIDAD_MEDIDA,
                   @LC_FINALIDAD = FINALIDAD
            FROM META
            WHERE ANO_EJE  = @P_ANO_EJE 
              AND SEC_EJEC = @P_SEC_EJEC
              AND SEC_FUNC = @LN_SEC_FUNC

            SELECT @LC_D_UNIDAD_MEDIDA_META = M.NOMBRE
            FROM UNIDAD_MEDIDA M
            WHERE M.UNIDAD_MEDIDA = @LC_UNIDAD_MEDIDA_META

            IF @LC_D_UNIDAD_MEDIDA_META IS NULL
                SET @LC_D_UNIDAD_MEDIDA_META = 'SIN DESCRIPCION'

            SELECT @LC_D_FINALIDAD = F.NOMBRE
            FROM FINALIDAD F
            WHERE F.ANO_EJE   = @P_ANO_EJE 
              AND F.FINALIDAD = @LC_FINALIDAD

            IF @LC_D_FINALIDAD IS NULL
                SET @LC_D_FINALIDAD = 'SIN DESCRIPCION'

            SELECT @LC_D_MARCA = MA.NOMBRE
            FROM MARCA MA 
            WHERE MA.MARCA = @LN_MARCA
              AND MA.TIPO_MARCA = 1

            IF @LC_D_MARCA IS NULL
                SET @LC_D_MARCA = 'SIN DESCRIPCION'

            SELECT @LN_ID_SI_MOV_ALM_DETA = MAX(SAD.ID_SI_MOV_ALM_DETA)
            FROM SI_MOVIMIENTO_ALMACEN_DETA SAD
            WHERE SAD.ANO_EJE       = @P_ANO_EJE 
              AND SAD.SEC_EJEC      = @P_SEC_EJEC
              AND SAD.ID_SI_MOV_ALM = @LN_ID_SI_MOV_ALM

            IF @LN_ID_SI_MOV_ALM_DETA IS NULL
              SET @LN_ID_SI_MOV_ALM_DETA = 0

            SET @LN_ID_SI_MOV_ALM_DETA = @LN_ID_SI_MOV_ALM_DETA + 1
                      
            INSERT INTO SI_MOVIMIENTO_ALMACEN_DETA
            ( ANO_EJE, SEC_EJEC, ID_SI_MOV_ALM, ID_SI_MOV_ALM_DETA, 
	      ITEM_CATALOGO, D_ITEM_CATALOGO,
              CANTIDAD_ITEM_BS, PRECIO_UNITARIO, PRECIO_TOTAL,
              UNIDAD_MEDIDA_ITEM_BS, D_UNIDAD_MEDIDA_ITEM_BS, MARCA, D_MARCA,
              TIPO_USO, CLASIFICADOR, SEC_FUNC, FINALIDAD, D_FINALIDAD,
              META, UNIDAD_MEDIDA_META, D_UNIDAD_MEDIDA_META, 
	      FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
             VALUES
            ( @P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_MOV_ALM, 
              @LN_ID_SI_MOV_ALM_DETA, @LC_ITEM_CATALOGO, @LC_NOMBRE_ITEM,
              @LN_CANTIDAD_ITEM_BS, @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL,
              @LN_UNIDAD_MEDIDA, @LC_D_UNIDAD_MEDIDA_ITEM_BS, @LN_MARCA, @LC_D_MARCA,
              @LC_TIPO_USO, @LC_CLASIFICADOR, @LN_SEC_FUNC, @LC_FINALIDAD, @LC_D_FINALIDAD,
              @LC_META, @LC_UNIDAD_MEDIDA_META, @LC_D_UNIDAD_MEDIDA_META, 
	      @fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(), @usuario_n)
	      
            FETCH NEXT FROM C_2 
            INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, 
                 @LC_ITEM_BIEN, @LN_CANTIDAD_ITEM_BS,
                 @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL, @LN_UNIDAD_MEDIDA, 
                 @LN_MARCA, @LC_TIPO_USO, @LC_CLASIFICADOR, @LN_SEC_FUNC
         END
         CLOSE C_2
         DEALLOCATE C_2

         FETCH NEXT FROM C_1
         INTO @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA, 
              @LN_PROVEEDOR, @LN_NRO_ORDEN, 
              @LC_NRO_FACTURA, @LC_TIPO_MOVIMIENTO, @LN_TIPO_TRANSAC, @LC_EMPLEADO, 
	      @LC_TIPO_USO, @LC_OBSERVACION, @LN_ALMACEN, @LN_SEC_ALMACEN, @LN_TIPO_PPTO
     END
     CLOSE C_1
     DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_PPR_SIMULA_CN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PPR_SIMULA_CN]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PPR_SIMULA_CN]
GO

CREATE PROCEDURE [dbo].[SP_PPR_SIMULA_CN]
(
@al_sec_ejec    NUMERIC(10),
@al_anno_ejec   NUMERIC(10),
@al_fase        NUMERIC(10),
@al_error_cod   NUMERIC(10)     OUTPUT,
@as_error_txt   VARCHAR(255)    OUTPUT
)
AS
------------------------------------------------------------------------------------
--Autor : Felix Castillo
--Objeto: Procesa la simulacion del cuadro de necesidades desde el ppr
------------------------------------------------------------------------------------
BEGIN
DECLARE @ll_cont                    NUMERIC(10) 
DECLARE @ll_nro_ambiente            NUMERIC(10) 
DECLARE @ll_tipo_calculo            NUMERIC(10) 
DECLARE @ll_cod_establec            NUMERIC(10) 
DECLARE @ldc_monto                  NUMERIC(20, 4) 
DECLARE @ldc_valor_imp              NUMERIC(20, 4) 
DECLARE @ldc_cant_total_ajust       NUMERIC(20, 4) 
DECLARE @ll_cur_secuencia           NUMERIC(10) 
DECLARE @ll_cur_sec_func            NUMERIC(10) 
DECLARE @ll_cur_sec_establec        NUMERIC(10) 
DECLARE @ll_cur_id_sub_finalidad    NUMERIC(10) 
DECLARE @ldc_cur_cantidad           NUMERIC(20, 4) 
DECLARE @ls_cur_sub_finalidad       VARCHAR(20) 
DECLARE @ldc_cur_monto              NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_01            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_02            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_03            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_04            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_05            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_06            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_07            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_08            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_09            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_10            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_11            NUMERIC(20, 4) 
DECLARE @ldc_cur_cant_12            NUMERIC(20, 4) 
DECLARE @ldc_cur_monto_ref          NUMERIC(20, 4) 
DECLARE @ll_cur_sede                NUMERIC(10) 
DECLARE @ldc_cur_tasa_impto         NUMERIC(20, 4) 
DECLARE @ll_cur_item_sec            NUMERIC(10) 
DECLARE @ldc_cur_precio_unit        NUMERIC(20, 6) 
DECLARE @ll_cur_id_kit              NUMERIC(10) 
DECLARE @ldc_cur_stock              NUMERIC(20, 4) 
DECLARE @ls_cur_cadena_funcional    VARCHAR(100) 
DECLARE @ls_cur_pliego              VARCHAR(20) 
DECLARE @ls_cur_centro_costo        VARCHAR(20) 
DECLARE @ls_cur_tipo_impuesto       VARCHAR(1) 
DECLARE @ldc_pcndi_cont             NUMERIC(10) 
DECLARE @ldc_cant_01_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_02_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_03_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_04_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_05_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_06_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_07_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_08_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_09_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_10_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_11_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_12_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_01_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_02_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_03_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_04_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_05_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_06_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_07_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_08_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_09_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_10_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_11_ref            NUMERIC(20, 4) 
DECLARE @ldc_mnto_12_ref            NUMERIC(20, 4) 
DECLARE @ldc_cant_total_ref         NUMERIC(20, 4) 
DECLARE @ldc_mnto_total_ref         NUMERIC(20, 4) 
DECLARE @ldc_valor_impto_ref        NUMERIC(20, 4) 
DECLARE @ldc_cantidad_unitaria_sum  NUMERIC(20, 4) 
DECLARE @ldc_cant_total_sum         NUMERIC(20, 4) 

-------------------------------
--declaro el cursor principal--
-------------------------------
DECLARE lcur_meta_fisica    CURSOR  FOR
SELECT  SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC, SIG_PPR_METFIS_X_SUBFIN.SEC_ESTABLEC,
        SIG_PPR_METFIS_X_SUBFIN.ID_SUB_FINALIDAD, SIG_PPR_METFIS_X_SUBFIN.CANTIDAD,
        SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD, SIG_PPR_METFIS_X_SUBFIN.MONTO,
        SIG_PPR_METFIS_X_SUBFIN.CANT_01, SIG_PPR_METFIS_X_SUBFIN.CANT_02,
        SIG_PPR_METFIS_X_SUBFIN.CANT_03, SIG_PPR_METFIS_X_SUBFIN.CANT_04,
        SIG_PPR_METFIS_X_SUBFIN.CANT_05, SIG_PPR_METFIS_X_SUBFIN.CANT_06,
        SIG_PPR_METFIS_X_SUBFIN.CANT_07, SIG_PPR_METFIS_X_SUBFIN.CANT_08,
        SIG_PPR_METFIS_X_SUBFIN.CANT_09, SIG_PPR_METFIS_X_SUBFIN.CANT_10,
        SIG_PPR_METFIS_X_SUBFIN.CANT_11, SIG_PPR_METFIS_X_SUBFIN.CANT_12,
        SIG_PPR_METFIS_X_SUBFIN.MONTO_REF, SIG_PPR_METFIS_X_SUBFIN.CADENA_FUNCIONAL,
        SIG_PPR_SEDE.SEDE, SIG_PPR_SEDE.PLIEGO
FROM    SIG_PPR_METFIS_X_SUBFIN, SIG_SUB_FINALIDAD, SIG_PPR_SEDE
WHERE   SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC            = @al_sec_ejec
AND     SIG_PPR_METFIS_X_SUBFIN.ANO_EJE             = @al_anno_ejec
AND     SIG_PPR_METFIS_X_SUBFIN.NRO_FASE            = @al_fase
------------------------------------------
AND     SIG_PPR_METFIS_X_SUBFIN.ANO_EJE             = SIG_PPR_SEDE.ANO_EJE
AND     SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC            = SIG_PPR_SEDE.SEC_EJEC
AND     SIG_PPR_METFIS_X_SUBFIN.SEC_ESTABLEC        = SIG_PPR_SEDE.SEC_ESTABLEC
------------------------------------------
AND     SIG_PPR_METFIS_X_SUBFIN.CANTIDAD            > 0
AND     SIG_PPR_METFIS_X_SUBFIN.ANO_EJE             = SIG_SUB_FINALIDAD.ANO_EJE
AND     SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD       = SIG_SUB_FINALIDAD.SUB_FINALIDAD
AND     SIG_PPR_METFIS_X_SUBFIN.ID_SUB_FINALIDAD    = SIG_SUB_FINALIDAD.ID_SUB_FINALIDAD
AND     'A'                                         = SIG_SUB_FINALIDAD.ESTADO 

------------------------------------------------------------------------------------
--valido que se hayan bloqueado los centros de costo
------------------------------------------------------------------------------------
SELECT
@ll_cont    = COUNT(1)
FROM    META, SIG_METAS_X_CENTRO, SIG_CENTRO_COSTO, ACT_PROY_NOMBRE
WHERE   META.SEC_EJEC                                       = @al_sec_ejec
AND     META.ANO_EJE                                        = @al_anno_ejec
AND     META.FLAG_ESTRATEGIA                                = 'S'
------------------------------------------
AND     META.ANO_EJE                                        = ACT_PROY_NOMBRE.ANO_EJE
AND     META.ACT_PROY                                       = ACT_PROY_NOMBRE.ACT_PROY
------------------------------------------
AND     SIG_METAS_X_CENTRO.ANO_EJE                          = META.ANO_EJE
AND     SIG_METAS_X_CENTRO.SEC_EJEC                         = META.SEC_EJEC
AND     SIG_METAS_X_CENTRO.SEC_FUNC                         = META.SEC_FUNC
AND     SIG_METAS_X_CENTRO.ANO_EJE                          = SIG_CENTRO_COSTO.ANO_EJE
AND     SIG_METAS_X_CENTRO.SEC_EJEC                         = SIG_CENTRO_COSTO.SEC_EJEC
AND     SIG_METAS_X_CENTRO.CENTRO_COSTO                     = SIG_CENTRO_COSTO.CENTRO_COSTO
AND     COALESCE(SIG_METAS_X_CENTRO.FLAG_BLOQUEO_PPR, '0')  = '0' 
IF @ll_cont > 0
BEGIN
    SELECT  @al_error_cod   = -1 
    SELECT  @as_error_txt   = 'Este proceso requiere que se hayan bloqueado TODOS los Centros de Costo' 
    DEALLOCATE  lcur_meta_fisica 
    RETURN 
END 

------------------------------------------------------------------------------------
--al menos una finalidad debe tener META FISICA
------------------------------------------------------------------------------------
SELECT
@ll_cont    = COUNT(1)
FROM    SIG_PPR_METFIS_X_SUBFIN
WHERE   SEC_EJEC    = @al_sec_ejec
AND     ANO_EJE     = @al_anno_ejec
AND     NRO_FASE    = @al_fase
AND     CANTIDAD    > 0 
IF @ll_cont = 0
BEGIN
    SELECT  @al_error_cod   = -2 
    SELECT  @as_error_txt   = 'Se requiere que se haya registrado al menos una Meta Fisica' 
    DEALLOCATE  lcur_meta_fisica 
    RETURN 
END 

------------------------------------------
--borro los temporales
------------------------------------------
TRUNCATE    TABLE   SIG_PPR_CUA_NEC_DET_ID 
TRUNCATE    TABLE   SIG_PPR_CUADRO_NECESIDAD_DET 
TRUNCATE    TABLE   SIG_PPR_CUADRO_NECESIDAD 
TRUNCATE    TABLE   SIG_PPR_TECHO_PRESUPUESTO 

------------------------------------------------------------------------------------
--inserto en los temporales de la simulacion del cn: SIG_PPR_CUADRO_NECESIDAD
------------------------------------------------------------------------------------
INSERT  INTO    SIG_PPR_CUADRO_NECESIDAD(
                ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA,
                FASE_CUADRO, TIPO_TAREA, NIVEL_TAREA, CODIGO_TAREA,
                SEC_FUNC_PROP, SEC_FUNC, ORIGEN, FUENTE_FINANC,
                CONCEPTO_GASTO, CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR,
                TIPO_RECURSO, TOTAL_ASIGNADO, TOTAL_PROGRA, TOTAL_APROB,
                TOTAL_MODIF, MONTO_ASIGNADO, MONTO_PROGRA, MONTO_APROB,
                MONTO_MODIF, VALOR_IMP_ASIGNADO , VALOR_IMP_PROGRA, VALOR_IMP_APROB,
                VALOR_IMP_MODIF, TIPO_IMPUESTO, FUENTE_IMPTO, TASA_IMPTO,
                FLAG_GASTO, TIPO_PPTO, TIPO_USO, TIPO_OPERACION,
                OPERACION, MAYOR, SUB_CTA, SUB_CTA_DET,
                NRO_PLANTILLA, TIPO_BIEN, TIPO_ORIGEN_EXTERNO, ID_CLASIFICADOR,
                SEC_ESTABLEC, SUB_FINALIDAD, FLAG_ORIGEN_CAB, ID_SUB_FINALIDAD
                )
SELECT          ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA,
                FASE_CUADRO, TIPO_TAREA, NIVEL_TAREA, CODIGO_TAREA,
                SEC_FUNC_PROP, SEC_FUNC, ORIGEN, FUENTE_FINANC,
                CONCEPTO_GASTO, CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR,
                TIPO_RECURSO, TOTAL_ASIGNADO, TOTAL_PROGRA, TOTAL_APROB,
                TOTAL_MODIF, MONTO_ASIGNADO, MONTO_PROGRA, MONTO_APROB,
                MONTO_MODIF, VALOR_IMP_ASIGNADO, VALOR_IMP_PROGRA, VALOR_IMP_APROB,
                VALOR_IMP_MODIF, TIPO_IMPUESTO, FUENTE_IMPTO, TASA_IMPTO,
                FLAG_GASTO, TIPO_PPTO, TIPO_USO, TIPO_OPERACION,
                OPERACION, MAYOR, SUB_CTA, SUB_CTA_DET,
                NRO_PLANTILLA, TIPO_BIEN, TIPO_ORIGEN_EXTERNO, ID_CLASIFICADOR,
                SEC_ESTABLEC, SUB_FINALIDAD, FLAG_ORIGEN_CAB, ID_SUB_FINALIDAD
FROM            SIG_CUADRO_NECESIDAD
WHERE           SEC_EJEC    = @al_sec_ejec
AND             ANO_EJE     = @al_anno_ejec
AND             FASE_CUADRO = @al_fase
AND             SEC_FUNC    IN  (
                                SELECT  SEC_FUNC
                                FROM    META
                                WHERE   META.FLAG_ESTRATEGIA    = 'S'
                                AND     META.ANO_EJE            = SIG_CUADRO_NECESIDAD.ANO_EJE
                                AND     META.SEC_EJEC           = SIG_CUADRO_NECESIDAD.SEC_EJEC
                                ) 

------------------------------------------------------------------------------------
--inserto en los temporales de la simulacion del cn: SIG_PPR_CUADRO_NECESIDAD_DET
------------------------------------------------------------------------------------
INSERT  INTO    SIG_PPR_CUADRO_NECESIDAD_DET
                (
                ANO_EJE, SEC_EJEC,
                CENTRO_COSTO, SECUENCIA,
                FASE_CUADRO, ITEM_SEC,
                TIPO_BIEN, GRUPO_BIEN,
                CLASE_BIEN, FAMILIA_BIEN,
                ITEM_BIEN, DESCRIP_SERVICIO,
                UNIDAD_MEDIDA, PRECIO_UNIT,
                CANT_01, CANT_02,
                CANT_03, CANT_04,
                CANT_05, CANT_06,
                CANT_07, CANT_08,
                CANT_09, CANT_10,
                CANT_11, CANT_12,
                CANT_TOTAL, MNTO_01,
                MNTO_02, MNTO_03,
                MNTO_04, MNTO_05,
                MNTO_06, MNTO_07,
                MNTO_08, MNTO_09,
                MNTO_10, MNTO_11,
                MNTO_12, MNTO_TOTAL,
                STOCK_ASIG, VALOR_STOCK,
                TIPO_IMPTO, TASA_IMPTO,
                FTE_IMPTO, VALOR_IMPTO,
                ESTADO, CANT_HIST,
                MNTO_HIST, NRO_CONSOLID,
                ESTADO_PAAC, NRO_PEDIDO,
                PORC_GASTO, FLAG_GASTO,
                FLAG_MODIF, FLAG_MIGRA,
                TIPO_ORIGEN_EXTERNO_DET, CANTIDAD_UNITARIA,
                PORCENTAJE, ESTADO_ITEM_KIT,
                ID_KIT, TIPO_CALCULO,
                FLAG_ORIGEN_DET
                )
SELECT          SIG_CUADRO_NECESIDAD_DET.ANO_EJE, SIG_CUADRO_NECESIDAD_DET.SEC_EJEC,
                SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO, SIG_CUADRO_NECESIDAD_DET.SECUENCIA,
                SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO, SIG_CUADRO_NECESIDAD_DET.ITEM_SEC,
                SIG_CUADRO_NECESIDAD_DET.TIPO_BIEN, SIG_CUADRO_NECESIDAD_DET.GRUPO_BIEN,
                SIG_CUADRO_NECESIDAD_DET.CLASE_BIEN, SIG_CUADRO_NECESIDAD_DET.FAMILIA_BIEN,
                SIG_CUADRO_NECESIDAD_DET.ITEM_BIEN, SIG_CUADRO_NECESIDAD_DET.DESCRIP_SERVICIO,
                SIG_CUADRO_NECESIDAD_DET.UNIDAD_MEDIDA, SIG_CUADRO_NECESIDAD_DET.PRECIO_UNIT,
                SIG_CUADRO_NECESIDAD_DET.CANT_01, SIG_CUADRO_NECESIDAD_DET.CANT_02,
                SIG_CUADRO_NECESIDAD_DET.CANT_03, SIG_CUADRO_NECESIDAD_DET.CANT_04,
                SIG_CUADRO_NECESIDAD_DET.CANT_05, SIG_CUADRO_NECESIDAD_DET.CANT_06,
                SIG_CUADRO_NECESIDAD_DET.CANT_07, SIG_CUADRO_NECESIDAD_DET.CANT_08,
                SIG_CUADRO_NECESIDAD_DET.CANT_09, SIG_CUADRO_NECESIDAD_DET.CANT_10,
                SIG_CUADRO_NECESIDAD_DET.CANT_11, SIG_CUADRO_NECESIDAD_DET.CANT_12,
                SIG_CUADRO_NECESIDAD_DET.CANT_TOTAL, SIG_CUADRO_NECESIDAD_DET.MNTO_01,
                SIG_CUADRO_NECESIDAD_DET.MNTO_02, SIG_CUADRO_NECESIDAD_DET.MNTO_03,
                SIG_CUADRO_NECESIDAD_DET.MNTO_04, SIG_CUADRO_NECESIDAD_DET.MNTO_05,
                SIG_CUADRO_NECESIDAD_DET.MNTO_06, SIG_CUADRO_NECESIDAD_DET.MNTO_07,
                SIG_CUADRO_NECESIDAD_DET.MNTO_08, SIG_CUADRO_NECESIDAD_DET.MNTO_09,
                SIG_CUADRO_NECESIDAD_DET.MNTO_10, SIG_CUADRO_NECESIDAD_DET.MNTO_11,
                SIG_CUADRO_NECESIDAD_DET.MNTO_12, SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL,
                SIG_CUADRO_NECESIDAD_DET.STOCK_ASIG, SIG_CUADRO_NECESIDAD_DET.VALOR_STOCK,
                SIG_CUADRO_NECESIDAD_DET.TIPO_IMPTO, SIG_CUADRO_NECESIDAD_DET.TASA_IMPTO,
                SIG_CUADRO_NECESIDAD_DET.FTE_IMPTO, SIG_CUADRO_NECESIDAD_DET.VALOR_IMPTO,
                SIG_CUADRO_NECESIDAD_DET.ESTADO, SIG_CUADRO_NECESIDAD_DET.CANT_HIST,
                SIG_CUADRO_NECESIDAD_DET.MNTO_HIST, SIG_CUADRO_NECESIDAD_DET.NRO_CONSOLID,
                SIG_CUADRO_NECESIDAD_DET.ESTADO_PAAC, SIG_CUADRO_NECESIDAD_DET.NRO_PEDIDO,
                SIG_CUADRO_NECESIDAD_DET.PORC_GASTO, SIG_CUADRO_NECESIDAD_DET.FLAG_GASTO,
                SIG_CUADRO_NECESIDAD_DET.FLAG_MODIF, SIG_CUADRO_NECESIDAD_DET.FLAG_MIGRA,
                SIG_CUADRO_NECESIDAD_DET.TIPO_ORIGEN_EXTERNO_DET, SIG_CUADRO_NECESIDAD_DET.CANTIDAD_UNITARIA,
                SIG_CUADRO_NECESIDAD_DET.PORCENTAJE, SIG_CUADRO_NECESIDAD_DET.ESTADO_ITEM_KIT,
                SIG_CUADRO_NECESIDAD_DET.ID_KIT, SIG_CUADRO_NECESIDAD_DET.TIPO_CALCULO,
                SIG_CUADRO_NECESIDAD_DET.FLAG_ORIGEN_DET
FROM            SIG_CUADRO_NECESIDAD_DET, SIG_CUADRO_NECESIDAD
WHERE           SIG_CUADRO_NECESIDAD.SEC_EJEC           = @al_sec_ejec
AND             SIG_CUADRO_NECESIDAD.ANO_EJE            = @al_anno_ejec
AND             SIG_CUADRO_NECESIDAD.FASE_CUADRO        = @al_fase
AND             SIG_CUADRO_NECESIDAD_DET.ANO_EJE        = SIG_CUADRO_NECESIDAD.ANO_EJE
AND             SIG_CUADRO_NECESIDAD_DET.SEC_EJEC       = SIG_CUADRO_NECESIDAD.SEC_EJEC
AND             SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO   = SIG_CUADRO_NECESIDAD.CENTRO_COSTO
AND             SIG_CUADRO_NECESIDAD_DET.SECUENCIA      = SIG_CUADRO_NECESIDAD.SECUENCIA
AND             SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO    = SIG_CUADRO_NECESIDAD.FASE_CUADRO
AND             SIG_CUADRO_NECESIDAD.SEC_FUNC           IN  (
                                                            SELECT  META.SEC_FUNC
                                                            FROM    META
                                                            WHERE   META.SEC_EJEC           = SIG_CUADRO_NECESIDAD.SEC_EJEC
                                                            AND     META.ANO_EJE            = SIG_CUADRO_NECESIDAD.ANO_EJE
                                                            AND     META.FLAG_ESTRATEGIA    = 'S'
                                                            ) 

------------------------------------------------------------------------------------
--inserto en los temporales de la simulacion del cn: SIG_PPR_CUA_NEC_DET_ID
------------------------------------------------------------------------------------
INSERT INTO SIG_PPR_CUA_NEC_DET_ID
            (
            ANO_EJE, SEC_EJEC, CENTRO_COSTO,
            SECUENCIA, FASE_CUADRO, ITEM_ID,
            ITEM_SEC, ID_KIT, TIPO_CALCULO,
            CANTIDAD_UNITARIA, TIPO_BIEN, GRUPO_BIEN,
            CLASE_BIEN, FAMILIA_BIEN, ITEM_BIEN,
            CANT_TOTAL, ESTADO
            )
SELECT      SIG_CUA_NEC_DET_ID.ANO_EJE, SIG_CUA_NEC_DET_ID.SEC_EJEC, SIG_CUA_NEC_DET_ID.CENTRO_COSTO,
            SIG_CUA_NEC_DET_ID.SECUENCIA, SIG_CUA_NEC_DET_ID.FASE_CUADRO, SIG_CUA_NEC_DET_ID.ITEM_ID,
            SIG_CUA_NEC_DET_ID.ITEM_SEC, SIG_CUA_NEC_DET_ID.ID_KIT, SIG_CUA_NEC_DET_ID.TIPO_CALCULO,
            SIG_CUA_NEC_DET_ID.CANTIDAD_UNITARIA, SIG_CUA_NEC_DET_ID.TIPO_BIEN, SIG_CUA_NEC_DET_ID.GRUPO_BIEN,
            SIG_CUA_NEC_DET_ID.CLASE_BIEN, SIG_CUA_NEC_DET_ID.FAMILIA_BIEN, SIG_CUA_NEC_DET_ID.ITEM_BIEN,
            SIG_CUA_NEC_DET_ID.CANT_TOTAL, SIG_CUA_NEC_DET_ID.ESTADO
FROM        SIG_CUADRO_NECESIDAD_DET, SIG_CUADRO_NECESIDAD, SIG_CUA_NEC_DET_ID
WHERE       SIG_CUADRO_NECESIDAD.SEC_EJEC           = @al_sec_ejec
AND         SIG_CUADRO_NECESIDAD.ANO_EJE            = @al_anno_ejec
AND         SIG_CUADRO_NECESIDAD.FASE_CUADRO        = @al_fase
AND         SIG_CUADRO_NECESIDAD_DET.ANO_EJE        = SIG_CUA_NEC_DET_ID.ANO_EJE
AND         SIG_CUADRO_NECESIDAD_DET.SEC_EJEC       = SIG_CUA_NEC_DET_ID.SEC_EJEC
AND         SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO   = SIG_CUA_NEC_DET_ID.CENTRO_COSTO
AND         SIG_CUADRO_NECESIDAD_DET.SECUENCIA      = SIG_CUA_NEC_DET_ID.SECUENCIA
AND         SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO    = SIG_CUA_NEC_DET_ID.FASE_CUADRO
AND         SIG_CUADRO_NECESIDAD_DET.ITEM_SEC       = SIG_CUA_NEC_DET_ID.ITEM_SEC
AND         SIG_CUADRO_NECESIDAD_DET.ANO_EJE        = SIG_CUADRO_NECESIDAD.ANO_EJE
AND         SIG_CUADRO_NECESIDAD_DET.SEC_EJEC       = SIG_CUADRO_NECESIDAD.SEC_EJEC
AND         SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO   = SIG_CUADRO_NECESIDAD.CENTRO_COSTO
AND         SIG_CUADRO_NECESIDAD_DET.SECUENCIA      = SIG_CUADRO_NECESIDAD.SECUENCIA
AND         SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO    = SIG_CUADRO_NECESIDAD.FASE_CUADRO
AND         SIG_CUADRO_NECESIDAD.SEC_FUNC           IN  (
                                                        SELECT  META.SEC_FUNC
                                                        FROM    META
                                                        WHERE   META.SEC_EJEC           = SIG_CUADRO_NECESIDAD.SEC_EJEC
                                                        AND     META.ANO_EJE            = SIG_CUADRO_NECESIDAD.ANO_EJE
                                                        AND     META.FLAG_ESTRATEGIA    = 'S'
                                                        ) 

------------------------------------------
--barro el cursor principal
------------------------------------------
OPEN    lcur_meta_fisica 
WHILE   1 = 1
BEGIN
    FETCH   lcur_meta_fisica
    INTO    @ll_cur_sec_func, @ll_cur_sec_establec,
            @ll_cur_id_sub_finalidad, @ldc_cur_cantidad,
            @ls_cur_sub_finalidad, @ldc_cur_monto,
            @ldc_cur_cant_01, @ldc_cur_cant_02,
            @ldc_cur_cant_03, @ldc_cur_cant_04,
            @ldc_cur_cant_05, @ldc_cur_cant_06,
            @ldc_cur_cant_07, @ldc_cur_cant_08,
            @ldc_cur_cant_09, @ldc_cur_cant_10,
            @ldc_cur_cant_11, @ldc_cur_cant_12,
            @ldc_cur_monto_ref, @ls_cur_cadena_funcional,
            @ll_cur_sede, @ls_cur_pliego 
    IF  @@FETCH_STATUS <> 0
    BEGIN
        BREAK 
    END 

    --obtengo el numero de ambientes del establecimiento y el cod_establec
    SELECT
    @ll_nro_ambiente                                = COALESCE(SIG_PPR_ESTABLECIMIENTO.NRO_AMBIENTE, 0),
    @ll_cod_establec                                = SIG_PPR_SEDE.SEC_ESTABLEC
    FROM    SIG_PPR_ESTABLECIMIENTO, SIG_PPR_SEDE
    WHERE   SIG_PPR_ESTABLECIMIENTO.SEC_EJEC        = @al_sec_ejec
    AND     SIG_PPR_ESTABLECIMIENTO.ANO_EJE         = @al_anno_ejec
    AND     SIG_PPR_ESTABLECIMIENTO.COD_ESTABLEC    = SIG_PPR_SEDE.COD_ESTABLEC
    AND     SIG_PPR_ESTABLECIMIENTO.SEC_EJEC        = SIG_PPR_SEDE.SEC_EJEC
    AND     SIG_PPR_ESTABLECIMIENTO.ANO_EJE         = SIG_PPR_SEDE.ANO_EJE
    AND     @ll_cur_sec_establec                    = SIG_PPR_SEDE.SEC_ESTABLEC 

    ------------------------------------------
    --declaro 2do. cursor
    ------------------------------------------
    DECLARE lcur_cuadro_necesidad    CURSOR  FOR
    SELECT  DISTINCT
            SIG_CUADRO_NECESIDAD.CENTRO_COSTO, SIG_CUADRO_NECESIDAD.SECUENCIA
    FROM    SIG_CENTRO_COSTO , SIG_CUADRO_X_CENTRO, SIG_CUADRO_NECESIDAD
    WHERE   SIG_CENTRO_COSTO.SEC_EJEC               = @al_sec_ejec
    AND     SIG_CENTRO_COSTO.ANO_EJE                = @al_anno_ejec
    AND     SIG_CENTRO_COSTO.SEDE                   = @ll_cur_sede
    AND     SIG_CENTRO_COSTO.PLIEGO                 = @ls_cur_pliego
    AND     SIG_CUADRO_NECESIDAD.FASE_CUADRO        = @al_fase
    AND     SIG_CUADRO_NECESIDAD.SUB_FINALIDAD      = @ls_cur_sub_finalidad
    AND     (
            SIG_CUADRO_NECESIDAD.ID_SUB_FINALIDAD   = @ll_cur_id_sub_finalidad
            OR
            @ll_cur_id_sub_finalidad                = 0
            )
    AND     (
            (SIG_CUADRO_NECESIDAD.SEC_FUNC_PROP = @ll_cur_sec_func  AND @al_fase < 5)
            OR
            (SIG_CUADRO_NECESIDAD.SEC_FUNC      = @ll_cur_sec_func  AND @al_fase = 5)
            )
    AND     SIG_CENTRO_COSTO.ANO_EJE                = SIG_CUADRO_X_CENTRO.ANO_EJE
    AND     SIG_CENTRO_COSTO.SEC_EJEC               = SIG_CUADRO_X_CENTRO.SEC_EJEC
    AND     SIG_CENTRO_COSTO.CENTRO_COSTO           = SIG_CUADRO_X_CENTRO.CENTRO_COSTO
    AND     SIG_CENTRO_COSTO.ANO_EJE                = SIG_CUADRO_NECESIDAD.ANO_EJE
    AND     SIG_CENTRO_COSTO.SEC_EJEC               = SIG_CUADRO_NECESIDAD.SEC_EJEC
    AND     SIG_CENTRO_COSTO.CENTRO_COSTO           = SIG_CUADRO_NECESIDAD.CENTRO_COSTO 

    --barro el 2do. cursor
    OPEN    lcur_cuadro_necesidad 
    WHILE   1 = 1
    BEGIN
        FETCH   lcur_cuadro_necesidad
        INTO    @ls_cur_centro_costo, @ll_cur_secuencia 
        IF  @@FETCH_STATUS <> 0
        BEGIN
            BREAK 
        END 

        ------------------------------------------
        --declaro 3er. cursor
        ------------------------------------------
        DECLARE lcur_cuadro_necesidad_det   CURSOR  FOR
        SELECT  DISTINCT
                SIG_CUADRO_NECESIDAD_DET.ITEM_SEC, SIG_CUADRO_NECESIDAD_DET.PRECIO_UNIT,
                SIG_CUADRO_NECESIDAD.TASA_IMPTO, SIG_CUADRO_NECESIDAD.TIPO_IMPUESTO
        FROM    SIG_CUADRO_NECESIDAD_DET, SIG_CUADRO_NECESIDAD
        WHERE   SIG_CUADRO_NECESIDAD_DET.SEC_EJEC           = @al_sec_ejec
        AND     SIG_CUADRO_NECESIDAD_DET.ANO_EJE            = @al_anno_ejec
        AND     SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO        = @al_fase
        AND     SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO       = @ls_cur_centro_costo
        AND     SIG_CUADRO_NECESIDAD_DET.SECUENCIA          = @ll_cur_secuencia
        AND     SIG_CUADRO_NECESIDAD_DET.ESTADO_ITEM_KIT    = 'A'
        AND     SIG_CUADRO_NECESIDAD_DET.SEC_EJEC           = SIG_CUADRO_NECESIDAD.SEC_EJEC
        AND     SIG_CUADRO_NECESIDAD_DET.ANO_EJE            = SIG_CUADRO_NECESIDAD.ANO_EJE
        AND     SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO        = SIG_CUADRO_NECESIDAD.FASE_CUADRO
        AND     SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO       = SIG_CUADRO_NECESIDAD.CENTRO_COSTO
        AND     SIG_CUADRO_NECESIDAD_DET.SECUENCIA          = SIG_CUADRO_NECESIDAD.SECUENCIA
        AND     EXISTS  (
                        SELECT  SIG_CUA_NEC_DET_ID.ANO_EJE
                        FROM    SIG_CUA_NEC_DET_ID
                        WHERE   SIG_CUA_NEC_DET_ID.ANO_EJE      = SIG_CUADRO_NECESIDAD_DET.ANO_EJE
                        AND     SIG_CUA_NEC_DET_ID.SEC_EJEC     = SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
                        AND     SIG_CUA_NEC_DET_ID.CENTRO_COSTO = SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
                        AND     SIG_CUA_NEC_DET_ID.SECUENCIA    = SIG_CUADRO_NECESIDAD_DET.SECUENCIA
                        AND     SIG_CUA_NEC_DET_ID.FASE_CUADRO  = SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
                        AND     SIG_CUA_NEC_DET_ID.ITEM_SEC     = SIG_CUADRO_NECESIDAD_DET.ITEM_SEC
                        AND     SIG_CUA_NEC_DET_ID.TIPO_BIEN    = SIG_CUADRO_NECESIDAD_DET.TIPO_BIEN
                        AND     SIG_CUA_NEC_DET_ID.GRUPO_BIEN   = SIG_CUADRO_NECESIDAD_DET.GRUPO_BIEN
                        AND     SIG_CUA_NEC_DET_ID.CLASE_BIEN   = SIG_CUADRO_NECESIDAD_DET.CLASE_BIEN
                        AND     SIG_CUA_NEC_DET_ID.FAMILIA_BIEN = SIG_CUADRO_NECESIDAD_DET.FAMILIA_BIEN
                        AND     SIG_CUA_NEC_DET_ID.ITEM_BIEN    = SIG_CUADRO_NECESIDAD_DET.ITEM_BIEN
                        AND     SIG_CUA_NEC_DET_ID.TIPO_CALCULO = 4
                        ) 

        --barro el 3er. cursor
        OPEN    lcur_cuadro_necesidad_det 
        WHILE   1 = 1
        BEGIN
            FETCH   lcur_cuadro_necesidad_det
            INTO    @ll_cur_item_sec, @ldc_cur_precio_unit,
                    @ldc_cur_tasa_impto, @ls_cur_tipo_impuesto 
            IF  @@FETCH_STATUS <> 0
            BEGIN
                BREAK 
            END 

            --me chifo los tipo 8 que no tienen ambiente
            IF  @ll_nro_ambiente    = 0
            BEGIN
                SELECT
                @ll_tipo_calculo            = MAX(TIPO_CALCULO)
                FROM    SIG_PPR_CUA_NEC_DET_ID
                WHERE   SEC_EJEC            = @al_sec_ejec
                AND     ANO_EJE             = @al_anno_ejec
                AND     FASE_CUADRO         = @al_fase
                AND     CENTRO_COSTO        = @ls_cur_centro_costo
                AND     SECUENCIA           = @ll_cur_secuencia
                AND     ITEM_SEC            = @ll_cur_item_sec 

                IF  @ll_tipo_calculo = 8
                BEGIN
                    DELETE
                    FROM    SIG_PPR_CUA_NEC_DET_ID
                    WHERE   SEC_EJEC        = @al_sec_ejec
                    AND     ANO_EJE         = @al_anno_ejec
                    AND     FASE_CUADRO     = @al_fase
                    AND     CENTRO_COSTO    = @ls_cur_centro_costo
                    AND     SECUENCIA       = @ll_cur_secuencia
                    AND     ITEM_SEC        = @ll_cur_item_sec
                    AND     TIPO_CALCULO    = 8 

                    DELETE
                    FROM    SIG_PPR_CUADRO_NECESIDAD_DET
                    WHERE   SEC_EJEC        = @al_sec_ejec
                    AND     ANO_EJE         = @al_anno_ejec
                    AND     FASE_CUADRO     = @al_fase
                    AND     CENTRO_COSTO    = @ls_cur_centro_costo
                    AND     SECUENCIA       = @ll_cur_secuencia
                    AND     ITEM_SEC        = @ll_cur_item_sec 
                END 
            END 

            ------------------------------------------
            --declaro 4to. cursor
            ------------------------------------------
            DECLARE lcur_item_stock CURSOR  FOR
            SELECT  ID_KIT, COALESCE(0, 0) AS STOCK
            FROM    SIG_PPR_CUA_NEC_DET_ID
            WHERE   SEC_EJEC        = @al_sec_ejec
            AND     ANO_EJE         = @al_anno_ejec
            AND     FASE_CUADRO     = @al_fase
            AND     CENTRO_COSTO    = @ls_cur_centro_costo
            AND     SECUENCIA       = @ll_cur_secuencia
            AND     ITEM_SEC        = @ll_cur_item_sec 

            --barro el 4to. cursor
            OPEN    lcur_item_stock 
            WHILE   1 = 1
            BEGIN
                FETCH   lcur_item_stock
                INTO    @ll_cur_id_kit, @ldc_cur_stock 
                IF  @@FETCH_STATUS <> 0
                BEGIN
                    BREAK 
                END 

                SELECT
                @ldc_cant_total_ajust           = COALESCE(CANT_KITS, 0)
                FROM    SIG_PPR_KIT_ITEMS_EST
                WHERE   SEC_EJEC                = @al_sec_ejec
                AND     ANO_EJE                 = @al_anno_ejec
                AND     ID_SUB_FINALIDAD        = @ll_cur_id_sub_finalidad
                AND     COD_ESTABLEC            = @ll_cod_establec
                AND     SEC_KIT                 = @ll_cur_id_kit 

                IF  @ldc_cur_cantidad = 0
                BEGIN
                    DELETE
                    FROM    SIG_PPR_CUA_NEC_DET_ID
                    WHERE   SEC_EJEC        = @al_sec_ejec
                    AND     ANO_EJE         = @al_anno_ejec
                    AND     FASE_CUADRO     = @al_fase
                    AND     CENTRO_COSTO    = @ls_cur_centro_costo
                    AND     SECUENCIA       = @ll_cur_secuencia
                    AND     ITEM_SEC        = @ll_cur_item_sec
                    AND     ID_KIT          = @ll_cur_id_kit 
                END 
                ELSE
                BEGIN
		            SELECT  @ldc_cant_total_ajust   = @ldc_cant_total_ajust - @ldc_cur_stock 

		            --PARA ITEMS TIPO CALCULO 4
                    IF  @ldc_cant_total_ajust <= 0
                    BEGIN
                        DELETE
                        FROM    SIG_PPR_CUA_NEC_DET_ID
                        WHERE   SEC_EJEC        = @al_sec_ejec
                        AND     ANO_EJE         = @al_anno_ejec
                        AND     FASE_CUADRO     = @al_fase
                        AND     CENTRO_COSTO    = @ls_cur_centro_costo
                        AND     SECUENCIA       = @ll_cur_secuencia
                        AND     ITEM_SEC        = @ll_cur_item_sec
                        AND     ID_KIT          = @ll_cur_id_kit
                        AND     TIPO_CALCULO    = 4 
                    END
                    ELSE
                    BEGIN
                        UPDATE  SIG_PPR_CUA_NEC_DET_ID
                        SET     CANT_TOTAL      = @ldc_cant_total_ajust
                        WHERE   SEC_EJEC        = @al_sec_ejec
                        AND     ANO_EJE         = @al_anno_ejec
                        AND     FASE_CUADRO     = @al_fase
                        AND     CENTRO_COSTO    = @ls_cur_centro_costo
                        AND     SECUENCIA       = @ll_cur_secuencia
                        AND     ITEM_SEC        = @ll_cur_item_sec
                        AND     ID_KIT          = @ll_cur_id_kit
                        AND     TIPO_CALCULO    = 4 
                    END 

		            --PARA ITEMS TIPO CALCULO 8
                    IF  @ll_nro_ambiente <= 0
                    BEGIN
                        DELETE
                        FROM    SIG_PPR_CUA_NEC_DET_ID
                        WHERE   SEC_EJEC        = @al_sec_ejec
                        AND     ANO_EJE         = @al_anno_ejec
                        AND     FASE_CUADRO     = @al_fase
                        AND     CENTRO_COSTO    = @ls_cur_centro_costo
                        AND     SECUENCIA       = @ll_cur_secuencia
                        AND     ITEM_SEC        = @ll_cur_item_sec
                        AND     ID_KIT          = @ll_cur_id_kit
                        AND     TIPO_CALCULO    = 8 
                    END
                    ELSE
                    BEGIN
                        UPDATE  SIG_PPR_CUA_NEC_DET_ID
                        SET     CANT_TOTAL      = @ldc_cant_total_ajust
                        WHERE   SEC_EJEC        = @al_sec_ejec
                        AND     ANO_EJE         = @al_anno_ejec
                        AND     FASE_CUADRO     = @al_fase
                        AND     CENTRO_COSTO    = @ls_cur_centro_costo
                        AND     SECUENCIA       = @ll_cur_secuencia
                        AND     ITEM_SEC        = @ll_cur_item_sec
                        AND     ID_KIT          = @ll_cur_id_kit
                        AND     TIPO_CALCULO    = 8 
                    END 
                END 
            END 
            CLOSE       lcur_item_stock 
            DEALLOCATE  lcur_item_stock 

            --borro los items activo fijo
            IF  @ldc_cur_cantidad = 0
            BEGIN
                DELETE
                FROM    SIG_PPR_CUADRO_NECESIDAD_DET
                WHERE   SEC_EJEC        = @al_sec_ejec
                AND     ANO_EJE         = @al_anno_ejec
                AND     FASE_CUADRO     = @al_fase
                AND     CENTRO_COSTO    = @ls_cur_centro_costo
                AND     SECUENCIA       = @ll_cur_secuencia
                AND     ITEM_SEC        = @ll_cur_item_sec 
            END 

            SELECT
            @ldc_pcndi_cont                     = COUNT(1),
            @ldc_cantidad_unitaria_sum          = COALESCE(SUM(CANTIDAD_UNITARIA), 0),
            @ldc_cant_total_sum                 = COALESCE(SUM(CANT_TOTAL), 0)
            FROM    SIG_PPR_CUA_NEC_DET_ID
            WHERE   SEC_EJEC                    = @al_sec_ejec
            AND     ANO_EJE                     = @al_anno_ejec
            AND     FASE_CUADRO                 = @al_fase
            AND     CENTRO_COSTO                = @ls_cur_centro_costo
            AND     SECUENCIA                   = @ll_cur_secuencia
            AND     ITEM_SEC                    = @ll_cur_item_sec 

            IF  @ldc_cant_total_sum <= 0
            BEGIN
                DELETE
                FROM    SIG_PPR_CUADRO_NECESIDAD_DET
                WHERE   SEC_EJEC        = @al_sec_ejec
                AND     ANO_EJE         = @al_anno_ejec
                AND     FASE_CUADRO     = @al_fase
                AND     CENTRO_COSTO    = @ls_cur_centro_costo
                AND     SECUENCIA       = @ll_cur_secuencia
                AND     ITEM_SEC        = @ll_cur_item_sec
                AND     ID_KIT          > 0 
            END
            ELSE
            BEGIN
                IF  @ldc_pcndi_cont = 1
                BEGIN
                    SELECT  @ldc_cant_01_ref    = @ldc_cur_cant_01 
                    SELECT  @ldc_cant_02_ref    = @ldc_cur_cant_02 
                    SELECT  @ldc_cant_03_ref    = @ldc_cur_cant_03 
                    SELECT  @ldc_cant_04_ref    = @ldc_cur_cant_04 
                    SELECT  @ldc_cant_05_ref    = @ldc_cur_cant_05 
                    SELECT  @ldc_cant_06_ref    = @ldc_cur_cant_06 
                    SELECT  @ldc_cant_07_ref    = @ldc_cur_cant_07 
                    SELECT  @ldc_cant_08_ref    = @ldc_cur_cant_08 
                    SELECT  @ldc_cant_09_ref    = @ldc_cur_cant_09 
                    SELECT  @ldc_cant_10_ref    = @ldc_cur_cant_10 
                    SELECT  @ldc_cant_11_ref    = @ldc_cur_cant_11 
                    SELECT  @ldc_cant_12_ref    = @ldc_cur_cant_12 
                    SELECT  @ldc_cant_total_ref = @ldc_cur_cantidad 

                    --calculo la distribucion de las cantidades
                    EXEC
                    SP_PPR_CUA_NEC_DET_CALC_CANT
                    @ldc_cant_01_ref            OUTPUT,
                    @ldc_cant_02_ref            OUTPUT,
                    @ldc_cant_03_ref            OUTPUT,
                    @ldc_cant_04_ref            OUTPUT,
                    @ldc_cant_05_ref            OUTPUT,
                    @ldc_cant_06_ref            OUTPUT,
                    @ldc_cant_07_ref            OUTPUT,
                    @ldc_cant_08_ref            OUTPUT,
                    @ldc_cant_09_ref            OUTPUT,
                    @ldc_cant_10_ref            OUTPUT,
                    @ldc_cant_11_ref            OUTPUT,
                    @ldc_cant_12_ref            OUTPUT,
                    @ldc_cant_total_ref         OUTPUT,
                    @ldc_cantidad_unitaria_sum,
                    @ldc_cant_total_sum,
                    @al_error_cod               OUTPUT,
                    @as_error_txt               OUTPUT 
                END
                ELSE
                BEGIN
                    SELECT  @ldc_cant_01_ref    = @ldc_cant_total_sum 
                    SELECT  @ldc_cant_02_ref    = 0 
                    SELECT  @ldc_cant_03_ref    = 0 
                    SELECT  @ldc_cant_04_ref    = 0 
                    SELECT  @ldc_cant_05_ref    = 0 
                    SELECT  @ldc_cant_06_ref    = 0 
                    SELECT  @ldc_cant_07_ref    = 0 
                    SELECT  @ldc_cant_08_ref    = 0 
                    SELECT  @ldc_cant_09_ref    = 0 
                    SELECT  @ldc_cant_10_ref    = 0 
                    SELECT  @ldc_cant_11_ref    = 0 
                    SELECT  @ldc_cant_12_ref    = 0 
                    SELECT  @ldc_cant_total_ref = @ldc_cant_total_sum 
                END 

                SELECT  @ldc_mnto_01_ref        = 0 
                SELECT  @ldc_mnto_02_ref        = 0 
                SELECT  @ldc_mnto_03_ref        = 0 
                SELECT  @ldc_mnto_04_ref        = 0 
                SELECT  @ldc_mnto_05_ref        = 0 
                SELECT  @ldc_mnto_06_ref        = 0 
                SELECT  @ldc_mnto_07_ref        = 0 
                SELECT  @ldc_mnto_08_ref        = 0 
                SELECT  @ldc_mnto_09_ref        = 0 
                SELECT  @ldc_mnto_10_ref        = 0 
                SELECT  @ldc_mnto_11_ref        = 0 
                SELECT  @ldc_mnto_12_ref        = 0 
                SELECT  @ldc_mnto_total_ref     = 0 
                SELECT  @ldc_valor_impto_ref    = 0 

                EXEC
                SP_PPR_CUA_NEC_DET_CALC_MONT
                @ldc_cant_01_ref,
                @ldc_cant_02_ref,
                @ldc_cant_03_ref,
                @ldc_cant_04_ref,
                @ldc_cant_05_ref,
                @ldc_cant_06_ref,
                @ldc_cant_07_ref,
                @ldc_cant_08_ref,
                @ldc_cant_09_ref,
                @ldc_cant_10_ref,
                @ldc_cant_11_ref,
                @ldc_cant_12_ref,
                @ldc_cur_precio_unit,
                @ls_cur_tipo_impuesto,
                @ldc_cur_tasa_impto,
                @ldc_mnto_01_ref        OUTPUT,
                @ldc_mnto_02_ref        OUTPUT,
                @ldc_mnto_03_ref        OUTPUT,
                @ldc_mnto_04_ref        OUTPUT,
                @ldc_mnto_05_ref        OUTPUT,
                @ldc_mnto_06_ref        OUTPUT,
                @ldc_mnto_07_ref        OUTPUT,
                @ldc_mnto_08_ref        OUTPUT,
                @ldc_mnto_09_ref        OUTPUT,
                @ldc_mnto_10_ref        OUTPUT,
                @ldc_mnto_11_ref        OUTPUT,
                @ldc_mnto_12_ref        OUTPUT,
                @ldc_mnto_total_ref     OUTPUT,
                @ldc_valor_impto_ref    OUTPUT 

                --actualiza el detalle del cuadro de necesidades
                UPDATE  SIG_PPR_CUADRO_NECESIDAD_DET
                SET     CANT_01         = @ldc_cant_01_ref,
                        CANT_02         = @ldc_cant_02_ref,
                        CANT_03         = @ldc_cant_03_ref,
                        CANT_04         = @ldc_cant_04_ref,
                        CANT_05         = @ldc_cant_05_ref,
                        CANT_06         = @ldc_cant_06_ref,
                        CANT_07         = @ldc_cant_07_ref,
                        CANT_08         = @ldc_cant_08_ref,
                        CANT_09         = @ldc_cant_09_ref,
                        CANT_10         = @ldc_cant_10_ref,
                        CANT_11         = @ldc_cant_11_ref,
                        CANT_12         = @ldc_cant_12_ref,
                        CANT_TOTAL      = @ldc_cant_total_ref,
                        MNTO_01         = @ldc_mnto_01_ref,
                        MNTO_02         = @ldc_mnto_02_ref,
                        MNTO_03         = @ldc_mnto_03_ref,
                        MNTO_04         = @ldc_mnto_04_ref,
                        MNTO_05         = @ldc_mnto_05_ref,
                        MNTO_06         = @ldc_mnto_06_ref,
                        MNTO_07         = @ldc_mnto_07_ref,
                        MNTO_08         = @ldc_mnto_08_ref,
                        MNTO_09         = @ldc_mnto_09_ref,
                        MNTO_10         = @ldc_mnto_10_ref,
                        MNTO_11         = @ldc_mnto_11_ref,
                        MNTO_12         = @ldc_mnto_12_ref,
                        MNTO_TOTAL      = @ldc_mnto_total_ref,
                        VALOR_IMPTO     = @ldc_valor_impto_ref
                WHERE   SEC_EJEC        = @al_sec_ejec
                AND     ANO_EJE         = @al_anno_ejec
                AND     FASE_CUADRO     = @al_fase
                AND     CENTRO_COSTO    = @ls_cur_centro_costo
                AND     SECUENCIA       = @ll_cur_secuencia
                AND     ITEM_SEC        = @ll_cur_item_sec 
            END 
        END 
        CLOSE       lcur_cuadro_necesidad_det 
        DEALLOCATE  lcur_cuadro_necesidad_det 

        --actualizo los montos totales del cuadro de necesidades
        SELECT
        @ldc_monto              = COALESCE(SUM(MNTO_TOTAL), 0),
        @ldc_valor_imp          = COALESCE(SUM(VALOR_IMPTO), 0)
        FROM    SIG_PPR_CUADRO_NECESIDAD_DET
        WHERE   SEC_EJEC        = @al_sec_ejec
        AND     ANO_EJE         = @al_anno_ejec
        AND     FASE_CUADRO     = @al_fase
        AND     CENTRO_COSTO    = @ls_cur_centro_costo
        AND     SECUENCIA       = @ll_cur_secuencia 

        IF  @al_fase    = 1
        BEGIN
            UPDATE  SIG_PPR_CUADRO_NECESIDAD
            SET     MONTO_PROGRA        = @ldc_monto,
                    VALOR_IMP_PROGRA    = @ldc_valor_imp,
                    TOTAL_PROGRA        = (@ldc_monto + @ldc_valor_imp)
            WHERE   SEC_EJEC            = @al_sec_ejec
            AND     ANO_EJE             = @al_anno_ejec
            AND     FASE_CUADRO         = @al_fase
            AND     CENTRO_COSTO        = @ls_cur_centro_costo
            AND     SECUENCIA           = @ll_cur_secuencia 
        END
        ELSE    IF  @al_fase    IN  (2, 3, 4)
        BEGIN
            UPDATE  SIG_PPR_CUADRO_NECESIDAD
            SET     MONTO_ASIGNADO      = @ldc_monto,
                    VALOR_IMP_ASIGNADO  = @ldc_valor_imp,
                    TOTAL_ASIGNADO      = (@ldc_monto + @ldc_valor_imp)
            WHERE   SEC_EJEC            = @al_sec_ejec
            AND     ANO_EJE             = @al_anno_ejec
            AND     FASE_CUADRO         = @al_fase
            AND     CENTRO_COSTO        = @ls_cur_centro_costo
            AND     SECUENCIA           = @ll_cur_secuencia 
        END
        ELSE    IF  @al_fase    = 5
        BEGIN
            UPDATE  SIG_PPR_CUADRO_NECESIDAD
            SET     MONTO_APROB     = @ldc_monto,
                    VALOR_IMP_APROB = @ldc_valor_imp,
                    TOTAL_APROB     = (@ldc_monto + @ldc_valor_imp)
            WHERE   SEC_EJEC        = @al_sec_ejec
            AND     ANO_EJE         = @al_anno_ejec
            AND     FASE_CUADRO     = @al_fase
            AND     CENTRO_COSTO    = @ls_cur_centro_costo
            AND     SECUENCIA       = @ll_cur_secuencia 
        END 
    END 
    CLOSE       lcur_cuadro_necesidad 
    DEALLOCATE  lcur_cuadro_necesidad 
END 
