FROM sig_cuadro_necesidad C ,  
     sig_cuadro_necesidad_Det D,  
     #TMP_SIG_PAAC_ITEM i       
WHERE  I.ANO_EJE=D.ANO_EJE AND I.SEC_EJEC=D.SEC_EJEC AND i.item_bien = d.item_bien and i.grupo_bien = d.grupo_bien and i.clase_bien = d.clase_bien and i.familia_bien = d.familia_bien and i.item_bien = d.item_bien and  
     I.NRO_CONSOLID = @PN_NRO_PAO and   
    (C.ANO_EJE = @PN_ANIO ) And    
    (C.SEC_EJEC  = @PN_EJECUTORA ) And    
    ( D.TIPO_BIEN  = @PS_TIPO ) and   
 	( D.ESTADO     = '5' ) and      
     EXISTS(select FUENTE from tmp_parametros_pao  where CODIGO = 3 and NRO_PAO = @PN_NRO_PAO AND Fuente = C.FUENTE_FINANC) AND    
 
    EXISTS (select CLASIFICADOR from tmp_parametros_pao where CODIGO = 2 and NRO_PAO = @PN_NRO_PAO AND CLASIFICADOR = C.CLASIFICADOR) AND 
 
  	EXISTS (select SEC_FUNC from tmp_parametros_pao where CODIGO = 4 and NRO_PAO = @PN_NRO_PAO AND SEC_FUNC = C.SEC_FUNC) AND
 
    EXISTS(select CENTRO_COSTO from tmp_parametros_pao where CODIGO = 5 and NRO_PAO = @PN_NRO_PAO AND  centro_costo = D.CENTRO_COSTO  )   AND
   
    exists( select '1' from tmp_parametros_pao  
 where CODIGO = 6 and NRO_PAO = @PN_NRO_PAO and  
 c.tipo_uso = tipo_uso and  
 c.tipo_tarea = tipo_tarea and  
 c.nivel_tarea = nivel_tarea and  
 c.codigo_tarea = codigo_tarea and
 TIPO_USO = C.TIPO_USO) and  
  
    ( (D.FASE_CUADRO = 3 and @PN_ANIO <= 2011) or (D.FASE_CUADRO = 5 and @PN_ANIO >= 2012) ) and     
    ( EXISTS (select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND
	      			ITEM= ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN))  OR
	  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN ) ) OR
	  EXISTS(select ITEM from tmp_parametros_pao where CODIGO = 1 and NRO_PAO = @PN_NRO_PAO AND ITEM =  (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN  ) ) 			      			
       ) AND     
    ( D.ano_eje    = C.ano_eje ) and  
    ( D.sec_ejec     = C.sec_ejec ) and  
    ( D.centro_costo = C.centro_costo ) and  
    ( D.FASE_CUADRO   = C.FASE_CUADRO ) and   
    ( D.secuencia    = C.secuencia ) and   
	/*  
   ( D.mnto_total   > 0 ) AND
   */
   (COALESCE(D.MNTO_TOTAL, 0) + COALESCE(D.MNTO_TOTAL_ANNO_01, 0) + COALESCE(D.MNTO_TOTAL_ANNO_02, 0) + COALESCE(D.MNTO_TOTAL_ANNO_03, 0)) > 0 and
    ( D.estado_item_kit = 'A' ) and
EXISTS(SELECT '1' FROM TMP_PARAMETROS_PAO AA  
    WHERE   
    AA.CODIGO = 1 AND   
    AA.NRO_PAO = @PN_NRO_PAO AND  
    AA.CENTRO_COSTO = D.CENTRO_COSTO AND   
    AA.SECUENCIA_CN = D.SECUENCIA AND  
    AA.ITEM_SEC_CN = D.ITEM_SEC AND  
    ( D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN = AA.ITEM ) )        
GROUP BY C.sec_func ,  
         C.origen ,  
         C.fuente_financ ,  
         C.clasificador ,  
         C.tipo_impuesto ,  
         C.tasa_impto ,  
         case when C.fuente_impto is null or RTRIM(LTRIM(C.fuente_impto)) = '' then null else  C.fuente_impto end,  
         sec_resumen1
  
DECLARE @SEC_RESUMEN numeric(5, 0), @SEC_META1 numeric(5, 0), @NUM INT, @SEC_RESUMEN_ANT numeric(5, 0)  
DECLARE CUR_META CURSOR FOR  
SELECT SEC_RESUMEN, SEC_META1 FROM #TMP_SIG_PAAC_METAS WHERE SEC_RESUMEN IN (SELECT SEC_RESUMEN FROM #TMP_SIG_PAAC_METAS GROUP BY SEC_RESUMEN HAVING COUNT(*) > 1) ORDER BY SEC_RESUMEN  
   
OPEN CUR_META  
FETCH CUR_META INTO @SEC_RESUMEN, @SEC_META1  
WHILE @@FETCH_STATUS = 0  
BEGIN  
   SELECT @NUM = 1  
   SELECT @SEC_RESUMEN_ANT = @SEC_RESUMEN  
   WHILE @@FETCH_STATUS = 0 AND @SEC_RESUMEN_ANT = @SEC_RESUMEN  
   BEGIN  
      UPDATE #TMP_SIG_PAAC_METAS SET SEC_META = @NUM WHERE SEC_META1 = @SEC_META1  
      SELECT @NUM = @NUM + 1  
      FETCH CUR_META INTO @SEC_RESUMEN, @SEC_META1  
   END  
END  
CLOSE CUR_META  
DEALLOCATE CUR_META  
   
UPDATE #TMP_SIG_PAAC_METAS SET SEC_META = 1 WHERE SEC_META IS NULL  
  
