					    			  WHEN 3 THEN MES_08_ANNO_02 
					    			  WHEN 4 THEN MES_08_ANNO_03 ELSE 0 END AS MES_08,	    			  
				   CASE @li_secu_cons WHEN 1 THEN MES_09   
