					    			  WHEN 3 THEN MES_10_ANNO_02 
					    			  WHEN 4 THEN MES_10_ANNO_03 ELSE 0 END AS MES_10,	
	   			   CASE @li_secu_cons WHEN 1 THEN MES_11  
