	  CENTRO_COSTO, FECHA_REG,   CUSER_ID,   NIVEL_TAREA,  
 TIPO_USO, MAYOR, SUB_CTA_DET  
 FROM #TMP_SIG_PAAC_CENTRO_COSTO  
   
IF @@ERROR <> 0  
   GOTO ERROR  
 
 	UPDATE SIG_PAAC_CENTRO_COSTO
	SET FLAG_MES_01 = (
			CASE COALESCE(MES_01, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_02 = (
			CASE COALESCE(MES_02, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_03 = (
			CASE COALESCE(MES_03, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_04 = (
			CASE COALESCE(MES_04, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_05 = (
			CASE COALESCE(MES_05, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_06 = (
			CASE COALESCE(MES_06, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_07 = (
			CASE COALESCE(MES_07, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_08 = (
			CASE COALESCE(MES_08, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_09 = (
			CASE COALESCE(MES_09, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_10 = (
			CASE COALESCE(MES_10, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_11 = (
			CASE COALESCE(MES_11, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
		,FLAG_MES_12 = (
			CASE COALESCE(MES_12, 0)
				WHEN 0
					THEN '0'
				ELSE '1'
				END
			)
	WHERE EXISTS (
			SELECT 1
			FROM #TMP_SIG_PAAC_CENTRO_COSTO TAB_TEMPORAL
			WHERE TAB_TEMPORAL.ANO_EJE = SIG_PAAC_CENTRO_COSTO.ANO_EJE
				AND TAB_TEMPORAL.SEC_EJEC = SIG_PAAC_CENTRO_COSTO.SEC_EJEC
				AND TAB_TEMPORAL.TIPO_CONSOLID = SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID
				AND TAB_TEMPORAL.NRO_CONSOLID = SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID
				AND TAB_TEMPORAL.TIPO_GENERACION = SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION
				AND TAB_TEMPORAL.TIPO_BIEN = SIG_PAAC_CENTRO_COSTO.TIPO_BIEN
				AND TAB_TEMPORAL.SEC_CONSOLID = SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID
				AND TAB_TEMPORAL.SEC_RESUMEN = SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN
				AND TAB_TEMPORAL.SEC_META = SIG_PAAC_CENTRO_COSTO.SEC_META
				AND TAB_TEMPORAL.SEC_CTRO_COSTO = SIG_PAAC_CENTRO_COSTO.SEC_CTRO_COSTO
			)


	IF @@ERROR <> 0
		GOTO ERROR

	SET @li_secu_cons = @li_secu_cons + 1
	SET @li_cont = @li_cont + 1   
	  
END 	
									   
DELETE SIG_PAAC_CENTRO_COSTO
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND CANTIDAD = 0
	AND EXISTS (
		SELECT 1
		FROM SIG_PAAC_METAS
			,SIG_PAAC_ITEM
			,SIG_CUADRO_NECESIDAD
			,SIG_CUADRO_NECESIDAD_DET
		WHERE SIG_PAAC_CENTRO_COSTO.SEC_EJEC = SIG_PAAC_METAS.SEC_EJEC
			AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = SIG_PAAC_METAS.ANO_EJE
			AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = SIG_PAAC_METAS.TIPO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID = SIG_PAAC_METAS.NRO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION = SIG_PAAC_METAS.TIPO_GENERACION
			AND SIG_PAAC_CENTRO_COSTO.TIPO_BIEN = SIG_PAAC_METAS.TIPO_BIEN
			AND SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID = SIG_PAAC_METAS.SEC_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN = SIG_PAAC_METAS.SEC_RESUMEN
			AND SIG_PAAC_CENTRO_COSTO.SEC_META = SIG_PAAC_METAS.SEC_META
			AND SIG_PAAC_CENTRO_COSTO.SEC_EJEC = SIG_PAAC_ITEM.SEC_EJEC
			AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = SIG_PAAC_ITEM.ANO_EJE
			AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = SIG_PAAC_ITEM.TIPO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID = SIG_PAAC_ITEM.NRO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION = SIG_PAAC_ITEM.TIPO_GENERACION
			AND SIG_PAAC_CENTRO_COSTO.TIPO_BIEN = SIG_PAAC_ITEM.TIPO_BIEN
			AND SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID = SIG_PAAC_ITEM.SEC_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN = SIG_PAAC_ITEM.SEC_RESUMEN
			AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = 1
			AND SIG_CUADRO_NECESIDAD.SEC_EJEC = SIG_PAAC_CENTRO_COSTO.SEC_EJEC
			AND SIG_CUADRO_NECESIDAD.ANO_EJE = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND SIG_CUADRO_NECESIDAD.CENTRO_COSTO = SIG_PAAC_CENTRO_COSTO.CENTRO_COSTO
			AND SIG_CUADRO_NECESIDAD.FASE_CUADRO = 5
			AND SIG_CUADRO_NECESIDAD.SEC_FUNC = SIG_PAAC_METAS.SEC_FUNC
			AND SIG_CUADRO_NECESIDAD.CLASIFICADOR = SIG_PAAC_METAS.CLASIFICADOR
			AND SIG_CUADRO_NECESIDAD.ORIGEN = SIG_PAAC_METAS.ORIGEN
			AND SIG_CUADRO_NECESIDAD.FUENTE_FINANC = SIG_PAAC_METAS.FUENTE_FINANC
			AND SIG_CUADRO_NECESIDAD.NIVEL_TAREA = SIG_PAAC_CENTRO_COSTO.NIVEL_TAREA
			AND SIG_CUADRO_NECESIDAD.CODIGO_TAREA = SIG_PAAC_CENTRO_COSTO.CODIGO_TAREA
			AND SIG_CUADRO_NECESIDAD.SEC_EJEC = SIG_CUADRO_NECESIDAD_DET.SEC_EJEC
			AND SIG_CUADRO_NECESIDAD.ANO_EJE = SIG_CUADRO_NECESIDAD_DET.ANO_EJE
			AND SIG_CUADRO_NECESIDAD.CENTRO_COSTO = SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO
			AND SIG_CUADRO_NECESIDAD.SECUENCIA = SIG_CUADRO_NECESIDAD_DET.SECUENCIA
			AND SIG_CUADRO_NECESIDAD.FASE_CUADRO = SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO
			AND SIG_PAAC_ITEM.TIPO_BIEN = SIG_CUADRO_NECESIDAD_DET.TIPO_BIEN
			AND SIG_PAAC_ITEM.GRUPO_BIEN = SIG_CUADRO_NECESIDAD_DET.GRUPO_BIEN
			AND SIG_PAAC_ITEM.CLASE_BIEN = SIG_CUADRO_NECESIDAD_DET.CLASE_BIEN
			AND SIG_PAAC_ITEM.FAMILIA_BIEN = SIG_CUADRO_NECESIDAD_DET.FAMILIA_BIEN
			AND SIG_PAAC_ITEM.ITEM_BIEN = SIG_CUADRO_NECESIDAD_DET.ITEM_BIEN
			AND COALESCE((
					CASE SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID
						WHEN 1
							THEN SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL
						WHEN 2
							THEN SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL_ANNO_01
						WHEN 3
							THEN SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL_ANNO_02
						WHEN 4
							THEN SIG_CUADRO_NECESIDAD_DET.MNTO_TOTAL_ANNO_03
						ELSE 0
						END
					), 0) = 0
		)

IF @@ERROR <> 0
	GOTO ERROR 
   
DELETE SIG_PAAC_METAS
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND CANTIDAD = 0
	AND NOT EXISTS (
		/* fact */
		SELECT 1
		FROM SIG_PAAC_CENTRO_COSTO
		WHERE SIG_PAAC_CENTRO_COSTO.SEC_EJEC = SIG_PAAC_METAS.SEC_EJEC
			AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = SIG_PAAC_METAS.ANO_EJE
			AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = SIG_PAAC_METAS.TIPO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID = SIG_PAAC_METAS.NRO_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION = SIG_PAAC_METAS.TIPO_GENERACION
			AND SIG_PAAC_CENTRO_COSTO.TIPO_BIEN = SIG_PAAC_METAS.TIPO_BIEN
			AND SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID = SIG_PAAC_METAS.SEC_CONSOLID
			AND SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN = SIG_PAAC_METAS.SEC_RESUMEN
			AND SIG_PAAC_CENTRO_COSTO.SEC_META = SIG_PAAC_METAS.SEC_META
		) 
   
IF @@ERROR <> 0  
   GOTO ERROR  
   
DELETE SIG_PAAC_ITEM
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND CANTIDAD = 0
	AND NOT EXISTS (
		/* fact */
		SELECT 1
		FROM SIG_PAAC_METAS
		WHERE SIG_PAAC_METAS.SEC_EJEC = SIG_PAAC_ITEM.SEC_EJEC
			AND SIG_PAAC_METAS.ANO_EJE = SIG_PAAC_ITEM.ANO_EJE
			AND SIG_PAAC_METAS.TIPO_CONSOLID = SIG_PAAC_ITEM.TIPO_CONSOLID
			AND SIG_PAAC_METAS.NRO_CONSOLID = SIG_PAAC_ITEM.NRO_CONSOLID
			AND SIG_PAAC_METAS.TIPO_GENERACION = SIG_PAAC_ITEM.TIPO_GENERACION
			AND SIG_PAAC_METAS.TIPO_BIEN = SIG_PAAC_ITEM.TIPO_BIEN
			AND SIG_PAAC_METAS.SEC_CONSOLID = SIG_PAAC_ITEM.SEC_CONSOLID
			AND SIG_PAAC_METAS.SEC_RESUMEN = SIG_PAAC_ITEM.SEC_RESUMEN
		)  
   
IF @@ERROR <> 0  
   GOTO ERROR  
   
                                DELETE SIG_PAAC_SECUENCIA
		 WHERE ANO_EJE 			= @PN_ANIO AND 
			   SEC_EJEC 		= @PN_EJECUTORA AND 
			   TIPO_CONSOLID 	= '1' AND 
			   NRO_CONSOLID  	= @PN_NRO_PAO AND 
			   TIPO_GENERACION 	= @ps_tipo_generacion AND 	
			   TIPO_BIEN 		= @PS_TIPO AND 		
			   NOT EXISTS ( SELECT 1   FROM SIG_PAAC_ITEM I
				             WHERE I.ano_eje          = SIG_PAAC_SECUENCIA.ANO_EJE AND
				                   I.sec_ejec         = SIG_PAAC_SECUENCIA.SEC_EJEC AND
				                   I.tipo_consolid    = SIG_PAAC_SECUENCIA.TIPO_CONSOLID AND
				                   I.nro_consolid     = SIG_PAAC_SECUENCIA.NRO_CONSOLID AND
				                   I.TIPO_GENERACION  = SIG_PAAC_SECUENCIA.TIPO_GENERACION AND
				                   I.TIPO_BIEN        = SIG_PAAC_SECUENCIA.TIPO_BIEN AND 
				                   I.SEC_CONSOLID 	  =  SIG_PAAC_SECUENCIA.SEC_CONSOLID  )
							
		IF @@ERROR <> 0    
		   GOTO ERROR  	    
				
			UPDATE  SIG_PAAC_ITEM
			SET         SIG_PAAC_ITEM.PRECIO_UNIT = D.PRECIO_UNIT , SIG_PAAC_ITEM.PRECIO_MONEDA = D.PRECIO_UNIT
			FROM 
			SIG_PAAC_METAS,
			SIG_PAAC_ITEM I,
			SIG_CUADRO_NECESIDAD,
			SIG_CUADRO_NECESIDAD_DET D,
			SIG_PAAC_CENTRO_COSTO
			WHERE   
			
			SIG_PAAC_CENTRO_COSTO.SEC_EJEC           = SIG_PAAC_METAS.SEC_EJEC           
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = SIG_PAAC_METAS.ANO_EJE  
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = SIG_PAAC_METAS.TIPO_CONSOLID      
			AND     SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID       = SIG_PAAC_METAS.NRO_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION    = SIG_PAAC_METAS.TIPO_GENERACION    
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_BIEN          = SIG_PAAC_METAS.TIPO_BIEN          
			AND     SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID       = SIG_PAAC_METAS.SEC_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN        = SIG_PAAC_METAS.SEC_RESUMEN        
			AND     SIG_PAAC_CENTRO_COSTO.SEC_META           = SIG_PAAC_METAS.SEC_META           
			AND     SIG_PAAC_CENTRO_COSTO.SEC_EJEC           = I.SEC_EJEC           
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = I.ANO_EJE  
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = I.TIPO_CONSOLID      
			AND     SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID       = I.NRO_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION    = I.TIPO_GENERACION    
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_BIEN          = I.TIPO_BIEN          
			AND     SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID       = I.SEC_CONSOLID       
			AND     SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN        = I.SEC_RESUMEN    
			AND     SIG_PAAC_CENTRO_COSTO.ANO_EJE            = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND     SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID      = 1
			AND     SIG_CUADRO_NECESIDAD.SEC_EJEC      = SIG_PAAC_CENTRO_COSTO.SEC_EJEC           
			AND     SIG_CUADRO_NECESIDAD.ANO_EJE       = SIG_PAAC_CENTRO_COSTO.ANO_EJE
			AND     SIG_CUADRO_NECESIDAD.CENTRO_COSTO  = SIG_PAAC_CENTRO_COSTO.CENTRO_COSTO  
			
			AND     SIG_CUADRO_NECESIDAD.FASE_CUADRO   = 5
			AND     SIG_CUADRO_NECESIDAD.SEC_FUNC      = SIG_PAAC_METAS.SEC_FUNC
			AND     SIG_CUADRO_NECESIDAD.CLASIFICADOR  = SIG_PAAC_METAS.CLASIFICADOR
			AND     SIG_CUADRO_NECESIDAD.ORIGEN        = SIG_PAAC_METAS.ORIGEN
			AND     SIG_CUADRO_NECESIDAD.FUENTE_FINANC = SIG_PAAC_METAS.FUENTE_FINANC
			
			AND     SIG_CUADRO_NECESIDAD.NIVEL_TAREA   = SIG_PAAC_CENTRO_COSTO.NIVEL_TAREA	
			AND     SIG_CUADRO_NECESIDAD.CODIGO_TAREA  = SIG_PAAC_CENTRO_COSTO.CODIGO_TAREA
			
			AND     SIG_CUADRO_NECESIDAD.SEC_EJEC      = D.SEC_EJEC      
			AND     SIG_CUADRO_NECESIDAD.ANO_EJE       = D.ANO_EJE       
			AND     SIG_CUADRO_NECESIDAD.CENTRO_COSTO  = D.CENTRO_COSTO  
			AND     SIG_CUADRO_NECESIDAD.SECUENCIA     = D.SECUENCIA    
			AND     SIG_CUADRO_NECESIDAD.FASE_CUADRO   = D.FASE_CUADRO
			AND     I.TIPO_BIEN    = D.TIPO_BIEN
			AND     I.GRUPO_BIEN   = D.GRUPO_BIEN
			AND     I.CLASE_BIEN   = D.CLASE_BIEN
			AND     I.FAMILIA_BIEN = D.FAMILIA_BIEN
			AND     I.ITEM_BIEN	= D.ITEM_BIEN
			
			AND     I.ANO_EJE = @PN_ANIO     
			AND     I.SEC_EJEC = @PN_EJECUTORA     
			AND     I.TIPO_CONSOLID = '1'     
			AND     I.NRO_CONSOLID = @PN_NRO_PAO   
			AND     I.TIPO_GENERACION = @ps_tipo_generacion
	
			IF @@ERROR <> 0    
				GOTO ERROR  
   
