CREATE PROCEDURE [dbo].[SP_REPORTE_PAAC_CONSUCODE_OSCE]
(@PN_ANIO NUMERIC, @PN_EJECUTORA NUMERIC, @ps_tipo_CONSOLID varchar(1),
@ps_tipo_generacion varchar(1),@PN_REPORTE NUMERIC )
 
AS

/*
Modificaciones SP

- Versión: 24.03.00     - SRF   - Modificado por: MPalacios     - Fecha: 02/10/2024     - Ajuste: Ampliación del campo NRO_PAAC y cálculo de máximo valor
- Versión: 25.02.01     - SRF	- Modificado por: MPalacios		- Fecha: 20/01/2026     - Ajuste: Incorporación de los nuevos tipos de PS creados en el año 2025 (incidencia - Issue 1118)
*/

DECLARE @CANO_EJE numeric(4, 0)
DECLARE @CSEC_EJEC numeric(6, 0)
DECLARE @CTIPO_CONSOLID char(1)
