     INSERT INTO tmp_techo_fase_7
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,
                  funcion, programa, sec_func_prop, centro_costo_presup, clasificador)
          SELECT DISTINCT
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,
                 b.funcion, b.programa, b.sec_func_prop, b.centro_costo_presup, b.clasificador
            FROM sig_techo_presupuesto b
           WHERE b.ano_eje     = @PN_ANIO and
                 b.sec_ejec    = @PN_EJEC and
                 b.fase_cuadro = @PN_FASE and
                 b.indicador   = '0'      and
                 b.flag_meta_aprob = '0'  and
                 not exists (SELECT '1'
                               FROM sig_techo_presupuesto c
                              WHERE c.ano_eje     = b.ano_eje  and
                                    c.sec_ejec    = b.sec_ejec and
                                    c.fase_cuadro = @PN_FASE   and
                                    c.origen      = b.origen   and
                                    c.fuente_financ = b.fuente_financ and
                                    c.categ_gasto   = b.categ_gasto   and
                                    c.grupo_gasto   = b.grupo_gasto   and
                                    c.sec_func_prop = b.sec_func_prop and
                                    c.centro_costo_presup = b.centro_costo_presup and
                                    c.clasificador    = b.clasificador and
                                    c.indicador       = '5' and
                                    c.flag_meta_aprob = '0')
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     SELECT @li_secuencia = IsNull(MAX(secuencia), 0)
       FROM sig_techo_presupuesto
      WHERE ano_eje  = @PN_ANIO and
            sec_ejec = @PN_EJEC
     
     INSERT INTO sig_techo_presupuesto
                 (ano_eje    , sec_ejec    , origen      , fuente_financ, secuencia    ,
                  categ_gasto, grupo_gasto , clasificador, funcion      , programa     ,
                  sec_func   , centro_costo, ppto_progra , ppto_aprob   , ppto_asignado,
                  ppto_modif , mnto_progra , mnto_asig   , mnto_aprob   , mnto_modif   ,
                  indicador  , paac_inicial, paac_modif  , porc_techo   , porc_asig    ,
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)
          SELECT @PN_ANIO, @PN_EJEC, origen , fuente_financ, (@li_secuencia + secuencia),
                 categ_gasto, grupo_gasto, clasificador, funcion, programa, NULL, NULL,
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '5', 0, 0, 0,
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE
            FROM tmp_techo_fase_7
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     UPDATE sig_techo_presupuesto
        SET mnto_asig = (SELECT SUM(A.mnto_asig)
                           FROM sig_techo_presupuesto A
                          WHERE A.ano_eje     = @PN_ANIO and
                                A.sec_ejec    = @PN_EJEC and
                                A.fase_cuadro = @PN_FASE and
                                A.origen      = sig_techo_presupuesto.origen and
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and
                                A.clasificador  =  sig_techo_presupuesto.clasificador and
                                A.indicador       = '0' and
                                A.flag_meta_aprob = '0')
      WHERE ano_eje     = @PN_ANIO and
            sec_ejec    = @PN_EJEC and
            fase_cuadro = @PN_FASE and
            indicador   = '5'      and
            flag_meta_aprob = '0'
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     INSERT INTO tmp_techo_fase_8
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,
                  funcion, programa, sec_func_prop, centro_costo_presup)
          SELECT DISTINCT
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,
                 b.funcion, b.programa, b.sec_func_prop, b.centro_costo_presup
            FROM sig_techo_presupuesto b
           WHERE b.ano_eje     = @PN_ANIO and
                 b.sec_ejec    = @PN_EJEC and
                 b.fase_cuadro = @PN_FASE and
                 b.indicador   = '0'      and
                 b.flag_meta_aprob = '0'  and
                 not exists (SELECT '1'
                               FROM sig_techo_presupuesto c
                              WHERE c.ano_eje     = b.ano_eje  and
                     c.sec_ejec    = b.sec_ejec and
                                    c.fase_cuadro = @PN_FASE   and
                                    c.origen      = b.origen   and
                                    c.fuente_financ = b.fuente_financ and
                                    c.categ_gasto   = b.categ_gasto   and
                                    c.grupo_gasto   = b.grupo_gasto   and
                                    c.sec_func_prop = b.sec_func_prop and
                                    c.centro_costo_presup = b.centro_costo_presup and
                                    c.indicador       = '4' and
                                    c.flag_meta_aprob = '0')
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     SELECT @li_secuencia = max(secuencia) 
       FROM sig_techo_presupuesto 
      WHERE ano_eje  = @PN_ANIO and
            sec_ejec = @PN_EJEC
     
     INSERT INTO sig_techo_presupuesto
                 (ano_eje      , sec_ejec       , origen      , fuente_financ, secuencia    ,
                  categ_gasto  , grupo_gasto    , clasificador, funcion      , programa     ,
                  sec_func     , centro_costo   , ppto_progra , ppto_aprob   , ppto_asignado,
                  ppto_modif   , mnto_progra    , mnto_asig   , mnto_aprob   , mnto_modif   ,
                  indicador    , paac_inicial   , paac_modif  , porc_techo   , porc_asig    ,
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)
          SELECT @PN_ANIO, @PN_EJEC, origen, fuente_financ, (@li_secuencia + secuencia),
                 categ_gasto, grupo_gasto, NULL, funcion, programa, NULL, NULL,
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '4', 0, 0, 0,
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE
            FROM tmp_techo_fase_8
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     UPDATE sig_techo_presupuesto
        SET mnto_asig = (SELECT SUM(A.mnto_asig)
                           FROM sig_techo_PRESUPUESTO A
                          WHERE A.ano_eje     = @PN_ANIO and
                                A.sec_ejec    = @PN_EJEC and
                                A.fase_cuadro = @PN_FASE and
                                A.origen      = sig_techo_presupuesto.origen and
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and
                                A.indicador       = '0' and
                                A.flag_meta_aprob = '0')
      WHERE ano_eje     = @PN_ANIO and
            sec_ejec    = @PN_EJEC and
            fase_cuadro = @PN_FASE and
            indicador   = '4'      and
            flag_meta_aprob = '0'
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
END

TRUNCATE TABLE dbo.tmp_techo_cn_fase 
TRUNCATE TABLE dbo.tmp_propuesta_fase 
TRUNCATE TABLE dbo.tmp_techo_fase_2 
TRUNCATE TABLE dbo.tmp_techo_fase_3
TRUNCATE TABLE dbo.tmp_techo_fase_4
TRUNCATE TABLE dbo.tmp_techo_fase_5
TRUNCATE TABLE dbo.tmp_techo_fase_6
TRUNCATE TABLE dbo.tmp_techo_fase_7
TRUNCATE TABLE dbo.tmp_techo_fase_8

RETURN 1
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_PATRIMONIO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_PATRIMONIO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_PATRIMONIO]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_PATRIMONIO]
    @P_ANO_EJE               NUMERIC(4,0),
    @P_SEC_EJC               VARCHAR(10),
    @fecha_carga_inicio     VARCHAR(10),
    @fecha_carga_fin        VARCHAR(10),
    @usuario_n              VARCHAR(30),
    @O_ERR_NUM               NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG               VARCHAR(255) OUTPUT   
AS
DECLARE @LD_FECHA_INI            DATETIME
DECLARE @LD_FECHA_FIN            DATETIME
DECLARE @LN_ID_SI_PEDIDO        NUMERIC(10,0)
DECLARE @LN_ID_SI_PEDIDO_DETA   NUMERIC(10,0)
DECLARE @LC_TIPO_BIEN            VARCHAR(1)
DECLARE @LC_TIPO_PEDIDO            VARCHAR(1)
DECLARE @LC_GRUPO_BIEN            VARCHAR(3)
DECLARE @LC_CLASE_BIEN            VARCHAR(3)
DECLARE @LC_FAMILIA_BIEN        VARCHAR(4)
DECLARE @LC_ITEM_BIEN            VARCHAR(20)
DECLARE @LC_TIPO_DOCUMENTO        VARCHAR(3) 
DECLARE @LC_FECHA_INICIAL       DATETIME
DECLARE @LC_FECHA_FINAL         DATETIME
DECLARE @LC_MONEDA_PAGO         VARCHAR(3)
DECLARE @LC_NRO_DOCUMENTO       VARCHAR(11)     
DECLARE @LC_VALOR_NEA             NUMERIC(16,6)
DECLARE @LC_FECHA_NEA           DATETIME
DECLARE @LC_MEDIDAS             VARCHAR(30)         
DECLARE @LC_ESTADO_ACTUAL       VARCHAR(1)     
DECLARE @LC_ESTADO_CONSERV      VARCHAR(1)
DECLARE @LC_FECHA_COMPRA        DATETIME     
DECLARE @LC_VALOR_COMPRA           NUMERIC(16,6)     
DECLARE @LC_NRO_ORDEN           NUMERIC(7)
DECLARE @LC_FEC_FIN_VIDA        DATETIME
DECLARE @LC_VIDA_UTIL             NUMERIC(8,6)
DECLARE @LC_TIPO_MODALIDAD      NUMERIC(1)
DECLARE @LC_CENTRO_COSTO        VARCHAR(150)
DECLARE @LC_NOMBRE_DEPEND       VARCHAR(150)     
DECLARE @LC_CODIGO_ACTIVO       VARCHAR(12)
DECLARE @LC_DESCRIPCION         VARCHAR(200)
DECLARE @LC_MODELO                 VARCHAR(40)    
DECLARE @LC_NRO_SERIE             VARCHAR(20)
DECLARE @LC_NOMBRE                 VARCHAR(10) 
DECLARE @LC_ESTADO                VARCHAR(2)    
DECLARE @LC_D_ITEM_CATALOGO      VARCHAR(150)
DECLARE @LN_ID_SI_PATRIMONIO         NUMERIC(10,0)
DECLARE @fecha_carga_inicio_1          DATETIME
DECLARE @fecha_carga_fin_1             DATETIME
DECLARE @LC_MARCA                    VARCHAR(10)
DECLARE @LC_ANO_PROCESO            NUMERIC(4,0)
DECLARE @LC_MES_PROCESO             VARCHAR(2)

-- inicio omrv 27.01.10
DECLARE @SEDE                    numeric(5,3)
DECLARE @D_SEDE                    varchar(50)
DECLARE @COD_ESTABLEC            numeric(5,0)
DECLARE @COD_ESTABLEC_SIS        varchar(20)
DECLARE @D_COD_ESTABLEC            varchar(200)
DECLARE @COD_CATEGORIA            numeric(5,0)
DECLARE @D_CORTO_COD_CATEGORIA  varchar(20)
-- fin omrv 27.01.10

BEGIN  
    TRUNCATE TABLE SI_PATRIMONIO

    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio,101) 
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
    
    IF @LN_ID_SI_PATRIMONIO IS NULL
    SET @LN_ID_SI_PATRIMONIO = 0    

        DECLARE C_1 CURSOR FOR        
            SELECT DISTINCT   
            sig_patrimonio.tipo_bien,
            sig_patrimonio.grupo_bien,
            sig_patrimonio.clase_bien,
            sig_patrimonio.familia_bien,
            sig_patrimonio.item_bien,
            sig_patrimonio.tipo_documento,
            sig_patrimonio.valor_nea,
            sig_patrimonio.fecha_nea,
            sig_patrimonio.medidas,
            sig_patrimonio.estado_actual,
            sig_patrimonio.estado_conserv,
            sig_patrimonio.fecha_compra,
            sig_patrimonio.valor_compra,
            sig_patrimonio.nro_orden,
            sig_patrimonio.fec_fin_vida,
            sig_patrimonio.vida_util,
            sig_patrimonio.tipo_modalidad,
            sig_patrimonio.centro_costo ,
            sig_centro_costo.nombre_depend ,
            sig_patrimonio.codigo_activo ,
            sig_patrimonio.descripcion ,
            sig_patrimonio.modelo ,
            sig_patrimonio.nro_serie ,
            marca.nombre,
            marca.marca,
            sig_patrimonio.estado, 
            sig_patrimonio.ano_proceso, 
                sig_patrimonio.mes_proceso
            FROM sig_patrimonio 
            LEFT OUTER JOIN marca ON 
            (sig_patrimonio.marca = marca.marca 
            AND sig_patrimonio.tipo_marca = marca.tipo_marca)
            LEFT OUTER JOIN sig_centro_costo ON 
            sig_patrimonio.ano_eje = sig_centro_costo.ano_eje 
            AND sig_patrimonio.sec_ejec = sig_centro_costo.sec_ejec 
            AND sig_patrimonio.centro_costo = sig_centro_costo.centro_costo 
        WHERE (sig_patrimonio.sec_ejec = @P_SEC_EJC) and          
              (not exists (Select p.secuencia from sig_patrimonio p 
               where p.sec_ejec=sig_patrimonio.sec_ejec 
               and   p.tipo_modalidad=sig_patrimonio.tipo_modalidad 
               and   p.secuencia=sig_patrimonio.secuencia 
               and  (p.mayor is null or p.mayor='')) ) 
               and  (not exists ( Select a.secuencia 
                             from sig_asignaciones a 
                             where a.ano_eje = @P_ANO_EJE 
           and   a.sec_ejec=sig_patrimonio.sec_ejec 
           and   a.tipo_modalidad=sig_patrimonio.tipo_modalidad 
           and   a.secuencia=sig_patrimonio.secuencia)) 
           and   (sig_patrimonio.estado=1 ) 
       UNION    
        SELECT  sig_patrimonio.tipo_bien,
            sig_patrimonio.grupo_bien,
            sig_patrimonio.clase_bien,
            sig_patrimonio.familia_bien,
            sig_patrimonio.item_bien,
            sig_patrimonio.tipo_documento,
            sig_patrimonio.valor_nea,
            sig_patrimonio.fecha_nea,
            sig_patrimonio.medidas,
            sig_patrimonio.estado_actual,
            sig_patrimonio.estado_conserv,
            sig_patrimonio.fecha_compra,
            sig_patrimonio.valor_compra,
            sig_patrimonio.nro_orden,
            sig_patrimonio.fec_fin_vida,
            sig_patrimonio.vida_util,
            sig_patrimonio.tipo_modalidad,
            sig_centro_costo.centro_costo , 
            sig_centro_costo.nombre_depend ,
            sig_patrimonio.codigo_activo ,
            sig_patrimonio.descripcion ,
            sig_patrimonio.modelo ,
            sig_patrimonio.nro_serie,
            marca.nombre,
            marca.marca,
            sig_patrimonio.estado, 
            sig_patrimonio.ano_proceso, 
                sig_patrimonio.mes_proceso
        FROM sig_asignaciones
                LEFT OUTER JOIN sig_centro_costo ON 
            sig_asignaciones.ano_eje = sig_centro_costo.ano_eje 
            AND sig_asignaciones.sec_ejec = sig_centro_costo.sec_ejec 
            AND sig_asignaciones.centro_entrega = sig_centro_costo.centro_costo,
            marca, sig_patrimonio 
        WHERE ( sig_patrimonio.sec_ejec = sig_asignaciones.sec_ejec ) and          
              ( sig_patrimonio.tipo_modalidad = sig_asignaciones.tipo_modalidad ) and          
              ( sig_patrimonio.secuencia = sig_asignaciones.secuencia ) and          
              ( marca.marca = sig_patrimonio.marca ) and          
              ( marca.tipo_marca = sig_patrimonio.tipo_marca ) and          
              (  sig_asignaciones.ano_eje = @P_ANO_EJE ) and          
              ( sig_asignaciones.sec_ejec = @P_SEC_EJC ) and          
              ( sig_asignaciones.nro_asignac = 
              ( Select max(nro_asignac) from sig_asignaciones a 
            where a.ano_eje=sig_asignaciones.ano_eje 
            and a.sec_ejec=sig_asignaciones.sec_ejec 
            and a.tipo_modalidad=sig_asignaciones.tipo_modalidad 
            and a.secuencia=sig_asignaciones.secuencia )) 
            and (not exists 
              (Select p.secuencia from sig_patrimonio p 
               where p.sec_ejec=sig_patrimonio.sec_ejec 
               and p.tipo_modalidad=sig_patrimonio.tipo_modalidad 
               and p.secuencia=sig_patrimonio.secuencia 
               and ( p.mayor is null or p.mayor='')))
               and ( sig_patrimonio.estado=1) 
    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_TIPO_BIEN,      @LC_GRUPO_BIEN,       @LC_CLASE_BIEN, 
     @LC_FAMILIA_BIEN,     @LC_ITEM_BIEN,              @LC_TIPO_DOCUMENTO, 
     @LC_VALOR_NEA,         @LC_FECHA_NEA,          @LC_MEDIDAS,
     @LC_ESTADO_ACTUAL,     @LC_ESTADO_CONSERV,     @LC_FECHA_COMPRA,
     @LC_VALOR_COMPRA,     @LC_NRO_ORDEN,        @LC_FEC_FIN_VIDA,
     @LC_VIDA_UTIL,         @LC_TIPO_MODALIDAD,     @LC_CENTRO_COSTO,
     @LC_NOMBRE_DEPEND,    @LC_CODIGO_ACTIVO,     @LC_DESCRIPCION,
     @LC_MODELO,        @LC_NRO_SERIE,        @LC_NOMBRE,
     @LC_MARCA,           @LC_ESTADO,         @LC_ANO_PROCESO,
     @LC_MES_PROCESO

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @LN_ID_SI_PATRIMONIO = @LN_ID_SI_PATRIMONIO + 1

            SELECT @LC_D_ITEM_CATALOGO = CAT.NOMBRE_ITEM
            FROM CATALOGO_BIEN_SERV_ORIGINAL CAT
            WHERE CAT.TIPO_BIEN    = 'B'  
        AND CAT.GRUPO_BIEN   = @LC_GRUPO_BIEN
            AND CAT.CLASE_BIEN   = @LC_CLASE_BIEN 
        AND CAT.FAMILIA_BIEN = @LC_FAMILIA_BIEN
            AND CAT.ITEM_BIEN    = @LC_ITEM_BIEN 

-- inicio omrv 27.01.10
SELECT @SEDE                    = SCC.SEDE,
       @D_SEDE                    = DSD.NOMBRE_SEDE,
       @COD_ESTABLEC            = CSD.COD_ESTABLEC,
       @COD_ESTABLEC_SIS        = EESS.COD_INTERNO,
       @D_COD_ESTABLEC            = EESS.DESC_ESTABLEC,
       @COD_CATEGORIA            = EESS.CATEGORIA,
       @D_CORTO_COD_CATEGORIA    = (SELECT CA.NOMBRE_CORTO FROM 
            SIG_PPR_CATEGORIA CA 
        WHERE CA.ANO_EJE = CSD.ANO_EJE AND 
                CA.CATEGORIA = EESS.CATEGORIA)  
FROM  SIG_PPR_SEDE CSD JOIN SIG_CENTRO_COSTO  SCC ON
     ( SCC.ANO_EJE      = CSD.ANO_EJE      AND
       SCC.SEC_EJEC     = CSD.SEC_EJEC     AND
       SCC.PLIEGO       = CSD.PLIEGO       AND
       SCC.SEDE         = CSD.SEDE         AND
       SCC.ESTADO       = 'A')
JOIN SIG_SEDES DSD ON
     ( DSD.SEDE   = CSD.SEDE AND
       DSD.PLIEGO = CSD.PLIEGO ) ,
     SIG_PPR_ESTABLECIMIENTO EESS
WHERE EESS.ANO_EJE      = CSD.ANO_EJE
  AND EESS.SEC_EJEC     = CSD.SEC_EJEC
  AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
  AND CSD.ANO_EJE       = @P_ANO_EJE
  AND CSD.SEC_EJEC      = @P_SEC_EJC
  AND SCC.CENTRO_COSTO  = @LC_CENTRO_COSTO

-- inicio fin 27.01.10
 
INSERT INTO SI_PATRIMONIO
                ( ANO_EJE,          SEC_EJEC,           ID_SI_PATRIMONIO, 
                  TIPO_BIEN,        ITEM_CATALOGO,      D_ITEM_CATALOGO,
                  TIPO_DOCUMENTO,   VALOR_NEA,          FECHA_NEA,
                  MEDIDAS,          ESTADO_ACTUAL,      ESTADO_CONSERVACION,
                  FECHA_COMPRA,     VALOR_COMPRA,       NRO_ORDEN,
                  FECHA_FIN_VIDA,   VIDA_UTIL,          TIPO_MODALIDAD,
                  CENTRO_COSTO,     D_CENTRO_COSTO,     CODIGO_ACTIVO,
                  MODELO,           NRO_SERIE,          DESCRIPCION_ACTIVO, 
                  CODIGO_MARCA,     NOMBRE_MARCA,       ESTADO_ACTIVO,
                  FECHA_CARGA_FIN,  FECHA_ENVIO,        FECHA_CARGA_INICIO, 
                  USUARIO_ENVIO,    ANO_PROCESO,        MES_PROCESO,
		  SEDE,		    D_SEDE,		COD_ESTABLEC            ,
                  COD_ESTABLEC_SIS, D_COD_ESTABLEC,	COD_CATEGORIA            ,
                  D_CORTO_COD_CATEGORIA)

            VALUES 
                     (@P_ANO_EJE,              @P_SEC_EJC,          @LN_ID_SI_PATRIMONIO,
              @LC_TIPO_BIEN,      @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN,      
              @LC_D_ITEM_CATALOGO,   @LC_TIPO_DOCUMENTO, @LC_VALOR_NEA,      
              @LC_FECHA_NEA,     @LC_MEDIDAS,          @LC_ESTADO_ACTUAL, @LC_ESTADO_CONSERV,
              @LC_FECHA_COMPRA,      @LC_VALOR_COMPRA,   @LC_NRO_ORDEN,
              @LC_FEC_FIN_VIDA,      @LC_VIDA_UTIL,      @LC_TIPO_MODALIDAD,
                      @LC_CENTRO_COSTO,      @LC_NOMBRE_DEPEND,  @LC_CODIGO_ACTIVO,
                      @LC_MODELO,            @LC_NRO_SERIE,      @LC_DESCRIPCION, 
              @LC_MARCA,         @LC_NOMBRE,         @LC_ESTADO,
              @fecha_carga_fin_1,    convert(varchar(10),getdate(),112),          
              @fecha_carga_inicio_1, @usuario_n,         @LC_ANO_PROCESO,
              @LC_MES_PROCESO,
            @SEDE                    ,@D_SEDE                    ,@COD_ESTABLEC            ,
            @COD_ESTABLEC_SIS        ,@D_COD_ESTABLEC            ,@COD_CATEGORIA            ,
            @D_CORTO_COD_CATEGORIA)


FETCH NEXT FROM C_1
    INTO @LC_TIPO_BIEN,      @LC_GRUPO_BIEN,       @LC_CLASE_BIEN, 
     @LC_FAMILIA_BIEN,     @LC_ITEM_BIEN,              @LC_TIPO_DOCUMENTO, 
     @LC_VALOR_NEA,         @LC_FECHA_NEA,          @LC_MEDIDAS,
     @LC_ESTADO_ACTUAL,     @LC_ESTADO_CONSERV,     @LC_FECHA_COMPRA,
     @LC_VALOR_COMPRA,     @LC_NRO_ORDEN,        @LC_FEC_FIN_VIDA,
     @LC_VIDA_UTIL,         @LC_TIPO_MODALIDAD,     @LC_CENTRO_COSTO,
     @LC_NOMBRE_DEPEND,    @LC_CODIGO_ACTIVO,     @LC_DESCRIPCION,
     @LC_MODELO,        @LC_NRO_SERIE,        @LC_NOMBRE,
     @LC_MARCA,           @LC_ESTADO,         @LC_ANO_PROCESO,
     @LC_MES_PROCESO
    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_CARGA_INVENTARIO_INM_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_INVENTARIO_INM_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_INVENTARIO_INM_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_INVENTARIO_INM_TRX]
     @P_ANO_EJE            	NUMERIC(4,0),
     @P_SEC_EJEC           	NUMERIC(6,0),    
     @O_ERR_NUM   			NUMERIC(6,0) OUTPUT,
     @O_ERR_MSG   			VARCHAR(255) OUTPUT
AS 

BEGIN
	
	INSERT INTO SI_INVENTARIO_INM_TRX 
	(
		ANO_EJE,			
		SEC_EJEC ,			
		NRO_INVENTARIO,		
		NOMBRE_INVENTARIO,	
		FECHA_INVENTARIO,	
		RESOLUCION, 
		ESTADO , 
		SEC_UNIDAD_ACTIVO,	
		DENOMINACION_UA,	
		IND_VERIFICA_UA,	
		IND_SOBRANTE_UA,	
		IND_FALTANTE_UA,	
		OBSERVACIONES_1_UA,	
		OBSERVACIONES_2_UA,	
		OBSERVACIONES_3_UA,	
		CODIGO_ITEM,		
		ESTADO_CONSERV_UA,  
		CODIGO_TIPO_UA,		
		UBICACION,			
		SECUENCIA,			
		DENOMINACION_INM,	
		IND_VERIFICA_P,		
		IND_SOBRANTE_P,		
		IND_FALTANTE_P,		
		OBSERVACIONES_1_P,	
		OBSERVACIONES_2_P,	
		OBSERVACIONES_3_P,	
		SEDE,				
		CODIGO_TIPO_INM,	
		ESTADO_CONSERV_P
		
	)	
  SELECT SIG_INM_IF.ANO_EJE,			
		 SIG_INM_IF.SEC_EJEC,			
		 SIG_INM_IF.NRO_INVENTARIO,	
		 COALESCE(SIG_INM_IF.NOMBRE_INVENTARIO,''),
		 COALESCE(CONVERT(VARCHAR(10),SIG_INM_IF.FECHA_INVENTARIO,111),''), 
		 COALESCE(SIG_INM_IF.RESOLUCION,''), 
		 COALESCE(SIG_INM_IF.ESTADO,'') ,		 	 		
		 SIG_INM_UNIDAD_ACTIVO_IF.SEC_UNIDAD_ACTIVO,
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.DENOMINACION,''),	
		 SIG_INM_UNIDAD_ACTIVO_IF.IND_VERIFICA,		
		 SIG_INM_UNIDAD_ACTIVO_IF.IND_SOBRANTE,		
		 SIG_INM_UNIDAD_ACTIVO_IF.IND_FALTANTE,		
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.OBSERVACIONES_1,''),	
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.OBSERVACIONES_2,''),	
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.OBSERVACIONES_3,''),	
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.CODIGO_ITEM,''),		
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.ESTADO_CONSERV,''),	
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.CODIGO_TIPO_UA,''),	
		 COALESCE(SIG_INM_UNIDAD_ACTIVO_IF.UBICACION,''),			 
		 SIG_PATRIMONIO_INM_IF.SECUENCIA,		
		 COALESCE(SIG_PATRIMONIO_INM_IF.DENOMINACION,''),		
		 SIG_PATRIMONIO_INM_IF.IND_VERIFICA,		
		 SIG_PATRIMONIO_INM_IF.IND_SOBRANTE,		
		 SIG_PATRIMONIO_INM_IF.IND_FALTANTE,
		 COALESCE(SIG_PATRIMONIO_INM_IF.OBSERVACIONES_1,''),	
		 COALESCE(SIG_PATRIMONIO_INM_IF.OBSERVACIONES_2,''),	
		 COALESCE(SIG_PATRIMONIO_INM_IF.OBSERVACIONES_3,''),  
		 COALESCE(SIG_PATRIMONIO_INM_IF.SEDE,0),				
		 COALESCE(SIG_PATRIMONIO_INM_IF.CODIGO_TIPO_INM,''),	
		 COALESCE(SIG_PATRIMONIO_INM_IF.ESTADO_CONSERV,'')	 
		
   FROM SIG_INM_IF,   
          SIG_INM_UNIDAD_ACTIVO_IF,   
          SIG_PATRIMONIO_INM_IF  
   WHERE ( SIG_INM_IF.ANO_EJE = SIG_INM_UNIDAD_ACTIVO_IF.ANO_EJE ) and  
         ( SIG_PATRIMONIO_INM_IF.ANO_EJE = SIG_INM_UNIDAD_ACTIVO_IF.ANO_EJE ) and  
         ( SIG_PATRIMONIO_INM_IF.SEC_EJEC = SIG_INM_UNIDAD_ACTIVO_IF.SEC_EJEC ) and  
         ( SIG_PATRIMONIO_INM_IF.SECUENCIA = SIG_INM_UNIDAD_ACTIVO_IF.SECUENCIA ) and  
         ( SIG_PATRIMONIO_INM_IF.NRO_INVENTARIO = SIG_INM_UNIDAD_ACTIVO_IF.NRO_INVENTARIO ) and  
         ( SIG_PATRIMONIO_INM_IF.ANO_EJE = SIG_INM_IF.ANO_EJE ) and  
         ( SIG_PATRIMONIO_INM_IF.SEC_EJEC = SIG_INM_IF.SEC_EJEC ) and  
         ( SIG_PATRIMONIO_INM_IF.NRO_INVENTARIO = SIG_INM_IF.NRO_INVENTARIO )   AND 
         SIG_INM_IF.ANO_EJE = 2014 AND SIG_INM_IF.SEC_EJEC = 204    
		   
END
GO


-- ----------------------------
-- procedure structure for SP_GENERA_SGE_ADQUISICIONES
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERA_SGE_ADQUISICIONES]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_GENERA_SGE_ADQUISICIONES]
GO

CREATE PROCEDURE [dbo].[SP_GENERA_SGE_ADQUISICIONES] (@Anio INT,@Ejecutora INT,@MesIni VARCHAR(2),@MesFin VARCHAR(2))
AS

DELETE FROM SGE_ADQUISICIONES_EXP
	  WHERE ANO_EJE=@Anio
	    AND SEC_EJEC=@Ejecutora
        AND MES_PROCESO BETWEEN ABS(@MesIni) AND ABS(@MesFin)

INSERT INTO SGE_ADQUISICIONES_EXP (ANO_EJE ,SEC_EJEC, NRO_ORDEN,TIPO_BIEN ,TIPO_PPTO,SEC_EJEC2,
            SECTOR,PLIEGO,MES_PROCESO,TIPO_ENTIDAD,GRUPO_BIEN,CLASE_BIEN ,FAMILIA_BIEN,ITEM_BIEN,CANT_ITEM,
			UNIDAD_MEDIDA,PRECIO_UNIT ,MONTO_SOLES,ORIGEN,FUENTE_FINANC,FUNCION,PROGRAMA ,SUB_PROGRAMA,
			ACT_PROY ,COMPONENTE,CLASIFICADOR ,FECHA_REG,DEPARTAMENTO,PROVINCIA,CATEGORIA_GASTO, 
			GRUPO,MODALIDAD,ELEMENTO_GASTO,RUC_PROV
          )
    SELECT OA.ANO_EJE ,OA.SEC_EJEC, OA.NRO_ORDEN,OA.TIPO_BIEN ,OA.TIPO_PPTO,OA.SEC_EJEC2,
            E.SECTOR,E.PLIEGO,OA.MES_CALEND,E.TIPO_ENTIDAD,OI.GRUPO_BIEN,OI.CLASE_BIEN ,OI.FAMILIA_BIEN,
			OI.ITEM_BIEN,SUM(OP.CANT_ARTICULO) CANT_ITEM,OI.UNIDAD_MEDIDA,
  			SUM(CASE WHEN OA.MONEDA='S/.' THEN OI.PREC_UNIT_MONEDA WHEN OA.MONEDA='US$' THEN ROUND(OI.PREC_UNIT_MONEDA*OA.TIPO_CAMBIO,2) END )/
			CASE WHEN SUM(OP.CANT_ARTICULO)=0 THEN 1 ELSE SUM(OP.CANT_ARTICULO) END PRECIO_UNIT ,
  			SUM(OP.MNTO_SOLES) MONTO_SOLES,OP.ORIGEN,OP.FUENTE_FINANC, M.FUNCION,M.PROGRAMA ,M.SUB_PROGRAMA,
			M.ACT_PROY ,M.COMPONENTE,SUBSTRING(OP.CLASIFICADOR,1,6) CLASIFICADOR ,OA.FECHA_REG,
			E.DEPARTAMENTO,E.PROVINCIA,SUBSTRING(OP.CLASIFICADOR,1,1) CATEGORIA_GASTO, SUBSTRING(OP.CLASIFICADOR,2,1) GRUPO,
		        SUBSTRING(OP.CLASIFICADOR,3,2) MODALIDAD,SUBSTRING(OP.CLASIFICADOR,5,2) ELEMENTO_GASTO,
			P.NRO_RUC RUC_PROV
	   FROM SIG_ORDEN_ADQUISICION OA,
	        SIG_ORDEN_ITEM OI,
			SIG_ORDEN_ITEM_PPTO OP,
			META M,
			EJECUTORA E,
			SIG_CONTRATISTAS P
      WHERE OA.ANO_EJE=OI.ANO_EJE
	  	AND OA.SEC_EJEC=OI.SEC_EJEC
		AND OA.NRO_ORDEN=OI.NRO_ORDEN
		AND OA.TIPO_BIEN=OI.TIPO_BIEN
		AND OA.TIPO_PPTO=OI.TIPO_PPTO
		AND OI.ANO_EJE=OP.ANO_EJE
		AND OI.SEC_EJEC=OP.SEC_EJEC
		AND OI.NRO_ORDEN=OP.NRO_ORDEN
		AND OI.TIPO_BIEN=OP.TIPO_BIEN
		AND OI.TIPO_PPTO=OP.TIPO_PPTO
		AND OI.SEC_ORDEN=OP.SEC_ORDEN
		AND OI.SEC_ITEM=OP.SEC_ITEM
		AND OA.ANO_EJE=M.ANO_EJE
		AND OA.SEC_EJEC=M.SEC_EJEC
		AND OP.SEC_FUNC=M.SEC_FUNC
		AND OA.SEC_EJEC=E.SEC_EJEC
		AND OA.PROVEEDOR=P.PROVEEDOR
		AND OA.ANO_EJE=@Anio
		AND OA.SEC_EJEC=@Ejecutora
		AND OA.MES_CALEND BETWEEN @MesIni AND @MesFin
   GROUP BY OA.ANO_EJE ,OA.SEC_EJEC, OA.NRO_ORDEN,OA.TIPO_BIEN ,OA.TIPO_PPTO,OA.SEC_EJEC2,
   		 	E.SECTOR,E.PLIEGO,OA.MES_CALEND,E.TIPO_ENTIDAD,OI.GRUPO_BIEN,OI.CLASE_BIEN ,OI.FAMILIA_BIEN,
			OI.ITEM_BIEN,OI.UNIDAD_MEDIDA,OP.ORIGEN,OP.FUENTE_FINANC, M.FUNCION,M.PROGRAMA ,M.SUB_PROGRAMA,
			M.ACT_PROY,M.COMPONENTE,OP.CLASIFICADOR ,OA.FECHA_REG,E.DEPARTAMENTO,E.PROVINCIA,P.NRO_RUC;
--/
GO


-- ----------------------------
-- procedure structure for DT_VALIDATELOGINPARAMS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_VALIDATELOGINPARAMS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_VALIDATELOGINPARAMS]
GO

CREATE PROCEDURE [dbo].[DT_VALIDATELOGINPARAMS]
    @vchLoginName  varchar(255),
    @vchPassword   varchar(255)
as

set nocount on

declare @iReturn int
declare @iObjectId int
select @iObjectId =0

declare @VSSGUID varchar(100)
select @VSSGUID = 'SQLVersionControl.VCS_SQL'

    declare @iPropertyObjectId int
    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    declare @vchSourceSafeINI varchar(255)
    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, 'VCSSourceSafeINI', @vchSourceSafeINI OUT

    exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT
    if @iReturn <> 0 GOTO E_OAError

    exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
											'ValidateLoginParams',
											NULL,
											@sSourceSafeINI = @vchSourceSafeINI,
											@sLoginName = @vchLoginName,
											@sPassword = @vchPassword
    if @iReturn <> 0 GOTO E_OAError

CleanUp:
    return

E_OAError:
    exec dbo.dt_displayoaerror @iObjectId, @iReturn
    GOTO CleanUp
GO


