IF @PN_FASE = 1
BEGIN
	insert into #tmp_techo_fase_2
	( origen ,fuente_financ , mnto_progra , FASE_CUADRO)
	SELECT DISTINCT b.origen, b.fuente_financ,
	(
		SELECT  sum(mnto_progra) 
		FROM sig_techo_presupuesto  a
		WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND
		       a.origen   = b.origen and a.fuente_financ = b.fuente_financ and
		       a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1
	) as total, 1
	FROM sig_techo_presupuesto b
	WHERE 	b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND
		b.indicador     = '0' and b.flag_meta_aprob = '0' and
		B.FASE_CUADRO = 1 AND
		not exists ( select '1'
		  	      FROM sig_techo_presupuesto c
			     WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND
				   c.origen    = b.origen and c.fuente_financ = b.fuente_financ and
				   c.FASE_CUADRO = 1 AND
				   c.indicador     ='1' and c.flag_meta_aprob = '0')

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	

	insert INTO sig_techo_presupuesto  
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
	sec_func       , centro_costo, 
	ppto_progra  , ppto_aprob  , ppto_asignado ,	ppto_modif,
	mnto_progra  , mnto_asig  , mnto_aprob	    , mnto_modif,
	indicador   , paac_inicial  , paac_modif     , porc_techo , 
	porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,
	FASE_CUADRO )
  	select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,
	( @li_secuencia + secuencia ) , NULL, NULL , NULL,
		NULL , NULL,
	0 , 0 , 0 , 0 ,
	mnto_progra,0, 0, 0 ,
	'1' ,0, 0 , 0 ,
	0 , NULL , '0' , NULL, 1
	from #tmp_techo_fase_2

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	DROP TABLE #tmp_techo_fase_2
END

	

