                        AND 	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO 
                        AND 	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP 
                        AND 	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP 
                        AND 	A.CLASIFICADOR =  sig_techo_presupuesto.CLASIFICADOR 
                        AND 	A.indicador     ='0' 
                        and 	A.flag_meta_aprob = '0' 
                        AND 	A.FASE_CUADRO = 1
                        )
	where   ano_eje         = @PN_ANIO 
    and     sec_ejec        = @PN_EJEC 
    AND	    indicador       ='5' 
    and	    flag_meta_aprob = '0' 
    AND	    FASE_CUADRO     = 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	
	insert into #tmp_techo_fase_8
	( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, SEC_FUNC_PROP, CENTRO_COSTO_PRESUP)
	SELECT DISTINCT b.origen, b.fuente_financ,
	(
		0
	) 
	as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.SEC_FUNC_PROP,
	B.CENTRO_COSTO_PRESUP
	FROM sig_techo_presupuesto b
	WHERE 	b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND
		b.indicador     = '0' and b.flag_meta_aprob = '0' and
		B.FASE_CUADRO = 1 AND
		not exists ( select '1'
		  	      FROM sig_techo_presupuesto c
			     WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND
				   c.origen    = b.origen and c.fuente_financ = b.fuente_financ and
				   C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND
				   C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND
				   C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND
				   c.FASE_CUADRO = 1 AND
				   c.indicador     = '4' /* 22.05.00v - HMR */
				   and c.flag_meta_aprob = '0')

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	

	SELECT @li_secuencia = ISNULL(MAX(secuencia),0) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	insert INTO sig_techo_presupuesto  
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
