-- ----------------------------
-- function structure for F_ELIMINA_TABS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[F_ELIMINA_TABS]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[F_ELIMINA_TABS]
GO

CREATE FUNCTION [dbo].[F_ELIMINA_TABS]
(@cadena varchar( 255 ) )
RETURNS varchar( 255 )
AS
BEGIN	
declare @lcodigo varchar(50)
declare @ldes    varchar(150)
declare @ldes2   varchar(150)
declare @lcar    varchar(5)
declare @lac     int
declare @lii     int
declare @long    int
declare @lalcance varchar(150)
declare @ltipo    varchar(150)

 set @ldes  = dbo.f_trim_campo( @cadena )
 set @ldes2 = ''
 set @lcar  = ''
 set @lii   = 1
 set @long  = LEN ( @ldes )

 while @lii<=@long
 begin

   set @lcar = ( SUBSTRING ( @ldes , @lii , 1 ) )
   set @lac  = ASCII( @lcar )
   if ( @lac=9 or @lac=13 or @lac=34 ) -- 9 TAB / 13 ENTER / 34 "
      set @ldes2= @ldes2 + ''
   else begin
       set @ldes2= @ldes2 + @lcar
   end

   set @lii = @lii + 1
 end


return @ldes2

END
GO


