CREATE PROCEDURE [dbo].[SP_SIG_KARDEX_REPROCESO_SALDO]
@ai_ano_eje numeric(4), @an_sec_ejec numeric(6), @as_mes varchar(2), @as_almacen varchar(3),
@as_sec_alma varchar(3), @as_tipo_uso varchar(1), @ai_tipo_ppto numeric(2), @an_encargo numeric(6),
@as_tipo_movi varchar(1), @an_tipo_tran numeric(2),  
--@an_nume_movi numeric(5) ,
@an_nume_movi numeric(6) ,
@as_usuing varchar(30), @adt_fecha_actual datetime, @as_equipo varchar(20),
@as_message varchar(100) output

------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

AS
BEGIN
DECLARE
@ls_msg varchar(1000),
@ls_correlativo varchar(4),
@li_code numeric(8),
@li_count numeric(8),

--variables para calcular los valores del reg actual
@xpu numeric(16,6),
