@xscant numeric(18,4),
@xnvalo numeric(14,2),
@xivalo numeric(14,2),
@xsvalo numeric(14,2),
--cdetmov_intervalo_in_out
@ld_fech_movi datetime,
@ls_tipo_movi varchar(1),
@ls_activo_fijo varchar(1),
@ld_tipo_tran numeric(2),
--@ld_nro_movi numeric(5),
@ld_nro_movi numeric(6),
@ld_secuencia numeric(2),
@ld_sec_detalle numeric(5),
@ld_sec_ppto numeric(2),
@ldec_tc numeric(18,4),
@ldec_tpu numeric(16,6),
@ldec_tsa numeric(18,4),
@ldec_tpp numeric(16,6),
@ldec_tvt numeric(14,2),
@ldec_tva numeric(14,2),

--valores temporales
@xsa5 numeric(18,4),
@xpp5 numeric(16,6),
@xpi5 numeric(16,6),
@xva5 numeric(14,2),

--valores generales
@ls_tipo_bien varchar(1),
@ls_grupo_bien varchar(2),
@ls_clase_bien varchar(2),
@ls_fami_bien varchar(4),
