@ld_item_bien_det numeric(5),
--
@ls_kardex_clasif varchar(1),
@ld_kardex_verifi  numeric(1)

-- Si parametro existe y esta activo se trabaja sin clasificador en kardex
set @ls_kardex_clasif = 'S'

SELECT @ld_kardex_verifi = count(*)
  FROM sig_maestro_det_numerico 
 WHERE cod_maestro = 'PARAMETRO' AND
       cod_detalle = 1 AND
       @ai_ano_eje >= valor_numerico AND
       estado = 'A'

set @ld_kardex_verifi = isnull(@ld_kardex_verifi, 0)

If (@ld_kardex_verifi > 0)
Begin
	set @ls_kardex_clasif = 'N'
END


IF (@ai_tipo_ppto = 2 )
BEGIN
	IF (@ai_ano_eje >= 2014)
	  SET @ls_kardex_clasif = 'S'
END 

--
  SELECT @ls_kard_peco = valor  
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec = @an_sec_ejec AND  
         cod_maestro = 'FLAG_KARD_PECOSA'

set @ls_kard_peco = isnull(@ls_kard_peco, '0')
If (@ls_kard_peco = '')
   set @ls_kard_peco = '0'

  SELECT @ls_flag_edit = valor  
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec = @an_sec_ejec AND  
         cod_maestro = 'FLAG_EDIT'

set @ls_flag_edit = isnull(@ls_flag_edit, '0')
If (@ls_flag_edit = '')
   set @ls_flag_edit = '0'

set @ls_correlativo = '0001'
If (@an_nume_movi = -1)
BEGIN
	UPDATE sig_kardex_por_almacen
	   SET cant_ingreso  = 0,
		cant_egreso   = 0,
		stock_actual  = stock_inicial,
		saldo_valor   = saldo_inicial,
		precio_promed = precio_invent,
		valor_ingreso = 0, 
		valor_egreso  = 0 
	 WHERE ano_eje     = @ai_ano_eje  and
		sec_ejec    = @an_sec_ejec and
		mes_proceso = @as_mes      and
		almacen     = @as_almacen  and
		sec_almacen = @as_sec_alma and
		tipo_uso in ( SELECT DISTINCT d.tipo_uso
				  FROM sig_detalle_movim_almacen d,
				       sig_movim_almacen m
				 WHERE d.ano_eje  = m.ano_eje  and
				       d.sec_ejec = m.sec_ejec and
				       d.almacen  = m.almacen  and
				       d.sec_almacen  = m.sec_almacen  and
				       d.tipo_movimto = m.tipo_movimto and
				       d.tipo_transac = m.tipo_transac and
				       d.tipo_ppto    = m.tipo_ppto    and
				       d.nro_movimto  = m.nro_movimto  and
				       ((@an_nume_movi <> -1) or
				       (@an_nume_movi = -1 and m.estado_kardex= 'S')) and
				       d.ano_eje      = @ai_ano_eje  and
				       d.sec_ejec     = @an_sec_ejec and
				       d.almacen      = @as_almacen  and
				       d.sec_almacen  = @as_sec_alma and
				       d.tipo_movimto in ('A','I','S') and
				       d.tipo_movimto like @as_tipo_movi and
				       ((@an_tipo_tran = -1 ) or
				       (@an_tipo_tran <> -1 and d.tipo_transac = @an_tipo_tran)) and
				       m.tipo_ppto    = @ai_tipo_ppto and
				       ((@an_nume_movi = -1) or
				       (@an_nume_movi <> -1 and d.nro_movimto  = @an_nume_movi)) and
				       d.mes_proceso  = @as_mes      and
				       ((@an_nume_movi = -1 and d.tipo_uso = @as_tipo_uso) or
				       (@an_nume_movi <> -1 and m.tipo_uso = @as_tipo_uso)) and
				       ((@ai_tipo_ppto = 1) or
				       (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
				       d.cant_articulo >= 0 ) and
		tipo_ppto   = @ai_tipo_ppto and
		secuencia   = @an_encargo

	IF @@ERROR <> 0 
	BEGIN
		set @as_message = 'No se puede inicializar los valores del Kardex :'
		return -1
	End

	UPDATE sig_kardex_por_almacen
	   SET cant_ingreso  = 0,
		cant_egreso   = 0,
		stock_actual  = stock_inicial,
		saldo_valor   = saldo_inicial,
		precio_promed = precio_invent,
		valor_ingreso = 0, 
		valor_egreso  = 0 
	 WHERE ano_eje     = @ai_ano_eje  and
		sec_ejec    = @an_sec_ejec and
		mes_proceso = @as_mes      and
		almacen     = @as_almacen  and
		sec_almacen = @as_sec_alma and
		tipo_uso    like @as_tipo_uso and
		tipo_ppto   = @ai_tipo_ppto and
		secuencia   = @an_encargo

	IF @@ERROR <> 0 
	BEGIN
		set @as_message = 'No se puede inicializar los valores del Kardex (2):'
		return -1
	End
END

-- cursor para proceso en batch o en linea 1 bien
DECLARE cbucle_generico CURSOR FOR
SELECT DISTINCT d.tipo_bien,    d.grupo_bien,  d.clase_bien,
		d.familia_bien, d.item_bien,   d.marca,
        d.tipo_uso,     m.nro_encargo, m.sec_ejec2,
		d.activo_fijo,  case @ls_kardex_clasif when 'N' then '0' else d.clasificador end as clasificador, d.mayor,
		d.sub_cta,      d.tipo_marca,
		d.unidad_medida, d.item_bien_det
  FROM sig_detalle_movim_almacen d,
       sig_movim_almacen m
 WHERE d.ano_eje  = m.ano_eje  and
       d.sec_ejec = m.sec_ejec and
       d.almacen  = m.almacen  and
       d.sec_almacen  = m.sec_almacen  and
       d.tipo_movimto = m.tipo_movimto and
       d.tipo_transac = m.tipo_transac and
       d.tipo_ppto    = m.tipo_ppto    and
       d.nro_movimto  = m.nro_movimto  and
       ((@an_nume_movi <> -1) or
       (@an_nume_movi = -1 and m.estado_kardex= 'S')) and
       d.ano_eje      = @ai_ano_eje  and
       d.sec_ejec     = @an_sec_ejec and
       d.almacen    = @as_almacen  and
       d.sec_almacen  = @as_sec_alma and
       d.tipo_movimto in ('A','I','S') and
       d.tipo_movimto like @as_tipo_movi and
       ((@an_tipo_tran = -1 ) or
       (@an_tipo_tran <> -1 and d.tipo_transac = @an_tipo_tran)) and
       m.tipo_ppto    = @ai_tipo_ppto and
       ((@an_nume_movi = -1) or
       (@an_nume_movi <> -1 and d.nro_movimto  = @an_nume_movi)) and
       d.mes_proceso  = @as_mes      and
       ((@an_nume_movi = -1 and d.tipo_uso = @as_tipo_uso) or
       (@an_nume_movi <> -1 and m.tipo_uso = @as_tipo_uso)) and
       ((@ai_tipo_ppto = 1) or
       (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
       d.cant_articulo >= 0

OPEN cbucle_generico
FETCH NEXT FROM cbucle_generico INTO @ls_tipo_bien, @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien, 
				        @ls_item_bien, @ld_marca, @ls_tipo_uso, @ld_encargo, 
					@ld_sec_ejec2, @ls_activo_fijo, @ls_clas_gast, @ls_plan_mayor,
					@ls_plan_subcta, @ls_tipo_marc, @ld_unid_medi, @ld_item_bien_det
WHILE @@FETCH_STATUS = 0
BEGIN
	set @ls_codi_bien = @ls_grupo_bien + @ls_clase_bien + @ls_fami_bien + @ls_item_bien

	-- captura datos del kardex y calcular el precio promedio inicial
	SELECT @xsa2 = stock_inicial, @xva2 = saldo_inicial, @xpp2 = precio_invent --xpp2  precio_promed
	  FROM sig_kardex_por_almacen
	 WHERE ano_eje      = @ai_ano_eje    and 
	 	sec_ejec    = @an_sec_ejec   and
		mes_proceso = @as_mes        and
		almacen     = @as_almacen    and
		sec_almacen = @as_sec_alma   and
		tipo_bien   = @ls_tipo_bien  and 
		codigo_bien = @ls_codi_bien  and
		marca       = @ld_marca      and 
		clasificador= @ls_clas_gast  and
		mayor       = @ls_plan_mayor and
		sub_cta     = @ls_plan_subcta and
		tipo_uso    = @ls_tipo_uso   and
		tipo_ppto   = @ai_tipo_ppto  and
		secuencia   = @an_encargo    and
		unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and item_bien_det is null) or
		 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

	set @ld_temp = @@rowcount
	If (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al capturar los datos del kardex :'
		return -1
	end

	IF (@ld_temp = 0)
	begin
		set @xpp2 = 0
		set @xsa2 = 0
		set @xva2 = 0
	end

	If (@xsa2 = 0)
		set @xpp2 = 0

	set @li_count=0
	set @ldec_tc=0
	set @ldec_tpu=0
	set @ldec_tvt=0
	set @ldec_tsa=0
	set @ldec_tva=0
	set @ldec_tpp=0

	-- upd sig_detalle_movim_almacen 
	-- get in out for item_bien since xfech_movi
	DECLARE cdetmov_intervalo_in_out CURSOR FOR
	SELECT d.fecha_movimto, d.tipo_movimto,
	       d.tipo_transac,  d.nro_movimto,   d.secuencia,
	       d.sec_detalle,   d.cant_articulo, d.precio_unit,
	       d.valor_total,   d.stock_actual,  d.valor_actual,
	       d.precio_promed
	  FROM sig_detalle_movim_almacen d,
	       sig_movim_almacen m
	 WHERE d.ano_eje      = m.ano_eje  and
	       d.sec_ejec     = m.sec_ejec and
	       d.almacen      = m.almacen  and
	       d.sec_almacen  = m.sec_almacen  and
	       d.tipo_movimto = m.tipo_movimto and
	       d.tipo_transac = m.tipo_transac and
	       d.tipo_ppto    = m.tipo_ppto    and
	       d.nro_movimto  = m.nro_movimto  and
	       m.estado_kardex= 'S' and
	       d.ano_eje      = @ai_ano_eje  and
	       d.sec_ejec     = @an_sec_ejec and
	       d.mes_proceso  = @as_mes      and
	       d.almacen      = @as_almacen  and
	       d.sec_almacen  = @as_sec_alma and
	       d.tipo_movimto in ('A','I','S')  and
	       d.tipo_bien    = @ls_tipo_bien   and
	       d.grupo_bien   = @ls_grupo_bien  and
	       d.clase_bien   = @ls_clase_bien  and
	       d.familia_bien = @ls_fami_bien   and
	       d.item_bien    = @ls_item_bien   and
	       d.marca        = @ld_marca       and
	       d.tipo_uso     = @ls_tipo_uso    and
	       m.tipo_ppto    = @ai_tipo_ppto   and
	       ((@ai_tipo_ppto = 1) or
	       (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	       d.cant_articulo >= 0 and
	       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
	        (@ls_kardex_clasif = 'N'))  and
	       d.mayor        = @ls_plan_mayor and
	       d.sub_cta      = @ls_plan_subcta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
	 order by d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
	       d.secuencia, d.sec_detalle

	OPEN cdetmov_intervalo_in_out
	FETCH NEXT FROM cdetmov_intervalo_in_out INTO @ld_fech_movi, @ls_tipo_movi, @ld_tipo_tran, @ld_nro_movi, 
						 @ld_secuencia, @ld_sec_detalle, @ldec_tc, @ldec_tpu, 
						 @ldec_tvt, @ldec_tsa, @ldec_tva, @ldec_tpp
	WHILE @@FETCH_STATUS = 0
	BEGIN

		set @li_count = @li_count + 1

		--for other case get values of preview detmov record
		DECLARE cpreview CURSOR FOR
		SELECT d.fecha_movimto, d.tipo_movimto,
		       d.tipo_transac,  d.nro_movimto,   d.secuencia,
		       d.sec_detalle,   d.cant_articulo, d.precio_unit,
		       d.valor_total,   d.stock_actual,  d.valor_actual,
		       d.precio_promed
		  FROM sig_detalle_movim_almacen d,
		       sig_movim_almacen m
		 WHERE d.ano_eje      = m.ano_eje  and
		       d.sec_ejec     = m.sec_ejec and
		       d.almacen      = m.almacen  and
		       d.sec_almacen  = m.sec_almacen  and
		       d.tipo_movimto = m.tipo_movimto and
		       d.tipo_transac = m.tipo_transac and
		       d.tipo_ppto    = m.tipo_ppto    and
		       d.nro_movimto  = m.nro_movimto  and
		       m.estado_kardex= 'S' and
		       d.ano_eje      = @ai_ano_eje  and
		       d.sec_ejec     = @an_sec_ejec and
		       d.mes_proceso  = @as_mes      and
		       d.almacen      = @as_almacen  and
		       d.sec_almacen  = @as_sec_alma and
		       d.tipo_movimto in ('A','I','S')  and
		       d.tipo_bien    = @ls_tipo_bien   and
		       d.grupo_bien   = @ls_grupo_bien  and
		       d.clase_bien   = @ls_clase_bien  and
		       d.familia_bien = @ls_fami_bien   and
		       d.item_bien    = @ls_item_bien   and
		       d.marca        = @ld_marca       and
		       d.tipo_uso     = @ls_tipo_uso    and
		       m.tipo_ppto    = @ai_tipo_ppto   and
		       ((@ai_tipo_ppto = 1) or
		       (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
		       d.cant_articulo >= 0 and
		       ((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
		        (@ls_kardex_clasif = 'N'))  and
		       d.mayor        = @ls_plan_mayor and
		       d.sub_cta      = @ls_plan_subcta and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		 order by d.fecha_movimto desc, d.fecha_reg desc, d.tipo_movimto, d.tipo_transac, 
		       d.nro_movimto, d.secuencia, d.sec_detalle

		OPEN cpreview
		FETCH NEXT FROM cpreview INTO @xfech_movi2, @xtipo_movi2, @xtipo_tran2, @xnro_secu2, @x_secuencia2,
				    	 @xnro_item2,  @xc2,  @xpu2, @xvt2, @xsa3, @xva3, @xpp3
		set @li_code = @@rowcount
		CLOSE cpreview
		DEALLOCATE cpreview

		If (@li_code > 0)
		begin
			If (@ls_tipo_movi = 'A')
			begin
				set @xsa = @xsa2
				set @xva = @xva2
				set @xpp = @xpp2
			end
			If (@ls_tipo_movi = 'I')
			begin
				set @xpu = @ldec_tpu
				set @xvt = @ldec_tvt
				set @xsa = @xsa2 + @ldec_tc
				set @xva = @xva2 + @xvt
				If (@li_count = 1 and @xsa2 = 0)
					set @xpp = @xpu
				Else
					set @xpp = round(@xva / @xsa,6)
			end
			If (@ls_tipo_movi = 'S')
			begin
				set @xpu = @xpp2
				set @xsa = @xsa2 - @ldec_tc
				if (@xsa = 0)  --Se da el valor saldo si la cantidad saldo es 0
					set @xvt = @xva2
				Else
					set @xvt = round(@ldec_tc * @xpp2,2)
				set @xva = @xva2 - @xvt
				set @xpp = @xpp2
			end
			set @xpp2 = @xpp
		end
		Else
		begin
			-- if not exist a older record than this one then init values with the same
			if ((@ls_tipo_movi='A' and @ld_tipo_tran = 1) or @li_count=1 )
			begin
				set @xpu = @xpp2
				set @xvt = @ldec_tvt
				set @xsa = @xsa2
				set @xva = @xva2
				set @xpp = @xpp2
			end
		END
		
		--init values for next record
		set @xpu2 = @xpu
		set @xvt2 = @xvt
		set @xsa2 = @xsa
		set @xva2 = @xva
		set @xpp2 = @xpp

		If (@ls_tipo_movi = 'I')
		Begin
			 update sig_detalle_movim_almacen
			    SET stock_actual  = @xsa,
				valor_actual  = @xva, 
				precio_promed = @xpp
			  where ano_eje      = @ai_ano_eje   and
				sec_ejec     = @an_sec_ejec  and
				almacen      = @as_almacen   and
				sec_almacen  = @as_sec_alma  and
				tipo_movimto = @ls_tipo_movi and
				tipo_transac = @ld_tipo_tran and
				tipo_ppto    = @ai_tipo_ppto and
				nro_movimto  = @ld_nro_movi  and
				secuencia    = @ld_secuencia and
				sec_detalle  = @ld_sec_detalle

			IF (@@error <> 0)
			begin
				close cdetmov_intervalo_in_out
				close cbucle_generico
				DEALLOCATE cdetmov_intervalo_in_out
				DEALLOCATE cbucle_generico
				set @as_message = 'Error al actualizar detalle de almacén :'
				return -1
			End
		end

		If (@ls_tipo_movi = 'S')
		Begin
			 update sig_detalle_movim_almacen
			    SET precio_unit   = @xpu, 
				valor_total   = @xvt, 
				stock_actual  = @xsa,
				valor_actual  = @xva, 
				precio_promed = @xpp
			  where ano_eje      = @ai_ano_eje   and
				sec_ejec     = @an_sec_ejec  and
				almacen      = @as_almacen   and
				sec_almacen  = @as_sec_alma  and
				tipo_movimto = @ls_tipo_movi and
				tipo_transac = @ld_tipo_tran and
				tipo_ppto    = @ai_tipo_ppto and
				nro_movimto  = @ld_nro_movi  and
				secuencia    = @ld_secuencia and
				sec_detalle  = @ld_sec_detalle
	
			IF (@@error <> 0)
			begin
				close cdetmov_intervalo_in_out
				close cbucle_generico
				DEALLOCATE cdetmov_intervalo_in_out
				DEALLOCATE cbucle_generico
				set @as_message = 'Error al actualizar detalle de almacén :'
				return -1
			End
				
			set @ld_sec_ppto = 1
			 UPDATE sig_detalle_cta_almacen  
			    SET valor_cuenta = @xvt
			  where ano_eje      = @ai_ano_eje   and
				sec_ejec     = @an_sec_ejec  and
				almacen      = @as_almacen   and
				sec_almacen  = @as_sec_alma  and
				tipo_movimto = @ls_tipo_movi and
				tipo_transac = @ld_tipo_tran and
				tipo_ppto    = @ai_tipo_ppto and
				nro_movimto  = @ld_nro_movi  and
				secuencia    = @ld_secuencia and
				sec_detalle  = @ld_sec_detalle and
				sec_ppto     = @ld_sec_ppto   and
				mayor        = @ls_plan_mayor and
				sub_cta      = @ls_plan_subcta and
				ind_alma     = '1' 

			IF (@@error <> 0)
			begin
				close cdetmov_intervalo_in_out
				close cbucle_generico
				DEALLOCATE cdetmov_intervalo_in_out
				DEALLOCATE cbucle_generico
				set @as_message = 'Error al actualizar valor de la cuenta contable :'
				return -1
			End

			--Solo actualiza si el flag esta prendido y es el proceso masivo
			If (@ls_kard_peco = '1' and @an_nume_movi = -1 AND @ld_tipo_tran NOT IN (7, 8,9)) --No incluye transferncias/PIA
			BEGIN
				  SELECT @ls_tipo_pedi = p.tipo_pedido, @ls_nume_pedi = p.nro_pedido, 
					 @ld_secu_pedi = p.secuencia, @ld_coun_aten = count(*)  
				    FROM sig_detalle_pedidos d,   
					 sig_detalle_pecosa p  
				   WHERE p.ano_eje     = d.ano_eje and  
					 p.sec_ejec    = d.sec_ejec and  
					 p.tipo_bien   = d.tipo_bien and  
					 p.tipo_pedido = d.tipo_pedido and  
					 p.nro_pedido  = d.nro_pedido and  
					 p.secuencia   = d.secuencia and  
					 d.ano_eje     = @ai_ano_eje AND  
					 d.sec_ejec    = @an_sec_ejec AND  
					 d.tipo_bien   = @ls_tipo_bien AND
					 d.grupo_bien  = @ls_grupo_bien AND  
					 d.clase_bien  = @ls_clase_bien AND  
					 d.familia_bien = @ls_fami_bien AND  
					 d.item_bien    = @ls_item_bien AND  
					 d.almacen      = @as_almacen AND  
					 d.sec_almacen  = @as_sec_alma AND  
					 p.marca        = @ld_marca AND  
					 p.nro_pecosa   = @ld_nro_movi AND
					 d.unidad_medida = @ld_unid_medi AND
					 
					 d.mayor = @ls_plan_mayor AND
                     d.sub_cta = @ls_plan_subcta AND
                     
					 ((@ld_item_bien_det is null and p.item_bien_det is null) or
					  (@ld_item_bien_det is not null and p.item_bien_det = @ld_item_bien_det)) AND
					 p.tipo_pedido not in ('4','X')
				GROUP BY p.tipo_pedido, p.nro_pedido, p.secuencia

				IF (@@error <> 0)
				begin
					close cdetmov_intervalo_in_out
					close cbucle_generico
					DEALLOCATE cdetmov_intervalo_in_out
					DEALLOCATE cbucle_generico
					set @as_message = 'No se puede obtener los datos del Pedido.'
					return -1
				End

				set @ld_valo_tota = @xvt
				set @ld_coun_deta = 0

				DECLARE clotedetalle CURSOR FOR
				  SELECT sec_atencion, cant_atendida
				    FROM sig_detalle_pecosa
				   WHERE ano_eje     = @ai_ano_eje AND
					 sec_ejec    = @an_sec_ejec AND
					 tipo_bien   = @ls_tipo_bien AND
					 tipo_pedido = @ls_tipo_pedi AND
					 nro_pedido  = @ls_nume_pedi AND
					 secuencia   = @ld_secu_pedi AND
					 marca       = @ld_marca AND
					 nro_pecosa  = @ld_nro_movi

				OPEN clotedetalle
				FETCH NEXT FROM clotedetalle INTO @ld_secu_aten, @ld_cant_aten
				WHILE @@FETCH_STATUS = 0
				BEGIN

					set @ld_coun_deta = @ld_coun_deta+1

					If (@ld_coun_deta=@ld_coun_aten)
						set @ld_valo_aten = @ld_valo_tota
					Else
					begin
						set @ld_valo_aten = round(@xpu * @ld_cant_aten,2)
						If (@ld_valo_aten>@ld_valo_tota)
							set @ld_valo_aten = @ld_valo_tota
					End
					set @ld_valo_tota = @ld_valo_tota - @ld_valo_aten

					  UPDATE sig_detalle_pecosa
					     set precio_unit = @xpu,
						 valor_total = @ld_valo_aten
					   WHERE ano_eje     = @ai_ano_eje AND
						 sec_ejec    = @an_sec_ejec AND
						 tipo_bien   = @ls_tipo_bien AND
						 tipo_pedido = @ls_tipo_pedi AND
						 nro_pedido  = @ls_nume_pedi AND
						 secuencia   = @ld_secu_pedi AND
						 sec_atencion = @ld_secu_aten

					IF (@@error <> 0)
					begin
						close cdetmov_intervalo_in_out
						close cbucle_generico
						close clotedetalle
						DEALLOCATE cdetmov_intervalo_in_out
						DEALLOCATE cbucle_generico
						DEALLOCATE clotedetalle
						set @as_message = 'No se puede actualizar el detalle Pecosa.'
						return -1
					End
					FETCH NEXT FROM clotedetalle INTO @ld_secu_aten, @ld_cant_aten
				END
				CLOSE clotedetalle
				DEALLOCATE clotedetalle

				  SELECT @ld_valo_tota = sum(valor_total)
				    FROM sig_detalle_pecosa
				   WHERE ano_eje     = @ai_ano_eje AND
					 sec_ejec    = @an_sec_ejec AND
					 tipo_bien   = @ls_tipo_bien AND
					 tipo_pedido = @ls_tipo_pedi AND
					 nro_pedido  = @ls_nume_pedi AND
					 secuencia   = @ld_secu_pedi

				  UPDATE sig_detalle_pedidos
				     set valor_total = @ld_valo_tota
				   WHERE ano_eje     = @ai_ano_eje AND
					 sec_ejec    = @an_sec_ejec AND
					 tipo_bien   = @ls_tipo_bien AND
					 tipo_pedido = @ls_tipo_pedi AND
					 nro_pedido  = @ls_nume_pedi AND
					 secuencia   = @ld_secu_pedi

				IF (@@error <> 0)
				begin
					close cdetmov_intervalo_in_out
					close cbucle_generico
					DEALLOCATE cdetmov_intervalo_in_out
					DEALLOCATE cbucle_generico
					set @as_message = 'No se puede actualizar el detalle de Pedido.'
					return -1
				End
			End
		End

		FETCH NEXT FROM cdetmov_intervalo_in_out INTO @ld_fech_movi, @ls_tipo_movi, @ld_tipo_tran, @ld_nro_movi, 
							 @ld_secuencia, @ld_sec_detalle, @ldec_tc, @ldec_tpu, 
							 @ldec_tvt, @ldec_tsa, @ldec_tva, @ldec_tpp
	END
	CLOSE cdetmov_intervalo_in_out
	DEALLOCATE cdetmov_intervalo_in_out

	-- upd sig_kardex_por_almacen 
	-- get final values from sig_detalle_movim_almacen
	 SELECT @xicant = sum(d.cant_articulo), @xivalo = sum(d.valor_total)
	   FROM sig_detalle_movim_almacen d,
		sig_movim_almacen m
	  WHERE d.ano_eje      = m.ano_eje      and
		d.sec_ejec     = m.sec_ejec     and
		d.almacen      = m.almacen      and
		d.sec_almacen  = m.sec_almacen  and
		d.tipo_movimto = m.tipo_movimto and
		d.tipo_transac = m.tipo_transac and
		d.tipo_ppto    = m.tipo_ppto    and
		d.nro_movimto  = m.nro_movimto  and
	        d.ano_eje      = @ai_ano_eje    and
	 	d.sec_ejec     = @an_sec_ejec   and
		d.almacen      = @as_almacen    and
		d.sec_almacen  = @as_sec_alma   and
		d.tipo_movimto = 'I'            and
		d.tipo_bien    = @ls_tipo_bien  and
		d.grupo_bien   = @ls_grupo_bien and
		d.clase_bien   = @ls_clase_bien and
		d.familia_bien = @ls_fami_bien and
		d.item_bien    = @ls_item_bien and
		d.marca        = @ld_marca     and
		d.mes_proceso  = @as_mes       and
		d.tipo_uso     = @ls_tipo_uso  and
		m.tipo_ppto    = @ai_tipo_ppto and
		((@ai_tipo_ppto = 1) or
		 (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	    m.estado_kardex= 'S' and
		d.cant_articulo >= 0 and
		((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
		 (@ls_kardex_clasif = 'N'))  and
		d.mayor        = @ls_plan_mayor and
		d.sub_cta      = @ls_plan_subcta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al leer los valores de Ingreso : '
		return -1
	End

	 SELECT @xscant = sum(d.cant_articulo), @xsvalo = sum(d.valor_total)
	   FROM sig_detalle_movim_almacen d,
		sig_movim_almacen m
	  WHERE d.ano_eje      = m.ano_eje  and
		d.sec_ejec     = m.sec_ejec and
		d.almacen      = m.almacen  and
		d.sec_almacen  = m.sec_almacen  and
		d.tipo_movimto = m.tipo_movimto and
		d.tipo_transac = m.tipo_transac and
		d.tipo_ppto    = m.tipo_ppto    and
		d.nro_movimto  = m.nro_movimto  and
	    d.ano_eje      = @ai_ano_eje   and
	 	d.sec_ejec     = @an_sec_ejec  and
		d.almacen      = @as_almacen   and
		d.sec_almacen  = @as_sec_alma  and
		d.tipo_movimto = 'S'           and
		d.tipo_bien    = @ls_tipo_bien and
		d.grupo_bien   = @ls_grupo_bien and
		d.clase_bien   = @ls_clase_bien and
		d.familia_bien = @ls_fami_bien and
		d.item_bien    = @ls_item_bien and
		d.marca        = @ld_marca     and
		d.mes_proceso  = @as_mes       and
		d.tipo_uso     = @ls_tipo_uso  and
		m.tipo_ppto    = @ai_tipo_ppto and
		((@ai_tipo_ppto = 1) or
		 (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
        m.estado_kardex= 'S' and
		d.cant_articulo >= 0 and
		((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
		 (@ls_kardex_clasif = 'N'))  and
		d.mayor        = @ls_plan_mayor and
		d.sub_cta      = @ls_plan_subcta and
		d.unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and d.item_bien_det is null) or
		 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al leer los valores de Salida : '
		return -1
	End

	set @xncant = isnull(@xncant, 0)
	set @xnprecunit = isnull(@xnprecunit, 0)
	set @xnvalo = isnull(@xnvalo, 0)
	set @xicant = isnull(@xicant, 0)
	set @xscant = isnull(@xscant, 0)
	set @xivalo = isnull(@xivalo, 0)
	set @xsvalo = isnull(@xsvalo, 0)

	-- captura datos del kardex y calcular el precio promedio inicial
	 SELECT @xsa5 = stock_inicial, @xva5 = saldo_inicial, @xpi5 = precio_invent
	   FROM sig_kardex_por_almacen
	  WHERE ano_eje     = @ai_ano_eje     and 
	 	sec_ejec    = @an_sec_ejec   and
		mes_proceso = @as_mes        and
		almacen     = @as_almacen    and
		sec_almacen = @as_sec_alma   and
		tipo_bien   = @ls_tipo_bien  and 
		codigo_bien = @ls_codi_bien  and
		marca       = @ld_marca      and 
		clasificador= @ls_clas_gast  and
		mayor       = @ls_plan_mayor and
		sub_cta     = @ls_plan_subcta and
		tipo_uso    = @ls_tipo_uso   and
		tipo_ppto   = @ai_tipo_ppto  and
		secuencia   = @an_encargo    and
		unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and item_bien_det is null) or
		 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

	IF (@@rowcount = 0)
	begin
		set @xsa5 = 0
		set @xva5 = 0
		set @xpi5 = 0
	end

	If (@xsa5 = 0)
		set @xpi5 = 0

	If (@xicant + @xscant = 0)
		set @xpp5 = @xpi5
	Else
		set @xpp5 = @xpp

	If (@ls_flag_edit = '0')
	Begin
		If (@xsa5 + @xicant - @xscant < 0)
		Begin
			set @ls_codi_bien = @ls_grupo_bien + @ls_clase_bien + @ls_fami_bien + @ls_item_bien
			set @ls_plan_mayor = @ls_plan_mayor + @ls_plan_subcta

			close cbucle_generico
			DEALLOCATE cbucle_generico
			If (@ls_kardex_clasif = 'S')
				RAISERROR ('Existen mas Salidas que ingreso en el item %s clasificador %s cuenta %s .',
					   16, 1, @ls_codi_bien, @ls_clas_gast, @ls_plan_mayor)
			Else
				RAISERROR ('Existen mas Salidas que ingreso en el item %s cuenta %s .',
					   16, 1, @ls_codi_bien, @ls_plan_mayor)

			ROLLBACK TRANSACTION
			return -1
		End
	End

	 UPDATE sig_kardex_por_almacen
	    SET cant_ingreso	= @xicant,
		cant_egreso	= @xscant,
		stock_actual	= stock_inicial + @xicant - @xscant,
		precio_promed = @xpp5,
		valor_ingreso = @xivalo, 
		valor_egreso  = @xsvalo, 
		saldo_valor   = saldo_inicial + @xivalo - @xsvalo
	  WHERE ano_eje       = @ai_ano_eje    and
	 	sec_ejec      = @an_sec_ejec   and
		mes_proceso   = @as_mes        and
		almacen       = @as_almacen    and
		sec_almacen   = @as_sec_alma   and
		tipo_bien     = @ls_tipo_bien  and
		codigo_bien   = @ls_codi_bien  and
		marca         = @ld_marca      and
		clasificador  = @ls_clas_gast  and
		mayor         = @ls_plan_mayor and
		sub_cta       = @ls_plan_subcta and
		tipo_uso      = @ls_tipo_uso   and
		tipo_ppto     = @ai_tipo_ppto  and
		secuencia     = @an_encargo    and
		unidad_medida = @ld_unid_medi and
		((@ld_item_bien_det is null and item_bien_det is null) or
		 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

	set @ld_temp = @@rowcount

	IF (@@error <> 0)
	begin
		close cbucle_generico
		DEALLOCATE cbucle_generico
		set @as_message = 'Error al actualizar el Kardex : '
		return -1
	End

	IF (@ld_temp = 0)
	begin
		set @ls_correlativo = ''
		SELECT @ls_correlativo = max(correlativo)
		  FROM sig_kardex_por_almacen
		 WHERE ano_eje       = @ai_ano_eje    and
			sec_ejec      = @an_sec_ejec   and
			mes_proceso   = @as_mes        and
			almacen       = @as_almacen    and
			sec_almacen   = @as_sec_alma   and
			tipo_bien     = @ls_tipo_bien  and
			codigo_bien   = @ls_codi_bien  and
			marca         = @ld_marca      and
			clasificador  = @ls_clas_gast  and
			mayor         = @ls_plan_mayor and
			sub_cta       = @ls_plan_subcta and
			tipo_uso      = @ls_tipo_uso   and
			tipo_ppto     = @ai_tipo_ppto  and
			secuencia     = @an_encargo

		set @ls_correlativo = isnull(@ls_correlativo, '0')
		If (@ls_correlativo = '')
		   set @ls_correlativo = '0'
				 
		set @ls_correlativo = right('0000'+convert(varchar(4), @ls_correlativo*1 + 1),4)

		  INSERT INTO sig_kardex_por_almacen  
			( ano_eje,       sec_ejec,      mes_proceso,   
			  almacen,       sec_almacen,   tipo_bien, codigo_bien,  
			  grupo_bien,    clase_bien,    familia_bien,   
			  item_bien,     marca,         tipo_uso,   
			  tipo_ppto,     secuencia,     nro_encargo,
			  sec_ejec2,	  cant_invent,   cant_bueno,   
			  stock_inicial, cant_ingreso,  cant_egreso,   
			  stock_actual,  precio_promed, saldo_valor,   
			  valor_ingreso, valor_egreso,  saldo_inicial,   
			  stock_enero,   cons_enero,    precio_invent,
			  cuser_id,      fecha_reg,     equipo_reg,
			  activo_fijo,   clasificador,  mayor,
			  sub_cta,       correlativo,	  tipo_marca,
			  unidad_medida, item_bien_det)  
		  VALUES ( @ai_ano_eje,    @an_sec_ejec,   @as_mes,   
			  @as_almacen,    @as_sec_alma,   @ls_tipo_bien, @ls_codi_bien,  
			  @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien,   
			  @ls_item_bien,  @ld_marca,      @ls_tipo_uso,   
			  @ai_tipo_ppto,  @an_encargo,    @ld_encargo,
			  @ld_sec_ejec2,	0,              0,   
			  @xncant,        @xicant,        @xscant,   
			  @xncant + @xicant - @xscant, @xpp5, @xnvalo + @xivalo - @xsvalo,   
			  @xivalo,        @xsvalo,        @xnvalo,   
			  0,              0,              0, 
			  @as_usuing,    @adt_fecha_actual, @as_equipo,
			  @ls_activo_fijo,@ls_clas_gast,  @ls_plan_mayor,
			  @ls_plan_subcta,@ls_correlativo, @ls_tipo_marc,
			  @ld_unid_medi,  @ld_item_bien_det) 

		IF (@@error <> 0)
		begin
			close cbucle_generico
			DEALLOCATE cbucle_generico
			set @as_message = 'Error al insertar en el Kardex : '
			return -1
		End
	End
	
	FETCH NEXT FROM cbucle_generico INTO @ls_tipo_bien, @ls_grupo_bien, @ls_clase_bien, @ls_fami_bien, 
					        @ls_item_bien, @ld_marca, @ls_tipo_uso, @ld_encargo, 
						@ld_sec_ejec2, @ls_activo_fijo, @ls_clas_gast, @ls_plan_mayor,
						@ls_plan_subcta, @ls_tipo_marc, @ld_unid_medi, @ld_item_bien_det
END
CLOSE cbucle_generico
DEALLOCATE cbucle_generico

 DELETE FROM sig_kardex_por_almacen
  WHERE ano_eje       = @ai_ano_eje  and
	sec_ejec     = @an_sec_ejec and
	mes_proceso  = @as_mes      and
	almacen      = @as_almacen  and
	sec_almacen  = @as_sec_alma and
	tipo_uso in ( SELECT DISTINCT d.tipo_uso
			  FROM sig_detalle_movim_almacen d,
			       sig_movim_almacen m
			 WHERE d.ano_eje  = m.ano_eje  and
			       d.sec_ejec = m.sec_ejec and
			       d.almacen  = m.almacen  and
			       d.sec_almacen  = m.sec_almacen  and
			       d.tipo_movimto = m.tipo_movimto and
			       d.tipo_transac = m.tipo_transac and
			       d.tipo_ppto    = m.tipo_ppto    and
			       d.nro_movimto  = m.nro_movimto  and
			       ((@an_nume_movi <> -1) or
			       (@an_nume_movi = -1 and m.estado_kardex= 'S')) and
			       d.ano_eje      = @ai_ano_eje  and
			       d.sec_ejec     = @an_sec_ejec and
			       d.almacen      = @as_almacen  and
			       d.sec_almacen  = @as_sec_alma and
			       d.tipo_movimto in ('A','I','S') and
			       d.tipo_movimto like @as_tipo_movi and
			       ((@an_tipo_tran = -1 ) or
			       (@an_tipo_tran <> -1 and d.tipo_transac = @an_tipo_tran)) and
			       m.tipo_ppto    = @ai_tipo_ppto and
			       ((@an_nume_movi = -1) or
			       (@an_nume_movi <> -1 and d.nro_movimto  = @an_nume_movi)) and
			       d.mes_proceso  = @as_mes      and
			       ((@an_nume_movi = -1 and d.tipo_uso = @as_tipo_uso) or
			       (@an_nume_movi <> -1 and m.tipo_uso = @as_tipo_uso)) and
			       ((@ai_tipo_ppto = 1) or
			       (@ai_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
			       d.cant_articulo >= 0 ) and
	tipo_ppto    = @ai_tipo_ppto and
	secuencia    = @an_encargo  and
	cant_invent  = 0 and
	cant_bueno   = 0 and
	cant_ingreso = 0 and
	cant_egreso  = 0 and
	stock_actual = 0 and
	stock_inicial= 0 

IF (@@error <> 0)
begin
	set @as_message = 'Error al capturar los datos del kardex : '
	return -1
End

 DELETE FROM sig_kardex_por_almacen
  WHERE ano_eje       = @ai_ano_eje  and
	sec_ejec     = @an_sec_ejec and
	mes_proceso  = @as_mes      and
	almacen      = @as_almacen  and
	sec_almacen  = @as_sec_alma and
	tipo_uso  like @as_tipo_uso and
	tipo_ppto    = @ai_tipo_ppto and
	secuencia    = @an_encargo  and
	cant_invent  = 0 and
	cant_bueno   = 0 and
	cant_ingreso = 0 and
	cant_egreso  = 0 and
	stock_actual = 0 and
	stock_inicial= 0 

IF (@@error <> 0)
begin
	set @as_message = 'Error al capturar los datos del kardex (2): '
	return -1
End

set @as_message = 'Concluyó conforme : '

Return 1
END
GO


-- ----------------------------
-- procedure structure for SP_PPR_RECAL_MONTO_REFERENCIAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PPR_RECAL_MONTO_REFERENCIAL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PPR_RECAL_MONTO_REFERENCIAL]
GO

CREATE PROCEDURE [dbo].[SP_PPR_RECAL_MONTO_REFERENCIAL]
(
@al_sec_ejec    NUMERIC(10),
@al_anno_ejec   NUMERIC(10),
@al_error_cod   NUMERIC(10)     OUTPUT,
@as_error_txt   VARCHAR(255)    OUTPUT
)
AS
BEGIN
DECLARE @ll_cont                    NUMERIC(10) 
DECLARE @ll_cur_id_sub_finalidad    NUMERIC(10) 
DECLARE @ll_cur_sec_establec        NUMERIC(10) 
DECLARE @ll_cur_sec_kit             NUMERIC(10) 
DECLARE @ldc_cur_cantidad_meta      NUMERIC(20, 4) 
DECLARE @ldc_cur_precio_ref         NUMERIC(20, 4) 
DECLARE @ldc_cur_cantidad           NUMERIC(20, 4) 
DECLARE @ls_cur_sub_finalidad       VARCHAR(20) 

------------------------------------------
--declaro el cursor principal
------------------------------------------
DECLARE lcur_meta_fisica_subfin CURSOR  FOR
SELECT  DISTINCT
        SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD, SIG_PPR_METFIS_X_SUBFIN.ID_SUB_FINALIDAD,
        SIG_PPR_METFIS_X_SUBFIN.CANTIDAD, SIG_PPR_SEDE.SEC_ESTABLEC
FROM    SIG_PPR_METFIS_X_SUBFIN, SIG_PPR_SEDE
WHERE   SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC        = @al_sec_ejec
AND     SIG_PPR_METFIS_X_SUBFIN.ANO_EJE         = @al_anno_ejec
------------------------------------------
AND     SIG_PPR_METFIS_X_SUBFIN.ANO_EJE         = SIG_PPR_SEDE.ANO_EJE
AND     SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC        = SIG_PPR_SEDE.SEC_EJEC
AND     SIG_PPR_METFIS_X_SUBFIN.SEC_ESTABLEC    = SIG_PPR_SEDE.SEC_ESTABLEC 

------------------------------------------
--barro el cursor principal
------------------------------------------
OPEN    lcur_meta_fisica_subfin 
WHILE   1 = 1
BEGIN
    FETCH   lcur_meta_fisica_subfin
    INTO    @ls_cur_sub_finalidad, @ll_cur_id_sub_finalidad,
            @ldc_cur_cantidad_meta, @ll_cur_sec_establec 
    IF  @@FETCH_STATUS <> 0
    BEGIN
        BREAK 
    END 

    ------------------------------------------
    --declaro el cursor de los valores para el kit
    ------------------------------------------
    DECLARE lcur_kit_cantidad_monto CURSOR  FOR
    SELECT  SIG_PPR_KIT_ITEMS_EST.SEC_KIT, SIG_PPR_KIT_ITEMS_EST.CANTIDAD,
            SIG_CATALOGO_BIEN_SERV_PRECIO.PRECIO_REF
    FROM    SIG_PPR_KIT_ITEMS_EST, SI_PPR_KIT_ITEMS, SIG_CATALOGO_BIEN_SERV_PRECIO
    WHERE   SI_PPR_KIT_ITEMS.ANO_EJE            = SIG_PPR_KIT_ITEMS_EST.ANO_EJE
    AND     SI_PPR_KIT_ITEMS.SEC_KIT            = SIG_PPR_KIT_ITEMS_EST.SEC_KIT
    AND     SI_PPR_KIT_ITEMS.ID_SUB_FINALIDAD   = SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD
    AND     SIG_PPR_KIT_ITEMS_EST.SEC_EJEC      = @al_sec_ejec
    AND     SIG_PPR_KIT_ITEMS_EST.ANO_EJE       = @al_anno_ejec
    AND     SI_PPR_KIT_ITEMS.SUB_FINALIDAD      = @ls_cur_sub_finalidad
    AND     SI_PPR_KIT_ITEMS.ID_SUB_FINALIDAD   = @ll_cur_id_sub_finalidad
    AND     SIG_PPR_KIT_ITEMS_EST.COD_ESTABLEC  = @ll_cur_sec_establec
    AND     SI_PPR_KIT_ITEMS.TIPO_BIEN          <> 'O'
    AND     SIG_PPR_KIT_ITEMS_EST.ESTADO        = 'A'
    AND     SI_PPR_KIT_ITEMS.ESTADO             = 'A'
    AND     SIG_PPR_KIT_ITEMS_EST.SEC_EJEC      = SIG_CATALOGO_BIEN_SERV_PRECIO.SEC_EJEC
    AND     SIG_PPR_KIT_ITEMS_EST.ANO_EJE       = SIG_CATALOGO_BIEN_SERV_PRECIO.ANO_EJE
    AND     SI_PPR_KIT_ITEMS.TIPO_BIEN          = SIG_CATALOGO_BIEN_SERV_PRECIO.TIPO_BIEN
    AND     SI_PPR_KIT_ITEMS.GRUPO_BIEN         = SIG_CATALOGO_BIEN_SERV_PRECIO.GRUPO_BIEN
    AND     SI_PPR_KIT_ITEMS.CLASE_BIEN         = SIG_CATALOGO_BIEN_SERV_PRECIO.CLASE_BIEN
    AND     SI_PPR_KIT_ITEMS.FAMILIA_BIEN       = SIG_CATALOGO_BIEN_SERV_PRECIO.FAMILIA_BIEN
    AND     SI_PPR_KIT_ITEMS.ITEM               = SIG_CATALOGO_BIEN_SERV_PRECIO.ITEM_BIEN
    AND     SI_PPR_KIT_ITEMS.TIPO_CALCULO       = 4 

    ------------------------------------------
    --barro el cursor del detalle por cada kit
    ------------------------------------------
    OPEN    lcur_kit_cantidad_monto 
    WHILE   1 = 1
    BEGIN
        FETCH   lcur_kit_cantidad_monto
        INTO    @ll_cur_sec_kit, @ldc_cur_cantidad,
                @ldc_cur_precio_ref 
        IF  @@FETCH_STATUS <> 0
        BEGIN
            BREAK 
        END 

        --calculo los kits
        SELECT  @ldc_cur_cantidad   = CEILING(@ldc_cur_cantidad * @ldc_cur_cantidad_meta) 

        --actualizo el kit
        UPDATE  SIG_PPR_KIT_ITEMS_EST
        SET     PRECIO_REF          = @ldc_cur_precio_ref,
                CANT_KITS           = @ldc_cur_cantidad,
                MNTO_KITS           = @ldc_cur_cantidad * @ldc_cur_precio_ref
        WHERE   SEC_EJEC            = @al_sec_ejec
        AND     ANO_EJE             = @al_anno_ejec
        AND     ID_SUB_FINALIDAD    = @ll_cur_id_sub_finalidad
        AND     COD_ESTABLEC        = @ll_cur_sec_establec
        AND     SEC_KIT             = @ll_cur_sec_kit 
    END 
    CLOSE       lcur_kit_cantidad_monto 
    DEALLOCATE  lcur_kit_cantidad_monto 
END 
CLOSE       lcur_meta_fisica_subfin 
DEALLOCATE  lcur_meta_fisica_subfin 

END
GO


