 A.PROGRAMA =  sig_techo_presupuesto.PROGRAMA AND  
 A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND  
 A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND  
 A.indicador     ='0' and  
 A.flag_meta_aprob = '0' AND  
 A.FASE_CUADRO = 1)  
 where   
 ano_eje = @PN_ANIO and  
 sec_ejec = @PN_EJEC AND  
 indicador     ='4' and  
 flag_meta_aprob = '0' AND  
 FASE_CUADRO = 1  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
END  
  
  
  
IF @ls_flag_gen_esp <> '0'   
BEGIN  
  
 insert into tmp_techo_fase_7  
 ( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, FUNCION, PROGRAMA, SEC_FUNC_PROP, CENTRO_COSTO_PRESUP, CLASIFICADOR)  
 SELECT DISTINCT b.origen, b.fuente_financ,  
 (  
  SELECT  sum(mnto_progra)   
  FROM sig_techo_presupuesto  a  
  WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND  
         a.origen   = b.origen and a.fuente_financ = b.fuente_financ and  
         A.CATEG_GASTO = B.CATEG_GASTO AND A.GRUPO_GASTO =B.GRUPO_GASTO AND  
         A.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND  
         A.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND  
         A.CLASIFICADOR = B.CLASIFICADOR AND  
         a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1  
 )   
 as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.FUNCION, B.PROGRAMA, B.SEC_FUNC_PROP,  
 B.CENTRO_COSTO_PRESUP, B.CLASIFICADOR  
 FROM sig_techo_presupuesto b  
 WHERE  b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND  
  b.indicador     = '0' and b.flag_meta_aprob = '0' and  
  B.FASE_CUADRO = 1 AND  
  not exists ( select '1'  
           FROM sig_techo_presupuesto c  
        WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND  
       c.origen    = b.origen and c.fuente_financ = b.fuente_financ and  
       C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND  
       C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND  
       C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND  
       C.CLASIFICADOR = B.CLASIFICADOR AND  
       c.FASE_CUADRO = 1 AND  
       c.indicador     ='5' and c.flag_meta_aprob = '0')  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
  
 SELECT @li_secuencia = ISNULL(MAX(secuencia),0)   
 FROM sig_techo_presupuesto   
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC  
  
 insert INTO sig_techo_presupuesto    
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,  
 secuencia    , categ_gasto   , grupo_gasto    , clasificador,   
 funcion      , programa      , sec_func       , centro_costo,   
 ppto_progra  , ppto_aprob  , ppto_asignado , ppto_modif,  
 mnto_progra  , mnto_asig  , mnto_aprob     , mnto_modif,  
 indicador   , paac_inicial  , paac_modif     , porc_techo ,   
 porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,  
 FASE_CUADRO )  
   select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,  
 ( @li_secuencia + secuencia ) , CATEG_GASTO, GRUPO_GASTO , CLASIFICADOR,  
 FUNCION ,PROGRAMA , NULL , NULL,  
 0 , 0 , 0 , 0 ,  
 mnto_progra,0, 0, 0 ,  
 '5' ,0, 0 , 0 ,  
 0 , SEC_FUNC_PROP , '0' , CENTRO_COSTO_PRESUP, 1  
 from tmp_techo_fase_7  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
 update sig_techo_presupuesto  
 set mnto_progra = ( SELECT SUM(A.MNTO_PROGRA) FROM SIG_TECHO_PRESUPUESTO A  
 where   
 A.ano_eje = @PN_ANIO and  
 A.sec_ejec = @PN_EJEC AND  
 A.origen    = sig_techo_presupuesto.ORIGEN AND  
 A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND  
 A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND  
 A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND  
 A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND  
 A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND  
 A.CLASIFICADOR =  sig_techo_presupuesto.CLASIFICADOR AND  
 A.indicador     ='0' and  
 A.flag_meta_aprob = '0' AND  
 A.FASE_CUADRO = 1)  
 where   
 ano_eje = @PN_ANIO and  
 sec_ejec = @PN_EJEC AND  
 indicador     ='5' and  
 flag_meta_aprob = '0' AND  
 FASE_CUADRO = 1  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
 insert into tmp_techo_fase_8  
 ( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, FUNCION, PROGRAMA, SEC_FUNC_PROP, CENTRO_COSTO_PRESUP)  
 SELECT DISTINCT b.origen, b.fuente_financ,  
 (  
  SELECT  sum(mnto_progra)   
  FROM sig_techo_presupuesto  a  
  WHERE  a.ano_eje  = b.ano_eje  and a.sec_ejec = b.sec_ejec AND  
         a.origen   = b.origen and a.fuente_financ = b.fuente_financ and  
         A.CATEG_GASTO = B.CATEG_GASTO AND A.GRUPO_GASTO =B.GRUPO_GASTO AND  
         A.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND  
         A.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND  
         a.indicador='0' and a.flag_meta_aprob = '0' and fase_cuadro = 1  
 )   
 as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.FUNCION, B.PROGRAMA, B.SEC_FUNC_PROP,  
 B.CENTRO_COSTO_PRESUP  
 FROM sig_techo_presupuesto b  
 WHERE  b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND  
  b.indicador     = '0' and b.flag_meta_aprob = '0' and  
  B.FASE_CUADRO = 1 AND  
  not exists ( select '1'  
           FROM sig_techo_presupuesto c  
        WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND  
       c.origen    = b.origen and c.fuente_financ = b.fuente_financ and  
       C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND  
       C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND  
       C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND  
       c.FASE_CUADRO = 1 AND  
       c.indicador     ='4' and c.flag_meta_aprob = '0')  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
 SELECT @li_secuencia = ISNULL(MAX(secuencia),0)   
 FROM sig_techo_presupuesto   
 WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC  
  
 insert INTO sig_techo_presupuesto    
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,  
 secuencia    , categ_gasto   , grupo_gasto    , clasificador,   
 funcion      , programa      , sec_func       , centro_costo,   
 ppto_progra  , ppto_aprob  , ppto_asignado , ppto_modif,  
 mnto_progra  , mnto_asig  , mnto_aprob     , mnto_modif,  
 indicador   , paac_inicial  , paac_modif     , porc_techo ,   
 porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,  
 FASE_CUADRO )  
   select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,  
 ( @li_secuencia + secuencia ) , CATEG_GASTO, GRUPO_GASTO , NULL,  
 FUNCION ,PROGRAMA , NULL , NULL,  
 0 , 0 , 0 , 0 ,  
 mnto_progra,0, 0, 0 ,  
 '4' ,0, 0 , 0 ,  
 0 , SEC_FUNC_PROP , '0' , CENTRO_COSTO_PRESUP, 1  
 from tmp_techo_fase_8  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
 update sig_techo_presupuesto  
 set mnto_progra = ( SELECT SUM(A.MNTO_PROGRA) FROM SIG_TECHO_PRESUPUESTO A  
 where   
 A.ano_eje = @PN_ANIO and  
 A.sec_ejec = @PN_EJEC AND  
 A.origen    = sig_techo_presupuesto.ORIGEN AND  
 A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND  
 A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND  
 A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND  
 A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND  
 A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND  
 A.indicador     ='0' and  
 A.flag_meta_aprob = '0' AND  
 A.FASE_CUADRO = 1)  
 where   
 ano_eje = @PN_ANIO and  
 sec_ejec = @PN_EJEC AND  
 indicador     ='4' and  
 flag_meta_aprob = '0' AND  
 FASE_CUADRO = 1  
  
 IF @@ERROR <> 0  
 BEGIN  
  return -1  
 END  
  
END  
  
TRUNCATE TABLE dbo.tmp_techo_cn_fase   
TRUNCATE TABLE dbo.tmp_propuesta_fase   
TRUNCATE TABLE dbo.tmp_techo_fase_2   
TRUNCATE TABLE dbo.tmp_techo_fase_3  
TRUNCATE TABLE dbo.tmp_techo_fase_4  
TRUNCATE TABLE dbo.tmp_techo_fase_5  
TRUNCATE TABLE dbo.tmp_techo_fase_6  
TRUNCATE TABLE dbo.tmp_techo_fase_7  
TRUNCATE TABLE dbo.tmp_techo_fase_8  
  
  
RETURN 1  
  
END;--/
GO


-- ----------------------------
-- procedure structure for DT_GENERATEANSINAME
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_GENERATEANSINAME]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_GENERATEANSINAME]
GO

CREATE PROCEDURE [dbo].[DT_GENERATEANSINAME](@name varchar(255) output) 
as 
	declare @prologue varchar(20) 
	declare @indexstring varchar(20) 
	declare @index integer 
 
	set @prologue = 'MSDT-A-' 
	set @index = 1 
 
	while 1 = 1 
	begin 
		set @indexstring = cast(@index as varchar(20)) 
		set @name = @prologue + @indexstring 
		if not exists (select value from dtproperties where value = @name) 
			break 
		 
		set @index = @index + 1 
 
		if (@index = 10000) 
			goto TooMany 
	end 
 
Leave: 
 
	return 
 
TooMany: 
 
	set @name = 'DIAGRAM' 
	goto Leave
GO


