                    sig_techo_presupuesto.indicador       = '0' and
                    sig_techo_presupuesto.flag_meta_aprob = '0'
                    )

     IF @@ERROR <> 0
     BEGIN
	  return -1
     END

IF  @ls_flag_techo = '1'
BEGIN
     DECLARE c_0b cursor for
     
     SELECT DISTINCT centro_costo
       FROM sig_techo_presupuesto
      WHERE ano_eje     = @PN_ANIO and
            sec_ejec    = @PN_EJEC and
            fase_cuadro = @PN_FASE and
            indicador   = '0'      and
            flag_meta_aprob = '0'  and
            centro_costo_presup is null
     
     open c_0b
     fetch c_0b into @ls_centro_costo
    
     WHILE @@FETCH_STATUS = 0
     BEGIN
          SELECT @ls_centro_costo_cambio = @ls_centro_costo
          SELECT @ls_flag_presup = 'N'
          
          WHILE @ls_flag_presup = 'N'
          BEGIN
               SELECT @ls_centro_padre = centro_padre,
                      @ls_flag_presup  = flag_presupuesto
                 FROM sig_centro_costo
                WHERE ano_eje  = @PN_ANIO and
                      sec_ejec = @PN_EJEC and
                      centro_costo = @ls_centro_costo_cambio
               
               If (@ls_flag_presup IS NULL) or (@ls_flag_presup = '')
               BEGIN
                    SELECT @ls_flag_presup = 'N'
               END
               
               IF upper(@ls_flag_presup) <> 'S' 
               BEGIN
                    IF (@ls_centro_padre IS NULL) or (@ls_centro_padre = '') 
                    BEGIN
                         SELECT @ls_flag_presup = 'S'
                         SELECT @ls_centro_costo_presup = ''
                    END
                    
                    ELSE
                    BEGIN
                         SELECT @ls_centro_costo_cambio = @ls_centro_padre
                         SELECT @ls_flag_presup = 'N'
                    END
               END
               
	       ELSE
	       BEGIN
	            SELECT @ls_flag_presup = 'S'
	            SELECT @ls_centro_costo_presup = @ls_centro_costo_cambio
	       END
          END
          
            UPDATE sig_techo_presupuesto
            SET centro_costo_presup = @ls_centro_costo_presup
            WHERE   ano_eje         = @PN_ANIO 
            and     sec_ejec        = @PN_EJEC 
            and     fase_cuadro     = @PN_FASE 
            and     centro_costo    = @ls_centro_costo 
            and     flag_meta_aprob = '0' 
            and     indicador       = '0' 
            and     centro_costo_presup is null

          IF @@ERROR <> 0
          BEGIN
	       CLOSE c_0b
	       DEALLOCATE c_0b
               
	       return -1
          END
          
          fetch c_0b into @ls_centro_costo
     END
     
     CLOSE c_0b
     DEALLOCATE c_0b
END

ELSE
BEGIN
     UPDATE sig_techo_presupuesto
        SET centro_costo_presup = centro_costo
      WHERE ano_eje     = @PN_ANIO and
            sec_ejec    = @PN_EJEC and
            fase_cuadro = @PN_FASE and
            flag_meta_aprob = '0'  and
            indicador       = '0'  and
            centro_costo_presup is null   	
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
END

SELECT @li_secuencia = IsNull(MAX(secuencia), 0)
  FROM sig_techo_presupuesto 
 WHERE ano_eje  = @PN_ANIO and
       sec_ejec = @PN_EJEC

INSERT INTO #tmp_techo_fase_2
            (origen ,fuente_financ , mnto_progra , fase_cuadro)
     SELECT DISTINCT
            b.origen, b.fuente_financ, 0, @PN_FASE
       FROM sig_techo_presupuesto b
      WHERE b.ano_eje     = @PN_ANIO and
            b.sec_ejec    = @PN_EJEC and
            b.fase_cuadro = @PN_FASE and
b.indicador   = '0'      and
            b.flag_meta_aprob = '0'  and
            not exists (SELECT '1'
                          FROM sig_techo_presupuesto c
                         WHERE c.ano_eje     = b.ano_eje  and
                               c.sec_ejec    = b.sec_ejec and
                               c.fase_cuadro = @PN_FASE   and
                               c.origen      = b.origen   and
                               c.fuente_financ   = b.fuente_financ and
                               c.indicador       = '1' and
                               c.flag_meta_aprob = '0')

IF @@ERROR <> 0
BEGIN
     return -1
END

INSERT INTO sig_techo_presupuesto
            (ano_eje    , sec_ejec    , origen      , fuente_financ, secuencia ,
             categ_gasto, grupo_gasto , clasificador,
             sec_func   , centro_costo, ppto_progra , ppto_aprob, ppto_asignado,
             ppto_modif , mnto_progra , mnto_asig   , mnto_aprob, mnto_modif   ,
             indicador  , paac_inicial, paac_modif  , porc_techo, porc_asig    ,
             sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)
     SELECT @PN_ANIO, @PN_EJEC, origen, fuente_financ, (@li_secuencia + secuencia ),
            NULL, NULL, NULL,
            NULL , NULL, 0, 0, 0,
            0, mnto_progra, 0, 0, 0 ,
            '1', 0, 0, 0, 0,
            NULL, '0', NULL, @PN_FASE
       FROM #tmp_techo_fase_2

IF @@ERROR <> 0
BEGIN
     return -1
END

