                                A.flag_meta_aprob = '0'),
		MNTO_PREVISION4 = (SELECT SUM(COALESCE(A.MNTO_PREVISION4, 0))
                           FROM sig_techo_presupuesto A
                          WHERE A.ano_eje     = @PN_ANIO and
                                A.sec_ejec    = @PN_EJEC and
                                A.fase_cuadro = @PN_FASE and
                                A.origen      = sig_techo_presupuesto.origen and
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and
                                A.clasificador  =  sig_techo_presupuesto.clasificador and
                                A.indicador       = '0' and
                                A.flag_meta_aprob = '0')
      WHERE ano_eje     = @PN_ANIO and
            sec_ejec    = @PN_EJEC and
            fase_cuadro = @PN_FASE and
            indicador   = '5'      and
            flag_meta_aprob = '0'
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     INSERT INTO #tmp_techo_fase_8
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,
                  sec_func_prop, centro_costo_presup)
          SELECT DISTINCT
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,
                 b.sec_func_prop, b.centro_costo_presup
            FROM sig_techo_presupuesto b
           WHERE b.ano_eje     = @PN_ANIO and
                 b.sec_ejec    = @PN_EJEC and
                 b.fase_cuadro = @PN_FASE and
                 b.indicador   = '0'      and
                 b.flag_meta_aprob = '0'  and
                 not exists (SELECT '1'
                               FROM sig_techo_presupuesto c
                              WHERE c.ano_eje     = b.ano_eje  and
                     c.sec_ejec    = b.sec_ejec and
                                    c.fase_cuadro = @PN_FASE   and
                                    c.origen      = b.origen   and
                                    c.fuente_financ = b.fuente_financ and
                                    c.categ_gasto   = b.categ_gasto   and
                                    c.grupo_gasto   = b.grupo_gasto   and
                                    c.sec_func_prop = b.sec_func_prop and
                                    c.centro_costo_presup = b.centro_costo_presup and
                                    c.indicador       = '4' and
                                    c.flag_meta_aprob = '0')
     
     IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
     SELECT @li_secuencia = max(secuencia) 
       FROM sig_techo_presupuesto 
      WHERE ano_eje  = @PN_ANIO and
            sec_ejec = @PN_EJEC
     
     INSERT INTO sig_techo_presupuesto
                 (ano_eje      , sec_ejec       , origen      , fuente_financ, secuencia    ,
                  categ_gasto  , grupo_gasto    , clasificador,
                  sec_func     , centro_costo   , ppto_progra , ppto_aprob   , ppto_asignado,
                  ppto_modif   , mnto_progra    , mnto_asig   , mnto_aprob   , mnto_modif   ,
                  indicador    , paac_inicial   , paac_modif  , porc_techo   , porc_asig    ,
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)
          SELECT @PN_ANIO, @PN_EJEC, origen, fuente_financ, (@li_secuencia + secuencia),
                 categ_gasto, grupo_gasto, NULL, NULL, NULL,
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '4', 0, 0, 0,
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE
            FROM #tmp_techo_fase_8
     
     IF @@ERROR <> 0
