                                A.origen      = sig_techo_presupuesto.origen and
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and
                                A.indicador       = '0' and
                                A.flag_meta_aprob = '0'),
            MNTO_OPAGO3 = (SELECT SUM(COALESCE(A.MNTO_OPAGO3, 0))
                           FROM sig_techo_PRESUPUESTO A
                          WHERE A.ano_eje     = @PN_ANIO and
                                A.sec_ejec    = @PN_EJEC and
                                A.fase_cuadro = @PN_FASE and
