-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_PLAN_REQUERIMIENTO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_PLAN_REQUERIMIENTO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_PLAN_REQUERIMIENTO]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_PLAN_REQUERIMIENTO]
AS
BEGIN  
	TRUNCATE TABLE TA_PLAN_REQUERIMIENTO
	INSERT INTO TA_PLAN_REQUERIMIENTO (
		ANO_EJE,			SEC_EJEC,		C_SEC_EJEC,		NRO_FASE,
		PROG_ESTRATEGICO,		FUNCION,		                PROGRAMA,		SUB_PROGRAMA,
		ACT_PROY,			COMPONENTE,		C_FINALIDAD,		C_SUB_FINALIDAD,
		SEDE,				D_SEDE,			C_EESS,			C_ESTABLEC,
		C_CATEGORIA_EESS,		D_CATEGORIA_EESS,	META_FISICA,		C_CENTRO_COSTO,
		D_CENTRO_COSTO,		C_TIPO_ITEM,		CODIGO_BIEN,		PREC_UNITARIO,
		CANT_COMPRA,			PREC_COMPRA,		      PRECIO_MAXIMO,		PRECIO_MINIMO,
		PRECIO_PROMEDIO,		PRECIO_DESV_EST,	      C_EspecificaDet,	                C_FUENTE_FINANC,
		TIPO_COSTO_DI,			TIPO_COSTO_FV,		      TIPO_COSTO_DIK,		TIPO_COSTO_T4,
		TIPO_COSTO_T3,			TIPO_CALCULO,		      AGRUPA_ITEM,		                UM_USO,
		CANTIDAD_VEZ,			NRO_VECES,		      CANTIDAD_CASO,		PORCENT_USO,
		FACTOR_CONVERS,		FACTOR_MERMA,		      CAT_REQ_UM_USO,	                CAT_REQ_UM_LOG,
		CANT_COMPRA_CALCULADO,	PREC_COMPRA_CALCULADO)
	
		SELECT  
		dbo.SI_PROGRAMACION_TRX.ANO_EJE, 
        dbo.SI_PROGRAMACION_TRX.SEC_EJEC, 
        RIGHT('000000' + CAST(dbo.SI_PROGRAMACION_TRX.SEC_EJEC AS VARCHAR(6)),6) AS C_SEC_EJEC, 
        dbo.SI_PROGRAMACION_TRX.NRO_FASE, 
        dbo.SI_PROGRAMACION_TRX.ESTRATEGIA_NACIONAL AS PROG_ESTRATEGICO,	
        dbo.SI_PROGRAMACION_TRX.FUNCION, 
        dbo.SI_PROGRAMACION_TRX.PROGRAMA, 
        dbo.SI_PROGRAMACION_TRX.SUB_PROGRAMA, 
        dbo.SI_PROGRAMACION_TRX.ACT_PROY, 
        dbo.SI_PROGRAMACION_TRX.COMPONENTE, 
        dbo.SI_PROGRAMACION_TRX.FINALIDAD, 
        dbo.SI_PROGRAMACION_TRX.SUB_FINALIDAD, 
        dbo.SI_PROGRAMACION_TRX.SEDE, 
        dbo.SI_PROGRAMACION_TRX.D_SEDE, 
        dbo.SI_PROGRAMACION_TRX.COD_ESTABLEC			AS C_EESS, 
        RIGHT('000000' + CAST(dbo.SI_PROGRAMACION_TRX.COD_ESTABLEC AS VARCHAR(6)),6) AS C_ESTABLEC, 
        dbo.SI_PROGRAMACION_TRX.COD_CATEGORIA			AS C_CATEGORIA_EESS, 
        dbo.SI_PROGRAMACION_TRX.D_CORTO_COD_CATEGORIA	AS D_CATEGORIA_EESS, 
        dbo.SI_PROGRAMACION_TRX.CANTIDAD				AS META_FISICA,
        dbo.SI_PROGRAMACION_DETA_TRX.CENTRO_COSTO		AS C_CENTRO_COSTO, 
        dbo.SI_PROGRAMACION_DETA_TRX.D_CENTRO_COSTO, 
        dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN			AS C_TIPO_ITEM, 
        dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO		AS CODIGO_BIEN, 
        dbo.SI_PROGRAMACION_DETA_TRX.PRECIO_REF			AS PREC_UNITARIO, 
        dbo.SI_PROGRAMACION_DETA_TRX.CANT_COMPRA, 
        dbo.SI_PROGRAMACION_DETA_TRX.PREC_COMPRA,
          (SELECT     MAX(PRECIO_UNITARIO) FROM  dbo.TA_PRECIOS 
			WHERE      (TIPO_BIEN = dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN) AND 
                       (ITEM_CATALOGO = dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO)) AS PRECIO_MAXIMO,
          (SELECT     MIN(PRECIO_UNITARIO) FROM  dbo.TA_PRECIOS
            WHERE      (TIPO_BIEN = dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN) AND 
                       (ITEM_CATALOGO = dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO)) AS PRECIO_MINIMO,
          (SELECT     AVG(PRECIO_UNITARIO) FROM  dbo.TA_PRECIOS
            WHERE      (TIPO_BIEN = dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN) AND 
                       (ITEM_CATALOGO = dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO)) AS PRECIO_PROMEDIO,
          (SELECT     STDEV(PRECIO_UNITARIO) FROM   dbo.TA_PRECIOS
            WHERE      (TIPO_BIEN = dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN) AND 
                       (ITEM_CATALOGO = dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO)) AS PRECIO_DESV_EST, 
          dbo.SI_PROGRAMACION_DETA_TRX.CLASIFICADOR, 
          dbo.SI_PROGRAMACION_DETA_TRX.ORIGEN_FUENTE AS C_FUENTE_FINANC, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_COSTO_DI, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_COSTO_FV, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_COSTO_DIK, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_COSTO_T4, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_COSTO_T3, 
          dbo.SI_PPR_KIT_ITEMS.TIPO_CALCULO,
          dbo.SI_PPR_KIT_ITEMS.AGRUPA_ITEM,
          dbo.SI_PPR_KIT_ITEMS.UM_USO,
          dbo.SI_PPR_KIT_ITEMS.CANTIDAD_VEZ,
          dbo.SI_PPR_KIT_ITEMS.NRO_VECES,
          dbo.SI_PPR_KIT_ITEMS.CANTIDAD_CASO,
          dbo.SI_PPR_KIT_ITEMS.PORCENT_USO,
          dbo.SI_PPR_KIT_ITEMS.FACTOR_CONVERS,
          dbo.SI_PPR_KIT_ITEMS.FACTOR_MERMA,
          dbo.SI_PPR_KIT_ITEMS.CAT_REQ_UM_USO,
          dbo.SI_PPR_KIT_ITEMS.CAT_REQ_UM_LOG,0,0
		  FROM  dbo.SI_PROGRAMACION_TRX 
				INNER JOIN dbo.SI_PROGRAMACION_DETA_TRX ON 
						dbo.SI_PROGRAMACION_TRX.ANO_EJE = dbo.SI_PROGRAMACION_DETA_TRX.ANO_EJE AND 
						dbo.SI_PROGRAMACION_TRX.SEC_EJEC = dbo.SI_PROGRAMACION_DETA_TRX.SEC_EJEC AND 
						dbo.SI_PROGRAMACION_TRX.ID_SI_PROGRAMACION = dbo.SI_PROGRAMACION_DETA_TRX.ID_SI_PROGRAMACION AND 
						dbo.SI_PROGRAMACION_TRX.ANO_EJE = dbo.SI_PROGRAMACION_DETA_TRX.ANO_EJE AND 
						dbo.SI_PROGRAMACION_TRX.SEC_EJEC = dbo.SI_PROGRAMACION_DETA_TRX.SEC_EJEC AND 
						dbo.SI_PROGRAMACION_TRX.ID_SI_PROGRAMACION = dbo.SI_PROGRAMACION_DETA_TRX.ID_SI_PROGRAMACION 
				INNER JOIN dbo.SI_PPR_KIT_ITEMS ON 
				dbo.SI_PROGRAMACION_DETA_TRX.TIPO_BIEN = dbo.SI_PPR_KIT_ITEMS.TIPO_BIEN AND 
				substring(dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO,1,2) = dbo.SI_PPR_KIT_ITEMS.GRUPO_BIEN AND 
				substring(dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO,3,2) = dbo.SI_PPR_KIT_ITEMS.CLASE_BIEN AND 
				substring(dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO,5,4) = dbo.SI_PPR_KIT_ITEMS.FAMILIA_BIEN AND 
				substring(dbo.SI_PROGRAMACION_DETA_TRX.ITEM_CATALOGO,9,4) = dbo.SI_PPR_KIT_ITEMS.ITEM AND 
				dbo.SI_PROGRAMACION_TRX.SUB_FINALIDAD = dbo.SI_PPR_KIT_ITEMS.SUB_FINALIDAD
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_PERSONAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_PERSONAL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_PERSONAL]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_PERSONAL]
AS
BEGIN  
		DELETE FROM TA_PERSONAL
		INSERT INTO TA_PERSONAL(
			C_SECTOR,		   C_PLIEGO,			 SEC_EJEC,				SEDE,				NOMBRE_SEDE,
			COD_ESTABLEC,	   COD_INTERNO,			 DESC_ESTABLEC,			CATEGORIA,			D_CATEGORIA,
			ID_PERSONAL,	   D_CENTRO_COSTO,		 CENTRO_COSTO,			EMPLEADO,			D_EMPLEADO,
			GRADO_INSTRUCCION, D_GRADO_INSTRUCCION,  D_TIPO_DOCUMENTO,		D_NRO_DOCUMENTO,
			PROFESION,		   D_PROFESION,			 TIPO_EMPLEADO)

		SELECT 
		EJE.C_SECTOR,
		EJE.C_PLIEGO, 
		P.SEC_EJEC,
		CC.SEDE,
		CC.NOMBRE_SEDE,
		CC.COD_ESTABLEC,
		CC.COD_INTERNO,
		CC.DESC_ESTABLEC,
		CC.CATEGORIA,
		CC.D_CATEGORIA,
		P.ID_PERSONAL,
		P.D_CENTRO_COSTO,
		P.CENTRO_COSTO,
		P.EMPLEADO,
		P.D_EMPLEADO,
		P.GRADO_INSTRUCCION,
		P.D_GRADO_INSTRUCCION,
		P.D_TIPO_DOCUMENTO,
		P.D_NRO_DOCUMENTO,
		P.PROFESION,
		P.D_PROFESION,
		P.TIPO_EMPLEADO 
		FROM SI_PERSONAL_TRX P LEFT OUTER JOIN
			 SIG_CENTRO_COSTO_TRX CC ON
				(CC.CENTRO_COSTO = P.CENTRO_COSTO AND
				 CC.SEC_EJEC = P.SEC_EJEC AND
				 CC.ANO_EJE = P.ANO_EJE ) LEFT OUTER JOIN
				TA_EJECUTORA EJE ON
				EJE.SEC_EJEC = P.SEC_EJEC
END
GO


