-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_CONTRATISTA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_CONTRATISTA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_CONTRATISTA]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_CONTRATISTA]
    @P_ANO_EJE   	    	NUMERIC(4,0),
    @P_SEC_EJEC   	    	VARCHAR(10),
    @fecha_carga_inicio     	VARCHAR(10),
    @fecha_carga_fin        	VARCHAR(10),
    @usuario_n              	VARCHAR(50)
AS
	DECLARE @fecha_carga_inicio_1     DATETIME  
	DECLARE @fecha_carga_fin_1        DATETIME  

BEGIN  
 	TRUNCATE TABLE SI_CONTRATISTA  
    	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    	SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

	INSERT INTO SI_CONTRATISTA(
		ANO_EJE, SEC_EJEC, PROVEEDOR, ESTADO, NRO_RUC, GIRO_GENERAL,
		NOMBRE_PROV, TELEFONOS, TELEFONO_FAX, EMAIL, DIRECCION,
		PAIS, DEPARTAMENTO, PROVINCIA, DISTRITO, NRO_RNP,
		FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
	SELECT @P_ANO_EJE, @P_SEC_EJEC, PROVEEDOR, ESTADO, 
		NRO_RUC, GIRO_GENERAL, 
		NOMBRE_PROV, TELEFONOS, TELEFONO_FAX, 
		EMAIL, DIRECCION, PAIS, DEPARTAMENTO, 
		PROVINCIA, DISTRITO, NRO_RNP, @fecha_carga_inicio_1, @fecha_carga_fin_1, 
		convert(varchar(10),getdate(),112), @usuario_n
		FROM SIG_CONTRATISTAS

END
GO


-- ----------------------------
-- procedure structure for SP_SI_TRANSMISION_PECOSA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_TRANSMISION_PECOSA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_TRANSMISION_PECOSA]
GO

CREATE PROCEDURE [dbo].[SP_SI_TRANSMISION_PECOSA]
@P_ANO_EJE numeric(4, 0), @P_SEC_EJEC numeric(6, 0), @O_ERR_NUM numeric(6, 0) OUTPUT, @O_ERR_MSG varchar(255) OUTPUT
WITH EXEC AS CALLER
AS
BEGIN 	
 	
 	IF OBJECT_ID ('dbo.tmp_si_pedido') IS NOT NULL
	DROP TABLE dbo.tmp_si_pedido

	Truncate  TABLE  dbo.SI_TRANS_PEDIDO
 	    
 	SELECT A.ANO_EJE,
 	       dsd.sector,
 	       dsd.SECTOR + ' - ' + RTRIM(S.NOMBRE) NOM_SECTOR,
 	       dsd.pliego PLIEGO,
 	       RTRIM(DSD.pliego + ' - ' + P.nombre) NOM_PLIEGO,
 	       A.SEC_EJEC,
 	       CONVERT(VARCHAR, EJC.sec_ejec) + ' - ' + EJC.nombre NOM_EJECUTORA,
 	       A.MES_PEDIDO MES_PECOSA,
 	       A.TIPO_USO,
 	       A.TIPO_TAREA TAREA_TIPO,
 	       A.NIVEL_TAREA,
 	       A.CODIGO_TAREA,
 	       SCC.CENTRO_COSTO,
 	       SCC.CENTRO_COSTO+' - '+SCC.ABREVIADO_DEPEND NOM_CENTRO_COSTO, 	       
 	       A.TIPO_BIEN,
 	       DP.GRUPO_BIEN,
 	       DP.CLASE_BIEN,
 	       DP.FAMILIA_BIEN,
 	       DP.ITEM_BIEN,
 	       DP.UNIDAD_MEDIDA,
 	       DP.NRO_PECOSA,
 	       DP.NRO_PEDIDO,
 	       DP.FECHA_PECOSA,
 	       A.FECHA_PEDIDO,
 	       DP.CANT_ATENDIDA ,
 	       DP.PRECIO_UNIT,
 	       DP.VALOR_TOTAL PRECIO_TOTAL,
 	       a.sec_func,
 	       a.ACT_PROY PRODUCTO,
 	       COALESCE(EESS.COD_OGEI, 0) PTO_ATEN,
          (COALESCE(EESS.COD_OGEI,'') +' - '+ COALESCE(EESS.DESC_ESTABLEC,'') )PTO_ATEN_NOMBRE,
 	       LTRIM(RTRIM(CA.NOMBRE_CORTO)) PTO_ATEN_CATEGORIA,
 	       eess.UBIGEO,
 	       COALESCE(SPD.DESC_DISA, 'NO TIENE') PTO_ATEN_DISA,
 	       COALESCE(SPR.DESC_RED, 'NO TIENE') PTO_ATEN_RED,
 	       COALESCE(SPM.DESC_MICRORED, 'NO TIENE') PTO_ATEN_MICRORED,
 	       EESS.SECTOR_AMBITO ,
 	       TE.ID_SUB_FINALIDAD,
 	       TE.SUBFINALIDAD SUBPRODUCTO    	     
 	 INTO tmp_si_pedido
 	FROM   SIG_PEDIDOS A
 	       JOIN SIG_DETALLE_PEDIDOS DP
 	            ON  (
 	                    a.ANO_EJE = DP.ANO_EJE
 	                    AND A.SEC_EJEC = DP.sec_ejec
 	                    AND A.TIPO_BIEN = DP.TIPO_BIEN
 	                    AND A.TIPO_PEDIDO = DP.TIPO_PEDIDO
 	                    AND A.NRO_PEDIDO = DP.NRO_PEDIDO
 	                )
 	       JOIN SIG_CENTRO_COSTO SCC
 	            ON  SCC.ANO_EJE = A.ANO_EJE
 	            AND SCC.SEC_EJEC = A.SEC_EJEC
 	            AND SCC.CENTRO_COSTO = A.CENTRO_COSTO
 	       JOIN SIG_SEDES DSD
 	            ON  (DSD.SEDE = SCC.SEDE AND DSD.pliego = SCC.pliego)
 	       LEFT OUTER JOIN SIG_PPR_SEDE CSD
 	            ON  (
 	                    CSD.ANO_EJE = SCC.ANO_EJE
 	                    AND CSD.SEC_EJEC = SCC.SEC_EJEC
 	                    AND CSD.PLIEGO = SCC.PLIEGO
 	                    AND CSD.SEDE = SCC.SEDE
 	                )
 	       LEFT OUTER JOIN SIG_PPR_ESTABLECIMIENTO EESS
 	            ON  (
 	                    EESS.ANO_EJE = CSD.ANO_EJE
 	                    AND EESS.SEC_EJEC = CSD.SEC_EJEC
 	                    AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
 	                )
 	       LEFT OUTER JOIN SIG_PPR_CATEGORIA CA
 	            ON  (
 	                    CA.ANO_EJE = CSD.ANO_EJE
 	                    AND CA.SECTOR_AMBITO = '01'
 	                    AND CA.CATEGORIA = EESS.CATEGORIA
 	                )
 	       JOIN sector s
 	            ON  (S.SECTOR = DSD.sector)
 	       JOIN pliego p
 	            ON  (P.PLIEGO = DSD.pliego AND P.sector = DSD.sector)
 	       JOIN ejecutora EJC
 	            ON  (EJC.SEC_EJEC = A.SEC_EJEC)
 	       LEFT OUTER JOIN SIG_PPR_DISA SPD
 	            ON  (
 	                    SUBSTRING(EESS.CAD_OPERATIVA, 1, 2) = SPD.COD_DISA
 	                    AND SPD.ESTADO = 'A'
 	                )
 	       LEFT	OUTER JOIN SIG_PPR_RED SPR
 	            ON  (
 	                    SUBSTRING(EESS.CAD_OPERATIVA, 1, 4) = SPR.COD_DISA + SPR.COD_RED
 	                    AND SPR.ESTADO = 'A'
 	                )
 	       LEFT	OUTER JOIN SIG_PPR_MICRORED SPM
 	            ON  (
 	                    SUBSTRING(EESS.CAD_OPERATIVA, 1, 6) = SPM.COD_DISA + SPM.COD_RED 
 	                    + SPM.COD_MICRORED
 	                    AND SPM.ESTADO = 'A'
 	            )
			LEFT OUTER JOIN SIG_TAREA_ESTRATEGICO TE
 	            ON (
 	            	TE.ANO_EJE= A.ANO_EJE AND
 	            	TE.SEC_EJEC = A.SEC_EJEC AND
 	            	TE.TIPO_TAREA = A.TIPO_TAREA AND
 	            	TE.NIVEL_TAREA = A.NIVEL_TAREA AND
 	            	TE.TAREA_GENERAL = A.CODIGO_TAREA 	
 	            )            
 	WHERE	A.ANO_EJE = @P_ANO_EJE  --2013 --
 	    AND A.SEC_EJEC = @P_SEC_EJEC --1264 --
 	    AND A.TIPO_PEDIDO = '2'	
	


	INSERT INTO SI_TRANS_PEDIDO (
		ANO_EJE,		  SECTOR,			NOM_SECTOR,			PLIEGO,			NOM_PLIEGO,		SEC_EJEC,		  NOM_EJECUTORA,
		MES_PECOSA,		  TIPO_USO,			PRODUCTO,			TAREA_TIPO,		NIVEL_TAREA, CODIGO_TAREA,		  CENTRO_COSTO,	
		NOM_CENTRO_COSTO, TIPO_BIEN,		GRUPO_BIEN,		CLASE_BIEN,			FAMILIA_BIEN,		ITEM_BIEN,		UNIDAD_MEDIDA,	
		NRO_PECOSA,		  NRO_PEDIDO,		FECHA_PECOSA,	FECHA_PEDIDO,		CANTIDAD_ATENDIDA,	PRECIO_UNITARIO,PRECIO_TOTAL,	
		sec_func,		  PTO_ATEN,			PTO_ATEN_NOMBRE,PTO_ATEN_CATEGORIA,	ubigeo,				PTO_ATEN_DISA,	PTO_ATEN_RED,	
		PTO_ATEN_MICRORED,SECTOR_AMBITO,	ID_SUB_FINALIDAD,	SUBPRODUCTO
	)
	SELECT 	
		ANO_EJE,		  SECTOR,			NOM_SECTOR,			PLIEGO,			NOM_PLIEGO,		SEC_EJEC,		  NOM_EJECUTORA,
		MES_PECOSA,		  TIPO_USO,			PRODUCTO,			TAREA_TIPO,		NIVEL_TAREA,	CODIGO_TAREA,	  CENTRO_COSTO,	
		NOM_CENTRO_COSTO, TIPO_BIEN,		GRUPO_BIEN,		CLASE_BIEN,			FAMILIA_BIEN,		ITEM_BIEN,		UNIDAD_MEDIDA,	
		NRO_PECOSA,		  NRO_PEDIDO,		FECHA_PECOSA,	FECHA_PEDIDO,		CANT_ATENDIDA,	PRECIO_UNIT,		PRECIO_TOTAL,	
		sec_funC,		  PTO_ATEN,			PTO_ATEN_NOMBRE,PTO_ATEN_CATEGORIA,	ubigeo,				PTO_ATEN_DISA,	PTO_ATEN_RED,	
		PTO_ATEN_MICRORED,SECTOR_AMBITO,	ID_SUB_FINALIDAD,	SUBPRODUCTO
	FROM tmp_si_pedido

	UPDATE SI_TRANS_PEDIDO
	SET    TAREA_NOMBRE = (
	           SELECT st.NOMBRE
	           FROM   sig_tarea st
	           WHERE  ST.ano_eje = SI_TRANS_PEDIDO.ANO_EJE
	                  AND ST.sec_ejec = SI_TRANS_PEDIDO.SEC_EJEC
	                  AND ST.tipo_tarea = SI_TRANS_PEDIDO.TAREA_TIPO
	                  AND ST.nivel_tarea = SI_TRANS_PEDIDO.NIVEL_TAREA
	                  AND ST.tarea_general = SI_TRANS_PEDIDO.CODIGO_TAREA
	       )
	WHERE  ANO_EJE = @P_ANO_EJE
	       AND SEC_EJEC = @P_SEC_EJEC

/**8. PROGRAMA PPTO**/	
	UPDATE SI_TRANS_PEDIDO
	SET PROGRAMA_PPTO = (SELECT M.ESTRATEGIA_NACIONAL
							FROM META M
							WHERE M.ANO_EJE= SI_TRANS_PEDIDO.ano_eje AND 
							M.SEC_EJEC= SI_TRANS_PEDIDO.SEC_EJEC AND
							M.SEC_FUNC= SI_TRANS_PEDIDO.sec_func ) 
	WHERE  
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC 

/**9 Nombre PROGRAMA PPTO**/

	UPDATE SI_TRANS_PEDIDO
	SET PROGRAMA_NOMBRE  = PROGRAMA_PPTO+' - '+(SELECT enn.NOMBRE
												FROM 
												ESTRATEGIA_NACIONAL_NOMBRE enn
												WHERE enn.ANO_EJE= SI_TRANS_PEDIDO.ano_eje AND
												enn.ESTRATEGIA_NACIONAL= SI_TRANS_PEDIDO.PROGRAMA_PPTO AND
												enn.ESTADO='A') 
	WHERE  
	ano_eje  = @P_ANO_EJE AND
	SEC_EJEC = @P_SEC_EJEC AND 
	PROGRAMA_PPTO NOT IN ('9001','9002')

	UPDATE SI_TRANS_PEDIDO
	SET PROGRAMA_NOMBRE = '0000 - SIN PROGRAMA PRESUPUESTAL'
	WHERE  
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC AND
	PROGRAMA_PPTO  IN ('9001','9002')

/**11. Producto Nombre**/	
	UPDATE SI_TRANS_PEDIDO
	SET PRODUCTO_NOMBRE = PRODUCTO+' - '+(  SELECT NOMBRE 
											FROM Act_Proy_Nombre  
											WHERE ANO_EJE= SI_TRANS_PEDIDO.ano_eje AND 
												  act_proy= SI_TRANS_PEDIDO.PRODUCTO   AND 
												  estado= 'A'											
											) 
	WHERE  
	ano_eje =@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC  AND 
	PRODUCTO NOT IN ('3999999')

	UPDATE SI_TRANS_PEDIDO
	SET PRODUCTO_NOMBRE = '000000 - SIN PRODUCTO'
	WHERE  
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC AND 
	PRODUCTO  IN ('3999999')

/**SUBPRODUCTO**/
	UPDATE SI_TRANS_PEDIDO
	SET    SUBPRODUCTO = '0000000'
	WHERE  ano_eje = @P_ANO_EJE
		   AND SEC_EJEC = @P_SEC_EJEC
		   AND ID_SUB_FINALIDAD IS NULL  	

	UPDATE SI_TRANS_PEDIDO
	SET SUBPRODUCTO_NOMBRE = SUBPRODUCTO +' - '+( SELECT S.NOMBRE FROM SIG_SUB_FINALIDAD S
								WHERE
								 S.ANO_EJE = SI_TRANS_PEDIDO.ANO_EJE AND
								 S.SUB_FINALIDAD = SI_TRANS_PEDIDO.SUBPRODUCTO AND
								 S.ID_SUB_FINALIDAD = SI_TRANS_PEDIDO.ID_SUB_FINALIDAD	AND
								 S.ESTADO = 'A')
	WHERE  
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC  AND 
	ID_SUB_FINALIDAD IS NOT NULL

	UPDATE SI_TRANS_PEDIDO
	SET    SUBPRODUCTO_NOMBRE = '0000000 - SIN PRODUCTO'
	WHERE  ano_eje = @P_ANO_EJE
	       AND SEC_EJEC = @P_SEC_EJEC
	       AND ID_SUB_FINALIDAD IS NULL  
			 
/**4.GRUPO**/	
	UPDATE 	SI_TRANS_PEDIDO
	SET GRUPO_NOMBRE= TIPO_BIEN+GRUPO_BIEN+' - '+(	SELECT nombre_grupo 
						FROM grupo_bien_serv
						WHERE tipo_bien= SI_TRANS_PEDIDO.TIPO_BIEN AND grupo_bien=SI_TRANS_PEDIDO.GRUPO_BIEN AND
						ESTADO ='A') 	
	   
	WHERE
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC 

/**5.CLASE**/	
	UPDATE 	SI_TRANS_PEDIDO
	SET CLASE_NOMBRE =TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+' - '+(	SELECT nombre_clase 
						FROM clase_bien_serv
						WHERE tipo_bien= SI_TRANS_PEDIDO.TIPO_BIEN AND 
						grupo_bien=SI_TRANS_PEDIDO.grupo_bien AND
						clase_bien= SI_TRANS_PEDIDO.CLASE_BIEN AND
						ESTADO ='A') 	
	   
	WHERE
	ano_eje  =@P_ANO_EJE AND
	SEC_EJEC =@P_SEC_EJEC 


/**6. FAMILIA**/	
	UPDATE 	SI_TRANS_PEDIDO
	SET FAMILIA_NOMBRE=TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+' - '+(	SELECT nombre_fam 
																				FROM familia_bien_serv
																				WHERE	tipo_bien= SI_TRANS_PEDIDO.TIPO_BIEN AND 
																						grupo_bien=SI_TRANS_PEDIDO.grupo_bien 
																						AND clase_bien= SI_TRANS_PEDIDO.CLASE_BIEN AND 
																						familia_bien=SI_TRANS_PEDIDO.FAMILIA_BIEN AND
																						ESTADO ='A') 		   
	WHERE
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC 

/**7. ITEM**/	
	UPDATE 	SI_TRANS_PEDIDO
	SET ITEM_NOMBRE= SUBSTRING(TIPO_BIEN+GRUPO_BIEN+ CLASE_BIEN+ FAMILIA_BIEN+ITEM_BIEN+' - '+(	SELECT NOMBRE_ITEM 
																						FROM CATALOGO_BIEN_SERV
																						WHERE 
																							SEC_EJEC= SI_TRANS_PEDIDO.SEC_EJEC AND
																						tipo_bien= SI_TRANS_PEDIDO.TIPO_BIEN AND 
																						grupo_bien=SI_TRANS_PEDIDO.grupo_bien 
																						AND clase_bien= SI_TRANS_PEDIDO.CLASE_BIEN AND 
																						familia_bien=SI_TRANS_PEDIDO.FAMILIA_BIEN 
																						AND ITEM_BIEN= SI_TRANS_PEDIDO.ITEM_BIEN AND					
																						ESTADO ='A'), 1, 150) 	   
	WHERE
	ano_eje=@P_ANO_EJE AND
	SEC_EJEC=@P_SEC_EJEC   
 
     
/*--4 Actualizar ubigeo*/
	UPDATE SI_TRANS_PEDIDO
	SET    nombre_DPTO_PTO = 'NO TIENE',
		   NOMBRE_PROV_PTO = 'NO TIENE',
		   NOMBRE_DIST_PTO = 'NO TIENE'
	WHERE  ano_eje = @P_ANO_EJE
		   AND SEC_EJEC = @P_SEC_EJEC
		   AND UBIGEO = '000000'  

	UPDATE SI_TRANS_PEDIDO  
	SET nombre_DPTO_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
							WHERE UBG.departamento= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,1,2) AND UBG.provincia='00' AND
							UBG.distrito='00' AND UBG.estado='A' )
	WHERE  nombre_DPTO_PTO IS NULL AND 
		ano_eje= @P_ANO_EJE AND
		SEC_EJEC=@P_SEC_EJEC  		

	UPDATE SI_TRANS_PEDIDO  
	SET nombre_PROV_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
							WHERE UBG.departamento= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,1,2) AND 
								  UBG.provincia= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,3,2) AND
								 UBG.distrito='00' AND UBG.estado='A' )
	WHERE  nombre_PROV_PTO IS NULL AND 
			ano_eje=@P_ANO_EJE AND
			SEC_EJEC=@P_SEC_EJEC 

	UPDATE SI_TRANS_PEDIDO  
	SET nombre_DIST_PTO= ( SELECT UBG.nombre FROM ubigeo UBG
							WHERE UBG.departamento= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,1,2) AND 
								  UBG.provincia= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,3,2) AND
								  UBG.distrito= SUBSTRING(SI_TRANS_PEDIDO.UBIGEO,5,2)  AND 
								  UBG.estado='A' )
	WHERE  nombre_DIST_PTO IS NULL AND 
			ano_eje=@P_ANO_EJE AND
			SEC_EJEC=@P_SEC_EJEC 


 END
GO


-- ----------------------------
-- procedure structure for sp_prg_genera_tabla_final_1_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_prg_genera_tabla_final_1_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[sp_prg_genera_tabla_final_1_TRX]
GO

CREATE PROCEDURE [dbo].[sp_prg_genera_tabla_final_1_TRX]
    @ano_eje        numeric(4,0),
    @sec_ejec       numeric(5,0),
    @fecha_carga_inicio     varchar(10),
    @fecha_carga_fin      varchar(10),
    @usuario_n              varchar(30),
    @nro_fase				numeric(1,0)
AS
    DECLARE @fecha_carga_inicio_1         DATETIME
    DECLARE @fecha_carga_fin_1            DATETIME  
BEGIN
    TRUNCATE TABLE SI_PRG_META_TRX   
    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

   /* select @nro_fase = nro_fase 
    from sig_ppr_cierre_fase
    where ano_eje  = @ano_eje
     and sec_ejec = @sec_ejec
     and estado = 'A'*/
 
    insert into SI_PRG_META_TRX
    (ANO_EJE, NRO_FASE, SEC_EJEC, SEC_FUNC, SECTOR, PLIEGO,
     FUNCION, PROGRAMA, SUB_PROGRAMA, ACT_PROY, COMPONENTE, META, FINALIDAD, 
     NOMBRE, MONTO, CANTIDAD, PAIS, DEPARTAMENTO, PROVINCIA, DISTRITO, FLAG_ESTRATEGIA, 
     UNIDAD_MEDIDA, D_UNIDAD_MEDIDA, FLAG_ACT_PROY, ESTRATEGIA_NACIONAL, 
     PROGRAMA_INSTITUCIONAL, FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
            select meta.ano_eje, @nro_fase, meta.sec_ejec, meta.sec_func, sig_ejecutora.sector, sig_ejecutora.pliego,
                		 meta.funcion, meta.programa, meta.sub_programa, meta.act_proy, 
				 meta.componente, meta.meta, meta.finalidad,
		                 meta.nombre, meta.monto, meta.cantidad, meta.pais, meta.departamento, 
				 meta.provincia, meta.distrito, meta.flag_estrategia,
                 		 meta.unidad_medida, '', null, 
				 meta.estrategia_nacional, meta.programa_institucional, 
				 @fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(),@usuario_n
            from meta ,
            sig_ejecutora
	    where meta.ano_eje = @ano_eje
            and meta.sec_ejec = @sec_ejec
            and sig_ejecutora.sec_ejec = meta.sec_ejec
            and meta.flag_estrategia = 'S'
            and @nro_fase = 5
            union
            select meta.ano_eje, @nro_fase, meta.sec_ejec, meta.sec_func_prop, sig_ejecutora.sector, sig_ejecutora.pliego,
                 		 meta.funcion, meta.programa, meta.sub_programa, meta.act_proy, 
				 meta.componente, meta.meta, meta.finalidad,
		                 meta.nombre, meta.monto, meta.cantidad, meta.pais, meta.departamento, 
				 meta.provincia, meta.distrito, meta.flag_estrategia,
				 meta.unidad_medida, '', meta.flag_act_proy, 
				 meta.estrategia_nacional, meta.programa_institucional,
				 @fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(),@usuario_n
	    from sig_meta_propuesta meta ,
            sig_ejecutora
			  where meta.ano_eje = @ano_eje
            and meta.sec_ejec = @sec_ejec
            and sig_ejecutora.sec_ejec = meta.sec_ejec
            and meta.flag_estrategia = 'S'
            and @nro_fase < 5
end
GO


-- ----------------------------
-- procedure structure for SP_SIG_TAREA_ESTRATEGICA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_TAREA_ESTRATEGICA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_TAREA_ESTRATEGICA]
GO

CREATE PROCEDURE [dbo].[SP_SIG_TAREA_ESTRATEGICA]
@an_ano_eje numeric(4), @an_sec_eje numeric(6), @as_origen varchar(1), @as_usuing varchar(8), @as_message varchar(100) output

AS
DECLARE
@ls_tipo_tarea varchar(1),
@ls_nivel_tarea varchar(1),
@ls_meta_nombre varchar(150),
@ls_act_proy varchar(7),
@ls_finalidad varchar(5),
@ls_grupo_tarea varchar(2),
@ls_subfinalidad varchar(7),
@ls_tipofinalidad varchar(1),
@ls_nombresubfinalidad varchar(200),
@ls_pi varchar(6),
@ls_nombrefinalidad varchar(250),

@ld_tarea_general numeric(4),
@ll_cuenta numeric(5),

@ls_fase varchar(1),
@ls_control varchar(1),
@ldt_fecha_actual datetime

--Se genera las tareas por cada meta estrategica
--Obs Solo procesa las metas que no tienen tarea
DECLARE c_estrategia CURSOR FOR
SELECT distinct m.act_proy, m.finalidad, f.sub_finalidad, '1' tipofinalidad,
	f.nombre, m.programa_institucional, a.nombre nombre_finalidad
  FROM sig_meta_propuesta_fase m, finalidad a,
	sig_sub_finalidad f
 WHERE 	m.ano_eje = f.ano_eje AND
	m.finalidad = f.finalidad AND
	@as_origen = '1' AND
	a.ano_eje =  @an_ano_eje and
	a.finalidad = m.finalidad and
	m.ano_eje  = @an_ano_eje AND
	m.sec_ejec = @an_sec_eje AND		 
	(m.fase_cuadro = @ls_fase AND @ls_control = '0') AND			
	m.flag_estrategia = 'S' and
	m.programa_institucional = f.programa_institucional and		 
	not exists (select ano_eje
			  from sig_tarea_estrategico
 		   	  where ano_eje = @an_ano_eje and
				sec_ejec = @an_sec_eje and
				finalidad = m.finalidad and
				programa_institucional = m.programa_institucional and
				subfinalidad = f.sub_finalidad)
ORDER BY 2,3,6

set @ldt_fecha_actual = GETDATE()
set @ls_nivel_tarea = 'E'

  SELECT @ls_fase = valor  
    FROM sig_parametro_ejecutora_anio
   WHERE ano_eje  = @an_ano_eje AND
	 sec_ejec = @an_sec_eje AND  
         cod_maestro = 'FLAG_SUBFASE_INT'

set @ls_fase = isnull(@ls_fase, '0')
If (@ls_fase = '')
   set @ls_fase = '0'

  SELECT @ls_control = valor  
    FROM sig_parametro_ejecutora_anio
   WHERE ano_eje  = @an_ano_eje AND
	 sec_ejec = @an_sec_eje AND  
         cod_maestro = 'FLAG_CONTROL_INT'

set @ls_control = isnull(@ls_control, '0')
If (@ls_control = '')
   set @ls_control = '0'

If (@as_origen = '1')
Begin
	UPDATE sig_meta_propuesta_fase
	   SET flag_estrategia = 'N',
		tipo_estrategia = null,
		tipo_tarea = null,
		nivel_tarea = null,
		tarea_general = null,
		programa_institucional = '0000',
		estrategia_nacional = '0000'
	 WHERE ano_eje  = @an_ano_eje AND
	       sec_ejec = @an_sec_eje AND
		 (fase_cuadro = @ls_fase AND @ls_control = '0') AND
		 ( (programa_institucional is null) OR
		   (not exists (SELECT ep.ano_eje
	           		  FROM sig_estrategia_parametro ep
				 WHERE ep.ano_eje = sig_meta_propuesta_fase.ano_eje AND
					ep.fase_cuadro = sig_meta_propuesta_fase.fase_cuadro AND
					ep.programa_institucional = sig_meta_propuesta_fase.programa_institucional AND
					ep.ano_eje 	= @an_ano_eje AND
					ep.estado 	= 'A' ))) 

	IF (@@ERROR <> 0)
	BEGIN
		set @as_message = 'No se puede inicializar las metas propuestas.'
		goto error
	End
	
	update sig_meta_propuesta_fase
	   set flag_estrategia = 'S', tipo_estrategia = 'K', estrategia_nacional = programa_institucional
	 where ano_eje  = @an_ano_eje and
		sec_ejec = @an_sec_eje and		 
		(fase_cuadro = @ls_fase AND @ls_control = '0') AND
		estrategia_nacional <> '0000' AND
		estrategia_nacional in ( select a.programa_institucional
					   from sig_estrategia_parametro a
					  Where a.ano_eje = @an_ano_eje and
						a.fase_cuadro = sig_meta_propuesta_fase.fase_cuadro and
						a.estado = 'A')
	
	IF (@@ERROR <> 0)
	BEGIN
		set @as_message = 'No se puede actualizar el indicador de estrategia.'
		goto error
	End
	
	UPDATE sig_meta_propuesta_fase
	   SET tipo_estrategia = 'G'
	 WHERE ano_eje  	= @an_ano_eje AND  
		sec_ejec = @an_sec_eje AND  			
		(fase_cuadro = @ls_fase AND @ls_control = '0') AND
		flag_estrategia ='S'   AND
		unidad_medida = 60
	
	IF (@@ERROR <> 0)
	BEGIN
		set @as_message = 'No se puede actualizar el indicador de estrategia.'
		goto error
	End
End

DELETE FROM sig_tarea_estrategico
 WHERE 	ano_eje  = @an_ano_eje AND
	sec_ejec = @an_sec_eje AND
	nivel_tarea = @ls_nivel_tarea AND
	not exists (SELECT ano_eje
			 FROM sig_centro_costo_tarea
			WHERE ano_eje  = @an_ano_eje AND
				sec_ejec  = @an_sec_eje AND
				tipo_tarea   = sig_tarea_estrategico.tipo_tarea and
				nivel_tarea  = sig_tarea_estrategico.nivel_tarea and
				codigo_tarea = sig_tarea_estrategico.tarea_general) and
	not exists (SELECT ano_eje
			  FROM sig_meta_propuesta
			 WHERE ano_eje  = @an_ano_eje AND
				 sec_ejec = @an_sec_eje AND
				 finalidad   = sig_tarea_estrategico.finalidad AND
				 programa_institucional  = sig_tarea_estrategico.programa_institucional) and
	not exists (SELECT ano_eje
			  FROM sig_meta_propuesta_fase
			 WHERE ano_eje  = @an_ano_eje AND
				 sec_ejec = @an_sec_eje AND
				 finalidad   = sig_tarea_estrategico.finalidad AND
				 programa_institucional  = sig_tarea_estrategico.programa_institucional) and
	not exists (SELECT ano_eje
			  FROM meta
			 WHERE ano_eje  = @an_ano_eje AND
				 sec_ejec = @an_sec_eje AND
				 finalidad   = sig_tarea_estrategico.finalidad AND
				 programa_institucional  = sig_tarea_estrategico.programa_institucional)

IF (@@ERROR <> 0)
BEGIN
	set @as_message = 'No se puede eliminar las tareas estrategicas sin metas.'
	goto error
End

DELETE FROM sig_tarea
 WHERE ano_eje  = @an_ano_eje AND
       sec_ejec = @an_sec_eje AND
	nivel_tarea = @ls_nivel_tarea AND
	 not exists (SELECT ano_eje
			  FROM sig_tarea_estrategico
			 WHERE ano_eje  	= @an_ano_eje AND
				sec_ejec 	= @an_sec_eje AND
				tipo_tarea   	= sig_tarea.tipo_tarea AND
				nivel_tarea  	= sig_tarea.nivel_tarea AND
				tarea_general 	= sig_tarea.tarea_general)

IF (@@ERROR <> 0)
BEGIN
	set @as_message = 'No se puede eliminar las tareas estrategicas en el maestro de Tareas.'
	goto error
End

OPEN c_estrategia
FETCH NEXT FROM c_estrategia INTO @ls_act_proy, @ls_finalidad,
				@ls_subfinalidad, @ls_tipofinalidad, @ls_nombresubfinalidad, @ls_pi, @ls_nombrefinalidad
WHILE @@FETCH_STATUS = 0
BEGIN
	set @ls_tipo_tarea = null
	set @ls_nivel_tarea = null
	set @ld_tarea_general = null
	
	if (@ls_tipofinalidad= '0')
		set @ls_subfinalidad = null
	
	set @ls_grupo_tarea = '02'
	set @ls_tipo_tarea  = '1'
	set @ls_nivel_tarea = 'E'
		
	If (substring(@ls_act_proy,1,1) = '2')
	Begin
		set @ls_grupo_tarea = '03'
		set @ls_tipo_tarea  = '2'
	End
		
	select @ll_cuenta = count(*)
	from sig_tarea
	where ano_eje     = @an_ano_eje and
		sec_ejec    = @an_sec_eje	and
		tipo_tarea  = @ls_tipo_tarea and
		nivel_tarea = @ls_nivel_tarea and					
		exists( select ano_eje
			  from sig_tarea_estrategico b
			 where b.ano_eje     = @an_ano_eje and
				b.sec_ejec    = @an_sec_eje	and
				b.tipo_tarea  = sig_tarea.tipo_tarea and
				b.nivel_tarea  = sig_tarea.nivel_tarea and
				b.tarea_general  = sig_tarea.tarea_general and
				b.finalidad      = @ls_finalidad and
				b.programa_institucional = @ls_pi and
				b.subfinalidad = @ls_subfinalidad)

	set @ll_cuenta = isnull(@ll_cuenta,0)
			
	if (@ll_cuenta > 0)
		set @ll_cuenta = @ll_cuenta
	else
	Begin
		select @ld_tarea_general = max(tarea_general)
		  from sig_tarea
		 where ano_eje     = @an_ano_eje and
			sec_ejec    = @an_sec_eje	and
			nivel_tarea = @ls_nivel_tarea

		set @ld_tarea_general = IsNull(@ld_tarea_general,0)
		set @ld_tarea_general = @ld_tarea_general + 1
	
		set @ls_meta_nombre = substring(@ls_pi + '-'+@ls_subfinalidad+'-'+@ls_nombresubfinalidad, 1, 150)
	
		  INSERT INTO sig_tarea  
			( ano_eje, sec_ejec, tipo_tarea, nivel_tarea, tarea_general,   
			  nombre, grupo_tarea, estado, fecha_reg, cuser_id,   
			  tipo_ppto, tipo_uso, sec_ejec2 , orden_tarea,
			  tipo_tarea_pad, nivel_tarea_pad, tarea_general_pad, tipo_meta)  
		  VALUES ( @an_ano_eje, @an_sec_eje, @ls_tipo_tarea, @ls_nivel_tarea, @ld_tarea_general,   
			  @ls_meta_nombre, @ls_grupo_tarea, 'A', @ldt_fecha_actual, @as_usuing,   
			  1, 'X', null,
			  null , null, null, null, 'E')  
		
		IF (@@ERROR <> 0)
		BEGIN
			close c_estrategia
			DEALLOCATE c_estrategia
			set @as_message = 'No se puede generar la tarea estratégica en el maestro de Tareas.'
			goto error
		End

		insert into sig_tarea_estrategico
			(ano_eje, sec_ejec, tipo_tarea, nivel_tarea, tarea_general,
			finalidad, programa_institucional, subfinalidad)
		select distinct @an_ano_eje, @an_sec_eje,@ls_tipo_tarea, @ls_nivel_tarea, @ld_tarea_general,
				@ls_finalidad, @ls_pi, @ls_subfinalidad
		  from sig_ejecutora
		 where not exists (select ano_eje
				   from sig_tarea_estrategico
				  where ano_eje  = @an_ano_eje and
					  sec_ejec = @an_sec_eje and
					  tipo_tarea = @ls_tipo_tarea AND
					  nivel_tarea = @ls_nivel_tarea AND
					  tarea_general = @ld_tarea_general AND
					  finalidad = @ls_finalidad and
					  programa_institucional = @ls_pi and
					  subfinalidad = @ls_subfinalidad)
		IF (@@ERROR <> 0)
		BEGIN
			close c_estrategia
			DEALLOCATE c_estrategia
			set @as_message = 'No se puede generar la tarea estratégica.'
			goto error
		End
	end

	FETCH NEXT FROM c_estrategia INTO @ls_act_proy, @ls_finalidad,
					@ls_subfinalidad, @ls_tipofinalidad, @ls_nombresubfinalidad, @ls_pi, @ls_nombrefinalidad
End
CLOSE c_estrategia
DEALLOCATE c_estrategia

Return 1

ERROR:
   ROLLBACK TRAN
   RETURN -1
;--/
GO


-- ----------------------------
-- procedure structure for sp_prg_genera_tabla_final_2_trx
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_prg_genera_tabla_final_2_trx]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[sp_prg_genera_tabla_final_2_trx]
GO

CREATE PROCEDURE [dbo].[sp_prg_genera_tabla_final_2_trx]
    @ano_eje     numeric(4,0), 
    @sec_ejec    numeric(5,0), 
    @fecha_carga_inicio  varchar(10),
    @fecha_carga_fin    varchar(10),
    @usuario_n           varchar(30)
AS
   DECLARE @fecha_carga_inicio_1         DATETIME
   DECLARE @fecha_carga_fin_1            DATETIME  
BEGIN
    declare @tipo_plant    numeric(1,0)
    declare @max_sec       numeric(10,0)
    declare @estrategia_nacional  varchar(4)
    declare @funcion          varchar(2)
    declare @programa         varchar(3)
    declare @sub_programa     varchar(4)
    declare @act_proy         varchar(7)
    declare @componente       varchar(7)
    declare @finalidad        varchar(5)
    declare @sec_func         numeric(5,0)
    declare @tipo_bien        varchar(1)
    declare @grupo_bien    varchar(2)
    declare @clase_bien    varchar(2)
    declare @familia_bien  varchar(4)
    declare @item_bien     varchar(4)
    declare @unidad_medida numeric(5,0)
    declare @precio_unit   numeric(16,6)
    declare @origen        varchar(1)
    declare @fuente_financ varchar(2)
    declare @clasificador  varchar(20)
    declare @cantidad      numeric(10,0)
    declare @monto         numeric(12,2)    
    declare @d_item_bien   varchar(100)
    declare @d_uni_medida  varchar(100)
	declare @FASE_CUADRO   numeric(5,0)
    set @tipo_plant = 1
 
    TRUNCATE TABLE SI_PRG_META_EJECUTORA_TRX
 
    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
    
    DECLARE cursor_metas CURSOR FOR 
 
        SELECT ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, SUB_PROGRAMA, 
               ACT_PROY, COMPONENTE, FINALIDAD, SEC_FUNC
        FROM META 
               WHERE SEC_EJEC = @sec_ejec
               and ANO_EJE = @ano_eje
               and FLAG_ESTRATEGIA = 'S'
               --and @nro_fase = 3
               UNION
               SELECT ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, SUB_PROGRAMA, 
               ACT_PROY, COMPONENTE, FINALIDAD, SEC_FUNC_PROP
               FROM SIG_META_PROPUESTA  
        WHERE SEC_EJEC = @sec_ejec
               and ANO_EJE = @ano_eje
               and FLAG_ESTRATEGIA = 'S'
               --and @nro_fase < 3
    
    OPEN cursor_metas
    FETCH NEXT FROM cursor_metas 
    INTO @estrategia_nacional,   @funcion, 
  @programa,   @sub_programa,  @act_proy, 
  @componente, @finalidad,  @sec_func
    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE cursor_items CURSOR FOR 
            SELECT det.TIPO_BIEN     ,
                   det.GRUPO_BIEN    ,
                   det.CLASE_BIEN    ,
                   det.FAMILIA_BIEN  ,
                   det.ITEM_BIEN     ,
                   det.PRECIO_UNIT   ,
                   det.UNIDAD_MEDIDA ,
                   cab.clasificador  ,
                   cab.ORIGEN        ,
                   cab.FUENTE_FINANC ,
                   sum(det.CANT_TOTAL) as cantidad,
                   sum(det.MNTO_TOTAL) as monto,
				   cab.FASE_CUADRO
             FROM SIG_CUADRO_NECESIDAD cab,   
                  SIG_CUADRO_NECESIDAD_DET det
            WHERE det.ANO_EJE       = cab.ANO_EJE
              and det.SEC_EJEC      = cab.SEC_EJEC
              and det.CENTRO_COSTO  = cab.CENTRO_COSTO
              and det.SECUENCIA     = cab.SECUENCIA
              and det.FASE_CUADRO   = cab.FASE_CUADRO
              and cab.ANO_EJE       = @ano_eje
              and cab.SEC_EJEC      = @sec_ejec
              and cab.SEC_FUNC_PROP = @sec_func
         GROUP BY det.TIPO_BIEN     ,
                  det.GRUPO_BIEN    ,
                  det.CLASE_BIEN    ,
                  det.FAMILIA_BIEN  ,
                  det.ITEM_BIEN     ,
                  det.PRECIO_UNIT   ,
                  det.UNIDAD_MEDIDA ,
				  cab.clasificador  ,
                  cab.ORIGEN        ,
                  cab.FUENTE_FINANC ,
				  cab.FASE_CUADRO
        union
            SELECT det.TIPO_BIEN     ,
                   det.GRUPO_BIEN    ,
                   det.CLASE_BIEN    ,
                   det.FAMILIA_BIEN  ,
                   det.ITEM_BIEN     ,
                   det.PRECIO_UNIT   ,
                   det.UNIDAD_MEDIDA ,
                   cab.clasificador  ,
                   cab.ORIGEN        ,
                   cab.FUENTE_FINANC ,
                   sum(det.CANT_TOTAL) as cantidad,
                   sum(det.MNTO_TOTAL) as monto,
				   cab.FASE_CUADRO
             FROM SIG_CUADRO_NECESIDAD cab,   
                  SIG_CUADRO_NECESIDAD_DET det
            WHERE det.ANO_EJE       = cab.ANO_EJE
              and det.SEC_EJEC      = cab.SEC_EJEC
              and det.CENTRO_COSTO  = cab.CENTRO_COSTO
              and det.SECUENCIA     = cab.SECUENCIA
              and det.FASE_CUADRO   = cab.FASE_CUADRO
              and cab.ANO_EJE       = @ano_eje
              and cab.SEC_EJEC      = @sec_ejec
              and cab.SEC_FUNC      = @sec_func
          
         GROUP BY det.TIPO_BIEN     ,
                  det.GRUPO_BIEN    ,
                  det.CLASE_BIEN    ,
                  det.FAMILIA_BIEN  ,
                  det.ITEM_BIEN     ,
                  det.PRECIO_UNIT   ,
                  det.UNIDAD_MEDIDA ,
                  cab.clasificador  ,
                  cab.ORIGEN        ,
                  cab.FUENTE_FINANC ,
				  cab.FASE_CUADRO
    
        OPEN cursor_items
    
        FETCH NEXT FROM cursor_items
        INTO @tipo_bien,  @grupo_bien,  @clase_bien, 
			 @familia_bien,  @item_bien,  @precio_unit, 
			 @unidad_medida,  @clasificador, 
			 @origen,   @fuente_financ, @cantidad, 
			 @monto, @FASE_CUADRO
    
        WHILE @@FETCH_STATUS = 0
        BEGIN
			  /*
			  Select @d_item_bien = NOMBRE_ITEM
              FROM CATALOGO_BIEN_SERV_ORIGINAL
              where TIPO_BIEN    = @tipo_bien
              and GRUPO_BIEN   = @grupo_bien
              and CLASE_BIEN   = @clase_bien
              and FAMILIA_BIEN = @familia_bien
              and ITEM_BIEN    = @item_bien
			   */

              Select @max_sec = max(SECUENCIA)
              from SI_PRG_META_EJECUTORA_TRX
              where ANO_EJE  = @ano_eje
              and SEC_EJEC = @sec_ejec
              and SEC_FUNC = @sec_func
              and NRO_FASE = @FASE_CUADRO
              and TIPO_PLANTILLA = 1
 
              if @max_sec Is Null SET @max_sec = 0            
						SET @max_sec = @max_sec + 1
 
            INSERT INTO SI_PRG_META_EJECUTORA_TRX
            (ANO_EJE, TIPO_PLANTILLA, NRO_FASE, 
			 SEC_FUNC, SEC_EJEC, SECUENCIA,
             TIPO_BIEN, GRUPO_BIEN, CLASE_BIEN, 
			 FAMILIA_BIEN, ITEM_BIEN, D_ITEM_BIEN,
             ESTRATEGIA_NACIONAL, FUNCION, PROGRAMA, 
			 SUB_PROGRAMA, ACT_PROY, COMPONENTE, 
			 FINALIDAD, PRECIO_REF, UNIDAD_MEDIDA, 
			 D_UNIDAD_MEDIDA, CANT_COMPRA, PREC_COMPRA, 
			 CLASIFICADOR, FUENTE_FINANC, ORIGEN_FUENTE, 
			 PROGRAMA_INSTITUCIONAL, FECHA_CARGA_INICIO, 
			 FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
            values
            (@ano_eje, @tipo_plant, @FASE_CUADRO, 
			 @sec_func, @sec_ejec, @max_sec, 
             @tipo_bien, @grupo_bien, @clase_bien, 
			 @familia_bien, @item_bien, '',
             @estrategia_nacional, @funcion, @programa, 
			 @sub_programa, @act_proy, @componente, @finalidad,
             @precio_unit, @unidad_medida, '', 
			 @cantidad, @monto, @clasificador, @fuente_financ, 
			 @origen, @estrategia_nacional, @fecha_carga_inicio_1, 
			 @fecha_carga_fin_1, getdate(), @usuario_n)
      
      FETCH NEXT FROM cursor_items
             INTO @tipo_bien,    @grupo_bien,     @clase_bien, 
				  @familia_bien,  @item_bien,      @precio_unit, 
				  @unidad_medida,   @clasificador, 
				  @origen,    @fuente_financ,  @cantidad, 
			      @monto,@FASE_CUADRO
        END        
        CLOSE cursor_items
        DEALLOCATE cursor_items
 
        FETCH NEXT FROM cursor_metas 
        INTO @estrategia_nacional,  @funcion,  @programa, 
			 @sub_programa,   @act_proy,  @componente, 
			 @finalidad,	@sec_func
    END   
    CLOSE cursor_metas
    DEALLOCATE cursor_metas
end
GO


