-- ----------------------------
-- procedure structure for SP_SI_CARGA_TA_EJECUTORA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_TA_EJECUTORA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_TA_EJECUTORA]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_TA_EJECUTORA]  
AS
BEGIN  
	TRUNCATE TABLE TA_EJECUTORA
	INSERT INTO TA_EJECUTORA (SEC_EJEC, NOMBRE, EJECUTORA, C_PLIEGO, D_PLIEGO, C_SECTOR, D_SECTOR)
  	SELECT ejecutora.sec_ejec, ejecutora.NOMBRE, ejecutora.ejecutora,
                               ejecutora.pliego, '' D_PLIEGO, ejecutora.sector,'' D_SECTOR 
	               FROM  ejecutora, sig_ejecutora V_EJECUTORAS
   	               WHERE ejecutora.sec_ejec = V_EJECUTORAS.SEC_EJEC

	UPDATE TA_EJECUTORA SET D_SECTOR = (SELECT SECTOR.nombre from SECTOR
	                WHERE TA_EJECUTORA.C_sector = SECTOR.sector)
	UPDATE pliego set nombre = REPLACE(nombre , 'GOBIERNO REGIONAL', 'G.R.' ) 
		WHERE nombre LIKE '%GOBIERNO REGIONAL%'
	UPDATE TA_EJECUTORA SET D_PLIEGO = (SELECT PLIEGO.nombre from PLIEGO
		WHERE TA_EJECUTORA.C_sector = PLIEGO.sector 
		AND TA_EJECUTORA.C_pliego = PLIEGO.pliego)
END
GO


-- ----------------------------
-- procedure structure for usp_GenTarea2013
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GenTarea2013]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GenTarea2013]
GO

CREATE PROCEDURE [dbo].[usp_GenTarea2013]
@lsecjec int
as
begin
insert into sig_centro_costo_tarea
 ( sec_ejec	,ano_eje	,centro_costo	,tipo_tarea	,nivel_tarea	,codigo_tarea	,
   nombre_tarea	,grupo_tarea	,tarea_general	,estado	,fecha_reg	,cuser_id	,
   tipo_ppto	,tipo_uso	,CANTIDAD	,UNIDAD_MEDIDA	)
select @lsecjec , 2013,tx.centro_costo,'1','E',tx.codigo_tarea,tx.nombre_tarea,'02',tx.codigo_tarea,'A',GETDATE(),'MIGRA',
	   1,'X',tx.CANTIDAD,tx.UNIDAD_MEDIDA
from
		(
			select t1.centro_costo	, t1.codigo_tarea	, t1.nombre_tarea	, t1.CANTIDAD	, t1.UNIDAD_MEDIDA	
			from (
					select CCT.centro_costo	, CCT.codigo_tarea	, CCT.nombre_tarea	, CCT.CANTIDAD	, CCT.UNIDAD_MEDIDA,
						   STE.SUBFINALIDAD
					from sig_centro_costo_tarea CCT,
						 SIG_TAREA_ESTRATEGICO STE
					where ( CCT.ano_eje = STE.ANO_EJE and 
							CCT.tipo_tarea = STE.TIPO_TAREA and
							CCT.nivel_tarea = STE.NIVEL_TAREA and CCT.codigo_tarea = STE.TAREA_GENERAL and
							CCT.ano_eje = 2012 and CCT.nivel_tarea = 'E' )
						and exists (select *
									  from sig_centro_costo CC_2013 
									  where CC_2013.ano_eje = 2013 and 
											CC_2013.centro_costo=CCT.centro_costo ) 
				 ) t1
			where t1.centro_costo+'|'+t1.SUBFINALIDAD 
				not in (
   				  select CCT2.centro_costo+'|' + STE2.SUBFINALIDAD
					from sig_centro_costo_tarea CCT2,
						 SIG_TAREA_ESTRATEGICO STE2
					WHERE  ( CCT2.ano_eje     = STE2.ANO_EJE     ) and
						   ( CCT2.tipo_tarea = STE2.TIPO_TAREA   ) and 
						   ( CCT2.nivel_tarea = STE2.NIVEL_TAREA ) and 
						   ( CCT2.codigo_tarea = STE2.TAREA_GENERAL ) and
						   ( CCT2.ano_eje = 2013 and CCT2.nivel_tarea = 'E' and CCT2.estado = 'A') and
						   ( CCT2.centro_costo=t1.centro_costo and STE2.SUBFINALIDAD=t1.SUBFINALIDAD )and
							exists ( select 1 
									   from SIG_TAREA_ESTRATEGICO STE_2013 
									  where STE_2013.ano_eje = 2013	and STE_2013.SUBFINALIDAD=STE2.SUBFINALIDAD ) 
				 )
		) tx
where not exists (
		   SELECT 1
		   FROM sig_centro_costo_tarea
		   where sec_ejec= @lsecjec and ano_eje=2013 and centro_costo=tx.centro_costo AND 
				 tipo_tarea='1' and nivel_tarea='E' and codigo_tarea=tx.codigo_tarea
	 )
	 and exists ( select 1 from sig_tarea 
					where ano_eje= 2013 and sec_ejec=@lsecjec and
						  tipo_tarea='1' and nivel_tarea='E' and tarea_general=tx.codigo_tarea )
end
GO


-- ----------------------------
-- procedure structure for ELIMINAR_INDEX_CATALOGO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ELIMINAR_INDEX_CATALOGO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[ELIMINAR_INDEX_CATALOGO]
GO

CREATE PROCEDURE [dbo].[ELIMINAR_INDEX_CATALOGO]
AS

DECLARE @NOMBRE_FOREINGKEY VARCHAR(200)
DECLARE @NOMBRE_TABLE VARCHAR(200)
DECLARE @CADENASQL NVARCHAR(100)

DECLARE CUR_TABLAS_CAMPOS_CATALOGO CURSOR FOR
SELECT SYSOBJECTS.NAME,  SYSINDEXES.NAME
FROM SYSINDEXES INNER JOIN SYSINDEXKEYS
ON SYSINDEXES.ID = SYSINDEXKEYS.ID
AND SYSINDEXES.INDID = SYSINDEXKEYS.INDID
INNER JOIN SYSCOLUMNS
ON SYSINDEXES.ID = SYSCOLUMNS.ID
AND SYSCOLUMNS.COLID = SYSINDEXKEYS.COLID
INNER JOIN SYSOBJECTS 
ON SYSOBJECTS.ID = SYSCOLUMNS.ID
WHERE SYSCOLUMNS.NAME = 'ITEM_BIEN'
AND SYSINDEXES.RESERVED <> 0
AND SUBSTRING(SYSINDEXES.NAME,1,3) <> 'PK_'

OPEN CUR_TABLAS_CAMPOS_CATALOGO
FETCH CUR_TABLAS_CAMPOS_CATALOGO INTO @NOMBRE_TABLE, @NOMBRE_FOREINGKEY

WHILE @@FETCH_STATUS = 0
BEGIN
	SET @CADENASQL = 'DROP INDEX ' + @NOMBRE_TABLE + '.' + @NOMBRE_FOREINGKEY
	EXEC SP_EXECUTESQL  @CADENASQL

	FETCH NEXT FROM CUR_TABLAS_CAMPOS_CATALOGO INTO @NOMBRE_TABLE, @NOMBRE_FOREINGKEY
END
CLOSE CUR_TABLAS_CAMPOS_CATALOGO
DEALLOCATE CUR_TABLAS_CAMPOS_CATALOGO;
--/
GO


-- ----------------------------
-- procedure structure for SP_INT_REGISTRA_LOG
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_INT_REGISTRA_LOG]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_INT_REGISTRA_LOG]
GO

CREATE PROCEDURE [dbo].[SP_INT_REGISTRA_LOG]
(@ano_eje NUMERIC(4), @sec_ejec NUMERIC(6),@sec_aud NUMERIC(10), @mensaje VARCHAR(100), @retorno NUMERIC(2) OUT)
AS
BEGIN
     DECLARE @resultado numeric(1),
             @num_id    numeric(14),
             @fecha     datetime
     
     SELECT @num_id = COALESCE(max(num_id),0)
       FROM sig_int_log
     
     select @num_id = @num_id + 1
     select @fecha = getdate()
     
     INSERT INTO sig_int_log
                 (num_id, ano_eje, sec_ejec, sec_aud, mensaje, fecha)
          VALUES (@num_id, @ano_eje, @sec_ejec, @sec_aud, @mensaje, @fecha)
     
     IF @@ERROR < 0
	select @retorno = -5
     ELSE   
        select @retorno = 1   						
END
GO


-- ----------------------------
-- procedure structure for SP_REPORTE_PAAC_CONSUCODE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_REPORTE_PAAC_CONSUCODE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_REPORTE_PAAC_CONSUCODE]
GO

CREATE PROCEDURE [dbo].[SP_REPORTE_PAAC_CONSUCODE]
(@PN_ANIO NUMERIC, @PN_EJECUTORA NUMERIC, @ps_tipo_CONSOLID varchar(1),
@ps_tipo_generacion varchar(1),@PN_REPORTE NUMERIC )
AS
SET NOCOUNT ON
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
BEGIN

DECLARE @CANO_EJE numeric(4, 0)
DECLARE @CSEC_EJEC numeric(6, 0)
DECLARE @CTIPO_CONSOLID char(1)
DECLARE @CNRO_CONSOLID numeric(5, 0)
DECLARE @CTIPO_GENERACION char(1)
DECLARE @CITEM_UNICO numeric(4, 0)
DECLARE @CPRECEDENTE varchar(1)
DECLARE @CTIPO_PROCESO varchar(2)
DECLARE @CNOM_TIPO_PROCESO varchar(250)
DECLARE @CTIPO_CIIU varchar(1)
DECLARE @CCATEGORIA_CIIU varchar(2)
DECLARE @CGRUPO_CIIU varchar(2)
DECLARE @COBJETO varchar(2)
DECLARE @CNOM_OBJETO varchar(250)
DECLARE @CESPEC_TECNICAS varchar(100)
DECLARE @CVALOR_MONEDA  numeric(16, 2)
DECLARE @CMONEDA varchar(6)
DECLARE @CFUENTE varchar(250)
DECLARE @CMES_PROPUESTO varchar(2)
DECLARE @CMODAL_COMPRA varchar(2)
DECLARE @CNOM_MODAL_COMPRA varchar(250)
DECLARE @CORGANO_CONVOCACION varchar(60)
DECLARE @CDEPARTAMENTO varchar(2)
DECLARE @CPROVINCIA varchar(2)
DECLARE @CDISTRITO varchar(2)
DECLARE @COBSERVACIONES varchar(100)
DECLARE @ESIGLAS varchar(40)
DECLARE @ESECTOR varchar(2)
DECLARE @EPLIEGO varchar(3)
DECLARE @PNOM_PLIEGO varchar(150)
DECLARE @ENOM_EJECUTORA varchar(150)
DECLARE @ERUC_EJEC varchar(11)
DECLARE @CINSTRUMENTO varchar(100)
DECLARE @CFLAG_PAAC varchar(1)
DECLARE @CNRO_PAAC varchar(4)
DECLARE @CNIVEL_DESCENT varchar(100)
DECLARE @CCONVOCACION_PROCESO varchar(1)
DECLARE @Cmodalidad_csc varchar(2)
DECLARE @INRO_ITEM numeric(6, 0)
DECLARE @ITIPO_BIEN varchar(1)
DECLARE @IGRUPO_BIEN varchar(2)
DECLARE @ICLASE_BIEN varchar(2)
DECLARE @IFAMILIA_BIEN varchar(4)
DECLARE @IITEM_BIEN varchar(4)
DECLARE @INOMBRE_ITEM varchar(100)
DECLARE @IUNIDAD_MEDIDA numeric(3, 0)
DECLARE @INOMBRE_UNIDAD varchar(100)
DECLARE @ICANTIDAD numeric(20, 6)
DECLARE @IVALOR_MONEDA numeric(16, 2)
DECLARE @NUM numeric(6, 0)
DECLARE @NUM_CUENTA numeric(6, 0)
DECLARE @ls_cadena VARCHAR(250)
DECLARE @ls_fuente VARCHAR(2)

------ Valores iniciales ------------
--set nocount on
--BEGIN TRAN
--ROLLBACK 
--set nocount off 
DECLARE CUR_DATA01 CURSOR SCROLL FOR
SELECT 
SIG_PAAC_CONSOLIDADO.ANO_EJE,
SIG_PAAC_CONSOLIDADO.SEC_EJEC,
SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID,
SIG_PAAC_CONSOLIDADO.NRO_CONSOLID,
SIG_PAAC_CONSOLIDADO.TIPO_GENERACION,
( SELECT COUNT(*)
  FROM SIG_PAAC_ITEM WITH ( NOLOCK )
  WHERE
  SIG_PAAC_CONSOLIDADO.ANO_EJE = SIG_PAAC_ITEM.ANO_EJE AND
  SIG_PAAC_CONSOLIDADO.SEC_EJEC = SIG_PAAC_ITEM.SEC_EJEC AND
  SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID =   SIG_PAAC_ITEM.TIPO_CONSOLID AND
  SIG_PAAC_CONSOLIDADO.NRO_CONSOLID =   SIG_PAAC_ITEM.NRO_CONSOLID AND
  SIG_PAAC_CONSOLIDADO.TIPO_GENERACION =   SIG_PAAC_ITEM.TIPO_GENERACION ),
SIG_PAAC_CONSOLIDADO.PRECEDENTE,
SIG_PAAC_CONSOLIDADO.TIPO_PROCESO,
(SELECT sig_maestro_proceso.descripcion 
 FROM sig_maestro_proceso
 WHERE 
 sig_maestro_proceso.ano_eje = SIG_PAAC_CONSOLIDADO.ANO_EJE AND  
 sig_maestro_proceso.tipo_organismo = '01'  AND  
 sig_maestro_proceso.codigo = 'TIPO_PROCESO' AND
 sig_maestro_proceso.codigo_det = SIG_PAAC_CONSOLIDADO.TIPO_PROCESO ),
SIG_PAAC_CONSOLIDADO.TIPO_CIIU,
SIG_PAAC_CONSOLIDADO.CATEGORIA_CIIU,
SIG_PAAC_CONSOLIDADO.GRUPO_CIIU,
SIG_PAAC_CONSOLIDADO.OBJETO,
( SELECT codigo_general_det.descripcion
  FROM codigo_general_det  
  WHERE 
  codigo_general_det.codigo = 'OBJETO' AND
  codigo_general_det.codigo_det = SIG_PAAC_CONSOLIDADO.OBJETO ) , 
SIG_PAAC_CONSOLIDADO.ESPEC_TECNICAS,
SIG_PAAC_CONSOLIDADO.VALOR_MONEDA,
SIG_PAAC_CONSOLIDADO.MONEDA,
SIG_PAAC_CONSOLIDADO.MES_PROPUESTO,
SIG_PAAC_CONSOLIDADO.MODAL_COMPRA,
( SELECT codigo_general_det.descripcion
  FROM codigo_general_det  
  WHERE 
  codigo_general_det.codigo = 'MODALIDAD_COMPRA'  AND  
  codigo_general_det.codigo_det = SIG_PAAC_CONSOLIDADO.MODAL_COMPRA ),
SIG_PAAC_CONSOLIDADO.ORGANO_CONVOCACION,
SIG_PAAC_CONSOLIDADO.DEPARTAMENTO,
SIG_PAAC_CONSOLIDADO.PROVINCIA,
SIG_PAAC_CONSOLIDADO.DISTRITO,
SIG_PAAC_CONSOLIDADO.OBSERVACIONES,
EJECUTORA.SIGLAS,
EJECUTORA.SECTOR,
EJECUTORA.PLIEGO,
PLIEGO.NOMBRE,
EJECUTORA.NOMBRE,
EJECUTORA.RUC_EJEC,
( SELECT sig_parametro_ejecutora_anio.valor
  FROM sig_parametro_ejecutora_anio  
  WHERE 
  SIG_PARAMETRO_EJECUTORA_ANIO.ANO_EJE = SIG_PAAC_CONSOLIDADO.ANO_EJE AND
  SIG_PARAMETRO_EJECUTORA_ANIO.SEC_EJEC = SIG_PAAC_CONSOLIDADO.SEC_EJEC AND
  SIG_PARAMETRO_EJECUTORA_ANIO.COD_MAESTRO = 'INSTRUMENTO_PAAC'),
sig_paac_consolidado.flag_paac,
SIG_PAAC_CONSOLIDADO.NRO_PAAC,
SIG_PAAC_CONSOLIDADO.nivel_descent,
SIG_PAAC_CONSOLIDADO.CONVOCACION_PROCESO,
SIG_PAAC_CONSOLIDADO.modalidad_csc
FROM SIG_PAAC_CONSOLIDADO, EJECUTORA, PLIEGO
WHERE 
SIG_PAAC_CONSOLIDADO.SEC_EJEC = EJECUTORA.SEC_EJEC AND
EJECUTORA.SECTOR = PLIEGO.SECTOR AND
EJECUTORA.PLIEGO = PLIEGO.PLIEGO AND
SIG_PAAC_CONSOLIDADO.ANO_EJE = @PN_ANIO AND
SIG_PAAC_CONSOLIDADO.SEC_EJEC = @PN_EJECUTORA AND
SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID =  @ps_tipo_CONSOLID AND
SIG_PAAC_CONSOLIDADO.TIPO_GENERACION = @ps_tipo_generacion AND
sig_paac_consolidado.flag_paac NOT IN ('0','3','5') and
sig_paac_consolidado.nro_paac <> '0000'
ORDER BY 
SIG_PAAC_CONSOLIDADO.NRO_PAAC

OPEN CUR_DATA01
FETCH CUR_DATA01 INTO @CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
@CTIPO_GENERACION,@CITEM_UNICO ,@CPRECEDENTE ,@CTIPO_PROCESO,@CNOM_TIPO_PROCESO,
@CTIPO_CIIU,@CCATEGORIA_CIIU,@CGRUPO_CIIU,@COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
@CVALOR_MONEDA,@CMONEDA,@CMES_PROPUESTO,@CMODAL_COMPRA,@CNOM_MODAL_COMPRA,
@CORGANO_CONVOCACION,@CDEPARTAMENTO,@CPROVINCIA,@CDISTRITO,@COBSERVACIONES,
@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,@ERUC_EJEC,@CINSTRUMENTO,
@CFLAG_PAAC,@CNRO_PAAC,@CNIVEL_DESCENT,@CCONVOCACION_PROCESO,@Cmodalidad_csc

WHILE @@FETCH_STATUS = 0
BEGIN

	SELECT @NUM_CUENTA = COUNT(*)
	FROM SIG_PAAC_ITEM, CATALOGO_BIEN_SERV, UNIDAD_MEDIDA
	WHERE
	SIG_PAAC_ITEM.SEC_EJEC = CATALOGO_BIEN_SERV.SEC_EJEC AND
	SIG_PAAC_ITEM.TIPO_BIEN = CATALOGO_BIEN_SERV.TIPO_BIEN AND
	SIG_PAAC_ITEM.GRUPO_BIEN = CATALOGO_BIEN_SERV.GRUPO_BIEN AND
	SIG_PAAC_ITEM.CLASE_BIEN = CATALOGO_BIEN_SERV.CLASE_BIEN AND
	SIG_PAAC_ITEM.FAMILIA_BIEN = CATALOGO_BIEN_SERV.FAMILIA_BIEN AND
	SIG_PAAC_ITEM.ITEM_BIEN = CATALOGO_BIEN_SERV.ITEM_BIEN AND
	SIG_PAAC_ITEM.UNIDAD_MEDIDA = UNIDAD_MEDIDA.UNIDAD_MEDIDA AND
	SIG_PAAC_ITEM.ANO_EJE = @CANO_EJE AND
	SIG_PAAC_ITEM.SEC_EJEC = @CSEC_EJEC AND
	SIG_PAAC_ITEM.TIPO_CONSOLID = @CTIPO_CONSOLID AND
	SIG_PAAC_ITEM.TIPO_GENERACION = @CTIPO_GENERACION and
	SIG_PAAC_ITEM.nro_consolid = @CNRO_CONSOLID

	IF @NUM_CUENTA IS NULL 
	BEGIN
		SELECT @NUM_CUENTA = 0 
	END


	IF @NUM_CUENTA > 0 
	BEGIN

		DECLARE c_datos CURSOR FOR	
		SELECT distinct fuente_financ
		FROM  sig_paac_metas
		WHERE 
		ano_eje = @CANO_EJE and
		sec_ejec = @CSEC_EJEC  and
		tipo_consolid = @CTIPO_CONSOLID and
		nro_consolid = @CNRO_CONSOLID and
		tipo_generacion = @CTIPO_GENERACION
			 
		OPEN  c_datos
		FETCH c_datos INTO @ls_fuente

		SELECT @LS_CADENA = ''
		WHILE @@FETCH_STATUS = 0
		BEGIN

			if @ls_fuente IS NULL 
			BEGIN
				SELECT @ls_fuente = ''
			END 

			if Rtrim(LTRIM(@ls_fuente)) <> '' 
			BEGIN
				if Rtrim(LTRIM(@ls_cadena)) <> '' 
				BEGIN
					SELECT @ls_cadena = @ls_fuente + ' , '+ @ls_cadena
				END
				else
				BEGIN
					SELECT @ls_cadena = @ls_fuente
				END
			END
			FETCH c_datos INTO @ls_fuente
		END
		CLOSE c_datos
		DEALLOCATE c_datos

		SELECT @CFUENTE = @ls_cadena

		SELECT @NUM = 0

		DECLARE CUR_DATA01_ITEM CURSOR FOR
		SELECT 
		SIG_PAAC_ITEM.TIPO_BIEN,
		SIG_PAAC_ITEM.GRUPO_BIEN,
		SIG_PAAC_ITEM.CLASE_BIEN,
		SIG_PAAC_ITEM.FAMILIA_BIEN,
		SIG_PAAC_ITEM.ITEM_BIEN,
		CATALOGO_BIEN_SERV.NOMBRE_ITEM,
		SIG_PAAC_ITEM.UNIDAD_MEDIDA,
		UNIDAD_MEDIDA.NOMBRE,
		SUM(SIG_PAAC_ITEM.CANTIDAD) AS WCANTIDAD ,
		SUM(SIG_PAAC_ITEM.VALOR_MONEDA) AS WVALOR_MONEDA
		FROM SIG_PAAC_ITEM, CATALOGO_BIEN_SERV, UNIDAD_MEDIDA
		WHERE
		SIG_PAAC_ITEM.SEC_EJEC = CATALOGO_BIEN_SERV.SEC_EJEC AND
		SIG_PAAC_ITEM.TIPO_BIEN = CATALOGO_BIEN_SERV.TIPO_BIEN AND
		SIG_PAAC_ITEM.GRUPO_BIEN = CATALOGO_BIEN_SERV.GRUPO_BIEN AND
		SIG_PAAC_ITEM.CLASE_BIEN = CATALOGO_BIEN_SERV.CLASE_BIEN AND
		SIG_PAAC_ITEM.FAMILIA_BIEN = CATALOGO_BIEN_SERV.FAMILIA_BIEN AND
		SIG_PAAC_ITEM.ITEM_BIEN = CATALOGO_BIEN_SERV.ITEM_BIEN AND
		SIG_PAAC_ITEM.UNIDAD_MEDIDA = UNIDAD_MEDIDA.UNIDAD_MEDIDA AND
		SIG_PAAC_ITEM.ANO_EJE = @CANO_EJE AND
		SIG_PAAC_ITEM.SEC_EJEC = @CSEC_EJEC AND
		SIG_PAAC_ITEM.TIPO_CONSOLID = @CTIPO_CONSOLID AND
		SIG_PAAC_ITEM.TIPO_GENERACION = @CTIPO_GENERACION and
		SIG_PAAC_ITEM.nro_consolid = @CNRO_CONSOLID
		GROUP BY 
		SIG_PAAC_ITEM.TIPO_BIEN,
		SIG_PAAC_ITEM.GRUPO_BIEN,
		SIG_PAAC_ITEM.CLASE_BIEN,
		SIG_PAAC_ITEM.FAMILIA_BIEN,
		SIG_PAAC_ITEM.ITEM_BIEN,
		CATALOGO_BIEN_SERV.NOMBRE_ITEM,
		SIG_PAAC_ITEM.UNIDAD_MEDIDA,
		UNIDAD_MEDIDA.NOMBRE
		ORDER BY
		CATALOGO_BIEN_SERV.NOMBRE_ITEM

		OPEN CUR_DATA01_ITEM
		FETCH CUR_DATA01_ITEM INTO @ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,
		@IFAMILIA_BIEN,@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,
		@INOMBRE_UNIDAD,@ICANTIDAD,@IVALOR_MONEDA 

		WHILE @@FETCH_STATUS = 0
		BEGIN
			SELECT @NUM = @NUM + 1

			INSERT INTO TMP_CONSUCODE_SIG_PAAC_CONS 
			(
			CREPORTE,CANO_EJE,CSEC_EJEC,CTIPO_CONSOLID,CNRO_CONSOLID,
			CTIPO_GENERACION,CITEM_UNICO,CPRECEDENTE,CTIPO_PROCESO,
			CNOM_TIPO_PROCESO,CTIPO_CIIU,CCATEGORIA_CIIU,CGRUPO_CIIU,
			COBJETO,CNOM_OBJETO,CESPEC_TECNICAS,CVALOR_MONEDA,
			CMONEDA,CFUENTE,CMES_PROPUESTO,CMODAL_COMPRA,CNOM_MODAL_COMPRA,
			CORGANO_CONVOCACION,CDEPARTAMENTO,CPROVINCIA,CDISTRITO,
			COBSERVACIONES,ESIGLAS,ESECTOR,EPLIEGO,PNOM_PLIEGO,
			ENOM_EJECUTORA,ERUC_EJEC,CINSTRUMENTO,CFLAG_PAAC,
			CNRO_PAAC,CNIVEL_DESCENT,CCONVOCACION_PROCESO,Cmodalidad_csc,
			INRO_ITEM,ITIPO_BIEN,IGRUPO_BIEN,ICLASE_BIEN,IFAMILIA_BIEN,
			IITEM_BIEN,INOMBRE_ITEM,IUNIDAD_MEDIDA,INOMBRE_UNIDAD,
			ICANTIDAD,IVALOR_MONEDA
			)
			VALUES
			(		
			@PN_REPORTE,@CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
			@CTIPO_GENERACION,@CITEM_UNICO ,@CPRECEDENTE ,@CTIPO_PROCESO,
			@CNOM_TIPO_PROCESO,@CTIPO_CIIU,@CCATEGORIA_CIIU,@CGRUPO_CIIU,
			@COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,@CVALOR_MONEDA,
			@CMONEDA,@CFUENTE, @CMES_PROPUESTO,@CMODAL_COMPRA,@CNOM_MODAL_COMPRA,
			@CORGANO_CONVOCACION,@CDEPARTAMENTO,@CPROVINCIA,@CDISTRITO,
			@COBSERVACIONES,@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,
			@ENOM_EJECUTORA,@ERUC_EJEC,@CINSTRUMENTO,@CFLAG_PAAC,
			@CNRO_PAAC,@CNIVEL_DESCENT,@CCONVOCACION_PROCESO,@Cmodalidad_csc,
			@NUM,@ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,@IFAMILIA_BIEN,
			@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,@INOMBRE_UNIDAD,
			@ICANTIDAD,@IVALOR_MONEDA 
			)

			IF @@ERROR <> 0
			BEGIN
				CLOSE CUR_DATA01_ITEM
				DEALLOCATE CUR_DATA01_ITEM
				CLOSE CUR_DATA01
				DEALLOCATE CUR_DATA01
				GOTO ERROR
			END

			FETCH CUR_DATA01_ITEM INTO @ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,
			@IFAMILIA_BIEN,@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,
			@INOMBRE_UNIDAD,@ICANTIDAD,@IVALOR_MONEDA 


		END
		CLOSE CUR_DATA01_ITEM
		DEALLOCATE CUR_DATA01_ITEM
	END

	FETCH CUR_DATA01 INTO @CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
	@CTIPO_GENERACION,@CITEM_UNICO ,@CPRECEDENTE ,@CTIPO_PROCESO,@CNOM_TIPO_PROCESO,
	@CTIPO_CIIU,@CCATEGORIA_CIIU,@CGRUPO_CIIU,@COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
	@CVALOR_MONEDA,@CMONEDA,@CMES_PROPUESTO,@CMODAL_COMPRA,@CNOM_MODAL_COMPRA,
	@CORGANO_CONVOCACION,@CDEPARTAMENTO,@CPROVINCIA,@CDISTRITO,@COBSERVACIONES,
	@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,@ERUC_EJEC,@CINSTRUMENTO,
	@CFLAG_PAAC,@CNRO_PAAC,@CNIVEL_DESCENT,@CCONVOCACION_PROCESO,@Cmodalidad_csc

END

CLOSE CUR_DATA01
DEALLOCATE CUR_DATA01

--COMMIT --TRAN
--set nocount off
RETURN 0
 
ERROR:
--  ROLLBACK --TRAN
--set nocount off
   RETURN 1;

END
--/
GO


