-- ----------------------------
-- procedure structure for sp_presupuesto_siaf_json
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_presupuesto_siaf_json]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[sp_presupuesto_siaf_json]
GO

CREATE PROCEDURE [dbo].[sp_presupuesto_siaf_json]
(
    @_parametro NVARCHAR(MAX)
)
AS
BEGIN

SET NOCOUNT ON;

DECLARE 
    @ANIO INT,
    @SEC_FUNC VARCHAR(30),
    @NOMBRE_META VARCHAR(500);

SELECT
    @ANIO = JSON_VALUE(@_parametro, '$.ANIO'),
    @SEC_FUNC = JSON_VALUE(@_parametro, '$.SEC_FUNC'),
    @NOMBRE_META = JSON_VALUE(@_parametro, '$.NOMBRE_META');

select 
json_query(
(
SELECT
	
    resumen.TOTAL_PPTO_SIAF AS SALDO_INICIAL_SIAF,
    resumen.TOTAL_CONSUMO AS SALDO_CONSUMIDO,
    resumen.TOTAL_SALDO_FINAL AS SALDO_FINAL,
    resumen.CANTIDAD_METAS,
    resumen.TOTAL_REGISTROS,

    (
        SELECT
            CAST(STP.FUENTE_FINANC AS VARCHAR(10)) AS FUENTE_FINANC,
            CAST(FF.FUENTE_FINANC_AGREGADA AS VARCHAR(50)) AS FUENTE_FINANC_AGREGADA,
            CAST(STP.SEC_FUNC AS VARCHAR(30)) AS SEC_FUNC,
            CAST(M.nombre AS VARCHAR(500)) AS NOMBRE_META,
            CAST(SCG.CLASIFICADOR AS VARCHAR(50)) AS CLASIFICADOR,
            CAST(SCG.NOMBRE_CLASIF AS VARCHAR(500)) AS NOMBRE_CLASIF,

            CAST(
                STP.PPTO_SIAF 
                - STP.PPTO_DEF 
                - STP.PPTO_RESER 
            AS DECIMAL(18,2)) AS SALDO_SIAF

        FROM SIG_TECHO_PRESUPUESTO STP
        INNER JOIN META M
            ON STP.ANO_EJE = M.ANO_EJE
            AND STP.SEC_EJEC = M.SEC_EJEC
            AND STP.SEC_FUNC = M.SEC_FUNC

        INNER JOIN SIG_CLASIFICADOR_GASTO SCG
            ON STP.ANO_EJE = SCG.ANO_EJE
            AND STP.CLASIFICADOR = SCG.CLASIFICADOR

        LEFT JOIN FUENTE_FINANC FF
            ON FF.ANO_EJE = STP.ANO_EJE
            AND FF.ORIGEN = STP.ORIGEN
            AND FF.FUENTE_FINANC = STP.FUENTE_FINANC

        WHERE
            STP.ANO_EJE = @ANIO
            AND STP.FLAG_META_APROB = '1'
            AND STP.INDICADOR = '4'
            AND STP.PPTO_MODIF > 0
            AND (@SEC_FUNC IS NULL OR STP.SEC_FUNC = @SEC_FUNC)
            AND (@NOMBRE_META IS NULL OR M.nombre LIKE '%' + @NOMBRE_META + '%')

        FOR JSON PATH
    ) AS data

FROM
(
    SELECT
        SUM(STP.PPTO_SIAF) AS TOTAL_PPTO_SIAF,
        SUM(STP.PPTO_DEF + STP.PPTO_RESER) AS TOTAL_CONSUMO,
        SUM(STP.PPTO_SIAF - STP.PPTO_DEF - STP.PPTO_RESER) AS TOTAL_SALDO_FINAL,
        COUNT(DISTINCT STP.SEC_FUNC) AS CANTIDAD_METAS,
        COUNT(*) AS TOTAL_REGISTROS

    FROM SIG_TECHO_PRESUPUESTO STP

    INNER JOIN META M
        ON STP.ANO_EJE = M.ANO_EJE
        AND STP.SEC_EJEC = M.SEC_EJEC
        AND STP.SEC_FUNC = M.SEC_FUNC

    INNER JOIN SIG_CLASIFICADOR_GASTO SCG
        ON STP.ANO_EJE = SCG.ANO_EJE
        AND STP.CLASIFICADOR = SCG.CLASIFICADOR

    WHERE
        STP.ANO_EJE = @ANIO
        AND STP.FLAG_META_APROB = '1'
        AND STP.INDICADOR = '4'
        AND STP.PPTO_MODIF > 0
        AND (@SEC_FUNC IS NULL OR STP.SEC_FUNC = @SEC_FUNC)
        AND (@NOMBRE_META IS NULL OR M.nombre LIKE '%' + @NOMBRE_META + '%')

) resumen

FOR JSON PATH
)) as data
END
GO


