       SIG_PATRIMONIO_INM.ADJ_DOCUMENTOS_ALTA,
       SIG_PATRIMONIO_INM.ADJ_DOCUMENTOS_BAJA,
       SIG_PATRIMONIO_INM.IND_SOLICITUD_DACION,
       SIG_PATRIMONIO_INM.IND_ACTA_DECOMISO,
       SIG_PATRIMONIO_INM.IND_SENTENCIA,
       SIG_PATRIMONIO_INM.IND_SOLICITUD_TRANSFERENCIA,
       COALESCE(SIG_PATRIMONIO_INM.NRO_RESOLUCION,''),
       SIG_PATRIMONIO_INM.ADJ_ACTA_RESOLUCION,
       COALESCE(SIG_PATRIMONIO_INM.OBSERVACIONES_ALTA,''),
       SIG_PATRIMONIO_INM.ADJ_PARTIDA_REGISTRAL,
       SIG_PATRIMONIO_INM.ADJ_PLANO_PERIMIETRICO,
       SIG_PATRIMONIO_INM.ADJ_PLANO_UBICAC,
       SIG_PATRIMONIO_INM.ADJ_MEMORIA_DESCRIPT,
       SIG_PATRIMONIO_INM.ADJ_TASACION,
       SIG_PATRIMONIO_INM.ADJ_FOTOGRAFIAS,       
       COALESCE(SIG_PATRIMONIO_INM.MES_PROCESO,''),
       COALESCE(SIG_PATRIMONIO_INM.TIPO_MOVIMTO,''),
       COALESCE(CONVERT(VARCHAR(10), SIG_PATRIMONIO_INM.FECHA_MOVIMTO,111),''),       
       COALESCE(SIG_PATRIMONIO_INM.SEDE,0),
       COALESCE(SIG_PATRIMONIO_INM.NRO_RESOLUC,''),
       COALESCE(SIG_PATRIMONIO_INM.FLAG_CIERRE,''),       
       COALESCE(CONVERT(VARCHAR(10), SIG_PATRIMONIO_INM.FECHA_CIERRE,111),''),     
       COALESCE(SIG_PATRIMONIO_INM.RP_TITULAR,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_OFICINA,''),
       COALESCE(CONVERT(VARCHAR(10), SIG_PATRIMONIO_INM.RP_FECHA_INSCRIPCION,111),''),       
       COALESCE(SIG_PATRIMONIO_INM.RP_TOMO,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_FOJAS,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_ASIENTO,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_FICHA,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_PARTIDA_ELECTRONICA,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_CODIGO_PREDIO,''),
       COALESCE(SIG_PATRIMONIO_INM.RP_AREA_TERRENO,0),
       COALESCE(SIG_PATRIMONIO_INM.RP_AREA_CONSTRUIDA, 0),
       COALESCE(SIG_PATRIMONIO_INM.RP_OBSERVACIONES,''),
       COALESCE(SIG_PATRIMONIO_INM.TIPO_INMUEBLE_A,''),
       COALESCE(SIG_PATRIMONIO_INM.NRO_ACTA,''),
       COALESCE(CONVERT(VARCHAR(10), SIG_PATRIMONIO_INM.FECHA_ACTA,111),''),  
       COALESCE(CONVERT(VARCHAR(10), SIG_PATRIMONIO_INM.FECHA_RESOL,111),''),
       COALESCE(SIG_PATRIMONIO_INM.SEC_EJEC2,0)
FROM   SIG_INM_COMPONENTE,
       SIG_INM_UNIDAD_ACTIVO,
       SIG_PATRIMONIO_INM
WHERE  (
           SIG_INM_UNIDAD_ACTIVO.SEC_EJEC = SIG_INM_COMPONENTE.SEC_EJEC
       )
       AND (
               SIG_INM_UNIDAD_ACTIVO.SECUENCIA = SIG_INM_COMPONENTE.SECUENCIA
           )
       AND (
               SIG_INM_UNIDAD_ACTIVO.SEC_UNIDAD_ACTIVO = SIG_INM_COMPONENTE.SEC_UNIDAD_ACTIVO
           )
       AND (
               SIG_PATRIMONIO_INM.SEC_EJEC = SIG_INM_UNIDAD_ACTIVO.SEC_EJEC
           )
       AND (
               SIG_PATRIMONIO_INM.SECUENCIA = SIG_INM_UNIDAD_ACTIVO.SECUENCIA
           )
       AND SIG_PATRIMONIO_INM.ANO_EJE = @P_ANO_EJE 
       AND SIG_INM_COMPONENTE.SEC_EJEC = @P_SEC_EJEC
       
       
 END
GO


-- ----------------------------
-- procedure structure for SP_CREA_PRE_SUB_CENT_FINA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CREA_PRE_SUB_CENT_FINA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CREA_PRE_SUB_CENT_FINA]
GO

CREATE PROCEDURE [dbo].[SP_CREA_PRE_SUB_CENT_FINA]
@Pano_eje	numeric	(4,0),
@Psec_ejec	numeric	(6,0)
AS
BEGIN
TRUNCATE TABLE SIG_PRE_SUB_CENTRO_FINALIDAD
INSERT INTO SIG_PRE_SUB_CENTRO_FINALIDAD
SELECT distinct 
		MP.ano_eje,
		 MP.sec_ejec,
		 MP.nro_fase,
		MP.sec_func_prop,
		SPS.SEC_ESTABLEC,
		 SIG_META_X_TAREA.SUBFINALIDAD,
		mp.programa_institucional + mp.funcion + mp.programa + mp.sub_programa + mp.act_proy + mp.componente + mp.finalidad AS CADENA_FUNCIONAL,
		 mp.unidad_medida,
		 SIG_META_X_TAREA.ID_SUB_FINALIDAD	 
  FROM sig_centro_costo_tarea  CCT,
       sig_tarea_estrategico SIG_META_X_TAREA,
       SIG_SUB_FINALIDAD,
	   SIG_PPR_META_PROPUESTA MP,
	   sig_centro_costo SCC,
	   SIG_PPR_SEDE SPS,
	  sig_metas_prop_x_centro MXC
 WHERE  	CCT.sec_ejec = SIG_META_X_TAREA.SEC_EJEC  and  
       CCT.ano_eje = SIG_META_X_TAREA.ANO_EJE  and  
       CCT.tipo_tarea = SIG_META_X_TAREA.TIPO_TAREA  and  
       CCT.nivel_tarea = SIG_META_X_TAREA.NIVEL_TAREA  and  
       CCT.codigo_tarea = SIG_META_X_TAREA.TAREA_GENERAL  and  
	    @Pano_eje >= @Pano_eje AND
       CCT.ano_eje = @Pano_eje  AND  
       CCT.sec_ejec = @Psec_ejec  AND  
         SIG_SUB_FINALIDAD.ANO_EJE                = SIG_META_X_TAREA.ANO_EJE                AND
       SIG_SUB_FINALIDAD.SUB_FINALIDAD          = SIG_META_X_TAREA.SUBFINALIDAD           AND
       SIG_SUB_FINALIDAD.ID_SUB_FINALIDAD          = SIG_META_X_TAREA.ID_SUB_FINALIDAD           AND
       SIG_SUB_FINALIDAD.PROGRAMA_INSTITUCIONAL = SIG_META_X_TAREA.PROGRAMA_INSTITUCIONAL AND
       SIG_SUB_FINALIDAD.ESTADO                 = 'A'		and		MP.ano_eje       = SIG_META_X_TAREA.ano_eje and	 
	    MP.sec_ejec      = SIG_META_X_TAREA.sec_ejec and
	   (@Pano_eje < 2012 and  MP.finalidad     = substring(SIG_META_X_TAREA.subfinalidad,1,5) or
		 @Pano_eje >= 2012 and substring(MP.act_proy,2,8)     = SIG_META_X_TAREA.subfinalidad )		and
		CCT.sec_ejec = SCC.SEC_EJEC AND
		CCT.ano_eje = SCC.ANO_EJE  AND
		CCT.centro_costo  = SCC.CENTRO_COSTO		and
		  SPS.ANO_EJE      = SCC.ANO_EJE  and	  
		 SPS.SEC_EJEC     = SCC.SEC_EJEC and
		 SPS.pliego       = SCC.pliego and
		 SPS.sede         = SCC.sede AND
		SCC.ano_eje       = SPS.ano_eje and	 
		 SCC.sec_ejec      = SPS.sec_ejec and
		 scc.centro_costo  = mxc.centro_costo and
		mxc.ano_eje       = MP.ano_eje and	 
		 mxc.sec_ejec      = MP.sec_ejec and
		 mxc.sec_func_prop = MP.SEC_FUNC_PROP
union 
SELECT	
		MP.ano_eje,
		 MP.sec_ejec,
		 MP.nro_fase,
		MP.sec_func,
		SPS.SEC_ESTABLEC,
		 SIG_META_X_TAREA.SUBFINALIDAD,
		mp.programa_institucional + mp.funcion + mp.programa + mp.sub_programa + mp.act_proy + mp.componente + mp.finalidad AS CADENA_FUNCIONAL,
		 mp.unidad_medida,
 SIG_META_X_TAREA.ID_SUB_FINALIDAD
  FROM  sig_centro_costo_tarea CCT,   
        sig_tarea_estrategico SIG_META_X_TAREA,
        SIG_SUB_FINALIDAD,
		SIG_PPR_META_PROPUESTA MP,
		sig_centro_costo SCC,
		SIG_PPR_SEDE SPS,
	    sig_metas_x_centro MXC
 WHERE CCT.sec_ejec = SIG_META_X_TAREA.SEC_EJEC  and  
       CCT.ano_eje = SIG_META_X_TAREA.ANO_EJE  and  
       CCT.tipo_tarea = SIG_META_X_TAREA.TIPO_TAREA  and  
       CCT.nivel_tarea = SIG_META_X_TAREA.NIVEL_TAREA  and  
       CCT.codigo_tarea = SIG_META_X_TAREA.TAREA_GENERAL  and  
	    @Pano_eje >= @Pano_eje AND
       CCT.ano_eje = @Pano_eje  AND  
       CCT.sec_ejec = @Psec_ejec  AND  
       SIG_SUB_FINALIDAD.ANO_EJE                = SIG_META_X_TAREA.ANO_EJE                AND
       SIG_SUB_FINALIDAD.SUB_FINALIDAD          = SIG_META_X_TAREA.SUBFINALIDAD           AND
       SIG_SUB_FINALIDAD.ID_SUB_FINALIDAD          = SIG_META_X_TAREA.ID_SUB_FINALIDAD           AND
       SIG_SUB_FINALIDAD.PROGRAMA_INSTITUCIONAL = SIG_META_X_TAREA.PROGRAMA_INSTITUCIONAL AND
       SIG_SUB_FINALIDAD.ESTADO                 = 'A' AND
	   MP.ano_eje       = SIG_META_X_TAREA.ano_eje and	 
	   MP.sec_ejec      = SIG_META_X_TAREA.sec_ejec and
		(@Pano_eje < 2012 and  MP.finalidad     = substring(SIG_META_X_TAREA.subfinalidad,1,5) or
		 @Pano_eje >= 2012 and substring(MP.act_proy,2,8)     = SIG_META_X_TAREA.subfinalidad) and

		CCT.sec_ejec = SCC.SEC_EJEC AND
		CCT.ano_eje = SCC.ANO_EJE  AND
		CCT.centro_costo  = SCC.CENTRO_COSTO  AND

		  SPS.ANO_EJE      = SCC.ANO_EJE  and	  
		 SPS.SEC_EJEC     = SCC.SEC_EJEC and
		 SPS.pliego       = SCC.pliego and
		 SPS.sede         = SCC.sede 
AND
		SCC.ano_eje       = SPS.ano_eje and	 
		 SCC.sec_ejec      = SPS.sec_ejec and
		 scc.centro_costo  = mxc.centro_costo 
and
    	mxc.ano_eje       = MP.ano_eje and	 
		 mxc.sec_ejec      = MP.sec_ejec and
		 mxc.sec_func = MP.SEC_FUNC 
END
GO


