-- ----------------------------
-- function structure for SF_DIAS_HABILES
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_DIAS_HABILES]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_DIAS_HABILES]
GO

CREATE FUNCTION [dbo].[SF_DIAS_HABILES]
(
@ad_fecha_inicio_dt    DATETIME,
@ad_fecha_fin_dt       DATETIME
)
RETURNS INTEGER
AS
BEGIN

DECLARE @ll_dias_dif     INTEGER
DECLARE @ll_dias_sem     INTEGER
DECLARE @ll_dif_real     INTEGER
DECLARE @ll_item         INTEGER
DECLARE @ll_busqueda     INTEGER
DECLARE @ll_cont         INTEGER
DECLARE @ld_fecha_ref    DATE
DECLARE @ld_fecha_fin    DATE
DECLARE @ad_fecha_inicio DATE
DECLARE @ad_fecha_fin    DATE

SET @ll_cont     = 0
SET @ll_dif_real = 0
SET @ad_fecha_inicio = CONVERT(DATE,@ad_fecha_inicio_dt)
SET @ad_fecha_fin = CONVERT(DATE,@ad_fecha_fin_dt)

IF (@ad_fecha_fin > @ad_fecha_inicio)
BEGIN
	SET @ll_dias_dif = DATEDIFF(DAY, @ad_fecha_inicio, @ad_fecha_fin)
	 
	SET @ll_item    = 0
	 
	WHILE @ll_item <> @ll_dias_dif
	BEGIN
	    SET @ld_fecha_ref   = DATEADD(DAY, @ll_item, @ad_fecha_inicio)
	    SET @ll_dias_sem    = DATEPART(WEEKDAY, @ld_fecha_ref)
	 
	    SET @ll_busqueda = 0
	    IF ((@ll_dias_sem = 1) OR (@ll_dias_sem = 7))
	        SET @ll_busqueda = 1
	    ELSE
	        SELECT  @ll_busqueda    = COUNT(1)
	        FROM    FERIADO
	        WHERE   FECHA   = @ld_fecha_ref
	 
	    IF @ll_busqueda > 0
	        SET @ll_cont    = @ll_cont + 1
	 
	    SET @ll_item    = @ll_item + 1
	END
	 
	SET @ld_fecha_fin   = DATEADD(DAY, (@ll_cont * -1), @ad_fecha_fin)
	SET @ll_dif_real    = DATEDIFF(DAY, @ad_fecha_inicio, @ld_fecha_fin)
END
 
RETURN  @ll_dif_real
 
END
GO


-- ----------------------------
-- procedure structure for SP_INT_MOVIMIENTO_RESPUESTA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_INT_MOVIMIENTO_RESPUESTA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_INT_MOVIMIENTO_RESPUESTA]
GO

CREATE PROCEDURE [dbo].[SP_INT_MOVIMIENTO_RESPUESTA]
(@ano_eje NUMERIC(4), @sec_ejec NUMERIC(6),@sec_aud NUMERIC(10), @respuesta NUMERIC(2) OUT)
AS
BEGIN
     DECLARE @retorno   NUMERIC(2),
             @fase_siga NUMERIC(1),
             @etapa     NUMERIC(2),
             @fase_siaf NUMERIC(1),
             @OK        VARCHAR(10)
     
     SELECT @OK = 'FALSE'
     
     --Obtenemos la fase siga
     EXECUTE sp_int_fase_siga @ano_eje, @sec_ejec, @fase_siga OUT
     IF @fase_siga < 0
        BEGIN
             select @retorno = @fase_siga
             GOTO ERROR
        END
     
     --Obtenemos la fase siaf
     SELECT @etapa = etapa
       FROM sig_int_movimiento_aud
      WHERE ano_eje = @ano_eje and sec_ejec = @sec_ejec and sec_aud = @sec_aud
     
     IF @etapa = 0
        select @fase_siaf = 1
     IF @etapa = 11
        select @fase_siaf = 2
     IF @etapa = 21
        select @fase_siaf = 3
     IF @etapa = 31
        select @fase_siaf = 4
     
     --Si fase siga es igual a fase siaf
     IF @fase_siga = @fase_siaf
        BEGIN
             -- Ejecutar SP Carga de Maestros
             EXECUTE sp_int_carga_maestros @ano_eje, @sec_ejec, @sec_aud, @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             DELETE FROM SIG_TMP_META_PROPUESTA
                   WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -10
                     GOTO ERROR
                END
             
             INSERT INTO SIG_TMP_META_PROPUESTA
                         (ANO_EJE      , SEC_EJEC     , SEC_FUNC_PROP  , SEC_FUNC,
                          FUNCION      , PROGRAMA     , SUB_PROGRAMA   , ACT_PROY,
                          COMPONENTE   , META         , FINALIDAD      , NOMBRE,
                          MONTO        , CANTIDAD     , UNIDAD_MEDIDA  , PAIS,
                          DEPARTAMENTO , PROVINCIA    , DISTRITO       , ESTADO,
                          PORC_META    , TIPO_TAREA   , NIVEL_TAREA    , TAREA_GENERAL,
                          SEC_FUNC_REQ , PROGRAMA_INSTITUCIONAL, FLAG_NUEVO     , FLAG_PROCESAR,
                          FLAG_ACT_PROY, ESTRATEGIA_NACIONAL   , FLAG_ESTRATEGIA, TIPO_ESTRATEGIA)
                  SELECT DISTINCT
                         ano_eje     , sec_ejec     , secuencia_meta, NULL,
                         funcion     , programa     , sub_programa  , act_proy,
                         componente  , meta         , finalidad     , substring(nombre,1,150),
                         monto       , cantidad     , unidad_medida , NULL,
                         departamento, provincia    , distrito      , NULL,
                         NULL        , NULL         , NULL          , NULL,
                         NULL        , programa_ppto, 'S'           , NULL,
                         LEFT(act_proy,1),
                         Right('0000'+convert(varchar,secuencia_meta),4),
                         Case programa_ppto when '0000' then 'N' else 'S' end,
                         Case
                             when programa_ppto = '0000' then NULL
                         else
                            Case
                                when unidad_medida  = '60'   then 'G'
                                when programa_ppto <> '0000' then 'K'
                            end
                         end
                    FROM SIG_INT_TMP_META
                   WHERE ano_eje_mov = @ano_eje AND sec_ejec_mov = @sec_ejec and sec_aud_mov = @sec_aud
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -11
                     GOTO ERROR
                END
             
             --Actualizamos los parametros
             EXECUTE sp_int_parametro_ejecutora_anio_upd @ano_eje, @sec_ejec, 'FLAG_CARGA_SIAF', '1', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             EXECUTE sp_int_parametro_ejecutora_anio_upd @ano_eje, @sec_ejec, 'FLAG_CARGA_CN'  , '1', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             EXECUTE sp_int_parametro_ejecutora_anio_upd @ano_eje, @sec_ejec, 'FLAG_PROCESO_CN', '0', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             --Actualizamos el registro log
             EXECUTE sp_int_registra_log @ano_eje, @sec_ejec, @sec_aud, 'Registro de LOG - Meta Propuesta TMP', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             --Declaración de Variables
             DECLARE @porigen           varchar(10),
                     @pfuente_financ    varchar(10),
                     @pfuente_financ_agregada varchar(10),
                     @pMonto            numeric(19,2),
                     @pcorrelativo      numeric(5),
                     @pfuncion          varchar(2),
                     @pprograma         varchar(3),
                     @psub_programa     varchar(4),
                     @pprograma_ppto    varchar(4),
                     @pact_proy         varchar(7),
                     @pdepartamento     varchar(2),
                     @ptipo_transaccion numeric(1),
                     @pgenerica         varchar(1),
                     @pcategoria_gasto  varchar(1)
             
             SELECT @pcorrelativo = 1
             
             --Eliminamos los registros para la fase siaf antes de volverlas a insertar
             DELETE FROM sig_int_techo_ppto_carga
                   WHERE ano_eje  = @ano_eje  and
                         sec_ejec = @sec_ejec and
                         subfase  = @fase_siaf
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -12
                     GOTO ERROR
                END
             
             --Se procede a cargar techo
             IF @fase_siga = 2
                BEGIN
                     UPDATE SIG_INT_TMP_ASIGNACION
                        SET fuente_financ = substring( '00' + fuente_financ, LEN('00'+fuente_financ)-1, LEN('00'+fuente_financ))
                      WHERE ano_eje_mov  = @ano_eje  and
                            sec_ejec_mov = @sec_ejec and
                            sec_aud_mov  = @sec_aud
                     
                     IF @@ERROR < 0
                        BEGIN
                             select @retorno = -13
                             GOTO ERROR
                        END
                     
                     DECLARE c1 CURSOR FOR
                      SELECT b.origen, A.fuente_financ, b.fuente_financ_agregada, sum(A.monto_asignado)
                        FROM sig_int_tmp_asignacion A LEFT JOIN Fuente_Financ B
                             ON A.ano_eje = B.ano_eje and A.fuente_financ = B.fuente_financ
                       WHERE A.ano_eje_mov  = @ano_eje  and
                             A.sec_ejec_mov = @sec_ejec and
                             A.sec_aud_mov  = @sec_aud
                       GROUP BY B.origen, A.fuente_financ, B.fuente_financ_agregada
                     
                     OPEN c1
                     FETCH c1 INTO @porigen,@pfuente_financ,@pfuente_financ_agregada,@pMonto
                     WHILE @@FETCH_STATUS = 0
                           BEGIN
                                INSERT INTO sig_int_techo_ppto_carga
                                            (ano_eje, sec_ejec, subfase, correl_envio, origen, fuente,
                                             fuente_financ_agregada, ppto_siaf, ppto_reser, ppto_siga)
                                     VALUES (@ano_eje, @sec_ejec, @fase_siaf, @pcorrelativo, @porigen, @pfuente_financ,
                                             @pfuente_financ_agregada, @pMonto, 0, @pMonto)
                                
                                IF @@ERROR < 0
                                   BEGIN
                                        select @retorno = -14
                                        GOTO ERROR
                                   END
                                
                                SELECT @pcorrelativo = @pcorrelativo + 1
                                FETCH c1 INTO @porigen,@pfuente_financ,@pfuente_financ_agregada,@pMonto
                           END
                     CLOSE c1
                     DEALLOCATE c1
                END
                
             IF @fase_siga = 4
                BEGIN
                     UPDATE sig_int_tmp_asigna_generica
                        SET fuente_financ = SUBSTRING( '00' + fuente_financ, LEN('00'+fuente_financ)-1, LEN('00'+fuente_financ))
                      WHERE ano_eje_mov  = @ano_eje  and
                            sec_ejec_mov = @sec_ejec and
                            sec_aud_mov  = @sec_aud
                     
                     IF @@ERROR < 0 
                        BEGIN
                             select @retorno = -15
                             GOTO ERROR
                        END
                     
                     DECLARE c2 CURSOR FOR
                     SELECT  A.funcion, A.programa, A.sub_programa, A.programa_ppto, A.act_proy,
                             A.fuente_financ, A.departamento, A.tipo_transaccion, A.generica,
                             A.categoria_gasto, SUM(A.monto_asignado), B.origen, B.fuente_financ_agregada
                        FROM sig_int_tmp_asigna_generica A LEFT JOIN Fuente_Financ B
                             ON A.ano_eje = B.ano_eje and A.fuente_financ = B.fuente_financ
                       WHERE A.ano_eje_mov  = @ano_eje  and
                             A.sec_ejec_mov = @sec_ejec and
                             A.sec_aud_mov  = @sec_aud
                       GROUP BY A.funcion, A.programa, A.sub_programa, A.programa_ppto, A.act_proy,
                                A.fuente_financ, A.departamento, A.tipo_transaccion, A.generica,
                                A.categoria_gasto, B.origen, B.fuente_financ_agregada
                     
                     OPEN c2
                     FETCH c2 INTO @pfuncion, @pprograma, @psub_programa, @pprograma_ppto, @pact_proy,
                                   @pfuente_financ, @pdepartamento, @ptipo_transaccion, @pgenerica,
                                   @pcategoria_gasto, @pMonto, @porigen, @pfuente_financ_agregada
                     
                     WHILE @@FETCH_STATUS = 0
                           BEGIN
                                INSERT INTO sig_int_techo_ppto_carga
                                            (ano_eje, sec_ejec, subfase, correl_envio, origen, fuente, fuente_financ_agregada,
                                             generic_categ, generic_grupo, funcion, programa, sub_programa, act_proy, programa_ppto,
                                             departamento, categoria_gasto, ppto_siaf, ppto_reser, ppto_siga)
                                     VALUES (@ano_eje, @sec_ejec, @fase_siaf, @pcorrelativo, @porigen, @pfuente_financ, @pfuente_financ_agregada,
                                             @ptipo_transaccion, @pgenerica, @pfuncion, @pprograma, @psub_programa, @pact_proy, @pprograma_ppto,
                                             @pdepartamento, @pcategoria_gasto, @pMonto, 0, @pMonto)
                                
                                IF @@ERROR < 0
                                   BEGIN
                                        select @retorno = -16
                                        GOTO ERROR
                                   END
                                   
                                   SELECT @pcorrelativo = @pcorrelativo + 1
                                   FETCH c2 INTO @pfuncion, @pprograma, @psub_programa, @pprograma_ppto, @pact_proy, @pfuente_financ,
                                                 @pdepartamento, @ptipo_transaccion, @pgenerica, @pcategoria_gasto, @pMonto, @porigen,
                                                 @pfuente_financ_agregada
                           END
                     CLOSE c2
                     DEALLOCATE c2
                END
                
             SELECT @OK = 'TRUE'
        END
        
     --Si fase siga es menor a fase siaf
     IF @fase_siga < @fase_siaf
        BEGIN
             -- Ejecutar SP Carga de Maestros
             EXECUTE sp_int_carga_maestros @ano_eje, @sec_ejec, @sec_aud, @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             DELETE FROM SIG_META_PROPUESTA_FASE
              WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec  and fase_cuadro = @fase_siaf
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -17
                     GOTO ERROR
                END
             
             INSERT INTO SIG_META_PROPUESTA_FASE
                         (ANO_EJE      , SEC_EJEC , SEC_FUNC_PROP, FASE_CUADRO, SEC_FUNC     ,
                          FUNCION      , PROGRAMA , SUB_PROGRAMA , ACT_PROY   , COMPONENTE   ,
                          META         , FINALIDAD, NOMBRE       , MONTO      , CANTIDAD     ,
                          UNIDAD_MEDIDA, PAIS     , DEPARTAMENTO , PROVINCIA  , DISTRITO     ,
                          ESTADO       , PORC_META, TIPO_TAREA   , NIVEL_TAREA, TAREA_GENERAL,
                          SEC_FUNC_REQ , PROGRAMA_INSTITUCIONAL,
                          FLAG_ACT_PROY, ESTRATEGIA_NACIONAL, FLAG_ESTRATEGIA, TIPO_ESTRATEGIA)
                   SELECT DISTINCT
                          ano_eje      , sec_ejec , secuencia_meta, @fase_siaf, NULL        ,
                          funcion      , programa , sub_programa  , act_proy  , componente  ,
                          meta         , finalidad, substring(nombre,1,150), monto, cantidad,
                          unidad_medida, NULL     , departamento  , provincia , distrito    ,
                          NULL         , NULL     , NULL          , NULL      , NULL        ,
                          NULL         , programa_ppto,
                          LEFT(act_proy,1),
                          Right('0000'+convert(varchar,secuencia_meta),4),
                          Case programa_ppto when '0000' then 'N' else 'S' end,
                         Case
                             when programa_ppto = '0000' then NULL
                         else
                            Case
                                when unidad_medida  = '60'   then 'G'
                                when programa_ppto <> '0000' then 'K'
                            end
                         end
                     FROM SIG_INT_TMP_META
                    WHERE ano_eje     = @ano_eje AND sec_ejec     = @sec_ejec and
                          ano_eje_mov = @ano_eje AND sec_ejec_mov = @sec_ejec and
                          sec_aud_mov = @sec_aud
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -18
                     GOTO ERROR
                END
             
             --Se inicializa el flag de metas estrategicas que no tienen asignado metas estrategicas
             UPDATE sig_meta_propuesta_fase
                SET flag_estrategia        = 'N',
                    estrategia_nacional    = '0000',
                    programa_institucional = '0000'
              WHERE ano_eje     = @ano_eje   and
                    sec_ejec    = @sec_ejec  and
                    fase_cuadro = @fase_siaf and
                    estrategia_nacional is null
             
             If @@ERROR < 0
                BEGIN
                     select @retorno = -19
                     GOTO ERROR
                END
             
             --Actualizando Programa Institucional
             INSERT INTO sig_estrategia_parametro
                         (ano_eje, fase_cuadro, programa_institucional, estado)
                  SELECT DISTINCT
                         ano_eje, fase_cuadro, programa_institucional, 'A'
                    FROM sig_meta_propuesta_fase
                   WHERE ano_eje     = @ano_eje   and
                         sec_ejec    = @sec_ejec  and
                         fase_cuadro = @fase_siaf and
                         not exists (SELECT programa_institucional
                                       FROM sig_estrategia_parametro EP
                                      WHERE EP.ano_eje     = ano_eje     and
                                            EP.fase_cuadro = fase_cuadro and
                                            EP.programa_institucional = programa_institucional)
             
             If @@ERROR < 0
                BEGIN
                     select @retorno = -20
                     Goto ERROR
                END
             
             -- Ejecutar SP tareas estrategicas
             EXECUTE sp_int_tarea_estrategica @ano_eje,@sec_ejec, @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             --Actualizamos el registro log
             EXECUTE sp_int_registra_log @ano_eje, @sec_ejec, @sec_aud, 'Registro de LOG - Meta Propuesta Fase', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             SELECT @OK = 'TRUE'
        END
        
     --Si fase siga es mayor a fase siaf
     IF @fase_siga > @fase_siaf
        BEGIN
             --Actualizamos el registro log
             EXECUTE sp_int_registra_log @ano_eje, @sec_ejec, @sec_aud, 'Registro de LOG - Verificar Fase de Programación', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
             
             SELECT @OK = 'FALSE'
        END
     
     IF @OK = 'TRUE'
        BEGIN
             UPDATE SIG_INT_MOVIMIENTO_AUD
                SET estado_envio = 'A'
              WHERE ano_eje  = @ano_eje  and
                    sec_ejec = @sec_ejec and
                    sec_aud <= @sec_aud  and
                    cod_peticion in ('2','3') and
                    estado_envio    = 'T'     and
                    estado_registro = 'A'
             
             IF @@ERROR < 0
                BEGIN
                     select @retorno = -21
                     GOTO ERROR
                END
             
             --Actualizamos el registro log
             EXECUTE sp_int_registra_log @ano_eje, @sec_ejec,@sec_aud, 'Registro de LOG - Movimientos', @retorno OUT
             IF @retorno < 0
                GOTO ERROR
        END
        
     select @respuesta = 1
     RETURN
     
     ERROR:
           select @respuesta = @retorno
           --select @respuesta = -1
END
GO


-- ----------------------------
-- procedure structure for SP_REP_SEG_PAAC_MODIF
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_REP_SEG_PAAC_MODIF]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_REP_SEG_PAAC_MODIF]
GO

CREATE PROCEDURE [dbo].[SP_REP_SEG_PAAC_MODIF]
(@PN_ANIO NUMERIC, @PN_EJECUTORA NUMERIC, @PN_REPORTE NUMERIC )
AS
DECLARE @ISEC_RESUMEN NUMERIC(4,0)
DECLARE @WCOUNT_REP NUMERIC(4,0)
DECLARE @WESTADO_REP VARCHAR(1)
DECLARE @WCOUNT_PAAC NUMERIC(4,0)
DECLARE @WNESTADO_PAAC VARCHAR(100)
DECLARE @WESTADO_PAAC VARCHAR(1)
DECLARE @CANO_EJE numeric(4, 0)
DECLARE @CSEC_EJEC numeric(6, 0)
DECLARE @CTIPO_CONSOLID char(1)
DECLARE @CNRO_CONSOLID numeric(5, 0)
DECLARE @CTIPO_GENERACION char(1)
DECLARE @CITEM_UNICO numeric(4, 0)
DECLARE @CTIPO_PROCESO varchar(2)
DECLARE @CNOM_TIPO_PROCESO varchar(250)
DECLARE @CNOM_TIPO_PROCESO_ABREV varchar(50)
DECLARE @COBJETO varchar(2)
DECLARE @CNOM_OBJETO varchar(250)
DECLARE @CESPEC_TECNICAS varchar(100)
DECLARE @CVALOR_MONEDA  numeric(16, 2)
DECLARE @CFUENTE varchar(250)
DECLARE @ESIGLAS varchar(40)
DECLARE @ESECTOR varchar(2)
DECLARE @EPLIEGO varchar(3)
DECLARE @PNOM_PLIEGO varchar(150)
DECLARE @ENOM_EJECUTORA varchar(150)
DECLARE @ERUC_EJEC varchar(11)
DECLARE @CINSTRUMENTO varchar(100)
DECLARE @CFLAG_PAAC varchar(1)
DECLARE @CNRO_PAAC varchar(4)
DECLARE @INRO_ITEM numeric(6, 0)
DECLARE @ITIPO_BIEN varchar(1)
DECLARE @IGRUPO_BIEN varchar(2)
DECLARE @ICLASE_BIEN varchar(2)
DECLARE @IFAMILIA_BIEN varchar(4)
DECLARE @IITEM_BIEN varchar(4)
DECLARE @INOMBRE_ITEM varchar(100)
DECLARE @IUNIDAD_MEDIDA numeric(3, 0)
DECLARE @INOMBRE_UNIDAD varchar(100)
DECLARE @ICANTIDAD numeric(20, 6)
DECLARE @IVALOR_MONEDA numeric(16, 2)
DECLARE @NUM numeric(6, 0)
DECLARE @NUM_CUENTA numeric(6, 0)
DECLARE @NUM_CUENTA_DETAB numeric(6, 0)
DECLARE @LS_CADENA VARCHAR(250)
DECLARE @LS_FUENTE VARCHAR(2)
DECLARE @NUM_CUENTA_PROCESO NUMERIC(6,0)
DECLARE @NUM_CUENTA_DETA NUMERIC(6,0)
DECLARE @SSEC_ITEM NUMERIC(4,0)
DECLARE @SCOD_ESTADO VARCHAR(1)
DECLARE @SVALOR_REF numeric(16, 2)
DECLARE @SPROCESO NUMERIC(5,0)
DECLARE @SSEC_PROCESO NUMERIC(4,0)
DECLARE @SCONVOCATORIA NUMERIC(2,0)
DECLARE @SANO_PROCESO NUMERIC(4,0)
DECLARE @SNRO_PROCESO NUMERIC(5,0)
DECLARE @SSIGLAS VARCHAR(40)
DECLARE @SFLAG_PSA VARCHAR(1)
DECLARE @STEXTO_FLAG_PSA VARCHAR(10)
DECLARE @STEXTO_WNRO_PROCESO VARCHAR(250)
DECLARE @SNRO_PROCESO_SEL VARCHAR(250)
DECLARE @SESTADO VARCHAR(40)
DECLARE @SPROVEEDOR NUMERIC(4,0)
DECLARE @SNOM_PROVEEDOR VARCHAR(100)
DECLARE @SNRO_RUC VARCHAR(11)
DECLARE @SVALOR_UNIT NUMERIC(16,2)
DECLARE @SVALOR_TOTAL NUMERIC(16,2)
DECLARE @SCANTIDAD_CI NUMERIC(20,6)
DECLARE @SCANTIDAD_ADJUDICADA NUMERIC(20,6)
DECLARE @NUM_PROV NUMERIC(2,0)
DECLARE @SADJUDICADO VARCHAR(1)
DECLARE @CTITULO VARCHAR(100)
DECLARE @WCUENTA_TOTAL_ITEM NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_DESIERTO NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_CANCELADO NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_CONCLUIDO  NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_PROCESO NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_PENDIENTE NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_BUENA_PRO_S  NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_BUENA_PRO_N NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S NUMERIC(6,0)
DECLARE @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N NUMERIC(6,0)
/*
CREATE TABLE DBO.TMP_SEGUIMIENTO_PAAC_MODIF
(
CREPORTE NUMERIC(10,0) NOT NULL,
CANO_EJE numeric(4, 0)NOT NULL,
CSEC_EJEC numeric(6, 0) NOT NULL,
CTIPO_CONSOLID char(1) NOT NULL,
CNRO_CONSOLID numeric(5, 0) NOT NULL,
CTIPO_GENERACION char(1) NOT NULL,
CFLAG_PAAC varchar(1) NULL,
CNRO_PAAC varchar(4) NULL,
CITEM_UNICO numeric(4, 0) NULL,
CTIPO_PROCESO varchar(2) NULL,
CNOM_TIPO_PROCESO varchar(250) NULL,
COBJETO varchar(2) NULL,
CNOM_OBJETO varchar(250) NULL,
CESPEC_TECNICAS varchar(100) NULL,
ESIGLAS varchar(40) NULL,
ESECTOR varchar(2) NULL,
EPLIEGO varchar(3) NULL,
PNOM_PLIEGO varchar(150) NULL,
ENOM_EJECUTORA varchar(150) NULL,
ERUC_EJEC varchar(11) NULL,
CINSTRUMENTO varchar(100) NULL,
CVALOR_MONEDA  numeric(16, 2) NULL,
CFUENTE varchar(250) NULL,
INRO_ITEM numeric(6, 0) NOT NULL,
ITIPO_BIEN varchar(1) NULL,
IGRUPO_BIEN varchar(2) NULL,
ICLASE_BIEN varchar(2) NULL,
IFAMILIA_BIEN varchar(4) NULL,
IITEM_BIEN varchar(4) NULL,
INOMBRE_ITEM varchar(100) NULL,
IUNIDAD_MEDIDA numeric(3, 0) NULL,
INOMBRE_UNIDAD varchar(100) NULL,
ICANTIDAD numeric(20, 6) NULL,
IVALOR_MONEDA numeric(16, 2) NULL,
SSEC_ITEM NUMERIC(4,0) NOT NULL,
SVALOR_REF numeric(16, 2) NULL,
SESTADO VARCHAR(40) NULL,
SNRO_PROCESO_SEL VARCHAR(250) NULL,
SNRO_CONVOCATORIA NUMERIC(2,0) NULL,
SPROVEEDOR NUMERIC(4,0) NULL,
SNOM_PROVEEDOR VARCHAR(100) NULL,
SNRO_RUC VARCHAR(11) NULL,
SVALOR_UNIT NUMERIC(16,2) NULL,
SVALOR_TOTAL NUMERIC(16,2) NULL,
SCANTIDAD_ADJUDICADA NUMERIC(20,6) NULL,
SNRO_PROV NUMERIC(2,0) NOT NULL,
SADJUDICADO VARCHAR(1) NULL,
CTITULO VARCHAR(100),
CNOM_TIPO_PROCESO_ABREV VARCHAR(50)
)
*/

--SP_HELP SIG_CONTRATISTAS
--CABECERA
--DATOS PRINCIPALES DEL PAAC
DECLARE CUR_PAAC CURSOR FOR
SELECT
SIG_PAAC_CONSOLIDADO.ANO_EJE AS WANO_EJE,
SIG_PAAC_CONSOLIDADO.SEC_EJEC AS WSEC_EJEC, 
SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID AS WTIPO_CONSOLID,
SIG_PAAC_CONSOLIDADO.NRO_CONSOLID AS WNRO_CONSOLID,
SIG_PAAC_CONSOLIDADO.TIPO_GENERACION AS WTIPO_GENERACION,
SIG_PAAC_CONSOLIDADO.FLAG_PAAC as WFLAG_PAAC,
SIG_PAAC_CONSOLIDADO.NRO_PAAC as WNRO_PAAC,
( SELECT COUNT(*)
  FROM SIG_PAAC_ITEM
  WHERE
  SIG_PAAC_CONSOLIDADO.ANO_EJE = SIG_PAAC_ITEM.ANO_EJE AND
  SIG_PAAC_CONSOLIDADO.SEC_EJEC = SIG_PAAC_ITEM.SEC_EJEC AND
  SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID =   SIG_PAAC_ITEM.TIPO_CONSOLID AND
  SIG_PAAC_CONSOLIDADO.NRO_CONSOLID =   SIG_PAAC_ITEM.NRO_CONSOLID AND
  SIG_PAAC_CONSOLIDADO.TIPO_GENERACION =   SIG_PAAC_ITEM.TIPO_GENERACION AND
  SIG_PAAC_ITEM.SEC_CONSOLID = 1 ) AS WITEM_UNICO,
SIG_PAAC_CONSOLIDADO.TIPO_PROCESO AS WTIPO_PROCESO,
(SELECT SIG_MAESTRO_PROCESO.DESCRIPCION
 FROM SIG_MAESTRO_PROCESO
 WHERE 
 SIG_MAESTRO_PROCESO.ANO_EJE = SIG_PAAC_CONSOLIDADO.ANO_EJE AND  
 SIG_MAESTRO_PROCESO.TIPO_ORGANISMO = '01'  AND  
 SIG_MAESTRO_PROCESO.CODIGO = 'TIPO_PROCESO' AND
 SIG_MAESTRO_PROCESO.CODIGO_DET = SIG_PAAC_CONSOLIDADO.TIPO_PROCESO ) AS WNOM_PROCESO,
(SELECT SIG_MAESTRO_PROCESO.DESCRIPCION_ABREVIADA
 FROM SIG_MAESTRO_PROCESO
 WHERE 
 SIG_MAESTRO_PROCESO.ANO_EJE = SIG_PAAC_CONSOLIDADO.ANO_EJE AND  
 SIG_MAESTRO_PROCESO.TIPO_ORGANISMO = '01'  AND  
 SIG_MAESTRO_PROCESO.CODIGO = 'TIPO_PROCESO' AND
 SIG_MAESTRO_PROCESO.CODIGO_DET = SIG_PAAC_CONSOLIDADO.TIPO_PROCESO ) AS WNOM_PROCESO_ABREVIADA,
SIG_PAAC_CONSOLIDADO.OBJETO AS WOBJETO,
( SELECT CODIGO_GENERAL_DET.DESCRIPCION
  FROM CODIGO_GENERAL_DET  
  WHERE 
  CODIGO_GENERAL_DET.CODIGO = 'OBJETO' AND
  CODIGO_GENERAL_DET.CODIGO_DET = SIG_PAAC_CONSOLIDADO.OBJETO ) AS WNOM_OBJETO,
SIG_PAAC_CONSOLIDADO.ESPEC_TECNICAS AS WESPEC_TECNICAS,
EJECUTORA.SIGLAS AS WSIGLAS,
EJECUTORA.SECTOR AS WSECTOR,
EJECUTORA.PLIEGO AS WPLIEGO,
PLIEGO.NOMBRE AS WNOM_PLIEGO,
EJECUTORA.NOMBRE AS WNOM_EJECUTORA,
EJECUTORA.RUC_EJEC AS WRUC_EJEC,
( SELECT SIG_PARAMETRO_EJECUTORA_ANIO.VALOR
  FROM SIG_PARAMETRO_EJECUTORA_ANIO
  WHERE 
  SIG_PARAMETRO_EJECUTORA_ANIO.ANO_EJE = SIG_PAAC_CONSOLIDADO.ANO_EJE AND
  SIG_PARAMETRO_EJECUTORA_ANIO.SEC_EJEC = SIG_PAAC_CONSOLIDADO.SEC_EJEC AND
  SIG_PARAMETRO_EJECUTORA_ANIO.COD_MAESTRO = 'INSTRUMENTO_PAAC') AS WINSTRUMENTO,
SIG_PAAC_CONSOLIDADO.VALOR_MONEDA AS WVALOR_MONEDA
FROM SIG_PAAC_CONSOLIDADO, EJECUTORA, PLIEGO
WHERE 
SIG_PAAC_CONSOLIDADO.SEC_EJEC = EJECUTORA.SEC_EJEC AND
EJECUTORA.SECTOR = PLIEGO.SECTOR AND
EJECUTORA.PLIEGO = PLIEGO.PLIEGO AND
SIG_PAAC_CONSOLIDADO.ANO_EJE = @PN_ANIO AND
SIG_PAAC_CONSOLIDADO.SEC_EJEC = @PN_EJECUTORA AND
SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID = '2' AND
SIG_PAAC_CONSOLIDADO.NRO_CONSOLID > 0 AND
SIG_PAAC_CONSOLIDADO.TIPO_GENERACION = '0' AND
sig_paac_consolidado.flag_paac NOT IN ('0','3','5') AND
sig_paac_consolidado.NRO_PAAC <> '0000'
ORDER BY 
SIG_PAAC_CONSOLIDADO.NRO_PAAC, 
SIG_PAAC_CONSOLIDADO.ANO_EJE,
SIG_PAAC_CONSOLIDADO.SEC_EJEC, 
SIG_PAAC_CONSOLIDADO.TIPO_CONSOLID,
SIG_PAAC_CONSOLIDADO.NRO_CONSOLID ,
SIG_PAAC_CONSOLIDADO.TIPO_GENERACION

OPEN CUR_PAAC
FETCH CUR_PAAC INTO @CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC,@CITEM_UNICO ,@CTIPO_PROCESO,
@CNOM_TIPO_PROCESO,@CNOM_TIPO_PROCESO_ABREV, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
@ERUC_EJEC,@CINSTRUMENTO, @CVALOR_MONEDA

WHILE @@FETCH_STATUS = 0
BEGIN
	--CUENTA SI EXISTEN ITEMS PARA PAAC MODIFICADO SELECCIONADO
	SELECT @NUM_CUENTA = COUNT(*)
	FROM SIG_PAAC_ITEM, CATALOGO_BIEN_SERV, UNIDAD_MEDIDA
	WHERE
	SIG_PAAC_ITEM.SEC_EJEC = CATALOGO_BIEN_SERV.SEC_EJEC AND
	SIG_PAAC_ITEM.TIPO_BIEN = CATALOGO_BIEN_SERV.TIPO_BIEN AND
	SIG_PAAC_ITEM.GRUPO_BIEN = CATALOGO_BIEN_SERV.GRUPO_BIEN AND
	SIG_PAAC_ITEM.CLASE_BIEN = CATALOGO_BIEN_SERV.CLASE_BIEN AND
	SIG_PAAC_ITEM.FAMILIA_BIEN = CATALOGO_BIEN_SERV.FAMILIA_BIEN AND
	SIG_PAAC_ITEM.ITEM_BIEN = CATALOGO_BIEN_SERV.ITEM_BIEN AND
	SIG_PAAC_ITEM.UNIDAD_MEDIDA = UNIDAD_MEDIDA.UNIDAD_MEDIDA AND
	SIG_PAAC_ITEM.ANO_EJE = @CANO_EJE AND
	SIG_PAAC_ITEM.SEC_EJEC = @CSEC_EJEC AND
	SIG_PAAC_ITEM.TIPO_CONSOLID = @CTIPO_CONSOLID AND
	SIG_PAAC_ITEM.TIPO_GENERACION = @CTIPO_GENERACION and
	SIG_PAAC_ITEM.NRO_CONSOLID = @CNRO_CONSOLID
	--CUENTA SI EXISTEN ITEMS PARA PAAC MODIFICADO SELECCIONADO

	--VERIFICA VALOR DE CUENTA DE ITEM DE PAAC MODIFICADO
	IF @NUM_CUENTA IS NULL 
	BEGIN
		SELECT @NUM_CUENTA = 0 
	END
	--VERIFICA VALOR DE CUENTA DE ITEM DE PAAC MODIFICADO

	--VALIDA SI EXISTEN ITEMS EN PAAC MODIFICADOR
	IF @NUM_CUENTA > 0 
	BEGIN
		--RECUPERAR FUENTE DE FINANCIAMIENTO
		DECLARE C_FUENTE CURSOR FOR	
		SELECT DISTINCT FUENTE_FINANC
		FROM  SIG_PAAC_METAS
		WHERE 
		ANO_EJE = @CANO_EJE and
		SEC_EJEC = @CSEC_EJEC  and
		TIPO_CONSOLID = @CTIPO_CONSOLID and
		NRO_CONSOLID = @CNRO_CONSOLID and
		TIPO_GENERACION = @CTIPO_GENERACION
			 
		OPEN C_FUENTE
		FETCH C_FUENTE INTO @LS_FUENTE

		SELECT @LS_CADENA = ''
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @LS_FUENTE IS NULL 
			BEGIN
				SELECT @LS_FUENTE = ''
			END 

			IF Rtrim(LTRIM(@LS_FUENTE)) <> '' 
			BEGIN
				IF Rtrim(LTRIM(@LS_CADENA)) <> '' 
				BEGIN
					SELECT @LS_CADENA = @LS_FUENTE + ' , '+ @LS_CADENA
				END
				ELSE
				BEGIN
					SELECT @LS_CADENA = @LS_FUENTE
				END
			END
			FETCH C_FUENTE INTO @LS_FUENTE
		END
		CLOSE C_FUENTE
		DEALLOCATE C_FUENTE
		SELECT @CFUENTE = @LS_CADENA
		--RECUPERAR FUENTE DE FINANCIAMIENTO

		--RECUPERAR DE ITEMS SEGUN PAAC MODIFICADO SELECCIONADO
		SELECT @NUM = 0

		DECLARE CUR_PAAC_ITEM CURSOR FOR
		SELECT 
		SIG_PAAC_ITEM.TIPO_BIEN AS WTIPO_BIEN,
		SIG_PAAC_ITEM.GRUPO_BIEN AS WGRUPO_BIEN,
		SIG_PAAC_ITEM.CLASE_BIEN AS WCLASE_BIEN,
		SIG_PAAC_ITEM.FAMILIA_BIEN AS WFAMILIA_BIEN,
		SIG_PAAC_ITEM.ITEM_BIEN AS WITEM_BIEN,
		CATALOGO_BIEN_SERV.NOMBRE_ITEM AS WNOM_ITEM,
		SIG_PAAC_ITEM.UNIDAD_MEDIDA AS WUNIDAD_MEDIDA,
		UNIDAD_MEDIDA.NOMBRE AS WNOM_UNIDAD,
		( CASE SIG_PAAC_ITEM.TIPO_BIEN WHEN 'B' THEN SUM(SIG_PAAC_ITEM.CANTIDAD) WHEN 'S' THEN 1 ELSE 1 END ) AS WCANTIDAD,
		SUM(SIG_PAAC_ITEM.VALOR_MONEDA) AS WVALOR_MONEDA,
		SIG_PAAC_ITEM.SEC_RESUMEN AS WSEC_RESUMEN
		FROM SIG_PAAC_ITEM, CATALOGO_BIEN_SERV, UNIDAD_MEDIDA
		WHERE
		SIG_PAAC_ITEM.SEC_EJEC = CATALOGO_BIEN_SERV.SEC_EJEC AND
		SIG_PAAC_ITEM.TIPO_BIEN = CATALOGO_BIEN_SERV.TIPO_BIEN AND
		SIG_PAAC_ITEM.GRUPO_BIEN = CATALOGO_BIEN_SERV.GRUPO_BIEN AND
		SIG_PAAC_ITEM.CLASE_BIEN = CATALOGO_BIEN_SERV.CLASE_BIEN AND
		SIG_PAAC_ITEM.FAMILIA_BIEN = CATALOGO_BIEN_SERV.FAMILIA_BIEN AND
		SIG_PAAC_ITEM.ITEM_BIEN = CATALOGO_BIEN_SERV.ITEM_BIEN AND
		SIG_PAAC_ITEM.UNIDAD_MEDIDA = UNIDAD_MEDIDA.UNIDAD_MEDIDA AND
		SIG_PAAC_ITEM.ANO_EJE = @CANO_EJE AND
		SIG_PAAC_ITEM.SEC_EJEC = @CSEC_EJEC AND
		SIG_PAAC_ITEM.TIPO_CONSOLID = @CTIPO_CONSOLID AND
		SIG_PAAC_ITEM.TIPO_GENERACION = @CTIPO_GENERACION and
		SIG_PAAC_ITEM.NRO_CONSOLID = @CNRO_CONSOLID
		GROUP BY
		SIG_PAAC_ITEM.TIPO_BIEN,
		SIG_PAAC_ITEM.GRUPO_BIEN,
		SIG_PAAC_ITEM.CLASE_BIEN,
		SIG_PAAC_ITEM.FAMILIA_BIEN,
		SIG_PAAC_ITEM.ITEM_BIEN,
		CATALOGO_BIEN_SERV.NOMBRE_ITEM,
		SIG_PAAC_ITEM.UNIDAD_MEDIDA,
		UNIDAD_MEDIDA.NOMBRE,
		SIG_PAAC_ITEM.SEC_RESUMEN
		ORDER BY 
		SIG_PAAC_ITEM.SEC_RESUMEN

		OPEN CUR_PAAC_ITEM
		FETCH CUR_PAAC_ITEM INTO @ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,
		@IFAMILIA_BIEN,@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,
		@INOMBRE_UNIDAD,@ICANTIDAD,@IVALOR_MONEDA ,@ISEC_RESUMEN

		WHILE @@FETCH_STATUS = 0
		BEGIN
			--SETEA CORRELATIVO DE ITEM
			SELECT @NUM = @NUM + 1

			--CONTEO SI EXISTEN DATOS DE PROCESOS DE SELECCION
			--POR CADA ITEM QUE RECUPERA
			SELECT @NUM_CUENTA_PROCESO = COUNT(*)
			FROM SIG_PROCESO_DE_SELECCION, SIG_PROCESO_SECUENCIA,
			SIG_CONVOCATORIA, SIG_CONVOCATORIA_ITEM
			WHERE 
			SIG_PROCESO_DE_SELECCION.ANO_EJE = SIG_PROCESO_SECUENCIA.ANO_EJE AND
			SIG_PROCESO_DE_SELECCION.SEC_EJEC = SIG_PROCESO_SECUENCIA.SEC_EJEC AND
			SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = SIG_PROCESO_SECUENCIA.TIPO_GENERACION AND
			SIG_PROCESO_DE_SELECCION.PROCESO = SIG_PROCESO_SECUENCIA.PROCESO AND
			SIG_PROCESO_SECUENCIA.ANO_EJE = SIG_CONVOCATORIA.ANO_EJE AND
			SIG_PROCESO_SECUENCIA.SEC_EJEC = SIG_CONVOCATORIA.SEC_EJEC AND
			SIG_PROCESO_SECUENCIA.TIPO_GENERACION = SIG_CONVOCATORIA.TIPO_GENERACION AND
			SIG_PROCESO_SECUENCIA.PROCESO = SIG_CONVOCATORIA.PROCESO AND
			SIG_PROCESO_SECUENCIA.SEC_PROCESO = SIG_CONVOCATORIA.SEC_PROCESO AND
			SIG_CONVOCATORIA.ANO_EJE = SIG_CONVOCATORIA_ITEM.ANO_EJE AND
			SIG_CONVOCATORIA.SEC_EJEC = SIG_CONVOCATORIA_ITEM.SEC_EJEC AND
			SIG_CONVOCATORIA.TIPO_GENERACION = SIG_CONVOCATORIA_ITEM.TIPO_GENERACION AND
			SIG_CONVOCATORIA.PROCESO = SIG_CONVOCATORIA_ITEM.PROCESO AND
			SIG_CONVOCATORIA.SEC_PROCESO = SIG_CONVOCATORIA_ITEM.SEC_PROCESO AND
			SIG_CONVOCATORIA.CONVOCATORIA = SIG_CONVOCATORIA_ITEM.CONVOCATORIA AND
			SIG_PROCESO_DE_SELECCION.ANO_EJE = @CANO_EJE AND
			SIG_PROCESO_DE_SELECCION.SEC_EJEC = @CSEC_EJEC AND
			SIG_PROCESO_DE_SELECCION.TIPO_CONSOLID = @CTIPO_CONSOLID AND
			SIG_PROCESO_DE_SELECCION.NRO_CONSOLID = @CNRO_CONSOLID AND
			SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = @CTIPO_GENERACION AND
			SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN
/*			SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
			SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
			SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
			SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
			SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
			SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN
*/
			IF @NUM_CUENTA_PROCESO IS NULL 
			BEGIN
				SELECT @NUM_CUENTA_PROCESO = 0 
			END
			--CONTEO SI EXISTEN DATOS DE PROCESOS DE SELECCION
			--POR CADA ITEM QUE RECUPERA

			--VALIDA SI EXISTEN ITEMS EN PAAC MODIFICADOR
			IF @NUM_CUENTA_PROCESO > 0 
			BEGIN
				--SI EXISTE CONTEO
				--HALLAR MAXIMO, CONVOCATORIA, PROCESO, SEC_PROCESO

				--RECUPERAR MAXIMO PROCESO DE SIG_CONVOCATORIA_ITEM
				SELECT @SPROCESO = MAX(SIG_CONVOCATORIA_ITEM.PROCESO)
				FROM SIG_PROCESO_DE_SELECCION, SIG_PROCESO_SECUENCIA,
				SIG_CONVOCATORIA, SIG_CONVOCATORIA_ITEM
				WHERE 
				SIG_PROCESO_DE_SELECCION.ANO_EJE = SIG_PROCESO_SECUENCIA.ANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = SIG_PROCESO_SECUENCIA.SEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = SIG_PROCESO_SECUENCIA.TIPO_GENERACION AND
				SIG_PROCESO_DE_SELECCION.PROCESO = SIG_PROCESO_SECUENCIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.ANO_EJE = SIG_CONVOCATORIA.ANO_EJE AND
				SIG_PROCESO_SECUENCIA.SEC_EJEC = SIG_CONVOCATORIA.SEC_EJEC AND
				SIG_PROCESO_SECUENCIA.TIPO_GENERACION = SIG_CONVOCATORIA.TIPO_GENERACION AND
				SIG_PROCESO_SECUENCIA.PROCESO = SIG_CONVOCATORIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.SEC_PROCESO = SIG_CONVOCATORIA.SEC_PROCESO AND
				SIG_CONVOCATORIA.ANO_EJE = SIG_CONVOCATORIA_ITEM.ANO_EJE AND
				SIG_CONVOCATORIA.SEC_EJEC = SIG_CONVOCATORIA_ITEM.SEC_EJEC AND
				SIG_CONVOCATORIA.TIPO_GENERACION = SIG_CONVOCATORIA_ITEM.TIPO_GENERACION AND
				SIG_CONVOCATORIA.PROCESO = SIG_CONVOCATORIA_ITEM.PROCESO AND
				SIG_CONVOCATORIA.SEC_PROCESO = SIG_CONVOCATORIA_ITEM.SEC_PROCESO AND
				SIG_CONVOCATORIA.CONVOCATORIA = SIG_CONVOCATORIA_ITEM.CONVOCATORIA AND
				SIG_PROCESO_DE_SELECCION.ANO_EJE = @CANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_CONSOLID = @CTIPO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.NRO_CONSOLID = @CNRO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN
/*				SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
				SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
				SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN*/

				IF @SPROCESO IS NULL
				BEGIN
					SELECT @SPROCESO = 0
				END

				--RECUPERAR MAXIMO SEC_PROCESO DE SIG_CONVOCATORIA_ITEM
				SELECT @SSEC_PROCESO = MAX(SIG_CONVOCATORIA_ITEM.SEC_PROCESO)
				FROM SIG_PROCESO_DE_SELECCION, SIG_PROCESO_SECUENCIA,
				SIG_CONVOCATORIA, SIG_CONVOCATORIA_ITEM
				WHERE 
				SIG_PROCESO_DE_SELECCION.ANO_EJE = SIG_PROCESO_SECUENCIA.ANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = SIG_PROCESO_SECUENCIA.SEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = SIG_PROCESO_SECUENCIA.TIPO_GENERACION AND
				SIG_PROCESO_DE_SELECCION.PROCESO = SIG_PROCESO_SECUENCIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.ANO_EJE = SIG_CONVOCATORIA.ANO_EJE AND
				SIG_PROCESO_SECUENCIA.SEC_EJEC = SIG_CONVOCATORIA.SEC_EJEC AND
				SIG_PROCESO_SECUENCIA.TIPO_GENERACION = SIG_CONVOCATORIA.TIPO_GENERACION AND
				SIG_PROCESO_SECUENCIA.PROCESO = SIG_CONVOCATORIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.SEC_PROCESO = SIG_CONVOCATORIA.SEC_PROCESO AND
				SIG_CONVOCATORIA.ANO_EJE = SIG_CONVOCATORIA_ITEM.ANO_EJE AND
				SIG_CONVOCATORIA.SEC_EJEC = SIG_CONVOCATORIA_ITEM.SEC_EJEC AND
				SIG_CONVOCATORIA.TIPO_GENERACION = SIG_CONVOCATORIA_ITEM.TIPO_GENERACION AND
				SIG_CONVOCATORIA.PROCESO = SIG_CONVOCATORIA_ITEM.PROCESO AND
				SIG_CONVOCATORIA.SEC_PROCESO = SIG_CONVOCATORIA_ITEM.SEC_PROCESO AND
				SIG_CONVOCATORIA.CONVOCATORIA = SIG_CONVOCATORIA_ITEM.CONVOCATORIA AND
				SIG_PROCESO_DE_SELECCION.ANO_EJE = @CANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_CONSOLID = @CTIPO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.NRO_CONSOLID = @CNRO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN AND
				SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO
/*				SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
				SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
				SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN AND
				SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO*/

				IF @SSEC_PROCESO IS NULL
				BEGIN
					SELECT @SSEC_PROCESO = 0
				END

				--RECUPERAR MAXIMO CONVOCATORIA DE SIG_CONVOCATORIA_ITEM
				SELECT @SCONVOCATORIA = MAX(SIG_CONVOCATORIA_ITEM.CONVOCATORIA)
				FROM SIG_PROCESO_DE_SELECCION, SIG_PROCESO_SECUENCIA,
				SIG_CONVOCATORIA, SIG_CONVOCATORIA_ITEM
				WHERE 
				SIG_PROCESO_DE_SELECCION.ANO_EJE = SIG_PROCESO_SECUENCIA.ANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = SIG_PROCESO_SECUENCIA.SEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = SIG_PROCESO_SECUENCIA.TIPO_GENERACION AND
				SIG_PROCESO_DE_SELECCION.PROCESO = SIG_PROCESO_SECUENCIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.ANO_EJE = SIG_CONVOCATORIA.ANO_EJE AND
				SIG_PROCESO_SECUENCIA.SEC_EJEC = SIG_CONVOCATORIA.SEC_EJEC AND
				SIG_PROCESO_SECUENCIA.TIPO_GENERACION = SIG_CONVOCATORIA.TIPO_GENERACION AND
				SIG_PROCESO_SECUENCIA.PROCESO = SIG_CONVOCATORIA.PROCESO AND
				SIG_PROCESO_SECUENCIA.SEC_PROCESO = SIG_CONVOCATORIA.SEC_PROCESO AND
				SIG_CONVOCATORIA.ANO_EJE = SIG_CONVOCATORIA_ITEM.ANO_EJE AND
				SIG_CONVOCATORIA.SEC_EJEC = SIG_CONVOCATORIA_ITEM.SEC_EJEC AND
				SIG_CONVOCATORIA.TIPO_GENERACION = SIG_CONVOCATORIA_ITEM.TIPO_GENERACION AND
				SIG_CONVOCATORIA.PROCESO = SIG_CONVOCATORIA_ITEM.PROCESO AND
				SIG_CONVOCATORIA.SEC_PROCESO = SIG_CONVOCATORIA_ITEM.SEC_PROCESO AND
				SIG_CONVOCATORIA.CONVOCATORIA = SIG_CONVOCATORIA_ITEM.CONVOCATORIA AND
				SIG_PROCESO_DE_SELECCION.ANO_EJE = @CANO_EJE AND
				SIG_PROCESO_DE_SELECCION.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROCESO_DE_SELECCION.TIPO_CONSOLID = @CTIPO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.NRO_CONSOLID = @CNRO_CONSOLID AND
				SIG_PROCESO_DE_SELECCION.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO AND
				SIG_CONVOCATORIA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
				SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN
/*				SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
				SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
				SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN AND
				SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO AND
				SIG_CONVOCATORIA_ITEM.SEC_PROCESO = @SSEC_PROCESO*/

				IF @SCONVOCATORIA IS NULL
				BEGIN
					SELECT @SCONVOCATORIA = 0
				END
				--SI EXISTE CONTEO
				--HALLAR MAXIMO, CONVOCATORIA, PROCESO, SEC_PROCESO

				--UNA VEZ RECUPERADO LOS DATOS SE RECUPERA EL NRO DE PROCESO
				SELECT @SANO_PROCESO = SIG_PROCESO_SECUENCIA.ANO_PROCESO, 
				@SNRO_PROCESO = SIG_PROCESO_SECUENCIA.NRO_PROCESO,
				@SSIGLAS = SIG_PROCESO_SECUENCIA.SIGLAS,
				@SFLAG_PSA = SIG_PROCESO_SECUENCIA.FLAG_PSA
				FROM SIG_PROCESO_SECUENCIA
				WHERE 
				SIG_PROCESO_SECUENCIA.ANO_EJE = @CANO_EJE AND
				SIG_PROCESO_SECUENCIA.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROCESO_SECUENCIA.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_PROCESO_SECUENCIA.PROCESO = @SPROCESO AND
				SIG_PROCESO_SECUENCIA.SEC_PROCESO =  @SSEC_PROCESO

				IF  @SFLAG_PSA = 'S'
				BEGIN
					SELECT  @STEXTO_FLAG_PSA = 'PSA'
				END
				ELSE
				BEGIN
					SELECT  @STEXTO_FLAG_PSA = ''
				END
			
				IF @SNRO_PROCESO IS NULL
				BEGIN
					SELECT  @STEXTO_WNRO_PROCESO = ''
				END
				ELSE
				BEGIN
					SELECT  @STEXTO_WNRO_PROCESO = RIGHT('00000' + RTRIM(LTRIM(CAST(@SNRO_PROCESO AS VARCHAR(5) ))), 5) + '-' + CAST(@SANO_PROCESO AS VARCHAR(4) ) + '-'

					IF @SSIGLAS IS NULL
					BEGIN
						IF @ESIGLAS IS NULL
						BEGIN
							SELECT  @STEXTO_WNRO_PROCESO = RTRIM(LTRIM(@STEXTO_FLAG_PSA)) + ' ' + RTRIM(LTRIM(@STEXTO_WNRO_PROCESO))
						END
						ELSE
						BEGIN
							SELECT  @STEXTO_WNRO_PROCESO = RTRIM(LTRIM(@STEXTO_FLAG_PSA)) + ' ' + RTRIM(LTRIM(@STEXTO_WNRO_PROCESO)) + RTRIM(LTRIM(@ESIGLAS))
						END
					END
					ELSE
					BEGIN
						SELECT  @STEXTO_WNRO_PROCESO = RTRIM(LTRIM(@STEXTO_FLAG_PSA)) + ' ' + RTRIM(LTRIM(@STEXTO_WNRO_PROCESO)) + RTRIM(LTRIM(@SSIGLAS))
					END
				END
				SELECT @SNRO_PROCESO_SEL = RTRIM(LTRIM(@STEXTO_WNRO_PROCESO))

				--UNA VEZ RECUPERADO LOS DATOS SE RECUPERA EL NRO DE PROCESO
				
				--UNA VEZ RECUPERADO LOS DATOS SE RECUPERA  EL NRO DE CONVOCATORIA
				--@SCONVOCATORIA
				--UNA VEZ RECUPERADO LOS DATOS SE RECUPERA  EL NRO DE CONVOCATORIA


				--SE CREA CURSOR PARA BARRER LOS ITEMS DE SIG_CONVOCATORIA_IETM
				--SE RECUPERA LOS DATOS
				--ESTADO, NRO_ITEM, VALOR REFERENCIAL
				--PRIMERO CUENTA SI EXISTE
				SELECT @NUM_CUENTA_DETA = COUNT(*)
				FROM SIG_CONVOCATORIA_ITEM
				WHERE 
				SIG_CONVOCATORIA_ITEM.ANO_EJE = @CANO_EJE AND
				SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_CONVOCATORIA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO AND
				SIG_CONVOCATORIA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
				SIG_CONVOCATORIA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
				SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN AND
/*				SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
				SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
				SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
				SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN AND*/
				EXISTS(
				SELECT 1 FROM SIG_PROPUESTA_ITEM, SIG_PROPUESTA_LOTE
				WHERE 
				SIG_PROPUESTA_ITEM.ANO_EJE = SIG_PROPUESTA_LOTE.ANO_EJE AND
				SIG_PROPUESTA_ITEM.SEC_EJEC = SIG_PROPUESTA_LOTE.SEC_EJEC AND
				SIG_PROPUESTA_ITEM.TIPO_GENERACION = SIG_PROPUESTA_LOTE.TIPO_GENERACION AND
				SIG_PROPUESTA_ITEM.PROCESO = SIG_PROPUESTA_LOTE.PROCESO AND
				SIG_PROPUESTA_ITEM.SEC_PROCESO = SIG_PROPUESTA_LOTE.SEC_PROCESO AND
				SIG_PROPUESTA_ITEM.CONVOCATORIA = SIG_PROPUESTA_LOTE.CONVOCATORIA AND
				SIG_PROPUESTA_ITEM.SEC_CONVOCATORIA = SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA AND
				SIG_PROPUESTA_ITEM.NRO_LOTE = SIG_PROPUESTA_LOTE.NRO_LOTE AND
				SIG_PROPUESTA_ITEM.PROVEEDOR = SIG_PROPUESTA_LOTE.PROVEEDOR AND
				SIG_PROPUESTA_ITEM.NRO_PROPUESTA = SIG_PROPUESTA_LOTE.NRO_PROPUESTA AND
				SIG_PROPUESTA_ITEM.ANO_EJE = @CANO_EJE AND
				SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROPUESTA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
				SIG_PROPUESTA_ITEM.PROCESO = @SPROCESO AND
				SIG_PROPUESTA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
				SIG_PROPUESTA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
				SIG_PROPUESTA_ITEM.NRO_ITEM = @ISEC_RESUMEN AND
/*				SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
				SIG_PROPUESTA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
				SIG_PROPUESTA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
				SIG_PROPUESTA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
				SIG_PROPUESTA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
				SIG_PROPUESTA_ITEM.ITEM_BIEN = @IITEM_BIEN AND
				SIG_PROPUESTA_ITEM.NRO_ITEM = SIG_CONVOCATORIA_ITEM.NRO_ITEM  AND*/
				SIG_PROPUESTA_LOTE.ADJUDICADO = 'S' )
				--PRIMERO CUENTA SI EXISTE

				IF @NUM_CUENTA_DETA IS NULL 
				BEGIN
					SELECT @NUM_CUENTA_DETA = 0 
				END

				IF @NUM_CUENTA_DETA = 0
				--NO EXISTE
				BEGIN
	
					SELECT @NUM_CUENTA_DETAB = COUNT(*)
					FROM SIG_CONVOCATORIA_ITEM
					WHERE 
					SIG_CONVOCATORIA_ITEM.ANO_EJE = @CANO_EJE AND
					SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_CONVOCATORIA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
					SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO AND
					SIG_CONVOCATORIA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
					SIG_CONVOCATORIA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
					SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN AND
/*					SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_CONVOCATORIA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
					SIG_CONVOCATORIA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
					SIG_CONVOCATORIA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
					SIG_CONVOCATORIA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
					SIG_CONVOCATORIA_ITEM.ITEM_BIEN = @IITEM_BIEN AND*/
					EXISTS(
					SELECT 1 FROM SIG_PROPUESTA_ITEM, SIG_PROPUESTA_LOTE
					WHERE 
					SIG_PROPUESTA_ITEM.ANO_EJE = SIG_PROPUESTA_LOTE.ANO_EJE AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = SIG_PROPUESTA_LOTE.SEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_GENERACION = SIG_PROPUESTA_LOTE.TIPO_GENERACION AND
					SIG_PROPUESTA_ITEM.PROCESO = SIG_PROPUESTA_LOTE.PROCESO AND
					SIG_PROPUESTA_ITEM.SEC_PROCESO = SIG_PROPUESTA_LOTE.SEC_PROCESO AND
					SIG_PROPUESTA_ITEM.CONVOCATORIA = SIG_PROPUESTA_LOTE.CONVOCATORIA AND
					SIG_PROPUESTA_ITEM.SEC_CONVOCATORIA = SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA AND
					SIG_PROPUESTA_ITEM.NRO_LOTE = SIG_PROPUESTA_LOTE.NRO_LOTE AND
					SIG_PROPUESTA_ITEM.PROVEEDOR = SIG_PROPUESTA_LOTE.PROVEEDOR AND
					SIG_PROPUESTA_ITEM.NRO_PROPUESTA = SIG_PROPUESTA_LOTE.NRO_PROPUESTA AND
					SIG_PROPUESTA_ITEM.ANO_EJE = @CANO_EJE AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
					SIG_PROPUESTA_ITEM.PROCESO = @SPROCESO AND
					SIG_PROPUESTA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
					SIG_PROPUESTA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
					SIG_PROPUESTA_ITEM.NRO_ITEM = @ISEC_RESUMEN AND
/*					SIG_PROPUESTA_ITEM.NRO_ITEM = SIG_CONVOCATORIA_ITEM.NRO_ITEM  AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
					SIG_PROPUESTA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
					SIG_PROPUESTA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
					SIG_PROPUESTA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
					SIG_PROPUESTA_ITEM.ITEM_BIEN = @IITEM_BIEN AND*/
					( SIG_PROPUESTA_LOTE.ADJUDICADO = 'N' OR SIG_PROPUESTA_LOTE.ADJUDICADO IS NULL OR RTRIM(LTRIM(SIG_PROPUESTA_LOTE.ADJUDICADO)) = '' ) )
					--PRIMERO CUENTA SI EXISTE

					IF @NUM_CUENTA_DETAB IS NULL 
					BEGIN
						SELECT @NUM_CUENTA_DETAB = 0 
					END

					IF @NUM_CUENTA_DETAB = 0 
					BEGIN
						--INSERTA MOVIMIENTO DE ITEM
						--NO HAY DATOS DE PROCESO DE SELECCION
						--SELECT @NUM = @NUM + 1
						SELECT @SADJUDICADO = 'N'

						SELECT @SCOD_ESTADO = SIG_CONVOCATORIA_ITEM.ESTADO ,
						@SVALOR_REF =  SIG_CONVOCATORIA_ITEM.VALOR_MONEDA
						FROM SIG_CONVOCATORIA_ITEM
						WHERE 
						SIG_CONVOCATORIA_ITEM.ANO_EJE = @CANO_EJE AND
						SIG_CONVOCATORIA_ITEM.SEC_EJEC = @CSEC_EJEC AND
						SIG_CONVOCATORIA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
						SIG_CONVOCATORIA_ITEM.PROCESO = @SPROCESO AND
						SIG_CONVOCATORIA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
						SIG_CONVOCATORIA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
						SIG_CONVOCATORIA_ITEM.NRO_ITEM = @ISEC_RESUMEN

						SELECT @SESTADO = 'PENDIENTE'

						IF @SCOD_ESTADO = '0' 
						BEGIN
							IF @SNRO_PROCESO IS NOT NULL OR @SNRO_PROCESO > 0
							BEGIN
								SELECT @SESTADO = 'PROCESO'
							END 
							ELSE
							BEGIN		
								SELECT @SESTADO = 'PENDIENTE'
							END
						END
						IF @SCOD_ESTADO = '1' 
						BEGIN
							SELECT @SESTADO = 'PROCESO'
						END
						IF @SCOD_ESTADO = '2' 
						BEGIN
							SELECT @SESTADO = 'CANCELADO'
						END
						IF @SCOD_ESTADO = '3' 
						BEGIN
							SELECT @SESTADO = 'BUENAPRO'
						END

						IF @SCOD_ESTADO = '4' 
						BEGIN
							SELECT @SESTADO = 'BUENAPRO CONSENTIDA'
						END

						IF @SCOD_ESTADO = '5' 
						BEGIN
							SELECT @SESTADO = 'DESIERTO'
						END

						INSERT INTO TMP_SEGUIMIENTO_PAAC_MODIF
						(
						CREPORTE,CANO_EJE,CSEC_EJEC,CTIPO_CONSOLID,CNRO_CONSOLID,
						CTIPO_GENERACION,CFLAG_PAAC,CNRO_PAAC,CITEM_UNICO,CTIPO_PROCESO,
						CNOM_TIPO_PROCESO,COBJETO,CNOM_OBJETO,CESPEC_TECNICAS,
						ESIGLAS,ESECTOR,EPLIEGO,PNOM_PLIEGO,ENOM_EJECUTORA,
						ERUC_EJEC,CINSTRUMENTO,CVALOR_MONEDA,CFUENTE,
						INRO_ITEM,ITIPO_BIEN,IGRUPO_BIEN,ICLASE_BIEN,IFAMILIA_BIEN,
