					DECLARE CUR_PAAC_ITEM_PROCESO CURSOR FOR
					SELECT SIG_PROPUESTA_ITEM.PROVEEDOR AS WPROVEEDOR,
					( SELECT SIG_CONTRATISTAS.NOMBRE_PROV
					FROM SIG_CONTRATISTAS
					WHERE SIG_CONTRATISTAS.PROVEEDOR = SIG_PROPUESTA_ITEM.PROVEEDOR ) AS WNOM_PROVEEDOR,
					( SELECT SIG_CONTRATISTAS.NRO_RUC
					FROM SIG_CONTRATISTAS
					WHERE SIG_CONTRATISTAS.PROVEEDOR = SIG_PROPUESTA_ITEM.PROVEEDOR ) AS WNRO_RUC_PROVEEDOR,
					SIG_PROPUESTA_ITEM.PRECIO_MONEDA AS WPRECIO_MONEDA,
					SIG_PROPUESTA_ITEM.VALOR_MONEDA AS WVALOR_MONEDA,
					SIG_PROPUESTA_ITEM.CANTIDAD_ADJUDICA AS WCANTIDAD_ADJUDICADA
					FROM SIG_PROPUESTA_ITEM, SIG_PROPUESTA_LOTE
					WHERE 
					SIG_PROPUESTA_ITEM.ANO_EJE = SIG_PROPUESTA_LOTE.ANO_EJE AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = SIG_PROPUESTA_LOTE.SEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_GENERACION = SIG_PROPUESTA_LOTE.TIPO_GENERACION AND
					SIG_PROPUESTA_ITEM.PROCESO = SIG_PROPUESTA_LOTE.PROCESO AND
					SIG_PROPUESTA_ITEM.SEC_PROCESO = SIG_PROPUESTA_LOTE.SEC_PROCESO AND
					SIG_PROPUESTA_ITEM.CONVOCATORIA = SIG_PROPUESTA_LOTE.CONVOCATORIA AND
					SIG_PROPUESTA_ITEM.SEC_CONVOCATORIA = SIG_PROPUESTA_LOTE.SEC_CONVOCATORIA AND
					SIG_PROPUESTA_ITEM.NRO_LOTE = SIG_PROPUESTA_LOTE.NRO_LOTE AND
					SIG_PROPUESTA_ITEM.PROVEEDOR = SIG_PROPUESTA_LOTE.PROVEEDOR AND
					SIG_PROPUESTA_ITEM.NRO_PROPUESTA = SIG_PROPUESTA_LOTE.NRO_PROPUESTA AND
					SIG_PROPUESTA_ITEM.ANO_EJE = @CANO_EJE AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_GENERACION = @CTIPO_GENERACION AND
					SIG_PROPUESTA_ITEM.PROCESO = @SPROCESO AND
					SIG_PROPUESTA_ITEM.SEC_PROCESO = @SSEC_PROCESO AND
					SIG_PROPUESTA_ITEM.CONVOCATORIA = @SCONVOCATORIA AND
					SIG_PROPUESTA_ITEM.NRO_ITEM = @SSEC_ITEM AND
					SIG_PROPUESTA_LOTE.ADJUDICADO = 'S' /*AND
					SIG_PROPUESTA_ITEM.SEC_EJEC = @CSEC_EJEC AND
					SIG_PROPUESTA_ITEM.TIPO_BIEN = @ITIPO_BIEN AND
					SIG_PROPUESTA_ITEM.GRUPO_BIEN = @IGRUPO_BIEN AND
					SIG_PROPUESTA_ITEM.CLASE_BIEN = @ICLASE_BIEN AND
					SIG_PROPUESTA_ITEM.FAMILIA_BIEN = @IFAMILIA_BIEN AND
					SIG_PROPUESTA_ITEM.ITEM_BIEN = @IITEM_BIEN */

					OPEN CUR_PAAC_ITEM_PROCESO
					FETCH CUR_PAAC_ITEM_PROCESO INTO @SPROVEEDOR, @SNOM_PROVEEDOR,
					@SNRO_RUC, @SVALOR_UNIT, @SVALOR_TOTAL, @SCANTIDAD_ADJUDICADA

					SELECT @NUM_PROV = 0

					WHILE @@FETCH_STATUS = 0
					BEGIN
						--INSERTA MOVIMIENTO DE ITEM
						--HAY DATOS DE PROCESO DE SELECCION

						IF @SCANTIDAD_CI  IS NULL 
						BEGIN
							SELECT @SCANTIDAD_CI =  0
						END
						IF @SCANTIDAD_ADJUDICADA IS NULL
						BEGIN
							SELECT @SCANTIDAD_ADJUDICADA =  0
						END
						IF @SVALOR_UNIT IS NULL
						BEGIN
							SELECT @SVALOR_UNIT =  0
						END

						IF @SCANTIDAD_ADJUDICADA <> @SCANTIDAD_CI 
						BEGIN
							SELECT @SVALOR_TOTAL =  round(@SVALOR_UNIT * @SCANTIDAD_ADJUDICADA, 2)
						END

						SELECT @NUM_PROV = @NUM_PROV + 1
						SELECT @SADJUDICADO = 'S'

						INSERT INTO TMP_SEGUIMIENTO_PAAC_MODIF
						(
						CREPORTE,CANO_EJE,CSEC_EJEC,CTIPO_CONSOLID,CNRO_CONSOLID,
						CTIPO_GENERACION,CFLAG_PAAC,CNRO_PAAC,CITEM_UNICO,CTIPO_PROCESO,
						CNOM_TIPO_PROCESO,COBJETO,CNOM_OBJETO,CESPEC_TECNICAS,
						ESIGLAS,ESECTOR,EPLIEGO,PNOM_PLIEGO,ENOM_EJECUTORA,
						ERUC_EJEC,CINSTRUMENTO,CVALOR_MONEDA,CFUENTE,
						INRO_ITEM,ITIPO_BIEN,IGRUPO_BIEN,ICLASE_BIEN,IFAMILIA_BIEN,
						IITEM_BIEN,INOMBRE_ITEM,IUNIDAD_MEDIDA,INOMBRE_UNIDAD,
						ICANTIDAD,IVALOR_MONEDA,
						SSEC_ITEM, SVALOR_REF, SESTADO, SNRO_PROCESO_SEL, SNRO_CONVOCATORIA,
						SPROVEEDOR, SNOM_PROVEEDOR, SNRO_RUC, SVALOR_UNIT, SVALOR_TOTAL,
						SCANTIDAD_ADJUDICADA, SNRO_PROV, SADJUDICADO, CNOM_TIPO_PROCESO_ABREV
						)
						VALUES
						(		
						@PN_REPORTE,@CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
						@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC, @CITEM_UNICO, @CTIPO_PROCESO,
						@CNOM_TIPO_PROCESO, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
						@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
						@ERUC_EJEC,@CINSTRUMENTO,@CVALOR_MONEDA,@CFUENTE,
						@NUM,@ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,@IFAMILIA_BIEN,
						@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,@INOMBRE_UNIDAD,
						@ICANTIDAD,@IVALOR_MONEDA ,
						@SSEC_ITEM, @SVALOR_REF,@SESTADO, @SNRO_PROCESO_SEL, @SCONVOCATORIA,
						@SPROVEEDOR, @SNOM_PROVEEDOR, @SNRO_RUC, @SVALOR_UNIT,@SVALOR_TOTAL,
						@SCANTIDAD_ADJUDICADA, @NUM_PROV, @SADJUDICADO, @CNOM_TIPO_PROCESO_ABREV
						)
	
						IF @@ERROR <> 0
						BEGIN
							CLOSE CUR_PAAC_ITEM_PROCESO
							DEALLOCATE CUR_PAAC_ITEM_PROCESO
							CLOSE CUR_PAAC_ITEM
							DEALLOCATE CUR_PAAC_ITEM
							CLOSE CUR_PAAC
							DEALLOCATE CUR_PAAC
							GOTO ERROR
						END

						FETCH CUR_PAAC_ITEM_PROCESO INTO @SPROVEEDOR, @SNOM_PROVEEDOR,
						@SNRO_RUC, @SVALOR_UNIT, @SVALOR_TOTAL, @SCANTIDAD_ADJUDICADA
					END
					CLOSE CUR_PAAC_ITEM_PROCESO
					DEALLOCATE CUR_PAAC_ITEM_PROCESO

				END
			END
			ELSE			
			BEGIN
				--INSERTA MOVIMIENTO DE ITEM
				--NO HAY DATOS DE PROCESO DE SELECCION
				--SELECT @NUM = @NUM + 1
				SELECT @SADJUDICADO = 'N'

				INSERT INTO TMP_SEGUIMIENTO_PAAC_MODIF
				(
				CREPORTE,CANO_EJE,CSEC_EJEC,CTIPO_CONSOLID,CNRO_CONSOLID,
				CTIPO_GENERACION,CFLAG_PAAC,CNRO_PAAC,CITEM_UNICO,CTIPO_PROCESO,
				CNOM_TIPO_PROCESO,COBJETO,CNOM_OBJETO,CESPEC_TECNICAS,
				ESIGLAS,ESECTOR,EPLIEGO,PNOM_PLIEGO,ENOM_EJECUTORA,
				ERUC_EJEC,CINSTRUMENTO,CVALOR_MONEDA,CFUENTE,
				INRO_ITEM,ITIPO_BIEN,IGRUPO_BIEN,ICLASE_BIEN,IFAMILIA_BIEN,
				IITEM_BIEN,INOMBRE_ITEM,IUNIDAD_MEDIDA,INOMBRE_UNIDAD,
				ICANTIDAD,IVALOR_MONEDA,
				SSEC_ITEM, SVALOR_REF, SESTADO, SNRO_PROCESO_SEL, SNRO_CONVOCATORIA,
				SPROVEEDOR, SNOM_PROVEEDOR, SNRO_RUC, SVALOR_UNIT, SVALOR_TOTAL,
				SCANTIDAD_ADJUDICADA, SNRO_PROV, SADJUDICADO, CNOM_TIPO_PROCESO_ABREV
				)
				VALUES
				(		
				@PN_REPORTE,@CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
				@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC, @CITEM_UNICO, @CTIPO_PROCESO,
				@CNOM_TIPO_PROCESO, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
				@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
				@ERUC_EJEC,@CINSTRUMENTO,@CVALOR_MONEDA,@CFUENTE,
				@NUM,@ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,@IFAMILIA_BIEN,
				@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,@INOMBRE_UNIDAD,
				@ICANTIDAD,@IVALOR_MONEDA ,
				0, 0.00,'', '', NULL,
				NULL, '', '', 0.00,0.00,
				0, 0, @SADJUDICADO, @CNOM_TIPO_PROCESO_ABREV
				)

				IF @@ERROR <> 0
				BEGIN
					CLOSE CUR_PAAC_ITEM
					DEALLOCATE CUR_PAAC_ITEM
					CLOSE CUR_PAAC
					DEALLOCATE CUR_PAAC
					GOTO ERROR
				END
			END

			FETCH CUR_PAAC_ITEM INTO @ITIPO_BIEN,@IGRUPO_BIEN,@ICLASE_BIEN,
			@IFAMILIA_BIEN,@IITEM_BIEN,@INOMBRE_ITEM ,@IUNIDAD_MEDIDA,
			@INOMBRE_UNIDAD,@ICANTIDAD,@IVALOR_MONEDA,@ISEC_RESUMEN
		END
		CLOSE CUR_PAAC_ITEM
		DEALLOCATE CUR_PAAC_ITEM
	END

	--ASIGNAR DESCRIPCION DE ESTADO EN CABECERA
	--

	SELECT @CTITULO = ''

	SELECT @WCUENTA_TOTAL_ITEM = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION
	
	IF @WCUENTA_TOTAL_ITEM IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_DESIERTO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'DESIERTO'

	IF @WCUENTA_TOTAL_ITEM_DESIERTO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_DESIERTO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_CANCELADO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'CANCELADO'

	IF @WCUENTA_TOTAL_ITEM_CANCELADO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_CANCELADO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_CONCLUIDO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'CONCLUIDO'

	IF @WCUENTA_TOTAL_ITEM_CONCLUIDO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_CONCLUIDO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_PROCESO = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'PROCESO'

	IF @WCUENTA_TOTAL_ITEM_PROCESO IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_PROCESO = 0 
	END

	SELECT @WCUENTA_TOTAL_ITEM_PENDIENTE = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'PENDIENTE'

	IF @WCUENTA_TOTAL_ITEM_PENDIENTE IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_PENDIENTE = 0 
	END



	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_DESIERTO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'DESIERTO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_CANCELADO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'CANCELADO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_CONCLUIDO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'ADJ. TOTAL'
	END


	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_PROCESO AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	IF @WCUENTA_TOTAL_ITEM = @WCUENTA_TOTAL_ITEM_PENDIENTE AND @WCUENTA_TOTAL_ITEM > 0 
	BEGIN
		SELECT @CTITULO = 'PENDIENTE'
	END


	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_CONCLUIDO AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_CONCLUIDO > 0
	BEGIN
		SELECT @CTITULO = 'ADJ. PARCIAL'
	END

	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_PROCESO AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_PROCESO > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	IF @WCUENTA_TOTAL_ITEM <> @WCUENTA_TOTAL_ITEM_PENDIENTE AND @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_PENDIENTE > 0
	BEGIN
		SELECT @CTITULO = 'PROCESO'
	END

	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_S = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO'AND
	SADJUDICADO = 'S'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_S IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_S = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_S > 0
	BEGIN
		SELECT @WCOUNT_REP = COUNT(*)
		FROM TMP_SEGUIMIENTO_PAAC_MODIF
		WHERE 
		CREPORTE = @PN_REPORTE AND
		CANO_EJE = @CANO_EJE AND
		CSEC_EJEC = @CSEC_EJEC AND
		CTIPO_CONSOLID = @CTIPO_CONSOLID AND
		CNRO_CONSOLID = @CNRO_CONSOLID AND
		CTIPO_GENERACION = @CTIPO_GENERACION AND
		SESTADO IN ('DESIERTO', 'PENDIENTE')  

		IF @WCOUNT_REP > 0 
		BEGIN
			SELECT @CTITULO = 'ADJ. PARCIAL'
		END
		ELSE
		BEGIN
			SELECT @WCOUNT_REP = COUNT(*)
			FROM TMP_SEGUIMIENTO_PAAC_MODIF
			WHERE 
			CREPORTE = @PN_REPORTE AND
			CANO_EJE = @CANO_EJE AND
			CSEC_EJEC = @CSEC_EJEC AND
			CTIPO_CONSOLID = @CTIPO_CONSOLID AND
			CNRO_CONSOLID = @CNRO_CONSOLID AND
			CTIPO_GENERACION = @CTIPO_GENERACION AND
			SESTADO = 'BUENAPRO'AND
			SADJUDICADO = 'N'

			IF @WCOUNT_REP > 0 
			BEGIN
				SELECT @CTITULO = 'PROCESO'
			END
			ELSE
			BEGIN
				SELECT @CTITULO = 'CONCLUIDO'
			END
		END
	END
	ELSE
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_N = COUNT(*)
		FROM TMP_SEGUIMIENTO_PAAC_MODIF
		WHERE 
		CREPORTE = @PN_REPORTE AND
		CANO_EJE = @CANO_EJE AND
		CSEC_EJEC = @CSEC_EJEC AND
		CTIPO_CONSOLID = @CTIPO_CONSOLID AND
		CNRO_CONSOLID = @CNRO_CONSOLID AND
		CTIPO_GENERACION = @CTIPO_GENERACION AND
		SESTADO = 'BUENAPRO'AND
		SADJUDICADO = 'N'

		IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_N IS NULL
		BEGIN
			SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_N = 0 
		END

		IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_N > 0
		BEGIN
			SELECT @CTITULO = 'PROCESO'
		END
	END

	SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S = COUNT(*)
	FROM TMP_SEGUIMIENTO_PAAC_MODIF
	WHERE 
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION AND
	SESTADO = 'BUENAPRO CONSENTIDA'AND
	SADJUDICADO = 'S'

	IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S IS NULL
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S = 0 
	END

	IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_S > 0
	BEGIN
		SELECT @WCOUNT_REP = COUNT(*)
		FROM TMP_SEGUIMIENTO_PAAC_MODIF
		WHERE 
		CREPORTE = @PN_REPORTE AND
		CANO_EJE = @CANO_EJE AND
		CSEC_EJEC = @CSEC_EJEC AND
		CTIPO_CONSOLID = @CTIPO_CONSOLID AND
		CNRO_CONSOLID = @CNRO_CONSOLID AND
		CTIPO_GENERACION = @CTIPO_GENERACION AND
		SESTADO IN ('DESIERTO', 'PENDIENTE')

		IF @WCOUNT_REP > 0
		BEGIN
			SELECT @CTITULO = 'ADJ. PARCIAL'		
		END
		ELSE
		BEGIN
			SELECT @WCOUNT_REP = COUNT(*)
			FROM TMP_SEGUIMIENTO_PAAC_MODIF
			WHERE 
			CREPORTE = @PN_REPORTE AND
			CANO_EJE = @CANO_EJE AND
			CSEC_EJEC = @CSEC_EJEC AND
			CTIPO_CONSOLID = @CTIPO_CONSOLID AND
			CNRO_CONSOLID = @CNRO_CONSOLID AND
			CTIPO_GENERACION = @CTIPO_GENERACION AND
			SESTADO = 'BUENAPRO CONSENTIDA'AND
			SADJUDICADO = 'N'

			IF @WCOUNT_REP > 0
			BEGIN
				SELECT @CTITULO = 'PROCESO'
			END
			ELSE
			BEGIN
				SELECT @CTITULO = 'CONCLUIDO'
			END
		END
	END
	ELSE
	BEGIN
		SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N = COUNT(*)
		FROM TMP_SEGUIMIENTO_PAAC_MODIF
		WHERE 
		CREPORTE = @PN_REPORTE AND
		CANO_EJE = @CANO_EJE AND
		CSEC_EJEC = @CSEC_EJEC AND
		CTIPO_CONSOLID = @CTIPO_CONSOLID AND
		CNRO_CONSOLID = @CNRO_CONSOLID AND
		CTIPO_GENERACION = @CTIPO_GENERACION AND
		SESTADO = 'BUENAPRO CONSENTIDA'AND
		SADJUDICADO = 'N'

		IF @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N IS NULL
		BEGIN
			SELECT @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N = 0 
		END

		IF @WCUENTA_TOTAL_ITEM > 0 AND @WCUENTA_TOTAL_ITEM_BUENA_PRO_CON_N > 0
		BEGIN
			SELECT @CTITULO = 'PROCESO'
		END
	END

	IF (RTRIM(LTRIM(@CTITULO)) = '') OR ( @CTITULO IS NULL )
	BEGIN
		SELECT 	@WESTADO_PAAC = ESTADO, @WESTADO_REP = ESTADO_REPROGRAMACION
		FROM SIG_PAAC_CONSOLIDADO
		WHERE
		ANO_EJE = @CANO_EJE AND
		SEC_EJEC = @CSEC_EJEC AND
		TIPO_CONSOLID = @CTIPO_CONSOLID AND
		NRO_CONSOLID = @CNRO_CONSOLID AND
		TIPO_GENERACION = @CTIPO_GENERACION 


		IF ( @WESTADO_REP IS NULL )  OR ( RTRIM(LTRIM(@WESTADO_REP)) = '')
		BEGIN 
			SELECT @WNESTADO_PAAC = sig_maestro_estado.nombre
			FROM sig_maestro_estado  
			WHERE sig_maestro_estado.cod_maestro = 'PAAC_MODIF_ESTADO' AND 
			sig_maestro_estado.cod_detalle = @WESTADO_PAAC
	
			IF @WESTADO_PAAC = '1' 
			BEGIN
				SELECT @CTITULO = UPPER(@WNESTADO_PAAC)
			END
			ELSE
			BEGIN
				SELECT @WCOUNT_PAAC = COUNT(*)
				FROM SIG_PROCESO_DE_SELECCION
				WHERE ANO_EJE = @CANO_EJE AND
				SEC_EJEC = @CSEC_EJEC AND
				TIPO_GENERACION = @CTIPO_GENERACION AND
				NRO_CONSOLID = @CNRO_CONSOLID AND
				TIPO_GENERACION = @CTIPO_GENERACION 

				IF @WCOUNT_PAAC IS NULL
				BEGIN
					SELECT @WCOUNT_PAAC = 0 
				END 

				IF @WCOUNT_PAAC = 0 
				BEGIN
					SELECT @CTITULO = 'PENDIENTE'
				END 
				ELSE
				BEGIN
					IF @WCOUNT_PAAC = 1 
					BEGIN
						SELECT @WNESTADO_PAAC = ( CASE ESTADO WHEN '0' THEN 'PENDIENTE' WHEN '1' THEN 'PROCESO' WHEN '2' THEN 'SUPENDIDO' WHEN '3' THEN 'CANCELADO' WHEN '4' THEN 'CONCLUIDO' END )
						FROM SIG_PROCESO_DE_SELECCION
						WHERE ANO_EJE = @CANO_EJE AND
						SEC_EJEC = @CSEC_EJEC AND
						TIPO_GENERACION = @CTIPO_GENERACION AND
						NRO_CONSOLID = @CNRO_CONSOLID AND
						TIPO_GENERACION = @CTIPO_GENERACION 
					END
					ELSE
					BEGIN
						SELECT @WNESTADO_PAAC = ( CASE ESTADO WHEN '0' THEN 'PENDIENTE' WHEN '1' THEN 'PROCESO' WHEN '2' THEN 'SUPENDIDO' WHEN '3' THEN 'CANCELADO' WHEN '4' THEN 'CONCLUIDO' END )
						FROM SIG_PROCESO_DE_SELECCION
						WHERE ANO_EJE = @CANO_EJE AND
						SEC_EJEC = @CSEC_EJEC AND
						TIPO_GENERACION = @CTIPO_GENERACION AND
						NRO_CONSOLID = @CNRO_CONSOLID AND
						TIPO_GENERACION = @CTIPO_GENERACION AND
						PROCESO = (SELECT MIN(A.ESTADO)
						FROM SIG_PROCESO_DE_SELECCION A
						WHERE A.ANO_EJE = @CANO_EJE AND
						A.SEC_EJEC = @CSEC_EJEC AND
						A.TIPO_GENERACION = @CTIPO_GENERACION AND
						A.PROCESO = SIG_PROCESO_DE_SELECCION.PROCESO AND
						A.NRO_CONSOLID = @CNRO_CONSOLID AND
						A.TIPO_GENERACION = @CTIPO_GENERACION  )
					END
					SELECT @CTITULO = UPPER(@WNESTADO_PAAC)
				END 

			END
		END
		ELSE
		BEGIN
		--INCLSION EXLUSION
			IF @WESTADO_REP = '1' 
			BEGIN
				SELECT @CTITULO = 'PENDIENTE'
			END 
			ELSE
			BEGIN
				SELECT @CTITULO = NOMBRE
				FROM SIG_MAESTRO_ESTADO
				WHERE COD_MAESTRO = 'ESTADO_INC_EXC' AND
				COD_DETALLE = @WESTADO_REP
			END 
		END
--		IF (RTRIM(LTRIM(@WESTADO_PAAC)) = '') OR (@WESTADO_PAAC IS NULL)  OR (RTRIM(LTRIM(@WESTADO_PAAC)) = '1')
--		BEGIN
--			SELECT @CTITULO = 'PENDIENTE'
--		END	
	END

	UPDATE TMP_SEGUIMIENTO_PAAC_MODIF
	SET CTITULO = @CTITULO
	WHERE
	CREPORTE = @PN_REPORTE AND
	CANO_EJE = @CANO_EJE AND
	CSEC_EJEC = @CSEC_EJEC AND
	CTIPO_CONSOLID = @CTIPO_CONSOLID AND
	CNRO_CONSOLID = @CNRO_CONSOLID AND
	CTIPO_GENERACION = @CTIPO_GENERACION 

	--
	--ASIGNAR DESCRIPCION DE ESTADO EN CABECERA

	FETCH CUR_PAAC INTO @CANO_EJE,@CSEC_EJEC,@CTIPO_CONSOLID,@CNRO_CONSOLID,
	@CTIPO_GENERACION,@CFLAG_PAAC,@CNRO_PAAC,@CITEM_UNICO ,@CTIPO_PROCESO,
	@CNOM_TIPO_PROCESO,@CNOM_TIPO_PROCESO_ABREV, @COBJETO,@CNOM_OBJETO,@CESPEC_TECNICAS,
	@ESIGLAS,@ESECTOR,@EPLIEGO,@PNOM_PLIEGO ,@ENOM_EJECUTORA,
	@ERUC_EJEC,@CINSTRUMENTO, @CVALOR_MONEDA

END

CLOSE CUR_PAAC
DEALLOCATE CUR_PAAC

RETURN 0
 
ERROR:
   RETURN 1;

--/
GO


