-- ----------------------------
-- procedure structure for SP_PROCESAR_TECHOC_FASE_22
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_TECHOC_FASE_22]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_TECHOC_FASE_22]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_TECHOC_FASE_22]  
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)  
AS  
  
BEGIN  
 DECLARE @lI_FASE_CUADRO NUMERIC(1,0)  
 DECLARE @ls_clasificador VARCHAR(20)  
 DECLARE @ls_flag_presup VARCHAR(1)  
 DECLARE @ls_centro_costo_presup VARCHAR(15)  
 DECLARE @ls_centro_costo_cambio VARCHAR(15)  
 DECLARE @ls_centro_costo VARCHAR(15)  
 DECLARE @ls_centro_padre VARCHAR(15)  
 DECLARE @ls_origen VARCHAR(1)  
 DECLARE @ls_codi_fuen VARCHAR(2)  
 DECLARE @ls_codi_fuen_impto VARCHAR(2)  
 DECLARE @ls_clas_gast VARCHAR(20)  
 DECLARE @ls_funcion VARCHAR(2)  
 DECLARE @ls_programa VARCHAR(3)  
 DECLARE @ld_Secu_func NUMERIC(4,0)  
 DECLARE @li_contador NUMERIC(10,0)  
 DECLARE @ld_valor_imp_progra NUMERIC(14,2)  
 DECLARE @li_secuencia NUMERIC(10,0)  
 DECLARE @ld_valor_progra NUMERIC(14,2)  
 DECLARE @ld_valor_aprob NUMERIC(14,2)  
 DECLARE @ld_mnto_impto NUMERIC(14,2)  
 DECLARE @ld_monto_progra NUMERIC(14,2)  
 DECLARE @ld_mnto_total NUMERIC(14,2)  
 DECLARE @ld_mnto_apro NUMERIC(14,2)  
 DECLARE @ld_mnto_asig NUMERIC(14,2)  
 DECLARE @ld_mnto_modif NUMERIC(14,2)  
 DECLARE @ls_categ_gasto VARCHAR(1)  
 DECLARE @ls_grupo_gasto VARCHAR(1)  
 DECLARE @ls_grupo VARCHAR(2)  
 DECLARE @ls_grupo1 VARCHAR(2)  
 DECLARE @ls_flag_gen_esp VARCHAR(1)  
 DECLARE @ld_valor_imp_asignado NUMERIC(14,2)  
 DECLARE @ld_valor_asignado NUMERIC(14,2)  
 DECLARE @ld_monto_asignado NUMERIC(14,2)  
 DECLARE @ld_monto_aprob NUMERIC(14,2)  
 DECLARE @ld_valor_imp_aprob NUMERIC(14,2)  
 declare @ld_min_correl numeric(8,0)  
 DECLARE @ls_flag_techo varchar(1)  
  
SELECT @ls_flag_gen_esp = valor  
  FROM sig_parametro_ejecutora_anio  
 WHERE ano_eje  = @PN_ANIO and  
       sec_ejec = @PN_EJEC and  
       cod_maestro = 'FLAG_TECHO_NIVEL'  
  
SELECT @ls_flag_techo = valor   
FROM sig_parametro_ejecutora_anio  
WHERE ano_eje  = @PN_ANIO and        
sec_ejec = @PN_EJEC and  
cod_maestro = 'FLAG_RESP_TECHO'  
  
SELECT @li_secuencia = IsNull(MAX(secuencia), 0)  
FROM sig_techo_presupuesto  
WHERE ano_eje  = @PN_ANIO and  
      sec_ejec = @PN_EJEC  
  
SET NOCOUNT ON  
  

IF @ls_flag_gen_esp <> '0' 
BEGIN  
     INSERT INTO tmp_techo_fase_7  
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,  
                  funcion, programa, sec_func_prop, centro_costo_presup, clasificador)  
          SELECT DISTINCT  
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,  
                 b.funcion, b.programa, b.sec_func_prop, b.centro_costo_presup, b.clasificador  
            FROM sig_techo_presupuesto b  
           WHERE b.ano_eje     = @PN_ANIO and  
                 b.sec_ejec    = @PN_EJEC and  
                 b.fase_cuadro = @PN_FASE and  
                 b.indicador   = '0'      and  
                 b.flag_meta_aprob = '0'  and  
                 not exists (SELECT '1'  
                               FROM sig_techo_presupuesto c  
                              WHERE c.ano_eje     = b.ano_eje  and  
                                    c.sec_ejec    = b.sec_ejec and  
                                    c.fase_cuadro = @PN_FASE   and  
                                    c.origen      = b.origen   and  
                                    c.fuente_financ = b.fuente_financ and  
                                    c.categ_gasto   = b.categ_gasto   and  
                                    c.grupo_gasto   = b.grupo_gasto   and  
                                    c.sec_func_prop = b.sec_func_prop and  
                                    c.centro_costo_presup = b.centro_costo_presup and  
                                    c.clasificador    = b.clasificador and  
                                    c.indicador       = '5' and  
                                    c.flag_meta_aprob = '0')  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
       

     SELECT @li_secuencia = IsNull(MAX(secuencia), 0)  
       FROM sig_techo_presupuesto  
      WHERE ano_eje  = @PN_ANIO and  
            sec_ejec = @PN_EJEC  
       

     INSERT INTO sig_techo_presupuesto  
                 (ano_eje    , sec_ejec    , origen      , fuente_financ, secuencia    ,  
                  categ_gasto, grupo_gasto , clasificador, funcion      , programa     ,  
                  sec_func   , centro_costo, ppto_progra , ppto_aprob   , ppto_asignado,  
                  ppto_modif , mnto_progra , mnto_asig   , mnto_aprob   , mnto_modif   ,  
                  indicador  , paac_inicial, paac_modif  , porc_techo   , porc_asig    ,  
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)  
          SELECT @PN_ANIO, @PN_EJEC, origen , fuente_financ, (@li_secuencia + secuencia),  
                 categ_gasto, grupo_gasto, clasificador, funcion, programa, NULL, NULL,  
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '5', 0, 0, 0,  
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE  
            FROM tmp_techo_fase_7  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
       

     UPDATE sig_techo_presupuesto  
        SET mnto_asig = (SELECT SUM(A.mnto_asig)  
                           FROM sig_techo_presupuesto A  
                          WHERE A.ano_eje     = @PN_ANIO and  
                                A.sec_ejec    = @PN_EJEC and  
                                A.fase_cuadro = @PN_FASE and  
                                A.origen      = sig_techo_presupuesto.origen and  
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and  
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and  
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and  
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and  
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and  
                                A.clasificador  =  sig_techo_presupuesto.clasificador and  
                                A.indicador       = '0' and  
                                A.flag_meta_aprob = '0')  
      WHERE ano_eje     = @PN_ANIO and  
            sec_ejec    = @PN_EJEC and  
            fase_cuadro = @PN_FASE and  
            indicador   = '5'      and  
            flag_meta_aprob = '0'  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
       

     INSERT INTO tmp_techo_fase_8  
                 (origen, fuente_financ, mnto_progra, fase_cuadro, categ_gasto, grupo_gasto,  
                  funcion, programa, sec_func_prop, centro_costo_presup)  
          SELECT DISTINCT  
                 b.origen, b.fuente_financ, 0, @PN_FASE, b.categ_gasto, b.grupo_gasto,  
                 b.funcion, b.programa, b.sec_func_prop, b.centro_costo_presup  
            FROM sig_techo_presupuesto b  
           WHERE b.ano_eje     = @PN_ANIO and  
                 b.sec_ejec    = @PN_EJEC and  
                 b.fase_cuadro = @PN_FASE and  
                 b.indicador   = '0'      and  
                 b.flag_meta_aprob = '0'  and  
                 not exists (SELECT '1'  
                               FROM sig_techo_presupuesto c  
                              WHERE c.ano_eje     = b.ano_eje  and  
                                    c.sec_ejec    = b.sec_ejec and  
                                    c.fase_cuadro = @PN_FASE   and  
                                    c.origen      = b.origen   and  
                                    c.fuente_financ = b.fuente_financ and  
                                    c.categ_gasto   = b.categ_gasto   and  
                                    c.grupo_gasto   = b.grupo_gasto   and  
                                    c.sec_func_prop = b.sec_func_prop and  
                                    c.centro_costo_presup = b.centro_costo_presup and  
                                    c.indicador       = '4' and  
                                    c.flag_meta_aprob = '0')  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
       
     SELECT @li_secuencia = max(secuencia)   
       FROM sig_techo_presupuesto   
      WHERE ano_eje  = @PN_ANIO and  
            sec_ejec = @PN_EJEC  
       
     INSERT INTO sig_techo_presupuesto  
                 (ano_eje      , sec_ejec       , origen      , fuente_financ, secuencia    ,  
                  categ_gasto  , grupo_gasto    , clasificador, funcion      , programa     ,  
                  sec_func     , centro_costo   , ppto_progra , ppto_aprob   , ppto_asignado,  
                  ppto_modif   , mnto_progra    , mnto_asig   , mnto_aprob   , mnto_modif   ,  
                  indicador    , paac_inicial   , paac_modif  , porc_techo   , porc_asig    ,  
                  sec_func_prop, flag_meta_aprob, centro_costo_presup, fase_cuadro)  
          SELECT @PN_ANIO, @PN_EJEC, origen, fuente_financ, (@li_secuencia + secuencia),  
                 categ_gasto, grupo_gasto, NULL, funcion, programa, NULL, NULL,  
                 0, 0, 0, 0, mnto_progra, 0, 0, 0, '4', 0, 0, 0,  
                 0, sec_func_prop, '0', centro_costo_presup, @PN_FASE  
            FROM tmp_techo_fase_8  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
       
     UPDATE sig_techo_presupuesto  
        SET mnto_asig = (SELECT SUM(A.mnto_asig)  
                           FROM sig_techo_PRESUPUESTO A  
                          WHERE A.ano_eje     = @PN_ANIO and  
                                A.sec_ejec    = @PN_EJEC and  
                                A.fase_cuadro = @PN_FASE and  
                                A.origen      = sig_techo_presupuesto.origen and  
                                A.fuente_financ = sig_techo_presupuesto.fuente_financ and  
                                A.categ_gasto   = sig_techo_presupuesto.categ_gasto   and  
                                A.grupo_gasto   = sig_techo_presupuesto.grupo_gasto   and  
                                A.sec_func_prop = sig_techo_presupuesto.sec_func_prop and  
                                A.centro_costo_presup = sig_techo_presupuesto.centro_costo_presup and  
                                A.indicador       = '0' and  
                                A.flag_meta_aprob = '0')  
      WHERE ano_eje     = @PN_ANIO and  
            sec_ejec    = @PN_EJEC and  
            fase_cuadro = @PN_FASE and  
            indicador   = '4'      and  
            flag_meta_aprob = '0'  
       
     IF @@ERROR <> 0  
     BEGIN  
	   return -1  
     END  
END  
  
TRUNCATE TABLE dbo.tmp_techo_cn_fase   
TRUNCATE TABLE dbo.tmp_propuesta_fase   
TRUNCATE TABLE dbo.tmp_techo_fase_2   
TRUNCATE TABLE dbo.tmp_techo_fase_3  
TRUNCATE TABLE dbo.tmp_techo_fase_4  
TRUNCATE TABLE dbo.tmp_techo_fase_5  
TRUNCATE TABLE dbo.tmp_techo_fase_6  
TRUNCATE TABLE dbo.tmp_techo_fase_7  
TRUNCATE TABLE dbo.tmp_techo_fase_8  
  
RETURN 1  
END;--/
GO


-- ----------------------------
-- function structure for SF_SIG_PARAMETRO_EJECUTORA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_SIG_PARAMETRO_EJECUTORA]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_SIG_PARAMETRO_EJECUTORA]
GO

CREATE FUNCTION [dbo].[SF_SIG_PARAMETRO_EJECUTORA] (
									@PN_SEC_EJEC		NUMERIC,
									@PS_CADENA			VARCHAR(250)
									)
RETURNS VARCHAR(250)
AS
BEGIN
	DECLARE @ls_valor		VARCHAR(250)

  SELECT @ls_valor = valor
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec 	= CONVERT(VARCHAR,@PN_SEC_EJEC) AND  
         cod_maestro = @PS_CADENA  	

	IF  @PS_CADENA = 'INIC_PAT_MES' OR @PS_CADENA = 'PROC_PAT_MES'
	BEGIN
		SET @ls_valor = RIGHT('00'+@ls_valor,2)
	END
	
	RETURN @ls_valor

END
GO


-- ----------------------------
-- procedure structure for usp_Mant_Indices_Online
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_Mant_Indices_Online]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_Mant_Indices_Online]
GO

CREATE PROCEDURE [dbo].[usp_Mant_Indices_Online]
  @RebuildThreshold   float = 30,
  @ReorgLow           float = 5,
  @ReorgHigh          float = 30,
  @MinPages           int   = 1000,
  @MaxDOP             int   = 4,
  @UseSortInTempdb    bit   = 1,
  @LowPriorityMinutes int   = 60,
  @AllowCSRebuild     bit   = 0 -- Columnstore REBUILD (por defecto no)
AS
BEGIN
  SET NOCOUNT ON;

  IF OBJECT_ID('tempdb..#frag') IS NOT NULL DROP TABLE #frag;

  SELECT
      f.object_id,
      f.index_id,
      i.name AS index_name,
      i.type_desc,
      f.avg_fragmentation_in_percent AS frag,
      f.page_count
  INTO #frag
  FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') f
  JOIN sys.indexes i
    ON i.object_id = f.object_id AND i.index_id = f.index_id
  WHERE f.index_id > 0
    AND f.page_count >= @MinPages
    AND i.is_hypothetical = 0
    AND i.is_disabled = 0;

  DECLARE
    @obj  nvarchar(512),
    @ix   nvarchar(512),
    @sql  nvarchar(max),
    @opt  nvarchar(400);

  -- Opciones para REBUILD online/resumable
  SET @opt = N'ONLINE = ON, RESUMABLE = ON, MAXDOP = ' + CONVERT(nvarchar(10), @MaxDOP);
  IF @UseSortInTempdb = 1
    SET @opt += N', SORT_IN_TEMPDB = ON';
  SET @opt += N', WAIT_AT_LOW_PRIORITY (MAX_DURATION = ' + CONVERT(nvarchar(10), @LowPriorityMinutes) + N' MINUTES, ABORT_AFTER_WAIT = SELF)';

  -------------------------------------------------------------------
  -- 2.1 REBUILD (árbol B-Tree) > @RebuildThreshold
  -------------------------------------------------------------------
  DECLARE cur_rb CURSOR LOCAL FAST_FORWARD FOR
  SELECT QUOTENAME(OBJECT_SCHEMA_NAME(object_id)) + '.' + QUOTENAME(OBJECT_NAME(object_id)) AS obj,
         QUOTENAME(index_name) AS ix, frag, page_count, type_desc
  FROM #frag
  WHERE frag > @RebuildThreshold
    AND type_desc NOT LIKE '%COLUMNSTORE%';

  OPEN cur_rb; FETCH NEXT FROM cur_rb INTO @obj, @ix, @RebuildThreshold, @MinPages, @opt; -- dummy read to match vars
  CLOSE cur_rb; DEALLOCATE cur_rb;

  -- Reabrir cursor correctamente (arriba fue solo para "warm up" nombres)
  DECLARE cur_rb2 CURSOR LOCAL FAST_FORWARD FOR
  SELECT QUOTENAME(OBJECT_SCHEMA_NAME(object_id)) + '.' + QUOTENAME(OBJECT_NAME(object_id)) AS obj,
         QUOTENAME(index_name) AS ix, frag, page_count
  FROM #frag
  WHERE frag > @RebuildThreshold
    AND type_desc NOT LIKE '%COLUMNSTORE%';

  OPEN cur_rb2;
  FETCH NEXT FROM cur_rb2 INTO @obj, @ix, @RebuildThreshold, @MinPages;
  WHILE @@FETCH_STATUS = 0
  BEGIN
    BEGIN TRY
      SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REBUILD WITH (' + @opt + N');';
      EXEC sp_executesql @sql;
      INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success)
      VALUES ('REBUILD', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @RebuildThreshold, @MinPages, @sql, 1);
    END TRY
    BEGIN CATCH
      -- Fallback offline
      BEGIN TRY
        SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REBUILD;';
        EXEC sp_executesql @sql;
        INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
        VALUES ('REBUILD_FALLBACK', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @RebuildThreshold, @MinPages, @sql, 1,
                LEFT(ERROR_MESSAGE(), 4000));
      END TRY
      BEGIN CATCH
        INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
        VALUES ('REBUILD_FALLBACK', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @RebuildThreshold, @MinPages, @sql, 0,
                LEFT(ERROR_MESSAGE(), 4000));
      END CATCH
    END CATCH
    FETCH NEXT FROM cur_rb2 INTO @obj, @ix, @RebuildThreshold, @MinPages;
  END
  CLOSE cur_rb2; DEALLOCATE cur_rb2;

  -------------------------------------------------------------------
  -- 2.2 REORGANIZE (árbol B-Tree) entre @ReorgLow y @ReorgHigh
  -------------------------------------------------------------------
  DECLARE cur_rg CURSOR LOCAL FAST_FORWARD FOR
  SELECT QUOTENAME(OBJECT_SCHEMA_NAME(object_id)) + '.' + QUOTENAME(OBJECT_NAME(object_id)) AS obj,
         QUOTENAME(index_name) AS ix, frag, page_count
  FROM #frag
  WHERE frag BETWEEN @ReorgLow AND @ReorgHigh
    AND type_desc NOT LIKE '%COLUMNSTORE%';

  OPEN cur_rg;
  FETCH NEXT FROM cur_rg INTO @obj, @ix, @ReorgLow, @MinPages;
  WHILE @@FETCH_STATUS = 0
  BEGIN
    SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REORGANIZE;';
    BEGIN TRY
      EXEC sp_executesql @sql;
      INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success)
      VALUES ('REORGANIZE', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @ReorgLow, @MinPages, @sql, 1);
    END TRY
    BEGIN CATCH
      INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
      VALUES ('REORGANIZE', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @ReorgLow, @MinPages, @sql, 0,
              LEFT(ERROR_MESSAGE(), 4000));
    END CATCH
    FETCH NEXT FROM cur_rg INTO @obj, @ix, @ReorgLow, @MinPages;
  END
  CLOSE cur_rg; DEALLOCATE cur_rg;

  -------------------------------------------------------------------
  -- 2.3 COLUMNSTORE: REORGANIZE (compacta rowgroups)
  -------------------------------------------------------------------
  DECLARE cur_cs CURSOR LOCAL FAST_FORWARD FOR
  SELECT QUOTENAME(OBJECT_SCHEMA_NAME(object_id)) + '.' + QUOTENAME(OBJECT_NAME(object_id)) AS obj,
         QUOTENAME(index_name) AS ix, frag, page_count, type_desc
  FROM #frag
  WHERE type_desc LIKE '%COLUMNSTORE%' AND frag >= @ReorgLow;

  OPEN cur_cs;
  DECLARE @frag decimal(6,2), @pc int, @td nvarchar(60);
  FETCH NEXT FROM cur_cs INTO @obj, @ix, @frag, @pc, @td;
  WHILE @@FETCH_STATUS = 0
  BEGIN
    IF @AllowCSRebuild = 1 AND @frag > @RebuildThreshold
    BEGIN
      BEGIN TRY
        SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REBUILD WITH (' + @opt + N');';
        EXEC sp_executesql @sql;
        INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success)
        VALUES ('REBUILD_CS', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @frag, @pc, @sql, 1);
      END TRY
      BEGIN CATCH
        SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REORGANIZE;';
        BEGIN TRY
          EXEC sp_executesql @sql;
          INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
          VALUES ('REORGANIZE_CS', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @frag, @pc, @sql, 1,
                  LEFT(ERROR_MESSAGE(), 4000));
        END TRY
        BEGIN CATCH
          INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
          VALUES ('REORGANIZE_CS', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @frag, @pc, @sql, 0,
                  LEFT(ERROR_MESSAGE(), 4000));
        END CATCH
      END CATCH
    END
    ELSE
    BEGIN
      SET @sql = N'ALTER INDEX ' + @ix + N' ON ' + @obj + N' REORGANIZE;';
      BEGIN TRY
        EXEC sp_executesql @sql;
        INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success)
        VALUES ('REORGANIZE_CS', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @frag, @pc, @sql, 1);
      END TRY
      BEGIN CATCH
        INSERT INTO dbo.MantHistory(action, schema_name, table_name, index_name, frag_pct, page_count, command_text, success, err_message)
        VALUES ('REORGANIZE_CS', PARSENAME(@obj,2), PARSENAME(@obj,1), REPLACE(@ix,'[',''), @frag, @pc, @sql, 0,
                LEFT(ERROR_MESSAGE(), 4000));
      END CATCH
    END
    FETCH NEXT FROM cur_cs INTO @obj, @ix, @frag, @pc, @td;
  END
  CLOSE cur_cs; DEALLOCATE cur_cs;

  -------------------------------------------------------------------
  -- 2.4 Actualiza estadísticas rápidas al final
  -------------------------------------------------------------------
  EXEC sp_updatestats;
END
GO


-- ----------------------------
-- procedure structure for SP_SI_RETORNA_FASE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_RETORNA_FASE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_RETORNA_FASE]
GO

CREATE PROCEDURE [dbo].[SP_SI_RETORNA_FASE]
    @P_FLAG                     VARCHAR(1),
    @P_ANO_EJE                  NUMERIC(4,0),
    @P_SEC_EJC                     VARCHAR(10),                                                                           
    @O_FASE_CUADRO               VARCHAR(1) OUTPUT    
AS 
DECLARE @LD_CUENTA_FASE_REQ              numeric(5,0)
DECLARE @LD_CUENTA_FASE_PROG_2         numeric(5,0)
DECLARE @LD_CUENTA_FASE_PROG_3         numeric(5,0)
DECLARE @LD_CUENTA_FASE_PROG_4         numeric(5,0) 

  IF (@P_FLAG = '1')
	Begin
	     SELECT @LD_CUENTA_FASE_REQ = COUNT(*)
	               FROM sig_cuadro_x_centro
	               WHERE ano_eje  = @P_ANO_EJE and
	                                 sec_ejec = @P_SEC_EJC  and 
	                                 centro_costo in (select centro_costo from sig_centro_costo where ano_eje = @P_ANO_EJE and sec_ejec = @P_SEC_EJC and estado ='A' ) and
	                     estado in ('0', '7')
	     IF @LD_CUENTA_FASE_REQ IS NULL SET @LD_CUENTA_FASE_REQ = 0
	
	     SELECT @LD_CUENTA_FASE_PROG_2 = count(*)
	               FROM sig_cuadro_x_centro
	               WHERE ano_eje  = @P_ANO_EJE and
	                                sec_ejec = @P_SEC_EJC and
	                                centro_costo in (select centro_costo from sig_centro_costo where ano_eje = @P_ANO_EJE and sec_ejec = @P_SEC_EJC and estado ='A' ) and
	                     estado in ('1','2');
	     IF @LD_CUENTA_FASE_PROG_2 IS NULL SET @LD_CUENTA_FASE_PROG_2 = 0
	
	     SELECT @LD_CUENTA_FASE_PROG_3 = count(*)
	               FROM sig_cuadro_x_centro
	               WHERE ano_eje  = @P_ANO_EJE and
	                                sec_ejec = @P_SEC_EJC and
	                                centro_costo in (select centro_costo from sig_centro_costo where ano_eje = @P_ANO_EJE and sec_ejec = @P_SEC_EJC and estado ='A' ) and
	                     estado in ('3','8');
	     IF @LD_CUENTA_FASE_PROG_3 IS NULL SET @LD_CUENTA_FASE_PROG_3 = 0
	
	     SELECT @LD_CUENTA_FASE_PROG_4 = count(*)
	               FROM sig_cuadro_x_centro
	               WHERE ano_eje  = @P_ANO_EJE and
	                                sec_ejec = @P_SEC_EJC and
	                                centro_costo in (select centro_costo from sig_centro_costo where ano_eje = @P_ANO_EJE and sec_ejec = @P_SEC_EJC and estado ='A' ) and
	                     estado in ('9','A');

	     IF @LD_CUENTA_FASE_PROG_4 IS NULL SET @LD_CUENTA_FASE_PROG_4 = 0
	     
	     IF @LD_CUENTA_FASE_REQ = 0 and @LD_CUENTA_FASE_PROG_2 = 0 and @LD_CUENTA_FASE_PROG_3 = 0 and @LD_CUENTA_FASE_PROG_4 = 0 
	      SET @O_FASE_CUADRO = 1
	     ELSE IF @LD_CUENTA_FASE_REQ > 0 and @LD_CUENTA_FASE_PROG_2 = 0 and @LD_CUENTA_FASE_PROG_3 = 0 and @LD_CUENTA_FASE_PROG_4 = 0 
	      SET @O_FASE_CUADRO = 1
	     ELSE IF @LD_CUENTA_FASE_REQ = 0 and @LD_CUENTA_FASE_PROG_2 > 0 and @LD_CUENTA_FASE_PROG_3 = 0 and @LD_CUENTA_FASE_PROG_4 = 0 
	      SET @O_FASE_CUADRO = 2
	     ELSE IF @LD_CUENTA_FASE_REQ = 0 and @LD_CUENTA_FASE_PROG_2 = 0 and @LD_CUENTA_FASE_PROG_3 > 0 and @LD_CUENTA_FASE_PROG_4 = 0 
	      SET @O_FASE_CUADRO = 3
	     ELSE IF @LD_CUENTA_FASE_REQ = 0 and @LD_CUENTA_FASE_PROG_2 = 0 and @LD_CUENTA_FASE_PROG_3 = 0 and @LD_CUENTA_FASE_PROG_4 > 0 
	      SET @O_FASE_CUADRO = 4
	     ELSE SET @O_FASE_CUADRO  = -1
     END
  ELSE
    select @O_FASE_CUADRO = valor from sig_parametro_ejecutora_anio 
       WHERE ano_eje  = @P_ANO_EJE
       AND cod_maestro  = 'FLAG_SUBFASE_INT'
;--/
GO


-- ----------------------------
-- procedure structure for SP_CARGA_KARDEX_MENSUAL_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_KARDEX_MENSUAL_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_KARDEX_MENSUAL_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_KARDEX_MENSUAL_TRX]
     @P_ANO_EJE            NUMERIC(4,0),
     @P_SEC_EJEC           NUMERIC(6,0),  
     @O_ERR_NUM            NUMERIC(6,0) OUTPUT,
     @O_ERR_MSG            VARCHAR(255) OUTPUT
AS   
BEGIN
     Declare   @LN_MES_PROCESO   NUMERIC(2,0)
     Declare   @LS_TIPO_BIEN     VARCHAR(1)
     Declare    @LS_CLASIFICADOR  VARCHAR(20)
     Declare    @LS_MAYOR         VARCHAR(4)       
     Declare    @LS_SUB_CTA       VARCHAR(8)
     Declare    @LN_TIPO_PPTO      NUMERIC(1,0) 
     Declare    @LN_SEC_EJEC2     NUMERIC(6,0)
     Declare    @LS_SECTOR        VARCHAR(2)
     Declare    @LS_PLIEGO        VARCHAR(3)
     Declare    @LN_TIPO_ENTIDAD  NUMERIC(2,0)
     Declare    @LS_GRUPO_BIEN    VARCHAR(2)
     Declare    @LS_CLASE_BIEN    VARCHAR(2)
     Declare    @LS_FAMILIA_BIEN  VARCHAR(4)
     Declare    @LS_ITEM_BIEN     VARCHAR(4)
     Declare    @LN_STOCK_INICIAL NUMERIC(20,6)
     Declare    @LN_CANT_INGRESO  NUMERIC(20,6)
     Declare    @LN_CANT_EGRESO    NUMERIC(20,6)
     Declare    @LN_STOCK_ACTUAL  NUMERIC(20,6) 
     Declare    @LN_PRECIO_PROMED NUMERIC(16,6)
     Declare    @LN_SALDO_INICIAL NUMERIC(18,4)
     Declare    @LN_VALOR_INGRESO NUMERIC(16,2)
     Declare    @LN_VALOR_EGRESO  NUMERIC(16,2)   
     Declare    @LN_SALDO_VALOR    NUMERIC(18,4) 
     Declare    @LD_FECHA_REG     DATETIME 
     Declare    @LS_CUSER_ID      VARCHAR(30)
     Declare    @LN_UNIDAD_MEDIDA NUMERIC(3,0)
     Declare    @LS_departamento  VARCHAR(2)
     Declare    @LS_provincia     VARCHAR(2)
     Declare    @LL_SECUENCIA     NUMERIC(6)
     Declare    @LS_CATEGORIA      VARCHAR(3)
     Declare    @LS_GRUPO          VARCHAR(3)
     Declare    @LS_MODALIDAD      VARCHAR(5)
     Declare    @LS_ELEMENTO_GASTO VARCHAR(5)    
     /*Declare    @LL_INICIO NUMERIC*/
     Declare    @LL_INICIO bigint
     Declare    @LL_LONG   NUMERIC 



    DELETE FROM SGE_KARDEX_MENSUAL_TRX
    
    SELECT @LL_SECUENCIA = MAX(SECUENCIA)
        FROM SGE_KARDEX_MENSUAL_TRX
     WHERE ANO_EJE  = @P_ANO_EJE  AND
           SEC_EJEC = @P_SEC_EJEC 
     
   	IF @LL_SECUENCIA IS NULL   
		SET @LL_SECUENCIA = 0      
		
    DECLARE C1 CURSOR FOR
            SELECT
                A.MES_PROCESO,
                A.TIPO_BIEN,
                (SELECT MAX(Z.CLASIFICADOR) 
                 FROM SIG_FAMILIA_CUENTA_EJECUTORA Z
                 WHERE  Z.ANO_EJE         = A.ANO_EJE
                    AND Z.SEC_EJEC        = A.SEC_EJEC
                    AND Z.GRUPO_BIEN    = A.GRUPO_BIEN
                    AND Z.CLASE_BIEN    = A.CLASE_BIEN
                    AND Z.FAMILIA_BIEN    = A.FAMILIA_BIEN
                    AND Z.TIPO_BIEN     = A.TIPO_BIEN
                    AND Z.MAYOR            = A.MAYOR
                    AND Z.SUB_CTA        = A.SUB_CTA
                    AND Z.TIPO_USO        = A.TIPO_USO
                ) CLASIFICADOR,
                A.MAYOR,
                A.SUB_CTA,
                A.TIPO_PPTO,
                A.SEC_EJEC2,
                B.SECTOR,
                B.PLIEGO,
                C.TIPO_ENTIDAD,
                A.GRUPO_BIEN,
                A.CLASE_BIEN,
                A.FAMILIA_BIEN,
                A.ITEM_BIEN,
                A.STOCK_INICIAL,
                A.CANT_INGRESO,
                A.CANT_EGRESO,
                A.STOCK_ACTUAL,
                A.PRECIO_PROMED,
                A.SALDO_INICIAL,
                A.VALOR_INGRESO,
                A.VALOR_EGRESO,
                A.SALDO_VALOR,
                A.FECHA_REG,
                A.CUSER_ID,
                A.UNIDAD_MEDIDA,
                C.departamento,
                C.provincia
            FROM SIG_KARDEX_POR_ALMACEN A
            JOIN SIG_EJECUTORA B
                ON  B.sec_ejec = A.SEC_EJEC
                AND B.estado='A'
            JOIN EJECUTORA C
                ON  C.sec_ejec = B.sec_ejec
            WHERE 
                A.SEC_EJEC = @P_SEC_EJEC AND 
                A.ANO_EJE  = @P_ANO_EJE 
      OPEN C1
		
	  FETCH NEXT FROM C1
	  INTO        
         @LN_MES_PROCESO,	@LS_TIPO_BIEN,	@LS_CLASIFICADOR,	@LS_MAYOR,		@LS_SUB_CTA,
         @LN_TIPO_PPTO,		@LN_SEC_EJEC2,  @LS_SECTOR,			@LS_PLIEGO,		@LN_TIPO_ENTIDAD,
         @LS_GRUPO_BIEN,	@LS_CLASE_BIEN, @LS_FAMILIA_BIEN,   @LS_ITEM_BIEN,  @LN_STOCK_INICIAL, 
         @LN_CANT_INGRESO,  @LN_CANT_EGRESO,@LN_STOCK_ACTUAL ,  @LN_PRECIO_PROMED,@LN_SALDO_INICIAL,
         @LN_VALOR_INGRESO, @LN_VALOR_EGRESO,@LN_SALDO_VALOR,   @LD_FECHA_REG,   @LS_CUSER_ID,
         @LN_UNIDAD_MEDIDA, @LS_departamento, @LS_provincia
           
        WHILE @@FETCH_STATUS = 0
        BEGIN 
           
	
        SET  @LL_INICIO = 0    
        SET  @LL_LONG = 0  

        SET @LL_SECUENCIA = @LL_SECUENCIA + 1       
        SET @LS_CATEGORIA =  SUBSTRING(@LS_CLASIFICADOR, 1  , (CHARINDEX('.',@LS_CLASIFICADOR ,  1) -1))
       
        SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 
	    SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1)) - (CHARINDEX('.' ,@LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 )  
	    SET @LS_GRUPO  = SUBSTRING( @LS_CLASIFICADOR, @LL_INICIO, @LL_LONG)
	   
	    SET @LL_INICIO = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1
	    SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) - (CHARINDEX('.' ,@LS_CLASIFICADOR, (charindex('.',@LS_CLASIFICADOR) + 1) )   + 1)
	    SET @LS_MODALIDAD = SUBSTRING( @LS_CLASIFICADOR,@LL_INICIO, @LL_LONG )

	    SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) +1
	    SET @LL_LONG = LEN(@LS_CLASIFICADOR) -  charindex('.' ,@LS_CLASIFICADOR, (charindex('.' ,@LS_CLASIFICADOR, (charindex('.',@LS_CLASIFICADOR) + 1) ) + 1)  ) 
	    SET @LS_ELEMENTO_GASTO =	 SUBSTRING(@LS_CLASIFICADOR, @LL_INICIO, @LL_LONG )                         
                
        INSERT INTO SGE_KARDEX_MENSUAL_TRX
        (   ANO_EJE,          SEC_EJEC,            MES_PROCESO,     TIPO_BIEN,        CLASIFICADOR,
            MAYOR,            SUB_CTA,             TIPO_PPTO,       SECUENCIA,        SEC_EJEC2,
            SECTOR,           PLIEGO,              TIPO_ENTIDAD,    GRUPO_BIEN,       CLASE_BIEN,
            FAMILIA_BIEN,     ITEM_BIEN,           STOCK_INICIAL,   CANT_INGRESO,     CANT_EGRESO,
            STOCK_ACTUAL,     PRECIO_PROMED,       SALDO_INICIAL,   VALOR_INGRESO,    VALOR_EGRESO,
            SALDO_VALOR,      FECHA_REG,           CUSER_ID,        UNIDAD_MEDIDA,    DEPARTAMENTO,     
            PROVINCIA,        CATEGORIA_GASTO,     GRUPO ,          MODALIDAD,        ELEMENTO_GASTO )
        VALUES
        (   @P_ANO_EJE,        @P_SEC_EJEC,          @LN_MES_PROCESO,  @LS_TIPO_BIEN ,    COALESCE(@LS_CLASIFICADOR, '0'),
            @LS_MAYOR,         @LS_SUB_CTA,          @LN_TIPO_PPTO,    @LL_SECUENCIA,     @LN_SEC_EJEC2, 
            @LS_SECTOR,        @LS_PLIEGO,           @LN_TIPO_ENTIDAD, @LS_GRUPO_BIEN,    @LS_CLASE_BIEN,
            @LS_FAMILIA_BIEN,  @LS_ITEM_BIEN,        @LN_STOCK_INICIAL,@LN_CANT_INGRESO,  @LN_CANT_EGRESO,
            @LN_STOCK_ACTUAL,  @LN_PRECIO_PROMED,    @LN_SALDO_INICIAL,@LN_VALOR_INGRESO, @LN_VALOR_EGRESO,
            @LN_SALDO_VALOR,   @LD_FECHA_REG,        @LS_CUSER_ID,     @LN_UNIDAD_MEDIDA, @LS_departamento,  
            @LS_provincia,     @LS_CATEGORIA,        @LS_GRUPO,        @LS_MODALIDAD,     @LS_ELEMENTO_GASTO  )                
    
 	FETCH NEXT FROM C1
	  INTO        
         @LN_MES_PROCESO,	@LS_TIPO_BIEN,	@LS_CLASIFICADOR,	@LS_MAYOR,		@LS_SUB_CTA,
         @LN_TIPO_PPTO,		@LN_SEC_EJEC2,  @LS_SECTOR,			@LS_PLIEGO,		@LN_TIPO_ENTIDAD,
         @LS_GRUPO_BIEN,	@LS_CLASE_BIEN, @LS_FAMILIA_BIEN,   @LS_ITEM_BIEN,  @LN_STOCK_INICIAL, 
         @LN_CANT_INGRESO,  @LN_CANT_EGRESO,@LN_STOCK_ACTUAL ,  @LN_PRECIO_PROMED,@LN_SALDO_INICIAL,
         @LN_VALOR_INGRESO, @LN_VALOR_EGRESO,@LN_SALDO_VALOR,   @LD_FECHA_REG,   @LS_CUSER_ID,
         @LN_UNIDAD_MEDIDA, @LS_departamento, @LS_provincia
                     
     END             
     CLOSE C1
     DEALLOCATE C1
    
     UPDATE SGE_KARDEX_MENSUAL_TRX
           SET SGE_KARDEX_MENSUAL_TRX.SECTOR = (SELECT B.SECTOR FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_KARDEX_MENSUAL_TRX.SEC_EJEC),
              SGE_KARDEX_MENSUAL_TRX.PLIEGO = (SELECT B.PLIEGO FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_KARDEX_MENSUAL_TRX.SEC_EJEC)
       WHERE 
               SGE_KARDEX_MENSUAL_TRX.ANO_EJE  = @P_ANO_EJE  AND
              SGE_KARDEX_MENSUAL_TRX.SEC_EJEC = @P_SEC_EJEC
               
    IF @@ERROR <> 0
       	 BEGIN
		 SET @O_ERR_MSG='Ocurrió error en la actualización de SGE_KARDEX_MENSUAL_TRX'
		 return -1
	END   
  
END
GO


-- ----------------------------
-- procedure structure for SP_SIG_MP_DET_MOVIM_X_ANO
-- ----------------------------
