-- ----------------------------
-- procedure structure for sp_catalogo_bien_servicios
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_catalogo_bien_servicios]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[sp_catalogo_bien_servicios]
GO

CREATE PROCEDURE [dbo].[sp_catalogo_bien_servicios]
(
    @_parametro NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @tipo_bien VARCHAR(1);

    SELECT 
        @tipo_bien = JSON_VALUE(@_parametro,'$.tipo_bien');

    SELECT 
    JSON_QUERY(
    (
        SELECT 
            CAST(CATALOGO_BIEN_SERV.TIPO_BIEN AS VARCHAR(1))  AS tipo_bien,
            CAST(CATALOGO_BIEN_SERV.GRUPO_BIEN AS VARCHAR(2)) AS grupo_bien,
            CAST(GRUPO_BIEN_SERV.NOMBRE_GRUPO AS VARCHAR(600)) AS nombre_grupo,
            CAST(CATALOGO_BIEN_SERV.CLASE_BIEN AS VARCHAR(2)) AS clase_bien,
            CAST(CLASE_BIEN_SERV.NOMBRE_CLASE AS VARCHAR(600)) AS nombre_clase,
            CAST(CATALOGO_BIEN_SERV.FAMILIA_BIEN AS VARCHAR(4)) AS familia_bien,
            CAST(FAMILIA_BIEN_SERV.NOMBRE_FAM AS VARCHAR(600)) AS nombre_familia,
            CAST(CATALOGO_BIEN_SERV.NOMBRE_ITEM AS VARCHAR(600)) AS nombre_item

        FROM CATALOGO_BIEN_SERV 
        LEFT JOIN GRUPO_BIEN_SERV 
            ON GRUPO_BIEN_SERV.tipo_bien = CATALOGO_BIEN_SERV.tipo_bien
            AND GRUPO_BIEN_SERV.grupo_bien = CATALOGO_BIEN_SERV.grupo_bien

        LEFT JOIN CLASE_BIEN_SERV
            ON CLASE_BIEN_SERV.tipo_bien = CATALOGO_BIEN_SERV.tipo_bien
            AND CLASE_BIEN_SERV.grupo_bien = CATALOGO_BIEN_SERV.grupo_bien
            AND CLASE_BIEN_SERV.clase_bien = CATALOGO_BIEN_SERV.clase_bien

        LEFT JOIN FAMILIA_BIEN_SERV 
            ON FAMILIA_BIEN_SERV.tipo_bien = CATALOGO_BIEN_SERV.tipo_bien
            AND FAMILIA_BIEN_SERV.grupo_bien = CATALOGO_BIEN_SERV.grupo_bien
            AND FAMILIA_BIEN_SERV.clase_bien = CATALOGO_BIEN_SERV.clase_bien
            AND FAMILIA_BIEN_SERV.familia_bien = CATALOGO_BIEN_SERV.familia_bien

        WHERE 
            CATALOGO_BIEN_SERV.ESTADO_MEF = 'A'
            AND (@tipo_bien IS NULL 
                 OR CATALOGO_BIEN_SERV.TIPO_BIEN = @tipo_bien)

        FOR JSON PATH
    )) AS data;

END
GO


-- ----------------------------
-- procedure structure for MIGRA_CN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[MIGRA_CN]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[MIGRA_CN]
GO

CREATE PROCEDURE [dbo].[MIGRA_CN]
(@ano_eje int, @sec_ejec int)
as
 
declare @cc varchar(15), @tipo_tarea varchar(1), @nivel_tarea varchar(1),
        @codigo_tarea int, @ff varchar(2), @meta int
declare @cc_ant varchar(15), @tipo_tarea_ant varchar(1), @nivel_tarea_ant varchar(1),
        @codigo_tarea_ant int
declare @num int
declare @n int, @cant_total numeric(14,2)
declare @tano_eje numeric(4), @tsec_ejec numeric(6), @torigen varchar(1), @tfuente_financ varchar(2), @tclasificador varchar(15), @tsec_func numeric(4), @tcentro_costo varchar(15), @tindicador int
 
set nocount on
 
