CREATE TABLE #tp (
 ano_eje numeric(4, 0) NOT NULL ,
 sec_ejec numeric(6, 0) NOT NULL ,
 origen varchar (1) COLLATE Modern_Spanish_CI_AS NOT NULL ,
 fuente_financ varchar (2) COLLATE Modern_Spanish_CI_AS NOT NULL ,
 categ_gasto varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 grupo_gasto varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 clasificador varchar (14) COLLATE Modern_Spanish_CI_AS NULL ,
 funcion varchar (2) COLLATE Modern_Spanish_CI_AS NULL ,
 programa varchar (3) COLLATE Modern_Spanish_CI_AS NULL ,
 sec_func numeric(4, 0) NULL ,
 centro_costo varchar (15) COLLATE Modern_Spanish_CI_AS NULL ,
 porc_techo numeric(38, 2) NULL ,
 ppto_progra numeric(38, 2) NULL ,
 ppto_aprob numeric(38, 2) NULL ,
 ppto_asignado numeric(38, 2) NULL ,
 ppto_modif numeric(38, 2) NULL ,
 mnto_progra numeric(38, 2) NULL ,
 mnto_asig numeric(38, 2) NULL ,
 mnto_aprob numeric(38, 2) NULL ,
 mnto_modif numeric(38, 2) NULL ,
 indicador varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 paac_inicial numeric(38, 2) NULL ,
 paac_modif numeric(38, 2) NULL ,
 porc_asig numeric(6, 2) NULL ,
 CUADRE_PPTO_PROGRA varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 CUADRE_PPTO_MODIF varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 CUADRE_PPTO_APROB varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 CUADRE_PPTO_ASIGNA varchar (1) COLLATE Modern_Spanish_CI_AS NULL ,
 PPTO_RESER numeric(38, 2) NULL ,
 EJEC_01 numeric(38, 2) NULL ,
 EJEC_02 numeric(38, 2) NULL ,
 EJEC_03 numeric(38, 2) NULL ,
 EJEC_04 numeric(38, 2) NULL ,
 EJEC_05 numeric(38, 2) NULL ,
 EJEC_06 numeric(38, 2) NULL ,
 EJEC_07 numeric(38, 2) NULL ,
 EJEC_08 numeric(38, 2) NULL ,
 EJEC_09 numeric(38, 2) NULL ,
 EJEC_10 numeric(38, 2) NULL ,
 EJEC_11 numeric(38, 2) NULL ,
 EJEC_12 numeric(38, 2) NULL ,
 PPTO_CONTAB numeric(38, 2) NULL ,
 PPTO_PIA numeric(38, 2) NULL ,
 PPTO_CPIA numeric(38, 2) NULL ,
 PRE_EJEC_01 numeric(38, 2) NULL ,
 PRE_EJEC_02 numeric(38, 2) NULL ,
 PRE_EJEC_03 numeric(38, 2) NULL ,
 PRE_EJEC_04 numeric(38, 2) NULL ,
 PRE_EJEC_05 numeric(38, 2) NULL ,
 PRE_EJEC_06 numeric(38, 2) NULL ,
 PRE_EJEC_07 numeric(38, 2) NULL ,
 PRE_EJEC_08 numeric(38, 2) NULL ,
 PRE_EJEC_09 numeric(38, 2) NULL ,
 PRE_EJEC_10 numeric(38, 2) NULL ,
 PRE_EJEC_11 numeric(38, 2) NULL ,
 PRE_EJEC_12 numeric(38, 2) NULL ,
 PAAC_AUTORIZADO numeric(38, 2) NULL ,
 PPTO_RESER2 numeric(38, 2) NULL ,
 secuencia int identity NOT NULL 
)
 
