if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 1) > 0
begin
   select * into dbo.tmp_sig_metas_x_centro
   from sig_metas_x_centro 
   where ano_eje = @ano_eje and sec_ejec = @sec_ejec
 
   delete sig_metas_x_centro where ano_eje = @ano_eje and sec_ejec = @sec_ejec
end
 
if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 2) > 0
begin
   select * into dbo.tmp_sig_cuadro_anual
   from sig_cuadro_anual
   where ano_eje = @ano_eje and sec_ejec = @sec_ejec 
 
   select * into dbo.tmp_sig_detalle_cuadro_anual
   from sig_detalle_cuadro_anual
   where ano_eje = @ano_eje and sec_ejec = @sec_ejec
 
   delete sig_detalle_cuadro_anual where ano_eje = @ano_eje and sec_ejec = @sec_ejec
   delete sig_cuadro_anual where ano_eje = @ano_eje and sec_ejec = @sec_ejec
end
 
if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 3) > 0
begin
   select * into dbo.tmp_sig_techo_presupuestal 
   from sig_techo_presupuestal 
   where ano_eje = @ano_eje and sec_ejec = @sec_ejec
 
   delete sig_techo_presupuestal where ano_eje = @ano_eje and sec_ejec = @sec_ejec
end
 
update meta set funcion = b.funcion, programa = b.programa, sub_programa = b.sub_programa, act_proy = b.act_proy, componente = b.componente, meta = b.meta, finalidad = b.finalidad, nombre = b.nombre
from meta a join (select * from sig_tmp_equivalencia_meta where ind_meta = 1) b on
     a.ano_eje = b.ano_eje and a.sec_ejec = b.sec_ejec and a.sec_func = b.sec_func
where a.ano_eje = @ano_eje and a.sec_ejec = @sec_ejec
 
insert into meta
(ano_eje, sec_ejec, sec_func, funcion, programa, sub_programa, act_proy, componente, meta, finalidad, nombre, monto, cantidad, unidad_med, fecha_ing, usuario_ing, fecha_mod, usuario_mod, estado, estado_envio, archivo, pais, departamento, provincia, distrito, unidad_medida)
select b.ano_eje, b.sec_ejec, b.sec_func, b.funcion, b.programa, b.sub_programa, b.act_proy, b.componente, b.meta, b.finalidad, b.nombre, b.monto, b.cantidad, b.unidad_med, b.fecha_ing, b.usuario_ing, b.fecha_mod, b.usuario_mod, b.estado, b.estado_envio, b.archivo, b.pais, b.departamento, b.provincia, b.distrito, b.unidad_medida
from (select * from meta where ano_eje = @ano_eje and sec_ejec = @sec_ejec) a right join (select * from sig_tmp_equivalencia_meta where ind_meta = 1 and ano_eje = @ano_eje and sec_ejec = @sec_ejec) b on
     a.ano_eje = b.ano_eje and a.sec_ejec = b.sec_ejec and a.sec_func = b.sec_func
where a.ano_eje is null
 
delete sig_meta_prop where ano_eje = @ano_eje and sec_ejec = @sec_ejec
 

