INSERT INTO sig_meta_prop  
( ano_eje,sec_ejec,sec_func,sec_func_r, funcion,programa,sub_programa,act_proy,   
           componente,meta,finalidad,nombre, monto,cantidad,unidad_medida,pais,   
           departamento,provincia,distrito, estado,porc_meta,flag_act_proy )  
SELECT ano_eje,sec_ejec,sec_func,sec_func, funcion,programa,sub_programa,act_proy,   
            componente,meta,finalidad,nombre, monto,cantidad,unidad_med,pais,   
            departamento,provincia,distrito,estado, 0,substring(act_proy,1,1)
FROM meta
where not exists (Select * 
                  from sig_meta_prop 
    where ano_eje = meta.ano_eje and sec_ejec = meta.sec_ejec and
   sec_func = meta.sec_func )
 
