if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 1) > 0
begin
   select a.ano_eje, a.sec_ejec, a.centro_costo, 0 secuencia, b.SEC_FUNC_R sec_func, a.origen, a.fuente_financ, a.tipo_recurso, max(a.porc_gfijos) porc_gfijos, max(a.porc_techo) porc_techo, max(a.cuser_id) cuser_id, max(a.fecha_reg) fecha_reg
   into #tmc
   from tmp_sig_metas_x_centro a join (select * from sig_tmp_equivalencia_meta where ind_meta = 0) b on a.ano_eje = b.ano_eje and a.sec_ejec = b.sec_ejec and a.sec_func = b.sec_func
   where a.ano_eje = @ano_eje and a.sec_ejec = @sec_ejec
   group by a.ano_eje, a.sec_ejec, a.centro_costo, b.SEC_FUNC_R, a.origen, a.fuente_financ, a.tipo_recurso
 
   ---------------------------
 
   declare @centro_costo varchar(15), @centro_costo_ant varchar(15)
   declare @sec_func int, @fuente_financ varchar(2)
 
   declare cur_tmc cursor for
   select centro_costo, sec_func, fuente_financ
   from #tmc
   order by 1
 
   open cur_tmc
   fetch cur_tmc into @centro_costo, @sec_func, @fuente_financ
 
   while @@fetch_status = 0
   begin
      set @n = 1 
      select @centro_costo_ant = @centro_costo
      while @centro_costo_ant = @centro_costo and @@fetch_status = 0
      begin
         update #tmc set secuencia = @n where centro_costo = @centro_costo and sec_func = @sec_func and fuente_financ = @fuente_financ
         fetch cur_tmc into @centro_costo, @sec_func, @fuente_financ
         select @n = @n + 1
      end
   end
   close cur_tmc
   deallocate cur_tmc
 
   insert into sig_metas_x_centro
   select * from #tmc
 
   update sig_tmp_migracion_metas set nreg_proc = @@rowcount where secuencial = 1
 
   drop table #tmc
end
 
--------------------------------------
 
if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 2) > 0
begin
   select a.sec_ejec, a.centro_costo, a.ano_eje, a.tipo_tarea, a.nivel_tarea, a.codigo_tarea, c.SEC_FUNC_R, a.origen, a.fuente_financ, a.tipo_recurso, a.tipo_impuesto, a.fuente_impto, b.fase_cuadro, b.tipo_bien, b.grupo_bien, b.clase_bien, b.familia_bien, b.item_bien, b.clasificador, b.unidad_medida, b.precio_unit, cant_01, cant_02, cant_03, cant_04, cant_05, cant_06, cant_07, cant_08, cant_09, cant_10, cant_11, cant_12, cant_total, mnto_01, mnto_02, mnto_03, mnto_04, mnto_05, mnto_06, mnto_07, mnto_08, mnto_09, mnto_10, mnto_11, mnto_12, mnto_total, stock_asig, valor_stock, tipo_impto, b.tasa_impto, b.fte_impto, b.valor_impto, b.estado, b.cant_hist, b.mnto_hist, b.flag_gasto, b.flag_modif, 0 sec, 0 sec_item, item_sec
   into #tcn
   from tmp_sig_cuadro_anual a join tmp_sig_detalle_cuadro_anual b on
        a.sec_ejec = b.sec_ejec and a.centro_costo = b.centro_costo and 
        a.ano_eje = b.ano_eje and a.tipo_tarea = b.tipo_tarea and 
        a.nivel_tarea = b.nivel_tarea and a.codigo_tarea = b.codigo_tarea and 
        a.secuencia = b.secuencia
        join (select * from sig_tmp_equivalencia_meta where ind_meta = 0) c on a.ano_eje = c.ano_eje and a.sec_ejec = c.sec_ejec and a.sec_func = c.sec_func
   where a.ano_eje = @ano_eje and a.sec_ejec = @sec_ejec
 
   --------------------
 
   declare c_sec cursor for
       select  CENTRO_COSTO, tipo_tarea, nivel_tarea, codigo_tarea, fuente_financ, SEC_FUNC_R 
       from #tcn
       group by CENTRO_COSTO, tipo_tarea, nivel_tarea, codigo_tarea, fuente_financ, SEC_FUNC_R
       order by CENTRO_COSTO, tipo_tarea, nivel_tarea, codigo_tarea, SEC_FUNC_R, fuente_financ
 
       open c_sec
       fetch next from c_sec into @cc, @tipo_tarea, @nivel_tarea, @codigo_tarea, @ff, @meta
       while (@@FETCH_STATUS=0)
       begin
          SELECT @cc_ant = @cc, @tipo_tarea_ant = @tipo_tarea, @nivel_tarea_ant = @nivel_tarea,
                  @codigo_tarea_ant = @codigo_tarea 
          select @num = 1
 
          while @cc_ant = @cc and @tipo_tarea_ant = @tipo_tarea and @nivel_tarea_ant = @nivel_tarea and @codigo_tarea_ant = @codigo_tarea and (@@FETCH_STATUS=0)
          begin 
              UPDATE #tcn
                SET SEC = @num 
                WHERE CENTRO_COSTO = @cc
                and tipo_tarea = @tipo_tarea
                and nivel_tarea = @nivel_tarea
                and codigo_tarea = @codigo_tarea
                and fuente_financ = @ff
                and SEC_FUNC_R = @meta
 
                select @num = @num + 1  
             fetch next from c_sec into @cc, @tipo_tarea, @nivel_tarea, @codigo_tarea, @ff, @meta
         end
       end
   close c_sec
   deallocate c_sec
 
   -------------------------- 
 
   declare @nums int
 
   select @nums = 1, @num = 1

   declare @tipo_bien varchar(1), @grupo_bien varchar(2), @clase_bien varchar(2),
           @familia_bien varchar(4), @item_bien varchar(4), @clasificador varchar(14), 
           @sec int, @sec_ant int, @flag_modif char(1), @item_sec numeric(18,6)
 
   declare c_sec_item cursor for
       SELECT CENTRO_COSTO, tipo_tarea, nivel_tarea, codigo_tarea, sec, tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, clasificador, flag_modif, item_sec
       FROM #tcn
       ORDER BY tipo_bien desc, CENTRO_COSTO, tipo_tarea, nivel_tarea, codigo_tarea, sec, grupo_bien, clase_bien, familia_bien, item_bien
 
       open c_sec_item
       fetch next from c_sec_item into @cc, @tipo_tarea, @nivel_tarea, @codigo_tarea, @sec, @tipo_bien, @grupo_bien, @clase_bien, @familia_bien, @item_bien, @clasificador, @flag_modif, @item_sec
       while (@@FETCH_STATUS=0)
       begin
           SELECT @cc_ant = @cc, @sec_ant = @sec, @tipo_tarea_ant = @tipo_tarea,
                  @nivel_tarea_ant = @nivel_tarea, @codigo_tarea_ant = @codigo_tarea
           select @num = @nums
 
       while ((@cc_ant = @cc and @sec_ant = @sec and @tipo_tarea_ant = @tipo_tarea and @nivel_tarea_ant = @nivel_tarea and @codigo_tarea_ant = @codigo_tarea) or (@tipo_bien = 'S')) and @@FETCH_STATUS=0
       begin 
              UPDATE #tcn
                SET SEC_item = @num 
                WHERE CENTRO_COSTO = @cc
                and sec = @sec
                and tipo_tarea = @tipo_tarea
                and nivel_tarea = @nivel_tarea
                and codigo_tarea = @codigo_tarea
                and tipo_bien = @tipo_bien
                and grupo_bien = @grupo_bien
                and clase_bien = @clase_bien
                and familia_bien = @familia_bien 
                and item_bien = @item_bien
                and clasificador = @clasificador
                and flag_modif = @flag_modif
                and ((item_sec = @item_sec and @tipo_bien = 'S') or (@tipo_bien = 'B'))
        
                 select @num = @num + 1  
                if @tipo_bien = 'S'
                   select @nums = @nums + 1
                fetch next from c_sec_item into @cc, @tipo_tarea, @nivel_tarea, @codigo_tarea, @sec, @tipo_bien, @grupo_bien, @clase_bien, @familia_bien, @item_bien, @clasificador, @flag_modif, @item_sec
     end
       end
   close c_sec_item
   deallocate c_sec_item
 
   ------------------------------------------
 
   insert into sig_cuadro_anual
   (sec_ejec, centro_costo, ano_eje, tipo_tarea, nivel_tarea, codigo_tarea, secuencia,
    sec_func, origen, fuente_financ, flag_gasto, tipo_recurso, tipo_impuesto, fuente_impto)
   select distinct sec_ejec, centro_costo, ano_eje, tipo_tarea, nivel_tarea, codigo_tarea, sec, 
          SEC_FUNC_R, origen, fuente_financ, flag_gasto, tipo_recurso, tipo_impuesto, fuente_impto
   from #tcn
 
   insert into sig_detalle_cuadro_anual
   (sec_ejec, centro_costo, ano_eje, tipo_tarea, nivel_tarea, codigo_tarea, secuencia, 
    fase_cuadro, item_sec, tipo_bien, grupo_bien, clase_bien, familia_bien, 
    item_bien, categ_gasto, grupo_gasto, clasificador, unidad_medida, precio_unit, cant_01, 
    cant_02, cant_03, cant_04, cant_05, cant_06, cant_07, cant_08, cant_09, cant_10, cant_11, 
    cant_12, cant_total, mnto_01, mnto_02, mnto_03, mnto_04, mnto_05, mnto_06, mnto_07, mnto_08, 
    mnto_09, mnto_10, mnto_11, mnto_12, mnto_total, stock_asig, valor_stock, tipo_impto, 
    tasa_impto, fte_impto, valor_impto, estado, cant_hist, mnto_hist, flag_gasto, flag_modif)
   select sec_ejec, centro_costo, ano_eje, tipo_tarea, nivel_tarea, codigo_tarea, sec, 
          fase_cuadro, sec_item, tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien,
          left(clasificador,1), substring(clasificador,2,1), clasificador, unidad_medida, 
          precio_unit, sum(cant_01), sum(cant_02), sum(cant_03), sum(cant_04), sum(cant_05), 
          sum(cant_06), sum(cant_07), sum(cant_08), sum(cant_09), sum(cant_10), sum(cant_11), 
          sum(cant_12), sum(cant_total), sum(mnto_01), sum(mnto_02), sum(mnto_03), sum(mnto_04), 
          sum(mnto_05), sum(mnto_06), sum(mnto_07), sum(mnto_08), sum(mnto_09), sum(mnto_10), 
          sum(mnto_11), sum(mnto_12), sum(mnto_total), sum(stock_asig), sum(valor_stock), 
          tipo_impto, tasa_impto, fte_impto, valor_impto, estado, sum(cant_hist), sum(mnto_hist), 
          flag_gasto, flag_modif
   from #tcn
   group by sec_ejec, centro_costo, ano_eje, tipo_tarea, nivel_tarea, codigo_tarea, sec, 
          fase_cuadro, sec_item, tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien,
          left(clasificador,1), substring(clasificador,2,1), clasificador, unidad_medida, 
          precio_unit, tipo_impto, tasa_impto, fte_impto, valor_impto, estado, flag_gasto, 
          flag_modif
 
   update sig_tmp_migracion_metas set nreg_proc = @@rowcount where secuencial = 2
 
   drop table #tcn
end
 
----- techo
 
if (select secuencial from sig_tmp_migracion_metas where ano_eje = @ano_eje and sec_ejec = @sec_ejec and secuencial = 3) > 0
begin
 
   insert into #tp
   select a.ano_eje, a.sec_ejec, a.origen, a.fuente_financ, a.categ_gasto, a.grupo_gasto, a.clasificador, max(case when a.funcion is not null then m.funcion else a.funcion end) funcion, max(case when a.programa is not null then m.programa else a.programa end) programa, c.SEC_FUNC_R, a.centro_costo, sum(porc_techo) porc_techo, sum(ppto_progra) ppto_progra, sum(ppto_aprob) ppto_aprob, sum(ppto_asignado) ppto_asignado, sum(ppto_modif) ppto_modif, sum(mnto_progra) mnto_progra, sum(mnto_asig) mnto_asig, sum(mnto_aprob) mnto_aprob, sum(mnto_modif) mnto_modif, a.indicador, sum(paac_inicial) paac_inicial, sum(paac_modif) paac_modif, max(porc_asig) porc_asig, max(CUADRE_PPTO_PROGRA) CUADRE_PPTO_PROGRA, max(CUADRE_PPTO_MODIF) CUADRE_PPTO_MODIF, max(CUADRE_PPTO_APROB) CUADRE_PPTO_APROB, max(CUADRE_PPTO_ASIGNA) CUADRE_PPTO_ASIGNA, sum(PPTO_RESER) PPTO_RESER, sum(EJEC_01) EJEC_01, sum(EJEC_02) EJEC_02, sum(EJEC_03) EJEC_03, sum(EJEC_04) EJEC_04, sum(EJEC_05) EJEC_05, sum(EJEC_06) EJEC_06, sum(EJEC_07) EJEC_07, sum(EJEC_08) EJEC_08, sum(EJEC_09) EJEC_09, sum(EJEC_10) EJEC_10, sum(EJEC_11) EJEC_11, sum(EJEC_12) EJEC_12, sum(PPTO_CONTAB) PPTO_CONTAB, sum(PPTO_PIA) PPTO_PIA, sum(PPTO_CPIA) PPTO_CPIA, sum(PRE_EJEC_01) PRE_EJEC_01, sum(PRE_EJEC_02) PRE_EJEC_02, sum(PRE_EJEC_03) PRE_EJEC_03, sum(PRE_EJEC_04) PRE_EJEC_04, sum(PRE_EJEC_05) PRE_EJEC_05, sum(PRE_EJEC_06) PRE_EJEC_06, sum(PRE_EJEC_07) PRE_EJEC_07, sum(PRE_EJEC_08) PRE_EJEC_08, sum(PRE_EJEC_09) PRE_EJEC_09, sum(PRE_EJEC_10) PRE_EJEC_10, sum(PRE_EJEC_11) PRE_EJEC_11, sum(PRE_EJEC_12) PRE_EJEC_12, sum(PAAC_AUTORIZADO) PAAC_AUTORIZADO, sum(PPTO_RESER2) PPTO_RESER2
   from tmp_sig_techo_presupuestal a 
        left join (select * from sig_tmp_equivalencia_meta where ind_meta = 0 and ano_eje = @ano_eje) c on a.ano_eje = c.ano_eje and a.sec_ejec = c.sec_ejec and a.sec_func = c.sec_func
        left join (select * from sig_tmp_equivalencia_meta where ind_meta = 1 and ano_eje = @ano_eje) m on c.sec_func = m.sec_func
   where a.ano_eje = @ano_eje and a.sec_ejec = @sec_ejec
   group by a.ano_eje, a.sec_ejec, a.origen, a.fuente_financ, a.categ_gasto, a.grupo_gasto, a.clasificador, c.SEC_FUNC_R, a.centro_costo, a.indicador
 
   insert into sig_techo_presupuestal
   select ano_eje, sec_ejec, origen, fuente_financ, secuencia, categ_gasto, grupo_gasto, clasificador, funcion, programa, sec_func, centro_costo, porc_techo, ppto_progra, ppto_aprob, ppto_asignado, ppto_modif, mnto_progra, mnto_asig, mnto_aprob, mnto_modif, indicador, paac_inicial, paac_modif, porc_asig, CUADRE_PPTO_PROGRA, CUADRE_PPTO_MODIF, CUADRE_PPTO_APROB, CUADRE_PPTO_ASIGNA, PPTO_RESER, EJEC_01, EJEC_02, EJEC_03, EJEC_04, EJEC_05, EJEC_06, EJEC_07, EJEC_08, EJEC_09, EJEC_10, EJEC_11, EJEC_12, PPTO_CONTAB, PPTO_PIA, PPTO_CPIA, PRE_EJEC_01, PRE_EJEC_02, PRE_EJEC_03, PRE_EJEC_04, PRE_EJEC_05, PRE_EJEC_06, PRE_EJEC_07, PRE_EJEC_08, PRE_EJEC_09, PRE_EJEC_10, PRE_EJEC_11, PRE_EJEC_12, PAAC_AUTORIZADO, PPTO_RESER2
   from #tp
 
   update sig_tmp_migracion_metas set nreg_proc = @@rowcount where secuencial = 3
 
   drop table #tp
end
 
