	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.CLASIFICADOR =  sig_techo_presupuesto.CLASIFICADOR AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1),
	mnto_anno_02 = ( SELECT SUM(A.MNTO_ANNO_02) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.CLASIFICADOR =  sig_techo_presupuesto.CLASIFICADOR AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1),
	mnto_anno_03 = ( SELECT SUM(A.MNTO_ANNO_03) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.CLASIFICADOR =  sig_techo_presupuesto.CLASIFICADOR AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1)
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     ='5' and
	flag_meta_aprob = '0' AND
	FASE_CUADRO = 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	

	insert into tmp_techo_fase_8
	( origen ,fuente_financ , mnto_progra , FASE_CUADRO, CATEG_GASTO, GRUPO_GASTO, SEC_FUNC_PROP, CENTRO_COSTO_PRESUP)
	SELECT DISTINCT b.origen, b.fuente_financ,
	(
		0
	) 
	as total, 1, B.CATEG_GASTO, B.GRUPO_GASTO, B.SEC_FUNC_PROP,
	B.CENTRO_COSTO_PRESUP
	FROM sig_techo_presupuesto b
	WHERE 	b.ano_eje = @PN_ANIO  and b.sec_ejec = @PN_EJEC AND
		b.indicador     = '0' and b.flag_meta_aprob = '0' and
		B.FASE_CUADRO = 1 AND
		not exists ( select '1'
		  	      FROM sig_techo_presupuesto c
			     WHERE c.ano_eje =  b.ano_eje and c.sec_ejec =b.sec_ejec AND
				   c.origen    = b.origen and c.fuente_financ = b.fuente_financ and
				   C.CATEG_GASTO = B.CATEG_GASTO AND C.GRUPO_GASTO =B.GRUPO_GASTO AND
				   C.SEC_FUNC_PROP = B.SEC_FUNC_PROP AND
				   C.CENTRO_COSTO_PRESUP = B.CENTRO_COSTO_PRESUP AND
				   c.FASE_CUADRO = 1 AND
				   c.indicador     ='5' and c.flag_meta_aprob = '0')

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	

	SELECT @li_secuencia = ISNULL(MAX(secuencia),0) 
	FROM sig_techo_presupuesto 
	WHERE ano_eje= @PN_ANIO and sec_ejec = @PN_EJEC

	insert INTO sig_techo_presupuesto  
      ( ano_eje     , sec_ejec      , origen         , fuente_financ,
	secuencia    , categ_gasto   , grupo_gasto    , clasificador, 
	sec_func       , centro_costo, 
	ppto_progra  , ppto_aprob  , ppto_asignado ,	ppto_modif,
	mnto_progra  , mnto_asig  , mnto_aprob	    , mnto_modif,
	indicador   , paac_inicial  , paac_modif     , porc_techo , 
	porc_asig   , sec_func_prop , flag_meta_aprob, centro_costo_presup,
	FASE_CUADRO )
  	select @PN_ANIO     , @PN_EJEC , origen , fuente_financ,
	( @li_secuencia + secuencia ) , CATEG_GASTO, GRUPO_GASTO , NULL,
	NULL , NULL,
	0 , 0 , 0 , 0 ,
	mnto_progra,0, 0, 0 ,
	'4' ,0, 0 , 0 ,
	0 , SEC_FUNC_PROP , '0' , CENTRO_COSTO_PRESUP, 1
	from tmp_techo_fase_8

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

	

	update sig_techo_presupuesto
	set mnto_progra = ( SELECT SUM(A.MNTO_PROGRA) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1),
	mnto_anno_01 = ( SELECT SUM(A.MNTO_ANNO_01) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1),
	mnto_anno_02 = ( SELECT SUM(A.MNTO_ANNO_02) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1),
	mnto_anno_03 = ( SELECT SUM(A.MNTO_ANNO_03) FROM SIG_TECHO_PRESUPUESTO A
	where 
	A.ano_eje = @PN_ANIO and
	A.sec_ejec = @PN_EJEC AND
	A.origen    = sig_techo_presupuesto.ORIGEN AND
	A.fuente_financ = sig_techo_presupuesto.FUENTE_FINANC AND
	A.CATEG_GASTO =  sig_techo_presupuesto.CATEG_GASTO AND
	A.GRUPO_GASTO =  sig_techo_presupuesto.GRUPO_GASTO AND
	A.SEC_FUNC_PROP =  sig_techo_presupuesto.SEC_FUNC_PROP AND
	A.CENTRO_COSTO_PRESUP =  sig_techo_presupuesto.CENTRO_COSTO_PRESUP AND
	A.indicador     ='0' and
	A.flag_meta_aprob = '0' AND
	A.FASE_CUADRO = 1)
	where 
	ano_eje = @PN_ANIO and
	sec_ejec = @PN_EJEC AND
	indicador     ='4' and
	flag_meta_aprob = '0' AND
	FASE_CUADRO = 1

	IF @@ERROR <> 0
	BEGIN
		return -1
	END

END

TRUNCATE TABLE dbo.tmp_techo_cn_fase 
TRUNCATE TABLE dbo.tmp_propuesta_fase 
TRUNCATE TABLE dbo.tmp_techo_fase_2 
TRUNCATE TABLE dbo.tmp_techo_fase_3
TRUNCATE TABLE dbo.tmp_techo_fase_4
TRUNCATE TABLE dbo.tmp_techo_fase_5
TRUNCATE TABLE dbo.tmp_techo_fase_6
TRUNCATE TABLE dbo.tmp_techo_fase_7
TRUNCATE TABLE dbo.tmp_techo_fase_8

RETURN 1

END
GO


-- ----------------------------
-- procedure structure for DT_GETPROPERTIESBYID_U
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_GETPROPERTIESBYID_U]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_GETPROPERTIESBYID_U]
GO

CREATE PROCEDURE [dbo].[DT_GETPROPERTIESBYID_U]
	@id int,
	@property varchar(64)
as
	set nocount on

	if (@property is null) or (@property = '')
		select property, version, uvalue, lvalue
			from dbo.dtproperties
			where  @id=objectid
	else
		select property, version, uvalue, lvalue
			from dbo.dtproperties
			where  @id=objectid and @property=property
GO


-- ----------------------------
-- procedure structure for DT_ADDTOSOURCECONTROL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_ADDTOSOURCECONTROL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_ADDTOSOURCECONTROL]
GO

CREATE PROCEDURE [dbo].[DT_ADDTOSOURCECONTROL]
    @vchSourceSafeINI varchar(255) = '',
    @vchProjectName   varchar(255) ='',
    @vchComment       varchar(255) ='',
    @vchLoginName     varchar(255) ='',
    @vchPassword      varchar(255) =''

as

set nocount on

declare @iReturn int
declare @iObjectId int
select @iObjectId = 0

declare @iStreamObjectId int
select @iStreamObjectId = 0

declare @VSSGUID varchar(100)
select @VSSGUID = 'SQLVersionControl.VCS_SQL'

declare @vchDatabaseName varchar(255)
select @vchDatabaseName = db_name()

declare @iReturnValue int
select @iReturnValue = 0

declare @iPropertyObjectId int
declare @vchParentId varchar(255)

declare @iObjectCount int
select @iObjectCount = 0

    exec @iReturn = master.dbo.sp_OACreate @VSSGUID, @iObjectId OUT
    if @iReturn <> 0 GOTO E_OAError


    /* Create Project in SS */
    exec @iReturn = master.dbo.sp_OAMethod @iObjectId,
											'AddProjectToSourceSafe',
											NULL,
											@vchSourceSafeINI,
											@vchProjectName output,
											@@SERVERNAME,
											@vchDatabaseName,
											@vchLoginName,
											@vchPassword,
											@vchComment


    if @iReturn <> 0 GOTO E_OAError

    /* Set Database Properties */

    begin tran SetProperties

    /* add high level object */

    exec @iPropertyObjectId = dbo.dt_adduserobject_vcs 'VCSProjectID'

    select @vchParentId = CONVERT(varchar(255),@iPropertyObjectId)

    exec dbo.dt_setpropertybyid @iPropertyObjectId, 'VCSProjectID', @vchParentId , NULL
    exec dbo.dt_setpropertybyid @iPropertyObjectId, 'VCSProject' , @vchProjectName , NULL
    exec dbo.dt_setpropertybyid @iPropertyObjectId, 'VCSSourceSafeINI' , @vchSourceSafeINI , NULL
    exec dbo.dt_setpropertybyid @iPropertyObjectId, 'VCSSQLServer', @@SERVERNAME, NULL
    exec dbo.dt_setpropertybyid @iPropertyObjectId, 'VCSSQLDatabase', @vchDatabaseName, NULL

    if @@error <> 0 GOTO E_General_Error

    commit tran SetProperties
    
    select @iObjectCount = 0;

CleanUp:
    select @vchProjectName
    select @iObjectCount
    return

E_General_Error:
    /* this is an all or nothing.  No specific error messages */
    goto CleanUp

E_OAError:
    exec dbo.dt_displayoaerror @iObjectId, @iReturn
    goto CleanUp
GO


-- ----------------------------
-- procedure structure for SP_MIGRA_CMN_APROBADO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_MIGRA_CMN_APROBADO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_MIGRA_CMN_APROBADO]
GO

CREATE PROCEDURE [dbo].[SP_MIGRA_CMN_APROBADO]
(
 @PN_ANIO 		NUMERIC,  
 @PN_EJECUTORA 	NUMERIC
)     
AS  
BEGIN
	DECLARE @li_secuencia 	NUMERIC(6)
	DECLARE @ld_sec_func 	NUMERIC(5)
	DECLARE @LS_CC 			VARCHAR(15) 
	DECLARE @LD_SEDE_ID 	NUMERIC(2) 
	DECLARE @LL_CUADROID 	NUMERIC(4)
	DECLARE @LL_CUADRODET_ID NUMERIC(4)
	DECLARE @ll_cont		NUMERIC(6)
	DECLARE @ll_sec_techo	NUMERIC(6)	
	DECLARE @LS_CC_PADRE	VARCHAR(15)
	DECLARE @LS_ORDEN	    VARCHAR(80)
	DECLARE @ls_ff			VARCHAR(2)
	
	
	CREATE TABLE dbo.tmp_techo_presupuesto_upd
	(
	SEC_EJEC              NUMERIC (10) NOT NULL,
	ANNO                  NUMERIC (4)  NOT NULL,
	FASE                  NUMERIC (1)  NOT NULL,
  	SECUENCIA             NUMERIC (10) NOT NULL,
	ORIGEN                VARCHAR (1) NULL,
	FUENTE_FINANC         VARCHAR (2) NULL,
	CATEG_GASTO           VARCHAR (1) NULL,
	GRUPO_GASTO           VARCHAR (1) NULL,
	CLASIFICADOR          VARCHAR (20) NULL,
	SEC_FUNC              NUMERIC (6)  NULL,   
	CENTRO_COSTO          VARCHAR (20) NULL,
	CENTRO_COSTO_PRESUP   VARCHAR (20) NULL,
	INDICADOR             VARCHAR (1)  NOT NULL,
	MNTO_CMN              NUMERIC (16,2) NOT NULL,
   	MNTO_CMN2             NUMERIC (16,2) NOT NULL,
  	MNTO_CMN3             NUMERIC (16,2) NOT NULL,
  	MNTO_CMN4             NUMERIC (16,2) NOT NULL,
	PPTO_TECHO            NUMERIC (16,2) NOT NULL,
  	PPTO_TECHO2           NUMERIC (16,2) NOT NULL,
  	PPTO_TECHO3           NUMERIC (16,2) NOT NULL,
  	PPTO_TECHO4           NUMERIC (16,2) NOT NULL,  	
	MNTO_MODIF            NUMERIC (16,2) NOT NULL,
	PPTO_MODIF            NUMERIC (16,2) NOT NULL,
	CUADRE_PPTO           NUMERIC (16,2) NOT NULL,
	CUADRE_PPTO_MODIF     NUMERIC (16,2) NOT NULL,
	PPTO_RESER            NUMERIC (16,2) NOT NULL,
	PPTO_RESER2           NUMERIC (16,2) NOT NULL,
	EJEC_01               NUMERIC (16,2) NOT NULL,
	EJEC_02               NUMERIC (16,2) NOT NULL,
	EJEC_03               NUMERIC (16,2) NOT NULL,
	EJEC_04               NUMERIC (16,2) NOT NULL,
	EJEC_05               NUMERIC (16,2) NOT NULL,
	EJEC_06               NUMERIC (16,2) NOT NULL,
	EJEC_07               NUMERIC (16,2) NOT NULL,
	EJEC_08               NUMERIC (16,2) NOT NULL,
	EJEC_09               NUMERIC (16,2) NOT NULL,
	EJEC_10               NUMERIC (16,2) NOT NULL,
	EJEC_11               NUMERIC (16,2) NOT NULL,
	EJEC_12               NUMERIC (16,2) NOT NULL,
	PAAC_MODIF            NUMERIC (16,2) NOT NULL,
	PPTO_CONTAB           NUMERIC (16,2) NOT NULL,
	PPTO_PIA              NUMERIC (16,2) NOT NULL,
	PPTO_CPIA             NUMERIC (16,2) NOT NULL,
	PPTO_EST              NUMERIC (16,2) NOT NULL,
	PPTO_DEF              NUMERIC (16,2) NOT NULL,
	PPTO_SIAF             NUMERIC (16,2) NOT NULL,
	PPTO_EJECU            NUMERIC (16,2) NOT NULL,
	PPTO_SIGA             NUMERIC (16,2) NOT NULL,
	PPTO_DEF_ANUAL        NUMERIC (16,2) NOT NULL,
	PPTO_DISP_SIAF        NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_CERT        NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_COMA        NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_COMM        NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_CERT_SIAF   NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_COMA_SIAF   NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_COMM_SIAF   NUMERIC (16,2) NOT NULL,
	MNTO_ACUM_DEVGDO_SIAF NUMERIC (16,2) NOT NULL,
	MNTO_RESERVA_PEDIDO   NUMERIC (16,2) NOT NULL,
	MNTO_OPAGO            NUMERIC (16,2) NOT NULL,
	MNTO_OPAGO2           NUMERIC (16,2) NOT NULL,
	MNTO_OPAGO3           NUMERIC (16,2) NOT NULL,
	MNTO_OPAGO4           NUMERIC (16,2) NOT NULL,	
	MNTO_PREVISION        NUMERIC (16,2) NOT NULL,
	MNTO_PREVISION2       NUMERIC (16,2) NOT NULL,
	MNTO_PREVISION3       NUMERIC (16,2) NOT NULL,
	MNTO_PREVISION4       NUMERIC (16,2) NOT NULL
	)
	
	/*---------Elimina registros de Tablas dependientes de la tabla Centro de costo que tengan CC inactivos----*/
	DELETE FROM dbo.TMP_CENTRO_COSTO_META_FUEN 
	 WHERE TMP_CENTRO_COSTO_META_FUEN.SEC_EJEC 	= @PN_EJECUTORA
	   AND TMP_CENTRO_COSTO_META_FUEN.ANNO 		= @PN_ANIO
	   AND NOT EXISTS (SELECT 1 FROM TMP_CENTRO_COSTO
						WHERE TMP_CENTRO_COSTO.SEC_EJEC 	= TMP_CENTRO_COSTO_META_FUEN.SEC_EJEC 
						  AND TMP_CENTRO_COSTO.ANNO 		= TMP_CENTRO_COSTO_META_FUEN.ANNO
						  AND TMP_CENTRO_COSTO.CENTRO_COSTO = TMP_CENTRO_COSTO_META_FUEN.CENTRO_COSTO 
						  AND TMP_CENTRO_COSTO.ESTADO = '1')
						
	IF @@ERROR <> 0
    BEGIN
	  return -1
    END
			
	DELETE FROM dbo.TMP_CENTRO_COSTO_SEDE 
	 WHERE TMP_CENTRO_COSTO_SEDE.SEC_EJEC 	= @PN_EJECUTORA
	   AND TMP_CENTRO_COSTO_SEDE.ANNO 		= @PN_ANIO
	   AND NOT EXISTS (SELECT 1 FROM TMP_CENTRO_COSTO
						WHERE TMP_CENTRO_COSTO.SEC_EJEC 	= TMP_CENTRO_COSTO_SEDE.SEC_EJEC 
						  AND TMP_CENTRO_COSTO.ANNO 		= TMP_CENTRO_COSTO_SEDE.ANNO
						  AND TMP_CENTRO_COSTO.CENTRO_COSTO = TMP_CENTRO_COSTO_SEDE.CENTRO_COSTO 
						  AND TMP_CENTRO_COSTO.ESTADO = '1') 
						
	IF @@ERROR <> 0
    BEGIN
	  return -1
    END			
			
	DELETE FROM dbo.TMP_CENTROMETA_ACTIOPER 
	 WHERE TMP_CENTROMETA_ACTIOPER.SEC_EJEC = @PN_EJECUTORA
	   AND TMP_CENTROMETA_ACTIOPER.ANNO 	= @PN_ANIO
	   AND NOT EXISTS (SELECT 1 FROM TMP_CENTRO_COSTO
						WHERE TMP_CENTRO_COSTO.SEC_EJEC 	= TMP_CENTROMETA_ACTIOPER.SEC_EJEC 
						  AND TMP_CENTRO_COSTO.ANNO 		= TMP_CENTROMETA_ACTIOPER.ANNO
						  AND TMP_CENTRO_COSTO.CENTRO_COSTO = TMP_CENTROMETA_ACTIOPER.CENTRO_COSTO 
						  AND TMP_CENTRO_COSTO.ESTADO = '1')	
						
	IF @@ERROR <> 0
    BEGIN
	  return -1
    END						
	
	/*--------Actividad Operativa----------------*/
	INSERT INTO dbo.SIG_TAREA 
	( ano_eje, 		sec_ejec, tipo_tarea, 	nivel_tarea, 	tarea_general, nombre, 		grupo_tarea, 		estado, 
	  fecha_reg, 	cuser_id, tipo_ppto, 	tipo_uso, 		sec_ejec2, 		TIPO_TAREA_PAD, NIVEL_TAREA_PAD, TAREA_GENERAL_PAD, 
	  ORDEN_TAREA,  TIPO_META,CODIGO_ALTERNO 
	 )
	SELECT 
	  ANNO, 	     SEC_EJEC, 		   TIPO_ACT_PROY,   ACT_OPE_NIVEL, ACT_OPE_ID, NOMBRE, '02',  CASE WHEN ESTADO ='1' THEN 'A' ELSE 'I' END AS ESTADO, 
	  FECHA_CREACION,USUARIO_CREACION, TIPO_PPTO, 		TIPO_USO, 	   NULL, 	   NULL, 	NULL, NULL, 
	  NULL, 		 NULL, 	   CODIGO_POI
	 FROM dbo.TMP_ACTIVIDAD_OPERATIVA TAO
	WHERE NOT EXISTS ( SELECT 1 FROM SIG_TAREA T
					    WHERE T.ano_eje 	  = TAO.ANNO
					      AND T.sec_ejec 	  = TAO.SEC_EJEC
						  AND T.tipo_tarea 	  = TAO.TIPO_ACT_PROY
						  AND T.nivel_tarea   = TAO.ACT_OPE_NIVEL
						  AND T.tarea_general = TAO.ACT_OPE_ID 
							)
						
  	IF @@ERROR <> 0
    BEGIN
	  return -1
    END
	
	/*--------CENTRO DE COSTO----------------*/
	INSERT INTO dbo.SIG_CENTRO_COSTO 
	( ANO_EJE, 		SEC_EJEC, 	CENTRO_COSTO, 	NOMBRE_DEPEND, 	ABREVIADO_DEPEND, 	SEDE, 			PLIEGO, 
	  TIPO_DEPEND,  ESTADO, 	FECHA_ALTA, 	FECHA_BAJA, 	EMPLEADO, 			NRO_PERSONAL,  	CENTRO_PADRE, 
	  FLAG_GF, 		FLAG_CN, 	FECHA_FLAG, 	ORDEN, 			CUSER_ID, 			CENTRO_SBN, 	FLAG_SISMED, 
	  FLAG_PRESUPUESTO,flag_ppr,TIPO_ROL, 		TIPO_REGISTRO, 	flag_pptal, 		SecUPs, 		CODIGO_ALTERNO,
	  FLAG_AREA_ESTRATEGICA
	 )
	SELECT 
	  CC.ANNO , CC.SEC_EJEC, CC.CENTRO_COSTO, CC.NOMBRE, 	CC.ABREVIATURA, 	CC_SEDE.SEDE_ID, S.PLIEGO, 
	  CC.NIVEL, CASE WHEN CC.ESTADO ='1' THEN 'A' ELSE 'I' END AS ESTADO, NULL, NULL, CC.PERSONAL_DOCNUM, 0, CC.CENTRO_PADRE, 
	  'N', 		NULL, 		NULL, 			CC.ORDEN, 		CC.USUARIO_CREACION,NULL, 			'N', 
	  'S', 		'0', 		'0', 			'0', 			NULL, 				NULL, 			NULL,
	  CC.FLAG_AREA_ESTRATEGICA
	FROM dbo.TMP_CENTRO_COSTO CC
	JOIN dbo.TMP_CENTRO_COSTO_SEDE CC_SEDE
		ON 		CC.SEC_EJEC 	= CC_SEDE.SEC_EJEC
			AND CC.ANNO 		= CC_SEDE.ANNO
			AND CC.CENTRO_COSTO = CC_SEDE.CENTRO_COSTO
	JOIN dbo.SIG_SEDES S
		ON 		S.SEDE = CC_SEDE.SEDE_ID
 	JOIN dbo.sig_ejecutora E
	  	ON E.sec_ejec 	= CC.SEC_EJEC
	   AND E.sector 	= S.SECTOR
	   AND E.pliego 	= S.PLIEGO
	WHERE NOT EXISTS ( 
						SELECT 1 FROM dbo.SIG_CENTRO_COSTO SCC
						 WHERE SCC.ANO_EJE 		= CC.ANNO
						   AND SCC.SEC_EJEC 	= CC.SEC_EJEC
						   AND SCC.CENTRO_COSTO = CC.CENTRO_COSTO
					 )	
					 
  	IF @@ERROR <> 0
    BEGIN
	  return -1
    END

 /*--------CUADRO x CENTRO ----------------*/   
  /*Registra CC padres*/
  INSERT INTO dbo.SIG_CUADRO_X_CENTRO
  ( ano_eje  , sec_ejec , centro_costo,   estado  , flag_padre, flag_modif, fecha_reg, cuser_id )
  SELECT ANO_EJE, sec_ejec,  centro_costo,  '5',    '1',    NULL,     GETDATE(),  CUSER_ID       
  FROM dbo.sig_centro_costo
   WHERE ano_eje    = @PN_ANIO and
       sec_ejec   	= @PN_EJECUTORA and
       tipo_depend  = '1' and
       estado     	= 'A' and 
       NOT EXISTS ( SELECT 1 
		              FROM dbo.SIG_CUADRO_X_CENTRO C
		             WHERE C.ANO_EJE 		= sig_centro_costo.ANO_EJE
		               AND C.SEC_EJEC 		= sig_centro_costo.SEC_EJEC
		               AND C.CENTRO_COSTO 	= sig_centro_costo.CENTRO_COSTO
		          ) 
    					 
  	IF @@ERROR <> 0
    BEGIN
	  return -1
    END
    
  DECLARE c_centro_padre CURSOR FOR
  SELECT centro_costo
    FROM dbo.SIG_CENTRO_COSTO
   WHERE ano_eje  = @PN_ANIO 
   AND sec_ejec   = @PN_EJECUTORA 
   AND tipo_depend= '1'
   AND estado     = 'A' 
   
  /*---Registra CC dependientes--- */
  OPEN c_centro_padre  
	FETCH NEXT FROM c_centro_padre INTO @LS_CC_PADRE
	WHILE @@FETCH_STATUS = 0  
	BEGIN   
      	SELECT @ls_orden = LTRIM(RTRIM(@ls_cc_padre))+'%' 
            
      	INSERT INTO dbo.SIG_CUADRO_X_CENTRO
	    ( ano_eje  , sec_ejec  , centro_costo, estado  , flag_padre, flag_modif, fecha_reg, cuser_id )
	    SELECT  ano_eje, sec_ejec, centro_costo, '5', '2', '0', getdate(), cuser_id      
	      FROM  dbo.sig_centro_costo
	     WHERE  ano_eje  = @PN_ANIO and
	        	sec_ejec = @PN_EJECUTORA and
	        	orden like @ls_orden and
	          	tipo_depend <>'1' and
	        	estado 		='A' and 
	        	centro_costo not in (select centro_padre
					                   FROM dbo.sig_centro_costo  
					                   WHERE ano_eje = @PN_ANIO and
					                   		 sec_ejec= @PN_EJECUTORA AND
					                   		 centro_padre IS NOT NULL
					                  )  AND
		   	 	NOT EXISTS ( SELECT 1 FROM dbo.SIG_CUADRO_X_CENTRO cuadro 
							  WHERE cuadro.ano_eje 		= sig_centro_costo.ano_eje 
								AND cuadro.sec_ejec 	= sig_centro_costo.sec_ejec
								AND cuadro.centro_costo = sig_centro_costo.centro_Costo
								AND cuadro.flag_padre 	= '2'
					   		)		                     
	   				
		IF (@@error <> 0)
		BEGIN		   
			CLOSE c_centro_padre
			DEALLOCATE c_centro_padre
			RETURN -1
		END
   		
		FETCH NEXT FROM c_centro_padre INTO @LS_CC_PADRE
   END
   CLOSE c_centro_padre  
   DEALLOCATE c_centro_padre 	          

   	/*------------------------*/
	UPDATE dbo.TMP_CENTRO_COSTO_META_FUEN
	SET SECUENCIA = 1

	IF @@ERROR <> 0
     BEGIN
	  return -1
     END			 

   	/*------------------------*/
	DECLARE c_centro_costo CURSOR FOR
	SELECT CENTRO_COSTO
	  FROM dbo.TMP_CENTRO_COSTO_META_FUEN
	 WHERE ANNO		= @PN_ANIO 
	   AND SEC_EJEC = @PN_EJECUTORA
	 GROUP BY CENTRO_COSTO 
	 HAVING COUNT(sec_ejec) > 1
	
	OPEN c_centro_costo  
	FETCH NEXT FROM c_centro_costo INTO @LS_CC
	WHILE @@FETCH_STATUS = 0  
	BEGIN   
		SELECT @li_secuencia = 1
		
		DECLARE c_meta CURSOR FOR
		SELECT sec_func, fuente_financ
		  FROM dbo.TMP_CENTRO_COSTO_META_FUEN
		 WHERE ANNO 		= @PN_ANIO 
		   AND SEC_EJEC 	= @PN_EJECUTORA  
		   AND CENTRO_COSTO = @LS_CC
		GROUP BY sec_func, fuente_financ
		
		OPEN c_meta
		FETCH NEXT FROM c_meta INTO @ld_sec_func, @ls_ff
		WHILE @@FETCH_STATUS = 0  
		BEGIN
			
				UPDATE dbo.TMP_CENTRO_COSTO_META_FUEN
				   SET SECUENCIA = @li_secuencia
				 WHERE ANNO 		= @PN_ANIO 
				   AND SEC_EJEC 	= @PN_EJECUTORA 
				   AND CENTRO_COSTO = @LS_CC 
				   AND SEC_FUNC 	= @ld_sec_func 
				   AND FUENTE_FINANC= @ls_ff
				
				IF (@@error <> 0)
				BEGIN
					CLOSE c_meta
					DEALLOCATE c_meta
					CLOSE C_CENTRO_COSTO
					DEALLOCATE C_CENTRO_COSTO
					RETURN -1
				END
				SELECT @li_secuencia = @li_secuencia + 1
							
				FETCH NEXT FROM c_meta INTO @ld_sec_func, @ls_ff
				
		END  
		CLOSE c_meta  
		DEALLOCATE c_meta 
		
		FETCH NEXT FROM c_centro_costo INTO @LS_CC
   END
   CLOSE c_centro_costo  
   DEALLOCATE c_centro_costo 	
	   
   	/*------------------------*/					
	INSERT INTO dbo.SIG_METAS_X_CENTRO 
	( ANO_EJE, 		SEC_EJEC, 		CENTRO_COSTO,   SECUENCIA, 		SEC_FUNC, 	  	ORIGEN, 			FUENTE_FINANC, 
	  TIPO_RECURSO, PORC_GFIJOS,	PORC_TECHO, 	CUSER_ID,  		FECHA_REG, 		FLAG_BLOQUEO_PPR, 	F_CREACION
	)
	SELECT 
	  CCM.ANNO, 	CCM.SEC_EJEC, 	CCM.CENTRO_COSTO, 	CCM.SECUENCIA,		  CCM.SEC_FUNC, 		CCM.ORIGEN, CCM.FUENTE_FINANC, 
	  '1', 			0, 				0, 					CCM.USUARIO_CREACION, CCM.FECHA_CREACION, 	NULL, 		NULL
	 FROM dbo.TMP_CENTRO_COSTO_META_FUEN CCM 
	WHERE NOT EXISTS (SELECT 1 
						FROM dbo.SIG_METAS_X_CENTRO MC
					   WHERE MC.ano_eje 		= CCM.ANNO
						 AND MC.sec_ejec 		= CCM.SEC_EJEC
						 AND MC.centro_costo 	= CCM.CENTRO_COSTO
						 AND MC.secuencia 		= CCM.SECUENCIA
					  )

	IF @@ERROR <> 0
     BEGIN
	  return -1
     END

	/*------------------------*/
	INSERT INTO dbo.SIG_META_CENTRO_TAREA 
	( SEC_EJEC, 	ANO_EJE, 	CENTRO_COSTO, 		TIPO_TAREA,     	NIVEL_TAREA, 		CODIGO_TAREA, 	
	  SECUENCIA,    NRO_FASE, 	TIPO_ORIGEN,		CUSER_ID, 			EQUIPO_REG, 		FECHA_REG, 		
	  CUSER_ACT, 	EQUIPO_ACT, FECHA_ACT
	)
	SELECT 
	 CCA.SEC_EJEC, 	CCA.ANNO, 	CCA.CENTRO_COSTO, 	CCA.TIPO_ACT_PROY,   CCA.ACT_OPE_NIVEL, CCA.ACT_OPE_ID, 		  
	 CCM.SECUENCIA, 5,		  	'L',				CCA.USUARIO_CREACION,'SIGAMEF',  		CCA.FECHA_CREACION, 
	 CCA.USUARIO_MODIFICACION, NULL, CCA.FECHA_MODIFICACION		 
	FROM dbo.TMP_CENTROMETA_ACTIOPER CCA
	JOIN dbo.TMP_CENTRO_COSTO_META_FUEN CCM
	ON 	CCM.SEC_EJEC 		= CCA.SEC_EJEC
	AND CCM.ANNO 			= CCA.ANNO
	AND CCM.CENTRO_COSTO 	= CCA.CENTRO_COSTO
	AND CCM.SEC_FUNC 		= CCA.SEC_FUNC
	AND CCM.FUENTE_FINANC 	= CCA.FUENTE_FINANC 
	AND CCM.FASE 			= CCA.FASE
	WHERE NOT EXISTS ( SELECT 1 
						 FROM dbo.SIG_META_CENTRO_TAREA MT
						WHERE 
							MT.SEC_EJEC 	= CCA.SEC_EJEC
						AND MT.ANO_EJE 		= CCA.ANNO
						AND MT.CENTRO_COSTO = CCA.CENTRO_COSTO
						AND MT.TIPO_TAREA 	= CCA.TIPO_ACT_PROY
						AND MT.NIVEL_TAREA 	= CCA.ACT_OPE_NIVEL
						AND MT.CODIGO_TAREA = CCA.ACT_OPE_ID
						AND MT.SECUENCIA 	= CCM.SECUENCIA
						AND MT.NRO_FASE 	= 5
					)

	IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
	/*------------------------*/
	INSERT INTO dbo.SIG_CENTRO_COSTO_TAREA 
	( sec_ejec, 	ano_eje, 		centro_costo, 		tipo_tarea, 		nivel_tarea, 		  codigo_tarea, 	
	  nombre_tarea, grupo_tarea,  	tarea_general, 		estado, 			fecha_reg, 			  cuser_id, 			  
	  tipo_ppto, 	tipo_uso, 		CANTIDAD, 			TIPO_ORIGEN
	)	
	SELECT DISTINCT
	  CCA.SEC_EJEC, CCA.ANNO, 		CCA.CENTRO_COSTO, 	CCA.TIPO_ACT_PROY, 	CCA.ACT_OPE_NIVEL, 	  CCA.ACT_OPE_ID, 	
	  AO.NOMBRE, 	'02', 			CCA.ACT_OPE_ID, 	'A', 			  	GETDATE(),   		  NULL , 
	  '1', 			AO.TIPO_USO,    0, 					CASE CCA.ACT_OPE_NIVEL WHEN 'C' THEN 'L' WHEN 'E' THEN 'R' ELSE NULL END TIPO_ORIGEN
	 FROM dbo.TMP_CENTROMETA_ACTIOPER CCA
	 JOIN dbo.TMP_ACTIVIDAD_OPERATIVA AO
		ON 	AO.SEC_EJEC 		= CCA.SEC_EJEC
	 	AND AO.ANNO 			= CCA.ANNO
	 	AND AO.TIPO_ACT_PROY 	= CCA.TIPO_ACT_PROY
	 	AND AO.ACT_OPE_NIVEL 	= CCA.ACT_OPE_NIVEL
	 	AND AO.ACT_OPE_ID 		= CCA.ACT_OPE_ID 
	WHERE CCA.FASE = 5 
	  AND NOT EXISTS ( SELECT 1 FROM dbo.SIG_CENTRO_COSTO_TAREA CCT
						WHERE CCT.sec_ejec 		= CCA.SEC_EJEC
						 AND CCT.ano_eje 		= CCA.ANNO
						 AND CCT.centro_costo 	= CCA.CENTRO_COSTO
						 AND CCT.tipo_tarea 	= CCA.TIPO_ACT_PROY
						 AND CCT.nivel_tarea 	= CCA.ACT_OPE_NIVEL
						 AND CCT.codigo_tarea 	= CCA.ACT_OPE_ID
					 ) 

	IF @@ERROR <> 0
     BEGIN
	  return -1
     END

	/*----------CATALOGO -------------*/
	INSERT INTO dbo.CATALOGO_BIEN_SERV 
	( SEC_EJEC, 	TIPO_BIEN, 	  			GRUPO_BIEN, 		CLASE_BIEN,     FAMILIA_BIEN, 		ITEM_BIEN, 	    NOMBRE_ITEM, 
	  FLAG_ACTIVO, 	TIPO_ACTIVO,  			UNIDAD_ADQUIS, 		FACTOR_UNIDAD,  UNIDAD_MEDIDA, 		MARCA_REF, 	    PRECIO_REF, 
	  FECHA_REF, 	PRECIO_COMPRA,		  	FECHA_COMPRA, 		FLAG_ITEM, 	 	STOCK_MINIMO,  		STOCK_MAXIMO,   ESTADO, 	
	  FECHA_ALTA, 	FECHA_ACT, 	  			BOLSA_PRODUCTO, 	CUSER_ID, 		PAIS, 				FLAG_VISUALIZA, ENVIADO, 
	  CODIGO_ITEM,  FLAG_SUBASTA_INVERSA, 	FLAG_MARCO_PRECIO, 	ESTADO_MEF, 	CODIGO_OSCE, 		ALIAS1, 		ALIAS2, 	ALIAS3 
	 )
	SELECT 
	 @PN_EJECUTORA,   	TCBS.TIPO_BIEN, 	TCBS.GRUPO_BIEN, 	TCBS.CLASE_BIEN, TCBS.FAMILIA_BIEN,  TCBS.ITEM_BIEN, TCBS.NOMBRE_ITEM, 
	 TCBS.FLAG_ACTIVO, 	NULL, 				TCBS.UNIDAD_MEDIDA, 0, 				 TCBS.UNIDAD_MEDIDA, TCBS.MARCA_REF, TCBS.PRECIO_REF, 
	 NULL, 				TCBS.PRECIO_COMPRA, NULL,  				TCBS.FLAG_ITEM,  0, 				 0,  			 TCBS.ESTADO,
	 TCBS.FECHA_ALTA, 	NULL,				TCBS.BOLSA_PRODUCTO,NULL, 			 '4028', 			 'S', 			 'S', 
	 NULL, 				TCBS.FLAG_SUBASTA_INVERSA, TCBS.FLAG_MARCO_PRECIO, 'A', TCBS.CODIGO_OSCE, 	 TCBS.ALIAS1, 	 TCBS.ALIAS2, 	TCBS.ALIAS3
	 FROM dbo.TMP_CATALOGO_BIEN_SERV TCBS
	WHERE NOT EXISTS ( SELECT 1 FROM dbo.CATALOGO_BIEN_SERV CBS
						WHERE CBS.SEC_EJEC 		= @PN_EJECUTORA
						  AND CBS.TIPO_BIEN 	= TCBS.TIPO_BIEN
					   	  AND CBS.GRUPO_BIEN   	= TCBS.GRUPO_BIEN
						  AND CBS.CLASE_BIEN   	= TCBS.CLASE_BIEN
						  AND CBS.FAMILIA_BIEN 	= TCBS.FAMILIA_BIEN
						  AND CBS.ITEM_BIEN    	= TCBS.ITEM_BIEN
						) 
						
	IF @@ERROR <> 0
     BEGIN
	  return -1
     END						

	/*------------------------*/
	UPDATE dbo.CATALOGO_BIEN_SERV
	SET CODIGO_ITEM = GRUPO_BIEN+CLASE_BIEN+FAMILIA_BIEN+ITEM_BIEN
	WHERE SEC_EJEC = @PN_EJECUTORA
	AND EXISTS (SELECT 1 FROM dbo.TMP_CATALOGO_BIEN_SERV CBS
				WHERE CBS.TIPO_BIEN 	= CATALOGO_BIEN_SERV.TIPO_BIEN
				  AND CBS.GRUPO_BIEN 	= CATALOGO_BIEN_SERV.GRUPO_BIEN
				  AND CBS.CLASE_BIEN 	= CATALOGO_BIEN_SERV.CLASE_BIEN
				  AND CBS.FAMILIA_BIEN 	= CATALOGO_BIEN_SERV.FAMILIA_BIEN
				  AND CBS.ITEM_BIEN 	= CATALOGO_BIEN_SERV.ITEM_BIEN
				)
				
	 IF @@ERROR <> 0
     BEGIN
	  return -1
     END			

	/*------------------------*/
	INSERT INTO dbo.SIG_CATALOGO_BIEN_SERV_PRECIO 
	( SEC_EJEC, 	 ANO_EJE, 					TIPO_BIEN, 			GRUPO_BIEN, 			CLASE_BIEN, 		FAMILIA_BIEN, 		ITEM_BIEN, 
	  PRECIO_REF, 	 UNIDAD_MEDIDA, 			FECHA_REG, 			ESTADO, 	   			CUSER_ID, 			EQUIPO_REG,  		INDICADOR, 
	  FECHA_REF, 	 CUSER_MODIF, 				FLAG_PROC_CN, 		PRECIO_REF_ORIGEN,  	flag_proc, 			flag_pase, 			flag_ppr_req, 
	  FLAG_PPR_PRG,  FLAG_PPR_APR
	 )
	SELECT 
	  CP.SEC_EJEC, 	 CP.ANNO,   		 		TCBS.TIPO_BIEN, 	TCBS.GRUPO_BIEN, 		TCBS.CLASE_BIEN, 		TCBS.FAMILIA_BIEN,  TCBS.ITEM_BIEN,
	  CP.PRECIO_REF, TCBS.UNIDAD_MEDIDA, 		CP.FECHA_CREACION,  CASE WHEN CP.ESTADO ='1' THEN 'A' ELSE 'I' END,	CP.USUARIO_CREACION,NULL,		 	'2',	
	  NULL, 		 CP.USUARIO_MODIFICACION, 	NULL, 				CP.PRECIO_REF_ANTERIOR, '0', 					'0',		 		NULL, 
	  NULL,  		 NULL
	FROM dbo.TMP_CATALOGO_EJEC_PRECIO CP
	JOIN dbo.TMP_CATALOGO_BIEN_SERV TCBS
	ON  TCBS.CATALOGO_NUM 	= CP.CATALOGO_NUM
	AND TCBS.ITEM_ID 		= CP.ITEM_ID 
	WHERE NOT EXISTS ( SELECT 1 FROM dbo.SIG_CATALOGO_BIEN_SERV_PRECIO CAT
						WHERE CAT.SEC_EJEC 		= CP.SEC_EJEC
						AND CAT.ANO_EJE 		= CP.ANNO
						AND CAT.TIPO_BIEN 		= TCBS.TIPO_BIEN
						AND CAT.GRUPO_BIEN 		= TCBS.GRUPO_BIEN
						AND CAT.CLASE_BIEN 		= TCBS.CLASE_BIEN
						AND CAT.FAMILIA_BIEN 	= TCBS.FAMILIA_BIEN
						AND CAT.ITEM_BIEN 		= TCBS.ITEM_BIEN
						) 
						
	IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     
    /*----------ACTUALIZA PRECIO DE ITEMS EXISTENTES EN EL CLIENTE --------------*/
     UPDATE dbo.SIG_CATALOGO_BIEN_SERV_PRECIO 
		SET SIG_CATALOGO_BIEN_SERV_PRECIO.PRECIO_REF = X.PRECIO_REF
		FROM ( SELECT TCBS.TIPO_BIEN, TCBS.GRUPO_BIEN, TCBS.CLASE_BIEN , TCBS.FAMILIA_BIEN ,TCBS.ITEM_BIEN, TCP.PRECIO_REF
			     FROM dbo.TMP_CATALOGO_BIEN_SERV TCBS
			   	 JOIN dbo.TMP_CATALOGO_EJEC_PRECIO TCP
				   ON TCBS.CATALOGO_NUM = TCP.CATALOGO_NUM
				  AND TCBS.ITEM_ID 		= TCP.ITEM_ID  
				WHERE TCP.SEC_EJEC 		= @PN_EJECUTORA  ) X
		WHERE SIG_CATALOGO_BIEN_SERV_PRECIO.ANO_EJE 		= @PN_ANIO 
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.SEC_EJEC 		= @PN_EJECUTORA 
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.TIPO_BIEN 		= X.TIPO_BIEN 	
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.GRUPO_BIEN 		= X.GRUPO_BIEN 	 
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.CLASE_BIEN 		= X.CLASE_BIEN 	
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.FAMILIA_BIEN 	= X.FAMILIA_BIEN 	
		  AND SIG_CATALOGO_BIEN_SERV_PRECIO.ITEM_BIEN 		= X.ITEM_BIEN 
		  AND COALESCE(SIG_CATALOGO_BIEN_SERV_PRECIO.PRECIO_REF, 0) <> X.PRECIO_REF 
		  
	IF @@ERROR <> 0
     BEGIN
	  return -1
     END
     		  
					
	/*------------------------*/
	INSERT INTO dbo.SIG_CAT_BIEN_SERV_PRECIO_FASE 
	( SEC_EJEC, 	ANO_EJE, 		TIPO_BIEN, 		GRUPO_BIEN, 	CLASE_BIEN, 	   FAMILIA_BIEN, ITEM_BIEN, 
	  FASE,   		PRECIO_REF, 	UNIDAD_MEDIDA, 	FECHA_REG, 		ESTADO, 		   CUSER_ID, 	 EQUIPO_REG, 
	  INDICADOR, 	FECHA_REF, 		CUSER_MODIF, 	FLAG_PROC_CN, 	precio_ref_origen, flag_proc, 	 flag_cambio, 
	  flag_pase
	)
	SELECT 
	  CPF.SEC_EJEC, CPF.ANNO,     	TCBS.TIPO_BIEN, 		  TCBS.GRUPO_BIEN,		TCBS.CLASE_BIEN,		TCBS.FAMILIA_BIEN, 	  TCBS.ITEM_BIEN, 
	  5, 	  	  	CPF.PRECIO_REF,	TCBS.UNIDAD_MEDIDA, 	  CPF.FECHA_CREACION, 	CASE WHEN CPF.ESTADO ='1' THEN 'A' ELSE 'I' END ,CPF.USUARIO_CREACION, NULL, 
	  '2', 			NULL,			CPF.USUARIO_MODIFICACION, NULL, 				CPF.PRECIO_REF_ANTERIOR,'0', 				  NULL, 
	  '0'
	FROM dbo.TMP_CATALOGO_EJEC_PRECIO_FASE CPF
	JOIN dbo.TMP_CATALOGO_BIEN_SERV TCBS
	ON  TCBS.CATALOGO_NUM 	= CPF.CATALOGO_NUM	
	AND TCBS.ITEM_ID 		= CPF.ITEM_ID 
	WHERE NOT EXISTS ( SELECT 1 FROM dbo.SIG_CAT_BIEN_SERV_PRECIO_FASE CF
						WHERE CF.SEC_EJEC 		= CPF.SEC_EJEC
						AND CF.ANO_EJE 			= CPF.ANNO
						AND CF.TIPO_BIEN 		= TCBS.TIPO_BIEN
						AND CF.GRUPO_BIEN 		= TCBS.GRUPO_BIEN
						AND CF.CLASE_BIEN 		= TCBS.CLASE_BIEN
						AND CF.FAMILIA_BIEN 	= TCBS.FAMILIA_BIEN
						AND CF.ITEM_BIEN 		= TCBS.ITEM_BIEN
						AND CF.FASE 			= 5
						) 
	
	IF @@ERROR <> 0
     BEGIN
	  return -1
     END	
          
    /*------ ACTUALIZA PRECIO POR FASE DE ITEMS EXISTENTES EN EL CLIENTE --------*/
    UPDATE dbo.SIG_CAT_BIEN_SERV_PRECIO_FASE 
	   SET SIG_CAT_BIEN_SERV_PRECIO_FASE.PRECIO_REF = X.PRECIO_REF
	  FROM ( SELECT TCBS.TIPO_BIEN, TCBS.GRUPO_BIEN, TCBS.CLASE_BIEN , TCBS.FAMILIA_BIEN ,TCBS.ITEM_BIEN, TCPF.PRECIO_REF
			   FROM dbo.TMP_CATALOGO_EJEC_PRECIO_FASE TCPF
			   JOIN dbo.TMP_CATALOGO_BIEN_SERV TCBS
				 ON TCBS.CATALOGO_NUM 	= TCPF.CATALOGO_NUM	
				AND TCBS.ITEM_ID 		= TCPF.ITEM_ID 
			  WHERE TCPF.SEC_EJEC = @PN_EJECUTORA
			    AND TCPF.ANNO 	  = @PN_ANIO 
			    AND TCPF.FASE     = 5 ) X
	 WHERE SIG_CAT_BIEN_SERV_PRECIO_FASE.ANO_EJE 		= @PN_ANIO 
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.SEC_EJEC 		= @PN_EJECUTORA 
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.FASE 			= 5 
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.TIPO_BIEN   	= X.TIPO_BIEN 	
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.GRUPO_BIEN 	= X.GRUPO_BIEN 	 
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.CLASE_BIEN 	= X.CLASE_BIEN 	
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.FAMILIA_BIEN 	= X.FAMILIA_BIEN 	
	   AND SIG_CAT_BIEN_SERV_PRECIO_FASE.ITEM_BIEN 		= X.ITEM_BIEN 
	   AND COALESCE(SIG_CAT_BIEN_SERV_PRECIO_FASE.PRECIO_REF, 0) <> X.PRECIO_REF 
    
    IF @@ERROR <> 0
     BEGIN
	  return -1
    END
    
	/*---------CATALOGO POR CENTRO DE COSTO ---------------*/
	INSERT INTO dbo.sig_centro_costo_x_item 
	( ano_eje, 	sec_ejec, 	  centro_costo, 	tipo_bien, 		grupo_bien, 	clase_bien, 	  familia_bien, 	item_bien, 		estado )
	SELECT 
	  CCE.ANNO, CCE.SEC_EJEC, CCE.CENTRO_COSTO, TCBS.TIPO_BIEN, TCBS.GRUPO_BIEN, TCBS.CLASE_BIEN, TCBS.FAMILIA_BIEN, TCBS.ITEM_BIEN, CCE.ESTADO
	FROM dbo.TMP_CENTCOST_CATAEJEC CCE
	JOIN dbo.TMP_CATALOGO_BIEN_SERV TCBS
	  ON TCBS.CATALOGO_NUM 	= CCE.CATALOGO_NUM
	 AND TCBS.ITEM_ID 		= CCE.ITEM_ID 
	WHERE NOT EXISTS (SELECT 1 FROM dbo.SIG_CENTRO_COSTO_X_ITEM CCI
					   WHERE   CCI.ano_eje 		= CCE.anno
						   AND CCI.sec_ejec 	= CCE.sec_ejec
						   AND CCI.centro_costo = CCE.centro_costo
						   AND CCI.tipo_bien 	= TCBS.tipo_bien
						   AND CCI.grupo_bien 	= TCBS.grupo_bien
						   AND CCI.clase_bien 	= TCBS.clase_bien
						   AND CCI.familia_bien = TCBS.familia_bien
						   AND CCI.item_bien 	= TCBS.item_bien	
						  )
	 AND EXISTS (SELECT 1
				  FROM dbo.sig_parametro_ejecutora
				 WHERE sig_parametro_ejecutora.sec_ejec 	= CCE.sec_ejec
				   AND sig_parametro_ejecutora.cod_maestro = 'FLAG_ASIG_ITEM'
				   AND sig_parametro_ejecutora.valor 		= '1'
				) 
 
	IF @@ERROR <> 0
     BEGIN
	  return -1
     END	
 
