				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 3 THEN COALESCE(CNA.CANT_PREV_PRES, 0) ELSE 0 END) AS CANT_PP_ANNO_04,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO THEN COALESCE(CNA.MONTO_PREV_PRES, 0) ELSE 0 END)AS MNTO_PP_ANNO_01,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 1 THEN COALESCE(CNA.MONTO_PREV_PRES, 0) ELSE 0 END)AS MNTO_PP_ANNO_02,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 2 THEN COALESCE(CNA.MONTO_PREV_PRES, 0) ELSE 0 END)AS MNTO_PP_ANNO_03,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 3 THEN COALESCE(CNA.MONTO_PREV_PRES, 0) ELSE 0 END)AS MNTO_PP_ANNO_04,  
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO THEN COALESCE(CNA.CANT_OBLI_FINA, 0) ELSE 0 END) AS CANT_OP_ANNO_01,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 1 THEN COALESCE(CNA.CANT_OBLI_FINA, 0) ELSE 0 END) AS CANT_OP_ANNO_02,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 2 THEN COALESCE(CNA.CANT_OBLI_FINA, 0) ELSE 0 END) AS CANT_OP_ANNO_03,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 3 THEN COALESCE(CNA.CANT_OBLI_FINA, 0) ELSE 0 END) AS CANT_OP_ANNO_04,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO THEN COALESCE(CNA.MONTO_OBLI_FINA, 0) ELSE 0 END)AS MNTO_OP_ANNO_01,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 1 THEN COALESCE(CNA.MONTO_OBLI_FINA, 0) ELSE 0 END)AS MNTO_OP_ANNO_02,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 2 THEN COALESCE(CNA.MONTO_OBLI_FINA, 0) ELSE 0 END)AS MNTO_OP_ANNO_03,
				  SUM(CASE WHEN CNA.ANNO_PROG=@PN_ANIO + 3 THEN COALESCE(CNA.MONTO_OBLI_FINA, 0) ELSE 0 END)AS MNTO_OP_ANNO_04
			  FROM dbo.TMP_CUADRO_NECESIDAD_DET_ANNO CNA, dbo.SIG_CUADRO_NECESIDAD_DET det				
			   WHERE cna.SEC_EJEC 		= det.SEC_EJEC
				 AND CNA.ANNO 			= det.ANO_EJE
				 AND CNA.FASE 			= det.FASE_CUADRO
				 AND CNA.CENTRO_COSTO 	= det.CENTRO_COSTO			  
				 AND CNA.CUADRO_ID 		= det.SECUENCIA
				 AND CNA.CUADRO_DET_ID 	= det.ITEM_SEC
			   	 AND CNA.SEC_EJEC 		= @PN_EJECUTORA 
				 AND CNA.ANNO 			= @PN_ANIO
				 AND CNA.FASE 			= 5
				GROUP BY CNA.CENTRO_COSTO, CNA.CUADRO_ID, CNA.CUADRO_DET_ID
	 		) X
	 	WHERE 
	 		SIG_CUADRO_NECESIDAD_DET.ANO_EJE 		= @PN_ANIO
	 	AND SIG_CUADRO_NECESIDAD_DET.SEC_EJEC 		= @PN_EJECUTORA
	 	AND SIG_CUADRO_NECESIDAD_DET.CENTRO_COSTO 	= X.CENTRO_COSTO
	 	AND SIG_CUADRO_NECESIDAD_DET.SECUENCIA 		= X.CUADRO_ID
	 	AND SIG_CUADRO_NECESIDAD_DET.FASE_CUADRO 	= 5
	 	AND SIG_CUADRO_NECESIDAD_DET.ITEM_SEC 		= X.CUADRO_DET_ID
	 	
	 	IF @@ERROR <> 0
	     BEGIN
		  return -1
	     END
	     	
	/*---------ACTUALIZA MONTO CABECERA CN ---------------*/  	
	UPDATE dbo.SIG_CUADRO_NECESIDAD
		SET TOTAL_APROB 		= COALESCE((DET.MNTO_TOTAL + det.VALOR_IMPTO) , 0),
			MONTO_APROB 		= DET.MNTO_TOTAL,
			MONTO_APROB_ANNO_01 = DET.MNTO_TOTAL_ANNO_01,
			MONTO_APROB_ANNO_02 = DET.MNTO_TOTAL_ANNO_02,
			MONTO_APROB_ANNO_03 = DET.MNTO_TOTAL_ANNO_03
	FROM  (
			SELECT B.MNTO_TOTAL , B.VALOR_IMPTO, B.MNTO_TOTAL_ANNO_01, B.MNTO_TOTAL_ANNO_02, B.MNTO_TOTAL_ANNO_03
			FROM dbo.SIG_CUADRO_NECESIDAD_DET B
			JOIN dbo.SIG_CUADRO_NECESIDAD C
			ON 	 C.ANO_EJE 		= B.ANO_EJE
			AND  C.SEC_EJEC    	= B.SEC_EJEC
			AND  C.CENTRO_COSTO	= B.CENTRO_COSTO
			AND  C.SECUENCIA 	= B.SECUENCIA
			AND  C.FASE_CUADRO 	= B.FASE_CUADRO
		    WHERE B.ANO_EJE     = @PN_ANIO      AND
		          B.SEC_EJEC    = @PN_EJECUTORA AND
				  B.FASE_CUADRO = 5
		) DET
	WHERE 
		SIG_CUADRO_NECESIDAD.ANO_EJE     = @PN_ANIO      AND
   		SIG_CUADRO_NECESIDAD.SEC_EJEC    = @PN_EJECUTORA AND
	 	SIG_CUADRO_NECESIDAD.FASE_CUADRO = 5             AND
		 EXISTS (SELECT A.ANO_EJE
		           FROM dbo.SIG_CUADRO_NECESIDAD_DET A
				  WHERE A.ANO_EJE      = @PN_ANIO      
					AND A.SEC_EJEC     = @PN_EJECUTORA 
					AND A.CENTRO_COSTO = SIG_CUADRO_NECESIDAD.CENTRO_COSTO 
					AND A.FASE_CUADRO  = SIG_CUADRO_NECESIDAD.FASE_CUADRO  
					AND A.SECUENCIA    = SIG_CUADRO_NECESIDAD.SECUENCIA
				)			  	

 	IF @@ERROR <> 0
     BEGIN
	  return -1
     END     
      
   	/*----------TECHO PRESUPUESTO --------------*/    	
   	/* inserta nivel 1 al 5 */
   	INSERT INTO dbo.tmp_techo_presupuesto_upd 
   	( 	SEC_EJEC, 			
