		  CLASIFICADOR, 	  	
		  TP.SEC_FUNC, 		 
		  TP.CENTRO_COSTO, 		
		  TP.CENTRO_COSTO_PRESUP,
		  TP.INDICADOR,  	
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO THEN TP.MNTO_CMN ELSE 0 END) AS MNTO_CMN, 
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO + 1 THEN TP.MNTO_CMN ELSE 0 END) AS MNTO_CMN2,		
