		  TP.MNTO_ACUM_COMM_SIAF,  
		  TP.MNTO_ACUM_DEVGDO_SIAF,  
		  TP.MNTO_RESERVA_PEDIDO,    	  	  	  			
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO THEN TP.MNTO_OPAGO ELSE 0 END) AS MNTO_OPAGO,		
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO + 1 THEN TP.MNTO_OPAGO ELSE 0 END) AS MNTO_OPAGO2,
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO + 2 THEN TP.MNTO_OPAGO ELSE 0 END) AS MNTO_OPAGO3,
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO + 3 THEN TP.MNTO_OPAGO ELSE 0 END) AS MNTO_OPAGO4,
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO THEN TP.MNTO_PREVISION ELSE 0 END) AS MNTO_PREVISION,
		  SUM(CASE WHEN TP.ANNO_PROG=@PN_ANIO + 1 THEN TP.MNTO_PREVISION ELSE 0 END) AS MNTO_PREVISION2,   
