-- ----------------------------
-- function structure for SF_FECHA_ALTA_ORIGEN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SF_FECHA_ALTA_ORIGEN]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[SF_FECHA_ALTA_ORIGEN]
GO

CREATE FUNCTION [dbo].[SF_FECHA_ALTA_ORIGEN] (
@as_nro_baja_error     VARCHAR(50),
@an_tipo_transac       NUMERIC(2, 0),
@al_codigo_alta        INTEGER,
@ad_fecha_alta_origen  DATETIME,
@ad_fecha_alta         DATETIME
)
RETURNS DATETIME
AS
BEGIN
-- Fecha Alta
DECLARE @ld_fecha_alta DATE

BEGIN
	 
	SET @ld_fecha_alta= (CASE COALESCE(LEN(RTRIM(@as_nro_baja_error)),0)
                              WHEN  0 THEN @ad_fecha_alta		
                              ELSE CASE @an_tipo_transac
                                        WHEN  4 THEN COALESCE( @ad_fecha_alta_origen, @ad_fecha_alta)  -- 'NEA - DONACION'
                                        WHEN  5 THEN COALESCE( @ad_fecha_alta_origen, @ad_fecha_alta)  -- 'NEA - TRANSF.EXTERNA'
                                        WHEN  9 THEN CASE @al_codigo_alta   -- 'NEA - OTROS'                                                          
														  WHEN 14 THEN COALESCE( @ad_fecha_alta_origen, @ad_fecha_alta)   -- Llave en Mano Modificado DYH
                                                          ELSE COALESCE( @ad_fecha_alta_origen, @ad_fecha_alta)   -- Por Proyectos
                                                     END
                                        ELSE    @ad_fecha_alta                                         -- 'INGRESO POR COMPRA'
                                   END
                         END)

END
 
--Retorna Fecha Alta Final 
RETURN  @ld_fecha_alta
 
END
GO


-- ----------------------------
-- procedure structure for SP_SIG_INVENTARIO_VALOR_REP
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_INVENTARIO_VALOR_REP]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_INVENTARIO_VALOR_REP]
GO

CREATE PROCEDURE [dbo].[SP_SIG_INVENTARIO_VALOR_REP]
@an_anno_ejec numeric(4), @an_secu_ejec numeric(6), @as_codi_alma varchar(3),
@as_secu_alma varchar(3), @as_tipo_bien varchar(1), @as_grup_bien varchar(2),
@as_clas_bien varchar(2), @as_fami_bien varchar(4), @as_item_bien varchar(4),
@as_tipo_uso  varchar(1), @an_tipo_ppto numeric(1), @an_encargo   numeric(6),
@ad_fech_fin  datetime, @as_usuing varchar(50), @as_mayor varchar(4), @as_subcta varchar(8), @as_message varchar(100) output

------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

AS
DECLARE
@ls_tipo_bien varchar(1),
@ls_grup_bien varchar(2),
@ls_clas_bien varchar(2),
@ls_fami_bien varchar(4),
@ls_item_bien varchar(4),
@ls_nomb_bien varchar(150),
@ls_clas_gast varchar(20),
@ls_cuen_mayo varchar(4),
@ls_cuen_scta varchar(8),
@ls_nomb_marc varchar(100),
@ls_nomb_medi varchar(100),
@ls_tipo_marc varchar(1),
@ls_msg	      varchar(1000),
@ls_tipo_uso  varchar(1),
@ld_codi_marc numeric(5),
@ld_unid_medi numeric(3),
@ld_stoc_actu numeric(20,6),
@ld_valo_actu numeric(16,4),
@ld_prec_actu numeric(16,6),
@ld_secuencia numeric(10),
@ld_secu_ejec2 numeric(6),
@ld_err        numeric(10),
@ls_tipo_movi varchar(1),
@ls_nume_guia varchar(10),
@ls_abre_movi varchar(50),
@ls_moda_alma varchar(1),
@ld_tipo_tran numeric(2),
--@ld_nume_movi numeric(5),
@ld_nume_movi numeric(6),
@ld_nume_orde numeric(7),
@ld_secu_movi numeric(2),
@ld_secu_deta numeric(5),
@ld_cant_arti numeric(20,6),
@ld_valo_arti numeric(16,4),
@ldt_fech_movi datetime,
@ld_item_bien_det numeric(5),
@ls_nomb_item_det varchar(100),
@ls_kardex_clasif varchar(1),
@ld_kardex_verifi  numeric(1)

-- Si parametro existe y esta activo se trabaja sin clasificador en kardex
set @ls_kardex_clasif = 'S'

SELECT @ld_kardex_verifi = count(*)
  FROM sig_maestro_det_numerico 
 WHERE cod_maestro = 'PARAMETRO' AND
       cod_detalle = 1 AND
       @an_anno_ejec >= valor_numerico AND
       estado = 'A'

set @ld_kardex_verifi = isnull(@ld_kardex_verifi, 0)

If (@ld_kardex_verifi > 0)
Begin
	set @ls_kardex_clasif = 'N'
End

--
  SELECT @ls_moda_alma = valor  
    FROM sig_parametro_ejecutora_anio  
   WHERE ano_eje = @an_anno_ejec AND
         sec_ejec = @an_secu_ejec AND 
         cod_maestro = 'TIPO_PROC_ALM'

set @ls_moda_alma = isnull(@ls_moda_alma, '0')
If (@ls_moda_alma = '')
   set @ls_moda_alma = '0'

 DECLARE c_item CURSOR FOR
  SELECT DISTINCT sig_detalle_movim_almacen.tipo_bien,   
         sig_detalle_movim_almacen.grupo_bien,   
         sig_detalle_movim_almacen.clase_bien,   
         sig_detalle_movim_almacen.familia_bien,   
         sig_detalle_movim_almacen.item_bien,   
         catalogo_bien_serv.nombre_item,   
         sig_detalle_movim_almacen.tipo_marca,   
         sig_detalle_movim_almacen.marca,   
         case @ls_kardex_clasif when 'N' then '0' else sig_detalle_movim_almacen.clasificador end as clasificador,   
         sig_detalle_movim_almacen.mayor,   
         sig_detalle_movim_almacen.sub_cta,   
         marca.nombre,   
         sig_detalle_movim_almacen.unidad_medida,   
         unidad_medida.abreviatura,
         sig_detalle_movim_almacen.tipo_uso,
         null as tipo_movimto,
         null as tipo_transac,
         null as nro_movimto,
         null as precio_unit,
         null as nro_guia,
         null as nro_orden,
         null as fecha_movimto,
         null as abrev_movimto,
         null as secuencia,
         null as sec_detalle,
         null as cant_articulo,
         null as valor_total,
         sig_detalle_movim_almacen.item_bien_det
    FROM sig_detalle_movim_almacen,   
         sig_movim_almacen,   
         catalogo_bien_serv,   
         marca,   
         unidad_medida
   WHERE sig_detalle_movim_almacen.tipo_marca = marca.tipo_marca and  
         sig_detalle_movim_almacen.marca = marca.marca and  
         sig_detalle_movim_almacen.unidad_medida = unidad_medida.unidad_medida and  
         sig_detalle_movim_almacen.ano_eje = sig_movim_almacen.ano_eje and  
         sig_detalle_movim_almacen.sec_ejec = sig_movim_almacen.sec_ejec and  
         sig_detalle_movim_almacen.almacen = sig_movim_almacen.almacen and  
         sig_detalle_movim_almacen.sec_almacen = sig_movim_almacen.sec_almacen and  
         sig_detalle_movim_almacen.tipo_movimto = sig_movim_almacen.tipo_movimto and  
         sig_detalle_movim_almacen.tipo_transac = sig_movim_almacen.tipo_transac and  
         sig_movim_almacen.tipo_ppto = sig_detalle_movim_almacen.tipo_ppto and  
         sig_movim_almacen.nro_movimto = sig_detalle_movim_almacen.nro_movimto and  
         sig_detalle_movim_almacen.sec_ejec = catalogo_bien_serv.sec_ejec and  
         sig_detalle_movim_almacen.tipo_bien = catalogo_bien_serv.tipo_bien and  
         sig_detalle_movim_almacen.grupo_bien = catalogo_bien_serv.grupo_bien and  
         sig_detalle_movim_almacen.clase_bien = catalogo_bien_serv.clase_bien and  
         sig_detalle_movim_almacen.familia_bien = catalogo_bien_serv.familia_bien and  
         sig_detalle_movim_almacen.item_bien = catalogo_bien_serv.item_bien and  
         sig_detalle_movim_almacen.ano_eje = @an_anno_ejec AND  
         sig_detalle_movim_almacen.sec_ejec = @an_secu_ejec AND  
         sig_detalle_movim_almacen.almacen = @as_codi_alma AND  
         sig_detalle_movim_almacen.sec_almacen = @as_secu_alma AND  
         sig_detalle_movim_almacen.tipo_movimto in ('A','I','S') AND  
         sig_detalle_movim_almacen.tipo_bien = @as_tipo_bien AND  
         sig_detalle_movim_almacen.grupo_bien like @as_grup_bien AND  
         sig_detalle_movim_almacen.clase_bien like @as_clas_bien AND  
         sig_detalle_movim_almacen.familia_bien like @as_fami_bien AND  
         sig_detalle_movim_almacen.item_bien like @as_item_bien AND  
         sig_detalle_movim_almacen.tipo_uso like @as_tipo_uso AND  
         sig_movim_almacen.tipo_ppto = @an_tipo_ppto AND  
         ((@an_tipo_ppto = 1) OR  
          (@an_tipo_ppto = 2 AND sig_movim_almacen.nro_encargo = @an_encargo)) AND  
         sig_movim_almacen.estado_kardex = 'S' AND  
         sig_detalle_movim_almacen.fecha_movimto <= @ad_fech_fin and
         @ls_moda_alma <> '1' AND 
         sig_detalle_movim_almacen.mayor like @as_mayor AND 
         sig_detalle_movim_almacen.sub_cta like @as_subcta 
         
   UNION 
  SELECT DISTINCT sig_detalle_movim_almacen.tipo_bien,   
         sig_detalle_movim_almacen.grupo_bien,   
         sig_detalle_movim_almacen.clase_bien,   
         sig_detalle_movim_almacen.familia_bien,   
         sig_detalle_movim_almacen.item_bien,   
         catalogo_bien_serv.nombre_item,   
         sig_detalle_movim_almacen.tipo_marca,   
         sig_detalle_movim_almacen.marca,   
         case @ls_kardex_clasif when 'N' then '0' else sig_detalle_movim_almacen.clasificador end as clasificador,   
         sig_detalle_movim_almacen.mayor,   
         sig_detalle_movim_almacen.sub_cta,   
         marca.nombre,   
         sig_detalle_movim_almacen.unidad_medida,   
         unidad_medida.abreviatura,
         sig_detalle_movim_almacen.tipo_uso,
         sig_detalle_movim_almacen.tipo_movimto,
         sig_detalle_movim_almacen.tipo_transac,
         sig_detalle_movim_almacen.nro_movimto,
         sig_detalle_movim_almacen.precio_unit,
         sig_movim_almacen.nro_guia,
         sig_movim_almacen.nro_orden,
         sig_detalle_movim_almacen.fecha_movimto,
         sig_tipo_movimiento.abrev_movimto,
         sig_detalle_movim_almacen.secuencia,
         sig_detalle_movim_almacen.sec_detalle,
         sig_detalle_movim_almacen.cant_articulo,
         sig_detalle_movim_almacen.valor_total,
         sig_detalle_movim_almacen.item_bien_det
    FROM sig_detalle_movim_almacen,   
         sig_movim_almacen,   
         sig_tipo_movimiento,   
         catalogo_bien_serv,   
         marca,   
         unidad_medida
   WHERE sig_detalle_movim_almacen.tipo_marca = marca.tipo_marca and  
         sig_detalle_movim_almacen.marca = marca.marca and  
         sig_detalle_movim_almacen.unidad_medida = unidad_medida.unidad_medida and  
         sig_detalle_movim_almacen.ano_eje = sig_movim_almacen.ano_eje and  
         sig_detalle_movim_almacen.sec_ejec = sig_movim_almacen.sec_ejec and  
         sig_detalle_movim_almacen.almacen = sig_movim_almacen.almacen and  
         sig_detalle_movim_almacen.sec_almacen = sig_movim_almacen.sec_almacen and  
         sig_detalle_movim_almacen.tipo_movimto = sig_movim_almacen.tipo_movimto and  
         sig_detalle_movim_almacen.tipo_transac = sig_movim_almacen.tipo_transac and  
         sig_movim_almacen.tipo_ppto = sig_detalle_movim_almacen.tipo_ppto and  
         sig_movim_almacen.nro_movimto = sig_detalle_movim_almacen.nro_movimto and  
         sig_movim_almacen.tipo_movimto = sig_tipo_movimiento.tipo_movimto and  
         sig_movim_almacen.tipo_transac = sig_tipo_movimiento.tipo_transac and  
         sig_detalle_movim_almacen.sec_ejec = catalogo_bien_serv.sec_ejec and  
         sig_detalle_movim_almacen.tipo_bien = catalogo_bien_serv.tipo_bien and  
         sig_detalle_movim_almacen.grupo_bien = catalogo_bien_serv.grupo_bien and  
         sig_detalle_movim_almacen.clase_bien = catalogo_bien_serv.clase_bien and  
         sig_detalle_movim_almacen.familia_bien = catalogo_bien_serv.familia_bien and  
         sig_detalle_movim_almacen.item_bien = catalogo_bien_serv.item_bien and  
         sig_detalle_movim_almacen.ano_eje = @an_anno_ejec AND  
         sig_detalle_movim_almacen.sec_ejec = @an_secu_ejec AND  
         sig_detalle_movim_almacen.almacen = @as_codi_alma AND  
         sig_detalle_movim_almacen.sec_almacen = @as_secu_alma AND  
         sig_detalle_movim_almacen.tipo_movimto in ('A','I') AND  
         sig_detalle_movim_almacen.tipo_bien = @as_tipo_bien AND  
         sig_detalle_movim_almacen.grupo_bien like @as_grup_bien AND  
         sig_detalle_movim_almacen.clase_bien like @as_clas_bien AND  
         sig_detalle_movim_almacen.familia_bien like @as_fami_bien AND  
         sig_detalle_movim_almacen.item_bien like @as_item_bien AND  
         sig_detalle_movim_almacen.tipo_uso like @as_tipo_uso AND  
         sig_movim_almacen.tipo_ppto = @an_tipo_ppto AND  
         ((@an_tipo_ppto = 1) OR  
          (@an_tipo_ppto = 2 AND sig_movim_almacen.nro_encargo = @an_encargo)) AND  
         sig_movim_almacen.estado_kardex = 'S' AND  
         sig_detalle_movim_almacen.fecha_movimto <= @ad_fech_fin AND
         @ls_moda_alma = '1' and
         sig_detalle_movim_almacen.mayor like @as_mayor AND 
         sig_detalle_movim_almacen.sub_cta like @as_subcta 

set @ld_secu_ejec2 = null
set @ld_secuencia = 0

Open c_item
FETCH NEXT FROM c_item into @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien, @ls_item_bien,   
				@ls_nomb_bien, @ls_tipo_marc, @ld_codi_marc, @ls_clas_gast, @ls_cuen_mayo,
				@ls_cuen_scta, @ls_nomb_marc, @ld_unid_medi, @ls_nomb_medi, @ls_tipo_uso,
				@ls_tipo_movi, @ld_tipo_tran, @ld_nume_movi, @ld_prec_actu, @ls_nume_guia,
				@ld_nume_orde, @ldt_fech_movi, @ls_abre_movi, @ld_secu_movi, @ld_secu_deta,
				@ld_stoc_actu, @ld_valo_actu, @ld_item_bien_det

WHILE @@FETCH_STATUS = 0
BEGIN
	if (@ls_moda_alma <> '1')
	begin
		set @ld_stoc_actu = 0
		set @ld_valo_actu = 0
		set @ld_prec_actu = 0

		DECLARE c_valor CURSOR FOR
		  SELECT sig_detalle_movim_almacen.stock_actual,   
		         sig_detalle_movim_almacen.valor_actual,   
		         sig_detalle_movim_almacen.precio_promed
		    FROM sig_detalle_movim_almacen,   
		         sig_movim_almacen
		   WHERE sig_detalle_movim_almacen.ano_eje  = sig_movim_almacen.ano_eje and  
		         sig_detalle_movim_almacen.sec_ejec = sig_movim_almacen.sec_ejec and  
		         sig_detalle_movim_almacen.almacen  = sig_movim_almacen.almacen and  
		         sig_detalle_movim_almacen.sec_almacen  = sig_movim_almacen.sec_almacen and  
		         sig_detalle_movim_almacen.tipo_movimto = sig_movim_almacen.tipo_movimto and  
		         sig_detalle_movim_almacen.tipo_transac = sig_movim_almacen.tipo_transac and  
		         sig_movim_almacen.tipo_ppto   = sig_detalle_movim_almacen.tipo_ppto and  
		         sig_movim_almacen.nro_movimto = sig_detalle_movim_almacen.nro_movimto and  
		         sig_detalle_movim_almacen.ano_eje  = @an_anno_ejec AND  
		         sig_detalle_movim_almacen.sec_ejec = @an_secu_ejec AND  
		         sig_detalle_movim_almacen.almacen  = @as_codi_alma AND  
		         sig_detalle_movim_almacen.sec_almacen = @as_secu_alma AND  
		         sig_detalle_movim_almacen.tipo_movimto in ('A','I','S') AND  
		         sig_detalle_movim_almacen.tipo_bien  = @ls_tipo_bien AND  
		         sig_detalle_movim_almacen.grupo_bien = @ls_grup_bien AND  
		         sig_detalle_movim_almacen.clase_bien = @ls_clas_bien AND  
		         sig_detalle_movim_almacen.familia_bien = @ls_fami_bien AND  
		         sig_detalle_movim_almacen.item_bien = @ls_item_bien AND  
		         sig_detalle_movim_almacen.marca = @ld_codi_marc AND
		         ((@ls_kardex_clasif = 'S' and sig_detalle_movim_almacen.clasificador = @ls_clas_gast) or
		          (@ls_kardex_clasif = 'N')) AND
		         sig_detalle_movim_almacen.mayor = @ls_cuen_mayo AND
		         sig_detalle_movim_almacen.sub_cta = @ls_cuen_scta AND
		         sig_detalle_movim_almacen.tipo_uso = @ls_tipo_uso AND  
		         sig_movim_almacen.tipo_ppto = @an_tipo_ppto AND  
		         ((@an_tipo_ppto = 1) OR  
		          (@an_tipo_ppto = 2 AND sig_movim_almacen.nro_encargo = @an_encargo)) AND  
		         sig_movim_almacen.estado_kardex = 'S' AND  
		         sig_detalle_movim_almacen.fecha_movimto <= @ad_fech_fin AND
		         sig_detalle_movim_almacen.unidad_medida = @ld_unid_medi AND
		         ((@ld_item_bien_det is null and sig_detalle_movim_almacen.item_bien_det is null) or
		          (@ld_item_bien_det is not null and sig_detalle_movim_almacen.item_bien_det = @ld_item_bien_det))
		ORDER BY sig_detalle_movim_almacen.fecha_movimto DESC,   
		         sig_detalle_movim_almacen.fecha_reg DESC,   
		         sig_detalle_movim_almacen.tipo_movimto DESC,   
		         sig_detalle_movim_almacen.tipo_transac DESC,   
		         sig_movim_almacen.nro_movimto DESC
	
		Open c_valor
		Fetch next from c_valor into @ld_stoc_actu, @ld_valo_actu, @ld_prec_actu
		Close c_valor
		DEALLOCATE c_valor
	End

	If (@ls_moda_alma = '1')
	Begin
		set @ld_cant_arti = 0
		set @ld_valo_arti = 0
		
		  SELECT @ld_cant_arti = sum(d.cant_articulo),
			 @ld_valo_arti = sum(d.valor_total)
		    FROM sig_detalle_movim_almacen d,
			 sig_movim_almacen m
		   WHERE d.ano_eje      = m.ano_eje  and
			 d.sec_ejec     = m.sec_ejec and
			 d.almacen      = m.almacen  and
			 d.sec_almacen  = m.sec_almacen  and
			 d.tipo_movimto = m.tipo_movimto and
			 d.tipo_transac = m.tipo_transac and
			 d.tipo_ppto    = m.tipo_ppto    and
			 d.nro_movimto  = m.nro_movimto  and
			 m.estado_kardex= 'S' and
			 d.ano_eje      = @an_anno_ejec and
			 d.sec_ejec     = @an_secu_ejec and
			 d.almacen      = @as_codi_alma and
			 d.sec_almacen  = @as_secu_alma and
			 d.tipo_movimto = 'S' and
			 d.cant_articulo >= 0 and
			 m.tipo_origen  = '0' and
			 d.tipo_movimto_orig = @ls_tipo_movi and
			 d.tipo_transac_orig = @ld_tipo_tran and
			 d.tipo_ppto_orig    = @an_tipo_ppto and
			 d.nro_movimto_orig  = @ld_nume_movi and
			 d.secuencia_orig    = @ld_secu_movi and
			 d.sec_detalle_orig  = @ld_secu_deta and
			 d.fecha_movimto <= @ad_fech_fin
		
		IF (@@error <> 0)
		begin
			close c_item
			DEALLOCATE c_item
			set @as_message = 'No se puede obtener las salidas para el método PEPS.'
			return -1
		End

		set @ld_cant_arti = isnull(@ld_cant_arti, 0)
		set @ld_valo_arti = isnull(@ld_valo_arti, 0)

		set @ld_stoc_actu = @ld_stoc_actu - @ld_cant_arti
		set @ld_valo_actu = @ld_valo_actu - @ld_valo_arti
		
	End
	
	If (@ld_stoc_actu <> 0 or @ld_valo_actu <> 0)
	Begin
		set @ld_item_bien_det = isnull(@ld_item_bien_det, 0)
		set @ls_nomb_item_det = ''

		If (@ld_item_bien_det > 0)
		       SELECT @ls_nomb_item_det = nombre  
			 FROM sig_item_atributo  
			WHERE sec_ejec   = @an_secu_ejec AND  
				tipo_bien  = @ls_tipo_bien AND  
				grupo_bien = @ls_grup_bien AND  
				clase_bien = @ls_clas_bien AND  
				familia_bien  = @ls_fami_bien AND  
				item_bien     = @ls_item_bien AND  
				item_bien_det = @ld_item_bien_det

		set @ld_secuencia = @ld_secuencia + 1

		INSERT INTO sig_tmp_rep_inv_valorizado  
		( id, ano_eje, sec_ejec, almacen, sec_almacen, tipo_uso, tipo_ppto,   
		  secuencia, nro_encargo, sec_ejec2, tipo_bien, grupo_bien, clase_bien,   
		  familia_bien, item_bien, nombre_item, tipo_marca, marca, nombre_marca,   
		  unidad_medida, nombre_medida, clasificador, mayor, sub_cta, nro_lote,   
		  fecha_expiracion, stock_lote, stock_actual, precio_actual, valor_actual,
		  tipo_movimto, tipo_transac, nro_movimto, nro_guia, nro_orden,
		  fecha_movimto, nombre_movimto, item_bien_det, item_bien_atributo)
		VALUES ( @as_usuing, @an_anno_ejec, @an_secu_ejec, @as_codi_alma, @as_secu_alma, @ls_tipo_uso, @an_tipo_ppto,
		  @ld_secuencia, @an_encargo,   @ld_secu_ejec2, @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien,
		  @ls_fami_bien, @ls_item_bien, @ls_nomb_bien, @ls_tipo_marc, @ld_codi_marc, @ls_nomb_marc,
		  @ld_unid_medi, @ls_nomb_medi, @ls_clas_gast, @ls_cuen_mayo, @ls_cuen_scta, null,   
		  null, 0, @ld_stoc_actu, @ld_prec_actu, @ld_valo_actu,
		  @ls_tipo_movi, @ld_tipo_tran, @ld_nume_movi, @ls_nume_guia, @ld_nume_orde,
		  @ldt_fech_movi, @ls_abre_movi, @ld_item_bien_det, @ls_nomb_item_det)

		IF (@@error <> 0)
		begin
			close c_item
			DEALLOCATE c_item
			set @as_message = 'No se puede insertar el detalle del reporte.'
			return -1
		End
	End

	FETCH NEXT FROM c_item into @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien, @ls_item_bien,   
				@ls_nomb_bien, @ls_tipo_marc, @ld_codi_marc, @ls_clas_gast, @ls_cuen_mayo,
				@ls_cuen_scta, @ls_nomb_marc, @ld_unid_medi, @ls_nomb_medi, @ls_tipo_uso,
				@ls_tipo_movi, @ld_tipo_tran, @ld_nume_movi, @ld_prec_actu, @ls_nume_guia,
				@ld_nume_orde, @ldt_fech_movi, @ls_abre_movi, @ld_secu_movi, @ld_secu_deta,
				@ld_stoc_actu, @ld_valo_actu, @ld_item_bien_det
END
CLOSE c_item
DEALLOCATE c_item

set @as_message = 'Concluyó conforme : '

Return 1
GO


