CREATE PROCEDURE [dbo].[SP_GENERA_PAO_INGRESO] (

--DECLARE
	@PN_ANIO NUMERIC
	,@PN_EJECUTORA NUMERIC
	,@PN_NRO_PAO NUMERIC
	,@ps_tipo_generacion VARCHAR(1)
	,@PS_TIPO VARCHAR(1)
	,@PS_MES_INI INT
	,@PS_MES_FIN INT
	,@ps_especif VARCHAR(100)
	,@ps_opcion_pao VARCHAR(1)
	,@ps_tipo_compra VARCHAR(1)
	,@ps_modal_compra VARCHAR(2)
	,@PS_USUARIO VARCHAR(30)
	,@PN_SEC_PAO NUMERIC
	)
AS

/*
Control de Modificaciones:
- Versión: 24.03.00     - SRF       - Modificado por: MPalacios     - Fecha: 02/10/2024     - Ajuste: Ampliación del campo NRO_PAAC y cálculo de máximo valor NRO_PAAC
*/   
DECLARE @ls_moneda VARCHAR(5)
	,@ls_pais VARCHAR(4)
	,@ls_depa VARCHAR(2)
	,@ls_prov VARCHAR(2)
	,@ls_dist VARCHAR(2)
	,@ls_estado VARCHAR(1)
	,@ld_tipo_Camb NUMERIC(2)
	,@ldt_fecha_Cons DATETIME
	,@ls_equipo VARCHAR(20)
	,@li_secu_cons VARCHAR(2)
	,@ls_tipo_cons CHAR(1)
	,@li_unidad_med_cons INT
	,@ls_tipo_organismo VARCHAR(2)
	,@PN_MAX_SEC_RESUMEN NUMERIC(6)
	,@li_cont NUMERIC(2)

------ Valores iniciales ------------  
SET NOCOUNT ON

SELECT @ls_moneda = 'S/.'
SELECT @ls_pais = '4028'
SELECT @ls_depa = '15'
SELECT @ls_prov = '01'
SELECT @ls_dist = '01'
SELECT @ls_estado = '0'
SELECT @ld_tipo_Camb = 1
SELECT @ls_tipo_cons = '1'
SELECT @li_secu_cons = '01'
SELECT @ldt_fecha_Cons = GETDATE()
SELECT @ls_equipo = ''
SELECT @ls_tipo_organismo = '01'

SELECT @li_unidad_med_cons = CASE 
		WHEN @PS_TIPO = 'B'
			THEN 112
		ELSE 113
		END

-- Inserta Secuencia PAAC   
SELECT @li_secu_cons = 1

