FROM SIG_CUADRO_NECESIDAD C
	,SIG_CUADRO_NECESIDAD_DET D
	,CATALOGO_BIEN_SERV S
WHERE D.ANO_EJE = @PN_ANIO
	AND D.SEC_EJEC = @PN_EJECUTORA
	AND EXISTS (
		SELECT CENTRO_COSTO
		FROM tmp_parametros_pao
		WHERE CODIGO = 5
			AND NRO_PAO = @PN_NRO_PAO
			AND centro_costo = D.CENTRO_COSTO
		)
	AND EXISTS (
		SELECT TIPO_TAREA
		FROM tmp_parametros_pao
		WHERE CODIGO = 6
			AND NRO_PAO = @PN_NRO_PAO
			AND TIPO_TAREA = C.TIPO_TAREA
			AND CODIGO_TAREA = C.CODIGO_TAREA
			AND TIPO_USO = C.TIPO_USO				
		)
	AND (
		(
			D.FASE_CUADRO = 3
			AND @PN_ANIO <= 2011
			)
		OR (
			D.FASE_CUADRO = 5
			AND @PN_ANIO >= 2012
			)
		)
	AND D.TIPO_BIEN = @PS_TIPO
	AND (
		EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN)
			)
		)
	AND D.ESTADO = '5'	
	AND D.estado_item_kit = 'A'
	AND EXISTS (
		SELECT FUENTE
		FROM tmp_parametros_pao
		WHERE CODIGO = 3
			AND NRO_PAO = @PN_NRO_PAO
			AND Fuente = C.FUENTE_FINANC
		)
	AND EXISTS (
		SELECT CLASIFICADOR
		FROM tmp_parametros_pao
		WHERE CODIGO = 2
			AND NRO_PAO = @PN_NRO_PAO
			AND CLASIFICADOR = C.CLASIFICADOR
		)
	AND EXISTS (
		SELECT SEC_FUNC
		FROM tmp_parametros_pao
		WHERE CODIGO = 4
			AND NRO_PAO = @PN_NRO_PAO
			AND SEC_FUNC = C.SEC_FUNC
		)
	AND (
		(
			@ps_modal_compra = 'SI'
			AND S.FLAG_SUBASTA_INVERSA = '1'
			)
		OR (
			@ps_modal_compra = 'CP'
			AND S.BOLSA_PRODUCTO = '1'
			)
		OR (
			@ps_modal_compra = 'MP'
			AND S.FLAG_MARCO_PRECIO = 'S'
			)
		OR (
			@ps_modal_compra NOT IN (
				'SI'
				,'CP'
				,'MP'
				)
			AND (
				S.FLAG_SUBASTA_INVERSA <> '1'
				OR S.FLAG_SUBASTA_INVERSA IS NULL
				)
			AND (
				S.BOLSA_PRODUCTO <> '1'
				OR S.BOLSA_PRODUCTO IS NULL
				)
			AND (
				S.FLAG_MARCO_PRECIO <> 'S'
				OR S.FLAG_MARCO_PRECIO IS NULL
				)
			)
		)
	AND D.ANO_EJE = C.ANO_EJE
	AND D.SEC_EJEC = C.SEC_EJEC
	AND D.CENTRO_COSTO = C.CENTRO_COSTO
	AND D.FASE_CUADRO = C.FASE_CUADRO
	AND D.SECUENCIA = C.SECUENCIA
	AND S.SEC_EJEC = D.SEC_EJEC
	AND S.TIPO_BIEN = D.TIPO_BIEN
	AND S.GRUPO_BIEN = D.GRUPO_BIEN
	AND S.CLASE_BIEN = D.CLASE_BIEN
	AND S.FAMILIA_BIEN = D.FAMILIA_BIEN
	AND S.ITEM_BIEN = D.ITEM_BIEN
	AND not exists (SELECT 1 FROM sig_paac_item item
					WHERE item.ANO_EJE = D.ANO_EJE AND
						  item.SEC_EJEC = D.SEC_EJEC AND
						  item.TIPO_CONSOLID = '1'  AND
						  item.NRO_CONSOLID = @PN_NRO_PAO AND
						  item.TIPO_GENERACION = @ps_tipo_generacion AND
						  item.TIPO_BIEN = D.TIPO_BIEN AND
						  item.SEC_CONSOLID = 1 AND
						  item.GRUPO_BIEN = D.GRUPO_BIEN AND
						  item.CLASE_BIEN = D.CLASE_BIEN AND
						  item.FAMILIA_BIEN = D.FAMILIA_BIEN AND
						  item.ITEM_BIEN = D.ITEM_BIEN						  
						  )
GROUP BY D.TIPO_BIEN
	,D.GRUPO_BIEN
	,D.CLASE_BIEN
	,D.FAMILIA_BIEN
	,D.ITEM_BIEN
	,D.UNIDAD_MEDIDA

IF @@ROWCOUNT = 0
	RETURN

SELECT @PN_MAX_SEC_RESUMEN = MAX(SEC_RESUMEN)
FROM SIG_PAAC_ITEM
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND TIPO_BIEN = @PS_TIPO
	--AND SEC_CONSOLID = @PN_SEC_PAO

IF @PN_MAX_SEC_RESUMEN IS NULL
BEGIN
	SELECT @PN_MAX_SEC_RESUMEN = 0
END

UPDATE #TMP_SIG_PAAC_ITEM
SET SEC_RESUMEN1 = SEC_RESUMEN2 + @PN_MAX_SEC_RESUMEN
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND TIPO_BIEN = @PS_TIPO
	AND SEC_CONSOLID = @PN_SEC_PAO


IF @@ROWCOUNT = 0
	RETURN

