		END AS cant_12_anno_03
FROM sig_cuadro_necesidad C
	,sig_cuadro_necesidad_Det D
	,#TMP_SIG_PAAC_ITEM i
WHERE I.ANO_EJE = D.ANO_EJE
	AND I.SEC_EJEC = D.SEC_EJEC
	AND i.item_bien = d.item_bien
	AND i.grupo_bien = d.grupo_bien
	AND i.clase_bien = d.clase_bien
	AND i.familia_bien = d.familia_bien
	AND i.item_bien = d.item_bien
	AND I.NRO_CONSOLID = @PN_NRO_PAO
	AND (C.ANO_EJE = @PN_ANIO)
	AND (C.SEC_EJEC = @PN_EJECUTORA)
	AND (D.TIPO_BIEN = @PS_TIPO)
	AND (D.ESTADO = '5')
	AND EXISTS (
		SELECT FUENTE
		FROM tmp_parametros_pao
		WHERE CODIGO = 3
			AND NRO_PAO = @PN_NRO_PAO
			AND Fuente = C.FUENTE_FINANC
		)
	AND EXISTS (
		SELECT CLASIFICADOR
		FROM tmp_parametros_pao
		WHERE CODIGO = 2
			AND NRO_PAO = @PN_NRO_PAO
			AND CLASIFICADOR = C.CLASIFICADOR
		)
	AND EXISTS (
		SELECT SEC_FUNC
		FROM tmp_parametros_pao
		WHERE CODIGO = 4
			AND NRO_PAO = @PN_NRO_PAO
			AND SEC_FUNC = C.SEC_FUNC
		)
	AND EXISTS (
		SELECT CENTRO_COSTO
		FROM tmp_parametros_pao
		WHERE CODIGO = 5
			AND NRO_PAO = @PN_NRO_PAO
			AND centro_costo = D.CENTRO_COSTO
		)
	AND EXISTS (
		SELECT TIPO_TAREA
		FROM tmp_parametros_pao
		WHERE CODIGO = 6
			AND NRO_PAO = @PN_NRO_PAO
			AND TIPO_TAREA = C.TIPO_TAREA
			AND CODIGO_TAREA = C.CODIGO_TAREA
			AND TIPO_USO = C.TIPO_USO				
		)
	AND (
		(
			D.FASE_CUADRO = 3
			AND @PN_ANIO <= 2011
			)
		OR (
			D.FASE_CUADRO = 5
			AND @PN_ANIO >= 2012
			)
		)
	AND (
		EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN)
			)
		)
	AND (D.ano_eje = C.ano_eje)
	AND (D.sec_ejec = C.sec_ejec)
	AND (D.centro_costo = C.centro_costo)
	AND (D.FASE_CUADRO = C.FASE_CUADRO)
	AND (D.secuencia = C.secuencia)
	AND
	/*( D.mnto_total   > 0 ) and*/
	(COALESCE(D.MNTO_TOTAL, 0) + COALESCE(D.MNTO_TOTAL_ANNO_01, 0) + COALESCE(D.MNTO_TOTAL_ANNO_02, 0) + COALESCE(D.MNTO_TOTAL_ANNO_03, 0)) > 0
	AND (D.estado_item_kit = 'A')
GROUP BY C.sec_func
	,C.origen
	,C.fuente_financ
	,C.clasificador
	,C.tipo_impuesto
	,C.tasa_impto
	,CASE 
		WHEN C.fuente_impto IS NULL
			OR RTRIM(LTRIM(C.fuente_impto)) = ''
			THEN NULL
		ELSE C.fuente_impto
		END
	,sec_resumen1

DECLARE @SEC_RESUMEN NUMERIC(5, 0)
	,@SEC_META1 NUMERIC(5, 0)
	,@NUM INT
	,@SEC_RESUMEN_ANT NUMERIC(5, 0)

DECLARE CUR_META CURSOR
FOR
SELECT SEC_RESUMEN
	,SEC_META1
FROM #TMP_SIG_PAAC_METAS
WHERE EXISTS (
		SELECT SEC_RESUMEN
		FROM #TMP_SIG_PAAC_METAS
		GROUP BY SEC_RESUMEN
		HAVING COUNT(*) > 1
		)
ORDER BY SEC_RESUMEN

OPEN CUR_META

FETCH CUR_META
INTO @SEC_RESUMEN
	,@SEC_META1

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @NUM = 1

	SELECT @SEC_RESUMEN_ANT = @SEC_RESUMEN

	WHILE @@FETCH_STATUS = 0
		AND @SEC_RESUMEN_ANT = @SEC_RESUMEN
	BEGIN
		UPDATE #TMP_SIG_PAAC_METAS
		SET SEC_META = @NUM
		WHERE SEC_META1 = @SEC_META1

		SELECT @NUM = @NUM + 1

		FETCH CUR_META
		INTO @SEC_RESUMEN
			,@SEC_META1
	END
END

CLOSE CUR_META

DEALLOCATE CUR_META

UPDATE #TMP_SIG_PAAC_METAS
SET SEC_META = 1
WHERE SEC_META IS NULL

