FROM SIG_CUADRO_necesidad C
	,SIG_CUADRO_necesidad_det D
	,#TMP_SIG_PAAC_ITEM i
	,#TMP_SIG_PAAC_METAS m
WHERE I.ANO_EJE = D.ANO_EJE
	AND I.SEC_EJEC = D.SEC_EJEC
	AND i.item_bien = d.item_bien
	AND i.grupo_bien = d.grupo_bien
	AND i.clase_bien = d.clase_bien
	AND i.familia_bien = d.familia_bien
	AND i.item_bien = d.item_bien
	AND I.NRO_CONSOLID = @PN_NRO_PAO
	AND I.SEC_RESUMEN1 = M.SEC_RESUMEN
	AND M.SEC_FUNC = C.SEC_FUNC
	AND M.FUENTE_FINANC = C.FUENTE_FINANC
	AND M.CLASIFICADOR = C.CLASIFICADOR
	AND (D.ANO_EJE = C.ANO_EJE)
	AND (D.SEC_EJEC = C.SEC_EJEC)
	AND (D.CENTRO_COSTO = C.CENTRO_COSTO)
	AND (D.fase_cuadro = C.fase_cuadro)
	AND (D.SECUENCIA = C.SECUENCIA)
	AND (C.ANO_EJE = @PN_ANIO)
	AND (C.SEC_EJEC = @PN_EJECUTORA)
	AND (D.TIPO_BIEN = @PS_TIPO)
	AND (D.ESTADO = '5')
	AND EXISTS (
		SELECT FUENTE
		FROM tmp_parametros_pao
		WHERE CODIGO = 3
			AND NRO_PAO = @PN_NRO_PAO
			AND Fuente = C.FUENTE_FINANC
		)
	AND EXISTS (
		SELECT CLASIFICADOR
		FROM tmp_parametros_pao
		WHERE CODIGO = 2
			AND NRO_PAO = @PN_NRO_PAO
			AND CLASIFICADOR = C.CLASIFICADOR
		)
	AND EXISTS (
		SELECT SEC_FUNC
		FROM tmp_parametros_pao
		WHERE CODIGO = 4
			AND NRO_PAO = @PN_NRO_PAO
			AND SEC_FUNC = C.SEC_FUNC
		)
	AND EXISTS (
		SELECT CENTRO_COSTO
		FROM tmp_parametros_pao
		WHERE CODIGO = 5
			AND NRO_PAO = @PN_NRO_PAO
			AND centro_costo = D.CENTRO_COSTO
		)
	AND EXISTS (
		SELECT TIPO_TAREA
		FROM tmp_parametros_pao
		WHERE CODIGO = 6
			AND NRO_PAO = @PN_NRO_PAO
			AND TIPO_TAREA = C.TIPO_TAREA
			AND CODIGO_TAREA = C.CODIGO_TAREA
			AND TIPO_USO = C.TIPO_USO				
		)
	AND (
		(
			D.FASE_CUADRO = 3
			AND @PN_ANIO <= 2011
			)
		OR (
			D.FASE_CUADRO = 5
			AND @PN_ANIO >= 2012
			)
		)
	AND (
		EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN)
			)
		OR EXISTS (
			SELECT ITEM
			FROM tmp_parametros_pao
			WHERE CODIGO = 1
				AND NRO_PAO = @PN_NRO_PAO
				AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN)
			)
		)
	AND
	/*( D.MNTO_TOTAL > 0 ) and*/
	(COALESCE(D.MNTO_TOTAL, 0) + COALESCE(D.MNTO_TOTAL_ANNO_01, 0) + COALESCE(D.MNTO_TOTAL_ANNO_02, 0) + COALESCE(D.MNTO_TOTAL_ANNO_03, 0)) > 0
	AND (D.estado_item_kit = 'A')
GROUP BY D.CENTRO_COSTO
	,C.TIPO_TAREA
	,C.CODIGO_TAREA
	,C.TIPO_IMPuesTO
	,C.TASA_IMPTO
	,CASE 
		WHEN C.fuente_impto IS NULL
			OR RTRIM(LTRIM(C.fuente_impto)) = ''
			THEN NULL
		ELSE C.fuente_impto
		END
	,C.NIVEL_TAREA
	,I.SEC_RESUMEN1
	,M.SEC_META
	,C.TIPO_USO
	,C.MAYOR
	,C.SUB_CTA_DET

DECLARE @SEC_META NUMERIC(5, 0)
	,@SEC_CTRO_COSTO1 NUMERIC(5, 0)
	,@SEC_META_ANT VARCHAR(100)

DECLARE CUR_CC CURSOR
FOR
SELECT T.SEC_RESUMEN
	,T.SEC_META
	,T.SEC_CTRO_COSTO1
FROM #TMP_SIG_PAAC_CENTRO_COSTO T
	,(
		SELECT SEC_RESUMEN
			,SEC_META
		FROM #TMP_SIG_PAAC_CENTRO_COSTO
		GROUP BY SEC_RESUMEN
			,SEC_META
		HAVING COUNT(*) > 1
		) A
WHERE T.SEC_RESUMEN = A.SEC_RESUMEN
	AND T.SEC_META = A.SEC_META
ORDER BY T.SEC_RESUMEN
	,T.SEC_META

OPEN CUR_CC

FETCH CUR_CC
INTO @SEC_RESUMEN
	,@SEC_META
	,@SEC_CTRO_COSTO1

WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @NUM = 1

	SELECT @SEC_META_ANT = LTRIM(STR(@SEC_RESUMEN)) + LTRIM(STR(@SEC_META))

	WHILE @@FETCH_STATUS = 0
		AND @SEC_META_ANT = LTRIM(STR(@SEC_RESUMEN)) + LTRIM(STR(@SEC_META))
	BEGIN
		UPDATE #TMP_SIG_PAAC_CENTRO_COSTO
		SET SEC_CTRO_COSTO = @NUM
		WHERE SEC_RESUMEN = @SEC_RESUMEN
			AND SEC_META = @SEC_META
			AND SEC_CTRO_COSTO1 = @SEC_CTRO_COSTO1

		SELECT @NUM = @NUM + 1

		FETCH CUR_CC
		INTO @SEC_RESUMEN
			,@SEC_META
			,@SEC_CTRO_COSTO1
	END
END

CLOSE CUR_CC

DEALLOCATE CUR_CC

UPDATE #TMP_SIG_PAAC_CENTRO_COSTO
SET SEC_CTRO_COSTO = 1
WHERE SEC_CTRO_COSTO IS NULL

SELECT @ls_pais = coalesce(pais, '')
	,@ls_depa = coalesce(departamento, '')
	,@ls_prov = coalesce(provincia, '')
	,@ls_dist = coalesce(distrito, '')
FROM Ejecutora
WHERE sec_ejec = @PN_EJECUTORA

IF (@ls_pais = '')
	OR (@ls_depa = '')
	OR (@ls_prov = '')
	OR (@ls_dist = '')
BEGIN
	SELECT @ls_pais = '4028'

	SELECT @ls_depa = '15'

	SELECT @ls_prov = '01'

	SELECT @ls_dist = '01'
END

