			,@PN_NRO_PAO
			,@ps_tipo_generacion
			,@ps_tipo
			,@li_secu_cons
			,(@PN_ANIO + @li_cont)
			,RIGHT('00' + LTRIM(STR(@PS_MES_INI)), 2)
			,RIGHT('00' + LTRIM(STR(@PS_MES_FIN)), 2)
