	AND SIG_PAAC_CENTRO_COSTO.TIPO_BIEN = SIG_PAAC_METAS.TIPO_BIEN
	AND SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID = SIG_PAAC_METAS.SEC_CONSOLID
	AND SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN = SIG_PAAC_METAS.SEC_RESUMEN
	AND SIG_PAAC_CENTRO_COSTO.SEC_META = SIG_PAAC_METAS.SEC_META
	AND SIG_PAAC_CENTRO_COSTO.SEC_EJEC = I.SEC_EJEC
	AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = I.ANO_EJE
	AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = I.TIPO_CONSOLID
	AND SIG_PAAC_CENTRO_COSTO.NRO_CONSOLID = I.NRO_CONSOLID
	AND SIG_PAAC_CENTRO_COSTO.TIPO_GENERACION = I.TIPO_GENERACION
	AND SIG_PAAC_CENTRO_COSTO.TIPO_BIEN = I.TIPO_BIEN
	AND SIG_PAAC_CENTRO_COSTO.SEC_CONSOLID = I.SEC_CONSOLID
	AND SIG_PAAC_CENTRO_COSTO.SEC_RESUMEN = I.SEC_RESUMEN
	AND SIG_PAAC_CENTRO_COSTO.ANO_EJE = SIG_PAAC_CENTRO_COSTO.ANO_EJE
	AND SIG_PAAC_CENTRO_COSTO.TIPO_CONSOLID = 1
	AND SIG_CUADRO_NECESIDAD.SEC_EJEC = SIG_PAAC_CENTRO_COSTO.SEC_EJEC
	AND SIG_CUADRO_NECESIDAD.ANO_EJE = SIG_PAAC_CENTRO_COSTO.ANO_EJE
	AND SIG_CUADRO_NECESIDAD.CENTRO_COSTO = SIG_PAAC_CENTRO_COSTO.CENTRO_COSTO
	AND SIG_CUADRO_NECESIDAD.FASE_CUADRO = 5
	AND SIG_CUADRO_NECESIDAD.SEC_FUNC = SIG_PAAC_METAS.SEC_FUNC
	AND SIG_CUADRO_NECESIDAD.CLASIFICADOR = SIG_PAAC_METAS.CLASIFICADOR
	AND SIG_CUADRO_NECESIDAD.ORIGEN = SIG_PAAC_METAS.ORIGEN
	AND SIG_CUADRO_NECESIDAD.FUENTE_FINANC = SIG_PAAC_METAS.FUENTE_FINANC
	AND SIG_CUADRO_NECESIDAD.NIVEL_TAREA = SIG_PAAC_CENTRO_COSTO.NIVEL_TAREA
	AND SIG_CUADRO_NECESIDAD.CODIGO_TAREA = SIG_PAAC_CENTRO_COSTO.CODIGO_TAREA
	AND SIG_CUADRO_NECESIDAD.SEC_EJEC = D.SEC_EJEC
	AND SIG_CUADRO_NECESIDAD.ANO_EJE = D.ANO_EJE
	AND SIG_CUADRO_NECESIDAD.CENTRO_COSTO = D.CENTRO_COSTO
	AND SIG_CUADRO_NECESIDAD.SECUENCIA = D.SECUENCIA
	AND SIG_CUADRO_NECESIDAD.FASE_CUADRO = D.FASE_CUADRO
	AND I.TIPO_BIEN = D.TIPO_BIEN
	AND I.GRUPO_BIEN = D.GRUPO_BIEN
	AND I.CLASE_BIEN = D.CLASE_BIEN
	AND I.FAMILIA_BIEN = D.FAMILIA_BIEN
	AND I.ITEM_BIEN = D.ITEM_BIEN
	AND I.ANO_EJE = @PN_ANIO
	AND I.SEC_EJEC = @PN_EJECUTORA
	AND I.TIPO_CONSOLID = '1'
	AND I.NRO_CONSOLID = @PN_NRO_PAO
	AND I.TIPO_GENERACION = @ps_tipo_generacion

IF @@ERROR <> 0
