SET VALOR = CASE 
		WHEN TIPO_IMPTO = 0
			THEN VALOR
		WHEN tipo_impto = 1
			THEN VALOR / ((tasa_impto / 100) + 1)
		WHEN tipo_impto > 1
			THEN VALOR - (VALOR * (tasa_impto / 100))
		END
	,VALOR_MONEDA = CASE 
		WHEN TIPO_IMPTO = 0
			THEN VALOR
		WHEN tipo_impto = 1
			THEN VALOR / ((tasa_impto / 100) + 1)
		WHEN tipo_impto > 1
			THEN VALOR - (VALOR * (tasa_impto / 100))
		END
	,VALOR_IMPTO = CASE 
		WHEN TIPO_IMPTO = 0
			THEN 0
		WHEN TIPO_IMPTO = 1
			THEN VALOR - (VALOR / ((tasa_impto / 100) + 1))
		WHEN TIPO_IMPTO > 1
			THEN (VALOR * (tasa_impto / 100))
		END
	,VALOR_IMPTO_MONEDA = CASE 
		WHEN TIPO_IMPTO = 0
			THEN 0
		WHEN TIPO_IMPTO = 1
			THEN VALOR - (VALOR / ((tasa_impto / 100) + 1))
		WHEN TIPO_IMPTO > 1
			THEN (VALOR * (tasa_impto / 100))
		END
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion

IF @@ERROR <> 0
	GOTO ERROR

----- Actualizar cantidades almacen  
UPDATE SIG_PAAC_ITEM
SET MES_01 = CASE 
		WHEN MES_01 < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		ELSE MES_01 - ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
		END
	,MES_02 = CASE 
		WHEN (MES_01 + MES_02) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
