		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN MES_08 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07))
		ELSE MES_08
		END
	,MES_10 = CASE 
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN MES_10 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09))
		ELSE MES_10
		END
	,MES_09 = CASE 
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN MES_09 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08))
		ELSE MES_09
		END
	,MES_11 = CASE 
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN MES_11 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10))
		ELSE MES_11
		END
	,MES_12 = CASE 
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN 0
		WHEN (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			AND (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11) < ((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD)
			THEN MES_12 - (((MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) - CANTIDAD) - (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11))
		ELSE MES_12
		END
WHERE (MES_01 + MES_02 + MES_03 + MES_04 + MES_05 + MES_06 + MES_07 + MES_08 + MES_09 + MES_10 + MES_11 + MES_12) > CANTIDAD
	AND ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion

IF @@ERROR <> 0
	GOTO ERROR

UPDATE SIG_PAAC_CENTRO_COSTO
SET FLAG_MES_01 = (
		CASE COALESCE(MES_01, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_02 = (
		CASE COALESCE(MES_02, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_03 = (
		CASE COALESCE(MES_03, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_04 = (
		CASE COALESCE(MES_04, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_05 = (
		CASE COALESCE(MES_05, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_06 = (
		CASE COALESCE(MES_06, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_07 = (
		CASE COALESCE(MES_07, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_08 = (
		CASE COALESCE(MES_08, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_09 = (
		CASE COALESCE(MES_09, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_10 = (
		CASE COALESCE(MES_10, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_11 = (
		CASE COALESCE(MES_11, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
	,FLAG_MES_12 = (
		CASE COALESCE(MES_12, 0)
			WHEN 0
				THEN '0'
			ELSE '1'
			END
		)
WHERE ANO_EJE = @PN_ANIO
	AND SEC_EJEC = @PN_EJECUTORA
	AND TIPO_CONSOLID = '1'
	AND NRO_CONSOLID = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion

IF @@ERROR <> 0
	GOTO ERROR

------ Proceso seleccion --------------------  
DECLARE @pn_monto_total_item NUMERIC(16, 2)
	,@ls_proc_selec VARCHAR(2)
	/* MPC - Issue 384 - Ampliación a 5 caracteres */
	,@ls_nume_plan VARCHAR(5)
DECLARE @pn_monto_total_item_val NUMERIC(16, 2)

SELECT @pn_monto_total_item = SUM(coalesce(VALOR, 0))
FROM sig_paac_item
WHERE ano_eje = @PN_ANIO
	AND sec_ejec = @PN_EJECUTORA
	AND tipo_consolid = @ls_tipo_cons
	AND nro_consolid = @PN_NRO_PAO
	AND TIPO_GENERACION = @ps_tipo_generacion
	AND TIPO_BIEN = @PS_TIPO

IF (@pn_monto_total_item = 0)
BEGIN
	SET @pn_monto_total_item_val = 0.01
END

IF (@pn_monto_total_item > 0)
BEGIN
	SET @pn_monto_total_item_val = @pn_monto_total_item
END

SELECT @ls_proc_selec = CODIGO
FROM SIG_TOPES_PROCESOS
WHERE ANO_EJE = @PN_ANIO
	AND TIPO_ORGANISMO = @ls_tipo_organismo
	AND TIPO_BIEN = @PS_TIPO
	AND FLAG = '1'
	AND CODIGO NOT IN ('33')
	AND @pn_monto_total_item_val BETWEEN MONTO_MINIMO
		AND MONTO_MAXIMO
		
IF @pn_monto_total_item_val > 0
	AND @ls_proc_selec <> '14' -- Diferencia a menor cuantia (Antes 05)  
BEGIN
    /*
	SELECT @ls_nume_plan = max(nro_paac)
	FROM sig_paac_consolidado
	WHERE ano_eje = @PN_ANIO
		AND sec_ejec = @PN_EJECUTORA
		AND tipo_consolid = @ls_tipo_cons
		AND TIPO_GENERACION = @ps_tipo_generacion
		AND flag_paac = '1'
    */
    
     SELECT @ls_nume_plan = MAX(CAST(nro_paac AS INT))
       FROM SIG_PAAC_CONSOLIDADO
     WHERE ANO_EJE       = @PN_ANIO
          AND SEC_EJEC      = @PN_EJECUTORA
          AND TIPO_CONSOLID = @ls_tipo_cons
          AND TIPO_GENERACION = @ps_tipo_generacion
          AND flag_paac = '1'
          AND coalesce(NRO_PAAC,' ') <>  ' '

	IF @ls_nume_plan IS NULL
	    /* SELECT @ls_nume_plan = '0001 */
		SELECT @ls_nume_plan = '00001'
	ELSE
	    /* SELECT @ls_nume_plan = right('0000' + ltrim(str(convert(INT, @ls_nume_plan) + 1)), 4) */
		SELECT @ls_nume_plan = right('00000' + ltrim(str(convert(INT, @ls_nume_plan) + 1)), 5)

	UPDATE SIG_PAAC_CONSOLIDADO
	SET VALOR_PLAN = @pn_monto_total_item
		,VALOR_MONEDA = @pn_monto_total_item
		,TIPO_PROCESO = @ls_proc_selec
		,FLAG_PAAC = '1'
		,NRO_PAAC = @ls_nume_plan
		,UNIDAD_MEDIDA = 112
		,CONVOCACION_PROCESO = '0'
		,PRECEDENTE = '0'
		,modal_compra = 'CA'
	WHERE ano_eje = @PN_ANIO
		AND sec_ejec = @PN_EJECUTORA
		AND tipo_consolid = @ls_tipo_cons
		AND nro_consolid = @PN_NRO_PAO
		AND TIPO_GENERACION = @ps_tipo_generacion

	IF @@ERROR <> 0
		GOTO ERROR
END

IF @pn_monto_total_item_val > 0
	AND @ls_proc_selec = '14'
BEGIN
	UPDATE SIG_PAAC_CONSOLIDADO
	SET VALOR_PLAN = @pn_monto_total_item
		,VALOR_MONEDA = @pn_monto_total_item
		,TIPO_PROCESO = @ls_proc_selec
		,FLAG_PAAC = '0'
		,UNIDAD_MEDIDA = 112
		,CONVOCACION_PROCESO = '0'
		,PRECEDENTE = '0'
		,modal_compra = 'OM'
	WHERE ano_eje = @PN_ANIO
		AND sec_ejec = @PN_EJECUTORA
		AND tipo_consolid = @ls_tipo_cons
		AND nro_consolid = @PN_NRO_PAO
		AND TIPO_GENERACION = @ps_tipo_generacion

IF @@ERROR <> 0
	GOTO ERROR
END

If @PS_MODAL_COMPRA = 'MP'  
BEGIN
   set @ls_proc_selec = '26' 
   UPDATE SIG_PAAC_CONSOLIDADO    
   SET 
	   TIPO_PROCESO = @ls_proc_selec,
       	MODAL_COMPRA = @PS_MODAL_COMPRA 
   WHERE ano_eje  		= @PN_ANIO and    
		 sec_ejec 		= @PN_EJECUTORA and    
		 tipo_consolid 	= @ls_tipo_cons  and    
		 nro_consolid  	= @PN_NRO_PAO and    
		 TIPO_GENERACION = @ps_tipo_generacion    
	 
   IF @@ERROR <> 0    
   GOTO ERROR
END

IF @PS_MES_INI = 1
	AND @PS_MES_FIN = 12
BEGIN
	-- ========================================  
	-- Actualiza Items existentes en el PAO  
	-- ========================================  
	UPDATE sig_cuadro_necesidaD_det
	SET sig_cuadro_necesidad_det.estado = 6
	FROM SIG_CUADRO_necesidad C
		,SIG_CUADRO_necesidad_Det D
		,CATALOGO_BIEN_SERV S
	WHERE (
			D.ANO_EJE = @PN_ANIO
			AND D.SEC_EJEC = @PN_EJECUTORA
			AND (
				(
					D.FASE_CUADRO = 3
					AND @PN_ANIO <= 2011
					)
				OR (
					D.FASE_CUADRO = 5
					AND @PN_ANIO >= 2012
					)
				)
			AND D.TIPO_BIEN = @PS_TIPO
			AND EXISTS (
				SELECT CENTRO_COSTO
				FROM tmp_parametros_pao
				WHERE CODIGO = 5
					AND NRO_PAO = @PN_NRO_PAO
					AND centro_costo = D.CENTRO_COSTO
				)
			AND EXISTS (
				SELECT TIPO_TAREA
				FROM tmp_parametros_pao
				WHERE CODIGO = 6
					AND NRO_PAO = @PN_NRO_PAO
					AND TIPO_TAREA = C.TIPO_TAREA
					AND CODIGO_TAREA = C.CODIGO_TAREA
					AND TIPO_USO = C.TIPO_USO		  
				)
			AND (
				EXISTS (
					SELECT ITEM
					FROM tmp_parametros_pao
					WHERE CODIGO = 1
						AND NRO_PAO = @PN_NRO_PAO
						AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN + D.ITEM_BIEN)
					)
				OR EXISTS (
					SELECT ITEM
					FROM tmp_parametros_pao
					WHERE CODIGO = 1
						AND NRO_PAO = @PN_NRO_PAO
						AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN)
					)
				OR EXISTS (
					SELECT ITEM
					FROM tmp_parametros_pao
					WHERE CODIGO = 1
						AND NRO_PAO = @PN_NRO_PAO
						AND ITEM = (D.GRUPO_BIEN + D.CLASE_BIEN + D.FAMILIA_BIEN)
					)
				)
			AND EXISTS (
				SELECT FUENTE
				FROM tmp_parametros_pao
				WHERE CODIGO = 3
					AND NRO_PAO = @PN_NRO_PAO
					AND Fuente = C.FUENTE_FINANC
				)
			AND EXISTS (
				SELECT CLASIFICADOR
				FROM tmp_parametros_pao
				WHERE CODIGO = 2
					AND NRO_PAO = @PN_NRO_PAO
					AND CLASIFICADOR = C.CLASIFICADOR
				)
			AND EXISTS (
				SELECT SEC_FUNC
				FROM tmp_parametros_pao
				WHERE CODIGO = 4
					AND NRO_PAO = @PN_NRO_PAO
					AND SEC_FUNC = C.SEC_FUNC
				)
			AND
			/*(D.CANT_TOTAL) > 0   AND*/
			(COALESCE(D.CANT_TOTAL, 0) + COALESCE(D.CANT_TOTAL_ANNO_01, 0) + COALESCE(D.CANT_TOTAL_ANNO_02, 0) + COALESCE(D.CANT_TOTAL_ANNO_03, 0)) > 0
			AND (
				(
					@ps_modal_compra = 'SI'
					AND S.FLAG_SUBASTA_INVERSA = '1'
					)
				OR (
					@ps_modal_compra = 'CP'
					AND S.BOLSA_PRODUCTO = '1'
					)
				OR (
					@ps_modal_compra = 'MP'
					AND S.FLAG_MARCO_PRECIO = 'S'
					)
				OR (
					@ps_modal_compra NOT IN ('SI','CP','MP')
					AND (
						S.FLAG_SUBASTA_INVERSA <> '1'
						OR S.FLAG_SUBASTA_INVERSA IS NULL
						)
					AND (
						S.BOLSA_PRODUCTO <> '1'
						OR S.BOLSA_PRODUCTO IS NULL
						)
					AND (
						S.FLAG_MARCO_PRECIO <> 'S'
						OR S.FLAG_MARCO_PRECIO IS NULL
						)
					)
				)
			)
		AND (
			D.ANO_EJE = C.ANO_EJE
			AND D.SEC_EJEC = C.SEC_EJEC
			AND D.CENTRO_COSTO = C.CENTRO_COSTO
			AND D.fase_cuadro = C.fase_cuadro
			AND D.SECUENCIA = C.SECUENCIA
			AND D.SEC_EJEC = S.SEC_EJEC
			AND D.TIPO_BIEN = S.TIPO_BIEN
			AND D.GRUPO_BIEN = S.GRUPO_BIEN
			AND D.CLASE_BIEN = S.CLASE_BIEN
			AND D.FAMILIA_BIEN = S.FAMILIA_BIEN
			AND D.ITEM_BIEN = S.ITEM_BIEN
			)
END

IF @@ERROR <> 0
	GOTO ERROR

DELETE tmp_parametros_pao
WHERE NRO_PAO = @PN_NRO_PAO

IF @@ERROR <> 0
	GOTO ERROR

COMMIT TRAN
SET NOCOUNT OFF
RETURN 0

ERROR:
     ROLLBACK TRAN
     SET NOCOUNT OFF
     RETURN 1
GO


-- ----------------------------
-- procedure structure for DT_CHECKOUTOBJECT_U
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_CHECKOUTOBJECT_U]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_CHECKOUTOBJECT_U]
GO

CREATE PROCEDURE [dbo].[DT_CHECKOUTOBJECT_U]
    @chObjectType  char(4),
    @vchObjectName nvarchar(255),
    @vchComment    nvarchar(255),
    @vchLoginName  nvarchar(255),
    @vchPassword   nvarchar(255),
    @iVCSFlags     int = 0,
    @iActionFlag   int = 0/* 0 => Checkout, 1 => GetLatest, 2 => UndoCheckOut */

as

	-- This procedure should no longer be called;  dt_checkoutobject should be called instead.
	-- Calls are forwarded to dt_checkoutobject to maintain backward compatibility.
	set nocount on
	exec dbo.dt_checkoutobject
		@chObjectType,  
		@vchObjectName, 
		@vchComment,    
		@vchLoginName,  
		@vchPassword,  
		@iVCSFlags,    
		@iActionFlag
GO


-- ----------------------------
-- function structure for F_ITEM_FECHA_RECEPCION
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[F_ITEM_FECHA_RECEPCION]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION[dbo].[F_ITEM_FECHA_RECEPCION]
GO

CREATE FUNCTION [dbo].[F_ITEM_FECHA_RECEPCION]
(
@al_ejec_sec NUMERIC(10),
@al_ejec_anno NUMERIC(10),
@as_almacen   VARCHAR(3),
@as_sec_almacen  VARCHAR(3),
@as_tipo_bien	 VARCHAR(1),
@as_grupo_bien	VARCHAR(3),
@as_clase_bien	VARCHAR(3),
@as_familia_bien	VARCHAR(4),
@as_item_bien	VARCHAR(4),
@as_marca VARCHAR(10),
@as_mayor VARCHAR(10),
@as_sub_cta VARCHAR(10),
@adt_fecha_fin DATE,
@as_lote_flag VARCHAR(1)
)
RETURNS DATE
AS
BEGIN

DECLARE @ldt_fecha_inv_ini DATE
DECLARE @ldt_fecha_recep DATE

IF @as_tipo_bien <> 'B'
BEGIN
    RETURN NULL
END

IF COALESCE(@as_lote_flag, '0') = '0'
BEGIN
        SELECT @ldt_fecha_recep = MAX(SIG_MOVIM_ALMACEN.FECHA_MOVIMTO)
        FROM SIG_DETALLE_MOVIM_ALMACEN
        JOIN SIG_MOVIM_ALMACEN
            ON SIG_MOVIM_ALMACEN.SEC_EJEC        = SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC
            AND SIG_MOVIM_ALMACEN.ANO_EJE        = SIG_DETALLE_MOVIM_ALMACEN.ANO_EJE
            AND SIG_MOVIM_ALMACEN.ALMACEN        = SIG_DETALLE_MOVIM_ALMACEN.ALMACEN
            AND SIG_MOVIM_ALMACEN.SEC_ALMACEN    = SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN
            AND SIG_MOVIM_ALMACEN.TIPO_MOVIMTO   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO
            AND SIG_MOVIM_ALMACEN.TIPO_TRANSAC   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_TRANSAC
            AND SIG_MOVIM_ALMACEN.TIPO_PPTO      = SIG_DETALLE_MOVIM_ALMACEN.TIPO_PPTO
            AND SIG_MOVIM_ALMACEN.NRO_MOVIMTO    = SIG_DETALLE_MOVIM_ALMACEN.NRO_MOVIMTO
            AND SIG_MOVIM_ALMACEN.FECHA_MOVIMTO <= @adt_fecha_fin
        WHERE SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC         = @al_ejec_sec
        AND SIG_DETALLE_MOVIM_ALMACEN.ALMACEN            = @as_almacen
        AND SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN        = @as_sec_almacen
        AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO       = 'R'
        AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_BIEN	= @as_tipo_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.GRUPO_BIEN	= @as_grupo_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.CLASE_BIEN	= @as_clase_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.FAMILIA_BIEN	= @as_familia_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.ITEM_BIEN	= @as_item_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.MARCA = @as_marca
        AND SIG_DETALLE_MOVIM_ALMACEN.MAYOR = @as_mayor
        AND SIG_DETALLE_MOVIM_ALMACEN.SUB_CTA = @as_sub_cta
        AND SIG_DETALLE_MOVIM_ALMACEN.NRO_MOVIMTO_DEST IS NOT NULL         
        
END
ELSE
BEGIN 
        SELECT @ldt_fecha_recep = MAX(SIG_MOVIM_ALMACEN.FECHA_MOVIMTO)
        FROM SIG_DETALLE_MOVIM_ALMACEN
        JOIN SIG_MOVIM_ALMACEN
            ON SIG_MOVIM_ALMACEN.SEC_EJEC        = SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC
            AND SIG_MOVIM_ALMACEN.ANO_EJE        = SIG_DETALLE_MOVIM_ALMACEN.ANO_EJE
            AND SIG_MOVIM_ALMACEN.ALMACEN        = SIG_DETALLE_MOVIM_ALMACEN.ALMACEN
            AND SIG_MOVIM_ALMACEN.SEC_ALMACEN    = SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN
            AND SIG_MOVIM_ALMACEN.TIPO_MOVIMTO   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO
            AND SIG_MOVIM_ALMACEN.TIPO_TRANSAC   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_TRANSAC
            AND SIG_MOVIM_ALMACEN.TIPO_PPTO      = SIG_DETALLE_MOVIM_ALMACEN.TIPO_PPTO
            AND SIG_MOVIM_ALMACEN.NRO_MOVIMTO    = SIG_DETALLE_MOVIM_ALMACEN.NRO_MOVIMTO
            AND SIG_MOVIM_ALMACEN.FECHA_MOVIMTO <= @adt_fecha_fin
        JOIN SIG_DETALLE_ALMACEN_LOTES
                ON SIG_DETALLE_ALMACEN_LOTES.SEC_EJEC	             = SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC	
                AND SIG_DETALLE_ALMACEN_LOTES.ANO_EJE	             = SIG_DETALLE_MOVIM_ALMACEN.ANO_EJE	             
                AND SIG_DETALLE_ALMACEN_LOTES.ALMACEN	    = SIG_DETALLE_MOVIM_ALMACEN.ALMACEN	    
                AND SIG_DETALLE_ALMACEN_LOTES.SEC_ALMACEN	    = SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN	    
                AND SIG_DETALLE_ALMACEN_LOTES.TIPO_MOVIMTO	    = SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO	    
                AND SIG_DETALLE_ALMACEN_LOTES.TIPO_TRANSAC	    = SIG_DETALLE_MOVIM_ALMACEN.TIPO_TRANSAC	    
                AND SIG_DETALLE_ALMACEN_LOTES.TIPO_PPTO	    = SIG_DETALLE_MOVIM_ALMACEN.TIPO_PPTO	    
                AND SIG_DETALLE_ALMACEN_LOTES.NRO_MOVIMTO	    = SIG_DETALLE_MOVIM_ALMACEN.NRO_MOVIMTO	    
                AND SIG_DETALLE_ALMACEN_LOTES.SECUENCIA	    = SIG_DETALLE_MOVIM_ALMACEN.SECUENCIA	    
                AND SIG_DETALLE_ALMACEN_LOTES.SEC_DETALLE    = SIG_DETALLE_MOVIM_ALMACEN.SEC_DETALLE
        WHERE SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC         = @al_ejec_sec
        AND SIG_DETALLE_MOVIM_ALMACEN.ALMACEN            = @as_almacen
        AND SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN        = @as_sec_almacen
        AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO       = 'R'
        AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_BIEN	= @as_tipo_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.GRUPO_BIEN	= @as_grupo_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.CLASE_BIEN	= @as_clase_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.FAMILIA_BIEN	= @as_familia_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.ITEM_BIEN	= @as_item_bien
        AND SIG_DETALLE_MOVIM_ALMACEN.MARCA = @as_marca
        AND SIG_DETALLE_MOVIM_ALMACEN.MAYOR = @as_mayor
        AND SIG_DETALLE_MOVIM_ALMACEN.SUB_CTA = @as_sub_cta
        AND SIG_DETALLE_ALMACEN_LOTES.NRO_MOVIMTO_DEST IS NOT NULL         
        
END

IF @ldt_fecha_recep IS NULL
BEGIN
    SELECT @ldt_fecha_inv_ini = MIN(SIG_MOVIM_ALMACEN.FECHA_MOVIMTO)
    FROM SIG_DETALLE_MOVIM_ALMACEN
    JOIN SIG_MOVIM_ALMACEN
        ON SIG_MOVIM_ALMACEN.SEC_EJEC        = SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC
        AND SIG_MOVIM_ALMACEN.ANO_EJE        = SIG_DETALLE_MOVIM_ALMACEN.ANO_EJE
        AND SIG_MOVIM_ALMACEN.ALMACEN        = SIG_DETALLE_MOVIM_ALMACEN.ALMACEN
        AND SIG_MOVIM_ALMACEN.SEC_ALMACEN    = SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN
        AND SIG_MOVIM_ALMACEN.TIPO_MOVIMTO   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO
        AND SIG_MOVIM_ALMACEN.TIPO_TRANSAC   = SIG_DETALLE_MOVIM_ALMACEN.TIPO_TRANSAC
        AND SIG_MOVIM_ALMACEN.TIPO_PPTO      = SIG_DETALLE_MOVIM_ALMACEN.TIPO_PPTO
        AND SIG_MOVIM_ALMACEN.NRO_MOVIMTO    = SIG_DETALLE_MOVIM_ALMACEN.NRO_MOVIMTO
    WHERE SIG_DETALLE_MOVIM_ALMACEN.SEC_EJEC         = @al_ejec_sec
    AND SIG_DETALLE_MOVIM_ALMACEN.ALMACEN            = @as_almacen
    AND SIG_DETALLE_MOVIM_ALMACEN.SEC_ALMACEN        = @as_sec_almacen
    AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_MOVIMTO       = 'A'
    AND SIG_DETALLE_MOVIM_ALMACEN.TIPO_BIEN	= @as_tipo_bien
    AND SIG_DETALLE_MOVIM_ALMACEN.GRUPO_BIEN	= @as_grupo_bien
    AND SIG_DETALLE_MOVIM_ALMACEN.CLASE_BIEN	= @as_clase_bien
    AND SIG_DETALLE_MOVIM_ALMACEN.FAMILIA_BIEN	= @as_familia_bien
    AND SIG_DETALLE_MOVIM_ALMACEN.ITEM_BIEN	= @as_item_bien
    AND SIG_DETALLE_MOVIM_ALMACEN.MARCA = @as_marca
    AND SIG_DETALLE_MOVIM_ALMACEN.MAYOR = @as_mayor
    AND SIG_DETALLE_MOVIM_ALMACEN.SUB_CTA = @as_sub_cta

    SET @ldt_fecha_recep =  @ldt_fecha_inv_ini
END

RETURN  @ldt_fecha_recep

END
GO


-- ----------------------------
-- procedure structure for SP_CARGA_ADQUISICIONES_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_CARGA_ADQUISICIONES_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_CARGA_ADQUISICIONES_TRX]
GO

CREATE PROCEDURE [dbo].[SP_CARGA_ADQUISICIONES_TRX]
    @P_ANO_EJE            	NUMERIC(4,0),
     @P_SEC_EJEC           	NUMERIC(6,0),    
     @O_ERR_NUM   	NUMERIC(6,0) OUTPUT,
     @O_ERR_MSG   	VARCHAR(255) OUTPUT
AS
BEGIN 
  
DECLARE @LL_NRO_ORDEN         NUMERIC(7)  
DECLARE @LS_TIPO_BIEN        VARCHAR(1)
DECLARE @LL_TIPO_PPTO         NUMERIC(2) 
DECLARE @LL_SEC_EJEC2        NUMERIC(6)
DECLARE @LS_SECTOR            VARCHAR(2)
DECLARE @LS_PLIEGO           VARCHAR(3)
DECLARE @LL_TIPO_ENTIDAD     NUMERIC(2)
DECLARE @LS_GRUPO_BIEN       VARCHAR(2) 
DECLARE @LS_CLASE_BIEN       VARCHAR(2)
DECLARE @LS_FAMILIA_BIEN     VARCHAR(4)
DECLARE @LS_ITEM_BIEN       VARCHAR(4) 
DECLARE @LN_CANT_ITEM       NUMERIC(16,6)
DECLARE @LN_UNIDAD_MEDIDA    NUMERIC(3)
DECLARE @LD_PREC_UNIT_MONEDA NUMERIC(16,6)
DECLARE @LD_PREC_TOT_SOLES NUMERIC(16,2)
DECLARE @LS_ORIGEN         VARCHAR(1)
DECLARE @LS_FUENTE_FINANC  VARCHAR(2)
DECLARE @LS_FUNCION         VARCHAR(2)
DECLARE @LS_PROGRAMA       VARCHAR(3)
DECLARE @LS_SUB_PROGRAMA   VARCHAR(4)
DECLARE @LS_ACT_PROY        VARCHAR(7)
DECLARE @LS_COMPONENTE      VARCHAR(7)
DECLARE @LS_CLASIFICADOR   VARCHAR(20)
DECLARE @LN_MES_CALEND     NUMERIC(2)
DECLARE @LS_DEPARTAMENTO   VARCHAR(2)
DECLARE @LS_PROVINCIA      VARCHAR(2)
DECLARE @LS_NRO_RUC        VARCHAR(11)
DECLARE @LL_SECUENCIA      NUMERIC(6)
DECLARE @LS_CATEGORIA      VARCHAR(3)
DECLARE @LS_GRUPO          VARCHAR(3)
DECLARE @LS_MODALIDAD      VARCHAR(5)
DECLARE @LS_ELEMENTO_GASTO VARCHAR(5)
DECLARE @LL_INICIO 		NUMERIC
DECLARE @LL_LONG   		NUMERIC

 BEGIN

    DELETE FROM dbo.SGE_ADQUISICIONES_TRX

    SELECT @LL_SECUENCIA = MAX(secuencia)
     FROM SGE_ADQUISICIONES_TRX
     WHERE ANO_EJE  = @P_ANO_EJE  AND
           SEC_EJEC = @P_SEC_EJEC 


	IF @LL_SECUENCIA IS NULL 
		SET @LL_SECUENCIA = 0
		
  DECLARE C1 CURSOR FOR
  		SELECT DISTINCT
                    A.NRO_ORDEN,
                    A.TIPO_BIEN,
                    A.TIPO_PPTO,
                    D.SEC_EJEC2,
                    B.SECTOR,
                    B.pliego,
                    G.TIPO_ENTIDAD,
                    A.GRUPO_BIEN,
                    A.CLASE_BIEN,
                    A.FAMILIA_BIEN,
                    A.ITEM_BIEN,
                    A.CANT_ITEM,
                    A.UNIDAD_MEDIDA,
                    A.PREC_UNIT_MONEDA,
                    A.PREC_TOT_SOLES,                    
                    (SELECT MAX(ORIGEN)
                     FROM SIG_ORDEN_ITEM_PPTO
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC  = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) ORIGEN,                    
                    (SELECT MAX( FUENTE_FINANC )
                     FROM SIG_ORDEN_ITEM_PPTO
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) FUENTE_FINANC,
                    (SELECT MAX(META.funcion )
                     FROM SIG_ORDEN_ITEM_PPTO
                     JOIN META
                        ON  META.ANO_EJE = SIG_ORDEN_ITEM_PPTO.ANO_EJE
                        AND META.SEC_EJEC = SIG_ORDEN_ITEM_PPTO.SEC_EJEC
                        AND META.SEC_FUNC = SIG_ORDEN_ITEM_PPTO.SEC_FUNC
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) FUNCION,
                    (SELECT MAX(META.PROGRAMA)
                     FROM SIG_ORDEN_ITEM_PPTO
                     JOIN META
                        ON  META.ANO_EJE = SIG_ORDEN_ITEM_PPTO.ANO_EJE
                        AND META.SEC_EJEC = SIG_ORDEN_ITEM_PPTO.SEC_EJEC
                        AND META.SEC_FUNC = SIG_ORDEN_ITEM_PPTO.SEC_FUNC
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) PROGRAMA,                    
                    (SELECT MAX(META.SUB_PROGRAMA)
                     FROM SIG_ORDEN_ITEM_PPTO
                     JOIN META
                        ON  META.ANO_EJE = SIG_ORDEN_ITEM_PPTO.ANO_EJE
                        AND META.SEC_EJEC = SIG_ORDEN_ITEM_PPTO.SEC_EJEC
                        AND META.SEC_FUNC = SIG_ORDEN_ITEM_PPTO.SEC_FUNC
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) SUB_PROGRAMA,                    
                    (SELECT MAX(META.ACT_PROY)
                     FROM SIG_ORDEN_ITEM_PPTO
                     JOIN META
                        ON  META.ANO_EJE = SIG_ORDEN_ITEM_PPTO.ANO_EJE
                        AND META.SEC_EJEC = SIG_ORDEN_ITEM_PPTO.SEC_EJEC
                        AND META.SEC_FUNC = SIG_ORDEN_ITEM_PPTO.SEC_FUNC
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) ACT_PROY,                    
                    (SELECT MAX(META.COMPONENTE)
                     FROM SIG_ORDEN_ITEM_PPTO
                     JOIN META
                        ON  META.ANO_EJE = SIG_ORDEN_ITEM_PPTO.ANO_EJE
                        AND META.SEC_EJEC = SIG_ORDEN_ITEM_PPTO.SEC_EJEC
                        AND META.SEC_FUNC = SIG_ORDEN_ITEM_PPTO.SEC_FUNC
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) COMPONENTE,                    
                    (SELECT MAX(CLASIFICADOR)
                     FROM SIG_ORDEN_ITEM_PPTO
                     WHERE     SIG_ORDEN_ITEM_PPTO.ANO_EJE = C.ANO_EJE
                         AND SIG_ORDEN_ITEM_PPTO.SEC_EJEC = C.SEC_EJEC
                         AND SIG_ORDEN_ITEM_PPTO.NRO_ORDEN = C.NRO_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_BIEN = C.TIPO_BIEN
                         AND SIG_ORDEN_ITEM_PPTO.TIPO_PPTO = C.TIPO_PPTO
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ORDEN = C.SEC_ORDEN
                         AND SIG_ORDEN_ITEM_PPTO.SEC_ITEM = A.SEC_ITEM
                    ) CLASIFICADOR,                    
                    convert(NUMERIC,D.MES_CALEND) MES_CALEND,
                    G.DEPARTAMENTO,
                    G.PROVINCIA,
                    H.NRO_RUC                    
                FROM SIG_ORDEN_ITEM A
                JOIN SIG_EJECUTORA B
                    ON  B.sec_ejec = A.SEC_EJEC
                JOIN SIG_ORDEN_SECUENCIA C
                    ON  C.ANO_EJE = A.ANO_EJE
                    AND C.SEC_EJEC = A.SEC_EJEC
                    AND C.NRO_ORDEN = A.NRO_ORDEN
                    AND C.TIPO_BIEN = A.TIPO_BIEN
                    AND C.TIPO_PPTO = A.TIPO_PPTO
                    AND C.SEC_ORDEN = A.SEC_ORDEN
                JOIN SIG_ORDEN_ADQUISICION D
                    ON  D.ANO_EJE = C.ANO_EJE
                    AND D.SEC_EJEC = C.SEC_EJEC
                    AND D.NRO_ORDEN = C.NRO_ORDEN
                    AND D.TIPO_BIEN = C.TIPO_BIEN
                    AND D.TIPO_PPTO = C.TIPO_PPTO
                JOIN EJECUTORA G
                    ON G.SEC_EJEC = B.SEC_EJEC
                JOIN SIG_CONTRATISTAS H
                    ON  H.PROVEEDOR = D.PROVEEDOR
                WHERE A.ANO_EJE  = @P_ANO_EJE 
                  AND A.SEC_EJEC = @P_SEC_EJEC   
                  
	OPEN C1     
	 FETCH NEXT FROM C1
	  INTO  
	  @LL_NRO_ORDEN,	   @LS_TIPO_BIEN,		@LL_TIPO_PPTO,		@LL_SEC_EJEC2,    @LS_SECTOR,		   @LS_PLIEGO,
	  @LL_TIPO_ENTIDAD,		@LS_GRUPO_BIEN,		@LS_CLASE_BIEN, 	 @LS_FAMILIA_BIEN ,@LS_ITEM_BIEN,  	@LN_CANT_ITEM    ,    
	  @LN_UNIDAD_MEDIDA ,    @LD_PREC_UNIT_MONEDA,@LD_PREC_TOT_SOLES,@LS_ORIGEN       ,@LS_FUENTE_FINANC,  @LS_FUNCION     ,    
	  @LS_PROGRAMA,          @LS_SUB_PROGRAMA,		@LS_ACT_PROY,        @LS_COMPONENTE,    @LS_CLASIFICADOR, @LN_MES_CALEND  ,   @LS_DEPARTAMENTO    ,
          @LS_PROVINCIA,         @LS_NRO_RUC 
             
        WHILE @@FETCH_STATUS = 0
        BEGIN     
        	SET @LL_INICIO = 0
          	SET @LL_LONG = 0
           	SET @LL_SECUENCIA = @LL_SECUENCIA + 1
           
           	SET @LS_CATEGORIA =  SUBSTRING(@LS_CLASIFICADOR, 1  , (CHARINDEX('.',@LS_CLASIFICADOR ,  1) -1))
       
       		SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 
	   		SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1)) - (CHARINDEX('.' ,@LS_CLASIFICADOR, CHARINDEX('.',@LS_CLASIFICADOR) ) + 1 )  
	   		SET @LS_GRUPO  = SUBSTRING( @LS_CLASIFICADOR, @LL_INICIO, @LL_LONG)
	   
	   		SET @LL_INICIO = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1
	   		SET @LL_LONG   = CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) - (CHARINDEX('.' ,@LS_CLASIFICADOR, (charindex('.',@LS_CLASIFICADOR) + 1) )   + 1)
	   		SET @LS_MODALIDAD = SUBSTRING( @LS_CLASIFICADOR,@LL_INICIO, @LL_LONG )

	   		SET @LL_INICIO = CHARINDEX('.', @LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1) ) +1
	   		SET @LL_LONG = LEN(@LS_CLASIFICADOR) -  CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.' ,@LS_CLASIFICADOR, (CHARINDEX('.',@LS_CLASIFICADOR) + 1) ) + 1)  ) 
	   		SET @LS_ELEMENTO_GASTO =	 SUBSTRING(@LS_CLASIFICADOR, @LL_INICIO, @LL_LONG )             
                          
           
            INSERT INTO SGE_ADQUISICIONES_TRX
            (ANO_EJE   ,     SEC_EJEC  ,  	NRO_ORDEN   ,   TIPO_BIEN     , 	TIPO_PPTO  ,  SECUENCIA   ,   SEC_EJEC2  ,        		SECTOR   ,   		PLIEGO   ,     TIPO_ENTIDAD  ,
             GRUPO_BIEN ,    CLASE_BIEN,  	FAMILIA_BIEN,   ITEM_BIEN     , 	CANT_ITEM  ,  UNIDAD_MEDIDA,  PRECIO_UNIT,        		MONTO_SOLES, 		ORIGEN   ,     FUENTE_FINANC ,  
             FUNCION  ,      PROGRAMA  ,    SUB_PROGRAMA,   ACT_PROY      , 	COMPONENTE ,  CLASIFICADOR ,  FECHA_REG  ,        		MES_PROCESO, 		DEPARTAMENTO,  PROVINCIA  ,
             CATEGORIA_GASTO ,   GRUPO     ,  	MODALIDAD   ,   ELEMENTO_GASTO, 	RUC_PROV )
            VALUES
            (@P_ANO_EJE,     @P_SEC_EJEC,   @LL_NRO_ORDEN,   @LS_TIPO_BIEN,   	@LL_TIPO_PPTO, @LL_SECUENCIA,    @LL_SEC_EJEC2,       	@LS_SECTOR ,       @LS_PLIEGO,      @LL_TIPO_ENTIDAD,
             @LS_GRUPO_BIEN, @LS_CLASE_BIEN,@LS_FAMILIA_BIEN,@LS_ITEM_BIEN,   	@LN_CANT_ITEM, @LN_UNIDAD_MEDIDA,@LD_PREC_UNIT_MONEDA,	@LD_PREC_TOT_SOLES,@LS_ORIGEN,      @LS_FUENTE_FINANC,
             @LS_FUNCION,    @LS_PROGRAMA,  @LS_SUB_PROGRAMA,@LS_ACT_PROY,    	@LS_COMPONENTE,@LS_CLASIFICADOR, NULL,               		@LN_MES_CALEND,    @LS_DEPARTAMENTO,@LS_PROVINCIA,
             @LS_CATEGORIA,  @LS_GRUPO,     @LS_MODALIDAD,   @LS_ELEMENTO_GASTO,@LS_NRO_RUC ) 
          
	   FETCH NEXT FROM C1
           INTO  @LL_NRO_ORDEN,	   @LS_TIPO_BIEN,		@LL_TIPO_PPTO,		@LL_SEC_EJEC2,    @LS_SECTOR,		   @LS_PLIEGO,
	    @LL_TIPO_ENTIDAD,		@LS_GRUPO_BIEN,		@LS_CLASE_BIEN, 	 @LS_FAMILIA_BIEN ,@LS_ITEM_BIEN,  	@LN_CANT_ITEM    ,    
	    @LN_UNIDAD_MEDIDA ,    @LD_PREC_UNIT_MONEDA,@LD_PREC_TOT_SOLES,@LS_ORIGEN       ,@LS_FUENTE_FINANC,  @LS_FUNCION     ,    
	    @LS_PROGRAMA,          @LS_SUB_PROGRAMA,		@LS_ACT_PROY,        @LS_COMPONENTE,    @LS_CLASIFICADOR, @LN_MES_CALEND  ,   @LS_DEPARTAMENTO    ,
            @LS_PROVINCIA,         @LS_NRO_RUC 
                          
      END          
      CLOSE C1
      DEALLOCATE C1  
   
    
  
        UPDATE SGE_ADQUISICIONES_TRX
         SET SGE_ADQUISICIONES_TRX.SECTOR = (SELECT B.SECTOR FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_ADQUISICIONES_TRX.SEC_EJEC),
             SGE_ADQUISICIONES_TRX.PLIEGO = (SELECT B.PLIEGO FROM EJECUTORA B WHERE B.SEC_EJEC= SGE_ADQUISICIONES_TRX.SEC_EJEC)
        WHERE 
            SGE_ADQUISICIONES_TRX.ANO_EJE   = @P_ANO_EJE AND
            SGE_ADQUISICIONES_TRX.SEC_EJEC  = @P_SEC_EJEC
            
         IF @@ERROR <> 0         
	 BEGIN
		 SET @O_ERR_MSG='Ocurrió error en la actualización de SGE_ADQUISICIONES_TRX'
		return -1
	 END         
              
   END
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_EA_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_EA_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_EA_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_EA_TRX]
    @P_ANO_EJE   	    NUMERIC(4,0),
    @P_SEC_EJEC  	    NUMERIC(6,0),
    @fecha_carga_inicio VARCHAR(10),
    @fecha_carga_fin    VARCHAR(10),	
    @usuario_n	   	    VARCHAR(30),
    @O_ERR_NUM   	    NUMERIC(6,0) OUTPUT,
    @O_ERR_MSG   	    VARCHAR(255) OUTPUT
AS
DECLARE @fecha_carga_inicio_1         DATETIME
DECLARE @fecha_carga_fin_1            DATETIME      
DECLARE @LD_FECHA_MOVIMIENTO          DATETIME
DECLARE @LC_NRO_GUIA_NEA              VARCHAR(10)
DECLARE @LC_NRO_FACTURA               VARCHAR(15)
DECLARE @LC_EMPLEADO                  VARCHAR(15)
DECLARE @LC_OBSERVACION               VARCHAR(100)
DECLARE @LC_CLASIFICADOR              VARCHAR(20)
DECLARE @LC_GRUPO_BIEN                CHAR(2)
DECLARE @LC_CLASE_BIEN                CHAR(2)
DECLARE @LC_FAMILIA_BIEN              CHAR(4)
DECLARE @LC_ITEM_BIEN                 CHAR(4)
DECLARE @LN_ID_SI_MOV_ALM             NUMERIC(10,0)
DECLARE @LN_ID_SI_MOV_ALM_DETA        NUMERIC(10,0)
DECLARE @LN_SEC_FUNC                  NUMERIC(4,0)
DECLARE @LC_FINALIDAD                 CHAR(5)
DECLARE @LC_D_FINALIDAD               VARCHAR(250)
DECLARE @LC_META                      VARCHAR(5)
DECLARE @LC_UNIDAD_MEDIDA_META        NUMERIC(3,0)
DECLARE @LC_D_UNIDAD_MEDIDA_META      VARCHAR(100)
DECLARE @LC_ITEM_CATALOGO             VARCHAR(20)
DECLARE @LC_NOMBRE_ITEM               VARCHAR(100)
DECLARE @LC_D_UNIDAD_MEDIDA_ITEM_BS   VARCHAR(100)
DECLARE @LC_D_ALMACEN                 VARCHAR(40)
DECLARE @LC_D_EMPLEADO                VARCHAR(150)
DECLARE @LC_NOMBRE_MOVIMIENTO         VARCHAR(50)
DECLARE @LC_NRO_RUC                   VARCHAR(20)
DECLARE @LC_NOMBRE_PROV               VARCHAR(100)
DECLARE @LN_ALMACEN                   VARCHAR(3)
DECLARE @LN_SEC_ALMACEN               VARCHAR(3)
DECLARE @LC_TIPO_MOVIMIENTO           CHAR(1)
DECLARE @LC_TIPO_USO                  CHAR(1)
DECLARE @LN_TIPO_TRANSAC            NUMERIC(5,0)
DECLARE @LN_PROVEEDOR               NUMERIC(5,0)
DECLARE @LN_NRO_ORDEN               NUMERIC(5,0)
DECLARE @LN_TIPO_PPTO               NUMERIC(5,0)
DECLARE @LN_NRO_MOVIMTO             NUMERIC(5,0)
DECLARE @LC_D_MARCA                 VARCHAR(100)
DECLARE @LN_CANTIDAD_ITEM_BS        NUMERIC(13,6)
DECLARE @LN_PRECIO_TOTAL            NUMERIC(20,2)
DECLARE @LN_PRECIO_UNITARIO         NUMERIC(20,2)
DECLARE @LN_UNIDAD_MEDIDA           NUMERIC(3,0)
DECLARE @LN_MARCA                   NUMERIC(5,0)

BEGIN  
    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)    

    DELETE FROM SI_MOVIMIENTO_ALMACEN_DETA_TRX
    DELETE FROM SI_MOVIMIENTO_ALMACEN_TRX
      
    SELECT @LN_ID_SI_MOV_ALM = MAX(SA.ID_SI_MOV_ALM)
    FROM SI_MOVIMIENTO_ALMACEN_TRX SA 
    WHERE SA.ANO_EJE  = @P_ANO_EJE 
    AND SA.SEC_EJEC = @P_SEC_EJEC

    IF @LN_ID_SI_MOV_ALM IS NULL
      	SET @LN_ID_SI_MOV_ALM = 0

    DECLARE C_1 CURSOR FOR
      SELECT NRO_MOVIMTO,
             FECHA_MOVIMTO,
             NRO_GUIA,
             PROVEEDOR,
             NRO_ORDEN,
             NRO_FACTURA,
             TIPO_MOVIMTO,
             TIPO_TRANSAC,
             RESPONSABLE,
             TIPO_USO,
             OBSERVACION,
             ALMACEN,
             SEC_ALMACEN,
             TIPO_PPTO
        FROM SIG_MOVIM_ALMACEN
       WHERE ANO_EJE         =  @P_ANO_EJE 
         AND SEC_EJEC        =  @P_SEC_EJEC
         AND TIPO_MOVIMTO    =  'I' 
         AND TIPO_TRANSAC    =  1
       ORDER BY NRO_MOVIMTO

    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA, 
	 @LN_PROVEEDOR, @LN_NRO_ORDEN, @LC_NRO_FACTURA, @LC_TIPO_MOVIMIENTO, 
	 @LN_TIPO_TRANSAC, @LC_EMPLEADO, @LC_TIPO_USO, @LC_OBSERVACION, 
	 @LN_ALMACEN, @LN_SEC_ALMACEN, @LN_TIPO_PPTO

    WHILE @@FETCH_STATUS = 0
    BEGIN
        
	SELECT @LC_D_EMPLEADO = LTRIM(RTRIM(COALESCE(APELLIDO_PATERNO,''))) + ' ' + LTRIM(RTRIM(COALESCE(APELLIDO_MATERNO,''))) + ' ' + LTRIM(RTRIM(COALESCE(NOMBRES,''))) 
	  	FROM SIG_PERSONAL
		WHERE SEC_EJEC = @P_SEC_EJEC
                 AND EMPLEADO = @LC_EMPLEADO
		
          IF @LC_D_EMPLEADO IS NULL OR LTRIM(RTRIM(@LC_D_EMPLEADO)) = ''
                SET @LC_D_EMPLEADO = 'SIN DESCRIPCION'
		
	SELECT @LC_NRO_RUC = NRO_RUC,
               @LC_NOMBRE_PROV = DBO.f_elimina_tabs(NOMBRE_PROV)
		FROM SIG_CONTRATISTAS
		WHERE PROVEEDOR = @LN_PROVEEDOR
		
	SELECT @LC_NOMBRE_MOVIMIENTO = NOMBRE_MOVIMTO
		FROM SIG_TIPO_MOVIMIENTO 
		WHERE TIPO_MOVIMTO = @LC_TIPO_MOVIMIENTO
		AND TIPO_TRANSAC = @LN_TIPO_TRANSAC
		
	SELECT @LC_D_ALMACEN = ALM.NOMBRE_ALM
		FROM SIG_ALMACEN ALM 
		WHERE ALM.SEC_EJEC  = @P_SEC_EJEC 
		AND ALM.ALMACEN     = @LN_ALMACEN
		AND ALM.SEC_ALMACEN = @LN_SEC_ALMACEN		

        SET @LN_ID_SI_MOV_ALM = @LN_ID_SI_MOV_ALM + 1

        INSERT INTO SI_MOVIMIENTO_ALMACEN_TRX(
        ANO_EJE,SEC_EJEC,ID_SI_MOV_ALM, NRO_MOVIMIENTO,FECHA_MOVIMIENTO,NRO_GUIA_NEA,
        PROVEEDOR_NRO_RUC,D_PROVEEDOR,NRO_ORDEN,NRO_FACTURA,
        TIPO_MOVIMIENTO,TIPO_TRANSACCION,NOMBRE_MOVIMIENTO,EMPLEADO,D_EMPLEADO,
        TIPO_USO,OBSERVACION,ALMACEN,SEC_ALMACEN,D_ALMACEN,TIPO_PRESUPUESTO, 
	FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
        VALUES(
        @P_ANO_EJE,  @P_SEC_EJEC,  @LN_ID_SI_MOV_ALM, @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA,
	@LC_NRO_RUC, @LC_NOMBRE_PROV,  @LN_NRO_ORDEN, @LC_NRO_FACTURA, 
        @LC_TIPO_MOVIMIENTO, @LN_TIPO_TRANSAC, @LC_NOMBRE_MOVIMIENTO, @LC_EMPLEADO, @LC_D_EMPLEADO, 
        @LC_TIPO_USO, @LC_OBSERVACION, @LN_ALMACEN, @LN_SEC_ALMACEN, @LC_D_ALMACEN, @LN_TIPO_PPTO, 
	@fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(), @usuario_n)

        DECLARE C_2 CURSOR FOR
             SELECT B.GRUPO_BIEN, 
                    B.CLASE_BIEN, 
                    B.FAMILIA_BIEN, 
                    B.ITEM_BIEN,
                    C.CANT_ARTICULO,
                    B.PRECIO_UNIT,
                    (coalesce(C.CANT_ARTICULO,0) * coalesce(B.PRECIO_UNIT,0)),
                    B.UNIDAD_MEDIDA, 
                    B.MARCA, 
                    B.TIPO_USO, 
                    C.CLASIFICADOR, 
                    C.SEC_FUNC
             FROM SIG_DETALLE_MOVIM_ALMACEN B, 
                  SIG_DETALLE_MOVIM_PPTO C
             WHERE B.ANO_EJE      = C.ANO_EJE 
               AND B.SEC_EJEC     = C.SEC_EJEC 
               AND B.ALMACEN      = C.ALMACEN
               AND B.SEC_ALMACEN  = C.SEC_ALMACEN 
               AND B.TIPO_MOVIMTO = C.TIPO_MOVIMTO 
               AND B.TIPO_TRANSAC = C.TIPO_TRANSAC
               AND B.TIPO_PPTO    = C.TIPO_PPTO 
               AND B.NRO_MOVIMTO  = C.NRO_MOVIMTO 
               AND B.SECUENCIA    = C.SECUENCIA
               AND B.SEC_DETALLE  = C.SEC_DETALLE
               AND B.ANO_EJE      = @P_ANO_EJE 
               AND B.SEC_EJEC     = @P_SEC_EJEC
               AND B.ALMACEN      = @LN_ALMACEN 
               AND B.SEC_ALMACEN  = @LN_SEC_ALMACEN 
               AND B.TIPO_MOVIMTO = @LC_TIPO_MOVIMIENTO 
               AND B.TIPO_TRANSAC = @LN_TIPO_TRANSAC 
               AND B.TIPO_PPTO    = @LN_TIPO_PPTO 
               AND B.NRO_MOVIMTO  = @LN_NRO_MOVIMTO
          ORDER BY B.NRO_MOVIMTO

        OPEN C_2
        FETCH NEXT FROM C_2 
        INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, @LC_ITEM_BIEN, @LN_CANTIDAD_ITEM_BS,
             @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL, @LN_UNIDAD_MEDIDA, @LN_MARCA, @LC_TIPO_USO, 
	     @LC_CLASIFICADOR, @LN_SEC_FUNC

        WHILE @@FETCH_STATUS = 0
        BEGIN

            SET @LC_ITEM_CATALOGO = @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN
            
	    SELECT @LC_NOMBRE_ITEM = dbo.f_elimina_tabs(CAT.NOMBRE_ITEM)
              FROM CATALOGO_BIEN_SERV_ORIGINAL CAT
	     WHERE CAT.TIPO_BIEN    = 'B'
	              AND CAT.GRUPO_BIEN   = @LC_GRUPO_BIEN
        	      AND CAT.CLASE_BIEN   = @LC_CLASE_BIEN
	              AND CAT.FAMILIA_BIEN = @LC_FAMILIA_BIEN
        	      AND CAT.ITEM_BIEN    = @LC_ITEM_BIEN 
	    
         /*   SELECT @LC_D_UNIDAD_MEDIDA_ITEM_BS = M.NOMBRE
              FROM UNIDAD_MEDIDA M
              WHERE M.UNIDAD_MEDIDA = @LN_UNIDAD_MEDIDA*/
	    			
            SELECT @LC_META = META, 
                   @LC_UNIDAD_MEDIDA_META = UNIDAD_MEDIDA,
                   @LC_FINALIDAD = FINALIDAD
            FROM META
            WHERE ANO_EJE  = @P_ANO_EJE 
              AND SEC_EJEC = @P_SEC_EJEC
              AND SEC_FUNC = @LN_SEC_FUNC
			
		SELECT @LC_D_UNIDAD_MEDIDA_META = M.NOMBRE
		FROM UNIDAD_MEDIDA M
		WHERE M.UNIDAD_MEDIDA = @LC_UNIDAD_MEDIDA_META
		            		
		IF @LC_D_UNIDAD_MEDIDA_META IS NULL
			SET @LC_D_UNIDAD_MEDIDA_META = 'SIN DESCRIPCION'

		SELECT @LC_D_FINALIDAD = F.NOMBRE
		FROM FINALIDAD F
		WHERE F.ANO_EJE   = @P_ANO_EJE 
		AND F.FINALIDAD = @LC_FINALIDAD
		
		IF @LC_D_FINALIDAD IS NULL
                	SET @LC_D_FINALIDAD = 'SIN DESCRIPCION'

		SELECT @LC_D_MARCA = MA.NOMBRE
		FROM MARCA MA 
		WHERE MA.MARCA = @LN_MARCA
		AND MA.TIPO_MARCA = 1

		IF @LC_D_MARCA IS NULL
                	SET @LC_D_MARCA = 'SIN DESCRIPCION'

              SELECT @LN_ID_SI_MOV_ALM_DETA = MAX(SAD.ID_SI_MOV_ALM_DETA)
              FROM SI_MOVIMIENTO_ALMACEN_DETA_TRX SAD
	      WHERE SAD.ANO_EJE     = @P_ANO_EJE 
              AND SAD.SEC_EJEC      = @P_SEC_EJEC
              AND SAD.ID_SI_MOV_ALM = @LN_ID_SI_MOV_ALM

             IF @LN_ID_SI_MOV_ALM_DETA IS NULL
	              SET @LN_ID_SI_MOV_ALM_DETA = 0
             SET @LN_ID_SI_MOV_ALM_DETA = @LN_ID_SI_MOV_ALM_DETA + 1
                      
            INSERT INTO SI_MOVIMIENTO_ALMACEN_DETA_TRX
            ( ANO_EJE, SEC_EJEC, ID_SI_MOV_ALM, ID_SI_MOV_ALM_DETA, 
	      ITEM_CATALOGO, D_ITEM_CATALOGO,
              CANTIDAD_ITEM_BS, PRECIO_UNITARIO, PRECIO_TOTAL,
              UNIDAD_MEDIDA_ITEM_BS, D_UNIDAD_MEDIDA_ITEM_BS, MARCA, D_MARCA,
              TIPO_USO, CLASIFICADOR, SEC_FUNC, FINALIDAD, D_FINALIDAD,
              META, UNIDAD_MEDIDA_META, D_UNIDAD_MEDIDA_META, 
			  FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
             VALUES
            ( @P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_MOV_ALM, 
              @LN_ID_SI_MOV_ALM_DETA, @LC_ITEM_CATALOGO, '',
              @LN_CANTIDAD_ITEM_BS, @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL,
              @LN_UNIDAD_MEDIDA, '', @LN_MARCA, '',
              @LC_TIPO_USO, @LC_CLASIFICADOR, @LN_SEC_FUNC, @LC_FINALIDAD, '',
              @LC_META, @LC_UNIDAD_MEDIDA_META, '', 
			  @fecha_carga_inicio_1, @fecha_carga_fin_1, getdate(), @usuario_n)
	      
            FETCH NEXT FROM C_2 
            INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, 
                 @LC_ITEM_BIEN, @LN_CANTIDAD_ITEM_BS,
                 @LN_PRECIO_UNITARIO, @LN_PRECIO_TOTAL, @LN_UNIDAD_MEDIDA, 
                 @LN_MARCA, @LC_TIPO_USO, @LC_CLASIFICADOR, @LN_SEC_FUNC
         END
         CLOSE C_2
         DEALLOCATE C_2

         FETCH NEXT FROM C_1
         INTO @LN_NRO_MOVIMTO, @LD_FECHA_MOVIMIENTO, @LC_NRO_GUIA_NEA, 
              @LN_PROVEEDOR, @LN_NRO_ORDEN, 
              @LC_NRO_FACTURA, @LC_TIPO_MOVIMIENTO, @LN_TIPO_TRANSAC, @LC_EMPLEADO, 
	      @LC_TIPO_USO, @LC_OBSERVACION, @LN_ALMACEN, @LN_SEC_ALMACEN, @LN_TIPO_PPTO
     END
     CLOSE C_1
     DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_SI_CALCULO_FORMULA
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CALCULO_FORMULA]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CALCULO_FORMULA]
GO

CREATE PROCEDURE [dbo].[SP_SI_CALCULO_FORMULA]
	@Ano_eje    			NUMERIC(4,0),
	@Sec_ejec				NUMERIC(6,0),
	@Cod_establec			NUMERIC(6,0),
	@Sec_kit                NUMERIC (16,0),
    @IdSubFin				NUMERIC(10,0)
  
AS
BEGIN 

UPDATE SIG_PPR_KIT_ITEMS_EST 
	   SET CANTIDAD= (1 + FACTOR_MERMA) * ((CANTIDAD_CASO * PORCENT_USO / 100) / FACTOR_CONVERS)
	  FROM SI_PPR_KIT_ITEMS KIT
	 WHERE SIG_PPR_KIT_ITEMS_EST.ANO_EJE        = @Ano_eje						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_EJEC		= @Sec_ejec						AND
	       SIG_PPR_KIT_ITEMS_EST.ESTADO			= 'A'								AND
	       SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD=@IdSubFin					    	AND
	       SIG_PPR_KIT_ITEMS_EST.COD_ESTABLEC	= @Cod_establec						AND
	       SIG_PPR_KIT_ITEMS_EST.SEC_KIT		= @Sec_kit							AND
	       KIT.ANO_EJE							= SIG_PPR_KIT_ITEMS_EST.ANO_EJE		AND
	       KIT.SEC_KIT							= SIG_PPR_KIT_ITEMS_EST.SEC_KIT		AND
	       KIT.ID_SUB_FINALIDAD					= SIG_PPR_KIT_ITEMS_EST.ID_SUB_FINALIDAD AND
	       KIT.TIPO_CALCULO   	 				= 4			      					AND 
	       KIT.TIPO_BIEN 	   					= 'B'								AND
	       KIT.ESTADO		  					= 'A'								
	       

END
GO


-- ----------------------------
-- procedure structure for SP_PROCESAR_TECHOC_FASE_1
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_PROCESAR_TECHOC_FASE_1]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_PROCESAR_TECHOC_FASE_1]
GO

CREATE PROCEDURE [dbo].[SP_PROCESAR_TECHOC_FASE_1]
(@PN_ANIO NUMERIC, @PN_EJEC NUMERIC,@PN_FASE NUMERIC)
AS

BEGIN
	DECLARE @lI_FASE_CUADRO NUMERIC(1,0)
	DECLARE @ls_clasificador VARCHAR(20)
	DECLARE @ls_flag_presup VARCHAR(1)
	DECLARE @ls_centro_costo_presup VARCHAR(15)
	DECLARE @ls_centro_costo_cambio VARCHAR(15)
	DECLARE @ls_centro_costo VARCHAR(15)
	DECLARE @ls_centro_padre VARCHAR(15)
	DECLARE @ls_origen VARCHAR(1)
	DECLARE @ls_codi_fuen VARCHAR(2)
	DECLARE @ls_codi_fuen_impto VARCHAR(2)
	DECLARE @ls_clas_gast VARCHAR(20)
	DECLARE @ls_funcion VARCHAR(2)
	DECLARE @ls_programa VARCHAR(3)
	DECLARE @ld_Secu_func NUMERIC(4,0)
	DECLARE @li_contador NUMERIC(10,0)
	DECLARE @ld_valor_imp_progra NUMERIC(14,2)
	DECLARE @li_secuencia NUMERIC(10,0)
	DECLARE @ld_valor_progra NUMERIC(14,2)
	DECLARE @ld_valor_aprob NUMERIC(14,2)
	DECLARE @ld_mnto_impto NUMERIC(14,2)
	DECLARE @ld_monto_progra NUMERIC(14,2)
	DECLARE @ld_mnto_total NUMERIC(14,2)
	DECLARE @ld_mnto_apro NUMERIC(14,2)
	DECLARE @ld_mnto_asig NUMERIC(14,2)
	DECLARE @ld_mnto_modif NUMERIC(14,2)
	DECLARE @ls_categ_gasto VARCHAR(1)
	DECLARE @ls_grupo_gasto VARCHAR(1)
	DECLARE @ls_grupo VARCHAR(2)
	DECLARE @ls_grupo1 VARCHAR(2)
	DECLARE @ls_flag_gen_esp VARCHAR(1)
	DECLARE @ld_valor_imp_asignado NUMERIC(14,2)
	DECLARE @ld_valor_asignado NUMERIC(14,2)
	DECLARE @ld_monto_asignado NUMERIC(14,2)
	DECLARE @ld_monto_aprob NUMERIC(14,2)
	DECLARE @ld_valor_imp_aprob NUMERIC(14,2)
	declare @ld_min_correl numeric(8,0)
	declare @li_CUENTA numeric(10,0)  
	


	SELECT @ls_flag_gen_esp = VALOR
	FROM  SIG_PARAMETRO_EJECUTORA_ANIO
	WHERE ANO_EJE = @PN_ANIO AND SEC_EJEC = @PN_EJEC AND 
	COD_MAESTRO = 'FLAG_TECHO_NIVEL'
	
	

	SELECT @li_secuencia = ISNULL(MAX(secuencia),0) 
	FROM sig_techo_presupuesto 
