	0 , 0 , 0 , 0 ,
	mnto_progra,0, 0, 0 ,
	'1' ,0, 0 , 0 ,
	0 , NULL , '0' , NULL, 1
	from tmp_techo_fase_2

	IF @@ERROR <> 0
	BEGIN
		return -1
	END


END

	

