    @P_ANO_EJE               NUMERIC(4,0),
    @P_SEC_EJC               VARCHAR(10),
    @fecha_carga_inicio      VARCHAR(10),
    @fecha_carga_fin         VARCHAR(10),
    @usuario_n               VARCHAR(30),
    @O_ERR_NUM               NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG               VARCHAR(255) OUTPUT   
AS
	DECLARE @LD_FECHA_INI            DATETIME
	DECLARE @LD_FECHA_FIN            DATETIME
	DECLARE @LC_SEC_EJEC  		 NUMERIC(5)
	DECLARE @LC_ANO_EJE		 NUMERIC(5)

	DECLARE @LC_NOMBRE_DEPEND        VARCHAR(100)
	DECLARE @LC_CENTRO_COSTO	 VARCHAR(15)
	DECLARE @LC_EMPLEADO		 VARCHAR(15)
	DECLARE @LC_NOMBRE_COMPLETO	 VARCHAR(60) 
	DECLARE @LC_GRADO_INST	 	 VARCHAR(1)
	DECLARE @LC_NOMBRE_GRADO_INST	 VARCHAR(24)
	DECLARE @LC_NOMBRE 		 VARCHAR(100)	
	DECLARE @LC_DOCUM_IDENT		 VARCHAR(12)
	DECLARE @LC_CODIGO_PROF		 CHAR(3)
	DECLARE @LC_NOMBRE_PROF		 VARCHAR(150)
	DECLARE @LC_TIPO_EMPLEADO	 VARCHAR(21)

	DECLARE @SEDE                    NUMERIC(5,3)
	DECLARE @D_SEDE                  VARCHAR(50)
	DECLARE @COD_ESTABLEC            NUMERIC(5,0)
	DECLARE @COD_ESTABLEC_SIS        VARCHAR(20)
	DECLARE @D_COD_ESTABLEC          VARCHAR(200)
	DECLARE @COD_CATEGORIA           NUMERIC(5,0)
	DECLARE @D_CORTO_COD_CATEGORIA   VARCHAR(20)

	DECLARE @LC_FECHA_INGRESO			DATETIME
	DECLARE @LC_FECHA_NAC				DATETIME
	DECLARE @LC_SEXO_EMPLEADO			VARCHAR(1)
	DECLARE @LC_ESTADO_CIVIL			VARCHAR(1)
	DECLARE @LC_NRO_COLEGIATURA 			VARCHAR(25)
	DECLARE @LC_SITUACION_LABORAL			VARCHAR(1)
	DECLARE @LC_DESCRIPCION_SITUACION_LABORAL	VARCHAR(150)
	DECLARE @LC_REGIMEN_LABORAL			VARCHAR(2)
	DECLARE @LC_DESCRIPCION_REGIMEN_LABORAL		VARCHAR(150)
	DECLARE @LC_CONDICION_LABORAL			VARCHAR(1)
	DECLARE @LC_DESCRIPCION_CONDICION_LABORAL	VARCHAR(150)
	DECLARE @LC_FECHA_INGRESO_SIAF			DATETIME
	DECLARE @LC_FECHA_CESE				DATETIME
	DECLARE @LC_GRUPO_OCUPACIONAL			VARCHAR(2)
	DECLARE @LC_DESCRIPCION_GRUPO_OCUPACIONAL	VARCHAR(150)
	DECLARE @LC_CATEGORIA_OCUPACIONAL		VARCHAR(2)
	DECLARE @LC_D_CAT_OCUPACIONAL			VARCHAR(200)
	DECLARE @fecha_carga_inicio_1    DATETIME
	DECLARE @fecha_carga_fin_1       DATETIME
	DECLARE @LN_ID_SI_PERSONAL       NUMERIC(9)

BEGIN  
    TRUNCATE TABLE SI_PERSONAL
	
	SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio,101) 
	SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)

	IF @LN_ID_SI_PERSONAL IS NULL
    		SET @LN_ID_SI_PERSONAL = 0    

        DECLARE C_1 CURSOR FOR        
	  
	  SELECT P.SEC_EJEC,
          C.ANO_EJE,
          CC.NOMBRE_DEPEND,
          C.CENTRO_COSTO,
          P.EMPLEADO ,
          P.NOMBRE_COMPLETO ,
          P.GRADO_INST ,
          CASE P.GRADO_INST 
                  WHEN 'B' THEN 'BACHILLER'
                  WHEN 'T' THEN 'TITULADO'
                  WHEN 'U' THEN 'UNIVERSITARIA COMPLETA'
                  WHEN 'I' THEN 'UNIVERSITARIA INCOMPLETA'
                  WHEN 'O' THEN 'INSTITUTO'
                  WHEN 'G' THEN 'EGRESADO'
                  WHEN 'E' THEN 'ESTUDIANTE'
                  WHEN 'L' THEN 'LICENCIADO'
                  WHEN 'N' THEN 'TECNICO'
	  END NOMBRE_GRADO_INST,
	  (SELECT NOMBRE TD 
	     FROM TIPO_DOCUMENTO TD
	     WHERE P.TIPO_DOCUM_IDENT = TD.TIPO_DOCUMENTO
	   ) NOMBRE,
	  P.DOCUM_IDENT,
	  P.CODIGO_PROF,
	  ( select D.DESCRIPCION 
            from codigo_general_det D
            where codigo = 'TIPO_PROFESION'
            AND D.CODIGO_DET = P.CODIGO_PROF
          ) NOMBRE_PROF,
          CASE P.tipo_empleado 
                  WHEN 'N' THEN 'Nombrado'
                  WHEN 'F' THEN 'Contrato Plazo Fijo'
                  WHEN 'I' THEN 'Contrato Plazo Indet.'
                  WHEN 'S' THEN 'Contrato-SNP'
                  WHEN 'E' THEN 'Destacado Externo'
          END TIPO_EMPLEADO,
          P.Fecha_Ingreso,
          P.Fecha_Nac,
          P.Sexo_empleado,
          P.Estado_Civil,
          P.Nro_Colegiatura,
          D.SITUACION_LABORAL, 
          (select descripcion from codigo_general_det 
            	where codigo = 'SITUACION_LABORAL' 
		and codigo_det = D.SITUACION_LABORAL
          ) D_SITUACION_LABORAL,
          D.REGIMEN_LABORAL, 
          (select descripcion from codigo_general_det 
            	where codigo = 'REGIMEN_LABORAL'
            	and codigo_det = D.REGIMEN_LABORAL
          ) D_REGIMEN_LABORAL,
          D.CONDICION_LABORAL, 
          (select descripcion from codigo_general_det 
            	where codigo = 'CONDICION_LABORAL_SIAF'
            	and codigo_det = D.CONDICION_LABORAL
          ) D_CONDICION_LABORAL,
	  D.FECHA_INGRESO, 
          D.FECHA_CESE, 
          D.GRUPO_OCUPACIONAL, 
          (select descripcion from codigo_general_det 
             	where codigo = 'GRUPO_OCUPACIONAL'
             	and codigo_det = D.GRUPO_OCUPACIONAL
          ) D_GRUPO_OCUPACIONAL,
          D.CATEGORIA_OCUPACIONAL,
          (SELECT nombre
		FROM SIG_CATEGORIA_OCUPACIONAL
		where grupo_ocupacional = D.grupo_ocupacional 
                and categoria_ocupacional = D.categoria_ocupacional
          ) D_Cat_Ocupacional
	from SIG_PERSONAL P left outer 
	join SIG_PERSONAL_DET D on
	     (P.sec_ejec = D.sec_ejec and
	      P.empleado = D.empleado) left outer 
	join SIG_CENTRO_COSTO_PERSONAL C on
	     (C.SEC_EJEC = P.SEC_EJEC AND
	        C.EMPLEADO = P.EMPLEADO AND
	        C.ANO_EJE   = @P_ANO_EJE
	      )  left outer 
	join SIG_CENTRO_COSTO CC ON
      	(CC.ANO_EJE        = C.ANO_EJE and
        CC.SEC_EJEC       = C.SEC_EJEC and
        CC.CENTRO_COSTO = C.CENTRO_COSTO)
	where P.ESTADO   = 'A' 
	and P.SEC_EJEC = @P_SEC_EJC
	ORDER BY C.ANO_EJE, 
		 CC.NOMBRE_DEPEND, 
		 P.NOMBRE_COMPLETO 

    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO 
		@LC_SEC_EJEC, @LC_ANO_EJE, @LC_NOMBRE_DEPEND, @LC_CENTRO_COSTO, @LC_EMPLEADO, 
		@LC_NOMBRE_COMPLETO, @LC_GRADO_INST, @LC_NOMBRE_GRADO_INST, @LC_NOMBRE, 
		@LC_DOCUM_IDENT, @LC_CODIGO_PROF, @LC_NOMBRE_PROF, @LC_TIPO_EMPLEADO,
		@LC_FECHA_INGRESO, @LC_FECHA_NAC, @LC_SEXO_EMPLEADO, @LC_ESTADO_CIVIL, 
		@LC_NRO_COLEGIATURA, @LC_SITUACION_LABORAL, @LC_DESCRIPCION_SITUACION_LABORAL,	
		@LC_REGIMEN_LABORAL, @LC_DESCRIPCION_REGIMEN_LABORAL, @LC_CONDICION_LABORAL,			
		@LC_DESCRIPCION_CONDICION_LABORAL, @LC_FECHA_INGRESO_SIAF, @LC_FECHA_CESE,
		@LC_GRUPO_OCUPACIONAL, @LC_DESCRIPCION_GRUPO_OCUPACIONAL, 
		@LC_CATEGORIA_OCUPACIONAL, @LC_D_CAT_OCUPACIONAL	

    	 WHILE @@FETCH_STATUS = 0
    	 BEGIN
            	SET @LN_ID_SI_PERSONAL = @LN_ID_SI_PERSONAL + 1
 
 	           SELECT @SEDE                    = SCC.SEDE,
       			  @D_SEDE                    = DSD.NOMBRE_SEDE,
	       		  @COD_ESTABLEC            = CSD.COD_ESTABLEC,
	       		  @COD_ESTABLEC_SIS        = EESS.COD_INTERNO,
	       		  @D_COD_ESTABLEC            = EESS.DESC_ESTABLEC,
	       		  @COD_CATEGORIA            = EESS.CATEGORIA,
	       		  @D_CORTO_COD_CATEGORIA    = (SELECT CA.NOMBRE_CORTO FROM 
 				       	    	  SIG_PPR_CATEGORIA CA 
				        WHERE CA.ANO_EJE = CSD.ANO_EJE AND 
        	        		CA.CATEGORIA = EESS.CATEGORIA)  
					FROM  SIG_PPR_SEDE CSD JOIN SIG_CENTRO_COSTO  SCC ON
				     ( SCC.ANO_EJE      = CSD.ANO_EJE      AND
				       SCC.SEC_EJEC     = CSD.SEC_EJEC     AND
				       SCC.PLIEGO       = CSD.PLIEGO       AND
				       SCC.SEDE         = CSD.SEDE         AND
				       SCC.ESTADO       = 'A')
				JOIN SIG_SEDES DSD ON
			     ( DSD.SEDE   = CSD.SEDE AND
			       DSD.PLIEGO = CSD.PLIEGO ) ,
		     	SIG_PPR_ESTABLECIMIENTO EESS
			WHERE EESS.ANO_EJE      = CSD.ANO_EJE
		  	AND EESS.SEC_EJEC     = CSD.SEC_EJEC
		  	AND EESS.COD_ESTABLEC = CSD.COD_ESTABLEC
		  	AND CSD.ANO_EJE       = @P_ANO_EJE
		  	AND CSD.SEC_EJEC      = @P_SEC_EJC
		  	AND SCC.CENTRO_COSTO  = @LC_CENTRO_COSTO

		INSERT INTO SI_PERSONAL
                (ANO_EJE, SEC_EJEC, ID_SI_PERSONAL, NOMBRE_DEPEND, CENTRO_COSTO, 
		 EMPLEADO, NOMBRE_COMPLETO, GRADO_INST, NOMBRE_GRADO_INST,
		 NOMBRE, DOCUM_IDENT, CODIGO_PROF, NOMBRE_PROF, TIPO_EMPLEADO,
		 SEDE, D_SEDE, COD_ESTABLEC, COD_ESTABLEC_SIS, 
		 D_COD_ESTABLEC, COD_CATEGORIA, D_CORTO_COD_CATEGORIA,
  		 FECHA_INGRESO, FECHA_NAC, SEXO_EMPLEADO, ESTADO_CIVIL,
  		 NRO_COLEGIATURA, SITUACION_LABORAL, DESCRIPCION_SITUACION_LABORAL,
  		 REGIMEN_LABORAL, DESCRIPCION_REGIMEN_LABORAL,
  		 CONDICION_LABORAL, DESCRIPCION_CONDICION_LABORAL,
  		 FECHA_INGRESO_SIAF, FECHA_CESE, GRUPO_OCUPACIONAL,
  		 DESCRIPCION_GRUPO_OCUPACIONAL, CATEGORIA_OCUPACIONAL, D_CAT_OCUPACIONAL,
		 FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)
		VALUES 
                ( @P_ANO_EJE, @P_SEC_EJC, @LN_ID_SI_PERSONAL, @LC_NOMBRE_DEPEND, @LC_CENTRO_COSTO,
		  @LC_EMPLEADO, @LC_NOMBRE_COMPLETO, @LC_GRADO_INST, @LC_NOMBRE_GRADO_INST,
		  @LC_NOMBRE, @LC_DOCUM_IDENT, @LC_CODIGO_PROF, @LC_NOMBRE_PROF,
		  @LC_TIPO_EMPLEADO, @SEDE, @D_SEDE, @COD_ESTABLEC,
		  @COD_ESTABLEC_SIS, @D_COD_ESTABLEC, @COD_CATEGORIA,    
		  @D_CORTO_COD_CATEGORIA, @LC_FECHA_INGRESO,			
	 	  @LC_FECHA_NAC, @LC_SEXO_EMPLEADO, @LC_ESTADO_CIVIL,			
	 	  @LC_NRO_COLEGIATURA, @LC_SITUACION_LABORAL,			
	 	  @LC_DESCRIPCION_SITUACION_LABORAL, @LC_REGIMEN_LABORAL,			
	 	  @LC_DESCRIPCION_REGIMEN_LABORAL, @LC_CONDICION_LABORAL,			
	 	  @LC_DESCRIPCION_CONDICION_LABORAL, @LC_FECHA_INGRESO_SIAF,			
	 	  @LC_FECHA_CESE, @LC_GRUPO_OCUPACIONAL, @LC_DESCRIPCION_GRUPO_OCUPACIONAL,	
		  @LC_CATEGORIA_OCUPACIONAL, @LC_D_CAT_OCUPACIONAL, @fecha_carga_inicio_1, 
		  @fecha_carga_fin_1, convert(varchar(10),getdate(),112), @usuario_n)

    FETCH NEXT FROM C_1
    INTO 
		@LC_SEC_EJEC, @LC_ANO_EJE, @LC_NOMBRE_DEPEND, @LC_CENTRO_COSTO, @LC_EMPLEADO, 
		@LC_NOMBRE_COMPLETO, @LC_GRADO_INST, @LC_NOMBRE_GRADO_INST, @LC_NOMBRE, 
		@LC_DOCUM_IDENT, @LC_CODIGO_PROF, @LC_NOMBRE_PROF, @LC_TIPO_EMPLEADO,
		@LC_FECHA_INGRESO, @LC_FECHA_NAC, @LC_SEXO_EMPLEADO, @LC_ESTADO_CIVIL, 
		@LC_NRO_COLEGIATURA, @LC_SITUACION_LABORAL, @LC_DESCRIPCION_SITUACION_LABORAL,	
		@LC_REGIMEN_LABORAL, @LC_DESCRIPCION_REGIMEN_LABORAL, @LC_CONDICION_LABORAL,			
		@LC_DESCRIPCION_CONDICION_LABORAL, @LC_FECHA_INGRESO_SIAF, @LC_FECHA_CESE,
		@LC_GRUPO_OCUPACIONAL, @LC_DESCRIPCION_GRUPO_OCUPACIONAL, 
		@LC_CATEGORIA_OCUPACIONAL, @LC_D_CAT_OCUPACIONAL	
    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for SP_GENERA_SGE_KARDEX_MENSUAL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_GENERA_SGE_KARDEX_MENSUAL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_GENERA_SGE_KARDEX_MENSUAL]
GO

CREATE PROCEDURE [dbo].[SP_GENERA_SGE_KARDEX_MENSUAL] ( @Anio int,@Ejecutora int,@MesIni  varchar(2),@MesFin  varchar(2))
AS

DELETE FROM SGE_KARDEX_MENSUAL_EXP
	  WHERE ANO_EJE=@Anio
	    AND SEC_EJEC=@Ejecutora
        AND MES_PROCESO BETWEEN abs(@MesIni) AND abs(@MesFin);


INSERT INTO SGE_KARDEX_MENSUAL_EXP
            (ANO_EJE,SEC_EJEC,MES_PROCESO,TIPO_BIEN,CLASIFICADOR,MAYOR,SUB_CTA,TIPO_PPTO,
	    SEC_EJEC2,SECTOR,PLIEGO,TIPO_ENTIDAD,GRUPO_BIEN,CLASE_BIEN,FAMILIA_BIEN,
	    ITEM_BIEN,STOCK_INICIAL,CANT_INGRESO,CANT_EGRESO,
	    STOCK_ACTUAL,PRECIO_PROMED,SALDO_INICIAL,
	    VALOR_INGRESO,VALOR_EGRESO,SALDO_VALOR,FECHA_REG,CUSER_ID,UNIDAD_MEDIDA,DEPARTAMENTO,
	    PROVINCIA,CATEGORIA_GASTO,GRUPO,MODALIDAD,ELEMENTO_GASTO)
    SELECT S.ANO_EJE,S.SEC_EJEC,CAST(S.MES_PROCESO AS INT) MES_PROCESO,S.TIPO_BIEN,S.CLASIFICADOR,S.MAYOR,S.SUB_CTA,S.TIPO_PPTO,
	    S.SEC_EJEC2,E.SECTOR,E.PLIEGO,E.TIPO_ENTIDAD,S.GRUPO_BIEN,S.CLASE_BIEN,S.FAMILIA_BIEN,
	    S.ITEM_BIEN,SUM(S.STOCK_INICIAL) STOCK_INICIAL,SUM(S.CANT_INGRESO) CANT_INGRESO,SUM(S.CANT_EGRESO) CANT_EGRESO,
	    SUM(S.STOCK_ACTUAL) STOCK_ACTUAL,
	    ROUND(SUM(S.SALDO_VALOR)/CASE WHEN SUM(S.STOCK_ACTUAL)=0 THEN 1 ELSE SUM(S.STOCK_ACTUAL) END,2) PRECIO_PROMED,
	    SUM(S.SALDO_INICIAL) SALDO_INICIAL,SUM(S.VALOR_INGRESO) VALOR_INGRESO,SUM(S.VALOR_EGRESO) VALOR_EGRESO,
	    SUM(S.SALDO_VALOR) SALDO_VALOR,S.FECHA_REG,S.CUSER_ID,C.UNIDAD_MEDIDA,E.DEPARTAMENTO,
	    E.PROVINCIA,SUBSTRING(S.CLASIFICADOR,1,1) CATEGORIA_GASTO, SUBSTRING(S.CLASIFICADOR,2,1) GRUPO,
	    SUBSTRING(S.CLASIFICADOR,3,2) MODALIDAD,SUBSTRING(S.CLASIFICADOR,5,2) ELEMENTO_GASTO
       FROM SIG_KARDEX_POR_ALMACEN S, EJECUTORA E, CATALOGO_BIEN_SERV C
      WHERE S.SEC_EJEC=E.SEC_EJEC
        AND S.TIPO_BIEN=C.TIPO_BIEN
	AND S.GRUPO_BIEN=C.GRUPO_BIEN
	AND S.CLASE_BIEN=C.CLASE_BIEN
	AND S.FAMILIA_BIEN=C.FAMILIA_BIEN
	AND S.ITEM_BIEN=C.ITEM_BIEN
        AND S.ANO_EJE=@Anio
	AND S.SEC_EJEC=@Ejecutora
        AND S.MES_PROCESO BETWEEN @MesIni AND @MesFin
   GROUP BY S.ANO_EJE,S.SEC_EJEC,S.MES_PROCESO,S.TIPO_BIEN,S.CLASIFICADOR,S.MAYOR,S.SUB_CTA,S.TIPO_PPTO,
	    S.SEC_EJEC2,E.SECTOR,E.PLIEGO,E.TIPO_ENTIDAD,S.GRUPO_BIEN,S.CLASE_BIEN,S.FAMILIA_BIEN,
            S.ITEM_BIEN,S.FECHA_REG,S.CUSER_ID,C.UNIDAD_MEDIDA,E.DEPARTAMENTO,E.PROVINCIA;
--/
GO


-- ----------------------------
-- procedure structure for SP_SIG_PROC_CONT_PERIODO
-- ----------------------------
/* procedure [SP_SIG_PROC_CONT_PERIODO] is encrypted */

-- ----------------------------
-- procedure structure for SP_SI_CARGA_EJEC_PEDIDO_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_EJEC_PEDIDO_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_EJEC_PEDIDO_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_EJEC_PEDIDO_TRX]
	@P_ANO_EJE    NUMERIC(4,0),
	@P_SEC_EJEC   NUMERIC(6,0),
	@fecha_carga_inicio VARCHAR(10),
	@fecha_carga_fin    VARCHAR(10),
	@usuario_n    varchar(30),
	@O_ERR_NUM    NUMERIC(6,0) OUTPUT,
	@O_ERR_MSG    VARCHAR(255) OUTPUT
AS
DECLARE @fecha_carga_inicio_1 DATETIME,
		@fecha_carga_fin_1    DATETIME,
		@LS_TIPO_PEDIDO 	CHAR(1),  
		@LS_TIPO_BIEN 	    CHAR(1),    
		@LN_NRO_PEDIDO 		CHAR(5),	
	  	@LS_CENTRO_COSTO 	VARCHAR(15), 
	  	@LS_D_CENTRO_COSTO  VARCHAR(100), 
	  	@LD_FECHA_PEDIDO	DATETIME,
	  	@LS_MES_PEDIDO		CHAR(2),   
	  	@LS_MOTIVO_PEDIDO	VARCHAR(500), 
	  	@LN_SEC_FUNC		NUMERIC(16, 0),  	
	  	@LS_FINALIDAD		CHAR(5),		
	  	@LS_D_FINALIDAD  	VARCHAR(250),
	  	@LS_UNIDAD_MEDIDA	CHAR(3),
	  	@LS_D_UNIDAD_MEDIDA VARCHAR(100), 
	  	@LN_EMPLEADO		VARCHAR(15),		  		
	  	@LS_TIPO_USO		CHAR(1),
	  	@LS_ESTADO		    CHAR(1),		  
	  	@LS_D_EMPLEADO		VARCHAR(60),
	  	@LN_ID_SI_PEDIDO	NUMERIC(16,0),
       --/*DETALLE*/-----
        @LN_ID_SI_PEDIDO_DETA NUMERIC(16),  
        @LS_ITEM_CATALOGO     VARCHAR(20),
        @LS_D_ITEM_CATALOGO   VARCHAR(150),	/*FACT*/
        @LS_UNIDAD_MEDIDA_ITEM_BS   NUMERIC(3),	
        @LS_D_UNIDAD_MEDIDA_ITEM_BS VARCHAR(100),
        @LS_CLASIFICADOR 	CHAR(20),		
        @LN_CANT_SOLICITADA NUMERIC(16,6),	         
        @LN_PRECIO_UNIT NUMERIC(16,6),			
        @LN_VALOR_TOTAL NUMERIC(16,2),			
        @LN_NRO_ORDEN   NUMERIC(18),				
        @LN_NRO_CUADRO  NUMERIC(18),			
        @LS_ESTADO_PED  CHAR(1),
        @LN_CANT_APROBADA NUMERIC(16,6),		
        @LN_CANT_ATENDIDA NUMERIC(16,6),			
        @LN_NRO_PECOSA    NUMERIC(18),				
        @LD_FECHA_PECOSA  DATETIME ,
	@LS_GRUPO_BIEN  CHAR(2) ,
	@LS_CLASE_BIEN  CHAR(2),
	@LS_FAMILIA_BIEN CHAR(4),  
	@LS_ITEM_BIEN CHAR(4)
		
DECLARE C_1 CURSOR FOR
	SELECT
	    A.TIPO_PEDIDO,
	    A.TIPO_BIEN,
	    A.NRO_PEDIDO,
	    A.CENTRO_COSTO,
        dbo.f_elimina_tabs(E.NOMBRE_DEPEND) D_CENTRO_COSTO,
	    A.FECHA_PEDIDO,
	    A.MES_PEDIDO,
	    dbo.f_elimina_tabs(A.MOTIVO_PEDIDO) MOTIVO_PEDIDO,
	    A.sec_func,
	    B.finalidad,
	    C.nombre D_FINALIDAD,
	    B.unidad_med UNIDAD_MEDIDA_META,
	    dbo.f_elimina_tabs(D.NOMBRE) D_UNIDAD_MEDIDA_META,
	    A.EMPLEADO,
	    A.TIPO_USO,
	    A.ESTADO,	    
	    F.nombre_completo D_EMPLEADO
	FROM SIG_PEDIDOS A
	JOIN META B
	    ON  B.ano_eje = A.ANO_EJE
	    AND B.sec_ejec = A.SEC_EJEC
	    AND B.sec_func = A.sec_func
	JOIN FINALIDAD C
	    ON  C.ANO_EJE = B.ano_eje
	    AND C.finalidad = B.finalidad
	LEFT JOIN UNIDAD_MEDIDA D
	    ON  D.UNIDAD_MEDIDA = B.unidad_med
	JOIN SIG_CENTRO_COSTO E
	    ON  E.ANO_EJE = A.ANO_EJE
	    AND E.SEC_EJEC = A.SEC_EJEC
	    AND E.CENTRO_COSTO = A.CENTRO_COSTO
	LEFT JOIN SIG_PERSONAL F
	    ON  F.sec_ejec = A.SEC_EJEC
	    AND F.empleado = A.EMPLEADO
	WHERE A.ANO_EJE = @P_ANO_EJE
          AND A.SEC_EJEC= @P_SEC_EJEC	
          AND A.TIPO_PEDIDO = '2'	
BEGIN 		

     SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
     SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)    
     
	-- Actualiza cod_renaes para el @P_ANO_EJE	
	update sig_ppr_establecimiento	
	   set cod_ogei = (select top 1 eess.cod_ogei
			     from sig_ppr_establecimiento eess					
			    where (@P_ANO_EJE + 1) = eess.ano_eje				and 
			     sig_ppr_establecimiento.sec_ejec = eess.sec_ejec	and 
			     sig_ppr_establecimiento.cod_establec = eess.cod_establec And 
			     eess.cod_ogei is not null)	
	 where sig_ppr_establecimiento.ano_eje  = @P_ANO_EJE	and 
	   	   sig_ppr_establecimiento.sec_ejec = @P_SEC_EJEC 
	   	   
	-- Elimina tabla que genera el txt
	DELETE FROM SI_PEDIDO_DETA_TRX
     	delete from SI_PEDIDO_TRX


     SELECT @LN_ID_SI_PEDIDO = MAX(ID_SI_PEDIDO) 
       FROM SI_PEDIDO_TRX
      WHERE ANO_EJE  = @P_ANO_EJE AND SEC_EJEC = @P_SEC_EJEC
	 
     IF @LN_ID_SI_PEDIDO IS NULL  SET @LN_ID_SI_PEDIDO = 0

     OPEN C_1
	FETCH NEXT FROM C_1
	INTO @LS_TIPO_PEDIDO,  @LS_TIPO_BIEN,    @LN_NRO_PEDIDO,	
	     @LS_CENTRO_COSTO,	@LS_D_CENTRO_COSTO, 	@LD_FECHA_PEDIDO, @LS_MES_PEDIDO,   @LS_MOTIVO_PEDIDO, 
	     @LN_SEC_FUNC,  	@LS_FINALIDAD,		@LS_D_FINALIDAD,  @LS_UNIDAD_MEDIDA,@LS_D_UNIDAD_MEDIDA, 
	     @LN_EMPLEADO,  	@LS_TIPO_USO, 		@LS_ESTADO,	  @LS_D_EMPLEADO

	     WHILE @@FETCH_STATUS = 0
	     BEGIN
	     	SET @LN_ID_SI_PEDIDO = @LN_ID_SI_PEDIDO + 1 
		-- Carga data en tabla
		INSERT INTO dbo.SI_PEDIDO_TRX
		(ANO_EJE,         SEC_EJEC,       ID_SI_PEDIDO,	 TIPO_PEDIDO,    TIPO_BIEN,          NRO_PEDIDO,
	     CENTRO_COSTO,    D_CENTRO_COSTO, FECHA_PEDIDO,   MES_PEDIDO,         MOTIVO_PEDIDO,  
	     sec_func,        finalidad,      D_FINALIDAD,    UNIDAD_MEDIDA_META, D_UNIDAD_MEDIDA_META , 
	     EMPLEADO,        TIPO_USO,       ESTADO,         D_EMPLEADO,         META,          
	     FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO,  USUARIO_ENVIO  )      
		VALUES
	  	(@P_ANO_EJE ,	    @P_SEC_EJEC,	   @LN_ID_SI_PEDIDO, @LS_TIPO_PEDIDO,  @LS_TIPO_BIEN,    @LN_NRO_PEDIDO,	
	  	 @LS_CENTRO_COSTO,  @LS_D_CENTRO_COSTO,@LD_FECHA_PEDIDO, @LS_MES_PEDIDO,   @LS_MOTIVO_PEDIDO, 
	  	 @LN_SEC_FUNC,      @LS_FINALIDAD,	   @LS_D_FINALIDAD,  @LS_UNIDAD_MEDIDA,@LS_D_UNIDAD_MEDIDA  , 
	  	 @LN_EMPLEADO,      @LS_TIPO_USO, 	   @LS_ESTADO,	  	 @LS_D_EMPLEADO,   @LN_SEC_FUNC,
		 @fecha_carga_inicio_1, @fecha_carga_fin_1,GETDATE(), 	@usuario_n)

		DECLARE C_2 CURSOR FOR  
		SELECT
			    A.GRUPO_BIEN,
			    A.CLASE_BIEN,
			    A.FAMILIA_BIEN,
			    A.ITEM_BIEN,
			    dbo.f_elimina_tabs(B.NOMBRE_ITEM) D_ITEM_CATALOGO,
			    B.UNIDAD_MEDIDA UNIDAD_MEDIDA_ITEM_BS,
			    C.NOMBRE D_UNIDAD_MEDIDA_ITEM_BS,
			    A.CLASIFICADOR,
			    A.CANT_SOLICITADA,
			    A.PRECIO_UNIT,
			    A.VALOR_TOTAL,
			    A.NRO_ORDEN,
			    A.NRO_CUADRO,
			    A.ESTADO_PED,
			    A.CANT_APROBADA,
			    A.CANT_ATENDIDA,
			    A.NRO_PECOSA,
			    A.FECHA_PECOSA
			FROM SIG_DETALLE_PEDIDOS A
			JOIN CATALOGO_BIEN_SERV B
				    ON  B.SEC_EJEC = A.sec_ejec
				    AND B.TIPO_BIEN = A.TIPO_BIEN
				    AND B.GRUPO_BIEN = A.GRUPO_BIEN
				    AND B.CLASE_BIEN = A.CLASE_BIEN
				    AND B.FAMILIA_BIEN = A.FAMILIA_BIEN
				    AND B.ITEM_BIEN = A.ITEM_BIEN
				LEFT JOIN UNIDAD_MEDIDA C
				    ON  C.UNIDAD_MEDIDA = B.UNIDAD_MEDIDA
			WHERE 
				    A.ANO_EJE        = @P_ANO_EJE        AND 
				    A.sec_ejec       = @P_SEC_EJEC        AND
				    A.TIPO_BIEN      = @LS_TIPO_BIEN    AND
				    A.TIPO_PEDIDO    = '2' AND
				    A.NRO_PEDIDO     = @LN_NRO_PEDIDO
			
			
		 SELECT @LN_ID_SI_PEDIDO_DETA = MAX(ID_SI_PEDIDO_DETA) 
		   FROM SI_PEDIDO_DETA_TRX
	 	  WHERE ANO_EJE  = @P_ANO_EJE AND SEC_EJEC = @P_SEC_EJEC
	 
	    	 IF @LN_ID_SI_PEDIDO_DETA IS NULL  	SET @LN_ID_SI_PEDIDO_DETA = 0
	 
		 OPEN C_2                                                                                                 
	     FETCH NEXT FROM C_2                                                                                      
		      INTO @LS_GRUPO_BIEN, 	@LS_CLASE_BIEN, 	@LS_FAMILIA_BIEN,   @LS_ITEM_BIEN,--,	@LS_ITEM_CATALOGO,
			   @LS_D_ITEM_CATALOGO, @LS_UNIDAD_MEDIDA_ITEM_BS,@LS_D_UNIDAD_MEDIDA_ITEM_BS,	@LS_CLASIFICADOR,	    
			   @LN_CANT_SOLICITADA, @LN_PRECIO_UNIT,	@LN_VALOR_TOTAL,		@LN_NRO_ORDEN,		
			   @LN_NRO_CUADRO,		@LS_ESTADO_PED,     @LN_CANT_APROBADA,		@LN_CANT_ATENDIDA,	    
			   @LN_NRO_PECOSA,      @LD_FECHA_PECOSA
				
		 WHILE @@FETCH_STATUS = 0                    
	     BEGIN 
        	 set @LS_ITEM_CATALOGO     = @LS_GRUPO_BIEN+@LS_CLASE_BIEN+@LS_FAMILIA_BIEN+@LS_ITEM_BIEN
		 	 set @LN_ID_SI_PEDIDO_DETA = @LN_ID_SI_PEDIDO_DETA + 1

	      INSERT INTO SI_PEDIDO_DETA_TRX
	     (ANO_EJE, 			SEC_EJEC, 		ID_SI_PEDIDO,			ID_SI_PEDIDO_DETA,	ITEM_CATALOGO, 
	      D_ITEM_CATALOGO,  UNIDAD_MEDIDA_ITEM_BS,D_UNIDAD_MEDIDA_ITEM_BS,	CLASIFICADOR,		CANT_SOLICITADA,
		  PRECIO_UNIT,		VALOR_TOTAL,		NRO_ORDEN,			NRO_CUADRO,		ESTADO_PED,
		  CANT_APROBADA,	CANT_ATENDIDA,		NRO_PECOSA,			FECHA_PECOSA,  	FECHA_CARGA_INICIO,
		  FECHA_CARGA_FIN,	FECHA_ENVIO,		USUARIO_ENVIO          )
         VALUES
         (@P_ANO_EJE, 			@P_SEC_EJEC, 			  @LN_ID_SI_PEDIDO, 		@LN_ID_SI_PEDIDO_DETA,  @LS_ITEM_CATALOGO,
          @LS_D_ITEM_CATALOGO,	@LS_UNIDAD_MEDIDA_ITEM_BS,@LS_D_UNIDAD_MEDIDA_ITEM_BS,	@LS_CLASIFICADOR,	@LN_CANT_SOLICITADA,	         
          COALESCE(@LN_PRECIO_UNIT, 0),		COALESCE(@LN_VALOR_TOTAL, 0),		  @LN_NRO_ORDEN,			@LN_NRO_CUADRO,			@LS_ESTADO_PED,
          @LN_CANT_APROBADA,	@LN_CANT_ATENDIDA,		  @LN_NRO_PECOSA,			@LD_FECHA_PECOSA,		@fecha_carga_inicio_1,
          @fecha_carga_inicio_1,GETDATE(),				  @usuario_n )
         
          	 FETCH NEXT FROM C_2                                                                                
               	 INTO  @LS_GRUPO_BIEN, 	@LS_CLASE_BIEN, 	@LS_FAMILIA_BIEN,   @LS_ITEM_BIEN,--,	@LS_ITEM_CATALOGO,
			   @LS_D_ITEM_CATALOGO, @LS_UNIDAD_MEDIDA_ITEM_BS,@LS_D_UNIDAD_MEDIDA_ITEM_BS,	@LS_CLASIFICADOR,	    
			   @LN_CANT_SOLICITADA, @LN_PRECIO_UNIT,	@LN_VALOR_TOTAL,		@LN_NRO_ORDEN,		
			   @LN_NRO_CUADRO,		@LS_ESTADO_PED,     @LN_CANT_APROBADA,		@LN_CANT_ATENDIDA,	    
			   @LN_NRO_PECOSA,      @LD_FECHA_PECOSA                             
             END                                                                                                    
             CLOSE C_2                                                                                              
             DEALLOCATE C_2                                                                                         
                                                                                                                  
          FETCH NEXT FROM C_1                                                                                    
          INTO @LS_TIPO_PEDIDO,  @LS_TIPO_BIEN,    @LN_NRO_PEDIDO,	
	     @LS_CENTRO_COSTO,	@LS_D_CENTRO_COSTO, 	@LD_FECHA_PEDIDO, @LS_MES_PEDIDO,   @LS_MOTIVO_PEDIDO, 
	     @LN_SEC_FUNC,  	@LS_FINALIDAD,		@LS_D_FINALIDAD,  @LS_UNIDAD_MEDIDA,@LS_D_UNIDAD_MEDIDA, 
	     @LN_EMPLEADO,  	@LS_TIPO_USO, 		@LS_ESTADO,	  @LS_D_EMPLEADO                   
       END                                                                                                        
       CLOSE C_1                                                                                                  
       DEALLOCATE C_1                                                                                             
END
GO


-- ----------------------------
-- procedure structure for DT_GETOBJWITHPROP
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_GETOBJWITHPROP]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_GETOBJWITHPROP]
GO

CREATE PROCEDURE [dbo].[DT_GETOBJWITHPROP]
	@property varchar(30),
	@value varchar(255)
as
	set nocount on

	if (@property is null) or (@property = '')
	begin
		raiserror('Must specify a property name.',-1,-1)
		return (1)
	end

	if (@value is null)
		select objectid id from dbo.dtproperties
			where property=@property

	else
		select objectid id from dbo.dtproperties
			where property=@property and value=@value
GO


