-- ----------------------------
-- procedure structure for DT_REMOVEFROMSOURCECONTROL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DT_REMOVEFROMSOURCECONTROL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[DT_REMOVEFROMSOURCECONTROL]
GO

CREATE PROCEDURE [dbo].[DT_REMOVEFROMSOURCECONTROL]

as

    set nocount on

    declare @iPropertyObjectId int
    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = 'VCSProjectID')

    exec dbo.dt_droppropertiesbyid @iPropertyObjectId, null

    /* -1 is returned by dt_droppopertiesbyid */
    if @@error <> 0 and @@error <> -1 return 1

    return 0
GO


-- ----------------------------
-- procedure structure for SP_SIG_KARDEX_PEPS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SIG_KARDEX_PEPS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SIG_KARDEX_PEPS]
GO

CREATE PROCEDURE [dbo].[SP_SIG_KARDEX_PEPS]
@an_ano_eje numeric(4), @an_sec_ejec numeric(6), @as_almacen varchar(3), @as_sec_alma varchar(3), @as_mes varchar(2), @as_tipo_uso varchar(1), 
@an_tipo_ppto numeric(2), @an_encargo numeric(6), @as_tipo_bien varchar(1), @as_grup_bien varchar(2), @as_clas_bien varchar(2),
@as_fami_bien varchar(4), @as_item_bien varchar(4), @as_clas_gast varchar(20), @as_plan_mayo varchar(4), @as_plan_scta varchar(8),
@as_usuing varchar(8), @adt_fecha_actual datetime, @as_equipo varchar(20), @as_message varchar(100) output, @as_origen varchar(1)
------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------
AS
DECLARE
@ls_codi_bien_para varchar(12),
@ls_mess_proc varchar(2),
@ls_mess_maxi varchar(2),
@ls_mess_sali varchar(2),
@ls_mess_kard varchar(2),
@ld_cont numeric(5),
@ld_cont_ingr numeric(5),
@ldec_kard_ican numeric(18,4),
@ldec_kard_ival numeric(14,2),
@ldec_kard_scan numeric(18,4),
@ldec_kard_sval numeric(14,2),
@ldec_kard_acan numeric(18,4),
@ldec_kard_aval numeric(14,2),
@ldec_kard_tcan numeric(18,4),
@ldec_kard_tval numeric(14,2),
@ls_tipo_uso  varchar(1),
@ls_tipo_bien varchar(1),
@ls_grup_bien varchar(2),
@ls_clas_bien varchar(2),
@ls_fami_bien varchar(4),
@ls_item_bien varchar(4),
@ls_clas_gast varchar(20),
@ls_plan_mayo varchar(4),
@ls_plan_scta varchar(8),
@ls_acti_fijo varchar(1),
@ls_flag_item varchar(1),
@ls_tipo_movi varchar(1),
@ls_flag_acti varchar(1),
@ls_tipo_acti varchar(1),
@ls_tipo_dest varchar(2),
@ls_moda_dest varchar(2),
@ls_flag_dest varchar(1),
@ls_acti_proy varchar(7),
@ls_orig_fuen varchar(1),
@ls_codi_fuen varchar(2),
@ls_tipo_natu varchar(1),
@ls_codi_bien varchar(12),
@ls_tipo_marc varchar(1),
@ls_correlati varchar(4),
@ld_codi_marc numeric(5),
@ld_sec_ejec2 numeric(6),
@ld_encargo   numeric(6),
@ld_operacion numeric(10),
@ldec_prec_unit numeric(16,6),
@ldec_valo_tota numeric(14,2),
@ld_secu_func numeric(4),
@ls_tmovi_sali varchar(1),
@ls_tmovi_ingr varchar(1),
@ls_cent_cost  varchar(15),
@ld_trans_sali numeric(2),
--@ld_nmovi_sali numeric(5),
@ld_nmovi_sali numeric(6),
@ld_secue_sali numeric(2),
@ldec_canti_sali numeric(18,4),
@ld_sdeta_sali numeric(5),
@ld_trans_ingr numeric(2),
--@ld_nmovi_ingr numeric(5),
@ld_nmovi_ingr numeric(6),
@ld_secue_ingr numeric(2),
@ld_sdeta_ingr numeric(5),
@ldec_stock_ingr numeric(18,4),
@ldec_cant_aten numeric(18,4),
@ldec_valo_ingr numeric(14,2),
@lb_continue varchar(1),
@ldt_fech_movi datetime,
@ldt_fmov_temp datetime,
@ldt_freg_temp datetime,
@ldec_anua_acan numeric(18,4),
@ldec_anua_aval numeric(14,2),
@ldec_anua_ican numeric(18,4),
@ldec_anua_ival numeric(14,2),
@ldec_anua_scan numeric(18,4),
@ldec_anua_sval numeric(14,2),
@ld_mes numeric(2),
@ls_tmovi_devo varchar(1),
@ld_trans_devo numeric(2),
@ld_tppto_devo numeric(1),
--@ld_nmovi_devo numeric(5),
@ld_nmovi_devo numeric(6),
@ld_secue_devo numeric(2),
@ld_sdeta_devo numeric(5),
@ld_canti_devo numeric(18,4),
@ls_temp_mayo varchar(10),
--Nro.Pedido
@ls_tipo_pedi varchar(1),
--@ls_nume_pedi varchar(5),
@ls_nume_pedi varchar(6),
@ld_secu_pedi numeric(4),
@ld_secu_peco numeric(2),
@ls_kard_peco varchar(1),
@ld_unid_medi numeric(3),
@ld_item_bien_det numeric(5),
@ld_sec_atencion numeric(2),
@ld_sec_atencion_orden numeric(2),
@ls_kardex_clasif varchar(1),
@ld_kardex_verifi  numeric(1),
@ls_clasi_sali varchar(20)

create table #ld_sdeta_sala (fila int, valor numeric(5))

set @ldec_kard_ican = 0
set @ldec_kard_ival = 0
set @ldec_kard_scan = 0
set @ldec_kard_sval = 0
set @ldec_kard_acan = 0
set @ldec_kard_aval = 0
set @ldec_kard_tcan = 0
set @ldec_kard_tval = 0
set @ls_correlati = '0001'
set @ldec_prec_unit = 0
set @ldec_valo_tota = 0
set @ldec_canti_sali = 0
set @ldec_stock_ingr = 0
set @ldec_cant_aten = 0
set @ldec_valo_ingr = 0
set @lb_continue = 'N'
set @ldec_anua_acan = 0
set @ldec_anua_aval = 0
set @ldec_anua_ican = 0
set @ldec_anua_ival = 0
set @ldec_anua_scan = 0
set @ldec_anua_sval = 0
set @ld_canti_devo = 0

set @ls_codi_bien_para = @as_grup_bien + @as_clas_bien + @as_fami_bien + @as_item_bien
set @ls_mess_maxi = @as_mes

-- Si parametro existe y esta activo se trabaja sin clasificador en kardex
set @ls_kardex_clasif = 'S'

SELECT @ld_kardex_verifi = count(*)
  FROM sig_maestro_det_numerico 
 WHERE cod_maestro = 'PARAMETRO' AND
       cod_detalle = 1 AND
       @an_ano_eje >= valor_numerico AND
       estado = 'A'

set @ld_kardex_verifi = isnull(@ld_kardex_verifi, 0)

If (@ld_kardex_verifi > 0)
Begin
	set @as_clas_gast = '%'
	set @ls_kardex_clasif = 'N'
End
--

  SELECT @ls_kard_peco = valor  
    FROM sig_parametro_ejecutora  
   WHERE sec_ejec = @an_sec_ejec AND  
         cod_maestro = 'FLAG_KARD_PECOSA' ;

set @ls_kard_peco = isnull(@ls_kard_peco, '0')
If (@ls_kard_peco = '')
   set @ls_kard_peco = '0'

  SELECT @ls_mess_kard = max(mes_proceso)  
    FROM sig_kardex_por_almacen  
   WHERE ano_eje     = @an_ano_eje  AND  
         sec_ejec    = @an_sec_ejec AND  
         almacen     = @as_almacen  AND  
         sec_almacen = @as_sec_alma 

set @ls_mess_kard = isnull(@ls_mess_kard, '00')
If (@ls_mess_kard = '')
	set @ls_mess_kard = '00'

If (@ls_mess_kard > @ls_mess_maxi)
	set @ls_mess_maxi = @ls_mess_kard

 UPDATE sig_kardex_por_almacen
    SET cant_ingreso  = 0, cant_egreso   = 0, stock_actual  = 0,
	saldo_valor   = 0, precio_promed = 0,
	valor_ingreso = 0, valor_egreso  = 0
  WHERE ano_eje     = @an_ano_eje  and
	sec_ejec    = @an_sec_ejec and
	mes_proceso >= @as_mes     and
	almacen     = @as_almacen  and
	sec_almacen = @as_sec_alma and
	tipo_bien    like @as_tipo_bien and
	codigo_bien  like @ls_codi_bien_para and
	clasificador like @as_clas_gast and
	mayor        like @as_plan_mayo and
	sub_cta      like @as_plan_scta and
	tipo_uso in (SELECT DISTINCT d.tipo_uso
			   FROM sig_detalle_movim_almacen d,
				sig_movim_almacen m
			  WHERE d.ano_eje      = m.ano_eje  and
				d.sec_ejec     = m.sec_ejec and
				d.almacen      = m.almacen  and
				d.sec_almacen  = m.sec_almacen  and
				d.tipo_movimto = m.tipo_movimto and
				d.tipo_transac = m.tipo_transac and
				d.tipo_ppto    = m.tipo_ppto    and
				d.nro_movimto  = m.nro_movimto  and
				m.estado_kardex= 'S' and
				d.ano_eje      = @an_ano_eje    and
				d.sec_ejec     = @an_sec_ejec   and
				d.almacen      = @as_almacen    and
				d.sec_almacen  = @as_sec_alma   and
				d.tipo_movimto in ('A','I','S') and
				m.tipo_ppto    = @an_tipo_ppto  and
				((@an_tipo_ppto = 1) or
				 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
				((@as_origen = '2'  and d.tipo_uso = @as_tipo_uso) or
				 (@as_origen <> '2' and m.tipo_uso = @as_tipo_uso)) and
				d.cant_articulo >= 0            and
				d.tipo_bien    like @as_tipo_bien and
				d.grupo_bien   like @as_grup_bien and
				d.clase_bien   like @as_clas_bien and
				d.familia_bien like @as_fami_bien and
				d.item_bien    like @as_item_bien and
				d.clasificador like @as_clas_gast and
				d.mayor        like @as_plan_mayo and
				d.sub_cta      like @as_plan_scta ) and
	tipo_ppto   = @an_tipo_ppto and
	secuencia   = @an_encargo 

IF (@@ERROR <> 0)
BEGIN
	set @as_message = 'No se puede inicializar los valores del Kardex :'
	return -1
End

 UPDATE sig_kardex_por_almacen
    SET cant_ingreso  = 0, cant_egreso   = 0, stock_actual  = 0,
	saldo_valor   = 0, precio_promed = 0,
	valor_ingreso = 0, valor_egreso  = 0
  WHERE ano_eje     = @an_ano_eje  and
	sec_ejec    = @an_sec_ejec and
	mes_proceso >= @as_mes     and
	almacen     = @as_almacen  and
	sec_almacen = @as_sec_alma and
	tipo_bien    like @as_tipo_bien and
	codigo_bien  like @ls_codi_bien_para and
	clasificador like @as_clas_gast and
	mayor        like @as_plan_mayo and
	sub_cta      like @as_plan_scta and
	tipo_uso     like @as_tipo_uso and
	tipo_ppto   = @an_tipo_ppto and
	secuencia   = @an_encargo 

IF (@@ERROR <> 0)
BEGIN
	set @as_message = 'No se puede inicializar los valores del Kardex(2):'
	return -1
End

--d.activo_fijo,
DECLARE c_item CURSOR FOR
SELECT DISTINCT d.tipo_bien, d.grupo_bien, d.clase_bien,
		d.familia_bien, d.item_bien, d.marca,
		m.nro_encargo, m.sec_ejec2, case @ls_kardex_clasif when 'N' then '0' else d.clasificador end as clasificador,
		d.mayor, d.sub_cta, 
		d.tipo_marca, d.tipo_uso,
		d.unidad_medida, d.item_bien_det
   FROM sig_detalle_movim_almacen d,
	sig_movim_almacen m
  WHERE d.ano_eje      = m.ano_eje  and
	d.sec_ejec     = m.sec_ejec and
	d.almacen      = m.almacen  and
	d.sec_almacen  = m.sec_almacen  and
	d.tipo_movimto = m.tipo_movimto and
	d.tipo_transac = m.tipo_transac and
	d.tipo_ppto    = m.tipo_ppto    and
	d.nro_movimto  = m.nro_movimto  and
	m.estado_kardex= 'S' and
	d.ano_eje      = @an_ano_eje    and
	d.sec_ejec     = @an_sec_ejec   and
	d.almacen      = @as_almacen    and
	d.sec_almacen  = @as_sec_alma   and
	d.tipo_movimto in ('A','I','S') and
	m.tipo_ppto    = @an_tipo_ppto  and
	((@an_tipo_ppto = 1) or
	 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
	((@as_origen = '2'  and d.tipo_uso = @as_tipo_uso) or
	 (@as_origen <> '2' and m.tipo_uso = @as_tipo_uso)) and
	d.cant_articulo >= 0            and
	d.tipo_bien    like @as_tipo_bien and
	d.grupo_bien   like @as_grup_bien and
	d.clase_bien   like @as_clas_bien and
	d.familia_bien like @as_fami_bien and
	d.item_bien    like @as_item_bien and
	d.clasificador like @as_clas_gast and
	d.mayor        like @as_plan_mayo and
	d.sub_cta      like @as_plan_scta 

OPEN c_item
FETCH NEXT FROM c_item INTO @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien,
			@ls_item_bien, @ld_codi_marc, @ld_encargo, @ld_sec_ejec2,
			@ls_clas_gast, @ls_plan_mayo, @ls_plan_scta, 
			@ls_tipo_marc, @ls_tipo_uso, @ld_unid_medi, @ld_item_bien_det
--@ls_acti_fijo,
WHILE @@FETCH_STATUS = 0
BEGIN
	 SELECT @ls_flag_item = flag_item, @ls_flag_acti = flag_activo, @ls_tipo_acti = tipo_activo
	   FROM catalogo_bien_serv  
	  WHERE sec_ejec   = @an_sec_ejec  AND
		tipo_bien  = @ls_tipo_bien AND  
		grupo_bien = @ls_grup_bien AND  
		clase_bien = @ls_clas_bien AND  
		familia_bien = @ls_fami_bien AND  
		item_bien = @ls_item_bien 

	set @ls_acti_fijo = @ls_flag_acti

	If (@ls_flag_item <> '1')
	BEGIN
		 SELECT @ls_tipo_natu = naturaleza  
		   FROM plan_ctb_sub_cta  
		  WHERE ano_eje = @an_ano_eje AND  
			mayor   = @ls_plan_mayo AND  
			sub_cta = @ls_plan_scta 

		DECLARE c_devol CURSOR FOR
		 SELECT d.tipo_movimto_orig, d.tipo_transac_orig, d.tipo_ppto_orig, d.nro_movimto_orig,
			d.secuencia_orig, d.sec_detalle_orig, sum(d.cant_articulo) as cant_articulo
		   FROM sig_detalle_movim_almacen d,
			sig_movim_almacen m
		  WHERE d.ano_eje      = m.ano_eje  and
			d.sec_ejec     = m.sec_ejec and
			d.almacen      = m.almacen  and
			d.sec_almacen  = m.sec_almacen  and
			d.tipo_movimto = m.tipo_movimto and
			d.tipo_transac = m.tipo_transac and
			d.tipo_ppto    = m.tipo_ppto    and
			d.nro_movimto  = m.nro_movimto  and
			m.estado_kardex= 'S' and
			d.ano_eje      = @an_ano_eje  and
			d.sec_ejec     = @an_sec_ejec and
			d.mes_proceso  >= @as_mes     and
			d.almacen      = @as_almacen  and
			d.sec_almacen  = @as_sec_alma and
			d.tipo_movimto = 'S' and
			d.tipo_bien    = @ls_tipo_bien  and
			d.grupo_bien   = @ls_grup_bien  and
			d.clase_bien   = @ls_clas_bien  and
			d.familia_bien = @ls_fami_bien  and
			d.item_bien    = @ls_item_bien  and
			d.marca        = @ld_codi_marc  and
			d.tipo_uso     = @ls_tipo_uso   and
			m.tipo_ppto    = @an_tipo_ppto  and
			((@an_tipo_ppto = 1) or
			 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
			d.cant_articulo >= 0 and
			((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
			 (@ls_kardex_clasif = 'N')) and
			d.mayor        = @ls_plan_mayo and
			d.sub_cta      = @ls_plan_scta and
			m.tipo_origen  = '0' and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		GROUP BY d.tipo_movimto_orig, d.tipo_transac_orig, d.tipo_ppto_orig, d.nro_movimto_orig,
			 d.secuencia_orig, d.sec_detalle_orig

		OPEN c_devol
		FETCH NEXT FROM c_devol INTO @ls_tmovi_devo, @ld_trans_devo, @ld_tppto_devo, @ld_nmovi_devo,
					@ld_secue_devo, @ld_sdeta_devo, @ld_canti_devo

		WHILE @@FETCH_STATUS = 0
		BEGIN
			 UPDATE sig_detalle_movim_almacen  
			    SET cant_atendida = cant_atendida - @ld_canti_devo   
			  WHERE ano_eje  = @an_ano_eje  AND  
				sec_ejec = @an_sec_ejec AND  
				almacen  = @as_almacen  AND  
				sec_almacen  = @as_sec_alma   AND  
				tipo_movimto = @ls_tmovi_devo AND  
				tipo_transac = @ld_trans_devo AND  
				tipo_ppto   = @ld_tppto_devo  AND  
				nro_movimto = @ld_nmovi_devo  AND  
				secuencia   = @ld_secue_devo  AND  
				sec_detalle = @ld_sdeta_devo 

			IF (@@error <> 0)
			begin
				close c_devol
				close c_item
				DEALLOCATE c_devol
				DEALLOCATE c_item
				set @as_message = 'Error al actualizar la devolución de cantidad :'
				return -1
			End
			FETCH NEXT FROM c_devol INTO @ls_tmovi_devo, @ld_trans_devo, @ld_tppto_devo, @ld_nmovi_devo,
						@ld_secue_devo, @ld_sdeta_devo, @ld_canti_devo
		END
		CLOSE c_devol
		DEALLOCATE c_devol

		DECLARE c_salida CURSOR FOR
		 SELECT d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
			d.secuencia, d.mes_proceso, d.clasificador, sum(d.cant_articulo) as cant_articulo
		   FROM sig_detalle_movim_almacen d,
			sig_movim_almacen m
		  WHERE d.ano_eje      = m.ano_eje  and
			d.sec_ejec     = m.sec_ejec and
			d.almacen      = m.almacen  and
			d.sec_almacen  = m.sec_almacen  and
			d.tipo_movimto = m.tipo_movimto and
			d.tipo_transac = m.tipo_transac and
			d.tipo_ppto    = m.tipo_ppto    and
			d.nro_movimto  = m.nro_movimto  and
			m.estado_kardex= 'S' and
			d.ano_eje      = @an_ano_eje  and
			d.sec_ejec     = @an_sec_ejec and
			d.mes_proceso  >= @as_mes     and
			d.almacen      = @as_almacen  and
			d.sec_almacen  = @as_sec_alma and
			d.tipo_movimto = 'S' and
			d.tipo_bien    = @ls_tipo_bien  and
			d.grupo_bien   = @ls_grup_bien  and
			d.clase_bien   = @ls_clas_bien  and
			d.familia_bien = @ls_fami_bien  and
			d.item_bien    = @ls_item_bien  and
			d.marca        = @ld_codi_marc  and
			d.tipo_uso     = @ls_tipo_uso   and
			m.tipo_ppto    = @an_tipo_ppto  and
			((@an_tipo_ppto = 1) or
			 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
			d.cant_articulo >= 0 and
			((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
			 (@ls_kardex_clasif = 'N')) and
			d.mayor        = @ls_plan_mayo and
			d.sub_cta      = @ls_plan_scta and
			m.tipo_origen  = '0' and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		GROUP BY d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
			 d.secuencia, d.mes_proceso, d.clasificador
		order by d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
			 d.secuencia, d.mes_proceso, d.clasificador

		OPEN c_salida
		FETCH NEXT FROM c_salida INTO @ldt_fmov_temp, @ldt_freg_temp, @ls_tmovi_sali, @ld_trans_sali,
					@ld_nmovi_sali, @ld_secue_sali, @ls_mess_sali, @ls_clasi_sali, @ldec_canti_sali

		WHILE @@FETCH_STATUS = 0
		BEGIN

			 SELECT DISTINCT @ls_cent_cost = p.centro_costo, @ld_operacion = d.operacion,
				@ldt_fech_movi = m.fecha_movimto,
				@ls_tipo_dest = d.tipo_destino, @ls_moda_dest = d.modal_destino,
				@ls_flag_dest = d.flag_destino, @ld_secu_func = p.sec_func,
				@ls_acti_proy = p.act_proy, @ls_orig_fuen = p.origen,
				@ls_codi_fuen = p.fuente_financ,
				@ls_tipo_pedi = d.tipo_pedido,
				@ls_nume_pedi = d.nro_pedido,
				@ld_secu_pedi = d.secuencia
			   FROM sig_movim_almacen m,   
				sig_detalle_pedidos d,   
				sig_pedidos p,
				sig_detalle_pecosa dp 
			  WHERE p.ano_eje   = d.ano_eje   and  
				p.sec_ejec  = d.sec_ejec  and  
				p.tipo_bien = d.tipo_bien and  
				p.tipo_pedido = d.tipo_pedido and  
				p.nro_pedido  = d.nro_pedido  and  
				d.ano_eje   = dp.ano_eje   and  
				d.sec_ejec  = dp.sec_ejec  and  
				d.tipo_bien = dp.tipo_bien and  
				d.tipo_pedido = dp.tipo_pedido and  
				d.nro_pedido  = dp.nro_pedido  and  
				d.secuencia   = dp.secuencia   and  
				m.ano_eje  = d.ano_eje  and  
				m.sec_ejec = d.sec_ejec and  
				m.almacen  = d.almacen  and  
				m.sec_almacen = d.sec_almacen and  
				m.tipo_ppto   = p.tipo_ppto   and  
				m.nro_movimto = d.nro_pecosa  and  
				m.ano_eje  = @an_ano_eje  AND  
				m.sec_ejec = @an_sec_ejec AND  
				m.almacen  = @as_almacen  AND  
				m.sec_almacen  = @as_sec_alma   AND  
				m.tipo_movimto = @ls_tmovi_sali AND  
				m.tipo_transac = @ld_trans_sali AND  
				m.tipo_ppto    = @an_tipo_ppto  AND  
				m.nro_movimto  = @ld_nmovi_sali AND  
				d.tipo_bien    = @ls_tipo_bien  AND
				d.grupo_bien   = @ls_grup_bien  AND  
				d.clase_bien   = @ls_clas_bien  AND  
				d.familia_bien = @ls_fami_bien  AND  
				d.item_bien    = @ls_item_bien  AND  
				d.clasificador = @ls_clasi_sali AND  
				d.mayor        = @ls_plan_mayo  AND  
				d.sub_cta      = @ls_plan_scta  AND
				d.unidad_medida = @ld_unid_medi AND
				((@ld_item_bien_det is null and dp.item_bien_det is null) or
				 (@ld_item_bien_det is not null and dp.item_bien_det = @ld_item_bien_det)) and
				p.tipo_pedido <> '4' 

			IF (@@rowcount = 0)
			BEGIN
				set @ls_cent_cost = ''
				set @ld_operacion = null
				set @ldt_fech_movi = @ldt_fmov_temp
				set @ls_tipo_dest = ''
				set @ls_moda_dest = ''
				set @ls_flag_dest = ''
				set @ld_secu_func = null
				set @ls_acti_proy = ''
				set @ls_orig_fuen = ''
				set @ls_codi_fuen=''
			END
					
			If (ltrim(rtrim(@ls_cent_cost)) = '')
				set @ls_cent_cost = null
		
			delete from #ld_sdeta_sala

			set @ld_cont = 0
			set @ld_cont_ingr = 0

			DECLARE c_item_salida CURSOR FOR
			 SELECT d.sec_detalle
			   FROM sig_detalle_movim_almacen d
			  WHERE d.ano_eje      = @an_ano_eje  and
				d.sec_ejec     = @an_sec_ejec and
				d.almacen      = @as_almacen  and
				d.sec_almacen  = @as_sec_alma and
				d.tipo_movimto = @ls_tmovi_sali and
				d.tipo_transac = @ld_trans_sali and
				d.tipo_ppto    = @an_tipo_ppto  and
				d.nro_movimto  = @ld_nmovi_sali and
				d.secuencia    = @ld_secue_sali and
				d.tipo_bien    = @ls_tipo_bien  and
				d.grupo_bien   = @ls_grup_bien  and
				d.clase_bien   = @ls_clas_bien  and
				d.familia_bien = @ls_fami_bien  and
				d.item_bien    = @ls_item_bien  and
				d.marca        = @ld_codi_marc  and
				d.clasificador = @ls_clasi_sali and
				d.mayor        = @ls_plan_mayo  and
				d.sub_cta      = @ls_plan_scta  and
				d.unidad_medida = @ld_unid_medi and
				((@ld_item_bien_det is null and d.item_bien_det is null) or
				 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
			ORDER BY 1

			OPEN c_item_salida
			FETCH NEXT FROM c_item_salida INTO @ld_sdeta_sali

			WHILE @@FETCH_STATUS = 0
			BEGIN
				set @ld_cont = @ld_cont + 1
				insert #ld_sdeta_sala (fila, valor) values (@ld_cont, @ld_sdeta_sali)
				
				--Elimina los registros de salida existentes
				DELETE FROM sig_detalle_cta_almacen
				  WHERE ano_eje  = @an_ano_eje  AND  
					sec_ejec = @an_sec_ejec AND  
					almacen  = @as_almacen  AND  
					sec_almacen  = @as_sec_alma   AND  
					tipo_movimto = @ls_tmovi_sali AND  
					tipo_transac = @ld_trans_sali AND  
					tipo_ppto   = @an_tipo_ppto  AND  
					nro_movimto = @ld_nmovi_sali AND  
					secuencia   = @ld_secue_sali AND  
					sec_detalle = @ld_sdeta_sali 

				 DELETE FROM sig_detalle_movim_ppto
				  WHERE ano_eje  = @an_ano_eje  AND  
					sec_ejec = @an_sec_ejec AND  
					almacen  = @as_almacen  AND  
					sec_almacen  = @as_sec_alma   AND  
					tipo_movimto = @ls_tmovi_sali AND  
					tipo_transac = @ld_trans_sali AND  
					tipo_ppto   = @an_tipo_ppto  AND  
					nro_movimto = @ld_nmovi_sali AND  
					secuencia   = @ld_secue_sali AND  
					sec_detalle = @ld_sdeta_sali 

				-- GTP - 24-11-2022 - Borra lotes
				 DELETE FROM SIG_DETALLE_ALMACEN_LOTES
				  WHERE ano_eje  = @an_ano_eje
					AND sec_ejec = @an_sec_ejec
					AND almacen  = @as_almacen
					AND sec_almacen  = @as_sec_alma
					AND tipo_movimto = @ls_tmovi_sali
					AND tipo_transac = @ld_trans_sali
					AND tipo_ppto   = @an_tipo_ppto
					AND nro_movimto = @ld_nmovi_sali
					AND secuencia   = @ld_secue_sali
					AND sec_detalle = @ld_sdeta_sali

				 DELETE FROM sig_detalle_movim_almacen  
				  WHERE ano_eje  = @an_ano_eje  AND
					sec_ejec = @an_sec_ejec AND
					almacen  = @as_almacen  AND
					sec_almacen  = @as_sec_alma   AND
					tipo_movimto = @ls_tmovi_sali AND
					tipo_transac = @ld_trans_sali AND
					tipo_ppto   = @an_tipo_ppto  AND
					nro_movimto = @ld_nmovi_sali AND
					secuencia   = @ld_secue_sali AND
					sec_detalle = @ld_sdeta_sali 

				FETCH NEXT FROM c_item_salida INTO @ld_sdeta_sali
			END
			CLOSE c_item_salida
			DEALLOCATE c_item_salida
		
			--Elimina PECOSA
			If (@ls_kard_peco = '1' and @as_origen = '2' and @ld_trans_sali = 1)
			Begin
				 DELETE FROM sig_detalle_pecosa  
				  WHERE ano_eje     = @an_ano_eje   AND  
				        sec_ejec    = @an_sec_ejec  AND  
				        tipo_bien   = @ls_tipo_bien AND  
				        tipo_pedido = @ls_tipo_pedi AND  
				        nro_pedido  = @ls_nume_pedi AND  
				        secuencia   = @ld_secu_pedi AND
				        marca   = @ld_codi_marc AND
					 ((@ld_item_bien_det is null and item_bien_det is null) or
					  (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))
	
				DECLARE c_pecosa_orden CURSOR FOR
				 SELECT sec_atencion
				   FROM sig_detalle_pecosa
				  WHERE ano_eje     = @an_ano_eje   AND  
				        sec_ejec    = @an_sec_ejec  AND  
				        tipo_bien   = @ls_tipo_bien AND  
				        tipo_pedido = @ls_tipo_pedi AND  
				        nro_pedido  = @ls_nume_pedi AND  
				        secuencia   = @ld_secu_pedi
				ORDER BY 1
	
				set @ld_sec_atencion_orden = 0
				OPEN c_pecosa_orden
				FETCH NEXT FROM c_pecosa_orden INTO @ld_sec_atencion
				WHILE @@FETCH_STATUS = 0
				BEGIN
					set @ld_sec_atencion_orden = @ld_sec_atencion_orden + 1

					 UPDATE sig_detalle_pecosa
					    SET sec_atencion = @ld_sec_atencion_orden
					  WHERE ano_eje     = @an_ano_eje   AND  
					        sec_ejec    = @an_sec_ejec  AND  
					        tipo_bien   = @ls_tipo_bien AND  
					        tipo_pedido = @ls_tipo_pedi AND  
					        nro_pedido  = @ls_nume_pedi AND  
					        secuencia   = @ld_secu_pedi AND
						sec_atencion= @ld_sec_atencion

					FETCH NEXT FROM c_pecosa_orden INTO @ld_sec_atencion
				END
				CLOSE c_pecosa_orden
				DEALLOCATE c_pecosa_orden
			End
			
			set @lb_continue   = 'S'
			set @ld_sdeta_sali = 0
			set @ld_secu_peco  = 0

			DECLARE c_ingreso CURSOR FOR
			 SELECT d.tipo_movimto, d.tipo_transac, d.nro_movimto,
				d.secuencia,    d.sec_detalle,  d.cant_articulo - d.cant_atendida as cantidad,
				d.precio_unit,  d.valor_total
			   FROM sig_detalle_movim_almacen d,
				sig_movim_almacen m
			  WHERE d.ano_eje      = m.ano_eje  and
				d.sec_ejec     = m.sec_ejec and	
				d.almacen      = m.almacen  and
				d.sec_almacen  = m.sec_almacen  and
				d.tipo_movimto = m.tipo_movimto and
				d.tipo_transac = m.tipo_transac and
				d.tipo_ppto    = m.tipo_ppto    and
				d.nro_movimto  = m.nro_movimto  and
				m.estado_kardex= 'S' and
				d.ano_eje      = @an_ano_eje  and
				d.sec_ejec     = @an_sec_ejec and
				d.almacen      = @as_almacen  and
				d.sec_almacen  = @as_sec_alma and
				d.tipo_movimto in ('A','I') and
				d.tipo_bien    = @ls_tipo_bien  and
				d.grupo_bien   = @ls_grup_bien  and
				d.clase_bien   = @ls_clas_bien  and
				d.familia_bien = @ls_fami_bien  and
				d.item_bien    = @ls_item_bien  and
				d.marca        = @ld_codi_marc  and
				d.tipo_uso     = @ls_tipo_uso   and
				m.tipo_ppto    = @an_tipo_ppto  and
				((@an_tipo_ppto = 1) or
				 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
				d.cant_articulo - d.cant_atendida > 0 and
				((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
				 (@ls_kardex_clasif = 'N')) and
				d.mayor        = @ls_plan_mayo and
				d.sub_cta      = @ls_plan_scta and
				d.fecha_movimto<= @ldt_fmov_temp and
				d.unidad_medida = @ld_unid_medi and
				((@ld_item_bien_det is null and d.item_bien_det is null) or
				 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
			order by d.fecha_movimto, d.fecha_reg, d.tipo_movimto, d.tipo_transac, d.nro_movimto,
				 d.secuencia, d.sec_detalle

			OPEN c_ingreso
			FETCH NEXT FROM c_ingreso INTO @ls_tmovi_ingr, @ld_trans_ingr, @ld_nmovi_ingr,
						@ld_secue_ingr, @ld_sdeta_ingr, @ldec_stock_ingr,
						@ldec_prec_unit, @ldec_valo_ingr
			WHILE @@FETCH_STATUS = 0
			BEGIN
				set @ld_cont_ingr = @ld_cont_ingr + 1

				If (@ld_cont_ingr <= @ld_cont)
					SELECT @ld_sdeta_sali = isnull(valor,0)
					  FROM #ld_sdeta_sala
					 WHERE fila = @ld_cont_ingr
				Else
					set @ld_sdeta_sali = 0
			
				If (@ld_sdeta_sali = 0)
				BEGIN
					 SELECT @ld_sdeta_sali = max(sec_detalle)
					   FROM sig_detalle_movim_almacen  
					  WHERE ano_eje  = @an_ano_eje  AND  
						sec_ejec = @an_sec_ejec AND  
						almacen  = @as_almacen  AND  
						sec_almacen  = @as_sec_alma   AND  
						tipo_movimto = @ls_tmovi_sali AND  
						tipo_transac = @ld_trans_sali AND  
						tipo_ppto   = @an_tipo_ppto   AND  
						nro_movimto = @ld_nmovi_sali  AND  
						secuencia   = @ld_secue_sali 

					IF (@@rowcount = 0)
						set @ld_sdeta_sali = 0

--					If (@ld_sdeta_sali = null) 
--						set @ld_sdeta_sali = 0
					set @ld_sdeta_sali = isnull(@ld_sdeta_sali, 0)

					set @ld_sdeta_sali = @ld_sdeta_sali + 1
				END

				If (@ldec_stock_ingr < @ldec_canti_sali)
					set @ldec_cant_aten = @ldec_stock_ingr
				Else
				BEGIN
					set @ldec_cant_aten = @ldec_canti_sali
					set @lb_continue = 'N'
				END

				set @ldec_canti_sali = @ldec_canti_sali - @ldec_cant_aten

				--Temp
				If (@ldec_cant_aten = @ldec_stock_ingr)
				BEGIN
					 SELECT @ldec_valo_tota = sum(valor_total)  
					   FROM sig_detalle_movim_almacen  
					  WHERE ano_eje  = @an_ano_eje  AND  
						sec_ejec = @an_sec_ejec AND  
						almacen  = @as_almacen  AND  
						sec_almacen = @as_sec_alma AND  
						tipo_movimto_orig = @ls_tmovi_ingr AND  
						tipo_transac_orig = @ld_trans_ingr AND  
						tipo_ppto_orig    = @an_tipo_ppto  AND  
						nro_movimto_orig  = @ld_nmovi_ingr AND  
						secuencia_orig    = @ld_secue_ingr AND  
						sec_detalle_orig  = @ld_sdeta_ingr AND
						tipo_movimto = 'S'

					IF (@@rowcount = 0)
						set @ldec_valo_tota = 0

--					If (@ldec_valo_tota = null)
--						set @ldec_valo_tota = 0
					set @ldec_valo_tota = isnull(@ldec_valo_tota, 0)

					set @ldec_valo_tota = @ldec_valo_ingr - @ldec_valo_tota

				END
				Else
					set @ldec_valo_tota = round(@ldec_cant_aten * @ldec_prec_unit, 2)

				--Actualiza la cantidad atendida del ingreso o inv.inicial
				 UPDATE sig_detalle_movim_almacen  
				    SET cant_atendida = cant_atendida + @ldec_cant_aten
				  WHERE ano_eje  = @an_ano_eje  AND  
					sec_ejec = @an_sec_ejec AND  
					almacen  = @as_almacen  AND  
					sec_almacen  = @as_sec_alma   AND  
					tipo_movimto = @ls_tmovi_ingr AND  
					tipo_transac = @ld_trans_ingr AND  
					tipo_ppto    = @an_tipo_ppto  AND  
					nro_movimto  = @ld_nmovi_ingr AND  
					secuencia    = @ld_secue_ingr AND  
					sec_detalle  = @ld_sdeta_ingr 

				--Inserta los registros existentes
				  INSERT INTO sig_detalle_movim_almacen  
				        ( ano_eje, sec_ejec, almacen, sec_almacen, tipo_movimto,   
					  tipo_transac, tipo_ppto, nro_movimto, secuencia, sec_detalle,
					  centro_costo, tipo_bien, grupo_bien, clase_bien, familia_bien,
					  item_bien, marca, clasificador, mayor, sub_cta,
					  operacion, activo_fijo, tipo_activo, fecha_entrada, cant_adquirido,
					  medida_adquis, cant_recibido, cant_articulo, unidad_medida, cant_devuelta,
					  precio_unit, precio_moneda, moneda, valor_total, fecha_movimto,
					  indi_recibido, precio_promed, tipo_destino, modal_destino, flag_destino,
					  mes_proceso, stock_actual, valor_actual, fecha_reg, cuser_id,
					  equipo_reg, sec_item, cant_atendida, tipo_movimto_orig, tipo_transac_orig,
					  tipo_ppto_orig, nro_movimto_orig, secuencia_orig, sec_detalle_orig,
					  tipo_marca, flag_interfase, tipo_uso, item_bien_det)  
				  VALUES( @an_ano_eje, @an_sec_ejec, @as_almacen, @as_sec_alma, @ls_tmovi_sali,
					  @ld_trans_sali, @an_tipo_ppto, @ld_nmovi_sali, @ld_secue_sali, @ld_sdeta_sali,
					  @ls_cent_cost, @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien,
					  @ls_item_bien, @ld_codi_marc, @ls_clasi_sali, @ls_plan_mayo, @ls_plan_scta,
					  @ld_operacion, @ls_flag_acti, @ls_tipo_acti, null, 0,
					  @ld_unid_medi, 0, @ldec_cant_aten, @ld_unid_medi, 0,
					  @ldec_prec_unit, @ldec_prec_unit, 'S/.', @ldec_valo_tota, @ldt_fech_movi,
					  null, 0, @ls_tipo_dest, @ls_moda_dest, @ls_flag_dest,
					  @ls_mess_sali, 0, 0, @adt_fecha_actual, @as_usuing,
					  @as_equipo, null, 0, @ls_tmovi_ingr, @ld_trans_ingr,
					  @an_tipo_ppto, @ld_nmovi_ingr, @ld_secue_ingr, @ld_sdeta_ingr,
					  @ls_tipo_marc, 'N', @ls_tipo_uso, @ld_item_bien_det)  

				  INSERT INTO sig_detalle_movim_ppto  
				        ( ano_eje, sec_ejec, almacen, sec_almacen, tipo_movimto,   
					  tipo_transac, tipo_ppto, nro_movimto, secuencia, sec_detalle,
					  sec_ppto, operacion, clasificador, tipo_destino, modal_destino,
					  sec_func, act_proy, origen, fuente_financ, tipo_recurso,
					  cant_articulo, fecha_reg )  
				  VALUES( @an_ano_eje, @an_sec_ejec, @as_almacen, @as_sec_alma, @ls_tmovi_sali,
					  @ld_trans_sali, @an_tipo_ppto, @ld_nmovi_sali, @ld_secue_sali, @ld_sdeta_sali,
					  1, @ld_operacion, @ls_clasi_sali, @ls_tipo_dest, @ls_moda_dest,
					  @ld_secu_func, @ls_acti_proy, @ls_orig_fuen, @ls_codi_fuen, null,
					  @ldec_cant_aten, @adt_fecha_actual )  

				  INSERT INTO sig_detalle_cta_almacen  
				        ( ano_eje, sec_ejec, almacen, sec_almacen, tipo_movimto,   
					  tipo_transac, tipo_ppto, nro_movimto, secuencia, sec_detalle,
					  sec_ppto, sec_cuenta, mayor, sub_cta, tipo_d_h,
					  ind_alma, valor_cuenta )  
				  VALUES( @an_ano_eje, @an_sec_ejec, @as_almacen, @as_sec_alma, @ls_tmovi_sali,
					  @ld_trans_sali, @an_tipo_ppto, @ld_nmovi_sali, @ld_secue_sali, @ld_sdeta_sali,
					  1, 1, @ls_plan_mayo, @ls_plan_scta, @ls_tipo_natu,
					  '1', @ldec_valo_tota )  

				--Inserta en PECOSA
				If (@ls_kard_peco = '1' and @as_origen = '2' and @ld_trans_sali = 1)
				Begin
					  SELECT @ld_secu_peco = max(sec_atencion)
					    FROM sig_detalle_pecosa  
					   WHERE ano_eje     = @an_ano_eje   AND  
					         sec_ejec    = @an_sec_ejec  AND  
					         tipo_bien   = @ls_tipo_bien AND  
					         tipo_pedido = @ls_tipo_pedi AND  
					         nro_pedido  = @ls_nume_pedi AND  
					         secuencia   = @ld_secu_pedi

					IF (@@rowcount = 0)
						set @ld_secu_peco = 0

					set @ld_secu_peco = isnull(@ld_secu_peco, 0)
					set @ld_secu_peco = @ld_secu_peco + 1

					  INSERT INTO sig_detalle_pecosa  
					        ( ano_eje, sec_ejec, tipo_bien, tipo_pedido,   
					          nro_pedido, secuencia, sec_atencion, marca,   
					          nro_lote, fecha_expiracion, precio_unit, cant_atendida,   
					          cant_aprobada, nro_pecosa, tipo_marca, ano_movimto,   
					          tipo_transac, nro_movimto, precio_movimto, tipo_movimto,   
					          valor_total, item_bien_det )  
					  VALUES (@an_ano_eje, @an_sec_Ejec, @ls_tipo_bien, @ls_tipo_pedi,   
					          @ls_nume_pedi, @ld_secu_pedi, @ld_secu_peco, @ld_codi_marc,   
					          null, null, @ldec_prec_unit,  @ldec_cant_aten,   
					         @ldec_cant_aten, @ld_nmovi_sali, @ls_tipo_marc, null,   
					          null, null, 0, null,   
						  @ldec_valo_tota, @ld_item_bien_det ) 
				End

				If (@lb_continue = 'N')
					break

				FETCH NEXT FROM c_ingreso INTO @ls_tmovi_ingr, @ld_trans_ingr, @ld_nmovi_ingr,
							@ld_secue_ingr, @ld_sdeta_ingr, @ldec_stock_ingr,
							@ldec_prec_unit, @ldec_valo_ingr
			END
			CLOSE c_ingreso
			DEALLOCATE c_ingreso

			If (@ldec_canti_sali > 0)
			BEGIN
				set @ls_codi_bien = @ls_grup_bien + @ls_clas_bien + @ls_fami_bien + @ls_item_bien
				set @ls_temp_mayo = @ls_plan_mayo + @ls_plan_scta

				If (@ls_kardex_clasif = 'S')
					RAISERROR ('Existen mas Salidas que ingreso en el item %s clasificador %s cuenta %s.',
						   16, 1, @ls_codi_bien, @ls_clas_gast, @ls_temp_mayo)
				Else
					RAISERROR ('Existen mas Salidas que ingreso en el item %s cuenta %s.',
						   16, 1, @ls_codi_bien, @ls_temp_mayo)

				ROLLBACK TRANSACTION
				return -1
			END

			FETCH NEXT FROM c_salida INTO @ldt_fmov_temp, @ldt_freg_temp, @ls_tmovi_sali, @ld_trans_sali,
						@ld_nmovi_sali, @ld_secue_sali, @ls_mess_sali, @ls_clasi_sali, @ldec_canti_sali

		END
		CLOSE c_salida
		DEALLOCATE c_salida
	END

	set @ld_mes = @as_mes * 1
	WHILE (@ld_mes <= (@ls_mess_maxi * 1))
	BEGIN
		set @ldec_kard_acan = 0
		set @ldec_kard_aval = 0
		set @ldec_kard_ican = 0
		set @ldec_kard_ival = 0
		set @ldec_kard_scan = 0
		set @ldec_kard_sval = 0
		set @ls_mess_proc = rtrim(ltrim(@ld_mes))
		set @ls_mess_proc = ltrim(rtrim(right('0000'+@ls_mess_proc,2)))

		DECLARE c_mens CURSOR FOR
		 SELECT d.tipo_movimto, sum(d.cant_articulo) as cant_articulo, sum(d.valor_total) as valor_total
		   FROM sig_detalle_movim_almacen d,
			sig_movim_almacen m
		  WHERE d.ano_eje      = m.ano_eje      and
			d.sec_ejec     = m.sec_ejec     and
			d.almacen      = m.almacen      and
			d.sec_almacen  = m.sec_almacen  and
			d.tipo_movimto = m.tipo_movimto and
			d.tipo_transac = m.tipo_transac and
			d.tipo_ppto    = m.tipo_ppto    and
			d.nro_movimto  = m.nro_movimto  and
			d.ano_eje      = @an_ano_eje    and
			d.sec_ejec     = @an_sec_ejec   and
			d.almacen      = @as_almacen    and
			d.sec_almacen  = @as_sec_alma   and
			d.tipo_movimto in ('A','I','S') and
			d.tipo_bien    = @ls_tipo_bien  and
			d.grupo_bien   = @ls_grup_bien and
			d.clase_bien   = @ls_clas_bien and
			d.familia_bien = @ls_fami_bien and
			d.item_bien    = @ls_item_bien and
			d.marca        = @ld_codi_marc and
			d.mes_proceso  = @ls_mess_proc and
			d.tipo_uso     = @ls_tipo_uso  and
			m.tipo_ppto    = @an_tipo_ppto and
			((@an_tipo_ppto = 1) or
			 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
			m.estado_kardex= 'S' and
			d.cant_articulo >= 0 and
			((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
			 (@ls_kardex_clasif = 'N')) and
			d.mayor        = @ls_plan_mayo and
			d.sub_cta      = @ls_plan_scta and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		 GROUP BY d.tipo_movimto

		OPEN c_mens
		FETCH NEXT FROM c_mens INTO @ls_tipo_movi, @ldec_kard_tcan, @ldec_kard_tval
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF (@ls_tipo_movi = 'A')
			BEGIN
				SET @ldec_kard_acan = @ldec_kard_tcan
				SET @ldec_kard_aval = @ldec_kard_tval
			END
			If (@ls_tipo_movi = 'I')
			BEGIN
				SET @ldec_kard_ican = @ldec_kard_tcan
				SET @ldec_kard_ival = @ldec_kard_tval
			END	
			If (@ls_tipo_movi = 'S')
			BEGIN
				SET @ldec_kard_scan = @ldec_kard_tcan
				SET @ldec_kard_sval = @ldec_kard_tval
			END

			FETCH NEXT FROM c_mens INTO @ls_tipo_movi, @ldec_kard_tcan, @ldec_kard_tval
		END
		CLOSE c_mens
		DEALLOCATE c_mens
	
		set @ldec_kard_acan = isnull(@ldec_kard_acan, 0)
		set @ldec_kard_aval = isnull(@ldec_kard_aval, 0)
		set @ldec_kard_ican = isnull(@ldec_kard_ican, 0)
		set @ldec_kard_ival = isnull(@ldec_kard_ival, 0)
		set @ldec_kard_scan = isnull(@ldec_kard_scan, 0)
		set @ldec_kard_sval = isnull(@ldec_kard_sval, 0)

		set @ldec_anua_acan = 0 
		set @ldec_anua_aval = 0
		set @ldec_anua_ican = 0
		set @ldec_anua_ival = 0
		set @ldec_anua_scan = 0
		set @ldec_anua_sval = 0
		set @ldec_kard_tcan = 0
		set @ldec_kard_tval = 0

		DECLARE c_anual CURSOR FOR
		 SELECT d.tipo_movimto, sum(d.cant_articulo) as cant_articulo, sum(d.valor_total) as valor_total
		   FROM sig_detalle_movim_almacen d,
			sig_movim_almacen m
		  WHERE d.ano_eje      = m.ano_eje      and
			d.sec_ejec     = m.sec_ejec     and
			d.almacen      = m.almacen      and
			d.sec_almacen  = m.sec_almacen  and
			d.tipo_movimto = m.tipo_movimto and
			d.tipo_transac = m.tipo_transac and
			d.tipo_ppto    = m.tipo_ppto    and
			d.nro_movimto  = m.nro_movimto  and
			d.ano_eje      = @an_ano_eje    and
			d.sec_ejec     = @an_sec_ejec   and
			d.almacen      = @as_almacen    and
			d.sec_almacen  = @as_sec_alma   and
			d.tipo_movimto in ('A','I','S') and
			d.tipo_bien    = @ls_tipo_bien  and
			d.grupo_bien   = @ls_grup_bien and
			d.clase_bien   = @ls_clas_bien and
			d.familia_bien = @ls_fami_bien and
			d.item_bien    = @ls_item_bien and
			d.marca        = @ld_codi_marc and
			d.mes_proceso  < @ls_mess_proc and
			d.tipo_uso     = @ls_tipo_uso  and
			m.tipo_ppto    = @an_tipo_ppto and
			((@an_tipo_ppto = 1) or
			 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
			m.estado_kardex= 'S' and
			d.cant_articulo >= 0 and
			((@ls_kardex_clasif = 'S' and d.clasificador = @ls_clas_gast) or
			 (@ls_kardex_clasif = 'N')) and
			d.mayor        = @ls_plan_mayo and
			d.sub_cta      = @ls_plan_scta and
			d.unidad_medida = @ld_unid_medi and
			((@ld_item_bien_det is null and d.item_bien_det is null) or
			 (@ld_item_bien_det is not null and d.item_bien_det = @ld_item_bien_det))
		 GROUP BY d.tipo_movimto

		OPEN c_anual
		FETCH NEXT FROM c_anual INTO @ls_tipo_movi, @ldec_kard_tcan, @ldec_kard_tval
		WHILE @@FETCH_STATUS = 0
		BEGIN
			If (@ls_tipo_movi = 'A')
			BEGIN
				set @ldec_anua_acan = @ldec_kard_tcan
				set @ldec_anua_aval = @ldec_kard_tval
			END
			If (@ls_tipo_movi = 'I')
			BEGIN
				set @ldec_anua_ican = @ldec_kard_tcan
				set @ldec_anua_ival = @ldec_kard_tval
			END
			If (@ls_tipo_movi = 'S')
			BEGIN
				set @ldec_anua_scan = @ldec_kard_tcan
				set @ldec_anua_sval = @ldec_kard_tval
			END

			FETCH NEXT FROM c_anual INTO @ls_tipo_movi, @ldec_kard_tcan, @ldec_kard_tval
		END
		CLOSE c_anual
		DEALLOCATE c_anual
	
		set @ldec_anua_acan = isnull(@ldec_anua_acan, 0)
		set @ldec_anua_aval = isnull(@ldec_anua_aval, 0)
		set @ldec_anua_ican = isnull(@ldec_anua_ican, 0)
		set @ldec_anua_ival = isnull(@ldec_anua_ival, 0)
		set @ldec_anua_scan = isnull(@ldec_anua_scan, 0)
		set @ldec_anua_sval = isnull(@ldec_anua_sval, 0)

		set @ls_codi_bien = @ls_grup_bien + @ls_clas_bien + @ls_fami_bien + @ls_item_bien
		set @ldec_kard_acan = @ldec_kard_acan + @ldec_anua_acan + @ldec_anua_ican - @ldec_anua_scan
		set @ldec_kard_aval = @ldec_kard_aval + @ldec_anua_aval + @ldec_anua_ival - @ldec_anua_sval
		
		 UPDATE sig_kardex_por_almacen
		    SET stock_inicial = @ldec_kard_acan,
			cant_ingreso	= @ldec_kard_ican,
			cant_egreso	= @ldec_kard_scan,
			stock_actual	= @ldec_kard_acan + @ldec_kard_ican - @ldec_kard_scan,
			precio_promed = 0,
			saldo_inicial = @ldec_kard_aval,
			valor_ingreso = @ldec_kard_ival, 
			valor_egreso  = @ldec_kard_sval, 
			saldo_valor   = @ldec_kard_aval + @ldec_kard_ival - @ldec_kard_sval
		  WHERE ano_eje       = @an_ano_eje    and
			sec_ejec      = @an_sec_ejec   and
			mes_proceso   = @ls_mess_proc  and
			almacen       = @as_almacen    and
			sec_almacen   = @as_sec_alma   and
			tipo_bien     = @ls_tipo_bien  and
			codigo_bien   = @ls_codi_bien  and
			marca         = @ld_codi_marc  and
			clasificador  = @ls_clas_gast  and
			mayor         = @ls_plan_mayo  and
			sub_cta       = @ls_plan_scta  and
			tipo_uso      = @ls_tipo_uso   and
			tipo_ppto     = @an_tipo_ppto  and
			secuencia     = @an_encargo    and
			unidad_medida = @ld_unid_medi  and
			((@ld_item_bien_det is null and item_bien_det is null) or
			 (@ld_item_bien_det is not null and item_bien_det = @ld_item_bien_det))

		If (@@rowcount = 0)
		BEGIN
			set @ls_correlati = ''
			SELECT @ls_correlati = max(correlativo)
			  FROM sig_kardex_por_almacen
			 WHERE ano_eje       = @an_ano_eje    and
				sec_ejec      = @an_sec_ejec   and
				mes_proceso   = @ls_mess_proc  and
				almacen       = @as_almacen    and
				sec_almacen   = @as_sec_alma   and
				tipo_bien     = @ls_tipo_bien  and
				codigo_bien   = @ls_codi_bien  and
				marca         = @ld_codi_marc  and
				clasificador  = @ls_clas_gast  and
				mayor         = @ls_plan_mayo  and
				sub_cta       = @ls_plan_scta  and
				tipo_uso      = @ls_tipo_uso   and
				tipo_ppto     = @an_tipo_ppto  and
				secuencia     = @an_encargo;
	
			set @ls_correlati = isnull(@ls_correlati, '0')
			If (@ls_correlati = '')
			   set @ls_correlati = '0'
					 
			set @ls_correlati = right('0000'+convert(varchar(4), @ls_correlati*1 + 1),4)

			INSERT INTO sig_kardex_por_almacen  
				( ano_eje,       sec_ejec,      mes_proceso,   
				  almacen,       sec_almacen,   tipo_bien, codigo_bien, 
				  grupo_bien,    clase_bien,    familia_bien,   
				  item_bien,     marca,         tipo_uso,   
				  tipo_ppto,     secuencia,     nro_encargo,
				  sec_ejec2,	  cant_invent,   cant_bueno,   
				  stock_inicial, cant_ingreso,  cant_egreso,   
				  stock_actual,  precio_promed, saldo_valor,   
				  valor_ingreso, valor_egreso,  saldo_inicial,   
				  stock_enero,   cons_enero,    precio_invent,
				  cuser_id,      fecha_reg,     equipo_reg,
				  activo_fijo,   clasificador,  mayor,
				  sub_cta,       correlativo,	  tipo_marca,
				  unidad_medida, item_bien_det)  
			  VALUES( @an_ano_eje,    @an_sec_ejec,   @ls_mess_proc,   
				  @as_almacen,    @as_sec_alma,   @ls_tipo_bien, @ls_codi_bien,  
				  @ls_grup_bien,  @ls_clas_bien,  @ls_fami_bien,   
				  @ls_item_bien,  @ld_codi_marc,  @ls_tipo_uso,   
				  @an_tipo_ppto,  @an_encargo,    @ld_encargo,
				  @ld_sec_ejec2,	0,              0,   
				  @ldec_kard_acan, @ldec_kard_ican, @ldec_kard_scan,   
				  @ldec_kard_acan + @ldec_kard_ican - @ldec_kard_scan, 0, @ldec_kard_aval + @ldec_kard_ival - @ldec_kard_sval,   
				  @ldec_kard_ival, @ldec_kard_sval, @ldec_kard_aval,   
				  0,              0,              0, 
				  @as_usuing,    @adt_fecha_actual, @as_equipo,
				  @ls_acti_fijo,  @ls_clas_gast,  @ls_plan_mayo,
				  @ls_plan_scta,  @ls_correlati,  @ls_tipo_marc,
				  @ld_unid_medi,  @ld_item_bien_det) 
		END
		set @ld_mes = @ld_mes + 1
	END
--@ls_acti_fijo,
	FETCH NEXT FROM c_item INTO @ls_tipo_bien, @ls_grup_bien, @ls_clas_bien, @ls_fami_bien,
				@ls_item_bien, @ld_codi_marc, @ld_encargo, @ld_sec_ejec2,
				@ls_clas_gast, @ls_plan_mayo, @ls_plan_scta, 
				@ls_tipo_marc, @ls_tipo_uso, @ld_unid_medi, @ld_item_bien_det
END
CLOSE c_item
DEALLOCATE c_item

DELETE FROM sig_kardex_por_almacen
 WHERE ano_eje      = @an_ano_eje  and
	sec_ejec     = @an_sec_ejec and
	mes_proceso  >= @as_mes     and
	almacen      = @as_almacen  and
	sec_almacen  = @as_sec_alma and
	tipo_bien    like @as_tipo_bien  and
	codigo_bien  like @ls_codi_bien_para  and
	clasificador like @as_clas_gast  and
	mayor        like @as_plan_mayo and
	sub_cta      like @as_plan_scta and
	tipo_uso in (SELECT DISTINCT d.tipo_uso
			   FROM sig_detalle_movim_almacen d,
				sig_movim_almacen m
			  WHERE d.ano_eje      = m.ano_eje  and
				d.sec_ejec     = m.sec_ejec and
				d.almacen      = m.almacen  and
				d.sec_almacen  = m.sec_almacen  and
				d.tipo_movimto = m.tipo_movimto and
				d.tipo_transac = m.tipo_transac and
				d.tipo_ppto    = m.tipo_ppto    and
				d.nro_movimto  = m.nro_movimto  and
				m.estado_kardex= 'S' and
				d.ano_eje      = @an_ano_eje    and
				d.sec_ejec     = @an_sec_ejec   and
				d.almacen      = @as_almacen    and
				d.sec_almacen  = @as_sec_alma   and
				d.tipo_movimto in ('A','I','S') and
				m.tipo_ppto    = @an_tipo_ppto  and
				((@an_tipo_ppto = 1) or
				 (@an_tipo_ppto = 2 and m.nro_encargo = @an_encargo)) and
				((@as_origen = '2'  and d.tipo_uso = @as_tipo_uso) or
				 (@as_origen <> '2' and m.tipo_uso = @as_tipo_uso)) and
				d.cant_articulo >= 0            and
				d.tipo_bien    like @as_tipo_bien and
				d.grupo_bien   like @as_grup_bien and
				d.clase_bien   like @as_clas_bien and
				d.familia_bien like @as_fami_bien and
				d.item_bien    like @as_item_bien and
				d.clasificador like @as_clas_gast and
				d.mayor        like @as_plan_mayo and
				d.sub_cta      like @as_plan_scta ) and
	tipo_ppto    = @an_tipo_ppto and
	secuencia    = @an_encargo   and
	cant_invent  = 0 and
	cant_bueno   = 0 and
	cant_ingreso = 0 and
	cant_egreso  = 0 and
	stock_actual = 0 and
	stock_inicial= 0 

IF (@@error <> 0)
begin
	set @as_message = 'Error al eliminar kardex vacío : '
	return -1
End

DELETE FROM sig_kardex_por_almacen
 WHERE ano_eje      = @an_ano_eje  and
	sec_ejec     = @an_sec_ejec and
	mes_proceso  >= @as_mes     and
	almacen      = @as_almacen  and
	sec_almacen  = @as_sec_alma and
	tipo_bien    like @as_tipo_bien  and
	codigo_bien  like @ls_codi_bien_para  and
	clasificador like @as_clas_gast  and
	mayor        like @as_plan_mayo and
	sub_cta      like @as_plan_scta and
	tipo_uso     like @as_tipo_uso and
	tipo_ppto    = @an_tipo_ppto and
	secuencia    = @an_encargo   and
	cant_invent  = 0 and
	cant_bueno   = 0 and
	cant_ingreso = 0 and
	cant_egreso  = 0 and
	stock_actual = 0 and
	stock_inicial= 0 

IF (@@error <> 0)
begin
	set @as_message = 'Error al eliminar kardex vacío(2) : '
	return -1
End

exec sp_sig_kardex_peps_saldo @an_ano_eje, @an_sec_ejec, @as_almacen, @as_sec_alma, @as_mes, @as_tipo_uso, 
			 @an_tipo_ppto, @an_encargo, @as_tipo_bien, @as_grup_bien, @as_clas_bien,
			 @as_fami_bien, @as_item_bien, @as_clas_gast, @as_plan_mayo, @as_plan_scta,
			 @as_origen

set @as_message = 'Concluyó conforme : '

Return 1;
--/
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_SI_CONTRATO_TRX
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_SI_CONTRATO_TRX]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_SI_CONTRATO_TRX]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_SI_CONTRATO_TRX]
    @P_ANO_EJE                  NUMERIC(4,0),
    @P_SEC_EJC         			VARCHAR(10),
    @fecha_carga_inicio         VARCHAR(10),
    @fecha_carga_fin            VARCHAR(10),
    @P_USUARIO       			VARCHAR(30),
    @O_ERR_NUM     				NUMERIC(6,0) OUTPUT,                                                                             
    @O_ERR_MSG     				VARCHAR(255) OUTPUT    
AS
DECLARE @LC_TIPO_BIEN               VARCHAR(1)
DECLARE @LC_NRO_CONTRATO			numeric(5,0)
DECLARE @LC_PROVEEDOR_NRO_RUC       VARCHAR(11)  
DECLARE @LN_PROVEEDOR				NUMERIC(5,0)
DECLARE @LC_D_PROVEEDOR				VARCHAR(100)
DECLARE @LC_ESPEC_TECNICAS			VARCHAR(350)   
DECLARE @LC_FECHA_INICIAL			DATETIME  
DECLARE @LC_FECHA_FINAL				DATETIME  
DECLARE @LC_FECHA					DATETIME        
DECLARE @LC_MONEDA_PAGO				VARCHAR(6)
DECLARE @LC_NRO_DOCUMENTO           VARCHAR(50)
DECLARE @LN_ID_SI_CONTRATO			NUMERIC(10,0)
DECLARE @LN_ID_SI_CONTRATO_DETA     NUMERIC(10,0)
DECLARE @LC_ANO_PROCESO				NUMERIC(4,0)   
DECLARE @LC_MES_PROCESO				VARCHAR(2)     
DECLARE @LC_ESTADO                  VARCHAR(20)
DECLARE @LC_NRO_ORDEN				NUMERIC(7,0)     
DECLARE @LC_TIPO					VARCHAR(1)
DECLARE @LC_EJECUTADO				NUMERIC(16,2)
DECLARE @LC_IMPORTE					NUMERIC(16,2) 
DECLARE @_CANTIDAD					NUMERIC(16,2)  
DECLARE @LC_FECHA_ORDEN				DATETIME
DECLARE @fecha_carga_inicio_1       DATETIME
DECLARE @fecha_carga_fin_1          DATETIME  
DECLARE @fecha_carga_inicio_2       VARCHAR(10)
DECLARE @fecha_carga_fin_2          VARCHAR(10)  

BEGIN  
     DELETE FROM DBO.SI_CONTRATO_DETA_TRX 
     DELETE FROM DBO.SI_CONTRATO_TRX 
	
     SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
     SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)
     SET @fecha_carga_inicio_2 = Convert(VARCHAR, @fecha_carga_inicio_1, 112)
     SET @fecha_carga_fin_2    = Convert(VARCHAR, @fecha_carga_fin_1, 112)
	
     SELECT @LN_ID_SI_CONTRATO = MAX(ID_SI_CONTRATO)
				FROM SI_CONTRATO_TRX
				WHERE ANO_EJE  = @P_ANO_EJE 
				  AND SEC_EJEC = @P_SEC_EJC
	
     IF @LN_ID_SI_CONTRATO IS NULL
				SET @LN_ID_SI_CONTRATO = 0
    
	DECLARE C_1 CURSOR FOR 
	SELECT DISTINCT(NRO_CONTRATO) AS NRO_CONTRATO, 
		   TIPO_BIEN, FECHA, 
		   ESPEC_TECNICAS, FECHA_INICIAL, FECHA_FINAL,
		   MONEDA_PAGO,  NRO_DOCUMENTO, PROVEEDOR 	 
	FROM(
	SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,  
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,  
		   SIG_CONTRATOS.PROVEEDOR,	
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Pendiente' as estado,   
           0 as nro_orden,   
           '1' as tipo,   
           0 as ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
           FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL   
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
		   (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
           ( sig_contrato_item_mensual.flag_proceso = 'N' ) ) 
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
	GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
             SIG_CONTRATOS.TIPO_BIEN,
             SIG_CONTRATOS.FECHA,   
             SIG_CONTRATOS.ESPEC_TECNICAS,   
             SIG_CONTRATOS.FECHA_INICIAL,   
             SIG_CONTRATOS.FECHA_FINAL,   
             SIG_CONTRATOS.MONEDA_PAGO,         
             SIG_CONTRATOS.NRO_DOCUMENTO,  
			 SIG_CONTRATOS.PROVEEDOR,	       
             SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
             SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
    SELECT SIG_CONTRATOS.NRO_CONTRATO, 
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,	        
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Cuadro' as estado,   
           0 as nro_orden,   
           '2' as tipo,   
           0 as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM  SIG_CONTRATOS,   
             SIG_CONTRATO_ITEM_MENSUAL,   
             SIG_CUADRO_ADQUISICION   
	   WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
            ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
            ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
            ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
            ((sig_contratos.ano_eje = @P_ANO_EJE ) AND  
            ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
            ( sig_contratos.ano_eje = sig_cuadro_adquisicion.ano_contrato ) AND  
            ( sig_cuadro_adquisicion.estado = '1' ) AND  
            ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
            (sig_contrato_item_mensual.ano_proceso > 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) )    
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
    GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
             SIG_CONTRATOS.TIPO_BIEN,
             SIG_CONTRATOS.FECHA,   
             SIG_CONTRATOS.ESPEC_TECNICAS,   
             SIG_CONTRATOS.FECHA_INICIAL,   
             SIG_CONTRATOS.FECHA_FINAL,   
             SIG_CONTRATOS.MONEDA_PAGO,         
             SIG_CONTRATOS.NRO_DOCUMENTO,  
			 SIG_CONTRATOS.PROVEEDOR,	       
             SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
             SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
  SELECT   SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN,   
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,	         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           sig_contratos.tipo_bien as estado,   
           sig_orden_adquisicion.nro_orden as nro_orden,   
           '3' as tipo,   
           sig_orden_adquisicion.total_fact_moneda as  ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda)  as importe,   
           sig_orden_adquisicion.fecha_orden as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CUADRO_ADQUISICION,   
                SIG_ORDEN_ADQUISICION   
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.ANO_EJE = SIG_ORDEN_ADQUISICION.ANO_CUADRO ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_EJEC = SIG_ORDEN_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CUADRO_ADQUISICION.TIPO_BIEN = SIG_ORDEN_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_CUADRO = SIG_ORDEN_ADQUISICION.SEC_CUADRO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
           ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
           ( sig_cuadro_adquisicion.estado = '2' ) AND  
           ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
           (sig_contrato_item_mensual.ano_proceso > 2006 AND  
           sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) ) 
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN, 
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,  
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,	               
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           SIG_ORDEN_ADQUISICION.NRO_ORDEN,   
           SIG_ORDEN_ADQUISICION.FECHA_ORDEN,   
           SIG_ORDEN_ADQUISICION.TOTAL_FACT_MONEDA
  UNION   
  SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,   
		   SIG_CONTRATOS.PROVEEDOR,	       
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Externo' as estado,   
            0 as nro_orden,   
           '4' as tipo,   
           sum ( sig_contrato_item_mensual.valor_moneda) as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
		   FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL
      WHERE (SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
            (SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
            (SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
            (SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
            ((sig_contratos.ano_eje = @P_ANO_EJE ) AND  
            (sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
            (sig_contrato_item_mensual.flag_proceso = 'S' ) AND  
            (sig_contrato_item_mensual.sec_cuadro is null ) ) 
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0' 
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,	        
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
    )AS TABLE1
  	
    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_NRO_CONTRATO,       @LC_TIPO_BIEN,			@LC_FECHA, 
		 @LC_ESPEC_TECNICAS,     @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  
		 @LC_MONEDA_PAGO,		 @LC_NRO_DOCUMENTO,		@LN_PROVEEDOR	

    WHILE @@FETCH_STATUS = 0
    BEGIN
    SET @LN_ID_SI_CONTRATO = @LN_ID_SI_CONTRATO + 1

    INSERT INTO SI_CONTRATO_TRX
    (ANO_EJE,             SEC_EJEC,            ID_SI_CONTRATO, 
     NRO_CONTRATO,        TIPO_BIEN,           FECHA_CONTRATO, 
     CONCEPTO_CONTRATO,   PROVEEDOR_NRO_RUC,   D_PROVEEDOR,  
	 PROVEEDOR,			  FECHA_INICIO,   	   FECHA_FIN,          
	 MONEDA_PAGO,		  FECHA_CARGA_INICIO,  NRO_DOCUMENTO,      
	 FECHA_CARGA_FIN,     FECHA_ENVIO,         USUARIO_ENVIO)        
	VALUES 
    (@P_ANO_EJE,            @P_SEC_EJC,         @LN_ID_SI_CONTRATO,
     @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,      @LC_FECHA, 
     @LC_ESPEC_TECNICAS,    '',   '',			@LN_PROVEEDOR,
	 @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,         @LC_MONEDA_PAGO, 
     @fecha_carga_inicio_1, @LC_NRO_DOCUMENTO,       @fecha_carga_fin_1, 
     getdate(),               @P_USUARIO) 

  DECLARE C_2 CURSOR FOR
  SELECT NRO_CONTRATO, TIPO_BIEN, FECHA, ESPEC_TECNICAS, FECHA_INICIAL,
         FECHA_FINAL, MONEDA_PAGO, NRO_DOCUMENTO, PROVEEDOR, 
         ANO_PROCESO, MES_PROCESO, estado, nro_orden,
         tipo, ejecutado, importe, fecha_orden 
         FROM (
  
	SELECT SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,  
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,	         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Pendiente' as estado,   
           0 as nro_orden,   
           '1' as tipo,   
           0 as ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
          FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL
       WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
		   ( sig_contrato_item_mensual.flag_proceso = 'N' ) )  
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
            SIG_CONTRATOS.TIPO_BIEN,
            SIG_CONTRATOS.FECHA,   
            SIG_CONTRATOS.ESPEC_TECNICAS,   
            SIG_CONTRATOS.FECHA_INICIAL,   
            SIG_CONTRATOS.FECHA_FINAL,   
            SIG_CONTRATOS.MONEDA_PAGO,         
            SIG_CONTRATOS.NRO_DOCUMENTO, 
			SIG_CONTRATOS.PROVEEDOR,	         
            SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
            SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
    SELECT SIG_CONTRATOS.NRO_CONTRATO, 
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,  
		   SIG_CONTRATOS.PROVEEDOR,	        
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Cuadro' as estado,   
           0 as nro_orden,   
           '2' as tipo,   
           0 as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
     FROM  SIG_CONTRATOS,   
           SIG_CONTRATO_ITEM_MENSUAL,   
           SIG_CUADRO_ADQUISICION 
       WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
            ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
            ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
            ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
            ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
            (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
            ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
            ( sig_contratos.ano_eje = sig_cuadro_adquisicion.ano_contrato ) AND  
		    ( sig_cuadro_adquisicion.estado = '1' ) AND  
            ((sig_contrato_item_mensual.ano_proceso <= 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
            (sig_contrato_item_mensual.ano_proceso > 2006 AND  
             sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) ) 
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
            SIG_CONTRATOS.TIPO_BIEN,
            SIG_CONTRATOS.FECHA,   
            SIG_CONTRATOS.ESPEC_TECNICAS,   
            SIG_CONTRATOS.FECHA_INICIAL,   
            SIG_CONTRATOS.FECHA_FINAL,   
            SIG_CONTRATOS.MONEDA_PAGO,         
            SIG_CONTRATOS.NRO_DOCUMENTO, 
			SIG_CONTRATOS.PROVEEDOR,        
            SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
            SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  UNION   
  SELECT   SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN,   
		   SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,  
		   SIG_CONTRATOS.PROVEEDOR,             
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           sig_contratos.tipo_bien as estado,   
           sig_orden_adquisicion.nro_orden as nro_orden,   
           '3' as tipo,   
           sig_orden_adquisicion.total_fact_moneda as  ejecutado,   
           sum(sig_contrato_item_mensual.valor_moneda)  as importe,   
           sig_orden_adquisicion.fecha_orden as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL,   
                SIG_CUADRO_ADQUISICION,   
                SIG_ORDEN_ADQUISICION 
       WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE = SIG_CUADRO_ADQUISICION.ANO_CONTRATO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC = SIG_CUADRO_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO = SIG_CUADRO_ADQUISICION.NRO_CONTRATO ) and  
           ( SIG_CONTRATOS.TIPO_BIEN = SIG_CUADRO_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.ANO_EJE = SIG_ORDEN_ADQUISICION.ANO_CUADRO ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_EJEC = SIG_ORDEN_ADQUISICION.SEC_EJEC ) and  
           ( SIG_CUADRO_ADQUISICION.TIPO_BIEN = SIG_ORDEN_ADQUISICION.TIPO_BIEN ) and  
           ( SIG_CUADRO_ADQUISICION.SEC_CUADRO = SIG_ORDEN_ADQUISICION.SEC_CUADRO ) and  
           ( SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO = SIG_CUADRO_ADQUISICION.ANO_EJE ) and  
           (( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           (  sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
		   (  sig_cuadro_adquisicion.estado = '2' ) AND  
           (( sig_contrato_item_mensual.ano_proceso <= 2006 AND  
              sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.sec_cuadro) OR  
           (sig_contrato_item_mensual.ano_proceso > 2006 AND  
            sig_contrato_item_mensual.sec_cuadro = sig_cuadro_adquisicion.nro_grupo_cuadro)) )   
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
   GROUP BY SIG_CONTRATOS.NRO_CONTRATO,  
           SIG_CONTRATOS.TIPO_BIEN, 
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,  
           SIG_CONTRATOS.NRO_DOCUMENTO,  
		   SIG_CONTRATOS.PROVEEDOR,                    
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           SIG_ORDEN_ADQUISICION.NRO_ORDEN,   
           SIG_ORDEN_ADQUISICION.FECHA_ORDEN,   
           SIG_ORDEN_ADQUISICION.TOTAL_FACT_MONEDA
  UNION   
  SELECT   SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
		   SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO,
		   SIG_CONTRATOS.PROVEEDOR,         
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO,   
           'Externo' as estado,   
            0 as nro_orden,   
           '4' as tipo,   
           sum ( sig_contrato_item_mensual.valor_moneda) as ejecutado,   
           sum ( sig_contrato_item_mensual.valor_moneda) as importe,   
           null as fecha_orden
       FROM SIG_CONTRATOS,   
                SIG_CONTRATO_ITEM_MENSUAL 
      WHERE ( SIG_CONTRATOS.ANO_EJE = SIG_CONTRATO_ITEM_MENSUAL.ANO_EJE ) and  
           ( SIG_CONTRATOS.SEC_EJEC = SIG_CONTRATO_ITEM_MENSUAL.SEC_EJEC ) and  
           ( SIG_CONTRATOS.TIPO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.TIPO_CONTRATO ) and  
           ( SIG_CONTRATOS.NRO_CONTRATO = SIG_CONTRATO_ITEM_MENSUAL.NRO_CONTRATO ) and  
           ( ( sig_contratos.ano_eje = @P_ANO_EJE ) AND  
           ( sig_contratos.sec_ejec = @P_SEC_EJC ) AND  
           ( sig_contrato_item_mensual.flag_proceso = 'S' ) AND  
           (  sig_contrato_item_mensual.sec_cuadro is null ) )   
			AND ISNULL(SIG_CONTRATOS.FLAG_SNP,'0') = '0'
    GROUP BY SIG_CONTRATOS.NRO_CONTRATO,   
           SIG_CONTRATOS.TIPO_BIEN,
           SIG_CONTRATOS.FECHA,   
           SIG_CONTRATOS.ESPEC_TECNICAS,   
           SIG_CONTRATOS.FECHA_INICIAL,   
           SIG_CONTRATOS.FECHA_FINAL,   
           SIG_CONTRATOS.MONEDA_PAGO,         
           SIG_CONTRATOS.NRO_DOCUMENTO, 
		   SIG_CONTRATOS.PROVEEDOR,        
           SIG_CONTRATO_ITEM_MENSUAL.ANO_PROCESO,   
           SIG_CONTRATO_ITEM_MENSUAL.MES_PROCESO
  )AS TABLA1 WHERE NRO_CONTRATO = @LC_NRO_CONTRATO
 
  OPEN C_2
         FETCH NEXT FROM C_2 
         INTO @LC_NRO_CONTRATO,      @LC_TIPO_BIEN, 
            @LC_FECHA,        @LC_ESPEC_TECNICAS, 
            @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  @LC_MONEDA_PAGO, 
            @LC_NRO_DOCUMENTO,     @LN_PROVEEDOR, 
		    @LC_ANO_PROCESO,  @LC_MES_PROCESO,
            @LC_ESTADO,      @LC_NRO_ORDEN,    @LC_TIPO, 
			@LC_EJECUTADO,     @LC_IMPORTE,      @LC_FECHA_ORDEN  
 
         WHILE @@FETCH_STATUS = 0
         BEGIN         
 
		SELECT @LN_ID_SI_CONTRATO_DETA = MAX(ID_SI_CONTRATO_DETA)
         FROM SI_CONTRATO_DETA_TRX
              WHERE ANO_EJE  = @P_ANO_EJE 
                AND SEC_EJEC = @P_SEC_EJC
                AND ID_SI_CONTRATO = @LN_ID_SI_CONTRATO
		
		IF @LC_ESTADO = 'B'      
				SET @LC_ESTADO = 'O/C'

		IF @LC_ESTADO = 'S'      
				SET @LC_ESTADO = 'O/S'
 
         IF @LN_ID_SI_CONTRATO_DETA IS NULL
                SET @LN_ID_SI_CONTRATO_DETA = 0
				SET @LN_ID_SI_CONTRATO_DETA = @LN_ID_SI_CONTRATO_DETA + 1

		INSERT INTO SI_CONTRATO_DETA_TRX
                    (ANO_EJE,			   SEC_EJEC,		   ID_SI_CONTRATO,  
					 ID_SI_CONTRATO_DETA,  ANO_PROCESO,        MES_PROCESO,          
					 ESTADO,			   NRO_ORDEN,		   TIPO,          
					 MONTO_EJECUTADO,      MONTO_IMPORTE,      FECHA_ORDEN, 
					 FECHA_CARGA_INICIO,   FECHA_CARGA_FIN,    FECHA_ENVIO,     
					 USUARIO_ENVIO)
           VALUES
			   (@P_ANO_EJE,				  @P_SEC_EJC,         @LN_ID_SI_CONTRATO,  
				@LN_ID_SI_CONTRATO_DETA,  @LC_ANO_PROCESO,    @LC_MES_PROCESO,      
				@LC_ESTADO,               @LC_NRO_ORDEN,      @LC_TIPO,
				@LC_EJECUTADO,            @LC_IMPORTE,        @LC_FECHA_ORDEN,
				@fecha_carga_inicio_1,    @fecha_carga_fin_1,   
				getdate(),    @P_USUARIO)
 
         FETCH NEXT FROM C_2 
         INTO @LC_NRO_CONTRATO,      @LC_TIPO_BIEN,   
			  @LC_FECHA,			 @LC_ESPEC_TECNICAS, 
              @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,   @LC_MONEDA_PAGO, 
              @LC_NRO_DOCUMENTO,     @LN_PROVEEDOR,	    @LC_ANO_PROCESO,  
			  @LC_MES_PROCESO,		 @LC_ESTADO,        @LC_NRO_ORDEN,    @LC_TIPO, 
			  @LC_EJECUTADO,		 @LC_IMPORTE,       @LC_FECHA_ORDEN  
         END
         CLOSE C_2
         DEALLOCATE C_2
			
		 FETCH NEXT FROM C_1
         INTO @LC_NRO_CONTRATO,       @LC_TIPO_BIEN,			@LC_FECHA, 
		 @LC_ESPEC_TECNICAS,     @LC_FECHA_INICIAL,     @LC_FECHA_FINAL,  
		 @LC_MONEDA_PAGO,		 @LC_NRO_DOCUMENTO,		@LN_PROVEEDOR	

    END
    CLOSE C_1
    DEALLOCATE C_1
END
GO


-- ----------------------------
-- procedure structure for usp_GenTMPCN2013
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_GenTMPCN2013]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[usp_GenTMPCN2013]
GO

CREATE PROCEDURE [dbo].[usp_GenTMPCN2013]
@anio int,
@secejec NUMERIC(6,0)
as
begin
--aaaaaaaaaaaaaaaaaaa

INSERT INTO sig_catalogo_bien_serv_precio
(sec_ejec, ano_eje, tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, precio_ref,
unidad_medida,fecha_reg, estado, cuser_id, equipo_reg, indicador, fecha_ref, cuser_modif,
flag_proc_cn, precio_ref_origen, flag_proc, flag_pase, flag_ppr_req, flag_ppr_prg,
flag_ppr_apr)
SELECT sec_ejec, 2013, tipo_bien, grupo_bien, clase_bien, familia_bien, item_bien, precio_ref,
unidad_medida,fecha_reg, estado, cuser_id, equipo_reg, indicador, fecha_ref, cuser_modif,
flag_proc_cn, precio_ref_origen, flag_proc, flag_pase, flag_ppr_req, flag_ppr_prg, flag_ppr_apr
FROM sig_catalogo_bien_serv_precio
WHERE ano_eje  = 2012 and
sec_ejec = @secejec AND
not exists (SELECT '1' FROM sig_catalogo_bien_serv_precio a
WHERE a.ano_eje      =2013 and
a.sec_ejec     = @secejec    and
a.tipo_bien    = sig_catalogo_bien_serv_precio.tipo_bien    and
a.grupo_bien   = sig_catalogo_bien_serv_precio.grupo_bien   and
a.clase_bien   = sig_catalogo_bien_serv_precio.clase_bien   and
a.familia_bien = sig_catalogo_bien_serv_precio.familia_bien and
a.item_bien    = sig_catalogo_bien_serv_precio.item_bien)

INSERT INTO Sig_TAREA
(SEC_EJEC, ANO_EJE, TIPO_TAREA, NIVEL_TAREA, TAREA_GENERAL, NOMBRE, GRUPO_TAREA, ESTADO, FECHA_REG,
CUSER_ID, TIPO_PPTO, TIPO_USO, SEC_EJEC2, TIPO_TAREA_PAD, NIVEL_TAREA_PAD, TAREA_GENERAL_PAD ,
ORDEN_TAREA, TIPO_META)
SELECT VV.SEC_EJEC, VV.ANO_EJE, VV.TIPO_TAREA, VV.NIVEL_TAREA, VV.CODIGO_TAREA, 
M.NOMBRE, M.GRUPO_TAREA, M.ESTADO, M.FECHA_REG,
M.CUSER_ID, M.TIPO_PPTO, M.TIPO_USO, M.SEC_EJEC2, M.TIPO_TAREA_PAD, M.NIVEL_TAREA_PAD, M.TAREA_GENERAL_PAD ,
M.ORDEN_TAREA, M.TIPO_META
FROM
sig_tarea M, 
(
select DISTINCT cn.SEC_EJEC,2013 ANO_EJE, Cn.TIPO_TAREA,cn.NIVEL_TAREA,
	   	(
				select top 1 TAREA_GENERAL
						from SIG_TAREA_ESTRATEGICO
						where ANO_EJE = 2012
						and SUBFINALIDAD = cn.sub_finalidad
		) as codigo_tarea
from sig_cuadro_necesidad cn,
	(
	 select distinct mp1.PROGRAMA_INSTITUCIONAL, 
						 mp1.SEC_FUNC_PROP, 
						 mp2.ACT_PROY, 
						 mp2.SEC_FUNC_PROP as SEC_FUNC_PROP2013,
						 mxc1.CENTRO_COSTO
		   from SIG_META_PROPUESTA_FASE mp1
		   join SIG_METAS_PROP_X_CENTRO mxc1
		   on (mp1.ANO_EJE = mxc1.ANO_EJE
		   and mp1.SEC_EJEC = mxc1.SEC_EJEC
		   and mp1.SEC_FUNC_PROP = mxc1.SEC_FUNC_PROP
		   and mp1.FASE_CUADRO = 1),
				SIG_META_PROPUESTA mp2
		   join SIG_METAS_PROP_X_CENTRO mxc2
		   on (mp2.ANO_EJE = mxc2.ANO_EJE
		   and mp2.SEC_EJEC = mxc2.SEC_EJEC
		   and mp2.SEC_FUNC_PROP = mxc2.SEC_FUNC_PROP) 
		  where mp1.ano_eje = 2012 and mp1.FLAG_ESTRATEGIA = 'S' and mp2.ano_eje = 2012
			and mp1.FASE_CUADRO = 1
			and mp1.PROGRAMA_INSTITUCIONAL = mp2.PROGRAMA_INSTITUCIONAL and mp1.ACT_PROY = mp2.ACT_PROY
			and mp2.FLAG_ESTRATEGIA = 'S'
			 and mxc1.SEC_EJEC = mxc2.SEC_EJEC
			 and mxc1.CENTRO_COSTO = mxc2.CENTRO_COSTO
		)t1
where cn.ANO_EJE= 2012 and cn.SEC_EJEC= @secejec and
	  cn.CENTRO_COSTO= t1.CENTRO_COSTO and cn.SEC_FUNC_PROP= t1.SEC_FUNC_PROP and
	  exists (select 1 from SIG_SUB_FINALIDAD sgf ,
								  			SIG_PPR_KIT_ITEMS_EST spk
											where sgf.ANO_EJE= 2013 and 
											sgf.SUB_FINALIDAD=cN.sub_finalidad  and 
											sgf.ESTADO='A'  AND 
											spk.ANO_EJE=sgf.ANO_EJE AND
											spk.SUB_FINALIDAD=sgf.SUB_FINALIDAD AND
											spk.ID_SUB_FINALIDAD= sgf.ID_SUB_FINALIDAD 
											AND	spk.ESTADO in ('A','M','N')  AND
										 	SPk.TIPO_CALCULO IN (4,5,6,8)   ) AND
EXISTS (SELECT X.ANO_EJE FROM SIG_META_PROPUESTA X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.SEC_FUNC_PROP = CN.SEC_FUNC_PROP) AND
EXISTS( SELECT X.ANO_EJE FROM Fuente_Financ_Ejec X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.FUENTE_FINANC =  CN.FUENTE_FINANC) AND
EXISTS( SELECT X.ANO_EJE FROM SIG_CLASIFICADOR_GASTO X
WHERE
X.ANO_EJE = 2013 AND
X.CLASIFICADOR = CN.CLASIFICADOR)
) AS VV
WHERE
M.ANO_EJE = 2012 AND
VV.ANO_EJE = 2013 AND
VV.SEC_EJEC = M.SEC_EJEC AND
VV.TIPO_TAREA = M.TIPO_TAREA AND
VV.NIVEL_TAREA = M.NIVEL_TAREA AND
VV.CODIGO_TAREA = M.TAREA_GENERAL AND
NOT EXISTS( SELECT X.ANO_EJE FROM sig_tarea X
WHERE
X.ano_eje = 2013 AND
X.sec_ejec = VV.SEC_EJEC AND
X.tipo_tarea = VV.TIPO_TAREA AND
X.NIVEL_TAREA = VV.NIVEL_TAREA AND
X.tarea_general = VV.CODIGO_TAREA)


INSERT INTO Sig_TAREA_ESTRATEGICO
(SEC_EJEC, ANO_EJE, TIPO_TAREA, NIVEL_TAREA, TAREA_GENERAL,Finalidad, PROGRAMA_INSTITUCIONAL,
SUBFINALIDAD, ID_SUB_FINALIDAD, Componente)
SELECT VV.SEC_EJEC, VV.ANO_EJE, VV.TIPO_TAREA, VV.NIVEL_TAREA, VV.CODIGO_TAREA, 
M.Finalidad, M.PROGRAMA_INSTITUCIONAL,
M.SUBFINALIDAD, M.ID_SUB_FINALIDAD, M.Componente
FROM
Sig_TAREA_ESTRATEGICO M, 
(
select DISTINCT cn.SEC_EJEC,2013 ANO_EJE, Cn.TIPO_TAREA,cn.NIVEL_TAREA,
	   	(
				select top 1 TAREA_GENERAL
						from SIG_TAREA_ESTRATEGICO
						where ANO_EJE = 2012
						and SUBFINALIDAD = cn.sub_finalidad
		) as codigo_tarea
from sig_cuadro_necesidad cn,
	(
	 select distinct mp1.PROGRAMA_INSTITUCIONAL, 
						 mp1.SEC_FUNC_PROP, 
						 mp2.ACT_PROY, 
						 mp2.SEC_FUNC_PROP as SEC_FUNC_PROP2013,
						 mxc1.CENTRO_COSTO
		   from SIG_META_PROPUESTA_FASE mp1
		   join SIG_METAS_PROP_X_CENTRO mxc1
		   on (mp1.ANO_EJE = mxc1.ANO_EJE
		   and mp1.SEC_EJEC = mxc1.SEC_EJEC
		   and mp1.SEC_FUNC_PROP = mxc1.SEC_FUNC_PROP
		   and mp1.FASE_CUADRO = 1),
				SIG_META_PROPUESTA mp2
		   join SIG_METAS_PROP_X_CENTRO mxc2
		   on (mp2.ANO_EJE = mxc2.ANO_EJE
		   and mp2.SEC_EJEC = mxc2.SEC_EJEC
		   and mp2.SEC_FUNC_PROP = mxc2.SEC_FUNC_PROP) 
		  where mp1.ano_eje = 2012 and mp1.FLAG_ESTRATEGIA = 'S' and mp2.ano_eje = 2012
			and mp1.FASE_CUADRO = 1
			and mp1.PROGRAMA_INSTITUCIONAL = mp2.PROGRAMA_INSTITUCIONAL and mp1.ACT_PROY = mp2.ACT_PROY
			and mp2.FLAG_ESTRATEGIA = 'S'
			 and mxc1.SEC_EJEC = mxc2.SEC_EJEC
			 and mxc1.CENTRO_COSTO = mxc2.CENTRO_COSTO
		)t1
where cn.ANO_EJE= 2012 and cn.SEC_EJEC= @secejec and
	  cn.CENTRO_COSTO= t1.CENTRO_COSTO and cn.SEC_FUNC_PROP= t1.SEC_FUNC_PROP and
	  exists (select 1 from SIG_SUB_FINALIDAD sgf ,
								  			SIG_PPR_KIT_ITEMS_EST spk
											where sgf.ANO_EJE= 2013 and 
											sgf.SUB_FINALIDAD=cN.sub_finalidad  and 
											sgf.ESTADO='A'  AND 
											spk.ANO_EJE=sgf.ANO_EJE AND
											spk.SUB_FINALIDAD=sgf.SUB_FINALIDAD AND
											spk.ID_SUB_FINALIDAD= sgf.ID_SUB_FINALIDAD 
											AND	spk.ESTADO in ('A','M','N') AND
										 	SPk.TIPO_CALCULO IN (4,5,6,8)   ) AND
EXISTS (SELECT X.ANO_EJE FROM SIG_META_PROPUESTA X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.SEC_FUNC_PROP = CN.SEC_FUNC_PROP) AND
EXISTS( SELECT X.ANO_EJE FROM Fuente_Financ_Ejec X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.FUENTE_FINANC =  CN.FUENTE_FINANC) AND
EXISTS( SELECT X.ANO_EJE FROM SIG_CLASIFICADOR_GASTO X
WHERE
X.ANO_EJE = 2013 AND
X.CLASIFICADOR = CN.CLASIFICADOR)
) AS VV
WHERE
M.ANO_EJE = 2012 AND
VV.ANO_EJE = 2013 AND
VV.SEC_EJEC = M.SEC_EJEC AND
VV.TIPO_TAREA = M.TIPO_TAREA AND
VV.NIVEL_TAREA = M.NIVEL_TAREA AND
VV.CODIGO_TAREA = M.TAREA_GENERAL AND
NOT EXISTS( SELECT X.ANO_EJE FROM Sig_TAREA_ESTRATEGICO X
WHERE
X.ano_eje = 2013 AND
X.sec_ejec = VV.SEC_EJEC AND
X.tipo_tarea = VV.TIPO_TAREA AND
X.NIVEL_TAREA = VV.NIVEL_TAREA AND
X.tarea_general = VV.CODIGO_TAREA)


INSERT INTO Sig_centro_costo_tarea
(SEC_EJEC, ANO_EJE, CENTRO_COSTO, TIPO_TAREA, NIVEL_TAREA, CODIGO_TAREA, NOMBRE_TAREA, GRUPO_TAREA,
TAREA_GENERAL, ESTADO, FECHA_REG, CUSER_ID, TIPO_PPTO, TIPO_USO, SEC_EJEC2, CANTIDAD, unidad_medida,
FLAG_TP, TIPO_TAREA_PAD, NIVEL_TAREA_PAD, TAREA_GENERAL_PAD)
SELECT VV.SEC_EJEC, VV.ANO_EJE, VV.CENTRO_COSTO, VV.TIPO_TAREA, VV.NIVEL_TAREA, VV.CODIGO_TAREA, 
M.NOMBRE, M.GRUPO_TAREA,
M.TAREA_GENERAL, M.ESTADO, M.FECHA_REG, M.CUSER_ID, M.TIPO_PPTO, M.TIPO_USO, M.SEC_EJEC2, 0, NULL,
NULL, M.TIPO_TAREA_PAD, M.NIVEL_TAREA_PAD, M.TAREA_GENERAL_PAD
FROM
SIG_TAREA M, 
(
select DISTINCT cn.SEC_EJEC,2013 ANO_EJE, Cn.TIPO_TAREA,cn.NIVEL_TAREA,CN.CENTRO_COSTO,
	   	(
				select top 1 TAREA_GENERAL
						from SIG_TAREA_ESTRATEGICO
						where ANO_EJE = 2012
						and SUBFINALIDAD = cn.sub_finalidad
		) as codigo_tarea
from sig_cuadro_necesidad cn,
	(
	 select distinct mp1.PROGRAMA_INSTITUCIONAL, 
						 mp1.SEC_FUNC_PROP, 
						 mp2.ACT_PROY, 
						 mp2.SEC_FUNC_PROP as SEC_FUNC_PROP2013,
						 mxc1.CENTRO_COSTO
		   from SIG_META_PROPUESTA_FASE mp1
		   join SIG_METAS_PROP_X_CENTRO mxc1
		   on (mp1.ANO_EJE = mxc1.ANO_EJE
		   and mp1.SEC_EJEC = mxc1.SEC_EJEC
		   and mp1.SEC_FUNC_PROP = mxc1.SEC_FUNC_PROP
		   and mp1.FASE_CUADRO = 1),
				SIG_META_PROPUESTA mp2
		   join SIG_METAS_PROP_X_CENTRO mxc2
		   on (mp2.ANO_EJE = mxc2.ANO_EJE
		   and mp2.SEC_EJEC = mxc2.SEC_EJEC
		   and mp2.SEC_FUNC_PROP = mxc2.SEC_FUNC_PROP) 
		  where mp1.ano_eje = 2012 and mp1.FLAG_ESTRATEGIA = 'S' and mp2.ano_eje = 2012
			and mp1.FASE_CUADRO = 1
			and mp1.PROGRAMA_INSTITUCIONAL = mp2.PROGRAMA_INSTITUCIONAL and mp1.ACT_PROY = mp2.ACT_PROY
			and mp2.FLAG_ESTRATEGIA = 'S'
			 and mxc1.SEC_EJEC = mxc2.SEC_EJEC
			 and mxc1.CENTRO_COSTO = mxc2.CENTRO_COSTO
		)t1
where cn.ANO_EJE= 2012 and cn.SEC_EJEC= @secejec AND cn.fase_cuadro=1 and
	  cn.CENTRO_COSTO= t1.CENTRO_COSTO and cn.SEC_FUNC_PROP= t1.SEC_FUNC_PROP and
	  exists (select 1 from SIG_SUB_FINALIDAD sgf ,
								  			SIG_PPR_KIT_ITEMS_EST spk
											where sgf.ANO_EJE= 2013 and 
											sgf.SUB_FINALIDAD=cN.sub_finalidad  and 
											sgf.ESTADO='A'  AND 
											spk.ANO_EJE=sgf.ANO_EJE AND
											spk.SUB_FINALIDAD=sgf.SUB_FINALIDAD AND
											spk.ID_SUB_FINALIDAD= sgf.ID_SUB_FINALIDAD 
											AND	spk.ESTADO in ('A','M','N')  AND
										 	SPk.TIPO_CALCULO IN (4,5,6,8)   ) AND
EXISTS (SELECT X.ANO_EJE FROM SIG_META_PROPUESTA X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.SEC_FUNC_PROP = CN.SEC_FUNC_PROP) AND
EXISTS( SELECT X.ANO_EJE FROM Fuente_Financ_Ejec X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.FUENTE_FINANC =  CN.FUENTE_FINANC) AND
EXISTS( SELECT X.ANO_EJE FROM SIG_CLASIFICADOR_GASTO X
WHERE
X.ANO_EJE = 2013 AND
X.CLASIFICADOR = CN.CLASIFICADOR)
) AS VV
WHERE
M.ANO_EJE = 2012 AND
VV.ANO_EJE = 2013 AND
VV.SEC_EJEC = M.SEC_EJEC AND
VV.TIPO_TAREA = M.TIPO_TAREA AND
VV.NIVEL_TAREA = M.NIVEL_TAREA AND
VV.CODIGO_TAREA = M.TAREA_GENERAL AND
NOT EXISTS( SELECT X.ANO_EJE FROM Sig_centro_costo_tarea X
WHERE
X.ano_eje = 2013 AND
X.sec_ejec = VV.SEC_EJEC AND
X.tipo_tarea = VV.TIPO_TAREA AND
X.NIVEL_TAREA = VV.NIVEL_TAREA AND
X.CODIGO_TAREA = VV.CODIGO_TAREA AND
X.centro_costo  = VV.CENTRO_COSTO)


INSERT INTO tmp_cab
(ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA, FASE_CUADRO, TIPO_TAREA, NIVEL_TAREA, CODIGO_TAREA, sec_func_prop, sec_func, ORIGEN, FUENTE_FINANC, 
		CONCEPTO_GASTO, CATEG_GASTO, GRUPO_GASTO, CLASIFICADOR, TIPO_RECURSO, TOTAL_ASIGNADO, TOTAL_PROGRA, TOTAL_APROB,TOTAL_MODIF, MONTO_ASIGNADO, 
		MONTO_PROGRA, MONTO_APROB, MONTO_MODIF, VALOR_IMP_ASIGNADO, VALOR_IMP_PROGRA, VALOR_IMP_APROB, VALOR_IMP_MODIF,TIPO_IMPUESTO, FUENTE_IMPTO, 
		TASA_IMPTO, FLAG_GASTO, TIPO_PPTO, TIPO_USO, EQUIPO_REG, FECHA_REG, CUSER_ID, tipo_operacion, operacion, mayor,sub_cta, sub_cta_det, NRO_PLANTILLA, 
		tipo_bien, TIPO_ORIGEN_EXTERNO, ID_CLASIFICADOR, sec_establec, sub_finalidad, flag_origen_cab,  ID_SUB_FINALIDAD)

select DISTINCT 2013 ANO_EJE, cn.SEC_EJEC,cn.CENTRO_COSTO,cn.SECUENCIA,cn.FASE_CUADRO,cn.TIPO_TAREA,cn.NIVEL_TAREA,
		(
				select top 1 TAREA_GENERAL
						from SIG_TAREA_ESTRATEGICO
						where ANO_EJE = @anio
						and SUBFINALIDAD = cn.sub_finalidad
		) as codigo_tarea,
       t1.SEC_FUNC_PROP2013, null sec_func, cn.ORIGEN,cn.FUENTE_FINANC,null concept_gasto,cn.CATEG_GASTO,cn.GRUPO_GASTO,
       cn.CLASIFICADOR,cn.TIPO_RECURSO,cn.TOTAL_ASIGNADO,cn.TOTAL_PROGRA,cn.TOTAL_APROB,cn.TOTAL_MODIF,cn.TOTAL_ASIGNADO,
       cn.MONTO_PROGRA,cn.MONTO_APROB,MONTO_MODIF,VALOR_IMP_ASIGNADO,VALOR_IMP_ASIGNADO,VALOR_IMP_APROB,VALOR_IMP_MODIF,
       cn.TIPO_IMPUESTO,cn.FUENTE_IMPTO,cn.TASA_IMPTO,cn.FLAG_GASTO,cn.TIPO_PPTO,cn.TIPO_USO, 'MIGRA013' EQUIPO_REG, getdate() FECHA_REG, 'MIGRA013'CUSER_ID,
       cn.tipo_operacion,cn.operacion,cn.mayor,cn.sub_cta,cn.sub_cta_det,cn.NRO_PLANTILLA,cn.tipo_bien,cn.TIPO_ORIGEN_EXTERNO,
       cn.ID_CLASIFICADOR,cn.sec_establec,cn.sub_finalidad,cn.flag_origen_cab,cn.ID_SUB_FINALIDAD
from sig_cuadro_necesidad cn,
	(
	 select distinct mp1.PROGRAMA_INSTITUCIONAL, 
						 mp1.SEC_FUNC_PROP, 
						 mp2.ACT_PROY, 
						 mp2.SEC_FUNC_PROP as SEC_FUNC_PROP2013,
						 mxc1.CENTRO_COSTO
		   from SIG_META_PROPUESTA_FASE mp1
		   join SIG_METAS_PROP_X_CENTRO mxc1
		   on (mp1.ANO_EJE = mxc1.ANO_EJE
		   and mp1.SEC_EJEC = mxc1.SEC_EJEC
		   and mp1.SEC_FUNC_PROP = mxc1.SEC_FUNC_PROP
		   and mp1.FASE_CUADRO = 1),
				SIG_META_PROPUESTA mp2
		   join SIG_METAS_PROP_X_CENTRO mxc2
		   on (mp2.ANO_EJE = mxc2.ANO_EJE
		   and mp2.SEC_EJEC = mxc2.SEC_EJEC
		   and mp2.SEC_FUNC_PROP = mxc2.SEC_FUNC_PROP) 
		  where mp1.ano_eje = 2012 and mp1.FLAG_ESTRATEGIA = 'S' and mp2.ano_eje = @anio
			and mp1.FASE_CUADRO = 1
			and mp1.PROGRAMA_INSTITUCIONAL = mp2.PROGRAMA_INSTITUCIONAL and mp1.ACT_PROY = mp2.ACT_PROY
			and mp2.FLAG_ESTRATEGIA = 'S'
			 and mxc1.SEC_EJEC = mxc2.SEC_EJEC
			 and mxc1.CENTRO_COSTO = mxc2.CENTRO_COSTO
		)t1
where cn.ANO_EJE= 2012 and cn.SEC_EJEC= @secejec AND  cn.fase_cuadro=1 AND
	  cn.CENTRO_COSTO= t1.CENTRO_COSTO and cn.SEC_FUNC_PROP= t1.SEC_FUNC_PROP and
	  exists (select 1 from SIG_SUB_FINALIDAD sgf ,
								  			SIG_PPR_KIT_ITEMS_EST spk
											where sgf.ANO_EJE= 2013 and 
											sgf.SUB_FINALIDAD=cN.sub_finalidad  and 
											sgf.ESTADO in ('A')   AND 
											spk.ANO_EJE=sgf.ANO_EJE AND
											spk.SUB_FINALIDAD=sgf.SUB_FINALIDAD AND
											spk.ID_SUB_FINALIDAD= sgf.ID_SUB_FINALIDAD 
											AND	spk.ESTADO IN ('A','M','N') AND
										 	SPk.TIPO_CALCULO IN (4,5,6,8)   ) AND
EXISTS (SELECT X.ANO_EJE FROM SIG_META_PROPUESTA X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC ) AND
EXISTS( SELECT X.ANO_EJE FROM Fuente_Financ_Ejec X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.FUENTE_FINANC =  CN.FUENTE_FINANC) AND
EXISTS( SELECT X.ANO_EJE FROM SIG_CLASIFICADOR_GASTO X
WHERE
X.ANO_EJE = 2013 AND
X.CLASIFICADOR = CN.CLASIFICADOR) AND
EXISTS( SELECT X.ANO_EJE FROM SIG_CENTRO_COSTO_TAREA X
WHERE
X.ANO_EJE = 2013 AND
X.SEC_EJEC = CN.SEC_EJEC AND
X.CENTRO_COSTO = CN.CENTRO_COSTO AND
X.tipo_tarea = CN.TIPO_TAREA AND
X.nivel_tarea = CN.NIVEL_TAREA AND
X.codigo_tarea = (
				select top 1 TAREA_GENERAL
						from SIG_TAREA_ESTRATEGICO
						where ANO_EJE = 2012
						and SUBFINALIDAD = cn.sub_finalidad
		))
							 	

		INSERT INTO tmp_det
			   (ANO_EJE, SEC_EJEC, CENTRO_COSTO, SECUENCIA, FASE_CUADRO, ITEM_SEC, TIPO_BIEN, GRUPO_BIEN, CLASE_BIEN, FAMILIA_BIEN,
				ITEM_BIEN, DESCRIP_SERVICIO, UNIDAD_MEDIDA, PRECIO_UNIT, CANT_01, CANT_02, CANT_03, CANT_04, CANT_05, CANT_06,
				CANT_07, CANT_08, CANT_09, CANT_10, CANT_11, CANT_12, CANT_TOTAL, MNTO_01, MNTO_02, MNTO_03, MNTO_04, MNTO_05,
				MNTO_06, MNTO_07, MNTO_08, MNTO_09, MNTO_10, MNTO_11, MNTO_12, MNTO_TOTAL, STOCK_ASIG, VALOR_STOCK, TIPO_IMPTO,
				TASA_IMPTO, FTE_IMPTO, VALOR_IMPTO, ESTADO, CANT_HIST, MNTO_HIST, NRO_CONSOLID, ESTADO_PAAC, NRO_PEDIDO, PORC_GASTO,
				FLAG_GASTO, FLAG_MODIF, EQUIPO_REG, CUSER_ID, FECHA_REG, flag_migra, tipo_origen_externo_det, cantidad_unitaria,
				porcentaje, ID_KIT, tipo_calculo, flag_origen_det, ESTADO_ITEM_KIT,  STOCK)
		 SELECT distinct 2013, d.SEC_EJEC, d.CENTRO_COSTO, d.SECUENCIA, d.FASE_CUADRO, d.ITEM_SEC, d.TIPO_BIEN, d.GRUPO_BIEN, d.CLASE_BIEN, d.FAMILIA_BIEN,
				d.ITEM_BIEN, d.DESCRIP_SERVICIO, d.UNIDAD_MEDIDA, d.PRECIO_UNIT, d.CANT_01, d.CANT_02, d.CANT_03, d.CANT_04, d.CANT_05, d.CANT_06,
				d.CANT_07, d.CANT_08, d.CANT_09, d.CANT_10, d.CANT_11, d.CANT_12, d.CANT_TOTAL, d.MNTO_01, d.MNTO_02, d.MNTO_03, d.MNTO_04, d.MNTO_05,
				d.MNTO_06, d.MNTO_07, d.MNTO_08, d.MNTO_09, d.MNTO_10, d.MNTO_11, d.MNTO_12, d.MNTO_TOTAL, d.STOCK_ASIG, d.VALOR_STOCK, d.TIPO_IMPTO,
				d.TASA_IMPTO, d.FTE_IMPTO, d.VALOR_IMPTO, d.ESTADO, d.CANT_HIST, d.MNTO_HIST, d.NRO_CONSOLID, d.ESTADO_PAAC, d.NRO_PEDIDO, d.PORC_GASTO,
				d.FLAG_GASTO, d.FLAG_MODIF, d.EQUIPO_REG, d.CUSER_ID, d.FECHA_REG, d.flag_migra, d.tipo_origen_externo_det, d.cantidad_unitaria,
				d.porcentaje, d.ID_KIT, d.tipo_calculo, d.flag_origen_det, d.ESTADO_ITEM_KIT,  d.STOCK
		  FROM  tmp_cab C ,
			    SIG_CUADRO_NECESIDAD_DET D,
			    CATALOGO_BIEN_SERV cbs,
			    SI_PPR_KIT_ITEMS   spk
		  WHERE ( d.ANO_EJE = 2012 )AND D.FASE_CUADRO=1 and 
				( c.ANO_EJE = 2013  and C.EQUIPO_REG='MIGRA013' ) and
			    ( c.SEC_EJEC = d.SEC_EJEC			AND
			      c.CENTRO_COSTO = d.CENTRO_COSTO AND 
			      c.SECUENCIA = d.SECUENCIA		AND 
			      c.FASE_CUADRO = d.FASE_CUADRO   AND
			      c.SEC_EJEC= @secejec ) and
			    ( cbs.TIPO_BIEN =d.TIPO_BIEN  and
			      cbs.GRUPO_BIEN=d.GRUPO_BIEN and  
			      cbs.CLASE_BIEN=d.CLASE_BIEN and
			      cbs.FAMILIA_BIEN=d.FAMILIA_BIEN and
			      cbs.ITEM_BIEN=d.ITEM_BIEN and
			      cbs.ESTADO='A' ) and
			    ( cbs.CODIGO_ITEM=spk.ITEM_BIEN and spk.TIPO_CALCULO IN (4,5,6,8) and
			      spk.ANO_EJE= 2012 ) and
				  exists ( select 1 from SIG_SUB_FINALIDAD sgf ,
				  			SIG_PPR_KIT_ITEMS_EST spk
							where sgf.ANO_EJE= 2013 and 
							sgf.SUB_FINALIDAD=c.sub_finalidad  and 
							sgf.ESTADO='A'  AND 
							spk.ANO_EJE=sgf.ANO_EJE AND
							spk.SUB_FINALIDAD=sgf.SUB_FINALIDAD AND
							spk.ID_SUB_FINALIDAD= sgf.ID_SUB_FINALIDAD 
							AND	spk.ESTADO IN ('A','M','N') AND
						 	SPk.TIPO_CALCULO IN (4,5,6,8)) AND
				((EXISTS( SELECT X.ANO_EJE FROM SIG_CATALOGO_BIEN_SERV_PRECIO X
						WHERE
						X.ANO_EJE = 2013 AND
						X.SEC_EJEC = C.SEC_EJEC AND
						X.TIPO_BIEN = D.TIPO_BIEN AND
						X.grupo_bien = D.GRUPO_BIEN AND
						X.CLASE_BIEN = D.CLASE_BIEN AND
						X.FAMILIA_BIEN = D.FAMILIA_BIEN AND
						X.ITEM_BIEN = D.ITEM_BIEN) AND D.TIPO_BIEN ='B') OR
				(D.TIPO_BIEN = 'S')) AND
				
				EXISTS(	SELECT I.ano_eje
						FROM 
						SIG_CUA_NEC_DET_ID i,
						CATALOGO_BIEN_SERV cbs
						
						where
						i.ANO_EJE  = d.ano_eje AND
						
						d.SEC_EJEC = i.SEC_EJEC  AND
						d.CENTRO_COSTO = i.CENTRO_COSTO AND
						d.SECUENCIA    = i.SECUENCIA AND
						d.FASE_CUADRO  = i.FASE_CUADRO and
						cbs.TIPO_BIEN =i.TIPO_BIEN  and
						cbs.GRUPO_BIEN=i.GRUPO_BIEN and  
						cbs.CLASE_BIEN=i.CLASE_BIEN and
						cbs.FAMILIA_BIEN=i.FAMILIA_BIEN and
						cbs.ITEM_BIEN=i.ITEM_BIEN and
						cbs.ESTADO='A'  and
						i.TIPO_CALCULO IN (4,5,6,8) ) 			
END
GO


-- ----------------------------
-- procedure structure for USP_PRDETALLEDELETE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[USP_PRDETALLEDELETE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[USP_PRDETALLEDELETE]
GO

CREATE PROCEDURE [dbo].[USP_PRDETALLEDELETE] 
	@ano_eje numeric(6,0),
	@sec_ejec numeric(6,0),
	@centro_costo varchar(15),
	@tipo_bien char(1),
	@secconsolid numeric(5,0),
	@secresumen numeric(5,0),
	@secmeta numeric(5,0),
	@seccentrocosto numeric(5,0),
	@nro_consolid numeric(5,0),
	@cuser_id varchar(8)
AS
	DECLARE @total_paac_centro_costo numeric(5,0)
	DECLARE @total_paac_meta numeric(5,0)
	DECLARE @tot_01 numeric(14,2)
	DECLARE @tot_02 numeric(14,2)
	DECLARE @tot_03 numeric(14,2)
	DECLARE @tot_04 numeric(14,2)
	DECLARE @tot_05 numeric(14,2)
	DECLARE @tot_06 numeric(14,2)
	DECLARE @tot_07 numeric(14,2)
	DECLARE @tot_08 numeric(14,2)
	DECLARE @tot_09 numeric(14,2)
	DECLARE @tot_10 numeric(14,2)
	DECLARE @tot_11 numeric(14,2)
	DECLARE @tot_12 numeric(14,2)
	DECLARE @cantidad_tot numeric(14,2)
	DECLARE @valor_tot numeric(14,2)
	DECLARE @valor_moneda  numeric(14,2)
	DECLARE @valor_impto  numeric(14,2)
	DECLARE @valor_impto_moneda numeric(14,2)

	DECLARE @validar BIT
	DECLARE @fuente_financ_result VARCHAR(2)
	DECLARE @sec_func_result NUMERIC(5,0)
	DECLARE @clasificador_result VARCHAR(6)

	DECLARE @nro_pedido varchar(5)
	SELECT @NRO_PEDIDO = nro_pedido from sig_paac_centro_costo
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND @tipo_bien = tipo_bien AND nro_consolid = @nro_consolid
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  
	AND sec_meta = @secmeta AND sec_ctro_costo = @seccentrocosto 

	BEGIN TRAN

	DELETE FROM SIG_PAAC_CENTRO_COSTO_ANEXO
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND @tipo_bien = tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  
	AND sec_meta = @secmeta AND sec_ctro_costo = @seccentrocosto 

	DELETE FROM SIG_PAAC_CENTRO_COSTO
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND centro_costo = @centro_costo AND @tipo_bien = tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  
	AND sec_meta = @secmeta AND sec_ctro_costo = @seccentrocosto 

	SELECT @total_paac_centro_costo = COUNT(*)	
	FROM SIG_PAAC_CENTRO_COSTO
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND @tipo_bien = tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  
	AND sec_meta = @secmeta

	PRINT '@total_paac_centro_costo'
	PRINT @total_paac_centro_costo
	IF @total_paac_centro_costo = 0
		DELETE FROM SIG_PAAC_METAS
		WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
		AND @tipo_bien = tipo_bien 
		AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  
		AND sec_meta = @secmeta 
	PRINT 'ingreso a deletr sig_paac_metas'
	
	SELECT @total_paac_meta = count(*)
	FROM SIG_PAAC_METAS
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND @tipo_bien = tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen  

	IF @total_paac_meta = 0
		DELETE FROM SIG_PAAC_ITEM
		WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
		AND @tipo_bien = tipo_bien 
		AND sec_consolid = @secconsolid AND sec_resumen = @secresumen

	SELECT @tot_01 = SUM(isnull(mes_01,0)), @tot_02 = SUM(isnull(mes_02,0)), @tot_03 = SUM(isnull(mes_03,0)), 
	@tot_04 = SUM(isnull(mes_04,0)), @tot_05 = SUM(isnull(mes_05,0)), @tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)), 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)), 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen
	AND sec_meta = @secmeta AND sec_ctro_costo = @seccentrocosto

	print 'actualizacion'

	UPDATE sig_paac_metas 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @valor_tot, 
	valor_impto  = @valor_impto, valor_moneda = @valor_moneda, valor_impto_moneda = @valor_impto_moneda,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen
	AND sec_meta = @secmeta 

	print 'suma2'

			       
	SELECT @tot_01 = SUM(isnull(mes_01,0)), 
		@tot_02 = SUM(isnull(mes_02,0)), 
		@tot_03 = SUM(isnull(mes_03,0)), 
		@tot_04 = SUM(isnull(mes_04,0)), 
		@tot_05 = SUM(isnull(mes_05,0)), 
		@tot_06 = SUM(isnull(mes_06,0)), 
	@tot_07 = SUM(isnull(mes_07,0)), @tot_08 = SUM(isnull(mes_08,0)), @tot_09 = SUM(isnull(mes_09,0)) , 
	@tot_10 = SUM(isnull(mes_10,0)), @tot_11 = SUM(isnull(mes_11,0)), @tot_12 = SUM(isnull(mes_12,0)) , 
	@cantidad_tot = SUM(isnull(cantidad,0)), @valor_tot = SUM(isnull(valor,0)), @valor_impto  = SUM(isnull(valor_impto,0))
	FROM sig_paac_centro_costo 
	WHERE ano_eje = @ano_eje AND sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen
	AND sec_meta = @secmeta AND sec_ctro_costo = @seccentrocosto

	print 'actualizacion2'

	UPDATE sig_paac_item 
	SET 
	mes_01 = @tot_01 , mes_02 = @tot_02, mes_03  = @tot_03,  mes_04  = @tot_04,  
	mes_05  = @tot_05, mes_06  = @tot_06, mes_07  = @tot_07,  mes_08  = @tot_08,  
	mes_09  = @tot_09, mes_10  = @tot_10,  mes_11  = @tot_11,  mes_12  = @tot_12,  
	cantidad  = @cantidad_tot, valor  = @valor_tot, valor_moneda  = @valor_tot,
	fecha_reg = getdate(), cuser_id = @cuser_id
	WHERE ano_eje = @ano_eje AND  sec_ejec = @sec_ejec 
	AND tipo_consolid = 2 AND nro_consolid = @nro_consolid 
	AND tipo_generacion = 0 AND tipo_bien = @tipo_bien 
	AND sec_consolid = @secconsolid AND sec_resumen = @secresumen

	EXEC USP_PRTPProceso @ano_eje,  @sec_ejec, @centro_costo,  @tipo_bien, @nro_pedido, '3', @validar OUTPUT, @fuente_financ_result OUTPUT, @sec_func_result OUTPUT, @clasificador_result OUTPUT

COMMIT TRAN
   print 'OK'
RETURN 0

ERROR:
   print 'no OK'
   ROLLBACK TRAN
   RETURN 1
GO


-- ----------------------------
-- procedure structure for SP_SI_CARGA_EJEC_PEDIDO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_SI_CARGA_EJEC_PEDIDO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE[dbo].[SP_SI_CARGA_EJEC_PEDIDO]
GO

CREATE PROCEDURE [dbo].[SP_SI_CARGA_EJEC_PEDIDO]
    @P_ANO_EJE   	NUMERIC(4,0),
    @P_SEC_EJEC  	NUMERIC(6,0),
    @fecha_carga_inicio VARCHAR(10),
    @fecha_carga_fin 	VARCHAR(10),
    @usuario_n		varchar(30),
    @O_ERR_NUM   	NUMERIC(6,0) OUTPUT,
    @O_ERR_MSG   	VARCHAR(255) OUTPUT
AS
/******************************************************************************/
/*Descripción  : Inserta resumen de EJECUCIÓN de gastos por ejecutora         */
/*               en tablas finales SI_PEDIDO, SI_PEDIDO_DETA                  */
/*Input        : Todos los IN                                                 */
/*Output       : Todos los OUT                                                */
/*Creación     : 20/FEB/2009 - Sandro Martínez L. (En base a la version       */
/*               para Oracle, desarrollado por Nery Arroyo)                   */
/******************************************************************************/
DECLARE @fecha_carga_inicio_1         DATETIME
DECLARE @fecha_carga_fin_1            DATETIME   

DECLARE @LN_ID_SI_PEDIDO            NUMERIC(10,0)
DECLARE @LN_ID_SI_PEDIDO_DETA       NUMERIC(10,0)
DECLARE @LC_TIPO_BIEN               VARCHAR(1)
DECLARE @LC_TIPO_PEDIDO             CHAR(1)
DECLARE @LC_NRO_PEDIDO              CHAR(5)
DECLARE @LN_SEC_FUNC                NUMERIC(4,0)
DECLARE @LC_FINALIDAD               CHAR(5)
DECLARE @LC_D_FINALIDAD             VARCHAR(250)
DECLARE @LC_META                    VARCHAR(5)
DECLARE @LC_UNIDAD_MEDIDA_META      NUMERIC(3,0)
DECLARE @LC_D_UNIDAD_MEDIDA_META    VARCHAR(100)
DECLARE @LC_ITEM_CATALOGO           VARCHAR(20)
DECLARE @LC_NOMBRE_ITEM             VARCHAR(100)
DECLARE @LC_D_UNIDAD_MEDIDA_ITEM_BS VARCHAR(100)
DECLARE @LS_CENTRO_COSTO            VARCHAR(15)
DECLARE @LS_D_CENTRO_COSTO          VARCHAR(100)
DECLARE @LD_FECHA_PEDIDO            DATETIME
DECLARE @LD_FECHA_PECOSA            DATETIME
DECLARE @LI_MES_PEDIDO              INTEGER 
DECLARE @LS_MOTIVO_PEDIDO           VARCHAR(3000)
DECLARE @LS_EMPLEADO                VARCHAR(15)
DECLARE @LS_D_EMPLEADO              VARCHAR(100)
DECLARE @LC_TIPO_USO                CHAR(1)
DECLARE @LC_ESTADO                  CHAR(1)
DECLARE @LC_GRUPO_BIEN              CHAR(2)
DECLARE @LC_CLASE_BIEN              CHAR(2)
DECLARE @LC_FAMILIA_BIEN            CHAR(4)
DECLARE @LC_ITEM_BIEN               CHAR(4)
DECLARE @LN_UNIDAD_MEDIDA           NUMERIC(3,0)
DECLARE @LN_CANT_SOLICITADA         NUMERIC(20,6)
DECLARE @LN_CANT_APROBADA           NUMERIC(20,6)
DECLARE @LN_CANT_ATENDIDA           NUMERIC(20,6)
DECLARE @LN_@PRECIO_UNIT            NUMERIC(16,6)
DECLARE @LN_@VALOR_TOTAL            NUMERIC(16,2)
DECLARE @LC_ESTADO_PED              CHAR(1)
DECLARE @LS_CLASIFICADOR            VARCHAR(20)
DECLARE @LN_NRO_ORDEN               NUMERIC(7,0)
DECLARE @LN_NRO_CUADRO              NUMERIC(6,0)
DECLARE @LN_NRO_PECOSA              NUMERIC(5,0)

BEGIN  
    /*CAMBIA A TIPO DATE A LAS VARIABLES RECIBIDAS, PARA EL RANGO DE FECHAS */
    SET @fecha_carga_inicio_1 = Convert(DATETIME, @fecha_carga_inicio, 101)
    SET @fecha_carga_fin_1    = Convert(DATETIME, @fecha_carga_fin, 101)    

    /*ELIMINA DATA*/
    DELETE FROM SI_PEDIDO_DETA
    DELETE FROM SI_PEDIDO
      
    /*CORRELATIVO DE PEDIDO*/
    SELECT @LN_ID_SI_PEDIDO = MAX(SIP.ID_SI_PEDIDO) 
    FROM SI_PEDIDO SIP
    WHERE SIP.ANO_EJE=@P_ANO_EJE 
      AND SIP.SEC_EJEC=@P_SEC_EJEC

    IF @LN_ID_SI_PEDIDO IS NULL
      SET @LN_ID_SI_PEDIDO = 0

    /*CARGA DE PEDIDOS*/
    DECLARE C_1 CURSOR FOR
      SELECT P.TIPO_PEDIDO, 
             P.TIPO_BIEN, 
             P.NRO_PEDIDO, 
             P.CENTRO_COSTO,
             P.FECHA_PEDIDO, 
             P.MES_PEDIDO, 
             P.MOTIVO_PEDIDO, 
             P.SEC_FUNC, 
             P.EMPLEADO, 
             P.TIPO_USO, 
             P.ESTADO
      FROM SIG_PEDIDOS P 
      WHERE P.ANO_EJE = @P_ANO_EJE 
        AND P.SEC_EJEC = @P_SEC_EJEC
       AND (P.FECHA_PEDIDO >= @fecha_carga_inicio_1 
        AND P.FECHA_PEDIDO <= @fecha_carga_fin_1)

    OPEN C_1
    FETCH NEXT FROM C_1 
    INTO @LC_TIPO_PEDIDO, @LC_TIPO_BIEN, @LC_NRO_PEDIDO, 
	 @LS_CENTRO_COSTO, @LD_FECHA_PEDIDO, @LI_MES_PEDIDO, 
	 @LS_MOTIVO_PEDIDO, @LN_SEC_FUNC, @LS_EMPLEADO, 
	 @LC_TIPO_USO, @LC_ESTADO

    WHILE @@FETCH_STATUS = 0
    BEGIN

        /*CAMPOS DE META SEGUN AÑO, EJECUTORA Y SEC_FUNC*/
        SELECT @LC_META = META, 
               @LC_UNIDAD_MEDIDA_META = UNIDAD_MEDIDA,
               @LC_FINALIDAD = FINALIDAD
         FROM META
        WHERE ANO_EJE  = @P_ANO_EJE 
          AND SEC_EJEC = @P_SEC_EJEC
          AND SEC_FUNC = @LN_SEC_FUNC

         /*DESCRIPCIÓN DE UNIDAD DE MEDIDA DE META*/
        SELECT @LC_D_UNIDAD_MEDIDA_META = NOMBRE 
          FROM UNIDAD_MEDIDA
         WHERE UNIDAD_MEDIDA = @LC_UNIDAD_MEDIDA_META

         /*DESCRIPCIÓN DE FINALIDAD DE META*/
        SELECT @LC_D_FINALIDAD = NOMBRE
          FROM FINALIDAD
         WHERE ANO_EJE   = @P_ANO_EJE 
           AND FINALIDAD = @LC_FINALIDAD

         /*DESCRIPCIÓN DE CENTRO DE COSTO*/
        SELECT @LS_D_CENTRO_COSTO = NOMBRE_DEPEND
          FROM SIG_CENTRO_COSTO
         WHERE ANO_EJE   = @P_ANO_EJE 
           AND SEC_EJEC  = @P_SEC_EJEC
           AND CENTRO_COSTO = @LS_CENTRO_COSTO

         /*DESCRIPCIÓN DE CENTRO DE COSTO*/
        SELECT @LS_D_EMPLEADO = apellido_paterno + ' ' + apellido_materno + '' + nombres
          FROM SIG_PERSONAL
         WHERE SEC_EJEC  = @P_SEC_EJEC
           AND EMPLEADO = @LS_EMPLEADO

        SET @LN_ID_SI_PEDIDO = @LN_ID_SI_PEDIDO + 1

        INSERT INTO SI_PEDIDO
        (ANO_EJE, SEC_EJEC, ID_SI_PEDIDO, TIPO_PEDIDO, TIPO_BIEN,
         NRO_PEDIDO, CENTRO_COSTO, FECHA_PEDIDO, MES_PEDIDO, MOTIVO_PEDIDO,
         SEC_FUNC, FINALIDAD, D_FINALIDAD, META, UNIDAD_MEDIDA_META, 
	 D_UNIDAD_MEDIDA_META, EMPLEADO, TIPO_USO, ESTADO, D_CENTRO_COSTO, 
	 D_EMPLEADO, FECHA_CARGA_INICIO, FECHA_CARGA_FIN, 
	 FECHA_ENVIO, USUARIO_ENVIO)

        VALUES (@P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_PEDIDO, 
	@LC_TIPO_PEDIDO, @LC_TIPO_BIEN, @LC_NRO_PEDIDO, @LS_CENTRO_COSTO, 
	@LD_FECHA_PEDIDO, @LI_MES_PEDIDO, @LS_MOTIVO_PEDIDO,
        @LN_SEC_FUNC, @LC_FINALIDAD, @LC_D_FINALIDAD, @LC_META, 
	@LC_UNIDAD_MEDIDA_META, @LC_D_UNIDAD_MEDIDA_META,
        @LS_EMPLEADO, @LC_TIPO_USO, @LC_ESTADO, @LS_D_CENTRO_COSTO, 
	@LS_D_EMPLEADO, @fecha_carga_inicio_1, @fecha_carga_fin_1,
        getdate(), @usuario_n) 

        /*CURSOR DE DETALLE_ORDEN*/   
        DECLARE C_2 CURSOR FOR
             SELECT GRUPO_BIEN,
                    CLASE_BIEN,
                    FAMILIA_BIEN,
                    ITEM_BIEN,
                    UNIDAD_MEDIDA,
                    CANT_SOLICITADA,
                    CANT_APROBADA,
                    CANT_ATENDIDA,
                    PRECIO_UNIT,
                    VALOR_TOTAL,
                    ESTADO_PED,
                    CLASIFICADOR,
                    NRO_ORDEN,
                    NRO_CUADRO,
                    NRO_PECOSA,
                    FECHA_PECOSA
            FROM SIG_DETALLE_PEDIDOS 
            WHERE ANO_EJE     = @P_ANO_EJE 
              AND SEC_EJEC    = @P_SEC_EJEC 
              AND TIPO_BIEN   = @LC_TIPO_BIEN
              AND TIPO_PEDIDO = @LC_TIPO_PEDIDO 
              AND NRO_PEDIDO  = @LC_NRO_PEDIDO

        OPEN C_2
        FETCH NEXT FROM C_2 
        INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, 
	     @LC_ITEM_BIEN, @LN_UNIDAD_MEDIDA, @LN_CANT_SOLICITADA, 
	     @LN_CANT_APROBADA, @LN_CANT_ATENDIDA, @LN_@PRECIO_UNIT, 
             @LN_@VALOR_TOTAL, @LC_ESTADO_PED, @LS_CLASIFICADOR, 
	     @LN_NRO_ORDEN, @LN_NRO_CUADRO, @LN_NRO_PECOSA, 
	     @LD_FECHA_PECOSA

        WHILE @@FETCH_STATUS = 0
        BEGIN
            SET @LC_ITEM_CATALOGO = @LC_GRUPO_BIEN + @LC_CLASE_BIEN + @LC_FAMILIA_BIEN + @LC_ITEM_BIEN

            /*DESCRIPCIÓN DE ITEM CATÁLOGO B/S*/
   SELECT @LC_NOMBRE_ITEM = CAT.NOMBRE_ITEM
            FROM CATALOGO_BIEN_SERV_ORIGINAL CAT
            WHERE CAT.TIPO_BIEN    = @LC_TIPO_BIEN
              AND CAT.GRUPO_BIEN   = @LC_GRUPO_BIEN
              AND CAT.CLASE_BIEN   = @LC_CLASE_BIEN
              AND CAT.FAMILIA_BIEN = @LC_FAMILIA_BIEN
              AND CAT.ITEM_BIEN    = @LC_ITEM_BIEN 

            /*DESCRIPCIÓN DE UNIDAD DE MEDIDA DE ITEM CATÁLOGO B/S*/
            SELECT @LC_D_UNIDAD_MEDIDA_ITEM_BS = M.NOMBRE
            FROM UNIDAD_MEDIDA M
            WHERE M.UNIDAD_MEDIDA = @LN_UNIDAD_MEDIDA

            /*MAXIMO SECUENCIAL EN SI_PEDIDO_DETA*/
            SELECT @LN_ID_SI_PEDIDO_DETA = MAX(SIPD.ID_SI_PEDIDO_DETA)
            FROM SI_PEDIDO_DETA SIPD
            WHERE SIPD.ANO_EJE      = @P_ANO_EJE 
              AND SIPD.SEC_EJEC     = @P_SEC_EJEC
              AND SIPD.ID_SI_PEDIDO = @LN_ID_SI_PEDIDO

            IF @LN_ID_SI_PEDIDO_DETA IS NULL
                SET @LN_ID_SI_PEDIDO_DETA = 0

            SET @LN_ID_SI_PEDIDO_DETA = @LN_ID_SI_PEDIDO_DETA + 1
                          
            INSERT INTO SI_PEDIDO_DETA
            (ANO_EJE, SEC_EJEC, ID_SI_PEDIDO, ID_SI_PEDIDO_DETA,
            ITEM_CATALOGO, D_ITEM_CATALOGO, UNIDAD_MEDIDA_ITEM_BS, 
	    D_UNIDAD_MEDIDA_ITEM_BS, CLASIFICADOR, CANT_SOLICITADA, 
	    PRECIO_UNIT, VALOR_TOTAL, NRO_ORDEN, NRO_CUADRO, ESTADO_PED, 
	    CANT_APROBADA, CANT_ATENDIDA, NRO_PECOSA, FECHA_PECOSA, 
	    FECHA_CARGA_INICIO, FECHA_CARGA_FIN, FECHA_ENVIO, USUARIO_ENVIO)

            VALUES(@P_ANO_EJE, @P_SEC_EJEC, @LN_ID_SI_PEDIDO, @LN_ID_SI_PEDIDO_DETA,
            @LC_ITEM_CATALOGO, @LC_NOMBRE_ITEM, @LN_UNIDAD_MEDIDA, 
	    @LC_D_UNIDAD_MEDIDA_ITEM_BS, @LS_CLASIFICADOR, @LN_CANT_SOLICITADA, 
	    @LN_@PRECIO_UNIT, @LN_@VALOR_TOTAL, @LN_NRO_ORDEN, @LN_NRO_CUADRO, 
	    @LC_ESTADO_PED, @LN_CANT_APROBADA, @LN_CANT_ATENDIDA, 
            @LN_NRO_PECOSA, @LD_FECHA_PECOSA, @fecha_carga_inicio_1, 
	    @fecha_carga_fin_1, getdate(), @usuario_n)
             
            FETCH NEXT FROM C_2 
            INTO @LC_GRUPO_BIEN, @LC_CLASE_BIEN, @LC_FAMILIA_BIEN, 
		     @LC_ITEM_BIEN, @LN_UNIDAD_MEDIDA, @LN_CANT_SOLICITADA, 
		     @LN_CANT_APROBADA, @LN_CANT_ATENDIDA, @LN_@PRECIO_UNIT, 
                     @LN_@VALOR_TOTAL, @LC_ESTADO_PED, @LS_CLASIFICADOR, 
		     @LN_NRO_ORDEN, @LN_NRO_CUADRO, @LN_NRO_PECOSA, 
		     @LD_FECHA_PECOSA
         END
         CLOSE C_2
         DEALLOCATE C_2

         FETCH NEXT FROM C_1
         INTO     @LC_TIPO_PEDIDO, @LC_TIPO_BIEN, 
		  @LC_NRO_PEDIDO, @LS_CENTRO_COSTO, @LD_FECHA_PEDIDO, 
                  @LI_MES_PEDIDO, @LS_MOTIVO_PEDIDO, @LN_SEC_FUNC, 
		  @LS_EMPLEADO, @LC_TIPO_USO, @LC_ESTADO
     END
     CLOSE C_1
     DEALLOCATE C_1
END
GO


