CREATE TRIGGER [dbo].[tg_cuadro_adquisicion_del]
ON [dbo].[SIG_CUADRO_ADQUISICION]
WITH EXECUTE AS CALLER
FOR DELETE
AS
declare @vn_Ano_Eje            numeric(4),
        @vn_Sec_Ejec           numeric(6),
        @vid_tipo_trans        numeric(2),
        @vid_nro_origen        numeric(6),
        @vid_nro_trans         numeric(6),
        @vi_tipo_ppto          numeric(1),
        @vs_flag_proc          varchar(1),
        @vi_tipo_trans         numeric(2),
        @vs_Nro_Pedido         VARCHAR(7),
        @vd_Fecha_Transaccion  DATETIME,
        @vn_Secuencia          NUMERIC(6),
        @vs_CUser              VARCHAR(30),
        @vs_Equipo             VARCHAR(20)

begin

	--Recuperamos Valores		
	select @vn_Ano_Eje		= ano_eje  ,
	       @vn_Sec_Ejec	= sec_ejec ,
	       @vi_tipo_ppto 	= tipo_ppto,
	       @vs_flag_proc    = flag_proceso
	from deleted


	if @vi_tipo_ppto = 1 and @vs_flag_proc = '0'
		select @vi_tipo_trans = 5

	if @vi_tipo_ppto = 2 and @vs_flag_proc = '0'
		select @vi_tipo_trans = 16

	if (@vs_flag_proc = '1' or @vs_flag_proc = '2' or @vs_flag_proc = '3' or @vs_flag_proc = '4')		
		select @vi_tipo_trans = 15
	

	select @vn_Ano_Eje		 = B.ano_eje,
	       @vn_Sec_Ejec	 = B.sec_ejec,
	       @vid_tipo_trans   = A.tipo_transaccion,
	       @vid_nro_origen   = A.nro_origen,
	       @vid_nro_trans    = A.nro_transaccion
	from  deleted B,
	      sig_seguimiento A
	where A.ano_eje 	= B.ano_eje and	
	      A.sec_ejec	= B.sec_ejec and	
	      A.tipo_bien	= B.tipo_bien and
	      A.nro_transaccion	= B.sec_cuadro and
	      A.tipo_transaccion = @vi_tipo_trans	


    -- Eliminando la tabla de estados del Seguimiento
	delete from sig_seguimiento_estado
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vid_tipo_trans and
	      nro_origen 	= @vid_nro_origen 

	--Eliminando la tabla de secuencias de una transacción
	delete from sig_seguimiento_secuencia
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vid_tipo_trans and
	      nro_origen 	= @vid_nro_origen 


	--Eliminando la tabla de estados del Seguimiento
	delete from sig_seguimiento	
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vid_tipo_trans and
	      nro_origen 	= @vid_nro_origen 


   -- datos de sesión
   IF OBJECT_ID ('TEMPDB..#sig_sesion') IS NOT NULL
      SELECT @vs_CUser=  CUSER_ID,
             @vs_Equipo= EQUIPO_REG
        FROM #SIG_SESION
   ELSE
      SELECT @vs_CUser=  CUSER_MOD,
             @vs_Equipo= EQUIPO_MOD
        FROM DELETED


    -- auditoría
    IF @vi_Tipo_Trans = 15
       SELECT @vs_Nro_Pedido=        CONVERT( VARCHAR(6), NRO_CUADRO),
              @vd_Fecha_Transaccion= FECHA_NRO_CUADRO
         FROM DELETED
    ELSE
       SELECT @vs_Nro_Pedido=        CONVERT( VARCHAR(7), NRO_REQUER),
              @vd_Fecha_Transaccion= FECHA_CUADRO
         FROM DELETED

    SELECT @vn_Secuencia= COALESCE(MAX(SECUENCIA),0) + 1
      FROM SIG_AUDITORIA
     WHERE ANO_EJE         = @vn_Ano_Eje   AND
           SEC_EJEC        = @vn_Sec_Ejec  AND
           TIPO_MOVIMIENTO = 'D'

    INSERT INTO SIG_AUDITORIA (
           ANO_EJE,             SEC_EJEC,               TIPO_MOVIMIENTO,      SECUENCIA,             SOLICITANTE,
           NRO_TRANSACCION,     FECHA_TRANSACCION,      ESTADO_TRANSACCION,   NRO_PEDIDO,            CENTRO_COSTO,
           FECHA_REG,           CUSER_ID,               EQUIPO_REG,           TIPO_PPTO,
           TIPO_TRANSACCION,    TIPO_PEDIDO)
	SELECT @vn_Ano_Eje,         @vn_Sec_Ejec,           'D',                  @vn_Secuencia,         D.EMPLEADO, 
		   D.SEC_CUADRO,        @vd_Fecha_Transaccion,  D.ESTADO,             @vs_Nro_Pedido,        D.CENTRO_COSTO,
           GETDATE(),           @vs_CUser,              @vs_Equipo,           D.TIPO_PPTO,
           @vi_Tipo_Trans,      CONVERT( VARCHAR, @vi_Tipo_Trans)
      FROM DELETED D


end
GO

CREATE TRIGGER [dbo].[TG_CUADRO_ADQUISICION_PAO_UPD]
ON [dbo].[SIG_CUADRO_ADQUISICION]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
DECLARE

@LN_vid_ano         NUMERIC(4),
@LN_vid_ejecutora   NUMERIC(6),
@LN_vid_tipo_trans  NUMERIC(2),
@LN_vid_tipo_trans_nuevo  NUMERIC(2),
@LN_vid_nro_origen  NUMERIC(6),
@LN_vid_nro_trans   NUMERIC(6),
@LN_vid_sec_cuadro  NUMERIC(6),
@LN_vis_tipo_bien   VARCHAR(1),
@LN_vis_tipo_ped    VARCHAR(1),
@LN_vis_nro_ped      VARCHAR(5),
@LN_vis_est_trans   VARCHAR(1),
@ls_cur_estado_ant  VARCHAR(1),
@LN_vii_nro_cuadro  NUMERIC(6),
@LN_vii_nro_cons_paac NUMERIC(7),
@LN_vid_tipo_ppto    NUMERIC(1),
@LN_vid_nro_destino    NUMERIC(6),
@LN_vis_tipo_consolid VARCHAR(1),
@LN_TOTAL              NUMERIC(6),
@ln_origen             NUMERIC(6),
@LN_flag_proyectado  VARCHAR(1),
@LN_cuenta_secuencia NUMERIC(2),
@vis_cuser_id	 VARCHAR(30),
@vis_equipo_reg	 VARCHAR(20),
@ls_cur_centro_costo    VARCHAR(20),
@ls_cur_empleado        VARCHAR(20),
@ll_cur_nro_requer      NUMERIC(10),
@ldt_cur_fecha_cuadro   datetime

BEGIN

SELECT
@LN_vid_ano           =  ano_eje,
@LN_vid_ejecutora     =  sec_ejec,
@LN_vis_tipo_bien     =  tipo_bien,
@LN_vid_sec_cuadro    =  sec_cuadro,
@LN_vis_est_trans     =  estado,
@LN_vii_nro_cuadro    =  nro_cuadro,
@LN_vii_nro_cons_paac =  nro_cons_paac,
@LN_vid_tipo_ppto     =  tipo_ppto,
@LN_flag_proyectado   =  flag_proyectado,
@vis_cuser_id           = CUSER_MOD,
@vis_equipo_reg         = EQUIPO_MOD,
@ls_cur_centro_costo    = centro_costo,
@ls_cur_empleado        = empleado,
@ll_cur_nro_requer      = nro_requer,
@ldt_cur_fecha_cuadro   = fecha_cuadro
FROM INSERTED

SELECT
@ls_cur_estado_ant  = ESTADO
FROM    DELETED

/*si el estado, no ha cambiado, no hacer nada*/
IF @LN_vis_est_trans = @ls_cur_estado_ant
    BEGIN
        RETURN 
    END

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

IF update(nro_cons_paac)
BEGIN
    IF (@LN_vii_nro_cons_paac > 0 )AND (  @LN_vii_nro_cuadro <= 0 or @LN_vii_nro_cuadro is null)
    BEGIN
       --seteo de transaccion por generacion de nro consolidado de pao
       SELECT @LN_vid_tipo_trans_nuevo = 4 --pao modificador
    
        IF @LN_vid_tipo_ppto = 1
            BEGIN
                --pedidos consolidados
                SELECT @LN_vid_tipo_trans = 5
                --valor de pao modificado
                SELECT @LN_vis_tipo_consolid  = '2'
            END
    
        IF @LN_vid_tipo_ppto = 2
            BEGIN
                --compras por encargo
                SELECT @LN_vid_tipo_trans = 16
                --valor de pao por encargos
                SELECT @LN_vis_tipo_consolid = '3'
            END
       
       SELECT 
       @LN_TOTAL  = COUNT(1)
       FROM     sig_seguimiento
       WHERE ano_eje   = @LN_vid_ano  and
       sec_ejec        = @LN_vid_ejecutora and
       tipo_bien       = @LN_vis_tipo_bien and
       nro_transaccion = @LN_vid_sec_cuadro and
       tipo_transaccion = @LN_vid_tipo_trans 
       
       IF @LN_TOTAL = 0 
            BEGIN
            --CORRELATIVO
                SELECT  
                @ln_origen = (COALESCE(MAX(B.nro_origen),0) + 1)
                FROM sig_seguimiento B
                WHERE   B.ano_eje   = @LN_vid_ano    
                AND     B.sec_ejec   = @LN_vid_ejecutora  
                AND     B.tipo_transaccion = @LN_vid_tipo_trans 
                      
                  --INSERTA CABECERA
                  INSERT INTO sig_seguimiento(
                  ano_eje,
                  sec_ejec,
                  tipo_transaccion,
                  nro_origen,
                  centro_costo,
                  solicitante,
                  tipo_ppto,
                  tipo_bien,
                  tipo_pedido,
                  nro_transaccion,
                  nro_pedido,
                  fecha_transaccion,
                  estado_transaccion,
                  fecha_reg,
                  cuser_id,
                  equipo_reg
                  )
                  VALUES ( 
                    @LN_vid_ano,
                    @LN_vid_ejecutora,
                    @LN_vid_tipo_trans ,
                    @ln_origen,
                    @ls_cur_centro_costo,
                    @ls_cur_empleado,
                    @LN_vid_tipo_ppto,
                    @LN_vis_tipo_bien,
                    '0',
                    @LN_vid_sec_cuadro,
                    LTRIM(RTRIM(CONVERT(VARCHAR(20), @ll_cur_nro_requer))),
                    @ldt_cur_fecha_cuadro,
                    @LN_vis_est_trans,
                    GETDATE(),
                    @vis_cuser_id,
                    @vis_equipo_reg
                  )
             END

       -- Recuperar argumentos
        --lee el que acabas de inserta o el que ya existe
        IF (
            SELECT 1
            FROM sig_seguimiento
            WHERE  
            ano_eje          = @LN_vid_ano         and
            sec_ejec         = @LN_vid_ejecutora   and
            tipo_pedido      = @LN_vis_tipo_consolid   and
            nro_transaccion  = @LN_vii_nro_cons_paac and
            tipo_transaccion = @LN_vid_tipo_trans_nuevo
            ) > 0
            BEGIN
                SELECT @LN_vid_nro_origen = nro_origen 
                FROM sig_seguimiento
                WHERE  
                ano_eje          = @LN_vid_ano         and
                sec_ejec         = @LN_vid_ejecutora   and
                tipo_pedido      = @LN_vis_tipo_consolid   and
                nro_transaccion  = @LN_vii_nro_cons_paac and
                tipo_transaccion = @LN_vid_tipo_trans_nuevo
            END
        ELSE
            BEGIN
                SELECT @LN_vid_nro_origen = 0
            END

        IF (
            SELECT 1
            FROM sig_seguimiento
            WHERE  ano_eje   = @LN_vid_ano         AND
            sec_ejec         = @LN_vid_ejecutora   AND
            tipo_bien        = @LN_vis_tipo_bien   AND
            nro_transaccion  = @LN_vid_sec_cuadro  AND
            tipo_transaccion = @LN_vid_tipo_trans
            ) > 0
            BEGIN       
                SELECT @LN_vid_nro_destino = nro_origen 
                FROM sig_seguimiento
                WHERE  ano_eje   = @LN_vid_ano         AND
                sec_ejec         = @LN_vid_ejecutora   AND
                tipo_bien        = @LN_vis_tipo_bien   AND
                nro_transaccion  = @LN_vid_sec_cuadro  AND
                tipo_transaccion = @LN_vid_tipo_trans
            END
        ELSE
            BEGIN
                SELECT @LN_vid_nro_destino = 0
            END

      -- Inserta en tabla secuencia
      IF (@LN_vid_nro_origen > 0 ) AND (@LN_vid_nro_destino > 0 ) AND (@LN_vid_nro_destino > 0)
        BEGIN

          SELECT LN_cuenta_secuencia = count(1) 
          FROM sig_seguimiento_secuencia
          WHERE
          ano_eje                   = @LN_vid_ano         AND
          sec_ejec                  = @LN_vid_ejecutora   AND
          tipo_transaccion          = @LN_vid_tipo_trans_nuevo and
          nro_origen                = @LN_vid_nro_origen and
          tipo_transaccion_destino = @LN_vid_tipo_trans and
          nro_destino               = @LN_vid_nro_destino

            IF @LN_cuenta_secuencia = 0 
                BEGIN
                  INSERT INTO sig_seguimiento_secuencia
                  (ano_eje,
                  sec_ejec,
                  tipo_transaccion,
                  nro_origen,
                  tipo_transaccion_destino,
                  nro_destino )
                  VALUES
                  (@LN_vid_ano,
                  @LN_vid_ejecutora,
                  @LN_vid_tipo_trans_nuevo,
                  @LN_vid_nro_origen,
                  @LN_vid_tipo_trans,
                  @LN_vid_nro_destino)
              END
        END
    END
END

END
GO

CREATE TRIGGER [dbo].[tg_cuadro_adquisicion_seg_upd]
ON [dbo].[SIG_CUADRO_ADQUISICION]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
	@vid_ejecutora   numeric(6),
	@vid_tipo_trans  numeric(2),
	@vid_nro_origen  numeric(6),
	@vid_nro_trans   numeric(6),
	@vid_sec_cuadro  numeric(6),
	@vis_tipo_bien   char(1),
	@vis_tipo_ped    char(1),
	@vis_nro_ped	 char(5),
	@vis_est_trans 	 char(1),
    @ls_estado_ori  varchar(1),
	@vii_nro_cuadro  numeric(6),
	@vii_nro_cons_paac numeric(6),
	@vi_tipo_ppto numeric(1),
	@vi_ano            numeric(4),
	@vi_ejecutora      numeric(6),
	@vi_tipo_trans      numeric(2),
	@vi_tipo_trans_ant  numeric(2),
	@vi_nro_origen     numeric(6),
	@vi_nro_destino    numeric(6),
	@vi_nro_trans      numeric(6),
	@vi_sec_cuadro     numeric(6),
	@vs_tipo_bien      char(1),
	@vs_tipo_ped       char(1),
	@vs_nro_ped	    char(5),
	@vs_est_trans 	    char(1),
	@vi_nro_cuadro_ant  numeric(6),
	@vi_nro_cuadro_nue  numeric(6),
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)	

select 
@vid_ano	 = ano_eje,
@vid_ejecutora	 = sec_ejec,
@vis_tipo_bien   =  tipo_bien,
@vid_sec_cuadro	 =  sec_cuadro,
@vis_est_trans   =  estado,
@vii_nro_cuadro     =  nro_cuadro,
@vii_nro_cons_paac  =  nro_cons_paac,
@vi_tipo_ppto       =  tipo_ppto,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from  inserted

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

update sig_cuadro_adquisicion 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
ano_eje     = @vid_ano       and
sec_ejec    = @vid_ejecutora and	 
tipo_bien   = @vis_tipo_bien AND
sec_cuadro = @vid_sec_cuadro 

/*obtengo el estado original*/
SELECT  @ls_estado_ori  = ESTADO
FROM    DELETED

/*si no ha cambiado el estado, salgo*/
IF @ls_estado_ori = @vis_est_trans
BEGIN
    RETURN
END

if update(estado)	
begin
	if ( (@vii_nro_cuadro is null ) or ( @vii_nro_cuadro <= 0 )  ) and ( @vii_nro_cons_paac is null or @vii_nro_cons_paac <= 0 )
	begin

		if @vi_tipo_ppto = 1
  		   begin
			--pedidos consolidados
			select @vid_tipo_trans = 5					
		   end
		
		if @vi_tipo_ppto = 2
	  	   begin
			--compras por encargo
			select @vid_tipo_trans = 16					
		   end	

		if not exists 
			(select *
		 	from sig_seguimiento
		 	where ano_eje         = @vid_ano 	and
		       	sec_ejec        = @vid_ejecutora and
		       	tipo_bien       = @vis_tipo_bien and
		       	nro_transaccion = @vid_sec_cuadro and
		       	tipo_transaccion = @vid_tipo_trans )
	
		begin
			--insertar cabecera de seguimiento

			-- Inserta sig_Seguimiento
			insert into sig_seguimiento(
			  ano_eje,
			  sec_ejec,
			  tipo_transaccion,
			  nro_origen,	
			  centro_costo,	
			  solicitante,		
			  tipo_ppto,
			  tipo_bien,	
			  tipo_pedido,		
			  nro_transaccion,
			  nro_pedido,
			  fecha_transaccion,	
			  estado_transaccion,
			  fecha_reg,
			  cuser_id,
			  equipo_reg
			  )
			select A.ano_eje,
			       A.sec_ejec,
			       @vid_tipo_trans ,
			       (select (isnull(max(B.nro_origen),0)+1)
				from sig_seguimiento B
				where(B.ano_eje 	 = @vid_ano	   ) and
				     (B.sec_ejec 	 = @vid_ejecutora  ) and
				     (B.tipo_transaccion = @vid_tipo_trans  )),				
				A.centro_costo,
				A.empleado,
				A.tipo_ppto,
				A.tipo_bien,
				'0',
				A.sec_cuadro,
				convert(varchar(6),A.nro_requer),
				A.fecha_nro_cuadro,	
				A.estado,
				getdate(),
				@vis_cuser_id,
				@vis_equipo_reg
			from inserted A		

		end

		-- Recuperar argumentos 
		--lee el que acabnas de insertra o el que ya existe	
		select @vid_nro_origen = nro_origen
		from sig_seguimiento
		where  ano_eje       	= @vid_ano         and
		       sec_ejec      	= @vid_ejecutora   and	 
		       tipo_bien	= @vis_tipo_bien   and
		       nro_transaccion	= @vid_sec_cuadro and
		       tipo_transaccion = @vid_tipo_trans 	
	
		-- Actualiza el seguimiento
		update sig_seguimiento 
		set estado_transaccion  = @vis_est_trans
		where  
		ano_eje       	= @vid_ano         and
	       	sec_ejec      	= @vid_ejecutora   and	 
		tipo_transaccion = @vid_tipo_trans  and
	       	nro_origen       = @vid_nro_origen 		       			

		insert into sig_seguimiento_estado
		( 
		ANO_EJE,
		SEC_EJEC,
		TIPO_TRANSACCION,
		NRO_ORIGEN,
		SEC_ESTADO,
		FECHA_ESTADO,
		ESTADO_SEGUIMIENTO,
		FECHA_REG,
		CUSER_ID ,
		EQUIPO_REG
		)
		select A.ano_eje,
	       	A.sec_ejec,
	       	@vid_tipo_trans,
	       	@vid_nro_origen,
	       	(select (isnull(max(C.sec_estado),0)+1)
		from sig_seguimiento_estado C
		where(C.ano_eje 	 = @vid_ano	   ) and
		     (C.sec_ejec 	 = @vid_ejecutora  ) and
		     (C.tipo_transaccion = @vid_tipo_trans ) and
		     (C.nro_origen	 = @vid_nro_origen)),	   
		getdate(),
		B.estado,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg			    
		from deleted A
		inner join inserted B
		on A.ano_eje 		= B.ano_eje    and
		A.sec_ejec 		= B.sec_ejec   and
	   	A.tipo_bien		= B.tipo_bien  and
	   	A.sec_cuadro		= B.sec_cuadro and
	   	A.estado <> B.estado

		--sp_help sig_seguimiento_estado
	
	end

	if ( @vii_nro_cuadro > 0  ) and ( @vii_nro_cons_paac is null or @vii_nro_cons_paac <= 0 )
	--cuadro de adquisicion - valor fijo
	begin
	select @vid_tipo_trans  = 15
	if not exists 
		(select *
		 from sig_seguimiento
		 where ano_eje         = @vid_ano 	and
		       sec_ejec        = @vid_ejecutora and
		       tipo_bien       = @vis_tipo_bien and
		       nro_transaccion = @vid_sec_cuadro and
		       tipo_transaccion = @vid_tipo_trans )
		begin
		-- Inserta Seguimiento
		insert into sig_seguimiento(
			  ano_eje,
			  sec_ejec,
			  tipo_transaccion,
			  nro_origen,	
			  centro_costo,	
			  solicitante,		
			  tipo_ppto,
			  tipo_bien,	
			  tipo_pedido,		
			  nro_transaccion,
			  nro_pedido,
			  fecha_transaccion,	
			  estado_transaccion,
			  fecha_reg,
			  cuser_id,
			  equipo_reg
			  )
			select A.ano_eje,
			       A.sec_ejec,
			       @vid_tipo_trans,
			       (select (isnull(max(B.nro_origen),0)+1)
				from sig_seguimiento B
				where(B.ano_eje 	 = @vid_ano	   ) and
				     (B.sec_ejec 	 = @vid_ejecutora  ) and
				     (B.tipo_transaccion = @vid_tipo_trans )),				
				A.centro_costo,
				A.empleado,
				A.tipo_ppto,
				A.tipo_bien,
				'0',
				A.sec_cuadro,
				convert(varchar(6),A.nro_cuadro),
				A.fecha_nro_cuadro,	
				A.estado,
				getdate(),
				@vis_cuser_id,
				@vis_equipo_reg
			from inserted A	

		end 		
		
	-- Recuperar argumentos 
	--el nuevo oriegen o el que ya existeia para cuadro de adq.
	select @vid_nro_origen = nro_origen
	from sig_seguimiento
	where  ano_eje       	= @vid_ano         and
	       sec_ejec      	= @vid_ejecutora   and	 
	       tipo_bien	= @vis_tipo_bien   and
	       nro_transaccion	= @vid_sec_cuadro and
	       tipo_transaccion = @vid_tipo_trans

	update sig_seguimiento 
	set estado_transaccion  = @vis_est_trans
	where  ano_eje       	= @vid_ano         and
	       sec_ejec      	= @vid_ejecutora   and	 
	       tipo_transaccion = @vid_tipo_trans  and
	       nro_origen       = @vid_nro_origen 		       			

	insert into sig_seguimiento_estado
	( 
	ANO_EJE,
	SEC_EJEC,
	TIPO_TRANSACCION,
	NRO_ORIGEN,
	SEC_ESTADO,
	FECHA_ESTADO,
	ESTADO_SEGUIMIENTO,
	FECHA_REG,
	CUSER_ID ,
	EQUIPO_REG
	)
	select A.ano_eje,
	       A.sec_ejec,
	       @vid_tipo_trans,
	       @vid_nro_origen,
	       (select (isnull(max(C.sec_estado),0)+1)
		from sig_seguimiento_estado C
		where(C.ano_eje 	 = @vid_ano	   ) and
		     (C.sec_ejec 	 = @vid_ejecutora  ) and
		     (C.tipo_transaccion = @vid_tipo_trans ) and
		     (C.nro_origen	 = @vid_nro_origen)),	   
		getdate(),
		B.estado,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg			    
	from deleted A
	inner join inserted B
	on A.ano_eje 		= B.ano_eje    and
	   A.sec_ejec 		= B.sec_ejec   and
	   A.tipo_bien		= B.tipo_bien  and
	   A.sec_cuadro		= B.sec_cuadro and
	   A.estado <> B.estado
	
	end

--cruce	
	
	select @vi_tipo_ppto = tipo_ppto
	from inserted
	
	if @vi_tipo_ppto = 1
  	   begin
		--pedidos consolidados
		select @vi_tipo_trans_ant = 5					
	   end
		
	if @vi_tipo_ppto = 2
  	   begin
		--compras por encargo
		select @vi_tipo_trans_ant = 16					
	   end	

       	if update(nro_cuadro)		
	begin
	
		select @vi_nro_cuadro_ant = nro_cuadro
		from deleted
	
		select @vi_nro_cuadro_nue = nro_cuadro
		from inserted

		if (@vi_nro_cuadro_nue is null) or (@vi_nro_cuadro_nue <= 0 ) and (@vi_nro_cuadro_ant > 0 )
		begin
			--se elimina o borra el campo nro_cuadro
			---lee el tipo trans cuadro de adquisiscion
			select @vi_tipo_trans = 15
			
			select @vi_ano	 = A.ano_eje,
		        @vi_ejecutora	 = A.sec_ejec,
			@vs_tipo_bien    = A.tipo_bien,
		       	@vi_sec_cuadro	 = A.sec_cuadro	       
			from  inserted A

			select @vi_nro_origen = nro_origen
			from sig_seguimiento
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_bien	= @vs_tipo_bien   and
			       nro_transaccion	= @vi_sec_cuadro  and
			       tipo_transaccion = @vi_tipo_trans

			delete from sig_seguimiento_estado
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_transaccion = @vi_tipo_trans  and
			       nro_origen       = @vi_nro_origen

			delete from sig_seguimiento_secuencia
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_transaccion = @vi_tipo_trans  and
			       nro_origen       = @vi_nro_origen
					
			delete from sig_seguimiento
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_transaccion = @vi_tipo_trans  and
			       nro_origen       = @vi_nro_origen

		end

		if (@vi_nro_cuadro_ant is null) or (@vi_nro_cuadro_ant <= 0 ) and (@vi_nro_cuadro_nue > 0 )

		begin
			--se le asigna al campo nro_cuadro un valor
			select @vi_tipo_trans = 15

			select @vi_ano	 = A.ano_eje,
		        @vi_ejecutora	 = A.sec_ejec,
			@vs_tipo_bien    = A.tipo_bien,
		       	@vi_sec_cuadro	 = A.sec_cuadro	       
			from  inserted A
	
	
			if not exists 
				(select *
				from sig_seguimiento
				where ano_eje         = @vi_ano 	and
			       	sec_ejec        = @vi_ejecutora  and
			       	tipo_bien       = @vs_tipo_bien  and
			       	nro_transaccion = @vi_sec_cuadro and
				tipo_transaccion= @vi_tipo_trans )
			begin
				insert into sig_seguimiento
				(
				  ano_eje,
				  sec_ejec,
				  tipo_transaccion,
				  nro_origen,	
				  centro_costo,
				  solicitante,		
				  tipo_ppto,
				  tipo_bien,	
				  tipo_pedido,		
				  nro_transaccion,
				  nro_pedido,
				  fecha_transaccion,	
				  estado_transaccion,
				  fecha_reg,
				  cuser_id,
				  equipo_reg
				  )
				select A.ano_eje,
			       	A.sec_ejec,
		       		@vi_tipo_trans,
			       (select (isnull(max(B.nro_origen),0)+1)
				from sig_seguimiento B
				where(B.ano_eje 	 = @vi_ano	   ) and
				     (B.sec_ejec 	 = @vi_ejecutora  ) and
				     (B.tipo_transaccion = @vi_tipo_trans  )),				
				A.centro_costo,
				A.empleado,
				A.tipo_ppto,
				A.tipo_bien,
				'0',
				A.sec_cuadro,
				convert(varchar(6),A.nro_cuadro),
				A.fecha_nro_cuadro,	
				A.estado,
				getdate(),
				@vis_cuser_id,
				@vis_equipo_reg
				from inserted A	

			end 		
		
			-- Recuperar argumentos 
			select @vi_nro_origen = nro_origen
			from sig_seguimiento
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_bien	= @vs_tipo_bien   and
			       nro_transaccion	= @vi_sec_cuadro  and
			       tipo_transaccion = @vi_tipo_trans

			select @vi_nro_destino = nro_origen
			from sig_seguimiento
			where  ano_eje       	= @vi_ano         and
			       sec_ejec      	= @vi_ejecutora   and	 
			       tipo_bien	= @vs_tipo_bien   and
			       nro_transaccion	= @vi_sec_cuadro  and
			       tipo_transaccion = @vi_tipo_trans_ant
		
		
			-- Inserta en tabla secuencia
			if (@vi_nro_origen is not null ) and (@vi_nro_destino is not null)
			begin
				insert into sig_seguimiento_secuencia
				(ano_eje,
				 sec_ejec,
				 tipo_transaccion, 
				 nro_origen,
				 tipo_transaccion_destino,
				 nro_destino )
				values	
				(@vi_ano,
				 @vi_ejecutora,
				 @vi_tipo_trans, 
				 @vi_nro_origen,
				 @vi_tipo_trans_ant,
				 @vi_nro_destino)
			end 

	       			
			-- Inserta en tabla estado
			insert into sig_seguimiento_estado
			select A.ano_eje,
		       	A.sec_ejec,
			@vi_tipo_trans,
	       		@vi_nro_origen,
	       		(select (isnull(max(C.sec_estado),0)+1)
			from sig_seguimiento_estado C
			where
			(C.ano_eje 	    = @vi_ano	  ) and
		     	(C.sec_ejec 	    = @vi_ejecutora  ) and
		     	(C.tipo_transaccion = @vi_tipo_trans ) and
		     	(C.nro_origen	    = @vi_nro_origen)),	   
			getdate(),
			A.estado,
			getdate(),
			@vis_cuser_id,
			@vis_equipo_reg			    
			from inserted A
	
		end
	end 
end
GO

CREATE TRIGGER [dbo].[TG_PED_CONSOLIDADO_INS]
ON [dbo].[SIG_CUADRO_ADQUISICION]
WITH EXECUTE AS CALLER
FOR INSERT
AS
DECLARE
@LN_vid_ano           NUMERIC(4),
@LN_vid_sec_ejec      NUMERIC(6),
@LN_vid_ejecutora     NUMERIC(6),
@LN_vid_nro_origen    NUMERIC(6),
@LN_vid_nro_destino   NUMERIC(6),
@ll_cur_sec_cuadro    NUMERIC(10),
@LN_vid_tipo_trans    NUMERIC(2),
@LN_vid_tipo_trans_ant NUMERIC(2),
@LS_vis_tipo_bien      VARCHAR(1),
@LN_vi_tipo_ppto      NUMERIC(1),
@LS_vis_tipo_ped      VARCHAR(1),
@LS_vis_nro_ped       VARCHAR(5),
@LS_vis_est_trans     VARCHAR(1),
@LN_aux               NUMERIC(2),
@LN_vi_nro_encargo    NUMERIC(6),
@LN_TOTAL             NUMERIC(6),
@LN_vii_nro_cuadro    NUMERIC(6),
@LN_vii_nro_cons_paac NUMERIC(6),
@LS_FLAG_PROCESO      VARCHAR(1),
@ln_origen            NUMERIC(6),
@ln_secuencia         NUMERIC(2),
@ll_cur_nro_requer      NUMERIC(10),

@ls_cuser_id            VARCHAR(30),
@ls_equipo_reg          VARCHAR(20),
@ls_cur_centro_costo    VARCHAR(20),
@ls_cur_empleado        VARCHAR(20),
@ldt_cur_fecha_cuadro   DATETIME

BEGIN

SELECT
@LN_vid_ano        = ano_eje,
@LN_vid_sec_ejec   = sec_ejec,
@LN_vi_tipo_ppto   = tipo_ppto,
@LN_vi_nro_encargo = nro_encargo,
@LS_vis_tipo_bien  = tipo_bien,
@LN_vii_nro_cuadro = nro_cuadro,
@LN_vii_nro_cons_paac = nro_cons_paac,
@LS_vis_est_trans   = estado,
@LS_FLAG_PROCESO    = FLAG_PROCESO,
@ls_cuser_id        = CUSER_ID,
@ls_equipo_reg      = EQUIPO_REG,

@ldt_cur_fecha_cuadro   = fecha_cuadro,
@ls_cur_centro_costo    = centro_costo,
@ls_cur_empleado        = empleado,
@ll_cur_sec_cuadro      = sec_cuadro,
@ll_cur_nro_requer      = nro_requer

FROM INSERTED

IF @LS_vis_tipo_bien = 'B' OR @LS_vis_tipo_bien ='S'
BEGIN
   -- Insertar  seguimiento
   IF @LN_vi_tipo_ppto = 1
   BEGIN

      IF @LS_FLAG_PROCESO = 0
      BEGIN
            SELECT  @LN_vid_tipo_trans = 5

    
            SELECT @ln_origen = COALESCE(MAX(nro_origen), 0) + 1
              FROM sig_seguimiento 
             WHERE ano_eje          = @LN_vid_ano  AND
                   sec_ejec         = @LN_vid_sec_ejec AND
                   tipo_transaccion = @LN_vid_tipo_trans
      
              INSERT INTO sig_seguimiento(
                          ano_eje,
                          sec_ejec,
                          tipo_transaccion,
                          nro_origen,
                          fecha_transaccion,
                          centro_costo,
                          solicitante,
                          estado_transaccion,
                          tipo_ppto,
                          tipo_bien,
                          tipo_pedido,
                          nro_transaccion,
                          nro_pedido,
                          fecha_reg,
                          cuser_id,
                          equipo_reg)
                   VALUES (
                            @LN_vid_ano,
                           @LN_vid_sec_ejec,
                          @LN_vid_tipo_trans,
                          @ln_origen,
                          @ldt_cur_fecha_cuadro,
                          @ls_cur_centro_costo,
                          @ls_cur_empleado,
                          @LS_vis_est_trans,
                          @LN_vi_tipo_ppto,
                          @LS_vis_tipo_bien,
                          '5',
                          @ll_cur_sec_cuadro,
                          LTRIM(RTRIM(CONVERT(VARCHAR(20), @ll_cur_nro_requer))),
                          GETDATE(),
                          @ls_cuser_id,
                          @ls_equipo_reg)

            -- Recuperando el NRO de Origen
            /*
            REVISAR POR JULIO (EXISTEN DOS REGISTROS CON ESTOS DATOS )
            UNO EN PROCESO DE SELECCION
            */
            IF  (
                select  1
                from sig_seguimiento
                where ano_eje           = @LN_vid_ano   
                and sec_ejec            = @LN_vid_sec_ejec  
                and nro_origen          = @ln_origen 
                and tipo_transaccion    = 5  
                and nro_transaccion     = @ll_cur_sec_cuadro
                )   > 0

                BEGIN
                    select distinct 
                    @LN_vid_ano          = @LN_vid_ano, 
                    @LN_vid_ejecutora    = @LN_vid_sec_ejec, 
                    @LS_vis_tipo_bien    = tipo_bien, 
                    @LN_vid_nro_origen   = nro_origen
                    /*@LN_vid_sec_cuadro   = @ll_cur_sec_cuadro*/
                    from sig_seguimiento
                    where ano_eje           = @LN_vid_ano   
                    and sec_ejec            = @LN_vid_sec_ejec  
                    and nro_origen          = @ln_origen 
                    and tipo_transaccion    = 5  
                    and nro_transaccion     = @ll_cur_sec_cuadro
                END
            ELSE
                BEGIN
                    SELECT  @LN_vid_ano         = 0
                    SELECT  @LN_vid_ejecutora   = 0
                    SELECT  @LS_vis_tipo_bien   = 0
                    SELECT  @LN_vid_nro_origen  = 0
                  /*LN_vid_sec_cuadro := 0*/
                END

          if @LN_vid_nro_origen > 0
                BEGIN
                --CORRELATIVO
                 SELECT @ln_secuencia = COALESCE(MAX(sec_estado),0) + 1
                   FROM sig_seguimiento_estado
                  WHERE ano_eje          = @LN_vid_ano      AND
                        sec_ejec         = @LN_vid_sec_ejec     AND
                        tipo_transaccion = @LN_vid_tipo_trans AND
                        nro_origen       = @LN_vid_nro_origen
        
                  --INSERTA DETALLE(ESTADO)
                  insert into sig_seguimiento_estado(
                              ano_eje,
                              sec_ejec,
                              tipo_transaccion,
                              nro_origen,
                              sec_estado,
                              fecha_estado,
                              estado_seguimiento,
                              fecha_reg,
                              cuser_id,
                              equipo_reg)
                       VALUES (
                              @LN_vid_ano,
                              @LN_vid_sec_ejec,
                              @LN_vid_tipo_trans,
                              @LN_vid_nro_origen,
                              @ln_secuencia ,
                              GETDATE(),
                              @LS_vis_est_trans,
                              GETDATE(),
                              @ls_cuser_id,
                              @ls_equipo_reg
                              )
                END
        END
   END
END

    IF @LN_vi_tipo_ppto = 2
    BEGIN
    
       IF @LS_FLAG_PROCESO = 0
       BEGIN
          -- 16: Compras x Encargo      3 : Pedido Encargos
          SELECT    @LN_vid_tipo_trans      = 16
          SELECT    @LN_vid_tipo_trans_ant  = 3
    
          --CORRELATIVO
             SELECT @ln_origen = COALESCE(MAX(nro_origen),0) + 1
               FROM sig_seguimiento
              WHERE ano_eje          = @LN_vid_ano   AND
                    sec_ejec         = @LN_vid_sec_ejec  AND
                    tipo_transaccion = @LN_vid_tipo_trans
    
          --INSERTA CABECERA
          INSERT INTO sig_seguimiento(
                      ano_eje,
                      sec_ejec,
                      tipo_transaccion,
                      nro_origen,
                      fecha_transaccion,
                      centro_costo,
                      solicitante,
                      estado_transaccion,
                      tipo_ppto,
                      tipo_bien,
                      tipo_pedido,
                      nro_transaccion,
                      nro_pedido,
                      fecha_reg,
                      cuser_id,
                      equipo_reg)
               VALUES (
                      @LN_vid_ano,
                      @LN_vid_sec_ejec,
                      @LN_vid_tipo_trans,
                      @ln_origen,
                      @ldt_cur_fecha_cuadro,
                      @ls_cur_centro_costo,
                      @ls_cur_empleado,
                      @LS_vis_est_trans,
                      @LN_vi_tipo_ppto,
                      @LS_vis_tipo_bien,
                      NULL,
                      @ll_cur_sec_cuadro,
                      LTRIM(RTRIM(CONVERT(VARCHAR(20), @ll_cur_nro_requer))),
                      GETDATE(),
                      @ls_cuser_id,
                      @ls_equipo_reg
                      )
    
          -- Recuperando el Nº de Origen
            if  (
                SELECT 1
                FROM sig_seguimiento
                WHERE ano_eje          = @LN_vid_ano    AND
                sec_ejec         = @LN_vid_sec_ejec   AND
                nro_origen       = @ln_origen and
                nro_transaccion  = @ll_cur_sec_cuadro AND
                tipo_transaccion = @LN_vid_tipo_trans
                ) > 0
                BEGIN
                    SELECT distinct 
                    @LN_vid_ano         = @LN_vid_ano, 
                    @LN_vid_ejecutora   = @LN_vid_sec_ejec, 
                    @LS_vis_tipo_bien   = tipo_bien, 
                    @LN_vid_nro_origen  = nro_origen
                    /*@LN_vid_sec_cuadro  = @ll_cur_sec_cuadro*/
                    FROM sig_seguimiento
                      WHERE ano_eje          = @LN_vid_ano    AND
                            sec_ejec         = @LN_vid_sec_ejec   AND
                            nro_origen       = @ln_origen and
                            nro_transaccion  = @ll_cur_sec_cuadro AND
                            tipo_transaccion = @LN_vid_tipo_trans
                END
            ELSE
                BEGIN
                    SELECT  @LN_vid_ano         = 0
                    SELECT  @LN_vid_ejecutora  = 0
                    SELECT  @LS_vis_tipo_bien  = 0
                    SELECT  @LN_vid_nro_origen = 0
                    /*SELECT  @LN_vid_sec_cuadro = 0*/
                END

    
          -- Recupera Destino
          
            IF  (
                select
                1
                from sig_seguimiento
                where   ano_eje          = @LN_vid_ano        
                AND     sec_ejec         = @LN_vid_sec_ejec   
                AND     nro_transaccion  = @LN_vi_nro_encargo 
                AND     tipo_transaccion = @LN_vid_tipo_trans_ant
                )   > 0
                BEGIN
                    select
                    @LN_vid_nro_destino     = nro_origen
                    from sig_seguimiento
                    where   ano_eje          = @LN_vid_ano        
                    AND     sec_ejec         = @LN_vid_sec_ejec   
                    AND     nro_transaccion  = @LN_vi_nro_encargo 
                    AND     tipo_transaccion = @LN_vid_tipo_trans_ant
                END
            ELSE
                BEGIN
                    SELECT  @LN_vid_nro_destino = 0
                END

          -- Inserta en la tabla de estados del seguimiento
          IF  @LN_vid_nro_origen > 0
            BEGIN
                --CORRELATIVO(SECUENCIA)
                SELECT @ln_secuencia = COALESCE(max(sec_estado),0) + 1
                  FROM sig_seguimiento_estado
                 WHERE ano_eje          = @LN_vid_ano        AND
                       sec_ejec         = @LN_vid_sec_ejec       AND
                       tipo_transaccion = @LN_vid_tipo_trans   AND
                       nro_origen       = @LN_vid_nro_origen
    
        
                 --INSERTA DETALLE(ESTADO)
                 INSERT INTO sig_seguimiento_estado(
                             ano_eje,
                             sec_ejec,
                             tipo_transaccion,
                             nro_origen,
                             sec_estado,
                             fecha_estado,
                             estado_seguimiento,
                             fecha_reg,
                             cuser_id,
                             equipo_reg)
                      VALUES (
                             @LN_vid_ano,
                             @LN_vid_sec_ejec,
                             @LN_vid_tipo_trans,
                             @LN_vid_nro_origen,
                             @ln_secuencia,
                             @ldt_cur_fecha_cuadro,
                             @LS_vis_est_trans,
                             GETDATE(),
                             @ls_cuser_id,
                             @ls_equipo_reg)
    
       END
    
    END

   -- Inserta Secuencia
   IF (@LN_vid_nro_origen > 0 AND @LN_vid_nro_destino > 0)
       BEGIN
          INSERT INTO sig_seguimiento_secuencia
                      (ano_eje, sec_ejec, tipo_transaccion,
                       nro_origen, tipo_transaccion_destino, nro_destino)
               VALUES (@LN_vid_ano, @LN_vid_sec_ejec, @LN_vid_tipo_trans,
                       @LN_vid_nro_origen,  @LN_vid_tipo_trans_ant, @LN_vid_nro_destino)
        END
END

END
GO


-- ----------------------------
