-- ----------------------------
-- Triggers structure for table SIG_ENCARGO_REQ
-- ----------------------------
CREATE TRIGGER [dbo].[tg_pedido_encargo_del]
ON [dbo].[SIG_ENCARGO_REQ]
WITH EXECUTE AS CALLER
FOR DELETE
AS
declare @vn_Ano_Eje            NUMERIC(4),
        @vn_Sec_Ejec           NUMERIC(6),
        @vn_Tipo_Transaccion   NUMERIC(2),
        @vn_Nro_Origen         NUMERIC(6),
        @vn_Nro_Transaccion    NUMERIC(6),
        @vn_Sec_Encargo_Req    NUMERIC(6),
        @vs_Sec_Encargo_Req    VARCHAR(10),
        @vs_Estado             CHAR(1),
        @vs_Centro_Costo       VARCHAR(15),
        @vd_Fecha_Encargo_Reg  DATETIME,
        @vn_Nro_Secuencia      NUMERIC(6),
        @vs_CUser              VARCHAR(30),
        @vs_Equipo_Reg         VARCHAR(20)

BEGIN

   -- datos de sesión
   IF OBJECT_ID ('TEMPDB..#sig_sesion') IS NOT NULL
      SELECT @vs_CUser=      CUSER_ID,
             @vs_Equipo_Reg= EQUIPO_REG
        FROM #SIG_SESION
   ELSE
      SELECT @vs_CUser=       CUSER_MOD,
             @vs_Equipo_Reg=  COALESCE( EQUIPO_MOD, '')
        FROM DELETED

	      
   SELECT @vn_Ano_Eje=           D.ANO_EJE,
          @vn_Sec_Ejec=          D.SEC_EJEC,
          @vn_Nro_Transaccion=   SIG_SEGUIMIENTO.NRO_TRANSACCION,
          @vn_Sec_Encargo_Req=   D.SEC_ENCARGO_REQ,
          @vs_Estado=            D.ESTADO,
          @vd_Fecha_Encargo_Reg= D.FECHA_ENCARGO_REQ,
          @vs_Centro_Costo=      D.CENTRO_COSTO
     FROM DELETED D
     JOIN SIG_SEGUIMIENTO ON
          SIG_SEGUIMIENTO.ANO_EJE          = D.ANO_EJE          AND
          SIG_SEGUIMIENTO.SEC_EJEC         = D.SEC_EJEC         AND
          SIG_SEGUIMIENTO.NRO_TRANSACCION  = D.SEC_ENCARGO_REQ  AND
          SIG_SEGUIMIENTO.TIPO_TRANSACCION = 3
	
	select @vn_Tipo_Transaccion = A.tipo_transaccion,
	       @vn_Nro_Origen = A.nro_origen
	from sig_seguimiento A
	where A.ano_eje 	= @vn_Ano_Eje 	 and
	      A.sec_ejec	= @vn_Sec_Ejec and
	      A.nro_transaccion = @vn_Nro_Transaccion		

	delete from sig_seguimiento_estado
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vn_Tipo_Transaccion and
	      nro_origen 	= @vn_Nro_Origen 

	delete from sig_seguimiento_secuencia
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vn_Tipo_Transaccion and
	      nro_origen 	= @vn_Nro_Origen 


	delete from sig_seguimiento	
	where ano_eje 		= @vn_Ano_Eje 	  and
	      sec_ejec 		= @vn_Sec_Ejec  and
	      tipo_transaccion	= @vn_Tipo_Transaccion and
	      nro_origen 	= @vn_Nro_Origen 


    -- auditoria
    SELECT @vs_Sec_Encargo_Req= CONVERT( VARCHAR(10), @vn_Sec_Encargo_Req)

    SELECT @vn_Nro_Secuencia= COALESCE(MAX(SECUENCIA),0) + 1
      FROM SIG_AUDITORIA
     WHERE ANO_EJE         = @vn_Ano_Eje   AND
           SEC_EJEC        = @vn_Sec_Ejec  AND
           TIPO_MOVIMIENTO = 'D'

    INSERT INTO SIG_AUDITORIA (
           ANO_EJE,                SEC_EJEC,               TIPO_MOVIMIENTO,         SECUENCIA,             TIPO_PEDIDO,
           NRO_PEDIDO,             NRO_TRANSACCION,        FECHA_TRANSACCION,       ESTADO_TRANSACCION,    CENTRO_COSTO,
           FECHA_REG,              CUSER_ID,               EQUIPO_REG,              TIPO_TRANSACCION)
    VALUES (
		   @vn_Ano_Eje,            @vn_Sec_Ejec,           'D',                     @vn_Nro_Secuencia,     '3',
           @vs_Sec_Encargo_Req,    @vn_Sec_Encargo_Req,    @vd_Fecha_Encargo_Reg,   @vs_Estado,            @vs_Centro_Costo,
		   GETDATE(),              @vs_CUser,              @vs_Equipo_Reg,          3) 


end
GO

CREATE TRIGGER [dbo].[tg_pedido_encargo_ins]
ON [dbo].[SIG_ENCARGO_REQ]
WITH EXECUTE AS CALLER
FOR INSERT
AS
declare @vid_nro_origen numeric(6),
	@vid_tipo_trans numeric(2),
	@vid_ano         numeric(4),		
	@vid_ejecutora   numeric(6),		
	@vid_sec_encargo numeric(6),		
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)

begin

	select @vid_ano		 = B.ano_eje	 ,
	       @vid_ejecutora	 = B.sec_ejec    ,
	       @vid_sec_encargo    = B.sec_encargo_req,
	       @vis_cuser_id	 = B.cuser_id ,
	       @vis_equipo_reg	 = B.equipo_reg
	from  inserted B

	select @vid_tipo_trans = 3

	insert into sig_seguimiento(
		  ano_eje,
		  sec_ejec,
		  tipo_transaccion,
		  nro_origen,	
		  fecha_transaccion,	
		  centro_costo,
		  solicitante,
		  estado_transaccion,
		  tipo_ppto,
		  tipo_pedido,		
		  nro_transaccion,
		  nro_pedido,
		  fecha_reg,
		  cuser_id,
		  equipo_reg
		  )
	select B.ano_eje,
	       B.sec_ejec,
	       @vid_tipo_trans,
		coalesce((select max(A.nro_origen)
		 from sig_seguimiento A
		 where A.ano_eje 	   = B.ano_eje	     and
		       A.sec_ejec 	   = B.sec_ejec	     and
		       A.tipo_transaccion = @vid_tipo_trans),0)+1,
	      B.fecha_encargo_req,
	      B.centro_costo,
	      B.empleado,	
	      B.estado,
	      2,
	      '3',
	      B.sec_encargo_req,
	      Right('000000'+convert(varchar(6),B.sec_encargo_req),6),	
	      getdate(),
	      @vis_cuser_id,
	      @vis_equipo_reg	        					
	from  inserted B

	
	select	@vid_nro_origen = A.nro_origen
	from sig_seguimiento A,
	     inserted B
	where A.ano_eje 	 = B.ano_eje 	     and
	      A.sec_ejec 	 = B.sec_ejec 	     and
	      A.nro_transaccion	 = B.sec_encargo_req and	
	      A.tipo_transaccion = @vid_tipo_trans 

	insert into sig_seguimiento_estado(
			ano_eje,
			sec_ejec,
			tipo_transaccion,
			nro_origen,
			sec_estado,
			fecha_estado,
			estado_seguimiento,
			fecha_reg,
			cuser_id,
			equipo_reg
			)	
	
	select A.ano_eje,
	       A.sec_ejec,
	       @vid_tipo_trans,
	       @vid_nro_origen,
	       coalesce((select max(sec_estado)  
		from sig_seguimiento_estado
		where ano_eje          = A.ano_eje 	   and               
		      sec_ejec	        = A.sec_ejec       and 
		      tipo_transaccion = @vid_tipo_trans  and
		      nro_origen       = @vid_nro_origen),0)+1,
		getdate(),
		A.estado,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg
		from inserted A
end
GO

CREATE TRIGGER [dbo].[tg_pedido_encargo_upd]
ON [dbo].[SIG_ENCARGO_REQ]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
	@vid_ejecutora   numeric(6),
	@vid_tipo_trans  numeric(2),
	@vid_nro_origen  numeric(6),
	@vid_nro_trans   numeric(6),
	@vis_tipo_bien   char(1),
	@vis_tipo_ped    char(1),
	@vis_nro_ped	 char(5),
	@vis_est_trans 	 char(1),
    @ls_estado_ori   varchar(1),
	@vd_fecha_ped    datetime,
	@vd_fecha_apr    DATETIME,
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)

BEGIN

select 
@vid_ano		 = ano_eje,
@vid_ejecutora	 = sec_ejec,
@vid_nro_trans    = sec_encargo_req,
@vis_est_trans	 = estado,
@vd_fecha_ped     = fecha_encargo_req,
@vd_fecha_apr	 = fecha_autorizacion,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from  inserted

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

update sig_encargo_req 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
ano_eje     = @vid_ano       and
sec_ejec    = @vid_ejecutora and	 
sec_encargo_req   = @vid_nro_trans 

/*obtengo el estado original*/
SELECT  @ls_estado_ori  = ESTADO
FROM    DELETED

/*si no ha cambiado el estado, salgo*/
IF @ls_estado_ori = @vis_est_trans
BEGIN
    RETURN
END

	select @vid_tipo_trans = 3

	if update(estado)		
	begin

 	if @vis_est_trans = '2' 
		begin
			select @vd_fecha_ped = @vd_fecha_apr
		end
	
	if not exists 
		(select 1
		 from sig_seguimiento
		 where ano_eje 	        = @vid_ano and
		       sec_ejec         = @vid_ejecutora and
		       nro_transaccion  = @vid_nro_trans and
		       tipo_transaccion = @vid_tipo_trans )
		begin
			select @vid_ano = @vid_ano
			
			insert into sig_seguimiento(		
	       		ano_eje, sec_ejec, tipo_transaccion,
		        nro_origen,
		        centro_costo, solicitante, tipo_ppto,
		        tipo_bien, tipo_pedido, nro_transaccion,
	      		nro_pedido, fecha_transaccion, estado_transaccion, 
	   	        fecha_reg, cuser_id, equipo_reg)   
			select A.ano_eje, A.sec_ejec, @vid_tipo_trans,
			       coalesce((select max(B.nro_origen)
				from sig_seguimiento B
				where B.ano_eje 	 = @vid_ano	    and
				      B.sec_ejec 	 = @vid_ejecutora   and
				      B.tipo_transaccion = @vid_tipo_trans ),0)+1,	
				A.centro_costo,	A.empleado, 2,
				null, '3', A.sec_encargo_req,
				right('000000' + convert(varchar(6),A.sec_encargo_req),6), A.fecha_encargo_req, A.estado,
				getdate(), @vis_cuser_id, @vis_equipo_reg
			from inserted A	

		end 		
	
	select @vid_nro_origen = nro_origen
	from sig_seguimiento
	where  ano_eje       	  = @vid_ano        and
	       sec_ejec      	  = @vid_ejecutora  and	 
	       nro_transaccion    = @vid_nro_trans  and
	       tipo_transaccion	  = @vid_tipo_trans
		

	update sig_seguimiento 
	set estado_transaccion  = @vis_est_trans
	where  ano_eje       	= @vid_ano       and
	       sec_ejec      	= @vid_ejecutora and	 
	       nro_transaccion  = @vid_nro_trans and
	       tipo_transaccion = @vid_tipo_trans		

	insert into sig_seguimiento_estado(
		ano_eje, sec_ejec, tipo_transaccion,
		nro_origen, sec_estado,
		fecha_estado, estado_seguimiento, fecha_reg,
		cuser_id, equipo_reg)
	select A.ano_eje, A.sec_ejec, @vid_tipo_trans,
	       @vid_nro_origen,
	       coalesce((select max(C.sec_estado)
		from sig_seguimiento_estado C
		where C.ano_eje 	 = @vid_ano	    and
		      C.sec_ejec 	 = @vid_ejecutora   and
		      C.tipo_transaccion = @vid_tipo_trans  and
		      C.nro_origen	 = @vid_nro_origen),0)+1,
		@vd_fecha_ped, B.estado, getdate(),
		@vis_cuser_id, @vis_equipo_reg			    
	from deleted A
	inner join inserted B
	on A.ano_eje 		= B.ano_eje  and
	   A.sec_ejec 		= B.sec_ejec and
	   A.sec_encargo_req	= B.sec_encargo_req and
	   A.estado <> B.estado
	end
end
GO


-- ----------------------------
