-- ----------------------------
-- Triggers structure for table SIG_INM_COMPONENTE
-- ----------------------------
CREATE TRIGGER [dbo].[TG_SIG_INM_COMPONENTE]
ON [dbo].[SIG_INM_COMPONENTE]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
DECLARE
@ll_ejec_sec        NUMERIC(10),
@ll_inm_uni_act_sec NUMERIC(10),
@ll_uni_act_sec     NUMERIC(10),
@ll_componente      NUMERIC(10),
@vis_cuser_id       VARCHAR(30),
@vis_equipo_reg     VARCHAR(20)

BEGIN

SELECT
@ll_ejec_sec        = SEC_EJEC,
@ll_inm_uni_act_sec = SECUENCIA,
@ll_uni_act_sec     = SEC_UNIDAD_ACTIVO,
@ll_componente      = SEC_COMPONENTE,
@vis_cuser_id       = CUSER_MOD,
@vis_equipo_reg     = EQUIPO_MOD
FROM    INSERTED

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

/*actualizo los valores del usuario modificado*/
UPDATE  SIG_INM_COMPONENTE
SET     CUSER_MOD           = @vis_cuser_id,
        EQUIPO_MOD          = @vis_equipo_reg,
FECHA_MOD           = GETDATE()
WHERE   SEC_EJEC            = @ll_ejec_sec
AND     SECUENCIA           = @ll_inm_uni_act_sec
AND     SEC_UNIDAD_ACTIVO   = @ll_uni_act_sec
AND     SEC_COMPONENTE      = @ll_componente

END
GO


