CREATE TRIGGER [dbo].[tg_movim_almacen_del]
ON [dbo].[SIG_MOVIM_ALMACEN]
WITH EXECUTE AS CALLER
FOR DELETE
AS
DECLARE
@ll_cur_ano_eje             NUMERIC(4),
@ll_cur_sec_ejec            NUMERIC(6),
@ll_cur_tipo_ppto           NUMERIC(10),
@vid_tipo_trans             NUMERIC(2),
@vid_nro_origen             NUMERIC(6),
@ll_secuencia_max           NUMERIC(10),
@ll_tipo_transaccion        NUMERIC(10),
@ll_cont                    NUMERIC(10),
@ls_tipo_movimiento         VARCHAR(1)  = 'D',
@ls_cur_tipo_bien           VARCHAR(1),
@ls_cur_tipo_pedido         VARCHAR(2),
@ls_cur_nro_pedido          VARCHAR(50),
@ls_cur_estado_transaccion  VARCHAR(1),
@ls_cur_centro_costo        VARCHAR(15),
@ls_cur_cuser_id            VARCHAR(30),
@ls_cur_equipo_reg          VARCHAR(20),
@ls_tipo_movimto            VARCHAR(1),
@ldt_cur_fecha_transaccion  DATETIME

BEGIN

SELECT  @ll_cont = COUNT(1)
FROM    DELETED
IF @ll_cont <> 1 
    RETURN

SELECT  
@ll_cur_ano_eje             = ANO_EJE,
@ll_cur_sec_ejec            = SEC_EJEC,
@ls_cur_nro_pedido          = convert(varchar(7), nro_movimto),
@ll_cur_tipo_ppto           = TIPO_PPTO,
@ls_cur_estado_transaccion  = ESTADO_KARDEX,
@ldt_cur_fecha_transaccion  = fecha_movimto,
@ls_cur_centro_costo        = CENTRO_COSTO,
@ls_cur_cuser_id            = CUSER_MOD,
@ls_cur_equipo_reg          = EQUIPO_MOD,
@ls_cur_tipo_bien           = TIPO_BIEN,
@ls_cur_tipo_pedido         = convert(varchar(2),TIPO_TRANSAC),
@ll_tipo_transaccion        = TIPO_TRANSAC,
@ls_tipo_movimto            = TIPO_MOVIMTO
FROM    DELETED

IF @ls_tipo_movimto <> 'I'
    RETURN

--si existe la tabla de sesion, saco de ahi los datos
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @ls_cur_cuser_id    = CUSER_ID,
                @ls_cur_equipo_reg  = EQUIPO_REG
        FROM    #SIG_SESION
    END

-- Eliminar el Seguimiento	
select @vid_tipo_trans = isnull( A.tipo_transaccion,0),
       @vid_nro_origen = isnull(A.nro_origen,0)
from sig_seguimiento A
where A.ano_eje 	= @ll_cur_ano_eje 	 and
      A.sec_ejec	= @ll_cur_sec_ejec and
      A.tipo_pedido     = @ls_cur_tipo_pedido  and
      A.nro_pedido      = @ls_cur_nro_pedido and	
      A.tipo_transaccion in (20,21,22,23,24,25,26,27)
      
-- Elimina en las tablas
delete from sig_seguimiento_estado
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @vid_tipo_trans and
      nro_origen 	= @vid_nro_origen 

delete from sig_seguimiento_secuencia
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @vid_tipo_trans and
      nro_origen 	= @vid_nro_origen 

delete from sig_seguimiento	
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @vid_tipo_trans and
      nro_origen 	= @vid_nro_origen

/*FACT, se migro funcionalidad de uo_auditoria*/

if (@ll_tipo_transaccion = 1) 
		begin
			SELECT  @ll_tipo_transaccion    = 20
		end
	else if (@ll_tipo_transaccion = 3)	
		begin
			SELECT  @ll_tipo_transaccion    = 21
		end
	else if (@ll_tipo_transaccion = 4)	
		begin
			SELECT  @ll_tipo_transaccion    = 22
		end
	else if (@ll_tipo_transaccion = 5)	
		begin
			SELECT  @ll_tipo_transaccion    = 23
		END
	else if (@ll_tipo_transaccion = 6)	
		begin
			SELECT  @ll_tipo_transaccion    = 24
		END
	else if (@ll_tipo_transaccion = 8)	
		begin
			SELECT  @ll_tipo_transaccion    = 25
		END
	else if (@ll_tipo_transaccion = 9)	
		begin
			SELECT  @ll_tipo_transaccion    = 26
		END
	else if (@ll_tipo_transaccion = 17)	
		begin
			SELECT  @ll_tipo_transaccion    = 27
		END
	else
		begin
			select @ll_tipo_transaccion = 0		
		END  

/*obtengo el secuencial de auditoria*/
SELECT  @ll_secuencia_max   = COALESCE(MAX(SECUENCIA), 0) + 1
FROM    SIG_AUDITORIA
WHERE   ANO_EJE             = @ll_cur_ano_eje
AND     SEC_EJEC            = @ll_cur_sec_ejec
AND     TIPO_MOVIMIENTO     = @ls_tipo_movimiento

INSERT  INTO    SIG_AUDITORIA(
                ANO_EJE, SEC_EJEC, TIPO_MOVIMIENTO, SECUENCIA,
                TIPO_TRANSACCION, NRO_ORIGEN, CENTRO_COSTO, SOLICITANTE,
                TIPO_PPTO, TIPO_BIEN, TIPO_PEDIDO, NRO_PEDIDO,
                NRO_CONSOLID, NRO_TRANSACCION, FECHA_TRANSACCION, ESTADO_TRANSACCION,
                SEC_TRANSACCION, FECHA_REG, CUSER_ID, EQUIPO_REG,
                TIPO_CONSOLID
                )
VALUES          (
                @ll_cur_ano_eje, @ll_cur_sec_ejec, @ls_tipo_movimiento,	@ll_secuencia_max,
                @ll_tipo_transaccion, NULL, NULL, NULL,
                NULL, @ls_cur_tipo_bien, @ls_cur_tipo_pedido, @ls_cur_nro_pedido,
                NULL, CAST(@ls_cur_nro_pedido AS NUMERIC(10)), @ldt_cur_fecha_transaccion, @ls_cur_estado_transaccion,
                NULL, GETDATE(), @ls_cur_cuser_id, @ls_cur_equipo_reg,
                NULL
                )

END
GO

CREATE TRIGGER [dbo].[tg_movim_almacen_ins]
ON [dbo].[SIG_MOVIM_ALMACEN]
WITH EXECUTE AS CALLER
FOR INSERT
AS
------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

declare @vid_tipo_trans numeric(2),
	@vid_nro_origen numeric(6),
	@vid_ano	    numeric(4),
	@vid_ejecutora	numeric(6),
	@vis_ALMACEN    varchar(3),
	@vis_SEC_ALMACEN varchar(3),
	@vis_TIPO_MOVIMTO varchar(1),
	@vid_TIPO_PPTO  numeric(1),	
	--@vid_NRO_MOVIMTO numeric(5),
	@vid_NRO_MOVIMTO numeric(6),
	@vis_tipo_trans_a numeric(2),
	@vis_cuser_id	varchar(30),
	@vis_equipo_reg	varchar(20)
begin

	SELECT @vid_ejecutora	= b.SEC_EJEC,   
           @vid_ano			= b.ANO_EJE,   
           @vis_ALMACEN		= b.ALMACEN,   
           @vis_SEC_ALMACEN	= b.SEC_ALMACEN,   
           @vis_TIPO_MOVIMTO= b.TIPO_MOVIMTO,   
           @vid_tipo_trans	= b.TIPO_TRANSAC,   
           @vid_TIPO_PPTO  	= b.TIPO_PPTO,   
           @vid_NRO_MOVIMTO	= b.NRO_MOVIMTO,
	       @vis_cuser_id	 = B.cuser_id    ,
	       @vis_equipo_reg	 = B.equipo_reg
    FROM inserted B
	
	select @vis_tipo_trans_a = convert(varchar(2),@vid_tipo_trans)

	if (@vid_tipo_trans = 1) 
		begin
			select @vid_tipo_trans = 20		
		end
	else if (@vid_tipo_trans = 3)	
		begin
			select @vid_tipo_trans = 21		
		end
	else if (@vid_tipo_trans = 4)	
		begin
			select @vid_tipo_trans = 22		
		end
	else if (@vid_tipo_trans = 5)	
		begin
			select @vid_tipo_trans = 23		
		END
	else if (@vid_tipo_trans = 6)	
		begin
			select @vid_tipo_trans = 24		
		END
	else if (@vid_tipo_trans = 8)	
		begin
			select @vid_tipo_trans = 25		
		END
	else if (@vid_tipo_trans = 9)	
		begin
			select @vid_tipo_trans = 26		
		END
	else if (@vid_tipo_trans = 17)	
		begin
			select @vid_tipo_trans = 27		
		END
	else
		begin
			select @vid_tipo_trans = 0		
		END    

	if (@vid_tipo_trans <> 0 and @vis_TIPO_movimto= 'I') 
		begin

       
		insert into sig_seguimiento(
			  ano_eje,
			  sec_ejec,
			  tipo_transaccion,
			  nro_origen,	
			  nro_transaccion,		
			  fecha_transaccion,	
			  solicitante,
			  estado_transaccion,
			  tipo_ppto,
			  tipo_bien,
			  tipo_pedido,		
			  nro_pedido,
			  centro_costo,			  
			  fecha_reg,
			  cuser_id,
			  equipo_reg
			  )
		select B.ano_eje,
		       B.sec_ejec,
		       @vid_tipo_trans,
			(select (isnull(max(A.nro_origen),0)+1)
			 from sig_seguimiento A
			 where (A.ano_eje 	   = B.ano_eje ) and
			       (A.sec_ejec 	   = B.sec_ejec) and
			       (A.tipo_transaccion = @vid_tipo_trans)  ),
		      B.nro_movimto,		
		      B.fecha_movimto,
		      B.RESPONSABLE,	
		      B.ESTADO_KARDEX,
		      B.tipo_ppto,
		      B.TIPO_BIEN,
		      @vis_tipo_trans_a,
		      convert(varchar(7), B.nro_movimto),		
		      B.almacen + B.sec_almacen,
		      getdate(),
		      @vis_cuser_id,
		      @vis_equipo_reg	        					
		from  inserted B
	
	
		select	@vid_nro_origen = A.nro_origen
		from sig_seguimiento A,
		     inserted B
		where A.ano_eje 	= B.ano_eje and
		      A.sec_ejec 	= B.sec_ejec and
		      A.nro_transaccion	= B.nro_movimto and
		      A.tipo_transaccion = @vid_tipo_trans and
		      A.centro_costo = B.almacen + B.sec_almacen	
	
		-- Registra en la tala sig_seguimiento_estado
		insert into sig_seguimiento_estado(
				ano_eje,
				sec_ejec,
				tipo_transaccion,
				nro_origen,
				sec_estado,
				fecha_estado,
				estado_seguimiento,
				fecha_reg,
				cuser_id,
				equipo_reg
				)	
		select A.ano_eje,
		       A.sec_ejec,
		       @vid_tipo_trans,
		       @vid_nro_origen,
		       (select isnull(max(sec_estado),0) +1 
			from sig_seguimiento_estado
			where ano_eje  	       = A.ano_eje 	and               
			      sec_ejec	       = A.sec_ejec 	and 
			      tipo_transaccion = @vid_tipo_trans and
			      nro_origen       = @vid_nro_origen ) ,
			getdate(),
			A.ESTADO_KARDEX,
			getdate(),
			@vis_cuser_id,
			@vis_equipo_reg
			from inserted A  	 	
		end	
end
GO

CREATE TRIGGER [dbo].[tg_movim_almacen_upd]
ON [dbo].[SIG_MOVIM_ALMACEN]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare 
@vid_ano         numeric(4),
@vid_ejecutora   numeric(6),
@vid_tipo_trans  numeric(2),
@vid_nro_trans   numeric(6),
@vid_nro_origen  numeric(6),
@ll_tipo_ppto   numeric(10),
@vis_est_trans   char(1),
@vid_sec_pedido  numeric(6),
@vd_fecha_ped    DATETIME,
@vis_cuser_id	 varchar(30),
@vis_equipo_reg	 varchar(20),
@vis_TIPO_movimto  varchar(1),
@vis_ALMACEN    varchar(3),
@vis_SEC_ALMACEN varchar(3),
@ls_estado_ori   VARCHAR(1)

begin

select 
@vid_ano            = ano_eje,
@vid_ejecutora      = sec_ejec,
@vid_nro_trans      = NRO_MOVIMTO,
@vis_est_trans      = ESTADO_KARDEX,
@vd_fecha_ped       = fecha_movimto,
@vid_tipo_trans	   = TIPO_TRANSAC,
@vis_TIPO_movimto   = TIPO_movimto,
@vis_ALMACEN		   = ALMACEN,   
@vis_SEC_ALMACEN	   = SEC_ALMACEN   ,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from  inserted 

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

update sig_movim_almacen 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
SEC_EJEC        = @vid_ejecutora and	 
ANO_EJE         = @vid_ano       and
ALMACEN         = @vis_ALMACEN AND 
SEC_ALMACEN     = @vis_SEC_ALMACEN and
TIPO_MOVIMTO    = @vis_TIPO_movimto and 
TIPO_TRANSAC    = @vid_tipo_trans and 
TIPO_PPTO       = @ll_tipo_ppto and
NRO_MOVIMTO     = @vid_nro_trans

/*obtengo el estado original*/
SELECT  @ls_estado_ori  = ESTADO_KARDEX
FROM    DELETED

/*si no ha cambiado el estado, salgo*/
IF @ls_estado_ori = @vis_est_trans
BEGIN
    RETURN
END

     if update(ESTADO_KARDEX)                
       begin
			if (@vid_tipo_trans = 1) 
				begin
					select @vid_tipo_trans = 20		
				end
			else if (@vid_tipo_trans = 3)	
				begin
					select @vid_tipo_trans = 21		
				end
			else if (@vid_tipo_trans = 4)	
				begin
					select @vid_tipo_trans = 22		
				end
			else if (@vid_tipo_trans = 5)	
				begin
					select @vid_tipo_trans = 23		
				END
			else if (@vid_tipo_trans = 6)	
				begin
					select @vid_tipo_trans = 24		
				END
			else if (@vid_tipo_trans = 8)	
				begin
					select @vid_tipo_trans = 25		
				END
			else if (@vid_tipo_trans = 9)	
				begin
					select @vid_tipo_trans = 26		
				END
			else if (@vid_tipo_trans = 17)	
				begin
					select @vid_tipo_trans = 27		
				END            
			else
				begin
					select @vid_tipo_trans = 0		
				END    

			if (@vid_tipo_trans <> 0 and @vis_TIPO_movimto= 'I') 
				begin

	            select @vid_nro_origen = nro_origen
	            from sig_seguimiento
	            where  ano_eje             = @vid_ano        and
	                   sec_ejec            = @vid_ejecutora  and 
	                   nro_transaccion     = @vid_nro_trans  and
	                   tipo_transaccion    = @vid_tipo_trans and
	                   centro_costo = @vis_almacen + @vis_sec_almacen
	
	            update sig_seguimiento 
	            set estado_transaccion     = @vis_est_trans
	            where  ano_eje             = @vid_ano        and
	                   sec_ejec            = @vid_ejecutora  and    
	                   nro_transaccion     = @vid_nro_trans  and
	                   tipo_transaccion    = @vid_tipo_trans and
	                   centro_costo = @vis_almacen + @vis_sec_almacen             
	
				if @vid_nro_origen IS NOT NULL and @vid_nro_origen <> 0
					begin
			            insert into sig_seguimiento_estado(
			                        ano_eje, sec_ejec, tipo_transaccion,
			                        nro_origen, sec_estado,
			                        fecha_estado, estado_seguimiento, fecha_reg,
			                        cuser_id, equipo_reg)
			
			            select A.ano_eje, A.sec_ejec, @vid_tipo_trans,
			                   @vid_nro_origen,
			                   (select (isnull(max(C.sec_estado),0)+1)
			                        from sig_seguimiento_estado C
			                        where(C.ano_eje            = @vid_ano      ) and
			                             (C.sec_ejec           = @vid_ejecutora  ) and
			                             (C.tipo_transaccion = @vid_tipo_trans ) and
			                             (C.nro_origen           = @vid_nro_origen)),        
			                 getdate(), B.ESTADO_KARDEX, getdate(),
			                 @vis_cuser_id, @vis_equipo_reg                                      
			            from deleted A
			            inner join inserted B
			            on A.ano_eje       = B.ano_eje  and
			               A.sec_ejec       = B.sec_ejec and
			               A.nro_movimto     = B.nro_movimto and
			               A.ESTADO_KARDEX 	<> B.ESTADO_KARDEX
					end
	
				END

     end

end
GO


