-- ----------------------------
CREATE TRIGGER [dbo].[tg_patrimonio_del]
ON [dbo].[SIG_MOVIMIENTO_ACTIVO]
WITH EXECUTE AS CALLER
FOR DELETE
AS
declare @vid_ano             numeric(4),
        @vid_ejecutora       numeric(6),
        @vis_TIPO_INST       varchar(1),
        @vis_TIPO_MOVIMTO    varchar(1),
        @vis_FLAG_SALIDA     varchar(1),
        @vis_TIPO_TRANSAC    varchar(2),
        @vid_NRO_SALIDA      numeric(6),
        @vid_Tipo_Transaccion numeric(2),
        @vis_TIPO_DOCUMENTO  varchar(3), 
        @vis_NRO_ORDEN       varchar(7),
        @vis_NRO_DOCUMENTO   varchar(25),
        @vis_NRO_RESOLUC     varchar(40),
        @vid_NRO_SEC_SALIDA  numeric(6),
        @vid_nro_origen      numeric(6),
        @vid_NRO_MOVIMTO     numeric(6),        
		/* 22.04.00 RF-Todos - JAR - Inicio */
		--@vid_NRO_INGRESO     numeric(5),
		@vid_NRO_INGRESO     numeric(6),
		/* 22.04.00 RF-Todos - JAR - Fin */
        @vis_nro_doc_interno varchar(30),
        @vis_nro_convenio    varchar(40),
        @vd_fecha_movimto    DATETIME,
        @vd_fecha_resol      DATETIME,
        @vd_fecha_acta       DATETIME,
        @vd_fecha_convenio   DATETIME,
        @vis_TIPO_BIEN       varchar(1),
        @vid_TIPO_PPTO       numeric(1),
        @vis_nro_acta        varchar(40),
        @vis_tipo_salida     varchar(2),
        @vis_cuser_id        varchar(30),
        @vis_equipo_reg      varchar(20)

begin
    
    select @vid_ano            = B.ano_eje,
           @vid_ejecutora      = B.sec_ejec,
           @vis_TIPO_INST      = B.TIPO_INST,
           @vis_TIPO_MOVIMTO   = B.TIPO_MOVIMTO,
           @vis_TIPO_DOCUMENTO = B.TIPO_DOCUMENTO,
           @vis_NRO_ORDEN      = convert(varchar(7),B.NRO_ORDEN),
           @vis_TIPO_TRANSAC   = convert(varchar(2),B.TIPO_TRANSAC),
           @vid_NRO_SALIDA     = COALESCE(B.NRO_SALIDA,0),
           @vis_FLAG_SALIDA    = COALESCE(B.FLAG_SALIDA,'0'),
           @vis_NRO_DOCUMENTO  = B.NRO_DOCUMENTO,
           @vis_NRO_RESOLUC    = B.NRO_RESOLUC,
           @vid_NRO_SEC_SALIDA = B.NRO_SEC_SALIDA,
           @vid_NRO_MOVIMTO    = B.NRO_MOVIMTO,
           @vid_NRO_INGRESO    = B.NRO_INGRESO,
           @vis_nro_convenio   = B.nro_convenio,
           @vis_nro_doc_interno= B.nro_doc_interno,
           @vd_fecha_movimto   = B.fecha_movimto,
           @vd_fecha_resol     = B.fecha_resol,
           @vd_fecha_acta      = B.fecha_acta,
           @vd_fecha_convenio  = B.fecha_convenio,
           @vis_TIPO_BIEN      = B.TIPO_BIEN,
           @vid_TIPO_PPTO      = B.TIPO_PPTO,
           @vis_nro_acta       = B.nro_acta,
           @vid_Tipo_Transaccion     = b.TIPO_TRANSAC,
           @vis_tipo_salida    = B.tipo_salida
    from  deleted B
    
    -- Datos de Sesión
    IF OBJECT_ID ('TEMPDB..#SIG_SESION') IS NOT NULL
       SELECT @vis_cuser_id=   CUSER_ID,
              @vis_equipo_reg= EQUIPO_REG
         FROM #SIG_SESION
    ELSE
       SELECT @vis_cuser_id=   CUSER_MOD,
              @vis_equipo_reg= EQUIPO_MOD
         FROM DELETED
    
    if (@vis_TIPO_INST = '1' AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0) 
       begin
           select @vid_Tipo_Transaccion = 31      
       end
    else if ((@vis_TIPO_INST = '2' OR @vis_TIPO_INST = '3' OR @vis_TIPO_INST = '4' OR @vis_TIPO_INST = '5' OR @vis_TIPO_INST = '6') AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0)              
       begin
           select @vid_Tipo_Transaccion = 32                      
       end
    else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' AND @vis_FLAG_SALIDA='0' AND @vid_NRO_SALIDA=0) 
       begin
           select @vid_Tipo_Transaccion = 33                      
       END
    else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' AND @vis_FLAG_SALIDA='0' AND (@vid_NRO_SALIDA=0 OR @vid_NRO_SEC_SALIDA<>0) )                         
       begin
           select @vid_Tipo_Transaccion = 34 -- Mantenimiento Activos
       END
    else if ((@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3') AND @vis_FLAG_SALIDA='1' AND @vid_NRO_SALIDA=0)     
       begin
           select @vid_Tipo_Transaccion = 35 -- Salidas
       END
    else       
       begin
           select @vid_Tipo_Transaccion = 0                        
       END       
                               
    if @vid_Tipo_Transaccion <> 0
    BEGIN                              
		if @vid_Tipo_Transaccion = 31 
           begin      
               select @vid_NRO_MOVIMTO = @vid_NRO_MOVIMTO              
               
               if @vis_TIPO_DOCUMENTO = '031' 
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_NRO_ORDEN 
                  END                                                      
               if @vis_TIPO_DOCUMENTO = '045' 
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_NRO_DOCUMENTO   
                  END
                              
               select @vd_fecha_movimto = @vd_fecha_movimto   

           END
		else if @vid_Tipo_Transaccion = 32 
           BEGIN
               select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO 
               
               if @vis_tipo_inst = '2' OR @vis_tipo_inst = '4' OR @vis_tipo_inst = '5' OR @vis_tipo_inst = '6'
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
                      select @vd_fecha_movimto  = @vd_fecha_resol
                  END                                                      
               else if @vis_tipo_inst = '3'
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_nro_convenio
                      select @vd_fecha_movimto  = @vd_fecha_convenio
                  END
           END
		               
		else if @vid_Tipo_Transaccion = 33 
           begin                    
               select @vid_NRO_MOVIMTO   = @vid_NRO_INGRESO 
               select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC 
               select @vd_fecha_movimto  = @vd_fecha_resol
           END
		               
		else if @vid_Tipo_Transaccion = 34 
           begin                    
               select @vid_NRO_MOVIMTO   = @vid_NRO_INGRESO
               select @vis_NRO_DOCUMENTO = @vis_NRO_ORDEN               
           END   
		                               
		else if @vid_Tipo_Transaccion = 35 
           begin
               select @vid_NRO_MOVIMTO  = @vid_NRO_SEC_SALIDA
               select @vd_fecha_movimto = @vd_fecha_movimto
                                                                                                                               
               if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5')                
                  begin
                      if (@vis_tipo_salida='8')              
	                     begin
                             select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
                             select @vd_fecha_movimto  = @vd_fecha_resol
	                     END
                      else if (@vis_tipo_salida='7')     
                         begin
                             select @vis_NRO_DOCUMENTO = @vis_nro_acta
                             select @vd_fecha_movimto  = @vd_fecha_acta
                         END
                      else if (@vis_tipo_salida='6')
                         begin
                             select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
                         END
                      else if (@vis_tipo_salida='5')     
                         begin
                             select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
                         END
                  END
               else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1') 
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
                  END
               else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3')     
                  begin
                      select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
                  END                                  
           END                                                                                     
		   
           INSERT INTO sig_auditoria
                       (ano_eje     , sec_ejec     , tipo_movimiento, secuencia ,                                           
                        solicitante , TIPO_CONSOLID, tipo_pedido    , nro_pedido,
                        nro_transaccion, fecha_transaccion, estado_transaccion,
                        centro_costo, fecha_reg    , cuser_id       , equipo_reg, tipo_transaccion )
                SELECT B.ano_eje, B.sec_ejec,      'D',
                       coalesce((select max(A.secuencia)
                                   from sig_auditoria A
                                  where A.ano_eje         = B.ano_eje  and
                                        A.sec_ejec        = B.sec_ejec and
                                        A.tipo_movimiento = 'D'),0)+1,  
                       @vis_NRO_DOCUMENTO, B.TIPO_MOVIMTO+convert(varchar(2),B.TIPO_TRANSAC),
                       B.TIPO_MOVIMTO, Right('000000'+convert(varchar(6),@vid_NRO_MOVIMTO),6), B.NRO_MOVIMTO, @vd_fecha_movimto ,B.estado,
                       B.centro_costo  , getdate(), @vis_cuser_id, @vis_equipo_reg, @vid_Tipo_Transaccion
                  FROM deleted B
            

          IF @vid_Tipo_Transaccion = 33
          BEGIN 
            SELECT @vid_nro_origen = A.nro_origen
              FROM sig_seguimiento A,
                   deleted B
             WHERE A.ano_eje          = B.ano_eje        and
                   A.sec_ejec         = B.sec_ejec       and
                   A.tipo_transaccion = @vid_Tipo_Transaccion  AND
                   A.NRO_TRANSACCION  = B.NRO_MOVIMTO
          END   
          
          -- Mantenimiento de Activos
          ELSE IF @vid_Tipo_Transaccion = 34
          	BEGIN
			    SELECT DISTINCT @vid_nro_origen = A.nro_origen
			  	FROM sig_seguimiento A,
			  	  		DELETED B
			  	WHERE A.ano_eje   = B.ano_eje   
			  		AND A.sec_ejec  = B.sec_ejec 
			  		AND A.NRO_TRANSACCION = B.nro_movimto
					AND CONVERT(NUMERIC(6,0), A.nro_pedido)  = B.nro_ingreso
					AND A.tipo_transaccion = @vid_Tipo_Transaccion   
			           
          	END
                    
          ELSE IF @vid_Tipo_Transaccion = 35 
          BEGIN 
            SELECT DISTINCT @vid_nro_origen = A.nro_origen
              FROM sig_seguimiento A,
                   deleted B
             WHERE A.ano_eje          = B.ano_eje        and
                   A.sec_ejec         = B.sec_ejec       AND
                   A.NRO_TRANSACCION  = B.NRO_MOVIMTO AND 
                   A.tipo_transaccion = @vid_Tipo_Transaccion  AND
                   A.NRO_TRANSACCION  = B.NRO_MOVIMTO
          END             
          ELSE
          BEGIN
			    select DISTINCT @vid_nro_origen = A.nro_origen
			  	  from sig_seguimiento A,
			  	  		DELETED B
			  	 where A.ano_eje   = B.ano_eje   and
			           A.sec_ejec  = B.sec_ejec and
			           A.nro_transaccion  = @vid_NRO_MOVIMTO and
			           A.tipo_transaccion = @vid_Tipo_Transaccion   
          END

                
                DELETE FROM sig_seguimiento_estado
                 WHERE ano_eje          = @vid_ano        and
                       sec_ejec         = @vid_ejecutora  and
                       tipo_transaccion = @vid_Tipo_Transaccion and
                       nro_origen       = @vid_nro_origen 
                
                DELETE FROM sig_seguimiento_secuencia
                 WHERE ano_eje          = @vid_ano        and
                       sec_ejec         = @vid_ejecutora  and
                       tipo_transaccion = @vid_Tipo_Transaccion and
                       nro_origen       = @vid_nro_origen 
                
                DELETE FROM sig_seguimiento    
                 WHERE ano_eje          = @vid_ano        and
                       sec_ejec         = @vid_ejecutora  and
                       tipo_transaccion = @vid_Tipo_Transaccion and
                       nro_origen       = @vid_nro_origen 

     END
END
GO

CREATE TRIGGER [dbo].[tg_patrimonio_ins]
ON [dbo].[SIG_MOVIMIENTO_ACTIVO]
WITH EXECUTE AS CALLER
FOR INSERT
AS
declare @vid_nro_origen numeric(6),
	@vid_Tipo_Transaccion   numeric(2),
	@vid_ano          numeric(4),		
	@vid_ejecutora    numeric(6),  
	@vis_TIPO_INST    varchar(1),
	@vis_TIPO_MOVIMTO varchar(1),
	@vis_TIPO_TRANSAC varchar(2),
	@vid_NRO_SALIDA   numeric(6),
	@vis_FLAG_SALIDA  varchar(1),
	@vid_NRO_MOVIMTO  numeric(6), 	
	/* 22.04.00 RF-Todos - JAR - Inicio */
	--@vid_NRO_INGRESO  numeric(5),
	@vid_NRO_INGRESO  numeric(6),
	/* 22.04.00 RF-Todos - JAR - Fin */
	@vis_TIPO_DOCUMENTO varchar(3), 
	@vis_NRO_ORDEN    varchar(7),
	@vis_NRO_DOCUMENTO varchar(40),
	@vis_NRO_RESOLUC  varchar(40),
	@vid_NRO_SEC_SALIDA numeric(6),
	@vis_nro_convenio varchar(40),
	@vis_nro_doc_interno varchar(30),
	@vd_fecha_movimto DATETIME,
	@vd_fecha_convenio DATETIME,
	@vd_fecha_acta    DATETIME,
	@vd_fecha_resol   DATETIME,
	@vis_TIPO_BIEN    varchar(1),
	@vid_TIPO_PPTO    numeric(1),
	@vis_estado       varchar(1),
	@vis_nro_acta     varchar(40),
	@vis_tipo_salida  varchar(2),
	@vis_cuser_id	  varchar(30),
	@vis_equipo_reg	  varchar(20)

begin

	select @vid_ano		 = B.ano_eje	 ,
	       @vid_ejecutora	 = B.sec_ejec    ,	       	       
	       @vis_TIPO_INST    = B.TIPO_INST,
   	       @vis_TIPO_MOVIMTO = B.TIPO_MOVIMTO ,
   	       @vis_TIPO_TRANSAC = convert(varchar(2),B.TIPO_TRANSAC),
   	       @vid_NRO_SALIDA	 = COALESCE(B.NRO_SALIDA,0),
   	       @vis_FLAG_SALIDA  = COALESCE(B.FLAG_SALIDA,'0'),
	       @vid_NRO_MOVIMTO  = B.NRO_MOVIMTO,
	       @vid_NRO_INGRESO  = B.NRO_INGRESO,
	       @vis_TIPO_DOCUMENTO = B.TIPO_DOCUMENTO,
   	       @vis_NRO_ORDEN    = convert(varchar(7),B.NRO_ORDEN),
	       @vis_NRO_DOCUMENTO = B.NRO_DOCUMENTO,
	       @vis_NRO_RESOLUC  = B.NRO_RESOLUC,
	       @vid_NRO_SEC_SALIDA = B.NRO_SEC_SALIDA,
	       @vis_nro_convenio = B.nro_convenio,
	       @vis_nro_doc_interno= B.nro_doc_interno,
	       @vd_fecha_movimto = B.fecha_movimto,
	       @vd_fecha_convenio = B.fecha_convenio,
	       @vd_fecha_acta    = B.fecha_acta,
	       @vd_fecha_resol   = B.fecha_resol,
	       @vis_TIPO_BIEN    = B.TIPO_BIEN,
		   @vid_TIPO_PPTO    = B.TIPO_PPTO,
		   @vis_nro_acta     = B.nro_acta,
		   @vis_tipo_salida  = B.tipo_salida,
		   @vis_cuser_id	 = B.cuser_id,
		   @vis_equipo_reg	 = B.equipo_reg
	from  inserted B


	if (@vis_TIPO_INST = '1' AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0) 
		begin
			select @vid_Tipo_Transaccion = 31	
		end
	else if ((@vis_TIPO_INST = '2' OR @vis_TIPO_INST = '3' OR @vis_TIPO_INST = '4' OR @vis_TIPO_INST = '5' OR @vis_TIPO_INST = '6') AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_Tipo_Transaccion = 32		
		end
	else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' AND @vis_FLAG_SALIDA='0' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_Tipo_Transaccion = 33		
		END
	else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' AND @vis_FLAG_SALIDA='0' AND (@vid_NRO_SALIDA=0 OR @vid_NRO_SEC_SALIDA<>0) )	
		begin
			select @vid_Tipo_Transaccion = 34		
		END
	else if ((@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3') AND @vis_FLAG_SALIDA='1' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_Tipo_Transaccion = 35		
		END
	else 	
		begin
			select @vid_Tipo_Transaccion = 0		
		END		


    if @vid_Tipo_Transaccion <> 0
    BEGIN	
		if @vid_Tipo_Transaccion = 31 
			begin	  
				select @vid_NRO_MOVIMTO = @vid_NRO_MOVIMTO	
				
				if @vis_TIPO_DOCUMENTO = '031' 
					begin
						select @vis_NRO_DOCUMENTO = @vis_NRO_ORDEN	
					END				
				else if @vis_TIPO_DOCUMENTO = '045' 
					begin
						select @vis_NRO_DOCUMENTO = @vis_NRO_DOCUMENTO	
					END
					
				select @vd_fecha_movimto = @vd_fecha_movimto	

			END			
			
		else if @vid_Tipo_Transaccion = 32 
			BEGIN
				select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO	
				
				if @vis_tipo_inst = '2' OR @vis_tipo_inst = '4' OR @vis_tipo_inst = '5' OR @vis_tipo_inst = '6'
					begin
						select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
						select @vd_fecha_movimto = @vd_fecha_resol	
					END				
				else if @vis_tipo_inst = '3' 
					begin
						select @vis_NRO_DOCUMENTO = @vis_nro_convenio
						select @vd_fecha_movimto = @vd_fecha_convenio	
					END			   											
			END
			
		else if @vid_Tipo_Transaccion = 33 
			begin		
				select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO	
				select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC 
				select @vd_fecha_movimto = @vd_fecha_resol
			END	
			
		else if @vid_Tipo_Transaccion = 34 
			BEGIN
				select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO	
				IF(@vis_NRO_ORDEN IS NULL OR rtrim(@vis_NRO_ORDEN) = '')
					BEGIN
						select @vis_NRO_DOCUMENTO = NULL
					END
				ELSE
					BEGIN
						SELECT @vis_NRO_DOCUMENTO = Coalesce(@vis_NRO_ORDEN,'.')
					END
			END				
			
		else if @vid_Tipo_Transaccion = 35 
			begin	   
				select @vid_NRO_MOVIMTO = @vid_NRO_SEC_SALIDA					
				select @vd_fecha_movimto = @vd_fecha_movimto
											
				if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5')	
					begin
						if (@vis_tipo_salida='8')	
							begin
								select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
								select @vd_fecha_movimto = @vd_fecha_resol								
							END
						else if (@vis_tipo_salida='7')	
							begin
								select @vis_NRO_DOCUMENTO = @vis_nro_acta
								select @vd_fecha_movimto = @vd_fecha_acta
							END
						else if (@vis_tipo_salida='6')	
							begin
								select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
							END
						else if (@vis_tipo_salida='5')	
							begin
								select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
							END
					END
				else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1')	
					begin
						select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
					END
				else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3')	
					begin
						select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
					END				
		END						


       INSERT INTO SIG_SEGUIMIENTO (
              ANO_EJE,                
              SEC_EJEC,                     
              TIPO_TRANSACCION,
              NRO_ORIGEN,
              FECHA_TRANSACCION,      
              CENTRO_COSTO,                 
              SOLICITANTE,                              
              ESTADO_TRANSACCION,
              TIPO_CONSOLID,                                        
              TIPO_PPTO,                                
              TIPO_PEDIDO,
              TIPO_BIEN,			  
              NRO_TRANSACCION,              NRO_PEDIDO,
              FECHA_REG,              CUSER_ID,                     EQUIPO_REG)
       SELECT	B.ANO_EJE,              
       			B.SEC_EJEC,                   
       			@vid_Tipo_Transaccion,                   
              	COALESCE((SELECT MAX(A.NRO_ORIGEN) FROM SIG_SEGUIMIENTO A WHERE A.ANO_EJE = B.ANO_EJE AND A.SEC_EJEC = B.SEC_EJEC AND A.TIPO_TRANSACCION = @vid_Tipo_Transaccion),0) + 1,
		      	@vd_fecha_movimto,      
		      	B.centro_costo,               
		      	@vis_NRO_DOCUMENTO, /*B.empleado,	*/    
		      	B.ESTADO,
		      B.TIPO_MOVIMTO + convert(varchar(2),B.TIPO_TRANSAC),  COALESCE(B.TIPO_PPTO,1),                  B.TIPO_MOVIMTO,
              B.TIPO_BIEN,            B.NRO_MOVIMTO,                RIGHT( '000000' + CONVERT(VARCHAR(6),@vid_NRO_MOVIMTO),6),	
		      GETDATE(),              @vis_cuser_id,                @vis_equipo_reg	        					
         FROM INSERTED B
	
		
		select	@vid_nro_origen = A.nro_origen
		from sig_seguimiento A,
		     inserted B
		where A.ano_eje 	 = B.ano_eje 	     and
		      A.sec_ejec 	 = B.sec_ejec 	     and
		      A.nro_transaccion	 = B.nro_movimto and	
		      A.tipo_transaccion = @vid_Tipo_Transaccion AND
		      A.TIPO_CONSOLID = B.TIPO_MOVIMTO+convert(varchar(2),B.TIPO_TRANSAC)
	
		insert into sig_seguimiento_estado(
				ano_eje,
				sec_ejec,
				tipo_transaccion,
				nro_origen,
				sec_estado,
				fecha_estado,
				estado_seguimiento,
				fecha_reg,
				cuser_id,
				equipo_reg
				)	
		
		select A.ano_eje,
		       A.sec_ejec,
		       @vid_Tipo_Transaccion,
		       @vid_nro_origen,
		       coalesce((select max(sec_estado) 
			   from sig_seguimiento_estado
			   where ano_eje          = A.ano_eje 	  and               
			       sec_ejec	      = A.sec_ejec   and 
			         tipo_transaccion = @vid_Tipo_Transaccion  and
			         nro_origen       = @vid_nro_origen ),0)+1,
			   getdate(),
			   A.estado,
			   getdate(),
			   @vis_cuser_id,
			   @vis_equipo_reg
			   from inserted A    	 	
		       	
	end		
END
GO

CREATE TRIGGER [dbo].[tg_patrimonio_upd]
ON [dbo].[SIG_MOVIMIENTO_ACTIVO]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
	@vid_ejecutora   numeric(6),
	@vis_TIPO_INST    varchar(1),
	@vis_TIPO_MOVIMTO varchar(1), 
	@vid_tipo_trans  numeric(2),
	@vid_nro_origen  numeric(6),
	@vid_nro_trans   numeric(6),
	@vis_tipo_bien   char(1),
	@vis_tipo_ped    char(1),
	@vis_nro_ped	 char(5),	
	/* 22.04.00 RF-Todos - JAR - Inicio */
	--@vid_NRO_INGRESO numeric(5),
	@vid_NRO_INGRESO numeric(6),
	/* 22.04.00 RF-Todos - JAR - Fin */
	@vid_NRO_MOVIMTO numeric(6),
	@vis_NRO_RESOLUC  varchar(40),
	@vis_NRO_DOCUMENTO varchar(40),
	@vd_fecha_resol  DATETIME,
	@vd_fecha_movimto DATETIME,
	@vis_nro_convenio varchar(40),
	@vd_fecha_convenio DATETIME,
	@vid_NRO_SEC_SALIDA numeric(6),
	@vis_tipo_salida  varchar(2),
	@vis_nro_acta  varchar(40),
	@vd_fecha_acta  datetime,
	@vis_nro_doc_interno varchar(30),
	@vis_TIPO_TRANSAC varchar(2),
	@vid_NRO_SALIDA  numeric(6),
	@vis_FLAG_SALIDA varchar(1),
	@vis_estado      varchar(1),
	@vd_fecha_ped    datetime,
	@vd_fecha_apr    DATETIME,
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20),
	@vid_tipo_ppto	 numeric(1),
	@vis_NRO_ORDEN    varchar(7)

BEGIN

	select @vid_ano		 = ano_eje,
	       @vid_ejecutora	 = sec_ejec,
   	       @vis_TIPO_INST    = TIPO_INST,
   	       @vis_TIPO_MOVIMTO = TIPO_MOVIMTO ,
	       @vid_nro_trans    = NRO_MOVIMTO,
   	       @vid_NRO_INGRESO  = NRO_INGRESO,
   	       @vid_NRO_MOVIMTO  = NRO_MOVIMTO,
   	       @vis_NRO_RESOLUC  = NRO_RESOLUC,
   	       @vis_NRO_DOCUMENTO = NRO_DOCUMENTO,
   	       @vd_fecha_resol   = fecha_resol,
   	       @vd_fecha_movimto = fecha_movimto,
	       @vis_nro_convenio = nro_convenio, 
   	       @vd_fecha_convenio = fecha_convenio,
   	       @vid_NRO_SEC_SALIDA = NRO_SEC_SALIDA,
   		   @vis_nro_acta     = nro_acta,
  	       @vd_fecha_acta    = fecha_acta,
   	       @vis_nro_doc_interno= nro_doc_interno,
	       @vis_TIPO_TRANSAC = convert(varchar(2),TIPO_TRANSAC),
   	       @vid_NRO_SALIDA	 = COALESCE(NRO_SALIDA,0),
   	       @vis_FLAG_SALIDA  = COALESCE(FLAG_SALIDA,'0'),
	       @vis_TIPO_BIEN    = TIPO_BIEN,
   	       @vis_estado       = estado,
	       @vd_fecha_ped     = FECHA_MOVIMTO,
   		   @vis_tipo_salida  = tipo_salida,
           @vis_cuser_id     = CUSER_MOD,
           @vis_equipo_reg   = EQUIPO_MOD,
           @vid_tipo_ppto	 = tipo_ppto,
           @vis_NRO_ORDEN    = convert(varchar(7), INSERTED.NRO_ORDEN)
      FROM INSERTED


    IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
	BEGIN
        -- Datos de Sesión
        IF OBJECT_ID ('TEMPDB..#sig_sesion') IS NOT NULL
           SELECT @vis_cuser_id=   CUSER_ID,
                  @vis_equipo_reg= EQUIPO_REG
             FROM #SIG_SESION
    END
   

    UPDATE SIG_MOVIMIENTO_ACTIVO
       SET CUSER_MOD=  @vis_cuser_id,
           EQUIPO_MOD= @vis_equipo_reg,
           FECHA_MOD=  GETDATE()
     WHERE ANO_EJE     = @vid_ano        AND
           SEC_EJEC    = @vid_ejecutora  AND
           NRO_MOVIMTO = @vid_nro_trans 
   
	
	if (@vis_TIPO_INST = '1' AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0) 
		begin
			select @vid_tipo_trans = 31	
		end
	else if ((@vis_TIPO_INST = '2' OR @vis_TIPO_INST = '3' OR @vis_TIPO_INST = '4' OR @vis_TIPO_INST = '5' OR @vis_TIPO_INST = '6') AND @vis_TIPO_MOVIMTO ='I' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_tipo_trans = 32		
		end
	else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' AND @vis_FLAG_SALIDA='0' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_tipo_trans = 33		
		END
	else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' AND @vis_FLAG_SALIDA='0' AND (@vid_NRO_SALIDA=0 OR @vid_NRO_SEC_SALIDA<>0))	
		begin
			select @vid_tipo_trans = 34	-- Mantenimiento Activos
		END
	else if ((@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1' OR @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3') AND @vis_FLAG_SALIDA='1' AND @vid_NRO_SALIDA=0)	
		begin
			select @vid_tipo_trans = 35 -- Salidas
		END
	else 	
		begin
			select @vid_tipo_trans = 0		
		END	


    if ((update(NRO_ORDEN) OR update(NRO_RESOLUC) or update(fecha_resol) or update(nro_convenio) or update(fecha_convenio) or update(nro_acta) or update(fecha_acta) or update(nro_doc_interno) or update(estado)) AND @vid_tipo_trans <> 0)	
    BEGIN
    

	if @vid_tipo_trans = 32 
		BEGIN
			select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO	
			
			if @vis_tipo_inst = '2' OR @vis_tipo_inst = '4' OR @vis_tipo_inst = '5' OR @vis_tipo_inst = '6'
				begin
					select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
					select @vd_fecha_movimto = @vd_fecha_resol	
				END				
			else if @vis_tipo_inst = '3' 
				begin
					select @vis_NRO_DOCUMENTO = @vis_nro_convenio
					select @vd_fecha_movimto = @vd_fecha_convenio	
				END												
		END
				
	else if @vid_tipo_trans = 34 
		BEGIN
			select @vid_NRO_MOVIMTO = @vid_NRO_INGRESO
			IF(@vis_NRO_ORDEN IS NULL OR rtrim(@vis_NRO_ORDEN) = '')
				BEGIN
					SELECT @vis_NRO_DOCUMENTO = NULL
				END
			ELSE
				BEGIN
					SELECT @vis_NRO_DOCUMENTO = NRO_ORDEN FROM INSERTED
	    		END
		END
				
	else if @vid_tipo_trans = 35 
		begin	   
			select @vid_NRO_MOVIMTO = @vid_NRO_SEC_SALIDA					
			select @vd_fecha_movimto = @vd_fecha_movimto
										
			if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='S5')	
				begin
					if (@vis_tipo_salida='8')	
						begin
							select @vis_NRO_DOCUMENTO = @vis_NRO_RESOLUC
							select @vd_fecha_movimto = @vd_fecha_resol								
						END
					else if (@vis_tipo_salida='7')	
						begin
							select @vis_NRO_DOCUMENTO = @vis_nro_acta
							select @vd_fecha_movimto = @vd_fecha_acta
						END
					else if (@vis_tipo_salida='6')	
						begin
							select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
						END
					else if (@vis_tipo_salida='5')	
						begin
							select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
						END
				END
			else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T1')	
				begin
					select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
				END
			else if (@vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC='T3')	
				begin
					select @vis_NRO_DOCUMENTO = @vis_nro_doc_interno
				END				
		END	

	
	if not exists 
		(select 1
		 from sig_seguimiento
		 where ano_eje 	        = @vid_ano and
		       sec_ejec         = @vid_ejecutora and
		       nro_transaccion  = @vid_nro_trans and
		       tipo_transaccion = @vid_tipo_trans )
		begin
			insert into sig_seguimiento(		
	       		ano_eje, sec_ejec, tipo_transaccion,
		        nro_origen,
		        centro_costo, solicitante, tipo_ppto,
		        tipo_bien, tipo_pedido, nro_transaccion,
	      		nro_pedido, fecha_transaccion, 
	      		estado_transaccion, 
	   	        fecha_reg, cuser_id, equipo_reg, tipo_consolid)   

			select A.ano_eje, A.sec_ejec, @vid_tipo_trans,
			       coalesce((select max(B.nro_origen)
				from sig_seguimiento B
				where B.ano_eje 	 = @vid_ano	    and
				      B.sec_ejec 	 = @vid_ejecutora   and
				      B.tipo_transaccion = @vid_tipo_trans ),0)+1,
				A.centro_costo,	A.empleado, A.TIPO_PPTO,
				A.TIPO_BIEN, A.TIPO_MOVIMTO, A.NRO_MOVIMTO,				
				/* 22.04.00 RF-Todos - JAR - Inicio */
				--right('00000' + convert(varchar(6),A.NRO_MOVIMTO),5), A.FECHA_MOVIMTO, 
				right('000000' + convert(varchar(6),A.NRO_MOVIMTO),6), A.FECHA_MOVIMTO, 
				/* 22.04.00 RF-Todos - JAR - Fin */
				estado,
				getdate(), @vis_cuser_id, @vis_equipo_reg, @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC
			from inserted A	
		end 		
	
    if (@vid_tipo_trans = 32 OR @vid_tipo_trans = 34 OR @vid_tipo_trans = 35)
	    BEGIN
	    
		update sig_seguimiento 
		set solicitante         = @vis_NRO_DOCUMENTO,
		    fecha_transaccion   = @vd_fecha_movimto
		where  ano_eje       	= @vid_ano       and
		       sec_ejec      	= @vid_ejecutora and	 
		       nro_transaccion  = @vid_nro_trans and
		       tipo_transaccion = @vid_tipo_trans AND
		       tipo_consolid = @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC
		END
		

    if update(estado)	
	    BEGIN
	    
		update sig_seguimiento 
		set estado_transaccion  = @vis_estado
		where  ano_eje       	= @vid_ano       and
		       sec_ejec      	= @vid_ejecutora and	 
		       nro_transaccion  = @vid_nro_trans and
		       tipo_transaccion = @vid_tipo_trans AND
		       tipo_consolid = @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC		    
	    
		select @vid_nro_origen = nro_origen
		from sig_seguimiento
		where  ano_eje       	  = @vid_ano        and
		       sec_ejec      	  = @vid_ejecutora  and	 
		       nro_transaccion    = @vid_nro_trans  and
		       tipo_transaccion	  = @vid_tipo_trans AND
		       tipo_consolid = @vis_TIPO_MOVIMTO+@vis_TIPO_TRANSAC
	       	    
		insert into sig_seguimiento_estado(
			ano_eje, sec_ejec, tipo_transaccion,
			nro_origen, sec_estado,
			fecha_estado, 
			estado_seguimiento, 
			fecha_reg, cuser_id, equipo_reg)
		select B.ano_eje, B.sec_ejec, @vid_tipo_trans,
		       @vid_nro_origen,
		       coalesce((select max(C.sec_estado)
			from sig_seguimiento_estado C
			where C.ano_eje 	 = B.ano_eje	    and
			      C.sec_ejec 	 = B.sec_ejec   and
			      C.tipo_transaccion = @vid_tipo_trans  and
			      C.nro_origen	 = @vid_nro_origen),0)+1,
			@vd_fecha_ped, 
			b.estado, 
			getdate(), @vis_cuser_id, @vis_equipo_reg			    
		from deleted A
		inner join inserted B
		on A.ano_eje 		= B.ano_eje  and
		   A.sec_ejec 		= B.sec_ejec and
		   A.NRO_MOVIMTO	= B.NRO_MOVIMTO and
		   A.estado <> B.estado
		end
	end
end
GO


