-- Triggers structure for table SIG_PAAC_CONSOLIDADO
-- ----------------------------
CREATE TRIGGER [dbo].[sig_pao_upd]
ON [dbo].[SIG_PAAC_CONSOLIDADO]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
        @vid_ejecutora       numeric(6),
        @vis_tipo_con      char(1),
        @vid_nro_con      numeric(5),
        @vis_tipo_gen      char(1),
        @vi_tipo_ppto        numeric(1),
        @vid_tipo_trans      numeric(2),
        @vid_tipo_trans_ant  numeric(2),
        @vid_nro_origen      numeric(6),
        @vid_nro_trans       numeric(6),
        @vis_cuser_id                  varchar(30),
        @vis_equipo_reg                           varchar(20),
		@ls_estado           varchar(1),
		@ls_estado_ori       varchar(1),
        @ll_cont             NUMERIC(10)
BEGIN
 
SELECT @ll_cont = COUNT(1)
FROM    DELETED
 
IF @ll_cont <> 1
    RETURN
    
--Recuperamos Valores
select 
@vid_ano                    = ano_eje,
@vid_ejecutora              = sec_ejec,
@vis_tipo_con    = tipo_consolid,
@vid_nro_con = nro_consolid,
@vis_tipo_gen    = tipo_generacion,
@ls_estado       = ESTADO,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from inserted
 
/*obtengo el estado original*/
SELECT  @ls_estado_ori  = ESTADO
FROM    DELETED
 
/*si no ha cambiado el estado, salgo*/
IF @ls_estado_ori = @ls_estado
BEGIN
    RETURN
END
 
/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END
 
update sig_paac_consolidado 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
ano_eje              = @vid_ano       and
sec_ejec             = @vid_ejecutora and  
tipo_consolid   = @vis_tipo_con AND
nro_consolid     = @vid_nro_con and
tipo_generacion = @vis_tipo_gen 
 
                select @vid_tipo_trans      = 4
 
                if @vis_tipo_con = '3'
                   begin 
                    select @vi_tipo_ppto = 2
                    select @vid_tipo_trans_ant  = 16        
                   end
                else
                   begin
                    select @vi_tipo_ppto = 1        
                    select @vid_tipo_trans_ant  = 5          
                   end
 
                if update(estado) and (@vis_tipo_con = '3' or @vis_tipo_con = '2')
                begin
 
 
                if not exists(select *
                                     from sig_seguimiento
                                     where ano_eje     = @vid_ano              and 
                                                   sec_ejec    = @vid_ejecutora  and
                                                   tipo_pedido = @vis_tipo_con   and
                                                   nro_transaccion = @vid_nro_con )
                begin
                insert into sig_seguimiento(
                                 ano_eje,
                                 sec_ejec,
                                 tipo_transaccion,
                                 nro_origen,     
                                 fecha_transaccion,       
                                 centro_costo,
                                 solicitante,
                                 estado_transaccion,
                                 tipo_ppto,
                                 tipo_pedido,   
                                 tipo_bien,                        
                                 nro_transaccion,
                                 nro_pedido,
                                 fecha_reg,
                                 cuser_id,
                                 equipo_reg
                                 )
                select B.ano_eje,
                       B.sec_ejec,
                       @vid_tipo_trans,
                               (select (isnull(max(A.nro_origen),0)+1)
                               from sig_seguimiento A
                               where (A.ano_eje            = B.ano_eje ) and
                                      (A.sec_ejec                   = B.sec_ejec) and
                                      (A.tipo_transaccion = @vid_tipo_trans)),
                      B.fecha_cons,
                      null,
                      null, 
                      B.estado,
                      @vi_tipo_ppto,
                      B.tipo_consolid,
                      B.tipo_bien,                
                      B.nro_consolid,
                      convert(varchar(5),B.nro_consolid),
                      getdate(),
                      @vis_cuser_id,
                      @vis_equipo_reg                                                                                   
                 from  inserted B
                end       
 
 
                -- Recupera
                select    @vid_nro_origen = isnull(A.nro_origen,0)
                from sig_seguimiento A,
                     inserted B
                where A.ano_eje            = B.ano_eje           and
                      A.sec_ejec    = B.sec_ejec          and
                      A.tipo_pedido            = B.tipo_consolid   and
                      A.nro_transaccion    = B.nro_consolid    and
                      A.tipo_transaccion = @vid_tipo_trans           
                -- Inserta Estados
                if (@vid_nro_origen > 0)
                begin
                insert into sig_seguimiento_estado
                                               (
                                               ano_eje,
                                               sec_ejec,
                                               tipo_transaccion,
                                               nro_origen,
                                               sec_estado,
                                               fecha_estado,
                                               estado_seguimiento,
                                               fecha_reg,
                                               cuser_id,
                                               equipo_reg
                                               )
                
                select A.ano_eje,
                       A.sec_ejec,
                       @vid_tipo_trans,
                       @vid_nro_origen,
                       (select isnull(max(sec_estado),0) +1 
                               from sig_seguimiento_estado
                               where ano_eje                       = A.ano_eje                and               
                                     sec_ejec              = A.sec_ejec               and 
                                     tipo_transaccion = @vid_tipo_trans and
                                     nro_origen       = @vid_nro_origen ) ,
                               getdate(),
                               A.estado,
                               getdate(),
                               @vis_cuser_id,
                               @vis_equipo_reg
                               from inserted A               
                end
      end
end
GO

CREATE TRIGGER [dbo].[tg_estudio_mercado_upd]
ON [dbo].[SIG_PAAC_CONSOLIDADO]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vi_anio    numeric(4),
	@vi_ejecutora    numeric(6),
	@vs_tipo_con	 char(1),
	@vs_tipo_gen	 char(1),
	@vi_transaccion  numeric(2),
	@vi_trans_ant  	 numeric(2),
	@vi_nro_origen   numeric(6),
	@vi_nro_destino  numeric(6),
	@vi_nro_trans    numeric(6),
	@vi_nro_con      numeric(6),
	@vi_tipo_ppto    numeric(1),
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)

begin

select @vi_trans_ant = 4
select @vi_transaccion = 14
/*
Recuperamos Valores		
*/
select 
@vi_anio        = ano_eje ,
@vi_ejecutora   = sec_ejec,	
@vs_tipo_con    = tipo_consolid,
@vi_nro_con     = nro_consolid,
@vs_tipo_gen    = tipo_generacion,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from inserted

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

update sig_paac_consolidado 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
ano_eje     	= @vi_anio       and
sec_ejec    	= @vi_ejecutora and	 
tipo_consolid   = @vs_tipo_con AND
nro_consolid 	= @vi_nro_con and
tipo_generacion = @vs_tipo_gen 

	-- Tipo Ppto
	if @vs_tipo_con = '3'
	   begin
	     select @vi_tipo_ppto=2			
	   end
	else
	   begin
	     select @vi_tipo_ppto=1
	   end

    if exists( select 1
	from sig_seguimiento
	where ano_eje 	      = @vi_anio      and
	      sec_ejec 	      = @vi_ejecutora and
              tipo_pedido     = @vs_tipo_con  and
	      nro_transaccion = @vi_nro_con   and
	      tipo_bien	      = @vs_tipo_gen  and
	      tipo_transaccion= @vi_trans_ant)		
     begin

	select @vi_nro_origen = nro_origen
	from sig_seguimiento
	where ano_eje 	      = @vi_anio      and
	      sec_ejec 	      = @vi_ejecutora and
              tipo_pedido     = @vs_tipo_con  and
	      nro_transaccion = @vi_nro_con   and
	      tipo_bien	      = @vs_tipo_gen  and
	      tipo_transaccion= @vi_trans_ant

	
		
    if update(nro_est_mdo)	
	begin
	insert into sig_seguimiento( 
		ano_eje, sec_ejec, tipo_transaccion, nro_origen, 
		tipo_pedido, tipo_bien, nro_transaccion,centro_costo,
		nro_pedido, fecha_transaccion, estado_transaccion,tipo_ppto,
		fecha_reg, cuser_id, equipo_reg
		)
	select ano_eje, sec_ejec, @vi_transaccion,
		 (select (isnull(max(B.nro_origen),0)+1)
		  from sig_seguimiento B
		  where(B.ano_eje 	   = @vi_anio	   ) and
		       (B.sec_ejec 	   = @vi_ejecutora  ) and
		       (B.tipo_transaccion = @vi_transaccion )), '11706040402',
		tipo_consolid,tipo_generacion,nro_consolid,
		convert(varchar(5), nro_est_mdo), fecha_est_mdo, estado_est_mdo,@vi_tipo_ppto,
		getdate(), @vis_cuser_id, @vis_equipo_reg		
	from inserted

	-- Recupera Nro Destino
	select @vi_nro_destino = nro_origen
	from sig_seguimiento
	where ano_eje 	      = @vi_anio      and
	      sec_ejec        = @vi_ejecutora and
              tipo_pedido     = @vs_tipo_con  and
	      nro_transaccion = @vi_nro_con   and
	      tipo_bien	      = @vs_tipo_gen  and
	      tipo_transaccion= @vi_transaccion	
	
	-- Inserta en tabla secuencia	
	insert into sig_seguimiento_secuencia
	values( @vi_anio,
	       @vi_ejecutora,
	       @vi_transaccion,
	       @vi_nro_destino,	
	       @vi_trans_ant,
	       @vi_nro_origen)	
     end
   end	
end
GO

CREATE TRIGGER [dbo].[tg_pao_del]
ON [dbo].[SIG_PAAC_CONSOLIDADO]
WITH EXECUTE AS CALLER
FOR DELETE
AS
------------------------------------------------------
-- Autor : Jony Ancasi
-- Objeto: Cambio de tamaño de campo Pedido y PECOSA
-- Cambio:
--			PECOSA NUMERIC(6) x NUMERIC(5)
--			PEDIDO VARCHAR(6) x VARCHAR(5)
------------------------------------------------------

DECLARE
@ll_cur_nro_transaccion     NUMERIC(10),
@ll_tipo_transaccion        NUMERIC(10) = 4,
@ll_secuencia_max           NUMERIC(10),
@ll_cur_ano_eje             NUMERIC(4),
@ll_cur_sec_ejec            NUMERIC(6),
@ll_cur_tipo_ppto           NUMERIC(10),
@ll_segui_nro_origen        NUMERIC(10),
@ls_cur_tipo_pedido         VARCHAR(2),
@ls_tipo_movimiento         VARCHAR(1)  = 'D',
--@ls_cur_nro_pedido          VARCHAR(5)  = '0',
@ls_cur_nro_pedido          VARCHAR(6)  = '0',
@ls_cur_tipo_consolid       VARCHAR(1),
@ls_cur_estado_transaccion  VARCHAR(1),
@ls_cur_tipo_bien           VARCHAR(1),
@ls_cur_cuser_id            VARCHAR(30),
@ls_cur_equipo_reg          VARCHAR(20),
@ldt_cur_fecha_transaccion  DATETIME

BEGIN

DECLARE lcur_Borrados CURSOR FOR
SELECT
ANO_EJE,
SEC_EJEC,
CONVERT(VARCHAR(5), NRO_CONSOLID),
ESTADO,
FECHA_CONS,
TIPO_BIEN,
CUSER_MOD,
EQUIPO_MOD,
TIPO_CONSOLID,
NRO_CONSOLID
FROM DELETED

SELECT
@ll_cur_ano_eje             = ANO_EJE,
@ll_cur_sec_ejec            = SEC_EJEC,
--@ls_cur_nro_pedido          = CONVERT(VARCHAR(5), NRO_CONSOLID),
@ls_cur_nro_pedido          = CONVERT(VARCHAR(6), NRO_CONSOLID),
@ls_cur_estado_transaccion  = ESTADO,
@ldt_cur_fecha_transaccion  = FECHA_CONS,
@ls_cur_tipo_bien           = TIPO_BIEN,
@ls_cur_cuser_id            = CUSER_MOD,
@ls_cur_equipo_reg          = EQUIPO_MOD,
@ls_cur_tipo_pedido         = TIPO_CONSOLID,
@ll_cur_nro_transaccion     = NRO_CONSOLID
FROM DELETED

IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @ls_cur_cuser_id    = CUSER_ID,
                @ls_cur_equipo_reg  = EQUIPO_REG
        FROM    #SIG_SESION
    END

OPEN    lcur_Borrados 
WHILE   1 = 1
BEGIN
    FETCH   lcur_Borrados
    INTO    @ll_cur_ano_eje,
            @ll_cur_sec_ejec,
            @ls_cur_nro_pedido,
            @ls_cur_estado_transaccion,
            @ldt_cur_fecha_transaccion,
            @ls_cur_tipo_bien,
            @ls_cur_cuser_id,
            @ls_cur_equipo_reg,
            @ls_cur_tipo_pedido,
            @ll_cur_nro_transaccion
    IF  @@FETCH_STATUS <> 0
    BEGIN
        BREAK
    END

    SELECT  @ll_segui_nro_origen = NRO_ORIGEN
    FROM    SIG_SEGUIMIENTO
    WHERE   SEC_EJEC            = @ll_cur_sec_ejec
    AND     ANO_EJE             = @ll_cur_ano_eje
    AND     TIPO_TRANSACCION    = @ll_tipo_transaccion
    AND     NRO_TRANSACCION     = @ll_cur_nro_transaccion
    AND     TIPO_PEDIDO         = @ls_cur_tipo_pedido
    
    delete from sig_seguimiento_estado
    WHERE   SEC_EJEC            = @ll_cur_sec_ejec
    AND     ANO_EJE             = @ll_cur_ano_eje
    AND     TIPO_TRANSACCION    = @ll_tipo_transaccion
    AND     NRO_ORIGEN          = @ll_segui_nro_origen
    
    delete from sig_seguimiento_secuencia
    WHERE   SEC_EJEC            = @ll_cur_sec_ejec
    AND     ANO_EJE             = @ll_cur_ano_eje
    AND     TIPO_TRANSACCION    = @ll_tipo_transaccion
    AND     NRO_ORIGEN          = @ll_segui_nro_origen
    
    delete from sig_seguimiento    
    WHERE   SEC_EJEC            = @ll_cur_sec_ejec
    AND     ANO_EJE             = @ll_cur_ano_eje
    AND     TIPO_TRANSACCION    = @ll_tipo_transaccion
    AND     NRO_ORIGEN          = @ll_segui_nro_origen
    
    SELECT  @ll_secuencia_max   = COALESCE(MAX(SECUENCIA), 0) + 1
    FROM    SIG_AUDITORIA
    WHERE   ANO_EJE             = @ll_cur_ano_eje
    AND     SEC_EJEC            = @ll_cur_sec_ejec
    AND     TIPO_MOVIMIENTO     = @ls_tipo_movimiento
    
    INSERT  INTO    SIG_AUDITORIA(
                    ANO_EJE, SEC_EJEC, TIPO_MOVIMIENTO, SECUENCIA,
                    TIPO_TRANSACCION, NRO_ORIGEN, CENTRO_COSTO, SOLICITANTE,
                    TIPO_PPTO, TIPO_BIEN, TIPO_PEDIDO, NRO_PEDIDO,
                    NRO_CONSOLID, NRO_TRANSACCION, FECHA_TRANSACCION, ESTADO_TRANSACCION,
                    SEC_TRANSACCION, FECHA_REG, CUSER_ID, EQUIPO_REG,
                    TIPO_CONSOLID
                    )
    VALUES          (
                    @ll_cur_ano_eje, @ll_cur_sec_ejec, @ls_tipo_movimiento,   @ll_secuencia_max,
                    @ll_tipo_transaccion, NULL, NULL, NULL,
                    @ll_cur_tipo_ppto, @ls_cur_tipo_bien, @ls_cur_tipo_pedido, @ls_cur_nro_pedido,
                    NULL, CAST(@ls_cur_nro_pedido AS NUMERIC(10)), @ldt_cur_fecha_transaccion, @ls_cur_estado_transaccion,
                    NULL, GETDATE(), @ls_cur_cuser_id, @ls_cur_equipo_reg,
                    @ls_cur_tipo_consolid
                    )
END

CLOSE       lcur_Borrados
DEALLOCATE  lcur_Borrados

END
GO

CREATE TRIGGER [dbo].[TG_PAO_INS]
ON [dbo].[SIG_PAAC_CONSOLIDADO]
WITH EXECUTE AS CALLER
FOR INSERT
AS
DECLARE
@LN_vi_anio           NUMERIC(4),
@LN_vi_ejecutora      NUMERIC(6),
@LN_vi_nro_origen     NUMERIC(6),
@LN_vi_nro_destino    NUMERIC(6),
@LN_vi_sec_cuadro     NUMERIC(6),
@LN_vi_nro_cons       NUMERIC(5),
@LN_vs_tipo_consolid  VARCHAR(1),
@LN_vi_tipo_trans     NUMERIC(2),
@LN_vs_tipo_bien      VARCHAR(1),
@LN_vi_tipo_ppto      NUMERIC(1),
@ln_origen            NUMERIC(6),
@ln_secuencia         NUMERIC(2),
@ls_cur_estado          VARCHAR(1),
@ldt_cur_fecha_cons     DATETIME,
@ls_cuser_id	 	  VARCHAR(30),
@ls_equipo_reg	 	  VARCHAR(20)

BEGIN
/*4: PAO*/

SELECT
@LN_vi_tipo_trans       = 4,
@LN_vi_anio             = ano_eje,
@LN_vi_ejecutora        = sec_ejec,
@LN_vs_tipo_consolid    = tipo_consolid,
@LN_vi_nro_cons         = nro_consolid,
@LN_vs_tipo_bien        = tipo_bien,
@ldt_cur_fecha_cons     = FECHA_CONS,
@ls_cur_estado          = ESTADO,
@ls_cuser_id            = CUSER_ID,
@ls_equipo_reg          = EQUIPO_REG
FROM    INSERTED

IF @LN_vs_tipo_consolid = '3'
    BEGIN
        /*16: Compras por Encargo*/
        SELECT  @LN_vi_tipo_ppto = 2
    END
ELSE
    BEGIN
        /*5: Pedido Consolidado*/
        SELECT  @LN_vi_tipo_ppto = 1
    END

IF @LN_vs_tipo_consolid = '2' OR @LN_vs_tipo_consolid = '3'
BEGIN
    SELECT @ln_origen    = (COALESCE(MAX(nro_origen),0) + 1)
    FROM sig_seguimiento
    WHERE  ano_eje          = @LN_vi_anio  and
           sec_ejec         = @LN_vi_ejecutora and
           tipo_transaccion = @LN_vi_tipo_trans

    INSERT INTO sig_seguimiento(
    ano_eje,
    sec_ejec,
    tipo_transaccion,
    nro_origen,
    fecha_transaccion,
    centro_costo,
    solicitante,
    estado_transaccion,
    tipo_ppto,
    tipo_pedido,
    tipo_bien,
    nro_transaccion,
    nro_pedido,
    fecha_reg,
    cuser_id,
    equipo_reg
    )
    VALUES ( 
    @LN_vi_anio,
    @LN_vi_ejecutora,
    @LN_vi_tipo_trans,
    @ln_origen,
    @ldt_cur_fecha_cons,
    null,
    null,
    @ls_cur_estado,
    @LN_vi_tipo_ppto,
    @LN_vs_tipo_consolid,
    @LN_vs_tipo_bien,
    @LN_vi_nro_cons,
    LTRIM(RTRIM(CONVERT(VARCHAR(20), @LN_vi_nro_cons))),
    GETDATE(),
    @ls_cuser_id,
    @ls_equipo_reg )

    -- Recupera
    IF  (
        SELECT 1
        FROM sig_seguimiento A
        WHERE A.ano_eje   = @LN_vi_anio       AND
        A.sec_ejec     = @LN_vi_ejecutora         AND
        A.tipo_pedido  = @LN_vs_tipo_consolid    AND
        A.nro_transaccion  = @LN_vi_nro_cons AND
        A.tipo_transaccion = @LN_vi_tipo_trans
        ) > 0
        BEGIN    
            SELECT @LN_vi_nro_origen = A.nro_origen 
            FROM sig_seguimiento A
            WHERE A.ano_eje   = @LN_vi_anio       AND
            A.sec_ejec     = @LN_vi_ejecutora         AND
            A.tipo_pedido  = @LN_vs_tipo_consolid    AND
            A.nro_transaccion  = @LN_vi_nro_cons AND
            A.tipo_transaccion = @LN_vi_tipo_trans
        END
    ELSE
        BEGIN
            SELECT @LN_vi_nro_origen = 0
        END

    -- CORRELATIVO
    SELECT @ln_secuencia = COALESCE(max(sec_estado), 0) + 1
    FROM sig_seguimiento_estado
    WHERE ano_eje    = @LN_vi_anio     AND
    sec_ejec         = @LN_vi_ejecutora    AND
    tipo_transaccion = @LN_vi_tipo_trans AND
    nro_origen       = @LN_vi_nro_origen
    
    -- Inserta Estados
    INSERT INTO sig_seguimiento_estado
    (ano_eje,
    sec_ejec,
    tipo_transaccion,
    nro_origen,
    sec_estado,
    fecha_estado,
    estado_seguimiento,
    fecha_reg,
    cuser_id,
    equipo_reg
    )
    VALUES (
    @LN_vi_anio,
    @LN_vi_ejecutora,
    @LN_vi_tipo_trans,
    @LN_vi_nro_origen,
    @ln_secuencia ,
    GETDATE(),
    @ls_cur_estado,
    GETDATE(),
    @ls_cuser_id,
    @ls_equipo_reg
    )
END


END
GO


