-- ----------------------------
-- Triggers structure for table SIG_PPR_ESTABLECIMIENTO
-- ----------------------------
CREATE TRIGGER [dbo].[TG_SIG_PPR_ESTABLECIMIENTO_INS]
ON [dbo].[SIG_PPR_ESTABLECIMIENTO]
WITH EXECUTE AS CALLER
FOR INSERT
AS
DECLARE
@ls_cuser_id        VARCHAR(30),
@ls_equipo_reg      VARCHAR(20),
@ll_sec_ejec        NUMERIC(10),
@ll_ano_eje         NUMERIC(10),
@ll_nro_origen_max  NUMERIC(10)

BEGIN

/*obtengo datos del registro insertado*/
