-- ----------------------------
-- Triggers structure for table SIG_PPR_METFIS_X_SUBFIN
-- ----------------------------
CREATE TRIGGER [dbo].[TG_SIG_PPR_METFIS_X_SUBFIN_INS]
ON [dbo].[SIG_PPR_METFIS_X_SUBFIN]
WITH EXECUTE AS CALLER
FOR INSERT
AS
DECLARE
@ls_cuser_id        VARCHAR(30),
@ls_equipo_reg      VARCHAR(20),
@ll_sec_ejec        NUMERIC(10),
@ll_ano_eje         NUMERIC(10),
@ll_nro_origen_max  NUMERIC(10)

BEGIN

/*obtengo datos del registro insertado*/
SELECT  @ll_sec_ejec    = SEC_EJEC,
        @ll_ano_eje     = ANO_EJE,
        @ls_cuser_id    = CUSER_ID,
        @ls_equipo_reg  = EQUIPO_REG
FROM    INSERTED

/*obtengo los datos de la sesion*/
IF  OBJECT_ID('TEMPDB..#sig_sesion')    IS  NOT NULL
    BEGIN
        SELECT  @ls_cuser_id    = CUSER_ID,
                @ls_equipo_reg  = EQUIPO_REG
        FROM    #SIG_SESION
    END

/*obtengo el correlativo*/
/*
SELECT  @ll_nro_origen_max  = COALESCE(MAX(NRO_ORIGEN), 0) + 1
FROM    SIG_SEGUIMIENTO
WHERE   SEC_EJEC            = @ll_sec_ejec
AND     ANO_EJE             = @ll_ano_eje
AND     TIPO_TRANSACCION    = 51
*/

/*inserto el registro a seguimiento*/
/*
INSERT  SIG_SEGUIMIENTO(
        SEC_EJEC, ANO_EJE, TIPO_TRANSACCION, NRO_ORIGEN,
        CENTRO_COSTO, SOLICITANTE, TIPO_PPTO, TIPO_BIEN,
        TIPO_PEDIDO, TIPO_CONSOLID, NRO_TRANSACCION,
        NRO_PEDIDO,
        NRO_CONSOLID, FECHA_TRANSACCION, ESTADO_TRANSACCION, FECHA_REG,
        CUSER_ID, EQUIPO_REG, SEC_TRANSACCION
        )
SELECT  SEC_EJEC, ANO_EJE, 51, @ll_nro_origen_max,
        NULL, NULL, 1, NULL,
        NULL, NULL, NULL,
        (
        CONVERT(VARCHAR(20), NRO_FASE) + '-' +
        CONVERT(VARCHAR(20), SEC_FUNC) + '-' +
        CONVERT(VARCHAR(20), SEC_ESTABLEC) + '-' +
        SUB_FINALIDAD
        ),
        NULL, GETDATE(), '0', GETDATE(),
        @ls_cuser_id, @ls_equipo_reg, NULL
FROM    INSERTED
*/

/*actualizo los datos del registro insertado*/
UPDATE  SIG_PPR_METFIS_X_SUBFIN
SET     CUSER_ID    = @ls_cuser_id,
        FECHA_REG   = GETDATE(),
        EQUIPO_REG  = @ls_equipo_reg
WHERE   EXISTS      (
                    SELECT  1
                    FROM    INSERTED
                    WHERE   INSERTED.SEC_EJEC       = SIG_PPR_METFIS_X_SUBFIN.SEC_EJEC
                    AND     INSERTED.ANO_EJE        = SIG_PPR_METFIS_X_SUBFIN.ANO_EJE
                    AND     INSERTED.NRO_FASE       = SIG_PPR_METFIS_X_SUBFIN.NRO_FASE
                    AND     INSERTED.SEC_FUNC       = SIG_PPR_METFIS_X_SUBFIN.SEC_FUNC
                    AND     INSERTED.SEC_ESTABLEC   = SIG_PPR_METFIS_X_SUBFIN.SEC_ESTABLEC
                    AND     INSERTED.SUB_FINALIDAD  = SIG_PPR_METFIS_X_SUBFIN.SUB_FINALIDAD
                    )

END
GO

