CREATE TRIGGER [dbo].[tg_proceso_sec_del]
ON [dbo].[SIG_PROCESO_SECUENCIA]
WITH EXECUTE AS CALLER
FOR DELETE
AS
DECLARE
@vid_nro_origen             NUMERIC(6),
@vid_nro_proceso            NUMERIC(6),
@vid_sec_proceso            NUMERIC(6),
@ll_tipo_transaccion        NUMERIC(10),
@ll_secuencia_max           NUMERIC(10),
@ll_cur_ano_eje             NUMERIC(4),
@ll_cur_sec_ejec            NUMERIC(6),
@ll_cur_tipo_ppto           NUMERIC(10),
@ls_tipo_movimiento         VARCHAR(1)  = 'D',
@ls_cur_nro_pedido          VARCHAR(50)  = '0',
@ls_cur_estado_transaccion  VARCHAR(1),
@ls_cur_tipo_bien           VARCHAR(1),
@ls_cur_cuser_id            VARCHAR(30),
@ls_cur_equipo_reg          VARCHAR(20),
@ls_cur_tipo_pedido         VARCHAR(2),
@ldt_cur_fecha_transaccion  DATETIME

BEGIN

SELECT
@ll_cur_ano_eje     = ANO_EJE,
@ll_cur_sec_ejec    = SEC_EJEC,
@ls_cur_tipo_pedido = tipo_generacion,
@vid_nro_proceso    = proceso,
@vid_sec_proceso    = sec_proceso,
@ls_cur_cuser_id    = CUSER_MOD,
@ls_cur_equipo_reg  = EQUIPO_MOD,
@ls_cur_nro_pedido  = right('0000'+ltrim(rtrim(convert(varchar(20), nro_proceso))),4) + '-' + 
                        right('0000'+ltrim(rtrim(convert(varchar(20), ano_proceso))),4)
FROM    DELETED

SELECT
@ls_cur_estado_transaccion  = ESTADO,
@ldt_cur_fecha_transaccion  = FECHA_REG,
@ls_cur_tipo_bien           = TIPO_BIEN,
@ll_cur_tipo_ppto           = TIPO_PPTO
FROM    SIG_PROCESO_DE_SELECCION
WHERE   ANO_EJE             = @ll_cur_ano_eje
AND     SEC_EJEC            = @ll_cur_sec_ejec
AND     TIPO_GENERACION     = @ls_cur_tipo_pedido
AND     PROCESO             = @vid_nro_proceso

--si existe la tabla de sesion, saco de ahi los datos
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @ls_cur_cuser_id    = CUSER_ID,
                @ls_cur_equipo_reg  = EQUIPO_REG
        FROM    #SIG_SESION
    END

SELECT  @ll_tipo_transaccion    = 6

select @vid_nro_origen = A.nro_origen
from sig_seguimiento A
where A.ano_eje 	   = @ll_cur_ano_eje 	    and
      A.sec_ejec	   = @ll_cur_sec_ejec and
      A.tipo_pedido	   = @ls_cur_tipo_pedido   and
      A.nro_transaccion    = @vid_nro_proceso and
      A.sec_transaccion    = @vid_sec_proceso and
      A.tipo_transaccion   = @ll_tipo_transaccion

delete from sig_seguimiento_estado
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @ll_tipo_transaccion and
      nro_origen 	= @vid_nro_origen 

delete from sig_seguimiento_secuencia
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @ll_tipo_transaccion and
      nro_origen 	= @vid_nro_origen 

delete from sig_seguimiento	
where ano_eje 		= @ll_cur_ano_eje 	  and
      sec_ejec 		= @ll_cur_sec_ejec  and
      tipo_transaccion	= @ll_tipo_transaccion and
      nro_origen 	= @vid_nro_origen

/*obtengo el secuencial de auditoria*/
SELECT  @ll_secuencia_max   = COALESCE(MAX(SECUENCIA), 0) + 1
FROM    SIG_AUDITORIA
WHERE   ANO_EJE             = @ll_cur_ano_eje
AND     SEC_EJEC            = @ll_cur_sec_ejec
AND     TIPO_MOVIMIENTO     = @ls_tipo_movimiento

INSERT  INTO    SIG_AUDITORIA(
                ANO_EJE, SEC_EJEC, TIPO_MOVIMIENTO, SECUENCIA,
                TIPO_TRANSACCION, NRO_ORIGEN, CENTRO_COSTO, SOLICITANTE,
                TIPO_PPTO, TIPO_BIEN, TIPO_PEDIDO, NRO_PEDIDO,
                NRO_CONSOLID, NRO_TRANSACCION, FECHA_TRANSACCION, ESTADO_TRANSACCION,
                SEC_TRANSACCION, FECHA_REG, CUSER_ID, EQUIPO_REG,
                TIPO_CONSOLID
                )
VALUES          (
                @ll_cur_ano_eje, @ll_cur_sec_ejec, @ls_tipo_movimiento,	@ll_secuencia_max,
                @ll_tipo_transaccion, NULL, NULL, NULL,
                @ll_cur_tipo_ppto, @ls_cur_tipo_bien, @ls_cur_tipo_pedido, @ls_cur_nro_pedido,
                NULL, NULL, @ldt_cur_fecha_transaccion, @ls_cur_estado_transaccion,
                NULL, GETDATE(), @ls_cur_cuser_id, @ls_cur_equipo_reg,
                NULL
                )

END
GO

CREATE TRIGGER [dbo].[tg_proceso_sec_ins]
ON [dbo].[SIG_PROCESO_SECUENCIA]
WITH EXECUTE AS CALLER
FOR INSERT
AS
declare @vid_tipo_trans numeric(2),
	@vid_nro_origen numeric(6),
	@vid_ano        numeric(4),
	@vid_ejecutora  numeric(6),
	@vis_tipo_cons  varchar(1),
	@vid_nume_cons  numeric(6),
	@vis_tipo_gene  varchar(1),
	@vid_tipo_trans_ant numeric(2),
	@vid_nro_destino    numeric(6),
	@vid_proceso     numeric(5),
	@vid_sec_proceso numeric(4),
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)		

begin
         
	select @vid_tipo_trans = 6
	select @vid_tipo_trans_ant = 4

	select @vid_ano		 = A.ano_eje,
	       @vid_ejecutora	 = A.sec_ejec,
	       @vis_tipo_cons    = A.tipo_consolid,
	       @vid_nume_cons	 = A.nro_consolid,
	       @vis_tipo_gene    = A.tipo_generacion,
	       @vid_proceso  	 = B.proceso,
	       @vid_sec_proceso	 = B.sec_proceso,
	       @vis_cuser_id	 = B.cuser_id,
	       @vis_equipo_reg	 = B.equipo_reg
	  from sig_proceso_de_seleccion A,
	       inserted B
	 where  A.ano_eje  = B.ano_eje and
		A.sec_ejec = B.sec_ejec and
		A.tipo_generacion = B.tipo_generacion and
		A.proceso  = B.proceso

	insert into sig_seguimiento(
		  ano_eje,
		  sec_ejec,
		  tipo_transaccion,
		  nro_origen,
		  nro_transaccion,
		  sec_transaccion,
		  fecha_transaccion,
		  centro_costo,
		  solicitante,
		  estado_transaccion,
		  tipo_ppto,
		  tipo_bien,
		  tipo_pedido,
		  nro_pedido,
		  fecha_reg,
		  cuser_id,
		  equipo_reg
		  )
	select B.ano_eje,
	       B.sec_ejec,
	       @vid_tipo_trans,
		(select (isnull(max(A.nro_origen),0)+1)
		 from sig_seguimiento A
		 where (A.ano_eje 	   = B.ano_eje ) and
		       (A.sec_ejec 	   = B.sec_ejec) and
		       (A.tipo_transaccion = @vid_tipo_trans)  ),
	      B.proceso,
	      B.sec_proceso,
	      B.fecha_secuencia,
	      null,
	      null,	
	      B.estado,
	      A.tipo_ppto,
	      A.tipo_bien,
	      B.tipo_generacion,
	      (SELECT descripcion_abreviada
		from sig_maestro_proceso
		where ano_eje = B.ano_eje and
			tipo_organismo = B.tipo_organismo and
			codigo = 'TIPO_PROCESO' and
			codigo_det = B.tipo_proceso )+'-'+right('0000'+convert(varchar, B.nro_proceso),4)+'-'+right('0000'+convert(varchar,B.ano_proceso),4),	
	      getdate(),
	      @vis_cuser_id,
	      @vis_equipo_reg
	from  sig_proceso_de_seleccion A,
		inserted B
	 where A.ano_eje = B.ano_eje and
		A.sec_ejec = B.sec_ejec and
		A.tipo_generacion = B.tipo_generacion and
		A.proceso = B.proceso

	select	@vid_nro_origen = A.nro_origen
	from sig_seguimiento A,
	     inserted B
	where A.ano_eje 	= B.ano_eje and
	      A.sec_ejec 	= B.sec_ejec and
	      A.tipo_pedido	= B.tipo_generacion and
	      A.nro_transaccion = B.proceso and
	      A.sec_transaccion = B.sec_proceso and
	      A.tipo_transaccion = @vid_tipo_trans

	-- Registra en la tala sig_seguimiento_estado
	insert into sig_seguimiento_estado(
			ano_eje,
			sec_ejec,
			tipo_transaccion,
			nro_origen,
			sec_estado,
			fecha_estado,
			estado_seguimiento,
			fecha_reg,
			cuser_id,
			equipo_reg
			)	
	select A.ano_eje,
	       A.sec_ejec,
	       @vid_tipo_trans,
	       @vid_nro_origen,
	       (select isnull(max(sec_estado),0) + 1
		from sig_seguimiento_estado
		where ano_eje  	       = A.ano_eje 	and               
		      sec_ejec	       = A.sec_ejec 	and 
		      tipo_transaccion = @vid_tipo_trans and
		      nro_origen       = @vid_nro_origen ) ,
		getdate(),
		A.estado,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg
		from inserted A  	 	

	 select @vid_nro_destino = nro_origen
	   from sig_seguimiento
	  where ano_eje     = @vid_ano 	and
		sec_ejec    = @vid_ejecutora	and
	       	tipo_pedido = @vis_tipo_cons	and
		tipo_transaccion = @vid_tipo_trans_ant  and
		nro_transaccion  = @vid_nume_cons

	-- Inserta en tabla secuencia
	if (@vid_nro_origen > 0  ) and (@vid_nro_destino > 0 )
	begin
		if not exists 
		     (select *
			from sig_seguimiento_secuencia
		    	where 
			ano_eje     = @vid_ano       and
			sec_ejec    = @vid_ejecutora and
			tipo_transaccion   = @vid_tipo_trans and
			nro_origen = @vid_nro_origen  and
			tipo_transaccion_destino  = @vid_tipo_trans_ant   and
			nro_destino = @vid_nro_destino )
			begin
				insert into sig_seguimiento_secuencia
				(
				 ano_eje,
				 sec_ejec,
				 tipo_transaccion, 
				 nro_origen,
				 tipo_transaccion_destino,
				 nro_destino )
				values	
				(@vid_ano,
				 @vid_ejecutora,
				 @vid_tipo_trans, 
				 @vid_nro_origen,
				 @vid_tipo_trans_ant,
				 @vid_nro_destino)
			end
	end
end
GO

CREATE TRIGGER [dbo].[tg_proceso_sec_upd]
ON [dbo].[SIG_PROCESO_SECUENCIA]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
	@vid_ejecutora   numeric(6),
	@vid_tipo_trans  numeric(2),
	@vid_nro_origen  numeric(6),
	@vis_tip_gen     char(1),
	@vid_nro_proceso numeric(6),
	@vid_sec_proceso numeric(6),
	@vis_estado	 	 char(1),
    @ls_estado_ori  varchar(1),
	@vis_cuser_id	 varchar(30),
	@vis_equipo_reg	 varchar(20)	

select 
@vid_ano		 = ano_eje,
@vid_ejecutora	 = sec_ejec,
@vis_tip_gen 	 = tipo_generacion,
@vid_nro_proceso = proceso,
@vid_sec_proceso = sec_proceso,
@vis_estado      = estado,
@vis_cuser_id   = CUSER_MOD,
@vis_equipo_reg = EQUIPO_MOD
from  inserted

/*fact: si no se actualiza las campos mod, los actualizo de la sesion*/
IF  OBJECT_ID('tempdb..#SIG_SESION') IS  NOT NULL
    BEGIN
        SELECT  @vis_cuser_id   = CUSER_ID,
                @vis_equipo_reg = EQUIPO_REG
        FROM    #SIG_SESION
    END

update sig_proceso_secuencia 
set CUSER_MOD = @vis_cuser_id,
    EQUIPO_MOD = @vis_equipo_reg,
    FECHA_MOD  = getdate()
where  
ano_eje     = @vid_ano       and
sec_ejec    = @vid_ejecutora and	 
tipo_generacion   = @vis_tip_gen AND
proceso 	= @vid_nro_proceso and
sec_proceso = @vid_sec_proceso 

/*obtengo el estado original*/
SELECT  @ls_estado_ori  = ESTADO
FROM    DELETED

/*si no ha cambiado el estado, salgo*/
IF @ls_estado_ori = @vis_estado
BEGIN
    RETURN
END

if update(estado)
begin
	select @vid_tipo_trans = 6

	if not exists 
	   	(select *
	    	from sig_seguimiento
	    	where 
		ano_eje     = @vid_ano       and
		sec_ejec    = @vid_ejecutora and
		tipo_pedido = @vis_tip_gen   and
		nro_transaccion  = @vid_nro_proceso and
		sec_transaccion  = @vid_sec_proceso and
		tipo_transaccion = @vid_tipo_trans )
	begin
		insert into sig_seguimiento(
			  ano_eje,
			  sec_ejec,
			  tipo_transaccion,
			  nro_origen,
			  nro_transaccion,
			  sec_transaccion,
			  fecha_transaccion,
			  centro_costo,
			  solicitante,
			  estado_transaccion,
			  tipo_ppto,
			  tipo_bien,
			  tipo_pedido,
			  nro_pedido,
			  fecha_reg,
			  cuser_id,
			  equipo_reg
			  )
		select B.ano_eje,
		       B.sec_ejec,
		       @vid_tipo_trans,
			(select (isnull(max(A.nro_origen),0)+1)
			 from sig_seguimiento A
			 where (A.ano_eje 	   = B.ano_eje ) and
			       (A.sec_ejec 	   = B.sec_ejec) and
			       (A.tipo_transaccion = @vid_tipo_trans)  ),
		      B.proceso,
		      B.sec_proceso,
		      B.fecha_secuencia,
		      null,
		      null,	
		      B.estado,
		      A.tipo_ppto,
		      A.tipo_bien,
		      B.tipo_generacion,
		      (SELECT descripcion_abreviada
			from sig_maestro_proceso
			where ano_eje = B.ano_eje and
				tipo_organismo = B.tipo_organismo and
				codigo = 'TIPO_PROCESO' and
				codigo_det = B.tipo_proceso )+'-'+right('0000'+convert(varchar, B.nro_proceso),4)+'-'+right('0000'+convert(varchar,B.ano_proceso),4),
		      getdate(),
		      @vis_cuser_id,
		      @vis_equipo_reg
		from  sig_proceso_de_seleccion A,
			inserted B
		where A.ano_eje = B.ano_eje and
			A.sec_ejec = B.sec_ejec and
			A.tipo_generacion = B.tipo_generacion and
			A.proceso = B.proceso 
	end

	select	@vid_nro_origen = A.nro_origen
	from sig_seguimiento A,
	     inserted B
	where A.ano_eje 	= B.ano_eje  and
	      A.sec_ejec 	= B.sec_ejec and
	      A.tipo_pedido	= B.tipo_generacion and
	      A.nro_transaccion = B.proceso and
	      A.sec_transaccion = B.sec_proceso and
	      A.tipo_transaccion = @vid_tipo_trans 
	 
	-- Actualiza el seguimiento
	update sig_seguimiento 
	set estado_transaccion = @vis_estado,
		nro_pedido =  (SELECT A.descripcion_abreviada++'-'+right('0000'+convert(varchar, B.nro_proceso),4)+'-'+right('0000'+convert(varchar,B.ano_proceso),4)
				from sig_maestro_proceso A,
				     inserted B
				  where A.ano_eje = B.ano_eje and
					A.tipo_organismo = B.tipo_organismo and
					A.codigo = 'TIPO_PROCESO' and
					A.codigo_det = B.tipo_proceso ),
		fecha_transaccion = (select B.fecha_secuencia from inserted B)
	where  
	ano_eje          = @vid_ano        and
       	sec_ejec         = @vid_ejecutora  and	 
	tipo_transaccion = @vid_tipo_trans and
	nro_origen       = @vid_nro_origen

	-- Registra en la tabla sig_seguimiento_estado
	insert into sig_seguimiento_estado
	(
		ano_eje,
		sec_ejec,
		tipo_transaccion,
		nro_origen,
		sec_estado,
		fecha_estado,
		estado_seguimiento,
		fecha_reg,
		cuser_id,
		equipo_reg
	)
	select 
		A.ano_eje,
	       	A.sec_ejec,
	       	@vid_tipo_trans,
	       	@vid_nro_origen,
	      	(select (isnull(max(C.sec_estado),0)+1)
			from sig_seguimiento_estado C
			where(C.ano_eje 	 = @vid_ano	   ) and
			     (C.sec_ejec 	 = @vid_ejecutora  ) and
			     (C.tipo_transaccion = @vid_tipo_trans ) and
			     (C.nro_origen	 = @vid_nro_origen)),
	       	getdate(),
	       	B.estado,		
	       	getdate(),
	       	@vis_cuser_id,
	       	@vis_equipo_reg
	from deleted A
	inner join inserted B
	on A.ano_eje 		= B.ano_eje  and
   	A.sec_ejec 		= B.sec_ejec and
   	A.tipo_generacion	= B.tipo_generacion and
   	A.proceso		= B.proceso and
   	A.estado <> B.estado
	
end
GO


