-- ----------------------------
-- Triggers structure for table SIG_PROY_PEDIDOS
-- ----------------------------
CREATE TRIGGER [dbo].[tg_pedido_viatico_del]
ON [dbo].[SIG_PROY_PEDIDOS]
WITH EXECUTE AS CALLER
FOR DELETE
AS
declare @vid_ano         numeric(4),
	    @vid_ejecutora   numeric(6),
	    @vid_tipo_trans  numeric(2),
	    @vid_nro_origen  numeric(6),
	    @vid_sec_pedido	 numeric(6),
        @vs_CUser        varchar(30),
        @vs_Equipo       varchar(20),
        @vis_nro_pedido  varchar(50),
        @vn_Nro_Secuencia numeric(6),
        @vis_centro_costo varchar(15) 

BEGIN
	-- Inicializando Variables
	SELECT @vid_ano		   = B.ano_ejec,
	       @vid_ejecutora  = B.sec_ejec,
       	   @vid_sec_pedido = B.sec_pedido ,
       	   @vis_centro_costo = B.centro_costo      
      FROM deleted B
             	
	
    -- Datos de Sesión
	IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
	   SELECT @vs_CUser  = CUSER_ID,
		 @vs_Equipo = EQUIPO_REG
	     FROM #SIG_SESION
	ELSE
	   SELECT @vs_CUser  = CUSER_MOD, 
	          @vs_Equipo = EQUIPO_MOD
	     FROM DELETED
	
	--Tipo de Transacción
	SELECT @vid_tipo_trans = 10
	SELECT @vis_nro_pedido = replicate('0',5 - len(@vid_sec_pedido)) + CAST(@vid_sec_pedido AS VARCHAR)

	
    -- Auditoria: Eliminación de Documento  
    SELECT @vn_Nro_Secuencia= COALESCE(MAX(Coalesce(SECUENCIA,0)),0) + 1
	     FROM SIG_AUDITORIA
	    WHERE ANO_EJE         = @vid_ano   AND
		      SEC_EJEC        = @vid_ejecutora  AND
		      TIPO_MOVIMIENTO = 'D'       
           
       
    INSERT INTO SIG_AUDITORIA
			(ano_eje     , sec_ejec          , tipo_movimiento , secuencia	 ,	 tipo_transaccion , centro_costo,  		tipo_ppto   , 
			 tipo_pedido 	, nro_pedido 	 , nro_transaccion, fecha_transaccion, estado_transaccion,	fecha_reg  , 
			 cuser_id	 , equipo_reg )
    SELECT @vid_ano	 	  , @vid_ejecutora   , 'D'             , @vn_Nro_Secuencia,@vid_tipo_trans, @vis_centro_costo,     1    , 
	   	   @vid_tipo_trans, @vis_nro_pedido  , @vid_sec_pedido , FECHA_PEDIDO       , ESTADO , 		GETDATE()   , 
	   	   @vs_CUser  , @vs_Equipo
      FROM DELETED
    
        
    -- Eliminación de Registros
	SELECT @vid_nro_origen = A.nro_origen
	  FROM sig_seguimiento A
	 WHERE A.ano_eje 	      = @vid_ano 	    and
  	       A.sec_ejec	      = @vid_ejecutora  and
	       A.nro_transaccion  = @vid_sec_pedido and		
	       A.tipo_transaccion = @vid_tipo_trans
	
	DELETE FROM sig_seguimiento_estado
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen 	    = @vid_nro_origen 
	
	DELETE FROM sig_seguimiento_secuencia
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen 	    = @vid_nro_origen 
	
	DELETE FROM sig_seguimiento	
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen     	= @vid_nro_origen 
END
GO

CREATE TRIGGER [dbo].[tg_pedido_viatico_ins]
ON [dbo].[SIG_PROY_PEDIDOS]
WITH EXECUTE AS CALLER
FOR INSERT
AS
declare @vid_tipo_trans numeric(2),
	@vid_nro_origen numeric(6),
	@vid_ano	numeric(4),
	@vid_ejecutora	numeric(6),
	@vis_sec_ped	numeric(6),		
	@vid_sid        numeric(4),	
	@vis_cuser_id	varchar(30),
	@vis_equipo_reg	varchar(20)	
BEGIN
	-- Inicializando Variables
	SELECT @vid_ano		   = B.ano_ejec  ,
	       @vid_ejecutora  = B.sec_ejec  ,
	       @vis_sec_ped    = B.sec_pedido, 
	       @vis_cuser_id   = B.cuser_id  ,
	       @vis_equipo_reg = B.equipo_reg
	  FROM inserted B
	
	-- Tipo de Transacción
	select @vid_tipo_trans = 10
    
	-- Registra Seguimiento de Documento
	INSERT INTO sig_seguimiento
                (ano_eje,
		         sec_ejec,
		         tipo_transaccion,
		         nro_origen,	
		         nro_transaccion,		
		         fecha_transaccion,	
		         centro_costo,
		         solicitante,
		         estado_transaccion,
		         tipo_ppto,
		         tipo_bien,
		         tipo_pedido,		
		         nro_pedido,
		         fecha_reg,
		         cuser_id,
		         equipo_reg)
	     SELECT B.ano_ejec,
	            B.sec_ejec,
	            @vid_tipo_trans,
		        (SELECT (isnull(max(A.nro_origen),0)+1)
		           FROM sig_seguimiento A
		          WHERE A.ano_eje  = B.ano_ejec and
		                A.sec_ejec = B.sec_ejec and
		                A.tipo_transaccion = @vid_tipo_trans),
	            B.sec_pedido,
	            B.fecha_pedido,
	            B.centro_costo,
	            B.empleado,	
	            B.estado,
	            B.tipo_ppto,
	            'V' as tipo_bien,
	            B.tipo_pedido,
	            convert(varchar(7), B.sec_pedido_proy),
	            getdate(),
	            @vis_cuser_id,
	            @vis_equipo_reg	        					
	       FROM inserted B

	SELECT @vid_nro_origen = A.nro_origen
	  FROM sig_seguimiento A,
	       inserted B
	 WHERE A.ano_eje          = B.ano_ejec   and
	       A.sec_ejec         = B.sec_ejec   and
	       A.nro_transaccion  = B.sec_pedido and
	       A.tipo_transaccion = @vid_tipo_trans	
    
	INSERT INTO sig_seguimiento_estado
                (ano_eje,
		         sec_ejec,
		         tipo_transaccion,
		         nro_origen,
		         sec_estado,
		         fecha_estado,
		         estado_seguimiento,
		         fecha_reg,
		         cuser_id,
		         equipo_reg)	
	     SELECT A.ano_ejec,
	            A.sec_ejec,
	            @vid_tipo_trans,
	            @vid_nro_origen,
	            (SELECT isnull(max(sec_estado),0) +1 
		           FROM sig_seguimiento_estado
		          WHERE ano_eje          = A.ano_ejec 	   and               
		                sec_ejec         = A.sec_ejec 	   and 
		                tipo_transaccion = @vid_tipo_trans and
		                nro_origen       = @vid_nro_origen ) ,
		        getdate(),
		        A.estado,
		        getdate(),
		        @vis_cuser_id,
		        @vis_equipo_reg
		   FROM inserted A
END
GO

CREATE TRIGGER [dbo].[tg_pedido_viatico_upd]
ON [dbo].[SIG_PROY_PEDIDOS]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano         numeric(4),
        @vid_ejecutora   numeric(6),
        @vid_tipo_trans  numeric(2),
        @vid_nro_trans   numeric(6),
        @vid_nro_origen  numeric(6),
        @vis_est_trans   char(1),
        @vid_sec_pedido  numeric(6),
        @vd_fecha_ped    DATETIME,
	    @vis_cuser_id	 varchar(30),
	    @vis_equipo_reg	 varchar(20)            

BEGIN
    SELECT @vid_ano       = ano_ejec,
           @vid_ejecutora = sec_ejec,
           @vid_nro_trans = sec_pedido,
           @vis_est_trans = estado,
           @vd_fecha_ped  = fecha_pedido
      FROM inserted 

	--Usuario Sesión
     IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
           SELECT @vis_cuser_id   = CUSER_ID,
                  @vis_equipo_reg = EQUIPO_REG
             FROM #SIG_SESION
      ELSE
           SELECT @vis_cuser_id   = CUSER_MOD,
                  @vis_equipo_reg = EQUIPO_MOD
             FROM INSERTED
		
		
	  IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
	  BEGIN
		UPDATE sig_proy_pedidos 
		   SET CUSER_MOD  = @vis_cuser_id,
			   EQUIPO_MOD = @vis_equipo_reg,
			   FECHA_MOD  = getdate()
		 WHERE ano_ejec   = @vid_ano       and
			   sec_ejec   = @vid_ejecutora and	 
			   sec_pedido = @vid_nro_trans
      END
	
    -- Tipo de Transacción
    SELECT @vid_tipo_trans = 10
    
    -- Valida Actualización de ESTADO
	IF NOT UPDATE(estado)
	   RETURN
	
	--
    SELECT @vid_nro_origen = nro_origen
      FROM sig_seguimiento
     WHERE ano_eje          = @vid_ano        and
           sec_ejec         = @vid_ejecutora  and 
           nro_transaccion  = @vid_nro_trans  and
           tipo_transaccion = @vid_tipo_trans
	
    UPDATE sig_seguimiento 
       SET fecha_transaccion  = @vd_fecha_ped  ,
              estado_transaccion = @vis_est_trans
     WHERE ano_eje          = @vid_ano       and
           sec_ejec         = @vid_ejecutora and    
           nro_transaccion  = @vid_nro_trans and
           tipo_transaccion = @vid_tipo_trans              
	
    INSERT INTO sig_seguimiento_estado
                (ano_eje, sec_ejec, tipo_transaccion,
                 nro_origen, sec_estado,
                 fecha_estado, estado_seguimiento, fecha_reg,
                 cuser_id, equipo_reg)
         SELECT A.ano_ejec, A.sec_ejec, @vid_tipo_trans,
                @vid_nro_origen,
        (SELECT (COALESCE(MAX(Coalesce(C.sec_estado,0)),0) + 1)
                   FROM sig_seguimiento_estado C
                  WHERE C.ano_eje          = @vid_ano        and
                        C.sec_ejec         = @vid_ejecutora  and
                        C.tipo_transaccion = @vid_tipo_trans and
                        C.nro_origen       = @vid_nro_origen),        
                getdate(), B.estado, getdate(),
                @vis_cuser_id, @vis_equipo_reg                                      
           FROM deleted A
           INNER JOIN inserted B
           on A.ano_ejec   = B.ano_ejec   and
              A.sec_ejec   = B.sec_ejec   and
              A.sec_pedido = B.sec_pedido and
              A.estado 	  <> B.estado
END
GO


