CREATE TRIGGER [dbo].[tg_planilla_viatico_del]
ON [dbo].[SIG_PROY_PLANILLA_PASAJE]
WITH EXECUTE AS CALLER
FOR DELETE
AS
DECLARE @vid_ano              numeric(4) ,
        @vid_ejecutora        numeric(6) ,
        @vid_tipo_trans       numeric(2) ,
        @vid_nro_origen       numeric(6) ,
        @vis_NRO_PLANILLA     varchar(15),
        @vis_NRO_ORDEN_PASAJE varchar(15), 	
        @vis_tipo_opcion      varchar(1) ,
        @vs_CUser             varchar(30) ,
        @vs_Equipo            varchar(20),
        @vn_Nro_Secuencia     numeric(6), 
        @vn_nro_trans		  numeric(6),
        @vd_FECHA_PVI		  DATETIME,
 		@vd_FECHA_OP		  DATETIME,
 		@vis_tipo_bien        varchar(1) ,
 		@vis_ESTADO_PVI 	  varchar(1) ,
		@vis_ESTADO_OP 	  	  varchar(1) ,
		@vis_centro_costo 	  varchar(15) ,
		@vd_fecha 			  DATETIME ,
		@vis_estado			  varchar(1),
		@vn_sec_pedido		  NUMERIC(6) 
 
BEGIN
	-- Inicializando Variables (Tipo Opcion: [O: Orden pasaje]/[P: Planilla Viáticos])
	SELECT @vid_ano		     = B.ano_ejec,
	       @vid_ejecutora	 = B.sec_ejec,
	       @vis_NRO_PLANILLA = B.NRO_PLANILLA,
	       @vis_NRO_ORDEN_PASAJE = B.NRO_ORDEN_PASAJE,
	       @vis_tipo_opcion  	 = B.tipo_opcion,
	       @vd_FECHA_PVI    	 = B.FECHA_PVI,
	       @vd_FECHA_OP    		 = B.FECHA_OP,
	       @vn_nro_trans 	 	 = COALESCE(B.SEC_ORDEN,0), -- B.SEC_ITEM_PLA_PAS,
	       @vn_sec_pedido		 = B.SEC_PEDIDO,
	       @vis_ESTADO_PVI		 = B.ESTADO_PVI,
	       @vis_ESTADO_OP		 = B.ESTADO_OP
	  FROM deleted B
	
   
    -- Datos de Sesión
	IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
	   SELECT @vs_CUser  = CUSER_ID,
		      @vs_Equipo = EQUIPO_REG
	     FROM #SIG_SESION
	ELSE
	   SELECT @vs_CUser  = CUSER_MOD ,
	          @vs_Equipo = EQUIPO_MOD
	     FROM DELETED
	
	
	--Tipo de Transacción
 	IF @vis_tipo_opcion ='P' 
	   BEGIN
			select @vid_tipo_trans   = 11
   			SELECT @vis_tipo_bien	 = 'V'
   			select @vis_NRO_PLANILLA = @vis_NRO_PLANILLA	
			select @vd_fecha   		 = @vd_FECHA_PVI
			select @vis_estado 		 = @vis_ESTADO_PVI
	   END
	ELSE
	   BEGIN
			select @vid_tipo_trans 	 = 12	  
			select @vis_tipo_bien  	 = 'S'
			select @vis_NRO_PLANILLA = @vis_NRO_ORDEN_PASAJE	
			select @vd_fecha         = @vd_FECHA_OP
			select @vis_estado       = @vis_ESTADO_OP			
	   END	
	
   
    -- Auditoria: Eliminación de Documento 
	SELECT @vn_Nro_Secuencia= COALESCE(MAX(SECUENCIA),0) + 1
	  FROM SIG_AUDITORIA
	 WHERE ANO_EJE         = @vid_ano   AND
	       SEC_EJEC        = @vid_ejecutora  AND
		   TIPO_MOVIMIENTO = 'D'
  
         
    SELECT @vis_centro_costo = Coalesce(CENTRO_COSTO ,'X')
      FROM SIG_PROY_PEDIDOS
     WHERE ANO_EJEC   = @vid_ano AND 
      	   SEC_EJEC   = @vid_ejecutora AND 
           SEC_PEDIDO = @vn_sec_pedido 
         
       
    INSERT INTO SIG_AUDITORIA
			(ano_eje     , sec_ejec     , tipo_movimiento , secuencia	 ,	 tipo_transaccion , centro_costo,  		tipo_ppto   , 
			 tipo_bien   , tipo_pedido 	, nro_pedido 	  , nro_transaccion, fecha_transaccion, estado_transaccion,	fecha_reg  , 
			 cuser_id	 , equipo_reg )
	SELECT @vid_ano	 , @vid_ejecutora , 'D'         , @vn_Nro_Secuencia, @vid_tipo_trans, @vis_centro_costo,     1    , 
	   	   @vis_tipo_bien,@vis_tipo_opcion, @vis_NRO_PLANILLA, @vn_nro_trans, @vd_fecha    , @vis_estado , GETDATE()   , 
	   	   @vs_CUser  , @vs_Equipo
      FROM DELETED

			       
           
	
	 -- Recupera Correlativo de Seguimiento CAB
	SELECT @vid_nro_origen = coalesce(A.nro_origen,0)
	  FROM sig_seguimiento A
	 WHERE A.ano_eje 	      = @vid_ano 	      and
	       A.sec_ejec	      = @vid_ejecutora    and
	       A.nro_pedido	      = @vis_NRO_PLANILLA and
	       A.tipo_transaccion = @vid_tipo_trans	
	
	
	-- Eliminación de Registros
	DELETE FROM sig_seguimiento_estado
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen 	    = @vid_nro_origen 
	
	DELETE FROM sig_seguimiento_secuencia
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen 	    = @vid_nro_origen 
	
	DELETE FROM sig_seguimiento	
	 WHERE ano_eje 		    = @vid_ano 	      and
	       sec_ejec 		= @vid_ejecutora  and
	       tipo_transaccion	= @vid_tipo_trans and
	       nro_origen 	    = @vid_nro_origen 
END
GO

CREATE TRIGGER [dbo].[tg_planilla_viatico_ins]
ON [dbo].[SIG_PROY_PLANILLA_PASAJE]
WITH EXECUTE AS CALLER
FOR INSERT
AS
declare @vid_ano               numeric(4),		
	    @vid_ejecutora         numeric(6),		
        @vid_ITEM_PLA_PAS      numeric(5),
        @vis_tipo_opcion       varchar(1),
        @vis_tipo_bien         char(1),		
        @vid_nro_origen        numeric(6),
        @vid_tipo_trans        numeric(2),
        @vid_tipo_trans_ant    numeric(2),
        @vis_centro_costo      varchar(15),
        @vis_comisionado       varchar(15),	       	
        @vd_FECHA_PVI          DATETIME,
        @vis_ESTADO_PVI        char(1),
        @vis_NRO_PLANILLA      varchar(15),
        @vd_FECHA_OP           DATETIME,
        @vis_ESTADO_OP         char(1),
        @vis_NRO_ORDEN_PASAJE  varchar(15), 
        @vid_sec_pedido        numeric(6),
        @vid_sec_item_comi     numeric(3),
        @vid_nro_destino       numeric(6),
        @vd_fecha              DATETIME,
        @vis_estado            char(1),
        @vis_ppto              varchar(1),
        @vis_cuser_id	       varchar(30),
        @vis_equipo_reg	       varchar(20)
	
BEGIN
	-- Inicializando Variables
	SELECT @vid_ano		         = B.ano_ejec	     ,
	       @vid_ejecutora	     = B.sec_ejec        ,
	       @vid_ITEM_PLA_PAS     = B.SEC_ITEM_PLA_PAS,
	       @vis_tipo_opcion      = B.tipo_opcion     ,
		   @vd_FECHA_PVI	     = B.fecha_pvi       ,
		   @vis_ESTADO_PVI	     = B.estado_pvi      ,
		   @vis_NRO_PLANILLA     = B.nro_planilla    ,
		   @vd_FECHA_OP	         = B.fecha_op        ,
		   @vis_ESTADO_OP        = B.estado_op       ,
   		   @vis_NRO_ORDEN_PASAJE = B.nro_orden_pasaje,
		   @vid_sec_pedido       = B.sec_pedido      ,
		   @vid_sec_item_comi    = B.sec_item_comi   ,
	       @vis_cuser_id         = B.cuser_id_pvi    ,
	       @vis_equipo_reg       = B.equipo_reg_pvi
	  FROM inserted B
	
 	IF @vis_tipo_opcion ='P' 
	   BEGIN
			select @vid_tipo_trans   = 11
			select @vis_tipo_bien    = 'V'			
			select @vd_fecha         = @vd_FECHA_PVI
			select @vis_estado       = @vis_ESTADO_PVI
			select @vis_NRO_PLANILLA = @vis_NRO_PLANILLA		
	   END
	ELSE
	   BEGIN
			select @vid_tipo_trans   = 12	  
			select @vis_tipo_bien    = 'S'
			select @vd_fecha         = @vd_FECHA_OP
			select @vis_estado       = @vis_ESTADO_OP
			select @vis_NRO_PLANILLA = @vis_NRO_ORDEN_PASAJE				
	   END
	
	--Tipo de Transacción
	select @vid_tipo_trans_ant = 10
	
	--
	SELECT @vis_centro_costo  = max(centro_costo),
	       @vis_comisionado	 = max(comisionado)  
	  FROM sig_proy_comi A
	 WHERE A.ano_ejec      = @vid_ano        AND
	       A.sec_ejec      = @vid_ejecutora  AND
	       A.sec_pedido    = @vid_sec_pedido AND
	       A.sec_item_comi = @vid_sec_item_comi
	
	IF not exists 
   	   (SELECT *
	      FROM sig_proy_comi A
	     WHERE A.ano_ejec      = @vid_ano        AND
	           A.sec_ejec      = @vid_ejecutora  AND
	           A.sec_pedido    = @vid_sec_pedido AND
	           A.sec_item_comi = @vid_sec_item_comi)
	BEGIN
	    select @vis_centro_costo = ''
	    select @vis_comisionado = ''
	END
	
	SELECT @vis_ppto  = tipo_ppto
	  FROM sig_proy_pedidos C
	 WHERE C.ano_ejec   = @vid_ano       AND
	       C.sec_ejec   = @vid_ejecutora AND
	       C.sec_pedido = @vid_sec_pedido  
	
	IF not exists 
   	   (SELECT *
	      FROM sig_proy_pedidos C
	     WHERE C.ano_ejec   = @vid_ano       AND
	           C.sec_ejec   = @vid_ejecutora AND
	           C.sec_pedido = @vid_sec_pedido)
	BEGIN
	    select @vis_ppto = '0'
	END
	
	-- Registra Seguimiento de Documento
	INSERT INTO sig_seguimiento(
		ano_eje,
		sec_ejec,
		tipo_transaccion,
		nro_origen,
		nro_transaccion,
		fecha_transaccion,
		centro_costo,
		solicitante,
		estado_transaccion,
		tipo_ppto,
		tipo_bien,
		tipo_pedido,
		nro_pedido,
		fecha_reg,
		cuser_id,
		equipo_reg
		)
	select b.ano_ejec,
        b.sec_ejec,
		@vid_tipo_trans,
		coalesce((SELECT max(A.nro_origen)
		FROM sig_seguimiento A
		WHERE A.ano_eje     = b.ano_ejec  AND
		A.sec_ejec          = b.sec_ejec  AND
		A.tipo_transaccion  = @vid_tipo_trans),0)+1,
		b.sec_item_pla_pas,
		@vd_fecha,
		@vis_centro_costo,  --
		@vis_comisionado,  --
		@vis_estado,
		@vis_ppto, --
		@vis_tipo_bien,
		NULL,
		@vis_NRO_PLANILLA,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg
	from inserted B
	
 	-- Recupera el Nº Origen	
	SELECT @vid_nro_origen = A.nro_origen
	  FROM sig_seguimiento A,
	       inserted B
	 WHERE A.ano_eje 	      = B.ano_ejec 	       and
	       A.sec_ejec 	      = B.sec_ejec 	       and
	       A.nro_transaccion  = B.sec_item_pla_pas and	
	       A.tipo_transaccion = @vid_tipo_trans 

 	-- Registra en la tala sig_seguimiento_estado		      
	INSERT INTO sig_seguimiento_estado(
		ano_eje,
		sec_ejec,
		tipo_transaccion,
		nro_origen,
		sec_estado,
		fecha_estado,
		estado_seguimiento,
		fecha_reg,
		cuser_id,
		equipo_reg
		)	
	select A.ano_ejec,
		A.sec_ejec,
		@vid_tipo_trans,
		@vid_nro_origen,
		coalesce((select max(sec_estado)  
		from sig_seguimiento_estado
		where ano_eje          = A.ano_ejec       and               
		      sec_ejec	       = A.sec_ejec       and 
		      tipo_transaccion = @vid_tipo_trans  and
		      nro_origen       = @vid_nro_origen),0)+1,
		getdate(),
		@vis_estado,
		getdate(),
		@vis_cuser_id,
		@vis_equipo_reg
		from inserted A   


	-- Inserta Secuencia
	SELECT @vid_nro_destino  = nro_origen
	  FROM sig_seguimiento C
	 WHERE c.ano_eje          = @vid_ano        AND
	       c.sec_ejec         = @vid_ejecutora  AND
	       c.nro_transaccion  = @vid_sec_pedido AND
	       c.tipo_transaccion = @vid_tipo_trans_ant  
	
	IF not exists 
   	   (SELECT *
	      FROM sig_seguimiento C
	     WHERE c.ano_eje          = @vid_ano        AND
	           c.sec_ejec         = @vid_ejecutora  AND
	           c.nro_transaccion  = @vid_sec_pedido AND
	           c.tipo_transaccion = @vid_tipo_trans_ant)
	BEGIN
	    select @vid_nro_destino = 0
	END	


 	IF (@vid_nro_destino IS NOT NULL) AND (@vid_nro_destino <> 0) 
    BEGIN
        INSERT INTO sig_seguimiento_secuencia
                    (ano_eje, sec_ejec, tipo_transaccion, nro_origen, tipo_transaccion_destino, nro_destino)
		     VALUES (@vid_ano, @vid_ejecutora, @vid_tipo_trans, @vid_nro_origen, @vid_tipo_trans_ant, @vid_nro_destino)
    END
END
GO

CREATE TRIGGER [dbo].[tg_planilla_viatico_upd]
ON [dbo].[SIG_PROY_PLANILLA_PASAJE]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
declare @vid_ano               numeric(4),
        @vid_ejecutora         numeric(6),
        @vid_tipo_trans        numeric(2),
        @vid_tipo_trans_ant    numeric(2),
        @vid_nro_origen        numeric(6),
        @vid_ITEM_PLA_PAS      numeric(5),
        @vis_tipo_opcion       varchar(1),
        @vd_FECHA_PVI          DATETIME,
        @vis_ESTADO_PVI        char(1),
        @vis_NRO_PLANILLA      varchar(15),
        @vd_FECHA_OP           DATETIME,
        @vis_ESTADO_OP         char(1),
        @vis_NRO_ORDEN_PASAJE  varchar(15),
        @vis_tipo_bien         char(1),
        @vd_fecha              DATETIME,
        @vis_estado            char(1),
        @vis_cuser_id	       varchar(30),
        @vis_equipo_reg	       varchar(20),
        @vs_Estado_upd 		   char(1),
        @vs_Estado_OP 		   char(1),
        @vn_total_estado   	   numeric(6)
BEGIN
	-- Inicializa Variable
	SELECT @vid_ano	    	 = B.ano_ejec,
	       @vid_ejecutora	 = B.sec_ejec,
	       @vid_ITEM_PLA_PAS = B.SEC_ITEM_PLA_PAS,
	       @vis_tipo_opcion  = B.tipo_opcion,
		   @vd_FECHA_PVI	 = B.fecha_pvi,
		   @vis_ESTADO_PVI	 = B.estado_pvi,
		   @vis_NRO_PLANILLA = B.nro_planilla,
		   @vd_FECHA_OP	     = B.fecha_op,
		   @vis_ESTADO_OP    = B.estado_op,
   		   @vis_NRO_ORDEN_PASAJE = B.nro_orden_pasaje
	  FROM inserted B

	SELECT @vs_Estado_upd = Coalesce(M.estado_pvi ,'X')	,
		   @vs_Estado_OP  = Coalesce(M.estado_OP  ,'X')
	  FROM DELETED M , INSERTED I
	 where
	   	   M.ANO_EJEC         = I.ANO_EJEC  AND
	       M.SEC_EJEC         = I.SEC_EJEC AND
	       M.SEC_ITEM_PLA_PAS = I.SEC_ITEM_PLA_PAS

	--Usuario Sesión

     IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
           SELECT @vis_cuser_id   = CUSER_ID,
                  @vis_equipo_reg = EQUIPO_REG
             FROM #SIG_SESION
     ELSE
           SELECT @vis_cuser_id   = CUSER_MOD,
                  @vis_equipo_reg = EQUIPO_MOD
             FROM INSERTED

    IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
    BEGIN
		UPDATE sig_proy_planilla_pasaje
		   SET CUSER_MOD  = @vis_cuser_id,
			   EQUIPO_MOD = @vis_equipo_reg,
			   FECHA_MOD  = getdate()
		 WHERE ano_ejec = @vid_ano       and
		       sec_ejec = @vid_ejecutora and
		       sec_item_pla_pas = @vid_ITEM_PLA_PAS
    END

	-- Tipo de Transacción
	select @vid_tipo_trans_ant = 10

 	IF @vis_tipo_opcion ='P'
	   BEGIN
			select @vid_tipo_trans = 11
			select @vis_tipo_bien = 'V'
			select @vd_fecha   = @vd_FECHA_PVI
			select @vis_estado = @vis_ESTADO_PVI
			select @vis_NRO_PLANILLA = @vis_NRO_PLANILLA
	   END
	ELSE
	   BEGIN
			select @vid_tipo_trans = 12
			select @vis_tipo_bien = 'S'
			select @vd_fecha        = @vd_FECHA_OP
			select @vis_estado       = @vis_ESTADO_OP
			select @vis_NRO_PLANILLA = @vis_NRO_ORDEN_PASAJE
			SELECT @vs_Estado_UPD 	 = @vs_Estado_OP
	   END

    -- Valida Actualización de ESTADO
   	IF NOT UPDATE(estado_pvi) OR NOT UPDATE(estado_op) OR
   	   NOT UPDATE(fecha_pvi)  OR NOT UPDATE(fecha_op)
	   RETURN

	if not exists
		(select 1
		 from sig_seguimiento
		 where ano_eje 	        = @vid_ano and
		       sec_ejec         = @vid_ejecutora and
		       nro_transaccion  = @vid_ITEM_PLA_PAS and
		       tipo_transaccion = @vid_tipo_trans )
		begin
			INSERT INTO sig_seguimiento(
				ano_eje, sec_ejec, tipo_transaccion,
				nro_origen,
				nro_transaccion,
				fecha_transaccion,
				centro_costo,
				solicitante,
				estado_transaccion,
				tipo_ppto,
				tipo_bien,
				tipo_pedido,
				nro_pedido,
				fecha_reg,
				cuser_id,
				equipo_reg
				)
			SELECT b.ano_ejec,
                b.sec_ejec,
                @vid_tipo_trans,
			    coalesce((select max(B.nro_origen)
				from sig_seguimiento B
				where B.ano_eje 	 = @vid_ano	    and
				      B.sec_ejec 	 = @vid_ejecutora   and
				      B.tipo_transaccion = @vid_tipo_trans ),0)+1,
				b.sec_item_pla_pas,
				@vd_fecha,
				A.centro_costo,
				A.comisionado,
				@vis_estado,
				C.tipo_ppto,
				@vis_tipo_bien,
				NULL,
				@vis_NRO_PLANILLA,
				getdate(),
				@vis_cuser_id,
				@vis_equipo_reg
				FROM sig_proy_comi A,
				sig_proy_pedidos C,
				inserted B
				WHERE A.ano_ejec   = b.ano_ejec	and
    				  A.sec_ejec   = b.sec_ejec	and
     				  A.sec_pedido = b.sec_pedido and
	          	      A.sec_item_comi = b.sec_item_comi and
    				  b.ano_ejec   = C.ano_ejec	and
         			  b.sec_ejec   = C.sec_ejec	and
			 	      b.sec_pedido = C.sec_pedido
		end

	-- Recupera el Nº Origen
	select @vid_nro_origen = nro_origen
	from sig_seguimiento
	where  ano_eje       	  = @vid_ano        and
	       sec_ejec      	  = @vid_ejecutora  and
	       nro_transaccion    = @vid_ITEM_PLA_PAS  and
	       tipo_transaccion	  = @vid_tipo_trans

	-- Actualiza la tabla sig_seguimiento
	update sig_seguimiento
	set fecha_transaccion   = @vd_fecha,
	    estado_transaccion  = @vis_estado
	where  ano_eje       	= @vid_ano       and
	       sec_ejec      	= @vid_ejecutora and
	       nro_transaccion  = @vid_ITEM_PLA_PAS and
	       tipo_transaccion = @vid_tipo_trans

	-- Registra en la tabla sig_seguimiento_estado
	INSERT INTO sig_seguimiento_estado(
		   ano_eje,
		   sec_ejec,
		   tipo_transaccion,
		   nro_origen,
		   sec_estado,
		   fecha_estado,
		   estado_seguimiento,
		   fecha_reg,
		   cuser_id,
		   equipo_reg
		   )
	SELECT DISTINCT b.ano_ejec,
		   b.sec_ejec,
		   @vid_tipo_trans,
		   @vid_nro_origen,
	       coalesce((select max(C.sec_estado)
		               from sig_seguimiento_estado C
		              where C.ano_eje 	 = B.ano_ejec and
			                C.sec_ejec 	 = B.sec_ejec and
			                C.tipo_transaccion = @vid_tipo_trans and
			                C.nro_origen = @vid_nro_origen),0)+1,
	       getdate(),
		   @vis_estado,
		   getdate(),
		   @vis_cuser_id,
	  	   @vis_equipo_reg
	  FROM deleted A
	       INNER JOIN inserted B
           on A.ano_ejec 		 = B.ano_ejec and
              A.sec_ejec 		 = B.sec_ejec and
              A.SEC_ITEM_PLA_PAS = B.SEC_ITEM_PLA_PAS and
              (A.estado_pvi <> B.estado_pvi OR A.estado_op <> B.estado_op)

END
GO


