        @vs_Nro_Serie            VARCHAR(20),
        @vs_Nro_Docum            VARCHAR(50),
        @vs_Nro_Comprob          VARCHAR(20),
        @vs_Documento            VARCHAR(60),
        @vn_Nro_Origen           NUMERIC(6),
        @vn_Tipo_Modulo          NUMERIC(4),
        @vn_Secuencia            NUMERIC(6),
        @vs_Estado               CHAR(1),
        @vs_CUser                VARCHAR(30),
        @vs_Equipo               VARCHAR(20),
        @vn_Regs                 NUMERIC(6),
        @vn_Ins                  NUMERIC(4),
        @vn_Del                  NUMERIC(4),
        @vs_Trigger              CHAR(1),
        @vn_Nro_Secuencia        NUMERIC(6),
        @vs_Documento_Fec        DATETIME,
        @vd_Fec_Comprob          DATETIME,
        @vs_Estado_upd           VARCHAR(1),
        @vs_departamento         VARCHAR(2),
        @vs_provincia            VARCHAR(2),
		@vs_distrito             VARCHAR(2),
		@vs_tipo_vale            CHAR(1),
		@vs_origen_comision      VARCHAR(50),
		@vs_destino_comision     VARCHAR(50),
		@vd_fec_inicio_comision  DATETIME,
		@vd_fec_final_comision   DATETIME,
		@vd_hora_inicio_comision DATETIME,
		@vd_hora_fin_comision    DATETIME
		
BEGIN
     -- Determina Acción de Trigger
     SELECT @vs_Trigger= 'I'

     IF EXISTS(SELECT * FROM DELETED)
        SELECT @vs_Trigger= 'U'
     
     --
     SELECT @vs_Estado_upd = Coalesce(M.ESTADO ,'X')
       FROM INSERTED I , deleted M 
	  WHERE M.ANO_EJE     = I.ANO_EJE AND
			M.SEC_EJEC    = I.SEC_EJEC AND
			M.SEC_CAJA    = i.SEC_CAJA AND
			M.SEC_MOVIMTO = I.SEC_MOVIMTO
     
     --
     IF @vs_Trigger= 'I'
        INSERT INTO SIG_TES_CAJA_CHICA_MOV (
               ANO_EJE,                 SEC_EJEC,                    SEC_CAJA,
               SEC_MOVIMTO,             TIPO_MOVIMTO,                TIPO_TRANSAC,
               EXP_SIAF,                FEC_MOVIMTO,                 RESP_AUTORIZACION,
               NRO_SERIE,               NRO_DOCUMENTO,               FEC_DOCUMENTO,
               NRO_COMPROBANTE,         FEC_COMPROBANTE,             NRO_CHEQUE,
               FEC_CHEQUE,              MONTO_ASIGNADO,              PORCENT_ENTREGA,
               PORCENT_AUTORIZACION,    MONTO_ENTREGA,               MONTO_AUTORIZACION,
               ESTADO,                  OBSERVACIONES,               ANO_EJE_PROV,
               SEC_EJEC_PROV,           SEC_PROV,                    ANO_EJE_REND,
               SEC_EJEC_REND,           SEC_REND,                    TIPO_DOCUMENTO,
               NRO_RUC,                 CENTRO_COSTO,                COD_EMPLEADO,
               CCOSTO_EMPLEADO,         RESP_CCOSTO_EMPLEADO,        TIPO_MOVILIDAD,
               TIPO_SALIDA,             MONTO_TOTAL,                 MONTO_IGV,
               MONTO_RETENCION,         MONTO_EXONERADO,             MONTO_NETO,
               FLAG_RENDICION,          FECHA_REG,                   CUSER_ID,
               EQUIPO_REG,              SEC_CAJA_REND,               AUTORIZACION,
               NRO_VALE,                FEC_RENDIDO,                 MONTO_RESERVA_VALE,
               FL_CARGA_RC,             FECHA_MOD,                   CUSER_MOD,
               EQUIPO_MOD,              MONTO_RCONSUMO,		         FLAG_CTRL_PAO_PROY,
	       	   FEC_EMISION, 			DEPARTAMENTO, 				 PROVINCIA, 
	       	   DISTRITO,				TIPO_VALE, 					 ORIGEN_COMISION,
	       	   DESTINO_COMISION,	    FEC_INICIO_COMISION, 	     FEC_FINAL_COMISION,
	       	   HORA_INICIO_COMISION,    HORA_FIN_COMISION, 			 SEC_MOVIMTO_BF,
	       	   SEC_PEDIDO )
        SELECT ANO_EJE,        SEC_EJEC,                    SEC_CAJA,
               SEC_MOVIMTO,             TIPO_MOVIMTO,                TIPO_TRANSAC,
               EXP_SIAF,                FEC_MOVIMTO,                 RESP_AUTORIZACION,
               NRO_SERIE,               NRO_DOCUMENTO,               FEC_DOCUMENTO,
               NRO_COMPROBANTE,         FEC_COMPROBANTE,             NRO_CHEQUE,
               FEC_CHEQUE,              MONTO_ASIGNADO,              PORCENT_ENTREGA,
               PORCENT_AUTORIZACION,    MONTO_ENTREGA,               MONTO_AUTORIZACION,
               ESTADO,                  OBSERVACIONES,               ANO_EJE_PROV,
               SEC_EJEC_PROV,           SEC_PROV,                    ANO_EJE_REND,
               SEC_EJEC_REND,           SEC_REND,                    TIPO_DOCUMENTO,
  			   NRO_RUC,                 CENTRO_COSTO,                COD_EMPLEADO,
               CCOSTO_EMPLEADO,         RESP_CCOSTO_EMPLEADO,        TIPO_MOVILIDAD,
               TIPO_SALIDA,             MONTO_TOTAL,                 MONTO_IGV,
               MONTO_RETENCION,         MONTO_EXONERADO,             MONTO_NETO,
    	       FLAG_RENDICION,   		FECHA_REG,                   CUSER_ID,
               EQUIPO_REG,              SEC_CAJA_REND,               AUTORIZACION,
               NRO_VALE,                FEC_RENDIDO,                 MONTO_RESERVA_VALE,
               FL_CARGA_RC,             FECHA_MOD,                   CUSER_MOD,
               EQUIPO_MOD,              MONTO_RCONSUMO,		         FLAG_CTRL_PAO_PROY,
	           FEC_EMISION,             DEPARTAMENTO,                PROVINCIA,
	           DISTRITO,				TIPO_VALE,					 ORIGEN_COMISION,
	           DESTINO_COMISION,		FEC_INICIO_COMISION,		 FEC_FINAL_COMISION,
	           HORA_INICIO_COMISION,	HORA_FIN_COMISION,			 SEC_MOVIMTO_BF,
	           SEC_PEDIDO
          FROM INSERTED

     ELSE
        UPDATE SIG_TES_CAJA_CHICA_MOV
           SET ANO_EJE= I.ANO_EJE,           SEC_EJEC= I.SEC_EJEC,              SEC_CAJA= I.SEC_CAJA,
               SEC_MOVIMTO= I.SEC_MOVIMTO,   TIPO_MOVIMTO= I.TIPO_MOVIMTO,      TIPO_TRANSAC= I.TIPO_TRANSAC,
               EXP_SIAF= I.EXP_SIAF,         FEC_MOVIMTO= I.FEC_MOVIMTO,        RESP_AUTORIZACION= I.RESP_AUTORIZACION,
               NRO_SERIE= I.NRO_SERIE,       NRO_DOCUMENTO= I.NRO_DOCUMENTO,    FEC_DOCUMENTO= I.FEC_DOCUMENTO,
               NRO_COMPROBANTE= I.NRO_COMPROBANTE,                              FEC_COMPROBANTE= I.FEC_COMPROBANTE,
               NRO_CHEQUE= I.NRO_CHEQUE,     FEC_CHEQUE= I.FEC_CHEQUE,          MONTO_ASIGNADO= I.MONTO_ASIGNADO,
               PORCENT_ENTREGA= I.PORCENT_ENTREGA,                              PORCENT_AUTORIZACION= I.PORCENT_AUTORIZACION,
               MONTO_ENTREGA= I.MONTO_ENTREGA,                                  MONTO_AUTORIZACION= I.MONTO_AUTORIZACION,
               ESTADO= I.ESTADO,             OBSERVACIONES= I.OBSERVACIONES,    ANO_EJE_PROV= I.ANO_EJE_PROV,
               SEC_EJEC_PROV= I.SEC_EJEC_PROV,                                  SEC_PROV= I.SEC_PROV,
               ANO_EJE_REND= I.ANO_EJE_REND, SEC_EJEC_REND= I.SEC_EJEC_REND,    SEC_REND= I.SEC_REND,
               TIPO_DOCUMENTO= I.TIPO_DOCUMENTO,                                NRO_RUC = I.NRO_RUC,
               CENTRO_COSTO= I.CENTRO_COSTO, COD_EMPLEADO= I.COD_EMPLEADO,      CCOSTO_EMPLEADO = I.CCOSTO_EMPLEADO,
               RESP_CCOSTO_EMPLEADO=         I.RESP_CCOSTO_EMPLEADO,            TIPO_MOVILIDAD = I.TIPO_MOVILIDAD,
               TIPO_SALIDA= I.TIPO_SALIDA,   MONTO_TOTAL= I.MONTO_TOTAL,        MONTO_IGV= I.MONTO_IGV,
               MONTO_RETENCION= I.MONTO_RETENCION,                              MONTO_EXONERADO= I.MONTO_EXONERADO,
               MONTO_NETO= I.MONTO_NETO,     FLAG_RENDICION= I.FLAG_RENDICION,  FECHA_REG= I.FECHA_REG,
               CUSER_ID= I.CUSER_ID,         EQUIPO_REG= I.EQUIPO_REG,          SEC_CAJA_REND= I.SEC_CAJA_REND,
               AUTORIZACION= I.AUTORIZACION, NRO_VALE= I.NRO_VALE,    FEC_RENDIDO= I.FEC_RENDIDO,
               MONTO_RESERVA_VALE= I.MONTO_RESERVA_VALE,                        FL_CARGA_RC= I.FL_CARGA_RC,
               FECHA_MOD= I.FECHA_MOD,       CUSER_MOD = I.CUSER_MOD,           EQUIPO_MOD= I.EQUIPO_MOD,
               MONTO_RCONSUMO = I.MONTO_RCONSUMO, 								FLAG_CTRL_PAO_PROY = I.FLAG_CTRL_PAO_PROY,
	           FEC_EMISION=I.FEC_EMISION,
	           DEPARTAMENTO=I.DEPARTAMENTO, 
	           PROVINCIA=I.PROVINCIA, 
	           DISTRITO=I.DISTRITO,
			   TIPO_VALE=I.TIPO_VALE,
			   ORIGEN_COMISION=I.ORIGEN_COMISION,
			   DESTINO_COMISION=I.DESTINO_COMISION,
			   FEC_INICIO_COMISION=I.FEC_INICIO_COMISION,
			   FEC_FINAL_COMISION=I.FEC_FINAL_COMISION,
			   HORA_INICIO_COMISION=I.HORA_INICIO_COMISION,
			   HORA_FIN_COMISION=I.HORA_FIN_COMISION,
			   SEC_MOVIMTO_BF = I.SEC_MOVIMTO_BF,
			   SEC_PEDIDO = I.SEC_PEDIDO
          FROM INSERTED I
         WHERE SIG_TES_CAJA_CHICA_MOV.ANO_EJE     = I.ANO_EJE   AND
               SIG_TES_CAJA_CHICA_MOV.SEC_EJEC    = I.SEC_EJEC  AND
               SIG_TES_CAJA_CHICA_MOV.SEC_CAJA    = I.SEC_CAJA  AND
               SIG_TES_CAJA_CHICA_MOV.SEC_MOVIMTO = I.SEC_MOVIMTO
     
     -- Inicializando Variables
     SELECT @vn_Ano_Eje      = ANO_EJE,
            @vn_Sec_Ejec     = SEC_EJEC,
            @vn_Sec_Caja     = SEC_CAJA,
            @vn_Sec_Movimto  = SEC_MOVIMTO,
            @vs_Tipo_Movimto = TIPO_MOVIMTO,
            @vs_Tipo_Transac = TIPO_TRANSAC,
            @vs_Nro_Serie    = LTRIM(RTRIM(NRO_SERIE)),
            @vs_Nro_Docum    = LTRIM(RTRIM(NRO_DOCUMENTO)),
            @vs_Nro_Comprob  = LTRIM(RTRIM(NRO_COMPROBANTE)),
            @vs_Estado       = ESTADO,
            @vs_Documento_Fec= FEC_DOCUMENTO,
            @vd_Fec_Comprob  = FEC_COMPROBANTE
       FROM INSERTED     
     
     -- Solo para Ingresos,Egresos y Arqueo
     IF @vs_Tipo_Movimto <> 'I' AND @vs_Tipo_Movimto <> 'E' AND @vs_Tipo_Movimto <> 'A'
        BEGIN
           RETURN
        END 
	 
      -- Datos de Sesión
     IF @vs_Trigger = 'I'
        SELECT @vs_CUser=  I.CUSER_ID,
               @vs_Equipo= I.EQUIPO_REG
          FROM INSERTED I
     ELSE
        BEGIN
		    IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
		       SELECT @vs_CUser=   CUSER_ID,
		              @vs_Equipo= EQUIPO_REG
		         FROM #SIG_SESION
		    ELSE
		       SELECT @vs_CUser  =  CUSER_MOD, 
		              @vs_Equipo =  EQUIPO_MOD
		         FROM INSERTED
	        
			-- Actualiza Datos de Caja Chica
			UPDATE SIG_TES_CAJA_CHICA_MOV
			   SET CUSER_MOD  = @vs_CUser,
			       EQUIPO_MOD = @vs_Equipo,
			       FECHA_MOD  = GETDATE()
			 WHERE ANO_EJE     = @vn_Ano_Eje  AND
			       SEC_EJEC    = @vn_Sec_Ejec AND
			       SEC_CAJA    = @vn_Sec_Caja AND
			       SEC_MOVIMTO = @vn_Sec_Movimto
        END
     
     -- Valida Actualización de ESTADO
     IF NOT UPDATE(ESTADO) 
        RETURN
     
     -- Define Transacción
     IF @vs_Tipo_Movimto = 'I'   	-- Ingreso
        BEGIN
             IF @vs_Tipo_Transac = 'A'   -- Ingreso Apertura
                BEGIN
                     SELECT @vn_Tipo_Modulo = 38
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
              
             IF @vs_Tipo_Transac = 'M'   -- Ingreso Ampliación
                BEGIN
                     SELECT @vn_Tipo_Modulo = 39
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
             
             IF @vs_Tipo_Transac = 'R'   -- Ingreso Reembolso
                BEGIN
                     SELECT @vn_Tipo_Modulo = 40
                     SELECT @vs_Documento    = @vs_Nro_Comprob
                     SELECT @vs_Documento_Fec= @vd_Fec_Comprob
                END
             
             IF @vs_Tipo_Transac = 'G'   -- Ingreso Acumulado Inicial
                BEGIN
                     SELECT @vn_Tipo_Modulo = 41
                     SELECT @vs_Documento  = ''
                END
        END
     
     IF @vs_Tipo_Movimto = 'E'   	-- Egresos
        BEGIN
             IF @vs_Tipo_Transac = 'C'   -- Egresos Comprobante Pago
                BEGIN
                     SELECT @vn_Tipo_Modulo = 42
                     SELECT @vs_Documento   = @vs_Nro_Serie + '-' + @vs_Nro_Docum
                END
             
             IF @vs_Tipo_Transac = 'P'   -- Egresos Planilla Movilidad
                BEGIN
                     SELECT @vn_Tipo_Modulo = 43
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
             
             IF @vs_Tipo_Transac = 'V'   -- Egresos Vale Provisional
                BEGIN
                     SELECT @vn_Tipo_Modulo = 44
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
             
             IF @vs_Tipo_Transac = 'G'   -- Egresos Acumulado Inicial
                BEGIN
                     SELECT @vn_Tipo_Modulo = 45
                     SELECT @vs_Documento   = ''
                END
             
             IF @vs_Tipo_Transac = 'B'   -- Rebaja de Apertura
                BEGIN
                     SELECT @vn_Tipo_Modulo = 46
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
        END
     
     IF @vs_Tipo_Movimto = 'A'   	-- Arqueo
        BEGIN
             IF @vs_Tipo_Transac = 'A'   -- Arqueo de Caja
                BEGIN
                     SELECT @vn_Tipo_Modulo = 48
                     SELECT @vs_Documento   = @vs_Nro_Docum
                END
        END
     
     SELECT @vs_Documento = SUBSTRING(@vs_Documento, 1, 50)
     
     -- Valida Registro de Documento
     IF NOT EXISTS (SELECT 1 FROM SIG_SEGUIMIENTO
                     WHERE ANO_EJE          = @vn_Ano_Eje     AND
                           SEC_EJEC     = @vn_Sec_Ejec    AND
                           CENTRO_COSTO     = @vn_Sec_Caja    AND
                           NRO_TRANSACCION  = @vn_Sec_Movimto AND
                           TIPO_TRANSACCION = @vn_Tipo_Modulo)
        BEGIN
             -- Calcula Correlativo de Seguimiento CAB
             SELECT @vn_Nro_Origen= COALESCE(MAX(NRO_ORIGEN),0) + 1
               FROM SIG_SEGUIMIENTO
              WHERE ANO_EJE          = @vn_Ano_Eje  AND
                    SEC_EJEC         = @vn_Sec_Ejec AND
                    TIPO_TRANSACCION = @vn_Tipo_Modulo
             
             -- Inserta Seguimiento CAB
             INSERT INTO SIG_SEGUIMIENTO
                         (ANO_EJE     , SEC_EJEC         , TIPO_TRANSACCION  , NRO_ORIGEN,
                          CENTRO_COSTO, SOLICITANTE      , TIPO_PPTO         , TIPO_BIEN ,
                          TIPO_PEDIDO , TIPO_CONSOLID    , NRO_TRANSACCION   , NRO_PEDIDO,
                          NRO_CONSOLID, FECHA_TRANSACCION, ESTADO_TRANSACCION, FECHA_REG ,
                          CUSER_ID    , EQUIPO_REG       , SEC_TRANSACCION)
                  SELECT @vn_Ano_Eje, @vn_Sec_Ejec     , @vn_Tipo_Modulo, @vn_Nro_Origen,
                         I.SEC_CAJA , NULL             , 1              , NULL          ,
                         NULL       , NULL             , I.SEC_MOVIMTO  , @vs_Documento ,
                         NULL       , @vs_Documento_Fec, I.ESTADO       , GETDATE()     ,
                         @vs_CUser  , @vs_Equipo       , NULL
                    FROM INSERTED I
        END
     
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_Nro_Origen= NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje     AND
            SEC_EJEC         = @vn_Sec_Ejec    AND
            CENTRO_COSTO     = @vn_Sec_Caja    AND
            NRO_TRANSACCION  = @vn_Sec_Movimto AND
            TIPO_TRANSACCION = @vn_Tipo_Modulo
     
     -- Actualiza Estado de Documento
     IF @vs_Trigger = 'U'
        BEGIN
             UPDATE SIG_SEGUIMIENTO
                SET FECHA_TRANSACCION  = @vs_Documento_Fec,
                    ESTADO_TRANSACCION = @vs_Estado
              WHERE ANO_EJE          = @vn_Ano_Eje    AND
                    SEC_EJEC         = @vn_Sec_Ejec   AND
                    NRO_ORIGEN       = @vn_Nro_Origen AND
                    TIPO_TRANSACCION = @vn_Tipo_Modulo
        END
          
     -- Calcula Correlativo de Seguimiento DET
     SELECT @vn_Secuencia= COALESCE(MAX(SEC_ESTADO),0) + 1
       FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_Ano_Eje     AND
            SEC_EJEC         = @vn_Sec_Ejec    AND
            TIPO_TRANSACCION = @vn_Tipo_Modulo AND
            NRO_ORIGEN       = @vn_Nro_Origen
          
     IF @vn_Secuencia = 1  --Si no existe detalle
     BEGIN
	     -- Inserta Seguimiento DET
	     INSERT INTO SIG_SEGUIMIENTO_ESTADO
	                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
	                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG      , CUSER_ID  , EQUIPO_REG)
	          SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Modulo, @vn_Nro_Origen, @vn_Secuencia,
	                 GETDATE()  , I.ESTADO    , GETDATE()      , @vs_CUser     , @vs_Equipo
	            FROM INSERTED I
     END
	 ELSE
		BEGIN			   
		
			IF @vs_Estado_upd <> @vs_Estado  
			BEGIN
				  INSERT INTO SIG_SEGUIMIENTO_ESTADO
		                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
		                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG       , CUSER_ID  , EQUIPO_REG)
		        SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Modulo, @vn_Nro_Origen, @vn_Secuencia,
		                 GETDATE()  , I.ESTADO    , GETDATE()      , @vs_CUser     , @vs_Equipo
		            FROM INSERTED I
			END 
		END
END
GO


