-- ----------------------------
-- Triggers structure for table SIG_TES_CAJA_CHICA_REND
-- ----------------------------
CREATE TRIGGER [dbo].[tg_caja_chica_rendicion_ins]
ON [dbo].[SIG_TES_CAJA_CHICA_REND]
WITH EXECUTE AS CALLER
INSTEAD OF INSERT, UPDATE
AS
DECLARE @vn_Ano_eje         NUMERIC(4),
        @vn_Sec_Ejec        NUMERIC(6),
        @vn_Sec_Caja        NUMERIC(4),
        @vs_Tipo_Movimto    CHAR(1),
        @vs_Tipo_Transac    CHAR(1),
        @vs_Nro_Serie       VARCHAR(10),
        @vs_Nro_Docum       VARCHAR(50),
        @vs_Documento       VARCHAR(60),
        @vn_Nro_Origen      NUMERIC(6),
        @vn_Tipo_Modulo     NUMERIC(4),
        @vn_Secuencia       NUMERIC(6),
        @vs_Estado          CHAR(1),
        @vs_CUser           VARCHAR(30),
        @vs_Equipo          VARCHAR(20),
        @vn_Regs            NUMERIC(6),
        @vn_Ins             NUMERIC(4),
        @vn_Del             NUMERIC(4),
        @vs_Trigger         CHAR(1),
        @vn_Nro_Secuencia   NUMERIC(6),
        @vn_Sec_Rendicion   NUMERIC(6),
        @vs_Tipo_Rendicion  CHAR(1),
        @vs_Estado_upd		CHAR(1),
       @vd_fecha   DATETIME

BEGIN

   	SELECT @vs_Estado_upd = Coalesce(M.ESTADO ,'X')	
	  FROM DELETED M , INSERTED I 
	 where
	   	   M.ANO_EJE       = I.ANO_EJE  AND
	       M.SEC_EJEC      = I.SEC_EJEC AND
	       M.SEC_CAJA      = I.SEC_CAJA AND
	       M.SEC_rendicion = I.SEC_RENDICION


     -- Determina Acción de Trigger
     SELECT @vs_Trigger= 'I'

     IF EXISTS(SELECT * FROM DELETED)
        SELECT @vs_Trigger= 'U'        
        
     IF @vs_Trigger= 'I'
     	INSERT INTO SIG_TES_CAJA_CHICA_REND (
		     	ANO_EJE,            SEC_EJEC,           SEC_RENDICION,
				SEC_CAJA,           NRO_RENDICION,      FEC_RENDICION,
				RESPONSABLE,        MONTO_RENDICION,    MONTO_TRANSITO,
				OBSERVACION,        ESTADO,             FECHA_REG,
				CUSER_ID,           EQUIPO_REG,         tipo_rendicion,
				NRO_LIQUIDACION,    FECHA_MOD,          CUSER_MOD,
				EQUIPO_MOD,         EXP_SIGA,           NRO_ORDEN)
     	SELECT  ANO_EJE,            SEC_EJEC,           SEC_RENDICION,
				SEC_CAJA,           NRO_RENDICION,      FEC_RENDICION,
				RESPONSABLE,        MONTO_RENDICION,    MONTO_TRANSITO,
				OBSERVACION,        ESTADO,             FECHA_REG,
				CUSER_ID,           EQUIPO_REG,         tipo_rendicion,
				NRO_LIQUIDACION,    FECHA_MOD,          CUSER_MOD,
				EQUIPO_MOD,         EXP_SIGA,           NRO_ORDEN
		FROM INSERTED
		
	 ELSE  	
	 	UPDATE SIG_TES_CAJA_CHICA_REND
	 		SET ANO_EJE=I.ANO_EJE,                    SEC_EJEC=I.SEC_EJEC,                  SEC_RENDICION=I.SEC_RENDICION,
				SEC_CAJA=I.SEC_CAJA,                  NRO_RENDICION=I.NRO_RENDICION,        FEC_RENDICION=I.FEC_RENDICION,
				RESPONSABLE=I.RESPONSABLE,            MONTO_RENDICION=I.MONTO_RENDICION,    MONTO_TRANSITO=I.MONTO_TRANSITO,
				OBSERVACION=I.OBSERVACION,            ESTADO=I.ESTADO,                      FECHA_REG=I.FECHA_REG,
				CUSER_ID=I.CUSER_ID,                  EQUIPO_REG=I.EQUIPO_REG,              tipo_rendicion=I.TIPO_RENDICION,
				NRO_LIQUIDACION=I.NRO_LIQUIDACION,    FECHA_MOD=I.FECHA_MOD,                CUSER_MOD=I.CUSER_MOD,
				EQUIPO_MOD=I.EQUIPO_MOD,              EXP_SIGA=I.EXP_SIGA,                  NRO_ORDEN=I.NRO_ORDEN	   		
	 	FROM INSERTED I
	 	WHERE SIG_TES_CAJA_CHICA_REND.ANO_EJE= I.ANO_EJE   AND
	 		  SIG_TES_CAJA_CHICA_REND.SEC_EJEC= I.SEC_EJEC AND
	 		  SIG_TES_CAJA_CHICA_REND.SEC_RENDICION = I.SEC_RENDICION AND
	 		  SIG_TES_CAJA_CHICA_REND.SEC_CAJA= I.SEC_CAJA
	 		  

	-- Inicializando Variables
     SELECT @vn_Ano_Eje        = ANO_EJE,
            @vn_Sec_Ejec       = SEC_EJEC,
            @vn_Sec_Caja       = SEC_CAJA,
            @vs_Estado         = ESTADO,
            @vn_Sec_Rendicion  = SEC_RENDICION,
            @vs_Tipo_Rendicion = TIPO_RENDICION,
            @vd_fecha   = FEC_RENDICION
       FROM INSERTED	
       
     -- Datos de Sesión
     IF @vs_Trigger = 'I'
        SELECT @vs_CUser=  I.CUSER_ID,
               @vs_Equipo= I.EQUIPO_REG
          FROM INSERTED I
     ELSE
        BEGIN
            -- IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
              --	BEGIN
			        IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
			           SELECT @vs_CUser=   CUSER_ID,
			                  @vs_Equipo= EQUIPO_REG
			             FROM #SIG_SESION
			        ELSE
			           SELECT @vs_CUser  = CUSER_MOD, 
			                  @vs_Equipo = EQUIPO_MOD 
			             FROM INSERTED
		            
				    -- Actualiza Datos de Rendición
				    UPDATE SIG_TES_CAJA_CHICA_REND
				       SET CUSER_MOD  = @vs_CUser,
				           EQUIPO_MOD = @vs_Equipo,
				           FECHA_MOD  = GETDATE()
				     WHERE ANO_EJE       = @vn_Ano_Eje       AND
				           SEC_EJEC      = @vn_Sec_Ejec      AND
				           SEC_RENDICION = @vn_Sec_Rendicion AND
				           SEC_CAJA      = @vn_Sec_Caja
			--    END
       	END   	  
        
        
     -- Valida Actualización de ESTADO
     IF NOT UPDATE(ESTADO) 
        RETURN
     
     -- Define Transacción
     IF @vs_Tipo_Rendicion = 'R'	   	-- Reembolso
        SELECT @vn_Tipo_Modulo = 46
     
     IF @vs_Tipo_Rendicion = 'L' 	   	-- Liquidación
        SELECT @vn_Tipo_Modulo = 47
        
        
     -- Valida Registro de Documento
     IF NOT EXISTS (SELECT 1 FROM SIG_SEGUIMIENTO
                     WHERE ANO_EJE          = @vn_Ano_Eje       AND
                           SEC_EJEC         = @vn_Sec_Ejec      AND
                           CENTRO_COSTO     = @vn_Sec_Caja      AND
                           NRO_TRANSACCION  = @vn_Sec_Rendicion AND
                           TIPO_TRANSACCION = @vn_Tipo_Modulo)
        BEGIN
      -- Calcula Correlativo de Seguimiento CAB
             SELECT @vn_Nro_Origen= COALESCE(MAX(Coalesce(NRO_ORIGEN,0)),0) + 1
               FROM SIG_SEGUIMIENTO
              WHERE ANO_EJE          = @vn_Ano_Eje  AND
                    SEC_EJEC         = @vn_Sec_Ejec AND
                    TIPO_TRANSACCION = @vn_Tipo_Modulo
             
             -- Inserta Seguimiento CAB
             INSERT INTO SIG_SEGUIMIENTO
                         (ANO_EJE     , SEC_EJEC         , TIPO_TRANSACCION  , NRO_ORIGEN,
                          CENTRO_COSTO, SOLICITANTE      , TIPO_PPTO    , TIPO_BIEN ,
                          TIPO_PEDIDO , TIPO_CONSOLID    , NRO_TRANSACCION   , NRO_PEDIDO,
                          NRO_CONSOLID, FECHA_TRANSACCION, ESTADO_TRANSACCION, FECHA_REG ,
                          CUSER_ID    , EQUIPO_REG       , SEC_TRANSACCION)
                  SELECT @vn_Ano_Eje, @vn_Sec_Ejec   , @vn_Tipo_Modulo  , @vn_Nro_Origen ,
                         I.SEC_CAJA , NULL           , 1                , NULL           ,
                         NULL       , NULL           , @vn_Sec_Rendicion, I.NRO_RENDICION,
                         NULL       , I.FEC_RENDICION, I.ESTADO         , GETDATE()      ,
                         @vs_CUser  , @vs_Equipo     , NULL
                    FROM INSERTED I
        END
      
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_Nro_Origen= NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje       AND
            SEC_EJEC         = @vn_Sec_Ejec      AND
            CENTRO_COSTO     = @vn_Sec_Caja      AND
            NRO_TRANSACCION  = @vn_Sec_Rendicion AND
            TIPO_TRANSACCION = @vn_Tipo_Modulo
     
     -- Actualiza Estado de Documento
     IF @vs_Trigger = 'U'
        BEGIN
             UPDATE SIG_SEGUIMIENTO
                SET FECHA_TRANSACCION  = @vd_fecha   ,
                    ESTADO_TRANSACCION = @vs_Estado
              WHERE ANO_EJE          = @vn_Ano_Eje    AND
                    SEC_EJEC         = @vn_Sec_Ejec   AND
                    NRO_ORIGEN       = @vn_Nro_Origen AND
                    TIPO_TRANSACCION = @vn_Tipo_Modulo
        END
     
     
     
     -- Calcula Correlativo de Seguimiento DET
     SELECT @vn_Secuencia= COALESCE(MAX(Coalesce(SEC_ESTADO,0)),0) + 1
       FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_Ano_Eje     AND
            SEC_EJEC         = @vn_Sec_Ejec    AND
            TIPO_TRANSACCION = @vn_Tipo_Modulo AND
            NRO_ORIGEN       = @vn_Nro_Origen
     
     
        
     
     
     IF @vn_Secuencia = 1  --Si no existe detalle
     BEGIN
    -- Inserta Seguimiento DET
	     INSERT INTO SIG_SEGUIMIENTO_ESTADO
	                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
	                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG       , CUSER_ID  , EQUIPO_REG)
	          SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Modulo, @vn_Nro_Origen, @vn_Secuencia,
	                 GETDATE()  , I.ESTADO    , GETDATE()      , @vs_CUser     , @vs_Equipo
	            FROM INSERTED I
     END
     ELSE
      BEGIN			   
		
			IF @vs_Estado_upd <> @vs_Estado  
			BEGIN
				 INSERT INTO SIG_SEGUIMIENTO_ESTADO
	                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
	                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG       , CUSER_ID  , EQUIPO_REG)
	          	 SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Modulo, @vn_Nro_Origen, @vn_Secuencia,
	                 	GETDATE()  , I.ESTADO    , GETDATE()      , @vs_CUser     , @vs_Equipo
	             FROM INSERTED I
            END
			
     	END
     
  END
GO


