-- ----------------------------
CREATE TRIGGER [dbo].[tg_recibo_ingreso_del]
ON [dbo].[SIG_TES_RECIBO_INGRESO]
WITH EXECUTE AS CALLER
FOR DELETE
AS
DECLARE @vn_Ano_Eje          NUMERIC(4),
        @vn_Sec_Ejec         NUMERIC(6),
        @vn_Sec_Recibo       NUMERIC(6),
        @vn_Nro_Origen       NUMERIC(6),
        @vn_Tipo_Transaccion NUMERIC(4),
        @vn_Nro_Secuencia    NUMERIC(6),
        @vs_CUser            VARCHAR(30),
        @vs_Equipo           VARCHAR(20)


BEGIN
     -- Inicializando Variables
     SELECT @vn_Ano_Eje    =  ANO_EJE,
            @vn_Sec_Ejec   = SEC_EJEC,
            @vn_Sec_Recibo = SEC_RECIBO
       FROM DELETED
     
     -- Datos de Sesión
	   IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
	  	SELECT @vs_CUser  = CUSER_ID,
		       @vs_Equipo = EQUIPO_REG
		  FROM #SIG_SESION
	 ELSE
	    SELECT @vs_CUser  = CUSER_MOD,
	           @vs_Equipo = EQUIPO_MOD
	      FROM DELETED
     
     -- Define Transacción
     SELECT @vn_Tipo_Transaccion= 37

     -- Auditoria: Eliminación de Documento
     SELECT @vn_Nro_Secuencia= COALESCE(MAX(SECUENCIA),0) + 1
       FROM sig_auditoria
      WHERE ANO_EJE         = @vn_Ano_Eje  AND
            SEC_EJEC        = @vn_Sec_Ejec AND
            TIPO_MOVIMIENTO = 'D'
     
     INSERT INTO SIG_AUDITORIA
                 (ano_eje  , sec_ejec  , tipo_movimiento, secuencia        , tipo_transaccion  , centro_costo,
                  tipo_ppto, nro_pedido, nro_transaccion, fecha_transaccion, estado_transaccion, fecha_reg   ,
                  cuser_id  , equipo_reg)
          SELECT @vn_Ano_Eje, @vn_Sec_Ejec, 'D'       , @vn_Nro_Secuencia, @vn_Tipo_Transaccion, COD_CAJA,
                 1          , nro_recibo  , SEC_RECIBO, fec_recibo       , estado              , GETDATE(),
                 @vs_CUser  , @vs_Equipo
            FROM DELETED
     
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_Nro_Origen= NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje          AND
            SEC_EJEC         = @vn_Sec_Ejec         AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion AND
            NRO_TRANSACCION  = @vn_Sec_Recibo
     
     -- Eliminación de Registros
     DELETE FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_Ano_Eje          AND
            SEC_EJEC         = @vn_Sec_Ejec         AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion AND
            NRO_ORIGEN       = @vn_Nro_Origen
     
     DELETE FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje          AND
            SEC_EJEC         = @vn_Sec_Ejec         AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion AND
            NRO_ORIGEN       = @vn_Nro_Origen

END
GO

CREATE TRIGGER [dbo].[tg_recibo_ingreso_ins]
ON [dbo].[SIG_TES_RECIBO_INGRESO]
WITH EXECUTE AS CALLER
INSTEAD OF INSERT, UPDATE
AS
DECLARE @vn_Ano_Eje          NUMERIC(4),
        @vn_Sec_Ejec         NUMERIC(6),
        @vn_Sec_Recibo       NUMERIC(6),
        @vn_Nro_Origen       NUMERIC(6),
        @vn_Tipo_Transaccion NUMERIC(4),
        @vn_Sec_Estado       NUMERIC(6),
        @vs_Estado           VARCHAR(1),
        @vs_CUser            VARCHAR(30),
        @vs_Equipo           VARCHAR(20),
        @vs_Trigger          CHAR(1),
@vd_fec_recibo datetime

BEGIN
     -- Determina Acción de Trigger
     SELECT @vs_Trigger= 'I'
     
     IF EXISTS(SELECT * FROM DELETED)
        SELECT @vs_Trigger= 'U'
     
     IF @vs_Trigger= 'I'
        INSERT INTO SIG_TES_RECIBO_INGRESO (
               ANO_EJE,                SEC_EJEC,            SEC_RECIBO,
               NRO_RECIBO,             FEC_RECIBO,          MES_RECIBO,
               TIPO_ORIGEN,            COD_CAJA,            ORIGEN,
               FUENTE_FINANC,          COD_PERSONA,         MOTIVO,
               VALOR_TOTAL,            TIPO_PAGO,           BANCO,
               NRO_DOC_PAGO,           FEC_DOC_PAGO,        ESTADO,
               ESTADO_SIAF,            EXP_SIAF,            TIPO_OPERACION,
               FECHA_REG,              CUSER_ID,            EQUIPO_REG,
               flag_intf,              sec_ejec_siaf,       FECHA_MOD,
               CUSER_MOD,              EQUIPO_MOD,          TIPO_PLANILLA_REMU,
               TIPO_DEVOLUCION,        ANIO_DEVOLUCION,     NRO_COMPR_PAGO)
        SELECT ANO_EJE,                SEC_EJEC,            SEC_RECIBO,
               NRO_RECIBO,             FEC_RECIBO,          MES_RECIBO,
               TIPO_ORIGEN,            COD_CAJA,            ORIGEN,
               FUENTE_FINANC,          COD_PERSONA,         MOTIVO,
               VALOR_TOTAL,            TIPO_PAGO,           BANCO,
               NRO_DOC_PAGO,           FEC_DOC_PAGO,        ESTADO,
               ESTADO_SIAF,            EXP_SIAF,            TIPO_OPERACION,
               FECHA_REG,              CUSER_ID,            EQUIPO_REG,
               flag_intf,              sec_ejec_siaf,       FECHA_MOD,
               CUSER_MOD,              EQUIPO_MOD,          TIPO_PLANILLA_REMU,
               TIPO_DEVOLUCION,        ANIO_DEVOLUCION,     NRO_COMPR_PAGO
          FROM INSERTED
     ELSE
        UPDATE SIG_TES_RECIBO_INGRESO
           SET ANO_EJE= I.ANO_EJE,                  SEC_EJEC= I.SEC_EJEC,                SEC_RECIBO = I.SEC_RECIBO,
               NRO_RECIBO= I.NRO_RECIBO,            FEC_RECIBO= I.FEC_RECIBO,            MES_RECIBO = I.MES_RECIBO,
               TIPO_ORIGEN= I.TIPO_ORIGEN,          COD_CAJA= I.COD_CAJA,                ORIGEN= I.ORIGEN,
               FUENTE_FINANC= I.FUENTE_FINANC,      COD_PERSONA= I.COD_PERSONA,          MOTIVO= I.MOTIVO,
               VALOR_TOTAL= I.VALOR_TOTAL,          TIPO_PAGO= I.TIPO_PAGO,              BANCO= I.BANCO,
               NRO_DOC_PAGO= I.NRO_DOC_PAGO,        FEC_DOC_PAGO= I.FEC_DOC_PAGO,        ESTADO= I.ESTADO,
               ESTADO_SIAF= I.ESTADO_SIAF,          EXP_SIAF= I.EXP_SIAF,                TIPO_OPERACION= I.TIPO_OPERACION,
               FECHA_REG= I.FECHA_REG,              CUSER_ID= I.CUSER_ID,                EQUIPO_REG= I.EQUIPO_REG,
               FLAG_INTF= I.FLAG_INTF,              SEC_EJEC_SIAF= I.SEC_EJEC_SIAF,      FECHA_MOD= I.FECHA_MOD,
               CUSER_MOD= I.CUSER_MOD,              EQUIPO_MOD= I.EQUIPO_MOD,            TIPO_PLANILLA_REMU = I.TIPO_PLANILLA_REMU,
               TIPO_DEVOLUCION= I.TIPO_DEVOLUCION,  ANIO_DEVOLUCION= I.ANIO_DEVOLUCION,  NRO_COMPR_PAGO= I.NRO_COMPR_PAGO
          FROM INSERTED I
         WHERE SIG_TES_RECIBO_INGRESO.ANO_EJE    = I.ANO_EJE   AND
               SIG_TES_RECIBO_INGRESO.SEC_EJEC   = I.SEC_EJEC  AND
               SIG_TES_RECIBO_INGRESO.SEC_RECIBO = I.SEC_RECIBO
     
     -- Inicializando Variables
     SELECT @vn_Ano_Eje   = ANO_EJE,
            @vn_Sec_Ejec  = SEC_EJEC,
            @vn_Sec_Recibo= SEC_RECIBO,
            @vs_Estado    = ESTADO,
 @vd_fec_recibo = FEC_RECIBO
       FROM INSERTED
     
     -- Datos de Sesión
     IF @vs_Trigger = 'I'
        SELECT @vs_CUser=  I.CUSER_ID,
               @vs_Equipo= I.EQUIPO_REG
          FROM INSERTED I
     ELSE
        BEGIN
             IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
             	BEGIN
			        IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
			           SELECT @vs_CUser=   CUSER_ID,
			                  @vs_Equipo= EQUIPO_REG
			             FROM #SIG_SESION
			        ELSE
			           SELECT @vs_CUser  =  CUSER_MOD,  
			                  @vs_Equipo =  EQUIPO_MOD
			             FROM INSERTED
		               
				       -- Actualiza Datos de Recibo
			           UPDATE SIG_TES_RECIBO_INGRESO 
				          SET CUSER_MOD  = @vs_CUser,
				              EQUIPO_MOD = @vs_Equipo,
				              FECHA_MOD  = GETDATE()
				        WHERE ANO_EJE    = @vn_Ano_Eje  AND
				              SEC_EJEC   = @vn_Sec_Ejec AND
				              SEC_RECIBO = @vn_Sec_Recibo
			    END
        END
     
     -- Valida Actualización de ESTADO
     IF NOT UPDATE(ESTADO) 
        RETURN
     
     -- Define Transacción
     SELECT @vn_Tipo_Transaccion= 37
     
     -- Valida Registro de Documento
     IF NOT EXISTS (SELECT 1 FROM SIG_SEGUIMIENTO
                     WHERE ANO_EJE          = @vn_Ano_Eje    AND
                           SEC_EJEC         = @vn_Sec_Ejec   AND
                           NRO_TRANSACCION  = @vn_Sec_Recibo AND
                           TIPO_TRANSACCION = @vn_Tipo_Transaccion)
        BEGIN
             -- Calcula Correlativo de Seguimiento CAB
             SELECT @vn_Nro_Origen= COALESCE(MAX(NRO_ORIGEN),0) + 1
               FROM SIG_SEGUIMIENTO
              WHERE ANO_EJE          = @vn_Ano_Eje  AND
                    SEC_EJEC         = @vn_Sec_Ejec AND
                    TIPO_TRANSACCION = @vn_Tipo_Transaccion
             
             -- Inserta Seguimiento CAB
             INSERT INTO SIG_SEGUIMIENTO
                         (ANO_EJE        , SEC_EJEC  , TIPO_TRANSACCION, NRO_ORIGEN       , CENTRO_COSTO ,
                          SOLICITANTE    , TIPO_PPTO , TIPO_BIEN       , TIPO_PEDIDO      , TIPO_CONSOLID,
                          NRO_TRANSACCION, NRO_PEDIDO, NRO_CONSOLID    , FECHA_TRANSACCION, ESTADO_TRANSACCION,
                          FECHA_REG      , CUSER_ID  , EQUIPO_REG      , SEC_TRANSACCION)
                  SELECT @vn_Ano_Eje   , @vn_Sec_Ejec, @vn_Tipo_Transaccion, @vn_Nro_Origen, I.COD_CAJA,
                         I.COD_PERSONA , 1           , NULL                , NULL          , NULL      ,
                         @vn_Sec_Recibo, I.NRO_RECIBO, NULL                , I.FEC_RECIBO  , I.ESTADO  ,
                         GETDATE()     , @vs_CUser   , @vs_Equipo          , NULL
                    FROM INSERTED I
        END
     
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_Nro_Origen = NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje    AND
            SEC_EJEC         = @vn_Sec_Ejec   AND
            NRO_TRANSACCION  = @vn_Sec_Recibo AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion
     
     -- Actualiza Estado de Documento
     IF @vs_Trigger = 'U'
        BEGIN
             UPDATE SIG_SEGUIMIENTO 
                SET FECHA_TRANSACCION  = @vd_fec_recibo ,
                    ESTADO_TRANSACCION = @vs_Estado
              WHERE ANO_EJE          = @vn_Ano_Eje    AND
                    SEC_EJEC         = @vn_Sec_Ejec   AND 
                    NRO_ORIGEN       = @vn_Nro_Origen AND
                    TIPO_TRANSACCION = @vn_Tipo_Transaccion
        END
     
     -- Calcula Correlativo de Seguimiento DET
     SELECT @vn_Sec_Estado= COALESCE(MAX(SEC_ESTADO),0) + 1
       FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_Ano_Eje          AND
            SEC_EJEC         = @vn_Sec_Ejec         AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion AND
            NRO_ORIGEN       = @vn_Nro_Origen
     
     -- Inserta Seguimiento DET
     INSERT INTO SIG_SEGUIMIENTO_ESTADO
                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG       , CUSER_ID  , EQUIPO_REG)
          SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Transaccion, @vn_Nro_Origen, @vn_Sec_Estado,
                 GETDATE()  , I.ESTADO    , GETDATE()           , @vs_CUser     , @vs_Equipo
            FROM INSERTED I

END
GO


