-- ----------------------------
CREATE TRIGGER [dbo].[tg_recibo_provisional_del]
ON [dbo].[SIG_TES_RECIBO_PROV]
WITH EXECUTE AS CALLER
FOR DELETE
AS
DECLARE @vn_ano_eje          NUMERIC(4),
        @vn_sec_ejec         NUMERIC(6),
        @vn_sec_recibo       NUMERIC(6),
        @vn_nro_origen       NUMERIC(6),
        @vn_tipo_transaccion NUMERIC(4),
        @vn_nro_secuencia    NUMERIC(6),
        @vs_cuser            VARCHAR(30),
        @vs_equipo           VARCHAR(20)

BEGIN
     -- Inicializando Variables
     SELECT @vn_ano_eje    =  ANO_EJE,
            @vn_sec_ejec   = SEC_EJEC,
            @vn_sec_recibo = SECUENCIA
       FROM DELETED

     -- Datos de Sesión
                 IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
	  	SELECT @vs_CUser  = CUSER_ID,
		       @vs_Equipo = EQUIPO_REG
		  FROM #SIG_SESION
	 ELSE
	    SELECT @vs_CUser  = CUSER_MOD,
	           @vs_Equipo = EQUIPO_MOD
	      FROM DELETED
     
     -- Define Transacción
     SELECT @vn_tipo_transaccion= 36
     
     -- Auditoria: Eliminación de Documento
     SELECT @vn_nro_secuencia = coalesce(max(secuencia),0)+1
       FROM sig_auditoria
      WHERE ano_eje         = @vn_ano_eje  and
            sec_ejec        = @vn_sec_ejec and
            tipo_movimiento = 'D'
     
     INSERT INTO sig_auditoria
                 (ano_eje  , sec_ejec  , tipo_movimiento, secuencia        , tipo_transaccion  , centro_costo,
                  tipo_ppto, nro_pedido, nro_transaccion, fecha_transaccion, estado_transaccion, fecha_reg   ,
                  cuser_id  , equipo_reg)
          SELECT ano_eje  , sec_ejec  , 'D'           , @vn_nro_secuencia, @vn_tipo_transaccion, cod_caja ,
                 1        , nro_recibo, @vn_sec_recibo, fec_recibo       , estado              , getdate(),
                 @vs_cuser, @vs_equipo
            FROM DELETED
     
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_nro_origen = NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_ano_eje          AND
            SEC_EJEC         = @vn_sec_ejec         AND
            TIPO_TRANSACCION = @vn_tipo_transaccion AND
            NRO_TRANSACCION  = @vn_sec_recibo
     
     -- Eliminación de Registros
     DELETE FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_ano_eje          AND
            SEC_EJEC         = @vn_sec_ejec         AND
            TIPO_TRANSACCION = @vn_tipo_transaccion AND
            NRO_ORIGEN       = @vn_nro_origen
     
     DELETE FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_ano_eje          AND
            SEC_EJEC         = @vn_sec_ejec         AND
            TIPO_TRANSACCION = @vn_tipo_transaccion AND
            NRO_ORIGEN       = @vn_nro_origen

END
GO

CREATE TRIGGER [dbo].[tg_recibo_provisional_ins]
ON [dbo].[SIG_TES_RECIBO_PROV]
WITH EXECUTE AS CALLER
INSTEAD OF INSERT, UPDATE
AS
DECLARE @vn_Ano_Eje          NUMERIC(4),
        @vn_Sec_Ejec         NUMERIC(6),
        @vn_Secuencia        NUMERIC(6),
        @vn_Cod_Caja         NUMERIC(4),
        @vn_Nro_Origen       NUMERIC(6),
        @vn_Tipo_Transaccion NUMERIC(4),
        @vn_Sec_Estado       NUMERIC(6),
        @vs_Estado           VARCHAR(1),
        @vs_CUser            VARCHAR(30),
        @vs_Equipo           VARCHAR(20),
        @vs_Trigger          CHAR(1),
@vd_fecha  datetime
BEGIN
     -- Determina Acción de Trigger
     SELECT @vs_Trigger= 'I'
     
     IF EXISTS(SELECT * FROM DELETED)
        SELECT @vs_Trigger= 'U'
     
     IF @vs_Trigger= 'I'
        INSERT INTO SIG_TES_RECIBO_PROV (
               ANO_EJE,         SEC_EJEC,        SECUENCIA,       COD_CAJA,
               NRO_RECIBO,      FEC_RECIBO,      MES_RECIBO,      DESCRIPCION,
               VALOR_TOTAL,     COD_PERSONA,     TIPO_PAGO,       BANCO,
               NRO_DOC_PAGO,    FEC_DOC_PAGO,    ESTADO,          FECHA_REG,
               CUSER_ID,        EQUIPO_REG,      FECHA_MOD,       CUSER_MOD,     EQUIPO_MOD)
        SELECT ANO_EJE,         SEC_EJEC,        SECUENCIA,       COD_CAJA,
               NRO_RECIBO,      FEC_RECIBO,      MES_RECIBO,      DESCRIPCION,
               VALOR_TOTAL,     COD_PERSONA,     TIPO_PAGO,       BANCO,
               NRO_DOC_PAGO,    FEC_DOC_PAGO,    ESTADO,          FECHA_REG,
               CUSER_ID,        EQUIPO_REG,      FECHA_MOD,       CUSER_MOD,     EQUIPO_MOD
          FROM INSERTED

     ELSE
        UPDATE SIG_TES_RECIBO_PROV
           SET ANO_EJE= I.ANO_EJE,            SEC_EJEC= I.SEC_EJEC,          SECUENCIA= I.SECUENCIA,     COD_CAJA= I.COD_CAJA,
               NRO_RECIBO= I.NRO_RECIBO,      FEC_RECIBO= I.FEC_RECIBO,      MES_RECIBO= I.MES_RECIBO,   DESCRIPCION= I.DESCRIPCION,
               VALOR_TOTAL= I.VALOR_TOTAL,    COD_PERSONA= I.COD_PERSONA,    TIPO_PAGO= I.TIPO_PAGO,     BANCO= I.BANCO,
               NRO_DOC_PAGO= I.NRO_DOC_PAGO,  FEC_DOC_PAGO= I.FEC_DOC_PAGO,  ESTADO= I.ESTADO,           FECHA_REG= I.FECHA_REG,
               CUSER_ID= I.CUSER_ID,          EQUIPO_REG= I.EQUIPO_REG,      FECHA_MOD= I.FECHA_MOD,     CUSER_MOD= I.CUSER_MOD,
               EQUIPO_MOD = I.EQUIPO_MOD
          FROM INSERTED I
         WHERE SIG_TES_RECIBO_PROV.ANO_EJE   = I.ANO_EJE   AND
               SIG_TES_RECIBO_PROV.SEC_EJEC  = I.SEC_EJEC  AND
               SIG_TES_RECIBO_PROV.SECUENCIA = I.SECUENCIA
     
     -- Inicializando Variables
     SELECT @vn_Ano_Eje  = ANO_EJE  ,
            @vn_Sec_Ejec = SEC_EJEC ,
            @vn_Secuencia= SECUENCIA,
            @vn_Cod_Caja = COD_CAJA ,
            @vs_Estado   = ESTADO,
@vd_fecha  = fec_recibo
       FROM INSERTED
     
     -- Datos de Sesión
     IF @vs_Trigger = 'I'
        SELECT @vs_CUser=  I.CUSER_ID,
               @vs_Equipo= I.EQUIPO_REG
          FROM INSERTED I
     ELSE
        BEGIN
             IF NOT (UPDATE(CUSER_MOD) OR UPDATE(EQUIPO_MOD))
             	BEGIN
			         IF OBJECT_ID ('tempdb..#sig_sesion') IS NOT NULL
			           SELECT @vs_CUser=   CUSER_ID,
			                  @vs_Equipo= EQUIPO_REG
			             FROM #SIG_SESION
			        ELSE
			           SELECT @vs_CUser  =  CUSER_MOD,  
			                  @vs_Equipo =  EQUIPO_MOD		
	                                            FROM INSERTED
		            
				    -- Actualiza Datos de Recibo
					UPDATE SIG_TES_RECIBO_PROV 
					   SET CUSER_MOD  = @vs_CUser ,
					       EQUIPO_MOD = @vs_Equipo,
					       FECHA_MOD  = GETDATE()
					 WHERE ANO_EJE   = @vn_Ano_Eje   AND
					       SEC_EJEC  = @vn_Sec_Ejec  AND
					       SECUENCIA = @vn_Secuencia AND
					       COD_CAJA  = @vn_Cod_Caja
			    END
        END
	 
     -- Valida Actualización de ESTADO
     IF NOT UPDATE(ESTADO) 
        RETURN
     
     -- Define Transacción
     SELECT @vn_Tipo_Transaccion= 36
     
     -- Valida Registro de Documento
     IF NOT EXISTS (SELECT 1 FROM SIG_SEGUIMIENTO
            WHERE ANO_EJE          = @vn_Ano_Eje   AND
                           SEC_EJEC         = @vn_Sec_Ejec  AND
                           NRO_TRANSACCION  = @vn_Secuencia AND
                           TIPO_TRANSACCION = @vn_Tipo_Transaccion)
        BEGIN
             -- Calcula Correlativo de Seguimiento CAB
             SELECT @vn_Nro_Origen= COALESCE(MAX(NRO_ORIGEN),0) + 1
               FROM SIG_SEGUIMIENTO
              WHERE ANO_EJE          = @vn_Ano_Eje  AND
                    SEC_EJEC         = @vn_Sec_Ejec AND
                    TIPO_TRANSACCION = @vn_Tipo_Transaccion
             
             -- Inserta Seguimiento CAB
             INSERT INTO SIG_SEGUIMIENTO
                         (ANO_EJE     , SEC_EJEC         , TIPO_TRANSACCION  , NRO_ORIGEN,
                          CENTRO_COSTO, SOLICITANTE      , TIPO_PPTO         , TIPO_BIEN ,
                          TIPO_PEDIDO , TIPO_CONSOLID    , NRO_TRANSACCION   , NRO_PEDIDO,
                          NRO_CONSOLID, FECHA_TRANSACCION, ESTADO_TRANSACCION, FECHA_REG ,
                          CUSER_ID    , EQUIPO_REG       , SEC_TRANSACCION)
                  SELECT @vn_Ano_Eje, @vn_Sec_Ejec , @vn_Tipo_Transaccion, @vn_Nro_Origen,
                         I.COD_CAJA , I.COD_PERSONA, 1                   , NULL          ,
                         NULL       , NULL         , @vn_Secuencia       , I.NRO_RECIBO  ,
                         NULL       , I.FEC_RECIBO , I.ESTADO            , GETDATE()     ,
                         @vs_CUser  , @vs_Equipo   , NULL
                    FROM INSERTED I
        END
     
     -- Recupera Correlativo de Seguimiento CAB
     SELECT @vn_Nro_Origen = NRO_ORIGEN
       FROM SIG_SEGUIMIENTO
      WHERE ANO_EJE          = @vn_Ano_Eje   AND
            SEC_EJEC         = @vn_Sec_Ejec  AND
            NRO_TRANSACCION  = @vn_Secuencia AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion
     
     -- Actualiza Estado de Documento
     IF @vs_Trigger = 'U'
        BEGIN
             UPDATE SIG_SEGUIMIENTO 
                SET FECHA_TRANSACCION  = @vd_fecha  ,
                    ESTADO_TRANSACCION = @vs_Estado
              WHERE ANO_EJE          = @vn_Ano_Eje    AND
                    SEC_EJEC         = @vn_Sec_Ejec   AND 
                    NRO_ORIGEN       = @vn_Nro_Origen AND
                    TIPO_TRANSACCION = @vn_Tipo_Transaccion
        END
     
     -- Calcula Correlativo de Seguimiento DET
     SELECT @vn_Sec_Estado= COALESCE(MAX(SEC_ESTADO),0) + 1
       FROM SIG_SEGUIMIENTO_ESTADO
      WHERE ANO_EJE          = @vn_Ano_Eje          AND
            SEC_EJEC         = @vn_Sec_Ejec         AND
            TIPO_TRANSACCION = @vn_Tipo_Transaccion AND
            NRO_ORIGEN       = @vn_Nro_Origen
     
     -- Inserta Seguimiento DET
     INSERT INTO SIG_SEGUIMIENTO_ESTADO
                 (ANO_EJE     , SEC_EJEC          , TIPO_TRANSACCION, NRO_ORIGEN, SEC_ESTADO,
                  FECHA_ESTADO, ESTADO_SEGUIMIENTO, FECHA_REG       , CUSER_ID  , EQUIPO_REG)
          SELECT @vn_Ano_Eje, @vn_Sec_Ejec, @vn_Tipo_Transaccion, @vn_Nro_Origen, @vn_Sec_Estado,
                 GETDATE()  , I.ESTADO    , GETDATE()           , @vs_CUser     , @vs_Equipo
            FROM INSERTED I
END
GO


