-- ----------------------------
-- Triggers structure for table USERS
-- ----------------------------
CREATE TRIGGER [dbo].[USERS_T1]
ON [dbo].[USERS]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE, DELETE
AS
declare @SEC_EJEC varchar(5)
select @SEC_EJEC = '117'
DELETE FROM SEG_ROL_PAGINA_PRIVILEGIO
DELETE FROM SEG_ROL_USUARIO;
DELETE FROM SEG_USUARIO;

INSERT INTO SEG_USUARIO (NOMBRE,PASSWORD,ESTADO,CADUCIDAD,BLOQUEO,USUARIO)
SELECT DISTINCT CUSERLNAME,CPASSWORD,'A','N','N',CUSER_ID FROM USERS A
--WHERE CUSER_ID IN (select CUSER_ID from users_opcion where CMENU_ID=20 AND( (TITULO='03' AND TITULO_SEC='00' AND OPCION IN ('02','03') )  OR      (TITULO='02' AND TITULO_SEC='00' AND OPCION IN ('04') )     ));

INSERT INTO SEG_ROL_USUARIO (USUARIO, ROL)
SELECT DISTINCT USUARIO, USUARIO FROM SEG_USUARIO;

INSERT INTO SEG_ROL_PAGINA_PRIVILEGIO
(PRIVILEGIO, ROL, PAGINA, SEC_EJEC)
SELECT DISTINCT A.MANTENIMIENTO, C.ROL, B.ORDEN, A.SEC_EJEC
FROM USERS_OPCION A INNER JOIN USERS_OPCION B
ON B.CUSER_ID = 'SIGAMEF' AND A.CUSER_ID <> 'SIGAMEF'
AND A.TITULO = B.TITULO  AND b.cmenu_id = 20  AND a.cmenu_id = 20
AND A.TITULO_SEC = B.TITULO_SEC AND A.OPCION = B.OPCION
INNER JOIN SEG_ROL_USUARIO C
ON C.USUARIO = A.CUSER_ID
WHERE NOT A.MANTENIMIENTO IS NULL
--WHERE A.SEC_EJEC = @SEC_EJEC

INSERT INTO SEG_ROL_PAGINA_PRIVILEGIO
(PRIVILEGIO, ROL, PAGINA, SEC_EJEC)
SELECT 2, SEG_ROL_USUARIO.ROL,1020000, SIG_EJECUTORA.SEC_EJEC
FROM SEG_ROL_USUARIO, SIG_EJECUTORA;
GO


